use std::env;
use std::fs;
use std::path::Path;
use std::collections::VecDeque;

fn read_u16(data: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([data[offset], data[offset + 1]])
}

fn read_u32(data: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn read_i32(data: &[u8], offset: usize) -> i32 {
    i32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn extract_channel(pixel: u32, mask: u32) -> u8 {
    let s = mask.trailing_zeros();
    let n = mask.count_ones();
    let m = (1u32 << n) - 1;
    let v = (pixel & mask) >> s;
    ((v * 255 + m / 2) / m) as u8
}

fn get_index(row: &[u8], x: usize, bpp: usize) -> usize {
    match bpp {
        1 => {
            let byte_idx = x / 8;
            let bit_idx = 7 - (x % 8);
            ((row[byte_idx] >> bit_idx) & 1) as usize
        }
        4 => {
            let byte_idx = x / 2;
            if x % 2 == 0 {
                ((row[byte_idx] >> 4) & 0xF) as usize
            } else {
                (row[byte_idx] & 0xF) as usize
            }
        }
        8 => row[x] as usize,
        _ => unreachable!(),
    }
}

fn process_bmp(name: &str, data: &[u8]) {
    let bf_off_bits = read_u32(data, 10) as usize;

    let dib_size = read_u32(data, 14) as usize;
    let width = read_i32(data, 18) as usize;
    let height_raw = read_i32(data, 22);
    let height = height_raw.unsigned_abs() as usize;
    let bottom_up = height_raw > 0;
    let bpp = read_u16(data, 28) as usize;
    let compression = read_u32(data, 30);
    let colors_used = read_u32(data, 46) as usize;

    if compression != 0 && compression != 3 {
        println!("== {}", name);
        println!("error: unsupported compression {}", compression);
        return;
    }

    let (red_mask, green_mask, blue_mask) = if compression == 3 {
        // Masks are at file offset 54 (14 + 40) in all cases
        (read_u32(data, 54), read_u32(data, 58), read_u32(data, 62))
    } else {
        (0u32, 0u32, 0u32)
    };

    let palette_offset = 14 + dib_size;
    let num_colors = if colors_used == 0 {
        1usize << bpp
    } else {
        colors_used
    };

    let palette: Vec<(u8, u8, u8)> = if bpp <= 8 {
        (0..num_colors)
            .map(|i| {
                let off = palette_offset + i * 4;
                (data[off + 2], data[off + 1], data[off]) // R, G, B
            })
            .collect()
    } else {
        Vec::new()
    };

    let row_bytes: usize = match bpp {
        1 => ((width + 7) / 8 + 3) / 4 * 4,
        4 => ((width + 1) / 2 + 3) / 4 * 4,
        8 => (width + 3) / 4 * 4,
        24 => (width * 3 + 3) / 4 * 4,
        32 => width * 4,
        _ => unreachable!(),
    };

    let mut ink = vec![vec![false; width]; height];
    let mut ink_count: usize = 0;

    for y in 0..height {
        let stored_y = if bottom_up { height - 1 - y } else { y };
        let row_offset = bf_off_bits + stored_y * row_bytes;

        for x in 0..width {
            let (r, g, b) = match bpp {
                1 | 4 | 8 => {
                    let idx = get_index(&data[row_offset..], x, bpp);
                    if idx < num_colors {
                        palette[idx]
                    } else {
                        (0, 0, 0)
                    }
                }
                24 => {
                    let off = row_offset + x * 3;
                    (data[off + 2], data[off + 1], data[off])
                }
                32 => {
                    let off = row_offset + x * 4;
                    if compression == 0 {
                        (data[off + 2], data[off + 1], data[off])
                    } else {
                        let pixel = read_u32(data, off);
                        (
                            extract_channel(pixel, red_mask),
                            extract_channel(pixel, green_mask),
                            extract_channel(pixel, blue_mask),
                        )
                    }
                }
                _ => unreachable!(),
            };

            let lum = (299 * r as u32 + 587 * g as u32 + 114 * b as u32) / 1000;
            if lum < 128 {
                ink[y][x] = true;
                ink_count += 1;
            }
        }
    }

    // Connected components via BFS, 8-connectivity
    let mut visited = vec![vec![false; width]; height];
    let mut components: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();

    for y in 0..height {
        for x in 0..width {
            if ink[y][x] && !visited[y][x] {
                let mut queue = VecDeque::new();
                queue.push_back((x, y));
                visited[y][x] = true;
                let mut minx = x;
                let mut miny = y;
                let mut maxx = x;
                let mut maxy = y;
                let mut count: usize = 0;

                while let Some((cx, cy)) = queue.pop_front() {
                    count += 1;
                    if cx < minx { minx = cx; }
                    if cx > maxx { maxx = cx; }
                    if cy < miny { miny = cy; }
                    if cy > maxy { maxy = cy; }

                    for dy in -1i32..=1 {
                        for dx in -1i32..=1 {
                            if dx == 0 && dy == 0 { continue; }
                            let nx = cx as i32 + dx;
                            let ny = cy as i32 + dy;
                            if nx >= 0 && nx < width as i32 && ny >= 0 && ny < height as i32 {
                                let nx = nx as usize;
                                let ny = ny as usize;
                                if ink[ny][nx] && !visited[ny][nx] {
                                    visited[ny][nx] = true;
                                    queue.push_back((nx, ny));
                                }
                            }
                        }
                    }
                }

                // (x,y) here is already the first pixel in reading order
                components.push((x, y, minx, miny, maxx, maxy, count));
            }
        }
    }

    println!("== {}", name);
    println!(
        "size {}x{} bpp {} header {} {} ink {}",
        width,
        height,
        bpp,
        dib_size,
        if bottom_up { "bottom-up" } else { "top-down" },
        ink_count
    );
    println!("components {}", components.len());
    for (fx, fy, minx, miny, maxx, maxy, count) in &components {
        println!(
            "{},{} bbox {},{}-{},{} pixels {}",
            fx, fy, minx, miny, maxx, maxy, count
        );
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries {
            let entry = entry.unwrap();
            let name = entry.file_name().to_str().unwrap().to_string();
            if name.ends_with(".bmp") {
                files.push(name);
            }
        }
    }
    files.sort();

    for name in &files {
        let path = Path::new(dir).join(name);
        let data = fs::read(&path).unwrap();
        process_bmp(name, &data);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <stdint.h>

static uint16_t rd_u16(const unsigned char *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t rd_u32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static int32_t rd_i32(const unsigned char *p) {
    return (int32_t)rd_u32(p);
}

static int ctz32(uint32_t x) {
    if (x == 0) return 32;
    int c = 0;
    while (!(x & 1)) { x >>= 1; c++; }
    return c;
}

static int popc32(uint32_t x) {
    int c = 0;
    while (x) { c += (int)(x & 1); x >>= 1; }
    return c;
}

static int extract8(uint32_t pixel, uint32_t mask) {
    int s = ctz32(mask);
    int n = popc32(mask);
    uint32_t m = (1u << n) - 1;
    uint32_t v = (pixel & mask) >> s;
    return (int)((v * 255 + m / 2) / m);
}

typedef struct {
