    let coloursUsed = Int(readU32LE(bytes, dibOff + 32))

    let supported = (compression == 0) || (compression == 3 && bpp == 32)
    if !supported {
        print("== \(name)")
        print("error: unsupported compression \(compression)")
        return
    }

    var redMask: UInt32 = 0, greenMask: UInt32 = 0, blueMask: UInt32 = 0
