import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static Map<String, Integer> currencies = new HashMap<>();
    static Map<String, Account> accounts = new LinkedHashMap<>();
    static List<String> rejections = new ArrayList<>();

    static class Account {
        String currency;
        BigDecimal balance;
        BigDecimal limit;
        Account(String currency, BigDecimal balance, BigDecimal limit) {
            this.currency = currency;
            this.balance = balance;
            this.limit = limit;
        }
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File file = new File(dir, "ledger.txt");
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine()) != null) {
                lines.add(line);
            }
        }

        for (int i = 0; i < lines.size(); i++) {
            int lineNum = i + 1;
            String line = lines.get(i);
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#")) continue;
            String[] parts = trimmed.split("\\s+");
            processCommand(parts, lineNum);
        }

        for (String r : rejections) {
            System.out.println(r);
        }
        System.out.println();

        List<String> names = new ArrayList<>(accounts.keySet());
        Collections.sort(names);
        for (String name : names) {
            Account acc = accounts.get(name);
            System.out.println(name + " " + acc.currency + " " + formatMoney(acc.balance, currencies.get(acc.currency)));
        }
        System.out.println();

        Map<String, BigDecimal> totals = new TreeMap<>();
        Map<String, Integer> counts = new TreeMap<>();
        for (Account acc : accounts.values()) {
            totals.merge(acc.currency, acc.balance, BigDecimal::add);
            counts.merge(acc.currency, 1, Integer::sum);
        }
        for (String code : totals.keySet()) {
            int mu = currencies.get(code);
            System.out.println("total " + code + " " + formatMoney(totals.get(code), mu) + " (" + counts.get(code) + " accounts)");
        }
    }

    static void processCommand(String[] parts, int lineNum) {
        String cmd = parts[0];
        switch (cmd) {
            case "currency": {
                currencies.put(parts[1], Integer.parseInt(parts[2]));
                break;
            }
            case "open": {
                String name = parts[1];
                String code = parts[2];
                if (accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT account exists " + name);
                    return;
                }
                BigDecimal limit = BigDecimal.ZERO;
                if (parts.length > 3) {
                    int mu = currencies.get(code);
                    limit = new BigDecimal(parts[3]).setScale(mu, RoundingMode.HALF_EVEN);
                }
                accounts.put(name, new Account(code, BigDecimal.ZERO, limit));
                break;
            }
            case "deposit": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal amount = new BigDecimal(parts[2]).setScale(mu, RoundingMode.HALF_EVEN);
                if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                acc.balance = acc.balance.add(amount);
                break;
            }
            case "withdraw": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal amount = new BigDecimal(parts[2]).setScale(mu, RoundingMode.HALF_EVEN);
                if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                if (acc.balance.subtract(amount).compareTo(acc.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + name);
                    return;
                }
                acc.balance = acc.balance.subtract(amount);
                break;
            }
            case "transfer": {
                String from = parts[1];
                String to = parts[2];
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                if (!accounts.containsKey(to)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + to);
                    return;
                }
                Account accFrom = accounts.get(from);
                Account accTo = accounts.get(to);
                if (!accFrom.currency.equals(accTo.currency)) {
                    rejections.add("line " + lineNum + ": REJECT currency mismatch");
                    return;
                }
                int mu = currencies.get(accFrom.currency);
                BigDecimal amount = new BigDecimal(parts[3]).setScale(mu, RoundingMode.HALF_EVEN);
                if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                if (accFrom.balance.subtract(amount).compareTo(accFrom.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                accFrom.balance = accFrom.balance.subtract(amount);
                accTo.balance = accTo.balance.add(amount);
                break;
            }
            case "convert": {
                String from = parts[1];
                String to = parts[2];
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                if (!accounts.containsKey(to)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + to);
                    return;
                }
                Account accFrom = accounts.get(from);
                Account accTo = accounts.get(to);
                int muFrom = currencies.get(accFrom.currency);
                int muTo = currencies.get(accTo.currency);
                BigDecimal amount = new BigDecimal(parts[3]).setScale(muFrom, RoundingMode.HALF_EVEN);
                if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                if (accFrom.balance.subtract(amount).compareTo(accFrom.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                BigDecimal rate = new BigDecimal(parts[4]);
                BigDecimal converted = amount.multiply(rate).setScale(muTo, RoundingMode.HALF_EVEN);
                accFrom.balance = accFrom.balance.subtract(amount);
                accTo.balance = accTo.balance.add(converted);
                break;
            }
            case "interest": {
                String name = parts[1];
                if (!accounts.containsKey(name)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + name);
                    return;
                }
                Account acc = accounts.get(name);
                int mu = currencies.get(acc.currency);
                BigDecimal rate = new BigDecimal(parts[2]);
                BigDecimal interest = acc.balance.multiply(rate).setScale(mu, RoundingMode.HALF_EVEN);
                acc.balance = acc.balance.add(interest);
                break;
            }
            case "split": {
                String from = parts[1];
                if (!accounts.containsKey(from)) {
                    rejections.add("line " + lineNum + ": REJECT unknown account " + from);
                    return;
                }
                List<String> targetNames = new ArrayList<>();
                List<BigInteger> weights = new ArrayList<>();
                for (int i = 3; i < parts.length; i++) {
                    String[] tp = parts[i].split(":");
                    targetNames.add(tp[0]);
                    weights.add(new BigInteger(tp[1]));
                }
                for (String tn : targetNames) {
                    if (!accounts.containsKey(tn)) {
                        rejections.add("line " + lineNum + ": REJECT unknown account " + tn);
                        return;
                    }
                }
                Account accFrom = accounts.get(from);
                for (String tn : targetNames) {
                    if (!accounts.get(tn).currency.equals(accFrom.currency)) {
                        rejections.add("line " + lineNum + ": REJECT currency mismatch");
                        return;
                    }
                }
                int mu = currencies.get(accFrom.currency);
                BigDecimal amount = new BigDecimal(parts[2]).setScale(mu, RoundingMode.HALF_EVEN);
                if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                    rejections.add("line " + lineNum + ": REJECT non-positive amount");
                    return;
                }
                if (accFrom.balance.subtract(amount).compareTo(accFrom.limit.negate()) < 0) {
                    rejections.add("line " + lineNum + ": REJECT insufficient funds " + from);
                    return;
                }
                BigInteger aMinor = amount.movePointRight(mu).toBigIntegerExact();
                BigInteger W = BigInteger.ZERO;
                for (BigInteger w : weights) W = W.add(w);

                int n = targetNames.size();
                BigInteger[] bases = new BigInteger[n];
                BigInteger[] rems = new BigInteger[n];
                BigInteger sumBases = BigInteger.ZERO;
                for (int i = 0; i < n; i++) {
                    BigInteger product = aMinor.multiply(weights.get(i));
                    bases[i] = product.divide(W);
                    rems[i] = product.mod(W);
                    sumBases = sumBases.add(bases[i]);
                }
                BigInteger leftover = aMinor.subtract(sumBases);

                Integer[] indices = new Integer[n];
                for (int i = 0; i < n; i++) indices[i] = i;
                Arrays.sort(indices, (a, b) -> {
                    int cmp = rems[b].compareTo(rems[a]);
                    if (cmp != 0) return cmp;
                    return Integer.compare(a, b);
                });

                for (int i = 0; i < leftover.intValue(); i++) {
                    bases[indices[i]] = bases[indices[i]].add(BigInteger.ONE);
                }

                accFrom.balance = accFrom.balance.subtract(amount);
                for (int i = 0; i < n; i++) {
                    BigDecimal share = new BigDecimal(bases[i]).movePointLeft(mu);
                    accounts.get(targetNames.get(i)).balance = accounts.get(targetNames.get(i)).balance.add(share);
                }
                break;
            }
        }
    }

    static String formatMoney(BigDecimal value, int minorUnits) {
        if (value.compareTo(BigDecimal.ZERO) == 0) {
            if (minorUnits == 0) return "0";
            return "0." + "0".repeat(minorUnits);
        }
        boolean negative = value.signum() < 0;
        BigDecimal abs = value.abs().setScale(minorUnits, RoundingMode.HALF_EVEN);
        if (abs.compareTo(BigDecimal.ZERO) == 0) {
            if (minorUnits == 0) return "0";
            return "0." + "0".repeat(minorUnits);
        }

        String intPart;
        String decPart = "";
        if (minorUnits == 0) {
            intPart = abs.toBigInteger().toString();
        } else {
            String plain = abs.setScale(minorUnits).toPlainString();
            int dot = plain.indexOf('.');
            if (dot >= 0) {
                intPart = plain.substring(0, dot);
                decPart = plain.substring(dot + 1);
            } else {
                intPart = plain;
                decPart = "0".repeat(minorUnits);
            }
            while (decPart.length() < minorUnits) decPart += "0";
        }

        StringBuilder sb = new StringBuilder();
        int len = intPart.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) sb.append(',');
            sb.append(intPart.charAt(i));
        }
        String result = sb.toString();
        if (minorUnits > 0) result += "." + decPart;
        if (negative) result = "-" + result;
        return result;
    }
}

import * as fs from 'fs';
import * as path from 'path';

function parseDecimal(s: string): [bigint, number] {
    let neg = false;
    let i = 0;
    if (s[i] === '-') { neg = true; i++; }
    let intPart = '';
    while (i < s.length && s[i] >= '0' && s[i] <= '9') { intPart += s[i]; i++; }
    let fracPart = '';
    if (i < s.length && s[i] === '.') {
        i++;
        while (i < s.length && s[i] >= '0' && s[i] <= '9') { fracPart += s[i]; i++; }
    }
    const digits = intPart + fracPart;
    const scale = fracPart.length;
    let value = BigInt(digits === '' ? '0' : digits);
    if (neg) value = -value;
    return [value, scale];
}

function roundHalfEven(v: bigint, d: bigint): bigint {
    const q = v / d;
    const r = v % d;
    const absR = r < 0n ? -r : r;
    const twiceAbsR = absR * 2n;
    if (twiceAbsR < d) return q;
    if (twiceAbsR > d) {
        return v > 0n ? q + 1n : q - 1n;
    }
    if (q % 2n === 0n) return q;
    return v > 0n ? q + 1n : q - 1n;
}

function roundToMinor(value: bigint, scale: number, minor: number): bigint {
    if (scale <= minor) {
        return value * (10n ** BigInt(minor - scale));
    } else {
        return roundHalfEven(value, 10n ** BigInt(scale - minor));
    }
}

function pow10(n: number): bigint {
    return 10n ** BigInt(n);
}

function formatMoney(minorUnits: bigint, minor: number): string {
    if (minorUnits === 0n) {
        if (minor === 0) return "0";
        return "0." + "0".repeat(minor);
    }
    let neg = minorUnits < 0n;
    let abs = neg ? -minorUnits : minorUnits;

    let intPart: string;
    let fracPart: string;

    if (minor === 0) {
        intPart = abs.toString();
        fracPart = "";
    } else {
        const divisor = pow10(minor);
        const ip = abs / divisor;
        const fp = abs % divisor;
        intPart = ip.toString();
        fracPart = fp.toString().padStart(minor, '0');
    }

    let formatted = '';
    const len = intPart.length;
    for (let i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 === 0) formatted += ',';
        formatted += intPart[i];
    }

    let result = (neg ? "-" : "") + formatted;
    if (minor > 0) result += "." + fracPart;
    return result;
}

const dir = process.argv[2];
const content = fs.readFileSync(path.join(dir, 'ledger.txt'), 'utf-8');
const lines = content.split('\n');

if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
}

interface Account {
    currency: string;
    balance: bigint;
    limit: bigint;
}

const currencies = new Map<string, number>();
const accounts = new Map<string, Account>();
const rejections: string[] = [];

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const trimmed = line.trim();
    if (trimmed === '' || trimmed[0] === '#') continue;

    const fields = trimmed.split(/\s+/);
    const cmd = fields[0];
    const n = lineNum + 1;

    let rejectReason: string | null = null;

    switch (cmd) {
        case 'currency': {
            const code = fields[1];
            const minor = parseInt(fields[2]);
            currencies.set(code, minor);
            break;
        }
        case 'open': {
            const accName = fields[1];
            const code = fields[2];
            const minor = currencies.get(code)!;
            const limitStr = fields.length > 3 ? fields[3] : '0';

            if (accounts.has(accName)) {
                rejectReason = `account exists ${accName}`;
                break;
            }

            const [lv, ls] = parseDecimal(limitStr);
            const limit = roundToMinor(lv, ls, minor);
            accounts.set(accName, { currency: code, balance: 0n, limit });
            break;
        }
        case 'deposit': {
            const accName = fields[1];
            const amtStr = fields[2];

            if (!accounts.has(accName)) {
                rejectReason = `unknown account ${accName}`;
                break;
            }

            const acc = accounts.get(accName)!;
            const minor = currencies.get(acc.currency)!;
            const [av, as] = parseDecimal(amtStr);
            const amount = roundToMinor(av, as, minor);

            if (amount <= 0n) {
                rejectReason = `non-positive amount`;
                break;
            }

            acc.balance += amount;
            break;
        }
        case 'withdraw': {
            const accName = fields[1];
            const amtStr = fields[2];

            if (!accounts.has(accName)) {
                rejectReason = `unknown account ${accName}`;
                break;
            }

            const acc = accounts.get(accName)!;
            const minor = currencies.get(acc.currency)!;
            const [av, as] = parseDecimal(amtStr);
            const amount = roundToMinor(av, as, minor);

            if (amount <= 0n) {
                rejectReason = `non-positive amount`;
                break;
            }

            if (acc.balance - amount < -acc.limit) {
                rejectReason = `insufficient funds ${accName}`;
                break;
            }

            acc.balance -= amount;
            break;
        }
        case 'transfer': {
            const fromName = fields[1];
            const toName = fields[2];
            const amtStr = fields[3];

            if (!accounts.has(fromName)) {
                rejectReason = `unknown account ${fromName}`;
                break;
            }
            if (!accounts.has(toName)) {
                rejectReason = `unknown account ${toName}`;
                break;
            }

            const from = accounts.get(fromName)!;
            const to = accounts.get(toName)!;

            if (from.currency !== to.currency) {
                rejectReason = `currency mismatch`;
                break;
            }

            const minor = currencies.get(from.currency)!;
            const [av, as] = parseDecimal(amtStr);
            const amount = roundToMinor(av, as, minor);

            if (amount <= 0n) {
                rejectReason = `non-positive amount`;
                break;
            }

            if (from.balance - amount < -from.limit) {
                rejectReason = `insufficient funds ${fromName}`;
                break;
            }

            from.balance -= amount;
            to.balance += amount;
            break;
        }
        case 'convert': {
            const fromName = fields[1];
            const toName = fields[2];
            const amtStr = fields[3];
            const rateStr = fields[4];

            if (!accounts.has(fromName)) {
                rejectReason = `unknown account ${fromName}`;
                break;
            }
            if (!accounts.has(toName)) {
                rejectReason = `unknown account ${toName}`;
                break;
            }

            const from = accounts.get(fromName)!;
            const to = accounts.get(toName)!;

            const fromMinor = currencies.get(from.currency)!;
            const toMinor = currencies.get(to.currency)!;

            const [av, as] = parseDecimal(amtStr);
            const amount = roundToMinor(av, as, fromMinor);

            if (amount <= 0n) {
                rejectReason = `non-positive amount`;
                break;
            }

            if (from.balance - amount < -from.limit) {
                rejectReason = `insufficient funds ${fromName}`;
                break;
            }

            const [rv, rs] = parseDecimal(rateStr);
            const numerator = amount * rv;
            const exp = fromMinor + rs - toMinor;
            let received: bigint;
            if (exp >= 0) {
                received = roundHalfEven(numerator, pow10(exp));
            } else {
                received = numerator * pow10(-exp);
            }

            from.balance -= amount;
            to.balance += received;
            break;
        }
        case 'interest': {
            const accName = fields[1];
            const rateStr = fields[2];

            if (!accounts.has(accName)) {
                rejectReason = `unknown account ${accName}`;
                break;
            }

            const acc = accounts.get(accName)!;
            const [rv, rs] = parseDecimal(rateStr);

            const numerator = acc.balance * rv;
            const interest = roundHalfEven(numerator, pow10(rs));

            acc.balance += interest;
            break;
        }
        case 'split': {
            const fromName = fields[1];
            const amtStr = fields[2];
            const targets: { name: string; weight: number }[] = [];
            for (let i = 3; i < fields.length; i++) {
                const colonIdx = fields[i].lastIndexOf(':');
                const name = fields[i].substring(0, colonIdx);
                const weight = parseInt(fields[i].substring(colonIdx + 1));
                targets.push({ name, weight });
            }

            if (!accounts.has(fromName)) {
                rejectReason = `unknown account ${fromName}`;
                break;
            }
            for (const t of targets) {
                if (!accounts.has(t.name)) {
                    rejectReason = `unknown account ${t.name}`;
                    break;
                }
            }
            if (rejectReason) break;

            const from = accounts.get(fromName)!;

            for (const t of targets) {
                const toAcc = accounts.get(t.name)!;
                if (from.currency !== toAcc.currency) {
                    rejectReason = `currency mismatch`;
                    break;
                }
            }
            if (rejectReason) break;

            const minor = currencies.get(from.currency)!;
            const [av, as] = parseDecimal(amtStr);
            const amount = roundToMinor(av, as, minor);

            if (amount <= 0n) {
                rejectReason = `non-positive amount`;
                break;
            }

            if (from.balance - amount < -from.limit) {
                rejectReason = `insufficient funds ${fromName}`;
                break;
            }

            const W = targets.reduce((s, t) => s + t.weight, 0);
            const Wn = BigInt(W);
            const allocations: bigint[] = targets.map(t => (amount * BigInt(t.weight)) / Wn);
            const remainders: bigint[] = targets.map(t => (amount * BigInt(t.weight)) % Wn);

            let leftover = amount - allocations.reduce((s, a) => s + a, 0n);

            const indices = targets.map((_, i) => i);
            indices.sort((a, b) => {
                if (remainders[a] !== remainders[b]) {
                    return remainders[b] > remainders[a] ? 1 : -1;
                }
                return a - b;
            });

            for (let i = 0; i < leftover; i++) {
                allocations[indices[i]] += 1n;
            }

            from.balance -= amount;
            for (let i = 0; i < targets.length; i++) {
                const toAcc = accounts.get(targets[i].name)!;
                toAcc.balance += allocations[i];
            }
            break;
        }
    }

    if (rejectReason) {
        rejections.push(`line ${n}: REJECT ${rejectReason}`);
    }
}

for (const r of rejections) {
    console.log(r);
}
console.log();

const sortedAccounts = [...accounts.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [name, acc] of sortedAccounts) {
    const minor = currencies.get(acc.currency)!;
    console.log(`${name} ${acc.currency} ${formatMoney(acc.balance, minor)}`);
}
console.log();

const totals = new Map<string, { sum: bigint; count: number }>();
for (const [, acc] of accounts) {
    const existing = totals.get(acc.currency);
    if (existing) {
        existing.sum += acc.balance;
        existing.count++;
    } else {
        totals.set(acc.currency, { sum: acc.balance, count: 1 });
    }
}

const sortedCurrencies = [...totals.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [code, { sum, count }] of sortedCurrencies) {
    const minor = currencies.get(code)!;
    console.log(`total ${code} ${formatMoney(sum, minor)} (${count} accounts)`);
}

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        List<String[]> queries = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(dir + "/queries.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] parts = line.split(" ", 2);
                queries.add(parts);
            }
        }

        for (String[] q : queries) {
            processQuery(q[0], q[1], port);
        }
    }

    static void processQuery(String name, String type, int port) throws Exception {
        int id = ThreadLocalRandom.current().nextInt(0, 65536);
        byte[] query = buildQuery(name, type, id);

        byte[] response = sendUdp(query, port, id);

        int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
        boolean tc = (flags & 0x0200) != 0;

        if (tc) {
            response = sendTcp(query, port);
        }

        parseAndPrint(name, type, response);
    }

    static byte[] buildQuery(String name, String type, int id) {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        bos.write((id >> 8) & 0xFF);
        bos.write(id & 0xFF);
        bos.write(0x01);
        bos.write(0x00);
        bos.write(0x00); bos.write(0x01);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);
        bos.write(0x00); bos.write(0x00);

        String cleanName = name;
        if (cleanName.endsWith(".")) cleanName = cleanName.substring(0, cleanName.length() - 1);

        if (!cleanName.isEmpty()) {
            String[] labels = cleanName.split("\\.");
            for (String label : labels) {
                byte[] lb = label.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
                bos.write(lb.length);
                bos.write(lb, 0, lb.length);
            }
        }
        bos.write(0);

        int qtype = typeToCode(type);
        bos.write((qtype >> 8) & 0xFF);
        bos.write(qtype & 0xFF);
        bos.write(0x00);
        bos.write(0x01);

        return bos.toByteArray();
    }

    static int typeToCode(String type) {
        switch (type) {
            case "A": return 1;
            case "CNAME": return 5;
            case "MX": return 15;
            case "TXT": return 16;
            case "AAAA": return 28;
            default: return 0;
        }
    }

    static byte[] sendUdp(byte[] query, int port, int id) throws Exception {
        DatagramSocket socket = new DatagramSocket();
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        DatagramPacket send = new DatagramPacket(query, query.length, addr, port);
        socket.send(send);

        byte[] buf = new byte[65535];
        while (true) {
            DatagramPacket recv = new DatagramPacket(buf, buf.length);
            socket.receive(recv);
            byte[] data = Arrays.copyOf(recv.getData(), recv.getLength());
            if (data.length < 12) continue;
            int rid = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
            int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
            int qr = (flags >> 15) & 1;
            if (qr == 1 && rid == id) {
                socket.close();
                return data;
            }
        }
    }

    static byte[] sendTcp(byte[] query, int port) throws Exception {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress("127.0.0.1", port));
        OutputStream os = socket.getOutputStream();
        int len = query.length;
        os.write((len >> 8) & 0xFF);
        os.write(len & 0xFF);
        os.write(query);
        os.flush();

        InputStream is = socket.getInputStream();
        int hi = is.read();
        int lo = is.read();
        int rlen = (hi << 8) | lo;

        byte[] data = new byte[rlen];
        int offset = 0;
        while (offset < rlen) {
            int n = is.read(data, offset, rlen - offset);
            if (n < 0) break;
            offset += n;
        }
        socket.close();
        return data;
    }

    static void parseAndPrint(String name, String type, byte[] msg) {
        int flags = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
        int rcode = flags & 0x0F;
        int qdcount = ((msg[4] & 0xFF) << 8) | (msg[5] & 0xFF);
        int ancount = ((msg[6] & 0xFF) << 8) | (msg[7] & 0xFF);

        int offset = 12;
        for (int i = 0; i < qdcount; i++) {
            offset = skipName(msg, offset);
            offset += 4;
        }

        String lowerName = name.toLowerCase();
        if (lowerName.endsWith(".")) lowerName = lowerName.substring(0, lowerName.length() - 1);
        if (lowerName.isEmpty()) lowerName = ".";
        System.out.println(lowerName + " " + type + " " + rcodeToString(rcode));

        for (int i = 0; i < ancount; i++) {
            String owner = readName(msg, offset);
            offset = skipName(msg, offset);

            int rtype = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
            long ttl = ((long)(msg[offset+4] & 0xFF) << 24) | ((msg[offset+5] & 0xFF) << 16)
                     | ((msg[offset+6] & 0xFF) << 8) | (msg[offset+7] & 0xFF);
            int rdlength = ((msg[offset+8] & 0xFF) << 8) | (msg[offset+9] & 0xFF);
            offset += 10;

            int rdataStart = offset;
            String data = parseRdata(msg, rdataStart, rdlength, rtype);
            offset += rdlength;

            String typeName = typeCodeToName(rtype);
            System.out.println("  " + owner + " " + ttl + " " + typeName + " " + data);
        }
    }

    static int skipName(byte[] msg, int offset) {
        while (true) {
            int len = msg[offset] & 0xFF;
            if (len == 0) return offset + 1;
            if ((len & 0xC0) == 0xC0) return offset + 2;
            offset += 1 + len;
        }
    }

    static String readName(byte[] msg, int offset) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        while (true) {
            int len = msg[offset] & 0xFF;
            if (len == 0) break;
            if ((len & 0xC0) == 0xC0) {
                int ptr = ((len & 0x3F) << 8) | (msg[offset + 1] & 0xFF);
                offset = ptr;
                continue;
            }
            if (!first) sb.append(".");
            first = false;
            for (int i = 0; i < len; i++) {
                sb.append((char)(msg[offset + 1 + i] & 0xFF));
            }
            offset += 1 + len;
        }
        if (sb.length() == 0) return ".";
        return sb.toString().toLowerCase();
    }

    static String parseRdata(byte[] msg, int start, int length, int rtype) {
        switch (rtype) {
            case 1: return parseA(msg, start, length);
            case 28: return parseAaaa(msg, start, length);
            case 5: return readName(msg, start);
            case 15: return parseMx(msg, start, length);
            case 16: return parseTxt(msg, start, length);
            default: return parseOther(msg, start, length);
        }
    }

    static String parseA(byte[] msg, int start, int length) {
        return (msg[start] & 0xFF) + "." + (msg[start+1] & 0xFF) + "."
             + (msg[start+2] & 0xFF) + "." + (msg[start+3] & 0xFF);
    }

    static String parseAaaa(byte[] msg, int start, int length) {
        int[] groups = new int[8];
        for (int i = 0; i < 8; i++) {
            groups[i] = ((msg[start + i*2] & 0xFF) << 8) | (msg[start + i*2 + 1] & 0xFF);
        }
        int bestStart = -1, bestLen = 0;
        int curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (groups[i] == 0) {
                if (curLen == 0) curStart = i;
                curLen++;
            } else {
                if (curLen >= 2 && curLen > bestLen) { bestStart = curStart; bestLen = curLen; }
                curLen = 0;
            }
        }
        if (curLen >= 2 && curLen > bestLen) { bestStart = curStart; bestLen = curLen; }

        StringBuilder sb = new StringBuilder();
        if (bestStart == -1) {
            for (int i = 0; i < 8; i++) {
                if (i > 0) sb.append(":");
                sb.append(Integer.toHexString(groups[i]));
            }
        } else {
            for (int i = 0; i < bestStart; i++) {
                if (i > 0) sb.append(":");
                sb.append(Integer.toHexString(groups[i]));
            }
            sb.append("::");
            for (int i = bestStart + bestLen; i < 8; i++) {
                if (i > bestStart + bestLen) sb.append(":");
                sb.append(Integer.toHexString(groups[i]));
            }
        }
        return sb.toString();
    }

    static String parseMx(byte[] msg, int start, int length) {
        int pref = ((msg[start] & 0xFF) << 8) | (msg[start + 1] & 0xFF);
        String exchange = readName(msg, start + 2);
        return pref + " " + exchange;
    }

    static String parseTxt(byte[] msg, int start, int length) {
        StringBuilder sb = new StringBuilder();
        int offset = start;
        int end = start + length;
        boolean first = true;
        while (offset < end) {
            if (!first) sb.append(" ");
            first = false;
            int strLen = msg[offset] & 0xFF;
            offset++;
            sb.append('"');
            for (int i = 0; i < strLen; i++) {
                int b = msg[offset + i] & 0xFF;
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b));
            }
            sb.append('"');
            offset += strLen;
        }
        return sb.toString();
    }

    static String parseOther(byte[] msg, int start, int length) {
        StringBuilder sb = new StringBuilder();
        sb.append("\\# ").append(length);
        if (length > 0) {
            sb.append(" ");
            for (int i = 0; i < length; i++) {
                sb.append(String.format("%02x", msg[start + i] & 0xFF));
            }
        }
        return sb.toString();
    }

    static String typeCodeToName(int code) {
        switch (code) {
            case 1: return "A";
            case 5: return "CNAME";
            case 15: return "MX";
            case 16: return "TXT";
            case 28: return "AAAA";
            default: return "TYPE" + code;
        }
    }

    static String rcodeToString(int rcode) {
        switch (rcode) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + rcode;
        }
    }
}

import Foundation

// MARK: - DNS Type Mapping
func typeToNumber(_ t: String) -> UInt16 {
    switch t {
    case "A": return 1
    case "AAAA": return 28
    case "MX": return 15
    case "TXT": return 16
    case "CNAME": return 5
    default: return 0
    }
}

func numberToTypeName(_ n: UInt16) -> String {
    switch n {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(n)"
    }
}

func rcodeString(_ r: Int) -> String {
    switch r {
    case 0: return "NOERROR"
    case 1: return "FORMERR"
    case 2: return "SERVFAIL"
    case 3: return "NXDOMAIN"
    case 4: return "NOTIMP"
    case 5: return "REFUSED"
    default: return "RCODE\(r)"
    }
}

// MARK: - Build DNS Query
func buildQuery(id: UInt16, name: String, qtype: UInt16) -> [UInt8] {
    var msg = [UInt8]()
    // Header
    msg.append(UInt8(id >> 8))
    msg.append(UInt8(id & 0xFF))
    msg.append(0x01) // flags high byte (RD=1)
    msg.append(0x00) // flags low byte
    msg.append(0x00); msg.append(0x01) // QDCOUNT=1
    msg.append(0x00); msg.append(0x00) // ANCOUNT=0
    msg.append(0x00); msg.append(0x00) // NSCOUNT=0
    msg.append(0x00); msg.append(0x00) // ARCOUNT=0
    // QNAME
    var n = name
    if n.hasSuffix(".") { n = String(n.dropLast()) }
    if !n.isEmpty {
        let labels = n.components(separatedBy: ".")
        for label in labels {
            let bytes = Array(label.utf8)
            msg.append(UInt8(bytes.count))
            msg.append(contentsOf: bytes)
        }
    }
    msg.append(0x00) // root
    // QTYPE
    msg.append(UInt8(qtype >> 8))
    msg.append(UInt8(qtype & 0xFF))
    // QCLASS = 1
    msg.append(0x00); msg.append(0x01)
    return msg
}

// MARK: - Socket Helpers
func makeSockaddrIn(_ port: UInt16) -> sockaddr_in {
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")
    return addr
}

func sendAll(_ sock: Int32, _ data: [UInt8]) {
    var sent = 0
    let total = data.count
    while sent < total {
        let n = data.withUnsafeBytes { ptr in
            send(sock, ptr.baseAddress!.advanced(by: sent), total - sent, 0)
        }
        if n <= 0 { break }
        sent += n
    }
}

func recvAll(_ sock: Int32, _ count: Int) -> [UInt8] {
    var buf = [UInt8](repeating: 0, count: count)
    var received = 0
    while received < count {
        let n = recv(sock, &buf[received], count - received, 0)
        if n <= 0 { break }
        received += n
    }
    return Array(buf[0..<received])
}

// MARK: - UDP
func sendUDP(msg: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    var addr = makeSockaddrIn(port)
    _ = withUnsafePointer(to: &addr) { addrPtr in
        addrPtr.withMemoryRebound(to: sockaddr.self, capacity: 1) { saPtr in
            sendto(sock, msg, msg.count, 0, saPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    while true {
        var buf = [UInt8](repeating: 0, count: 65535)
        let n = recvfrom(sock, &buf, buf.count, 0, nil, nil)
        if n >= 12 {
            let respID = (UInt16(buf[0]) << 8) | UInt16(buf[1])
            let flags = (UInt16(buf[2]) << 8) | UInt16(buf[3])
            if (flags & 0x8000) != 0 && respID == expectedID {
                close(sock)
                return Array(buf[0..<n])
            }
        }
    }
}

// MARK: - TCP
func sendTCP(msg: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    var addr = makeSockaddrIn(port)
    _ = withUnsafePointer(to: &addr) { addrPtr in
        addrPtr.withMemoryRebound(to: sockaddr.self, capacity: 1) { saPtr in
            connect(sock, saPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    // Send length-prefixed message
    var lengthPrefix: [UInt8] = [UInt8(msg.count >> 8), UInt8(msg.count & 0xFF)]
    sendAll(sock, lengthPrefix)
    sendAll(sock, msg)
    // Receive length prefix
    let lenBuf = recvAll(sock, 2)
    let msgLen = (Int(lenBuf[0]) << 8) | Int(lenBuf[1])
    // Receive message
    let resp = recvAll(sock, msgLen)
    close(sock)
    return resp
}

// MARK: - Name Parsing with Compression
func parseName(_ msg: [UInt8], _ pos: Int) -> (name: String, nextPos: Int) {
    var labels = [String]()
    var p = pos
    var jumped = false
    var nextPos = pos
    var guardCount = 0
    while true {
        guardCount += 1
        if guardCount > 256 { break }
        if p >= msg.count { break }
        let len = Int(msg[p])
        if len == 0 {
            if !jumped { nextPos = p + 1 }
            break
        }
        if (len & 0xC0) == 0xC0 {
            // Pointer
            if p + 1 >= msg.count { break }
            let ptr = ((len & 0x3F) << 8) | Int(msg[p + 1])
            if !jumped { nextPos = p + 2 }
            jumped = true
            p = ptr
        } else {
            // Label
            p += 1
            if p + len > msg.count { break }
            let labelBytes = Array(msg[p..<(p+len)])
            let label = String(bytes: labelBytes, encoding: .ascii) ?? ""
            labels.append(label.lowercased())
            p += len
        }
    }
    let name = labels.isEmpty ? "." : labels.joined(separator: ".")
    return (name, nextPos)
}

// MARK: - Skip Name (for question section)
func skipName(_ msg: [UInt8], _ pos: Int) -> Int {
    var p = pos
    while true {
        if p >= msg.count { break }
        let len = Int(msg[p])
        if len == 0 { return p + 1 }
        if (len & 0xC0) == 0xC0 { return p + 2 }
        p += 1 + len
    }
    return p
}

// MARK: - IPv6 Formatting (RFC 5952 §4)
func formatIPv6(_ bytes: [UInt8]) -> String {
    var groups = [UInt16]()
    for i in 0..<8 {
        let g = (UInt16(bytes[i*2]) << 8) | UInt16(bytes[i*2+1])
        groups.append(g)
    }
    // Find longest run of consecutive zero groups (length >= 2)
    var bestStart = -1
    var bestLen = 0
    var i = 0
    while i < 8 {
        if groups[i] == 0 {
            var j = i
            while j < 8 && groups[j] == 0 { j += 1 }
            let runLen = j - i
            if runLen >= 2 && runLen > bestLen {
                bestLen = runLen
                bestStart = i
            }
            i = j
        } else {
            i += 1
        }
    }
    // Build string
    var parts = [String]()
    for g in groups {
        parts.append(String(g, radix: 16))
    }
    if bestStart >= 0 {
        let left = parts[0..<bestStart].joined(separator: ":")
        let right = parts[(bestStart+bestLen)..<8].joined(separator: ":")
        if left.isEmpty && right.isEmpty { return "::" }
        if left.isEmpty { return "::" + right }
        if right.isEmpty { return left + "::" }
        return left + "::" + right
    } else {
        return parts.joined(separator: ":")
    }
}

// MARK: - TXT Formatting
func formatTXT(_ rdata: [UInt8]) -> String {
    var result = [String]()
    var p = 0
    while p < rdata.count {
        let strLen = Int(rdata[p])
        p += 1
        var str = ""
        let end = min(p + strLen, rdata.count)
        while p < end {
            let b = rdata[p]
            if b == 0x22 { // "
                str += "\\\""
            } else if b == 0x5C { // \
                str += "\\\\"
            } else if b >= 0x20 && b <= 0x7E {
                str.append(Character(UnicodeScalar(b)))
            } else {
                str += "\\\(String(format: "%03d", Int(b)))"
            }
            p += 1
        }
        // If strLen was 0, we still have an empty string
        result.append("\"\(str)\"")
    }
    return result.joined(separator: " ")
}

// MARK: - Parse and Print Response
func parseAndPrint(response: [UInt8], name: String, typeStr: String) {
    if response.count < 12 { return }
    let flags = (Int(response[2]) << 8) | Int(response[3])
    let rcode = flags & 0x000F
    let qdcount = (Int(response[4]) << 8) | Int(response[5])
    let ancount = (Int(response[6]) << 8) | Int(response[7])

    // Print query line
    var outName = name.lowercased()
    if outName.hasSuffix(".") { outName = String(outName.dropLast()) }
    print("\(outName) \(typeStr) \(rcodeString(rcode))")

    // Skip question section
    var pos = 12
    for _ in 0..<qdcount {
        pos = skipName(response, pos)
        pos += 4 // QTYPE + QCLASS
    }

    // Parse answer section
    for _ in 0..<ancount {
        if pos >= response.count { break }
        let (owner, nextPos) = parseName(response, pos)
        pos = nextPos
        if pos + 10 > response.count { break }
        let rtype = (UInt16(response[pos]) << 8) | UInt16(response[pos+1])
        pos += 2
        let rclass = (UInt16(response[pos]) << 8) | UInt16(response[pos+1])
        pos += 2
        let ttl = (UInt32(response[pos]) << 24) | (UInt32(response[pos+1]) << 16) |
                  (UInt32(response[pos+2]) << 8) | UInt32(response[pos+3])
        pos += 4
        let rdlen = (Int(response[pos]) << 8) | Int(response[pos+1])
        pos += 2
        if pos + rdlen > response.count { break }
        let rdata = Array(response[pos..<(pos+rdlen)])
        pos += rdlen

        let typeName = numberToTypeName(rtype)
        var dataStr = ""

        switch rtype {
        case 1: // A
            if rdlen == 4 {
                dataStr = "\(rdata[0]).\(rdata[1]).\(rdata[2]).\(rdata[3])"
            }
        case 28: // AAAA
            if rdlen == 16 {
                dataStr = formatIPv6(rdata)
            }
        case 5: // CNAME
            let (target, _) = parseName(response, pos - rdlen)
            dataStr = target
        case 15: // MX
            if rdlen >= 3 {
                let pref = (Int(rdata[0]) << 8) | Int(rdata[1])
                let (exchange, _) = parseName(response, pos - rdlen + 2)
                dataStr = "\(pref) \(exchange)"
            }
        case 16: // TXT
            dataStr = formatTXT(rdata)
        default:
            if rdlen == 0 {
                dataStr = "\\# 0"
            } else {
                let hex = rdata.map { String(format: "%02x", $0) }.joined()
                dataStr = "\\# \(rdlen) \(hex)"
            }
        }

        print("  \(owner) \(ttl) \(typeName) \(dataStr)")
    }
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dir = args[1]
let port = UInt16(args[2]) ?? 0

let queriesPath = dir + "/queries.txt"
guard let content = try? String(contentsOfFile: queriesPath, encoding: .utf8) else { exit(1) }

let lines = content.components(separatedBy: "\n")

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    let parts = trimmed.components(separatedBy: " ")
    guard parts.count >= 2 else { continue }
    let name = parts[0]
    let typeStr = parts[1]
    let qtype = typeToNumber(typeStr)
    let id = UInt16.random(in: 0...65535)

    let msg = buildQuery(id: id, name: name, qtype: qtype)
    var response = sendUDP(msg: msg, port: port, expectedID: id)

    if response.count >= 4 {
        let flags = (UInt16(response[2]) << 8) | UInt16(response[3])
        if (flags & 0x0200) != 0 {
            response = sendTCP(msg: msg, port: port, expectedID: id)
        }
    }

    parseAndPrint(response: response, name: name, typeStr: typeStr)
}

exit(0)

#!/usr/bin/env python3
import sys
import os
import struct
import random
import socket


def encode_qname(name):
    if name.endswith('.'):
        name = name[:-1]
    if name == '':
        return b'\x00'
    labels = name.split('.')
    result = bytearray()
    for label in labels:
        encoded = label.encode('ascii')
        result.append(len(encoded))
        result.extend(encoded)
    result.append(0)
    return bytes(result)


def parse_name(msg, offset):
    labels = []
    visited = set()
    next_offset = None

    while True:
        if offset in visited:
            raise ValueError("Pointer loop")
        visited.add(offset)

        length = msg[offset]
        if (length & 0xC0) == 0xC0:
            pointer = ((length & 0x3F) << 8) | msg[offset + 1]
            if next_offset is None:
                next_offset = offset + 2
            offset = pointer
        elif length == 0:
            if next_offset is None:
                next_offset = offset + 1
            break
        else:
            label = msg[offset + 1:offset + 1 + length]
            labels.append(label.decode('latin-1'))
            offset += 1 + length

    if not labels:
        return '.', next_offset
    return '.'.join(labels).lower(), next_offset


def format_aaaa(data):
    groups = [struct.unpack('!H', data[i * 2:(i + 1) * 2])[0] for i in range(8)]

    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0

    for i in range(8):
        if groups[i] == 0:
            if cur_start == -1:
                cur_start = i
                cur_len = 1
            else:
                cur_len += 1
        else:
            if cur_len >= 2 and cur_len > best_len:
                best_start = cur_start
                best_len = cur_len
            cur_start = -1
            cur_len = 0
    if cur_len >= 2 and cur_len > best_len:
        best_start = cur_start
        best_len = cur_len

    hex_groups = [format(g, 'x') for g in groups]

    if best_start == -1:
        return ':'.join(hex_groups)

    left = hex_groups[:best_start]
    right = hex_groups[best_start + best_len:]

    if left and right:
        return ':'.join(left) + '::' + ':'.join(right)
    elif left:
        return ':'.join(left) + '::'
    elif right:
        return '::' + ':'.join(right)
    else:
        return '::'


def format_txt(rdata):
    parts = []
    i = 0
    while i < len(rdata):
        slen = rdata[i]
        i += 1
        s = rdata[i:i + slen]
        i += slen
        escaped = ''
        for b in s:
            if b == 0x22:
                escaped += '\\"'
            elif b == 0x5C:
                escaped += '\\\\'
            elif 0x20 <= b <= 0x7E:
                escaped += chr(b)
            else:
                escaped += '\\' + format(b, '03d')
        parts.append('"' + escaped + '"')
    return ' '.join(parts)


def build_query(qid, name, qtype):
    header = struct.pack('!HHHHHH', qid, 0x0100, 1, 0, 0, 0)
    qname = encode_qname(name)
    question = qname + struct.pack('!HH', qtype, 1)
    return header + question


def send_udp(host, port, data, expected_id):
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.sendto(data, (host, port))
    try:
        while True:
            resp, _ = sock.recvfrom(65535)
            if len(resp) >= 12:
                resp_id = struct.unpack('!H', resp[0:2])[0]
                flags = struct.unpack('!H', resp[2:4])[0]
                qr = (flags >> 15) & 1
                if qr == 1 and resp_id == expected_id:
                    return resp
    finally:
        sock.close()


def recv_exact(sock, n):
    data = b''
    while len(data) < n:
        chunk = sock.recv(n - len(data))
        if not chunk:
            raise ConnectionError("Connection closed")
        data += chunk
    return data


def send_tcp(host, port, data, expected_id):
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((host, port))
    try:
        msg = struct.pack('!H', len(data)) + data
        sock.sendall(msg)
        length_data = recv_exact(sock, 2)
        length = struct.unpack('!H', length_data)[0]
        resp = recv_exact(sock, length)
        return resp
    finally:
        sock.close()


def parse_response(msg):
    qid, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', msg[0:12])
    rcode = flags & 0xF

    offset = 12
    for _ in range(qdcount):
        _, offset = parse_name(msg, offset)
        offset += 4

    answers = []
    for _ in range(ancount):
        owner, offset = parse_name(msg, offset)
        rtype, rclass, ttl, rdlength = struct.unpack('!HHIH', msg[offset:offset + 10])
        offset += 10
        rdata_start = offset
        offset += rdlength
        answers.append((owner, ttl, rtype, rdata_start, rdlength))

    return rcode, answers


def main():
    directory = sys.argv[1]
    port = int(sys.argv[2])

    queries_file = os.path.join(directory, 'queries.txt')

    with open(queries_file, 'r') as f:
        lines = f.readlines()

    type_map = {'A': 1, 'AAAA': 28, 'MX': 15, 'TXT': 16, 'CNAME': 5}
    rcode_names = {0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'}
    type_names = {1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA'}

    for line in lines:
        line = line.strip()
        if not line:
            continue
        parts = line.split(' ')
        name = parts[0]
        qtype_str = parts[1]
        qtype = type_map[qtype_str]

        qid = random.randint(0, 65535)
        query = build_query(qid, name, qtype)

        response = send_udp('127.0.0.1', port, query, qid)

        flags = struct.unpack('!H', response[2:4])[0]
        tc = (flags >> 9) & 1

        if tc:
            response = send_tcp('127.0.0.1', port, query, qid)

        rcode, answers = parse_response(response)

        display_name = name.lower()
        if display_name.endswith('.') and display_name != '.':
            display_name = display_name[:-1]
        if display_name == '':
            display_name = '.'

        rcode_str = rcode_names.get(rcode, 'RCODE' + str(rcode))
        print(f'{display_name} {qtype_str} {rcode_str}')

        for owner, ttl, rtype, rdata_start, rdlength in answers:
            type_str = type_names.get(rtype, f'TYPE{rtype}')

            if rtype == 1:  # A
                rdata = response[rdata_start:rdata_start + rdlength]
                data_str = '.'.join(str(b) for b in rdata)
            elif rtype == 28:  # AAAA
                rdata = response[rdata_start:rdata_start + rdlength]
                data_str = format_aaaa(rdata)
            elif rtype == 5:  # CNAME
                data_str, _ = parse_name(response, rdata_start)
            elif rtype == 15:  # MX
                pref = struct.unpack('!H', response[rdata_start:rdata_start + 2])[0]
                exchange, _ = parse_name(response, rdata_start + 2)
                data_str = f'{pref} {exchange}'
            elif rtype == 16:  # TXT
                rdata = response[rdata_start:rdata_start + rdlength]
                data_str = format_txt(rdata)
            else:
                rdata = response[rdata_start:rdata_start + rdlength]
                if rdlength == 0:
                    data_str = f'\\# {rdlength}'
                else:
                    data_str = f'\\# {rdlength} {rdata.hex()}'

            print(f'  {owner} {ttl} {type_str} {data_str}')


if __name__ == '__main__':
    main()

import * as fs from "fs";
import * as path from "path";
import * as dgram from "dgram";
import * as net from "net";
import * as crypto from "crypto";

const args = process.argv.slice(2);
const dir = args[0];
const port = parseInt(args[1]);

const content = fs.readFileSync(path.join(dir, "queries.txt"), "utf-8");
const lines = content.split("\n");

const typeToNum: Record<string, number> = { A: 1, AAAA: 28, MX: 15, TXT: 16, CNAME: 5 };
const numToType: Record<number, string> = { 1: "A", 5: "CNAME", 15: "MX", 16: "TXT", 28: "AAAA" };
const rcodeNames: Record<number, string> = {
  0: "NOERROR", 1: "FORMERR", 2: "SERVFAIL", 3: "NXDOMAIN", 4: "NOTIMP", 5: "REFUSED",
};

function buildQuery(name: string, type: string): { buf: Buffer; id: number } {
  const id = crypto.randomBytes(2).readUInt16BE(0);
  const trimmed = name.replace(/\.$/, "");
  const labels = trimmed === "" ? [] : trimmed.split(".");

  const parts: number[] = [];
  for (const label of labels) {
    parts.push(label.length);
    for (let i = 0; i < label.length; i++) {
      parts.push(label.charCodeAt(i));
    }
  }
  parts.push(0);

  const qtype = typeToNum[type];
  const buf = Buffer.alloc(12 + parts.length + 4);
  buf.writeUInt16BE(id, 0);
  buf.writeUInt16BE(0x0100, 2);
  buf.writeUInt16BE(1, 4);
  buf.writeUInt16BE(0, 6);
  buf.writeUInt16BE(0, 8);
  buf.writeUInt16BE(0, 10);

  let off = 12;
  for (const b of parts) buf[off++] = b;
  buf.writeUInt16BE(qtype, off); off += 2;
  buf.writeUInt16BE(1, off);

  return { buf, id };
}

function parseName(buf: Buffer, offset: number): [string, number] {
  const labels: string[] = [];
  let jumped = false;
  let nextOffset = -1;

  while (true) {
    if (offset >= buf.length) break;
    const len = buf[offset];
    if (len === 0) {
      if (!jumped) nextOffset = offset + 1;
      break;
    }
    if ((len & 0xc0) === 0xc0) {
      const ptr = ((len & 0x3f) << 8) | buf[offset + 1];
      if (!jumped) nextOffset = offset + 2;
      offset = ptr;
      jumped = true;
    } else {
      labels.push(buf.slice(offset + 1, offset + 1 + len).toString("ascii"));
      offset += 1 + len;
    }
  }

  let name = labels.join(".").toLowerCase();
  if (name === "") name = ".";
  return [name, nextOffset];
}

interface DnsRecord {
  owner: string;
  ttl: number;
  type: number;
  rdataOffset: number;
  rdlength: number;
}

interface DnsResponse {
  rcode: number;
  tc: boolean;
  answers: DnsRecord[];
}

function parseResponse(buf: Buffer): DnsResponse {
  const flags = buf.readUInt16BE(2);
  const tc = (flags & 0x0200) !== 0;
  const rcode = flags & 0x000f;
  const qdcount = buf.readUInt16BE(4);
  const ancount = buf.readUInt16BE(6);

  let offset = 12;
  for (let i = 0; i < qdcount; i++) {
    [, offset] = parseName(buf, offset);
    offset += 4;
  }

  const answers: DnsRecord[] = [];
  for (let i = 0; i < ancount; i++) {
    const [owner, off1] = parseName(buf, offset);
    offset = off1;
    const type = buf.readUInt16BE(offset); offset += 2;
    offset += 2; // CLASS
    const ttl = buf.readUInt32BE(offset); offset += 4;
    const rdlength = buf.readUInt16BE(offset); offset += 2;
    const rdataOffset = offset;
    offset += rdlength;
    answers.push({ owner, ttl, type, rdataOffset, rdlength });
  }

  return { rcode, tc, answers };
}

function sendUDP(query: Buffer, id: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = dgram.createSocket("udp4");
    let done = false;
    socket.on("message", (msg) => {
      if (done) return;
      if (msg.length >= 4) {
        const msgId = msg.readUInt16BE(0);
        const flags = msg.readUInt16BE(2);
        const qr = (flags & 0x8000) !== 0;
        if (qr && msgId === id) {
          done = true;
          socket.close();
          resolve(msg);
        }
      }
    });
    socket.on("error", (err) => {
      if (!done) { done = true; socket.close(); reject(err); }
    });
    socket.send(query, 0, query.length, port, "127.0.0.1", (err) => {
      if (err && !done) { done = true; socket.close(); reject(err); }
    });
  });
}

function sendTCP(query: Buffer): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection({ host: "127.0.0.1", port }, () => {
      const lenBuf = Buffer.alloc(2);
      lenBuf.writeUInt16BE(query.length, 0);
      socket.write(Buffer.concat([lenBuf, query]));
    });

    const chunks: Buffer[] = [];
    let totalLen = -1;
    let done = false;

    socket.on("data", (data) => {
      if (done) return;
      chunks.push(data);
      const combined = Buffer.concat(chunks);
      if (totalLen === -1 && combined.length >= 2) {
        totalLen = combined.readUInt16BE(0);
      }
      if (totalLen !== -1 && combined.length >= 2 + totalLen) {
        done = true;
        socket.end();
        resolve(combined.slice(2, 2 + totalLen));
      }
    });

    socket.on("error", (err) => {
      if (!done) { done = true; socket.destroy(); reject(err); }
    });
  });
}

function formatAAAA(buf: Buffer): string {
  const groups: string[] = [];
  for (let i = 0; i < 8; i++) {
    groups.push(buf.readUInt16BE(i * 2).toString(16));
  }

  let bestStart = -1, bestLen = 0;
  let curStart = -1, curLen = 0;
  for (let i = 0; i < 8; i++) {
    if (groups[i] === "0") {
      if (curStart === -1) { curStart = i; curLen = 1; }
      else curLen++;
    } else {
      if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }
      curStart = -1; curLen = 0;
    }
  }
  if (curLen > bestLen) { bestStart = curStart; bestLen = curLen; }

  if (bestLen < 2) return groups.join(":");

  const before = groups.slice(0, bestStart).join(":");
  const after = groups.slice(bestStart + bestLen).join(":");
  return before + "::" + after;
}

function formatTXT(rdata: Buffer): string {
  const parts: string[] = [];
  let offset = 0;
  while (offset < rdata.length) {
    const len = rdata[offset];
    offset++;
    let str = '"';
    for (let i = 0; i < len; i++) {
      const b = rdata[offset + i];
      if (b === 0x22) str += '\\"';
      else if (b === 0x5c) str += "\\\\";
      else if (b >= 0x20 && b <= 0x7e) str += String.fromCharCode(b);
      else str += "\\" + b.toString(10).padStart(3, "0");
    }
    str += '"';
    offset += len;
    parts.push(str);
  }
  return parts.join(" ");
}

function formatRecord(msg: Buffer, rec: DnsRecord): string {
  const typeName = numToType[rec.type] || `TYPE${rec.type}`;
  let data: string;

  switch (rec.type) {
    case 1:
      data = `${msg[rec.rdataOffset]}.${msg[rec.rdataOffset + 1]}.${msg[rec.rdataOffset + 2]}.${msg[rec.rdataOffset + 3]}`;
      break;
    case 28:
      data = formatAAAA(msg.slice(rec.rdataOffset, rec.rdataOffset + rec.rdlength));
      break;
    case 5:
      [data] = parseName(msg, rec.rdataOffset);
      break;
    case 15: {
      const pref = msg.readUInt16BE(rec.rdataOffset);
      const [exchange] = parseName(msg, rec.rdataOffset + 2);
      data = `${pref} ${exchange}`;
      break;
    }
    case 16:
      data = formatTXT(msg.slice(rec.rdataOffset, rec.rdataOffset + rec.rdlength));
      break;
    default:
      if (rec.rdlength === 0) {
        data = "\\# 0";
      } else {
        const hex = msg.slice(rec.rdataOffset, rec.rdataOffset + rec.rdlength).toString("hex");
        data = `\\# ${rec.rdlength} ${hex}`;
      }
      break;
  }

  return `  ${rec.owner} ${rec.ttl} ${typeName} ${data}`;
}

function formatQueryName(name: string): string {
  const trimmed = name.replace(/\.$/, "").toLowerCase();
  return trimmed === "" ? "." : trimmed;
}

async function main() {
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === "") continue;

    const parts = trimmed.split(" ");
    const name = parts[0];
    const type = parts[1];

    const { buf: query, id } = buildQuery(name, type);

    let respBuf = await sendUDP(query, id);
    let resp = parseResponse(respBuf);

    if (resp.tc) {
      respBuf = await sendTCP(query);
      resp = parseResponse(respBuf);
    }

    const rcodeStr = rcodeNames[resp.rcode] || `RCODE${resp.rcode}`;
    const outName = formatQueryName(name);

    console.log(`${outName} ${type} ${rcodeStr}`);

    for (const rec of resp.answers) {
      console.log(formatRecord(respBuf, rec));
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import Foundation

// ==================== BigInt ====================
struct BigInt: Equatable {
    var neg: Bool
    var limbs: [Int64] // base 10^9, least significant first
    static let BASE: Int64 = 1_000_000_000

    var isZero: Bool { limbs.isEmpty }
    static let zero = BigInt(neg: false, limbs: [])
    static let one = BigInt(neg: false, limbs: [1])

    init(neg: Bool, limbs: [Int64]) {
        var l = limbs
        while l.last == 0 { l.removeLast() }
        self.neg = l.isEmpty ? false : neg
        self.limbs = l
    }

    init(_ i: Int64) {
        if i == 0 { neg = false; limbs = [] }
        else {
            neg = i < 0
            var v = i < 0 ? -i : i
            var l: [Int64] = []
            while v > 0 { l.append(v % BigInt.BASE); v /= BigInt.BASE }
            limbs = l
        }
    }

    init(neg: Bool, decimalString s: String) {
        var l: [Int64] = []
        var i = s.count - 1
        while i >= 0 {
            var chunk: Int64 = 0
            var mul: Int64 = 1
            var j = 0
            while j < 9 && i >= 0 {
                let ch = s[s.index(s.startIndex, offsetBy: i)]
                chunk += Int64(ch.asciiValue! - 48) * mul
                mul *= 10
                i -= 1; j += 1
            }
            l.append(chunk)
        }
        self.init(neg: neg, limbs: l)
    }

    func toDecimalString() -> String {
        if isZero { return "0" }
        var s = String(limbs.last!)
        for i in stride(from: limbs.count - 2, through: 0, by: -1) {
            s += String(format: "%09lld", limbs[i])
        }
        return s
    }

    static func cmpMag(_ a: BigInt, _ b: BigInt) -> Int {
        if a.limbs.count != b.limbs.count { return a.limbs.count < b.limbs.count ? -1 : 1 }
        for i in stride(from: a.limbs.count - 1, through: 0, by: -1) {
            if a.limbs[i] != b.limbs[i] { return a.limbs[i] < b.limbs[i] ? -1 : 1 }
        }
        return 0
    }

    static func < (a: BigInt, b: BigInt) -> Bool {
        if a.isZero && b.isZero { return false }
        if a.neg != b.neg {
            if !a.neg && b.neg { return false }
            if a.neg && !b.neg { return true }
        }
        let c = cmpMag(a, b)
        return a.neg ? c > 0 : c < 0
    }

    static func <= (a: BigInt, b: BigInt) -> Bool { return !(b < a) }
    static func > (a: BigInt, b: BigInt) -> Bool { return b < a }
    static func >= (a: BigInt, b: BigInt) -> Bool { return !(a < b) }

    static func addMag(_ a: [Int64], _ b: [Int64]) -> [Int64] {
        var result: [Int64] = []
        var carry: Int64 = 0
        let n = max(a.count, b.count)
        for i in 0..<n {
            var sum = carry
            if i < a.count { sum += a[i] }
            if i < b.count { sum += b[i] }
            if sum >= BigInt.BASE { sum -= BigInt.BASE; carry = 1 } else { carry = 0 }
            result.append(sum)
        }
        if carry > 0 { result.append(carry) }
        return result
    }

    static func subMag(_ a: [Int64], _ b: [Int64]) -> [Int64] {
        var result: [Int64] = []
        var borrow: Int64 = 0
        for i in 0..<a.count {
            var diff = a[i] - borrow
            if i < b.count { diff -= b[i] }
            if diff < 0 { diff += BigInt.BASE; borrow = 1 } else { borrow = 0 }
            result.append(diff)
        }
        return result
    }

    static func + (a: BigInt, b: BigInt) -> BigInt {
        if a.isZero { return b }
        if b.isZero { return a }
        if a.neg == b.neg { return BigInt(neg: a.neg, limbs: addMag(a.limbs, b.limbs)) }
        let c = cmpMag(a, b)
        if c == 0 { return .zero }
        if c > 0 { return BigInt(neg: a.neg, limbs: subMag(a.limbs, b.limbs)) }
        else { return BigInt(neg: b.neg, limbs: subMag(b.limbs, a.limbs)) }
    }

    static func - (a: BigInt, b: BigInt) -> BigInt {
        return a + BigInt(neg: !b.neg, limbs: b.limbs)
    }

    static func negate(_ a: BigInt) -> BigInt {
        if a.isZero { return a }
        return BigInt(neg: !a.neg, limbs: a.limbs)
    }

    static func abs(_ a: BigInt) -> BigInt {
        return BigInt(neg: false, limbs: a.limbs)
    }

    static func * (a: BigInt, b: BigInt) -> BigInt {
        if a.isZero || b.isZero { return .zero }
        let n = a.limbs.count, m = b.limbs.count
        var result = [Int64](repeating: 0, count: n + m)
        for i in 0..<n {
            var carry: Int64 = 0
            for j in 0..<m {
                let prod = a.limbs[i] &* b.limbs[j] &+ result[i+j] &+ carry
                result[i+j] = prod % BigInt.BASE
                carry = prod / BigInt.BASE
            }
            result[i+m] += carry
        }
        return BigInt(neg: a.neg != b.neg, limbs: result)
    }

    static func mul10(_ a: BigInt) -> BigInt {
        if a.isZero { return a }
        var limbs = a.limbs
        var carry: Int64 = 0
        for i in 0..<limbs.count {
            let v = limbs[i] * 10 + carry
            limbs[i] = v % BigInt.BASE
            carry = v / BigInt.BASE
        }
        if carry > 0 { limbs.append(carry) }
        return BigInt(neg: a.neg, limbs: limbs)
    }

    static func mulPow10(_ a: BigInt, _ k: Int) -> BigInt {
        if k == 0 || a.isZero { return a }
        var r = a
        for _ in 0..<k { r = mul10(r) }
        return r
    }

    static func divmod10(_ a: BigInt) -> (BigInt, Int64) {
        if a.isZero { return (.zero, 0) }
        var limbs = a.limbs
        var rem: Int64 = 0
        for i in stride(from: limbs.count - 1, through: 0, by: -1) {
            let cur = rem * BigInt.BASE + limbs[i]
            limbs[i] = cur / 10
            rem = cur % 10
        }
        return (BigInt(neg: a.neg, limbs: limbs), rem)
    }

    static func divmodPow10(_ a: BigInt, _ k: Int) -> (BigInt, BigInt) {
        if k == 0 { return (a, .zero) }
        var q = a
        var rem: BigInt = .zero
        var power: BigInt = .one
        for _ in 0..<k {
            let (nq, r) = divmod10(q)
            q = nq
            rem = rem + BigInt(r) * power
            power = power * BigInt(10)
        }
        return (q, rem)
    }

    // General divmod for non-negative a, positive b
    static func divmod(_ a: BigInt, _ b: BigInt) -> (BigInt, BigInt) {
        if a < b { return (.zero, a) }
        let aStr = a.toDecimalString()
        let bStr = b.toDecimalString()
        var quotient = ""
        var remainderStr = ""
        for ch in aStr {
            remainderStr.append(ch)
            while remainderStr.count > 1 && remainderStr.first == "0" { remainderStr.removeFirst() }
            if remainderStr == "0" { quotient.append("0"); continue }
            var rem = BigInt(neg: false, decimalString: remainderStr)
            var count = 0
            while rem >= b { rem = rem - b; count += 1 }
            quotient.append(String(count))
            remainderStr = rem.toDecimalString()
        }
        while quotient.count > 1 && quotient.first == "0" { quotient.removeFirst() }
        let q = quotient.isEmpty ? BigInt.zero : BigInt(neg: false, decimalString: quotient)
        let r = remainderStr.isEmpty ? BigInt.zero : BigInt(neg: false, decimalString: remainderStr)
        return (q, r)
    }
}

// ==================== BigDecimal ====================
struct BigDecimal {
    var val: BigInt
    var scale: Int
    static let zero = BigDecimal(val: .zero, scale: 0)

    func round(to places: Int) -> BigDecimal {
        if scale <= places {
            let k = places - scale
            return BigDecimal(val: BigInt.mulPow10(val, k), scale: places)
        } else {
            let k = scale - places
            let absVal = BigInt(neg: false, limbs: val.limbs)
            let (q, r) = BigInt.divmodPow10(absVal, k)
            let half: BigInt
            if k == 0 { half = .zero }
            else { half = BigInt.mulPow10(BigInt(5), k - 1) }
            var qFinal: BigInt
            if r < half { qFinal = q }
            else if r > half { qFinal = q + BigInt.one }
            else {
                let lastDigit: Int64 = q.isZero ? 0 : (q.limbs[0] % 10)
                if lastDigit % 2 == 0 { qFinal = q } else { qFinal = q + BigInt.one }
            }
            if val.neg && !qFinal.isZero {
                qFinal = BigInt(neg: true, limbs: qFinal.limbs)
            }
            return BigDecimal(val: qFinal, scale: places)
        }
    }

    static func alignScales(_ a: BigDecimal, _ b: BigDecimal) -> (BigInt, BigInt) {
        let maxScale = max(a.scale, b.scale)
        let av = BigInt.mulPow10(a.val, maxScale - a.scale)
        let bv = BigInt.mulPow10(b.val, maxScale - b.scale)
        return (av, bv)
    }

    static func + (a: BigDecimal, b: BigDecimal) -> BigDecimal {
        let (av, bv) = alignScales(a, b)
        return BigDecimal(val: av + bv, scale: max(a.scale, b.scale))
    }

    static func - (a: BigDecimal, b: BigDecimal) -> BigDecimal {
        let (av, bv) = alignScales(a, b)
        return BigDecimal(val: av - bv, scale: max(a.scale, b.scale))
    }

    static func * (a: BigDecimal, b: BigDecimal) -> BigDecimal {
        return BigDecimal(val: a.val * b.val, scale: a.scale + b.scale)
    }
}

// ==================== Parsing ====================
func parseBigDecimal(_ s: String) -> BigDecimal {
    var str = s
    var neg = false
    if str.first == "-" { neg = true; str.removeFirst() }
    else if str.first == "+" { str.removeFirst() }
    var intPart = ""
    var fracPart = ""
    if let dotIdx = str.firstIndex(of: ".") {
        intPart = String(str[str.startIndex..<dotIdx])
        fracPart = String(str[str.index(after: dotIdx)...])
    } else {
        intPart = str
    }
    if intPart.isEmpty { intPart = "0" }
    // Remove leading zeros from intPart but keep at least one digit
    while intPart.count > 1 && intPart.first == "0" { intPart.removeFirst() }
    let allDigits = intPart + fracPart
    // Remove leading zeros
    var digits = allDigits
    while digits.count > 1 && digits.first == "0" { digits.removeFirst() }
    if digits == "0" { return BigDecimal(val: .zero, scale: fracPart.count) }
    let bi = BigInt(neg: neg, decimalString: digits)
    return BigDecimal(val: bi, scale: fracPart.count)
}

// ==================== Formatting ====================
func addCommas(_ s: String) -> String {
    var result = ""
    let chars = Array(s)
    for (i, c) in chars.enumerated() {
        if i > 0 && (chars.count - i) % 3 == 0 { result.append(",") }
        result.append(c)
    }
    return result
}

func formatMoney(_ val: BigInt, minorUnits: Int) -> String {
    if val.isZero {
        if minorUnits == 0 { return "0" }
        return "0." + String(repeating: "0", count: minorUnits)
    }
    let isNeg = val.neg
    let absVal = BigInt(neg: false, limbs: val.limbs)
    let (intPart, fracPart) = BigInt.divmodPow10(absVal, minorUnits)
    var intStr = intPart.toDecimalString()
    intStr = addCommas(intStr)
    if minorUnits == 0 {
        return (isNeg ? "-" : "") + intStr
    }
    var fracStr = fracPart.toDecimalString()
    while fracStr.count < minorUnits { fracStr = "0" + fracStr }
    return (isNeg ? "-" : "") + intStr + "." + fracStr
}

// ==================== Main ====================
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
let filePath = dir + "/ledger.txt"
guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else { exit(1) }

let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]  // code -> minorUnits
struct Account {
    var code: String
    var balance: BigInt
    var limit: BigInt
}
var accounts: [String: Account] = [:]
var rejections: [(Int, String)] = []

for (idx, line) in lines.enumerated() {
    let lineNum = idx + 1
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    if trimmed.first == "#" { continue }

    let tokens = line.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
    guard !tokens.isEmpty else { continue }
    let cmd = tokens[0]

    switch cmd {
    case "currency":
        guard tokens.count >= 3 else { continue }
        let code = tokens[1]
        let mu = Int(tokens[2]) ?? 0
        currencies[code] = mu

    case "open":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        let code = tokens[2]
        if accounts[name] != nil {
            rejections.append((lineNum, "account exists \(name)"))
            continue
        }
        let mu = currencies[code] ?? 2
        var limitVal: BigInt = .zero
        if tokens.count >= 4 {
            let limitBD = parseBigDecimal(tokens[3]).round(to: mu)
            limitVal = limitBD.val
            if limitVal.neg { limitVal = BigInt(neg: false, limbs: limitVal.limbs) }
        }
        accounts[name] = Account(code: code, balance: .zero, limit: limitVal)

    case "deposit":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        guard let acct = accounts[name] else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code] ?? 2
        let amountBD = parseBigDecimal(tokens[2]).round(to: mu)
        let amount = amountBD.val
        if amount <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        accounts[name]!.balance = accounts[name]!.balance + amount

    case "withdraw":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        guard let acct = accounts[name] else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code] ?? 2
        let amountBD = parseBigDecimal(tokens[2]).round(to: mu)
        let amount = amountBD.val
        if amount <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = acct.balance - amount
        let negLimit = BigInt(neg: true, limbs: acct.limit.limbs)
        if newBal < negLimit {
            rejections.append((lineNum, "insufficient funds \(name)"))
            continue
        }
        accounts[name]!.balance = newBal

    case "transfer":
        guard tokens.count >= 4 else { continue }
        let from = tokens[1], to = tokens[2]
        guard let acctFrom = accounts[from] else {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        guard let acctTo = accounts[to] else {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        if acctFrom.code != acctTo.code {
            rejections.append((lineNum, "currency mismatch"))
            continue
        }
        let mu = currencies[acctFrom.code] ?? 2
        let amountBD = parseBigDecimal(tokens[3]).round(to: mu)
        let amount = amountBD.val
        if amount <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = acctFrom.balance - amount
        let negLimit = BigInt(neg: true, limbs: acctFrom.limit.limbs)
        if newBal < negLimit {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        accounts[from]!.balance = newBal
        accounts[to]!.balance = acctTo.balance + amount

    case "convert":
        guard tokens.count >= 5 else { continue }
        let from = tokens[1], to = tokens[2]
        guard let acctFrom = accounts[from] else {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        guard let acctTo = accounts[to] else {
            rejections.append((lineNum, "unknown account \(to)"))
            continue
        }
        let fromMu = currencies[acctFrom.code] ?? 2
        let toMu = currencies[acctTo.code] ?? 2
        let amountBD = parseBigDecimal(tokens[3]).round(to: fromMu)
        let amount = amountBD.val
        if amount <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = acctFrom.balance - amount
        let negLimit = BigInt(neg: true, limbs: acctFrom.limit.limbs)
        if newBal < negLimit {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        let rateBD = parseBigDecimal(tokens[4])
        let amountAsBD = BigDecimal(val: amount, scale: fromMu)
        let receivedBD = (amountAsBD * rateBD).round(to: toMu)
        let received = receivedBD.val
        accounts[from]!.balance = newBal
        accounts[to]!.balance = acctTo.balance + received

    case "interest":
        guard tokens.count >= 3 else { continue }
        let name = tokens[1]
        guard let acct = accounts[name] else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code] ?? 2
        let rateBD = parseBigDecimal(tokens[2])
        let balBD = BigDecimal(val: acct.balance, scale: mu)
        let interestBD = (balBD * rateBD).round(to: mu)
        accounts[name]!.balance = acct.balance + interestBD.val

    case "split":
        guard tokens.count >= 4 else { continue }
        let from = tokens[1]
        guard let acctFrom = accounts[from] else {
            rejections.append((lineNum, "unknown account \(from)"))
            continue
        }
        // Parse targets
        var targetNames: [String] = []
        var weights: [BigInt] = []
        for i in 3..<tokens.count {
            let parts = tokens[i].split(separator: ":", maxSplits: 1)
            guard parts.count == 2 else { continue }
            let tName = String(parts[0])
            let wStr = String(parts[1])
            targetNames.append(tName)
            weights.append(BigInt(neg: false, decimalString: wStr))
        }
        // Check all targets exist
        for tn in targetNames {
            guard accounts[tn] != nil else {
                rejections.append((lineNum, "unknown account \(tn)"))
                continue
            }
        }
        // Re-check if any were rejected
        var rejected = false
        for tn in targetNames {
            if accounts[tn] == nil { rejected = true; break }
        }
        if rejected { continue }

        // Check currency mismatch
        let fromCode = acctFrom.code
        for tn in targetNames {
            if accounts[tn]!.code != fromCode {
                rejections.append((lineNum, "currency mismatch"))
                rejected = true
                break
            }
        }
        if rejected { continue }

        let mu = currencies[fromCode] ?? 2
        let amountBD = parseBigDecimal(tokens[2]).round(to: mu)
        let amount = amountBD.val
        if amount <= .zero {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = acctFrom.balance - amount
        let negLimit = BigInt(neg: true, limbs: acctFrom.limit.limbs)
        if newBal < negLimit {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        // Distribute
        let W = weights.reduce(BigInt.zero) { $0 + $1 }
        var bases: [BigInt] = []
        var rems: [BigInt] = []
        for i in 0..<targetNames.count {
            let product = amount * weights[i]
            let (q, r) = BigInt.divmod(product, W)
            bases.append(q)
            rems.append(r)
        }
        let sumBases = bases.reduce(BigInt.zero) { $0 + $1 }
        let leftover = amount - sumBases
        let leftoverCount = Int(leftover.limbs.isEmpty ? 0 : leftover.limbs[0])

        // Sort indices by remainder desc, then by index asc
        var indices = Array(0..<targetNames.count)
        indices.sort { i, j in
            if rems[i] != rems[j] { return rems[i] > rems[j] }
            return i < j
        }
        for j in 0..<leftoverCount {
            bases[indices[j]] = bases[indices[j]] + BigInt.one
        }

        accounts[from]!.balance = newBal
        for i in 0..<targetNames.count {
            accounts[targetNames[i]]!.balance = accounts[targetNames[i]]!.balance + bases[i]
        }

    default:
        break
    }
}

// ==================== Output ====================
var output = ""
for (lineNum, reason) in rejections {
    output += "line \(lineNum): REJECT \(reason)\n"
}
output += "\n"

let sortedAccounts = accounts.keys.sorted()
for name in sortedAccounts {
    let acct = accounts[name]!
    let mu = currencies[acct.code] ?? 2
    let balStr = formatMoney(acct.balance, minorUnits: mu)
    output += "\(name) \(acct.code) \(balStr)\n"
}
output += "\n"

// Currency totals
var currencyTotals: [String: (sum: BigInt, count: Int)] = [:]
for name in sortedAccounts {
    let acct = accounts[name]!
    let code = acct.code
    if currencyTotals[code] == nil {
        currencyTotals[code] = (BigInt.zero, 0)
    }
    currencyTotals[code]!.sum = currencyTotals[code]!.sum + acct.balance
    currencyTotals[code]!.count += 1
}
let sortedCurrencies = currencyTotals.keys.sorted()
for code in sortedCurrencies {
    let mu = currencies[code] ?? 2
    let (sum, count) = currencyTotals[code]!
    let sumStr = formatMoney(sum, minorUnits: mu)
    output += "total \(code) \(sumStr) (\(count) accounts)\n"
}

print(output, terminator: "")
exit(0)

import json
import sys
import os


def main():
    directory = sys.argv[1]

    with open(os.path.join(directory, 'schema.json'), 'r', encoding='utf-8') as f:
        schema = json.load(f)

    with open(os.path.join(directory, 'instances.json'), 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0
    output_lines = []

    for i, instance in enumerate(instances):
        errors = validate(instance, schema, "#", "#", schema)
        if not errors:
            output_lines.append(f"{i}: valid")
            valid_count += 1
        else:
            sorted_errors = sorted(errors, key=lambda e: (e[0], e[1]))
            output_lines.append(f"{i}: invalid ({len(sorted_errors)})")
            for inst_loc, schema_loc in sorted_errors:
                output_lines.append(f"  {inst_loc} {schema_loc}")
            invalid_count += 1

    output_lines.append(f"valid={valid_count} invalid={invalid_count}")
    print('\n'.join(output_lines))


def validate(instance, schema, instance_loc, schema_loc, root_schema):
    errors = set()

    if schema is True:
        return errors
    if schema is False:
        errors.add((instance_loc, schema_loc))
        return errors

    # type
    if 'type' in schema:
        if not check_type(instance, schema['type']):
            errors.add((instance_loc, f"{schema_loc}/type"))

    # enum
    if 'enum' in schema:
        if not any(deep_equal(instance, v) for v in schema['enum']):
            errors.add((instance_loc, f"{schema_loc}/enum"))

    # const
    if 'const' in schema:
        if not deep_equal(instance, schema['const']):
            errors.add((instance_loc, f"{schema_loc}/const"))

    # Number keywords
    if is_number(instance):
        if 'minimum' in schema:
            if not (instance >= schema['minimum']):
                errors.add((instance_loc, f"{schema_loc}/minimum"))
        if 'maximum' in schema:
            if not (instance <= schema['maximum']):
                errors.add((instance_loc, f"{schema_loc}/maximum"))
        if 'exclusiveMinimum' in schema:
            if not (instance > schema['exclusiveMinimum']):
                errors.add((instance_loc, f"{schema_loc}/exclusiveMinimum"))
        if 'exclusiveMaximum' in schema:
            if not (instance < schema['exclusiveMaximum']):
                errors.add((instance_loc, f"{schema_loc}/exclusiveMaximum"))

    # String keywords
    if isinstance(instance, str):
        if 'minLength' in schema:
            if len(instance) < schema['minLength']:
                errors.add((instance_loc, f"{schema_loc}/minLength"))
        if 'maxLength' in schema:
            if len(instance) > schema['maxLength']:
                errors.add((instance_loc, f"{schema_loc}/maxLength"))

    # Array keywords
    if isinstance(instance, list):
        if 'minItems' in schema:
            if len(instance) < schema['minItems']:
                errors.add((instance_loc, f"{schema_loc}/minItems"))
        if 'maxItems' in schema:
            if len(instance) > schema['maxItems']:
                errors.add((instance_loc, f"{schema_loc}/maxItems"))
        if 'uniqueItems' in schema and schema['uniqueItems'] is True:
            found_dup = False
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        found_dup = True
                        break
                if found_dup:
                    break
            if found_dup:
                errors.add((instance_loc, f"{schema_loc}/uniqueItems"))

        # prefixItems
        if 'prefixItems' in schema:
            prefix_items = schema['prefixItems']
            for i in range(min(len(instance), len(prefix_items))):
                sub_errors = validate(
                    instance[i], prefix_items[i],
                    f"{instance_loc}/{i}",
                    f"{schema_loc}/prefixItems/{i}",
                    root_schema
                )
                errors.update(sub_errors)

        # items
        if 'items' in schema:
            start = len(schema.get('prefixItems', []))
            for i in range(start, len(instance)):
                sub_errors = validate(
                    instance[i], schema['items'],
                    f"{instance_loc}/{i}",
                    f"{schema_loc}/items",
                    root_schema
                )
                errors.update(sub_errors)

    # Object keywords
    if isinstance(instance, dict):
        if 'properties' in schema:
            for name, subschema in schema['properties'].items():
                if name in instance:
                    sub_errors = validate(
                        instance[name], subschema,
                        f"{instance_loc}/{escape_json_pointer(name)}",
                        f"{schema_loc}/properties/{escape_json_pointer(name)}",
                        root_schema
                    )
                    errors.update(sub_errors)

        if 'required' in schema:
            for j, name in enumerate(schema['required']):
                if name not in instance:
                    errors.add((instance_loc, f"{schema_loc}/required/{j}"))

        if 'additionalProperties' in schema:
            prop_keys = set(schema.get('properties', {}).keys())
            for name in instance:
                if name not in prop_keys:
                    sub_errors = validate(
                        instance[name], schema['additionalProperties'],
                        f"{instance_loc}/{escape_json_pointer(name)}",
                        f"{schema_loc}/additionalProperties",
                        root_schema
                    )
                    errors.update(sub_errors)

        if 'minProperties' in schema:
            if len(instance) < schema['minProperties']:
                errors.add((instance_loc, f"{schema_loc}/minProperties"))
        if 'maxProperties' in schema:
            if len(instance) > schema['maxProperties']:
                errors.add((instance_loc, f"{schema_loc}/maxProperties"))

    # Applicators
    if 'allOf' in schema:
        for i, subschema in enumerate(schema['allOf']):
            sub_errors = validate(instance, subschema, instance_loc, f"{schema_loc}/allOf/{i}", root_schema)
            errors.update(sub_errors)

    if 'anyOf' in schema:
        accepted = False
        for subschema in schema['anyOf']:
            sub_errors = validate(instance, subschema, instance_loc, "", root_schema)
            if not sub_errors:
                accepted = True
                break
        if not accepted:
            errors.add((instance_loc, f"{schema_loc}/anyOf"))

    if 'oneOf' in schema:
        count = 0
        for subschema in schema['oneOf']:
            sub_errors = validate(instance, subschema, instance_loc, "", root_schema)
            if not sub_errors:
                count += 1
        if count != 1:
            errors.add((instance_loc, f"{schema_loc}/oneOf"))

    if 'not' in schema:
        sub_errors = validate(instance, schema['not'], instance_loc, "", root_schema)
        if not sub_errors:
            errors.add((instance_loc, f"{schema_loc}/not"))

    if 'if' in schema:
        if_errors = validate(instance, schema['if'], instance_loc, "", root_schema)
        if not if_errors:
            if 'then' in schema:
                sub_errors = validate(instance, schema['then'], instance_loc, f"{schema_loc}/then", root_schema)
                errors.update(sub_errors)
        else:
            if 'else' in schema:
                sub_errors = validate(instance, schema['else'], instance_loc, f"{schema_loc}/else", root_schema)
                errors.update(sub_errors)

    # $ref
    if '$ref' in schema:
        ref_schema, ref_loc = resolve_ref(schema['$ref'], root_schema)
        sub_errors = validate(instance, ref_schema, instance_loc, ref_loc, root_schema)
        errors.update(sub_errors)

    return errors


def resolve_ref(ref, root_schema):
    if ref == '#':
        return root_schema, '#'
    # Must be #/$defs/<name>
    path = ref[2:]  # Remove "#/"
    parts = path.split('/')
    if len(parts) != 2 or parts[0] != '$defs':
        return True, '#'
    name = unescape_json_pointer_token(parts[1])
    defs = root_schema.get('$defs', {})
    ref_schema = defs.get(name, True)
    ref_loc = f"#/$defs/{parts[1]}"
    return ref_schema, ref_loc


def unescape_json_pointer_token(token):
    token = token.replace('~1', '/')
    token = token.replace('~0', '~')
    return token


def escape_json_pointer(token):
    token = token.replace('~', '~0')
    token = token.replace('/', '~1')
    return token


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def is_integer(value):
    if not is_number(value):
        return False
    return value == int(value)


def check_type(instance, type_spec):
    if isinstance(type_spec, str):
        types = [type_spec]
    else:
        types = type_spec

    for t in types:
        if t == 'null' and instance is None:
            return True
        if t == 'boolean' and isinstance(instance, bool):
            return True
        if t == 'number' and is_number(instance):
            return True
        if t == 'integer' and is_integer(instance):
            return True
        if t == 'string' and isinstance(instance, str):
            return True
        if t == 'array' and isinstance(instance, list):
            return True
        if t == 'object' and isinstance(instance, dict):
            return True
    return False


def deep_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if a is None:
        return b is None
    if b is None:
        return False
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(deep_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(deep_equal(a[k], b[k]) for k in a)
    return False


if __name__ == '__main__':
    main()

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::{SocketAddr, TcpStream, UdpSocket};

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap();

    let queries_path = format!("{}/queries.txt", dir);
    let content = fs::read_to_string(&queries_path).unwrap();

    let server_addr: SocketAddr = format!("127.0.0.1:{}", port).parse().unwrap();
    let mut out = String::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let space_pos = trimmed.find(' ').unwrap();
        let name = &trimmed[..space_pos];
        let qtype_str = trimmed[space_pos + 1..].trim();

        let id = random_id();
        let query = build_query(id, name, qtype_str);

        let mut resp = udp_query(&server_addr, &query, id);
        if resp.len() >= 12 && (resp[2] & 0x02) != 0 {
            resp = tcp_query(&server_addr, &query, id);
        }

        parse_and_print(&mut out, name, qtype_str, &resp);
    }

    let mut stdout = std::io::stdout();
    stdout.write_all(out.as_bytes()).unwrap();
    stdout.flush().unwrap();
}

fn random_id() -> u16 {
    use std::fs::File;
    let mut f = File::open("/dev/urandom").unwrap();
    let mut buf = [0u8; 2];
    f.read_exact(&mut buf).unwrap();
    u16::from_be_bytes(buf)
}

fn qtype_num(t: &str) -> u16 {
    match t {
        "A" => 1,
        "CNAME" => 5,
        "MX" => 15,
        "TXT" => 16,
        "AAAA" => 28,
        _ => 0,
    }
}

fn build_query(id: u16, name: &str, qtype_str: &str) -> Vec<u8> {
    let mut msg = Vec::new();
    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&0x0100u16.to_be_bytes()); // flags
    msg.extend_from_slice(&1u16.to_be_bytes()); // QDCOUNT
    msg.extend_from_slice(&0u16.to_be_bytes()); // ANCOUNT
    msg.extend_from_slice(&0u16.to_be_bytes()); // NSCOUNT
    msg.extend_from_slice(&0u16.to_be_bytes()); // ARCOUNT

    // QNAME
    let name_no_dot = name.trim_end_matches('.');
    if !name_no_dot.is_empty() {
        for label in name_no_dot.split('.') {
            msg.push(label.len() as u8);
            msg.extend_from_slice(label.as_bytes());
        }
    }
    msg.push(0);

    // QTYPE
    let qt = qtype_num(qtype_str);
    msg.extend_from_slice(&qt.to_be_bytes());
    // QCLASS
    msg.extend_from_slice(&1u16.to_be_bytes());

    msg
}

fn udp_query(addr: &SocketAddr, query: &[u8], expected_id: u16) -> Vec<u8> {
    let sock = UdpSocket::bind("0.0.0.0:0").unwrap();
    sock.connect(addr).unwrap();
    sock.send(query).unwrap();

    let mut buf = vec![0u8; 65535];
    loop {
        let (n, _) = sock.recv_from(&mut buf).unwrap();
        let data = &buf[..n];
        if data.len() >= 12 {
            let rid = u16::from_be_bytes([data[0], data[1]]);
            let qr = (data[2] & 0x80) != 0;
            if qr && rid == expected_id {
                return data.to_vec();
            }
        }
    }
}

fn tcp_query(addr: &SocketAddr, query: &[u8], _expected_id: u16) -> Vec<u8> {
    let mut stream = TcpStream::connect(addr).unwrap();
    let len_bytes = (query.len() as u16).to_be_bytes();
    stream.write_all(&len_bytes).unwrap();
    stream.write_all(query).unwrap();
    stream.flush().unwrap();

    let mut lb = [0u8; 2];
    read_exact(&mut stream, &mut lb);
    let msg_len = u16::from_be_bytes(lb) as usize;
    let mut buf = vec![0u8; msg_len];
    read_exact(&mut stream, &mut buf);
    buf
}

fn read_exact(stream: &mut TcpStream, buf: &mut [u8]) {
    let mut off = 0;
    while off < buf.len() {
        let n = stream.read(&mut buf[off..]).unwrap();
        if n == 0 {
            panic!("EOF");
        }
        off += n;
    }
}

fn parse_name(msg: &[u8], start: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = start;
    let mut next_offset: Option<usize> = None;

    loop {
        if pos >= msg.len() {
            break;
        }
        let len = msg[pos] as usize;
        if len == 0 {
            if next_offset.is_none() {
                next_offset = Some(pos + 1);
            }
            break;
        }
        if len & 0xC0 == 0xC0 {
            let ptr = ((len & 0x3F) << 8) | (msg[pos + 1] as usize);
            if next_offset.is_none() {
                next_offset = Some(pos + 2);
            }
            pos = ptr;
        } else {
            let label = String::from_utf8_lossy(&msg[pos + 1..pos + 1 + len])
                .to_lowercase();
            labels.push(label);
            pos += 1 + len;
        }
    }

    let name = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    };
    (name, next_offset.unwrap_or(pos))
}

fn parse_and_print(out: &mut String, qname: &str, qtype_str: &str, msg: &[u8]) {
    if msg.len() < 12 {
        return;
    }
    let rcode = (msg[3] & 0x0F) as u16;
    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let rcode_str = match rcode {
        0 => "NOERROR",
        1 => "FORMERR",
        2 => "SERVFAIL",
        3 => "NXDOMAIN",
        4 => "NOTIMP",
        5 => "REFUSED",
        n => {
            // We'll handle this below
            let _ = n;
            ""
        }
    };
    let rcode_str = if rcode_str.is_empty() {
        format!("RCODE{}", rcode)
    } else {
        rcode_str.to_string()
    };

    // Format query name for output
    let out_name = {
        let lower = qname.to_lowercase();
        let trimmed = lower.trim_end_matches('.');
        if trimmed.is_empty() {
            ".".to_string()
        } else {
            trimmed.to_string()
        }
    };

    out.push_str(&format!("{} {} {}\n", out_name, qtype_str, rcode_str));

    // Skip question section
    let mut pos = 12;
    for _ in 0..qdcount {
        let (_, next) = parse_name(msg, pos);
        pos = next;
        pos += 4; // QTYPE + QCLASS
    }

    // Parse answer section
    for _ in 0..ancount {
        if pos + 10 > msg.len() {
            break;
        }
        let (owner, next) = parse_name(msg, pos);
        pos = next;
        if pos + 10 > msg.len() {
            break;
        }
        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        // rclass = u16::from_be_bytes([msg[pos+2], msg[pos+3]]);
        let ttl = u32::from_be_bytes([msg[pos + 4], msg[pos + 5], msg[pos + 6], msg[pos + 7]]);
        let rdlen = u16::from_be_bytes([msg[pos + 8], msg[pos + 9]]) as usize;
        pos += 10;
        let rdata = &msg[pos..pos + rdlen];
        pos += rdlen;

        let type_str = match rtype {
            1 => "A",
            5 => "CNAME",
            15 => "MX",
            16 => "TXT",
            28 => "AAAA",
            n => {
                let s = format!("TYPE{}", n);
                out.push_str(&format!("  {} {} {} {}\n", owner, ttl, s, format_unknown(rdata)));
                continue;
            }
        };

        let data_str = match rtype {
            1 => {
                if rdata.len() >= 4 {
                    format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3])
                } else {
                    String::new()
                }
            }
            5 => {
                let (target, _) = parse_name(msg, pos - rdlen);
                target
            }
            15 => {
                if rdata.len() >= 3 {
                    let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                    let (exchange, _) = parse_name(msg, pos - rdlen + 2);
                    format!("{} {}", pref, exchange)
                } else {
                    String::new()
                }
            }
            16 => {
                format_txt(rdata)
            }
            28 => {
                if rdata.len() >= 16 {
                    format_ipv6(&rdata[..16])
                } else {
                    String::new()
                }
            }
            _ => String::new(),
        };

        out.push_str(&format!("  {} {} {} {}\n", owner, ttl, type_str, data_str));
    }
}

fn format_unknown(rdata: &[u8]) -> String {
    if rdata.is_empty() {
        format!("\\# 0")
    } else {
        let hex: String = rdata.iter().map(|b| format!("{:02x}", b)).collect();
        format!("\\# {} {}", rdata.len(), hex)
    }
}

fn format_txt(rdata: &[u8]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut i = 0;
    while i < rdata.len() {
        let len = rdata[i] as usize;
        i += 1;
        if i + len > rdata.len() {
            break;
        }
        let chars = &rdata[i..i + len];
        i += len;
        let mut s = String::from("\"");
        for &b in chars {
            if b == b'"' {
                s.push_str("\\\"");
            } else if b == b'\\' {
                s.push_str("\\\\");
            } else if b >= 0x20 && b <= 0x7E {
                s.push(b as char);
            } else {
                s.push_str(&format!("\\{:03}", b));
            }
        }
        s.push('"');
        parts.push(s);
    }
    parts.join(" ")
}

fn format_ipv6(bytes: &[u8]) -> String {
    let groups: Vec<u16> = (0..8)
        .map(|i| u16::from_be_bytes([bytes[i * 2], bytes[i * 2 + 1]]))
        .collect();

    // Find longest run of >=2 consecutive zero groups (first if tie)
    let mut best_start = usize::MAX;
    let mut best_len: usize = 0;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let run_len = i - start;
            if run_len >= 2 && run_len > best_len {
                best_len = run_len;
                best_start = start;
            }
        } else {
            i += 1;
        }
    }

    if best_len >= 2 {
        let mut parts: Vec<String> = Vec::new();
        for j in 0..best_start {
            parts.push(format!("{:x}", groups[j]));
        }
        let mut result = parts.join(":");
        result.push_str("::");
        let mut parts2: Vec<String> = Vec::new();
        for j in (best_start + best_len)..8 {
            parts2.push(format!("{:x}", groups[j]));
        }
        result.push_str(&parts2.join(":"));
        result
    } else {
        let parts: Vec<String> = groups.iter().map(|g| format!("{:x}", g)).collect();
        parts.join(":")
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

#[derive(Clone, Debug)]
struct BigNum {
    neg: bool,
    digits: Vec<u8>,
}

impl BigNum {
    fn zero() -> Self { BigNum { neg: false, digits: vec![] } }
    fn is_zero(&self) -> bool { self.digits.is_empty() }

    fn from_u64(mut n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut d = Vec::new();
        while n > 0 { d.push((n % 10) as u8); n /= 10; }
        BigNum { neg: false, digits: d }
    }

    fn from_str(s: &str) -> Self {
        let mut d = Vec::new();
        for &c in s.as_bytes().iter().rev() { d.push(c - b'0'); }
        while d.last() == Some(&0) { d.pop(); }
        if d.is_empty() { Self::zero() } else { BigNum { neg: false, digits: d } }
    }

    fn cmp_abs(&self, o: &Self) -> Ordering {
        if self.digits.len() != o.digits.len() { return self.digits.len().cmp(&o.digits.len()); }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != o.digits[i] { return self.digits[i].cmp(&o.digits[i]); }
        }
        Ordering::Equal
    }

    fn add_abs(a: &Self, b: &Self) -> Self {
        let mut r = Vec::new();
        let mut c = 0u8;
        let n = a.digits.len().max(b.digits.len());
        for i in 0..n {
            let da = if i < a.digits.len() { a.digits[i] as u16 } else { 0 };
            let db = if i < b.digits.len() { b.digits[i] as u16 } else { 0 };
            let s = da + db + c as u16;
            r.push((s % 10) as u8);
            c = (s / 10) as u8;
        }
        if c > 0 { r.push(c); }
        while r.last() == Some(&0) { r.pop(); }
        if r.is_empty() { Self::zero() } else { BigNum { neg: false, digits: r } }
    }

    fn sub_abs(a: &Self, b: &Self) -> Self {
        let mut r = Vec::new();
        let mut borrow = 0i16;
        for i in 0..a.digits.len() {
            let da = a.digits[i] as i16;
            let db = if i < b.digits.len() { b.digits[i] as i16 } else { 0 };
            let mut d = da - db - borrow;
            if d < 0 { d += 10; borrow = 1; } else { borrow = 0; }
            r.push(d as u8);
        }
        while r.last() == Some(&0) { r.pop(); }
        if r.is_empty() { Self::zero() } else { BigNum { neg: false, digits: r } }
    }

    fn mul(a: &Self, b: &Self) -> Self {
        if a.is_zero() || b.is_zero() { return Self::zero(); }
        let n = a.digits.len(); let m = b.digits.len();
        let mut r = vec![0u32; n + m];
        for i in 0..n {
            let mut carry = 0u32;
            for j in 0..m {
                let p = (a.digits[i] as u32) * (b.digits[j] as u32) + r[i+j] + carry;
                r[i+j] = p % 10; carry = p / 10;
            }
            let mut pos = i + m;
            while carry > 0 { let s = r[pos] + carry; r[pos] = s % 10; carry = s / 10; pos += 1; }
        }
        let mut d: Vec<u8> = r.iter().map(|&x| x as u8).collect();
        while d.last() == Some(&0) { d.pop(); }
        if d.is_empty() { Self::zero() } else { BigNum { neg: a.neg != b.neg, digits: d } }
    }

    fn div_mod(a: &Self, b: &Self) -> (Self, Self) {
        if a.cmp_abs(b) == Ordering::Less { return (Self::zero(), a.clone()); }
        let mut q = vec![0u8; a.digits.len()];
        let mut rem = Self::zero();
        for i in (0..a.digits.len()).rev() {
            rem = rem.mul10_add(a.digits[i]);
            let mut qi = 0u8;
            while rem.cmp_abs(b) != Ordering::Less { rem = Self::sub_abs(&rem, b); qi += 1; }
            q[i] = qi;
        }
        while q.last() == Some(&0) { q.pop(); }
        let qq = if q.is_empty() { Self::zero() } else { BigNum { neg: false, digits: q } };
        (qq, rem)
    }

    fn mul10_add(&self, d: u8) -> Self {
        if self.is_zero() { return if d == 0 { Self::zero() } else { BigNum { neg: false, digits: vec![d] } }; }
        let mut v = Vec::with_capacity(self.digits.len() + 1);
        v.push(d);
        v.extend_from_slice(&self.digits);
        while v.last() == Some(&0) { v.pop(); }
        if v.is_empty() { Self::zero() } else { BigNum { neg: false, digits: v } }
    }

    fn add_signed(a: &Self, b: &Self) -> Self {
        if a.neg == b.neg {
            let mut r = Self::add_abs(a, b);
            r.neg = a.neg && !r.is_zero(); r
        } else {
            match a.cmp_abs(b) {
                Ordering::Greater => { let mut r = Self::sub_abs(a, b); r.neg = a.neg && !r.is_zero(); r }
                Ordering::Less => { let mut r = Self::sub_abs(b, a); r.neg = b.neg && !r.is_zero(); r }
                Ordering::Equal => Self::zero(),
            }
        }
    }

    fn mul_pow10(a: &Self, n: u32) -> Self {
        if a.is_zero() || n == 0 { return a.clone(); }
        let mut d = vec![0u8; n as usize];
        d.extend_from_slice(&a.digits);
        BigNum { neg: a.neg, digits: d }
    }

    fn pow10(n: u32) -> Self {
        if n == 0 { return BigNum::from_u64(1); }
        let mut d = vec![0u8; n as usize]; d.push(1);
        BigNum { neg: false, digits: d }
    }

    fn half_pow10(k: u32) -> Self {
        let mut d = vec![0u8; (k - 1) as usize]; d.push(5);
        BigNum { neg: false, digits: d }
    }

    fn neg(&self) -> Self {
        if self.is_zero() { return Self::zero(); }
        BigNum { neg: !self.neg, digits: self.digits.clone() }
    }
}

#[derive(Clone, Debug)]
struct Decimal {
    value: BigNum,
    scale: u32,
}

impl Decimal {
    fn zero() -> Self { Decimal { value: BigNum::zero(), scale: 0 } }

    fn parse(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (ip, fp) = if let Some(p) = rest.find('.') { (&rest[..p], &rest[p+1..]) } else { (rest, "") };
        let ds = format!("{}{}", ip, fp);
        let mut v = BigNum::from_str(&ds);
        v.neg = neg && !v.is_zero();
        Decimal { value: v, scale: fp.len() as u32 }
    }

    fn align(a: &Decimal, b: &Decimal) -> (BigNum, BigNum, u32) {
        let ms = a.scale.max(b.scale);
        (BigNum::mul_pow10(&a.value, ms - a.scale), BigNum::mul_pow10(&b.value, ms - b.scale), ms)
    }

    fn add(a: &Decimal, b: &Decimal) -> Decimal {
        let (av, bv, s) = Self::align(a, b);
        Decimal { value: BigNum::add_signed(&av, &bv), scale: s }
    }

    fn sub(a: &Decimal, b: &Decimal) -> Decimal {
        let (av, bv, s) = Self::align(a, b);
        let nbv = bv.neg();
        Decimal { value: BigNum::add_signed(&av, &nbv), scale: s }
    }

    fn mul(a: &Decimal, b: &Decimal) -> Decimal {
        Decimal { value: BigNum::mul(&a.value, &b.value), scale: a.scale + b.scale }
    }

    fn round(&self, d: u32) -> Decimal {
        if self.scale <= d {
            let v = BigNum::mul_pow10(&self.value, d - self.scale);
            Decimal { value: v, scale: d }
        } else {
            let k = self.scale - d;
            let divisor = BigNum::pow10(k);
            let abs_v = BigNum { neg: false, digits: self.value.digits.clone() };
            let (mut q, r) = BigNum::div_mod(&abs_v, &divisor);
            let half = BigNum::half_pow10(k);
            match r.cmp_abs(&half) {
                Ordering::Greater => { q = BigNum::add_abs(&q, &BigNum::from_u64(1)); }
                Ordering::Equal => {
                    if !q.digits.is_empty() && q.digits[0] % 2 == 1 {
                        q = BigNum::add_abs(&q, &BigNum::from_u64(1));
                    }
                }
                Ordering::Less => {}
            }
            q.neg = self.value.neg && !q.is_zero();
            Decimal { value: q, scale: d }
        }
    }

    fn to_minor(&self, d: u32) -> BigNum {
        if self.scale == d { self.value.clone() }
        else { BigNum::mul_pow10(&self.value, d - self.scale) }
    }

    fn is_neg(&self) -> bool { self.value.neg && !self.value.is_zero() }
    fn is_zero(&self) -> bool { self.value.is_zero() }
}

struct Account {
    currency: String,
    balance: BigNum,
    limit: BigNum,
}

fn add_commas(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut r = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { r.push(','); }
        r.push(c);
    }
    r
}

fn format_money(val: &BigNum, mu: u32) -> String {
    let is_neg = val.neg && !val.is_zero();
    let all_d: String = if val.is_zero() { "0".to_string() }
        else { (0..val.digits.len()).rev().map(|i| (val.digits[i] + b'0') as char).collect() };
    let m = mu as usize;
    let (int_s, frac_s) = if m == 0 {
        (all_d.clone(), String::new())
    } else if all_d.len() <= m {
        ("0".to_string(), format!("{:0>width$}", all_d, width = m))
    } else {
        let sp = all_d.len() - m;
        (all_d[..sp].to_string(), all_d[sp..].to_string())
    };
    let mut r = String::new();
    if is_neg { r.push('-'); }
    r.push_str(&add_commas(&int_s));
    if m > 0 { r.push('.'); r.push_str(&frac_s); }
    r
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: HashMap<String, u32> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (ln, line) in content.lines().enumerate() {
        let line_num = ln + 1;
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.is_empty() { continue; }

        let cmd = fields[0];
        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let mu: u32 = fields[2].parse().unwrap();
                currencies.insert(code, mu);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&code).unwrap();
                let limit_dec = if fields.len() > 3 { Decimal::parse(fields[3]).round(mu) } else { Decimal::zero() };
                let limit = limit_dec.to_minor(mu);
                accounts.insert(name, Account { currency: code, balance: BigNum::zero(), limit });
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let add = amt.to_minor(mu);
                let bal = BigNum::add_signed(&accounts[&name].balance, &add);
                accounts.get_mut(&name).unwrap().balance = bal;
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&name].balance, &sub.neg());
                let min_allowed = accounts[&name].limit.neg();
                if new_bal.is_neg() && new_bal.cmp_abs(&min_allowed) == Ordering::Greater {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                // Check: new_bal < -limit means new_bal is more negative than -limit
                // new_bal < -limit  <=>  |new_bal| > |limit| (when both negative)
                // Actually: new_bal < -limit  <=>  new_bal + limit < 0
                let check = BigNum::add_signed(&new_bal, &accounts[&name].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else if !accounts.contains_key(&to) { unknown = Some(to.clone()); }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                let ct = accounts[&to].currency.clone();
                if cf != ct {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let mu = *currencies.get(&cf).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &sub.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                accounts.get_mut(&from).unwrap().balance = new_bal;
                let new_to = BigNum::add_signed(&accounts[&to].balance, &sub);
                accounts.get_mut(&to).unwrap().balance = new_to;
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else if !accounts.contains_key(&to) { unknown = Some(to.clone()); }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                let ct = accounts[&to].currency.clone();
                let mu_f = *currencies.get(&cf).unwrap();
                let mu_t = *currencies.get(&ct).unwrap();
                let amt = Decimal::parse(amount_str).round(mu_f);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu_f);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &sub.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let rate = Decimal::parse(rate_str);
                let product = Decimal::mul(&amt, &rate);
                let credit = product.round(mu_t);
                let credit_minor = credit.to_minor(mu_t);
                accounts.get_mut(&from).unwrap().balance = new_bal;
                let new_to = BigNum::add_signed(&accounts[&to].balance, &credit_minor);
                accounts.get_mut(&to).unwrap().balance = new_to;
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let rate = Decimal::parse(rate_str);
                let bal_dec = Decimal { value: accounts[&name].balance.clone(), scale: mu };
                let product = Decimal::mul(&bal_dec, &rate);
                let credit = product.round(mu);
                let credit_minor = credit.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&name].balance, &credit_minor);
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "split" => {
                let from = fields[1].to_string();
                let amount_str = fields[2];
                let mut targets: Vec<(String, BigNum)> = Vec::new();
                for i in 3..fields.len() {
                    let f = fields[i];
                    let colon = f.rfind(':').unwrap();
                    let tn = f[..colon].to_string();
                    let w = BigNum::from_str(&f[colon+1..]);
                    targets.push((tn, w));
                }
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else {
                    for (tn, _) in &targets {
                        if !accounts.contains_key(tn) { unknown = Some(tn.clone()); break; }
                    }
                }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                for (tn, _) in &targets {
                    if accounts[tn].currency != cf {
                        rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                        break;
                    }
                }
                // Check if we already pushed a rejection for currency mismatch
                if rejections.last().map_or(false, |r| r.starts_with(&format!("line {}: REJECT currency", line_num))) {
                    continue;
                }
                let mu = *currencies.get(&cf).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let a_int = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &a_int.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                // Compute weights sum
                let mut w_sum = BigNum::zero();
                for (_, w) in &targets { w_sum = BigNum::add_abs(&w_sum, w); }
                // Compute base and remainder for each target
                let n = targets.len();
                let mut bases: Vec<BigNum> = Vec::new();
                let mut rems: Vec<BigNum> = Vec::new();
                let mut total_base = BigNum::zero();
                for (_, w) in &targets {
                    let prod = BigNum::mul(&a_int, w);
                    let (q, r) = BigNum::div_mod(&prod, &w_sum);
                    bases.push(q.clone());
                    rems.push(r);
                    total_base = BigNum::add_abs(&total_base, &q);
                }
                let leftover = BigNum::sub_abs(&a_int, &total_base);
                let leftover_n = if leftover.is_zero() { 0usize } else {
                    // leftover is small (< n), convert to usize
                    let mut v = 0usize;
                    for i in (0..leftover.digits.len()).rev() { v = v * 10 + leftover.digits[i] as usize; }
                    v
                };
                // Sort indices by remainder descending, stable
                let mut indices: Vec<usize> = (0..n).collect();
                indices.sort_by(|&a, &b| {
                    match rems[b].cmp_abs(&rems[a]) {
                        Ordering::Equal => Ordering::Equal,
                        x => x,
                    }
                });
                // Distribute leftover
                let mut extras = vec![false; n];
                for i in 0..leftover_n { extras[indices[i]] = true; }
                // Apply
                accounts.get_mut(&from).unwrap().balance = new_bal;
                for (i, (tn, _)) in targets.iter().enumerate() {
                    let mut give = bases[i].clone();
                    if extras[i] { give = BigNum::add_abs(&give, &BigNum::from_u64(1)); }
                    let new_to = BigNum::add_signed(&accounts[tn].balance, &give);
                    accounts.get_mut(tn).unwrap().balance = new_to;
                }
            }
            _ => {}
        }
    }

    // Output
    let mut out = String::new();
    for r in &rejections { out.push_str(r); out.push('\n'); }
    out.push('\n');

    let mut names: Vec<&String> = accounts.keys().collect();
    names.sort();
    for name in &names {
        let acc = &accounts[*name];
        let mu = *currencies.get(&acc.currency).unwrap();
        out.push_str(&format!("{} {} {}\n", name, acc.currency, format_money(&acc.balance, mu)));
    }
    out.push('\n');

    let mut cur_totals: HashMap<String, (BigNum, usize)> = HashMap::new();
    for (_, acc) in &accounts {
        let e = cur_totals.entry(acc.currency.clone()).or_insert((BigNum::zero(), 0));
        e.0 = BigNum::add_signed(&e.0, &acc.balance);
        e.1 += 1;
    }
    let mut cur_codes: Vec<&String> = cur_totals.keys().collect();
    cur_codes.sort();
    for code in &cur_codes {
        let (sum, count) = &cur_totals[code];
        let mu = *currencies.get(code.as_str()).unwrap();
        out.push_str(&format!("total {} {} ({} accounts)\n", code, format_money(sum, mu), count));
    }

    print!("{}", out);
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

#[derive(Clone, Debug)]
struct BigNum {
    neg: bool,
    digits: Vec<u8>,
}

impl BigNum {
    fn zero() -> Self { BigNum { neg: false, digits: vec![] } }
    fn is_zero(&self) -> bool { self.digits.is_empty() }
    fn is_neg(&self) -> bool { self.neg && !self.digits.is_empty() }

    fn from_u64(mut n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut d = Vec::new();
        while n > 0 { d.push((n % 10) as u8); n /= 10; }
        BigNum { neg: false, digits: d }
    }

    fn from_str(s: &str) -> Self {
        let mut d = Vec::new();
        for &c in s.as_bytes().iter().rev() { d.push(c - b'0'); }
        while d.last() == Some(&0) { d.pop(); }
        if d.is_empty() { Self::zero() } else { BigNum { neg: false, digits: d } }
    }

    fn cmp_abs(&self, o: &Self) -> Ordering {
        if self.digits.len() != o.digits.len() { return self.digits.len().cmp(&o.digits.len()); }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != o.digits[i] { return self.digits[i].cmp(&o.digits[i]); }
        }
        Ordering::Equal
    }

    fn add_abs(a: &Self, b: &Self) -> Self {
        let mut r = Vec::new();
        let mut c = 0u8;
        let n = a.digits.len().max(b.digits.len());
        for i in 0..n {
            let da = if i < a.digits.len() { a.digits[i] as u16 } else { 0 };
            let db = if i < b.digits.len() { b.digits[i] as u16 } else { 0 };
            let s = da + db + c as u16;
            r.push((s % 10) as u8);
            c = (s / 10) as u8;
        }
        if c > 0 { r.push(c); }
        while r.last() == Some(&0) { r.pop(); }
        if r.is_empty() { Self::zero() } else { BigNum { neg: false, digits: r } }
    }

    fn sub_abs(a: &Self, b: &Self) -> Self {
        let mut r = Vec::new();
        let mut borrow = 0i16;
        for i in 0..a.digits.len() {
            let da = a.digits[i] as i16;
            let db = if i < b.digits.len() { b.digits[i] as i16 } else { 0 };
            let mut d = da - db - borrow;
            if d < 0 { d += 10; borrow = 1; } else { borrow = 0; }
            r.push(d as u8);
        }
        while r.last() == Some(&0) { r.pop(); }
        if r.is_empty() { Self::zero() } else { BigNum { neg: false, digits: r } }
    }

    fn mul(a: &Self, b: &Self) -> Self {
        if a.is_zero() || b.is_zero() { return Self::zero(); }
        let n = a.digits.len(); let m = b.digits.len();
        let mut r = vec![0u32; n + m];
        for i in 0..n {
            let mut carry = 0u32;
            for j in 0..m {
                let p = (a.digits[i] as u32) * (b.digits[j] as u32) + r[i+j] + carry;
                r[i+j] = p % 10; carry = p / 10;
            }
            let mut pos = i + m;
            while carry > 0 { let s = r[pos] + carry; r[pos] = s % 10; carry = s / 10; pos += 1; }
        }
        let mut d: Vec<u8> = r.iter().map(|&x| x as u8).collect();
        while d.last() == Some(&0) { d.pop(); }
        if d.is_empty() { Self::zero() } else { BigNum { neg: a.neg != b.neg, digits: d } }
    }

    fn div_mod(a: &Self, b: &Self) -> (Self, Self) {
        if a.cmp_abs(b) == Ordering::Less { return (Self::zero(), a.clone()); }
        let mut q = vec![0u8; a.digits.len()];
        let mut rem = Self::zero();
        for i in (0..a.digits.len()).rev() {
            rem = rem.mul10_add(a.digits[i]);
            let mut qi = 0u8;
            while rem.cmp_abs(b) != Ordering::Less { rem = Self::sub_abs(&rem, b); qi += 1; }
            q[i] = qi;
        }
        while q.last() == Some(&0) { q.pop(); }
        let qq = if q.is_empty() { Self::zero() } else { BigNum { neg: false, digits: q } };
        (qq, rem)
    }

    fn mul10_add(&self, d: u8) -> Self {
        if self.is_zero() { return if d == 0 { Self::zero() } else { BigNum { neg: false, digits: vec![d] } }; }
        let mut v = Vec::with_capacity(self.digits.len() + 1);
        v.push(d);
        v.extend_from_slice(&self.digits);
        while v.last() == Some(&0) { v.pop(); }
        if v.is_empty() { Self::zero() } else { BigNum { neg: false, digits: v } }
    }

    fn add_signed(a: &Self, b: &Self) -> Self {
        if a.neg == b.neg {
            let mut r = Self::add_abs(a, b);
            r.neg = a.neg && !r.is_zero(); r
        } else {
            match a.cmp_abs(b) {
                Ordering::Greater => { let mut r = Self::sub_abs(a, b); r.neg = a.neg && !r.is_zero(); r }
                Ordering::Less => { let mut r = Self::sub_abs(b, a); r.neg = b.neg && !r.is_zero(); r }
                Ordering::Equal => Self::zero(),
            }
        }
    }

    fn mul_pow10(a: &Self, n: u32) -> Self {
        if a.is_zero() || n == 0 { return a.clone(); }
        let mut d = vec![0u8; n as usize];
        d.extend_from_slice(&a.digits);
        BigNum { neg: a.neg, digits: d }
    }

    fn pow10(n: u32) -> Self {
        if n == 0 { return BigNum::from_u64(1); }
        let mut d = vec![0u8; n as usize]; d.push(1);
        BigNum { neg: false, digits: d }
    }

    fn half_pow10(k: u32) -> Self {
        let mut d = vec![0u8; (k - 1) as usize]; d.push(5);
        BigNum { neg: false, digits: d }
    }

    fn neg(&self) -> Self {
        if self.is_zero() { return Self::zero(); }
        BigNum { neg: !self.neg, digits: self.digits.clone() }
    }
}

#[derive(Clone, Debug)]
struct Decimal {
    value: BigNum,
    scale: u32,
}

impl Decimal {
    fn zero() -> Self { Decimal { value: BigNum::zero(), scale: 0 } }

    fn parse(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (ip, fp) = if let Some(p) = rest.find('.') { (&rest[..p], &rest[p+1..]) } else { (rest, "") };
        let ds = format!("{}{}", ip, fp);
        let mut v = BigNum::from_str(&ds);
        v.neg = neg && !v.is_zero();
        Decimal { value: v, scale: fp.len() as u32 }
    }

    fn align(a: &Decimal, b: &Decimal) -> (BigNum, BigNum, u32) {
        let ms = a.scale.max(b.scale);
        (BigNum::mul_pow10(&a.value, ms - a.scale), BigNum::mul_pow10(&b.value, ms - b.scale), ms)
    }

    fn add(a: &Decimal, b: &Decimal) -> Decimal {
        let (av, bv, s) = Self::align(a, b);
        Decimal { value: BigNum::add_signed(&av, &bv), scale: s }
    }

    fn sub(a: &Decimal, b: &Decimal) -> Decimal {
        let (av, bv, s) = Self::align(a, b);
        let nbv = bv.neg();
        Decimal { value: BigNum::add_signed(&av, &nbv), scale: s }
    }

    fn mul(a: &Decimal, b: &Decimal) -> Decimal {
        Decimal { value: BigNum::mul(&a.value, &b.value), scale: a.scale + b.scale }
    }

    fn round(&self, d: u32) -> Decimal {
        if self.scale <= d {
            let v = BigNum::mul_pow10(&self.value, d - self.scale);
            Decimal { value: v, scale: d }
        } else {
            let k = self.scale - d;
            let divisor = BigNum::pow10(k);
            let abs_v = BigNum { neg: false, digits: self.value.digits.clone() };
            let (mut q, r) = BigNum::div_mod(&abs_v, &divisor);
            let half = BigNum::half_pow10(k);
            match r.cmp_abs(&half) {
                Ordering::Greater => { q = BigNum::add_abs(&q, &BigNum::from_u64(1)); }
                Ordering::Equal => {
                    if !q.digits.is_empty() && q.digits[0] % 2 == 1 {
                        q = BigNum::add_abs(&q, &BigNum::from_u64(1));
                    }
                }
                Ordering::Less => {}
            }
            q.neg = self.value.neg && !q.is_zero();
            Decimal { value: q, scale: d }
        }
    }

    fn to_minor(&self, d: u32) -> BigNum {
        if self.scale == d { self.value.clone() }
        else { BigNum::mul_pow10(&self.value, d - self.scale) }
    }

    fn is_neg(&self) -> bool { self.value.neg && !self.value.is_zero() }
    fn is_zero(&self) -> bool { self.value.is_zero() }
}

struct Account {
    currency: String,
    balance: BigNum,
    limit: BigNum,
}

fn add_commas(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut r = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if i > 0 && (n - i) % 3 == 0 { r.push(','); }
        r.push(c);
    }
    r
}

fn format_money(val: &BigNum, mu: u32) -> String {
    let is_neg = val.neg && !val.is_zero();
    let all_d: String = if val.is_zero() { "0".to_string() }
        else { (0..val.digits.len()).rev().map(|i| (val.digits[i] + b'0') as char).collect() };
    let m = mu as usize;
    let (int_s, frac_s) = if m == 0 {
        (all_d.clone(), String::new())
    } else if all_d.len() <= m {
        ("0".to_string(), format!("{:0>width$}", all_d, width = m))
    } else {
        let sp = all_d.len() - m;
        (all_d[..sp].to_string(), all_d[sp..].to_string())
    };
    let mut r = String::new();
    if is_neg { r.push('-'); }
    r.push_str(&add_commas(&int_s));
    if m > 0 { r.push('.'); r.push_str(&frac_s); }
    r
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: HashMap<String, u32> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (ln, line) in content.lines().enumerate() {
        let line_num = ln + 1;
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('#') { continue; }
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.is_empty() { continue; }

        let cmd = fields[0];
        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let mu: u32 = fields[2].parse().unwrap();
                currencies.insert(code, mu);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&code).unwrap();
                let limit_dec = if fields.len() > 3 { Decimal::parse(fields[3]).round(mu) } else { Decimal::zero() };
                let limit = limit_dec.to_minor(mu);
                accounts.insert(name, Account { currency: code, balance: BigNum::zero(), limit });
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let add = amt.to_minor(mu);
                let bal = BigNum::add_signed(&accounts[&name].balance, &add);
                accounts.get_mut(&name).unwrap().balance = bal;
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&name].balance, &sub.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&name].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else if !accounts.contains_key(&to) { unknown = Some(to.clone()); }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                let ct = accounts[&to].currency.clone();
                if cf != ct {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let mu = *currencies.get(&cf).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &sub.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                accounts.get_mut(&from).unwrap().balance = new_bal;
                let new_to = BigNum::add_signed(&accounts[&to].balance, &sub);
                accounts.get_mut(&to).unwrap().balance = new_to;
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else if !accounts.contains_key(&to) { unknown = Some(to.clone()); }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                let ct = accounts[&to].currency.clone();
                let mu_f = *currencies.get(&cf).unwrap();
                let mu_t = *currencies.get(&ct).unwrap();
                let amt = Decimal::parse(amount_str).round(mu_f);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let sub = amt.to_minor(mu_f);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &sub.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let rate = Decimal::parse(rate_str);
                let product = Decimal::mul(&amt, &rate);
                let credit = product.round(mu_t);
                let credit_minor = credit.to_minor(mu_t);
                accounts.get_mut(&from).unwrap().balance = new_bal;
                let new_to = BigNum::add_signed(&accounts[&to].balance, &credit_minor);
                accounts.get_mut(&to).unwrap().balance = new_to;
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let mu = *currencies.get(&accounts[&name].currency).unwrap();
                let rate = Decimal::parse(rate_str);
                let bal_dec = Decimal { value: accounts[&name].balance.clone(), scale: mu };
                let product = Decimal::mul(&bal_dec, &rate);
                let credit = product.round(mu);
                let credit_minor = credit.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&name].balance, &credit_minor);
                accounts.get_mut(&name).unwrap().balance = new_bal;
            }
            "split" => {
                let from = fields[1].to_string();
                let amount_str = fields[2];
                let mut targets: Vec<(String, BigNum)> = Vec::new();
                for i in 3..fields.len() {
                    let f = fields[i];
                    let colon = f.rfind(':').unwrap();
                    let tn = f[..colon].to_string();
                    let w = BigNum::from_str(&f[colon+1..]);
                    targets.push((tn, w));
                }
                let mut unknown = None;
                if !accounts.contains_key(&from) { unknown = Some(from.clone()); }
                else {
                    for (tn, _) in &targets {
                        if !accounts.contains_key(tn) { unknown = Some(tn.clone()); break; }
                    }
                }
                if let Some(n) = unknown {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, n));
                    continue;
                }
                let cf = accounts[&from].currency.clone();
                let mut mismatch = false;
                for (tn, _) in &targets {
                    if accounts[tn].currency != cf {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let mu = *currencies.get(&cf).unwrap();
                let amt = Decimal::parse(amount_str).round(mu);
                if amt.is_neg() || amt.is_zero() {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let a_int = amt.to_minor(mu);
                let new_bal = BigNum::add_signed(&accounts[&from].balance, &a_int.neg());
                let check = BigNum::add_signed(&new_bal, &accounts[&from].limit);
                if check.is_neg() {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                // Compute weights sum
                let mut w_sum = BigNum::zero();
                for (_, w) in &targets { w_sum = BigNum::add_abs(&w_sum, w); }
                // Compute base and remainder for each target
                let n = targets.len();
                let mut bases: Vec<BigNum> = Vec::new();
                let mut rems: Vec<BigNum> = Vec::new();
                let mut total_base = BigNum::zero();
                for (_, w) in &targets {
                    let prod = BigNum::mul(&a_int, w);
                    let (q, r) = BigNum::div_mod(&prod, &w_sum);
                    bases.push(q.clone());
                    rems.push(r);
                    total_base = BigNum::add_abs(&total_base, &q);
                }
                let leftover = BigNum::sub_abs(&a_int, &total_base);
                let leftover_n = if leftover.is_zero() { 0usize } else {
                    let mut v = 0usize;
                    for i in (0..leftover.digits.len()).rev() { v = v * 10 + leftover.digits[i] as usize; }
                    v
                };
                // Sort indices by remainder descending, stable (equal remainders: first listed wins)
                let mut indices: Vec<usize> = (0..n).collect();
                indices.sort_by(|&a, &b| {
                    match rems[b].cmp_abs(&rems[a]) {
                        Ordering::Equal => Ordering::Equal,
                        x => x,
                    }
                });
                // Distribute leftover
                let mut extras = vec![false; n];
                for i in 0..leftover_n { extras[indices[i]] = true; }
                // Apply
                accounts.get_mut(&from).unwrap().balance = new_bal;
                for (i, (tn, _)) in targets.iter().enumerate() {
                    let mut give = bases[i].clone();
                    if extras[i] { give = BigNum::add_abs(&give, &BigNum::from_u64(1)); }
                    let new_to = BigNum::add_signed(&accounts[tn].balance, &give);
                    accounts.get_mut(tn).unwrap().balance = new_to;
                }
            }
            _ => {}
        }
    }

    // Output
    let mut out = String::new();
    for r in &rejections { out.push_str(r); out.push('\n'); }
    out.push('\n');

    let mut names: Vec<&String> = accounts.keys().collect();
    names.sort();
    for name in &names {
        let acc = &accounts[*name];
        let mu = *currencies.get(&acc.currency).unwrap();
        out.push_str(&format!("{} {} {}\n", name, acc.currency, format_money(&acc.balance, mu)));
    }
    out.push('\n');

    let mut cur_totals: HashMap<String, (BigNum, usize)> = HashMap::new();
    for (_, acc) in &accounts {
        let e = cur_totals.entry(acc.currency.clone()).or_insert((BigNum::zero(), 0));
        e.0 = BigNum::add_signed(&e.0, &acc.balance);
        e.1 += 1;
    }
    let mut cur_codes: Vec<String> = cur_totals.keys().cloned().collect();
    cur_codes.sort();
    for code in &cur_codes {
        let (sum, count) = &cur_totals[code];
        let mu = *currencies.get(code.as_str()).unwrap();
        out.push_str(&format!("total {} {} ({} accounts)\n", code, format_money(sum, mu), count));
    }

    print!("{}", out);
}

import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8'));
const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8'));

function hasOwn(obj: any, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function deepEqual(a: any, b: any): boolean {
  if (a === null && b === null) return true;
  if (a === null || b === null) return false;
  if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (typeof a === 'string' && typeof b === 'string') return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const k of keysA) {
      if (!hasOwn(b, k)) return false;
      if (!deepEqual(a[k], b[k])) return false;
    }
    return true;
  }
  return false;
}

function strLen(s: string): number {
  let count = 0;
  for (const _ of s) count++;
  return count;
}

function encodeToken(t: string): string {
  return t.replace(/~/g, '~0').replace(/\//g, '~1');
}

function buildPointer(tokens: (string | number)[]): string {
  return '#' + tokens.map(t => '/' + encodeToken(String(t))).join('');
}

function comparePointers(a: string, b: string): number {
  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');
  const minLen = Math.min(bufA.length, bufB.length);
  for (let i = 0; i < minLen; i++) {
    if (bufA[i] !== bufB[i]) return bufA[i] - bufB[i];
  }
  return bufA.length - bufB.length;
}

function matchesType(v: any, typeName: string): boolean {
  switch (typeName) {
    case 'null': return v === null;
    case 'boolean': return typeof v === 'boolean';
    case 'object': return typeof v === 'object' && v !== null && !Array.isArray(v);
    case 'array': return Array.isArray(v);
    case 'number': return typeof v === 'number';
    case 'string': return typeof v === 'string';
    case 'integer': return typeof v === 'number' && Number.isInteger(v);
    default: return false;
  }
}

function isObject(v: any): boolean {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function resolveRef(ref: string, rootSchema: any): { schema: any; location: (string | number)[] } {
  if (ref === '#') {
    return { schema: rootSchema, location: [] };
  }
  if (!ref.startsWith('#/')) {
    return { schema: false, location: [] };
  }
  const pointer = ref.slice(2);
  const tokens = pointer.split('/').map(t => t.replace(/~1/g, '/').replace(/~0/g, '~'));
  let current: any = rootSchema;
  for (const token of tokens) {
    if (current === null || typeof current !== 'object' || Array.isArray(current)) {
      return { schema: false, location: tokens };
    }
    current = current[token];
  }
  return { schema: current, location: tokens };
}

type Err = [string, string];

function validate(
  instance: any,
  schema: any,
  instLoc: (string | number)[],
  schemaLoc: (string | number)[],
  rootSchema: any
): Err[] {
  const errors: Err[] = [];

  if (schema === true) return [];
  if (schema === false) {
    return [[buildPointer(instLoc), buildPointer(schemaLoc)]];
  }
  if (typeof schema !== 'object' || schema === null) return [];

  // type
  if ('type' in schema) {
    const typeVal = schema['type'];
    const types: string[] = Array.isArray(typeVal) ? typeVal : [typeVal];
    const matches = types.some(t => matchesType(instance, t));
    if (!matches) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'type'])]);
    }
  }

  // enum
  if ('enum' in schema) {
    const enumArr: any[] = schema['enum'];
    if (!enumArr.some(e => deepEqual(instance, e))) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'enum'])]);
    }
  }

  // const
  if ('const' in schema) {
    if (!deepEqual(instance, schema['const'])) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'const'])]);
    }
  }

  // Numbers
  if (typeof instance === 'number') {
    if ('minimum' in schema) {
      if (!(instance >= schema['minimum'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'minimum'])]);
      }
    }
    if ('maximum' in schema) {
      if (!(instance <= schema['maximum'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'maximum'])]);
      }
    }
    if ('exclusiveMinimum' in schema) {
      if (!(instance > schema['exclusiveMinimum'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'exclusiveMinimum'])]);
      }
    }
    if ('exclusiveMaximum' in schema) {
      if (!(instance < schema['exclusiveMaximum'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'exclusiveMaximum'])]);
      }
    }
  }

  // Strings
  if (typeof instance === 'string') {
    if ('minLength' in schema) {
      if (!(strLen(instance) >= schema['minLength'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'minLength'])]);
      }
    }
    if ('maxLength' in schema) {
      if (!(strLen(instance) <= schema['maxLength'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'maxLength'])]);
      }
    }
  }

  // Arrays
  if (Array.isArray(instance)) {
    if ('minItems' in schema) {
      if (!(instance.length >= schema['minItems'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'minItems'])]);
      }
    }
    if ('maxItems' in schema) {
      if (!(instance.length <= schema['maxItems'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'maxItems'])]);
      }
    }
    if ('uniqueItems' in schema && schema['uniqueItems'] === true) {
      let hasDup = false;
      for (let i = 0; i < instance.length && !hasDup; i++) {
        for (let j = i + 1; j < instance.length && !hasDup; j++) {
          if (deepEqual(instance[i], instance[j])) {
            hasDup = true;
          }
        }
      }
      if (hasDup) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'uniqueItems'])]);
      }
    }
    if ('prefixItems' in schema) {
      const prefixItems: any[] = schema['prefixItems'];
      for (let i = 0; i < Math.min(instance.length, prefixItems.length); i++) {
        const sub = validate(instance[i], prefixItems[i], [...instLoc, i], [...schemaLoc, 'prefixItems', i], rootSchema);
        errors.push(...sub);
      }
    }
    if ('items' in schema) {
      const prefixLen = 'prefixItems' in schema ? (schema['prefixItems'] as any[]).length : 0;
      for (let i = prefixLen; i < instance.length; i++) {
        const sub = validate(instance[i], schema['items'], [...instLoc, i], [...schemaLoc, 'items'], rootSchema);
        errors.push(...sub);
      }
    }
  }

  // Objects
  if (isObject(instance)) {
    if ('required' in schema) {
      const req: string[] = schema['required'];
      for (let j = 0; j < req.length; j++) {
        if (!hasOwn(instance, req[j])) {
          errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'required', j])]);
        }
      }
    }
    if ('properties' in schema) {
      const props: Record<string, any> = schema['properties'];
      for (const key of Object.keys(props)) {
        if (hasOwn(instance, key)) {
          const sub = validate(instance[key], props[key], [...instLoc, key], [...schemaLoc, 'properties', key], rootSchema);
          errors.push(...sub);
        }
      }
    }
    if ('additionalProperties' in schema) {
      const propKeys = 'properties' in schema
        ? new Set(Object.keys(schema['properties']))
        : new Set<string>();
      for (const key of Object.keys(instance)) {
        if (!propKeys.has(key)) {
          const sub = validate(instance[key], schema['additionalProperties'], [...instLoc, key], [...schemaLoc, 'additionalProperties'], rootSchema);
          errors.push(...sub);
        }
      }
    }
    if ('minProperties' in schema) {
      if (!(Object.keys(instance).length >= schema['minProperties'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'minProperties'])]);
      }
    }
    if ('maxProperties' in schema) {
      if (!(Object.keys(instance).length <= schema['maxProperties'])) {
        errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'maxProperties'])]);
      }
    }
  }

  // allOf
  if ('allOf' in schema) {
    const allOf: any[] = schema['allOf'];
    for (let i = 0; i < allOf.length; i++) {
      const sub = validate(instance, allOf[i], instLoc, [...schemaLoc, 'allOf', i], rootSchema);
      errors.push(...sub);
    }
  }

  // anyOf
  if ('anyOf' in schema) {
    const anyOf: any[] = schema['anyOf'];
    let anyAccepted = false;
    for (let i = 0; i < anyOf.length; i++) {
      const sub = validate(instance, anyOf[i], instLoc, [...schemaLoc, 'anyOf', i], rootSchema);
      if (sub.length === 0) {
        anyAccepted = true;
        break;
      }
    }
    if (!anyAccepted) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'anyOf'])]);
    }
  }

  // oneOf
  if ('oneOf' in schema) {
    const oneOf: any[] = schema['oneOf'];
    let acceptCount = 0;
    for (let i = 0; i < oneOf.length; i++) {
      const sub = validate(instance, oneOf[i], instLoc, [...schemaLoc, 'oneOf', i], rootSchema);
      if (sub.length === 0) {
        acceptCount++;
      }
    }
    if (acceptCount !== 1) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'oneOf'])]);
    }
  }

  // not
  if ('not' in schema) {
    const sub = validate(instance, schema['not'], instLoc, [...schemaLoc, 'not'], rootSchema);
    if (sub.length === 0) {
      errors.push([buildPointer(instLoc), buildPointer([...schemaLoc, 'not'])]);
    }
  }

  // if/then/else
  if ('if' in schema) {
    const ifErrors = validate(instance, schema['if'], instLoc, [...schemaLoc, 'if'], rootSchema);
    if (ifErrors.length === 0) {
      if ('then' in schema) {
        const thenErrors = validate(instance, schema['then'], instLoc, [...schemaLoc, 'then'], rootSchema);
        errors.push(...thenErrors);
      }
    } else {
      if ('else' in schema) {
        const elseErrors = validate(instance, schema['else'], instLoc, [...schemaLoc, 'else'], rootSchema);
        errors.push(...elseErrors);
      }
    }
  }

  // $ref
  if ('$ref' in schema) {
    const resolved = resolveRef(schema['$ref'], rootSchema);
    const sub = validate(instance, resolved.schema, instLoc, resolved.location, rootSchema);
    errors.push(...sub);
  }

  return errors;
}

const results: string[] = [];
let validCount = 0;
let invalidCount = 0;

for (let idx = 0; idx < instances.length; idx++) {
  const instance = instances[idx];
  const rawErrors = validate(instance, schema, [], [], schema);

  const seen = new Set<string>();
  const uniqueErrors: Err[] = [];
  for (const [inst, sch] of rawErrors) {
    const key = inst + '\0' + sch;
    if (!seen.has(key)) {
      seen.add(key);
      uniqueErrors.push([inst, sch]);
    }
  }

  uniqueErrors.sort((a, b) => {
    const c = comparePointers(a[0], b[0]);
    if (c !== 0) return c;
    return comparePointers(a[1], b[1]);
  });

  if (uniqueErrors.length === 0) {
    results.push(`${idx}: valid`);
    validCount++;
  } else {
    results.push(`${idx}: invalid (${uniqueErrors.length})`);
    for (const [inst, sch] of uniqueErrors) {
      results.push(`  ${inst} ${sch}`);
    }
    invalidCount++;
  }
}

results.push(`valid=${validCount} invalid=${invalidCount}`);
console.log(results.join('\n'));

import sys
import json
import base64
import hmac
import hashlib
import os
import re


def is_valid_base64url(s):
    if not s:
        return False
    if not re.fullmatch(r'[A-Za-z0-9\-_]+', s):
        return False
    if len(s) % 4 == 1:
        return False
    return True


def decode_base64url(s):
    padding = 4 - (len(s) % 4)
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)


def verify_token(token, now, leeway, issuer, audience, keys):
    # Rule 1: MALFORMED
    segments = token.split('.')
    if len(segments) != 3:
        return 'MALFORMED'

    for seg in segments:
        if not is_valid_base64url(seg):
            return 'MALFORMED'

    try:
        header_bytes = decode_base64url(segments[0])
        payload_bytes = decode_base64url(segments[1])
        sig_bytes = decode_base64url(segments[2])
    except Exception:
        return 'MALFORMED'

    try:
        header = json.loads(header_bytes.decode('utf-8'))
        payload = json.loads(payload_bytes.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError, Exception):
        return 'MALFORMED'

    if not isinstance(header, dict) or not isinstance(payload, dict):
        return 'MALFORMED'

    # Rule 2: UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
        return 'UNSUPPORTED_ALG'

    # Rule 3: UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys:
        return 'UNKNOWN_KEY'

    # Rule 4: ALG_MISMATCH
    key = keys[kid]
    if key['alg'] != alg:
        return 'ALG_MISMATCH'

    # Rule 5: BAD_SIGNATURE
    try:
        secret = decode_base64url(key['k'])
    except Exception:
        return 'BAD_SIGNATURE'

    signing_input = (segments[0] + '.' + segments[1]).encode('ascii')

    hash_func = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}[alg]
    expected_sig = hmac.new(secret, signing_input, hash_func).digest()

    if sig_bytes != expected_sig:
        return 'BAD_SIGNATURE'

    # Rule 6: EXPIRED
    if 'exp' in payload:
        exp = payload['exp']
        if now >= exp + leeway:
            return 'EXPIRED'

    # Rule 7: NOT_YET_VALID
    if 'nbf' in payload:
        nbf = payload['nbf']
        if now + leeway < nbf:
            return 'NOT_YET_VALID'

    # Rule 8: BAD_ISSUER
    if 'iss' not in payload:
        return 'BAD_ISSUER'
    iss = payload['iss']
    if not isinstance(iss, str) or iss != issuer:
        return 'BAD_ISSUER'

    # Rule 9: BAD_AUDIENCE
    if 'aud' not in payload:
        return 'BAD_AUDIENCE'
    aud = payload['aud']
    if isinstance(aud, str):
        if aud != audience:
            return 'BAD_AUDIENCE'
    elif isinstance(aud, list):
        if audience not in aud:
            return 'BAD_AUDIENCE'
    else:
        return 'BAD_AUDIENCE'

    # VALID
    sub = payload['sub']
    scope_raw = payload.get('scope', '')
    if not isinstance(scope_raw, str):
        scope_raw = ''
    parts = scope_raw.split(' ')
    scopes = sorted(set(p for p in parts if p))
    scope_str = ','.join(scopes)

    return f"VALID sub={sub} scope={scope_str}"


def main():
    dir_path = sys.argv[1]

    with open(os.path.join(dir_path, 'config.json'), 'r', encoding='utf-8') as f:
        config = json.load(f)

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = {k['kid']: k for k in config['keys']}

    with open(os.path.join(dir_path, 'tokens.txt'), 'r', encoding='utf-8') as f:
        raw_lines = f.read().split('\n')

    tokens = []
    for line in raw_lines:
        trimmed = line.strip(' \t')
        if trimmed:
            tokens.append(trimmed)

    valid_count = 0
    invalid_count = 0
    results = []

    for idx, token in enumerate(tokens, 1):
        result = verify_token(token, now, leeway, issuer, audience, keys)
        if result.startswith('VALID'):
            valid_count += 1
        else:
            invalid_count += 1
        results.append((idx, result))

    for idx, result in results:
        print(f"{idx}: {result}")

    print()
    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static String json;
    static int pos;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schemaStr = new String(Files.readAllBytes(Paths.get(dir, "schema.json")), StandardCharsets.UTF_8);
        String instancesStr = new String(Files.readAllBytes(Paths.get(dir, "instances.json")), StandardCharsets.UTF_8);

        Object schema = parseJson(schemaStr);
        @SuppressWarnings("unchecked")
        List<Object> instances = (List<Object>) parseJson(instancesStr);

        int validCount = 0, invalidCount = 0;
        for (int i = 0; i < instances.size(); i++) {
            TreeSet<String> errors = new TreeSet<>(Main::compareErrors);
            validate(instances.get(i), schema, "#", "#", errors, schema);
            if (errors.isEmpty()) {
                System.out.println(i + ": valid");
                validCount++;
            } else {
                System.out.println(i + ": invalid (" + errors.size() + ")");
                for (String err : errors) {
                    int sep = err.indexOf('\0');
                    System.out.println("  " + err.substring(0, sep) + " " + err.substring(sep + 1));
                }
                invalidCount++;
            }
        }
        System.out.println("valid=" + validCount + " invalid=" + invalidCount);
    }

    static int compareErrors(String a, String b) {
        int sepA = a.indexOf('\0');
        int sepB = b.indexOf('\0');
        int c = compareCodePoints(a.substring(0, sepA), b.substring(0, sepB));
        if (c != 0) return c;
        return compareCodePoints(a.substring(sepA + 1), b.substring(sepB + 1));
    }

    static int compareCodePoints(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }

    // --- JSON Parser ---

    static Object parseJson(String s) {
        json = s;
        pos = 0;
        return parseValue();
    }

    static void skipWs() {
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
            else break;
        }
    }

    static Object parseValue() {
        skipWs();
        char c = json.charAt(pos);
        if (c == '{') return parseObj();
        if (c == '[') return parseArr();
        if (c == '"') return parseStr();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        return parseNum();
    }

    static Map<String, Object> parseObj() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseStr();
            skipWs();
            pos++; // ':'
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            if (json.charAt(pos) == ',') pos++;
            else break;
        }
        pos++;
        return map;
    }

    static List<Object> parseArr() {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWs();
            if (json.charAt(pos) == ',') pos++;
            else break;
        }
        pos++;
        return list;
    }

    static String parseStr() {
        pos++; // opening "
        StringBuilder sb = new StringBuilder();
        while (json.charAt(pos) != '"') {
            char c = json.charAt(pos);
            if (c == '\\') {
                pos++;
                char e = json.charAt(pos);
                if (e == 'u') {
                    pos++; // skip 'u'
                    int cp = parseHex4();
                    if (Character.isHighSurrogate((char) cp)) {
                        pos++; // skip '\'
                        pos++; // skip 'u'
                        int lo = parseHex4();
                        sb.append((char) cp);
                        sb.append((char) lo);
                    } else {
                        sb.append((char) cp);
                    }
                } else {
                    pos++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                    }
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        pos++; // closing "
        return sb.toString();
    }

    static int parseHex4() {
        int v = 0;
        for (int i = 0; i < 4; i++) {
            char c = json.charAt(pos++);
            v = v * 16 + hexVal(c);
        }
        return v;
    }

    static int hexVal(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        return c - 'A' + 10;
    }

    static Double parseNum() {
        int start = pos;
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || (c >= '0' && c <= '9')) pos++;
            else break;
        }
        return Double.parseDouble(json.substring(start, pos));
    }

    // --- Deep Equality ---

    @SuppressWarnings("unchecked")
    static boolean deepEqual(Object a, Object b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        if (a instanceof Boolean && b instanceof Boolean) return a.equals(b);
        if (a instanceof Double && b instanceof Double) return ((Double) a).doubleValue() == ((Double) b).doubleValue();
        if (a instanceof String && b instanceof String) return a.equals(b);
        if (a instanceof List && b instanceof List) {
            List<Object> la = (List<Object>) a, lb = (List<Object>) b;
            if (la.size() != lb.size()) return false;
            for (int i = 0; i < la.size(); i++)
                if (!deepEqual(la.get(i), lb.get(i))) return false;
            return true;
        }
        if (a instanceof Map && b instanceof Map) {
            Map<String, Object> ma = (Map<String, Object>) a, mb = (Map<String, Object>) b;
            if (ma.size() != mb.size()) return false;
            for (Map.Entry<String, Object> e : ma.entrySet()) {
                if (!mb.containsKey(e.getKey())) return false;
                if (!deepEqual(e.getValue(), mb.get(e.getKey()))) return false;
            }
            return true;
        }
        return false;
    }

    // --- Type helpers ---

    static String instanceType(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return "boolean";
        if (obj instanceof Double) return "number";
        if (obj instanceof String) return "string";
        if (obj instanceof List) return "array";
        if (obj instanceof Map) return "object";
        return "unknown";
    }

    static boolean isInteger(double d) {
        return d == Math.floor(d) && !Double.isInfinite(d);
    }

    @SuppressWarnings("unchecked")
    static boolean matchesType(Object instance, Object typeVal) {
        String it = instanceType(instance);
        if (typeVal instanceof String) {
            return typeMatches(it, (String) typeVal, instance);
        } else if (typeVal instanceof List) {
            for (Object t : (List<Object>) typeVal) {
                if (typeMatches(it, (String) t, instance)) return true;
            }
            return false;
        }
        return true;
    }

    static boolean typeMatches(String instanceType, String typeName, Object instance) {
        if (typeName.equals("number")) return instanceType.equals("number");
        if (typeName.equals("integer")) return instanceType.equals("number") && isInteger((Double) instance);
        return instanceType.equals(typeName);
    }

    // --- JSON Pointer encoding ---

    static String encodeToken(String token) {
        return token.replace("~", "~0").replace("/", "~1");
    }

    static String decodeToken(String token) {
        return token.replace("~1", "/").replace("~0", "~");
    }

    // --- Validation ---

    @SuppressWarnings("unchecked")
    static void validate(Object instance, Object schema, String instLoc, String schemaLoc,
                         TreeSet<String> errors, Object rootSchema) {
        if (schema instanceof Boolean) {
            if (!(Boolean) schema) {
                errors.add(instLoc + "\0" + schemaLoc);
            }
            return;
        }
        if (!(schema instanceof Map)) return;
        Map<String, Object> sch = (Map<String, Object>) schema;

        // type
        if (sch.containsKey("type")) {
            if (!matchesType(instance, sch.get("type"))) {
                errors.add(instLoc + "\0" + schemaLoc + "/type");
            }
        }

        // enum
        if (sch.containsKey("enum")) {
            List<Object> enumArr = (List<Object>) sch.get("enum");
            boolean found = false;
            for (Object e : enumArr) {
                if (deepEqual(instance, e)) { found = true; break; }
            }
            if (!found) errors.add(instLoc + "\0" + schemaLoc + "/enum");
        }

        // const
        if (sch.containsKey("const")) {
            if (!deepEqual(instance, sch.get("const"))) {
                errors.add(instLoc + "\0" + schemaLoc + "/const");
            }
        }

        // Number keywords (only for number instances)
        if (instance instanceof Double) {
            double num = (Double) instance;
            if (sch.containsKey("minimum")) {
                double v = (Double) sch.get("minimum");
                if (num < v) errors.add(instLoc + "\0" + schemaLoc + "/minimum");
            }
            if (sch.containsKey("maximum")) {
                double v = (Double) sch.get("maximum");
                if (num > v) errors.add(instLoc + "\0" + schemaLoc + "/maximum");
            }
            if (sch.containsKey("exclusiveMinimum")) {
                double v = (Double) sch.get("exclusiveMinimum");
                if (num <= v) errors.add(instLoc + "\0" + schemaLoc + "/exclusiveMinimum");
            }
            if (sch.containsKey("exclusiveMaximum")) {
                double v = (Double) sch.get("exclusiveMaximum");
                if (num >= v) errors.add(instLoc + "\0" + schemaLoc + "/exclusiveMaximum");
            }
        }

        // String keywords (only for string instances)
        if (instance instanceof String) {
            String s = (String) instance;
            int len = s.codePointCount(0, s.length());
            if (sch.containsKey("minLength")) {
                int v = ((Double) sch.get("minLength")).intValue();
                if (len < v) errors.add(instLoc + "\0" + schemaLoc + "/minLength");
            }
            if (sch.containsKey("maxLength")) {
                int v = ((Double) sch.get("maxLength")).intValue();
                if (len > v) errors.add(instLoc + "\0" + schemaLoc + "/maxLength");
            }
        }

        // Array keywords (only for array instances)
        if (instance instanceof List) {
            List<Object> arr = (List<Object>) instance;
            if (sch.containsKey("minItems")) {
                int v = ((Double) sch.get("minItems")).intValue();
                if (arr.size() < v) errors.add(instLoc + "\0" + schemaLoc + "/minItems");
            }
            if (sch.containsKey("maxItems")) {
                int v = ((Double) sch.get("maxItems")).intValue();
                if (arr.size() > v) errors.add(instLoc + "\0" + schemaLoc + "/maxItems");
            }
            if (sch.containsKey("uniqueItems")) {
                if (Boolean.TRUE.equals(sch.get("uniqueItems"))) {
                    boolean unique = true;
                    outer:
                    for (int i = 0; i < arr.size(); i++) {
                        for (int j = i + 1; j < arr.size(); j++) {
                            if (deepEqual(arr.get(i), arr.get(j))) {
                                unique = false;
                                break outer;
                            }
                        }
                    }
                    if (!unique) errors.add(instLoc + "\0" + schemaLoc + "/uniqueItems");
                }
            }
            // prefixItems
            int prefixLen = 0;
            if (sch.containsKey("prefixItems")) {
                List<Object> pi = (List<Object>) sch.get("prefixItems");
                prefixLen = pi.size();
                for (int i = 0; i < Math.min(arr.size(), pi.size()); i++) {
                    validate(arr.get(i), pi.get(i), instLoc + "/" + i,
                            schemaLoc + "/prefixItems/" + i, errors, rootSchema);
                }
            }
            // items
            if (sch.containsKey("items")) {
                Object itemsSchema = sch.get("items");
                int start = sch.containsKey("prefixItems") ? prefixLen : 0;
                for (int i = start; i < arr.size(); i++) {
                    validate(arr.get(i), itemsSchema, instLoc + "/" + i,
                            schemaLoc + "/items", errors, rootSchema);
                }
            }
        }

        // Object keywords (only for object instances)
        if (instance instanceof Map) {
            Map<String, Object> obj = (Map<String, Object>) instance;
            if (sch.containsKey("minProperties")) {
                int v = ((Double) sch.get("minProperties")).intValue();
                if (obj.size() < v) errors.add(instLoc + "\0" + schemaLoc + "/minProperties");
            }
            if (sch.containsKey("maxProperties")) {
                int v = ((Double) sch.get("maxProperties")).intValue();
                if (obj.size() > v) errors.add(instLoc + "\0" + schemaLoc + "/maxProperties");
            }
            // properties
            Set<String> propKeys = Collections.emptySet();
            if (sch.containsKey("properties")) {
                Map<String, Object> props = (Map<String, Object>) sch.get("properties");
                propKeys = props.keySet();
                for (Map.Entry<String, Object> entry : obj.entrySet()) {
                    String name = entry.getKey();
                    if (props.containsKey(name)) {
                        validate(entry.getValue(), props.get(name),
                                instLoc + "/" + encodeToken(name),
                                schemaLoc + "/properties/" + encodeToken(name), errors, rootSchema);
                    }
                }
            }
            // required
            if (sch.containsKey("required")) {
                List<Object> req = (List<Object>) sch.get("required");
                for (int j = 0; j < req.size(); j++) {
                    String name = (String) req.get(j);
                    if (!obj.containsKey(name)) {
                        errors.add(instLoc + "\0" + schemaLoc + "/required/" + j);
                    }
                }
            }
            // additionalProperties
            if (sch.containsKey("additionalProperties")) {
                Object addSchema = sch.get("additionalProperties");
                for (Map.Entry<String, Object> entry : obj.entrySet()) {
                    String name = entry.getKey();
                    if (!propKeys.contains(name)) {
                        validate(entry.getValue(), addSchema,
                                instLoc + "/" + encodeToken(name),
                                schemaLoc + "/additionalProperties", errors, rootSchema);
                    }
                }
            }
        }

        // allOf
        if (sch.containsKey("allOf")) {
            List<Object> allOf = (List<Object>) sch.get("allOf");
            for (int i = 0; i < allOf.size(); i++) {
                validate(instance, allOf.get(i), instLoc, schemaLoc + "/allOf/" + i, errors, rootSchema);
            }
        }

        // anyOf
        if (sch.containsKey("anyOf")) {
            List<Object> anyOf = (List<Object>) sch.get("anyOf");
            boolean anyAccepted = false;
            for (Object sub : anyOf) {
                TreeSet<String> temp = new TreeSet<>(Main::compareErrors);
                validate(instance, sub, instLoc, "#", temp, rootSchema);
                if (temp.isEmpty()) { anyAccepted = true; break; }
            }
            if (!anyAccepted) errors.add(instLoc + "\0" + schemaLoc + "/anyOf");
        }

        // oneOf
        if (sch.containsKey("oneOf")) {
            List<Object> oneOf = (List<Object>) sch.get("oneOf");
            int count = 0;
            for (Object sub : oneOf) {
                TreeSet<String> temp = new TreeSet<>(Main::compareErrors);
                validate(instance, sub, instLoc, "#", temp, rootSchema);
                if (temp.isEmpty()) count++;
            }
            if (count != 1) errors.add(instLoc + "\0" + schemaLoc + "/oneOf");
        }

        // not
        if (sch.containsKey("not")) {
            Object notSchema = sch.get("not");
            TreeSet<String> temp = new TreeSet<>(Main::compareErrors);
            validate(instance, notSchema, instLoc, "#", temp, rootSchema);
            if (temp.isEmpty()) errors.add(instLoc + "\0" + schemaLoc + "/not");
        }

        // if/then/else
        if (sch.containsKey("if")) {
            Object ifSchema = sch.get("if");
            TreeSet<String> temp = new TreeSet<>(Main::compareErrors);
            validate(instance, ifSchema, instLoc, "#", temp, rootSchema);
            if (temp.isEmpty()) {
                if (sch.containsKey("then")) {
                    validate(instance, sch.get("then"), instLoc, schemaLoc + "/then", errors, rootSchema);
                }
            } else {
                if (sch.containsKey("else")) {
                    validate(instance, sch.get("else"), instLoc, schemaLoc + "/else", errors, rootSchema);
                }
            }
        }

        // $ref
        if (sch.containsKey("$ref")) {
            String ref = (String) sch.get("$ref");
            Object refSchema = resolveRef(ref, rootSchema);
            validate(instance, refSchema, instLoc, ref, errors, rootSchema);
        }
    }

    @SuppressWarnings("unchecked")
    static Object resolveRef(String ref, Object rootSchema) {
        if (ref.equals("#")) return rootSchema;
        // "#/$defs/<name>"
        String token = ref.substring("#/$defs/".length());
        String name = decodeToken(token);
        Map<String, Object> root = (Map<String, Object>) rootSchema;
        Map<String, Object> defs = (Map<String, Object>) root.get("$defs");
        return defs.get(name);
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String configStr = new String(Files.readAllBytes(Paths.get(dir, "config.json")), StandardCharsets.UTF_8);
        String tokensStr = new String(Files.readAllBytes(Paths.get(dir, "tokens.txt")), StandardCharsets.UTF_8);

        Object configObj = new JsonParser(configStr).parse();
        @SuppressWarnings("unchecked")
        Map<String, Object> config = (Map<String, Object>) configObj;
        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");
        @SuppressWarnings("unchecked")
        List<Object> keysList = (List<Object>) config.get("keys");

        Map<String, Map<String, Object>> keyMap = new HashMap<>();
        for (Object k : keysList) {
            @SuppressWarnings("unchecked")
            Map<String, Object> key = (Map<String, Object>) k;
            keyMap.put((String) key.get("kid"), key);
        }

        String[] lines = tokensStr.split("\n", -1);
        int tokenNum = 0;
        int validCount = 0;
        int invalidCount = 0;
        StringBuilder sb = new StringBuilder();

        for (String line : lines) {
            String trimmed = trimSpacesTabs(line);
            if (trimmed.isEmpty()) continue;
            tokenNum++;

            String result = verifyToken(trimmed, now, leeway, issuer, audience, keyMap);
            if (result.startsWith("VALID")) {
                validCount++;
            } else {
                invalidCount++;
            }
            sb.append(tokenNum).append(": ").append(result).append("\n");
        }

        sb.append("\n");
        sb.append("valid=").append(validCount).append(" invalid=").append(invalidCount);
        PrintStream out = new PrintStream(System.out, true, "UTF-8");
        out.print(sb.toString());
        out.flush();
    }

    static String trimSpacesTabs(String s) {
        int start = 0, end = s.length();
        while (start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t')) start++;
        while (end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t')) end--;
        return s.substring(start, end);
    }

    @SuppressWarnings("unchecked")
    static String verifyToken(String token, double now, double leeway, String issuer, String audience, Map<String, Map<String, Object>> keyMap) {
        // Rule 1: MALFORMED
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) return "MALFORMED";
        for (String p : parts) {
            if (p.isEmpty()) return "MALFORMED";
            if (!isValidBase64url(p)) return "MALFORMED";
        }
        byte[] headerBytes = base64urlDecode(parts[0]);
        byte[] payloadBytes = base64urlDecode(parts[1]);
        byte[] sigBytes = base64urlDecode(parts[2]);

        Object headerObj;
        Object payloadObj;
        try {
            headerObj = new JsonParser(new String(headerBytes, StandardCharsets.UTF_8)).parse();
            payloadObj = new JsonParser(new String(payloadBytes, StandardCharsets.UTF_8)).parse();
        } catch (Exception e) {
            return "MALFORMED";
        }
        if (!(headerObj instanceof Map) || !(payloadObj instanceof Map)) return "MALFORMED";

        Map<String, Object> header = (Map<String, Object>) headerObj;
        Map<String, Object> payload = (Map<String, Object>) payloadObj;

        // Rule 2: UNSUPPORTED_ALG
        Object algObj = header.get("alg");
        if (!(algObj instanceof String)) return "UNSUPPORTED_ALG";
        String alg = (String) algObj;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512")) return "UNSUPPORTED_ALG";

        // Rule 3: UNKNOWN_KEY
        Object kidObj = header.get("kid");
        if (!(kidObj instanceof String)) return "UNKNOWN_KEY";
        String kid = (String) kidObj;
        Map<String, Object> key = keyMap.get(kid);
        if (key == null) return "UNKNOWN_KEY";

        // Rule 4: ALG_MISMATCH
        String keyAlg = (String) key.get("alg");
        if (!alg.equals(keyAlg)) return "ALG_MISMATCH";

        // Rule 5: BAD_SIGNATURE
        String kStr = (String) key.get("k");
        byte[] secret = base64urlDecode(kStr);
        String signingInput = parts[0] + "." + parts[1];
        byte[] signingInputBytes = signingInput.getBytes(StandardCharsets.US_ASCII);
        String macAlgo;
        int expectedLen;
        switch (alg) {
            case "HS256": macAlgo = "HmacSHA256"; expectedLen = 32; break;
            case "HS384": macAlgo = "HmacSHA384"; expectedLen = 48; break;
            case "HS512": macAlgo = "HmacSHA512"; expectedLen = 64; break;
            default: return "BAD_SIGNATURE";
        }
        try {
            Mac mac = Mac.getInstance(macAlgo);
            mac.init(new SecretKeySpec(secret, macAlgo));
            byte[] expectedSig = mac.doFinal(signingInputBytes);
            if (sigBytes.length != expectedLen || !Arrays.equals(sigBytes, expectedSig)) return "BAD_SIGNATURE";
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        // Rule 6: EXPIRED
        if (payload.containsKey("exp")) {
            Object expObj = payload.get("exp");
            if (expObj instanceof Number) {
                double exp = ((Number) expObj).doubleValue();
                if (now >= exp + leeway) return "EXPIRED";
            }
        }

        // Rule 7: NOT_YET_VALID
        if (payload.containsKey("nbf")) {
            Object nbfObj = payload.get("nbf");
            if (nbfObj instanceof Number) {
                double nbf = ((Number) nbfObj).doubleValue();
                if (now + leeway < nbf) return "NOT_YET_VALID";
            }
        }

        // Rule 8: BAD_ISSUER
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !issObj.equals(issuer)) return "BAD_ISSUER";

        // Rule 9: BAD_AUDIENCE
        Object audObj = payload.get("aud");
        if (audObj == null) return "BAD_AUDIENCE";
        if (audObj instanceof String) {
            if (!audObj.equals(audience)) return "BAD_AUDIENCE";
        } else if (audObj instanceof List) {
            List<?> audList = (List<?>) audObj;
            boolean found = false;
            for (Object e : audList) {
                if (e instanceof String && e.equals(audience)) { found = true; break; }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = (String) payload.get("sub");
        String scopeStr = "";
        Object scopeObj = payload.get("scope");
        if (scopeObj instanceof String) {
            scopeStr = (String) scopeObj;
        }
        String scopes = processScopes(scopeStr);
        return "VALID sub=" + sub + " scope=" + scopes;
    }

    static String processScopes(String scopeStr) {
        if (scopeStr == null || scopeStr.isEmpty()) return "";
        String[] pieces = scopeStr.split(" ");
        TreeSet<String> set = new TreeSet<>();
        for (String p : pieces) {
            if (!p.isEmpty()) set.add(p);
        }
        return String.join(",", set);
    }

    static boolean isValidBase64url(String s) {
        if (s.length() % 4 == 1) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_'))
                return false;
        }
        return true;
    }

    static byte[] base64urlDecode(String s) {
        int len = s.length();
        int outLen = (len * 6) / 8;
        byte[] out = new byte[outLen];
        int bitBuf = 0;
        int bitsLeft = 0;
        int idx = 0;
        for (int i = 0; i < len; i++) {
            int val = b64urlChar(s.charAt(i));
            bitBuf = (bitBuf << 6) | val;
            bitsLeft += 6;
            if (bitsLeft >= 8) {
                bitsLeft -= 8;
                out[idx++] = (byte) ((bitBuf >> bitsLeft) & 0xFF);
            }
        }
        return out;
    }

    static int b64urlChar(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == '-') return 62;
        if (c == '_') return 63;
        return 0;
    }

    // --- JSON Parser ---
    static class JsonParser {
        private final String src;
        private int pos;

        JsonParser(String src) {
            this.src = src;
            this.pos = 0;
        }

        Object parse() {
            skipWs();
            Object val = parseValue();
            skipWs();
            return val;
        }

        private Object parseValue() {
            skipWs();
            if (pos >= src.length()) throw new RuntimeException("Unexpected end");
            char c = src.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') return parseLiteral("true", Boolean.TRUE);
            if (c == 'f') return parseLiteral("false", Boolean.FALSE);
            if (c == 'n') return parseLiteral("null", null);
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("Unexpected char: " + c);
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            skipWs();
            if (pos < src.length() && src.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                if (pos >= src.length() || src.charAt(pos) != '"') throw new RuntimeException("Expected string key");
                String key = parseString();
                skipWs();
                if (pos >= src.length() || src.charAt(pos) != ':') throw new RuntimeException("Expected :");
                pos++;
                skipWs();
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos >= src.length()) throw new RuntimeException("Unexpected end in object");
                if (src.charAt(pos) == ',') { pos++; continue; }
                if (src.charAt(pos) == '}') { pos++; break; }
                throw new RuntimeException("Expected , or }");
            }
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // [
            skipWs();
            if (pos < src.length() && src.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                Object val = parseValue();
                list.add(val);
                skipWs();
                if (pos >= src.length()) throw new RuntimeException("Unexpected end in array");
                if (src.charAt(pos) == ',') { pos++; continue; }
                if (src.charAt(pos) == ']') { pos++; break; }
                throw new RuntimeException("Expected , or ]");
            }
            return list;
        }

        private String parseString() {
            pos++; // opening "
            StringBuilder sb = new StringBuilder();
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    if (pos >= src.length()) throw new RuntimeException("Unexpected end in string");
                    char e = src.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            pos++;
                            if (pos + 4 > src.length()) throw new RuntimeException("Bad unicode escape");
                            String hex = src.substring(pos, pos + 4);
                            int cp = Integer.parseInt(hex, 16);
                            sb.append((char) cp);
                            pos += 3; // will be incremented below
                            break;
                        default: throw new RuntimeException("Bad escape: " + e);
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            throw new RuntimeException("Unterminated string");
        }

        private Double parseNumber() {
            int start = pos;
            if (pos < src.length() && src.charAt(pos) == '-') pos++;
            while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
            if (pos < src.length() && src.charAt(pos) == '.') {
                pos++;
                while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
            }
            if (pos < src.length() && (src.charAt(pos) == 'e' || src.charAt(pos) == 'E')) {
                pos++;
                if (pos < src.length() && (src.charAt(pos) == '+' || src.charAt(pos) == '-')) pos++;
                while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
            }
            return Double.parseDouble(src.substring(start, pos));
        }

        private Object parseLiteral(String lit, Object val) {
            if (src.startsWith(lit, pos)) { pos += lit.length(); return val; }
            throw new RuntimeException("Expected " + lit);
        }

        private void skipWs() {
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }
    }
}

