        pos += 2; /* rclass */
        uint32_t ttl = ((uint32_t)msg[pos] << 24) | ((uint32_t)msg[pos + 1] << 16) |
                       ((uint32_t)msg[pos + 2] << 8) | msg[pos + 3];
        pos += 4;
        uint16_t rdlen = (msg[pos] << 8) | msg[pos + 1]; pos += 2;

        int rdata_start = pos;
        if (rdata_start + rdlen > msglen) break;

        printf("  ");
        print_name(owner);
        printf(" %u ", ttl);

        const char *tn = num_to_type(rtype);
        if (tn) printf("%s ", tn);
        else printf("TYPE%d ", rtype);

        switch (rtype) {
            case 1:
                printf("%d.%d.%d.%d\n",
                       msg[rdata_start], msg[rdata_start + 1],
                       msg[rdata_start + 2], msg[rdata_start + 3]);
                break;
            case 28:
                print_aaaa(msg + rdata_start);
                printf("\n");
                break;
            case 5: {
                char target[MAX_NAME];
                int tnp;
                dns_read_name(msg, msglen, rdata_start, target, sizeof(target), &tnp);
                print_name(target);
                printf("\n");
                break;
            }
            case 15: {
                uint16_t pref = (msg[rdata_start] << 8) | msg[rdata_start + 1];
                char exchange[MAX_NAME];
                int enp;
                dns_read_name(msg, msglen, rdata_start + 2, exchange, sizeof(exchange), &enp);
                printf("%u ", pref);
                print_name(exchange);
                printf("\n");
                break;
            }
            case 16:
                print_txt(msg + rdata_start, rdlen);
                printf("\n");
                break;
            default:
                printf("\\# %d", rdlen);
                if (rdlen > 0) {
                    printf(" ");
                    for (int j = 0; j < rdlen; j++)
                        printf("%02x", msg[rdata_start + j]);
                }
                printf("\n");
                break;
