}

int main(int argc, char *argv[]) {
    if (argc != 3) return 1;
    const char *dir = argv[1];
    int port = atoi(argv[2]);

    char path[4096];
    snprintf(path, sizeof(path), "%s/queries.txt", dir);
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    srand((unsigned)time(NULL));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((uint16_t)port);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len == 0) continue;

        char *space = strchr(line, ' ');
        if (!space) continue;
        *space = '\0';
        char *name = line;
        char *type_str = space + 1;

        int qtype = type_to_num(type_str);
        if (qtype < 0) continue;

        char dispname[MAX_NAME];
        normalize_query_name(name, dispname, sizeof(dispname));

        uint8_t query[MAX_MSG];
        uint16_t id = (uint16_t)(rand() & 0xFFFF);
        int qlen = build_query(name, qtype, id, query);

        /* UDP */
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(sock, query, qlen, 0, (struct sockaddr *)&addr, sizeof(addr));

        uint8_t resp[MAX_MSG];
        int rlen;
        while (1) {
            rlen = (int)recv(sock, resp, sizeof(resp), 0);
            if (rlen < 12) continue;
            uint16_t rid = (resp[0] << 8) | resp[1];
            uint16_t rf = (resp[2] << 8) | resp[3];
            if (rid == id && (rf & 0x8000)) break;
        }
        close(sock);

        /* TCP fallback if TC=1 */
        uint16_t rflags = (resp[2] << 8) | resp[3];
        if (rflags & 0x0200) {
            int tsock = socket(AF_INET, SOCK_STREAM, 0);
            connect(tsock, (struct sockaddr *)&addr, sizeof(addr));

            uint8_t tcpbuf[MAX_MSG + 2];
            tcpbuf[0] = (qlen >> 8) & 0xFF;
            tcpbuf[1] = qlen & 0xFF;
            memcpy(tcpbuf + 2, query, qlen);
            write_exact(tsock, tcpbuf, qlen + 2);

            uint8_t lb[2];
            read_exact(tsock, lb, 2);
            int msglen = (lb[0] << 8) | lb[1];
            read_exact(tsock, resp, msglen);
            rlen = msglen;
            close(tsock);
        }

        parse_and_print(resp, rlen, dispname, type_str);
    }

    fclose(f);
    return 0;
}

