static int type_to_num(const char *t) {
    if (strcmp(t, "A") == 0) return 1;
    if (strcmp(t, "AAAA") == 0) return 28;
    if (strcmp(t, "MX") == 0) return 15;
    if (strcmp(t, "TXT") == 0) return 16;
    if (strcmp(t, "CNAME") == 0) return 5;
    return -1;
}

static const char *num_to_type(int t) {
    switch (t) {
        case 1: return "A";
        case 28: return "AAAA";
        case 15: return "MX";
        case 16: return "TXT";
        case 5: return "CNAME";
        default: return NULL;
    }
}

static void print_rcode(int rcode) {
    switch (rcode) {
        case 0: printf("NOERROR"); break;
        case 1: printf("FORMERR"); break;
        case 2: printf("SERVFAIL"); break;
        case 3: printf("NXDOMAIN"); break;
        case 4: printf("NOTIMP"); break;
        case 5: printf("REFUSED"); break;
        default: printf("RCODE%d", rcode); break;
    }
}

static int dns_read_name(const uint8_t *msg, int msglen, int pos,
                         char *out, int outsize, int *new_pos) {
    int out_len = 0;
    int first = 1;
    int cur = pos;
    int stream_end = -1;
    int loops = 0;

    while (loops++ < 128) {
        if (cur < 0 || cur >= msglen) {
            out[0] = '\0';
            *new_pos = pos;
            return -1;
        }
        uint8_t b = msg[cur];
        if (b == 0) {
            if (stream_end == -1) stream_end = cur + 1;
            break;
        }
        if ((b & 0xC0) == 0xC0) {
            if (cur + 1 >= msglen) {
                out[0] = '\0';
                *new_pos = pos;
                return -1;
            }
            int ptr = ((b & 0x3F) << 8) | msg[cur + 1];
            if (stream_end == -1) stream_end = cur + 2;
            cur = ptr;
            continue;
        }
        cur++;
        if (cur + b > msglen) {
            out[0] = '\0';
            *new_pos = pos;
            return -1;
        }
        if (!first) {
            if (out_len < outsize - 1) out[out_len++] = '.';
        }
        first = 0;
        for (int i = 0; i < b; i++) {
            if (out_len < outsize - 1)
                out[out_len++] = tolower((unsigned char)msg[cur + i]);
        }
        cur += b;
    }
    out[out_len] = '\0';
    *new_pos = (stream_end == -1) ? cur : stream_end;
    return 0;
}

static void print_name(const char *name) {
    if (name[0] == '\0') printf(".");
    else printf("%s", name);
}

static void print_aaaa(const uint8_t *addr) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (addr[i * 2] << 8) | addr[i * 2 + 1];

    int best_start = -1, best_len = 0;
    for (int i = 0; i < 8;) {
        if (groups[i] == 0) {
            int j = i;
            while (j < 8 && groups[j] == 0) j++;
            if (j - i >= 2 && j - i > best_len) {
                best_start = i;
                best_len = j - i;
            }
            i = j;
        } else {
            i++;
        }
    }

    if (best_start == -1) {
        for (int i = 0; i < 8; i++) {
            if (i > 0) printf(":");
            printf("%x", groups[i]);
        }
    } else {
        for (int i = 0; i < best_start; i++) {
            if (i > 0) printf(":");
            printf("%x", groups[i]);
        }
        if (best_start > 0) printf(":");
        printf("::");
        for (int i = best_start + best_len; i < 8; i++) {
            printf("%x", groups[i]);
            if (i < 7) printf(":");
        }
    }
}

static void print_txt(const uint8_t *rdata, int rdlen) {
    int pos = 0;
    int first = 1;
    while (pos < rdlen) {
        if (!first) printf(" ");
        first = 0;
        int slen = rdata[pos++];
        printf("\"");
        for (int i = 0; i < slen && pos < rdlen; i++, pos++) {
            uint8_t c = rdata[pos];
            if (c == '"') printf("\\\"");
            else if (c == '\\') printf("\\\\");
            else if (c >= 0x20 && c <= 0x7E) putchar(c);
            else printf("\\%03d", c);
        }
        printf("\"");
    }
}

