import Foundation
import CommonCrypto

func isValidBase64url(_ s: String) -> Bool {
    if s.isEmpty { return false }
    for c in s {
        guard (c >= "A" && c <= "Z") || (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-" || c == "_" else {
            return false
        }
    }
    if s.contains("=") { return false }
    if s.count % 4 == 1 { return false }
    return true
}

func base64urlDecode(_ s: String) -> Data? {
    if s.isEmpty { return nil }
    for c in s {
        guard (c >= "A" && c <= "Z") || (c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c == "-" || c == "_" else {
            return nil
        }
    }
    if s.contains("=") { return nil }
    if s.count % 4 == 1 { return nil }
    var b64 = s.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
    let pad = (4 - (b64.count % 4)) % 4
    b64 += String(repeating: "=", count: pad)
    return Data(base64Encoded: b64)
}

func computeHMAC(alg: String, key: Data, message: Data) -> Data? {
    var algorithm: CCHmacAlgorithm
    var macLen: Int
    switch alg {
    case "HS256":
        algorithm = CCHmacAlgorithm(kCCHmacAlgSHA256)
        macLen = Int(CC_SHA256_DIGEST_LENGTH)
    case "HS384":
        algorithm = CCHmacAlgorithm(kCCHmacAlgSHA384)
        macLen = Int(CC_SHA384_DIGEST_LENGTH)
    case "HS512":
        algorithm = CCHmacAlgorithm(kCCHmacAlgSHA512)
        macLen = Int(CC_SHA512_DIGEST_LENGTH)
    default:
        return nil
    }
    var result = [UInt8](repeating: 0, count: macLen)
    key.withUnsafeBytes { keyPtr in
        message.withUnsafeBytes { msgPtr in
            CCHmac(algorithm, keyPtr.baseAddress, key.count, msgPtr.baseAddress, message.count, &result)
        }
    }
    return Data(result)
}

enum TokenResult {
    case valid(sub: String, scopes: String)
    case error(String)
}

func verifyToken(_ token: String, now: Double, leeway: Double, issuer: String, audience: String,
                 keySet: [String: (kty: String, alg: String, k: Data)]) -> TokenResult {
    // Rule 1: MALFORMED
    let segments = token.components(separatedBy: ".")
    if segments.count != 3 { return .error("MALFORMED") }
    for seg in segments {
        if seg.isEmpty { return .error("MALFORMED") }
        if !isValidBase64url(seg) { return .error("MALFORMED") }
    }
    guard let headerData = base64urlDecode(segments[0]) else { return .error("MALFORMED") }
    guard let payloadData = base64urlDecode(segments[1]) else { return .error("MALFORMED") }
    guard let sigData = base64urlDecode(segments[2]) else { return .error("MALFORMED") }
    guard let headerObj = (try? JSONSerialization.jsonObject(with: headerData)) as? [String: Any] else {
        return .error("MALFORMED")
    }
    guard let payloadObj = (try? JSONSerialization.jsonObject(with: payloadData)) as? [String: Any] else {
        return .error("MALFORMED")
    }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = headerObj["alg"] as? String else { return .error("UNSUPPORTED_ALG") }
    if alg != "HS256" && alg != "HS384" && alg != "HS512" { return .error("UNSUPPORTED_ALG") }

    // Rule 3: UNKNOWN_KEY
    guard let kid = headerObj["kid"] as? String else { return .error("UNKNOWN_KEY") }
    guard let key = keySet[kid] else { return .error("UNKNOWN_KEY") }

    // Rule 4: ALG_MISMATCH
    if key.alg != alg { return .error("ALG_MISMATCH") }

    // Rule 5: BAD_SIGNATURE
    let signingInputStr = segments[0] + "." + segments[1]
    guard let signingInput = signingInputStr.data(using: .ascii) else { return .error("BAD_SIGNATURE") }
    guard let expectedSig = computeHMAC(alg: alg, key: key.k, message: signingInput) else {
        return .error("BAD_SIGNATURE")
    }
    if sigData != expectedSig { return .error("BAD_SIGNATURE") }

    // Rule 6: EXPIRED
    if let expVal = payloadObj["exp"], let expNum = expVal as? NSNumber {
        let exp = expNum.doubleValue
        if now >= exp + leeway { return .error("EXPIRED") }
    }

    // Rule 7: NOT_YET_VALID
    if let nbfVal = payloadObj["nbf"], let nbfNum = nbfVal as? NSNumber {
        let nbf = nbfNum.doubleValue
        if now + leeway < nbf { return .error("NOT_YET_VALID") }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payloadObj["iss"] as? String else { return .error("BAD_ISSUER") }
    if iss != issuer { return .error("BAD_ISSUER") }

    // Rule 9: BAD_AUDIENCE
    guard let aud = payloadObj["aud"] else { return .error("BAD_AUDIENCE") }
    if let audStr = aud as? String {
        if audStr != audience { return .error("BAD_AUDIENCE") }
    } else if let audArr = aud as? [Any] {
        var found = false
        for elem in audArr {
            if let s = elem as? String, s == audience {
                found = true
                break
            }
        }
        if !found { return .error("BAD_AUDIENCE") }
    } else {
        return .error("BAD_AUDIENCE")
    }

    // VALID
    let sub = payloadObj["sub"] as? String ?? ""
    var scopesStr = ""
    if let scope = payloadObj["scope"] as? String {
        let parts = scope.components(separatedBy: " ").filter { !$0.isEmpty }
        let unique = Array(Set(parts))
        let sorted = unique.sorted { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
        scopesStr = sorted.joined(separator: ",")
    }
    return .valid(sub: sub, scopes: scopesStr)
}

