/* ============ Parsing ============ */
static char *tok(char **p){
    while(**p==' '||**p=='\t') (*p)++;
    if(**p==0||**p=='\n'||**p=='\r') return NULL;
    char *s=*p;
    while(**p&&**p!=' '&&**p!='\t'&&**p!='\n'&&**p!='\r') (*p)++;
    if(**p) (*p)++[0-1]=0; /* null terminate */
    /* Actually let me redo this */
    return s;
}

/* Simpler tokenizer */
static char *get_tok(char **p){
    while(**p==' '||**p=='\t') (*p)++;
    if(**p==0||**p=='\n'||**p=='\r') return NULL;
    char *s=*p;
    while(**p&&**p!=' '&&**p!='\t'&&**p!='\n'&&**p!='\r') (*p)++;
    if(**p){ **p=0; (*p)++; }
    return s;
}

static void parse_dec(Dec *d, const char *s){
    d->sign=1; d->scale=0; bi_zero(&d->abs);
    if(*s=='-'){ d->sign=-1; s++; }
    else if(*s=='+'){ s++; }
    int int_digits=0, frac_digits=0;
    /* count integer digits */
    const char *p=s;
    while(*p>='0'&&*p<='9'){ int_digits++; p++; }
    if(*p=='.'){ p++; while(*p>='0'&&*p<='9'){ frac_digits++; p++; } }
    d->scale=frac_digits;
    /* build the integer: int_digits + frac_digits digits */
    BI result; bi_zero(&result);
    p=s;
    while(*p>='0'&&*p<='9'){
        bi_mul_small(&result,&result,10);
        bi_add_small(&result,(uint32_t)(*p-'0'));
        p++;
    }
    if(*p=='.') p++;
    while(*p>='0'&&*p<='9'){
        bi_mul_small(&result,&result,10);
        bi_add_small(&result,(uint32_t)(*p-'0'));
        p++;
    }
    d->abs=result;
    if(bi_is_zero(&d->abs)) d->sign=0;
}

static void parse_bi(BI *r, const char *s){
    bi_zero(r);
    while(*s>='0'&&*s<='9'){
        bi_mul_small(r,r,10);
        bi_add_small(r,(uint32_t)(*s-'0'));
        s++;
    }
}

/* ============ Formatting ============ */
static void bi_to_str(const BI *a, char *buf){
    if(bi_is_zero(a)){ buf[0]='0'; buf[1]=0; return; }
    BI tmp; bi_copy(&tmp,a);
    char rev[300]; int len=0;
    while(!bi_is_zero(&tmp)){
        uint32_t rem=bi_div_small(&tmp,10);
        rev[len++]='0'+(char)rem;
    }
    for(int i=0;i<len;i++) buf[i]=rev[len-1-i];
    buf[len]=0;
}

static void fmt_money(const Dec *d, int minor, char *buf){
    Dec tmp=*d;
    dec_round(&tmp,minor);
    if(tmp.sign==0||bi_is_zero(&tmp.abs)){
        /* print 0.00... */
        buf[0]='0'; int pos=1;
        if(minor>0){ buf[pos++]='.'; for(int i=0;i<minor;i++) buf[pos++]='0'; }
        buf[pos]=0; return;
    }
    int pos=0;
    if(tmp.sign<0) buf[pos++]='-';
    /* integer part = abs / 10^minor, frac part = abs % 10^minor */
    BI divisor; bi_pow10(&divisor,minor);
    BI ipart, fpart;
    bi_divmod(&ipart,&fpart,&tmp.abs,&divisor);
    char ibuf[300]; bi_to_str(&ipart,ibuf);
    int ilen=(int)strlen(ibuf);
    /* insert commas */
    int first_group=ilen%3; if(first_group==0) first_group=3;
    for(int i=0;i<ilen;i++){
        if(i>0&&(i-first_group)%3==0) buf[pos++]=',';
        buf[pos++]=ibuf[i];
    }
    if(minor>0){
        buf[pos++]='.';
        char fbuf[300]; bi_to_str(&fpart,fbuf);
        int flen=(int)strlen(fbuf);
        for(int i=0;i<minor-flen;i++) buf[pos++]='0';
        for(int i=0;i<flen;i++) buf[pos++]=fbuf[i];
    }
    buf[pos]=0;
}

/* ============ Main ============ */
int main(int argc, char *argv[]){
    if(argc<2){ fprintf(stderr,"Usage: %s <dir>\n",argv[0]); return 1; }
    char path[4096];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f){ perror("open"); return 1; }

    char line[MAX_LINE];
    int lineno=0;

    while(fgets(line,sizeof(line),f)){
        lineno++;
        /* strip trailing newline */
        int len=(int)strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;

        /* check blank/comment */
        int blank=1;
        for(int i=0;i<len;i++){ if(line[i]!=' '&&line[i]!='\t'){ blank=0; break; } }
        if(blank) continue;
        int fi=0; while(fi<len&&(line[fi]==' '||line[fi]=='\t')) fi++;
        if(line[fi]=='#') continue;

        /* tokenize */
        char *p=line;
        char *cmd=get_tok(&p);
        if(!cmd) continue;

        if(strcmp(cmd,"currency")==0){
            char *code=get_tok(&p);
            char *mu=get_tok(&p);
            if(!code||!mu) continue;
            int mi=atoi(mu);
            int ci=find_curr(code);
            if(ci<0){
                ci=ncurr++;
                strcpy(currs[ci].code,code);
                currs[ci].minor=mi;
            } else {
                currs[ci].minor=mi;
            }
        }
        else if(strcmp(cmd,"open")==0){
            char *name=get_tok(&p);
            char *code=get_tok(&p);
            char *lim=get_tok(&p);
            if(!name||!code) continue;
            /* check account exists */
            if(find_acct(name)>=0){
                snprintf(rejs[nrej++],300,"line %d: REJECT account exists %s",lineno,name);
                continue;
            }
            int ci=find_curr(code);
            if(ci<0) continue; /* shouldn't happen */
            Acct *a=&accts[nacct++];
            strcpy(a->name,name);
            a->cidx=ci;
            dec_zero(&a->bal);
            dec_zero(&a->limit);
            if(lim){
                parse_dec(&a->limit,lim);
                dec_round(&a->limit,currs[ci].minor);
            }
            a->active=1;
        }
        else if(strcmp(cmd,"deposit")==0){
            char *name=get_tok(&p);
            char *amt=get_tok(&p);
            if(!name||!amt) continue;
            int ai=find_acct(name);
            if(ai<0){ snprintf(rejs[nrej++],300,"line %d: REJECT unknown account %s",lineno,name); continue; }
            Dec a; parse_dec(&a,amt);
            int mi=currs[accts[ai].cidx].minor;
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],300,"line %d: REJECT non-positive amount",lineno); continue; }
            dec_add(&accts[ai].bal,&accts[ai].bal,&a);
        }
        else if(strcmp(cmd,"withdraw")==0){
            char *name=get_tok(&p);
            char *amt=get_tok(&p);
            if(!name||!amt) continue;
            int ai=find_acct(name);
            if(ai<0){ snprintf(rejs[nrej++],300,"line %d: REJECT unknown account %s",lineno,name); continue; }
            Dec a; parse_dec(&a,amt);
            int mi=currs[accts[ai].cidx].minor;
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],300,"line %d: REJECT non-positive amount",lineno); continue; }
            /* check funds: new_bal = bal - a >= -limit */
            Dec newbal;
            Dec neg_a=a; neg_a.sign=-neg_a.sign; if(neg_a.sign==0) neg_a.sign=0;
            dec_add(&newbal,&accts[ai].bal,&neg_a);
            /* check newbal >= -limit, i.e., newbal + limit >= 0 */
            Dec neg_lim=accts[ai].limit; neg_lim.sign=-neg_lim.sign; if(neg_lim.sign==0) neg_lim.sign=0;
            Dec check; dec_add(&check,&newbal,&neg_lim);
            if(check.sign<0){
                snprintf(rejs[nrej++],300,"line %d: REJECT insufficient funds %s",lineno,name);
                continue;
            }
            accts[ai].bal=newbal;
        }
        else if(strcmp(cmd,"transfer")==0){
