            Dec neg_lim=accts[fi2].limit; neg_lim.sign=-neg_lim.sign;
            Dec check; dec_add(&check,&newbal,&neg_lim);
            if(check.sign<0){
                snprintf(rejs[nrej++],300,"line %d: REJECT insufficient funds %s",lineno,fn);
                continue;
