            "description": "Add up a non-empty list of integers.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "numbers": {
                        "type": "array",
                        "items": {"type": "integer"},
                        "minItems": 1
                    }
                },
                "required": ["numbers"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "sum": {"type": "integer"},
                    "count": {"type": "integer"}
                },
                "required": ["sum", "count"]
            },
            "annotations": {"readOnlyHint": True, "idempotentHint": True}
        },
        {
            "name": "text_stats",
            "title": "Text statistics",
            "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"}
                },
                "required": ["text"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "words": {"type": "integer"},
                    "codepoints": {"type": "integer"},
                    "utf8_bytes": {"type": "integer"}
                },
                "required": ["words", "codepoints", "utf8_bytes"]
            },
            "annotations": {"readOnlyHint": True}
        }
    ]

    TOOL_NAMES = {t["name"] for t in TOOLS}
    TOOL_MAP = {t["name"]: t for t in TOOLS}

    def output(obj):
        sys.stdout.write(json.dumps(obj, ensure_ascii=False) + '\n')

    def err_resp(rid, code, message):
        return {"jsonrpc": "2.0", "id": rid, "error": {"code": code, "message": message}}

    def ok_resp(rid, result):
        return {"jsonrpc": "2.0", "id": rid, "result": result}

    def validate_arguments(tool, args):
        schema = tool["inputSchema"]
        properties = schema.get("properties", {})
        required = schema.get("required", [])

        unknown = [k for k in args if k not in properties]
        if unknown:
            unknown.sort()
            return (f"unknown argument: {unknown[0]}", None)

        for prop_name in properties:
            if prop_name not in args:
                if prop_name in required:
                    return (f"missing required argument: {prop_name}", None)
                continue

            val = args[prop_name]
            prop_schema = properties[prop_name]
            prop_type = prop_schema.get("type")

            if prop_type == "string":
                if not isinstance(val, str):
                    return (f"argument {prop_name} must be a string", None)
                if prop_schema.get("minLength", 0) > 0 and len(val) == 0:
                    return (f"argument {prop_name} must not be empty", None)
            elif prop_type == "array":
                if not isinstance(val, list):
                    return (f"argument {prop_name} must be an array of integers", None)
                items_type = prop_schema.get("items", {}).get("type")
                if items_type == "integer":
                    for item in val:
                        if isinstance(item, bool) or not isinstance(item, int):
                            return (f"argument {prop_name} must be an array of integers", None)
                if prop_schema.get("minItems", 0) > 0 and len(val) == 0:
                    return (f"argument {prop_name} must not be empty", None)

        return (None, args)

    def tool_failure(message):
        return {"content": [{"type": "text", "text": message}], "isError": True}

    def tool_success(text):
        return {"content": [{"type": "text", "text": text}], "isError": False}

    def tool_success_structured(structured):
        return {
            "content": [{"type": "text", "text": json.dumps(structured, ensure_ascii=False)}],
            "structuredContent": structured,
            "isError": False
        }

    def handle_tools_call(rid, params):
        if params is None:
            params = {}

        name = params.get("name")
        if not isinstance(name, str):
            output(err_resp(rid, -32602, "Invalid params"))
            return

        if name not in TOOL_NAMES:
            output(err_resp(rid, -32602, f"Unknown tool: {name}"))
            return

        tool = TOOL_MAP[name]

        if "arguments" in params:
            args = params["arguments"]
            if not isinstance(args, dict):
                output(ok_resp(rid, tool_failure("arguments must be an object")))
                return
        else:
            args = {}

        err, _ = validate_arguments(tool, args)
        if err:
            output(ok_resp(rid, tool_failure(err)))
            return

        if name == "kv_set":
            key = args["key"]
            value = args["value"]
            existed = key in store
            store[key] = value
            text = f"updated {key}" if existed else f"created {key}"
            output(ok_resp(rid, tool_success(text)))

        elif name == "kv_get":
            key = args["key"]
            if key not in store:
                output(ok_resp(rid, tool_failure(f"key not found: {key}")))
            else:
                output(ok_resp(rid, tool_success(store[key])))

        elif name == "kv_list":
            prefix = args.get("prefix", "")
            keys = sorted([k for k in store if k.startswith(prefix)])
            structured = {"keys": keys, "count": len(keys)}
            output(ok_resp(rid, tool_success_structured(structured)))

        elif name == "sum":
            numbers = args["numbers"]
            total = sum(numbers)
            structured = {"sum": total, "count": len(numbers)}
            output(ok_resp(rid, tool_success_structured(structured)))

        elif name == "text_stats":
            text = args["text"]
            parts = re.split(r'[ \t\n\r]', text)
            words = sum(1 for p in parts if p)
            codepoints = len(text)
            utf8_bytes = len(text.encode('utf-8'))
            structured = {"words": words, "codepoints": codepoints, "utf8_bytes": utf8_bytes}
            output(ok_resp(rid, tool_success_structured(structured)))

    for line in sys.stdin:
        line = line.rstrip('\n')
        if line.endswith('\r'):
            line = line[:-1]

        if line.strip(' \t\r') == '':
            continue

        try:
            msg = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            output({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}})
            continue

        if not isinstance(msg, dict):
            output({"jsonrpc": "2.0", "id": None, "error": {"code": -32600, "message": "Invalid Request"}})
            continue

        if "method" not in msg and ("result" in msg or "error" in msg):
            continue

        jsonrpc_ok = msg.get("jsonrpc") == "2.0"
        method_ok = isinstance(msg.get("method"), str)
        has_id = "id" in msg
        id_is_valid = is_valid_id(msg["id"]) if has_id else True

        is_invalid = (not jsonrpc_ok) or (not method_ok) or (has_id and not id_is_valid)

        if is_invalid:
            resp_id = msg["id"] if (has_id and id_is_valid) else None
            output({"jsonrpc": "2.0", "id": resp_id, "error": {"code": -32600, "message": "Invalid Request"}})
            continue

        if not has_id:
            continue

        rid = msg["id"]
        method = msg["method"]

        if method not in ("initialize", "ping", "tools/list", "tools/call"):
            output(err_resp(rid, -32601, "Method not found"))
            continue

        if "params" in msg and not isinstance(msg["params"], dict):
            output(err_resp(rid, -32602, "Invalid params"))
            continue

        if not initialized and method not in ("initialize", "ping"):
            output(err_resp(rid, -32002, "Server not initialized"))
            continue

        params = msg.get("params")

        if method == "initialize":
            if initialized:
                output(err_resp(rid, -32600, "Already initialized"))
                continue
            if params is None or not isinstance(params.get("protocolVersion"), str):
                output(err_resp(rid, -32602, "Invalid params"))
                continue
            version = params["protocolVersion"]
            if version not in ("2025-06-18", "2025-03-26", "2024-11-05"):
                version = "2025-06-18"
            initialized = True
            output(ok_resp(rid, {
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"}
            }))

        elif method == "ping":
            output(ok_resp(rid, {}))

        elif method == "tools/list":
            output(ok_resp(rid, {"tools": TOOLS}))

        elif method == "tools/call":
            handle_tools_call(rid, params)

    sys.stdout.flush()
    sys.exit(0)


if __name__ == "__main__":
    main()

import java.io.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

public class Main {
    static boolean initialized = false;
    static LinkedHashMap<String, String> kvStore = new LinkedHashMap<>();

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        StringBuilder out = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            if (line.isEmpty()) continue;
            boolean onlyWs = true;
            for (int i = 0; i < line.length(); i++) {
                char c = line.charAt(i);
                if (c != ' ' && c != '\t' && c != '\r') { onlyWs = false; break; }
            }
            if (onlyWs) continue;
            String resp = processLine(line);
            if (resp != null) {
                out.append(resp).append('\n');
            }
        }
        System.out.print(out.toString());
        System.out.flush();
    }

    static String processLine(String line) {
        JVal parsed;
        try {
            parsed = parseJson(line);
        } catch (Exception e) {
            return errResponse(null, -32700, "Parse error");
        }
        if (parsed == null || parsed.type != JVal.OBJ) {
            return errResponse(null, -32600, "Invalid Request");
        }
        JVal methodVal = parsed.objVal.get("method");
        JVal resultVal = parsed.objVal.get("result");
        JVal errorVal = parsed.objVal.get("error");
        if (methodVal == null && (resultVal != null || errorVal != null)) {
            return null; // client response, ignore
        }
        // Check jsonrpc
        JVal jsonrpcVal = parsed.objVal.get("jsonrpc");
        if (jsonrpcVal == null || jsonrpcVal.type != JVal.STR || !jsonrpcVal.strVal.equals("2.0")) {
            return errResponse(getValidId(parsed), -32600, "Invalid Request");
        }
        // Check method
        if (methodVal == null || methodVal.type != JVal.STR) {
            return errResponse(getValidId(parsed), -32600, "Invalid Request");
        }
        // Check id validity
        boolean hasId = parsed.objVal.containsKey("id");
        JVal idVal = parsed.objVal.get("id");
        if (hasId && !isValidId(idVal)) {
            return errResponse(null, -32600, "Invalid Request");
        }
        // Notification: no id member
        if (!hasId) {
            return null;
        }
        // It's a request
        String method = methodVal.strVal;
        // 6a: method not recognized
        if (!method.equals("initialize") && !method.equals("ping") && !method.equals("tools/list") && !method.equals("tools/call")) {
            return errResponse(idVal, -32601, "Method not found");
        }
        // 6b: params present but not object
        JVal paramsVal = parsed.objVal.get("params");
        if (paramsVal != null && paramsVal.type != JVal.OBJ) {
            return errResponse(idVal, -32602, "Invalid params");
        }
        // 6c: not initialized
        if (!initialized && !method.equals("initialize") && !method.equals("ping")) {
            return errResponse(idVal, -32002, "Server not initialized");
        }
        // 6d: dispatch
        switch (method) {
            case "initialize": return handleInitialize(idVal, paramsVal);
            case "ping": return okResponse(idVal, new JVal(JVal.OBJ));
            case "tools/list": return handleToolsList(idVal);
            case "tools/call": return handleToolsCall(idVal, paramsVal);
        }
        return errResponse(idVal, -32601, "Method not found");
    }

    static JVal getValidId(JVal obj) {
        if (!obj.objVal.containsKey("id")) return null;
        JVal id = obj.objVal.get("id");
        if (isValidId(id)) return id;
        return null;
    }

    static boolean isValidId(JVal v) {
        if (v == null) return false;
        if (v.type == JVal.STR) return true;
        if (v.type == JVal.NUM && v.numIsInt) return true;
        return false;
    }

    static String handleInitialize(JVal idVal, JVal paramsVal) {
        if (initialized) {
            return errResponse(idVal, -32600, "Already initialized");
        }
        if (paramsVal == null) {
            return errResponse(idVal, -32602, "Invalid params");
        }
        JVal pv = paramsVal.objVal.get("protocolVersion");
        if (pv == null || pv.type != JVal.STR) {
            return errResponse(idVal, -32602, "Invalid params");
        }
        String ver = pv.strVal;
        if (!ver.equals("2025-06-18") && !ver.equals("2025-03-26") && !ver.equals("2024-11-05")) {
            ver = "2025-06-18";
        }
        initialized = true;
        JVal result = new JVal(JVal.OBJ);
        result.objVal.put("protocolVersion", JVal.str(ver));
        JVal caps = new JVal(JVal.OBJ);
        JVal toolsCap = new JVal(JVal.OBJ);
        toolsCap.objVal.put("listChanged", new JVal(JVal.BOOL, false));
        caps.objVal.put("tools", toolsCap);
        result.objVal.put("capabilities", caps);
        JVal serverInfo = new JVal(JVal.OBJ);
        serverInfo.objVal.put("name", JVal.str("cb2-kv"));
        serverInfo.objVal.put("title", JVal.str("CB2 key-value server"));
        serverInfo.objVal.put("version", JVal.str("1.4.2"));
        result.objVal.put("serverInfo", serverInfo);
        return okResponse(idVal, result);
    }

    static String handleToolsList(JVal idVal) {
        JVal result = new JVal(JVal.OBJ);
        JVal tools = new JVal(JVal.ARR);
        tools.arrVal.add(buildTool("kv_set", "Set a value", "Store a string value under a key, replacing any previous value.",
            buildSchemaObj(new String[]{"key","value"}, new String[]{"string","string"}, new boolean[]{true,true}, true, null, null), null, null));
        tools.arrVal.add(buildTool("kv_get", "Get a value", "Return the value stored under a key.",
            buildSchemaObj(new String[]{"key"}, new String[]{"string"}, new boolean[]{true}, true, null, null), null, null));
        tools.arrVal.add(buildTool("kv_list", "List keys", "List the stored keys that start with a prefix, sorted by Unicode code point.",
            buildSchemaObj(new String[]{"prefix"}, new String[]{"string"}, new boolean[]{false}, false, null, null),
            buildSchemaObj(new String[]{"keys","count"}, new String[]{"array","integer"}, new boolean[]{true,true}, false,
                new JVal[]{arrOfStr(), new JVal(JVal.OBJ)}, null), null));
        // Fix kv_list outputSchema properly
        tools.arrVal.set(2, buildTool("kv_list", "List keys", "List the stored keys that start with a prefix, sorted by Unicode code point.",
            buildSchemaObj(new String[]{"prefix"}, new String[]{"string"}, new boolean[]{false}, false, null, null),
            buildKvListOutputSchema(), null));
        tools.arrVal.add(buildTool("sum", "Sum integers", "Add up a non-empty list of integers.",
            buildSchemaObj(new String[]{"numbers"}, new String[]{"array"}, new boolean[]{true}, true, null, null),
            buildSumOutputSchema(), buildAnnotations(true, true)));
        tools.arrVal.add(buildTool("text_stats", "Text statistics", "Count the words, Unicode code points and UTF-8 bytes of a text.",
            buildSchemaObj(new String[]{"text"}, new String[]{"string"}, new boolean[]{true}, true, null, null),
            buildTextStatsOutputSchema(), buildAnnotations(true, null)));
        result.objVal.put("tools", tools);
        return okResponse(idVal, result);
    }

    static JVal buildTool(String name, String title, String desc, JVal inputSchema, JVal outputSchema, JVal annotations) {
        JVal tool = new JVal(JVal.OBJ);
        tool.objVal.put("name", JVal.str(name));
        tool.objVal.put("title", JVal.str(title));
        tool.objVal.put("description", JVal.str(desc));
        tool.objVal.put("inputSchema", inputSchema);
        if (outputSchema != null) tool.objVal.put("outputSchema", outputSchema);
        if (annotations != null) tool.objVal.put("annotations", annotations);
        return tool;
    }

    static JVal buildSchemaObj(String[] propNames, String[] propTypes, boolean[] required, boolean additionalProperties, JVal[] extraTypes, String[] extraReq) {
        JVal schema = new JVal(JVal.OBJ);
        schema.objVal.put("type", JVal.str("object"));
        JVal props = new JVal(JVal.OBJ);
        for (int i = 0; i < propNames.length; i++) {
            JVal prop = new JVal(JVal.OBJ);
            if (propTypes[i].equals("string")) {
                prop.objVal.put("type", JVal.str("string"));
                if (required[i]) prop.objVal.put("minLength", JVal.numInt(1));
            } else if (propTypes[i].equals("array")) {
                prop.objVal.put("type", JVal.str("array"));
                JVal items = new JVal(JVal.OBJ);
                items.objVal.put("type", JVal.str("integer"));
                prop.objVal.put("items", items);
                if (required[i]) prop.objVal.put("minItems", JVal.numInt(1));
            } else if (propTypes[i].equals("integer")) {
                prop.objVal.put("type", JVal.str("integer"));
            }
            props.objVal.put(propNames[i], prop);
        }
        schema.objVal.put("properties", props);
        JVal req = new JVal(JVal.ARR);
        for (int i = 0; i < propNames.length; i++) {
            if (required[i]) req.arrVal.add(JVal.str(propNames[i]));
        }
        if (req.arrVal.size() > 0) {
            schema.objVal.put("required", req);
        }
        if (additionalProperties) {
            schema.objVal.put("additionalProperties", new JVal(JVal.BOOL, false));
        }
        return schema;
    }

    static JVal arrOfStr() {
        JVal a = new JVal(JVal.OBJ);
        a.objVal.put("type", JVal.str("array"));
        JVal items = new JVal(JVal.OBJ);
        items.objVal.put("type", JVal.str("string"));
        a.objVal.put("items", items);
        return a;
    }

    static JVal buildKvListOutputSchema() {
        JVal schema = new JVal(JVal.OBJ);
        schema.objVal.put("type", JVal.str("object"));
