        keys: { type: "array", items: { type: "string" } },
        count: { type: "integer" }
      },
      required: ["keys", "count"]
    }
  },
  {
    name: "sum",
    title: "Sum integers",
    description: "Add up a non-empty list of integers.",
    inputSchema: {
      type: "object",
      properties: {
        numbers: { type: "array", items: { type: "integer" }, minItems: 1 }
      },
      required: ["numbers"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" }
      },
      required: ["sum", "count"]
    },
    annotations: { readOnlyHint: true, idempotentHint: true }
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
