static const uint64_t sha512_H0[8]={
0x6a09e667f3bcc908ULL,0xbb67ae8584caa73bULL,0x3c6ef372fe94f82bULL,0xa54ff53a5f1d36f1ULL,
0x510e527fade682d1ULL,0x9b05688c2b3e6c1fULL,0x1f83d9abfb41bd6bULL,0x5be0cd19137e2179ULL
};
static const uint64_t sha384_H0[8]={
0xcbbb9d5dc1059ed8ULL,0x629a292a367cd507ULL,0x9159015a3070dd17ULL,0x152fecd8f70e5939ULL,
0x67332667ffc00b31ULL,0x8eb44a8768581511ULL,0xdb0c2e0d64f98fa7ULL,0x47b5481dbefa4fa4ULL
};
#define ROTR64(x,n) (((x)>>(n))|((x)<<(64-(n))))
static void sha512_compress(uint64_t st[8],const uint8_t blk[128]){
    uint64_t W[80];
    for(int i=0;i<16;i++){
        W[i]=0;for(int j=0;j<8;j++) W[i]=(W[i]<<8)|blk[i*8+j];
    }
    for(int i=16;i<80;i++){
        uint64_t s0=ROTR64(W[i-15],1)^ROTR64(W[i-15],8)^(W[i-15]>>7);
        uint64_t s1=ROTR64(W[i-2],19)^ROTR64(W[i-2],61)^(W[i-2]>>6);
        W[i]=W[i-16]+s0+W[i-7]+s1;
    }
    uint64_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for(int i=0;i<80;i++){
        uint64_t S1=ROTR64(e,14)^ROTR64(e,18)^ROTR64(e,41);
        uint64_t ch=(e&f)^((~e)&g);
        uint64_t t1=h+S1+ch+sha512_K[i]+W[i];
        uint64_t S0=ROTR64(a,28)^ROTR64(a,34)^ROTR64(a,39);
        uint64_t maj=(a&b)^(a&c)^(b&c);
        uint64_t t2=S0+maj;
        h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
    }
    st[0]+=a;st[1]+=b;st[2]+=c;st[3]+=d;st[4]+=e;st[5]+=f;st[6]+=g;st[7]+=h;
}
static void sha512_generic(const uint8_t*msg,size_t len,uint8_t*out,int outbytes,const uint64_t*H0){
    uint64_t st[8];memcpy(st,H0,64);
    size_t i=0;
    while(len-i>=128){sha512_compress(st,msg+i);i+=128;}
    uint8_t buf[256];memset(buf,0,256);
    size_t rem=len-i;
    memcpy(buf,msg+i,rem);
    buf[rem]=0x80;
    size_t padlen=(rem<112)?128:256;
    uint64_t bits=(uint64_t)len*8;
    buf[padlen-1]=(uint8_t)bits;buf[padlen-2]=(uint8_t)(bits>>8);
    buf[padlen-3]=(uint8_t)(bits>>16);buf[padlen-4]=(uint8_t)(bits>>24);
    buf[padlen-5]=(uint8_t)(bits>>32);buf[padlen-6]=(uint8_t)(bits>>40);
    buf[padlen-7]=(uint8_t)(bits>>48);buf[padlen-8]=(uint8_t)(bits>>56);
    sha512_compress(st,buf);
    if(padlen==256) sha512_compress(st,buf+128);
    for(int j=0;j<8;j++){
        for(int k=0;k<8;k++){
            int idx=j*8+k;
            if(idx<outbytes) out[idx]=(uint8_t)(st[j]>>(56-k*8));
        }
    }
}
static void sha512(const uint8_t*msg,size_t len,uint8_t out[64]){sha512_generic(msg,len,out,64,sha512_H0);}
static void sha384(const uint8_t*msg,size_t len,uint8_t out[48]){sha512_generic(msg,len,out,48,sha384_H0);}

/* ==================== HMAC ==================== */
static void hmac_sha256(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[32]){
    uint8_t k[64];memset(k,0,64);
    if(klen>64){sha256(key,klen,k);klen=32;}
    memcpy(k,key,klen);
    uint8_t ipad[64],opad[64];
    for(int i=0;i<64;i++){ipad[i]=k[i]^0x36;opad[i]=k[i]^0x5c;}
    uint8_t tmp[64+4096]; /* not ideal but works for reasonable sizes */
    /* Use dynamic approach */
    uint8_t *buf=malloc(64+mlen);
    memcpy(buf,ipad,64);memcpy(buf+64,msg,mlen);
    uint8_t inner[32];sha256(buf,64+mlen,inner);free(buf);
    buf=malloc(64+32);
    memcpy(buf,opad,64);memcpy(buf+64,inner,32);
    sha256(buf,96,out);free(buf);
    (void)tmp;
}
static void hmac_sha512_generic(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t*out,int outbytes,const uint64_t*H0){
    uint8_t k[128];memset(k,0,128);
    if(klen>128){uint8_t h[64];sha512_generic(key,klen,h,64,sha512_H0);memcpy(k,h,64);klen=64;}
    memcpy(k,key,klen);
    uint8_t ipad[128],opad[128];
    for(int i=0;i<128;i++){ipad[i]=k[i]^0x36;opad[i]=k[i]^0x5c;}
    uint8_t *buf=malloc(128+mlen);
    memcpy(buf,ipad,128);memcpy(buf+128,msg,mlen);
    uint8_t inner[64];sha512_generic(buf,128+mlen,inner,64,sha512_H0);free(buf);
    buf=malloc(128+64);
    memcpy(buf,opad,128);memcpy(buf+128,inner,64);
    sha512_generic(buf,192,out,outbytes,H0);free(buf);
}
static void hmac_sha384(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[48]){
    hmac_sha512_generic(key,klen,msg,mlen,out,48,sha384_H0);
}
static void hmac_sha512(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[64]){
    hmac_sha512_generic(key,klen,msg,mlen,out,64,sha512_H0);
}

/* ==================== Base64url ==================== */
static int b64url_valid(const char*s,size_t len){
    if(len%4==1) return 0;
    for(size_t i=0;i<len;i++){
        char c=s[i];
        if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_')) return 0;
    }
    return 1;
}
static int b64val(char c){
    if(c>='A'&&c<='Z') return c-'A';
    if(c>='a'&&c<='z') return c-'a'+26;
    if(c>='0'&&c<='9') return c-'0'+52;
    if(c=='-') return 62;
    if(c=='_') return 63;
    return -1;
}
static uint8_t*b64url_decode(const char*s,size_t len,size_t*outlen){
    size_t n=(len/4)*3+(len%4==2?1:(len%4==3?2:0));
    uint8_t*out=malloc(n+1);
    size_t j=0;
    for(size_t i=0;i+4<=len;i+=4){
        int a=b64val(s[i]),b=b64val(s[i+1]),c=b64val(s[i+2]),d=b64val(s[i+3]);
        out[j++]=(a<<2)|(b>>4);
        out[j++]=((b&0xF)<<4)|(c>>2);
        out[j++]=((c&0x3)<<6)|d;
    }
    size_t rem=len%4;
    if(rem==2){
        int a=b64val(s[len-2]),b=b64val(s[len-1]);
        out[j++]=(a<<2)|(b>>4);
    }else if(rem==3){
        int a=b64val(s[len-3]),b=b64val(s[len-2]),c=b64val(s[len-1]);
        out[j++]=(a<<2)|(b>>4);
        out[j++]=((b&0xF)<<4)|(c>>2);
    }
    *outlen=j;
    return out;
}

/* ==================== JSON Parser ==================== */
typedef enum{JNULL,JBOOL,JNUM,JSTR,JARR,JOBJ}jtype;
typedef struct jval{
    jtype type;
    int bval;
    double nval;
    char*sval;
    struct{struct jval**items;size_t count;}arr;
    struct{char**keys;struct jval**vals;size_t count;}obj;
}jval;

typedef struct{const char*p;const char*end;}jctx;

static void jskip(jctx*c){while(c->p<c->end&&(*c->p==' '||*c->p=='\t'||*c->p=='\n'||*c->p=='\r'))c->p++;}
static jval*jparse(jctx*c);

static char*jparse_str_raw(jctx*c){
    if(*c->p!='"')return NULL;
    c->p++;
    size_t cap=64,len=0;
    char*buf=malloc(cap);
    while(c->p<c->end&&*c->p!='"'){
        if(len+1>=cap){cap*=2;buf=realloc(buf,cap);}
        if(*c->p=='\\'){
            c->p++;
            if(c->p>=c->end)break;
            switch(*c->p){
                case '"':buf[len++]='"';c->p++;break;
                case '\\':buf[len++]='\\';c->p++;break;
                case '/':buf[len++]='/';c->p++;break;
                case 'b':buf[len++]='\b';c->p++;break;
                case 'f':buf[len++]='\f';c->p++;break;
                case 'n':buf[len++]='\n';c->p++;break;
                case 'r':buf[len++]='\r';c->p++;break;
                case 't':buf[len++]='\t';c->p++;break;
                case 'u':{
                    c->p++;
                    if(c->p+4>c->end){buf[len++]='u';break;}
                    unsigned cp=0;
                    for(int i=0;i<4;i++){
                        char ch=c->p[i];int v;
                        if(ch>='0'&&ch<='9')v=ch-'0';
                        else if(ch>='a'&&ch<='f')v=ch-'a'+10;
                        else if(ch>='A'&&ch<='F')v=ch-'A'+10;
                        else{v=0;}
                        cp=(cp<<4)|v;
                    }
                    c->p+=4;
                    /* surrogate pair */
                    if(cp>=0xD800&&cp<=0xDBFF&&c->p+6<=c->end&&c->p[0]=='\\'&&c->p[1]=='u'){
                        unsigned lo=0;
                        for(int i=2;i<6;i++){
                            char ch=c->p[i];int v;
                            if(ch>='0'&&ch<='9')v=ch-'0';
                            else if(ch>='a'&&ch<='f')v=ch-'a'+10;
                            else if(ch>='A'&&ch<='F')v=ch-'A'+10;
                            else{v=0;}
                            lo=(lo<<4)|v;
                        }
                        if(lo>=0xDC00&&lo<=0xDFFF){
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            c->p+=6;
                        }
                    }
                    /* encode UTF-8 */
                    if(cp<0x80){buf[len++]=cp;}
                    else if(cp<0x800){buf[len++]=0xC0|(cp>>6);buf[len++]=0x80|(cp&0x3F);}
                    else if(cp<0x10000){buf[len++]=0xE0|(cp>>12);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    else{buf[len++]=0xF0|(cp>>18);buf[len++]=0x80|((cp>>12)&0x3F);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    break;
                }
                default:buf[len++]=*c->p;c->p++;break;
            }
        }else{
            buf[len++]=*c->p;c->p++;
        }
    }
    if(c->p<c->end&&*c->p=='"')c->p++;
    buf[len]=0;
    return buf;
}

static jval*jparse(jctx*c){
    jskip(c);
    if(c->p>=c->end)return NULL;
    jval*v=calloc(1,sizeof(jval));
    if(*c->p=='{'){
        c->p++;v->type=JOBJ;
        size_t cap=8;v->obj.keys=malloc(cap*sizeof(char*));v->obj.vals=malloc(cap*sizeof(jval*));
        jskip(c);
        if(c->p<c->end&&*c->p=='}'){c->p++;return v;}
        while(1){
            jskip(c);
            char*key=jparse_str_raw(c);
            jskip(c);
            if(c->p<c->end&&*c->p==':')c->p++;
            jval*val=jparse(c);
            if(v->obj.count>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(jval*));}
            v->obj.keys[v->obj.count]=key;
            v->obj.vals[v->obj.count]=val;
            v->obj.count++;
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p=='}'){c->p++;break;}
            break;
        }
        return v;
    }else if(*c->p=='['){
        c->p++;v->type=JARR;
        size_t cap=8;v->arr.items=malloc(cap*sizeof(jval*));
        jskip(c);
        if(c->p<c->end&&*c->p==']'){c->p++;return v;}
        while(1){
            jval*val=jparse(c);
            if(v->arr.count>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(jval*));}
            v->arr.items[v->arr.count++]=val;
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p==']'){c->p++;break;}
            break;
        }
        return v;
    }else if(*c->p=='"'){
        v->type=JSTR;v->sval=jparse_str_raw(c);return v;
    }else if(*c->p=='t'){
        if(c->end-c->p>=4&&memcmp(c->p,"true",4)==0){c->p+=4;v->type=JBOOL;v->bval=1;}
        else{v->type=JNULL;}
        return v;
    }else if(*c->p=='f'){
        if(c->end-c->p>=5&&memcmp(c->p,"false",5)==0){c->p+=5;v->type=JBOOL;v->bval=0;}
        else{v->type=JNULL;}
        return v;
    }else if(*c->p=='n'){
        if(c->end-c->p>=4&&memcmp(c->p,"null",4)==0){c->p+=4;}
        v->type=JNULL;return v;
    }else{
        /* number */
        char*endp;
        v->type=JNUM;
        v->nval=strtod(c->p,&endp);
        c->p=endp;
        return v;
    }
}

static jval*jobj_get(jval*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return NULL;
    for(size_t i=0;i<obj->obj.count;i++){
        if(obj->obj.keys[i]&&strcmp(obj->obj.keys[i],key)==0) return obj->obj.vals[i];
    }
    return NULL;
}
static int jobj_has(jval*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return 0;
    for(size_t i=0;i<obj->obj.count;i++){
        if(obj->obj.keys[i]&&strcmp(obj->obj.keys[i],key)==0) return 1;
    }
    return 0;
}

/* ==================== Main ==================== */
int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    char*dir=argv[1];
    /* Read config.json */
    char cpath[4096];snprintf(cpath,sizeof(cpath),"%s/config.json",dir);
    FILE*f=fopen(cpath,"rb");
    if(!f){perror("config");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*cbuf=malloc(fsz+1);fread(cbuf,1,fsz,f);cbuf[fsz]=0;fclose(f);
    jctx jc={cbuf,cbuf+fsz};
    jval*cfg=jparse(&jc);

    double now=jobj_get(cfg,"now")->nval;
    double leeway=jobj_get(cfg,"leeway")->nval;
    char*issuer=jobj_get(cfg,"issuer")?jobj_get(cfg,"issuer")->sval:NULL;
    char*audience=jobj_get(cfg,"audience")?jobj_get(cfg,"audience")->sval:NULL;
    jval*keys_arr=jobj_get(cfg,"keys");

    /* Read tokens.txt */
    char tpath[4096];snprintf(tpath,sizeof(tpath),"%s/tokens.txt",dir);
    f=fopen(tpath,"rb");
    if(!f){perror("tokens");return 1;}
    fseek(f,0,SEEK_END);fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*tbuf=malloc(fsz+1);fread(tbuf,1,fsz,f);tbuf[fsz]=0;fclose(f);

    /* Split into lines */
    char**lines=NULL;int nlines=0;
    {
        char*p=tbuf;
        while(*p){
            char*nl=strchr(p,'\n');
            char*line;
            if(nl){*nl=0;line=p;p=nl+1;}
            else{line=p;p=p+strlen(p);}
            /* trim spaces and tabs */
            while(*line==' '||*line=='\t')line++;
            char*end=line+strlen(line)-1;
            while(end>=line&&(*end==' '||*end=='\t')){*end=0;end--;}
            if(*line){
                nlines++;lines=realloc(lines,nlines*sizeof(char*));
                lines[nlines-1]=line;
            }
        }
    }

    int valid_count=0,invalid_count=0;

    for(int li=0;li<nlines;li++){
        char*tok=lines[li];
        const char*result=NULL;
        char sub_out[4096]={0};
        char scope_out[4096]={0};

        /* Rule 1: MALFORMED */
        /* Split on '.' */
        char*dot1=strchr(tok,'.');
        char*dot2=dot1?strchr(dot1+1,'.'):NULL;
        char*dot3=dot2?strchr(dot2+1,'.'):NULL;
        if(!dot1||!dot2||dot3){result="MALFORMED";goto emit;}
        size_t hlen=dot1-tok;
        size_t plen=dot2-dot1-1;
        size_t slen=tok+strlen(tok)-dot2-1;
        char*hseg=malloc(hlen+1);memcpy(hseg,tok,hlen);hseg[hlen]=0;
        char*pseg=malloc(plen+1);memcpy(pseg,dot1+1,plen);pseg[plen]=0;
        char*sseg=malloc(slen+1);memcpy(sseg,dot2+1,slen);sseg[slen]=0;

        if(hlen==0||plen==0||slen==0){result="MALFORMED";goto emit;}
        if(!b64url_valid(hseg,hlen)||!b64url_valid(pseg,plen)||!b64url_valid(sseg,slen)){result="MALFORMED";goto emit;}

        size_t hdec_len,pdec_len,sdec_len;
        uint8_t*hdec=b64url_decode(hseg,hlen,&hdec_len);
        uint8_t*pdec=b64url_decode(pseg,plen,&pdec_len);
        uint8_t*sdec=b64url_decode(sseg,slen,&sdec_len);

        /* Parse header and payload as JSON */
        jctx hc={(char*)hdec,(char*)hdec+hdec_len};
        jval*header=jparse(&hc);
        jctx pc={(char*)pdec,(char*)pdec+pdec_len};
        jval*payload=jparse(&pc);

        if(!header||header->type!=JOBJ||!payload||payload->type!=JOBJ){result="MALFORMED";goto emit;}

        /* Rule 2: UNSUPPORTED_ALG */
        jval*alg_v=jobj_get(header,"alg");
        if(!alg_v||alg_v->type!=JSTR||!alg_v->sval){result="UNSUPPORTED_ALG";goto emit;}
        char*alg=alg_v->sval;
        int alg_id=0; /* 0=HS256,1=HS384,2=HS512 */
        if(strcmp(alg,"HS256")==0)alg_id=0;
        else if(strcmp(alg,"HS384")==0)alg_id=1;
        else if(strcmp(alg,"HS512")==0)alg_id=2;
        else{result="UNSUPPORTED_ALG";goto emit;}

        /* Rule 3: UNKNOWN_KEY */
        jval*kid_v=jobj_get(header,"kid");
        if(!kid_v||kid_v->type!=JSTR||!kid_v->sval){result="UNKNOWN_KEY";goto emit;}
        char*kid=kid_v->sval;
        jval*key_obj=NULL;
        if(keys_arr&&keys_arr->type==JARR){
            for(size_t ki=0;ki<keys_arr->arr.count;ki++){
                jval*ko=keys_arr->arr.items[ki];
                jval*kkid=jobj_get(ko,"kid");
                if(kkid&&kkid->type==JSTR&&kkid->sval&&strcmp(kkid->sval,kid)==0){key_obj=ko;break;}
            }
        }
        if(!key_obj){result="UNKNOWN_KEY";goto emit;}

        /* Rule 4: ALG_MISMATCH */
        jval*key_alg_v=jobj_get(key_obj,"alg");
        if(!key_alg_v||key_alg_v->type!=JSTR||!key_alg_v->sval||strcmp(key_alg_v->sval,alg)!=0){result="ALG_MISMATCH";goto emit;}

        /* Rule 5: BAD_SIGNATURE */
        jval*key_k_v=jobj_get(key_obj,"k");
        if(!key_k_v||key_k_v->type!=JSTR||!key_k_v->sval){result="BAD_SIGNATURE";goto emit;}
        size_t secret_len;
        uint8_t*secret=b64url_decode(key_k_v->sval,strlen(key_k_v->sval),&secret_len);
        /* signing input: hseg + "." + pseg */
        size_t si_len=hlen+1+plen;
        char*si=malloc(si_len+1);
        memcpy(si,hseg,hlen);si[hlen]='.';memcpy(si+hlen+1,pseg,plen);si[si_len]=0;
        uint8_t hmac_out[64];
        if(alg_id==0) hmac_sha256(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        else if(alg_id==1) hmac_sha384(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        else hmac_sha512(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        size_t expected_len=(alg_id==0)?32:(alg_id==1)?48:64;
        if(sdec_len!=expected_len||memcmp(sdec,hmac_out,expected_len)!=0){result="BAD_SIGNATURE";goto emit;}

        /* Rule 6: EXPIRED */
        if(jobj_has(payload,"exp")){
            jval*exp_v=jobj_get(payload,"exp");
            if(exp_v&&exp_v->type==JNUM){
                if(now>=exp_v->nval+leeway){result="EXPIRED";goto emit;}
            }
        }

        /* Rule 7: NOT_YET_VALID */
        if(jobj_has(payload,"nbf")){
            jval*nbf_v=jobj_get(payload,"nbf");
            if(nbf_v&&nbf_v->type==JNUM){
                if(now+leeway<nbf_v->nval){result="NOT_YET_VALID";goto emit;}
            }
        }

        /* Rule 8: BAD_ISSUER */
        {
            jval*iss_v=jobj_get(payload,"iss");
            if(!iss_v||iss_v->type!=JSTR||!iss_v->sval||!issuer||strcmp(iss_v->sval,issuer)!=0){result="BAD_ISSUER";goto emit;}
        }

        /* Rule 9: BAD_AUDIENCE */
        {
            jval*aud_v=jobj_get(payload,"aud");
            if(!aud_v){result="BAD_AUDIENCE";goto emit;}
            if(aud_v->type==JSTR){
                if(!audience||!aud_v->sval||strcmp(aud_v->sval,audience)!=0){result="BAD_AUDIENCE";goto emit;}
            }else if(aud_v->type==JARR){
                int found=0;
                for(size_t ai=0;ai<aud_v->arr.count;ai++){
                    jval*el=aud_v->arr.items[ai];
                    if(el&&el->type==JSTR&&el->sval&&audience&&strcmp(el->sval,audience)==0){found=1;break;}
                }
                if(!found){result="BAD_AUDIENCE";goto emit;}
            }else{result="BAD_AUDIENCE";goto emit;}
        }

        /* VALID */
        {
            jval*sub_v=jobj_get(payload,"sub");
            if(sub_v&&sub_v->type==JSTR&&sub_v->sval){
                strncpy(sub_out,sub_v->sval,sizeof(sub_out)-1);
            }
            jval*scope_v=jobj_get(payload,"scope");
            if(scope_v&&scope_v->type==JSTR&&scope_v->sval&&scope_v->sval[0]){
                /* split on spaces */
                char**scopes=NULL;int nsc=0;
                char*sp=strdup(scope_v->sval);
                char*saveptr=sp;
                char*tok2=strtok(sp," ");
                while(tok2){
                    scopes=realloc(scopes,(nsc+1)*sizeof(char*));
                    scopes[nsc++]=tok2;
                    tok2=strtok(NULL," ");
                }
                /* sort */
                for(int a=0;a<nsc;a++)for(int b=a+1;b<nsc;b++){
                    if(strcmp(scopes[a],scopes[b])>0){char*t=scopes[a];scopes[a]=scopes[b];scopes[b]=t;}
                }
                /* dedup and join */
                int first=1;
                for(int a=0;a<nsc;a++){
                    if(a>0&&strcmp(scopes[a],scopes[a-1])==0)continue;
                    if(!first)strcat(scope_out,",");
                    strcat(scope_out,scopes[a]);
                    first=0;
                }
                free(sp);free(scopes);
            }
            valid_count++;
        }
        emit:
        printf("%d: ",li+1);
        if(result) printf("%s\n",result);
        else printf("VALID sub=%s scope=%s\n",sub_out,scope_out);
    }

    printf("\nvalid=%d invalid=%d\n",valid_count,invalid_count);
    return 0;
}

