static const char *tool_names[]={"kv_set","kv_get","kv_list","sum","text_stats"};
static const char *tool_props_set[]={"key","value"};
static const char *tool_props_get[]={"key"};
static const char *tool_props_list[]={"prefix"};
static const char *tool_props_sum[]={"numbers"};
static const char *tool_props_text[]={"text"};

static const char **get_tool_props(const char *name, int *np){
    if(!strcmp(name,"kv_set")){ *np=2; return tool_props_set; }
    if(!strcmp(name,"kv_get")){ *np=1; return tool_props_get; }
    if(!strcmp(name,"kv_list")){ *np=1; return tool_props_list; }
    if(!strcmp(name,"sum")){ *np=1; return tool_props_sum; }
    if(!strcmp(name,"text_stats")){ *np=1; return tool_props_text; }
    *np=0; return NULL;
}
static bool is_required(const char *tool, const char *prop){
    if(!strcmp(tool,"kv_set")) return !strcmp(prop,"key")||!strcmp(prop,"value");
    if(!strcmp(tool,"kv_get")) return !strcmp(prop,"key");
    if(!strcmp(tool,"kv_list")) return false;
    if(!strcmp(tool,"sum")) return !strcmp(prop,"numbers");
    if(!strcmp(tool,"text_stats")) return !strcmp(prop,"text");
    return false;
}
static bool has_minLength(const char *tool, const char *prop){
    if(!strcmp(tool,"kv_set")&&(!strcmp(prop,"key"))) return true;
    if(!strcmp(tool,"kv_get")&&(!strcmp(prop,"key"))) return true;
    return false;
}
static bool has_minItems(const char *tool, const char *prop){
    if(!strcmp(tool,"sum")&&(!strcmp(prop,"numbers"))) return true;
    return false;
}
static bool is_array_int(const char *tool, const char *prop){
    if(!strcmp(tool,"sum")&&(!strcmp(prop,"numbers"))) return true;
    return false;
}

