/* ==================== Validation & Execution ==================== */
static bool is_valid_id(jval *v){
    if(!v) return false;
    return v->t==JV_STR || v->t==JV_INT;
}
static bool is_int_val(jval *v){
    return v && v->t==JV_INT;
}

/* Build failure tool result */
static void build_fail(sb_t *out, const char *msg){
    sb_puts(out,"{\"content\":[");
    sb_puts(out,"{\"type\":\"text\",\"text\":");
    ser_string(out,msg);
    sb_puts(out,"}],\"isError\":true}");
}
/* Build success tool result (no outputSchema) */
static void build_ok_text(sb_t *out, const char *text){
    sb_puts(out,"{\"content\":[");
    sb_puts(out,"{\"type\":\"text\",\"text\":");
    ser_string(out,text);
    sb_puts(out,"}],\"isError\":false}");
}
/* Build success tool result (with outputSchema) */
static void build_ok_struct(sb_t *out, jval *structured){
    sb_puts(out,"{\"content\":[{\"type\":\"text\",\"text\":");
    sb_t inner; sb_init(&inner);
    ser_value(&inner,structured);
    sb_putc(&inner,0);
    ser_string(out,inner.b);
    free(inner.b);
    sb_puts(out,"}],\"structuredContent\":");
    ser_value(out,structured);
    sb_puts(out,",\"isError\":false}");
}

static void validate_and_run(sb_t *out, const char *tool_name, jval *args){
    int np;
    const char **props = get_tool_props(tool_name, &np);

    /* Check unknown arguments */
    if(args && args->t==JV_OBJ){
        const char *smallest = NULL;
        for(size_t i=0;i<args->o.n;i++){
            bool known=false;
            for(int j=0;j<np;j++){
                if(strcmp(args->o.k[i],props[j])==0){ known=true; break; }
            }
            if(!known){
                if(!smallest || strcmp(args->o.k[i],smallest)<0) smallest=args->o.k[i];
            }
        }
        if(smallest){
            char buf[512]; snprintf(buf,sizeof(buf),"unknown argument: %s",smallest);
            build_fail(out,buf); return;
        }
    }

    /* Check each property in schema order */
    for(int j=0;j<np;j++){
        const char *pn=props[j];
        jval *pv = args ? obj_get(args,pn) : NULL;
        bool present = args && obj_has(args,pn);

        if(!present){
            if(is_required(tool_name,pn)){
                char buf[512]; snprintf(buf,sizeof(buf),"missing required argument: %s",pn);
                build_fail(out,buf); return;
            }
            continue;
        }

        /* Type check */
        if(is_array_int(tool_name,pn)){
            if(!pv || pv->t!=JV_ARR){
                char buf[512]; snprintf(buf,sizeof(buf),"argument %s must be an array of integers",pn);
                build_fail(out,buf); return;
            }
            for(size_t k=0;k<pv->a.n;k++){
                if(!is_int_val(pv->a.v[k])){
                    char buf[512]; snprintf(buf,sizeof(buf),"argument %s must be an array of integers",pn);
                    build_fail(out,buf); return;
                }
            }
            if(has_minItems(tool_name,pn) && pv->a.n==0){
                char buf[512]; snprintf(buf,sizeof(buf),"argument %s must not be empty",pn);
                build_fail(out,buf); return;
            }
        } else {
            /* string type */
            if(!pv || pv->t!=JV_STR){
                char buf[512]; snprintf(buf,sizeof(buf),"argument %s must be a string",pn);
                build_fail(out,buf); return;
            }
            if(has_minLength(tool_name,pn) && pv->s[0]=='\0'){
                char buf[512]; snprintf(buf,sizeof(buf),"argument %s must not be empty",pn);
                build_fail(out,buf); return;
            }
        }
    }

    /* Execute tool */
    if(!strcmp(tool_name,"kv_set")){
        jval *kv=obj_get(args,"key"), *vv=obj_get(args,"value");
        bool existed = kv_exists(kv->s);
        kv_set(kv->s, vv->s);
        char buf[1024]; snprintf(buf,sizeof(buf),"%s %s",existed?"updated":"created",kv->s);
        build_ok_text(out,buf);
    } else if(!strcmp(tool_name,"kv_get")){
        jval *kv=obj_get(args,"key");
        char *val=NULL;
        if(!kv_find(kv->s,&val)){
            char buf[1024]; snprintf(buf,sizeof(buf),"key not found: %s",kv->s);
            build_fail(out,buf); return;
        }
        build_ok_text(out,val);
    } else if(!strcmp(tool_name,"kv_list")){
        const char *prefix = "";
        jval *pv = args ? obj_get(args,"prefix") : NULL;
        if(pv && pv->t==JV_STR) prefix=pv->s;
        size_t plen=strlen(prefix);
        const char **keys=NULL; size_t kn=0,kcap=0;
        for(size_t i=0;i<kv_count;i++){
            if(strncmp(kv_store[i].key,prefix,plen)==0){
                if(kn==kcap){ kcap=kcap?kcap*2:16; keys=realloc(keys,kcap*sizeof(char*)); }
                keys[kn++]=kv_store[i].key;
            }
        }
        /* Sort by strcmp (code point order for UTF-8) */
        for(size_t i=1;i<kn;i++){
            const char *tmp=keys[i];
            size_t j=i;
            while(j>0&&strcmp(keys[j-1],tmp)>0){ keys[j]=keys[j-1]; j--; }
            keys[j]=tmp;
        }
        jval *s=jv_obj();
        jval *ka=jv_arr();
        for(size_t i=0;i<kn;i++) jval_arr_push(ka,jv_str(keys[i]));
        jval_obj_put(s,"keys",ka);
        jval_obj_put(s,"count",jv_int((long long)kn));
        build_ok_struct(out,s);
        jval_free(s); free(keys);
    } else if(!strcmp(tool_name,"sum")){
        jval *na=obj_get(args,"numbers");
        long long total=0;
        for(size_t i=0;i<na->a.n;i++) total+=na->a.v[i]->i;
        jval *s=jv_obj();
        jval_obj_put(s,"sum",jv_int(total));
        jval_obj_put(s,"count",jv_int((long long)na->a.n));
        build_ok_struct(out,s);
        jval_free(s);
    } else if(!strcmp(tool_name,"text_stats")){
        jval *tv=obj_get(args,"text");
        const char *text=tv->s;
        size_t tlen=strlen(text);
        /* words */
        long long words=0;
        bool in_word=false;
        for(size_t i=0;i<tlen;i++){
            char c=text[i];
            if(c==' '||c=='\t'||c=='\n'||c=='\r'){
                in_word=false;
            } else {
                if(!in_word){ words++; in_word=true; }
            }
        }
        /* codepoints */
        long long cps=0;
        for(size_t i=0;i<tlen;){
            unsigned char c=(unsigned char)text[i];
            if(c<0x80) i+=1;
            else if(c<0xE0) i+=2;
            else if(c<0xF0) i+=3;
            else i+=4;
            cps++;
        }
        jval *s=jv_obj();
        jval_obj_put(s,"words",jv_int(words));
        jval_obj_put(s,"codepoints",jv_int(cps));
        jval_obj_put(s,"utf8_bytes",jv_int((long long)tlen));
        build_ok_struct(out,s);
        jval_free(s);
    }
}

/* ==================== MCP Server State ==================== */
static bool server_initialized=false;

/* ==================== Message Processing ==================== */
static void emit_error(sb_t *out, jval *id, int code, const char *msg){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"error\":{\"code\":");
    sb_printf(out,"%d",code);
    sb_puts(out,",\"message\":");
    ser_string(out,msg);
    sb_puts(out,"}}");
}
static void emit_result(sb_t *out, jval *id, const char *result_json){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"result\":");
    sb_puts(out,result_json);
    sb_puts(out,"}");
}
static void emit_result_jval(sb_t *out, jval *id, jval *result){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"result\":");
    ser_value(out,result);
    sb_puts(out,"}");
}

static void process_line(const char *line, size_t len, sb_t *out){
    /* Parse JSON */
    jval *msg = parse_json(line, len);
    if(!msg){
        emit_error(out, NULL, -32700, "Parse error");
        sb_putc(out,'\n');
        return;
    }
    /* Must be object */
    if(msg->t!=JV_OBJ){
        emit_error(out, NULL, -32600, "Invalid Request");
        jval_free(msg); sb_putc(out,'\n'); return;
    }
    /* Client response: no method, has result or error */
    jval *method = obj_get(msg,"method");
    jval *result_m = obj_get(msg,"result");
    jval *error_m  = obj_get(msg,"error");
    if(!method && (result_m||error_m)){
        jval_free(msg); return;
    }
    /* Check invalid request */
    jval *jsonrpc = obj_get(msg,"jsonrpc");
    jval *id = obj_get(msg,"id");
    bool invalid = false;
    if(!jsonrpc || jsonrpc->t!=JV_STR || strcmp(jsonrpc->s,"2.0")!=0) invalid=true;
    if(!method || method->t!=JV_STR) invalid=true;
    if(obj_has(msg,"id") && !is_valid_id(id)) invalid=true;

    if(invalid){
        jval *echo_id = (obj_has(msg,"id") && is_valid_id(id)) ? id : NULL;
        emit_error(out, echo_id, -32600, "Invalid Request");
        sb_putc(out,'\n');
        jval_free(msg); return;
    }

    /* Notification: no id member */
    if(!obj_has(msg,"id")){
        jval_free(msg); return;
    }

    /* It's a request. Echo id. */
    const char *mname = method->s;

    /* Check method */
    if(strcmp(mname,"initialize")!=0 && strcmp(mname,"ping")!=0 &&
       strcmp(mname,"tools/list")!=0 && strcmp(mname,"tools/call")!=0){
        emit_error(out, id, -32601, "Method not found");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Check params */
    jval *params = obj_get(msg,"params");
    if(params && params->t!=JV_OBJ){
        emit_error(out, id, -32602, "Invalid params");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Check initialized */
    if(!server_initialized && strcmp(mname,"initialize")!=0 && strcmp(mname,"ping")!=0){
        emit_error(out, id, -32002, "Server not initialized");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Dispatch */
    if(!strcmp(mname,"initialize")){
        if(server_initialized){
            emit_error(out, id, -32600, "Already initialized");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        if(!params){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *pv = obj_get(params,"protocolVersion");
        if(!pv || pv->t!=JV_STR){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        server_initialized=true;
        const char *ver = pv->s;
        const char *resp_ver = "2025-06-18";
        if(strcmp(ver,"2025-06-18")==0||strcmp(ver,"2025-03-26")==0||strcmp(ver,"2024-11-05")==0)
            resp_ver=ver;
        jval *res=jv_obj();
        jval_obj_put(res,"protocolVersion",jv_str(resp_ver));
        jval *caps=jv_obj();
        jval *tools_cap=jv_obj();
        jval_obj_put(tools_cap,"listChanged",jv_bool(0));
        jval_obj_put(caps,"tools",tools_cap);
        jval_obj_put(res,"capabilities",caps);
        jval *si=jv_obj();
        jval_obj_put(si,"name",jv_str("cb2-kv"));
        jval_obj_put(si,"title",jv_str("CB2 key-value server"));
        jval_obj_put(si,"version",jv_str("1.4.2"));
        jval_obj_put(res,"serverInfo",si);
        emit_result_jval(out,id,res);
        sb_putc(out,'\n');
        jval_free(res); jval_free(msg); return;
    }
    if(!strcmp(mname,"ping")){
        jval *res=jv_obj();
        emit_result_jval(out,id,res);
        sb_putc(out,'\n');
        jval_free(res); jval_free(msg); return;
    }
    if(!strcmp(mname,"tools/list")){
        emit_result(out,id,TOOLS_LIST_JSON);
        sb_putc(out,'\n');
        jval_free(msg); return;
    }
    if(!strcmp(mname,"tools/call")){
        if(!params){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *pname = obj_get(params,"name");
        if(!pname || pname->t!=JV_STR){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        const char *tn=pname->s;
        bool known=false;
        for(int i=0;i<5;i++) if(strcmp(tn,tool_names[i])==0){ known=true; break; }
        if(!known){
            char buf[512]; snprintf(buf,sizeof(buf),"Unknown tool: %s",tn);
            emit_error(out, id, -32602, buf);
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *arguments = obj_get(params,"arguments");
        /* Build the tool result */
        sb_t tool_res; sb_init(&tool_res);
        if(arguments && arguments->t!=JV_OBJ){
            build_fail(&tool_res,"arguments must be an object");
        } else {
            validate_and_run(&tool_res, tn, arguments);
        }
        sb_putc(&tool_res,0);
        emit_result(out, id, tool_res.b);
        sb_putc(out,'\n');
        free(tool_res.b);
        jval_free(msg); return;
    }

    jval_free(msg);
}

/* ==================== Main ==================== */
int main(void){
    char *line=NULL;
    size_t bufsz=0;
    ssize_t nread;
    while((nread=getline(&line,&bufsz,stdin))!=-1){
        /* Strip trailing \r and \n */
        while(nread>0 && (line[nread-1]=='\n'||line[nread-1]=='\r')) nread--;
        /* Check if empty or all whitespace (spaces, tabs, CR) */
        bool skip=true;
        for(ssize_t i=0;i<nread;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'){ skip=false; break; }
        }
        if(skip) continue;

        sb_t out; sb_init(&out);
        process_line(line, (size_t)nread, &out);
        if(out.len>0){
            fwrite(out.b,1,out.len,stdout);
        }
        sb_free(&out);
    }
    free(line);
    fflush(stdout);
    return 0;
}

import Foundation

// CRC-32 (zlib/PNG)
let crc32Table: [UInt32] = {
    var t = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 { c = (c & 1) != 0 ? (0xEDB88320 ^ (c >> 1)) : (c >> 1) }
        t[i] = c
    }
    return t
}()

func crc32(_ d: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in d { c = crc32Table[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8) }
    return c ^ 0xFFFFFFFF
}

func base64Decode(_ input: [UInt8]) -> [UInt8] {
    var bits: UInt32 = 0, bc = 0, out: [UInt8] = []
    for b in input {
        if b == 0x3D { break } // '='
        let v: UInt32
        switch b {
        case 0x41...0x5A: v = UInt32(b - 0x41)
        case 0x61...0x7A: v = UInt32(b - 0x61) + 26
        case 0x30...0x39: v = UInt32(b - 0x30) + 52
        case 0x2B: v = 62
        case 0x2F: v = 63
        default: continue
        }
        bits = (bits << 6) | v; bc += 6
        if bc >= 8 { bc -= 8; out.append(UInt8((bits >> bc) & 0xFF)) }
    }
    return out
}

func decodeQP(_ data: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    // Split into lines
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(data[i]); i += 1 }
    }
    lines.append(cur)
    // Strip trailing spaces/tabs from each line
    for j in 0..<lines.count {
        while let last = lines[j].last, last == 0x20 || last == 0x09 { lines[j].removeLast() }
    }
    // Join soft line breaks
    var result: [UInt8] = []
    var li = 0
    while li < lines.count {
        var cl = lines[li]; li += 1
        while cl.last == 0x3D && li < lines.count { // '='
            cl.removeLast()
            cl += lines[li]; li += 1
        }
        // Decode =XY in cl
        var di = 0
        while di < cl.count {
            if cl[di] == 0x3D && di + 2 < cl.count {
                let h1 = cl[di+1], h2 = cl[di+2]
                if let v1 = hexVal(h1), let v2 = hexVal(h2) {
                    result.append(UInt8(v1 * 16 + v2)); di += 3; continue
                }
            }
            result.append(cl[di]); di += 1
        }
        if li < lines.count { result += lineBreak }
    }
    return result
}

func hexVal(_ b: UInt8) -> Int? {
    switch b {
    case 0x30...0x39: return Int(b - 0x30)
    case 0x41...0x46: return Int(b - 0x41) + 10
    case 0x61...0x66: return Int(b - 0x61) + 10
    default: return nil
    }
}

let win1252: [UInt32] = {
    var t = [UInt32](repeating: 0, count: 32)
    let vals: [UInt32] = [0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
                          0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
                          0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
                          0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178]
    for i in 0..<32 { t[i] = vals[i] }
    return t
}()

func decodeCharset(_ data: [UInt8], _ cs: String) -> [UInt32] {
    let c = cs.lowercased()
    if c == "utf-8" || c == "us-ascii" {
        // Decode UTF-8
        var out: [UInt32] = []
        var i = 0
        while i < data.count {
            let b = data[i]
            if b < 0x80 { out.append(UInt32(b)); i += 1 }
            else if b < 0xC0 { out.append(UInt32(b)); i += 1 } // shouldn't happen per spec
            else if b < 0xE0 {
                let cp = (UInt32(b & 0x1F) << 6) | UInt32(data[i+1] & 0x3F); out.append(cp); i += 2
            } else if b < 0xF0 {
                let cp = (UInt32(b & 0x0F) << 12) | (UInt32(data[i+1] & 0x3F) << 6) | UInt32(data[i+2] & 0x3F); out.append(cp); i += 3
            } else {
                let cp = (UInt32(b & 0x07) << 18) | (UInt32(data[i+1] & 0x3F) << 12) | (UInt32(data[i+2] & 0x3F) << 6) | UInt32(data[i+3] & 0x3F); out.append(cp); i += 4
            }
        }
        return out
    } else if c == "iso-8859-1" {
        return data.map { UInt32($0) }
    } else if c == "windows-1252" {
        return data.map { b -> UInt32 in
            if b >= 0x80 && b <= 0x9F { return win1252[Int(b - 0x80)] }
            return UInt32(b)
        }
    }
    return data.map { UInt32($0) }
}

func replaceCRLF(_ cps: [UInt32]) -> [UInt32] {
    var out: [UInt32] = []
    var i = 0
    while i < cps.count {
        if cps[i] == 0x0D {
            if i + 1 < cps.count && cps[i+1] == 0x0A { out.append(0x0A); i += 2 }
            else { out.append(0x0A); i += 1 }
        } else { out.append(cps[i]); i += 1 }
    }
    return out
}

// Encoded-word decoding
func decodeEncodedWords(_ text: [UInt32]) -> [UInt32] {
    // Work on character array
    let chars = text.map { Character(UnicodeScalar($0)!) }
    var words: [(start: Int, end: Int, charset: String, encoding: Character, encText: [UInt8])] = []
    var i = 0
    while i < chars.count {
        if i + 1 < chars.count && chars[i] == "=" && chars[i+1] == "?" {
            // Try to match =?charset?encoding?encoded-text?=
            if let match = tryEncodedWord(chars, i) {
                words.append(match)
                i = match.end
                continue
            }
        }
        i += 1
    }
    if words.isEmpty { return text }
    // Group adjacent words with same charset
    struct Group { var wordIndices: [Int]; var start: Int; var end: Int }
    var groups: [Group] = []
    var wi = 0
    while wi < words.count {
        var g = Group(wordIndices: [wi], start: words[wi].start, end: words[wi].end)
        wi += 1
        while wi < words.count {
            let prev = words[wi-1], curr = words[wi]
            // Check adjacency: only spaces/tabs between prev.end and curr.start
            let between = chars[prev.end..<curr.start]
            if between.allSatisfy({ $0 == " " || $0 == "\t" }) &&
               stripLang(prev.charset).lowercased() == stripLang(curr.charset).lowercased() {
                g.wordIndices.append(wi)
                g.end = curr.end
                wi += 1
            } else { break }
        }
        groups.append(g)
    }
    // Build output
    var out: [UInt32] = []
    var ci = 0
    for g in groups {
        // Add text before group
        while ci < g.start { out.append(UInt32(chars[ci].asciiValue ?? 0x3F)); ci += 1 }
        // Decode group
        var allBytes: [UInt8] = []
        for wi2 in g.wordIndices {
            let w = words[wi2]
            if w.encoding == "B" || w.encoding == "b" {
                allBytes += base64Decode(w.encText)
            } else {
                var j = 0
                while j < w.encText.count {
                    if w.encText[j] == 0x5F { allBytes.append(0x20); j += 1 }
                    else if w.encText[j] == 0x3D && j + 2 < w.encText.count,
                            let v1 = hexVal(w.encText[j+1]), let v2 = hexVal(w.encText[j+2]) {
                        allBytes.append(UInt8(v1*16+v2)); j += 3
                    } else { allBytes.append(w.encText[j]); j += 1 }
                }
            }
        }
        let cs = stripLang(words[g.wordIndices[0]].charset)
        out += decodeCharset(allBytes, cs)
        ci = g.end
    }
    while ci < chars.count { out.append(UInt32(chars[ci].asciiValue ?? 0x3F)); ci += 1 }
    return out
}

func stripLang(_ cs: String) -> String {
    if let idx = cs.firstIndex(of: "*") { return String(cs[cs.startIndex..<idx]) }
    return cs
}

func tryEncodedWord(_ chars: [Character], _ start: Int) -> (start: Int, end: Int, charset: String, encoding: Character, encText: [UInt8])? {
    // chars[start] == '=', chars[start+1] == '?'
    var i = start + 2
    // charset: 1+ chars other than ?, space, tab
    let csStart = i
    while i < chars.count && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" { i += 1 }
    if i == csStart || i >= chars.count || chars[i] != "?" { return nil }
    let charset = String(chars[csStart..<i])
    i += 1 // skip ?
    // encoding: B, b, Q, q
    if i >= chars.count { return nil }
    let enc = chars[i]
    if enc != "B" && enc != "b" && enc != "Q" && enc != "q" { return nil }
    i += 1
    if i >= chars.count || chars[i] != "?" { return nil }
    i += 1 // skip ?
    // encoded-text: 0+ chars other than ?, space, tab
    let etStart = i
    while i < chars.count && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" { i += 1 }
    if i >= chars.count || chars[i] != "?" { return nil }
    let encTextStr = String(chars[etStart..<i])
    i += 1 // skip ?
    if i >= chars.count || chars[i] != "=" { return nil }
    i += 1 // skip =
    let encText = Array(encTextStr.utf8)
    return (start, i, charset, enc, encText)
}

// Parameter parsing
func parseParams(_ s: String) -> [(String, String)] {
    let chars = Array(s)
    var params: [(String, String)] = []
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    while i < chars.count {
        if chars[i] == ";" { i += 1 }
        skipWS()
        if i >= chars.count { break }
        let attr = readToken(["=", " ", "\t", ";"])
        skipWS()
        if i < chars.count && chars[i] == "=" { i += 1 }
        skipWS()
        if i >= chars.count { break }
        let val: String
        if chars[i] == "\"" {
            i += 1; val = ""; var v = ""
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count { v.append(chars[i+1]); i += 2 }
                else { v.append(chars[i]); i += 1 }
            }
            if i < chars.count { i += 1 } // skip closing "
            val = v
        } else {
            val = readToken([";", " ", "\t"])
        }
        params.append((attr.lowercased(), val))
    }
    return params
}

func parseContentType(_ value: String) -> (type: String, subtype: String, params: [(String, String)]) {
    let chars = Array(value)
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    skipWS()
    let type = readToken(["/", " ", "\t", ";"]).lowercased()
    skipWS()
    if i < chars.count && chars[i] == "/" { i += 1 }
    skipWS()
    let subtype = readToken([";", " ", "\t"]).lowercased()
    skipWS()
    let params = parseParams(String(chars[i...]))
    return (type, subtype, params)
}

func parseContentDisposition(_ value: String) -> (disposition: String, params: [(String, String)]) {
    let chars = Array(value)
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    skipWS()
    let disp = readToken([";", " ", "\t"]).lowercased()
    skipWS()
    let params = parseParams(String(chars[i...]))
    return (disp, params)
}

// RFC 2231 resolution
func resolveRFC2231(params: [(String, String)], attr: String) -> String? {
    let a = attr.lowercased()
    // Check for a* (single encoded)
    var singleVal: String? = nil
    var segments: [(Int, Bool, String)] = [] // (index, isEncoded, value)
    for (name, val) in params {
        if name == a + "*" {
            singleVal = val
        } else if name.hasPrefix(a + "*") {
            let rest = String(name.dropFirst(a.count + 1))
            // rest is like "0", "0*", "1", "1*", etc.
            var isEncoded = false
            var numStr = rest
            if numStr.hasSuffix("*") { isEncoded = true; numStr = String(numStr.dropLast()) }
            if let idx = Int(numStr) {
                segments.append((idx, isEncoded, val))
            }
        }
    }
    if let sv = singleVal {
        // Single form: charset'language'percent-encoded
        return decodeRFC2231Single(sv)
    }
    if segments.isEmpty { return nil }
    segments.sort { $0.0 < $1.0 }
    // Check if any are encoded
    let anyEncoded = segments.contains(where: { $0.1 })
    if anyEncoded {
        // Segment 0 must be encoded and start with charset'language'
        var allBytes: [UInt8] = []
        var charset = "us-ascii"
        for (idx, isEnc, val) in segments {
            if idx == 0 && isEnc {
                // charset'language'percent-encoded
                let parts = val.split(separator: "'", maxSplits: 2, omittingEmptySubsequences: false)
                if parts.count >= 3 {
                    charset = String(parts[0])
                    let pe = String(parts[2])
                    allBytes += percentDecode(pe)
                } else {
                    allBytes += percentDecode(val)
                }
            } else if isEnc {
                allBytes += percentDecode(val)
            } else {
                allBytes += Array(val.utf8)
            }
        }
        return decodeBytesToString(allBytes, charset)
    } else {
        // All literal
        var allBytes: [UInt8] = []
        for (_, _, val) in segments { allBytes += Array(val.utf8) }
        return decodeBytesToString(allBytes, "us-ascii")
    }
}

func decodeRFC2231Single(_ val: String) -> String {
    let parts = val.split(separator: "'", maxSplits: 2, omittingEmptySubsequences: false)
    var charset = "us-ascii"
    var pe = val
    if parts.count >= 3 {
        charset = String(parts[0])
        pe = String(parts[2])
    }
    let bytes = percentDecode(pe)
    return decodeBytesToString(bytes, charset)
}

func percentDecode(_ s: String) -> [UInt8] {
    var out: [UInt8] = []
    let chars = Array(s)
    var i = 0
    while i < chars.count {
        if chars[i] == "%" && i + 2 < chars.count,
           let v1 = hexVal(UInt8(ascii: chars[i+1])), let v2 = hexVal(UInt8(ascii: chars[i+2])) {
            out.append(UInt8(v1*16+v2)); i += 3
        } else {
            out.append(UInt8(ascii: chars[i])); i += 1
        }
    }
    return out
}

func decodeBytesToString(_ bytes: [UInt8], _ charset: String) -> String {
    let cps = decodeCharset(bytes, charset.lowercased())
    return String(UnicodeScalarArray(cps))
}

struct UnicodeScalarArray: Sequence {
    let cps: [UInt32]
    init(_ c: [UInt32]) { cps = c }
    func makeIterator() -> IndexingIterator<[Unicode.Scalar]> {
        return cps.compactMap { Unicode.Scalar($0) }.makeIterator()
    }
}

// Quoted string output
func quotedString(_ text: String) -> String {
    var out = "\""
    for scalar in text.unicodeScalars {
        let v = scalar.value
        if v == 0x5C { out += "\\\\" }
        else if v == 0x22 { out += "\\\"" }
        else if v == 0x0A { out += "\\n" }
        else if v == 0x09 { out += "\\t" }
        else if v < 0x20 || (v >= 0x7F && v <= 0x9F) {
            out += String(format: "\\u%04x", v)
        } else { out.unicodeScalars.append(scalar) }
    }
    out += "\""
    return out
}

func quotedStringFromCps(_ cps: [UInt32]) -> String {
    var out = "\""
    for v in cps {
        if v == 0x5C { out += "\\\\" }
        else if v == 0x22 { out += "\\\"" }
        else if v == 0x0A { out += "\\n" }
        else if v == 0x09 { out += "\\t" }
        else if v < 0x20 || (v >= 0x7F && v <= 0x9F) {
            out += String(format: "\\u%04x", v)
        } else {
            if let s = Unicode.Scalar(v) { out.unicodeScalars.append(s) }
        }
    }
    out += "\""
    return out
}

// Entity
struct Entity {
    var headers: [(String, String)] // name lowercased, value trimmed
    var bodyBytes: [UInt8]
    var parts: [Entity]?
}

func getHeader(_ e: Entity, _ name: String) -> String? {
    let n = name.lowercased()
    for (h, v) in e.headers { if h == n { return v } }
    return nil
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    // Split into lines
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(data[i]); i += 1 }
    }
    lines.append(cur)
    // Unfold: remove line break followed by space/tab
    var unfolded: [[UInt8]] = []
    for line in lines {
        if !unfolded.isEmpty && !line.isEmpty && (line[0] == 0x20 || line[0] == 0x09) {
            unfolded[unfolded.count-1] += line
        } else {
            unfolded.append(line)
        }
    }
    // Find empty line
    var emptyIdx = unfolded.count
    for j in 0..<unfolded.count {
        if unfolded[j].isEmpty { emptyIdx = j; break }
    }
    // Headers
    var headers: [(String, String)] = []
    for j in 0..<emptyIdx {
        let line = unfolded[j]
        let s = String(bytes: line, encoding: .ascii) ?? String(decoding: line, as: UTF8.self)
        if let colonPos = s.firstIndex(of: ":") {
            let name = String(s[s.startIndex..<colonPos]).lowercased()
            var val = String(s[s.index(after: colonPos)...])
            // trim leading/trailing spaces and tabs
            while let f = val.first, f == " " || f == "\t" { val.removeFirst() }
            while let l = val.last, l == " " || l == "\t" { val.removeLast() }
            headers.append((name, val))
        }
    }
    // Body
    let bodyStart = emptyIdx + 1
    var bodyBytes: [UInt8] = []
    for j in bodyStart..<unfolded.count {
        if j > bodyStart { bodyBytes += lineBreak }
        bodyBytes += unfolded[j]
    }
    return Entity(headers: headers, bodyBytes: bodyBytes, parts: nil)
}

func parseMultipartBody(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [Entity] {
    // Split body into lines
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < body.count {
        if i + lineBreak.count <= body.count && Array(body[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(body[i]); i += 1 }
    }
    lines.append(cur)
    // Find delimiters
    let delim = Array(("--" + boundary).utf8)
    let closeDelim = Array(("--" + boundary + "--").utf8)
    func isDelimiter(_ line: [UInt8]) -> Bool {
        if line.count < delim.count { return false }
        if Array(line[0..<delim.count]) != delim { return false }
        for k in delim.count..<line.count {
            if line[k] != 0x20 && line[k] != 0x09 { return false }
        }
        return true
    }
    func isCloseDelimiter(_ line: [UInt8]) -> Bool {
        if line.count < closeDelim.count { return false }
        if Array(line[0..<closeDelim.count]) != closeDelim { return false }
        for k in closeDelim.count..<line.count {
            if line[k] != 0x20 && line[k] != 0x09 { return false }
        }
        return true
    }
    var delimIndices: [Int] = []
    for j in 0..<lines.count {
        if isDelimiter(lines[j]) || isCloseDelimiter(lines[j]) {
            delimIndices.append(j)
        }
    }
    if delimIndices.isEmpty { return [] }
    // Parts between consecutive delimiters
    var parts: [Entity] = []
    for k in 0..<(delimIndices.count - 1) {
        let start = delimIndices[k] + 1
        let end = delimIndices[k + 1]
        if start >= end {
            // Empty part
            parts.append(Entity(headers: [], bodyBytes: [], parts: nil))
            continue
        }
        // Reconstruct part data (join lines with lineBreak)
        var partData: [UInt8] = []
        for j in start..<end {
            if j > start { partData += lineBreak }
            partData += lines[j]
        }
        parts.append(parseEntity(partData, lineBreak: lineBreak))
    }
    return parts
}

func transferDecode(_ data: [UInt8], cte: String, lineBreak: [UInt8]) -> [UInt8] {
    switch cte {
    case "base64": return base64Decode(data)
    case "quoted-printable": return decodeQP(data, lineBreak: lineBreak)
    default: return data // 7bit, 8bit, binary
    }
}

func getFileName(_ e: Entity) -> String? {
    // Check Content-Disposition filename RFC 2231
    if let cd = getHeader(e, "content-disposition") {
        let (_, cdParams) = parseContentDisposition(cd)
        if let r = resolveRFC2231(params: cdParams, attr: "filename") { return r }
        if let plain = cdParams.first(where: { $0.0 == "filename" }) {
            return decodeEncodedWordsString(plain.1)
        }
    }
    // Check Content-Type name RFC 2231
    if let ct = getHeader(e, "content-type") {
        let (_, _, ctParams) = parseContentType(ct)
        if let r = resolveRFC2231(params: ctParams, attr: "name") { return r }
        if let plain = ctParams.first(where: { $0.0 == "name" }) {
            return decodeEncodedWordsString(plain.1)
        }
    }
    return nil
}

func decodeEncodedWordsString(_ s: String) -> String {
    let cps = Array(s.unicodeScalars).map { UInt32($0.value) }
    let decoded = decodeEncodedWords(cps)
    return String(UnicodeScalarArray(decoded))
}

func printTree(_ e: Entity, indent: Int, lineBreak: [UInt8], out: inout String) {
    let pad = String(repeating: "  ", count: indent)
    let ct = getHeader(e, "content-type")
    let cteH = getHeader(e, "content-transfer-encoding")?.lowercased() ?? "7bit"
    let cdH = getHeader(e, "content-disposition")

    var type = "text", subtype = "plain", charset = "us-ascii"
    var cdParams: [(String, String)] = []
    var ctParams: [(String, String)] = []
    var dispType: String? = nil

    if let ctv = ct {
        let p = parseContentType(ctv)
        type = p.type; subtype = p.subtype; ctParams = p.params
        if let cs = ctParams.first(where: { $0.0 == "charset" }) { charset = cs.1.lowercased() }
    }
    if let cdv = cdH {
        let p = parseContentDisposition(cdv)
        dispType = p.disposition; cdParams = p.params
    }

    if type == "multipart" {
        let boundary = ctParams.first(where: { $0.0 == "boundary" })?.1 ?? ""
        let parts = parseMultipartBody(e.bodyBytes, boundary: boundary, lineBreak: lineBreak)
        out += "\(pad)multipart/\(subtype) parts=\(parts.count)\n"
        for p in parts { printTree(p, indent: indent + 1, lineBreak: lineBreak, out: &out) }
    } else if type == "text" && dispType != "attachment" {
        let decoded = transferDecode(e.bodyBytes, cte: cteH, lineBreak: lineBreak)
        var cps = decodeCharset(decoded, charset)
        cps = replaceCRLF(cps)
        let n = cps.count
        out += "\(pad)text/\(subtype) charset=\(charset) cte=\(cteH) chars=\(n)\n"
        let pad2 = String(repeating: "  ", count: indent + 1)
        out += "\(pad2)\(quotedStringFromCps(cps))\n"
    } else {
        let decoded = transferDecode(e.bodyBytes, cte: cteH, lineBreak: lineBreak)
        let size = decoded.count
        let crc = crc32(decoded)
        let name = getFileName(e)
        let dispStr = dispType ?? "-"
        let nameStr = name != nil ? quotedString(name!) : "-"
        out += "\(pad)\(type)/\(subtype) cte=\(cteH) disposition=\(dispStr) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))\n"
    }
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let entries = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }
let emlFiles = entries.filter { $0.hasSuffix(".eml") }.sorted { $0 < $1 }

var first = true
for fname in emlFiles {
    if !first { print("") }
    first = false
    let path = dir + "/" + fname
    guard let data = fm.contents(atPath: path) else { continue }
    let bytes = [UInt8](data)
    // Detect line break
    let lineBreak: [UInt8] = bytes.contains(0x0D) ? [0x0D, 0x0A] : [0x0A]

    let entity = parseEntity(bytes, lineBreak: lineBreak)

    print("== \(fname)")
    if let from = getHeader(entity, "from") {
        print("From: \(quotedString(decodeEncodedWordsString(from)))")
    } else { print("From: -") }
    if let subj = getHeader(entity, "subject") {
        print("Subject: \(quotedString(decodeEncodedWordsString(subj)))")
    } else { print("Subject: -") }

    var out = ""
    printTree(entity, indent: 0, lineBreak: lineBreak, out: &out)
    // Remove trailing newline and print
    if out.hasSuffix("\n") { out.removeLast() }
    print(out)
}

import Foundation

// CRC-32 (zlib/PNG)
let crc32Table: [UInt32] = {
    var t = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 { c = (c & 1) != 0 ? (0xEDB88320 ^ (c >> 1)) : (c >> 1) }
        t[i] = c
    }
    return t
}()

func crc32(_ d: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in d { c = crc32Table[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8) }
    return c ^ 0xFFFFFFFF
}

func base64Decode(_ input: [UInt8]) -> [UInt8] {
    var bits: UInt32 = 0, bc = 0, out: [UInt8] = []
    for b in input {
        if b == 0x3D { break }
        let v: UInt32
        switch b {
        case 0x41...0x5A: v = UInt32(b - 0x41)
        case 0x61...0x7A: v = UInt32(b - 0x61) + 26
        case 0x30...0x39: v = UInt32(b - 0x30) + 52
        case 0x2B: v = 62
        case 0x2F: v = 63
        default: continue
        }
        bits = (bits << 6) | v; bc += 6
        if bc >= 8 { bc -= 8; out.append(UInt8((bits >> bc) & 0xFF)) }
    }
    return out
}

func hexVal(_ b: UInt8) -> Int? {
    switch b {
    case 0x30...0x39: return Int(b - 0x30)
    case 0x41...0x46: return Int(b - 0x41) + 10
    case 0x61...0x66: return Int(b - 0x61) + 10
    default: return nil
    }
}

func decodeQP(_ data: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(data[i]); i += 1 }
    }
    lines.append(cur)
    for j in 0..<lines.count {
        while let last = lines[j].last, last == 0x20 || last == 0x09 { lines[j].removeLast() }
    }
    var result: [UInt8] = []
    var li = 0
    while li < lines.count {
        var cl = lines[li]; li += 1
        while cl.last == 0x3D && li < lines.count {
            cl.removeLast()
            cl += lines[li]; li += 1
        }
        var di = 0
        while di < cl.count {
            if cl[di] == 0x3D && di + 2 < cl.count {
                let h1 = cl[di+1], h2 = cl[di+2]
                if let v1 = hexVal(h1), let v2 = hexVal(h2) {
                    result.append(UInt8(v1 * 16 + v2)); di += 3; continue
                }
            }
            result.append(cl[di]); di += 1
        }
        if li < lines.count { result += lineBreak }
    }
    return result
}

let win1252: [UInt32] = {
    let vals: [UInt32] = [0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
                          0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
                          0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
                          0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178]
    return vals
}()

func decodeCharset(_ data: [UInt8], _ cs: String) -> [UInt32] {
    let c = cs.lowercased()
    if c == "utf-8" || c == "us-ascii" {
        var out: [UInt32] = []
        var i = 0
        while i < data.count {
            let b = data[i]
            if b < 0x80 { out.append(UInt32(b)); i += 1 }
            else if b < 0xC0 { out.append(UInt32(b)); i += 1 }
            else if b < 0xE0 {
                let cp = (UInt32(b & 0x1F) << 6) | UInt32(data[i+1] & 0x3F); out.append(cp); i += 2
            } else if b < 0xF0 {
                let cp = (UInt32(b & 0x0F) << 12) | (UInt32(data[i+1] & 0x3F) << 6) | UInt32(data[i+2] & 0x3F); out.append(cp); i += 3
            } else {
                let cp = (UInt32(b & 0x07) << 18) | (UInt32(data[i+1] & 0x3F) << 12) | (UInt32(data[i+2] & 0x3F) << 6) | UInt32(data[i+3] & 0x3F); out.append(cp); i += 4
            }
        }
        return out
    } else if c == "iso-8859-1" {
        return data.map { UInt32($0) }
    } else if c == "windows-1252" {
        return data.map { b -> UInt32 in
            if b >= 0x80 && b <= 0x9F { return win1252[Int(b - 0x80)] }
            return UInt32(b)
        }
    }
    return data.map { UInt32($0) }
}

func replaceCRLF(_ cps: [UInt32]) -> [UInt32] {
    var out: [UInt32] = []
    var i = 0
    while i < cps.count {
        if cps[i] == 0x0D {
            if i + 1 < cps.count && cps[i+1] == 0x0A { out.append(0x0A); i += 2 }
            else { out.append(0x0A); i += 1 }
        } else { out.append(cps[i]); i += 1 }
    }
    return out
}

func cpsToString(_ cps: [UInt32]) -> String {
    var s = ""
    for v in cps {
        if let sc = Unicode.Scalar(v) { s.unicodeScalars.append(sc) }
    }
    return s
}

// Encoded-word decoding
func stripLang(_ cs: String) -> String {
    if let idx = cs.firstIndex(of: "*") { return String(cs[cs.startIndex..<idx]) }
    return cs
}

func tryEncodedWord(_ cps: [UInt32], _ start: Int) -> (start: Int, end: Int, charset: String, encoding: Character, encText: [UInt8])? {
    guard start + 1 < cps.count, cps[start] == 0x3D, cps[start+1] == 0x3F else { return nil }
    var i = start + 2
    let csStart = i
    while i < cps.count && cps[i] != 0x3F && cps[i] != 0x20 && cps[i] != 0x09 { i += 1 }
    if i == csStart || i >= cps.count || cps[i] != 0x3F { return nil }
    let charset = String(decoding: cps[csStart..<i].map { UInt8($0) }, as: UTF8.self)
    i += 1
    if i >= cps.count { return nil }
    let encByte = UInt8(cps[i])
    let enc: Character
    if encByte == 0x42 || encByte == 0x62 { enc = "B" }
    else if encByte == 0x51 || encByte == 0x71 { enc = "Q" }
    else { return nil }
    i += 1
    if i >= cps.count || cps[i] != 0x3F { return nil }
    i += 1
    let etStart = i
    while i < cps.count && cps[i] != 0x3F && cps[i] != 0x20 && cps[i] != 0x09 { i += 1 }
    if i >= cps.count || cps[i] != 0x3F { return nil }
    let encText = cps[etStart..<i].map { UInt8($0) }
    i += 1
    if i >= cps.count || cps[i] != 0x3D { return nil }
    i += 1
    return (start, i, charset, enc, encText)
}

func decodeEncodedWords(_ text: [UInt32]) -> [UInt32] {
    var words: [(start: Int, end: Int, charset: String, encoding: Character, encText: [UInt8])] = []
    var i = 0
    while i < text.count {
        if i + 1 < text.count && text[i] == 0x3D && text[i+1] == 0x3F {
            if let match = tryEncodedWord(text, i) {
                words.append(match)
                i = match.end
                continue
            }
        }
        i += 1
    }
    if words.isEmpty { return text }
    struct Group { var wordIndices: [Int]; var start: Int; var end: Int }
    var groups: [Group] = []
    var wi = 0
    while wi < words.count {
        var g = Group(wordIndices: [wi], start: words[wi].start, end: words[wi].end)
        wi += 1
        while wi < words.count {
            let prev = words[wi-1], curr = words[wi]
            let between = text[prev.end..<curr.start]
            if between.allSatisfy({ $0 == 0x20 || $0 == 0x09 }) &&
               stripLang(prev.charset).lowercased() == stripLang(curr.charset).lowercased() {
                g.wordIndices.append(wi)
                g.end = curr.end
                wi += 1
            } else { break }
        }
        groups.append(g)
    }
    var out: [UInt32] = []
    var ci = 0
    for g in groups {
        while ci < g.start { out.append(text[ci]); ci += 1 }
        var allBytes: [UInt8] = []
        for wi2 in g.wordIndices {
            let w = words[wi2]
            if w.encoding == "B" {
                allBytes += base64Decode(w.encText)
            } else {
                var j = 0
                while j < w.encText.count {
                    if w.encText[j] == 0x5F { allBytes.append(0x20); j += 1 }
                    else if w.encText[j] == 0x3D && j + 2 < w.encText.count,
                            let v1 = hexVal(w.encText[j+1]), let v2 = hexVal(w.encText[j+2]) {
                        allBytes.append(UInt8(v1*16+v2)); j += 3
                    } else { allBytes.append(w.encText[j]); j += 1 }
                }
            }
        }
        let cs = stripLang(words[g.wordIndices[0]].charset)
        out += decodeCharset(allBytes, cs)
        ci = g.end
    }
    while ci < text.count { out.append(text[ci]); ci += 1 }
    return out
}

func decodeEncodedWordsString(_ s: String) -> String {
    let cps = Array(s.unicodeScalars).map { UInt32($0.value) }
    let decoded = decodeEncodedWords(cps)
    return cpsToString(decoded)
}

// Parameter parsing
func parseParams(_ s: String) -> [(String, String)] {
    let chars = Array(s)
    var params: [(String, String)] = []
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    while i < chars.count {
        if chars[i] == ";" { i += 1 }
        skipWS()
        if i >= chars.count { break }
        let attr = readToken(["=", " ", "\t", ";"])
        skipWS()
        if i < chars.count && chars[i] == "=" { i += 1 }
        skipWS()
        if i >= chars.count { break }
        let val: String
        if chars[i] == "\"" {
            i += 1; var v = ""
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count { v.append(chars[i+1]); i += 2 }
                else { v.append(chars[i]); i += 1 }
            }
            if i < chars.count { i += 1 }
            val = v
        } else {
            val = readToken([";", " ", "\t"])
        }
        params.append((attr.lowercased(), val))
    }
    return params
}

func parseContentType(_ value: String) -> (type: String, subtype: String, params: [(String, String)]) {
    let chars = Array(value)
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    skipWS()
    let type = readToken(["/", " ", "\t", ";"]).lowercased()
    skipWS()
    if i < chars.count && chars[i] == "/" { i += 1 }
    skipWS()
    let subtype = readToken([";", " ", "\t"]).lowercased()
    skipWS()
    let params = parseParams(String(chars[i...]))
    return (type, subtype, params)
}

func parseContentDisposition(_ value: String) -> (disposition: String, params: [(String, String)]) {
    let chars = Array(value)
    var i = 0
    func skipWS() { while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 } }
    func readToken(_ stop: Set<Character>) -> String {
        var t = ""
        while i < chars.count && !stop.contains(chars[i]) { t.append(chars[i]); i += 1 }
        return t
    }
    skipWS()
    let disp = readToken([";", " ", "\t"]).lowercased()
    skipWS()
    let params = parseParams(String(chars[i...]))
    return (disp, params)
}

func percentDecode(_ s: String) -> [UInt8] {
    var out: [UInt8] = []
    let chars = Array(s)
    var i = 0
    while i < chars.count {
        if chars[i] == "%" && i + 2 < chars.count {
            let c1 = chars[i+1], c2 = chars[i+2]
            if let v1 = c1.asciiValue.flatMap({ hexVal($0) }), let v2 = c2.asciiValue.flatMap({ hexVal($0) }) {
                out.append(UInt8(v1*16+v2)); i += 3; continue
            }
        }
        if let ab = chars[i].asciiValue { out.append(ab) } else { out.append(0x3F) }
        i += 1
    }
    return out
}

func decodeBytesToString(_ bytes: [UInt8], _ charset: String) -> String {
    let cps = decodeCharset(bytes, charset.lowercased())
    return cpsToString(cps)
}

// RFC 2231 resolution
func resolveRFC2231(params: [(String, String)], attr: String) -> String? {
    let a = attr.lowercased()
    var singleVal: String? = nil
    var segments: [(Int, Bool, String)] = []
    for (name, val) in params {
        if name == a + "*" {
            singleVal = val
        } else if name.hasPrefix(a + "*") {
            let rest = String(name.dropFirst(a.count + 1))
            var isEncoded = false
            var numStr = rest
            if numStr.hasSuffix("*") { isEncoded = true; numStr = String(numStr.dropLast()) }
            if let idx = Int(numStr) {
                segments.append((idx, isEncoded, val))
            }
        }
    }
    if let sv = singleVal {
        return decodeRFC2231Single(sv)
    }
    if segments.isEmpty { return nil }
    segments.sort { $0.0 < $1.0 }
    let anyEncoded = segments.contains(where: { $0.1 })
    if anyEncoded {
        var allBytes: [UInt8] = []
        var charset = "us-ascii"
        for (idx, isEnc, val) in segments {
            if idx == 0 && isEnc {
                let parts = val.split(separator: "'", maxSplits: 2, omittingEmptySubsequences: false)
                if parts.count >= 3 {
                    charset = String(parts[0])
                    let pe = String(parts[2])
                    allBytes += percentDecode(pe)
                } else {
                    allBytes += percentDecode(val)
                }
            } else if isEnc {
                allBytes += percentDecode(val)
            } else {
                allBytes += Array(val.utf8)
            }
        }
        return decodeBytesToString(allBytes, charset)
    } else {
        var allBytes: [UInt8] = []
        for (_, _, val) in segments { allBytes += Array(val.utf8) }
        return decodeBytesToString(allBytes, "us-ascii")
    }
}

func decodeRFC2231Single(_ val: String) -> String {
    let parts = val.split(separator: "'", maxSplits: 2, omittingEmptySubsequences: false)
    var charset = "us-ascii"
    var pe = val
    if parts.count >= 3 {
        charset = String(parts[0])
        pe = String(parts[2])
    }
    let bytes = percentDecode(pe)
    return decodeBytesToString(bytes, charset)
}

// Quoted string output
func quotedStringFromCps(_ cps: [UInt32]) -> String {
    var out = "\""
    for v in cps {
        if v == 0x5C { out += "\\\\" }
        else if v == 0x22 { out += "\\\"" }
        else if v == 0x0A { out += "\\n" }
        else if v == 0x09 { out += "\\t" }
        else if v < 0x20 || (v >= 0x7F && v <= 0x9F) {
            out += String(format: "\\u%04x", v)
        } else {
            if let sc = Unicode.Scalar(v) { out.unicodeScalars.append(sc) }
        }
    }
    out += "\""
    return out
}

func quotedString(_ text: String) -> String {
    let cps = Array(text.unicodeScalars).map { UInt32($0.value) }
    return quotedStringFromCps(cps)
}

// Entity
struct Entity {
    var headers: [(String, String)]
    var bodyBytes: [UInt8]
    var parts: [Entity]?
}

func getHeader(_ e: Entity, _ name: String) -> String? {
    let n = name.lowercased()
    for (h, v) in e.headers { if h == n { return v } }
    return nil
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(data[i]); i += 1 }
    }
    lines.append(cur)
    // Unfold
    var unfolded: [[UInt8]] = []
    for line in lines {
        if !unfolded.isEmpty && !line.isEmpty && (line[0] == 0x20 || line[0] == 0x09) {
            unfolded[unfolded.count-1] += line
        } else {
            unfolded.append(line)
        }
    }
    // Find empty line
    var emptyIdx = unfolded.count
    for j in 0..<unfolded.count {
        if unfolded[j].isEmpty { emptyIdx = j; break }
    }
    // Headers
    var headers: [(String, String)] = []
    for j in 0..<emptyIdx {
        let line = unfolded[j]
        let s = String(bytes: line, encoding: .ascii) ?? String(decoding: line, as: UTF8.self)
        if let colonPos = s.firstIndex(of: ":") {
            let name = String(s[s.startIndex..<colonPos]).lowercased()
            var val = String(s[s.index(after: colonPos)...])
            while let f = val.first, f == " " || f == "\t" { val.removeFirst() }
            while let l = val.last, l == " " || l == "\t" { val.removeLast() }
            headers.append((name, val))
        }
    }
    // Body
    let bodyStart = emptyIdx + 1
    var bodyBytes: [UInt8] = []
    for j in bodyStart..<unfolded.count {
        if j > bodyStart { bodyBytes += lineBreak }
        bodyBytes += unfolded[j]
    }
    return Entity(headers: headers, bodyBytes: bodyBytes, parts: nil)
}

func parseMultipartBody(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [Entity] {
    var lines: [[UInt8]] = []
    var cur: [UInt8] = []
    var i = 0
    while i < body.count {
        if i + lineBreak.count <= body.count && Array(body[i..<i+lineBreak.count]) == lineBreak {
            lines.append(cur); cur = []; i += lineBreak.count
        } else { cur.append(body[i]); i += 1 }
    }
    lines.append(cur)
    let delim = Array(("--" + boundary).utf8)
    let closeDelim = Array(("--" + boundary + "--").utf8)
    func isDelimiter(_ line: [UInt8]) -> Bool {
        if line.count < delim.count { return false }
        if Array(line[0..<delim.count]) != delim { return false }
        for k in delim.count..<line.count {
            if line[k] != 0x20 && line[k] != 0x09 { return false }
        }
        return true
    }
    func isCloseDelimiter(_ line: [UInt8]) -> Bool {
        if line.count < closeDelim.count { return false }
        if Array(line[0..<closeDelim.count]) != closeDelim { return false }
        for k in closeDelim.count..<line.count {
            if line[k] != 0x20 && line[k] != 0x09 { return false }
        }
        return true
    }
    var delimIndices: [Int] = []
    for j in 0..<lines.count {
        if isDelimiter(lines[j]) || isCloseDelimiter(lines[j]) {
            delimIndices.append(j)
        }
    }
    if delimIndices.isEmpty { return [] }
    var parts: [Entity] = []
    for k in 0..<(delimIndices.count - 1) {
        let start = delimIndices[k] + 1
        let end = delimIndices[k + 1]
        if start >= end {
            parts.append(Entity(headers: [], bodyBytes: [], parts: nil))
            continue
        }
        var partData: [UInt8] = []
        for j in start..<end {
            if j > start { partData += lineBreak }
            partData += lines[j]
        }
        parts.append(parseEntity(partData, lineBreak: lineBreak))
    }
    return parts
}

func transferDecode(_ data: [UInt8], cte: String, lineBreak: [UInt8]) -> [UInt8] {
    switch cte {
    case "base64": return base64Decode(data)
    case "quoted-printable": return decodeQP(data, lineBreak: lineBreak)
    default: return data
    }
}

func getFileName(_ e: Entity) -> String? {
    if let cd = getHeader(e, "content-disposition") {
        let (_, cdParams) = parseContentDisposition(cd)
        if let r = resolveRFC2231(params: cdParams, attr: "filename") { return r }
        if let plain = cdParams.first(where: { $0.0 == "filename" }) {
            return decodeEncodedWordsString(plain.1)
        }
    }
    if let ct = getHeader(e, "content-type") {
        let (_, _, ctParams) = parseContentType(ct)
        if let r = resolveRFC2231(params: ctParams, attr: "name") { return r }
        if let plain = ctParams.first(where: { $0.0 == "name" }) {
            return decodeEncodedWordsString(plain.1)
        }
    }
    return nil
}

func printTree(_ e: Entity, indent: Int, lineBreak: [UInt8], out: inout String) {
    let pad = String(repeating: "  ", count: indent)
    let ct = getHeader(e, "content-type")
    let cteH = getHeader(e, "content-transfer-encoding")?.lowercased() ?? "7bit"
    let cdH = getHeader(e, "content-disposition")

    var type = "text", subtype = "plain", charset = "us-ascii"
    var ctParams: [(String, String)] = []
    var dispType: String? = nil

    if let ctv = ct {
        let p = parseContentType(ctv)
        type = p.type; subtype = p.subtype; ctParams = p.params
        if let cs = ctParams.first(where: { $0.0 == "charset" }) { charset = cs.1.lowercased() }
    }
    if let cdv = cdH {
        let p = parseContentDisposition(cdv)
        dispType = p.disposition
    }

    if type == "multipart" {
        let boundary = ctParams.first(where: { $0.0 == "boundary" })?.1 ?? ""
        let parts = parseMultipartBody(e.bodyBytes, boundary: boundary, lineBreak: lineBreak)
        out += "\(pad)multipart/\(subtype) parts=\(parts.count)\n"
        for p in parts { printTree(p, indent: indent + 1, lineBreak: lineBreak, out: &out) }
    } else if type == "text" && dispType != "attachment" {
        let decoded = transferDecode(e.bodyBytes, cte: cteH, lineBreak: lineBreak)
        var cps = decodeCharset(decoded, charset)
        cps = replaceCRLF(cps)
        let n = cps.count
        out += "\(pad)text/\(subtype) charset=\(charset) cte=\(cteH) chars=\(n)\n"
        let pad2 = String(repeating: "  ", count: indent + 1)
        out += "\(pad2)\(quotedStringFromCps(cps))\n"
    } else {
        let decoded = transferDecode(e.bodyBytes, cte: cteH, lineBreak: lineBreak)
        let size = decoded.count
        let crc = crc32(decoded)
        let name = getFileName(e)
        let dispStr = dispType ?? "-"
        let nameStr = name != nil ? quotedString(name!) : "-"
        out += "\(pad)\(type)/\(subtype) cte=\(cteH) disposition=\(dispStr) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))\n"
    }
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let entries = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }
let emlFiles = entries.filter { $0.hasSuffix(".eml") }.sorted { $0 < $1 }

var first = true
for fname in emlFiles {
    if !first { print("") }
    first = false
    let path = dir + "/" + fname
    guard let data = fm.contents(atPath: path) else { continue }
    let bytes = [UInt8](data)
    let lineBreak: [UInt8] = bytes.contains(0x0D) ? [0x0D, 0x0A] : [0x0A]

    let entity = parseEntity(bytes, lineBreak: lineBreak)

    print("== \(fname)")
    if let from = getHeader(entity, "from") {
        print("From: \(quotedString(decodeEncodedWordsString(from)))")
    } else { print("From: -") }
    if let subj = getHeader(entity, "subject") {
        print("Subject: \(quotedString(decodeEncodedWordsString(subj)))")
    } else { print("Subject: -") }

    var out = ""
    printTree(entity, indent: 0, lineBreak: lineBreak, out: &out)
    if out.hasSuffix("\n") { out.removeLast() }
    print(out)
}

import sys
import os
import re
import zlib
import base64


def main():
    if len(sys.argv) < 2:
        return
    directory = sys.argv[1]
    files = sorted([f for f in os.listdir(directory) if f.endswith('.eml')])

    results = []
    for fname in files:
        path = os.path.join(directory, fname)
        with open(path, 'rb') as f:
            data = f.read()
        results.append(process_file(fname, data))

    if results:
        sys.stdout.write('\n\n'.join(results) + '\n')


def detect_line_break(data):
    idx = data.find(b'\n')
    if idx == -1:
        return b'\n'
    if idx > 0 and data[idx - 1] == 0x0D:
        return b'\r\n'
    return b'\n'


def process_file(fname, data):
    lb = detect_line_break(data)
    entity = parse_entity(data, lb)
    headers = entity['headers']

    from_val = get_header(headers, 'from')
    subject_val = get_header(headers, 'subject')

    if from_val is not None:
        from_val = decode_encoded_words(from_val)
    if subject_val is not None:
        subject_val = decode_encoded_words(subject_val)

    lines = []
    lines.append(f"== {fname}")
    lines.append(f"From: {quote_string(from_val) if from_val is not None else '-'}")
    lines.append(f"Subject: {quote_string(subject_val) if subject_val is not None else '-'}")

    build_tree(entity, lb, 0, lines)
    return '\n'.join(lines)


def parse_entity(data, lb):
    if not data:
        return {'headers': [], 'body': b''}

    if data.startswith(lb):
        headers_data = b''
        body = data[len(lb):]
    else:
        idx = data.find(lb + lb)
        if idx == -1:
            headers_data = data
            body = b''
        else:
            headers_data = data[:idx + len(lb)]
            body = data[idx + 2 * len(lb):]

    headers = parse_headers(headers_data, lb)
    return {'headers': headers, 'body': body}


def parse_headers(headers_data, lb):
    if not headers_data:
        return []

    unfolded = bytearray(headers_data)
    lb_bytes = bytes(lb)
    i = 0
    while i < len(unfolded):
        idx = unfolded.find(lb_bytes, i)
        if idx == -1:
            break
        after = idx + len(lb_bytes)
        if after < len(unfolded) and unfolded[after] in (0x20, 0x09):
            del unfolded[idx:after]
        else:
            i = after

    lines = bytes(unfolded).split(lb_bytes)
    if lines and lines[-1] == b'':
        lines = lines[:-1]

    headers = []
    for line in lines:
        if not line:
            continue
        colon_idx = line.find(b':')
        if colon_idx == -1:
            continue
        name = line[:colon_idx].decode('ascii').lower()
        value = line[colon_idx + 1:].decode('ascii')
        value = value.strip(' \t')
        headers.append((name, value))
    return headers


def get_header(headers, name):
    for h_name, h_value in headers:
        if h_name == name:
            return h_value
    return None


def parse_content_type(value):
    if not value or not value.strip():
        return ('text', 'plain', [])
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1
    type_start = i
    while i < len(value) and value[i] not in ' \t/':
        i += 1
    type_name = value[type_start:i].lower()
    while i < len(value) and value[i] in ' \t':
        i += 1
    if i < len(value) and value[i] == '/':
        i += 1
    else:
        return ('text', 'plain', [])
    while i < len(value) and value[i] in ' \t':
        i += 1
    sub_start = i
    while i < len(value) and value[i] not in ' \t;':
        i += 1
    subtype = value[sub_start:i].lower()
    params = parse_params(value[i:])
    return (type_name, subtype, params)


def parse_content_disposition(value):
    if not value or not value.strip():
        return (None, [])
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1
    disp_start = i
    while i < len(value) and value[i] not in ' \t;':
        i += 1
    disp_type = value[disp_start:i].lower()
    params = parse_params(value[i:])
    return (disp_type, params)


def parse_params(s):
    params = []
    i = 0
    while i < len(s):
        while i < len(s) and s[i] in ' \t':
            i += 1
        if i >= len(s):
            break
        if s[i] != ';':
            break
        i += 1
        while i < len(s) and s[i] in ' \t':
            i += 1
        if i >= len(s):
            break
        attr_start = i
        while i < len(s) and s[i] not in ' \t=':
            i += 1
        attr = s[attr_start:i].lower()
        while i < len(s) and s[i] in ' \t':
            i += 1
        if i < len(s) and s[i] == '=':
            i += 1
        else:
            params.append((attr, ''))
            continue
        while i < len(s) and s[i] in ' \t':
            i += 1
        if i < len(s) and s[i] == '"':
            i += 1
            val_chars = []
            while i < len(s) and s[i] != '"':
                if s[i] == '\\' and i + 1 < len(s):
                    val_chars.append(s[i + 1])
                    i += 2
                else:
                    val_chars.append(s[i])
                    i += 1
            if i < len(s):
                i += 1
            value = ''.join(val_chars)
        else:
            val_start = i
            while i < len(s) and s[i] not in ' \t;':
                i += 1
            value = s[val_start:i]
        params.append((attr, value))
    return params


def parse_multipart(body, boundary, lb):
    if not boundary:
        return []

    delim = b'--' + boundary
    close_delim = b'--' + boundary + b'--'

    lines = []
    pos = 0
    while pos < len(body):
        idx = body.find(lb, pos)
        if idx == -1:
            lines.append((pos, len(body), body[pos:]))
            break
        lines.append((pos, idx, body[pos:idx]))
        pos = idx + len(lb)

    delim_indices = []
    close_indices = []
    for i, (start, end, content) in enumerate(lines):
        stripped = content.rstrip(b' \t')
        if stripped == delim:
            delim_indices.append(i)
        elif stripped == close_delim:
            close_indices.append(i)

    if not delim_indices:
        return []

    first = delim_indices[0]
    close_idx = len(lines)
    for ci in close_indices:
        if ci > first:
            close_idx = ci
            break

    delims_in_range = [first]
    for di in delim_indices[1:]:
        if di < close_idx:
            delims_in_range.append(di)

    parts = []
    boundaries = delims_in_range + [close_idx]
    for i in range(len(boundaries) - 1):
        start_line = boundaries[i] + 1
        end_line = boundaries[i + 1]
        if start_line >= end_line:
            parts.append(b'')
            continue
        part_start = lines[start_line][0]
        part_end = lines[end_line - 1][1]
        parts.append(body[part_start:part_end])
    return parts


def get_cte(headers):
    val = get_header(headers, 'content-transfer-encoding')
    if val is None:
        return '7bit'
    return val.lower().strip()


def get_charset(params):
    for name, value in params:
        if name == 'charset':
            return value.lower()
    return 'us-ascii'


def build_tree(entity, lb, indent, lines):
    headers = entity['headers']
    body = entity['body']

    ct_value = get_header(headers, 'content-type')
    if ct_value is None:
        ct_type, ct_subtype, ct_params = ('text', 'plain', [])
    else:
        ct_type, ct_subtype, ct_params = parse_content_type(ct_value)

    cd_value = get_header(headers, 'content-disposition')
    if cd_value is None:
        cd_type, cd_params = (None, [])
    else:
        cd_type, cd_params = parse_content_disposition(cd_value)

    cte = get_cte(headers)
    prefix = '  ' * indent

    if ct_type == 'multipart':
        boundary = None
        for name, value in ct_params:
            if name == 'boundary':
                boundary = value.encode('ascii')
                break
        parts_data = parse_multipart(body, boundary, lb)
        lines.append(f"{prefix}multipart/{ct_subtype} parts={len(parts_data)}")
        for part_data in parts_data:
            part_entity = parse_entity(part_data, lb)
            build_tree(part_entity, lb, indent + 1, lines)

    elif ct_type == 'text' and cd_type != 'attachment':
        charset = get_charset(ct_params)
        decoded_bytes = decode_cte(body, cte, lb)
        text = decode_charset(decoded_bytes, charset)
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        n = len(text)
        lines.append(f"{prefix}text/{ct_subtype} charset={charset} cte={cte} chars={n}")
        lines.append(f"{'  ' * (indent + 1)}{quote_string(text)}")

    else:
        decoded_bytes = decode_cte(body, cte, lb)
        size = len(decoded_bytes)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        name = get_filename(headers)
        name_str = quote_string(name) if name is not None else '-'
        disp_str = cd_type if cd_type else '-'
        lines.append(
            f"{prefix}{ct_type}/{ct_subtype} cte={cte} disposition={disp_str} "
            f"name={name_str} size={size} crc32={crc:08x}"
        )


def get_filename(headers):
    cd_value = get_header(headers, 'content-disposition')
    ct_value = get_header(headers, 'content-type')

    cd_params = []
    if cd_value:
        _, cd_params = parse_content_disposition(cd_value)

    ct_params = []
    if ct_value:
        _, _, ct_params = parse_content_type(ct_value)

    result = get_rfc2231_param(cd_params, 'filename')
    if result is not None:
        return result

    result = get_regular_param(cd_params, 'filename')
    if result is not None:
        return decode_encoded_words(result)

    result = get_rfc2231_param(ct_params, 'name')
    if result is not None:
        return result

    result = get_regular_param(ct_params, 'name')
    if result is not None:
        return decode_encoded_words(result)

    return None


def get_regular_param(params, attr):
    for name, value in params:
        if name == attr:
            return value
    return None


def get_rfc2231_param(params, attr):
    attr = attr.lower()
    single_key = attr + '*'
    has_rfc2231 = False
    segments = {}
    charset = None

    for name, value in params:
        if name == single_key:
            has_rfc2231 = True
            charset, pct_value = parse_rfc2231_prefix(value)
            segments[0] = (pct_value, True)
        elif name.startswith(attr + '*'):
            rest = name[len(attr) + 1:]
            if rest.endswith('*'):
                num_str = rest[:-1]
                if num_str.isdigit():
                    has_rfc2231 = True
                    segments[int(num_str)] = (value, True)
            else:
                if rest.isdigit():
                    has_rfc2231 = True
                    segments[int(rest)] = (value, False)

    if not has_rfc2231:
        return None

    all_bytes = bytearray()
    for idx in sorted(segments.keys()):
        value, is_pct = segments[idx]
        if is_pct:
            if idx == 0 and charset is None:
                charset, pct_value = parse_rfc2231_prefix(value)
                all_bytes.extend(percent_decode(pct_value))
            else:
                all_bytes.extend(percent_decode(value))
        else:
            all_bytes.extend(value.encode('ascii'))

    if charset is None:
        charset = 'us-ascii'
    return decode_charset(bytes(all_bytes), charset)


def parse_rfc2231_prefix(value):
    idx1 = value.find("'")
    if idx1 == -1:
        return 'us-ascii', value
    idx2 = value.find("'", idx1 + 1)
    if idx2 == -1:
        return value[:idx1], value[idx1 + 1:]
    return value[:idx1], value[idx2 + 1:]


def percent_decode(s):
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s) and is_hex(s[i + 1]) and is_hex(s[i + 2]):
            result.append(int(s[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)


def is_hex(c):
    return c in '0123456789abcdefABCDEF'


def is_hex_byte(b):
    return (0x30 <= b <= 0x39) or (0x41 <= b <= 0x46) or (0x61 <= b <= 0x66)


def quote_string(s):
    result = ['"']
    for ch in s:
        cp = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append(f'\\u{cp:04x}')
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


def decode_charset(data, charset):
    charset = charset.lower().strip()
    if charset in ('us-ascii', 'ascii'):
        return data.decode('ascii')
    elif charset == 'utf-8':
        return data.decode('utf-8')
    elif charset == 'iso-8859-1':
        return data.decode('iso-8859-1')
    elif charset == 'windows-1252':
        return decode_windows1252(data)
    else:
        return data.decode('latin-1')


def decode_windows1252(data):
    cp1252_map = {
        0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192,
        0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021,
        0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
        0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D, 0x8F: 0x008F,
        0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
        0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
        0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A,
        0x9C: 0x0153, 0x9D: 0x009D, 0x9E: 0x017E, 0x9F: 0x0178,
    }
    result = []
    for b in data:
        if 0x80 <= b <= 0x9F:
            result.append(chr(cp1252_map[b]))
        else:
            result.append(chr(b))
    return ''.join(result)


def decode_base64_cte(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    buf = bytearray()
    for b in data:
        if b == ord('='):
            break
        if b in alphabet:
            buf.append(b)
    pad = (4 - len(buf) % 4) % 4
    buf.extend(b'=' * pad)
    return base64.b64decode(bytes(buf))


def decode_qp_cte(data, lb):
    lines = data.split(bytes(lb))
    stripped = [line.rstrip(b' \t') for line in lines]

    result_lines = []
    i = 0
    while i < len(stripped):
        current = stripped[i]
        while current.endswith(b'='):
            current = current[:-1]
            i += 1
            if i < len(stripped):
                current += stripped[i]
            else:
                break
        result_lines.append(current)
        i += 1

    decoded_lines = []
    for line in result_lines:
        decoded = bytearray()
        j = 0
        while j < len(line):
            if (line[j:j + 1] == b'=' and j + 2 < len(line)
                    and is_hex_byte(line[j + 1]) and is_hex_byte(line[j + 2])):
                decoded.append(int(line[j + 1:j + 3], 16))
                j += 3
            else:
                decoded.append(line[j])
                j += 1
        decoded_lines.append(bytes(decoded))

    return bytes(lb).join(decoded_lines)


def decode_cte(data, encoding, lb):
    encoding = encoding.lower()
    if encoding in ('7bit', '8bit', 'binary'):
        return data
    elif encoding == 'base64':
        return decode_base64_cte(data)
    elif encoding == 'quoted-printable':
        return decode_qp_cte(data, lb)
    else:
        return data


EW_PATTERN = re.compile(r'=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=')


def decode_base64_ew(text):
    s = text
    pad = (4 - len(s) % 4) % 4
    s += '=' * pad
    try:
        return base64.b64decode(s)
    except Exception:
        return b''


def decode_q_ew(text):
    result = bytearray()
    i = 0
    while i < len(text):
        if text[i] == '_':
            result.append(0x20)
            i += 1
        elif (text[i] == '=' and i + 2 < len(text)
              and is_hex(text[i + 1]) and is_hex(text[i + 2])):
            result.append(int(text[i + 1:i + 3], 16))
            i += 3
        else:
            result.append(ord(text[i]))
            i += 1
    return bytes(result)


def decode_encoded_words(text):
    matches = list(EW_PATTERN.finditer(text))
    if not matches:
        return text

    runs = []
    current_run = None

    for m in matches:
        charset_raw = m.group(1)
        encoding = m.group(2)
        encoded_text = m.group(3)

        charset_norm = charset_raw.split('*')[0].lower()

        if encoding in ('B', 'b'):
            word_bytes = decode_base64_ew(encoded_text)
        else:
            word_bytes = decode_q_ew(encoded_text)

        if current_run is not None:
            gap = text[current_run['end']:m.start()]
            if gap and not all(c in ' \t' for c in gap):
                runs.append(current_run)
                current_run = None
            elif current_run['charset_norm'] != charset_norm:
                runs.append(current_run)
                current_run = None

        if current_run is None:
            current_run = {
                'start': m.start(),
                'end': m.end(),
                'charset_norm': charset_norm,
                'bytes': [word_bytes]
            }
        else:
            current_run['end'] = m.end()
            current_run['bytes'].append(word_bytes)

    if current_run:
        runs.append(current_run)

    result = text
    for run in reversed(runs):
        all_bytes = b''.join(run['bytes'])
        decoded = decode_charset(all_bytes, run['charset_norm'])
        result = result[:run['start']] + decoded + result[run['end']:]

    return result


if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static String LB;

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".eml"));
        if (files == null) files = new File[0];
        Arrays.sort(files, Comparator.comparing(File::getName));
        for (int i = 0; i < files.length; i++) {
            if (i > 0) System.out.println();
            processFile(files[i]);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        LB = detectLB(data);
        Entity msg = parseEntity(data);
        System.out.println("== " + f.getName());
        String from = getHeader(msg, "from");
        String subj = getHeader(msg, "subject");
        System.out.println("From: " + (from == null ? "-" : quoted(decodeEncodedWords(from))));
        System.out.println("Subject: " + (subj == null ? "-" : quoted(decodeEncodedWords(subj))));
        printEntity(msg, 0);
    }

    static String detectLB(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == '\r' && data[i + 1] == '\n') return "\r\n";
        }
        return "\n";
    }

    static List<String> splitLines(byte[] data) {
        List<String> lines = new ArrayList<>();
        byte[] lb = LB.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        int i = 0;
        while (i <= data.length) {
            int j = i;
            while (j + lb.length <= data.length) {
                boolean match = true;
                for (int k = 0; k < lb.length; k++) {
                    if (data[j + k] != lb[k]) { match = false; break; }
                }
                if (match) break;
                j++;
            }
            if (j + lb.length <= data.length) {
                boolean match = true;
                for (int k = 0; k < lb.length; k++) {
                    if (data[j + k] != lb[k]) { match = false; break; }
                }
                if (match) {
                    lines.add(new String(data, i, j - i, java.nio.charset.StandardCharsets.ISO_8859_1));
                    i = j + lb.length;
                    continue;
                }
            }
            lines.add(new String(data, i, data.length - i, java.nio.charset.StandardCharsets.ISO_8859_1));
            break;
        }
        return lines;
    }

    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();
        List<String> lines = splitLines(data);
        int sep = -1;
        for (int i = 0; i < lines.size(); i++) {
            if (lines.get(i).isEmpty()) { sep = i; break; }
        }
        List<String> headerLines;
        byte[] bodyBytes;
        if (sep < 0) {
            headerLines = lines;
            bodyBytes = new byte[0];
        } else {
            headerLines = lines.subList(0, sep);
            List<String> bodyLines = lines.subList(sep + 1, lines.size());
            if (bodyLines.isEmpty()) {
                bodyBytes = new byte[0];
            } else {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < bodyLines.size(); i++) {
                    if (i > 0) sb.append(LB);
                    sb.append(bodyLines.get(i));
                }
                bodyBytes = sb.toString().getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            }
        }
        e.headers = parseHeaders(headerLines);
        e.body = bodyBytes;
        String ct = getHeader(e, "content-type");
        if (ct != null) {
            String[] ts = parseTypeSubtype(ct);
            if (ts[0].equals("multipart")) {
                Map<String, String> params = parseParams(ct);
                String boundary = params.get("boundary");
                if (boundary != null) {
                    e.parts = parseMultipart(e.body, boundary);
                } else {
                    e.parts = new ArrayList<>();
                }
            }
        }
        return e;
    }

    static Map<String, String> parseHeaders(List<String> lines) {
        List<String> unfolded = new ArrayList<>();
        for (String line : lines) {
            if (!line.isEmpty() && (line.charAt(0) == ' ' || line.charAt(0) == '\t')) {
                if (!unfolded.isEmpty()) {
                    unfolded.set(unfolded.size() - 1, unfolded.get(unfolded.size() - 1) + line);
                } else {
                    unfolded.add(line);
                }
            } else {
                unfolded.add(line);
            }
        }
        Map<String, String> map = new LinkedHashMap<>();
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String value = line.substring(colon + 1);
            int start = 0, end = value.length();
            while (start < end && (value.charAt(start) == ' ' || value.charAt(start) == '\t')) start++;
            while (end > start && (value.charAt(end - 1) == ' ' || value.charAt(end - 1) == '\t')) end--;
            value = value.substring(start, end);
            map.put(name, value);
        }
        return map;
    }

    static String getHeader(Entity e, String name) {
        return e.headers.get(name.toLowerCase());
    }

    static String[] parseTypeSubtype(String value) {
        String v = value.trim();
        int slash = v.indexOf('/');
        if (slash < 0) return new String[]{"text", "plain"};
        String type = v.substring(0, slash).trim().toLowerCase();
        String rest = v.substring(slash + 1);
        int semi = findParamStart(rest);
        String subtype;
        if (semi < 0) {
            subtype = rest.trim().toLowerCase();
        } else {
            subtype = rest.substring(0, semi).trim().toLowerCase();
        }
        return new String[]{type, subtype};
    }

    static int findParamStart(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == ';') return i;
        }
        return -1;
    }

    static Map<String, String> parseParams(String value) {
        Map<String, String> params = new LinkedHashMap<>();
        int semi = findParamStart(value);
        if (semi < 0) return params;
        int pos = semi;
        while (pos < value.length()) {
            while (pos < value.length() && (value.charAt(pos) == ';' || value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
            if (pos >= value.length()) break;
            int nameStart = pos;
            while (pos < value.length() && value.charAt(pos) != '=' && value.charAt(pos) != ';' && value.charAt(pos) != ' ' && value.charAt(pos) != '\t') pos++;
            String name = value.substring(nameStart, pos).trim().toLowerCase();
            while (pos < value.length() && (value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
            if (pos < value.length() && value.charAt(pos) == '=') {
                pos++;
                while (pos < value.length() && (value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
                String val;
                if (pos < value.length() && value.charAt(pos) == '"') {
                    pos++;
                    StringBuilder sb = new StringBuilder();
                    while (pos < value.length() && value.charAt(pos) != '"') {
                        if (value.charAt(pos) == '\\' && pos + 1 < value.length()) {
                            sb.append(value.charAt(pos + 1));
                            pos += 2;
                        } else {
                            sb.append(value.charAt(pos));
                            pos++;
                        }
                    }
                    if (pos < value.length()) pos++;
                    val = sb.toString();
                } else {
                    int vStart = pos;
                    while (pos < value.length() && value.charAt(pos) != ';' && value.charAt(pos) != ' ' && value.charAt(pos) != '\t') pos++;
                    val = value.substring(vStart, pos);
                }
                params.put(name, val);
            } else {
                params.put(name, "");
            }
        }
        return params;
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<String> lines = splitLines(body);
        String delim = "--" + boundary;
        String closeDelim = delim + "--";
        List<int[]> delimPositions = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (isCloseDelimiter(line, closeDelim)) {
                delimPositions.add(new int[]{i, 1});
            } else if (isDelimiter(line, delim)) {
                delimPositions.add(new int[]{i, 0});
            }
        }
        List<Entity> parts = new ArrayList<>();
        for (int i = 0; i < delimPositions.size() - 1; i++) {
            int startLine = delimPositions.get(i)[0];
            int endLine = delimPositions.get(i + 1)[0];
            if (delimPositions.get(i)[1] == 1) break;
            List<String> partLines = lines.subList(startLine + 1, endLine);
            byte[] partData;
            if (partLines.isEmpty()) {
                partData = new byte[0];
            } else {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < partLines.size(); j++) {
                    if (j > 0) sb.append(LB);
                    sb.append(partLines.get(j));
                }
                partData = sb.toString().getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            }
            parts.add(parseEntity(partData));
        }
        return parts;
    }

    static boolean isDelimiter(String line, String delim) {
        if (!line.startsWith(delim)) return false;
        String rest = line.substring(delim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static boolean isCloseDelimiter(String line, String closeDelim) {
        if (!line.startsWith(closeDelim)) return false;
        String rest = line.substring(closeDelim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static void printEntity(Entity e, int indent) {
        String pad = "  ".repeat(indent);
        String ct = getHeader(e, "content-type");
        String[] ts;
        if (ct != null) {
            ts = parseTypeSubtype(ct);
        } else {
            ts = new String[]{"text", "plain"};
        }
        String type = ts[0], subtype = ts[1];

        if (e.parts != null) {
            System.out.println(pad + "multipart/" + subtype + " parts=" + e.parts.size());
            for (Entity p : e.parts) {
                printEntity(p, indent + 1);
            }
            return;
        }

        String cte = getHeader(e, "content-transfer-encoding");
        if (cte == null) cte = "7bit";
        cte = cte.trim().toLowerCase();

        String cd = getHeader(e, "content-disposition");
        String dispType = null;
        Map<String, String> cdParams = null;
        if (cd != null) {
            int semi = findParamStart(cd);
            dispType = (semi < 0 ? cd : cd.substring(0, semi)).trim().toLowerCase();
            cdParams = parseParams(cd);
        }

        Map<String, String> ctParams = ct != null ? parseParams(ct) : new LinkedHashMap<>();

        if (type.equals("text") && !"attachment".equals(dispType)) {
            String charset = ctParams.getOrDefault("charset", "us-ascii").toLowerCase();
            byte[] decoded = decodeCTE(e.body, cte);
            String text = decodeCharset(decoded, charset);
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(pad + "text/" + subtype + " charset=" + charset + " cte=" + cte + " chars=" + chars);
            System.out.println("  ".repeat(indent + 1) + quoted(text));
        } else {
            byte[] decoded = decodeCTE(e.body, cte);
            CRC32 crc = new CRC32();
            crc.update(decoded);
            String name = getFileName(e, cdParams, ctParams);
            String nameStr = name == null ? "-" : quoted(name);
            System.out.println(pad + type + "/" + subtype + " cte=" + cte +
                    " disposition=" + (dispType == null ? "-" : dispType) +
                    " name=" + nameStr +
                    " size=" + decoded.length +
                    " crc32=" + String.format("%08x", crc.getValue()));
        }
    }

    static String getFileName(Entity e, Map<String, String> cdParams, Map<String, String> ctParams) {
        String r;
        r = getRFC2231(cdParams, "filename");
        if (r != null) return r;
        if (cdParams != null && cdParams.containsKey("filename")) {
            return decodeEncodedWords(cdParams.get("filename"));
        }
        r = getRFC2231(ctParams, "name");
        if (r != null) return r;
        if (ctParams != null && ctParams.containsKey("name")) {
            return decodeEncodedWords(ctParams.get("name"));
        }
        return null;
    }

    static String getRFC2231(Map<String, String> params, String attr) {
        if (params == null) return null;
        attr = attr.toLowerCase();
        if (params.containsKey(attr + "*")) {
            String val = params.get(attr + "*");
            String charset = extractCharsetFromPct(val);
            byte[] bytes = percentDecode(stripCharsetLang(val));
            return decodeCharset(bytes, charset);
        }
        List<String> segments = new ArrayList<>();
        List<Boolean> pctFlags = new ArrayList<>();
        int i = 0;
        boolean anyPct = false;
        while (true) {
            String pctKey = attr + "*" + i + "*";
            String plainKey = attr + "*" + i;
            if (params.containsKey(pctKey)) {
                segments.add(params.get(pctKey));
                pctFlags.add(true);
                anyPct = true;
            } else if (params.containsKey(plainKey)) {
                segments.add(params.get(plainKey));
                pctFlags.add(false);
            } else {
                break;
            }
            i++;
        }
        if (segments.isEmpty()) return null;
        String charset = "us-ascii";
        if (anyPct) {
            for (int j = 0; j < segments.size(); j++) {
                if (pctFlags.get(j)) {
                    charset = extractCharsetFromPct(segments.get(j));
                    break;
                }
            }
        }
        byte[] result = new byte[0];
        for (int j = 0; j < segments.size(); j++) {
            String seg = segments.get(j);
            if (pctFlags.get(j)) {
                if (j == 0 || (j > 0 && !pctFlags.get(j - 1))) {
                    seg = stripCharsetLang(seg);
                }
                result = concat(result, percentDecode(seg));
            } else {
                result = concat(result, seg.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
            }
        }
        return decodeCharset(result, charset);
    }

    static String extractCharsetFromPct(String val) {
        int q1 = val.indexOf('\'');
        if (q1 < 0) return "us-ascii";
        int q2 = val.indexOf('\'', q1 + 1);
        if (q2 < 0) return "us-ascii";
        String cs = val.substring(0, q1);
        if (cs.isEmpty()) return "us-ascii";
        return cs.toLowerCase();
    }

    static String stripCharsetLang(String val) {
        int q1 = val.indexOf('\'');
        if (q1 < 0) return val;
        int q2 = val.indexOf('\'', q1 + 1);
        if (q2 < 0) return val;
        return val.substring(q2 + 1);
    }

    static byte[] percentDecode(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '%' && i + 2 < s.length()) {
                int hi = hexVal(s.charAt(i + 1));
                int lo = hexVal(s.charAt(i + 2));
                if (hi >= 0 && lo >= 0) {
                    out.write((hi << 4) | lo);
                    i += 2;
                } else {
                    out.write(s.charAt(i));
                }
            } else {
                out.write(s.charAt(i) & 0xFF);
            }
        }
        return out.toByteArray();
    }

    static byte[] concat(byte[] a, byte[] b) {
        byte[] r = new byte[a.length + b.length];
        System.arraycopy(a, 0, r, 0, a.length);
        System.arraycopy(b, 0, r, a.length, b.length);
        return r;
    }

    static int hexVal(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    }

    static byte[] decodeCTE(byte[] data, String encoding) {
        switch (encoding) {
            case "base64": return decodeBase64(data);
            case "quoted-printable": return decodeQP(data);
            default: return data;
        }
    }

    static byte[] decodeBase64(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            char c = (char) (b & 0xFF);
            if (c == '=') break;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            }
        }
        String s = sb.toString();
        int len = s.length();
        int fullGroups = len / 4;
        int remainder = len % 4;
        int outLen = fullGroups * 3 + (remainder == 2 ? 1 : remainder == 3 ? 2 : 0);
        byte[] out = new byte[outLen];
        int oi = 0;
        for (int i = 0; i < fullGroups; i++) {
            int v = (b64Val(s.charAt(i * 4)) << 18) | (b64Val(s.charAt(i * 4 + 1)) << 12) |
                    (b64Val(s.charAt(i * 4 + 2)) << 6) | b64Val(s.charAt(i * 4 + 3));
            out[oi++] = (byte) (v >> 16);
            out[oi++] = (byte) (v >> 8);
            out[oi++] = (byte) v;
        }
        if (remainder == 2) {
            int v = (b64Val(s.charAt(fullGroups * 4)) << 18) | (b64Val(s.charAt(fullGroups * 4 + 1)) << 12);
            out[oi++] = (byte) (v >> 16);
        } else if (remainder == 3) {
            int v = (b64Val(s.charAt(fullGroups * 4)) << 18) | (b64Val(s.charAt(fullGroups * 4 + 1)) << 12) |
                    (b64Val(s.charAt(fullGroups * 4 + 2)) << 6);
            out[oi++] = (byte) (v >> 16);
            out[oi++] = (byte) (v >> 8);
        }
        return out;
    }

    static int b64Val(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return 0;
    }

    static byte[] decodeQP(byte[] data) {
        String s = new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
        List<String> lines = new ArrayList<>();
        int pos = 0;
        while (pos <= s.length()) {
            int nl = s.indexOf('\n', pos);
            if (nl < 0) {
                lines.add(s.substring(pos));
                break;
            }
            String line = s.substring(pos, nl);
            if (line.endsWith("\r")) line = line.substring(0, line.length() - 1);
            lines.add(line);
            pos = nl + 1;
        }
        if (pos > s.length()) {
            // file ended with \n, last "line" was already added
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int li = 0; li < lines.size(); li++) {
            String line = lines.get(li);
            // Remove trailing spaces/tabs
            int end = line.length();
            while (end > 0 && (line.charAt(end - 1) == ' ' || line.charAt(end - 1) == '\t')) end--;
            line = line.substring(0, end);
            boolean softBreak = line.endsWith("=");
            for (int i = 0; i < line.length(); i++) {
                if (line.charAt(i) == '=') {
                    if (i + 2 < line.length()) {
                        int hi = hexVal(line.charAt(i + 1));
                        int lo = hexVal(line.charAt(i + 2));
                        if (hi >= 0 && lo >= 0) {
                            out.write((hi << 4) | lo);
                            i += 2;
                        } else {
                            out.write('=');
                        }
                    } else if (i + 1 < line.length()) {
                        int hi = hexVal(line.charAt(i + 1));
                        if (hi >= 0) {
                            // only one hex digit, treat as literal =
                            out.write('=');
                        } else {
                            out.write('=');
                        }
                    } else {
                        // = at end (but we checked softBreak separately)
                        out.write('=');
                    }
                } else {
                    out.write(line.charAt(i) & 0xFF);
                }
            }
            if (li < lines.size() - 1) {
                if (!softBreak) {
                    out.write('\n');
                }
            }
        }
        return out.toByteArray();
    }

    static String decodeCharset(byte[] data, String charset) {
        charset = charset.toLowerCase().trim();
        switch (charset) {
            case "us-ascii":
            case "ascii": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
            case "utf-8":
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            case "iso-8859-1":
            case "latin1":
            case "latin-1": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
            case "windows-1252":
            case "cp1252": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) {
                    int b = data[i] & 0xFF;
                    if (b >= 0x80 && b <= 0x9F) {
                        cs[i] = (char) cp1252(b);
                    } else {
                        cs[i] = (char) b;
                    }
                }
                return new String(cs);
            }
            default: {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
        }
    }

    static int cp1252(int b) {
        switch (b) {
            case 0x80: return 0x20AC; case 0x81: return 0x0081;
            case 0x82: return 0x201A; case 0x83: return 0x0192;
            case 0x84: return 0x201E; case 0x85: return 0x2026;
            case 0x86: return 0x2020; case 0x87: return 0x2021;
            case 0x88: return 0x02C6; case 0x89: return 0x2030;
            case 0x8A: return 0x0160; case 0x8B: return 0x2039;
            case 0x8C: return 0x0152; case 0x8D: return 0x008D;
            case 0x8E: return 0x017D; case 0x8F: return 0x008F;
            case 0x90: return 0x0090; case 0x91: return 0x2018;
            case 0x92: return 0x2019; case 0x93: return 0x201C;
            case 0x94: return 0x201D; case 0x95: return 0x2022;
            case 0x96: return 0x2013; case 0x97: return 0x2014;
            case 0x98: return 0x02DC; case 0x99: return 0x2122;
            case 0x9A: return 0x0161; case 0x9B: return 0x203A;
            case 0x9C: return 0x0153; case 0x9D: return 0x009D;
            case 0x9E: return 0x017E; case 0x9F: return 0x0178;
            default: return b;
        }
    }

    static String decodeEncodedWords(String text) {
        if (text == null) return null;
        StringBuilder result = new StringBuilder();
        int pos = 0;
        while (pos < text.length()) {
            int ewStart = findEncodedWordStart(text, pos);
            if (ewStart < 0) {
                result.append(text, pos, text.length());
                break;
            }
            result.append(text, pos, ewStart);
            // Collect maximal run of adjacent encoded words with same charset
            List<String> wordBytes = new ArrayList<>();
            List<int[]> wordPositions = new ArrayList<>();
            String runCharset = null;
            int cur = ewStart;
            while (cur < text.length()) {
                int[] match = matchEncodedWord(text, cur);
                if (match == null) break;
                int mStart = match[0], mEnd = match[1];
                String cs = match[2] != null ? normalizeCharset(text.substring(match[2], match[3])) : null;
                String enc = text.substring(match[4], match[5]);
                String encText = text.substring(match[6], match[7]);
                if (runCharset == null) {
                    runCharset = cs;
                } else if (!runCharset.equalsIgnoreCase(cs)) {
                    break;
                }
                if (!wordBytes.isEmpty()) {
                    // Check adjacency: only spaces/tabs between previous word end and this word start
                    for (int i = wordPositions.get(wordPositions.size() - 1)[1]; i < mStart; i++) {
                        if (text.charAt(i) != ' ' && text.charAt(i) != '\t') {
                            // Not adjacent, break
                            mStart = -1;
                            break;
                        }
                    }
                    if (mStart == -1) break;
                }
                byte[] bytes;
                if (enc.equalsIgnoreCase("B")) {
                    bytes = decodeBase64(encText.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
                } else {
                    bytes = decodeQEncoding(encText);
                }
                wordBytes.add(new String(bytes, java.nio.charset.StandardCharsets.ISO_8859_1));
                wordPositions.add(new int[]{mStart, mEnd});
                cur = mEnd;
            }
            if (wordBytes.isEmpty()) {
                result.append(text.charAt(ewStart));
                pos = ewStart + 1;
            } else {
                StringBuilder allBytes = new StringBuilder();
                for (String s : wordBytes) allBytes.append(s);
                String decoded = decodeCharset(allBytes.toString().getBytes(java.nio.charset.StandardCharsets.ISO_8859_1), runCharset);
                result.append(decoded);
                pos = wordPositions.get(wordPositions.size() - 1)[1];
            }
        }
        return result.toString();
    }

    static int findEncodedWordStart(String text, int from) {
        int idx = text.indexOf("=?", from);
        while (idx >= 0) {
            if (matchEncodedWord(text, idx) != null) return idx;
            idx = text.indexOf("=?", idx + 1);
        }
        return -1;
    }

    // Returns [start, end, csStart, csEnd, encStart, encEnd, txtStart, txtEnd] or null
    static int[] matchEncodedWord(String text, int pos) {
        if (pos + 2 > text.length() || text.charAt(pos) != '=' || text.charAt(pos + 1) != '?') return null;
        int i = pos + 2;
        int csStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int csEnd = i;
        if (csEnd == csStart) return null;
        i++; // skip ?
        int encStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int encEnd = i;
        String enc = text.substring(encStart, encEnd);
        if (!enc.equals("B") && !enc.equals("b") && !enc.equals("Q") && !enc.equals("q")) return null;
        i++; // skip ?
        int txtStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int txtEnd = i;
        if (i + 1 >= text.length() || text.charAt(i + 1) != '=') return null;
        i += 2; // skip ?=
        return new int[]{pos, i, csStart, csEnd, encStart, encEnd, txtStart, txtEnd};
    }

    static String normalizeCharset(String cs) {
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs.toLowerCase();
    }

    static byte[] decodeQEncoding(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '_') {
                out.write(0x20);
            } else if (c == '=' && i + 2 < s.length()) {
                int hi = hexVal(s.charAt(i + 1));
                int lo = hexVal(s.charAt(i + 2));
                if (hi >= 0 && lo >= 0) {
                    out.write((hi << 4) | lo);
                    i += 2;
                } else {
                    out.write('=');
                }
            } else {
                out.write(c & 0xFF);
            }
        }
        return out.toByteArray();
    }

    static String quoted(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }

    static class Entity {
        Map<String, String> headers;
        byte[] body;
        List<Entity> parts;
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static String LB;

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".eml"));
        if (files == null) files = new File[0];
        Arrays.sort(files, Comparator.comparing(File::getName));
        for (int i = 0; i < files.length; i++) {
            if (i > 0) System.out.println();
            processFile(files[i]);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        LB = detectLB(data);
        Entity msg = parseEntity(data);
        System.out.println("== " + f.getName());
        String from = getHeader(msg, "from");
        String subj = getHeader(msg, "subject");
        System.out.println("From: " + (from == null ? "-" : quoted(decodeEncodedWords(from))));
        System.out.println("Subject: " + (subj == null ? "-" : quoted(decodeEncodedWords(subj))));
        printEntity(msg, 0);
    }

    static String detectLB(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == '\r' && data[i + 1] == '\n') return "\r\n";
        }
        return "\n";
    }

    static List<String> splitLines(byte[] data) {
        List<String> lines = new ArrayList<>();
        byte[] lb = LB.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
        int i = 0;
        while (i <= data.length) {
            int j = i;
            while (j + lb.length <= data.length) {
                boolean match = true;
                for (int k = 0; k < lb.length; k++) {
                    if (data[j + k] != lb[k]) { match = false; break; }
                }
                if (match) break;
                j++;
            }
            if (j + lb.length <= data.length) {
                boolean match = true;
                for (int k = 0; k < lb.length; k++) {
                    if (data[j + k] != lb[k]) { match = false; break; }
                }
                if (match) {
                    lines.add(new String(data, i, j - i, java.nio.charset.StandardCharsets.ISO_8859_1));
                    i = j + lb.length;
                    continue;
                }
            }
            lines.add(new String(data, i, data.length - i, java.nio.charset.StandardCharsets.ISO_8859_1));
            break;
        }
        return lines;
    }

    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();
        List<String> lines = splitLines(data);
        int sep = -1;
        for (int i = 0; i < lines.size(); i++) {
            if (lines.get(i).isEmpty()) { sep = i; break; }
        }
        List<String> headerLines;
        byte[] bodyBytes;
        if (sep < 0) {
            headerLines = lines;
            bodyBytes = new byte[0];
        } else {
            headerLines = lines.subList(0, sep);
            List<String> bodyLines = lines.subList(sep + 1, lines.size());
            if (bodyLines.isEmpty()) {
                bodyBytes = new byte[0];
            } else {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < bodyLines.size(); i++) {
                    if (i > 0) sb.append(LB);
                    sb.append(bodyLines.get(i));
                }
                bodyBytes = sb.toString().getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            }
        }
        e.headers = parseHeaders(headerLines);
        e.body = bodyBytes;
        String ct = getHeader(e, "content-type");
        if (ct != null) {
            String[] ts = parseTypeSubtype(ct);
            if (ts[0].equals("multipart")) {
                Map<String, String> params = parseParams(ct);
                String boundary = params.get("boundary");
                if (boundary != null) {
                    e.parts = parseMultipart(e.body, boundary);
                } else {
                    e.parts = new ArrayList<>();
                }
            }
        }
        return e;
    }

    static Map<String, String> parseHeaders(List<String> lines) {
        List<String> unfolded = new ArrayList<>();
        for (String line : lines) {
            if (!line.isEmpty() && (line.charAt(0) == ' ' || line.charAt(0) == '\t')) {
                if (!unfolded.isEmpty()) {
                    unfolded.set(unfolded.size() - 1, unfolded.get(unfolded.size() - 1) + line);
                } else {
                    unfolded.add(line);
                }
            } else {
                unfolded.add(line);
            }
        }
        Map<String, String> map = new LinkedHashMap<>();
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String value = line.substring(colon + 1);
            int start = 0, end = value.length();
            while (start < end && (value.charAt(start) == ' ' || value.charAt(start) == '\t')) start++;
            while (end > start && (value.charAt(end - 1) == ' ' || value.charAt(end - 1) == '\t')) end--;
            value = value.substring(start, end);
            map.put(name, value);
        }
        return map;
    }

    static String getHeader(Entity e, String name) {
        return e.headers.get(name.toLowerCase());
    }

    static String[] parseTypeSubtype(String value) {
        String v = value.trim();
        int slash = v.indexOf('/');
        if (slash < 0) return new String[]{"text", "plain"};
        String type = v.substring(0, slash).trim().toLowerCase();
        String rest = v.substring(slash + 1);
        int semi = findParamStart(rest);
        String subtype;
        if (semi < 0) {
            subtype = rest.trim().toLowerCase();
        } else {
            subtype = rest.substring(0, semi).trim().toLowerCase();
        }
        return new String[]{type, subtype};
    }

    static int findParamStart(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == ';') return i;
        }
        return -1;
    }

    static Map<String, String> parseParams(String value) {
        Map<String, String> params = new LinkedHashMap<>();
        int semi = findParamStart(value);
        if (semi < 0) return params;
        int pos = semi;
        while (pos < value.length()) {
            while (pos < value.length() && (value.charAt(pos) == ';' || value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
            if (pos >= value.length()) break;
            int nameStart = pos;
            while (pos < value.length() && value.charAt(pos) != '=' && value.charAt(pos) != ';' && value.charAt(pos) != ' ' && value.charAt(pos) != '\t') pos++;
            String name = value.substring(nameStart, pos).trim().toLowerCase();
            while (pos < value.length() && (value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
            if (pos < value.length() && value.charAt(pos) == '=') {
                pos++;
                while (pos < value.length() && (value.charAt(pos) == ' ' || value.charAt(pos) == '\t')) pos++;
                String val;
                if (pos < value.length() && value.charAt(pos) == '"') {
                    pos++;
                    StringBuilder sb = new StringBuilder();
                    while (pos < value.length() && value.charAt(pos) != '"') {
                        if (value.charAt(pos) == '\\' && pos + 1 < value.length()) {
                            sb.append(value.charAt(pos + 1));
                            pos += 2;
                        } else {
                            sb.append(value.charAt(pos));
                            pos++;
                        }
                    }
                    if (pos < value.length()) pos++;
                    val = sb.toString();
                } else {
                    int vStart = pos;
                    while (pos < value.length() && value.charAt(pos) != ';' && value.charAt(pos) != ' ' && value.charAt(pos) != '\t') pos++;
                    val = value.substring(vStart, pos);
                }
                params.put(name, val);
            } else {
                params.put(name, "");
            }
        }
        return params;
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<String> lines = splitLines(body);
        String delim = "--" + boundary;
        String closeDelim = delim + "--";
        List<int[]> delimPositions = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (isCloseDelimiter(line, closeDelim)) {
                delimPositions.add(new int[]{i, 1});
            } else if (isDelimiter(line, delim)) {
                delimPositions.add(new int[]{i, 0});
            }
        }
        List<Entity> parts = new ArrayList<>();
        for (int i = 0; i < delimPositions.size() - 1; i++) {
            int startLine = delimPositions.get(i)[0];
            int endLine = delimPositions.get(i + 1)[0];
            if (delimPositions.get(i)[1] == 1) break;
            List<String> partLines = lines.subList(startLine + 1, endLine);
            byte[] partData;
            if (partLines.isEmpty()) {
                partData = new byte[0];
            } else {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < partLines.size(); j++) {
                    if (j > 0) sb.append(LB);
                    sb.append(partLines.get(j));
                }
                partData = sb.toString().getBytes(java.nio.charset.StandardCharsets.ISO_8859_1);
            }
            parts.add(parseEntity(partData));
        }
        return parts;
    }

    static boolean isDelimiter(String line, String delim) {
        if (!line.startsWith(delim)) return false;
        String rest = line.substring(delim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static boolean isCloseDelimiter(String line, String closeDelim) {
        if (!line.startsWith(closeDelim)) return false;
        String rest = line.substring(closeDelim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static void printEntity(Entity e, int indent) {
        String pad = "  ".repeat(indent);
        String ct = getHeader(e, "content-type");
        String[] ts;
        if (ct != null) {
            ts = parseTypeSubtype(ct);
        } else {
            ts = new String[]{"text", "plain"};
        }
        String type = ts[0], subtype = ts[1];

        if (e.parts != null) {
            System.out.println(pad + "multipart/" + subtype + " parts=" + e.parts.size());
            for (Entity p : e.parts) {
                printEntity(p, indent + 1);
            }
            return;
        }

        String cte = getHeader(e, "content-transfer-encoding");
        if (cte == null) cte = "7bit";
        cte = cte.trim().toLowerCase();

        String cd = getHeader(e, "content-disposition");
        String dispType = null;
        Map<String, String> cdParams = null;
        if (cd != null) {
            int semi = findParamStart(cd);
            dispType = (semi < 0 ? cd : cd.substring(0, semi)).trim().toLowerCase();
            cdParams = parseParams(cd);
        }

        Map<String, String> ctParams = ct != null ? parseParams(ct) : new LinkedHashMap<>();

        if (type.equals("text") && !"attachment".equals(dispType)) {
            String charset = ctParams.getOrDefault("charset", "us-ascii").toLowerCase();
            byte[] decoded = decodeCTE(e.body, cte);
            String text = decodeCharset(decoded, charset);
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(pad + "text/" + subtype + " charset=" + charset + " cte=" + cte + " chars=" + chars);
            System.out.println("  ".repeat(indent + 1) + quoted(text));
        } else {
            byte[] decoded = decodeCTE(e.body, cte);
            CRC32 crc = new CRC32();
            crc.update(decoded);
            String name = getFileName(e, cdParams, ctParams);
            String nameStr = name == null ? "-" : quoted(name);
            System.out.println(pad + type + "/" + subtype + " cte=" + cte +
                    " disposition=" + (dispType == null ? "-" : dispType) +
                    " name=" + nameStr +
                    " size=" + decoded.length +
                    " crc32=" + String.format("%08x", crc.getValue()));
        }
    }

    static String getFileName(Entity e, Map<String, String> cdParams, Map<String, String> ctParams) {
        String r;
        r = getRFC2231(cdParams, "filename");
        if (r != null) return r;
        if (cdParams != null && cdParams.containsKey("filename")) {
            return decodeEncodedWords(cdParams.get("filename"));
        }
        r = getRFC2231(ctParams, "name");
        if (r != null) return r;
        if (ctParams != null && ctParams.containsKey("name")) {
            return decodeEncodedWords(ctParams.get("name"));
        }
        return null;
    }

    static String getRFC2231(Map<String, String> params, String attr) {
        if (params == null) return null;
        attr = attr.toLowerCase();
        if (params.containsKey(attr + "*")) {
            String val = params.get(attr + "*");
            String charset = extractCharsetFromPct(val);
            byte[] bytes = percentDecode(stripCharsetLang(val));
            return decodeCharset(bytes, charset);
        }
        List<String> segments = new ArrayList<>();
        List<Boolean> pctFlags = new ArrayList<>();
        int i = 0;
        boolean anyPct = false;
        while (true) {
            String pctKey = attr + "*" + i + "*";
            String plainKey = attr + "*" + i;
            if (params.containsKey(pctKey)) {
                segments.add(params.get(pctKey));
                pctFlags.add(true);
                anyPct = true;
            } else if (params.containsKey(plainKey)) {
                segments.add(params.get(plainKey));
                pctFlags.add(false);
            } else {
                break;
            }
            i++;
        }
        if (segments.isEmpty()) return null;
        String charset = "us-ascii";
        if (anyPct) {
            for (int j = 0; j < segments.size(); j++) {
                if (pctFlags.get(j)) {
                    charset = extractCharsetFromPct(segments.get(j));
                    break;
                }
            }
        }
        byte[] result = new byte[0];
        boolean stripped = false;
        for (int j = 0; j < segments.size(); j++) {
            String seg = segments.get(j);
            if (pctFlags.get(j)) {
                if (!stripped) {
                    seg = stripCharsetLang(seg);
                    stripped = true;
                }
                result = concat(result, percentDecode(seg));
            } else {
                result = concat(result, seg.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
            }
        }
        return decodeCharset(result, charset);
    }

    static String extractCharsetFromPct(String val) {
        int q1 = val.indexOf('\'');
        if (q1 < 0) return "us-ascii";
        int q2 = val.indexOf('\'', q1 + 1);
        if (q2 < 0) return "us-ascii";
        String cs = val.substring(0, q1);
        if (cs.isEmpty()) return "us-ascii";
        return cs.toLowerCase();
    }

    static String stripCharsetLang(String val) {
        int q1 = val.indexOf('\'');
        if (q1 < 0) return val;
        int q2 = val.indexOf('\'', q1 + 1);
        if (q2 < 0) return val;
        return val.substring(q2 + 1);
    }

    static byte[] percentDecode(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '%' && i + 2 < s.length()) {
                int hi = hexVal(s.charAt(i + 1));
                int lo = hexVal(s.charAt(i + 2));
                if (hi >= 0 && lo >= 0) {
                    out.write((hi << 4) | lo);
                    i += 2;
                } else {
                    out.write(s.charAt(i));
                }
            } else {
                out.write(s.charAt(i) & 0xFF);
            }
        }
        return out.toByteArray();
    }

    static byte[] concat(byte[] a, byte[] b) {
        byte[] r = new byte[a.length + b.length];
        System.arraycopy(a, 0, r, 0, a.length);
        System.arraycopy(b, 0, r, a.length, b.length);
        return r;
    }

    static int hexVal(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    }

    static byte[] decodeCTE(byte[] data, String encoding) {
        switch (encoding) {
            case "base64": return decodeBase64(data);
            case "quoted-printable": return decodeQP(data);
            default: return data;
        }
    }

    static byte[] decodeBase64(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            char c = (char) (b & 0xFF);
            if (c == '=') break;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            }
        }
        String s = sb.toString();
        int len = s.length();
        int fullGroups = len / 4;
        int remainder = len % 4;
        int outLen = fullGroups * 3 + (remainder == 2 ? 1 : remainder == 3 ? 2 : 0);
        byte[] out = new byte[outLen];
        int oi = 0;
        for (int i = 0; i < fullGroups; i++) {
            int v = (b64Val(s.charAt(i * 4)) << 18) | (b64Val(s.charAt(i * 4 + 1)) << 12) |
                    (b64Val(s.charAt(i * 4 + 2)) << 6) | b64Val(s.charAt(i * 4 + 3));
            out[oi++] = (byte) (v >> 16);
            out[oi++] = (byte) (v >> 8);
            out[oi++] = (byte) v;
        }
        if (remainder == 2) {
            int v = (b64Val(s.charAt(fullGroups * 4)) << 18) | (b64Val(s.charAt(fullGroups * 4 + 1)) << 12);
            out[oi++] = (byte) (v >> 16);
        } else if (remainder == 3) {
            int v = (b64Val(s.charAt(fullGroups * 4)) << 18) | (b64Val(s.charAt(fullGroups * 4 + 1)) << 12) |
                    (b64Val(s.charAt(fullGroups * 4 + 2)) << 6);
            out[oi++] = (byte) (v >> 16);
            out[oi++] = (byte) (v >> 8);
        }
        return out;
    }

    static int b64Val(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return 0;
    }

    static byte[] decodeQP(byte[] data) {
        String s = new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
        List<String> lines = new ArrayList<>();
        int pos = 0;
        while (pos < s.length()) {
            int nl = s.indexOf('\n', pos);
            if (nl < 0) {
                lines.add(s.substring(pos));
                break;
            }
            String line = s.substring(pos, nl);
            if (line.endsWith("\r")) line = line.substring(0, line.length() - 1);
            lines.add(line);
            pos = nl + 1;
        }
        if (s.endsWith("\n")) {
            lines.add("");
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int li = 0; li < lines.size(); li++) {
            String line = lines.get(li);
            int end = line.length();
            while (end > 0 && (line.charAt(end - 1) == ' ' || line.charAt(end - 1) == '\t')) end--;
            line = line.substring(0, end);
            boolean softBreak = line.endsWith("=");
            int processLen = softBreak ? line.length() - 1 : line.length();
            for (int i = 0; i < processLen; i++) {
                if (line.charAt(i) == '=') {
                    if (i + 2 < processLen) {
                        int hi = hexVal(line.charAt(i + 1));
                        int lo = hexVal(line.charAt(i + 2));
                        if (hi >= 0 && lo >= 0) {
                            out.write((hi << 4) | lo);
                            i += 2;
                        } else {
                            out.write('=');
                        }
                    } else {
                        out.write('=');
                    }
                } else {
                    out.write(line.charAt(i) & 0xFF);
                }
            }
            if (li < lines.size() - 1) {
                if (!softBreak) {
                    out.write('\n');
                }
            }
        }
        return out.toByteArray();
    }

    static String decodeCharset(byte[] data, String charset) {
        charset = charset.toLowerCase().trim();
        switch (charset) {
            case "us-ascii":
            case "ascii": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
            case "utf-8":
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            case "iso-8859-1":
            case "latin1":
            case "latin-1": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
            case "windows-1252":
            case "cp1252": {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) {
                    int b = data[i] & 0xFF;
                    if (b >= 0x80 && b <= 0x9F) {
                        cs[i] = (char) cp1252(b);
                    } else {
                        cs[i] = (char) b;
                    }
                }
                return new String(cs);
            }
            default: {
                char[] cs = new char[data.length];
                for (int i = 0; i < data.length; i++) cs[i] = (char) (data[i] & 0xFF);
                return new String(cs);
            }
        }
    }

    static int cp1252(int b) {
        switch (b) {
            case 0x80: return 0x20AC; case 0x81: return 0x0081;
            case 0x82: return 0x201A; case 0x83: return 0x0192;
            case 0x84: return 0x201E; case 0x85: return 0x2026;
            case 0x86: return 0x2020; case 0x87: return 0x2021;
            case 0x88: return 0x02C6; case 0x89: return 0x2030;
            case 0x8A: return 0x0160; case 0x8B: return 0x2039;
            case 0x8C: return 0x0152; case 0x8D: return 0x008D;
            case 0x8E: return 0x017D; case 0x8F: return 0x008F;
            case 0x90: return 0x0090; case 0x91: return 0x2018;
            case 0x92: return 0x2019; case 0x93: return 0x201C;
            case 0x94: return 0x201D; case 0x95: return 0x2022;
            case 0x96: return 0x2013; case 0x97: return 0x2014;
            case 0x98: return 0x02DC; case 0x99: return 0x2122;
            case 0x9A: return 0x0161; case 0x9B: return 0x203A;
            case 0x9C: return 0x0153; case 0x9D: return 0x009D;
            case 0x9E: return 0x017E; case 0x9F: return 0x0178;
            default: return b;
        }
    }

    static String decodeEncodedWords(String text) {
        if (text == null) return null;
        StringBuilder result = new StringBuilder();
        int pos = 0;
        while (pos < text.length()) {
            int ewStart = findEncodedWordStart(text, pos);
            if (ewStart < 0) {
                result.append(text, pos, text.length());
                break;
            }
            result.append(text, pos, ewStart);
            List<byte[]> wordBytes = new ArrayList<>();
            List<int[]> wordPositions = new ArrayList<>();
            String runCharset = null;
            int cur = ewStart;
            while (cur < text.length()) {
                int[] match = matchEncodedWord(text, cur);
                if (match == null) break;
                int mStart = match[0], mEnd = match[1];
                String cs = normalizeCharset(text.substring(match[2], match[3]));
                String enc = text.substring(match[4], match[5]);
                String encText = text.substring(match[6], match[7]);
                if (runCharset == null) {
                    runCharset = cs;
                } else if (!runCharset.equalsIgnoreCase(cs)) {
                    break;
                }
                if (!wordBytes.isEmpty()) {
                    int prevEnd = wordPositions.get(wordPositions.size() - 1)[1];
                    boolean adjacent = true;
                    for (int i = prevEnd; i < mStart; i++) {
                        if (text.charAt(i) != ' ' && text.charAt(i) != '\t') {
                            adjacent = false;
                            break;
                        }
                    }
                    if (!adjacent) break;
                }
                byte[] bytes;
                if (enc.equalsIgnoreCase("B")) {
                    bytes = decodeBase64(encText.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
                } else {
                    bytes = decodeQEncoding(encText);
                }
                wordBytes.add(bytes);
                wordPositions.add(new int[]{mStart, mEnd});
                cur = mEnd;
            }
            if (wordBytes.isEmpty()) {
                result.append(text.charAt(ewStart));
                pos = ewStart + 1;
            } else {
                ByteArrayOutputStream allBytes = new ByteArrayOutputStream();
                for (byte[] b : wordBytes) allBytes.write(b, 0, b.length);
                String decoded = decodeCharset(allBytes.toByteArray(), runCharset);
                result.append(decoded);
                pos = wordPositions.get(wordPositions.size() - 1)[1];
            }
        }
        return result.toString();
    }

    static int findEncodedWordStart(String text, int from) {
        int idx = text.indexOf("=?", from);
        while (idx >= 0) {
            if (matchEncodedWord(text, idx) != null) return idx;
            idx = text.indexOf("=?", idx + 1);
        }
        return -1;
    }

    static int[] matchEncodedWord(String text, int pos) {
        if (pos + 2 > text.length() || text.charAt(pos) != '=' || text.charAt(pos + 1) != '?') return null;
        int i = pos + 2;
        int csStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int csEnd = i;
        if (csEnd == csStart) return null;
        i++;
        int encStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int encEnd = i;
        String enc = text.substring(encStart, encEnd);
        if (!enc.equals("B") && !enc.equals("b") && !enc.equals("Q") && !enc.equals("q")) return null;
        i++;
        int txtStart = i;
        while (i < text.length() && text.charAt(i) != '?' && text.charAt(i) != ' ' && text.charAt(i) != '\t') i++;
        if (i >= text.length() || text.charAt(i) != '?') return null;
        int txtEnd = i;
        if (i + 1 >= text.length() || text.charAt(i + 1) != '=') return null;
        i += 2;
        return new int[]{pos, i, csStart, csEnd, encStart, encEnd, txtStart, txtEnd};
    }

    static String normalizeCharset(String cs) {
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs.toLowerCase();
    }

    static byte[] decodeQEncoding(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '_') {
                out.write(0x20);
            } else if (c == '=' && i + 2 < s.length()) {
                int hi = hexVal(s.charAt(i + 1));
                int lo = hexVal(s.charAt(i + 2));
                if (hi >= 0 && lo >= 0) {
                    out.write((hi << 4) | lo);
                    i += 2;
                } else {
                    out.write('=');
                }
            } else {
                out.write(c & 0xFF);
            }
        }
        return out.toByteArray();
    }

    static String quoted(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }

    static class Entity {
        Map<String, String> headers;
        byte[] body;
        List<Entity> parts;
    }
}

import * as fs from 'fs';
import * as path from 'path';

// CRC-32 (zlib/PNG)
const crcTable: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c >>> 0;
}
function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Base64 decode
function base64Decode(s: string): Buffer {
  let filtered = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '=') break;
    if (/[A-Za-z0-9+\/]/.test(c)) filtered += c;
  }
  return Buffer.from(filtered, 'base64');
}

// Quoted-printable decode
function qpDecode(buf: Buffer): Buffer {
  const text = buf.toString('binary');
  const lines = text.split(/\r\n|\n/);
  // Remove trailing spaces/tabs from each line
  for (let i = 0; i < lines.length; i++) {
    lines[i] = lines[i].replace(/[ \t]+$/, '');
  }
  // Join soft line breaks
  const joined: string[] = [];
  let i = 0;
  while (i < lines.length) {
    let cur = lines[i];
    while (cur.endsWith('=') && i + 1 < lines.length) {
      cur = cur.slice(0, -1) + lines[i + 1];
      i++;
    }
    joined.push(cur);
    i++;
  }
  // Decode =XY
  const result: number[] = [];
  for (let j = 0; j < joined.length; j++) {
    const line = joined[j];
    let k = 0;
    while (k < line.length) {
      if (line[k] === '=' && k + 2 < line.length) {
        const hex = line.slice(k + 1, k + 3);
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          result.push(parseInt(hex, 16));
          k += 3;
        } else {
          result.push(line.charCodeAt(k));
          k++;
        }
      } else {
        result.push(line.charCodeAt(k));
        k++;
      }
    }
    if (j < joined.length - 1) {
      result.push(0x0A); // keep line break
    }
  }
  return Buffer.from(result);
}

// Windows-1252 table for 0x80-0x9F
const win1252: number[] = [
  0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
  0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
  0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
  0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
];

function decodeCharset(buf: Buffer, charset: string): string {
  const cs = charset.toLowerCase();
  if (cs === 'us-ascii' || cs === 'ascii') {
    let s = '';
    for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
    return s;
  }
  if (cs === 'utf-8' || cs === 'utf8') {
    return buf.toString('utf-8');
  }
  if (cs === 'iso-8859-1' || cs === 'latin1' || cs === 'latin-1') {
    let s = '';
    for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
    return s;
  }
  if (cs === 'windows-1252' || cs === 'cp1252') {
    let s = '';
    for (let i = 0; i < buf.length; i++) {
      const b = buf[i];
      if (b >= 0x80 && b <= 0x9F) {
        s += String.fromCharCode(win1252[b - 0x80]);
      } else {
        s += String.fromCharCode(b);
      }
    }
    return s;
  }
  // fallback: treat as latin1
  let s = '';
  for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
  return s;
}

// RFC 2047 encoded-word decoding
function decodeRfc2047(text: string): string {
  const ewRegex = /=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=/g;
  interface Token { type: 'ew'; charset: string; bytes: number[]; start: number; end: number; }
  interface TextToken { type: 'text'; text: string; start: number; end: number; }
  const tokens: (Token | TextToken)[] = [];
  let lastEnd = 0;
  let m: RegExpExecArray | null;
  ewRegex.lastIndex = 0;
  while ((m = ewRegex.exec(text)) !== null) {
    if (m.index > lastEnd) {
      tokens.push({ type: 'text', text: text.slice(lastEnd, m.index), start: lastEnd, end: m.index });
    }
    const charset = m[1];
    const enc = m[2].toUpperCase();
    const encText = m[3];
    let bytes: number[];
    if (enc === 'B') {
      const decoded = base64Decode(encText);
      bytes = Array.from(decoded);
    } else {
      bytes = [];
      for (let i = 0; i < encText.length; i++) {
        if (encText[i] === '_') {
          bytes.push(0x20);
        } else if (encText[i] === '=' && i + 2 < encText.length && /^[0-9A-Fa-f]{2}$/.test(encText.slice(i+1, i+3))) {
          bytes.push(parseInt(encText.slice(i+1, i+3), 16));
          i += 2;
        } else {
          bytes.push(encText.charCodeAt(i));
        }
      }
    }
    tokens.push({ type: 'ew', charset, bytes, start: m.index, end: m.index + m[0].length });
    lastEnd = m.index + m[0].length;
  }
  if (lastEnd < text.length) {
    tokens.push({ type: 'text', text: text.slice(lastEnd), start: lastEnd, end: text.length });
  }
  // Group adjacent encoded-words with same charset
  function normalizeCharset(cs: string): string {
    const idx = cs.indexOf('*');
    return (idx >= 0 ? cs.slice(0, idx) : cs).toLowerCase();
  }
  const result: string[] = [];
  let ti = 0;
  while (ti < tokens.length) {
    if (tokens[ti].type === 'text') {
      result.push((tokens[ti] as TextToken).text);
      ti++;
    } else {
      // Collect adjacent encoded-words with same charset
      const group: Token[] = [tokens[ti] as Token];
      const normCs = normalizeCharset((tokens[ti] as Token).charset);
      let j = ti + 1;
      while (j < tokens.length) {
        // Check if only spaces/tabs between previous ew and this token
        const prevEnd = group[group.length - 1].end;
        if (tokens[j].type === 'text') {
          const t = (tokens[j] as TextToken).text;
          if (t === '' || /^[ \t]+$/.test(t)) {
            // Check if next token is an ew with same charset
            if (j + 1 < tokens.length && tokens[j + 1].type === 'ew' &&
                normalizeCharset((tokens[j + 1] as Token).charset) === normCs) {
              group.push(tokens[j + 1] as Token);
              j += 2;
            } else {
              break;
            }
          } else {
            break;
          }
        } else if (tokens[j].type === 'ew' && normalizeCharset((tokens[j] as Token).charset) === normCs) {
          group.push(tokens[j] as Token);
          j++;
        } else {
          break;
        }
      }
      // Concatenate bytes and decode
      const allBytes: number[] = [];
      for (const g of group) {
        for (const b of g.bytes) allBytes.push(b);
      }
      const cs = group[0].charset;
      const actualCs = cs.indexOf('*') >= 0 ? cs.slice(0, cs.indexOf('*')) : cs;
      result.push(decodeCharset(Buffer.from(allBytes), actualCs));
      ti = j;
    }
  }
  return result.join('');
}

// Parse parameter value (token or quoted string)
function parseParamValue(s: string, pos: number): { value: string; pos: number } {
  // Skip spaces/tabs
  while (pos < s.length && (s[pos] === ' ' || s[pos] === '\t')) pos++;
  if (pos >= s.length) return { value: '', pos };
  if (s[pos] === '"') {
    pos++;
    let val = '';
    while (pos < s.length) {
      if (s[pos] === '\\' && pos + 1 < s.length) {
        val += s[pos + 1];
        pos += 2;
      } else if (s[pos] === '"') {
        pos++;
        break;
      } else {
        val += s[pos];
        pos++;
      }
    }
    return { value: val, pos };
  } else {
    let val = '';
    while (pos < s.length && s[pos] !== ';' && s[pos] !== ' ' && s[pos] !== '\t') {
      val += s[pos];
      pos++;
    }
    return { value: val, pos };
  }
}

interface ParsedParams {
  type: string;
  subtype: string;
  params: Map<string, string>;
  rfc2231: Map<string, Map<string, string>>; // attr -> (index -> value)
  rfc2231Encoded: Set<string>; // attrs that have encoded segments
}

function parseContentType(value: string): ParsedParams {
  const result: ParsedParams = { type: '', subtype: '', params: new Map(), rfc2231: new Map(), rfc2231Encoded: new Set() };
  // Parse type/subtype
  let pos = 0;
  while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
  let typeStr = '';
  while (pos < value.length && value[pos] !== '/' && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
    typeStr += value[pos]; pos++;
  }
  while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
  if (pos < value.length && value[pos] === '/') {
    pos++;
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    let subStr = '';
    while (pos < value.length && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
      subStr += value[pos]; pos++;
    }
    result.type = typeStr.toLowerCase();
    result.subtype = subStr.toLowerCase();
  } else {
    result.type = typeStr.toLowerCase();
    result.subtype = '';
  }
  // Parse parameters
  while (pos < value.length) {
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t' || value[pos] === ';')) pos++;
    if (pos >= value.length) break;
    // Parse attribute name
    let attr = '';
    while (pos < value.length && value[pos] !== '=' && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
      attr += value[pos]; pos++;
    }
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    if (pos >= value.length || value[pos] !== '=') continue;
    pos++; // skip =
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    const { value: pval, pos: newPos } = parseParamValue(value, pos);
    pos = newPos;
    const attrLower = attr.toLowerCase();
    // Check RFC 2231 form
    const rfc2231Match = attrLower.match(/^(.+)\*(\d+)(\*)?$/);
    const rfc2231Single = attrLower.match(/^(.+)\*$/);
    if (rfc2231Match) {
      const baseAttr = rfc2231Match[1];
      const idx = rfc2231Match[2];
      const isEncoded = rfc2231Match[3] === '*';
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set(idx, pval);
      if (isEncoded) result.rfc2231Encoded.add(baseAttr);
    } else if (rfc2231Single) {
      const baseAttr = rfc2231Single[1];
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set('0', pval);
      result.rfc2231Encoded.add(baseAttr);
    } else {
      result.params.set(attrLower, pval);
    }
  }
  return result;
}

function parseContentDisposition(value: string): { type: string; params: Map<string, string>; rfc2231: Map<string, Map<string, string>>; rfc2231Encoded: Set<string> } {
  const result = { type: '', params: new Map<string, string>(), rfc2231: new Map<string, Map<string, string>>(), rfc2231Encoded: new Set<string>() };
  let pos = 0;
  while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
  let dispType = '';
  while (pos < value.length && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
    dispType += value[pos]; pos++;
  }
  result.type = dispType.toLowerCase();
  while (pos < value.length) {
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t' || value[pos] === ';')) pos++;
    if (pos >= value.length) break;
    let attr = '';
    while (pos < value.length && value[pos] !== '=' && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
      attr += value[pos]; pos++;
    }
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    if (pos >= value.length || value[pos] !== '=') continue;
    pos++;
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    const { value: pval, pos: newPos } = parseParamValue(value, pos);
    pos = newPos;
    const attrLower = attr.toLowerCase();
    const rfc2231Match = attrLower.match(/^(.+)\*(\d+)(\*)?$/);
    const rfc2231Single = attrLower.match(/^(.+)\*$/);
    if (rfc2231Match) {
      const baseAttr = rfc2231Match[1];
      const idx = rfc2231Match[2];
      const isEncoded = rfc2231Match[3] === '*';
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set(idx, pval);
      if (isEncoded) result.rfc2231Encoded.add(baseAttr);
    } else if (rfc2231Single) {
      const baseAttr = rfc2231Single[1];
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set('0', pval);
      result.rfc2231Encoded.add(baseAttr);
    } else {
      result.params.set(attrLower, pval);
    }
  }
  return result;
}

// RFC 2231 decode
function decodeRfc2231(segments: Map<string, string>, encoded: boolean): string {
  const indices = Array.from(segments.keys()).sort((a, b) => parseInt(a) - parseInt(b));
  let bytes: number[] = [];
  let charset = 'us-ascii';
  let firstEncoded = true;
  for (const idx of indices) {
    const val = segments.get(idx)!;
    if (encoded) {
      let s = val;
      if (firstEncoded) {
        // charset'language'value
        const q1 = s.indexOf("'");
        if (q1 >= 0) {
          const q2 = s.indexOf("'", q1 + 1);
          if (q2 >= 0) {
            charset = s.slice(0, q1) || 'us-ascii';
            s = s.slice(q2 + 1);
          }
        }
        firstEncoded = false;
      }
      // Percent-decode
      let j = 0;
      while (j < s.length) {
        if (s[j] === '%' && j + 2 < s.length && /^[0-9A-Fa-f]{2}$/.test(s.slice(j+1, j+3))) {
          bytes.push(parseInt(s.slice(j+1, j+3), 16));
          j += 3;
        } else {
          bytes.push(s.charCodeAt(j));
          j++;
        }
      }
    } else {
      // Literal: each char is its own byte
      for (let j = 0; j < val.length; j++) {
        bytes.push(val.charCodeAt(j));
      }
    }
  }
  return decodeCharset(Buffer.from(bytes), charset);
}

function getFileName(cd: { params: Map<string, string>; rfc2231: Map<string, Map<string, string>>; rfc2231Encoded: Set<string> } | null,
                     ct: ParsedParams): string | null {
  // Check Content-Disposition filename RFC 2231
  if (cd && cd.rfc2231.has('filename')) {
    return decodeRfc2231(cd.rfc2231.get('filename')!, cd.rfc2231Encoded.has('filename'));
  }
  // Check Content-Disposition filename regular
  if (cd && cd.params.has('filename')) {
    return decodeRfc2047(cd.params.get('filename')!);
  }
  // Check Content-Type name RFC 2231
  if (ct.rfc2231.has('name')) {
    return decodeRfc2231(ct.rfc2231.get('name')!, ct.rfc2231Encoded.has('name'));
  }
  // Check Content-Type name regular
  if (ct.params.has('name')) {
    return decodeRfc2047(ct.params.get('name')!);
  }
  return null;
}

// Quoted string for output
function quoteStr(s: string): string {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20) out += '\\u' + cp.toString(16).padStart(4, '0');
    else if (cp >= 0x7F && cp <= 0x9F) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += ch;
  }
  out += '"';
  return out;
}

interface Entity {
  headers: Map<string, string>;
  body: Buffer;
  ct: ParsedParams;
  cd: { type: string; params: Map<string, string>; rfc2231: Map<string, Map<string, string>>; rfc2231Encoded: Set<string> } | null;
  cte: string;
  parts?: Entity[];
}

function splitLines(buf: Buffer, le: string): string[] {
  const leBuf = Buffer.from(le, 'binary');
  const lines: string[] = [];
  let start = 0;
  while (start <= buf.length) {
    const idx = buf.indexOf(leBuf, start);
    if (idx === -1) {
      lines.push(buf.slice(start).toString('binary'));
      break;
    }
    lines.push(buf.slice(start, idx).toString('binary'));
    start = idx + leBuf.length;
  }
  return lines;
}

function parseEntity(buf: Buffer, le: string, isTopLevel: boolean): Entity {
  const lines = splitLines(buf, le);
  // Find first empty line
  let sepIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] === '') { sepIdx = i; break; }
  }
  let headerLines: string[];
  let bodyBuf: Buffer;
  if (sepIdx === -1) {
    headerLines = lines;
    bodyBuf = Buffer.alloc(0);
  } else {
    headerLines = lines.slice(0, sepIdx);
    // Body: everything after the empty line
    if (isTopLevel) {
      // Body runs to end of file including final line break
      const headerEnd = sepIdx === 0 ? 0 : (() => {
        let pos = 0;
        for (let i = 0; i <= sepIdx; i++) {
          pos += Buffer.from(lines[i], 'binary').length;
          if (i < lines.length - 1 || (i === lines.length - 1 && buf.slice(pos).length > 0)) {
            // Check if there's a line ending after this line
            const leBuf = Buffer.from(le, 'binary');
            if (pos + leBuf.length <= buf.length && buf.slice(pos, pos + leBuf.length).equals(leBuf)) {
              pos += leBuf.length;
            }
          }
        }
        return pos;
      })();
      bodyBuf = buf.slice(headerEnd);
    } else {
      // Part body: lines after empty line, joined with le, no trailing le
      const bodyLines = lines.slice(sepIdx + 1);
      bodyBuf = Buffer.from(bodyLines.join(le), 'binary');
    }
  }
  // Unfold headers
  const unfolded: string[] = [];
  for (const line of headerLines) {
    if ((line.startsWith(' ') || line.startsWith('\t')) && unfolded.length > 0) {
      unfolded[unfolded.length - 1] += line;
    } else {
      unfolded.push(line);
    }
  }
  // Parse headers
  const headers = new Map<string, string>();
  for (const line of unfolded) {
    const colonIdx = line.indexOf(':');
    if (colonIdx >= 0) {
      const name = line.slice(0, colonIdx).toLowerCase();
      let val = line.slice(colonIdx + 1);
      val = val.replace(/^[ \t]+/, '').replace(/[ \t]+$/, '');
      headers.set(name, val);
    }
  }
  // Parse Content-Type
  const ctVal = headers.get('content-type') || 'text/plain';
  const ct = parseContentType(ctVal);
  if (!headers.has('content-type')) {
    ct.type = 'text';
    ct.subtype = 'plain';
    ct.params.set('charset', 'us-ascii');
  }
  // Parse Content-Disposition
  const cdVal = headers.get('content-disposition');
  const cd = cdVal ? parseContentDisposition(cdVal) : null;
  // CTE
  let cte = (headers.get('content-transfer-encoding') || '7bit').toLowerCase();
  if (ct.type === 'multipart') cte = '7bit';
  // Set default charset for text
  if (ct.type === 'text' && !ct.params.has('charset')) {
    ct.params.set('charset', 'us-ascii');
  }
  // Multipart: parse parts
  let parts: Entity[] | undefined;
  if (ct.type === 'multipart') {
    const boundary = ct.params.get('boundary') || '';
    parts = parseMultipart(bodyBuf, le, boundary);
  }
  return { headers, body: bodyBuf, ct, cd, cte, parts };
}

function parseMultipart(body: Buffer, le: string, boundary: string): Entity[] {
  const leBuf = Buffer.from(le, 'binary');
  const delimStr = `--${boundary}`;
  const closeStr = `--${boundary}--`;
  const lines = splitLines(body, le);
  // Find boundary line indices
  const boundaryIndices: { idx: number; isClose: boolean }[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === closeStr || (line.startsWith(closeStr) && /^[ \t]*$/.test(line.slice(closeStr.length)))) {
      boundaryIndices.push({ idx: i, isClose: true });
    } else if (line === delimStr || (line.startsWith(delimStr) && /^[ \t]*$/.test(line.slice(delimStr.length)))) {
      // Make sure it's not a close delimiter (already handled above)
      boundaryIndices.push({ idx: i, isClose: false });
    }
  }
  if (boundaryIndices.length === 0) return [];
  // Find first and last (close) delimiter
  let startIdx = 0;
  let endIdx = boundaryIndices.length - 1;
  // Parts are between consecutive boundary lines
  const parts: Entity[] = [];
  for (let i = 0; i < boundaryIndices.length - 1; i++) {
    const fromLine = boundaryIndices[i].idx + 1;
    const toLine = boundaryIndices[i + 1].idx;
    const partLines = lines.slice(fromLine, toLine);
    const partBuf = Buffer.from(partLines.join(le), 'binary');
    parts.push(parseEntity(partBuf, le, false));
  }
  // If last boundary is not close, add one more part from last boundary to end
  if (boundaryIndices.length > 0 && !boundaryIndices[boundaryIndices.length - 1].isClose) {
    const fromLine = boundaryIndices[boundaryIndices.length - 1].idx + 1;
    const partLines = lines.slice(fromLine);
    const partBuf = Buffer.from(partLines.join(le), 'binary');
    parts.push(parseEntity(partBuf, le, false));
  }
  return parts;
}

function decodeBody(entity: Entity): Buffer {
  const cte = entity.cte;
  if (cte === 'base64') {
    return base64Decode(entity.body.toString('binary'));
  } else if (cte === 'quoted-printable') {
    return qpDecode(entity.body);
  } else {
    // 7bit, 8bit, binary: raw bytes
    return entity.body;
  }
}

function decodeText(entity: Entity): string {
  const decoded = decodeBody(entity);
  const charset = entity.ct.params.get('charset') || 'us-ascii';
  let text = decodeCharset(decoded, charset);
  // Replace CRLF and lone CR with LF
  text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  return text;
}

function printEntity(entity: Entity, indent: number, output: string[]) {
  const prefix = '  '.repeat(indent);
  if (entity.ct.type === 'multipart') {
    const parts = entity.parts || [];
    output.push(`${prefix}multipart/${entity.ct.subtype} parts=${parts.length}`);
    for (const part of parts) {
      printEntity(part, indent + 1, output);
    }
  } else if (entity.ct.type === 'text' && (!entity.cd || entity.cd.type !== 'attachment')) {
    const charset = entity.ct.params.get('charset') || 'us-ascii';
    const text = decodeText(entity);
    const charCount = [...text].length; // Unicode code points
    output.push(`${prefix}text/${entity.ct.subtype} charset=${charset} cte=${entity.cte} chars=${charCount}`);
    output.push(`${prefix}  ${quoteStr(text)}`);
  } else {
    const decoded = decodeBody(entity);
    const size = decoded.length;
    const crc = crc32(decoded).toString(16).padStart(8, '0');
    const disp = entity.cd ? entity.cd.type : '-';
    const name = getFileName(entity.cd, entity.ct);
    const nameStr = name !== null ? quoteStr(name) : '-';
    output.push(`${prefix}${entity.ct.type}/${entity.ct.subtype} cte=${entity.cte} disposition=${disp} name=${nameStr} size=${size} crc32=${crc}`);
  }
}

function processFile(filePath: string, fileName: string): string[] {
  const buf = fs.readFileSync(filePath);
  // Detect line ending
  let le = '\n';
  for (let i = 0; i < buf.length - 1; i++) {
    if (buf[i] === 0x0D && buf[i + 1] === 0x0A) { le = '\r\n'; break; }
  }
  const entity = parseEntity(buf, le, true);
  const output: string[] = [];
  output.push(`== ${fileName}`);
  const from = entity.headers.get('from');
  const subject = entity.headers.get('subject');
  output.push(`From: ${from !== undefined ? quoteStr(decodeRfc2047(from)) : '-'}`);
  output.push(`Subject: ${subject !== undefined ? quoteStr(decodeRfc2047(subject)) : '-'}`);
  printEntity(entity, 0, output);
  return output;
}

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml'));
  files.sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));
  const outputs: string[] = [];
  for (let i = 0; i < files.length; i++) {
    if (i > 0) outputs.push('');
    const lines = processFile(path.join(dir, files[i]), files[i]);
    for (const l of lines) outputs.push(l);
  }
  process.stdout.write(outputs.join('\n') + '\n');
}

main();

import * as fs from 'fs';
import * as path from 'path';

// CRC-32 (zlib/PNG)
const crcTable: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c >>> 0;
}
function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Base64 decode
function base64Decode(s: string): Buffer {
  let filtered = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '=') break;
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c === '+' || c === '/') {
      filtered += c;
    }
  }
  return Buffer.from(filtered, 'base64');
}

// Quoted-printable decode
function qpDecode(buf: Buffer): Buffer {
  const text = buf.toString('binary');
  const lines = text.split(/\r\n|\n/);
  for (let i = 0; i < lines.length; i++) {
    lines[i] = lines[i].replace(/[ \t]+$/, '');
  }
  const joined: string[] = [];
  let i = 0;
  while (i < lines.length) {
    let cur = lines[i];
    while (cur.endsWith('=') && i + 1 < lines.length) {
      cur = cur.slice(0, -1) + lines[i + 1];
      i++;
    }
    joined.push(cur);
    i++;
  }
  const result: number[] = [];
  for (let j = 0; j < joined.length; j++) {
    const line = joined[j];
    let k = 0;
    while (k < line.length) {
      if (line[k] === '=' && k + 2 < line.length && /^[0-9A-Fa-f]{2}$/.test(line.slice(k + 1, k + 3))) {
        result.push(parseInt(line.slice(k + 1, k + 3), 16));
        k += 3;
      } else {
        result.push(line.charCodeAt(k));
        k++;
      }
    }
    if (j < joined.length - 1) {
      result.push(0x0A);
    }
  }
  return Buffer.from(result);
}

// Windows-1252 table for 0x80-0x9F
const win1252: number[] = [
  0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
  0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
  0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
  0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
];

function decodeCharset(buf: Buffer, charset: string): string {
  const cs = charset.toLowerCase();
  if (cs === 'us-ascii' || cs === 'ascii') {
    let s = '';
    for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
    return s;
  }
  if (cs === 'utf-8' || cs === 'utf8') {
    return buf.toString('utf-8');
  }
  if (cs === 'iso-8859-1' || cs === 'latin1' || cs === 'latin-1') {
    let s = '';
    for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
    return s;
  }
  if (cs === 'windows-1252' || cs === 'cp1252') {
    let s = '';
    for (let i = 0; i < buf.length; i++) {
      const b = buf[i];
      if (b >= 0x80 && b <= 0x9F) {
        s += String.fromCharCode(win1252[b - 0x80]);
      } else {
        s += String.fromCharCode(b);
      }
    }
    return s;
  }
  let s = '';
  for (let i = 0; i < buf.length; i++) s += String.fromCharCode(buf[i]);
  return s;
}

// RFC 2047 encoded-word decoding
function decodeRfc2047(text: string): string {
  interface EwMatch { start: number; end: number; charset: string; bytes: number[]; }
  const matches: EwMatch[] = [];
  const regex = /=\?([^?\s\t]+)\?([BbQq])\?([^?\s\t]*)\?=/g;
  let m: RegExpExecArray | null;
  regex.lastIndex = 0;
  while ((m = regex.exec(text)) !== null) {
    const charset = m[1];
    const enc = m[2].toUpperCase();
    const encText = m[3];
    let bytes: number[];
    if (enc === 'B') {
      bytes = Array.from(base64Decode(encText));
    } else {
      bytes = [];
      for (let i = 0; i < encText.length; i++) {
        if (encText[i] === '_') {
          bytes.push(0x20);
        } else if (encText[i] === '=' && i + 2 < encText.length && /^[0-9A-Fa-f]{2}$/.test(encText.slice(i + 1, i + 3))) {
          bytes.push(parseInt(encText.slice(i + 1, i + 3), 16));
          i += 2;
        } else {
          bytes.push(encText.charCodeAt(i));
        }
      }
    }
    matches.push({ start: m.index, end: m.index + m[0].length, charset, bytes });
  }

  function normCs(cs: string): string {
    const idx = cs.indexOf('*');
    return (idx >= 0 ? cs.slice(0, idx) : cs).toLowerCase();
  }

  // Group adjacent encoded-words with same charset
  const groups: { start: number; end: number; bytes: number[]; charset: string }[] = [];
  for (const match of matches) {
    const last = groups[groups.length - 1];
    if (last) {
      const between = text.slice(last.end, match.start);
      if (/^[ \t]*$/.test(between) && normCs(last.charset) === normCs(match.charset)) {
        last.end = match.end;
        for (const b of match.bytes) last.bytes.push(b);
        continue;
      }
    }
    groups.push({ start: match.start, end: match.end, bytes: [...match.bytes], charset: match.charset });
  }

  let result = '';
  let pos = 0;
  for (const g of groups) {
    result += text.slice(pos, g.start);
    const cs = g.charset;
    const actualCs = cs.indexOf('*') >= 0 ? cs.slice(0, cs.indexOf('*')) : cs;
    result += decodeCharset(Buffer.from(g.bytes), actualCs);
    pos = g.end;
  }
  result += text.slice(pos);
  return result;
}

// Parse parameter value (token or quoted string)
function parseParamValue(s: string, pos: number): { value: string; pos: number } {
  while (pos < s.length && (s[pos] === ' ' || s[pos] === '\t')) pos++;
  if (pos >= s.length) return { value: '', pos };
  if (s[pos] === '"') {
    pos++;
    let val = '';
    while (pos < s.length) {
      if (s[pos] === '\\' && pos + 1 < s.length) {
        val += s[pos + 1];
        pos += 2;
      } else if (s[pos] === '"') {
        pos++;
        break;
      } else {
        val += s[pos];
        pos++;
      }
    }
    return { value: val, pos };
  } else {
    let val = '';
    while (pos < s.length && s[pos] !== ';' && s[pos] !== ' ' && s[pos] !== '\t') {
      val += s[pos];
      pos++;
    }
    return { value: val, pos };
  }
}

interface ParsedParams {
  type: string;
  subtype: string;
  params: Map<string, string>;
  rfc2231: Map<string, Map<string, string>>;
  rfc2231Encoded: Set<string>;
}

function parseParams(value: string, isContentType: boolean): ParsedParams {
  const result: ParsedParams = { type: '', subtype: '', params: new Map(), rfc2231: new Map(), rfc2231Encoded: new Set() };
  let pos = 0;
  while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
  let typeStr = '';
  while (pos < value.length && value[pos] !== '/' && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
    typeStr += value[pos]; pos++;
  }
  while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
  if (isContentType && pos < value.length && value[pos] === '/') {
    pos++;
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    let subStr = '';
    while (pos < value.length && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
      subStr += value[pos]; pos++;
    }
    result.type = typeStr.toLowerCase();
    result.subtype = subStr.toLowerCase();
  } else {
    result.type = typeStr.toLowerCase();
    result.subtype = '';
  }
  while (pos < value.length) {
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t' || value[pos] === ';')) pos++;
    if (pos >= value.length) break;
    let attr = '';
    while (pos < value.length && value[pos] !== '=' && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
      attr += value[pos]; pos++;
    }
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    if (pos >= value.length || value[pos] !== '=') continue;
    pos++;
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    const { value: pval, pos: newPos } = parseParamValue(value, pos);
    pos = newPos;
    const attrLower = attr.toLowerCase();
    const rfc2231Match = attrLower.match(/^(.+)\*(\d+)(\*)?$/);
    const rfc2231Single = attrLower.match(/^(.+)\*$/);
    if (rfc2231Match) {
      const baseAttr = rfc2231Match[1];
      const idx = rfc2231Match[2];
      const isEncoded = rfc2231Match[3] === '*';
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set(idx, pval);
      if (isEncoded) result.rfc2231Encoded.add(baseAttr);
    } else if (rfc2231Single) {
      const baseAttr = rfc2231Single[1];
      if (!result.rfc2231.has(baseAttr)) result.rfc2231.set(baseAttr, new Map());
      result.rfc2231.get(baseAttr)!.set('0', pval);
      result.rfc2231Encoded.add(baseAttr);
    } else {
      result.params.set(attrLower, pval);
    }
  }
  return result;
}

function parseContentType(value: string): ParsedParams {
  return parseParams(value, true);
}

function parseContentDisposition(value: string): ParsedParams {
  return parseParams(value, false);
}

// RFC 2231 decode
function decodeRfc2231(segments: Map<string, string>, encoded: boolean): string {
  const indices = Array.from(segments.keys()).sort((a, b) => parseInt(a) - parseInt(b));
  let bytes: number[] = [];
  let charset = 'us-ascii';
  let firstEncoded = true;
  for (const idx of indices) {
    const val = segments.get(idx)!;
    if (encoded) {
      let s = val;
      if (firstEncoded) {
        const q1 = s.indexOf("'");
        if (q1 >= 0) {
          const q2 = s.indexOf("'", q1 + 1);
          if (q2 >= 0) {
            charset = s.slice(0, q1) || 'us-ascii';
            s = s.slice(q2 + 1);
          }
        }
        firstEncoded = false;
      }
      let j = 0;
      while (j < s.length) {
        if (s[j] === '%' && j + 2 < s.length && /^[0-9A-Fa-f]{2}$/.test(s.slice(j + 1, j + 3))) {
          bytes.push(parseInt(s.slice(j + 1, j + 3), 16));
          j += 3;
        } else {
          bytes.push(s.charCodeAt(j));
          j++;
        }
      }
    } else {
      for (let j = 0; j < val.length; j++) {
        bytes.push(val.charCodeAt(j));
      }
    }
  }
  return decodeCharset(Buffer.from(bytes), charset);
}

function getFileName(cd: ParsedParams | null, ct: ParsedParams): string | null {
  if (cd && cd.rfc2231.has('filename')) {
    return decodeRfc2231(cd.rfc2231.get('filename')!, cd.rfc2231Encoded.has('filename'));
  }
  if (cd && cd.params.has('filename')) {
    return decodeRfc2047(cd.params.get('filename')!);
  }
  if (ct.rfc2231.has('name')) {
    return decodeRfc2231(ct.rfc2231.get('name')!, ct.rfc2231Encoded.has('name'));
  }
  if (ct.params.has('name')) {
    return decodeRfc2047(ct.params.get('name')!);
  }
  return null;
}

// Quoted string for output
function quoteStr(s: string): string {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20) out += '\\u' + cp.toString(16).padStart(4, '0');
    else if (cp >= 0x7F && cp <= 0x9F) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += ch;
  }
  out += '"';
  return out;
}

interface Entity {
  headers: Map<string, string>;
  body: Buffer;
  ct: ParsedParams;
  cd: ParsedParams | null;
  cte: string;
  parts?: Entity[];
}

function splitLines(buf: Buffer, le: string): string[] {
  const leBuf = Buffer.from(le, 'binary');
  const lines: string[] = [];
  let start = 0;
  while (start <= buf.length) {
    const idx = buf.indexOf(leBuf, start);
    if (idx === -1) {
      lines.push(buf.slice(start).toString('binary'));
      break;
    }
    lines.push(buf.slice(start, idx).toString('binary'));
    start = idx + leBuf.length;
  }
  return lines;
}

function parseEntity(buf: Buffer, le: string, isTopLevel: boolean): Entity {
  const lines = splitLines(buf, le);
  let sepIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] === '') { sepIdx = i; break; }
  }
  let headerLines: string[];
  let bodyBuf: Buffer;
  if (sepIdx === -1) {
    headerLines = lines;
    bodyBuf = Buffer.alloc(0);
  } else {
    headerLines = lines.slice(0, sepIdx);
    if (isTopLevel) {
      // Body runs to end of file including final line break
      // Compute byte offset after the empty line's line break
      const leBuf = Buffer.from(le, 'binary');
      let offset = 0;
      for (let i = 0; i <= sepIdx; i++) {
        offset += Buffer.from(lines[i], 'binary').length;
        if (i < lines.length - 1 || (i === lines.length - 1 && offset < buf.length)) {
          // Check if there's a le after this line
          if (offset + leBuf.length <= buf.length && buf.slice(offset, offset + leBuf.length).equals(leBuf)) {
            offset += leBuf.length;
          }
        }
      }
      bodyBuf = buf.slice(offset);
    } else {
      const bodyLines = lines.slice(sepIdx + 1);
      bodyBuf = Buffer.from(bodyLines.join(le), 'binary');
    }
  }
  // Unfold headers
  const unfolded: string[] = [];
  for (const line of headerLines) {
    if ((line.startsWith(' ') || line.startsWith('\t')) && unfolded.length > 0) {
      unfolded[unfolded.length - 1] += line;
    } else {
      unfolded.push(line);
    }
  }
  // Parse headers
  const headers = new Map<string, string>();
  for (const line of unfolded) {
    const colonIdx = line.indexOf(':');
    if (colonIdx >= 0) {
      const name = line.slice(0, colonIdx).toLowerCase();
      let val = line.slice(colonIdx + 1);
      val = val.replace(/^[ \t]+/, '').replace(/[ \t]+$/, '');
      headers.set(name, val);
    }
  }
  // Parse Content-Type
  const ctVal = headers.get('content-type');
  let ct: ParsedParams;
  if (ctVal) {
    ct = parseContentType(ctVal);
  } else {
    ct = { type: 'text', subtype: 'plain', params: new Map([['charset', 'us-ascii']]), rfc2231: new Map(), rfc2231Encoded: new Set() };
  }
  // Parse Content-Disposition
  const cdVal = headers.get('content-disposition');
  const cd = cdVal ? parseContentDisposition(cdVal) : null;
  // CTE
  let cte = (headers.get('content-transfer-encoding') || '7bit').toLowerCase();
  if (ct.type === 'multipart') cte = '7bit';
  // Default charset for text
  if (ct.type === 'text' && !ct.params.has('charset')) {
    ct.params.set('charset', 'us-ascii');
  }
  // Multipart: parse parts
  let parts: Entity[] | undefined;
  if (ct.type === 'multipart') {
    const boundary = ct.params.get('boundary') || '';
    parts = parseMultipart(bodyBuf, le, boundary);
  }
  return { headers, body: bodyBuf, ct, cd, cte, parts };
}

function parseMultipart(body: Buffer, le: string, boundary: string): Entity[] {
  const leBuf = Buffer.from(le, 'binary');
  const delimStr = `--${boundary}`;
  const closeStr = `--${boundary}--`;
  const lines = splitLines(body, le);

  // Find delimiter lines
  interface BoundaryLine { idx: number; isClose: boolean; }
  const boundaryLines: BoundaryLine[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === closeStr || (line.startsWith(closeStr) && /^[ \t]*$/.test(line.slice(closeStr.length)))) {
      boundaryLines.push({ idx: i, isClose: true });
      break; // Stop at first close delimiter - everything after is epilogue
    } else if (line === delimStr || (line.startsWith(delimStr) && /^[ \t]*$/.test(line.slice(delimStr.length)))) {
      boundaryLines.push({ idx: i, isClose: false });
    }
  }
  if (boundaryLines.length === 0) return [];

  // Parts are between consecutive boundary lines
  const parts: Entity[] = [];
  for (let i = 0; i < boundaryLines.length - 1; i++) {
    const fromLine = boundaryLines[i].idx + 1;
    const toLine = boundaryLines[i + 1].idx;
    const partLines = lines.slice(fromLine, toLine);
    const partBuf = Buffer.from(partLines.join(le), 'binary');
    parts.push(parseEntity(partBuf, le, false));
  }
  // If last boundary is not close, content after it to end is a part
  if (!boundaryLines[boundaryLines.length - 1].isClose) {
    const fromLine = boundaryLines[boundaryLines.length - 1].idx + 1;
    const partLines = lines.slice(fromLine);
    const partBuf = Buffer.from(partLines.join(le), 'binary');
    parts.push(parseEntity(partBuf, le, false));
  }
  return parts;
}

function decodeBody(entity: Entity): Buffer {
  const cte = entity.cte;
  if (cte === 'base64') {
    return base64Decode(entity.body.toString('binary'));
  } else if (cte === 'quoted-printable') {
    return qpDecode(entity.body);
  } else {
    return entity.body;
  }
}

function decodeText(entity: Entity): string {
  const decoded = decodeBody(entity);
  const charset = (entity.ct.params.get('charset') || 'us-ascii').toLowerCase();
  let text = decodeCharset(decoded, charset);
  text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  return text;
}

function printEntity(entity: Entity, indent: number, output: string[]) {
  const prefix = '  '.repeat(indent);
  if (entity.ct.type === 'multipart') {
    const parts = entity.parts || [];
    output.push(`${prefix}multipart/${entity.ct.subtype} parts=${parts.length}`);
    for (const part of parts) {
      printEntity(part, indent + 1, output);
    }
  } else if (entity.ct.type === 'text' && (!entity.cd || entity.cd.type !== 'attachment')) {
    const charset = (entity.ct.params.get('charset') || 'us-ascii').toLowerCase();
    const text = decodeText(entity);
    const charCount = [...text].length;
    output.push(`${prefix}text/${entity.ct.subtype} charset=${charset} cte=${entity.cte} chars=${charCount}`);
    output.push(`${prefix}  ${quoteStr(text)}`);
  } else {
    const decoded = decodeBody(entity);
    const size = decoded.length;
    const crc = crc32(decoded).toString(16).padStart(8, '0');
    const disp = entity.cd ? entity.cd.type : '-';
    const name = getFileName(entity.cd, entity.ct);
    const nameStr = name !== null ? quoteStr(name) : '-';
    output.push(`${prefix}${entity.ct.type}/${entity.ct.subtype} cte=${entity.cte} disposition=${disp} name=${nameStr} size=${size} crc32=${crc}`);
  }
}

function processFile(filePath: string, fileName: string): string[] {
  const buf = fs.readFileSync(filePath);
  let le = '\n';
  for (let i = 0; i < buf.length - 1; i++) {
    if (buf[i] === 0x0D && buf[i + 1] === 0x0A) { le = '\r\n'; break; }
  }
  const entity = parseEntity(buf, le, true);
  const output: string[] = [];
  output.push(`== ${fileName}`);
  const from = entity.headers.get('from');
  const subject = entity.headers.get('subject');
  output.push(`From: ${from !== undefined ? quoteStr(decodeRfc2047(from)) : '-'}`);
  output.push(`Subject: ${subject !== undefined ? quoteStr(decodeRfc2047(subject)) : '-'}`);
  printEntity(entity, 0, output);
  return output;
}

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml'));
  files.sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));
  const outputs: string[] = [];
  for (let i = 0; i < files.length; i++) {
    if (i > 0) outputs.push('');
    const lines = processFile(path.join(dir, files[i]), files[i]);
    for (const l of lines) outputs.push(l);
  }
  process.stdout.write(outputs.join('\n') + '\n');
}

main();

