/* ===== CRC-32 ===== */
static uint32_t crc_tbl[256];
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?0xEDB88320^(c>>1):c>>1;crc_tbl[i]=c;}
}
static uint32_t crc32_calc(const unsigned char*d,size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++)c=crc_tbl[(c^d[i])&0xFF]^(c>>8);
    return c^0xFFFFFFFF;
}

/* ===== Dynamic string ===== */
typedef struct{char*s;size_t len,cap;}Str;
static void str_init(Str*st){st->s=NULL;st->len=st->cap=0;}
static void str_grow(Str*st,size_t n){if(st->len+n+1>st->cap){st->cap=st->cap?st->cap*2:64;while(st->cap<st->len+n+1)st->cap*=2;st->s=realloc(st->s,st->cap);}}
