    while(pos<ilen){
        size_t ws,we;char cs[256],enc;char et[4096];size_t clen,elen;
        if(!find_encword(input,ilen,pos,&ws,&we,cs,&enc,et,&elen)){
            str_app(&out,input+pos,ilen-pos);break;
        }
        /* output text before this word */
        if(ws>pos)str_app(&out,input+pos,ws-pos);
        /* collect run of adjacent encoded-words with same charset */
        size_t run_end=we;
        size_t run_start=ws;
        /* collect all encoded bytes */
        Str allbytes;str_init(&allbytes);
        /* decode first word */
        {
            if(enc=='B'||enc=='b'){
                size_t dl;unsigned char*d=b64_decode(et,elen,&dl);
                str_app(&allbytes,(char*)d,dl);free(d);
            } else {
                for(size_t i=0;i<elen;i++){
                    if(et[i]=='_'){str_appc(&allbytes,0x20);}
                    else if(et[i]=='='&&i+2<elen&&is_hex(et[i+1])&&is_hex(et[i+2])){
                        str_appc(&allbytes,(char)((hex_val(et[i+1])<<4)|hex_val(et[i+2])));i+=2;
                    } else str_appc(&allbytes,et[i]);
                }
            }
        }
        /* try to extend run */
        while(1){
            size_t gap_start=run_end;
            while(gap_start<ilen&&(input[gap_start]==' '||input[gap_start]=='\t'))gap_start++;
            size_t ws2,we2;char cs2[256],enc2;char et2[4096];size_t clen2,elen2;
            if(gap_start>=ilen)break;
            if(!find_encword(input,ilen,gap_start,&ws2,&we2,cs2,&enc2,et2,&elen2))break;
            if(ws2!=gap_start)break; /* not adjacent (non-ws between) */
            if(!cs_same(cs,cs2))break;
            /* add this word's bytes */
            if(enc2=='B'||enc2=='b'){
                size_t dl;unsigned char*d=b64_decode(et2,elen2,&dl);
                str_app(&allbytes,(char*)d,dl);free(d);
            } else {
                for(size_t i=0;i<elen2;i++){
                    if(et2[i]=='_'){str_appc(&allbytes,0x20);}
                    else if(et2[i]=='='&&i+2<elen2&&is_hex(et2[i+1])&&is_hex(et2[i+2])){
                        str_appc(&allbytes,(char)((hex_val(et2[i+1])<<4)|hex_val(et2[i+2])));i+=2;
                    } else str_appc(&allbytes,et2[i]);
                }
            }
            run_end=we2;
        }
        /* decode all bytes with charset */
        size_t np;uint32_t*cps=charset_decode((unsigned char*)allbytes.s,allbytes.len,cs,&np);
        for(size_t i=0;i<np;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
        free(cps);free(allbytes.s);
        pos=run_end;
    }
    return str_take(&out);
}

/* ===== Parameter parsing ===== */
typedef struct{char*name;char*value;}Param;

static void skip_ws(const char*s,size_t*pos,size_t len){while(*pos<len&&(s[*pos]==' '||s[*pos]=='\t'))(*pos)++;}

static void parse_params(const char*s,size_t start,size_t len,Param**out,int*no){
    Param*p=NULL;int np=0;
    size_t pos=start;
    while(pos<len){
        skip_ws(s,&pos,len);
        if(pos>=len||s[pos]!=';')break;
        pos++; /* skip ; */
        skip_ws(s,&pos,len);
        /* param name */
        size_t ns=pos;
        while(pos<len&&s[pos]!='='&&s[pos]!=';'&&s[pos]!=' '&&s[pos]!='\t')pos++;
        char*pname=dupn(s+ns,pos-ns);
        for(char*c=pname;*c;c++)*c=tolower((unsigned char)*c);
        skip_ws(s,&pos,len);
        if(pos<len&&s[pos]=='='){pos++;skip_ws(s,&pos,len);}
        /* param value */
        char*pval=NULL;
        if(pos<len&&s[pos]=='"'){
            pos++;Str vs;str_init(&vs);
            while(pos<len&&s[pos]!='"'){
                if(s[pos]=='\\'&&pos+1<len){pos++;str_appc(&vs,s[pos]);pos++;}
                else{str_appc(&vs,s[pos]);pos++;}
            }
            if(pos<len)pos++; /* skip closing " */
            pval=str_take(&vs);
        } else {
            size_t vs=pos;
            while(pos<len&&s[pos]!=';'&&s[pos]!=' '&&s[pos]!='\t')pos++;
            pval=dupn(s+vs,pos-vs);
        }
        p=realloc(p,(np+1)*sizeof(Param));
        p[np].name=pname;p[np].value=pval;np++;
    }
    *out=p;*no=np;
}

static const char*find_param(Param*ps,int np,const char*name){
    for(int i=0;i<np;i++)if(!ci_cmp(ps[i].name,name))return ps[i].value;
    return NULL;
}

/* ===== RFC 2231 ===== */
static int is_rfc2231_param(Param*ps,int np,const char*attr){
    size_t alen=strlen(attr);
    for(int i=0;i<np;i++){
        size_t nlen=strlen(ps[i].name);
        if(nlen<=alen)continue;
        if(strncasecmp(ps[i].name,attr,alen)!=0)continue;
        if(ps[i].name[alen]!='*')continue;
        /* check it's a valid rfc2231 form */
        const char*rest=ps[i].name+alen+1;
        if(*rest=='\0')return 1; /* attr* single form */
        /* continuation: attr*N or attr*N* */
        while(*rest>='0'&&*rest<='9')rest++;
        if(rest>ps[i].name+alen+1){
            if(*rest=='\0'||(*rest=='*'&&*(rest+1)=='\0'))return 1;
        }
    }
    return 0;
}

static unsigned char*percent_decode(const char*s,size_t len,size_t*out_len){
    unsigned char*buf=malloc(len+1);size_t bl=0;
    for(size_t i=0;i<len;i++){
        if(s[i]=='%'&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
            buf[bl++]=(unsigned char)((hex_val(s[i+1])<<4)|hex_val(s[i+2]));i+=2;
        } else buf[bl++]=s[i];
    }
    *out_len=bl;return buf;
}

static char*decode_rfc2231(Param*ps,int np,const char*attr){
    /* single form: attr*=charset'lang'value */
    char single_name[256];snprintf(single_name,sizeof(single_name),"%s*",attr);
    const char*sv=find_param(ps,np,single_name);
    if(sv){
        /* parse charset'language'value */
        const char*q1=strchr(sv,'\'');
        if(!q1)return strdup(sv);
        char*cs=dupn(sv,q1-sv);
        const char*q2=strchr(q1+1,'\'');
        if(!q2){free(cs);return strdup(sv);}
        const char*val=q2+1;
        size_t dl;unsigned char*d=percent_decode(val,strlen(val),&dl);
        size_t np2;uint32_t*cps=charset_decode(d,dl,cs,&np2);
        Str out;str_init(&out);
        for(size_t i=0;i<np2;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
        free(cps);free(d);free(cs);
        return str_take(&out);
    }
    /* continuation form: attr*0, attr*1, ... or attr*0*, attr*1*, ... */
    int has_cont=0;
    /* collect segments */
    typedef struct{int idx;int pct;char*val;}Seg;
    Seg*segs=NULL;int nsegs=0;
    size_t alen=strlen(attr);
    for(int i=0;i<np;i++){
        size_t nlen=strlen(ps[i].name);
        if(nlen<=alen+1)continue;
        if(strncasecmp(ps[i].name,attr,alen)!=0)continue;
        if(ps[i].name[alen]!='*')continue;
        const char*rest=ps[i].name+alen+1;
        char*endp;long idx=strtol(rest,&endp,10);
        if(endp==rest)continue;
        int pct=0;
        if(*endp=='*'&&*(endp+1)=='\0')pct=1;
        else if(*endp!='\0')continue;
        segs=realloc(segs,(nsegs+1)*sizeof(Seg));
        segs[nsegs].idx=idx;segs[nsegs].pct=pct;segs[nsegs].val=strdup(ps[i].value);
        nsegs++;has_cont=1;
    }
    if(!has_cont)return NULL;
    /* sort by idx */
    for(int i=0;i<nsegs;i++)for(int j=i+1;j<nsegs;j++)if(segs[j].idx<segs[i].idx){Seg t=segs[i];segs[i]=segs[j];segs[j]=t;}
    /* get charset from first percent-encoded segment */
    char*cs=NULL;
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            const char*q1=strchr(segs[i].val,'\'');
            if(q1){
                const char*q2=strchr(q1+1,'\'');
                if(q2){cs=dupn(segs[i].val,q1-segs[i].val);
                    /* strip charset'lang' from this segment */
                    char*nv=strdup(q2+1);free(segs[i].val);segs[i].val=nv;
                }
            }
            break;
        }
    }
    /* concatenate bytes */
    Str allb;str_init(&allb);
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            size_t dl;unsigned char*d=percent_decode(segs[i].val,strlen(segs[i].val),&dl);
            str_app(&allb,(char*)d,dl);free(d);
        } else {
            str_app(&allb,segs[i].val,strlen(segs[i].val));
        }
        free(segs[i].val);
    }
    free(segs);
    /* decode with charset */
    size_t np2;uint32_t*cps=charset_decode((unsigned char*)allb.s,allb.len,cs?cs:"us-ascii",&np2);
    Str out;str_init(&out);
    for(size_t i=0;i<np2;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
    free(cps);free(allb.s);free(cs);
    return str_take(&out);
}

/* ===== Entity structure ===== */
typedef struct Entity{
    char**hnames;char**hvals;int nh;
    char*ctype_type;char*ctype_sub;Param*cparams;int ncparams;
    char*cdisp_type;Param*dparams;int ndparams;
    char*cte;
    unsigned char*body;size_t body_len;
    struct Entity*parts;int nparts;
}Entity;

static void get_header(Entity*e,const char*name,const char**out){
    for(int i=0;i<e->nh;i++)if(!ci_cmp(e->hnames[i],name)){*out=e->hvals[i];return;}
    *out=NULL;
}

/* ===== Parsing ===== */
static void parse_headers(const unsigned char*data,size_t len,int lb_len,Entity*e){
    e->hnames=NULL;e->hvals=NULL;e->nh=0;
    /* unfold: remove line break followed by space/tab */
    Str uf;str_init(&uf);
    size_t pos=0;
    while(pos<len){
        /* find end of line */
        size_t le=pos;
        while(le<len){
            if(lb_len==2&&le+1<len&&data[le]=='\r'&&data[le+1]=='\n')break;
            if(lb_len==1&&data[le]=='\n')break;
            le++;
        }
        size_t next=le+(le<len?lb_len:0);
        /* check if next char is space/tab (continuation) */
        if(next<len&&(data[next]==' '||data[next]=='\t')){
            /* unfold: add line content without line break, keep the space/tab */
            str_app(&uf,(char*)data+pos,le-pos);
            pos=next; /* skip line break, keep space/tab */
        } else {
            str_app(&uf,(char*)data+pos,le-pos);
            str_appc(&uf,'\n'); /* internal separator */
            pos=next;
        }
    }
    /* split into lines */
    char*s=uf.s;
    char*line=strtok(s,"\n");
    while(line){
        char*colon=strchr(line,':');
        if(colon){
            size_t nl=colon-line;
            char*nm=dupn(line,nl);
            for(char*c=nm;*c;c++)*c=tolower((unsigned char)*c);
            char*val=colon+1;
            while(*val==' '||*val=='\t')val++;
            size_t vl=strlen(val);
            while(vl>0&&(val[vl-1]==' '||val[vl-1]=='\t'))vl--;
            char*vv=dupn(val,vl);
            e->hnames=realloc(e->hnames,(e->nh+1)*sizeof(char*));
            e->hvals=realloc(e->hvals,(e->nh+1)*sizeof(char*));
            e->hnames[e->nh]=nm;e->hvals[e->nh]=vv;e->nh++;
        }
        line=strtok(NULL,"\n");
    }
    free(uf.s);
}

static void parse_entity(const unsigned char*data,size_t len,int lb_len,Entity*e);

static void find_body(const unsigned char*data,size_t len,int lb_len,size_t*hdr_end,size_t*body_start){
    /* find first empty line */
    size_t pos=0;
    if(len==0){*hdr_end=0;*body_start=0;return;}
    /* check if starts with line break */
    if((lb_len==2&&len>=2&&data[0]=='\r'&&data[1]=='\n')||(lb_len==1&&data[0]=='\n')){
        *hdr_end=0;*body_start=lb_len;return;
    }
    /* scan lines */
    while(pos<len){
        size_t le=pos;
        while(le<len){
            if(lb_len==2&&le+1<len&&data[le]=='\r'&&data[le+1]=='\n')break;
            if(lb_len==1&&data[le]=='\n')break;
            le++;
        }
        if(le==pos){
            /* empty line */
            *hdr_end=pos;
            *body_start=le+lb_len;
            return;
        }
        if(le>=len)break;
        pos=le+lb_len;
    }
    /* no empty line found */
    *hdr_end=len;*body_start=len;
}

static void parse_ct(const char*val,Entity*e){
    e->ctype_type=strdup("text");e->ctype_sub=strdup("plain");e->cparams=NULL;e->ncparams=0;
    if(!val){return;}
    /* find type/subtype */
    const char*slash=strchr(val,'/');
    if(!slash){e->ctype_type=strdup(val);return;}
    /* type: skip ws */
    const char*ts=val;while(*ts==' '||*ts=='\t')ts++;
    const char*te=slash;while(te>ts&&(te[-1]==' '||te[-1]=='\t'))te--;
    e->ctype_type=dupn(ts,te-ts);for(char*c=e->ctype_type;*c;c++)*c=tolower((unsigned char)*c);
    /* subtype */
    const char*ss=slash+1;while(*ss==' '||*ss=='\t')ss++;
    const char*se=ss;while(*se&&*se!=';')se++;
    while(se>ss&&(se[-1]==' '||se[-1]=='\t'))se--;
    e->ctype_sub=dupn(ss,se-ss);for(char*c=e->ctype_sub;*c;c++)*c=tolower((unsigned char)*c);
    /* params */
    const char*semi=strchr(val,';');
    if(semi)parse_params(val,semi-val,strlen(val),&e->cparams,&e->ncparams);
}

static void parse_cd(const char*val,Entity*e){
    e->cdisp_type=NULL;e->dparams=NULL;e->ndparams=0;
    if(!val)return;
    /* disposition type */
    const char*s=val;while(*s==' '||*s=='\t')s++;
    const char*te=s;while(*te&&*te!=';'&&*te!=' '&&*te!='\t')te++;
    e->cdisp_type=dupn(s,te-s);for(char*c=e->cdisp_type;*c;c++)*c=tolower((unsigned char)*c);
    /* params */
    const char*semi=strchr(val,';');
    if(semi)parse_params(val,semi-val,strlen(val),&e->dparams,&e->ndparams);
}

static int is_delim(const unsigned char*line,size_t llen,const char*B){
    size_t blen=strlen(B);
    if(llen<blen+2)return 0;
    if(line[0]!='-'||line[1]!='-')return 0;
    if(memcmp(line+2,B,blen)!=0)return 0;
    for(size_t i=2+blen;i<llen;i++){
        if(line[i]!=' '&&line[i]!='\t')return 0;
    }
    return 1;
}
static int is_close_delim(const unsigned char*line,size_t llen,const char*B){
    size_t blen=strlen(B);
    if(llen<blen+4)return 0;
    if(line[0]!='-'||line[1]!='-')return 0;
    if(memcmp(line+2,B,blen)!=0)return 0;
    if(line[2+blen]!='-'||line[3+blen]!='-')return 0;
    for(size_t i=4+blen;i<llen;i++){
        if(line[i]!=' '&&line[i]!='\t')return 0;
    }
    return 1;
}

static void parse_entity(const unsigned char*data,size_t len,int lb_len,Entity*e){
    memset(e,0,sizeof(Entity));
    size_t hdr_end,body_start;
    find_body(data,len,lb_len,&hdr_end,&body_start);
    parse_headers(data,hdr_end,lb_len,e);
    /* content type */
    const char*ctv;get_header(e,"content-type",&ctv);
    parse_ct(ctv,e);
    /* content disposition */
    const char*cdv;get_header(e,"content-disposition",&cdv);
    parse_cd(cdv,e);
    /* CTE */
    const char*ctev;get_header(e,"content-transfer-encoding",&ctev);
    if(ctev&&*ctev){
        e->cte=dupn(ctev,strlen(ctev));
        for(char*c=e->cte;*c;c++)*c=tolower((unsigned char)*c);
        /* trim */
        size_t l=strlen(e->cte);while(l>0&&(e->cte[l-1]==' '||e->cte[l-1]=='\t'))e->cte[--l]=0;
        size_t s=0;while(e->cte[s]==' '||e->cte[s]=='\t')s++;
        if(s>0){memmove(e->cte,e->cte+s,l-s+1);}
    } else e->cte=strdup("7bit");
    /* body */
    e->body=(unsigned char*)data+body_start;
    e->body_len=len-body_start;
    /* multipart? */
    if(!ci_cmp(e->ctype_type,"multipart")){
        const char*b=find_param(e->cparams,e->ncparams,"boundary");
        if(!b)b="";
        /* find delimiters in body */
        size_t*dl_pos=NULL;int n_dl=0;
        size_t pos=0;
        while(pos<e->body_len){
            size_t le=pos;
            while(le<e->body_len){
                if(lb_len==2&&le+1<e->body_len&&e->body[le]=='\r'&&e->body[le+1]=='\n')break;
                if(lb_len==1&&e->body[le]=='\n')break;
                le++;
            }
            if(is_delim(e->body+pos,le-pos,b)||is_close_delim(e->body+pos,le-pos,b)){
                dl_pos=realloc(dl_pos,(n_dl+1)*sizeof(size_t));
                dl_pos[n_dl++]=pos;
            }
            if(le>=e->body_len)break;
            pos=le+lb_len;
        }
        /* find first delimiter and close delimiter */
        int first_dl=-1,close_dl=-1;
        for(int i=0;i<n_dl;i++){
            size_t le=dl_pos[i];
            while(le<e->body_len){
                if(lb_len==2&&le+1<e->body_len&&e->body[le]=='\r'&&e->body[le+1]=='\n')break;
                if(lb_len==1&&e->body[le]=='\n')break;
                le++;
            }
            if(is_close_delim(e->body+dl_pos[i],le-dl_pos[i],b)){close_dl=i;break;}
            if(first_dl<0)first_dl=i;
        }
        /* parts are between consecutive delimiters */
        if(first_dl>=0){
            int start_i=first_dl;
            int end_i=(close_dl>=0)?close_dl:n_dl;
            int nparts=end_i-start_i;
            if(nparts<0)nparts=0;
            e->parts=malloc((nparts>0?nparts:1)*sizeof(Entity));
            e->nparts=0;
            for(int i=start_i;i<end_i;i++){
                /* part content: from after delimiter i to before delimiter i+1 */
                size_t le_i=dl_pos[i];
                while(le_i<e->body_len){
                    if(lb_len==2&&le_i+1<e->body_len&&e->body[le_i]=='\r'&&e->body[le_i+1]=='\n')break;
                    if(lb_len==1&&e->body[le_i]=='\n')break;
                    le_i++;
                }
                size_t pstart=le_i+lb_len;
                size_t pend;
                if(i+1<end_i){
                    pend=dl_pos[i+1];
                    /* remove trailing line break */
                    if(pend>pstart&&pend>=lb_len){
                        /* check if there's a line break just before pend */
                        if(lb_len==2&&pend>=2&&e->body[pend-2]=='\r'&&e->body[pend-1]=='\n')pend-=2;
                        else if(lb_len==1&&pend>=1&&e->body[pend-1]=='\n')pend-=1;
                    }
                } else {
                    /* last part before close delimiter or end of body */
                    pend=e->body_len;
                    if(pend>pstart&&pend>=lb_len){
                        if(lb_len==2&&pend>=2&&e->body[pend-2]=='\r'&&e->body[pend-1]=='\n')pend-=2;
                        else if(lb_len==1&&pend>=1&&e->body[pend-1]=='\n')pend-=1;
                    }
                }
                if(pend<pstart)pend=pstart;
                parse_entity(e->body+pstart,pend-pstart,lb_len,&e->parts[e->nparts]);
                e->nparts++;
            }
        }
        free(dl_pos);
    }
}

/* ===== Transfer decoding ===== */
static unsigned char*decode_cte(const unsigned char*body,size_t blen,const char*cte,int lb_len,size_t*out_len){
    if(!ci_cmp(cte,"base64")){
        return b64_decode((const char*)body,blen,out_len);
    } else if(!ci_cmp(cte,"quoted-printable")){
        return qp_decode(body,blen,out_len,lb_len);
    } else {
        /* 7bit, 8bit, binary */
        unsigned char*r=malloc(blen+1);memcpy(r,body,blen);*out_len=blen;return r;
    }
}

/* ===== Output helpers ===== */
static void print_quoted(FILE*f,const uint32_t*cps,size_t n){
    fputc('"',f);
    for(size_t i=0;i<n;i++){
        uint32_t c=cps[i];
        if(c=='\\')fputs("\\\\",f);
        else if(c=='"')fputs("\\\"",f);
        else if(c=='\n')fputs("\\n",f);
        else if(c=='\t')fputs("\\t",f);
        else if(c<0x20||c==0x7F||(c>=0x80&&c<=0x9F)){
            fprintf(f,"\\u%04x",c);
        } else {
            char ub[4];int ul;utf8_enc(c,ub,&ul);
            fwrite(ub,1,ul,f);
        }
    }
    fputc('"',f);
}

static void print_quoted_str(FILE*f,const char*s){
    /* decode as utf-8 to code points, then print */
    size_t slen=strlen(s);
    size_t np;uint32_t*cps=charset_decode((unsigned char*)s,slen,"utf-8",&np);
    print_quoted(f,cps,np);
    free(cps);
}

/* ===== Get filename ===== */
static char*get_filename(Entity*e){
    /* RFC 2231 Content-Disposition filename */
    if(e->dparams){
        if(is_rfc2231_param(e->dparams,e->ndparams,"filename")){
            char*r=decode_rfc2231(e->dparams,e->ndparams,"filename");
            if(r)return r;
        }
    }
    /* plain Content-Disposition filename */
    const char*fn=find_param(e->dparams?e->dparams:NULL,e->ndparams,"filename");
    if(fn)return decode_rfc2047(fn);
    /* RFC 2231 Content-Type name */
    if(e->cparams){
        if(is_rfc2231_param(e->cparams,e->ncparams,"name")){
            char*r=decode_rfc2231(e->cparams,e->ncparams,"name");
            if(r)return r;
        }
    }
    /* plain Content-Type name */
    const char*nm=find_param(e->cparams?e->cparams:NULL,e->ncparams,"name");
    if(nm)return decode_rfc2047(nm);
    return NULL;
}

/* ===== Get charset ===== */
static const char*get_charset(Entity*e){
    const char*cs=find_param(e->cparams,e->ncparams,"charset");
    return cs?cs:"us-ascii";
}

/* ===== Print tree ===== */
static void print_tree(FILE*f,Entity*e,int level,int lb_len){
    for(int i=0;i<level*2;i++)fputc(' ',f);
    if(!ci_cmp(e->ctype_type,"multipart")){
        fprintf(f,"multipart/%s parts=%d\n",e->ctype_sub,e->nparts);
        for(int i=0;i<e->nparts;i++)print_tree(f,&e->parts[i],level+1,lb_len);
    } else {
        int is_text=!ci_cmp(e->ctype_type,"text");
        int is_attach=e->cdisp_type&&!ci_cmp(e->cdisp_type,"attachment");
        if(is_text&&!is_attach){
            /* text part */
            const char*cs=get_charset(e);
            size_t dlen;
            unsigned char*decoded=decode_cte(e->body,e->body_len,e->cte,lb_len,&dlen);
            /* normalize line endings: CRLF->LF, lone CR->LF */
            Str norm;str_init(&norm);
            for(size_t i=0;i<dlen;i++){
                if(decoded[i]=='\r'){
                    if(i+1<dlen&&decoded[i+1]=='\n'){str_appc(&norm,'\n');i++;}
                    else str_appc(&norm,'\n');
                } else str_appc(&norm,decoded[i]);
            }
            free(decoded);
            size_t np;uint32_t*cps=charset_decode((unsigned char*)norm.s,norm.len,cs,&np);
            fprintf(f,"%s/%s charset=%s cte=%s chars=%zu\n",e->ctype_type,e->ctype_sub,cs,e->cte,np);
            for(int i=0;i<(level+1)*2;i++)fputc(' ',f);
            print_quoted(f,cps,np);
            fputc('\n',f);
            free(cps);free(norm.s);
        } else {
            /* other part */
            size_t dlen;
            unsigned char*decoded=decode_cte(e->body,e->body_len,e->cte,lb_len,&dlen);
            uint32_t crc=crc32_calc(decoded,dlen);
            char*fname=get_filename(e);
            const char*disp=e->cdisp_type?e->cdisp_type:"-";
            fprintf(f,"%s/%s cte=%s disposition=%s name=",e->ctype_type,e->ctype_sub,e->cte,disp);
            if(fname){print_quoted_str(f,fname);free(fname);}
            else fputc('-',f);
            fprintf(f," size=%zu crc32=%08x\n",dlen,crc);
            free(decoded);
        }
    }
}

/* ===== Main ===== */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char**argv){
    crc_init();
    if(argc<2)return 0;
    DIR*d=opendir(argv[1]);
    if(!d)return 0;
    char**files=NULL;int nf=0;
    struct dirent*de;
    while((de=readdir(d))){
        size_t l=strlen(de->d_name);
        if(l>4&&!strcmp(de->d_name+l-4,".eml")){
            files=realloc(files,(nf+1)*sizeof(char*));
            files[nf++]=strdup(de->d_name);
        }
    }
    closedir(d);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)fputc('\n',stdout);
        /* read file */
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
        unsigned char*data=malloc(fsz+1);
        fread(data,1,fsz,f);fclose(f);
        int lb_len=1;
        for(long i=0;i<fsz-1;i++){if(data[i]=='\r'&&data[i+1]=='\n'){lb_len=2;break;}}
        /* parse */
        Entity msg;
        parse_entity(data,fsz,lb_len,&msg);
        /* output */
        printf("== %s\n",files[fi]);
        const char*from;get_header(&msg,"from",&from);
        const char*subj;get_header(&msg,"subject",&subj);
        printf("From: ");
        if(from){char*d=decode_rfc2047(from);print_quoted_str(stdout,d);free(d);}
        else fputc('-',stdout);
        fputc('\n',stdout);
        printf("Subject: ");
        if(subj){char*d=decode_rfc2047(subj);print_quoted_str(stdout,d);free(d);}
        else fputc('-',stdout);
        fputc('\n',stdout);
        print_tree(stdout,&msg,0,lb_len);
        free(data);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    free(files);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <dirent.h>
#include <sys/stat.h>
#include <stdint.h>

/* ===== CRC-32 ===== */
static uint32_t crc_tbl[256];
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?0xEDB88320^(c>>1):c>>1;crc_tbl[i]=c;}
}
static uint32_t crc32_calc(const unsigned char*d,size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++)c=crc_tbl[(c^d[i])&0xFF]^(c>>8);
    return c^0xFFFFFFFF;
}

/* ===== Dynamic string ===== */
typedef struct{char*s;size_t len,cap;}Str;
static void str_init(Str*st){st->s=NULL;st->len=st->cap=0;}
static void str_grow(Str*st,size_t n){if(st->len+n+1>st->cap){st->cap=st->cap?st->cap*2:64;while(st->cap<st->len+n+1)st->cap*=2;st->s=realloc(st->s,st->cap);}}
static void str_app(Str*st,const char*s,size_t n){str_grow(st,n);memcpy(st->s+st->len,s,n);st->len+=n;st->s[st->len]=0;}
static void str_appc(Str*st,char c){str_grow(st,1);st->s[st->len++]=c;st->s[st->len]=0;}
static char*str_take(Str*st){if(!st->s)return strdup("");return st->s;}

/* ===== Utilities ===== */
static char*dupn(const char*s,size_t n){char*r=malloc(n+1);memcpy(r,s,n);r[n]=0;return r;}
static char*strdup_safe(const char*s){return s?strdup(s):NULL;}
static int ci_cmp(const char*a,const char*b){if(!a&&!b)return 0;if(!a)return -1;if(!b)return 1;while(*a&&*b){int ca=tolower((unsigned char)*a),cb=tolower((unsigned char)*b);if(ca!=cb)return ca-cb;a++;b++;}return tolower((unsigned char)*a)-tolower((unsigned char)*b);}
static int is_hex(int c){return(c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}
static int hex_val(int c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;return c-'A'+10;}

/* ===== Base64 ===== */
static int b64_val(int c){
    if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;
    if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;
}
static unsigned char*b64_decode(const char*src,size_t slen,size_t*out_len){
    unsigned char*buf=malloc(slen+4);size_t bl=0;int bits=0,acc=0;
    for(size_t i=0;i<slen;i++){
        if(src[i]=='=')break;
        int v=b64_val((unsigned char)src[i]);
        if(v<0)continue;
        acc=(acc<<6)|v;bits+=6;
        if(bits>=8){bits-=8;buf[bl++]=(acc>>bits)&0xFF;}
    }
    *out_len=bl;return buf;
}

/* ===== Quoted-Printable ===== */
static unsigned char*qp_decode(const unsigned char*src,size_t slen,size_t*out_len,int lb_len){
    unsigned char*buf=malloc(slen+4);size_t bl=0;
    size_t pos=0;
    while(pos<slen){
        size_t ls=pos;
        while(pos<slen){
            if(lb_len==2&&pos+1<slen&&src[pos]=='\r'&&src[pos+1]=='\n')break;
            if(lb_len==1&&src[pos]=='\n')break;
            pos++;
        }
        size_t le=pos;
        pos+=(pos<slen)?lb_len:0;
        /* remove trailing spaces/tabs */
        while(le>ls&&(src[le-1]==' '||src[le-1]=='\t'))le--;
        /* soft line break */
        if(le>ls&&src[le-1]=='='){
            le--;
            /* check if this = would split =XY: if next line starts with 2 hex, keep the = */
            if(pos<slen){
                size_t nls=pos;
                while(pos<slen){
                    if(lb_len==2&&pos+1<slen&&src[pos]=='\r'&&src[pos+1]=='\n')break;
                    if(lb_len==1&&src[pos]=='\n')break;
                    pos++;
                }
                size_t nle=pos;
                pos+=(pos<slen)?lb_len:0;
                while(nle>nls&&(src[nle-1]==' '||src[nle-1]=='\t'))nle--;
                if(nle-nls>=2&&is_hex(src[nls])&&is_hex(src[nls+1])){
                    /* =XY split across lines - keep the = */
                    buf[bl++]='=';
                    /* process the next line normally */
                    pos=nls;
                    continue;
                }
                /* process next line */
                ls=nls;le=nle;
                /* fall through to process this line content */
            } else {
                /* no next line, = is literal */
                buf[bl++]='=';
            }
        }
        /* process line content for =XY */
        for(size_t i=ls;i<le;i++){
            if(src[i]=='='&&i+2<le&&is_hex(src[i+1])&&is_hex(src[i+2])){
                buf[bl++]=(unsigned char)((hex_val(src[i+1])<<4)|hex_val(src[i+2]));
                i+=2;
            } else {
                buf[bl++]=src[i];
            }
        }
        /* add line break if not last line */
        if(pos<slen){
            for(int k=0;k<lb_len;k++)buf[bl++]=(unsigned char)(lb_len==2?((k==0)?'\r':'\n'):'\n');
        }
    }
    *out_len=bl;return buf;
}

/* ===== Charset decoding ===== */
/* Returns array of uint32_t code points */
static uint32_t*charset_decode(const unsigned char*data,size_t len,const char*cs,size_t*out_n){
    size_t cap=len+1;uint32_t*cp=malloc(cap*sizeof(uint32_t));size_t n=0;
    size_t i=0;
    if(!cs||!strcasecmp(cs,"us-ascii")||!strcasecmp(cs,"ascii")){
        while(i<len){if(n>=cap){cap*=2;cp=realloc(cp,cap*sizeof(uint32_t));}cp[n++]=data[i++];}
    } else if(!strcasecmp(cs,"utf-8")||!strcasecmp(cs,"utf8")){
        while(i<len){
            if(n>=cap){cap*=2;cp=realloc(cp,cap*sizeof(uint32_t));}
            unsigned char b0=data[i];
            if(b0<0x80){cp[n++]=b0;i++;}
            else if((b0&0xE0)==0xC0&&i+1<len){cp[n++]=((b0&0x1F)<<6)|(data[i+1]&0x3F);i+=2;}
            else if((b0&0xF0)==0xE0&&i+2<len){cp[n++]=((b0&0x0F)<<12)|((data[i+1]&0x3F)<<6)|(data[i+2]&0x3F);i+=3;}
            else if((b0&0xF8)==0xF0&&i+3<len){cp[n++]=((b0&0x07)<<18)|((data[i+1]&0x3F)<<12)|((data[i+2]&0x3F)<<6)|(data[i+3]&0x3F);i+=4;}
            else{cp[n++]=b0;i++;}
        }
    } else if(!strcasecmp(cs,"iso-8859-1")||!strcasecmp(cs,"latin1")||!strcasecmp(cs,"iso8859-1")){
        while(i<len){if(n>=cap){cap*=2;cp=realloc(cp,cap*sizeof(uint32_t));}cp[n++]=data[i++];}
    } else if(!strcasecmp(cs,"windows-1252")||!strcasecmp(cs,"cp1252")||!strcasecmp(cs,"win1252")){
        static const uint32_t cp1252[32]={
            0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
            0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
            0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
            0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
        };
        while(i<len){
            if(n>=cap){cap*=2;cp=realloc(cp,cap*sizeof(uint32_t));}
            unsigned char b=data[i++];
            if(b>=0x80&&b<=0x9F)cp[n++]=cp1252[b-0x80];
            else cp[n++]=b;
        }
    } else {
        /* unknown charset, treat as latin1 */
        while(i<len){if(n>=cap){cap*=2;cp=realloc(cp,cap*sizeof(uint32_t));}cp[n++]=data[i++];}
    }
    *out_n=n;return cp;
}

/* ===== UTF-8 encode ===== */
static void utf8_enc(uint32_t cp,char*buf,int*len){
    if(cp<0x80){buf[0]=cp;*len=1;}
    else if(cp<0x800){buf[0]=0xC0|(cp>>6);buf[1]=0x80|(cp&0x3F);*len=2;}
    else if(cp<0x10000){buf[0]=0xE0|(cp>>12);buf[1]=0x80|((cp>>6)&0x3F);buf[2]=0x80|(cp&0x3F);*len=3;}
    else{buf[0]=0xF0|(cp>>18);buf[1]=0x80|((cp>>12)&0x3F);buf[2]=0x80|((cp>>6)&0x3F);buf[3]=0x80|(cp&0x3F);*len=4;}
}

/* ===== RFC 2047 encoded-word decoding ===== */
static int find_encword(const char*s,size_t len,size_t start,size_t*wstart,size_t*wend,char*charset,size_t*clen,char*enc,char*etxt,size_t*elen){
    for(size_t i=start;i+1<len;i++){
        if(s[i]=='='&&s[i+1]=='?'){
            size_t p=i+2;
            size_t cs_start=p;
            while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
            if(p>=len||s[p]!='?')continue;
            size_t cs_end=p;p++;
            if(p>=len)continue;
            if(s[p]!='B'&&s[p]!='b'&&s[p]!='Q'&&s[p]!='q')continue;
            char enc_ch=s[p];p++;
            if(p>=len||s[p]!='?')continue;
            p++;
            size_t et_start=p;
            while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
            if(p+1>=len||s[p]!='?'||s[p+1]!='=')continue;
            size_t et_end=p;p+=2;
            *wstart=i;*wend=p;
            *clen=cs_end-cs_start;memcpy(charset,s+cs_start,*clen);charset[*clen]=0;
            *enc=enc_ch;
            *elen=et_end-et_start;memcpy(etxt,s+et_start,*elen);etxt[*elen]=0;
            return 1;
        }
    }
    return 0;
}

static char*strip_lang(const char*cs){
    char*r=malloc(strlen(cs)+1);int j=0;
    for(int i=0;cs[i];i++){if(cs[i]=='*')break;r[j++]=cs[i];}
    r[j]=0;return r;
}
static int cs_same(const char*a,const char*b){
    char*sa=strip_lang(a),*sb=strip_lang(b);
    int r=ci_cmp(sa,sb);free(sa);free(sb);return r==0;
}

static char*decode_rfc2047(const char*input){
    if(!input)return strdup("");
    size_t ilen=strlen(input);
    Str out;str_init(&out);
    size_t pos=0;
    while(pos<ilen){
        size_t ws,we;char cs[256],enc;char et[4096];size_t clen,elen;
        if(!find_encword(input,ilen,pos,&ws,&we,cs,&clen,&enc,et,&elen)){
            str_app(&out,input+pos,ilen-pos);break;
        }
        /* output text before this word */
        if(ws>pos)str_app(&out,input+pos,ws-pos);
        /* collect run of adjacent encoded-words with same charset */
        size_t run_end=we;
        /* collect all encoded bytes */
        Str allbytes;str_init(&allbytes);
        /* decode first word */
        {
            if(enc=='B'||enc=='b'){
                size_t dl;unsigned char*d=b64_decode(et,elen,&dl);
                str_app(&allbytes,(char*)d,dl);free(d);
            } else {
                for(size_t i=0;i<elen;i++){
                    if(et[i]=='_'){str_appc(&allbytes,0x20);}
                    else if(et[i]=='='&&i+2<elen&&is_hex(et[i+1])&&is_hex(et[i+2])){
                        str_appc(&allbytes,(char)((hex_val(et[i+1])<<4)|hex_val(et[i+2])));i+=2;
                    } else str_appc(&allbytes,et[i]);
                }
            }
        }
        /* try to extend run */
        while(1){
            size_t gap_start=run_end;
            while(gap_start<ilen&&(input[gap_start]==' '||input[gap_start]=='\t'))gap_start++;
            size_t ws2,we2;char cs2[256],enc2;char et2[4096];size_t clen2,elen2;
            if(gap_start>=ilen)break;
            if(!find_encword(input,ilen,gap_start,&ws2,&we2,cs2,&clen2,&enc2,et2,&elen2))break;
            if(ws2!=gap_start)break; /* not adjacent (non-ws between) */
            if(!cs_same(cs,cs2))break;
            /* add this word's bytes */
            if(enc2=='B'||enc2=='b'){
                size_t dl;unsigned char*d=b64_decode(et2,elen2,&dl);
                str_app(&allbytes,(char*)d,dl);free(d);
            } else {
                for(size_t i=0;i<elen2;i++){
                    if(et2[i]=='_'){str_appc(&allbytes,0x20);}
                    else if(et2[i]=='='&&i+2<elen2&&is_hex(et2[i+1])&&is_hex(et2[i+2])){
                        str_appc(&allbytes,(char)((hex_val(et2[i+1])<<4)|hex_val(et2[i+2])));i+=2;
                    } else str_appc(&allbytes,et2[i]);
                }
            }
            run_end=we2;
        }
        /* decode all bytes with charset */
        size_t np;uint32_t*cps=charset_decode((unsigned char*)allbytes.s,allbytes.len,cs,&np);
        for(size_t i=0;i<np;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
        free(cps);free(allbytes.s);
        pos=run_end;
    }
    return str_take(&out);
}

/* ===== Parameter parsing ===== */
typedef struct{char*name;char*value;}Param;

static void skip_ws(const char*s,size_t*pos,size_t len){while(*pos<len&&(s[*pos]==' '||s[*pos]=='\t'))(*pos)++;}

static void parse_params(const char*s,size_t start,size_t len,Param**out,int*no){
    Param*p=NULL;int np=0;
    size_t pos=start;
    while(pos<len){
        skip_ws(s,&pos,len);
        if(pos>=len||s[pos]!=';')break;
        pos++; /* skip ; */
        skip_ws(s,&pos,len);
        /* param name */
        size_t ns=pos;
        while(pos<len&&s[pos]!='='&&s[pos]!=';'&&s[pos]!=' '&&s[pos]!='\t')pos++;
        char*pname=dupn(s+ns,pos-ns);
        for(char*c=pname;*c;c++)*c=tolower((unsigned char)*c);
        skip_ws(s,&pos,len);
        if(pos<len&&s[pos]=='='){pos++;skip_ws(s,&pos,len);}
        /* param value */
        char*pval=NULL;
        if(pos<len&&s[pos]=='"'){
            pos++;Str vs;str_init(&vs);
            while(pos<len&&s[pos]!='"'){
                if(s[pos]=='\\'&&pos+1<len){pos++;str_appc(&vs,s[pos]);pos++;}
                else{str_appc(&vs,s[pos]);pos++;}
            }
            if(pos<len)pos++; /* skip closing " */
            pval=str_take(&vs);
        } else {
            size_t vs=pos;
            while(pos<len&&s[pos]!=';'&&s[pos]!=' '&&s[pos]!='\t')pos++;
            pval=dupn(s+vs,pos-vs);
        }
        p=realloc(p,(np+1)*sizeof(Param));
        p[np].name=pname;p[np].value=pval;np++;
    }
    *out=p;*no=np;
}

static const char*find_param(Param*ps,int np,const char*name){
    for(int i=0;i<np;i++)if(!ci_cmp(ps[i].name,name))return ps[i].value;
    return NULL;
}

/* ===== RFC 2231 ===== */
static int is_rfc2231_param(Param*ps,int np,const char*attr){
    size_t alen=strlen(attr);
    for(int i=0;i<np;i++){
        size_t nlen=strlen(ps[i].name);
        if(nlen<=alen)continue;
        if(strncasecmp(ps[i].name,attr,alen)!=0)continue;
        if(ps[i].name[alen]!='*')continue;
        /* check it's a valid rfc2231 form */
        const char*rest=ps[i].name+alen+1;
        if(*rest=='\0')return 1; /* attr* single form */
        /* continuation: attr*N or attr*N* */
        while(*rest>='0'&&*rest<='9')rest++;
        if(rest>ps[i].name+alen+1){
            if(*rest=='\0'||(*rest=='*'&&*(rest+1)=='\0'))return 1;
        }
    }
    return 0;
}

static unsigned char*percent_decode(const char*s,size_t len,size_t*out_len){
    unsigned char*buf=malloc(len+1);size_t bl=0;
    for(size_t i=0;i<len;i++){
        if(s[i]=='%'&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
            buf[bl++]=(unsigned char)((hex_val(s[i+1])<<4)|hex_val(s[i+2]));i+=2;
        } else buf[bl++]=s[i];
    }
    *out_len=bl;return buf;
}

static char*decode_rfc2231(Param*ps,int np,const char*attr){
    /* single form: attr*=charset'lang'value */
    char single_name[256];snprintf(single_name,sizeof(single_name),"%s*",attr);
    const char*sv=find_param(ps,np,single_name);
    if(sv){
        /* parse charset'language'value */
        const char*q1=strchr(sv,'\'');
        if(!q1)return strdup(sv);
        char*cs=dupn(sv,q1-sv);
        const char*q2=strchr(q1+1,'\'');
        if(!q2){free(cs);return strdup(sv);}
        const char*val=q2+1;
        size_t dl;unsigned char*d=percent_decode(val,strlen(val),&dl);
        size_t np2;uint32_t*cps=charset_decode(d,dl,cs,&np2);
        Str out;str_init(&out);
        for(size_t i=0;i<np2;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
        free(cps);free(d);free(cs);
        return str_take(&out);
    }
    /* continuation form: attr*0, attr*1, ... or attr*0*, attr*1*, ... */
    int has_cont=0;
    /* collect segments */
    typedef struct{int idx;int pct;char*val;}Seg;
    Seg*segs=NULL;int nsegs=0;
    size_t alen=strlen(attr);
    for(int i=0;i<np;i++){
        size_t nlen=strlen(ps[i].name);
        if(nlen<=alen+1)continue;
        if(strncasecmp(ps[i].name,attr,alen)!=0)continue;
        if(ps[i].name[alen]!='*')continue;
        const char*rest=ps[i].name+alen+1;
        char*endp;long idx=strtol(rest,&endp,10);
        if(endp==rest)continue;
        int pct=0;
        if(*endp=='*'&&*(endp+1)=='\0')pct=1;
        else if(*endp!='\0')continue;
        segs=realloc(segs,(nsegs+1)*sizeof(Seg));
        segs[nsegs].idx=(int)idx;segs[nsegs].pct=pct;segs[nsegs].val=strdup(ps[i].value);
        nsegs++;has_cont=1;
    }
    if(!has_cont)return NULL;
    /* sort by idx */
    for(int i=0;i<nsegs;i++)for(int j=i+1;j<nsegs;j++)if(segs[j].idx<segs[i].idx){Seg t=segs[i];segs[i]=segs[j];segs[j]=t;}
    /* get charset from first percent-encoded segment */
    char*cs=NULL;
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            const char*q1=strchr(segs[i].val,'\'');
            if(q1){
                const char*q2=strchr(q1+1,'\'');
                if(q2){cs=dupn(segs[i].val,q1-segs[i].val);
                    /* strip charset'lang' from this segment */
                    char*nv=strdup(q2+1);free(segs[i].val);segs[i].val=nv;
                }
            }
            break;
        }
    }
    /* concatenate bytes */
    Str allb;str_init(&allb);
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            size_t dl;unsigned char*d=percent_decode(segs[i].val,strlen(segs[i].val),&dl);
            str_app(&allb,(char*)d,dl);free(d);
        } else {
            str_app(&allb,segs[i].val,strlen(segs[i].val));
        }
        free(segs[i].val);
    }
    free(segs);
    /* decode with charset */
    size_t np2;uint32_t*cps=charset_decode((unsigned char*)allb.s,allb.len,cs?cs:"us-ascii",&np2);
    Str out;str_init(&out);
    for(size_t i=0;i<np2;i++){char ub[4];int ul;utf8_enc(cps[i],ub,&ul);str_app(&out,ub,ul);}
    free(cps);free(allb.s);free(cs);
    return str_take(&out);
}

/* ===== Entity structure ===== */
typedef struct Entity{
    char**hnames;char**hvals;int nh;
    char*ctype_type;char*ctype_sub;Param*cparams;int ncparams;
    char*cdisp_type;Param*dparams;int ndparams;
    char*cte;
    unsigned char*body;size_t body_len;
    struct Entity*parts;int nparts;
}Entity;

static void get_header(Entity*e,const char*name,const char**out){
    for(int i=0;i<e->nh;i++)if(!ci_cmp(e->hnames[i],name)){*out=e->hvals[i];return;}
    *out=NULL;
}

/* ===== Parsing ===== */
static void parse_headers(const unsigned char*data,size_t len,int lb_len,Entity*e){
    e->hnames=NULL;e->hvals=NULL;e->nh=0;
    /* unfold: remove line break followed by space/tab */
    Str uf;str_init(&uf);
    size_t pos=0;
    while(pos<len){
        /* find end of line */
        size_t le=pos;
        while(le<len){
            if(lb_len==2&&le+1<len&&data[le]=='\r'&&data[le+1]=='\n')break;
            if(lb_len==1&&data[le]=='\n')break;
            le++;
        }
        size_t next=le+(le<len?lb_len:0);
        /* check if next char is space/tab (continuation) */
        if(next<len&&(data[next]==' '||data[next]=='\t')){
            /* unfold: add line content without line break, keep the space/tab */
            str_app(&uf,(char*)data+pos,le-pos);
            pos=next; /* skip line break, keep space/tab */
        } else {
            str_app(&uf,(char*)data+pos,le-pos);
            str_appc(&uf,'\n'); /* internal separator */
            pos=next;
        }
    }
    /* split into lines */
    char*s=uf.s;
    char*line=strtok(s,"\n");
    while(line){
        char*colon=strchr(line,':');
        if(colon){
            size_t nl=colon-line;
            char*nm=dupn(line,nl);
            for(char*c=nm;*c;c++)*c=tolower((unsigned char)*c);
            char*val=colon+1;
            while(*val==' '||*val=='\t')val++;
            size_t vl=strlen(val);
            while(vl>0&&(val[vl-1]==' '||val[vl-1]=='\t'))vl--;
            char*vv=dupn(val,vl);
            e->hnames=realloc(e->hnames,(e->nh+1)*sizeof(char*));
            e->hvals=realloc(e->hvals,(e->nh+1)*sizeof(char*));
            e->hnames[e->nh]=nm;e->hvals[e->nh]=vv;e->nh++;
        }
        line=strtok(NULL,"\n");
    }
    free(uf.s);
}

static void parse_entity(const unsigned char*data,size_t len,int lb_len,Entity*e);

static void find_body(const unsigned char*data,size_t len,int lb_len,size_t*hdr_end,size_t*body_start){
    /* find first empty line */
    size_t pos=0;
    if(len==0){*hdr_end=0;*body_start=0;return;}
    /* check if starts with line break */
    if((lb_len==2&&len>=2&&data[0]=='\r'&&data[1]=='\n')||(lb_len==1&&data[0]=='\n')){
        *hdr_end=0;*body_start=lb_len;return;
    }
    /* scan lines */
    while(pos<len){
        size_t le=pos;
        while(le<len){
            if(lb_len==2&&le+1<len&&data[le]=='\r'&&data[le+1]=='\n')break;
            if(lb_len==1&&data[le]=='\n')break;
            le++;
        }
        if(le==pos){
            /* empty line */
            *hdr_end=pos;
            *body_start=le+lb_len;
            return;
        }
        if(le>=len)break;
        pos=le+lb_len;
    }
    /* no empty line found */
    *hdr_end=len;*body_start=len;
}

static void parse_ct(const char*val,Entity*e){
    e->ctype_type=strdup("text");e->ctype_sub=strdup("plain");e->cparams=NULL;e->ncparams=0;
    if(!val){return;}
    /* find type/subtype */
    const char*slash=strchr(val,'/');
    if(!slash){e->ctype_type=strdup(val);return;}
    /* type: skip ws */
    const char*ts=val;while(*ts==' '||*ts=='\t')ts++;
    const char*te=slash;while(te>ts&&(te[-1]==' '||te[-1]=='\t'))te--;
    e->ctype_type=dupn(ts,te-ts);for(char*c=e->ctype_type;*c;c++)*c=tolower((unsigned char)*c);
    /* subtype */
    const char*ss=slash+1;while(*ss==' '||*ss=='\t')ss++;
    const char*se=ss;while(*se&&*se!=';')se++;
    while(se>ss&&(se[-1]==' '||se[-1]=='\t'))se--;
    e->ctype_sub=dupn(ss,se-ss);for(char*c=e->ctype_sub;*c;c++)*c=tolower((unsigned char)*c);
    /* params */
    const char*semi=strchr(val,';');
    if(semi)parse_params(val,semi-val,strlen(val),&e->cparams,&e->ncparams);
}

static void parse_cd(const char*val,Entity*e){
    e->cdisp_type=NULL;e->dparams=NULL;e->ndparams=0;
    if(!val)return;
    /* disposition type */
    const char*s=val;while(*s==' '||*s=='\t')s++;
    const char*te=s;while(*te&&*te!=';'&&*te!=' '&&*te!='\t')te++;
    e->cdisp_type=dupn(s,te-s);for(char*c=e->cdisp_type;*c;c++)*c=tolower((unsigned char)*c);
    /* params */
    const char*semi=strchr(val,';');
    if(semi)parse_params(val,semi-val,strlen(val),&e->dparams,&e->ndparams);
}

static int is_delim(const unsigned char*line,size_t llen,const char*B){
    size_t blen=strlen(B);
    if(llen<blen+2)return 0;
    if(line[0]!='-'||line[1]!='-')return 0;
    if(memcmp(line+2,B,blen)!=0)return 0;
    for(size_t i=2+blen;i<llen;i++){
        if(line[i]!=' '&&line[i]!='\t')return 0;
    }
    return 1;
}
static int is_close_delim(const unsigned char*line,size_t llen,const char*B){
    size_t blen=strlen(B);
    if(llen<blen+4)return 0;
    if(line[0]!='-'||line[1]!='-')return 0;
    if(memcmp(line+2,B,blen)!=0)return 0;
    if(line[2+blen]!='-'||line[3+blen]!='-')return 0;
    for(size_t i=4+blen;i<llen;i++){
        if(line[i]!=' '&&line[i]!='\t')return 0;
    }
    return 1;
}

static void parse_entity(const unsigned char*data,size_t len,int lb_len,Entity*e){
    memset(e,0,sizeof(Entity));
    size_t hdr_end,body_start;
    find_body(data,len,lb_len,&hdr_end,&body_start);
    parse_headers(data,hdr_end,lb_len,e);
    /* content type */
    const char*ctv;get_header(e,"content-type",&ctv);
    parse_ct(ctv,e);
    /* content disposition */
    const char*cdv;get_header(e,"content-disposition",&cdv);
    parse_cd(cdv,e);
    /* CTE */
    const char*ctev;get_header(e,"content-transfer-encoding",&ctev);
    if(ctev&&*ctev){
        e->cte=dupn(ctev,strlen(ctev));
        for(char*c=e->cte;*c;c++)*c=tolower((unsigned char)*c);
        /* trim */
        size_t l=strlen(e->cte);while(l>0&&(e->cte[l-1]==' '||e->cte[l-1]=='\t'))e->cte[--l]=0;
        size_t s=0;while(e->cte[s]==' '||e->cte[s]=='\t')s++;
        if(s>0){memmove(e->cte,e->cte+s,l-s+1);}
    } else e->cte=strdup("7bit");
    /* body */
    e->body=(unsigned char*)data+body_start;
    e->body_len=len-body_start;
    /* multipart? */
    if(!ci_cmp(e->ctype_type,"multipart")){
        const char*b=find_param(e->cparams,e->ncparams,"boundary");
        if(!b)b="";
        /* find delimiters in body */
        size_t*dl_pos=NULL;int n_dl=0;
        size_t pos=0;
        while(pos<e->body_len){
            size_t le=pos;
            while(le<e->body_len){
                if(lb_len==2&&le+1<e->body_len&&e->body[le]=='\r'&&e->body[le+1]=='\n')break;
                if(lb_len==1&&e->body[le]=='\n')break;
                le++;
            }
            if(is_delim(e->body+pos,le-pos,b)||is_close_delim(e->body+pos,le-pos,b)){
                dl_pos=realloc(dl_pos,(n_dl+1)*sizeof(size_t));
                dl_pos[n_dl++]=pos;
            }
            if(le>=e->body_len)break;
            pos=le+lb_len;
        }
        /* find first delimiter and close delimiter */
        int first_dl=-1,close_dl=-1;
        for(int i=0;i<n_dl;i++){
            size_t le=dl_pos[i];
            while(le<e->body_len){
                if(lb_len==2&&le+1<e->body_len&&e->body[le]=='\r'&&e->body[le+1]=='\n')break;
                if(lb_len==1&&e->body[le]=='\n')break;
                le++;
            }
            if(is_close_delim(e->body+dl_pos[i],le-dl_pos[i],b)){close_dl=i;break;}
            if(first_dl<0)first_dl=i;
        }
        /* parts are between consecutive delimiters */
        if(first_dl>=0){
            int start_i=first_dl;
            int end_i=(close_dl>=0)?close_dl:n_dl;
            int nparts=end_i-start_i;
            if(nparts<0)nparts=0;
            e->parts=malloc((nparts>0?nparts:1)*sizeof(Entity));
            e->nparts=0;
            for(int i=start_i;i<end_i;i++){
                /* part content: from after delimiter i to before delimiter i+1 */
                size_t le_i=dl_pos[i];
                while(le_i<e->body_len){
                    if(lb_len==2&&le_i+1<e->body_len&&e->body[le_i]=='\r'&&e->body[le_i+1]=='\n')break;
                    if(lb_len==1&&e->body[le_i]=='\n')break;
                    le_i++;
                }
                size_t pstart=le_i+lb_len;
                size_t pend;
                if(i+1<end_i){
                    pend=dl_pos[i+1];
                    /* remove trailing line break */
                    if(pend>pstart&&pend>=lb_len){
                        /* check if there's a line break just before pend */
                        if(lb_len==2&&pend>=2&&e->body[pend-2]=='\r'&&e->body[pend-1]=='\n')pend-=2;
                        else if(lb_len==1&&pend>=1&&e->body[pend-1]=='\n')pend-=1;
                    }
                } else {
                    /* last part before close delimiter or end of body */
                    pend=e->body_len;
                    if(pend>pstart&&pend>=lb_len){
                        if(lb_len==2&&pend>=2&&e->body[pend-2]=='\r'&&e->body[pend-1]=='\n')pend-=2;
                        else if(lb_len==1&&pend>=1&&e->body[pend-1]=='\n')pend-=1;
                    }
                }
                if(pend<pstart)pend=pstart;
                parse_entity(e->body+pstart,pend-pstart,lb_len,&e->parts[e->nparts]);
                e->nparts++;
            }
        }
        free(dl_pos);
    }
}

/* ===== Transfer decoding ===== */
static unsigned char*decode_cte(const unsigned char*body,size_t blen,const char*cte,int lb_len,size_t*out_len){
    if(!ci_cmp(cte,"base64")){
        return b64_decode((const char*)body,blen,out_len);
    } else if(!ci_cmp(cte,"quoted-printable")){
        return qp_decode(body,blen,out_len,lb_len);
    } else {
        /* 7bit, 8bit, binary */
        unsigned char*r=malloc(blen+1);memcpy(r,body,blen);*out_len=blen;return r;
    }
}

/* ===== Output helpers ===== */
static void print_quoted(FILE*f,const uint32_t*cps,size_t n){
    fputc('"',f);
    for(size_t i=0;i<n;i++){
        uint32_t c=cps[i];
        if(c=='\\')fputs("\\\\",f);
        else if(c=='"')fputs("\\\"",f);
        else if(c=='\n')fputs("\\n",f);
        else if(c=='\t')fputs("\\t",f);
        else if(c<0x20||c==0x7F||(c>=0x80&&c<=0x9F)){
            fprintf(f,"\\u%04x",c);
        } else {
            char ub[4];int ul;utf8_enc(c,ub,&ul);
            fwrite(ub,1,ul,f);
        }
    }
    fputc('"',f);
}

static void print_quoted_str(FILE*f,const char*s){
    /* decode as utf-8 to code points, then print */
    size_t slen=strlen(s);
    size_t np;uint32_t*cps=charset_decode((unsigned char*)s,slen,"utf-8",&np);
    print_quoted(f,cps,np);
    free(cps);
}

/* ===== Get filename ===== */
static char*get_filename(Entity*e){
    /* RFC 2231 Content-Disposition filename */
    if(e->dparams){
        if(is_rfc2231_param(e->dparams,e->ndparams,"filename")){
            char*r=decode_rfc2231(e->dparams,e->ndparams,"filename");
            if(r)return r;
        }
    }
    /* plain Content-Disposition filename */
    const char*fn=find_param(e->dparams?e->dparams:NULL,e->ndparams,"filename");
    if(fn)return decode_rfc2047(fn);
    /* RFC 2231 Content-Type name */
    if(e->cparams){
        if(is_rfc2231_param(e->cparams,e->ncparams,"name")){
            char*r=decode_rfc2231(e->cparams,e->ncparams,"name");
            if(r)return r;
        }
    }
    /* plain Content-Type name */
    const char*nm=find_param(e->cparams?e->cparams:NULL,e->ncparams,"name");
    if(nm)return decode_rfc2047(nm);
    return NULL;
}

/* ===== Get charset ===== */
static const char*get_charset(Entity*e){
    const char*cs=find_param(e->cparams,e->ncparams,"charset");
    return cs?cs:"us-ascii";
}

/* ===== Print tree ===== */
static void print_tree(FILE*f,Entity*e,int level,int lb_len){
    for(int i=0;i<level*2;i++)fputc(' ',f);
    if(!ci_cmp(e->ctype_type,"multipart")){
        fprintf(f,"multipart/%s parts=%d\n",e->ctype_sub,e->nparts);
        for(int i=0;i<e->nparts;i++)print_tree(f,&e->parts[i],level+1,lb_len);
    } else {
        int is_text=!ci_cmp(e->ctype_type,"text");
        int is_attach=e->cdisp_type&&!ci_cmp(e->cdisp_type,"attachment");
        if(is_text&&!is_attach){
            /* text part */
            const char*cs=get_charset(e);
            size_t dlen;
            unsigned char*decoded=decode_cte(e->body,e->body_len,e->cte,lb_len,&dlen);
            /* normalize line endings: CRLF->LF, lone CR->LF */
            Str norm;str_init(&norm);
            for(size_t i=0;i<dlen;i++){
                if(decoded[i]=='\r'){
                    if(i+1<dlen&&decoded[i+1]=='\n'){str_appc(&norm,'\n');i++;}
                    else str_appc(&norm,'\n');
                } else str_appc(&norm,decoded[i]);
            }
            free(decoded);
            size_t np;uint32_t*cps=charset_decode((unsigned char*)norm.s,norm.len,cs,&np);
            fprintf(f,"%s/%s charset=%s cte=%s chars=%zu\n",e->ctype_type,e->ctype_sub,cs,e->cte,np);
            for(int i=0;i<(level+1)*2;i++)fputc(' ',f);
            print_quoted(f,cps,np);
            fputc('\n',f);
            free(cps);free(norm.s);
        } else {
            /* other part */
            size_t dlen;
            unsigned char*decoded=decode_cte(e->body,e->body_len,e->cte,lb_len,&dlen);
            uint32_t crc=crc32_calc(decoded,dlen);
            char*fname=get_filename(e);
            const char*disp=e->cdisp_type?e->cdisp_type:"-";
            fprintf(f,"%s/%s cte=%s disposition=%s name=",e->ctype_type,e->ctype_sub,e->cte,disp);
            if(fname){print_quoted_str(f,fname);free(fname);}
            else fputc('-',f);
            fprintf(f," size=%zu crc32=%08x\n",dlen,crc);
            free(decoded);
        }
    }
}

/* ===== Main ===== */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char**argv){
    crc_init();
    if(argc<2)return 0;
    DIR*d=opendir(argv[1]);
    if(!d)return 0;
    char**files=NULL;int nf=0;
    struct dirent*de;
    while((de=readdir(d))){
        size_t l=strlen(de->d_name);
        if(l>4&&!strcmp(de->d_name+l-4,".eml")){
            files=realloc(files,(nf+1)*sizeof(char*));
            files[nf++]=strdup(de->d_name);
        }
    }
    closedir(d);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)fputc('\n',stdout);
        /* read file */
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
        unsigned char*data=malloc(fsz+1);
        fread(data,1,fsz,f);fclose(f);
        int lb_len=1;
        for(long i=0;i<fsz-1;i++){if(data[i]=='\r'&&data[i+1]=='\n'){lb_len=2;break;}}
        /* parse */
        Entity msg;
        parse_entity(data,fsz,lb_len,&msg);
        /* output */
        printf("== %s\n",files[fi]);
        const char*from;get_header(&msg,"from",&from);
        const char*subj;get_header(&msg,"subject",&subj);
        printf("From: ");
        if(from){char*d=decode_rfc2047(from);print_quoted_str(stdout,d);free(d);}
        else fputc('-',stdout);
        fputc('\n',stdout);
        printf("Subject: ");
        if(subj){char*d=decode_rfc2047(subj);print_quoted_str(stdout,d);free(d);}
        else fputc('-',stdout);
        fputc('\n',stdout);
        print_tree(stdout,&msg,0,lb_len);
        free(data);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    free(files);
    return 0;
}

import Foundation

// MARK: - Token

enum TT {
    case int, str, ident
    case letKw, fnKw, ifKw, elseKw, whileKw, forKw, inKw
    case returnKw, breakKw, continueKw
    case andKw, orKw, notKw, trueKw, falseKw, nilKw
    case eqeq, neq, lteq, gteq, lt, gt, assign
    case plus, minus, star, slash, percent
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon, eof
}

struct Token {
    let type: TT
    let text: String
    let line: Int
}

// MARK: - Lexer

func lex(_ src: String) -> [Token] {
    var tokens: [Token] = []
    let chars = Array(src)
    let n = chars.count
    var i = 0
    var line = 1

    func skipWS() {
        while i < n {
            let c = chars[i]
            if c == " " || c == "\t" || c == "\r" {
                i += 1
            } else if c == "\n" {
                line += 1; i += 1
            } else if c == "#" {
                while i < n && chars[i] != "\n" { i += 1 }
            } else {
                break
            }
        }
    }

    while true {
        skipWS()
        if i >= n { tokens.append(Token(type: .eof, text: "", line: line)); break }
        let startLine = line
        let c = chars[i]

        // Number
        if c >= "0" && c <= "9" {
            var s = ""
            while i < n && chars[i] >= "0" && chars[i] <= "9" { s.append(chars[i]); i += 1 }
            tokens.append(Token(type: .int, text: s, line: startLine))
            continue
        }

        // String
        if c == "\"" {
            i += 1
            var s = ""
            while i < n && chars[i] != "\"" {
                if chars[i] == "\\" {
                    i += 1
                    if i < n {
                        let e = chars[i]
                        switch e {
                        case "n": s.append("\n")
                        case "t": s.append("\t")
                        case "\"": s.append("\"")
                        case "\\": s.append("\\")
                        default: s.append(e)
                        }
                        i += 1
                    }
                } else {
                    s.append(chars[i]); i += 1
                }
            }
            i += 1 // skip closing "
            tokens.append(Token(type: .str, text: s, line: startLine))
            continue
        }

        // Identifier / keyword
        if c.isLetter || c == "_" {
            var s = ""
            while i < n && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_") { s.append(chars[i]); i += 1 }
            let tt: TT
            switch s {
            case "let": tt = .letKw
            case "fn": tt = .fnKw
            case "if": tt = .ifKw
            case "else": tt = .elseKw
            case "while": tt = .whileKw
            case "for": tt = .forKw
            case "in": tt = .inKw
            case "return": tt = .returnKw
            case "break": tt = .breakKw
            case "continue": tt = .continueKw
            case "and": tt = .andKw
            case "or": tt = .orKw
            case "not": tt = .notKw
            case "true": tt = .trueKw
            case "false": tt = .falseKw
            case "nil": tt = .nilKw
            default: tt = .ident
            }
            tokens.append(Token(type: tt, text: s, line: startLine))
            continue
        }

        // Operators / punctuation
        func two(_ a: Character, _ b: Character, _ t: TT) -> Bool {
            if i + 1 < n && chars[i] == a && chars[i+1] == b {
                i += 2; tokens.append(Token(type: t, text: "\(a)\(b)", line: startLine)); return true
            }
            return false
        }

        if two("=", "=", .eqeq) { continue }
        if two("!", "=", .neq) { continue }
        if two("<", "=", .lteq) { continue }
        if two(">", "=", .gteq) { continue }

        let one: (Character, TT) -> Bool = { ch, t in
            if chars[i] == ch { i += 1; tokens.append(Token(type: t, text: String(ch), line: startLine)); return true }
            return false
        }

        if one("<", .lt) { continue }
        if one(">", .gt) { continue }
        if one("=", .assign) { continue }
        if one("+", .plus) { continue }
        if one("-", .minus) { continue }
        if one("*", .star) { continue }
        if one("/", .slash) { continue }
        if one("%", .percent) { continue }
        if one("(", .lparen) { continue }
        if one(")", .rparen) { continue }
        if one("[", .lbracket) { continue }
        if one("]", .rbracket) { continue }
        if one("{", .lbrace) { continue }
        if one("}", .rbrace) { continue }
        if one(",", .comma) { continue }
        if one(";", .semicolon) { continue }

        // Shouldn't reach here for valid programs
        i += 1
    }
    return tokens
}

// MARK: - AST

indirect enum Expr {
    case intLit(Int, Int) // value, line
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binOp(String, Expr, Expr, Int) // op, left, right, line
    case unOp(String, Expr, Int) // "-", "not"
    case call(Expr, [Expr], Int) // callee, args, line of '('
    case index(Expr, Expr, Int) // obj, idx, line of '['
    case listLit([Expr], Int)
    case fnExpr([String], [Stmt], Int) // params, body, line
}

indirect enum Stmt {
    case letStmt(String, Expr, Int)
    case fnDecl(String, [String], [Stmt], Int)
    case ifStmt(Expr, [Stmt], [Stmt]?, Int)
    case whileStmt(Expr, [Stmt], Int)
    case forStmt(String, Expr, [Stmt], Int)
    case returnStmt(Expr?, Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assignStmt(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int) // obj, idx, val, line of '['
    case exprStmt(Expr, Int)
}

// MARK: - Values

final class TernList {
    var elements: [Value]
    init(_ e: [Value]) { elements = e }
}

final class TernFunc {
    let params: [String]
    let body: [Stmt]
    let capturedScope: Scope
    let isBuiltin: Bool
    let builtinFn: (([Value], Int) throws -> Value)?
    let arity: Int? // nil for variadic
    let name: String

    init(params: [String], body: [Stmt], capturedScope: Scope) {
        self.params = params; self.body = body; self.capturedScope = capturedScope
        self.isBuiltin = false; self.builtinFn = nil; self.arity = params.count; self.name = "<fn>"
    }

    init(name: String, arity: Int?, builtinFn: @escaping ([Value], Int) throws -> Value) {
        self.params = []; self.body = []; self.capturedScope = Scope(parent: nil)
        self.isBuiltin = true; self.builtinFn = builtinFn; self.arity = arity; self.name = name
    }
}

enum Value {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(TernList)
    case fn(TernFunc)
    case nil_

    var typeName: String {
        switch self {
        case .int: return "int"
        case .bool: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .fn: return "function"
        case .nil_: return "nil"
        }
    }

    var isTruthy: Bool {
        switch self {
        case .int(let v): return v != 0
        case .bool(let v): return v
        case .string(let v): return !v.isEmpty
        case .list(let l): return !l.elements.isEmpty
        case .fn: return true
        case .nil_: return false
        }
    }
}

// MARK: - Scope

final class Scope {
    var vars: [String: Value]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func get(_ name: String) -> Value? {
        var s: Scope? = self
        while let cur = s {
            if let v = cur.vars[name] { return v }
            s = cur.parent
        }
        return nil
    }

    func set(_ name: String, _ val: Value) -> Bool {
        var s: Scope? = self
        while let cur = s {
            if cur.vars[name] != nil { cur.vars[name] = val; return true }
            s = cur.parent
        }
        return false
    }

    func declare(_ name: String, _ val: Value) {
        vars[name] = val
    }
}

// MARK: - Errors

struct TernError: Error {
    let line: Int
    let msg: String
}

struct BreakSignal: Error {}
struct ContinueSignal: Error {}
struct ReturnSignal: Error { let value: Value }

// MARK: - Interpreter

final class Interpreter {
    let globalScope: Scope

    init() {
        let builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        setupBuiltins(builtinScope)
    }

    func setupBuiltins(_ scope: Scope) {
        scope.declare("print", .fn(TernFunc(name: "print", arity: nil) { args, _ in
            var parts: [String] = []
            for a in args { parts.append(displayValue(a, inList: false, visited: [])) }
            print(parts.joined(separator: " "))
            return .nil_
        }))

        scope.declare("str", .fn(TernFunc(name: "str", arity: 1) { args, _ in
            return .string(displayValue(args[0], inList: false, visited: []))
        }))

        scope.declare("type", .fn(TernFunc(name: "type", arity: 1) { args, _ in
            return .string(args[0].typeName)
        }))

        scope.declare("len", .fn(TernFunc(name: "len", arity: 1) { args, line in
            switch args[0] {
            case .string(let s): return .int(s.count)
            case .list(let l): return .int(l.elements.count)
            default: throw TernError(line: line, msg: "bad argument to len")
            }
        }))

        scope.declare("push", .fn(TernFunc(name: "push", arity: 2) { args, line in
            guard case .list(let l) = args[0] else { throw TernError(line: line, msg: "bad argument to push") }
            l.elements.append(args[1])
            return .nil_
        }))

        scope.declare("pop", .fn(TernFunc(name: "pop", arity: 1) { args, line in
            guard case .list(let l) = args[0] else { throw TernError(line: line, msg: "bad argument to pop") }
            guard !l.elements.isEmpty else { throw TernError(line: line, msg: "bad argument to pop") }
            return l.elements.removeLast()
        }))

        scope.declare("range", .fn(TernFunc(name: "range", arity: 2) { args, line in
            guard case .int(let a) = args[0], case .int(let b) = args[1] else {
                throw TernError(line: line, msg: "bad argument to range")
            }
            if b <= a { return .list(TernList([])) }
            var elems: [Value] = []
            elems.reserveCapacity(b - a)
            var v = a
            while v < b { elems.append(.int(v)); v += 1 }
            return .list(TernList(elems))
        }))

        scope.declare("slice", .fn(TernFunc(name: "slice", arity: 3) { args, line in
            let x = args[0]
            guard case .int(let a) = args[1], case .int(let b) = args[2] else {
                throw TernError(line: line, msg: "bad argument to slice")
            }
            switch x {
            case .string(let s):
                let arr = Array(s)
                guard a >= 0 && b <= arr.count && a <= b else { throw TernError(line: line, msg: "bad argument to slice") }
                return .string(String(arr[a..<b]))
            case .list(let l):
                guard a >= 0 && b <= l.elements.count && a <= b else { throw TernError(line: line, msg: "bad argument to slice") }
                return .list(TernList(Array(l.elements[a..<b])))
            default:
                throw TernError(line: line, msg: "bad argument to slice")
            }
        }))
    }

    func displayValue(_ v: Value, inList: Bool, visited: Set<ObjectIdentifier>) -> String {
        switch v {
        case .int(let x): return String(x)
        case .bool(let x): return x ? "true" : "false"
        case .nil_: return "nil"
        case .fn: return "<fn>"
        case .string(let s):
            if inList {
                var r = "\""
                for ch in s {
                    switch ch {
                    case "\\": r += "\\\\"
                    case "\"": r += "\\\""
                    case "\n": r += "\\n"
                    case "\t": r += "\\t"
                    default: r.append(ch)
                    }
                }
                r += "\""
                return r
            } else {
                return s
            }
        case .list(let l):
            let oid = ObjectIdentifier(l)
            if visited.contains(oid) { return "[...]" }
            var newVisited = visited
            newVisited.insert(oid)
            var parts: [String] = []
            for e in l.elements { parts.append(displayValue(e, inList: true, visited: newVisited)) }
            return "[" + parts.joined(separator: ", ") + "]"
        }
    }

    func valuesEqual(_ a: Value, _ b: Value) -> Bool {
        switch (a, b) {
        case (.int(let x), .int(let y)): return x == y
        case (.bool(let x), .bool(let y)): return x == y
        case (.string(let x), .string(let y)): return x == y
        case (.nil_, .nil_): return true
        case (.fn(let x), .fn(let y)): return x === y
        case (.list(let x), .list(let y)):
            if x.elements.count != y.elements.count { return false }
            for i in 0..<x.elements.count {
                if !valuesEqual(x.elements[i], y.elements[i]) { return false }
            }
            return true
        default: return false
        }
    }

    // MARK: - Evaluation

    func eval(_ e: Expr, _ scope: Scope) throws -> Value {
        switch e {
        case .intLit(let v, _): return .int(v)
        case .strLit(let s, _): return .string(s)
        case .boolLit(let b, _): return .bool(b)
        case .nilLit: return .nil_
        case .ident(let name, let line):
            if let v = scope.get(name) { return v }
            throw TernError(line: line, msg: "undefined variable \(name)")
        case .binOp(let op, let l, let r, let line):
            let lv = try eval(l, scope)
            let rv = try eval(r, scope)
            return try applyBinOp(op, lv, rv, line)
        case .unOp(let op, let operand, let line):
            let v = try eval(operand, scope)
            if op == "-" {
                guard case .int(let x) = v else { throw TernError(line: line, msg: "cannot apply - to \(v.typeName)") }
                if x == Int.min { throw TernError(line: line, msg: "integer overflow") }
                return .int(-x)
            } else { // not
                return .bool(!v.isTruthy)
            }
        case .call(let calleeExpr, let argExprs, let line):
            let callee = try eval(calleeExpr, scope)
            var args: [Value] = []
            for ae in argExprs { args.append(try eval(ae, scope)) }
            return try callFunction(callee, args, line)
        case .index(let objExpr, let idxExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            return try indexAccess(obj, idx, line)
        case .listLit(let elems, _):
            var vals: [Value] = []
            for e in elems { vals.append(try eval(e, scope)) }
            return .list(TernList(vals))
        case .fnExpr(let params, let body, _):
            return .fn(TernFunc(params: params, body: body, capturedScope: scope))
        }
    }

    func applyBinOp(_ op: String, _ l: Value, _ r: Value, _ line: Int) throws -> Value {
        switch op {
        case "and":
            if !l.isTruthy { return l }
            return r
        case "or":
            if l.isTruthy { return l }
            return r
        case "not":
            return .bool(!l.isTruthy)
        case "==": return .bool(valuesEqual(l, r))
        case "!=": return .bool(!valuesEqual(l, r))
        case "+":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.addingReportingOverflow(b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            if case .string(let a) = l, case .string(let b) = r { return .string(a + b) }
            if case .list(let a) = l, case .list(let b) = r {
                return .list(TernList(a.elements + b.elements))
            }
            throw TernError(line: line, msg: "cannot apply + to \(l.typeName) and \(r.typeName)")
        case "-":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.subtractingReportingOverflow(b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply - to \(l.typeName) and \(r.typeName)")
        case "*":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.multipliedReportingOverflow(by: b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply * to \(l.typeName) and \(r.typeName)")
        case "/":
            if case .int(let a) = l, case .int(let b) = r {
                if b == 0 { throw TernError(line: line, msg: "division by zero") }
                if a == Int.min && b == -1 { throw TernError(line: line, msg: "integer overflow") }
                return .int(a / b)
            }
            throw TernError(line: line, msg: "cannot apply / to \(l.typeName) and \(r.typeName)")
        case "%":
            if case .int(let a) = l, case .int(let b) = r {
                if b == 0 { throw TernError(line: line, msg: "division by zero") }
                if b == -1 { return .int(0) }
                let q = a / b
                let (qb, ov) = q.multipliedReportingOverflow(by: b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                let (res, ov2) = a.subtractingReportingOverflow(qb)
                if ov2 { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply % to \(l.typeName) and \(r.typeName)")
        case "<":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a < b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a < b) }
            throw TernError(line: line, msg: "cannot apply < to \(l.typeName) and \(r.typeName)")
        case "<=":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a <= b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a <= b) }
            throw TernError(line: line, msg: "cannot apply <= to \(l.typeName) and \(r.typeName)")
        case ">":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a > b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a > b) }
            throw TernError(line: line, msg: "cannot apply > to \(l.typeName) and \(r.typeName)")
        case ">=":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a >= b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a >= b) }
            throw TernError(line: line, msg: "cannot apply >= to \(l.typeName) and \(r.typeName)")
        default:
            throw TernError(line: line, msg: "unknown op \(op)")
        }
    }

    func callFunction(_ callee: Value, _ args: [Value], _ line: Int) throws -> Value {
        guard case .fn(let f) = callee else {
            throw TernError(line: line, msg: "cannot call \(callee.typeName)")
        }
        if let ar = f.arity {
            if args.count != ar {
                throw TernError(line: line, msg: "expected \(ar) arguments, got \(args.count)")
            }
        }
        if f.isBuiltin {
            return try f.builtinFn!(args, line)
        }
        let callScope = Scope(parent: f.capturedScope)
        for (i, p) in f.params.enumerated() {
            callScope.declare(p, args[i])
        }
        do {
            try execBlock(f.body, callScope)
        } catch let ret as ReturnSignal {
            return ret.value
        }
        return .nil_
    }

    func indexAccess(_ obj: Value, _ idx: Value, _ line: Int) throws -> Value {
        switch obj {
        case .list(let l):
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index list with \(idx.typeName)")
            }
            if i < 0 || i >= l.elements.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(l.elements.count)")
            }
            return l.elements[i]
        case .string(let s):
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index string with \(idx.typeName)")
            }
            let arr = Array(s)
            if i < 0 || i >= arr.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(arr.count)")
            }
            return .string(String(arr[i]))
        default:
            throw TernError(line: line, msg: "cannot index \(obj.typeName) with \(idx.typeName)")
        }
    }

    // MARK: - Statement Execution

    func execBlock(_ stmts: [Stmt], _ scope: Scope) throws {
        for s in stmts {
            try execStmt(s, scope)
        }
    }

    func execStmt(_ s: Stmt, _ scope: Scope) throws {
        switch s {
        case .letStmt(let name, let expr, _):
            let v = try eval(expr, scope)
            scope.declare(name, v)
        case .fnDecl(let name, let params, let body, _):
            let f = TernFunc(params: params, body: body, capturedScope: scope)
            scope.declare(name, .fn(f))
        case .ifStmt(let cond, let thenBody, let elseBody, _):
            let cv = try eval(cond, scope)
            if cv.isTruthy {
                let s2 = Scope(parent: scope)
                try execBlock(thenBody, s2)
            } else if let eb = elseBody {
                let s2 = Scope(parent: scope)
                try execBlock(eb, s2)
            }
        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try eval(cond, scope)
                if !cv.isTruthy { break }
                let s2 = Scope(parent: scope)
                do {
                    try execBlock(body, s2)
                } catch is BreakSignal { break }
                catch is ContinueSignal { continue }
            }
        case .forStmt(let varName, let iterExpr, let body, let line):
            let listVal = try eval(iterExpr, scope)
            guard case .list(let lst) = listVal else {
                throw TernError(line: line, msg: "cannot iterate \(listVal.typeName)")
            }
            var i = 0
            while i < lst.elements.count {
                let s2 = Scope(parent: scope)
                s2.declare(varName, lst.elements[i])
                do {
                    try execBlock(body, s2)
                } catch is BreakSignal { break }
                catch is ContinueSignal { }
                i += 1
            }
        case .returnStmt(let expr, _):
            if let e = expr {
                let v = try eval(e, scope)
                throw ReturnSignal(value: v)
            } else {
                throw ReturnSignal(value: .nil_)
            }
        case .breakStmt: throw BreakSignal()
        case .continueStmt: throw ContinueSignal()
        case .assignStmt(let name, let expr, let line):
            let v = try eval(expr, scope)
            if !scope.set(name, v) {
                throw TernError(line: line, msg: "undefined variable \(name)")
            }
        case .indexAssign(let objExpr, let idxExpr, let valExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            let val = try eval(valExpr, scope)
            guard case .list(let l) = obj else {
                throw TernError(line: line, msg: "cannot assign into \(obj.typeName)")
            }
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index list with \(idx.typeName)")
            }
            if i < 0 || i >= l.elements.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(l.elements.count)")
            }
            l.elements[i] = val
        case .exprStmt(let expr, _):
            _ = try eval(expr, scope)
        }
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execBlock(stmts, globalScope)
        } catch let err as TernError {
            print("error at line \(err.line): \(err.msg)")
        } catch {
            // shouldn't happen
        }
    }
}

// MARK: - Parser

final class Parser {
    let tokens: [Token]
    var pos: Int = 0

    init(_ tokens: [Token]) { self.tokens = tokens }

    func peek() -> Token { tokens[pos] }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ tt: TT) -> Token {
        let t = tokens[pos]
        if t.type != tt { fatalError("Expected \(tt) but got \(t.type) at line \(t.line)") }
        pos += 1
        return t
    }
    func match(_ tt: TT) -> Bool {
        if tokens[pos].type == tt { pos += 1; return true }
        return false
    }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while peek().type != .eof {
            stmts.append(parseStmt())
        }
        return stmts
    }

    func parseStmt() -> Stmt {
        let t = peek()
        switch t.type {
        case .letKw:
            advance()
            let name = expect(.ident).text
            expect(.assign)
            let expr = parseExpr()
            expect(.semicolon)
            return .letStmt(name, expr, t.line)
        case .fnKw:
            advance()
            let name = expect(.ident).text
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name, params, body, t.line)
        case .ifKw:
            return parseIfStmt()
        case .whileKw:
            advance()
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond, body, t.line)
        case .forKw:
            advance()
            let varName = expect(.ident).text
            expect(.inKw)
            let iterExpr = parseExpr()
            let body = parseBlock()
            return .forStmt(varName, iterExpr, body, t.line)
        case .returnKw:
            advance()
            if peek().type == .semicolon {
                advance()
                return .returnStmt(nil, t.line)
            }
            let expr = parseExpr()
            expect(.semicolon)
            return .returnStmt(expr, t.line)
        case .breakKw:
            advance(); expect(.semicolon)
            return .breakStmt(t.line)
        case .continueKw:
            advance(); expect(.semicolon)
            return .continueStmt(t.line)
        case .ident:
            // Check for assignment: IDENT = expr ;
            if tokens[pos+1].type == .assign {
                advance()
                let name = advance().text
                expect(.assign)
                let expr = parseExpr()
                expect(.semicolon)
                return .assignStmt(name, expr, t.line)
            }
            // Otherwise parse expression, check for index assignment
            let expr = parseExpr()
            if peek().type == .lbracket {
                // index assignment: expr[idx] = val ;
                let lbTok = advance() // consume [
                let idx = parseExpr()
                expect(.rbracket)
                expect(.assign)
                let val = parseExpr()
                expect(.semicolon)
                return .indexAssign(expr, idx, val, lbTok.line)
            }
            expect(.semicolon)
            return .exprStmt(expr, t.line)
        default:
            let expr = parseExpr()
            expect(.semicolon)
            return .exprStmt(expr, t.line)
        }
    }

    func parseIfStmt() -> Stmt {
        let t = expect(.ifKw)
        let cond = parseExpr()
        let thenBody = parseBlock()
        var elseBody: [Stmt]? = nil
        if peek().type == .elseKw {
            advance()
            if peek().type == .ifKw {
                let ifStmt = parseIfStmt()
                elseBody = [ifStmt]
            } else {
                elseBody = parseBlock()
            }
        }
        return .ifStmt(cond, thenBody, elseBody, t.line)
    }

    func parseBlock() -> [Stmt] {
        expect(.lbrace)
        var stmts: [Stmt] = []
        while peek().type != .rbrace {
            stmts.append(parseStmt())
        }
        expect(.rbrace)
        return stmts
    }

    func parseParams() -> [String] {
        var params: [String] = []
        if peek().type != .rparen {
            params.append(expect(.ident).text)
            while match(.comma) {
                params.append(expect(.ident).text)
            }
        }
        return params
    }

    // MARK: - Expression Parsing (precedence climbing)

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var left = parseAnd()
        while peek().type == .orKw {
            let t = advance()
            let right = parseAnd()
            left = .binOp("or", left, right, t.line)
        }
        return left
    }

    func parseAnd() -> Expr {
        var left = parseNot()
        while peek().type == .andKw {
            let t = advance()
            let right = parseNot()
            left = .binOp("and", left, right, t.line)
        }
        return left
    }

    func parseNot() -> Expr {
        if peek().type == .notKw {
            let t = advance()
            let operand = parseNot()
            return .unOp("not", operand, t.line)
        }
        return parseComp()
    }

    func parseComp() -> Expr {
        var left = parseAdd()
        while true {
            let t = peek()
            let op: String?
            switch t.type {
            case .eqeq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .lteq: op = "<="
            case .gt: op = ">"
            case .gteq: op = ">="
            default: op = nil
            }
            if op == nil { break }
            advance()
            let right = parseAdd()
            left = .binOp(op!, left, right, t.line)
        }
        return left
    }

    func parseAdd() -> Expr {
        var left = parseMul()
        while peek().type == .plus || peek().type == .minus {
            let t = advance()
            let op = t.type == .plus ? "+" : "-"
            let right = parseMul()
            left = .binOp(op, left, right, t.line)
        }
        return left
    }

    func parseMul() -> Expr {
        var left = parseUnary()
        while peek().type == .star || peek().type == .slash || peek().type == .percent {
            let t = advance()
            let op: String
            switch t.type {
            case .star: op = "*"
            case .slash: op = "/"
            default: op = "%"
            }
            let right = parseUnary()
            left = .binOp(op, left, right, t.line)
        }
        return left
    }

    func parseUnary() -> Expr {
        if peek().type == .minus {
            let t = advance()
            let operand = parseUnary()
            return .unOp("-", operand, t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var expr = parsePrimary()
        while true {
            if peek().type == .lparen {
                let t = advance()
                var args: [Expr] = []
                if peek().type != .rparen {
                    args.append(parseExpr())
                    while match(.comma) { args.append(parseExpr()) }
                }
                expect(.rparen)
                expr = .call(expr, args, t.line)
            } else if peek().type == .lbracket {
                let t = advance()
                let idx = parseExpr()
                expect(.rbracket)
                expr = .index(expr, idx, t.line)
            } else {
                break
            }
        }
        return expr
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.type {
        case .int:
            advance()
            return .intLit(Int(t.text)!, t.line)
        case .str:
            advance()
            return .strLit(t.text, t.line)
        case .trueKw:
            advance()
            return .boolLit(true, t.line)
        case .falseKw:
            advance()
            return .boolLit(false, t.line)
        case .nilKw:
            advance()
            return .nilLit(t.line)
        case .ident:
            advance()
            return .ident(t.text, t.line)
        case .lparen:
            advance()
            let expr = parseExpr()
            expect(.rparen)
            return expr
        case .lbracket:
            advance()
            var elems: [Expr] = []
            if peek().type != .rbracket {
                elems.append(parseExpr())
                while match(.comma) { elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .fnKw:
            advance()
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params, body, t.line)
        default:
            fatalError("Unexpected token \(t.type) at line \(t.line)")
        }
    }
}

// MARK: - Main

let args = CommandLine.arguments
if args.count < 2 {
    exit(0)
}

let dir = args[1]
let path = (dir as NSString).appendingPathComponent("program.tern")
guard let src = try? String(contentsOfFile: path, encoding: .ascii) else {
    exit(0)
}

let tokens = lex(src)
let parser = Parser(tokens)
let stmts = parser.parseProgram()
let interp = Interpreter()
interp.run(stmts)
exit(0)

import Foundation

// MARK: - Token

enum TT {
    case int, str, ident
    case letKw, fnKw, ifKw, elseKw, whileKw, forKw, inKw
    case returnKw, breakKw, continueKw
    case andKw, orKw, notKw, trueKw, falseKw, nilKw
    case eqeq, neq, lteq, gteq, lt, gt, assign
    case plus, minus, star, slash, percent
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon, eof
}

struct Token {
    let type: TT
    let text: String
    let line: Int
}

// MARK: - Lexer

func lex(_ src: String) -> [Token] {
    var tokens: [Token] = []
    let chars = Array(src)
    let n = chars.count
    var i = 0
    var line = 1

    func skipWS() {
        while i < n {
            let c = chars[i]
            if c == " " || c == "\t" || c == "\r" {
                i += 1
            } else if c == "\n" {
                line += 1; i += 1
            } else if c == "#" {
                while i < n && chars[i] != "\n" { i += 1 }
            } else {
                break
            }
        }
    }

    while true {
        skipWS()
        if i >= n { tokens.append(Token(type: .eof, text: "", line: line)); break }
        let startLine = line
        let c = chars[i]

        // Number
        if c >= "0" && c <= "9" {
            var s = ""
            while i < n && chars[i] >= "0" && chars[i] <= "9" { s.append(chars[i]); i += 1 }
            tokens.append(Token(type: .int, text: s, line: startLine))
            continue
        }

        // String
        if c == "\"" {
            i += 1
            var s = ""
            while i < n && chars[i] != "\"" {
                if chars[i] == "\\" {
                    i += 1
                    if i < n {
                        let e = chars[i]
                        switch e {
                        case "n": s.append("\n")
                        case "t": s.append("\t")
                        case "\"": s.append("\"")
                        case "\\": s.append("\\")
                        default: s.append(e)
                        }
                        i += 1
                    }
                } else {
                    s.append(chars[i]); i += 1
                }
            }
            i += 1 // skip closing "
            tokens.append(Token(type: .str, text: s, line: startLine))
            continue
        }

        // Identifier / keyword
        if c.isLetter || c == "_" {
            var s = ""
            while i < n && (chars[i].isLetter || chars[i].isNumber || chars[i] == "_") { s.append(chars[i]); i += 1 }
            let tt: TT
            switch s {
            case "let": tt = .letKw
            case "fn": tt = .fnKw
            case "if": tt = .ifKw
            case "else": tt = .elseKw
            case "while": tt = .whileKw
            case "for": tt = .forKw
            case "in": tt = .inKw
            case "return": tt = .returnKw
            case "break": tt = .breakKw
            case "continue": tt = .continueKw
            case "and": tt = .andKw
            case "or": tt = .orKw
            case "not": tt = .notKw
            case "true": tt = .trueKw
            case "false": tt = .falseKw
            case "nil": tt = .nilKw
            default: tt = .ident
            }
            tokens.append(Token(type: tt, text: s, line: startLine))
            continue
        }

        // Operators / punctuation (two-char first)
        func two(_ a: Character, _ b: Character, _ t: TT) -> Bool {
            if i + 1 < n && chars[i] == a && chars[i+1] == b {
                i += 2; tokens.append(Token(type: t, text: "\(a)\(b)", line: startLine)); return true
            }
            return false
        }

        if two("=", "=", .eqeq) { continue }
        if two("!", "=", .neq) { continue }
        if two("<", "=", .lteq) { continue }
        if two(">", "=", .gteq) { continue }

        let one: (Character, TT) -> Bool = { ch, t in
            if chars[i] == ch { i += 1; tokens.append(Token(type: t, text: String(ch), line: startLine)); return true }
            return false
        }

        if one("<", .lt) { continue }
        if one(">", .gt) { continue }
        if one("=", .assign) { continue }
        if one("+", .plus) { continue }
        if one("-", .minus) { continue }
        if one("*", .star) { continue }
        if one("/", .slash) { continue }
        if one("%", .percent) { continue }
        if one("(", .lparen) { continue }
        if one(")", .rparen) { continue }
        if one("[", .lbracket) { continue }
        if one("]", .rbracket) { continue }
        if one("{", .lbrace) { continue }
        if one("}", .rbrace) { continue }
        if one(",", .comma) { continue }
        if one(";", .semicolon) { continue }

        // Shouldn't reach here for valid programs
        i += 1
    }
    return tokens
}

// MARK: - AST

indirect enum Expr {
    case intLit(Int, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binOp(String, Expr, Expr, Int)
    case unOp(String, Expr, Int)
    case call(Expr, [Expr], Int)
    case index(Expr, Expr, Int)
    case listLit([Expr], Int)
    case fnExpr([String], [Stmt], Int)
}

indirect enum Stmt {
    case letStmt(String, Expr, Int)
    case fnDecl(String, [String], [Stmt], Int)
    case ifStmt(Expr, [Stmt], [Stmt]?, Int)
    case whileStmt(Expr, [Stmt], Int)
    case forStmt(String, Expr, [Stmt], Int)
    case returnStmt(Expr?, Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assignStmt(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int)
    case exprStmt(Expr, Int)
}

// MARK: - Values

final class TernList {
    var elements: [Value]
    init(_ e: [Value]) { elements = e }
}

final class TernFunc {
    let params: [String]
    let body: [Stmt]
    let capturedScope: Scope
    let isBuiltin: Bool
    let builtinFn: (([Value], Int) throws -> Value)?
    let arity: Int?
    let name: String

    init(params: [String], body: [Stmt], capturedScope: Scope) {
        self.params = params; self.body = body; self.capturedScope = capturedScope
        self.isBuiltin = false; self.builtinFn = nil; self.arity = params.count; self.name = "<fn>"
    }

    init(name: String, arity: Int?, builtinFn: @escaping ([Value], Int) throws -> Value) {
        self.params = []; self.body = []; self.capturedScope = Scope(parent: nil)
        self.isBuiltin = true; self.builtinFn = builtinFn; self.arity = arity; self.name = name
    }
}

enum Value {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(TernList)
    case fn(TernFunc)
    case nil_

    var typeName: String {
        switch self {
        case .int: return "int"
        case .bool: return "bool"
        case .string: return "string"
        case .list: return "list"
        case .fn: return "function"
        case .nil_: return "nil"
        }
    }

    var isTruthy: Bool {
        switch self {
        case .int(let v): return v != 0
        case .bool(let v): return v
        case .string(let v): return !v.isEmpty
        case .list(let l): return !l.elements.isEmpty
        case .fn: return true
        case .nil_: return false
        }
    }
}

// MARK: - Scope

final class Scope {
    var vars: [String: Value]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func get(_ name: String) -> Value? {
        var s: Scope? = self
        while let cur = s {
            if let v = cur.vars[name] { return v }
            s = cur.parent
        }
        return nil
    }

    func set(_ name: String, _ val: Value) -> Bool {
        var s: Scope? = self
        while let cur = s {
            if cur.vars[name] != nil { cur.vars[name] = val; return true }
            s = cur.parent
        }
        return false
    }

    func declare(_ name: String, _ val: Value) {
        vars[name] = val
    }
}

// MARK: - Errors

struct TernError: Error {
    let line: Int
    let msg: String
}

struct BreakSignal: Error {}
struct ContinueSignal: Error {}
struct ReturnSignal: Error { let value: Value }

// MARK: - Interpreter

final class Interpreter {
    let globalScope: Scope

    init() {
        let builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        setupBuiltins(builtinScope)
    }

    func setupBuiltins(_ scope: Scope) {
        scope.declare("print", .fn(TernFunc(name: "print", arity: nil) { args, _ in
            var parts: [String] = []
            for a in args { parts.append(Interpreter.displayValue(a, inList: false, visited: [])) }
            print(parts.joined(separator: " "))
            return .nil_
        }))

        scope.declare("str", .fn(TernFunc(name: "str", arity: 1) { args, _ in
            return .string(Interpreter.displayValue(args[0], inList: false, visited: []))
        }))

        scope.declare("type", .fn(TernFunc(name: "type", arity: 1) { args, _ in
            return .string(args[0].typeName)
        }))

        scope.declare("len", .fn(TernFunc(name: "len", arity: 1) { args, line in
            switch args[0] {
            case .string(let s): return .int(s.count)
            case .list(let l): return .int(l.elements.count)
            default: throw TernError(line: line, msg: "bad argument to len")
            }
        }))

        scope.declare("push", .fn(TernFunc(name: "push", arity: 2) { args, line in
            guard case .list(let l) = args[0] else { throw TernError(line: line, msg: "bad argument to push") }
            l.elements.append(args[1])
            return .nil_
        }))

        scope.declare("pop", .fn(TernFunc(name: "pop", arity: 1) { args, line in
            guard case .list(let l) = args[0] else { throw TernError(line: line, msg: "bad argument to pop") }
            guard !l.elements.isEmpty else { throw TernError(line: line, msg: "bad argument to pop") }
            return l.elements.removeLast()
        }))

        scope.declare("range", .fn(TernFunc(name: "range", arity: 2) { args, line in
            guard case .int(let a) = args[0], case .int(let b) = args[1] else {
                throw TernError(line: line, msg: "bad argument to range")
            }
            if b <= a { return .list(TernList([])) }
            var elems: [Value] = []
            elems.reserveCapacity(b - a)
            var v = a
            while v < b { elems.append(.int(v)); v += 1 }
            return .list(TernList(elems))
        }))

        scope.declare("slice", .fn(TernFunc(name: "slice", arity: 3) { args, line in
            let x = args[0]
            guard case .int(let a) = args[1], case .int(let b) = args[2] else {
                throw TernError(line: line, msg: "bad argument to slice")
            }
            switch x {
            case .string(let s):
                let arr = Array(s)
                guard a >= 0 && b <= arr.count && a <= b else { throw TernError(line: line, msg: "bad argument to slice") }
                return .string(String(arr[a..<b]))
            case .list(let l):
                guard a >= 0 && b <= l.elements.count && a <= b else { throw TernError(line: line, msg: "bad argument to slice") }
                return .list(TernList(Array(l.elements[a..<b])))
            default:
                throw TernError(line: line, msg: "bad argument to slice")
            }
        }))
    }

    static func displayValue(_ v: Value, inList: Bool, visited: Set<ObjectIdentifier>) -> String {
        switch v {
        case .int(let x): return String(x)
        case .bool(let x): return x ? "true" : "false"
        case .nil_: return "nil"
        case .fn: return "<fn>"
        case .string(let s):
            if inList {
                var r = "\""
                for ch in s {
                    switch ch {
                    case "\\": r += "\\\\"
                    case "\"": r += "\\\""
                    case "\n": r += "\\n"
                    case "\t": r += "\\t"
                    default: r.append(ch)
                    }
                }
                r += "\""
                return r
            } else {
                return s
            }
        case .list(let l):
            let oid = ObjectIdentifier(l)
            if visited.contains(oid) { return "[...]" }
            var newVisited = visited
            newVisited.insert(oid)
            var parts: [String] = []
            for e in l.elements { parts.append(displayValue(e, inList: true, visited: newVisited)) }
            return "[" + parts.joined(separator: ", ") + "]"
        }
    }

    func valuesEqual(_ a: Value, _ b: Value) -> Bool {
        switch (a, b) {
        case (.int(let x), .int(let y)): return x == y
        case (.bool(let x), .bool(let y)): return x == y
        case (.string(let x), .string(let y)): return x == y
        case (.nil_, .nil_): return true
        case (.fn(let x), .fn(let y)): return x === y
        case (.list(let x), .list(let y)):
            if x.elements.count != y.elements.count { return false }
            for i in 0..<x.elements.count {
                if !valuesEqual(x.elements[i], y.elements[i]) { return false }
            }
            return true
        default: return false
        }
    }

    // MARK: - Evaluation

    func eval(_ e: Expr, _ scope: Scope) throws -> Value {
        switch e {
        case .intLit(let v, _): return .int(v)
        case .strLit(let s, _): return .string(s)
        case .boolLit(let b, _): return .bool(b)
        case .nilLit: return .nil_
        case .ident(let name, let line):
            if let v = scope.get(name) { return v }
            throw TernError(line: line, msg: "undefined variable \(name)")
        case .binOp(let op, let l, let r, let line):
            let lv = try eval(l, scope)
            let rv = try eval(r, scope)
            return try applyBinOp(op, lv, rv, line)
        case .unOp(let op, let operand, let line):
            let v = try eval(operand, scope)
            if op == "-" {
                guard case .int(let x) = v else { throw TernError(line: line, msg: "cannot apply - to \(v.typeName)") }
                if x == Int.min { throw TernError(line: line, msg: "integer overflow") }
                return .int(-x)
            } else {
                return .bool(!v.isTruthy)
            }
        case .call(let calleeExpr, let argExprs, let line):
            let callee = try eval(calleeExpr, scope)
            var args: [Value] = []
            for ae in argExprs { args.append(try eval(ae, scope)) }
            return try callFunction(callee, args, line)
        case .index(let objExpr, let idxExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            return try indexAccess(obj, idx, line)
        case .listLit(let elems, _):
            var vals: [Value] = []
            for e in elems { vals.append(try eval(e, scope)) }
            return .list(TernList(vals))
        case .fnExpr(let params, let body, _):
            return .fn(TernFunc(params: params, body: body, capturedScope: scope))
        }
    }

    func applyBinOp(_ op: String, _ l: Value, _ r: Value, _ line: Int) throws -> Value {
        switch op {
        case "and":
            if !l.isTruthy { return l }
            return r
        case "or":
            if l.isTruthy { return l }
            return r
        case "==": return .bool(valuesEqual(l, r))
        case "!=": return .bool(!valuesEqual(l, r))
        case "+":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.addingReportingOverflow(b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            if case .string(let a) = l, case .string(let b) = r { return .string(a + b) }
            if case .list(let a) = l, case .list(let b) = r {
                return .list(TernList(a.elements + b.elements))
            }
            throw TernError(line: line, msg: "cannot apply + to \(l.typeName) and \(r.typeName)")
        case "-":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.subtractingReportingOverflow(b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply - to \(l.typeName) and \(r.typeName)")
        case "*":
            if case .int(let a) = l, case .int(let b) = r {
                let (res, ov) = a.multipliedReportingOverflow(by: b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply * to \(l.typeName) and \(r.typeName)")
        case "/":
            if case .int(let a) = l, case .int(let b) = r {
                if b == 0 { throw TernError(line: line, msg: "division by zero") }
                if a == Int.min && b == -1 { throw TernError(line: line, msg: "integer overflow") }
                return .int(a / b)
            }
            throw TernError(line: line, msg: "cannot apply / to \(l.typeName) and \(r.typeName)")
        case "%":
            if case .int(let a) = l, case .int(let b) = r {
                if b == 0 { throw TernError(line: line, msg: "division by zero") }
                if b == -1 { return .int(0) }
                let q = a / b
                let (qb, ov) = q.multipliedReportingOverflow(by: b)
                if ov { throw TernError(line: line, msg: "integer overflow") }
                let (res, ov2) = a.subtractingReportingOverflow(qb)
                if ov2 { throw TernError(line: line, msg: "integer overflow") }
                return .int(res)
            }
            throw TernError(line: line, msg: "cannot apply % to \(l.typeName) and \(r.typeName)")
        case "<":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a < b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a < b) }
            throw TernError(line: line, msg: "cannot apply < to \(l.typeName) and \(r.typeName)")
        case "<=":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a <= b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a <= b) }
            throw TernError(line: line, msg: "cannot apply <= to \(l.typeName) and \(r.typeName)")
        case ">":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a > b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a > b) }
            throw TernError(line: line, msg: "cannot apply > to \(l.typeName) and \(r.typeName)")
        case ">=":
            if case .int(let a) = l, case .int(let b) = r { return .bool(a >= b) }
            if case .string(let a) = l, case .string(let b) = r { return .bool(a >= b) }
            throw TernError(line: line, msg: "cannot apply >= to \(l.typeName) and \(r.typeName)")
        default:
            throw TernError(line: line, msg: "unknown op \(op)")
        }
    }

    func callFunction(_ callee: Value, _ args: [Value], _ line: Int) throws -> Value {
        guard case .fn(let f) = callee else {
            throw TernError(line: line, msg: "cannot call \(callee.typeName)")
        }
        if let ar = f.arity {
            if args.count != ar {
                throw TernError(line: line, msg: "expected \(ar) arguments, got \(args.count)")
            }
        }
        if f.isBuiltin {
            return try f.builtinFn!(args, line)
        }
        let callScope = Scope(parent: f.capturedScope)
        for (i, p) in f.params.enumerated() {
            callScope.declare(p, args[i])
        }
        do {
            try execBlock(f.body, callScope)
        } catch let ret as ReturnSignal {
            return ret.value
        }
        return .nil_
    }

    func indexAccess(_ obj: Value, _ idx: Value, _ line: Int) throws -> Value {
        switch obj {
        case .list(let l):
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index list with \(idx.typeName)")
            }
            if i < 0 || i >= l.elements.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(l.elements.count)")
            }
            return l.elements[i]
        case .string(let s):
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index string with \(idx.typeName)")
            }
            let arr = Array(s)
            if i < 0 || i >= arr.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(arr.count)")
            }
            return .string(String(arr[i]))
        default:
            throw TernError(line: line, msg: "cannot index \(obj.typeName) with \(idx.typeName)")
        }
    }

    // MARK: - Statement Execution

    func execBlock(_ stmts: [Stmt], _ scope: Scope) throws {
        for s in stmts {
            try execStmt(s, scope)
        }
    }

    func execStmt(_ s: Stmt, _ scope: Scope) throws {
        switch s {
        case .letStmt(let name, let expr, _):
            let v = try eval(expr, scope)
            scope.declare(name, v)
        case .fnDecl(let name, let params, let body, _):
            let f = TernFunc(params: params, body: body, capturedScope: scope)
            scope.declare(name, .fn(f))
        case .ifStmt(let cond, let thenBody, let elseBody, _):
            let cv = try eval(cond, scope)
            if cv.isTruthy {
                let s2 = Scope(parent: scope)
                try execBlock(thenBody, s2)
            } else if let eb = elseBody {
                let s2 = Scope(parent: scope)
                try execBlock(eb, s2)
            }
        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try eval(cond, scope)
                if !cv.isTruthy { break }
                let s2 = Scope(parent: scope)
                do {
                    try execBlock(body, s2)
                } catch is BreakSignal { break }
                catch is ContinueSignal { continue }
            }
        case .forStmt(let varName, let iterExpr, let body, let line):
            let listVal = try eval(iterExpr, scope)
            guard case .list(let lst) = listVal else {
                throw TernError(line: line, msg: "cannot iterate \(listVal.typeName)")
            }
            var i = 0
            while i < lst.elements.count {
                let s2 = Scope(parent: scope)
                s2.declare(varName, lst.elements[i])
                do {
                    try execBlock(body, s2)
                } catch is BreakSignal { break }
                catch is ContinueSignal { }
                i += 1
            }
        case .returnStmt(let expr, _):
            if let e = expr {
                let v = try eval(e, scope)
                throw ReturnSignal(value: v)
            } else {
                throw ReturnSignal(value: .nil_)
            }
        case .breakStmt: throw BreakSignal()
        case .continueStmt: throw ContinueSignal()
        case .assignStmt(let name, let expr, let line):
            let v = try eval(expr, scope)
            if !scope.set(name, v) {
                throw TernError(line: line, msg: "undefined variable \(name)")
            }
        case .indexAssign(let objExpr, let idxExpr, let valExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            let val = try eval(valExpr, scope)
            guard case .list(let l) = obj else {
                throw TernError(line: line, msg: "cannot assign into \(obj.typeName)")
            }
            guard case .int(let i) = idx else {
                throw TernError(line: line, msg: "cannot index list with \(idx.typeName)")
            }
            if i < 0 || i >= l.elements.count {
                throw TernError(line: line, msg: "index \(i) out of range for length \(l.elements.count)")
            }
            l.elements[i] = val
        case .exprStmt(let expr, _):
            _ = try eval(expr, scope)
        }
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execBlock(stmts, globalScope)
        } catch let err as TernError {
            print("error at line \(err.line): \(err.msg)")
        } catch {
            // shouldn't happen
        }
    }
}

// MARK: - Parser

final class Parser {
    let tokens: [Token]
    var pos: Int = 0

    init(_ tokens: [Token]) { self.tokens = tokens }

    func peek() -> Token { tokens[pos] }
    @discardableResult func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    @discardableResult func expect(_ tt: TT) -> Token {
        let t = tokens[pos]
        if t.type != tt { fatalError("Expected \(tt) but got \(t.type) at line \(t.line)") }
        pos += 1
        return t
    }
    func match(_ tt: TT) -> Bool {
        if tokens[pos].type == tt { pos += 1; return true }
        return false
    }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while peek().type != .eof {
            stmts.append(parseStmt())
        }
        return stmts
    }

    func parseStmt() -> Stmt {
        let t = peek()
        switch t.type {
        case .letKw:
            advance()
            let name = expect(.ident).text
            expect(.assign)
            let expr = parseExpr()
            expect(.semicolon)
            return .letStmt(name, expr, t.line)
        case .fnKw:
            advance()
            let name = expect(.ident).text
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name, params, body, t.line)
        case .ifKw:
            return parseIfStmt()
        case .whileKw:
            advance()
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond, body, t.line)
        case .forKw:
            advance()
            let varName = expect(.ident).text
            expect(.inKw)
            let iterExpr = parseExpr()
            let body = parseBlock()
            return .forStmt(varName, iterExpr, body, t.line)
        case .returnKw:
            advance()
            if peek().type == .semicolon {
                advance()
                return .returnStmt(nil, t.line)
            }
            let expr = parseExpr()
            expect(.semicolon)
            return .returnStmt(expr, t.line)
        case .breakKw:
            advance(); expect(.semicolon)
            return .breakStmt(t.line)
        case .continueKw:
            advance(); expect(.semicolon)
            return .continueStmt(t.line)
        case .ident:
            // Check for assignment: IDENT = expr ;
            if tokens[pos+1].type == .assign {
                let name = advance().text
                expect(.assign)
                let expr = parseExpr()
                expect(.semicolon)
                return .assignStmt(name, expr, t.line)
            }
            // Otherwise parse expression, check for index assignment
            let expr = parseExpr()
            if peek().type == .lbracket {
                let lbTok = advance()
                let idx = parseExpr()
                expect(.rbracket)
                expect(.assign)
                let val = parseExpr()
                expect(.semicolon)
                return .indexAssign(expr, idx, val, lbTok.line)
            }
            expect(.semicolon)
            return .exprStmt(expr, t.line)
        default:
            let expr = parseExpr()
            expect(.semicolon)
            return .exprStmt(expr, t.line)
        }
    }

    func parseIfStmt() -> Stmt {
        let t = expect(.ifKw)
        let cond = parseExpr()
        let thenBody = parseBlock()
        var elseBody: [Stmt]? = nil
        if peek().type == .elseKw {
            advance()
            if peek().type == .ifKw {
                let ifStmt = parseIfStmt()
                elseBody = [ifStmt]
            } else {
                elseBody = parseBlock()
            }
        }
        return .ifStmt(cond, thenBody, elseBody, t.line)
    }

    func parseBlock() -> [Stmt] {
        expect(.lbrace)
        var stmts: [Stmt] = []
        while peek().type != .rbrace {
            stmts.append(parseStmt())
        }
        expect(.rbrace)
        return stmts
    }

    func parseParams() -> [String] {
        var params: [String] = []
        if peek().type != .rparen {
            params.append(expect(.ident).text)
            while match(.comma) {
                params.append(expect(.ident).text)
            }
        }
        return params
    }

    // MARK: - Expression Parsing

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var left = parseAnd()
        while peek().type == .orKw {
            let t = advance()
            let right = parseAnd()
            left = .binOp("or", left, right, t.line)
        }
        return left
    }

    func parseAnd() -> Expr {
        var left = parseNot()
        while peek().type == .andKw {
            let t = advance()
            let right = parseNot()
            left = .binOp("and", left, right, t.line)
        }
        return left
    }

    func parseNot() -> Expr {
        if peek().type == .notKw {
            let t = advance()
            let operand = parseNot()
            return .unOp("not", operand, t.line)
        }
        return parseComp()
    }

    func parseComp() -> Expr {
        var left = parseAdd()
        while true {
            let t = peek()
            let op: String?
            switch t.type {
            case .eqeq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .lteq: op = "<="
            case .gt: op = ">"
            case .gteq: op = ">="
            default: op = nil
            }
            if op == nil { break }
            advance()
            let right = parseAdd()
            left = .binOp(op!, left, right, t.line)
        }
        return left
    }

    func parseAdd() -> Expr {
        var left = parseMul()
        while peek().type == .plus || peek().type == .minus {
            let t = advance()
            let op = t.type == .plus ? "+" : "-"
            let right = parseMul()
            left = .binOp(op, left, right, t.line)
        }
        return left
    }

    func parseMul() -> Expr {
        var left = parseUnary()
        while peek().type == .star || peek().type == .slash || peek().type == .percent {
            let t = advance()
            let op: String
            switch t.type {
            case .star: op = "*"
            case .slash: op = "/"
            default: op = "%"
            }
            let right = parseUnary()
            left = .binOp(op, left, right, t.line)
        }
        return left
    }

    func parseUnary() -> Expr {
        if peek().type == .minus {
            let t = advance()
            let operand = parseUnary()
            return .unOp("-", operand, t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var expr = parsePrimary()
        while true {
            if peek().type == .lparen {
                let t = advance()
                var args: [Expr] = []
                if peek().type != .rparen {
                    args.append(parseExpr())
                    while match(.comma) { args.append(parseExpr()) }
                }
                expect(.rparen)
                expr = .call(expr, args, t.line)
            } else if peek().type == .lbracket {
                let t = advance()
                let idx = parseExpr()
                expect(.rbracket)
                expr = .index(expr, idx, t.line)
            } else {
                break
            }
        }
        return expr
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.type {
        case .int:
            advance()
            return .intLit(Int(t.text)!, t.line)
        case .str:
            advance()
            return .strLit(t.text, t.line)
        case .trueKw:
            advance()
            return .boolLit(true, t.line)
        case .falseKw:
            advance()
            return .boolLit(false, t.line)
        case .nilKw:
            advance()
            return .nilLit(t.line)
        case .ident:
            advance()
            return .ident(t.text, t.line)
        case .lparen:
            advance()
            let expr = parseExpr()
            expect(.rparen)
            return expr
        case .lbracket:
            advance()
            var elems: [Expr] = []
            if peek().type != .rbracket {
                elems.append(parseExpr())
                while match(.comma) { elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .fnKw:
            advance()
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params, body, t.line)
        default:
            fatalError("Unexpected token \(t.type) at line \(t.line)")
        }
    }
}

// MARK: - Main

let args = CommandLine.arguments
if args.count < 2 {
    exit(0)
}

let dir = args[1]
let path = (dir as NSString).appendingPathComponent("program.tern")
guard let src = try? String(contentsOfFile: path, encoding: .ascii) else {
    exit(0)
}

let tokens = lex(src)
let parser = Parser(tokens)
let stmts = parser.parseProgram()
let interp = Interpreter()
interp.run(stmts)
exit(0)

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    // ==================== TOKENS ====================
    enum TT { INT, STR, IDENT, LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
              AND, OR, NOT, TRUE, FALSE, NIL,
              EQ, NEQ, LE, GE, LT, GT, ASSIGN, PLUS, MINUS, STAR, SLASH, PERCENT,
              LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE, COMMA, SEMI, EOF }

    static class Token {
        TT type; String str; long ival; int line;
        Token(TT t, String s, int l) { type=t; str=s; line=l; }
        Token(TT t, long v, int l) { type=t; ival=v; line=l; }
    }

    // ==================== LEXER ====================
    static class Lexer {
        String src; int pos, line;
        Lexer(String s) { src=s; pos=0; line=1; }

        void skipWs() {
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (c=='\n') { line++; pos++; }
                else if (c==' '||c=='\t'||c=='\r') pos++;
                else if (c=='#') { while(pos<src.length()&&src.charAt(pos)!='\n') pos++; }
                else break;
            }
        }

        List<Token> tokenize() {
            List<Token> toks = new ArrayList<>();
            while (true) {
                skipWs();
                if (pos >= src.length()) { toks.add(new Token(TT.EOF,"",line)); break; }
                char c = src.charAt(pos);
                int sl = line;
                if (Character.isDigit(c)) {
                    int start=pos;
                    while(pos<src.length()&&Character.isDigit(src.charAt(pos))) pos++;
                    toks.add(new Token(TT.INT, Long.parseLong(src.substring(start,pos)), sl));
                } else if (c=='"') {
                    pos++; StringBuilder sb=new StringBuilder();
                    while(pos<src.length()) {
                        char ch=src.charAt(pos);
                        if(ch=='"'){pos++;break;}
                        if(ch=='\\'){pos++;char e=src.charAt(pos);
                            switch(e){case'n':sb.append('\n');break;case't':sb.append('\t');break;
                            case'"':sb.append('"');break;case'\\':sb.append('\\');break;}
                            pos++;
                        } else { sb.append(ch); pos++; }
                    }
                    toks.add(new Token(TT.STR, sb.toString(), sl));
                } else if (Character.isLetter(c)||c=='_') {
                    int start=pos;
                    while(pos<src.length()&&(Character.isLetterOrDigit(src.charAt(pos))||src.charAt(pos)=='_')) pos++;
                    String w=src.substring(start,pos);
                    TT t = switch(w) {
                        case "let"->TT.LET; case "fn"->TT.FN; case "if"->TT.IF; case "else"->TT.ELSE;
                        case "while"->TT.WHILE; case "for"->TT.FOR; case "in"->TT.IN;
                        case "return"->TT.RETURN; case "break"->TT.BREAK; case "continue"->TT.CONTINUE;
                        case "and"->TT.AND; case "or"->TT.OR; case "not"->TT.NOT;
                        case "true"->TT.TRUE; case "false"->TT.FALSE; case "nil"->TT.NIL;
                        default->TT.IDENT;
                    };
                    toks.add(new Token(t,w,sl));
                } else {
                    String op;
                    if(pos+1<src.length()) {
                        String two=src.substring(pos,pos+2);
                        if(two.equals("==")){toks.add(new Token(TT.EQ,"==",sl));pos+=2;continue;}
                        if(two.equals("!=")){toks.add(new Token(TT.NEQ,"!=",sl));pos+=2;continue;}
                        if(two.equals("<=")){toks.add(new Token(TT.LE,"<=",sl));pos+=2;continue;}
                        if(two.equals(">=")){toks.add(new Token(TT.GE,">=",sl));pos+=2;continue;}
                    }
                    switch(c) {
                        case '<':toks.add(new Token(TT.LT,"<",sl));pos++;break;
                        case '>':toks.add(new Token(TT.GT,">",sl));pos++;break;
                        case '=':toks.add(new Token(TT.ASSIGN,"=",sl));pos++;break;
                        case '+':toks.add(new Token(TT.PLUS,"+",sl));pos++;break;
                        case '-':toks.add(new Token(TT.MINUS,"-",sl));pos++;break;
                        case '*':toks.add(new Token(TT.STAR,"*",sl));pos++;break;
                        case '/':toks.add(new Token(TT.SLASH,"/",sl));pos++;break;
                        case '%':toks.add(new Token(TT.PERCENT,"%",sl));pos++;break;
                        case '(':toks.add(new Token(TT.LPAREN,"(",sl));pos++;break;
                        case ')':toks.add(new Token(TT.RPAREN,")",sl));pos++;break;
                        case '[':toks.add(new Token(TT.LBRACKET,"[",sl));pos++;break;
                        case ']':toks.add(new Token(TT.RBRACKET,"]",sl));pos++;break;
                        case '{':toks.add(new Token(TT.LBRACE,"{",sl));pos++;break;
                        case '}':toks.add(new Token(TT.RBRACE,"}",sl));pos++;break;
                        case ',':toks.add(new Token(TT.COMMA,",",sl));pos++;break;
                        case ';':toks.add(new Token(TT.SEMI,";",sl));pos++;break;
                        default: pos++; break;
                    }
                }
            }
            return toks;
        }
    }

    // ==================== AST ====================
    static abstract class Expr { int line; }
    static class IntLit extends Expr { long v; IntLit(long v,int l){this.v=v;line=l;} }
    static class StrLit extends Expr { String v; StrLit(String v,int l){this.v=v;line=l;} }
    static class BoolLit extends Expr { boolean v; BoolLit(boolean v,int l){this.v=v;line=l;} }
    static class NilLit extends Expr { NilLit(int l){line=l;} }
    static class IdentExpr extends Expr { String name; IdentExpr(String n,int l){name=n;line=l;} }
    static class ListLit extends Expr { List<Expr> elems; ListLit(List<Expr> e,int l){elems=e;line=l;} }
    static class FnExpr extends Expr { List<String> params; List<Stmt> body; FnExpr(List<String> p,List<Stmt> b,int l){params=p;body=b;line=l;} }
    static class BinaryExpr extends Expr { String op; Expr l,r; BinaryExpr(String o,Expr l,Expr r,int ln){op=o;this.l=l;this.r=r;line=ln;} }
    static class AndExpr extends Expr { Expr l,r; AndExpr(Expr l,Expr r){this.l=l;this.r=r;line=0;} }
    static class OrExpr extends Expr { Expr l,r; OrExpr(Expr l,Expr r){this.l=l;this.r=r;line=0;} }
    static class NotExpr extends Expr { Expr e; NotExpr(Expr e){this.e=e;} }
    static class NegExpr extends Expr { Expr e; NegExpr(Expr e){this.e=e;} }
    static class CallExpr extends Expr { Expr callee; List<Expr> args; int openLine; CallExpr(Expr c,List<Expr> a,int ol){callee=c;args=a;openLine=ol;line=ol;} }
    static class IndexExpr extends Expr { Expr obj,idx; int brLine; IndexExpr(Expr o,Expr i,int bl){obj=o;idx=i;brLine=bl;line=bl;} }

    static abstract class Stmt { int line; }
    static class LetStmt extends Stmt { String name; Expr val; LetStmt(String n,Expr v,int l){name=n;val=v;line=l;} }
    static class FnStmt extends Stmt { String name; List<String> params; List<Stmt> body; FnStmt(String n,List<String> p,List<Stmt> b,int l){name=n;params=p;body=b;line=l;} }
    static class IfStmt extends Stmt { Expr cond; List<Stmt> then; List<Stmt> els; IfStmt(Expr c,List<Stmt> t,List<Stmt> e,int l){cond=c;then=t;els=e;line=l;} }
    static class WhileStmt extends Stmt { Expr cond; List<Stmt> body; WhileStmt(Expr c,List<Stmt> b,int l){cond=c;body=b;line=l;} }
    static class ForStmt extends Stmt { String var; Expr iter; List<Stmt> body; int line; ForStmt(String v,Expr e,List<Stmt> b,int l){var=v;iter=e;body=b;line=l;} }
    static class ReturnStmt extends Stmt { Expr val; ReturnStmt(Expr v,int l){val=v;line=l;} }
    static class BreakStmt extends Stmt { BreakStmt(int l){line=l;} }
    static class ContinueStmt extends Stmt { ContinueStmt(int l){line=l;} }
    static class AssignStmt extends Stmt { String name; Expr val; AssignStmt(String n,Expr v,int l){name=n;val=v;line=l;} }
    static class IndexAssignStmt extends Stmt { Expr obj,idx,val; int brLine; IndexAssignStmt(Expr o,Expr i,Expr v,int bl){obj=o;idx=i;val=v;brLine=bl;line=bl;} }
    static class ExprStmt extends Stmt { Expr e; ExprStmt(Expr e){this.e=e;} }

    // ==================== PARSER ====================
    static class Parser {
        List<Token> toks; int pos;
        Parser(List<Token> t){toks=t;pos=0;}
        Token peek(){return toks.get(pos);}
        Token advance(){return toks.get(pos++);}
        boolean check(TT t){return peek().type==t;}
        Token expect(TT t){Token tk=peek();if(tk.type!=t)throw new RuntimeException("expected "+t+" got "+tk.type);pos++;return tk;}

        List<Stmt> parseProgram(){List<Stmt> r=new ArrayList<>();while(!check(TT.EOF))r.add(parseStmt());return r;}

        List<Stmt> parseBlock(){expect(TT.LBRACE);List<Stmt> r=new ArrayList<>();while(!check(TT.RBRACE)&&!check(TT.EOF))r.add(parseStmt());expect(TT.RBRACE);return r;}

        Stmt parseStmt(){
            Token tk=peek();
            switch(tk.type){
                case LET:{advance();String n=expect(TT.IDENT).str;expect(TT.ASSIGN);Expr v=parseExpr();expect(TT.SEMI);return new LetStmt(n,v,tk.line);}
                case FN:{
                    if(toks.get(pos+1).type==TT.IDENT){
                        advance();String n=expect(TT.IDENT).str;expect(TT.LPAREN);List<String> p=parseParams();expect(TT.RPAREN);List<Stmt> b=parseBlock();return new FnStmt(n,p,b,tk.line);
                    } else { return parseExprOrAssign(); }
                }
                case IF:return parseIfStmt();
                case WHILE:{advance();Expr c=parseExpr();List<Stmt> b=parseBlock();return new WhileStmt(c,b,tk.line);}
                case FOR:{advance();String v=expect(TT.IDENT).str;expect(TT.IN);Expr e=parseExpr();List<Stmt> b=parseBlock();return new ForStmt(v,e,b,tk.line);}
                case RETURN:{advance();Expr e=null;if(!check(TT.SEMI))e=parseExpr();expect(TT.SEMI);return new ReturnStmt(e,tk.line);}
                case BREAK:{advance();expect(TT.SEMI);return new BreakStmt(tk.line);}
                case CONTINUE:{advance();expect(TT.SEMI);return new ContinueStmt(tk.line);}
                default: return parseExprOrAssign();
            }
        }

        Stmt parseExprOrAssign(){
            int startLine=peek().line;
            if(peek().type==TT.IDENT && toks.get(pos+1).type==TT.ASSIGN){
                String n=advance().str;advance();Expr v=parseExpr();expect(TT.SEMI);return new AssignStmt(n,v,startLine);
            }
            Expr e=parsePostfix();
            if(check(TT.ASSIGN)){
                advance();Expr v=parseExpr();expect(TT.SEMI);
                if(e instanceof IndexExpr ix){return new IndexAssignStmt(ix.obj,ix.idx,v,ix.brLine);}
                throw new RuntimeException("invalid assignment target");
            }
            expect(TT.SEMI);return new ExprStmt(e);
        }

        Stmt parseIfStmt(){
            Token tk=expect(TT.IF);Expr c=parseExpr();List<Stmt> then=parseBlock();List<Stmt> els=null;
            if(check(TT.ELSE)){advance();if(check(TT.IF))els=List.of(parseIfStmt());else els=parseBlock();}
            return new IfStmt(c,then,els,tk.line);
        }

        List<String> parseParams(){
            List<String> r=new ArrayList<>();
            if(check(TT.IDENT)){r.add(advance().str);while(check(TT.COMMA)){advance();r.add(expect(TT.IDENT).str);}}
            return r;
        }

        Expr parseExpr(){return parseOr();}
        Expr parseOr(){Expr l=parseAnd();while(check(TT.OR)){advance();Expr r=parseAnd();l=new OrExpr(l,r);}return l;}
        Expr parseAnd(){Expr l=parseNot();while(check(TT.AND)){advance();Expr r=parseNot();l=new AndExpr(l,r);}return l;}
        Expr parseNot(){if(check(TT.NOT)){advance();Expr e=parseNot();return new NotExpr(e);}return parseComparison();}
        Expr parseComparison(){
            Expr l=parseAddSub();
            while(check(TT.EQ)||check(TT.NEQ)||check(TT.LT)||check(TT.LE)||check(TT.GT)||check(TT.GE)){
                Token op=advance();Expr r=parseAddSub();l=new BinaryExpr(op.str,l,r,op.line);
            }
            return l;
        }
        Expr parseAddSub(){
            Expr l=parseMulDiv();
            while(check(TT.PLUS)||check(TT.MINUS)){Token op=advance();Expr r=parseMulDiv();l=new BinaryExpr(op.str,l,r,op.line);}
            return l;
        }
        Expr parseMulDiv(){
            Expr l=parseUnary();
            while(check(TT.STAR)||check(TT.SLASH)||check(TT.PERCENT)){Token op=advance();Expr r=parseUnary();l=new BinaryExpr(op.str,l,r,op.line);}
            return l;
        }
        Expr parseUnary(){if(check(TT.MINUS)){advance();Expr e=parseUnary();return new NegExpr(e);}return parsePostfix();}
        Expr parsePostfix(){
            Expr e=parsePrimary();
            while(true){
                if(check(TT.LPAREN)){
                    int ol=advance().line;List<Expr> args=new ArrayList<>();
                    if(!check(TT.RPAREN)){args.add(parseExpr());while(check(TT.COMMA)){advance();args.add(parseExpr());}}
                    expect(TT.RPAREN);e=new CallExpr(e,args,ol);
                } else if(check(TT.LBRACKET)){
                    int bl=advance().line;Expr idx=parseExpr();expect(TT.RBRACKET);e=new IndexExpr(e,idx,bl);
                } else break;
            }
            return e;
        }
        Expr parsePrimary(){
            Token tk=peek();
            switch(tk.type){
                case INT:{advance();return new IntLit(tk.ival,tk.line);}
                case STR:{advance();return new StrLit(tk.str,tk.line);}
                case TRUE:{advance();return new BoolLit(true,tk.line);}
                case FALSE:{advance();return new BoolLit(false,tk.line);}
                case NIL:{advance();return new NilLit(tk.line);}
                case IDENT:{advance();return new IdentExpr(tk.str,tk.line);}
                case LPAREN:{advance();Expr e=parseExpr();expect(TT.RPAREN);return e;}
                case LBRACKET:{
                    advance();List<Expr> elems=new ArrayList<>();
                    if(!check(TT.RBRACKET)){elems.add(parseExpr());while(check(TT.COMMA)){advance();elems.add(parseExpr());}}
                    expect(TT.RBRACKET);return new ListLit(elems,tk.line);
                }
                case FN:{
                    advance();expect(TT.LPAREN);List<String> p=parseParams();expect(TT.RPAREN);List<Stmt> b=parseBlock();return new FnExpr(p,b,tk.line);
                }
                default: throw new RuntimeException("unexpected token: "+tk.type);
            }
        }
    }

    // ==================== VALUES ====================
    static final Object NIL = new Object(){public String toString(){return "nil";}};

    static class TernFunction {
        String name; List<String> params; List<Stmt> body; Scope captured;
        int paramCount; boolean variadic; BuiltinFn builtin;
        TernFunction(String name,List<String> params,List<Stmt> body,Scope cap){
            this.name=name;this.params=params;this.body=body;this.captured=cap;this.builtin=null;
        }
        TernFunction(String name,int pc,BuiltinFn fn){
            this.name=name;this.paramCount=pc;this.builtin=fn;this.variadic=(pc==-1);
        }
    }
    interface BuiltinFn { Object call(List<Object> args, int line); }

    static class Scope {
        Map<String,Object> vars=new HashMap<>();
        Scope parent;
        Scope(Scope p){parent=p;}
        Object get(String name){
            Scope s=this;
            while(s!=null){if(s.vars.containsKey(name))return s.vars.get(name);s=s.parent;}
            return null;
        }
        boolean has(String name){Scope s=this;while(s!=null){if(s.vars.containsKey(name))return true;s=s.parent;}return false;}
        void set(String name,Object v){
            Scope s=this;
            while(s!=null){if(s.vars.containsKey(name)){s.vars.put(name,v);return;}s=s.parent;}
        }
        void declare(String name,Object v){vars.put(name,v);}
    }

    // ==================== ERRORS ====================
    static class TernError extends RuntimeException {
        String msg; int line;
        TernError(String msg,int line){super(msg);this.msg=msg;this.line=line;}
    }
    static class BreakEx extends RuntimeException { BreakEx(){super(null,null,false,false);} }
    static class ContinueEx extends RuntimeException { ContinueEx(){super(null,null,false,false);} }
    static class ReturnEx extends RuntimeException { Object val; ReturnEx(Object v){super(null,null,false,false);val=v;} }

    // ==================== INTERPRETER ====================
    static class Interpreter {
        Scope globalScope;
        StringBuilder out = new StringBuilder();

        Interpreter() {
            Scope builtins = new Scope(null);
            globalScope = new Scope(builtins);
            setupBuiltins(builtins);
        }

        void setupBuiltins(Scope bs) {
            bs.declare("print", new TernFunction("print",-1,args->{
                for(int i=0;i<args.size();i++){
                    if(i>0)out.append(' ');
                    out.append(display(args.get(i),false,new ArrayList<>()));
                }
                out.append('\n');return NIL;
            }));
            bs.declare("str", new TernFunction("str",1,args->{
                return display(args.get(0),false,new ArrayList<>());
            }));
            bs.declare("type", new TernFunction("type",1,args->{
                return typeName(args.get(0));
            }));
            bs.declare("len", new TernFunction("len",1,args->{
                Object v=args.get(0);
                if(v instanceof String)return (long)((String)v).length();
                if(v instanceof ArrayList)return (long)((ArrayList<?>)v).size();
                throw new TernError("bad argument to len",0);
            }));
            bs.declare("push", new TernFunction("push",2,args->{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TernError("bad argument to push",0);
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                list.add(args.get(1));return NIL;
            }));
            bs.declare("pop", new TernFunction("pop",1,args->{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TernError("bad argument to pop",0);
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                if(list.isEmpty())throw new TernError("bad argument to pop",0);
                return list.remove(list.size()-1);
            }));
            bs.declare("range", new TernFunction("range",2,args->{
                Object a=args.get(0),b=args.get(1);
                if(!(a instanceof Long)||!(b instanceof Long))throw new TernError("bad argument to range",0);
                long lo=(Long)a,hi=(Long)b;
                ArrayList<Object> r=new ArrayList<>();
                for(long i=lo;i<hi;i++)r.add(i);
                return r;
            }));
            bs.declare("slice", new TernFunction("slice",3,args->{
                Object x=args.get(0),ai=args.get(1),bi=args.get(2);
                if(!(ai instanceof Long)||!(bi instanceof Long))throw new TernError("bad argument to slice",0);
                long a=(Long)ai,b=(Long)bi;
                if(x instanceof String){
                    String s=(String)x;
                    if(a<0||b>s.length()||a>b)throw new TernError("bad argument to slice",0);
                    return s.substring((int)a,(int)b);
                } else if(x instanceof ArrayList){
                    @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)x;
                    if(a<0||b>list.size()||a>b)throw new TernError("bad argument to slice",0);
                    return new ArrayList<>(list.subList((int)a,(int)b));
                }
                throw new TernError("bad argument to slice",0);
            }));
        }

        String typeName(Object v){
            if(v instanceof Long)return "int";
            if(v instanceof Boolean)return "bool";
            if(v instanceof String)return "string";
            if(v instanceof ArrayList)return "list";
            if(v instanceof TernFunction)return "function";
            if(v==NIL)return "nil";
            return "nil";
        }

        boolean truthy(Object v){
            if(v==NIL)return false;
            if(v instanceof Boolean)return (Boolean)v;
            if(v instanceof Long)return (Long)v!=0;
            if(v instanceof String)return !((String)v).isEmpty();
            if(v instanceof ArrayList)return !((ArrayList<?>)v).isEmpty();
            return true;
        }

        String display(Object v, boolean inList, List<Object> ancestors){
            if(v==NIL)return "nil";
            if(v instanceof Long)return v.toString();
            if(v instanceof Boolean)return v.toString();
            if(v instanceof String){
                if(!inList)return (String)v;
                StringBuilder sb=new StringBuilder("\"");
                for(char c:((String)v).toCharArray()){
                    if(c=='\\')sb.append("\\\\");
                    else if(c=='"')sb.append("\\\"");
                    else if(c=='\n')sb.append("\\n");
                    else if(c=='\t')sb.append("\\t");
                    else sb.append(c);
                }
                sb.append('"');return sb.toString();
            }
            if(v instanceof TernFunction)return "<fn>";
            if(v instanceof ArrayList){
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                for(Object a:ancestors)if(a==list)return "[...]";
                ancestors.add(list);
                StringBuilder sb=new StringBuilder("[");
                for(int i=0;i<list.size();i++){
                    if(i>0)sb.append(", ");
                    sb.append(display(list.get(i),true,ancestors));
                }
                sb.append(']');
                ancestors.remove(ancestors.size()-1);
                return sb.toString();
            }
            return "nil";
        }

        boolean valuesEqual(Object a, Object b){
            if(a==b)return true;
            if(a==NIL&&b==NIL)return true;
            if(a==NIL||b==NIL)return false;
            if(a instanceof Long&&b instanceof Long)return a.equals(b);
            if(a instanceof Boolean&&b instanceof Boolean)return a.equals(b);
            if(a instanceof String&&b instanceof String)return a.equals(b);
            if(a instanceof TernFunction&&b instanceof TernFunction)return a==b;
            if(a instanceof ArrayList&&b instanceof ArrayList){
                @SuppressWarnings("unchecked") ArrayList<Object> la=(ArrayList<Object>)a;
                @SuppressWarnings("unchecked") ArrayList<Object> lb=(ArrayList<Object>)b;
                if(la.size()!=lb.size())return false;
                for(int i=0;i<la.size();i++)if(!valuesEqual(la.get(i),lb.get(i)))return false;
                return true;
            }
            return false;
        }

        void run(List<Stmt> prog){
            try { execBlock(prog, globalScope); }
            catch(TernError e){ out.append("error at line ").append(e.line).append(": ").append(e.msg).append("\n"); }
        }

        void execBlock(List<Stmt> stmts, Scope scope){
            for(Stmt s:stmts)execStmt(s,scope);
        }

        void execStmt(Stmt s, Scope scope){
            if(s instanceof LetStmt ls){
                Object v=eval(ls.val,scope);
                scope.declare(ls.name,v);
            } else if(s instanceof FnStmt fs){
                TernFunction fn=new TernFunction(fs.name,fs.params,fs.body,scope);
                scope.declare(fs.name,fn);
            } else if(s instanceof IfStmt is){
                if(truthy(eval(is.cond,scope))){
                    execBlock(is.then,new Scope(scope));
                } else if(is.els!=null){
                    execBlock(is.els,new Scope(scope));
                }
            } else if(s instanceof WhileStmt ws){
                while(true){
                    if(!truthy(eval(ws.cond,scope)))break;
                    try { execBlock(ws.body,new Scope(scope)); }
                    catch(BreakEx e){break;}
                    catch(ContinueEx e){continue;}
                }
            } else if(s instanceof ForStmt fs){
                Object iter=eval(fs.iter,scope);
                if(!(iter instanceof ArrayList)){
                    throw new TernError("cannot iterate "+typeName(iter),fs.line);
                }
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)iter;
                long i=0;
                while(i<list.size()){
                    Scope iterScope=new Scope(scope);
                    iterScope.declare(fs.var,list.get((int)i));
                    try { execBlock(fs.body,iterScope); }
                    catch(BreakEx e){break;}
                    catch(ContinueEx e){}
                    i++;
                }
            } else if(s instanceof ReturnStmt rs){
                Object v=rs.val!=null?eval(rs.val,scope):NIL;
                throw new ReturnEx(v);
            } else if(s instanceof BreakStmt){
                throw new BreakEx();
            } else if(s instanceof ContinueStmt){
                throw new ContinueEx();
            } else if(s instanceof AssignStmt as){
                Object v=eval(as.val,scope);
                if(!scope.has(as.name))throw new TernError("undefined variable "+as.name,as.line);
                scope.set(as.name,v);
            } else if(s instanceof IndexAssignStmt ias){
                Object obj=eval(ias.obj,scope);
                Object idx=eval(ias.idx,scope);
                Object val=eval(ias.val,scope);
                if(!(obj instanceof ArrayList)){
                    throw new TernError("cannot assign into "+typeName(obj),ias.brLine);
                }
                if(!(idx instanceof Long)){
                    throw new TernError("cannot index list with "+typeName(idx),ias.brLine);
                }
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)obj;
                long ii=(Long)idx;
                if(ii<0||ii>=list.size()){
                    throw new TernError("index "+ii+" out of range for length "+list.size(),ias.brLine);
                }
                list.set((int)ii,val);
            } else if(s instanceof ExprStmt es){
                eval(es.e,scope);
            }
        }

        Object eval(Expr e, Scope scope){
            if(e instanceof IntLit il)return il.v;
            if(e instanceof StrLit sl)return sl.v;
            if(e instanceof BoolLit bl)return bl.v;
            if(e instanceof NilLit)return NIL;
            if(e instanceof IdentExpr ie){
                if(!scope.has(ie.name))throw new TernError("undefined variable "+ie.name,ie.line);
                return scope.get(ie.name);
            }
            if(e instanceof ListLit ll){
                ArrayList<Object> list=new ArrayList<>();
                for(Expr el:ll.elems)list.add(eval(el,scope));
                return list;
            }
            if(e instanceof FnExpr fe){
                return new TernFunction("",fe.params,fe.body,scope);
            }
            if(e instanceof AndExpr ae){
                Object l=eval(ae.l,scope);
                if(!truthy(l))return l;
                return eval(ae.r,scope);
            }
            if(e instanceof OrExpr oe){
                Object l=eval(oe.l,scope);
                if(truthy(l))return l;
                return eval(oe.r,scope);
            }
            if(e instanceof NotExpr ne){
                return !truthy(eval(ne.e,scope));
            }
            if(e instanceof NegExpr ne){
                Object v=eval(ne.e,scope);
                if(!(v instanceof Long))throw new TernError("cannot apply - to "+typeName(v),ne.line);
                long x=(Long)v;
                if(x==Long.MIN_VALUE)throw new TernError("integer overflow",ne.line);
                return -x;
            }
            if(e instanceof BinaryExpr be){
                Object l=eval(be.l,scope);
                Object r=eval(be.r,scope);
                return binaryOp(be.op,l,r,be.line);
            }
            if(e instanceof CallExpr ce){
                Object callee=eval(ce.callee,scope);
                List<Object> args=new ArrayList<>();
                for(Expr a:ce.args)args.add(eval(a,scope));
                if(!(callee instanceof TernFunction)){
                    throw new TernError("cannot call "+typeName(callee),ce.openLine);
                }
                TernFunction fn=(TernFunction)callee;
                if(fn.builtin!=null){
                    if(!fn.variadic&&args.size()!=fn.paramCount){
                        throw new TernError("expected "+fn.paramCount+" arguments, got "+args.size(),ce.openLine);
                    }
                    try { return fn.builtin.call(args,ce.openLine); }
                    catch(TernError te){ if(te.line==0)te.line=ce.openLine; throw te; }
                }
                if(args.size()!=fn.params.size()){
                    throw new TernError("expected "+fn.params.size()+" arguments, got "+args.size(),ce.openLine);
                }
                Scope callScope=new Scope(fn.captured);
                for(int i=0;i<fn.params.size();i++)callScope.declare(fn.params.get(i),args.get(i));
                try { execBlock(fn.body,callScope); }
                catch(ReturnEx re){return re.val;}
                return NIL;
            }
            if(e instanceof IndexExpr ie){
                Object obj=eval(ie.obj,scope);
                Object idx=eval(ie.idx,scope);
                if(obj instanceof ArrayList){
                    if(!(idx instanceof Long))throw new TernError("cannot index list with "+typeName(idx),ie.brLine);
                    @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)obj;
                    long i=(Long)idx;
                    if(i<0||i>=list.size())throw new TernError("index "+i+" out of range for length "+list.size(),ie.brLine);
                    return list.get((int)i);
                } else if(obj instanceof String){
                    if(!(idx instanceof Long))throw new TernError("cannot index string with "+typeName(idx),ie.brLine);
                    String s=(String)obj;
                    long i=(Long)idx;
                    if(i<0||i>=s.length())throw new TernError("index "+i+" out of range for length "+s.length(),ie.brLine);
                    return String.valueOf(s.charAt((int)i));
                } else {
                    throw new TernError("cannot index "+typeName(obj)+" with "+typeName(idx),ie.brLine);
                }
            }
            throw new RuntimeException("unknown expr");
        }

        Object binaryOp(String op, Object l, Object r, int line){
            switch(op){
                case "==":return valuesEqual(l,r);
                case "!=":return !valuesEqual(l,r);
                case "+":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.addExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    if(l instanceof String&&r instanceof String)return (String)l+(String)r;
                    if(l instanceof ArrayList&&r instanceof ArrayList){
                        @SuppressWarnings("unchecked") ArrayList<Object> la=(ArrayList<Object>)l;
                        @SuppressWarnings("unchecked") ArrayList<Object> ra=(ArrayList<Object>)r;
                        ArrayList<Object> res=new ArrayList<>(la);res.addAll(ra);return res;
                    }
                    throw new TernError("cannot apply + to "+typeName(l)+" and "+typeName(r),line);
                }
                case "-":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.subtractExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    throw new TernError("cannot apply - to "+typeName(l)+" and "+typeName(r),line);
                }
                case "*":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.multiplyExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    throw new TernError("cannot apply * to "+typeName(l)+" and "+typeName(r),line);
                }
                case "/":{
                    if(!(l instanceof Long)||!(r instanceof Long))throw new TernError("cannot apply / to "+typeName(l)+" and "+typeName(r),line);
                    long a=(Long)l,b=(Long)r;
                    if(b==0)throw new TernError("division by zero",line);
                    if(a==Long.MIN_VALUE&&b==-1)throw new TernError("integer overflow",line);
                    return a/b;
                }
                case "%":{
                    if(!(l instanceof Long)||!(r instanceof Long))throw new TernError("cannot apply % to "+typeName(l)+" and "+typeName(r),line);
                    long a=(Long)l,b=(Long)r;
                    if(b==0)throw new TernError("division by zero",line);
                    if(b==-1)return 0L;
                    return a-(a/b)*b;
                }
                case "<":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l<(Long)r;
                    if(l instanceof String&&r instanceof String)return ((String)l).compareTo((String)r)<0;
                    throw new TernError("cannot apply < to "+typeName(l)+" and "+typeName(r),line);
                }
                case "<=":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l<=(Long)r;
                    if(l instanceof String&&r instanceof String)return ((String)l).compareTo((String)r)<=0;
                    throw new TernError("cannot apply <= to "+typeName(l)+" and "+typeName(r),line);
                }
                case ">":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l>(Long)r;
                    if(l instanceof String&&r instanceof String)return ((String)l).compareTo((String)r)>0;
                    throw new TernError("cannot apply > to "+typeName(l)+" and "+typeName(r),line);
                }
                case ">=":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l>=(Long)r;
                    if(l instanceof String&&r instanceof String)return ((String)l).compareTo((String)r)>=0;
                    throw new TernError("cannot apply >= to "+typeName(l)+" and "+typeName(r),line);
                }
            }
            throw new RuntimeException("unknown op: "+op);
        }
    }

    // ==================== MAIN ====================
    public static void main(String[] args) throws Exception {
        String dir=args[0];
        String src=Files.readString(Path.of(dir,"program.tern"));
        Lexer lex=new Lexer(src);
        List<Token> toks=lex.tokenize();
        Parser parser=new Parser(toks);
        List<Stmt> prog=parser.parseProgram();
        Interpreter interp=new Interpreter();
        interp.run(prog);
        System.out.print(interp.out.toString());
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    // ==================== TOKENS ====================
    enum TT { INT, STR, IDENT, LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
              AND, OR, NOT, TRUE, FALSE, NIL,
              EQ, NEQ, LE, GE, LT, GT, ASSIGN, PLUS, MINUS, STAR, SLASH, PERCENT,
              LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE, COMMA, SEMI, EOF }

    static class Token {
        TT type; String str; long ival; int line;
        Token(TT t, String s, int l) { type=t; str=s; line=l; }
        Token(TT t, long v, int l) { type=t; ival=v; line=l; }
    }

    // ==================== LEXER ====================
    static class Lexer {
        String src; int pos, line;
        Lexer(String s) { src=s; pos=0; line=1; }

        void skipWs() {
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (c=='\n') { line++; pos++; }
                else if (c==' '||c=='\t'||c=='\r') pos++;
                else if (c=='#') { while(pos<src.length()&&src.charAt(pos)!='\n') pos++; }
                else break;
            }
        }

        List<Token> tokenize() {
            List<Token> toks = new ArrayList<>();
            while (true) {
                skipWs();
                if (pos >= src.length()) { toks.add(new Token(TT.EOF,"",line)); break; }
                char c = src.charAt(pos);
                int sl = line;
                if (Character.isDigit(c)) {
                    int start=pos;
                    while(pos<src.length()&&Character.isDigit(src.charAt(pos))) pos++;
                    toks.add(new Token(TT.INT, Long.parseLong(src.substring(start,pos)), sl));
                } else if (c=='"') {
                    pos++; StringBuilder sb=new StringBuilder();
                    while(pos<src.length()) {
                        char ch=src.charAt(pos);
                        if(ch=='"'){pos++;break;}
                        if(ch=='\\'){pos++;char e=src.charAt(pos);
                            switch(e){case'n':sb.append('\n');break;case't':sb.append('\t');break;
                            case'"':sb.append('"');break;case'\\':sb.append('\\');break;}
                            pos++;
                        } else { sb.append(ch); pos++; }
                    }
                    toks.add(new Token(TT.STR, sb.toString(), sl));
                } else if (Character.isLetter(c)||c=='_') {
                    int start=pos;
                    while(pos<src.length()&&(Character.isLetterOrDigit(src.charAt(pos))||src.charAt(pos)=='_')) pos++;
                    String w=src.substring(start,pos);
                    TT t = switch(w) {
                        case "let"->TT.LET; case "fn"->TT.FN; case "if"->TT.IF; case "else"->TT.ELSE;
                        case "while"->TT.WHILE; case "for"->TT.FOR; case "in"->TT.IN;
                        case "return"->TT.RETURN; case "break"->TT.BREAK; case "continue"->TT.CONTINUE;
                        case "and"->TT.AND; case "or"->TT.OR; case "not"->TT.NOT;
                        case "true"->TT.TRUE; case "false"->TT.FALSE; case "nil"->TT.NIL;
                        default->TT.IDENT;
                    };
                    toks.add(new Token(t,w,sl));
                } else {
                    if(pos+1<src.length()) {
                        String two=src.substring(pos,pos+2);
                        if(two.equals("==")){toks.add(new Token(TT.EQ,"==",sl));pos+=2;continue;}
                        if(two.equals("!=")){toks.add(new Token(TT.NEQ,"!=",sl));pos+=2;continue;}
                        if(two.equals("<=")){toks.add(new Token(TT.LE,"<=",sl));pos+=2;continue;}
                        if(two.equals(">=")){toks.add(new Token(TT.GE,">=",sl));pos+=2;continue;}
                    }
                    switch(c) {
                        case '<':toks.add(new Token(TT.LT,"<",sl));pos++;break;
                        case '>':toks.add(new Token(TT.GT,">",sl));pos++;break;
                        case '=':toks.add(new Token(TT.ASSIGN,"=",sl));pos++;break;
                        case '+':toks.add(new Token(TT.PLUS,"+",sl));pos++;break;
                        case '-':toks.add(new Token(TT.MINUS,"-",sl));pos++;break;
                        case '*':toks.add(new Token(TT.STAR,"*",sl));pos++;break;
                        case '/':toks.add(new Token(TT.SLASH,"/",sl));pos++;break;
                        case '%':toks.add(new Token(TT.PERCENT,"%",sl));pos++;break;
                        case '(':toks.add(new Token(TT.LPAREN,"(",sl));pos++;break;
                        case ')':toks.add(new Token(TT.RPAREN,")",sl));pos++;break;
                        case '[':toks.add(new Token(TT.LBRACKET,"[",sl));pos++;break;
                        case ']':toks.add(new Token(TT.RBRACKET,"]",sl));pos++;break;
                        case '{':toks.add(new Token(TT.LBRACE,"{",sl));pos++;break;
                        case '}':toks.add(new Token(TT.RBRACE,"}",sl));pos++;break;
                        case ',':toks.add(new Token(TT.COMMA,",",sl));pos++;break;
                        case ';':toks.add(new Token(TT.SEMI,";",sl));pos++;break;
                        default: pos++; break;
                    }
                }
            }
            return toks;
        }
    }

    // ==================== AST ====================
    static abstract class Expr { int line; }
    static class IntLit extends Expr { long v; IntLit(long v,int l){this.v=v;line=l;} }
    static class StrLit extends Expr { String v; StrLit(String v,int l){this.v=v;line=l;} }
    static class BoolLit extends Expr { boolean v; BoolLit(boolean v,int l){this.v=v;line=l;} }
    static class NilLit extends Expr { NilLit(int l){line=l;} }
    static class IdentExpr extends Expr { String name; IdentExpr(String n,int l){name=n;line=l;} }
    static class ListLit extends Expr { List<Expr> elems; ListLit(List<Expr> e,int l){elems=e;line=l;} }
    static class FnExpr extends Expr { List<String> params; List<Stmt> body; FnExpr(List<String> p,List<Stmt> b,int l){params=p;body=b;line=l;} }
    static class BinaryExpr extends Expr { String op; Expr l,r; BinaryExpr(String o,Expr l,Expr r,int ln){op=o;this.l=l;this.r=r;line=ln;} }
    static class AndExpr extends Expr { Expr l,r; AndExpr(Expr l,Expr r,int ln){this.l=l;this.r=r;line=ln;} }
    static class OrExpr extends Expr { Expr l,r; OrExpr(Expr l,Expr r,int ln){this.l=l;this.r=r;line=ln;} }
    static class NotExpr extends Expr { Expr e; NotExpr(Expr e,int ln){this.e=e;line=ln;} }
    static class NegExpr extends Expr { Expr e; NegExpr(Expr e,int ln){this.e=e;line=ln;} }
    static class CallExpr extends Expr { Expr callee; List<Expr> args; int openLine; CallExpr(Expr c,List<Expr> a,int ol){callee=c;args=a;openLine=ol;line=ol;} }
    static class IndexExpr extends Expr { Expr obj,idx; int brLine; IndexExpr(Expr o,Expr i,int bl){obj=o;idx=i;brLine=bl;line=bl;} }

    static abstract class Stmt { int line; }
    static class LetStmt extends Stmt { String name; Expr val; LetStmt(String n,Expr v,int l){name=n;val=v;line=l;} }
    static class FnStmt extends Stmt { String name; List<String> params; List<Stmt> body; FnStmt(String n,List<String> p,List<Stmt> b,int l){name=n;params=p;body=b;line=l;} }
    static class IfStmt extends Stmt { Expr cond; List<Stmt> then; List<Stmt> els; IfStmt(Expr c,List<Stmt> t,List<Stmt> e,int l){cond=c;then=t;els=e;line=l;} }
    static class WhileStmt extends Stmt { Expr cond; List<Stmt> body; WhileStmt(Expr c,List<Stmt> b,int l){cond=c;body=b;line=l;} }
    static class ForStmt extends Stmt { String var; Expr iter; List<Stmt> body; ForStmt(String v,Expr e,List<Stmt> b,int l){var=v;iter=e;body=b;line=l;} }
    static class ReturnStmt extends Stmt { Expr val; ReturnStmt(Expr v,int l){val=v;line=l;} }
    static class BreakStmt extends Stmt { BreakStmt(int l){line=l;} }
    static class ContinueStmt extends Stmt { ContinueStmt(int l){line=l;} }
    static class AssignStmt extends Stmt { String name; Expr val; AssignStmt(String n,Expr v,int l){name=n;val=v;line=l;} }
    static class IndexAssignStmt extends Stmt { Expr obj,idx,val; int brLine; IndexAssignStmt(Expr o,Expr i,Expr v,int bl){obj=o;idx=i;val=v;brLine=bl;line=bl;} }
    static class ExprStmt extends Stmt { Expr e; ExprStmt(Expr e,int l){this.e=e;line=l;} }

    // ==================== PARSER ====================
    static class Parser {
        List<Token> toks; int pos;
        Parser(List<Token> t){toks=t;pos=0;}
        Token peek(){return toks.get(pos);}
        Token advance(){return toks.get(pos++);}
        boolean check(TT t){return peek().type==t;}
        Token expect(TT t){Token tk=peek();if(tk.type!=t)throw new RuntimeException("expected "+t+" got "+tk.type);pos++;return tk;}

        List<Stmt> parseProgram(){List<Stmt> r=new ArrayList<>();while(!check(TT.EOF))r.add(parseStmt());return r;}

        List<Stmt> parseBlock(){expect(TT.LBRACE);List<Stmt> r=new ArrayList<>();while(!check(TT.RBRACE)&&!check(TT.EOF))r.add(parseStmt());expect(TT.RBRACE);return r;}

        Stmt parseStmt(){
            Token tk=peek();
            switch(tk.type){
                case LET:{advance();String n=expect(TT.IDENT).str;expect(TT.ASSIGN);Expr v=parseExpr();expect(TT.SEMI);return new LetStmt(n,v,tk.line);}
                case FN:{
                    if(toks.get(pos+1).type==TT.IDENT){
                        advance();String n=expect(TT.IDENT).str;expect(TT.LPAREN);List<String> p=parseParams();expect(TT.RPAREN);List<Stmt> b=parseBlock();return new FnStmt(n,p,b,tk.line);
                    } else { return parseExprOrAssign(); }
                }
                case IF:return parseIfStmt();
                case WHILE:{advance();Expr c=parseExpr();List<Stmt> b=parseBlock();return new WhileStmt(c,b,tk.line);}
                case FOR:{advance();String v=expect(TT.IDENT).str;expect(TT.IN);Expr e=parseExpr();List<Stmt> b=parseBlock();return new ForStmt(v,e,b,tk.line);}
                case RETURN:{advance();Expr e=null;if(!check(TT.SEMI))e=parseExpr();expect(TT.SEMI);return new ReturnStmt(e,tk.line);}
                case BREAK:{advance();expect(TT.SEMI);return new BreakStmt(tk.line);}
                case CONTINUE:{advance();expect(TT.SEMI);return new ContinueStmt(tk.line);}
                default: return parseExprOrAssign();
            }
        }

        Stmt parseExprOrAssign(){
            int startLine=peek().line;
            if(peek().type==TT.IDENT && toks.get(pos+1).type==TT.ASSIGN){
                String n=advance().str;advance();Expr v=parseExpr();expect(TT.SEMI);return new AssignStmt(n,v,startLine);
            }
            Expr e=parsePostfix();
            if(check(TT.ASSIGN)){
                advance();Expr v=parseExpr();expect(TT.SEMI);
                if(e instanceof IndexExpr ix){return new IndexAssignStmt(ix.obj,ix.idx,v,ix.brLine);}
                throw new RuntimeException("invalid assignment target");
            }
            expect(TT.SEMI);return new ExprStmt(e,startLine);
        }

        Stmt parseIfStmt(){
            Token tk=expect(TT.IF);Expr c=parseExpr();List<Stmt> then=parseBlock();List<Stmt> els=null;
            if(check(TT.ELSE)){advance();if(check(TT.IF))els=List.of(parseIfStmt());else els=parseBlock();}
            return new IfStmt(c,then,els,tk.line);
        }

        List<String> parseParams(){
            List<String> r=new ArrayList<>();
            if(check(TT.IDENT)){r.add(advance().str);while(check(TT.COMMA)){advance();r.add(expect(TT.IDENT).str);}}
            return r;
        }

        Expr parseExpr(){return parseOr();}
        Expr parseOr(){Expr l=parseAnd();while(check(TT.OR)){Token op=advance();Expr r=parseAnd();l=new OrExpr(l,r,op.line);}return l;}
        Expr parseAnd(){Expr l=parseNot();while(check(TT.AND)){Token op=advance();Expr r=parseNot();l=new AndExpr(l,r,op.line);}return l;}
        Expr parseNot(){if(check(TT.NOT)){Token op=advance();Expr e=parseNot();return new NotExpr(e,op.line);}return parseComparison();}
        Expr parseComparison(){
            Expr l=parseAddSub();
            while(check(TT.EQ)||check(TT.NEQ)||check(TT.LT)||check(TT.LE)||check(TT.GT)||check(TT.GE)){
                Token op=advance();Expr r=parseAddSub();l=new BinaryExpr(op.str,l,r,op.line);
            }
            return l;
        }
        Expr parseAddSub(){
            Expr l=parseMulDiv();
            while(check(TT.PLUS)||check(TT.MINUS)){Token op=advance();Expr r=parseMulDiv();l=new BinaryExpr(op.str,l,r,op.line);}
            return l;
        }
        Expr parseMulDiv(){
            Expr l=parseUnary();
            while(check(TT.STAR)||check(TT.SLASH)||check(TT.PERCENT)){Token op=advance();Expr r=parseUnary();l=new BinaryExpr(op.str,l,r,op.line);}
            return l;
        }
        Expr parseUnary(){if(check(TT.MINUS)){Token op=advance();Expr e=parseUnary();return new NegExpr(e,op.line);}return parsePostfix();}
        Expr parsePostfix(){
            Expr e=parsePrimary();
            while(true){
                if(check(TT.LPAREN)){
                    int ol=advance().line;List<Expr> args=new ArrayList<>();
                    if(!check(TT.RPAREN)){args.add(parseExpr());while(check(TT.COMMA)){advance();args.add(parseExpr());}}
                    expect(TT.RPAREN);e=new CallExpr(e,args,ol);
                } else if(check(TT.LBRACKET)){
                    int bl=advance().line;Expr idx=parseExpr();expect(TT.RBRACKET);e=new IndexExpr(e,idx,bl);
                } else break;
            }
            return e;
        }
        Expr parsePrimary(){
            Token tk=peek();
            switch(tk.type){
                case INT:{advance();return new IntLit(tk.ival,tk.line);}
                case STR:{advance();return new StrLit(tk.str,tk.line);}
                case TRUE:{advance();return new BoolLit(true,tk.line);}
                case FALSE:{advance();return new BoolLit(false,tk.line);}
                case NIL:{advance();return new NilLit(tk.line);}
                case IDENT:{advance();return new IdentExpr(tk.str,tk.line);}
                case LPAREN:{advance();Expr e=parseExpr();expect(TT.RPAREN);return e;}
                case LBRACKET:{
                    advance();List<Expr> elems=new ArrayList<>();
                    if(!check(TT.RBRACKET)){elems.add(parseExpr());while(check(TT.COMMA)){advance();elems.add(parseExpr());}}
                    expect(TT.RBRACKET);return new ListLit(elems,tk.line);
                }
                case FN:{
                    advance();expect(TT.LPAREN);List<String> p=parseParams();expect(TT.RPAREN);List<Stmt> b=parseBlock();return new FnExpr(p,b,tk.line);
                }
                default: throw new RuntimeException("unexpected token: "+tk.type);
            }
        }
    }

    // ==================== VALUES ====================
    static final Object NIL = new Object(){public String toString(){return "nil";}};

    static class TernFunction {
        String name; List<String> params; List<Stmt> body; Scope captured;
        int paramCount; boolean variadic; BuiltinFn builtin;
        TernFunction(String name,List<String> params,List<Stmt> body,Scope cap){
            this.name=name;this.params=params;this.body=body;this.captured=cap;this.builtin=null;
        }
        TernFunction(String name,int pc,BuiltinFn fn){
            this.name=name;this.paramCount=pc;this.builtin=fn;this.variadic=(pc==-1);
        }
    }
    @FunctionalInterface
    interface BuiltinFn { Object call(List<Object> args, int line); }

    static class Scope {
        Map<String,Object> vars=new HashMap<>();
        Scope parent;
        Scope(Scope p){parent=p;}
        Object get(String name){
            Scope s=this;
            while(s!=null){if(s.vars.containsKey(name))return s.vars.get(name);s=s.parent;}
            return null;
        }
        boolean has(String name){Scope s=this;while(s!=null){if(s.vars.containsKey(name))return true;s=s.parent;}return false;}
        void set(String name,Object v){
            Scope s=this;
            while(s!=null){if(s.vars.containsKey(name)){s.vars.put(name,v);return;}s=s.parent;}
        }
        void declare(String name,Object v){vars.put(name,v);}
    }

    // ==================== ERRORS ====================
    static class TernError extends RuntimeException {
        String msg; int line;
        TernError(String msg,int line){super(msg);this.msg=msg;this.line=line;}
    }
    static class BreakEx extends RuntimeException { BreakEx(){super(null,null,false,false);} }
    static class ContinueEx extends RuntimeException { ContinueEx(){super(null,null,false,false);} }
    static class ReturnEx extends RuntimeException { Object val; ReturnEx(Object v){super(null,null,false,false);val=v;} }

    // ==================== INTERPRETER ====================
    static class Interpreter {
        Scope globalScope;
        StringBuilder out = new StringBuilder();

        Interpreter() {
            Scope builtins = new Scope(null);
            globalScope = new Scope(builtins);
            setupBuiltins(builtins);
        }

        void setupBuiltins(Scope bs) {
            bs.declare("print", new TernFunction("print",-1,(List<Object> args, int line)->{
                for(int i=0;i<args.size();i++){
                    if(i>0)out.append(' ');
                    out.append(display(args.get(i),false,new ArrayList<>()));
                }
                out.append('\n');return NIL;
            }));
            bs.declare("str", new TernFunction("str",1,(List<Object> args, int line)->{
                return display(args.get(0),false,new ArrayList<>());
            }));
            bs.declare("type", new TernFunction("type",1,(List<Object> args, int line)->{
                return typeName(args.get(0));
            }));
            bs.declare("len", new TernFunction("len",1,(List<Object> args, int line)->{
                Object v=args.get(0);
                if(v instanceof String)return (long)((String)v).length();
                if(v instanceof ArrayList)return (long)((ArrayList<?>)v).size();
                throw new TernError("bad argument to len",line);
            }));
            bs.declare("push", new TernFunction("push",2,(List<Object> args, int line)->{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TernError("bad argument to push",line);
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                list.add(args.get(1));return NIL;
            }));
            bs.declare("pop", new TernFunction("pop",1,(List<Object> args, int line)->{
                Object v=args.get(0);
                if(!(v instanceof ArrayList))throw new TernError("bad argument to pop",line);
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                if(list.isEmpty())throw new TernError("bad argument to pop",line);
                return list.remove(list.size()-1);
            }));
            bs.declare("range", new TernFunction("range",2,(List<Object> args, int line)->{
                Object a=args.get(0),b=args.get(1);
                if(!(a instanceof Long)||!(b instanceof Long))throw new TernError("bad argument to range",line);
                long lo=(Long)a,hi=(Long)b;
                ArrayList<Object> r=new ArrayList<>();
                for(long i=lo;i<hi;i++)r.add(i);
                return r;
            }));
            bs.declare("slice", new TernFunction("slice",3,(List<Object> args, int line)->{
                Object x=args.get(0),ai=args.get(1),bi=args.get(2);
                if(!(ai instanceof Long)||!(bi instanceof Long))throw new TernError("bad argument to slice",line);
                long a=(Long)ai,b=(Long)bi;
                if(x instanceof String){
                    String s=(String)x;
                    if(a<0||b>s.length()||a>b)throw new TernError("bad argument to slice",line);
                    return s.substring((int)a,(int)b);
                } else if(x instanceof ArrayList){
                    @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)x;
                    if(a<0||b>list.size()||a>b)throw new TernError("bad argument to slice",line);
                    return new ArrayList<>(list.subList((int)a,(int)b));
                }
                throw new TernError("bad argument to slice",line);
            }));
        }

        String typeName(Object v){
            if(v instanceof Long)return "int";
            if(v instanceof Boolean)return "bool";
            if(v instanceof String)return "string";
            if(v instanceof ArrayList)return "list";
            if(v instanceof TernFunction)return "function";
            if(v==NIL)return "nil";
            return "nil";
        }

        boolean truthy(Object v){
            if(v==NIL)return false;
            if(v instanceof Boolean)return (Boolean)v;
            if(v instanceof Long)return (Long)v!=0;
            if(v instanceof String)return !((String)v).isEmpty();
            if(v instanceof ArrayList)return !((ArrayList<?>)v).isEmpty();
            return true;
        }

        String display(Object v, boolean inList, List<Object> ancestors){
            if(v==NIL)return "nil";
            if(v instanceof Long)return v.toString();
            if(v instanceof Boolean)return v.toString();
            if(v instanceof String){
                if(!inList)return (String)v;
                StringBuilder sb=new StringBuilder("\"");
                for(char c:((String)v).toCharArray()){
                    if(c=='\\')sb.append("\\\\");
                    else if(c=='"')sb.append("\\\"");
                    else if(c=='\n')sb.append("\\n");
                    else if(c=='\t')sb.append("\\t");
                    else sb.append(c);
                }
                sb.append('"');return sb.toString();
            }
            if(v instanceof TernFunction)return "<fn>";
            if(v instanceof ArrayList){
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)v;
                for(Object a:ancestors)if(a==list)return "[...]";
                ancestors.add(list);
                StringBuilder sb=new StringBuilder("[");
                for(int i=0;i<list.size();i++){
                    if(i>0)sb.append(", ");
                    sb.append(display(list.get(i),true,ancestors));
                }
                sb.append(']');
                ancestors.remove(ancestors.size()-1);
                return sb.toString();
            }
            return "nil";
        }

        boolean valuesEqual(Object a, Object b){
            if(a==b)return true;
            if(a==NIL&&b==NIL)return true;
            if(a==NIL||b==NIL)return false;
            if(a instanceof Long&&b instanceof Long)return a.equals(b);
            if(a instanceof Boolean&&b instanceof Boolean)return a.equals(b);
            if(a instanceof String&&b instanceof String)return a.equals(b);
            if(a instanceof TernFunction&&b instanceof TernFunction)return a==b;
            if(a instanceof ArrayList&&b instanceof ArrayList){
                @SuppressWarnings("unchecked") ArrayList<Object> la=(ArrayList<Object>)a;
                @SuppressWarnings("unchecked") ArrayList<Object> lb=(ArrayList<Object>)b;
                if(la.size()!=lb.size())return false;
                for(int i=0;i<la.size();i++)if(!valuesEqual(la.get(i),lb.get(i)))return false;
                return true;
            }
            return false;
        }

        void run(List<Stmt> prog){
            try { execBlock(prog, globalScope); }
            catch(TernError e){ out.append("error at line ").append(e.line).append(": ").append(e.msg).append("\n"); }
        }

        void execBlock(List<Stmt> stmts, Scope scope){
            for(Stmt s:stmts)execStmt(s,scope);
        }

        void execStmt(Stmt s, Scope scope){
            if(s instanceof LetStmt ls){
                Object v=eval(ls.val,scope);
                scope.declare(ls.name,v);
            } else if(s instanceof FnStmt fs){
                TernFunction fn=new TernFunction(fs.name,fs.params,fs.body,scope);
                scope.declare(fs.name,fn);
            } else if(s instanceof IfStmt is){
                if(truthy(eval(is.cond,scope))){
                    execBlock(is.then,new Scope(scope));
                } else if(is.els!=null){
                    execBlock(is.els,new Scope(scope));
                }
            } else if(s instanceof WhileStmt ws){
                while(true){
                    if(!truthy(eval(ws.cond,scope)))break;
                    try { execBlock(ws.body,new Scope(scope)); }
                    catch(BreakEx e){break;}
                    catch(ContinueEx e){continue;}
                }
            } else if(s instanceof ForStmt fs){
                Object iter=eval(fs.iter,scope);
                if(!(iter instanceof ArrayList)){
                    throw new TernError("cannot iterate "+typeName(iter),fs.line);
                }
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)iter;
                long i=0;
                while(i<list.size()){
                    Scope iterScope=new Scope(scope);
                    iterScope.declare(fs.var,list.get((int)i));
                    try { execBlock(fs.body,iterScope); }
                    catch(BreakEx e){break;}
                    catch(ContinueEx e){/* fall through to i++ */}
                    i++;
                }
            } else if(s instanceof ReturnStmt rs){
                Object v=rs.val!=null?eval(rs.val,scope):NIL;
                throw new ReturnEx(v);
            } else if(s instanceof BreakStmt){
                throw new BreakEx();
            } else if(s instanceof ContinueStmt){
                throw new ContinueEx();
            } else if(s instanceof AssignStmt as){
                Object v=eval(as.val,scope);
                if(!scope.has(as.name))throw new TernError("undefined variable "+as.name,as.line);
                scope.set(as.name,v);
            } else if(s instanceof IndexAssignStmt ias){
                Object obj=eval(ias.obj,scope);
                Object idx=eval(ias.idx,scope);
                Object val=eval(ias.val,scope);
                if(!(obj instanceof ArrayList)){
                    throw new TernError("cannot assign into "+typeName(obj),ias.brLine);
                }
                if(!(idx instanceof Long)){
                    throw new TernError("cannot index list with "+typeName(idx),ias.brLine);
                }
                @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)obj;
                long ii=(Long)idx;
                if(ii<0||ii>=list.size()){
                    throw new TernError("index "+ii+" out of range for length "+list.size(),ias.brLine);
                }
                list.set((int)ii,val);
            } else if(s instanceof ExprStmt es){
                eval(es.e,scope);
            }
        }

        Object eval(Expr e, Scope scope){
            if(e instanceof IntLit il)return il.v;
            if(e instanceof StrLit sl)return sl.v;
            if(e instanceof BoolLit bl)return bl.v;
            if(e instanceof NilLit)return NIL;
            if(e instanceof IdentExpr ie){
                if(!scope.has(ie.name))throw new TernError("undefined variable "+ie.name,ie.line);
                return scope.get(ie.name);
            }
            if(e instanceof ListLit ll){
                ArrayList<Object> list=new ArrayList<>();
                for(Expr el:ll.elems)list.add(eval(el,scope));
                return list;
            }
            if(e instanceof FnExpr fe){
                return new TernFunction("",fe.params,fe.body,scope);
            }
            if(e instanceof AndExpr ae){
                Object l=eval(ae.l,scope);
                if(!truthy(l))return l;
                return eval(ae.r,scope);
            }
            if(e instanceof OrExpr oe){
                Object l=eval(oe.l,scope);
                if(truthy(l))return l;
                return eval(oe.r,scope);
            }
            if(e instanceof NotExpr ne){
                return !truthy(eval(ne.e,scope));
            }
            if(e instanceof NegExpr ne){
                Object v=eval(ne.e,scope);
                if(!(v instanceof Long))throw new TernError("cannot apply - to "+typeName(v),ne.line);
                long x=(Long)v;
                if(x==Long.MIN_VALUE)throw new TernError("integer overflow",ne.line);
                return -x;
            }
            if(e instanceof BinaryExpr be){
                Object l=eval(be.l,scope);
                Object r=eval(be.r,scope);
                return binaryOp(be.op,l,r,be.line);
            }
            if(e instanceof CallExpr ce){
                Object callee=eval(ce.callee,scope);
                List<Object> args=new ArrayList<>();
                for(Expr a:ce.args)args.add(eval(a,scope));
                if(!(callee instanceof TernFunction)){
                    throw new TernError("cannot call "+typeName(callee),ce.openLine);
                }
                TernFunction fn=(TernFunction)callee;
                if(fn.builtin!=null){
                    if(!fn.variadic&&args.size()!=fn.paramCount){
                        throw new TernError("expected "+fn.paramCount+" arguments, got "+args.size(),ce.openLine);
                    }
                    return fn.builtin.call(args,ce.openLine);
                }
                if(args.size()!=fn.params.size()){
                    throw new TernError("expected "+fn.params.size()+" arguments, got "+args.size(),ce.openLine);
                }
                Scope callScope=new Scope(fn.captured);
                for(int i=0;i<fn.params.size();i++)callScope.declare(fn.params.get(i),args.get(i));
                try { execBlock(fn.body,callScope); }
                catch(ReturnEx re){return re.val;}
                return NIL;
            }
            if(e instanceof IndexExpr ie){
                Object obj=eval(ie.obj,scope);
                Object idx=eval(ie.idx,scope);
                if(obj instanceof ArrayList){
                    if(!(idx instanceof Long))throw new TernError("cannot index list with "+typeName(idx),ie.brLine);
                    @SuppressWarnings("unchecked") ArrayList<Object> list=(ArrayList<Object>)obj;
                    long i=(Long)idx;
                    if(i<0||i>=list.size())throw new TernError("index "+i+" out of range for length "+list.size(),ie.brLine);
                    return list.get((int)i);
                } else if(obj instanceof String){
                    if(!(idx instanceof Long))throw new TernError("cannot index string with "+typeName(idx),ie.brLine);
                    String s=(String)obj;
                    long i=(Long)idx;
                    if(i<0||i>=s.length())throw new TernError("index "+i+" out of range for length "+s.length(),ie.brLine);
                    return String.valueOf(s.charAt((int)i));
                } else {
                    throw new TernError("cannot index "+typeName(obj)+" with "+typeName(idx),ie.brLine);
                }
            }
            throw new RuntimeException("unknown expr");
        }

        Object binaryOp(String op, Object l, Object r, int line){
            switch(op){
                case "==":return valuesEqual(l,r);
                case "!=":return !valuesEqual(l,r);
                case "+":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.addExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    if(l instanceof String&&r instanceof String)return (String)l+(String)r;
                    if(l instanceof ArrayList&&r instanceof ArrayList){
                        @SuppressWarnings("unchecked") ArrayList<Object> la=(ArrayList<Object>)l;
                        @SuppressWarnings("unchecked") ArrayList<Object> ra=(ArrayList<Object>)r;
                        ArrayList<Object> res=new ArrayList<>(la);res.addAll(ra);return res;
                    }
                    throw new TernError("cannot apply + to "+typeName(l)+" and "+typeName(r),line);
                }
                case "-":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.subtractExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    throw new TernError("cannot apply - to "+typeName(l)+" and "+typeName(r),line);
                }
                case "*":{
                    if(l instanceof Long&&r instanceof Long){
                        try{return Math.multiplyExact((Long)l,(Long)r);}catch(ArithmeticException e){throw new TernError("integer overflow",line);}
                    }
                    throw new TernError("cannot apply * to "+typeName(l)+" and "+typeName(r),line);
                }
                case "/":{
                    if(!(l instanceof Long)||!(r instanceof Long))throw new TernError("cannot apply / to "+typeName(l)+" and "+typeName(r),line);
                    long a=(Long)l,b=(Long)r;
                    if(b==0)throw new TernError("division by zero",line);
                    if(a==Long.MIN_VALUE&&b==-1)throw new TernError("integer overflow",line);
                    return a/b;
                }
                case "%":{
                    if(!(l instanceof Long)||!(r instanceof Long))throw new TernError("cannot apply % to "+typeName(l)+" and "+typeName(r),line);
                    long a=(Long)l,b=(Long)r;
                    if(b==0)throw new TernError("division by zero",line);
                    if(b==-1)return 0L;
                    return a-(a/b)*b;
                }
                case "<":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l<(Long)r;
                    if(l instanceof String&&r instanceof String)return compareStrings((String)l,(String)r)<0;
                    throw new TernError("cannot apply < to "+typeName(l)+" and "+typeName(r),line);
                }
                case "<=":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l<=(Long)r;
                    if(l instanceof String&&r instanceof String)return compareStrings((String)l,(String)r)<=0;
                    throw new TernError("cannot apply <= to "+typeName(l)+" and "+typeName(r),line);
                }
                case ">":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l>(Long)r;
                    if(l instanceof String&&r instanceof String)return compareStrings((String)l,(String)r)>0;
                    throw new TernError("cannot apply > to "+typeName(l)+" and "+typeName(r),line);
                }
                case ">=":{
                    if(l instanceof Long&&r instanceof Long)return (Long)l>=(Long)r;
                    if(l instanceof String&&r instanceof String)return compareStrings((String)l,(String)r)>=0;
                    throw new TernError("cannot apply >= to "+typeName(l)+" and "+typeName(r),line);
                }
            }
            throw new RuntimeException("unknown op: "+op);
        }

        int compareStrings(String a, String b){
            int len=Math.min(a.length(),b.length());
            for(int i=0;i<len;i++){
                int ca=a.charAt(i)&0xFFFF;
                int cb=b.charAt(i)&0xFFFF;
                if(ca!=cb)return ca-cb;
            }
            return a.length()-b.length();
        }
    }

    // ==================== MAIN ====================
    public static void main(String[] args) throws Exception {
        String dir=args[0];
        String src=Files.readString(Path.of(dir,"program.tern"));
        Lexer lex=new Lexer(src);
        List<Token> toks=lex.tokenize();
        Parser parser=new Parser(toks);
        List<Stmt> prog=parser.parseProgram();
        Interpreter interp=new Interpreter();
        interp.run(prog);
        System.out.print(interp.out.toString());
    }
}

import sys
import os

INT_MIN = -(2**63)
INT_MAX = 2**63 - 1

KEYWORDS = frozenset(['let','fn','if','else','while','for','in','return',
                      'break','continue','and','or','not','true','false','nil'])

class Token:
    __slots__ = ('type','value','line')
    def __init__(self, t, v, l):
        self.type = t; self.value = v; self.line = l

def tokenize(source):
    tokens = []; i = 0; line = 1; n = len(source)
    while i < n:
        c = source[i]
        if c in ' \t\r\n':
            if c == '\n': line += 1
            i += 1
        elif c == '#':
            while i < n and source[i] != '\n': i += 1
        elif c == '"':
            sl = line; i += 1; parts = []
            while i < n and source[i] != '"':
                if source[i] == '\\':
                    i += 1; nc = source[i]
                    if nc == 'n': parts.append('\n')
                    elif nc == 't': parts.append('\t')
                    elif nc == '"': parts.append('"')
                    elif nc == '\\': parts.append('\\')
                    else: parts.append(nc)
                    i += 1
                else:
                    parts.append(source[i]); i += 1
            i += 1
            tokens.append(Token('STRING', ''.join(parts), sl))
        elif c.isdigit():
            j = i
            while i < n and source[i].isdigit(): i += 1
            tokens.append(Token('INT', int(source[j:i]), line))
        elif c.isalpha() or c == '_':
            j = i
            while i < n and (source[i].isalnum() or source[i] == '_'): i += 1
            w = source[j:i]
            tokens.append(Token('KEYWORD' if w in KEYWORDS else 'IDENT', w, line))
        else:
            if i+1 < n:
                two = source[i:i+2]
                if two in ('==','!=','<=','>='):
                    tokens.append(Token('OP', two, line)); i += 2; continue
            if c in '(){}[],;+-*/%=<>':
                tokens.append(Token('OP', c, line)); i += 1
            else:
                i += 1
    tokens.append(Token('EOF', None, line))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens; self.pos = 0
    def peek(self): return self.tokens[self.pos]
    def advance(self):
        t = self.tokens[self.pos]; self.pos += 1; return t
    def expect(self, tp, val=None):
        t = self.advance()
        return t
    def match(self, tp, val=None):
        t = self.peek()
        if t.type == tp and (val is None or t.value == val):
            return self.advance()
        return None
    def parse_program(self):
        stmts = []
        while self.peek().type != 'EOF':
            stmts.append(self.parse_stmt())
        return stmts
    def parse_block(self):
        self.expect('OP','{'); stmts = []
        while not (self.peek().type == 'OP' and self.peek().value == '}'):
            stmts.append(self.parse_stmt())
        self.expect('OP','}'); return stmts
    def parse_params(self):
        params = []
        if self.peek().type == 'OP' and self.peek().value == ')': return params
        params.append(self.expect('IDENT').value)
        while self.match('OP',','):
            params.append(self.expect('IDENT').value)
        return params
    def parse_stmt(self):
        t = self.peek()
        if t.type == 'KEYWORD':
            if t.value == 'let':
                self.advance(); name = self.expect('IDENT').value
                self.expect('OP','='); expr = self.parse_expr(); self.expect('OP',';')
                return ('let', name, expr)
            elif t.value == 'fn':
                self.advance(); name = self.expect('IDENT').value
                self.expect('OP','('); params = self.parse_params(); self.expect('OP',')')
                body = self.parse_block()
                return ('fnstmt', name, params, body)
            elif t.value == 'if':
                return self.parse_ifstmt()
            elif t.value == 'while':
                self.advance(); cond = self.parse_expr(); body = self.parse_block()
                return ('while', cond, body)
            elif t.value == 'for':
                self.advance(); var = self.expect('IDENT').value
                self.expect('KEYWORD','in'); expr = self.parse_expr(); body = self.parse_block()
                return ('for', var, expr, body, t.line)
            elif t.value == 'return':
                self.advance()
                if self.peek().type == 'OP' and self.peek().value == ';':
                    self.advance(); return ('return', None)
                expr = self.parse_expr(); self.expect('OP',';')
                return ('return', expr)
            elif t.value == 'break':
                self.advance(); self.expect('OP',';'); return ('break',)
            elif t.value == 'continue':
                self.advance(); self.expect('OP',';'); return ('continue',)
        if t.type == 'IDENT':
            if self.pos+1 < len(self.tokens) and self.tokens[self.pos+1].type == 'OP' and self.tokens[self.pos+1].value == '=':
                self.advance(); self.advance(); expr = self.parse_expr(); self.expect('OP',';')
                return ('assign', t.value, expr, t.line)
        expr = self.parse_expr()
        if self.peek().type == 'OP' and self.peek().value == '=':
            self.advance(); val = self.parse_expr(); self.expect('OP',';')
            return ('index_assign', expr, val, expr[3] if expr[0]=='index' else 0)
        self.expect('OP',';'); return ('exprstmt', expr)
    def parse_ifstmt(self):
        self.advance(); cond = self.parse_expr(); then_b = self.parse_block()
        else_b = None
        if self.peek().type == 'KEYWORD' and self.peek().value == 'else':
            self.advance()
            if self.peek().type == 'KEYWORD' and self.peek().value == 'if':
                else_b = self.parse_ifstmt()
            else:
                else_b = ('block', self.parse_block())
        return ('if', cond, then_b, else_b)
    def parse_expr(self): return self.parse_or()
    def parse_or(self):
        left = self.parse_and()
        while self.peek().type == 'KEYWORD' and self.peek().value == 'or':
            self.advance(); right = self.parse_and(); left = ('or', left, right)
        return left
    def parse_and(self):
        left = self.parse_not()
        while self.peek().type == 'KEYWORD' and self.peek().value == 'and':
            self.advance(); right = self.parse_not(); left = ('and', left, right)
        return left
    def parse_not(self):
        if self.peek().type == 'KEYWORD' and self.peek().value == 'not':
            self.advance(); return ('not', self.parse_not())
        return self.parse_comparison()
    def parse_comparison(self):
        left = self.parse_add()
        while self.peek().type == 'OP' and self.peek().value in ('==','!=','<','<=','>','>='):
            op = self.advance(); right = self.parse_add()
            left = ('binop', op.value, left, right, op.line)
        return left
    def parse_add(self):
        left = self.parse_mul()
        while self.peek().type == 'OP' and self.peek().value in ('+','-'):
            op = self.advance(); right = self.parse_mul()
            left = ('binop', op.value, left, right, op.line)
        return left
    def parse_mul(self):
        left = self.parse_unary()
        while self.peek().type == 'OP' and self.peek().value in ('*','/','%'):
            op = self.advance(); right = self.parse_unary()
            left = ('binop', op.value, left, right, op.line)
        return left
    def parse_unary(self):
        if self.peek().type == 'OP' and self.peek().value == '-':
            op = self.advance(); return ('neg', self.parse_unary(), op.line)
        return self.parse_postfix()
    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            if self.peek().type == 'OP' and self.peek().value == '(':
                ot = self.advance(); args = []
                if not (self.peek().type == 'OP' and self.peek().value == ')'):
                    args.append(self.parse_expr())
                    while self.match('OP',','): args.append(self.parse_expr())
                self.expect('OP',')'); expr = ('call', expr, args, ot.line)
            elif self.peek().type == 'OP' and self.peek().value == '[':
                ot = self.advance(); idx = self.parse_expr(); self.expect('OP',']')
                expr = ('index', expr, idx, ot.line)
            else: break
        return expr
    def parse_primary(self):
        t = self.peek()
        if t.type == 'INT': self.advance(); return ('int', t.value)
        if t.type == 'STRING': self.advance(); return ('str', t.value)
        if t.type == 'KEYWORD':
            if t.value == 'true': self.advance(); return ('bool', True)
            if t.value == 'false': self.advance(); return ('bool', False)
            if t.value == 'nil': self.advance(); return ('nil',)
            if t.value == 'fn':
                self.advance(); self.expect('OP','('); params = self.parse_params(); self.expect('OP',')')
                body = self.parse_block(); return ('fn', params, body)
        if t.type == 'IDENT':
            self.advance(); return ('ident', t.value, t.line)
        if t.type == 'OP' and t.value == '(':
            self.advance(); e = self.parse_expr(); self.expect('OP',')'); return e
        if t.type == 'OP' and t.value == '[':
            self.advance(); elems = []
            if not (self.peek().type == 'OP' and self.peek().value == ']'):
                elems.append(self.parse_expr())
                while self.match('OP',','): elems.append(self.parse_expr())
            self.expect('OP',']'); return ('list', elems)
        self.advance(); return ('nil',)

_NOT_FOUND = object()

class Function:
    __slots__ = ('params','body','captured_scope')
    def __init__(self, p, b, s): self.params=p; self.body=b; self.captured_scope=s

class Builtin:
    __slots__ = ('name','func','arity')
    def __init__(self, n, f, a): self.name=n; self.func=f; self.arity=a

class Scope:
    __slots__ = ('vars','parent')
    def __init__(self, parent=None): self.vars={}; self.parent=parent
    def get(self, name):
        s = self
        while s is not None:
            if name in s.vars: return s.vars[name]
            s = s.parent
        return _NOT_FOUND
    def set(self, name, val):
        s = self
        while s is not None:
            if name in s.vars: s.vars[name]=val; return True
            s = s.parent
        return False
    def declare(self, name, val): self.vars[name]=val

class TernError(Exception):
    def __init__(self, line, msg): self.line=line; self.msg=msg

class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass
class ReturnSignal(Exception):
    def __init__(self, v): self.value=v
class BuiltinError(Exception):
    def __init__(self, name): self.name=name

def check_int(v): return isinstance(v, int) and not isinstance(v, bool)

def type_name(v):
    if v is None: return "nil"
    if isinstance(v, bool): return "bool"
    if isinstance(v, int): return "int"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "list"
    if isinstance(v, (Function, Builtin)): return "function"
    return "unknown"

def is_truthy(v):
    if v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, int): return v != 0
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, list): return len(v) > 0
    return True

def tern_equal(a, b):
    if a is None and b is None: return True
    if a is None or b is None: return False
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, int) and isinstance(b, int): return a == b
    if isinstance(a, int) or isinstance(b, int): return False
    if isinstance(a, str) and isinstance(b, str): return a == b
    if isinstance(a, str) or isinstance(b, str): return False
    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b): return False
        return all(tern_equal(x,y) for x,y in zip(a,b))
    if isinstance(a, list) or isinstance(b, list): return False
    if isinstance(a, (Function,Builtin)) or isinstance(b, (Function,Builtin)):
        return a is b
    return False

def esc_str(s):
    r = []
    for c in s:
        if c=='\\': r.append('\\\\')
        elif c=='"': r.append('\\"')
        elif c=='\n': r.append('\\n')
        elif c=='\t': r.append('\\t')
        else: r.append(c)
    return ''.join(r)

def display(v, in_list=False, anc=None):
    if anc is None: anc = frozenset()
    if v is None: return "nil"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, int): return str(v)
    if isinstance(v, str):
        return '"' + esc_str(v) + '"' if in_list else v
    if isinstance(v, list):
        if id(v) in anc: return "[...]"
        na = anc | {id(v)}
        if not v: return "[]"
        return "[" + ", ".join(display(e, True, na) for e in v) + "]"
    if isinstance(v, (Function, Builtin)): return "<fn>"
    return str(v)

def trunc_div(a, b):
    q = abs(a) // abs(b)
    if (a < 0) ^ (b < 0): q = -q
    return q

def trunc_mod(a, b):
    if b == -1: return 0
    return a - trunc_div(a, b) * b

def check_range(v, line):
    if v < INT_MIN or v > INT_MAX:
        raise TernError(line, "integer overflow")

class Interpreter:
    def __init__(self):
        self.output = []
        self.builtins_scope = self._make_builtins()

    def _make_builtins(self):
        sc = Scope(None)
        def bprint(args):
            self.output.append(' '.join(display(a) for a in args))
            return None
        def bstr(args):
            return display(args[0])
        def btype(args):
            return type_name(args[0])
        def blen(args):
            x = args[0]
            if isinstance(x, str) or isinstance(x, list): return len(x)
            raise BuiltinError("len")
        def bpush(args):
            lst, v = args
            if not isinstance(lst, list): raise BuiltinError("push")
            lst.append(v); return None
        def bpop(args):
            lst = args[0]
            if not isinstance(lst, list) or len(lst)==0: raise BuiltinError("pop")
            return lst.pop()
        def brange(args):
            a, b = args
            if not (check_int(a) and check_int(b)): raise BuiltinError("range")
            if b <= a: return []
            return list(range(a, b))
        def bslice(args):
            x, a, b = args
            if not (check_int(a) and check_int(b)): raise BuiltinError("slice")
            if isinstance(x, str):
                if not (0<=a<=b<=len(x)): raise BuiltinError("slice")
                return x[a:b]
            elif isinstance(x, list):
                if not (0<=a<=b<=len(x)): raise BuiltinError("slice")
                return x[a:b]
            raise BuiltinError("slice")
        sc.declare('print', Builtin('print', bprint, None))
        sc.declare('str', Builtin('str', bstr, 1))
        sc.declare('type', Builtin('type', btype, 1))
        sc.declare('len', Builtin('len', blen, 1))
        sc.declare('push', Builtin('push', bpush, 2))
        sc.declare('pop', Builtin('pop', bpop, 1))
        sc.declare('range', Builtin('range', brange, 2))
        sc.declare('slice', Builtin('slice', bslice, 3))
        return sc

    def run(self, program):
        gs = Scope(self.builtins_scope)
        try:
            self.exec_block(program, gs)
        except TernError as e:
            self.output.append(f"error at line {e.line}: {e.msg}")

    def exec_block(self, stmts, scope):
        for s in stmts:
            self.exec_stmt(s, scope)

    def exec_stmt(self, stmt, scope):
        k = stmt[0]
        if k == 'let':
            _, name, expr = stmt
            scope.declare(name, self.eval_expr(expr, scope))
        elif k == 'fnstmt':
            _, name, params, body = stmt
            scope.declare(name, Function(params, body, scope))
        elif k == 'if':
            _, cond, then_b, else_b = stmt
            if is_truthy(self.eval_expr(cond, scope)):
                self.exec_block(then_b, Scope(scope))
            elif else_b is not None:
                if else_b[0] == 'if':
                    self.exec_stmt(else_b, scope)
                else:
                    self.exec_block(else_b[1], Scope(scope))
        elif k == 'while':
            _, cond, body = stmt
            while is_truthy(self.eval_expr(cond, scope)):
                try:
                    self.exec_block(body, Scope(scope))
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
        elif k == 'for':
            _, var, expr, body, line = stmt
            lst = self.eval_expr(expr, scope)
            if not isinstance(lst, list):
                raise TernError(line, f"cannot iterate {type_name(lst)}")
            i = 0
            while i < len(lst):
                inner = Scope(scope)
                inner.declare(var, lst[i])
                try:
                    self.exec_block(body, inner)
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
                i += 1
        elif k == 'return':
            _, expr = stmt
            raise ReturnSignal(self.eval_expr(expr, scope) if expr is not None else None)
        elif k == 'break':
            raise BreakSignal()
        elif k == 'continue':
            raise ContinueSignal()
        elif k == 'assign':
            _, name, expr, line = stmt
            val = self.eval_expr(expr, scope)
            if not scope.set(name, val):
                raise TernError(line, f"undefined variable {name}")
        elif k == 'index_assign':
            _, idx_expr, val_expr, line = stmt
            obj = self.eval_expr(idx_expr[1], scope)
            idx = self.eval_expr(idx_expr[2], scope)
            val = self.eval_expr(val_expr, scope)
            if not isinstance(obj, list):
                raise TernError(line, f"cannot assign into {type_name(obj)}")
            if not check_int(idx):
                raise TernError(line, f"cannot index list with {type_name(idx)}")
            if idx < 0 or idx >= len(obj):
                raise TernError(line, f"index {idx} out of range for length {len(obj)}")
            obj[idx] = val
        elif k == 'exprstmt':
            self.eval_expr(stmt[1], scope)

    def eval_expr(self, expr, scope):
        k = expr[0]
        if k == 'int': return expr[1]
        if k == 'str': return expr[1]
        if k == 'bool': return expr[1]
        if k == 'nil': return None
        if k == 'ident':
            _, name, line = expr
            v = scope.get(name)
            if v is _NOT_FOUND:
                raise TernError(line, f"undefined variable {name}")
            return v
        if k == 'binop':
            _, op, left, right, line = expr
            if op == '==':
                return tern_equal(self.eval_expr(left, scope), self.eval_expr(right, scope))
            if op == '!=':
                return not tern_equal(self.eval_expr(left, scope), self.eval_expr(right, scope))
            lv = self.eval_expr(left, scope)
            rv = self.eval_expr(right, scope)
            return self._binop(op, lv, rv, line)
        if k == 'neg':
            _, operand, line = expr
            v = self.eval_expr(operand, scope)
            if not check_int(v):
                raise TernError(line, f"cannot apply - to {type_name(v)}")
            r = -v
            if r < INT_MIN or r > INT_MAX:
                raise TernError(line, "integer overflow")
            return r
        if k == 'not':
            return not is_truthy(self.eval_expr(expr[1], scope))
        if k == 'and':
            lv = self.eval_expr(expr[1], scope)
            if not is_truthy(lv): return lv
            return self.eval_expr(expr[2], scope)
        if k == 'or':
            lv = self.eval_expr(expr[1], scope)
            if is_truthy(lv): return lv
            return self.eval_expr(expr[2], scope)
        if k == 'call':
            _, callee_e, args_e, line = expr
            callee = self.eval_expr(callee_e, scope)
            args = [self.eval_expr(a, scope) for a in args_e]
            return self._call(callee, args, line)
        if k == 'index':
            _, obj_e, idx_e, line = expr
            obj = self.eval_expr(obj_e, scope)
            idx = self.eval_expr(idx_e, scope)
            if not (isinstance(obj, (list, str)) and check_int(idx)):
                raise TernError(line, f"cannot index {type_name(obj)} with {type_name(idx)}")
            if idx < 0 or idx >= len(obj):
                raise TernError(line, f"index {idx} out of range for length {len(obj)}")
            return obj[idx]
        if k == 'list':
            return [self.eval_expr(e, scope) for e in expr[1]]
        if k == 'fn':
            return Function(expr[1], expr[2], scope)
        return None

    def _binop(self, op, lv, rv, line):
        if op == '+':
            if check_int(lv) and check_int(rv):
                r = lv + rv; check_range(r, line); return r
            if isinstance(lv, str) and isinstance(rv, str): return lv + rv
            if isinstance(lv, list) and isinstance(rv, list): return lv + rv
            raise TernError(line, f"cannot apply + to {type_name(lv)} and {type_name(rv)}")
        if op == '-':
            if check_int(lv) and check_int(rv):
                r = lv - rv; check_range(r, line); return r
            raise TernError(line, f"cannot apply - to {type_name(lv)} and {type_name(rv)}")
        if op == '*':
            if check_int(lv) and check_int(rv):
                r = lv * rv; check_range(r, line); return r
            raise TernError(line, f"cannot apply * to {type_name(lv)} and {type_name(rv)}")
        if op == '/':
            if check_int(lv) and check_int(rv):
                if rv == 0: raise TernError(line, "division by zero")
                r = trunc_div(lv, rv); check_range(r, line); return r
            raise TernError(line, f"cannot apply / to {type_name(lv)} and {type_name(rv)}")
        if op == '%':
            if check_int(lv) and check_int(rv):
                if rv == 0: raise TernError(line, "division by zero")
                r = trunc_mod(lv, rv); check_range(r, line); return r
            raise TernError(line, f"cannot apply % to {type_name(lv)} and {type_name(rv)}")
        if op in ('<','<=','>','>='):
            if check_int(lv) and check_int(rv): pass
            elif isinstance(lv, str) and isinstance(rv, str): pass
            else: raise TernError(line, f"cannot apply {op} to {type_name(lv)} and {type_name(rv)}")
            if op == '<': return lv < rv
            if op == '<=': return lv <= rv
            if op == '>': return lv > rv
            return lv >= rv
        return None

    def _call(self, callee, args, line):
        if isinstance(callee, Builtin):
            if callee.arity is not None and len(args) != callee.arity:
                raise TernError(line, f"expected {callee.arity} arguments, got {len(args)}")
            try:
                return callee.func(args)
            except BuiltinError as e:
                raise TernError(line, f"bad argument to {e.name}")
        if isinstance(callee, Function):
            if len(args) != len(callee.params):
                raise TernError(line, f"expected {len(callee.params)} arguments, got {len(args)}")
            cs = Scope(callee.captured_scope)
            for p, a in zip(callee.params, args):
                cs.declare(p, a)
            try:
                self.exec_block(callee.body, cs)
            except ReturnSignal as r:
                return r.value
            return None
        raise TernError(line, f"cannot call {type_name(callee)}")

def main():
    if len(sys.argv) < 2:
        return
    d = sys.argv[1]
    with open(os.path.join(d, 'program.tern'), 'r') as f:
        source = f.read()
    tokens = tokenize(source)
    parser = Parser(tokens)
    program = parser.parse_program()
    interp = Interpreter()
    interp.run(program)
    out = sys.stdout
    for line in interp.output:
        out.write(line + '\n')
    out.flush()

if __name__ == '__main__':
    main()

use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".eml") {
            files.push(name);
        }
    }
    files.sort();
    let mut first = true;
    for name in &files {
        if !first { println!(); }
        first = false;
        let path = Path::new(dir).join(name);
        let data = fs::read(&path).unwrap();
        let le = if data.contains(&b'\r') && {
            let mut found = false;
            for i in 0..data.len().saturating_sub(1) {
                if data[i] == b'\r' && data[i+1] == b'\n' { found = true; break; }
            }
            found
        } { b"\r\n".to_vec() } else { b"\n".to_vec() };
        let entity = parse_entity(&data, &le);
        println!("== {}", name);
        let from = get_header(&entity, "from");
        let subject = get_header(&entity, "subject");
        match from {
            Some(v) => println!("From: {}", quoted_string(&decode_encoded_words(&v))),
            None => println!("From: -"),
        }
        match subject {
            Some(v) => println!("Subject: {}", quoted_string(&decode_encoded_words(&v))),
            None => println!("Subject: -"),
        }
        let mut out = String::new();
        print_entity(&entity, 0, &mut out);
        print!("{}", out);
    }
}

struct Entity {
    headers: Vec<(String, String)>,
    body: Vec<u8>,
    ct_type: String,
    ct_subtype: String,
    ct_params: Vec<(String, String)>,
    cd_type: Option<String>,
    cd_params: Vec<(String, String)>,
    cte: String,
    parts: Vec<Entity>,
    is_multipart: bool,
}

fn get_header(e: &Entity, name: &str) -> Option<String> {
    e.headers.iter().find(|(k,_)| k == name).map(|(_,v)| v.clone())
}

fn get_param(params: &[(String,String)], name: &str) -> Option<String> {
    params.iter().find(|(k,_)| k == name).map(|(_,v)| v.clone())
}

fn parse_entity(data: &[u8], le: &[u8]) -> Entity {
    let lines = split_lines(data, le);
    let empty_idx = lines.iter().position(|&(s,e)| s == e);
    let (hdr_lines, body_start) = match empty_idx {
        Some(idx) => {
            let bs = if idx + 1 < lines.len() { lines[idx+1].0 } else { data.len() };
            (&lines[..idx], bs)
        }
        None => (&lines[..], data.len()),
    };
    let headers = unfold_headers(hdr_lines, data, le);
    let body = data[body_start..].to_vec();
    let ct_str = get_header(&Entity{headers: headers.clone(), body: vec![], ct_type: String::new(), ct_subtype: String::new(), ct_params: vec![], cd_type: None, cd_params: vec![], cte: String::new(), parts: vec![], is_multipart: false}, "content-type");
    let (ct_type, ct_subtype, ct_params) = match &ct_str {
        Some(s) => parse_content_type(s),
        None => ("text".to_string(), "plain".to_string(), vec![]),
    };
    let cd_str = get_header(&Entity{headers: headers.clone(), body: vec![], ct_type: String::new(), ct_subtype: String::new(), ct_params: vec![], cd_type: None, cd_params: vec![], cte: String::new(), parts: vec![], is_multipart: false}, "content-disposition");
    let (cd_type, cd_params) = match &cd_str {
        Some(s) => parse_content_disp(s),
        None => (None, vec![]),
    };
    let cte_str = get_header(&Entity{headers: headers.clone(), body: vec![], ct_type: String::new(), ct_subtype: String::new(), ct_params: vec![], cd_type: None, cd_params: vec![], cte: String::new(), parts: vec![], is_multipart: false}, "content-transfer-encoding");
    let cte = cte_str.unwrap_or_else(|| "7bit".to_string()).to_lowercase();
    let is_multipart = ct_type == "multipart";
    let parts = if is_multipart {
        let boundary = get_param(&ct_params, "boundary").unwrap_or_default();
        parse_multipart_parts(&body, boundary.as_bytes(), le)
    } else {
        vec![]
    };
    Entity { headers, body, ct_type, ct_subtype, ct_params, cd_type, cd_params, cte, parts, is_multipart }
}

fn split_lines(data: &[u8], le: &[u8]) -> Vec<(usize, usize)> {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < data.len() {
        if i + le.len() <= data.len() && &data[i..i+le.len()] == le {
            lines.push((start, i));
            i += le.len();
            start = i;
        } else {
            i += 1;
        }
    }
    if start < data.len() {
        lines.push((start, data.len()));
    }
    lines
}

fn unfold_headers(hdr_lines: &[(usize, usize)], data: &[u8], le: &[u8]) -> Vec<(String, String)> {
    let mut result: Vec<(String, String)> = Vec::new();
    let mut i = 0;
    while i < hdr_lines.len() {
        let (s, e) = hdr_lines[i];
        let mut line = data[s..e].to_vec();
        i += 1;
        while i < hdr_lines.len() {
            let (ns, ne) = hdr_lines[i];
            if ns < data.len() && (data[ns] == b' ' || data[ns] == b'\t') {
                line.extend_from_slice(&data[ns..ne]);
                i += 1;
            } else {
                break;
            }
        }
        let line_str = String::from_utf8_lossy(&line).to_string();
        if let Some(colon_pos) = line_str.find(':') {
            let name = line_str[..colon_pos].trim().to_lowercase();
            let value = line_str[colon_pos+1..].trim_matches(|c| c==' '||c=='\t').to_string();
            result.push((name, value));
        }
    }
    result
}

fn parse_content_type(s: &str) -> (String, String, Vec<(String, String)>) {
    let mut pos = 0;
    let bytes = s.as_bytes();
    skip_ws(bytes, &mut pos);
    let type_str = read_token(bytes, &mut pos).to_lowercase();
    skip_ws(bytes, &mut pos);
    if pos < bytes.len() && bytes[pos] == b'/' { pos += 1; }
    skip_ws(bytes, &mut pos);
    let subtype = read_token(bytes, &mut pos).to_lowercase();
    let params = parse_params(bytes, &mut pos);
    (type_str, subtype, params)
}

fn parse_content_disp(s: &str) -> (Option<String>, Vec<(String, String)>) {
    let mut pos = 0;
    let bytes = s.as_bytes();
    skip_ws(bytes, &mut pos);
    let dtype = read_token(bytes, &mut pos).to_lowercase();
    let params = parse_params(bytes, &mut pos);
    let dtype = if dtype.is_empty() { None } else { Some(dtype) };
    (dtype, params)
}

fn skip_ws(b: &[u8], pos: &mut usize) {
    while *pos < b.len() && (b[*pos] == b' ' || b[*pos] == b'\t') { *pos += 1; }
}

fn read_token(b: &[u8], pos: &mut usize) -> String {
    let start = *pos;
    while *pos < b.len() && b[*pos] != b';' && b[*pos] != b' ' && b[*pos] != b'\t' {
        *pos += 1;
    }
    String::from_utf8_lossy(&b[start..*pos]).to_string()
}

fn read_quoted(b: &[u8], pos: &mut usize) -> String {
    // pos should be at the opening "
    *pos += 1; // skip "
    let mut result = Vec::new();
    while *pos < b.len() {
        if b[*pos] == b'\\' && *pos + 1 < b.len() {
            result.push(b[*pos+1]);
            *pos += 2;
        } else if b[*pos] == b'"' {
            *pos += 1;
            break;
        } else {
            result.push(b[*pos]);
            *pos += 1;
        }
    }
    String::from_utf8_lossy(&result).to_string()
}

fn read_param_value(b: &[u8], pos: &mut usize) -> String {
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b'"' {
        read_quoted(b, pos)
    } else {
        read_token(b, pos)
    }
}

fn parse_params(b: &[u8], pos: &mut usize) -> Vec<(String, String)> {
    let mut params = Vec::new();
    loop {
        skip_ws(b, pos);
        if *pos >= b.len() { break; }
        if b[*pos] != b';' { break; }
        *pos += 1; // skip ;
        skip_ws(b, pos);
        if *pos >= b.len() { break; }
        let attr = read_param_attr(b, pos).to_lowercase();
        skip_ws(b, pos);
        if *pos < b.len() && b[*pos] == b'=' {
            *pos += 1;
            skip_ws(b, pos);
            let val = read_param_value(b, pos);
            params.push((attr, val));
        } else {
            params.push((attr, String::new()));
        }
    }
    params
}

fn read_param_attr(b: &[u8], pos: &mut usize) -> String {
    let start = *pos;
    while *pos < b.len() && b[*pos] != b'=' && b[*pos] != b';' && b[*pos] != b' ' && b[*pos] != b'\t' {
        *pos += 1;
    }
    String::from_utf8_lossy(&b[start..*pos]).to_string()
}

fn parse_multipart_parts(body: &[u8], boundary: &[u8], le: &[u8]) -> Vec<Vec<u8>> {
    let lines = split_lines(body, le);
    let mut delim_indices: Vec<usize> = Vec::new();
    for (i, &(s, e)) in lines.iter().enumerate() {
        let line = &body[s..e];
        if is_delimiter(line, boundary) || is_close_delim(line, boundary) {
            delim_indices.push(i);
        }
    }
    if delim_indices.len() < 2 { return vec![]; }
    let mut parts = Vec::new();
    for w in 0..delim_indices.len()-1 {
        let di1 = delim_indices[w];
        let di2 = delim_indices[w+1];
        let part_start = if di1 + 1 < lines.len() { lines[di1+1].0 } else { body.len() };
        let part_end = if di2 > 0 {
            let prev_line_end = lines[di2-1].1;
            prev_line_end
        } else {
            part_start
        };
        if part_start <= part_end {
            parts.push(body[part_start..part_end].to_vec());
        } else {
            parts.push(vec![]);
        }
    }
    parts
}

fn is_delimiter(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 2 + boundary.len();
    if line.len() < prefix_len { return false; }
    if &line[0..2] != b"--" { return false; }
    if &line[2..prefix_len] != boundary { return false; }
    line[prefix_len..].iter().all(|&c| c == b' ' || c == b'\t')
}

fn is_close_delim(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 4 + boundary.len();
    if line.len() < prefix_len { return false; }
    if &line[0..2] != b"--" { return false; }
    if &line[2..2+boundary.len()] != boundary { return false; }
    if &line[2+boundary.len()..prefix_len] != b"--" { return false; }
    line[prefix_len..].iter().all(|&c| c == b' ' || c == b'\t')
}

fn print_entity(e: &Entity, indent: usize, out: &mut String) {
    let prefix = " ".repeat(indent * 2);
    if e.is_multipart {
        out.push_str(&format!("{}multipart/{} parts={}\n", prefix, e.ct_subtype, e.parts.len()));
        for p in &e.parts {
            let pe = parse_entity_from_bytes(p, &get_le(e));
            print_entity(&pe, indent + 1, out);
        }
    } else if is_text_part(e) {
        let charset = get_param(&e.ct_params, "charset").unwrap_or_else(|| "us-ascii".to_string()).to_lowercase();
        let decoded_bytes = decode_cte(&e.body, &e.cte);
        let mut text = decode_charset(&decoded_bytes, &charset);
        text = text.replace("\r\n", "\n").replace('\r', "\n");
        let chars = text.chars().count();
        out.push_str(&format!("{}text/{} charset={} cte={} chars={}\n", prefix, e.ct_subtype, charset, e.cte, chars));
        out.push_str(&format!("{}  {}\n", prefix, quoted_string(&text)));
    } else {
        let decoded_bytes = decode_cte(&e.body, &e.cte);
        let size = decoded_bytes.len();
        let crc = crc32(&decoded_bytes);
        let disp = e.cd_type.as_deref().unwrap_or("-");
        let name = get_filename(e);
        let name_str = match &name {
            Some(n) => quoted_string(n),
            None => "-".to_string(),
        };
        out.push_str(&format!("{}{}/{} cte={} disposition={} name={} size={} crc32={:08x}\n",
            prefix, e.ct_type, e.ct_subtype, e.cte, disp, name_str, size, crc));
    }
}

fn get_le(_e: &Entity) -> Vec<u8> {
    // We need to pass line_end through; let's store it differently
    // This is a hack; let's restructure
    b"\r\n".to_vec()
}

fn parse_entity_from_bytes(data: &[u8], le: &[u8]) -> Entity {
    parse_entity(data, le)
}

fn is_text_part(e: &Entity) -> bool {
    e.ct_type == "text" && e.cd_type.as_deref() != Some("attachment")
}

fn decode_cte(data: &[u8], encoding: &str) -> Vec<u8> {
    match encoding {
        "base64" => decode_base64(data),
        "quoted-printable" => decode_quoted_printable(data),
        _ => data.to_vec(),
    }
}

fn decode_base64(data: &[u8]) -> Vec<u8> {
    let mut filtered: Vec<u8> = Vec::new();
    for &b in data {
        if b == b'=' { break; }
        if b.is_ascii_alphanumeric() || b == b'+' || b == b'/' {
            filtered.push(b);
        }
    }
    let mut result = Vec::new();
    let mut i = 0;
    while i + 3 < filtered.len() {
        let n = (b64val(filtered[i]) as u32) << 18 |
                (b64val(filtered[i+1]) as u32) << 12 |
                (b64val(filtered[i+2]) as u32) << 6 |
                (b64val(filtered[i+3]) as u32);
        result.push((n >> 16) as u8);
        result.push((n >> 8) as u8);
        result.push(n as u8);
        i += 4;
    }
    let rem = filtered.len() - i;
    if rem == 2 {
        let n = (b64val(filtered[i]) as u32) << 18 | (b64val(filtered[i+1]) as u32) << 12;
        result.push((n >> 16) as u8);
    } else if rem == 3 {
        let n = (b64val(filtered[i]) as u32) << 18 | (b64val(filtered[i+1]) as u32) << 12 |
                (b64val(filtered[i+2]) as u32) << 6;
        result.push((n >> 16) as u8);
        result.push((n >> 8) as u8);
    }
    result
}

fn b64val(b: u8) -> u8 {
    match b {
        b'A'..=b'Z' => b - b'A',
        b'a'..=b'z' => b - b'a' + 26,
        b'0'..=b'9' => b - b'0' + 52,
        b'+' => 62,
        b'/' => 63,
        _ => 0,
    }
}

fn decode_quoted_printable(data: &[u8]) -> Vec<u8> {
    // Determine line ending in this data
    let le: Vec<u8> = if data.windows(2).any(|w| w == b"\r\n") { b"\r\n".to_vec() } else { b"\n".to_vec() };
    let lines = split_lines(data, &le);
    let mut processed_lines: Vec<Vec<u8>> = Vec::new();
    for &(s, e) in &lines {
        let mut line = data[s..e].to_vec();
        // Remove trailing spaces and tabs
        while !line.is_empty() && (line[line.len()-1] == b' ' || line[line.len()-1] == b'\t') {
            line.pop();
        }
        processed_lines.push(line);
    }
    // Handle soft line breaks
    let mut merged: Vec<Vec<u8>> = Vec::new();
    let mut current: Vec<u8> = Vec::new();
    for (i, line) in processed_lines.into_iter().enumerate() {
        if !line.is_empty() && line[line.len()-1] == b'=' {
            // Check if this would split an =XY sequence
            // If line ends with = and it's not part of =XY (i.e., the = is the last char)
            // Actually, if line ends with =, it's a soft line break UNLESS it would split =XY
            // "A soft line break never splits an =XY sequence"
            // If the line ends with =X (where X is hex) and next line starts with Y (hex), don't break
            // But the line ends with =, so there's nothing after = on this line
            // The check: if we remove the = and join with next line, does it create =XY?
            // If line is "...=" and next starts with "XY...", joining gives "...XY..." - no = before XY
            // Actually the = is removed, so no issue
            // But what if line is "...=X" - wait, it ends with =, so last char is =
            // Hmm, let me re-read: "a line that then ends with `=` is joined"
            // So if after removing trailing ws, line ends with =, it's a soft line break
            // "A soft line break never splits an =XY sequence" means:
            // if line ends with =X (hex) and next line starts with Y (hex), the = is NOT a soft line break
            // But if line ends with =X, the last char is X not =, so it's not a soft line break anyway!
            // Unless... the line is just "=" or ends with "=" after removing trailing ws
            // I think the rule is: if line ends with = (last char), it's soft line break
            // The "never splits =XY" just means we don't accidentally treat =X at end as soft break
            // Since =X doesn't end with =, it's fine
            current.extend_from_slice(&line[..line.len()-1]); // remove the =
            // Don't add line break - this is the soft line break
        } else {
            current.extend_from_slice(&line);
            if i < processed_lines.len() - 1 {
                merged.push(current.clone());
                current.clear();
            }
        }
    }
    if !current.is_empty() || merged.is_empty() {
        merged.push(current);
    }
    // Now decode =XY sequences
    let mut result: Vec<u8> = Vec::new();
    for (i, line) in merged.iter().enumerate() {
        let mut j = 0;
        while j < line.len() {
            if line[j] == b'=' && j + 2 < line.len() && is_hex(line[j+1]) && is_hex(line[j+2]) {
                let hi = hex_val(line[j+1]);
                let lo = hex_val(line[j+2]);
                result.push(hi * 16 + lo);
                j += 3;
            } else {
                result.push(line[j]);
                j += 1;
            }
        }
        if i < merged.len() - 1 {
            result.push(b'\n');
        }
    }
    result
}

fn is_hex(b: u8) -> bool {
    b.is_ascii_digit() || (b >= b'a' && b <= b'f') || (b >= b'A' && b <= b'F')
}

fn hex_val(b: u8) -> u8 {
    if b >= b'0' && b <= b'9' { b - b'0' }
    else if b >= b'a' && b <= b'f' { b - b'a' + 10 }
    else { b - b'A' + 10 }
}

fn decode_charset(data: &[u8], charset: &str) -> String {
    match charset {
        "utf-8" | "us-ascii" => String::from_utf8_lossy(data).to_string(),
        "iso-8859-1" => data.iter().map(|&b| char::from_u32(b as u32).unwrap()).collect(),
        "windows-1252" => {
            data.iter().map(|&b| {
                if b >= 0x80 && b <= 0x9F {
                    let cp = WINDOWS_1252[(b - 0x80) as usize];
                    char::from_u32(cp).unwrap_or('\u{FFFD}')
                } else {
                    char::from_u32(b as u32).unwrap()
                }
            }).collect()
        },
        _ => String::from_utf8_lossy(data).to_string(),
    }
}

static WINDOWS_1252: [u32; 32] = [
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
    0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
    0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
    0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
];

fn decode_encoded_words(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut result = String::new();
    let mut pos = 0;
    while pos < bytes.len() {
        if let Some((ms, me, charset, encoding, etext)) = find_encoded_word(bytes, pos) {
            let base_cs = normalize_charset_name(&charset);
            let mut all_bytes: Vec<u8> = Vec::new();
            all_bytes.extend(decode_word_bytes(encoding, &etext));
            let mut next_pos = me;
            loop {
                let mut skip = next_pos;
                while skip < bytes.len() && (bytes[skip] == b' ' || bytes[skip] == b'\t') {
                    skip += 1;
                }
                if skip >= bytes.len() { break; }
                if let Some((ms2, me2, cs2, enc2, et2)) = find_encoded_word(bytes, skip) {
                    if ms2 == skip && normalize_charset_name(&cs2) == base_cs {
                        all_bytes.extend(decode_word_bytes(enc2, &et2));
                        next_pos = me2;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            let decoded = decode_charset(&all_bytes, &base_cs);
            result.push_str(&decoded);
            pos = next_pos;
        } else {
            result.push(bytes[pos] as char);
            pos += 1;
        }
    }
    result
}

fn normalize_charset_name(cs: &str) -> String {
    let lower = cs.to_lowercase();
    if let Some(idx) = lower.find('*') {
        lower[..idx].to_string()
    } else {
        lower
    }
}

fn find_encoded_word(b: &[u8], start: usize) -> Option<(usize, usize, String, u8, String)> {
    let mut i = start;
    while i + 1 < b.len() {
        if b[i] == b'=' && b[i+1] == b'?' {
            let ms = i;
            i += 2;
            let cs_start = i;
            while i < b.len() && b[i] != b'?' && b[i] != b' ' && b[i] != b'\t' { i += 1; }
            if i == cs_start || i >= b.len() || b[i] != b'?' { i = ms + 1; continue; }
            let charset = String::from_utf8_lossy(&b[cs_start..i]).to_string();
            i += 1;
            if i >= b.len() { i = ms + 1; continue; }
            let enc = b[i];
            if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' { i = ms + 1; continue; }
            i += 1;
            if i >= b.len() || b[i] != b'?' { i = ms + 1; continue; }
            i += 1;
            let et_start = i;
            while i < b.len() && b[i] != b'?' && b[i] != b' ' && b[i] != b'\t' { i += 1; }
            let etext = String::from_utf8_lossy(&b[et_start..i]).to_string();
            if i + 1 >= b.len() || b[i] != b'?' || b[i+1] != b'=' { i = ms + 1; continue; }
            i += 2;
            return Some((ms, i, charset, enc, etext));
        }
        i += 1;
    }
    None
}

fn decode_word_bytes(encoding: u8, etext: &str) -> Vec<u8> {
    if encoding == b'B' || encoding == b'b' {
        decode_base64(etext.as_bytes())
    } else {
        let b = etext.as_bytes();
        let mut result = Vec::new();
        let mut i = 0;
        while i < b.len() {
            if b[i] == b'_' {
                result.push(0x20);
                i += 1;
            } else if b[i] == b'=' && i + 2 < b.len() && is_hex(b[i+1]) && is_hex(b[i+2]) {
                result.push(hex_val(b[i+1]) * 16 + hex_val(b[i+2]));
                i += 3;
            } else {
                result.push(b[i]);
                i += 1;
            }
        }
        result
    }
}

fn get_filename(e: &Entity) -> Option<String> {
    // Check CD filename* (RFC 2231), CD filename, CT name* (RFC 2231), CT name
    if let Some(v) = try_rfc2231(&e.cd_params, "filename") { return Some(v); }
    if let Some(v) = get_param(&e.cd_params, "filename") { return Some(decode_encoded_words(&v)); }
    if let Some(v) = try_rfc2231(&e.ct_params, "name") { return Some(v); }
    if let Some(v) = get_param(&e.ct_params, "name") { return Some(decode_encoded_words(&v)); }
    None
}

fn try_rfc2231(params: &[(String, String)], attr: &str) -> Option<String> {
    // Check single form: attr*
    let single_name = format!("{}*", attr);
    if let Some(val) = get_param(params, &single_name) {
        return decode_rfc2231_single(&val);
    }
    // Check continuation: attr*0, attr*1, ..., attr*0*, attr*1*, ...
    let mut segments: Vec<(u32, bool, String)> = Vec::new(); // (index, percent_encoded, value)
    for (name, val) in params {
        if name.starts_with(&format!("{}*", attr)) {
            let rest = &name[attr.len()+1..];
            if rest.is_empty() { continue; } // that's the single form
            let (idx_str, pct) = if rest.ends_with('*') {
                (&rest[..rest.len()-1], true)
            } else {
                (rest, false)
            };
            if let Ok(idx) = idx_str.parse::<u32>() {
                segments.push((idx, pct, val.clone()));
            }
        }
    }
    if segments.is_empty() { return None; }
    segments.sort_by_key(|(i,_,_)| *i);
    // Check if any is percent-encoded; if so, segment 0 must be
    let has_pct = segments.iter().any(|(_,p,_)| *p);
    if has_pct && !segments[0].1 { return None; }
    // Determine charset
    let mut charset = "us-ascii".to_string();
    let mut all_bytes: Vec<u8> = Vec::new();
    let mut first_pct = true;
    for (_, pct, val) in &segments {
        let mut v = val.as_bytes().to_vec();
        if *pct {
            if first_pct {
                // Strip charset'language' prefix
                if let Some(q1) = v.iter().position(|&c| c == b'\'') {
                    charset = String::from_utf8_lossy(&v[..q1]).to_lowercase();
                    if let Some(q2) = v[q1+1..].iter().position(|&c| c == b'\'') {
                        v = v[q1+1+q2+1..].to_vec();
                    } else {
                        v = v[q1+1..].to_vec();
                    }
                }
                first_pct = false;
            }
            // Percent-decode
            let mut decoded = Vec::new();
            let mut i = 0;
            while i < v.len() {
                if v[i] == b'%' && i + 2 < v.len() && is_hex(v[i+1]) && is_hex(v[i+2]) {
                    decoded.push(hex_val(v[i+1]) * 16 + hex_val(v[i+2]));
                    i += 3;
                } else {
                    decoded.push(v[i]);
                    i += 1;
                }
            }
            all_bytes.extend(decoded);
        } else {
            all_bytes.extend(v);
        }
    }
    Some(decode_charset(&all_bytes, &charset))
}

fn decode_rfc2231_single(val: &str) -> Option<String> {
    let b = val.as_bytes();
    let q1 = b.iter().position(|&c| c == b'\'')?;
    let charset = String::from_utf8_lossy(&b[..q1]).to_lowercase();
    let rest_start = q1 + 1;
    let rest = if rest_start < b.len() {
        match b[rest_start..].iter().position(|&c| c == b'\'') {
            Some(q2) => &b[rest_start+q2+1..],
            None => &b[rest_start..],
        }
    } else {
        &b[rest_start..]
    };
    let mut decoded = Vec::new();
    let mut i = 0;
    while i < rest.len() {
        if rest[i] == b'%' && i + 2 < rest.len() && is_hex(rest[i+1]) && is_hex(rest[i+2]) {
            decoded.push(hex_val(rest[i+1]) * 16 + hex_val(rest[i+2]));
            i += 3;
        } else {
            decoded.push(rest[i]);
            i += 1;
        }
    }
    Some(decode_charset(&decoded, &charset))
}

fn quoted_string(s: &str) -> String {
    let mut result = String::from("\"");
    for ch in s.chars() {
        match ch {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 || ((c as u32) >= 0x7F && (c as u32) <= 0x9F) => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1); }
            else { c >>= 1; }
        }
        table[i as usize] = c;
    }
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".eml") {
            files.push(name);
        }
    }
    files.sort();
    let mut first = true;
    for name in &files {
        if !first {
            println!();
        }
        first = false;
        let path = Path::new(dir).join(name);
        let data = fs::read(&path).unwrap();
        let le = detect_line_ending(&data);
        let entity = parse_entity(&data, &le);
        println!("== {}", name);
        let from = get_header(&entity, "from");
        let subject = get_header(&entity, "subject");
        match from {
            Some(v) => println!("From: {}", quoted_string(&decode_encoded_words(&v))),
            None => println!("From: -"),
        }
        match subject {
            Some(v) => println!("Subject: {}", quoted_string(&decode_encoded_words(&v))),
            None => println!("Subject: -"),
        }
        let mut out = String::new();
        print_entity(&entity, 0, &mut out);
        print!("{}", out);
    }
}

struct Entity {
    headers: Vec<(String, String)>,
    body: Vec<u8>,
    ct_type: String,
    ct_subtype: String,
    ct_params: Vec<(String, String)>,
    cd_type: Option<String>,
    cd_params: Vec<(String, String)>,
    cte: String,
    parts: Vec<Entity>,
    is_multipart: bool,
}

fn detect_line_ending(data: &[u8]) -> Vec<u8> {
    for i in 0..data.len().saturating_sub(1) {
        if data[i] == b'\r' && data[i + 1] == b'\n' {
            return b"\r\n".to_vec();
        }
    }
    b"\n".to_vec()
}

fn get_header(e: &Entity, name: &str) -> Option<String> {
    e.headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

fn get_param(params: &[(String, String)], name: &str) -> Option<String> {
    params.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

fn parse_entity(data: &[u8], le: &[u8]) -> Entity {
    let lines = split_lines(data, le);
    let empty_idx = lines.iter().position(|&(s, e)| s == e);
    let (hdr_end, body_start) = match empty_idx {
        Some(idx) => {
            let bs = if idx + 1 < lines.len() {
                lines[idx + 1].0
            } else {
                data.len()
            };
            (idx, bs)
        }
        None => (lines.len(), data.len()),
    };
    let hdr_lines = &lines[..hdr_end];
    let headers = unfold_headers(hdr_lines, data);
    let body = data[body_start..].to_vec();

    let ct_str = headers.iter().find(|(k, _)| k == "content-type").map(|(_, v)| v.clone());
    let (ct_type, ct_subtype, ct_params) = match &ct_str {
        Some(s) => parse_content_type(s),
        None => ("text".to_string(), "plain".to_string(), vec![]),
    };

    let cd_str = headers.iter().find(|(k, _)| k == "content-disposition").map(|(_, v)| v.clone());
    let (cd_type, cd_params) = match &cd_str {
        Some(s) => parse_content_disp(s),
        None => (None, vec![]),
    };

    let cte_str = headers.iter().find(|(k, _)| k == "content-transfer-encoding").map(|(_, v)| v.clone());
    let cte = cte_str.unwrap_or_else(|| "7bit".to_string()).to_lowercase();

    let is_multipart = ct_type == "multipart";
    let parts = if is_multipart {
        let boundary = get_param(&ct_params, "boundary").unwrap_or_default();
        parse_multipart_parts(&body, boundary.as_bytes(), le)
    } else {
        vec![]
    };

    Entity {
        headers,
        body,
        ct_type,
        ct_subtype,
        ct_params,
        cd_type,
        cd_params,
        cte,
        parts,
        is_multipart,
    }
}

fn split_lines(data: &[u8], le: &[u8]) -> Vec<(usize, usize)> {
    let mut lines = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i + le.len() <= data.len() {
        if &data[i..i + le.len()] == le {
            lines.push((start, i));
            i += le.len();
            start = i;
        } else {
            i += 1;
        }
    }
    if start < data.len() {
        lines.push((start, data.len()));
    }
    lines
}

fn unfold_headers(hdr_lines: &[(usize, usize)], data: &[u8]) -> Vec<(String, String)> {
    let mut result: Vec<(String, String)> = Vec::new();
    let mut i = 0;
    while i < hdr_lines.len() {
        let (s, e) = hdr_lines[i];
        let mut line = data[s..e].to_vec();
        i += 1;
        while i < hdr_lines.len() {
            let (ns, ne) = hdr_lines[i];
            if ns < data.len() && (data[ns] == b' ' || data[ns] == b'\t') {
                line.extend_from_slice(&data[ns..ne]);
                i += 1;
            } else {
                break;
            }
        }
        let line_str = String::from_utf8_lossy(&line).to_string();
        if let Some(colon_pos) = line_str.find(':') {
            let name = line_str[..colon_pos].trim().to_lowercase();
            let value = line_str[colon_pos + 1..]
                .trim_matches(|c| c == ' ' || c == '\t')
                .to_string();
            result.push((name, value));
        }
    }
    result
}

fn parse_content_type(s: &str) -> (String, String, Vec<(String, String)>) {
    let mut pos = 0;
    let bytes = s.as_bytes();
    skip_ws(bytes, &mut pos);
    let type_str = read_token(bytes, &mut pos).to_lowercase();
    skip_ws(bytes, &mut pos);
    if pos < bytes.len() && bytes[pos] == b'/' {
        pos += 1;
    }
    skip_ws(bytes, &mut pos);
    let subtype = read_token(bytes, &mut pos).to_lowercase();
    let params = parse_params(bytes, &mut pos);
    (type_str, subtype, params)
}

fn parse_content_disp(s: &str) -> (Option<String>, Vec<(String, String)>) {
    let mut pos = 0;
    let bytes = s.as_bytes();
    skip_ws(bytes, &mut pos);
    let dtype = read_token(bytes, &mut pos).to_lowercase();
    let params = parse_params(bytes, &mut pos);
    let dtype = if dtype.is_empty() { None } else { Some(dtype) };
    (dtype, params)
}

fn skip_ws(b: &[u8], pos: &mut usize) {
    while *pos < b.len() && (b[*pos] == b' ' || b[*pos] == b'\t') {
        *pos += 1;
    }
}

fn read_token(b: &[u8], pos: &mut usize) -> String {
    let start = *pos;
    while *pos < b.len() && b[*pos] != b';' && b[*pos] != b' ' && b[*pos] != b'\t' {
        *pos += 1;
    }
    String::from_utf8_lossy(&b[start..*pos]).to_string()
}

fn read_quoted(b: &[u8], pos: &mut usize) -> String {
    *pos += 1; // skip "
    let mut result = Vec::new();
    while *pos < b.len() {
        if b[*pos] == b'\\' && *pos + 1 < b.len() {
            result.push(b[*pos + 1]);
            *pos += 2;
        } else if b[*pos] == b'"' {
            *pos += 1;
            break;
        } else {
            result.push(b[*pos]);
            *pos += 1;
        }
    }
    String::from_utf8_lossy(&result).to_string()
}

fn read_param_value(b: &[u8], pos: &mut usize) -> String {
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b'"' {
        read_quoted(b, pos)
    } else {
        read_token(b, pos)
    }
}

fn parse_params(b: &[u8], pos: &mut usize) -> Vec<(String, String)> {
    let mut params = Vec::new();
    loop {
        skip_ws(b, pos);
        if *pos >= b.len() {
            break;
        }
        if b[*pos] != b';' {
            break;
        }
        *pos += 1;
        skip_ws(b, pos);
        if *pos >= b.len() {
            break;
        }
        let attr = read_param_attr(b, pos).to_lowercase();
        skip_ws(b, pos);
        if *pos < b.len() && b[*pos] == b'=' {
            *pos += 1;
            skip_ws(b, pos);
            let val = read_param_value(b, pos);
            params.push((attr, val));
        } else {
            params.push((attr, String::new()));
        }
    }
    params
}

fn read_param_attr(b: &[u8], pos: &mut usize) -> String {
    let start = *pos;
    while *pos < b.len() && b[*pos] != b'=' && b[*pos] != b';' && b[*pos] != b' ' && b[*pos] != b'\t' {
        *pos += 1;
    }
    String::from_utf8_lossy(&b[start..*pos]).to_string()
}

fn parse_multipart_parts(body: &[u8], boundary: &[u8], le: &[u8]) -> Vec<Entity> {
    let lines = split_lines(body, le);
    let mut delim_indices: Vec<usize> = Vec::new();
    for (i, &(s, e)) in lines.iter().enumerate() {
        let line = &body[s..e];
        if is_delimiter(line, boundary) || is_close_delim(line, boundary) {
            delim_indices.push(i);
        }
    }
    if delim_indices.len() < 2 {
        return vec![];
    }
    let mut parts = Vec::new();
    for w in 0..delim_indices.len() - 1 {
        let di1 = delim_indices[w];
        let di2 = delim_indices[w + 1];
        if di1 + 1 >= di2 {
            // no content lines between delimiters
            parts.push(parse_entity(b"", le));
        } else {
            let part_start = lines[di1 + 1].0;
            let part_end = lines[di2 - 1].1;
            let part_data = &body[part_start..part_end];
            parts.push(parse_entity(part_data, le));
        }
    }
    parts
}

fn is_delimiter(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 2 + boundary.len();
    if line.len() < prefix_len {
        return false;
    }
    if &line[0..2] != b"--" {
        return false;
    }
    if &line[2..prefix_len] != boundary {
        return false;
    }
    line[prefix_len..].iter().all(|&c| c == b' ' || c == b'\t')
}

fn is_close_delim(line: &[u8], boundary: &[u8]) -> bool {
    let prefix_len = 4 + boundary.len();
    if line.len() < prefix_len {
        return false;
    }
    if &line[0..2] != b"--" {
        return false;
    }
    if &line[2..2 + boundary.len()] != boundary {
        return false;
    }
    if &line[2 + boundary.len()..prefix_len] != b"--" {
        return false;
    }
    line[prefix_len..].iter().all(|&c| c == b' ' || c == b'\t')
}

fn print_entity(e: &Entity, indent: usize, out: &mut String) {
    let prefix = " ".repeat(indent * 2);
    if e.is_multipart {
        out.push_str(&format!(
            "{}multipart/{} parts={}\n",
            prefix, e.ct_subtype, e.parts.len()
        ));
        for p in &e.parts {
            print_entity(p, indent + 1, out);
        }
    } else if is_text_part(e) {
        let charset = get_param(&e.ct_params, "charset")
            .unwrap_or_else(|| "us-ascii".to_string())
            .to_lowercase();
        let decoded_bytes = decode_cte(&e.body, &e.cte, b"\r\n");
        let mut text = decode_charset(&decoded_bytes, &charset);
        text = text.replace("\r\n", "\n").replace('\r', "\n");
        let chars = text.chars().count();
        out.push_str(&format!(
            "{}text/{} charset={} cte={} chars={}\n",
            prefix, e.ct_subtype, charset, e.cte, chars
        ));
        out.push_str(&format!("{}  {}\n", prefix, quoted_string(&text)));
    } else {
        let decoded_bytes = decode_cte(&e.body, &e.cte, b"\r\n");
        let size = decoded_bytes.len();
        let crc = crc32(&decoded_bytes);
        let disp = e.cd_type.as_deref().unwrap_or("-");
        let name = get_filename(e);
        let name_str = match &name {
            Some(n) => quoted_string(n),
            None => "-".to_string(),
        };
        out.push_str(&format!(
            "{}{}/{} cte={} disposition={} name={} size={} crc32={:08x}\n",
            prefix, e.ct_type, e.ct_subtype, e.cte, disp, name_str, size, crc
        ));
    }
}

fn is_text_part(e: &Entity) -> bool {
    e.ct_type == "text" && e.cd_type.as_deref() != Some("attachment")
}

fn decode_cte(data: &[u8], encoding: &str, le: &[u8]) -> Vec<u8> {
    match encoding {
        "base64" => decode_base64(data),
        "quoted-printable" => decode_quoted_printable(data, le),
        _ => data.to_vec(),
    }
}

fn decode_base64(data: &[u8]) -> Vec<u8> {
    let mut filtered: Vec<u8> = Vec::new();
    for &b in data {
        if b == b'=' {
            break;
        }
        if b.is_ascii_alphanumeric() || b == b'+' || b == b'/' {
            filtered.push(b);
        }
    }
    let mut result = Vec::new();
    let mut i = 0;
    while i + 3 < filtered.len() {
        let n = (b64val(filtered[i]) as u32) << 18
            | (b64val(filtered[i + 1]) as u32) << 12
            | (b64val(filtered[i + 2]) as u32) << 6
            | (b64val(filtered[i + 3]) as u32);
        result.push((n >> 16) as u8);
        result.push((n >> 8) as u8);
        result.push(n as u8);
        i += 4;
    }
    let rem = filtered.len() - i;
    if rem == 2 {
        let n = (b64val(filtered[i]) as u32) << 18 | (b64val(filtered[i + 1]) as u32) << 12;
        result.push((n >> 16) as u8);
    } else if rem == 3 {
        let n = (b64val(filtered[i]) as u32) << 18
            | (b64val(filtered[i + 1]) as u32) << 12
            | (b64val(filtered[i + 2]) as u32) << 6;
        result.push((n >> 16) as u8);
        result.push((n >> 8) as u8);
    }
    result
}

fn b64val(b: u8) -> u8 {
    match b {
        b'A'..=b'Z' => b - b'A',
        b'a'..=b'z' => b - b'a' + 26,
        b'0'..=b'9' => b - b'0' + 52,
        b'+' => 62,
        b'/' => 63,
        _ => 0,
    }
}

fn decode_quoted_printable(data: &[u8], le: &[u8]) -> Vec<u8> {
    if data.is_empty() {
        return vec![];
    }
    let ends_with_le = data.len() >= le.len() && &data[data.len() - le.len()..] == le;
    let lines = split_lines(data, le);
    // Remove trailing spaces/tabs from each line
    let mut processed: Vec<Vec<u8>> = Vec::new();
    for &(s, e) in &lines {
        let mut line = data[s..e].to_vec();
        while !line.is_empty() && (line[line.len() - 1] == b' ' || line[line.len() - 1] == b'\t') {
            line.pop();
        }
        processed.push(line);
    }
    // Handle soft line breaks
    let mut logical_lines: Vec<Vec<u8>> = Vec::new();
    let mut i = 0;
    while i < processed.len() {
        let mut current = processed[i].clone();
        while i < processed.len() - 1 && !current.is_empty() && current[current.len() - 1] == b'=' {
            // Check if this would split an =XY sequence:
            // if next line starts with two hex digits, don't treat as soft break
            let next_line = &processed[i + 1];
            if next_line.len() >= 2 && is_hex(next_line[0]) && is_hex(next_line[1]) {
                break;
            }
            current.pop(); // remove the =
            i += 1;
            current.extend_from_slice(&processed[i]);
        }
        logical_lines.push(current);
        i += 1;
    }
    // Decode =XY in each logical line
    let mut result: Vec<u8> = Vec::new();
    for (idx, line) in logical_lines.iter().enumerate() {
        let mut j = 0;
        while j < line.len() {
            if line[j] == b'=' && j + 2 < line.len() && is_hex(line[j + 1]) && is_hex(line[j + 2]) {
                result.push(hex_val(line[j + 1]) * 16 + hex_val(line[j + 2]));
                j += 3;
            } else {
                result.push(line[j]);
                j += 1;
            }
        }
        if idx < logical_lines.len() - 1 {
            result.extend_from_slice(le);
        }
    }
    if ends_with_le && !logical_lines.is_empty() {
        result.extend_from_slice(le);
    }
    result
}

fn is_hex(b: u8) -> bool {
    b.is_ascii_digit() || (b >= b'a' && b <= b'f') || (b >= b'A' && b <= b'F')
}

fn hex_val(b: u8) -> u8 {
    if b >= b'0' && b <= b'9' {
        b - b'0'
    } else if b >= b'a' && b <= b'f' {
        b - b'a' + 10
    } else {
        b - b'A' + 10
    }
}

fn decode_charset(data: &[u8], charset: &str) -> String {
    match charset {
        "utf-8" | "us-ascii" => String::from_utf8_lossy(data).to_string(),
        "iso-8859-1" => data.iter().map(|&b| char::from_u32(b as u32).unwrap()).collect(),
        "windows-1252" => {
            data.iter()
                .map(|&b| {
                    if b >= 0x80 && b <= 0x9F {
                        let cp = WINDOWS_1252[(b - 0x80) as usize];
                        char::from_u32(cp).unwrap_or('\u{FFFD}')
                    } else {
                        char::from_u32(b as u32).unwrap()
                    }
                })
                .collect()
        }
        _ => String::from_utf8_lossy(data).to_string(),
    }
}

static WINDOWS_1252: [u32; 32] = [
    0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160,
    0x2039, 0x0152, 0x008D, 0x017D, 0x008F, 0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022,
    0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
];

fn decode_encoded_words(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut result = String::new();
    let mut pos = 0;
    while pos < bytes.len() {
        if let Some((ms, me, charset, encoding, etext)) = find_encoded_word(bytes, pos) {
            // Add any text before this encoded word
            if ms > pos {
                result.push_str(&String::from_utf8_lossy(&bytes[pos..ms]));
            }
            let base_cs = normalize_charset_name(&charset);
            let mut all_bytes: Vec<u8> = decode_word_bytes(encoding, &etext);
            let mut next_pos = me;
            // Try to extend the run
            loop {
                let mut skip = next_pos;
                while skip < bytes.len() && (bytes[skip] == b' ' || bytes[skip] == b'\t') {
                    skip += 1;
                }
                if skip >= bytes.len() {
                    break;
                }
                if let Some((ms2, me2, cs2, enc2, et2)) = find_encoded_word(bytes, skip) {
                    if ms2 == skip && normalize_charset_name(&cs2) == base_cs {
                        all_bytes.extend(decode_word_bytes(enc2, &et2));
                        next_pos = me2;
                    } else {
                        break;
                    }
                } else {
                    break;
                }
            }
            let decoded = decode_charset(&all_bytes, &base_cs);
            result.push_str(&decoded);
            pos = next_pos;
        } else {
            // No encoded word found from pos onwards; add rest as-is
            result.push_str(&String::from_utf8_lossy(&bytes[pos..]));
            break;
        }
    }
    result
}

fn normalize_charset_name(cs: &str) -> String {
    let lower = cs.to_lowercase();
    if let Some(idx) = lower.find('*') {
        lower[..idx].to_string()
    } else {
        lower
    }
}

fn find_encoded_word(b: &[u8], start: usize) -> Option<(usize, usize, String, u8, String)> {
    let mut i = start;
    while i + 1 < b.len() {
        if b[i] == b'=' && b[i + 1] == b'?' {
            let ms = i;
            i += 2;
            let cs_start = i;
            while i < b.len() && b[i] != b'?' && b[i] != b' ' && b[i] != b'\t' {
                i += 1;
            }
            if i == cs_start || i >= b.len() || b[i] != b'?' {
                i = ms + 1;
                continue;
            }
            let charset = String::from_utf8_lossy(&b[cs_start..i]).to_string();
            i += 1;
            if i >= b.len() {
                i = ms + 1;
                continue;
            }
            let enc = b[i];
            if enc != b'B' && enc != b'b' && enc != b'Q' && enc != b'q' {
                i = ms + 1;
                continue;
            }
            i += 1;
            if i >= b.len() || b[i] != b'?' {
                i = ms + 1;
                continue;
            }
            i += 1;
            let et_start = i;
            while i < b.len() && b[i] != b'?' && b[i] != b' ' && b[i] != b'\t' {
                i += 1;
            }
            let etext = String::from_utf8_lossy(&b[et_start..i]).to_string();
            if i + 1 >= b.len() || b[i] != b'?' || b[i + 1] != b'=' {
                i = ms + 1;
                continue;
            }
            i += 2;
            return Some((ms, i, charset, enc, etext));
        }
        i += 1;
    }
    None
}

fn decode_word_bytes(encoding: u8, etext: &str) -> Vec<u8> {
    if encoding == b'B' || encoding == b'b' {
        decode_base64(etext.as_bytes())
    } else {
        let b = etext.as_bytes();
        let mut result = Vec::new();
        let mut i = 0;
        while i < b.len() {
            if b[i] == b'_' {
                result.push(0x20);
                i += 1;
            } else if b[i] == b'=' && i + 2 < b.len() && is_hex(b[i + 1]) && is_hex(b[i + 2]) {
                result.push(hex_val(b[i + 1]) * 16 + hex_val(b[i + 2]));
                i += 3;
            } else {
                result.push(b[i]);
                i += 1;
            }
        }
        result
    }
}

fn get_filename(e: &Entity) -> Option<String> {
    if let Some(v) = try_rfc2231(&e.cd_params, "filename") {
        return Some(v);
    }
    if let Some(v) = get_param(&e.cd_params, "filename") {
        return Some(decode_encoded_words(&v));
    }
    if let Some(v) = try_rfc2231(&e.ct_params, "name") {
        return Some(v);
    }
    if let Some(v) = get_param(&e.ct_params, "name") {
        return Some(decode_encoded_words(&v));
    }
    None
}

fn try_rfc2231(params: &[(String, String)], attr: &str) -> Option<String> {
    // Check single form: attr*
    let single_name = format!("{}*", attr);
    if let Some(val) = get_param(params, &single_name) {
        return decode_rfc2231_single(&val);
    }
    // Check continuation: attr*0, attr*1, ..., attr*0*, attr*1*, ...
    let prefix = format!("{}*", attr);
    let mut segments: Vec<(u32, bool, String)> = Vec::new();
    for (name, val) in params {
        if name.starts_with(&prefix) && name.len() > prefix.len() {
            let rest = &name[prefix.len()..];
            if rest.is_empty() {
                continue;
            }
            let (idx_str, pct) = if rest.ends_with('*') {
                (&rest[..rest.len() - 1], true)
            } else {
                (rest, false)
            };
            if let Ok(idx) = idx_str.parse::<u32>() {
                segments.push((idx, pct, val.clone()));
            }
        }
    }
    if segments.is_empty() {
        return None;
    }
    segments.sort_by_key(|(i, _, _)| *i);
    let has_pct = segments.iter().any(|(_, p, _)| *p);
    if has_pct && !segments[0].1 {
        return None;
    }
    let mut charset = "us-ascii".to_string();
    let mut all_bytes: Vec<u8> = Vec::new();
    let mut first_pct = true;
    for (_, pct, val) in &segments {
        let v = val.as_bytes().to_vec();
        if *pct {
            let mut v = v;
            if first_pct {
                if let Some(q1) = v.iter().position(|&c| c == b'\'') {
                    charset = String::from_utf8_lossy(&v[..q1]).to_lowercase();
                    if let Some(q2) = v[q1 + 1..].iter().position(|&c| c == b'\'') {
                        v = v[q1 + 1 + q2 + 1..].to_vec();
                    } else {
                        v = v[q1 + 1..].to_vec();
                    }
                }
                first_pct = false;
            }
            let mut decoded = Vec::new();
            let mut i = 0;
            while i < v.len() {
                if v[i] == b'%' && i + 2 < v.len() && is_hex(v[i + 1]) && is_hex(v[i + 2]) {
                    decoded.push(hex_val(v[i + 1]) * 16 + hex_val(v[i + 2]));
                    i += 3;
                } else {
                    decoded.push(v[i]);
                    i += 1;
                }
            }
            all_bytes.extend(decoded);
        } else {
            all_bytes.extend(v);
        }
    }
    Some(decode_charset(&all_bytes, &charset))
}

fn decode_rfc2231_single(val: &str) -> Option<String> {
    let b = val.as_bytes();
    let q1 = b.iter().position(|&c| c == b'\'')?;
    let charset = String::from_utf8_lossy(&b[..q1]).to_lowercase();
    let rest_start = q1 + 1;
    let rest = if rest_start < b.len() {
        match b[rest_start..].iter().position(|&c| c == b'\'') {
            Some(q2) => &b[rest_start + q2 + 1..],
            None => &b[rest_start..],
        }
    } else {
        &b[rest_start..]
    };
    let mut decoded = Vec::new();
    let mut i = 0;
    while i < rest.len() {
        if rest[i] == b'%' && i + 2 < rest.len() && is_hex(rest[i + 1]) && is_hex(rest[i + 2]) {
            decoded.push(hex_val(rest[i + 1]) * 16 + hex_val(rest[i + 2]));
            i += 3;
        } else {
            decoded.push(rest[i]);
            i += 1;
        }
    }
    Some(decode_charset(&decoded, &charset))
}

fn quoted_string(s: &str) -> String {
    let mut result = String::from("\"");
    for ch in s.chars() {
        match ch {
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 || ((c as u32) >= 0x7F && (c as u32) <= 0x9F) => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i as usize] = c;
    }
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc = table[((crc ^ (b as u32)) & 0xFF) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFFFFFF
}

import sys
import os
import zlib
import re


def split_lines(content):
    if not content:
        return []
    parts = content.split(b'\n')
    lines = []
    for i, part in enumerate(parts):
        if i < len(parts) - 1:
            lines.append(part + b'\n')
        else:
            if part:
                lines.append(part)
    return lines


def join_lines(lines):
    return b''.join(lines)


def parse_diff(diff_data):
    diff_lines = diff_data.split(b'\n')
    if diff_lines and diff_lines[-1] == b'':
        diff_lines.pop()

    sections = []
    i = 0
    n = len(diff_lines)

    while i < n:
        if diff_lines[i].startswith(b'diff --git '):
            section, i = parse_section(diff_lines, i, n)
            sections.append(section)
        else:
            i += 1

    return sections


def parse_section(diff_lines, i, n):
    line = diff_lines[i]
    parts = line.split(b' ')
    path = parts[2][2:]

    kind = 'modify'
    i += 1

    while i < n:
        line = diff_lines[i]
        if line.startswith(b'diff --git ') or line.startswith(b'@@ '):
            break
        if line.startswith(b'new file mode '):
            kind = 'create'
            i += 1
        elif line.startswith(b'deleted file mode '):
            kind = 'delete'
            i += 1
        elif line.startswith(b'index '):
            i += 1
        elif line.startswith(b'--- '):
            i += 1
        elif line.startswith(b'+++ '):
            i += 1
        else:
            i += 1

    hunks = []
    while i < n and diff_lines[i].startswith(b'@@ '):
        hunk, i = parse_hunk(diff_lines, i, n)
        hunks.append(hunk)

    return (path, kind, hunks), i


def parse_hunk(diff_lines, i, n):
    header = diff_lines[i]
    m = re.match(rb'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', header)
    a = int(m.group(1))
    b = int(m.group(2)) if m.group(2) is not None else 1
    c = int(m.group(3))
    d = int(m.group(4)) if m.group(4) is not None else 1

    i += 1

    old_lines = []
    new_lines = []
    last_marker = None

    while i < n:
        line = diff_lines[i]
        if line.startswith(b'@@ ') or line.startswith(b'diff --git '):
            break

        if len(line) == 0:
            i += 1
            continue

        marker = line[0:1]
        content = line[1:]

        if marker == b'\\':
            if last_marker == b' ':
                if old_lines:
                    old_lines[-1] = old_lines[-1][:-1]
                if new_lines:
                    new_lines[-1] = new_lines[-1][:-1]
            elif last_marker == b'-':
                if old_lines:
                    old_lines[-1] = old_lines[-1][:-1]
            elif last_marker == b'+':
                if new_lines:
                    new_lines[-1] = new_lines[-1][:-1]
            i += 1
        elif marker == b' ':
            old_lines.append(content + b'\n')
            new_lines.append(content + b'\n')
            last_marker = b' '
            i += 1
        elif marker == b'-':
            old_lines.append(content + b'\n')
            last_marker = b'-'
            i += 1
        elif marker == b'+':
            new_lines.append(content + b'\n')
            last_marker = b'+'
            i += 1
        else:
            i += 1

    return (a, b, c, d, old_lines, new_lines), i


def process_section(path, kind, hunks, tree_path):
    full_path = os.path.join(tree_path, path.decode('utf-8', errors='surrogateescape'))

    if kind == 'create':
        if os.path.isfile(full_path):
            return (path, kind, [], 'error: already exists')
        content_lines = []
    else:
        if not os.path.isfile(full_path):
            return (path, kind, [], 'error: not found')
        with open(full_path, 'rb') as f:
            content = f.read()
        content_lines = split_lines(content)

    delta = 0
    hunk_results = []
    all_applied = True

    for idx, hunk in enumerate(hunks, 1):
        a, b, c, d, old_lines, new_lines = hunk

        if len(old_lines) != b or len(new_lines) != d:
            hunk_results.append(f"hunk {idx}: malformed")
            all_applied = False
            continue

        P = a + delta

        if b == 0:
            if 0 <= P <= len(content_lines):
                content_lines = content_lines[:P] + new_lines + content_lines[P:]
                delta += d - b
                hunk_results.append(f"hunk {idx}: applied at {P} (offset 0)")
            else:
                hunk_results.append(f"hunk {idx}: rejected")
                all_applied = False
        else:
            n_lines = len(content_lines)
            found = False
            best_p = None
            offset = 0

            while True:
                candidates = []
                if offset == 0:
                    candidates = [P]
                else:
                    candidates = [P - offset, P + offset]

                for p in candidates:
                    if p < 1 or p + b - 1 > n_lines:
                        continue
                    if content_lines[p - 1:p - 1 + b] == old_lines:
                        best_p = p
                        found = True
                        break

                if found:
                    break

                if P - (offset + 1) < 1 and P + (offset + 1) > n_lines - b + 1:
                    break

                offset += 1

            if found:
                content_lines = content_lines[:best_p - 1] + new_lines + content_lines[best_p - 1 + b:]
                delta += d - b
                off = best_p - P
                if off > 0:
                    off_str = f"+{off}"
                elif off < 0:
                    off_str = str(off)
                else:
                    off_str = "0"
                hunk_results.append(f"hunk {idx}: applied at {best_p} (offset {off_str})")
            else:
                hunk_results.append(f"hunk {idx}: rejected")
                all_applied = False

    if kind == 'delete':
        if all_applied and len(content_lines) == 0:
            return (path, kind, hunk_results, 'result: deleted')

    content = join_lines(content_lines)
    n = len(content_lines)
    crc = zlib.crc32(content) & 0xFFFFFFFF
    return (path, kind, hunk_results, f"result: {n} lines, crc32 {crc:08x}")


def main():
    if len(sys.argv) < 2:
        sys.exit(0)

    arg_dir = sys.argv[1]
    diff_path = os.path.join(arg_dir, 'changes.diff')
    tree_path = os.path.join(arg_dir, 'tree')

    with open(diff_path, 'rb') as f:
        diff_data = f.read()

    sections = parse_diff(diff_data)

    results = []
    for path, kind, hunks in sections:
        result = process_section(path, kind, hunks, tree_path)
        results.append(result)

    results.sort(key=lambda x: x[0])

    output_lines = []
    for path, kind, hunk_results, result_line in results:
        path_str = path.decode('utf-8', errors='surrogateescape')
        output_lines.append(f"{path_str}: {kind}")
        for hr in hunk_results:
            output_lines.append(f"  {hr}")
        output_lines.append(f"  {result_line}")

    if output_lines:
        sys.stdout.write('\n'.join(output_lines) + '\n')

    sys.exit(0)


if __name__ == '__main__':
    main()

import * as fs from 'fs';
import * as path from 'path';

// ============ TYPES ============

type TernValue = bigint | boolean | string | TernList | TernFunction | null;
interface TernList { _t: 'list'; elements: TernValue[]; }
interface TernFunction { _t: 'function'; params: string[]; body: Stmt[]; scope: Scope; name?: string; }
interface Scope { vars: Map<string, TernValue>; parent: Scope | null; }

type Stmt =
  | { kind: 'let'; name: string; expr: Expr; line: number }
  | { kind: 'fnDecl'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'if'; cond: Expr; thenBody: Stmt[]; elseBody: Stmt[] | null; elseIf: Stmt | null; line: number }
  | { kind: 'while'; cond: Expr; body: Stmt[]; line: number }
  | { kind: 'for'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'return'; expr: Expr | null; line: number }
  | { kind: 'break'; line: number }
  | { kind: 'continue'; line: number }
  | { kind: 'assign'; name: string; expr: Expr; line: number }
  | { kind: 'indexAssign'; obj: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'exprStmt'; expr: Expr; line: number };

type Expr =
  | { kind: 'int'; value: bigint; line: number }
  | { kind: 'str'; value: string; line: number }
  | { kind: 'bool'; value: boolean; line: number }
  | { kind: 'nil'; line: number }
  | { kind: 'ident'; name: string; line: number }
  | { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'unary'; op: string; operand: Expr; line: number }
  | { kind: 'call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'index'; obj: Expr; index: Expr; line: number }
  | { kind: 'listLit'; elements: Expr[]; line: number }
  | { kind: 'fnExpr'; params: string[]; body: Stmt[]; line: number };

// ============ LEXER ============

enum TT {
  INT, STR, IDENT,
  LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
  AND, OR, NOT, TRUE, FALSE, NIL,
  EQ, NEQ, LE, GE, LT, GT, ASSIGN,
  PLUS, MINUS, STAR, SLASH, PERCENT,
  LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE,
  COMMA, SEMI, EOF
}

interface Token { type: TT; value: string; line: number; }

const KEYWORDS: Record<string, TT> = {
  let: TT.LET, fn: TT.FN, if: TT.IF, else: TT.ELSE,
  while: TT.WHILE, for: TT.FOR, in: TT.IN,
  return: TT.RETURN, break: TT.BREAK, continue: TT.CONTINUE,
  and: TT.AND, or: TT.OR, not: TT.NOT,
  true: TT.TRUE, false: TT.FALSE, nil: TT.NIL,
};

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0, line = 1;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '\n') { line++; i++; continue; }
    if (c === '#') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      let s = i; while (i < n && src[i] >= '0' && src[i] <= '9') i++;
      tokens.push({ type: TT.INT, value: src.slice(s, i), line }); continue;
    }
    if (c === '"') {
      i++; let val = '';
      while (i < n && src[i] !== '"') {
        if (src[i] === '\\') {
          i++;
          if (src[i] === 'n') val += '\n';
          else if (src[i] === 't') val += '\t';
          else if (src[i] === '"') val += '"';
          else if (src[i] === '\\') val += '\\';
          i++;
        } else { val += src[i]; i++; }
      }
      i++; tokens.push({ type: TT.STR, value: val, line }); continue;
    }
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_') {
      let s = i;
      while (i < n && ((src[i] >= 'a' && src[i] <= 'z') || (src[i] >= 'A' && src[i] <= 'Z') || (src[i] >= '0' && src[i] <= '9') || src[i] === '_')) i++;
      const w = src.slice(s, i);
      const kw = KEYWORDS[w];
      tokens.push(kw !== undefined ? { type: kw, value: w, line } : { type: TT.IDENT, value: w, line });
      continue;
    }
    const c2 = i + 1 < n ? src[i + 1] : '';
    if (c === '=' && c2 === '=') { tokens.push({ type: TT.EQ, value: '==', line }); i += 2; continue; }
    if (c === '!' && c2 === '=') { tokens.push({ type: TT.NEQ, value: '!=', line }); i += 2; continue; }
    if (c === '<' && c2 === '=') { tokens.push({ type: TT.LE, value: '<=', line }); i += 2; continue; }
    if (c === '>' && c2 === '=') { tokens.push({ type: TT.GE, value: '>=', line }); i += 2; continue; }
    if (c === '<') { tokens.push({ type: TT.LT, value: '<', line }); i++; continue; }
    if (c === '>') { tokens.push({ type: TT.GT, value: '>', line }); i++; continue; }
    if (c === '=') { tokens.push({ type: TT.ASSIGN, value: '=', line }); i++; continue; }
    if (c === '+') { tokens.push({ type: TT.PLUS, value: '+', line }); i++; continue; }
    if (c === '-') { tokens.push({ type: TT.MINUS, value: '-', line }); i++; continue; }
    if (c === '*') { tokens.push({ type: TT.STAR, value: '*', line }); i++; continue; }
    if (c === '/') { tokens.push({ type: TT.SLASH, value: '/', line }); i++; continue; }
    if (c === '%') { tokens.push({ type: TT.PERCENT, value: '%', line }); i++; continue; }
    if (c === '(') { tokens.push({ type: TT.LPAREN, value: '(', line }); i++; continue; }
    if (c === ')') { tokens.push({ type: TT.RPAREN, value: ')', line }); i++; continue; }
    if (c === '[') { tokens.push({ type: TT.LBRACKET, value: '[', line }); i++; continue; }
    if (c === ']') { tokens.push({ type: TT.RBRACKET, value: ']', line }); i++; continue; }
    if (c === '{') { tokens.push({ type: TT.LBRACE, value: '{', line }); i++; continue; }
    if (c === '}') { tokens.push({ type: TT.RBRACE, value: '}', line }); i++; continue; }
    if (c === ',') { tokens.push({ type: TT.COMMA, value: ',', line }); i++; continue; }
    if (c === ';') { tokens.push({ type: TT.SEMI, value: ';', line }); i++; continue; }
    i++; // shouldn't happen
  }
  tokens.push({ type: TT.EOF, value: '', line });
  return tokens;
}

// ============ PARSER ============

class Parser {
  private tokens: Token[];
  private pos: number = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  private peek(): Token { return this.tokens[this.pos]; }
  private advance(): Token { return this.tokens[this.pos++]; }
  private expect(type: TT): Token {
    const t = this.tokens[this.pos];
    if (t.type !== type) throw new Error(`Expected ${type} got ${t.type} at line ${t.line}`);
    this.pos++; return t;
  }
  private check(type: TT): boolean { return this.tokens[this.pos].type === type; }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (!this.check(TT.EOF)) stmts.push(this.parseStmt());
    return stmts;
  }

  private parseBlock(): Stmt[] {
    this.expect(TT.LBRACE);
    const stmts: Stmt[] = [];
    while (!this.check(TT.RBRACE) && !this.check(TT.EOF)) stmts.push(this.parseStmt());
    this.expect(TT.RBRACE);
    return stmts;
  }

  private parseParams(): string[] {
    const params: string[] = [];
    if (!this.check(TT.RPAREN)) {
      params.push(this.expect(TT.IDENT).value);
      while (this.check(TT.COMMA)) { this.advance(); params.push(this.expect(TT.IDENT).value); }
    }
    return params;
  }

  private parseStmt(): Stmt {
    const t = this.peek();
    switch (t.type) {
      case TT.LET: {
        this.advance();
        const name = this.expect(TT.IDENT).value;
        this.expect(TT.ASSIGN);
        const expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'let', name, expr, line: t.line };
      }
      case TT.FN: {
        this.advance();
        const name = this.expect(TT.IDENT).value;
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fnDecl', name, params, body, line: t.line };
      }
      case TT.IF: return this.parseIf();
      case TT.WHILE: {
        this.advance();
        const cond = this.parseExpr();
        const body = this.parseBlock();
        return { kind: 'while', cond, body, line: t.line };
      }
      case TT.FOR: {
        this.advance();
        const varName = this.expect(TT.IDENT).value;
        this.expect(TT.IN);
        const iterable = this.parseExpr();
        const body = this.parseBlock();
        return { kind: 'for', varName, iterable, body, line: t.line };
      }
      case TT.RETURN: {
        this.advance();
        let expr: Expr | null = null;
        if (!this.check(TT.SEMI)) expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'return', expr, line: t.line };
      }
      case TT.BREAK: { this.advance(); this.expect(TT.SEMI); return { kind: 'break', line: t.line }; }
      case TT.CONTINUE: { this.advance(); this.expect(TT.SEMI); return { kind: 'continue', line: t.line }; }
      case TT.IDENT: {
        // Check for assignment: IDENT = expr ;
        if (this.tokens[this.pos + 1].type === TT.ASSIGN) {
          this.advance();
          const name = this.advance().value;
          this.advance(); // skip =
          const expr = this.parseExpr();
          this.expect(TT.SEMI);
          return { kind: 'assign', name, expr, line: t.line };
        }
        // Otherwise parse as expression, check for index assignment
        const expr = this.parseExpr();
        if (this.check(TT.ASSIGN)) {
          this.advance();
          const value = this.parseExpr();
          this.expect(TT.SEMI);
          if (expr.kind === 'index') {
            return { kind: 'indexAssign', obj: expr.obj, index: expr.index, value, line: t.line };
          }
          // Shouldn't happen for valid programs
          throw new Error('Invalid assignment target');
        }
        this.expect(TT.SEMI);
        return { kind: 'exprStmt', expr, line: t.line };
      }
      default: {
        const expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'exprStmt', expr, line: t.line };
      }
    }
  }

  private parseIf(): Stmt {
    const t = this.advance(); // 'if'
    const cond = this.parseExpr();
    const thenBody = this.parseBlock();
    let elseBody: Stmt[] | null = null;
    let elseIf: Stmt | null = null;
    if (this.check(TT.ELSE)) {
      this.advance();
      if (this.check(TT.IF)) {
        elseIf = this.parseIf();
      } else {
        elseBody = this.parseBlock();
      }
    }
    return { kind: 'if', cond, thenBody, elseBody, elseIf, line: t.line };
  }

  // Expression parsing
  private parseExpr(): Expr { return this.parseOr(); }
  private parseOr(): Expr {
    let left = this.parseAnd();
    while (this.check(TT.OR)) {
      const t = this.advance();
      const right = this.parseAnd();
      left = { kind: 'binary', op: 'or', left, right, line: t.line };
    }
    return left;
  }
  private parseAnd(): Expr {
    let left = this.parseNot();
    while (this.check(TT.AND)) {
      const t = this.advance();
      const right = this.parseNot();
      left = { kind: 'binary', op: 'and', left, right, line: t.line };
    }
    return left;
  }
  private parseNot(): Expr {
    if (this.check(TT.NOT)) {
      const t = this.advance();
      const operand = this.parseNot();
      return { kind: 'unary', op: 'not', operand, line: t.line };
    }
    return this.parseComparison();
  }
  private parseComparison(): Expr {
    let left = this.parseAdd();
    while (this.check(TT.EQ) || this.check(TT.NEQ) || this.check(TT.LT) ||
           this.check(TT.LE) || this.check(TT.GT) || this.check(TT.GE)) {
      const t = this.advance();
      const right = this.parseAdd();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseAdd(): Expr {
    let left = this.parseMul();
    while (this.check(TT.PLUS) || this.check(TT.MINUS)) {
      const t = this.advance();
      const right = this.parseMul();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseMul(): Expr {
    let left = this.parseUnary();
    while (this.check(TT.STAR) || this.check(TT.SLASH) || this.check(TT.PERCENT)) {
      const t = this.advance();
      const right = this.parseUnary();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseUnary(): Expr {
    if (this.check(TT.MINUS)) {
      const t = this.advance();
      const operand = this.parseUnary();
      return { kind: 'unary', op: '-', operand, line: t.line };
    }
    return this.parsePostfix();
  }
  private parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.check(TT.LPAREN)) {
        const t = this.advance();
        const args: Expr[] = [];
        if (!this.check(TT.RPAREN)) {
          args.push(this.parseExpr());
          while (this.check(TT.COMMA)) { this.advance(); args.push(this.parseExpr()); }
        }
        this.expect(TT.RPAREN);
        expr = { kind: 'call', callee: expr, args, line: t.line };
      } else if (this.check(TT.LBRACKET)) {
        const t = this.advance();
        const index = this.parseExpr();
        this.expect(TT.RBRACKET);
        expr = { kind: 'index', obj: expr, index, line: t.line };
      } else break;
    }
    return expr;
  }
  private parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case TT.INT: this.advance(); return { kind: 'int', value: BigInt(t.value), line: t.line };
      case TT.STR: this.advance(); return { kind: 'str', value: t.value, line: t.line };
      case TT.TRUE: this.advance(); return { kind: 'bool', value: true, line: t.line };
      case TT.FALSE: this.advance(); return { kind: 'bool', value: false, line: t.line };
      case TT.NIL: this.advance(); return { kind: 'nil', line: t.line };
      case TT.IDENT: this.advance(); return { kind: 'ident', name: t.value, line: t.line };
      case TT.LPAREN: {
        this.advance();
        const expr = this.parseExpr();
        this.expect(TT.RPAREN);
        return expr;
      }
      case TT.LBRACKET: {
        this.advance();
        const elements: Expr[] = [];
        if (!this.check(TT.RBRACKET)) {
          elements.push(this.parseExpr());
          while (this.check(TT.COMMA)) { this.advance(); elements.push(this.parseExpr()); }
        }
        this.expect(TT.RBRACKET);
        return { kind: 'listLit', elements, line: t.line };
      }
      case TT.FN: {
        this.advance();
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fnExpr', params, body, line: t.line };
      }
      default:
        throw new Error(`Unexpected token ${t.type} at line ${t.line}`);
    }
  }
}

// ============ INTERPRETER ============

const INT_MIN = -(1n << 63n);
const INT_MAX = (1n << 63n) - 1n;

class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { constructor(public value: TernValue) {} }
class TernError { constructor(public line: number, public message: string) {} }

function typeOf(v: TernValue): string {
  if (v === null) return 'nil';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'string') return 'string';
  if (typeof v === 'object' && '_t' in v) {
    if ((v as any)._t === 'list') return 'list';
    if ((v as any)._t === 'function') return 'function';
  }
  return 'unknown';
}

function isTruthy(v: TernValue): boolean {
  if (v === null || v === false) return false;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'string') return v.length > 0;
  if (typeof v === 'object' && '_t' in v && (v as any)._t === 'list') return (v as TernList).elements.length > 0;
  return true; // functions are truthy
}

function checkInt(v: bigint, line: number): void {
  if (v < INT_MIN || v > INT_MAX) throw new TernError(line, 'integer overflow');
}

function displayValue(v: TernValue, inList: boolean, seen: Set<TernList>): string {
  if (v === null) return 'nil';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'string') {
    if (!inList) return v;
    let s = '"';
    for (const ch of v) {
      if (ch === '\\') s += '\\\\';
      else if (ch === '"') s += '\\"';
      else if (ch === '\n') s += '\\n';
      else if (ch === '\t') s += '\\t';
      else s += ch;
    }
    return s + '"';
  }
  if (typeof v === 'object' && '_t' in v) {
    if ((v as any)._t === 'function') return '<fn>';
    if ((v as any)._t === 'list') {
      const list = v as TernList;
      if (seen.has(list)) return '[...]';
      seen.add(list);
      const parts: string[] = [];
      for (const el of list.elements) {
        parts.push(displayValue(el, true, seen));
      }
      seen.delete(list);
      return '[' + parts.join(', ') + ']';
    }
  }
  return '???';
}

class Interpreter {
  private globalScope: Scope;
  private output: string = '';

  constructor() {
    const builtinScope: Scope = { vars: new Map(), parent: null };
    this.globalScope = { vars: new Map(), parent: builtinScope };
    this.registerBuiltins(builtinScope);
  }

  private registerBuiltins(scope: Scope): void {
    const mk = (name: string, arity: number | -1, fn: (args: TernValue[], line: number) => TernValue): void => {
      const f: TernFunction = { _t: 'function', params: [], body: [], scope, name };
      (f as any).__builtin = { arity, fn, name };
      scope.vars.set(name, f);
    };

    mk('print', -1, (args, line) => {
      const parts: string[] = [];
      for (const a of args) parts.push(displayValue(a, false, new Set()));
      this.output += parts.join(' ') + '\n';
      return null;
    });
    mk('str', 1, (args, line) => {
      return displayValue(args[0], false, new Set());
    });
    mk('type', 1, (args, line) => {
      return typeOf(args[0]);
    });
    mk('len', 1, (args, line) => {
      const v = args[0];
      if (typeof v === 'string') return BigInt(v.length);
      if (typeof v === 'object' && '_t' in v && (v as any)._t === 'list') return BigInt((v as TernList).elements.length);
      throw new TernError(line, 'bad argument to len');
    });
    mk('push', 2, (args, line) => {
      const list = args[0];
      if (typeof list !== 'object' || !('_t' in list) || (list as any)._t !== 'list')
        throw new TernError(line, 'bad argument to push');
      (list as TernList).elements.push(args[1]);
      return null;
    });
    mk('pop', 1, (args, line) => {
      const list = args[0];
      if (typeof list !== 'object' || !('_t' in list) || (list as any)._t !== 'list')
        throw new TernError(line, 'bad argument to pop');
      const el = (list as TernList).elements;
      if (el.length === 0) throw new TernError(line, 'bad argument to pop');
      return el.pop()!;
    });
    mk('range', 2, (args, line) => {
      if (typeof args[0] !== 'bigint' || typeof args[1] !== 'bigint')
        throw new TernError(line, 'bad argument to range');
      const a = args[0] as bigint, b = args[1] as bigint;
      const elems: TernValue[] = [];
      for (let i = a; i < b; i++) elems.push(i);
      return { _t: 'list', elements: elems };
    });
    mk('slice', 3, (args, line) => {
      const x = args[0], a = args[1], b = args[2];
      if (typeof a !== 'bigint' || typeof b !== 'bigint')
        throw new TernError(line, 'bad argument to slice');
      const ai = a as bigint, bi = b as bigint;
      if (typeof x === 'string') {
        const len = BigInt(x.length);
        if (ai < 0n || bi > len || ai > bi) throw new TernError(line, 'bad argument to slice');
        return x.slice(Number(ai), Number(bi));
      }
      if (typeof x === 'object' && '_t' in x && (x as any)._t === 'list') {
        const elems = (x as TernList).elements;
        const len = BigInt(elems.length);
        if (ai < 0n || bi > len || ai > bi) throw new TernError(line, 'bad argument to slice');
        return { _t: 'list', elements: elems.slice(Number(ai), Number(bi)) };
      }
      throw new TernError(line, 'bad argument to slice');
    });
  }

  private lookup(scope: Scope, name: string, line: number): TernValue {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) return s.vars.get(name)!;
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  private assign(scope: Scope, name: string, value: TernValue, line: number): void {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) { s.vars.set(name, value); return; }
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  run(stmts: Stmt[]): void {
    try {
      this.execBlock(stmts, this.globalScope);
    } catch (e) {
      if (e instanceof TernError) {
        process.stdout.write(this.output);
        process.stdout.write(`error at line ${e.line}: ${e.message}\n`);
        process.exit(0);
      }
      throw e;
    }
  }

  private execBlock(stmts: Stmt[], scope: Scope): void {
    for (const s of stmts) this.execStmt(s, scope);
  }

  private execStmt(s: Stmt, scope: Scope): void {
    switch (s.kind) {
      case 'let': {
        const val = this.eval(s.expr, scope);
        scope.vars.set(s.name, val);
        break;
      }
      case 'fnDecl': {
        const fn: TernFunction = { _t: 'function', params: s.params, body: s.body, scope, name: s.name };
        scope.vars.set(s.name, fn);
        break;
      }
      case 'if': {
        const cond = this.eval(s.cond, scope);
        if (isTruthy(cond)) {
          this.execBlock(s.thenBody, { vars: new Map(), parent: scope });
        } else if (s.elseIf) {
          this.execStmt(s.elseIf, scope);
        } else if (s.elseBody) {
          this.execBlock(s.elseBody, { vars: new Map(), parent: scope });
        }
        break;
      }
      case 'while': {
        while (true) {
          const cond = this.eval(s.cond, scope);
          if (!isTruthy(cond)) break;
          const bodyScope: Scope = { vars: new Map(), parent: scope };
          try {
            this.execBlock(s.body, bodyScope);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) continue;
            throw e;
          }
        }
        break;
      }
      case 'for': {
        const listVal = this.eval(s.iterable, scope);
        if (typeof listVal !== 'object' || !('_t' in listVal) || (listVal as any)._t !== 'list')
          throw new TernError(s.line, `cannot iterate ${typeOf(listVal)}`);
        const list = listVal as TernList;
        let i = 0;
        while (i < list.elements.length) {
          const bodyScope: Scope = { vars: new Map(), parent: scope };
          bodyScope.vars.set(s.varName, list.elements[i]);
          try {
            this.execBlock(s.body, bodyScope);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { i++; continue; }
            throw e;
          }
          i++;
        }
        break;
      }
      case 'return': {
        const val = s.expr ? this.eval(s.expr, scope) : null;
        throw new ReturnSignal(val);
      }
      case 'break': throw new BreakSignal();
      case 'continue': throw new ContinueSignal();
      case 'assign': {
        const val = this.eval(s.expr, scope);
        this.assign(scope, s.name, val, s.line);
        break;
      }
      case 'indexAssign': {
        const obj = this.eval(s.obj, scope);
        const idx = this.eval(s.index, scope);
        const val = this.eval(s.value, scope);
        if (typeof obj !== 'object' || !('_t' in obj) || (obj as any)._t !== 'list')
          throw new TernError(s.line, `cannot assign into ${typeOf(obj)}`);
        if (typeof idx !== 'bigint')
          throw new TernError(s.line, `cannot index list with ${typeOf(idx)}`);
        const list = obj as TernList;
        const i = Number(idx);
        if (i < 0 || i >= list.elements.length)
          throw new TernError(s.line, `index ${idx} out of range for length ${list.elements.length}`);
        list.elements[i] = val;
        break;
      }
      case 'exprStmt': {
        this.eval(s.expr, scope);
        break;
      }
    }
  }

  private eval(e: Expr, scope: Scope): TernValue {
    switch (e.kind) {
      case 'int': return e.value;
      case 'str': return e.value;
      case 'bool': return e.value;
      case 'nil': return null;
      case 'ident': return this.lookup(scope, e.name, e.line);
      case 'listLit': {
        const elems: TernValue[] = [];
        for (const el of e.elements) elems.push(this.eval(el, scope));
        return { _t: 'list', elements: elems };
      }
      case 'fnExpr': {
        return { _t: 'function', params: e.params, body: e.body, scope };
      }
      case 'unary': {
        if (e.op === 'not') {
          const v = this.eval(e.operand, scope);
          return !isTruthy(v);
        }
        if (e.op === '-') {
          const v = this.eval(e.operand, scope);
          if (typeof v !== 'bigint')
            throw new TernError(e.line, `cannot apply - to ${typeOf(v)}`);
          const result = -v;
          checkInt(result, e.line);
          return result;
        }
        throw new Error('unknown unary op');
      }
      case 'binary': return this.evalBinary(e, scope);
      case 'call': return this.evalCall(e, scope);
      case 'index': return this.evalIndex(e, scope);
    }
  }

  private evalBinary(e: Expr & { kind: 'binary' }, scope: Scope): TernValue {
    const op = e.op;
    // Short-circuit
    if (op === 'and') {
      const l = this.eval(e.left, scope);
      if (!isTruthy(l)) return l;
      return this.eval(e.right, scope);
    }
    if (op === 'or') {
      const l = this.eval(e.left, scope);
      if (isTruthy(l)) return l;
      return this.eval(e.right, scope);
    }

    const l = this.eval(e.left, scope);
    const r = this.eval(e.right, scope);

    if (op === '==' || op === '!=') {
      const eq = this.valuesEqual(l, r);
      return op === '==' ? eq : !eq;
    }

    if (op === '+' ) {
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        const res = l + r;
        checkInt(res, e.line);
        return res;
      }
      if (typeof l === 'string' && typeof r === 'string') return l + r;
      if (typeof l === 'object' && '_t' in l && (l as any)._t === 'list' &&
          typeof r === 'object' && '_t' in r && (r as any)._t === 'list') {
        return { _t: 'list', elements: [...(l as TernList).elements, ...(r as TernList).elements] };
      }
      throw new TernError(e.line, `cannot apply + to ${typeOf(l)} and ${typeOf(r)}`);
    }

    if (op === '-' || op === '*' || op === '/' || op === '%') {
      if (typeof l !== 'bigint' || typeof r !== 'bigint')
        throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      if (op === '/') {
        if (r === 0n) throw new TernError(e.line, 'division by zero');
        const res = l / r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '%') {
        if (r === 0n) throw new TernError(e.line, 'division by zero');
        const res = l - (l / r) * r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '-') {
        const res = l - r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '*') {
        const res = l * r;
        checkInt(res, e.line);
        return res;
      }
    }

    if (op === '<' || op === '<=' || op === '>' || op === '>=') {
      let cmp: number;
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        cmp = l < r ? -1 : l > r ? 1 : 0;
      } else if (typeof l === 'string' && typeof r === 'string') {
        cmp = l < r ? -1 : l > r ? 1 : 0;
      } else {
        throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      }
      if (op === '<') return cmp < 0;
      if (op === '<=') return cmp <= 0;
      if (op === '>') return cmp > 0;
      return cmp >= 0;
    }

    throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
  }

  private valuesEqual(a: TernValue, b: TernValue): boolean {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
    if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
    if (typeof a === 'string' && typeof b === 'string') return a === b;
    if (typeof a === 'object' && '_t' in a && (a as any)._t === 'list' &&
        typeof b === 'object' && '_t' in b && (b as any)._t === 'list') {
      const la = (a as TernList).elements, lb = (b as TernList).elements;
      if (la.length !== lb.length) return false;
      for (let i = 0; i < la.length; i++) {
        if (!this.valuesEqual(la[i], lb[i])) return false;
      }
      return true;
    }
    if (typeof a === 'object' && '_t' in a && (a as any)._t === 'function' &&
        typeof b === 'object' && '_t' in b && (b as any)._t === 'function') {
      return a === b;
    }
    return false;
  }

  private evalCall(e: Expr & { kind: 'call' }, scope: Scope): TernValue {
    const callee = this.eval(e.callee, scope);
    const args: TernValue[] = [];
    for (const a of e.args) args.push(this.eval(a, scope));

    if (typeof callee !== 'object' || !('_t' in callee) || (callee as any)._t !== 'function')
      throw new TernError(e.line, `cannot call ${typeOf(callee)}`);

    const fn = callee as TernFunction;
    const builtin = (fn as any).__builtin;
    if (builtin) {
      if (builtin.arity !== -1 && args.length !== builtin.arity)
        throw new TernError(e.line, `expected ${builtin.arity} arguments, got ${args.length}`);
      return builtin.fn(args, e.line);
    }

    if (args.length !== fn.params.length)
      throw new TernError(e.line, `expected ${fn.params.length} arguments, got ${args.length}`);

    const callScope: Scope = { vars: new Map(), parent: fn.scope };
    for (let i = 0; i < fn.params.length; i++) {
      callScope.vars.set(fn.params[i], args[i]);
    }
    try {
      this.execBlock(fn.body, callScope);
    } catch (e2) {
      if (e2 instanceof ReturnSignal) return e2.value;
      throw e2;
    }
    return null;
  }

  private evalIndex(e: Expr & { kind: 'index' }, scope: Scope): TernValue {
    const obj = this.eval(e.obj, scope);
    const idx = this.eval(e.index, scope);

    if (typeof obj === 'object' && '_t' in obj && (obj as any)._t === 'list') {
      if (typeof idx !== 'bigint')
        throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
      const list = obj as TernList;
      const i = Number(idx);
      if (i < 0 || i >= list.elements.length)
        throw new TernError(e.line, `index ${idx} out of range for length ${list.elements.length}`);
      return list.elements[i];
    }
    if (typeof obj === 'string') {
      if (typeof idx !== 'bigint')
        throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
      const i = Number(idx);
      if (i < 0 || i >= obj.length)
        throw new TernError(e.line, `index ${idx} out of range for length ${obj.length}`);
      return obj[i];
    }
    throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
  }
}

// ============ MAIN ============

const dir = process.argv[2];
if (!dir) { process.exit(1); }
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = lex(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();
const interp = new Interpreter();
interp.run(program);
process.stdout.write(interp.output);
process.exit(0);

import * as fs from 'fs';
import * as path from 'path';

// ============ TYPES ============

type TernValue = bigint | boolean | string | TernList | TernFunction | null;
interface TernList { _t: 'list'; elements: TernValue[]; }
interface TernFunction { _t: 'function'; params: string[]; body: Stmt[]; scope: Scope; name?: string; __builtin?: { arity: number | -1; fn: (args: TernValue[], line: number) => TernValue; name: string }; }
interface Scope { vars: Map<string, TernValue>; parent: Scope | null; }

type Stmt =
  | { kind: 'let'; name: string; expr: Expr; line: number }
  | { kind: 'fnDecl'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'if'; cond: Expr; thenBody: Stmt[]; elseBody: Stmt[] | null; elseIf: Stmt | null; line: number }
  | { kind: 'while'; cond: Expr; body: Stmt[]; line: number }
  | { kind: 'for'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'return'; expr: Expr | null; line: number }
  | { kind: 'break'; line: number }
  | { kind: 'continue'; line: number }
  | { kind: 'assign'; name: string; expr: Expr; line: number }
  | { kind: 'indexAssign'; obj: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'exprStmt'; expr: Expr; line: number };

type Expr =
  | { kind: 'int'; value: bigint; line: number }
  | { kind: 'str'; value: string; line: number }
  | { kind: 'bool'; value: boolean; line: number }
  | { kind: 'nil'; line: number }
  | { kind: 'ident'; name: string; line: number }
  | { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'unary'; op: string; operand: Expr; line: number }
  | { kind: 'call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'index'; obj: Expr; index: Expr; line: number }
  | { kind: 'listLit'; elements: Expr[]; line: number }
  | { kind: 'fnExpr'; params: string[]; body: Stmt[]; line: number };

// ============ LEXER ============

enum TT {
  INT, STR, IDENT,
  LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
  AND, OR, NOT, TRUE, FALSE, NIL,
  EQ, NEQ, LE, GE, LT, GT, ASSIGN,
  PLUS, MINUS, STAR, SLASH, PERCENT,
  LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE,
  COMMA, SEMI, EOF
}

interface Token { type: TT; value: string; line: number; }

const KEYWORDS: Record<string, TT> = {
  let: TT.LET, fn: TT.FN, if: TT.IF, else: TT.ELSE,
  while: TT.WHILE, for: TT.FOR, in: TT.IN,
  return: TT.RETURN, break: TT.BREAK, continue: TT.CONTINUE,
  and: TT.AND, or: TT.OR, not: TT.NOT,
  true: TT.TRUE, false: TT.FALSE, nil: TT.NIL,
};

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0, line = 1;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\r') { i++; continue; }
    if (c === '\n') { line++; i++; continue; }
    if (c === '#') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c >= '0' && c <= '9') {
      let s = i; while (i < n && src[i] >= '0' && src[i] <= '9') i++;
      tokens.push({ type: TT.INT, value: src.slice(s, i), line }); continue;
    }
    if (c === '"') {
      i++; let val = '';
      while (i < n && src[i] !== '"') {
        if (src[i] === '\\') {
          i++;
          if (src[i] === 'n') val += '\n';
          else if (src[i] === 't') val += '\t';
          else if (src[i] === '"') val += '"';
          else if (src[i] === '\\') val += '\\';
          i++;
        } else { val += src[i]; i++; }
      }
      i++; tokens.push({ type: TT.STR, value: val, line }); continue;
    }
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_') {
      let s = i;
      while (i < n && ((src[i] >= 'a' && src[i] <= 'z') || (src[i] >= 'A' && src[i] <= 'Z') || (src[i] >= '0' && src[i] <= '9') || src[i] === '_')) i++;
      const w = src.slice(s, i);
      const kw = KEYWORDS[w];
      tokens.push(kw !== undefined ? { type: kw, value: w, line } : { type: TT.IDENT, value: w, line });
      continue;
    }
    const c2 = i + 1 < n ? src[i + 1] : '';
    if (c === '=' && c2 === '=') { tokens.push({ type: TT.EQ, value: '==', line }); i += 2; continue; }
    if (c === '!' && c2 === '=') { tokens.push({ type: TT.NEQ, value: '!=', line }); i += 2; continue; }
    if (c === '<' && c2 === '=') { tokens.push({ type: TT.LE, value: '<=', line }); i += 2; continue; }
    if (c === '>' && c2 === '=') { tokens.push({ type: TT.GE, value: '>=', line }); i += 2; continue; }
    if (c === '<') { tokens.push({ type: TT.LT, value: '<', line }); i++; continue; }
    if (c === '>') { tokens.push({ type: TT.GT, value: '>', line }); i++; continue; }
    if (c === '=') { tokens.push({ type: TT.ASSIGN, value: '=', line }); i++; continue; }
    if (c === '+') { tokens.push({ type: TT.PLUS, value: '+', line }); i++; continue; }
    if (c === '-') { tokens.push({ type: TT.MINUS, value: '-', line }); i++; continue; }
    if (c === '*') { tokens.push({ type: TT.STAR, value: '*', line }); i++; continue; }
    if (c === '/') { tokens.push({ type: TT.SLASH, value: '/', line }); i++; continue; }
    if (c === '%') { tokens.push({ type: TT.PERCENT, value: '%', line }); i++; continue; }
    if (c === '(') { tokens.push({ type: TT.LPAREN, value: '(', line }); i++; continue; }
    if (c === ')') { tokens.push({ type: TT.RPAREN, value: ')', line }); i++; continue; }
    if (c === '[') { tokens.push({ type: TT.LBRACKET, value: '[', line }); i++; continue; }
    if (c === ']') { tokens.push({ type: TT.RBRACKET, value: ']', line }); i++; continue; }
    if (c === '{') { tokens.push({ type: TT.LBRACE, value: '{', line }); i++; continue; }
    if (c === '}') { tokens.push({ type: TT.RBRACE, value: '}', line }); i++; continue; }
    if (c === ',') { tokens.push({ type: TT.COMMA, value: ',', line }); i++; continue; }
    if (c === ';') { tokens.push({ type: TT.SEMI, value: ';', line }); i++; continue; }
    i++;
  }
  tokens.push({ type: TT.EOF, value: '', line });
  return tokens;
}

// ============ PARSER ============

class Parser {
  private tokens: Token[];
  private pos: number = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  private peek(): Token { return this.tokens[this.pos]; }
  private advance(): Token { return this.tokens[this.pos++]; }
  private expect(type: TT): Token {
    const t = this.tokens[this.pos];
    if (t.type !== type) throw new Error(`Expected ${type} got ${t.type} at line ${t.line}`);
    this.pos++; return t;
  }
  private check(type: TT): boolean { return this.tokens[this.pos].type === type; }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (!this.check(TT.EOF)) stmts.push(this.parseStmt());
    return stmts;
  }

  private parseBlock(): Stmt[] {
    this.expect(TT.LBRACE);
    const stmts: Stmt[] = [];
    while (!this.check(TT.RBRACE) && !this.check(TT.EOF)) stmts.push(this.parseStmt());
    this.expect(TT.RBRACE);
    return stmts;
  }

  private parseParams(): string[] {
    const params: string[] = [];
    if (!this.check(TT.RPAREN)) {
      params.push(this.expect(TT.IDENT).value);
      while (this.check(TT.COMMA)) { this.advance(); params.push(this.expect(TT.IDENT).value); }
    }
    return params;
  }

  private parseStmt(): Stmt {
    const t = this.peek();
    switch (t.type) {
      case TT.LET: {
        this.advance();
        const name = this.expect(TT.IDENT).value;
        this.expect(TT.ASSIGN);
        const expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'let', name, expr, line: t.line };
      }
      case TT.FN: {
        this.advance();
        const name = this.expect(TT.IDENT).value;
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fnDecl', name, params, body, line: t.line };
      }
      case TT.IF: return this.parseIf();
      case TT.WHILE: {
        this.advance();
        const cond = this.parseExpr();
        const body = this.parseBlock();
        return { kind: 'while', cond, body, line: t.line };
      }
      case TT.FOR: {
        this.advance();
        const varName = this.expect(TT.IDENT).value;
        this.expect(TT.IN);
        const iterable = this.parseExpr();
        const body = this.parseBlock();
        return { kind: 'for', varName, iterable, body, line: t.line };
      }
      case TT.RETURN: {
        this.advance();
        let expr: Expr | null = null;
        if (!this.check(TT.SEMI)) expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'return', expr, line: t.line };
      }
      case TT.BREAK: { this.advance(); this.expect(TT.SEMI); return { kind: 'break', line: t.line }; }
      case TT.CONTINUE: { this.advance(); this.expect(TT.SEMI); return { kind: 'continue', line: t.line }; }
      case TT.IDENT: {
        // Check for assignment: IDENT = expr ;
        if (this.tokens[this.pos + 1].type === TT.ASSIGN) {
          const name = this.advance().value;  // consume IDENT, get name
          this.advance();                      // consume =
          const expr = this.parseExpr();
          this.expect(TT.SEMI);
          return { kind: 'assign', name, expr, line: t.line };
        }
        // Otherwise parse as expression, check for index assignment
        const expr = this.parseExpr();
        if (this.check(TT.ASSIGN)) {
          this.advance();
          const value = this.parseExpr();
          this.expect(TT.SEMI);
          if (expr.kind === 'index') {
            return { kind: 'indexAssign', obj: expr.obj, index: expr.index, value, line: t.line };
          }
          throw new Error('Invalid assignment target');
        }
        this.expect(TT.SEMI);
        return { kind: 'exprStmt', expr, line: t.line };
      }
      default: {
        const expr = this.parseExpr();
        this.expect(TT.SEMI);
        return { kind: 'exprStmt', expr, line: t.line };
      }
    }
  }

  private parseIf(): Stmt {
    const t = this.advance(); // 'if'
    const cond = this.parseExpr();
    const thenBody = this.parseBlock();
    let elseBody: Stmt[] | null = null;
    let elseIf: Stmt | null = null;
    if (this.check(TT.ELSE)) {
      this.advance();
      if (this.check(TT.IF)) {
        elseIf = this.parseIf();
      } else {
        elseBody = this.parseBlock();
      }
    }
    return { kind: 'if', cond, thenBody, elseBody, elseIf, line: t.line };
  }

  // Expression parsing
  private parseExpr(): Expr { return this.parseOr(); }
  private parseOr(): Expr {
    let left = this.parseAnd();
    while (this.check(TT.OR)) {
      const t = this.advance();
      const right = this.parseAnd();
      left = { kind: 'binary', op: 'or', left, right, line: t.line };
    }
    return left;
  }
  private parseAnd(): Expr {
    let left = this.parseNot();
    while (this.check(TT.AND)) {
      const t = this.advance();
      const right = this.parseNot();
      left = { kind: 'binary', op: 'and', left, right, line: t.line };
    }
    return left;
  }
  private parseNot(): Expr {
    if (this.check(TT.NOT)) {
      const t = this.advance();
      const operand = this.parseNot();
      return { kind: 'unary', op: 'not', operand, line: t.line };
    }
    return this.parseComparison();
  }
  private parseComparison(): Expr {
    let left = this.parseAdd();
    while (this.check(TT.EQ) || this.check(TT.NEQ) || this.check(TT.LT) ||
           this.check(TT.LE) || this.check(TT.GT) || this.check(TT.GE)) {
      const t = this.advance();
      const right = this.parseAdd();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseAdd(): Expr {
    let left = this.parseMul();
    while (this.check(TT.PLUS) || this.check(TT.MINUS)) {
      const t = this.advance();
      const right = this.parseMul();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseMul(): Expr {
    let left = this.parseUnary();
    while (this.check(TT.STAR) || this.check(TT.SLASH) || this.check(TT.PERCENT)) {
      const t = this.advance();
      const right = this.parseUnary();
      left = { kind: 'binary', op: t.value, left, right, line: t.line };
    }
    return left;
  }
  private parseUnary(): Expr {
    if (this.check(TT.MINUS)) {
      const t = this.advance();
      const operand = this.parseUnary();
      return { kind: 'unary', op: '-', operand, line: t.line };
    }
    return this.parsePostfix();
  }
  private parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.check(TT.LPAREN)) {
        const t = this.advance();
        const args: Expr[] = [];
        if (!this.check(TT.RPAREN)) {
          args.push(this.parseExpr());
          while (this.check(TT.COMMA)) { this.advance(); args.push(this.parseExpr()); }
        }
        this.expect(TT.RPAREN);
        expr = { kind: 'call', callee: expr, args, line: t.line };
      } else if (this.check(TT.LBRACKET)) {
        const t = this.advance();
        const index = this.parseExpr();
        this.expect(TT.RBRACKET);
        expr = { kind: 'index', obj: expr, index, line: t.line };
      } else break;
    }
    return expr;
  }
  private parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case TT.INT: this.advance(); return { kind: 'int', value: BigInt(t.value), line: t.line };
      case TT.STR: this.advance(); return { kind: 'str', value: t.value, line: t.line };
      case TT.TRUE: this.advance(); return { kind: 'bool', value: true, line: t.line };
      case TT.FALSE: this.advance(); return { kind: 'bool', value: false, line: t.line };
      case TT.NIL: this.advance(); return { kind: 'nil', line: t.line };
      case TT.IDENT: this.advance(); return { kind: 'ident', name: t.value, line: t.line };
      case TT.LPAREN: {
        this.advance();
        const expr = this.parseExpr();
        this.expect(TT.RPAREN);
        return expr;
      }
      case TT.LBRACKET: {
        this.advance();
        const elements: Expr[] = [];
        if (!this.check(TT.RBRACKET)) {
          elements.push(this.parseExpr());
          while (this.check(TT.COMMA)) { this.advance(); elements.push(this.parseExpr()); }
        }
        this.expect(TT.RBRACKET);
        return { kind: 'listLit', elements, line: t.line };
      }
      case TT.FN: {
        this.advance();
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fnExpr', params, body, line: t.line };
      }
      default:
        throw new Error(`Unexpected token ${t.type} at line ${t.line}`);
    }
  }
}

// ============ INTERPRETER ============

const INT_MIN = -(1n << 63n);
const INT_MAX = (1n << 63n) - 1n;

class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { constructor(public value: TernValue) {} }
class TernError { constructor(public line: number, public message: string) {} }

function typeOf(v: TernValue): string {
  if (v === null) return 'nil';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'string') return 'string';
  if (typeof v === 'object' && '_t' in v) {
    if ((v as any)._t === 'list') return 'list';
    if ((v as any)._t === 'function') return 'function';
  }
  return 'unknown';
}

function isTruthy(v: TernValue): boolean {
  if (v === null || v === false) return false;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'string') return v.length > 0;
  if (typeof v === 'object' && '_t' in v && (v as any)._t === 'list') return (v as TernList).elements.length > 0;
  return true;
}

function checkInt(v: bigint, line: number): void {
  if (v < INT_MIN || v > INT_MAX) throw new TernError(line, 'integer overflow');
}

function displayValue(v: TernValue, inList: boolean, seen: Set<TernList>): string {
  if (v === null) return 'nil';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'string') {
    if (!inList) return v;
    let s = '"';
    for (const ch of v) {
      if (ch === '\\') s += '\\\\';
      else if (ch === '"') s += '\\"';
      else if (ch === '\n') s += '\\n';
      else if (ch === '\t') s += '\\t';
      else s += ch;
    }
    return s + '"';
  }
  if (typeof v === 'object' && '_t' in v) {
    if ((v as any)._t === 'function') return '<fn>';
    if ((v as any)._t === 'list') {
      const list = v as TernList;
      if (seen.has(list)) return '[...]';
      seen.add(list);
      const parts: string[] = [];
      for (const el of list.elements) {
        parts.push(displayValue(el, true, seen));
      }
      seen.delete(list);
      return '[' + parts.join(', ') + ']';
    }
  }
  return '???';
}

class Interpreter {
  private globalScope: Scope;
  output: string = '';

  constructor() {
    const builtinScope: Scope = { vars: new Map(), parent: null };
    this.globalScope = { vars: new Map(), parent: builtinScope };
    this.registerBuiltins(builtinScope);
  }

  private registerBuiltins(scope: Scope): void {
    const mk = (name: string, arity: number | -1, fn: (args: TernValue[], line: number) => TernValue): void => {
      const f: TernFunction = { _t: 'function', params: [], body: [], scope, name, __builtin: { arity, fn, name } };
      scope.vars.set(name, f);
    };

    mk('print', -1, (args, line) => {
      const parts: string[] = [];
      for (const a of args) parts.push(displayValue(a, false, new Set()));
      this.output += parts.join(' ') + '\n';
      return null;
    });
    mk('str', 1, (args, line) => {
      return displayValue(args[0], false, new Set());
    });
    mk('type', 1, (args, line) => {
      return typeOf(args[0]);
    });
    mk('len', 1, (args, line) => {
      const v = args[0];
      if (typeof v === 'string') return BigInt(v.length);
      if (typeof v === 'object' && '_t' in v && (v as any)._t === 'list') return BigInt((v as TernList).elements.length);
      throw new TernError(line, 'bad argument to len');
    });
    mk('push', 2, (args, line) => {
      const list = args[0];
      if (typeof list !== 'object' || !('_t' in list) || (list as any)._t !== 'list')
        throw new TernError(line, 'bad argument to push');
      (list as TernList).elements.push(args[1]);
      return null;
    });
    mk('pop', 1, (args, line) => {
      const list = args[0];
      if (typeof list !== 'object' || !('_t' in list) || (list as any)._t !== 'list')
        throw new TernError(line, 'bad argument to pop');
      const el = (list as TernList).elements;
      if (el.length === 0) throw new TernError(line, 'bad argument to pop');
      return el.pop()!;
    });
    mk('range', 2, (args, line) => {
      if (typeof args[0] !== 'bigint' || typeof args[1] !== 'bigint')
        throw new TernError(line, 'bad argument to range');
      const a = args[0] as bigint, b = args[1] as bigint;
      const elems: TernValue[] = [];
      for (let i = a; i < b; i++) elems.push(i);
      return { _t: 'list', elements: elems };
    });
    mk('slice', 3, (args, line) => {
      const x = args[0], a = args[1], b = args[2];
      if (typeof a !== 'bigint' || typeof b !== 'bigint')
        throw new TernError(line, 'bad argument to slice');
      const ai = a as bigint, bi = b as bigint;
      if (typeof x === 'string') {
        const len = BigInt(x.length);
        if (ai < 0n || bi > len || ai > bi) throw new TernError(line, 'bad argument to slice');
        return x.slice(Number(ai), Number(bi));
      }
      if (typeof x === 'object' && '_t' in x && (x as any)._t === 'list') {
        const elems = (x as TernList).elements;
        const len = BigInt(elems.length);
        if (ai < 0n || bi > len || ai > bi) throw new TernError(line, 'bad argument to slice');
        return { _t: 'list', elements: elems.slice(Number(ai), Number(bi)) };
      }
      throw new TernError(line, 'bad argument to slice');
    });
  }

  private lookup(scope: Scope, name: string, line: number): TernValue {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) return s.vars.get(name)!;
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  private assign(scope: Scope, name: string, value: TernValue, line: number): void {
    let s: Scope | null = scope;
    while (s !== null) {
      if (s.vars.has(name)) { s.vars.set(name, value); return; }
      s = s.parent;
    }
    throw new TernError(line, `undefined variable ${name}`);
  }

  run(stmts: Stmt[]): void {
    try {
      this.execBlock(stmts, this.globalScope);
    } catch (e) {
      if (e instanceof TernError) {
        process.stdout.write(this.output);
        process.stdout.write(`error at line ${e.line}: ${e.message}\n`);
        process.exit(0);
      }
      throw e;
    }
  }

  private execBlock(stmts: Stmt[], scope: Scope): void {
    for (const s of stmts) this.execStmt(s, scope);
  }

  private execStmt(s: Stmt, scope: Scope): void {
    switch (s.kind) {
      case 'let': {
        const val = this.eval(s.expr, scope);
        scope.vars.set(s.name, val);
        break;
      }
      case 'fnDecl': {
        const fn: TernFunction = { _t: 'function', params: s.params, body: s.body, scope, name: s.name };
        scope.vars.set(s.name, fn);
        break;
      }
      case 'if': {
        const cond = this.eval(s.cond, scope);
        if (isTruthy(cond)) {
          this.execBlock(s.thenBody, { vars: new Map(), parent: scope });
        } else if (s.elseIf) {
          this.execStmt(s.elseIf, scope);
        } else if (s.elseBody) {
          this.execBlock(s.elseBody, { vars: new Map(), parent: scope });
        }
        break;
      }
      case 'while': {
        while (true) {
          const cond = this.eval(s.cond, scope);
          if (!isTruthy(cond)) break;
          const bodyScope: Scope = { vars: new Map(), parent: scope };
          try {
            this.execBlock(s.body, bodyScope);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) continue;
            throw e;
          }
        }
        break;
      }
      case 'for': {
        const listVal = this.eval(s.iterable, scope);
        if (typeof listVal !== 'object' || !('_t' in listVal) || (listVal as any)._t !== 'list')
          throw new TernError(s.line, `cannot iterate ${typeOf(listVal)}`);
        const list = listVal as TernList;
        let i = 0;
        while (i < list.elements.length) {
          const bodyScope: Scope = { vars: new Map(), parent: scope };
          bodyScope.vars.set(s.varName, list.elements[i]);
          try {
            this.execBlock(s.body, bodyScope);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { i++; continue; }
            throw e;
          }
          i++;
        }
        break;
      }
      case 'return': {
        const val = s.expr ? this.eval(s.expr, scope) : null;
        throw new ReturnSignal(val);
      }
      case 'break': throw new BreakSignal();
      case 'continue': throw new ContinueSignal();
      case 'assign': {
        const val = this.eval(s.expr, scope);
        this.assign(scope, s.name, val, s.line);
        break;
      }
      case 'indexAssign': {
        const obj = this.eval(s.obj, scope);
        const idx = this.eval(s.index, scope);
        const val = this.eval(s.value, scope);
        if (typeof obj !== 'object' || !('_t' in obj) || (obj as any)._t !== 'list')
          throw new TernError(s.line, `cannot assign into ${typeOf(obj)}`);
        if (typeof idx !== 'bigint')
          throw new TernError(s.line, `cannot index list with ${typeOf(idx)}`);
        const list = obj as TernList;
        const i = Number(idx);
        if (i < 0 || i >= list.elements.length)
          throw new TernError(s.line, `index ${idx} out of range for length ${list.elements.length}`);
        list.elements[i] = val;
        break;
      }
      case 'exprStmt': {
        this.eval(s.expr, scope);
        break;
      }
    }
  }

  private eval(e: Expr, scope: Scope): TernValue {
    switch (e.kind) {
      case 'int': return e.value;
      case 'str': return e.value;
      case 'bool': return e.value;
      case 'nil': return null;
      case 'ident': return this.lookup(scope, e.name, e.line);
      case 'listLit': {
        const elems: TernValue[] = [];
        for (const el of e.elements) elems.push(this.eval(el, scope));
        return { _t: 'list', elements: elems };
      }
      case 'fnExpr': {
        return { _t: 'function', params: e.params, body: e.body, scope };
      }
      case 'unary': {
        if (e.op === 'not') {
          const v = this.eval(e.operand, scope);
          return !isTruthy(v);
        }
        if (e.op === '-') {
          const v = this.eval(e.operand, scope);
          if (typeof v !== 'bigint')
            throw new TernError(e.line, `cannot apply - to ${typeOf(v)}`);
          const result = -v;
          checkInt(result, e.line);
          return result;
        }
        throw new Error('unknown unary op');
      }
      case 'binary': return this.evalBinary(e, scope);
      case 'call': return this.evalCall(e, scope);
      case 'index': return this.evalIndex(e, scope);
    }
  }

  private evalBinary(e: Expr & { kind: 'binary' }, scope: Scope): TernValue {
    const op = e.op;
    if (op === 'and') {
      const l = this.eval(e.left, scope);
      if (!isTruthy(l)) return l;
      return this.eval(e.right, scope);
    }
    if (op === 'or') {
      const l = this.eval(e.left, scope);
      if (isTruthy(l)) return l;
      return this.eval(e.right, scope);
    }

    const l = this.eval(e.left, scope);
    const r = this.eval(e.right, scope);

    if (op === '==' || op === '!=') {
      const eq = this.valuesEqual(l, r);
      return op === '==' ? eq : !eq;
    }

    if (op === '+') {
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        const res = l + r;
        checkInt(res, e.line);
        return res;
      }
      if (typeof l === 'string' && typeof r === 'string') return l + r;
      if (typeof l === 'object' && '_t' in l && (l as any)._t === 'list' &&
          typeof r === 'object' && '_t' in r && (r as any)._t === 'list') {
        return { _t: 'list', elements: [...(l as TernList).elements, ...(r as TernList).elements] };
      }
      throw new TernError(e.line, `cannot apply + to ${typeOf(l)} and ${typeOf(r)}`);
    }

    if (op === '-' || op === '*' || op === '/' || op === '%') {
      if (typeof l !== 'bigint' || typeof r !== 'bigint')
        throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      if (op === '/') {
        if (r === 0n) throw new TernError(e.line, 'division by zero');
        const res = l / r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '%') {
        if (r === 0n) throw new TernError(e.line, 'division by zero');
        const res = l - (l / r) * r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '-') {
        const res = l - r;
        checkInt(res, e.line);
        return res;
      }
      if (op === '*') {
        const res = l * r;
        checkInt(res, e.line);
        return res;
      }
    }

    if (op === '<' || op === '<=' || op === '>' || op === '>=') {
      let cmp: number;
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        cmp = l < r ? -1 : l > r ? 1 : 0;
      } else if (typeof l === 'string' && typeof r === 'string') {
        cmp = l < r ? -1 : l > r ? 1 : 0;
      } else {
        throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      }
      if (op === '<') return cmp < 0;
      if (op === '<=') return cmp <= 0;
      if (op === '>') return cmp > 0;
      return cmp >= 0;
    }

    throw new TernError(e.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
  }

  private valuesEqual(a: TernValue, b: TernValue): boolean {
    if (a === null && b === null) return true;
    if (a === null || b === null) return false;
    if (typeof a === 'bigint' && typeof b === 'bigint') return a === b;
    if (typeof a === 'boolean' && typeof b === 'boolean') return a === b;
    if (typeof a === 'string' && typeof b === 'string') return a === b;
    if (typeof a === 'object' && '_t' in a && (a as any)._t === 'list' &&
        typeof b === 'object' && '_t' in b && (b as any)._t === 'list') {
      const la = (a as TernList).elements, lb = (b as TernList).elements;
      if (la.length !== lb.length) return false;
      for (let i = 0; i < la.length; i++) {
        if (!this.valuesEqual(la[i], lb[i])) return false;
      }
      return true;
    }
    if (typeof a === 'object' && '_t' in a && (a as any)._t === 'function' &&
        typeof b === 'object' && '_t' in b && (b as any)._t === 'function') {
      return a === b;
    }
    return false;
  }

  private evalCall(e: Expr & { kind: 'call' }, scope: Scope): TernValue {
    const callee = this.eval(e.callee, scope);
    const args: TernValue[] = [];
    for (const a of e.args) args.push(this.eval(a, scope));

    if (typeof callee !== 'object' || !('_t' in callee) || (callee as any)._t !== 'function')
      throw new TernError(e.line, `cannot call ${typeOf(callee)}`);

    const fn = callee as TernFunction;
    const builtin = fn.__builtin;
    if (builtin) {
      if (builtin.arity !== -1 && args.length !== builtin.arity)
        throw new TernError(e.line, `expected ${builtin.arity} arguments, got ${args.length}`);
      return builtin.fn(args, e.line);
    }

    if (args.length !== fn.params.length)
      throw new TernError(e.line, `expected ${fn.params.length} arguments, got ${args.length}`);

    const callScope: Scope = { vars: new Map(), parent: fn.scope };
    for (let i = 0; i < fn.params.length; i++) {
      callScope.vars.set(fn.params[i], args[i]);
    }
    try {
      this.execBlock(fn.body, callScope);
    } catch (e2) {
      if (e2 instanceof ReturnSignal) return e2.value;
      throw e2;
    }
    return null;
  }

  private evalIndex(e: Expr & { kind: 'index' }, scope: Scope): TernValue {
    const obj = this.eval(e.obj, scope);
    const idx = this.eval(e.index, scope);

    if (typeof obj === 'object' && '_t' in obj && (obj as any)._t === 'list') {
      if (typeof idx !== 'bigint')
        throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
      const list = obj as TernList;
      const i = Number(idx);
      if (i < 0 || i >= list.elements.length)
        throw new TernError(e.line, `index ${idx} out of range for length ${list.elements.length}`);
      return list.elements[i];
    }
    if (typeof obj === 'string') {
      if (typeof idx !== 'bigint')
        throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
      const i = Number(idx);
      if (i < 0 || i >= obj.length)
        throw new TernError(e.line, `index ${idx} out of range for length ${obj.length}`);
      return obj[i];
    }
    throw new TernError(e.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
  }
}

// ============ MAIN ============

const dir = process.argv[2];
if (!dir) { process.exit(1); }
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = lex(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();
const interp = new Interpreter();
interp.run(program);
process.stdout.write(interp.output);
process.exit(0);

use std::collections::HashMap;
use std::cell::RefCell;
use std::rc::Rc;
use std::io::Write;

// ===== TOKENS & LEXER =====

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Int(i64), Str(String), Ident(String),
    Eq, Ne, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LP, RP, LB, RB, LC, RC, Comma, Semi,
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil, Eof,
}

struct Token { t: Tok, line: usize }

fn lex(src: &str) -> Vec<Token> {
    let b = src.as_bytes();
    let mut pos = 0usize;
    let mut line = 1usize;
    let mut toks = Vec::new();
    while pos < b.len() {
        let c = b[pos];
        if c == b'\n' { line += 1; pos += 1; continue; }
        if c == b' ' || c == b'\t' || c == b'\r' { pos += 1; continue; }
        if c == b'#' { while pos < b.len() && b[pos] != b'\n' { pos += 1; } continue; }
        if c.is_ascii_digit() {
            let start = pos;
            while pos < b.len() && b[pos].is_ascii_digit() { pos += 1; }
            let v: i64 = src[start..pos].parse().unwrap();
            toks.push(Token{t:Tok::Int(v), line});
            continue;
        }
        if c == b'"' {
            pos += 1;
            let mut s = String::new();
            while pos < b.len() && b[pos] != b'"' {
                if b[pos] == b'\\' {
                    pos += 1;
                    match b[pos] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        _ => s.push(b[pos] as char),
                    }
                    pos += 1;
                } else {
                    s.push(b[pos] as char);
                    pos += 1;
                }
            }
            pos += 1; // skip closing "
            toks.push(Token{t:Tok::Str(s), line});
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let start = pos;
            while pos < b.len() && (b[pos].is_ascii_alphanumeric() || b[pos] == b'_') { pos += 1; }
            let word = &src[start..pos];
            let t = match word {
                "let" => Tok::Let, "fn" => Tok::Fn, "if" => Tok::If,
                "else" => Tok::Else, "while" => Tok::While, "for" => Tok::For,
                "in" => Tok::In, "return" => Tok::Return, "break" => Tok::Break,
                "continue" => Tok::Continue, "and" => Tok::And, "or" => Tok::Or,
                "not" => Tok::Not, "true" => Tok::True, "false" => Tok::False,
                "nil" => Tok::Nil,
                _ => Tok::Ident(word.to_string()),
            };
            toks.push(Token{t, line});
            continue;
        }
        let t = match c {
            b'(' => { pos+=1; Tok::LP }
            b')' => { pos+=1; Tok::RP }
            b'[' => { pos+=1; Tok::LB }
            b']' => { pos+=1; Tok::RB }
            b'{' => { pos+=1; Tok::LC }
            b'}' => { pos+=1; Tok::RC }
            b',' => { pos+=1; Tok::Comma }
            b';' => { pos+=1; Tok::Semi }
            b'+' => { pos+=1; Tok::Plus }
            b'-' => { pos+=1; Tok::Minus }
            b'*' => { pos+=1; Tok::Star }
            b'/' => { pos+=1; Tok::Slash }
            b'%' => { pos+=1; Tok::Percent }
            b'=' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Eq }
                else { pos+=1; Tok::Assign }
            }
            b'!' => { pos+=2; Tok::Ne }
            b'<' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Le }
                else { pos+=1; Tok::Lt }
            }
            b'>' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Ge }
                else { pos+=1; Tok::Gt }
            }
            _ => { pos+=1; Tok::Eof }
        };
        toks.push(Token{t, line});
    }
    toks.push(Token{t:Tok::Eof, line});
    toks
}

// ===== AST =====

#[derive(Clone, Debug)]
enum Expr {
    Int(i64, usize), Str(String, usize), Bool(bool, usize), Nil(usize),
    Ident(String, usize),
    BinOp(BinOpT, Box<Expr>, Box<Expr>, usize),
    Not(Box<Expr>, usize), Neg(Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>, usize),
    FnLit(Vec<String>, Vec<Stmt>, usize),
    And(Box<Expr>, Box<Expr>, usize),
    Or(Box<Expr>, Box<Expr>, usize),
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum BinOpT { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge }

#[derive(Clone, Debug)]
enum Stmt {
    Let(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If(Expr, Vec<Stmt>, Option<ElseBranch>, usize),
    While(Expr, Vec<Stmt>, usize),
    For(String, Expr, Vec<Stmt>, usize),
    Return(Option<Expr>, usize),
    Break(usize), Continue(usize),
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr, usize),
}

#[derive(Clone, Debug)]
enum ElseBranch { Block(Vec<Stmt>), IfStmt(Box<Stmt>) }

// ===== PARSER =====

struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn new(toks: Vec<Token>) -> Self { Parser{toks, pos:0} }
    fn peek(&self) -> &Tok { &self.toks[self.pos].t }
    fn line(&self) -> usize { self.toks[self.pos].line }
    fn advance(&mut self) -> &Token { let t = &self.toks[self.pos]; self.pos+=1; t }
    fn expect(&mut self, t: &Tok) { assert_eq!(&self.toks[self.pos].t, t, "expected {:?} got {:?}", t, self.toks[self.pos].t); self.pos+=1; }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut s = Vec::new();
        while *self.peek() != Tok::Eof { s.push(self.parse_stmt()); }
        s
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(&Tok::LC);
        let mut s = Vec::new();
        while *self.peek() != Tok::RC { s.push(self.parse_stmt()); }
        self.expect(&Tok::RC);
        s
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut p = Vec::new();
        if let Tok::Ident(_) = self.peek() {
            if let Tok::Ident(name) = self.advance().t.clone() { p.push(name); }
            while *self.peek() == Tok::Comma {
                self.advance();
                if let Tok::Ident(name) = self.advance().t.clone() { p.push(name); }
            }
        }
        p
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().clone() {
            Tok::Let => {
                self.advance();
                let name = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::Assign);
                let e = self.parse_expr();
                self.expect(&Tok::Semi);
                Stmt::Let(name, e, self.line())
            }
            Tok::Fn => {
                let ln = self.line();
                self.advance();
                let name = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::LP);
                let params = self.parse_params();
                self.expect(&Tok::RP);
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body, ln)
            }
            Tok::If => self.parse_if(),
            Tok::While => {
                let ln = self.line();
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body, ln)
            }
            Tok::For => {
                let ln = self.line();
                self.advance();
                let var = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::In);
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(var, e, body, ln)
            }
            Tok::Return => {
                let ln = self.line();
                self.advance();
                let e = if *self.peek() == Tok::Semi { None } else { Some(self.parse_expr()) };
                self.expect(&Tok::Semi);
                Stmt::Return(e, ln)
            }
            Tok::Break => { let ln=self.line(); self.advance(); self.expect(&Tok::Semi); Stmt::Break(ln) }
            Tok::Continue => { let ln=self.line(); self.advance(); self.expect(&Tok::Semi); Stmt::Continue(ln) }
            _ => {
                let e = self.parse_expr();
                if *self.peek() == Tok::Assign {
                    self.advance();
                    match e {
                        Expr::Ident(name, ln) => {
                            let v = self.parse_expr();
                            self.expect(&Tok::Semi);
                            Stmt::Assign(name, v, ln)
                        }
                        Expr::Index(base, idx, ln) => {
                            let v = self.parse_expr();
                            self.expect(&Tok::Semi);
                            Stmt::IndexAssign(base, idx, v, ln)
                        }
                        _ => unreachable!()
                    }
                } else {
                    self.expect(&Tok::Semi);
                    Stmt::ExprStmt(e, self.line())
                }
            }
        }
    }

    fn parse_if(&mut self) -> Stmt {
        let ln = self.line();
        self.advance(); // 'if'
        let cond = self.parse_expr();
        let body = self.parse_block();
        let els = if *self.peek() == Tok::Else {
            self.advance();
            if *self.peek() == Tok::If {
                Some(ElseBranch::IfStmt(Box::new(self.parse_if())))
            } else {
                Some(ElseBranch::Block(self.parse_block()))
            }
        } else { None };
        Stmt::If(cond, body, els, ln)
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }
    fn parse_or(&mut self) -> Expr {
        let mut l = self.parse_and();
        while *self.peek() == Tok::Or {
            let ln = self.line(); self.advance();
            let r = self.parse_and();
            l = Expr::Or(Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_and(&mut self) -> Expr {
        let mut l = self.parse_not();
        while *self.peek() == Tok::And {
            let ln = self.line(); self.advance();
            let r = self.parse_not();
            l = Expr::And(Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_not(&mut self) -> Expr {
        if *self.peek() == Tok::Not {
            let ln = self.line(); self.advance();
            let e = self.parse_not();
            Expr::Not(Box::new(e), ln)
        } else { self.parse_cmp() }
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut l = self.parse_add();
        loop {
            let op = match self.peek() {
                Tok::Eq => BinOpT::Eq, Tok::Ne => BinOpT::Ne,
                Tok::Lt => BinOpT::Lt, Tok::Le => BinOpT::Le,
                Tok::Gt => BinOpT::Gt, Tok::Ge => BinOpT::Ge,
                _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_add();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_add(&mut self) -> Expr {
        let mut l = self.parse_mul();
        loop {
            let op = match self.peek() {
                Tok::Plus => BinOpT::Add, Tok::Minus => BinOpT::Sub, _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_mul();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_mul(&mut self) -> Expr {
        let mut l = self.parse_unary();
        loop {
            let op = match self.peek() {
                Tok::Star => BinOpT::Mul, Tok::Slash => BinOpT::Div, Tok::Percent => BinOpT::Mod, _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_unary();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_unary(&mut self) -> Expr {
        if *self.peek() == Tok::Minus {
            let ln = self.line(); self.advance();
            let e = self.parse_unary();
            Expr::Neg(Box::new(e), ln)
        } else { self.parse_postfix() }
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek() {
                Tok::LP => {
                    let ln = self.line(); self.advance();
                    let mut args = Vec::new();
                    if *self.peek() != Tok::RP {
                        args.push(self.parse_expr());
                        while *self.peek() == Tok::Comma { self.advance(); args.push(self.parse_expr()); }
                    }
                    self.expect(&Tok::RP);
                    e = Expr::Call(Box::new(e), args, ln);
                }
                Tok::LB => {
                    let ln = self.line(); self.advance();
                    let idx = self.parse_expr();
                    self.expect(&Tok::RB);
                    e = Expr::Index(Box::new(e), Box::new(idx), ln);
                }
                _ => break,
            }
        }
        e
    }
    fn parse_primary(&mut self) -> Expr {
        match self.peek().clone() {
            Tok::Int(v) => { let ln=self.line(); self.advance(); Expr::Int(v, ln) }
            Tok::Str(s) => { let ln=self.line(); self.advance(); Expr::Str(s, ln) }
            Tok::True => { let ln=self.line(); self.advance(); Expr::Bool(true, ln) }
            Tok::False => { let ln=self.line(); self.advance(); Expr::Bool(false, ln) }
            Tok::Nil => { let ln=self.line(); self.advance(); Expr::Nil(ln) }
            Tok::Ident(n) => { let ln=self.line(); self.advance(); Expr::Ident(n, ln) }
            Tok::LP => { self.advance(); let e = self.parse_expr(); self.expect(&Tok::RP); e }
            Tok::LB => {
                let ln = self.line(); self.advance();
                let mut items = Vec::new();
                if *self.peek() != Tok::RB {
                    items.push(self.parse_expr());
                    while *self.peek() == Tok::Comma { self.advance(); items.push(self.parse_expr()); }
                }
                self.expect(&Tok::RB);
                Expr::ListLit(items, ln)
            }
            Tok::Fn => {
                let ln = self.line(); self.advance();
                self.expect(&Tok::LP);
                let params = self.parse_params();
                self.expect(&Tok::RP);
                let body = self.parse_block();
                Expr::FnLit(params, body, ln)
            }
            _ => unreachable!()
        }
    }
}

// ===== VALUES =====

#[derive(Clone)]
enum Value {
    Int(i64), Bool(bool), Str(String),
    List(Rc<RefCell<Vec<Value>>>),
    Func(Rc<FuncData>),
    Nil,
}

enum FuncData {
    User { params: Vec<String>, body: Vec<Stmt>, captured: Rc<RefCell<Scope>> },
    Builtin(BuiltinKind),
}

#[derive(Clone, Copy, PartialEq)]
enum BuiltinKind { Print, Str, TypeOf, Len, Push, Pop, Range, Slice }

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

// ===== ERROR =====

struct RuntimeError { line: usize, msg: String }

// ===== INTERPRETER =====

struct Interp {
    current: Rc<RefCell<Scope>>,
    output: String,
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Nil => false,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Func(_) => true,
    }
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int", Value::Bool(_) => "bool", Value::Str(_) => "string",
        Value::List(_) => "list", Value::Func(_) => "function", Value::Nil => "nil",
    }
}

fn display(v: &Value, in_list: bool, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(b) => if *b {"true".to_string()} else {"false".to_string()},
        Value::Nil => "nil".to_string(),
        Value::Func(_) => "<fn>".to_string(),
        Value::Str(s) => {
            if in_list {
                let mut r = String::from("\"");
                for c in s.chars() {
                    match c {
                        '\\' => r.push_str("\\\\"),
                        '"' => r.push_str("\\\""),
                        '\n' => r.push_str("\\n"),
                        '\t' => r.push_str("\\t"),
                        _ => r.push(c),
                    }
                }
                r.push('"');
                r
            } else { s.clone() }
        }
        Value::List(items) => {
            let ptr = Rc::as_ptr(items) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let inner: Vec<String> = items.borrow().iter().map(|v| display(v, true, seen)).collect();
            seen.pop();
            format!("[{}]", inner.join(", "))
        }
    }
}

fn vals_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::List(x), Value::List(y)) => {
            let xb = x.borrow(); let yb = y.borrow();
            if xb.len() != yb.len() { return false; }
            xb.iter().zip(yb.iter()).all(|(a,b)| vals_eq(a,b))
        }
        (Value::Func(x), Value::Func(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

impl Interp {
    fn new() -> Self {
        let builtins = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:None}));
        let global = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(builtins.clone())}));
        // register builtins
        {
            let mut bs = builtins.borrow_mut();
            for (name, kind) in [
                ("print", BuiltinKind::Print), ("str", BuiltinKind::Str),
                ("type", BuiltinKind::TypeOf), ("len", BuiltinKind::Len),
                ("push", BuiltinKind::Push), ("pop", BuiltinKind::Pop),
                ("range", BuiltinKind::Range), ("slice", BuiltinKind::Slice),
            ] {
                bs.vars.insert(name.to_string(), Value::Func(Rc::new(FuncData::Builtin(kind))));
            }
        }
        Interp { current: global, output: String::new() }
    }

    fn lookup(&self, name: &str) -> Option<Value> {
        let mut sc = self.current.clone();
        loop {
            let s = sc.borrow();
            if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
            if let Some(ref p) = s.parent {
                let p = p.clone();
                drop(s);
                sc = p;
            } else { return None; }
        }
    }

    fn assign(&self, name: &str, val: Value) -> Result<(), RuntimeError> {
        let mut sc = self.current.clone();
        loop {
            {
                let s = sc.borrow();
                if s.vars.contains_key(name) {
                    drop(s);
                    sc.borrow_mut().vars.insert(name.to_string(), val);
                    return Ok(());
                }
            }
            let p = { let s = sc.borrow(); s.parent.clone() };
            match p { Some(p) => sc = p, None => return Err(RuntimeError{line:0, msg:format!("undefined variable {}", name)}) }
        }
    }

    fn enter_block(&mut self) -> Rc<RefCell<Scope>> {
        let old = self.current.clone();
        let new = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(old.clone())}));
        self.current = new;
        old
    }

    fn leave_block(&mut self, old: Rc<RefCell<Scope>>) {
        self.current = old;
    }

    fn eval(&self, e: &Expr) -> Result<Value, RuntimeError> {
        match e {
            Expr::Int(v, _) => Ok(Value::Int(*v)),
            Expr::Str(s, _) => Ok(Value::Str(s.clone())),
            Expr::Bool(b, _) => Ok(Value::Bool(*b)),
            Expr::Nil(_) => Ok(Value::Nil),
            Expr::Ident(name, ln) => {
                self.lookup(name).ok_or(RuntimeError{line:*ln, msg:format!("undefined variable {}", name)})
            }
            Expr::And(l, r, _) => {
                let lv = self.eval(l)?;
                if !truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Or(l, r, _) => {
                let lv = self.eval(l)?;
                if truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Not(e, _) => {
                let v = self.eval(e)?;
                Ok(Value::Bool(!truthy(&v)))
            }
            Expr::Neg(e, ln) => {
                let v = self.eval(e)?;
                match v {
                    Value::Int(n) => n.checked_neg().map(Value::Int).ok_or(RuntimeError{line:*ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:*ln, msg:format!("cannot apply - to {}", type_name(&v))})
                }
            }
            Expr::BinOp(op, l, r, ln) => {
                let lv = self.eval(l)?;
                let rv = self.eval(r)?;
                self.binop(*op, lv, rv, *ln)
            }
            Expr::Call(callee, args, ln) => {
                let cv = self.eval(callee)?;
                let mut argv = Vec::with_capacity(args.len());
                for a in args { argv.push(self.eval(a)?); }
                self.call(cv, argv, *ln)
            }
            Expr::Index(obj, idx, ln) => {
                let ov = self.eval(obj)?;
                let iv = self.eval(idx)?;
                self.index_read(&ov, &iv, *ln)
            }
            Expr::ListLit(items, _) => {
                let mut v = Vec::with_capacity(items.len());
                for it in items { v.push(self.eval(it)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body, _) => {
                Ok(Value::Func(Rc::new(FuncData::User{
                    params: params.clone(), body: body.clone(), captured: self.current.clone()
                })))
            }
        }
    }

    fn binop(&self, op: BinOpT, l: Value, r: Value, ln: usize) -> Result<Value, RuntimeError> {
        match op {
            BinOpT::Eq => Ok(Value::Bool(vals_eq(&l, &r))),
            BinOpT::Ne => Ok(Value::Bool(!vals_eq(&l, &r))),
            BinOpT::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                    (Value::List(a), Value::List(b)) => {
                        let mut v = a.borrow().clone();
                        v.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply + to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Sub => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply - to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mul => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_mul(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply * to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Div => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        a.checked_div(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply / to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mod => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        if *b == -1 { return Ok(Value::Int(0)); }
                        let q = a.checked_div(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        let qb = q.checked_mul(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        a.checked_sub(qb).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply % to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Lt | BinOpT::Le | BinOpT::Gt | BinOpT::Ge => {
                let (a, b) = match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let res = match op { BinOpT::Lt=>a<*b, BinOpT::Le=>a<=*b, BinOpT::Gt=>a>*b, _=>a>=*b };
                        return Ok(Value::Bool(res));
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op { BinOpT::Lt=>a<b, BinOpT::Le=>a<=b, BinOpT::Gt=>a>b, _=>a>=b };
                        return Ok(Value::Bool(res));
                    }
                    _ => return Err(RuntimeError{line:ln, msg:format!("cannot apply {} to {} and {}", 
                        match op { BinOpT::Lt=>"<", BinOpT::Le=>"<=", BinOpT::Gt=>">", _=>">=" },
                        type_name(&l), type_name(&r))}),
                };
                let _ = (a, b);
                unreachable!()
            }
        }
    }

    fn index_read(&self, obj: &Value, idx: &Value, ln: usize) -> Result<Value, RuntimeError> {
        match (obj, idx) {
            (Value::List(items), Value::Int(i)) => {
                let items = items.borrow();
                let i = *i as usize;
                if i >= items.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, items.len())});
                }
                Ok(items[i].clone())
            }
            (Value::Str(s), Value::Int(i)) => {
                let i = *i as usize;
                if i >= s.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, s.len())});
                }
                Ok(Value::Str(s[i..i+1].to_string()))
            }
            (Value::List(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index list with {}", type_name(idx))}),
            (Value::Str(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index string with {}", type_name(idx))}),
            _ => Err(RuntimeError{line:ln, msg:format!("cannot index {} with {}", type_name(obj), type_name(idx))}),
        }
    }

    fn call(&self, cv: Value, args: Vec<Value>, ln: usize) -> Result<Value, RuntimeError> {
        match &*cv {
            FuncData::Builtin(kind) => {
                let expected = match kind {
                    BuiltinKind::Print => -1,
                    BuiltinKind::Str | BuiltinKind::TypeOf | BuiltinKind::Len | BuiltinKind::Pop => 1,
                    BuiltinKind::Push | BuiltinKind::Range => 2,
                    BuiltinKind::Slice => 3,
                };
                if expected >= 0 && args.len() != expected as usize {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", expected, args.len())});
                }
                self.call_builtin(*kind, args, ln)
            }
            FuncData::User{params, body, captured} => {
                if args.len() != params.len() {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", params.len(), args.len())});
                }
                let mut vars = HashMap::new();
                for (p, a) in params.iter().zip(args) { vars.insert(p.clone(), a); }
                let new_scope = Rc::new(RefCell::new(Scope{vars, parent:Some(captured.clone())}));
                let old = self.current.clone();
                // We need interior mutability for current, so we'll use a workaround
                // Actually we can't mutate self.current in &self... let me restructure
                // For now, let's use RefCell for current too
                drop(old);
                self.call_user(params, body, captured, args, ln)
            }
        }
    }

    fn call_user(&self, _params: &Vec<String>, body: &Vec<Stmt>, captured: &Rc<RefCell<Scope>>, args: Vec<Value>, _ln: usize) -> Result<Value, RuntimeError> {
        // This is handled in the mutable version
        unreachable!()
    }

    fn call_builtin(&self, kind: BuiltinKind, args: Vec<Value>, ln: usize) -> Result<Value, RuntimeError> {
        let bad = |name: &str| RuntimeError{line:ln, msg:format!("bad argument to {}", name)};
        match kind {
            BuiltinKind::Print => {
                let parts: Vec<String> = args.iter().map(|v| display(v, false, &mut vec![])).collect();
                self.output.push_str(&parts.join(" "));
                self.output.push('\n');
                Ok(Value::Nil)
            }
            BuiltinKind::Str => {
                Ok(Value::Str(display(&args[0], false, &mut vec![])))
            }
            BuiltinKind::TypeOf => {
                Ok(Value::Str(type_name(&args[0]).to_string()))
            }
            BuiltinKind::Len => {
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(bad("len"))
                }
            }
            BuiltinKind::Push => {
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(bad("push"))
                }
            }
            BuiltinKind::Pop => {
                match &args[0] {
                    Value::List(l) => {
                        let mut items = l.borrow_mut();
                        items.pop().map(|v| v).ok_or(bad("pop"))
                    }
                    _ => Err(bad("pop"))
                }
            }
            BuiltinKind::Range => {
                match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Value::Int(i)); i += 1; }
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(bad("range"))
                }
            }
            BuiltinKind::Slice => {
                match (&args[0], &args[1], &args[2]) {
                    (Value::Str(s), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        if a > b || b > s.len() { return Err(bad("slice")); }
                        Ok(Value::Str(s[a..b].to_string()))
                    }
                    (Value::List(l), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        let items = l.borrow();
                        if a > b || b > items.len() { return Err(bad("slice")); }
                        Ok(Value::List(Rc::new(RefCell::new(items[a..b].to_vec()))))
                    }
                    _ => Err(bad("slice"))
                }
            }
        }
    }
}

// We need a mutable version for scope manipulation. Let me restructure with RefCell for current.

struct Interp2 {
    current: RefCell<Rc<RefCell<Scope>>>,
    output: RefCell<String>,
}

enum CF { Normal, Break, Continue, Return(Value) }

impl Interp2 {
    fn new() -> Self {
        let builtins = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:None}));
        {
            let mut bs = builtins.borrow_mut();
            for (name, kind) in [
                ("print", BuiltinKind::Print), ("str", BuiltinKind::Str),
                ("type", BuiltinKind::TypeOf), ("len", BuiltinKind::Len),
                ("push", BuiltinKind::Push), ("pop", BuiltinKind::Pop),
                ("range", BuiltinKind::Range), ("slice", BuiltinKind::Slice),
            ] {
                bs.vars.insert(name.to_string(), Value::Func(Rc::new(FuncData::Builtin(kind))));
            }
        }
        let global = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(builtins)}));
        Interp2 { current: RefCell::new(global), output: RefCell::new(String::new()) }
    }

    fn cur(&self) -> Rc<RefCell<Scope>> { self.current.borrow().clone() }

    fn lookup(&self, name: &str) -> Option<Value> {
        let mut sc = self.cur();
        loop {
            let s = sc.borrow();
            if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
            if let Some(ref p) = s.parent {
                let p = p.clone();
                drop(s);
                sc = p;
            } else { return None; }
        }
    }

    fn assign(&self, name: &str, val: Value) -> Result<(), RuntimeError> {
        let mut sc = self.cur();
        loop {
            if sc.borrow().vars.contains_key(name) {
                sc.borrow_mut().vars.insert(name.to_string(), val);
                return Ok(());
            }
            let p = { let s = sc.borrow(); s.parent.clone() };
            match p { Some(p) => sc = p, None => return Err(RuntimeError{line:0, msg:format!("undefined variable {}", name)}) }
        }
    }

    fn eval(&self, e: &Expr) -> Result<Value, RuntimeError> {
        match e {
            Expr::Int(v, _) => Ok(Value::Int(*v)),
            Expr::Str(s, _) => Ok(Value::Str(s.clone())),
            Expr::Bool(b, _) => Ok(Value::Bool(*b)),
            Expr::Nil(_) => Ok(Value::Nil),
            Expr::Ident(name, ln) => {
                self.lookup(name).ok_or_else(|| RuntimeError{line:*ln, msg:format!("undefined variable {}", name)})
            }
            Expr::And(l, r, _) => {
                let lv = self.eval(l)?;
                if !truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Or(l, r, _) => {
                let lv = self.eval(l)?;
                if truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Not(e, _) => {
                let v = self.eval(e)?;
                Ok(Value::Bool(!truthy(&v)))
            }
            Expr::Neg(e, ln) => {
                let v = self.eval(e)?;
                match v {
                    Value::Int(n) => n.checked_neg().map(Value::Int).ok_or(RuntimeError{line:*ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:*ln, msg:format!("cannot apply - to {}", type_name(&v))})
                }
            }
            Expr::BinOp(op, l, r, ln) => {
                let lv = self.eval(l)?;
                let rv = self.eval(r)?;
                self.binop(*op, lv, rv, *ln)
            }
            Expr::Call(callee, args, ln) => {
                let cv = self.eval(callee)?;
                let mut argv = Vec::with_capacity(args.len());
                for a in args { argv.push(self.eval(a)?); }
                self.call(cv, argv, *ln)
            }
            Expr::Index(obj, idx, ln) => {
                let ov = self.eval(obj)?;
                let iv = self.eval(idx)?;
                self.index_read(&ov, &iv, *ln)
            }
            Expr::ListLit(items, _) => {
                let mut v = Vec::with_capacity(items.len());
                for it in items { v.push(self.eval(it)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body, _) => {
                Ok(Value::Func(Rc::new(FuncData::User{
                    params: params.clone(), body: body.clone(), captured: self.cur()
                })))
            }
        }
    }

    fn binop(&self, op: BinOpT, l: Value, r: Value, ln: usize) -> Result<Value, RuntimeError> {
        match op {
            BinOpT::Eq => Ok(Value::Bool(vals_eq(&l, &r))),
            BinOpT::Ne => Ok(Value::Bool(!vals_eq(&l, &r))),
            BinOpT::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                    (Value::List(a), Value::List(b)) => {
                        let mut v = a.borrow().clone();
                        v.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply + to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Sub => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply - to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mul => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_mul(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply * to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Div => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        a.checked_div(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply / to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mod => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        if *b == -1 { return Ok(Value::Int(0)); }
                        let q = a.checked_div(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        let qb = q.checked_mul(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        a.checked_sub(qb).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply % to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Lt | BinOpT::Le | BinOpT::Gt | BinOpT::Ge => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let res = match op { BinOpT::Lt=>a<*b, BinOpT::Le=>a<=*b, BinOpT::Gt=>a>*b, _=>a>=*b };
                        Ok(Value::Bool(res))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op { BinOpT::Lt=>a<b, BinOpT::Le=>a<=b, BinOpT::Gt=>a>b, _=>a>=b };
                        Ok(Value::Bool(res))
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply {} to {} and {}",
                        match op { BinOpT::Lt=>"<", BinOpT::Le=>"<=", BinOpT::Gt=>">", _=>">=" },
                        type_name(&l), type_name(&r))}),
                }
            }
        }
    }

    fn index_read(&self, obj: &Value, idx: &Value, ln: usize) -> Result<Value, RuntimeError> {
        match (obj, idx) {
            (Value::List(items), Value::Int(i)) => {
                let items = items.borrow();
                let i = *i as usize;
                if i >= items.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, items.len())});
                }
                Ok(items[i].clone())
            }
            (Value::Str(s), Value::Int(i)) => {
                let i = *i as usize;
                if i >= s.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, s.len())});
                }
                Ok(Value::Str(s[i..i+1].to_string()))
            }
            (Value::List(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index list with {}", type_name(idx))}),
            (Value::Str(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index string with {}", type_name(idx))}),
            _ => Err(RuntimeError{line:ln, msg:format!("cannot index {} with {}", type_name(obj), type_name(idx))}),
        }
    }

    fn call(&self, cv: Value, args: Vec<Value>, ln: usize) -> Result<Value, RuntimeError> {
        match &*cv {
            FuncData::Builtin(kind) => {
                let expected: i32 = match kind {
                    BuiltinKind::Print => -1,
                    BuiltinKind::Str | BuiltinKind::TypeOf | BuiltinKind::Len | BuiltinKind::Pop => 1,
                    BuiltinKind::Push | BuiltinKind::Range => 2,
                    BuiltinKind::Slice => 3,
                };
                if expected >= 0 && args.len() != expected as usize {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", expected, args.len())});
                }
                self.call_builtin(*kind, &args, ln)
            }
            FuncData::User{params, body, captured} => {
                if args.len() != params.len() {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", params.len(), args.len())});
                }
                let mut vars = HashMap::new();
                for (p, a) in params.iter().zip(args.into_iter()) { vars.insert(p.clone(), a); }
                let new_scope = Rc::new(RefCell::new(Scope{vars, parent:Some(captured.clone())}));
                let old = self.current.borrow().clone();
                *self.current.borrow_mut() = new_scope;
                let result = self.exec_body(body);
                *self.current.borrow_mut() = old;
                match result? {
                    CF::Return(v) => Ok(v),
                    _ => Ok(Value::Nil),
                }
            }
        }
    }

    fn call_builtin(&self, kind: BuiltinKind, args: &[Value], ln: usize) -> Result<Value, RuntimeError> {
        let bad = |name: &str| RuntimeError{line:ln, msg:format!("bad argument to {}", name)};
        match kind {
            BuiltinKind::Print => {
                let parts: Vec<String> = args.iter().map(|v| display(v, false, &mut vec![])).collect();
                self.output.borrow_mut().push_str(&parts.join(" "));
                self.output.borrow_mut().push('\n');
                Ok(Value::Nil)
            }
            BuiltinKind::Str => Ok(Value::Str(display(&args[0], false, &mut vec![]))),
            BuiltinKind::TypeOf => Ok(Value::Str(type_name(&args[0]).to_string())),
            BuiltinKind::Len => {
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(bad("len"))
                }
            }
            BuiltinKind::Push => {
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(bad("push"))
                }
            }
            BuiltinKind::Pop => {
                match &args[0] {
                    Value::List(l) => {
                        l.borrow_mut().pop().ok_or_else(|| bad("pop"))
                    }
                    _ => Err(bad("pop"))
                }
            }
            BuiltinKind::Range => {
                match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Value::Int(i)); i += 1; }
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(bad("range"))
                }
            }
            BuiltinKind::Slice => {
                match (&args[0], &args[1], &args[2]) {
                    (Value::Str(s), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        if a > b || b > s.len() { return Err(bad("slice")); }
                        Ok(Value::Str(s[a..b].to_string()))
                    }
                    (Value::List(l), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        let items = l.borrow();
                        if a > b || b > items.len() { return Err(bad("slice")); }
                        Ok(Value::List(Rc::new(RefCell::new(items[a..b].to_vec()))))
                    }
                    _ => Err(bad("slice"))
                }
            }
        }
    }

    fn exec_body(&self, stmts: &[Stmt]) -> Result<CF, RuntimeError> {
        for s in stmts {
            match self.exec_stmt(s)? {
                CF::Normal => continue,
                other => return Ok(other),
            }
        }
        Ok(CF::Normal)
    }

    fn exec_block(&self, stmts: &[Stmt]) -> Result<CF, RuntimeError> {
        let old = self.current.borrow().clone();
        let new = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(old.clone())}));
        *self.current.borrow_mut() = new;
        let r = self.exec_body(stmts);
        *self.current.borrow_mut() = old;
        r
    }

    fn exec_stmt(&self, s: &Stmt) -> Result<CF, RuntimeError> {
        match s {
            Stmt::Let(name, expr, _) => {
                let v = self.eval(expr)?;
                self.cur().borrow_mut().vars.insert(name.clone(), v);
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, _) => {
                let fv = Value::Func(Rc::new(FuncData::User{
                    params: params.clone(), body: body.clone(), captured: self.cur()
                }));
                self.cur().borrow_mut().vars.insert(name.clone(), fv);
                Ok(CF::Normal)
            }
            Stmt::If(cond, body, els, _) => {
                let cv = self.eval(cond)?;
                if truthy(&cv) {
                    self.exec_block(body)
                } else {
                    match els {
                        Some(ElseBranch::Block(b)) => self.exec_block(b),
                        Some(ElseBranch::IfStmt(s)) => self.exec_stmt(s),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body, _) => {
                loop {
                    let cv = self.eval(cond)?;
                    if !truthy(&cv) { break; }
                    match self.exec_block(body)? {
                        CF::Break => break,
                        CF::Continue => continue,
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => {}
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, expr, body, ln) => {
                let list_val = self.eval(expr)?;
                let list = match &list_val {
                    Value::List(l) => l.clone(),
                    _ => return Err(RuntimeError{line:*ln, msg:format!("cannot iterate {}", type_name(&list_val))}),
                };
                let mut i: usize = 0;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let old = self.current.borrow().clone();
                    let mut vars = HashMap::new();
                    vars.insert(var.clone(), elem);
                    let new_scope = Rc::new(RefCell::new(Scope{vars, parent:Some(old.clone())}));
                    *self.current.borrow_mut() = new_scope;
                    let r = self.exec_body(body);
                    *self.current.borrow_mut() = old;
                    match r? {
                        CF::Break => break,
                        CF::Continue => { i += 1; continue; }
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => { i += 1; }
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::Return(expr, _) => {
                let v = match expr { Some(e) => self.eval(e)?, None => Value::Nil };
                Ok(CF::Return(v))
            }
            Stmt::Break(_) => Ok(CF::Break),
            Stmt::Continue(_) => Ok(CF::Continue),
            Stmt::Assign(name, expr, ln) => {
                let v = self.eval(expr)?;
                self.assign(name, v).map_err(|e| RuntimeError{line:*ln, msg:e.msg})?;
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(base, idx, val, ln) => {
                let bv = self.eval(base)?;
                let iv = self.eval(idx)?;
                let vv = self.eval(val)?;
                match (&bv, &iv) {
                    (Value::List(items), Value::Int(i)) => {
                        let i = *i as usize;
                        let items = items.borrow();
                        if i >= items.len() {
                            return Err(RuntimeError{line:*ln, msg:format!("index {} out of range for length {}", *i, items.len())});
                        }
                        drop(items);
                        items.borrow_mut()[i] = vv;
                    }
                    (Value::List(_), _) => return Err(RuntimeError{line:*ln, msg:format!("cannot index list with {}", type_name(&iv))}),
                    _ => return Err(RuntimeError{line:*ln, msg:format!("cannot assign into {}", type_name(&bv))}),
                }
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(e, _) => {
                self.eval(e)?;
                Ok(CF::Normal)
            }
        }
    }
}

// ===== MAIN =====

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = std::fs::read_to_string(&path).unwrap();
    let toks = lex(&src);
    let mut parser = Parser::new(toks);
    let program = parser.parse_program();
    let interp = Interp2::new();
    let result = interp.exec_body(&program);
    let mut out = interp.output.borrow().clone();
    if let Err(e) = result {
        out.push_str(&format!("error at line {}: {}\n", e.line, e.msg));
    }
    let stdout = std::io::stdout();
    let mut w = stdout.lock();
    w.write_all(out.as_bytes()).unwrap();
    w.flush().unwrap();
}

use std::collections::HashMap;
use std::cell::RefCell;
use std::rc::Rc;
use std::io::Write;

// ===== TOKENS & LEXER =====

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Int(i64), Str(String), Ident(String),
    Eq, Ne, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LP, RP, LB, RB, LC, RC, Comma, Semi,
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil, Eof,
}

struct Token { t: Tok, line: usize }

fn lex(src: &str) -> Vec<Token> {
    let b = src.as_bytes();
    let mut pos = 0usize;
    let mut line = 1usize;
    let mut toks = Vec::new();
    while pos < b.len() {
        let c = b[pos];
        if c == b'\n' { line += 1; pos += 1; continue; }
        if c == b' ' || c == b'\t' || c == b'\r' { pos += 1; continue; }
        if c == b'#' { while pos < b.len() && b[pos] != b'\n' { pos += 1; } continue; }
        if c.is_ascii_digit() {
            let start = pos;
            while pos < b.len() && b[pos].is_ascii_digit() { pos += 1; }
            let v: i64 = src[start..pos].parse().unwrap();
            toks.push(Token{t:Tok::Int(v), line});
            continue;
        }
        if c == b'"' {
            pos += 1;
            let mut s = String::new();
            while pos < b.len() && b[pos] != b'"' {
                if b[pos] == b'\\' {
                    pos += 1;
                    match b[pos] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        _ => s.push(b[pos] as char),
                    }
                    pos += 1;
                } else {
                    s.push(b[pos] as char);
                    pos += 1;
                }
            }
            pos += 1; // skip closing "
            toks.push(Token{t:Tok::Str(s), line});
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let start = pos;
            while pos < b.len() && (b[pos].is_ascii_alphanumeric() || b[pos] == b'_') { pos += 1; }
            let word = &src[start..pos];
            let t = match word {
                "let" => Tok::Let, "fn" => Tok::Fn, "if" => Tok::If,
                "else" => Tok::Else, "while" => Tok::While, "for" => Tok::For,
                "in" => Tok::In, "return" => Tok::Return, "break" => Tok::Break,
                "continue" => Tok::Continue, "and" => Tok::And, "or" => Tok::Or,
                "not" => Tok::Not, "true" => Tok::True, "false" => Tok::False,
                "nil" => Tok::Nil,
                _ => Tok::Ident(word.to_string()),
            };
            toks.push(Token{t, line});
            continue;
        }
        let t = match c {
            b'(' => { pos+=1; Tok::LP }
            b')' => { pos+=1; Tok::RP }
            b'[' => { pos+=1; Tok::LB }
            b']' => { pos+=1; Tok::RB }
            b'{' => { pos+=1; Tok::LC }
            b'}' => { pos+=1; Tok::RC }
            b',' => { pos+=1; Tok::Comma }
            b';' => { pos+=1; Tok::Semi }
            b'+' => { pos+=1; Tok::Plus }
            b'-' => { pos+=1; Tok::Minus }
            b'*' => { pos+=1; Tok::Star }
            b'/' => { pos+=1; Tok::Slash }
            b'%' => { pos+=1; Tok::Percent }
            b'=' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Eq }
                else { pos+=1; Tok::Assign }
            }
            b'!' => { pos+=2; Tok::Ne }
            b'<' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Le }
                else { pos+=1; Tok::Lt }
            }
            b'>' => {
                if pos+1 < b.len() && b[pos+1] == b'=' { pos+=2; Tok::Ge }
                else { pos+=1; Tok::Gt }
            }
            _ => { pos+=1; Tok::Eof }
        };
        toks.push(Token{t, line});
    }
    toks.push(Token{t:Tok::Eof, line});
    toks
}

// ===== AST =====

#[derive(Clone, Debug)]
enum Expr {
    Int(i64, usize), Str(String, usize), Bool(bool, usize), Nil(usize),
    Ident(String, usize),
    BinOp(BinOpT, Box<Expr>, Box<Expr>, usize),
    Not(Box<Expr>, usize), Neg(Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>, usize),
    FnLit(Vec<String>, Vec<Stmt>, usize),
    And(Box<Expr>, Box<Expr>, usize),
    Or(Box<Expr>, Box<Expr>, usize),
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum BinOpT { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge }

#[derive(Clone, Debug)]
enum Stmt {
    Let(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If(Expr, Vec<Stmt>, Option<ElseBranch>, usize),
    While(Expr, Vec<Stmt>, usize),
    For(String, Expr, Vec<Stmt>, usize),
    Return(Option<Expr>, usize),
    Break(usize), Continue(usize),
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr, usize),
}

#[derive(Clone, Debug)]
enum ElseBranch { Block(Vec<Stmt>), IfStmt(Box<Stmt>) }

// ===== PARSER =====

struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn new(toks: Vec<Token>) -> Self { Parser{toks, pos:0} }
    fn peek(&self) -> &Tok { &self.toks[self.pos].t }
    fn line(&self) -> usize { self.toks[self.pos].line }
    fn advance(&mut self) -> &Token { let t = &self.toks[self.pos]; self.pos+=1; t }
    fn expect(&mut self, t: &Tok) { assert_eq!(&self.toks[self.pos].t, t, "expected {:?} got {:?}", t, self.toks[self.pos].t); self.pos+=1; }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut s = Vec::new();
        while *self.peek() != Tok::Eof { s.push(self.parse_stmt()); }
        s
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(&Tok::LC);
        let mut s = Vec::new();
        while *self.peek() != Tok::RC { s.push(self.parse_stmt()); }
        self.expect(&Tok::RC);
        s
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut p = Vec::new();
        if let Tok::Ident(_) = self.peek() {
            if let Tok::Ident(name) = self.advance().t.clone() { p.push(name); }
            while *self.peek() == Tok::Comma {
                self.advance();
                if let Tok::Ident(name) = self.advance().t.clone() { p.push(name); }
            }
        }
        p
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().clone() {
            Tok::Let => {
                self.advance();
                let name = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::Assign);
                let e = self.parse_expr();
                self.expect(&Tok::Semi);
                Stmt::Let(name, e, self.line())
            }
            Tok::Fn => {
                let ln = self.line();
                self.advance();
                let name = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::LP);
                let params = self.parse_params();
                self.expect(&Tok::RP);
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body, ln)
            }
            Tok::If => self.parse_if(),
            Tok::While => {
                let ln = self.line();
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body, ln)
            }
            Tok::For => {
                let ln = self.line();
                self.advance();
                let var = if let Tok::Ident(n) = self.advance().t.clone() { n } else { unreachable!() };
                self.expect(&Tok::In);
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(var, e, body, ln)
            }
            Tok::Return => {
                let ln = self.line();
                self.advance();
                let e = if *self.peek() == Tok::Semi { None } else { Some(self.parse_expr()) };
                self.expect(&Tok::Semi);
                Stmt::Return(e, ln)
            }
            Tok::Break => { let ln=self.line(); self.advance(); self.expect(&Tok::Semi); Stmt::Break(ln) }
            Tok::Continue => { let ln=self.line(); self.advance(); self.expect(&Tok::Semi); Stmt::Continue(ln) }
            _ => {
                let e = self.parse_expr();
                if *self.peek() == Tok::Assign {
                    self.advance();
                    match e {
                        Expr::Ident(name, ln) => {
                            let v = self.parse_expr();
                            self.expect(&Tok::Semi);
                            Stmt::Assign(name, v, ln)
                        }
                        Expr::Index(base, idx, ln) => {
                            let v = self.parse_expr();
                            self.expect(&Tok::Semi);
                            Stmt::IndexAssign(base, idx, v, ln)
                        }
                        _ => unreachable!()
                    }
                } else {
                    self.expect(&Tok::Semi);
                    Stmt::ExprStmt(e, self.line())
                }
            }
        }
    }

    fn parse_if(&mut self) -> Stmt {
        let ln = self.line();
        self.advance(); // 'if'
        let cond = self.parse_expr();
        let body = self.parse_block();
        let els = if *self.peek() == Tok::Else {
            self.advance();
            if *self.peek() == Tok::If {
                Some(ElseBranch::IfStmt(Box::new(self.parse_if())))
            } else {
                Some(ElseBranch::Block(self.parse_block()))
            }
        } else { None };
        Stmt::If(cond, body, els, ln)
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }
    fn parse_or(&mut self) -> Expr {
        let mut l = self.parse_and();
        while *self.peek() == Tok::Or {
            let ln = self.line(); self.advance();
            let r = self.parse_and();
            l = Expr::Or(Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_and(&mut self) -> Expr {
        let mut l = self.parse_not();
        while *self.peek() == Tok::And {
            let ln = self.line(); self.advance();
            let r = self.parse_not();
            l = Expr::And(Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_not(&mut self) -> Expr {
        if *self.peek() == Tok::Not {
            let ln = self.line(); self.advance();
            let e = self.parse_not();
            Expr::Not(Box::new(e), ln)
        } else { self.parse_cmp() }
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut l = self.parse_add();
        loop {
            let op = match self.peek() {
                Tok::Eq => BinOpT::Eq, Tok::Ne => BinOpT::Ne,
                Tok::Lt => BinOpT::Lt, Tok::Le => BinOpT::Le,
                Tok::Gt => BinOpT::Gt, Tok::Ge => BinOpT::Ge,
                _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_add();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_add(&mut self) -> Expr {
        let mut l = self.parse_mul();
        loop {
            let op = match self.peek() {
                Tok::Plus => BinOpT::Add, Tok::Minus => BinOpT::Sub, _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_mul();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_mul(&mut self) -> Expr {
        let mut l = self.parse_unary();
        loop {
            let op = match self.peek() {
                Tok::Star => BinOpT::Mul, Tok::Slash => BinOpT::Div, Tok::Percent => BinOpT::Mod, _ => break,
            };
            let ln = self.line(); self.advance();
            let r = self.parse_unary();
            l = Expr::BinOp(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_unary(&mut self) -> Expr {
        if *self.peek() == Tok::Minus {
            let ln = self.line(); self.advance();
            let e = self.parse_unary();
            Expr::Neg(Box::new(e), ln)
        } else { self.parse_postfix() }
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek() {
                Tok::LP => {
                    let ln = self.line(); self.advance();
                    let mut args = Vec::new();
                    if *self.peek() != Tok::RP {
                        args.push(self.parse_expr());
                        while *self.peek() == Tok::Comma { self.advance(); args.push(self.parse_expr()); }
                    }
                    self.expect(&Tok::RP);
                    e = Expr::Call(Box::new(e), args, ln);
                }
                Tok::LB => {
                    let ln = self.line(); self.advance();
                    let idx = self.parse_expr();
                    self.expect(&Tok::RB);
                    e = Expr::Index(Box::new(e), Box::new(idx), ln);
                }
                _ => break,
            }
        }
        e
    }
    fn parse_primary(&mut self) -> Expr {
        match self.peek().clone() {
            Tok::Int(v) => { let ln=self.line(); self.advance(); Expr::Int(v, ln) }
            Tok::Str(s) => { let ln=self.line(); self.advance(); Expr::Str(s, ln) }
            Tok::True => { let ln=self.line(); self.advance(); Expr::Bool(true, ln) }
            Tok::False => { let ln=self.line(); self.advance(); Expr::Bool(false, ln) }
            Tok::Nil => { let ln=self.line(); self.advance(); Expr::Nil(ln) }
            Tok::Ident(n) => { let ln=self.line(); self.advance(); Expr::Ident(n, ln) }
            Tok::LP => { self.advance(); let e = self.parse_expr(); self.expect(&Tok::RP); e }
            Tok::LB => {
                let ln = self.line(); self.advance();
                let mut items = Vec::new();
                if *self.peek() != Tok::RB {
                    items.push(self.parse_expr());
                    while *self.peek() == Tok::Comma { self.advance(); items.push(self.parse_expr()); }
                }
                self.expect(&Tok::RB);
                Expr::ListLit(items, ln)
            }
            Tok::Fn => {
                let ln = self.line(); self.advance();
                self.expect(&Tok::LP);
                let params = self.parse_params();
                self.expect(&Tok::RP);
                let body = self.parse_block();
                Expr::FnLit(params, body, ln)
            }
            _ => unreachable!()
        }
    }
}

// ===== VALUES =====

#[derive(Clone)]
enum Value {
    Int(i64), Bool(bool), Str(String),
    List(Rc<RefCell<Vec<Value>>>),
    Func(Rc<FuncData>),
    Nil,
}

enum FuncData {
    User { params: Vec<String>, body: Vec<Stmt>, captured: Rc<RefCell<Scope>> },
    Builtin(BuiltinKind),
}

#[derive(Clone, Copy, PartialEq)]
enum BuiltinKind { Print, Str, TypeOf, Len, Push, Pop, Range, Slice }

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

// ===== ERROR =====

struct RuntimeError { line: usize, msg: String }

// ===== INTERPRETER =====

enum CF { Normal, Break, Continue, Return(Value) }

struct Interp {
    current: RefCell<Rc<RefCell<Scope>>>,
    output: RefCell<String>,
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Nil => false,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Func(_) => true,
    }
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int", Value::Bool(_) => "bool", Value::Str(_) => "string",
        Value::List(_) => "list", Value::Func(_) => "function", Value::Nil => "nil",
    }
}

fn display(v: &Value, in_list: bool, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(b) => if *b {"true".to_string()} else {"false".to_string()},
        Value::Nil => "nil".to_string(),
        Value::Func(_) => "<fn>".to_string(),
        Value::Str(s) => {
            if in_list {
                let mut r = String::from("\"");
                for c in s.chars() {
                    match c {
                        '\\' => r.push_str("\\\\"),
                        '"' => r.push_str("\\\""),
                        '\n' => r.push_str("\\n"),
                        '\t' => r.push_str("\\t"),
                        _ => r.push(c),
                    }
                }
                r.push('"');
                r
            } else { s.clone() }
        }
        Value::List(items) => {
            let ptr = Rc::as_ptr(items) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let inner: Vec<String> = items.borrow().iter().map(|v| display(v, true, seen)).collect();
            seen.pop();
            format!("[{}]", inner.join(", "))
        }
    }
}

fn vals_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::List(x), Value::List(y)) => {
            let xb = x.borrow(); let yb = y.borrow();
            if xb.len() != yb.len() { return false; }
            xb.iter().zip(yb.iter()).all(|(a,b)| vals_eq(a,b))
        }
        (Value::Func(x), Value::Func(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}

impl Interp {
    fn new() -> Self {
        let builtins = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:None}));
        {
            let mut bs = builtins.borrow_mut();
            for (name, kind) in [
                ("print", BuiltinKind::Print), ("str", BuiltinKind::Str),
                ("type", BuiltinKind::TypeOf), ("len", BuiltinKind::Len),
                ("push", BuiltinKind::Push), ("pop", BuiltinKind::Pop),
                ("range", BuiltinKind::Range), ("slice", BuiltinKind::Slice),
            ] {
                bs.vars.insert(name.to_string(), Value::Func(Rc::new(FuncData::Builtin(kind))));
            }
        }
        let global = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(builtins)}));
        Interp { current: RefCell::new(global), output: RefCell::new(String::new()) }
    }

    fn cur(&self) -> Rc<RefCell<Scope>> { self.current.borrow().clone() }

    fn lookup(&self, name: &str) -> Option<Value> {
        let mut sc = self.cur();
        loop {
            let s = sc.borrow();
            if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
            if let Some(ref p) = s.parent {
                let p = p.clone();
                drop(s);
                sc = p;
            } else { return None; }
        }
    }

    fn assign(&self, name: &str, val: Value) -> Result<(), RuntimeError> {
        let mut sc = self.cur();
        loop {
            if sc.borrow().vars.contains_key(name) {
                sc.borrow_mut().vars.insert(name.to_string(), val);
                return Ok(());
            }
            let p = { let s = sc.borrow(); s.parent.clone() };
            match p { Some(p) => sc = p, None => return Err(RuntimeError{line:0, msg:format!("undefined variable {}", name)}) }
        }
    }

    fn eval(&self, e: &Expr) -> Result<Value, RuntimeError> {
        match e {
            Expr::Int(v, _) => Ok(Value::Int(*v)),
            Expr::Str(s, _) => Ok(Value::Str(s.clone())),
            Expr::Bool(b, _) => Ok(Value::Bool(*b)),
            Expr::Nil(_) => Ok(Value::Nil),
            Expr::Ident(name, ln) => {
                self.lookup(name).ok_or_else(|| RuntimeError{line:*ln, msg:format!("undefined variable {}", name)})
            }
            Expr::And(l, r, _) => {
                let lv = self.eval(l)?;
                if !truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Or(l, r, _) => {
                let lv = self.eval(l)?;
                if truthy(&lv) { Ok(lv) } else { self.eval(r) }
            }
            Expr::Not(e, _) => {
                let v = self.eval(e)?;
                Ok(Value::Bool(!truthy(&v)))
            }
            Expr::Neg(e, ln) => {
                let v = self.eval(e)?;
                match v {
                    Value::Int(n) => n.checked_neg().map(Value::Int).ok_or(RuntimeError{line:*ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:*ln, msg:format!("cannot apply - to {}", type_name(&v))})
                }
            }
            Expr::BinOp(op, l, r, ln) => {
                let lv = self.eval(l)?;
                let rv = self.eval(r)?;
                self.binop(*op, lv, rv, *ln)
            }
            Expr::Call(callee, args, ln) => {
                let cv = self.eval(callee)?;
                let mut argv = Vec::with_capacity(args.len());
                for a in args { argv.push(self.eval(a)?); }
                self.call(cv, argv, *ln)
            }
            Expr::Index(obj, idx, ln) => {
                let ov = self.eval(obj)?;
                let iv = self.eval(idx)?;
                self.index_read(&ov, &iv, *ln)
            }
            Expr::ListLit(items, _) => {
                let mut v = Vec::with_capacity(items.len());
                for it in items { v.push(self.eval(it)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body, _) => {
                Ok(Value::Func(Rc::new(FuncData::User{
                    params: params.clone(), body: body.clone(), captured: self.cur()
                })))
            }
        }
    }

    fn binop(&self, op: BinOpT, l: Value, r: Value, ln: usize) -> Result<Value, RuntimeError> {
        match op {
            BinOpT::Eq => Ok(Value::Bool(vals_eq(&l, &r))),
            BinOpT::Ne => Ok(Value::Bool(!vals_eq(&l, &r))),
            BinOpT::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                    (Value::List(a), Value::List(b)) => {
                        let mut v: Vec<Value> = a.borrow().iter().cloned().collect();
                        v.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply + to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Sub => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply - to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mul => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => a.checked_mul(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()}),
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply * to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Div => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        a.checked_div(*b).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply / to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Mod => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        if *b == 0 { return Err(RuntimeError{line:ln, msg:"division by zero".to_string()}); }
                        if *b == -1 { return Ok(Value::Int(0)); }
                        let q = a.checked_div(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        let qb = q.checked_mul(*b).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})?;
                        a.checked_sub(qb).map(Value::Int).ok_or(RuntimeError{line:ln, msg:"integer overflow".to_string()})
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply % to {} and {}", type_name(&l), type_name(&r))})
                }
            }
            BinOpT::Lt | BinOpT::Le | BinOpT::Gt | BinOpT::Ge => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let (a, b) = (*a, *b);
                        let res = match op { BinOpT::Lt=>a<b, BinOpT::Le=>a<=b, BinOpT::Gt=>a>b, _=>a>=b };
                        Ok(Value::Bool(res))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op { BinOpT::Lt=>a<b, BinOpT::Le=>a<=b, BinOpT::Gt=>a>b, _=>a>=b };
                        Ok(Value::Bool(res))
                    }
                    _ => Err(RuntimeError{line:ln, msg:format!("cannot apply {} to {} and {}",
                        match op { BinOpT::Lt=>"<", BinOpT::Le=>"<=", BinOpT::Gt=>">", _=>">=" },
                        type_name(&l), type_name(&r))}),
                }
            }
        }
    }

    fn index_read(&self, obj: &Value, idx: &Value, ln: usize) -> Result<Value, RuntimeError> {
        match (obj, idx) {
            (Value::List(items), Value::Int(i)) => {
                let items = items.borrow();
                let i = *i as usize;
                if i >= items.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, items.len())});
                }
                Ok(items[i].clone())
            }
            (Value::Str(s), Value::Int(i)) => {
                let i = *i as usize;
                if i >= s.len() {
                    return Err(RuntimeError{line:ln, msg:format!("index {} out of range for length {}", *i, s.len())});
                }
                Ok(Value::Str(s[i..i+1].to_string()))
            }
            (Value::List(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index list with {}", type_name(idx))}),
            (Value::Str(_), _) => Err(RuntimeError{line:ln, msg:format!("cannot index string with {}", type_name(idx))}),
            _ => Err(RuntimeError{line:ln, msg:format!("cannot index {} with {}", type_name(obj), type_name(idx))}),
        }
    }

    fn call(&self, cv: Value, args: Vec<Value>, ln: usize) -> Result<Value, RuntimeError> {
        match &*cv {
            FuncData::Builtin(kind) => {
                let expected: i32 = match kind {
                    BuiltinKind::Print => -1,
                    BuiltinKind::Str | BuiltinKind::TypeOf | BuiltinKind::Len | BuiltinKind::Pop => 1,
                    BuiltinKind::Push | BuiltinKind::Range => 2,
                    BuiltinKind::Slice => 3,
                };
                if expected >= 0 && args.len() != expected as usize {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", expected, args.len())});
                }
                self.call_builtin(*kind, &args, ln)
            }
            FuncData::User{params, body, captured} => {
                if args.len() != params.len() {
                    return Err(RuntimeError{line:ln, msg:format!("expected {} arguments, got {}", params.len(), args.len())});
                }
                let mut vars = HashMap::new();
                for (p, a) in params.iter().zip(args.into_iter()) { vars.insert(p.clone(), a); }
                let new_scope = Rc::new(RefCell::new(Scope{vars, parent:Some(captured.clone())}));
                let old = self.current.borrow().clone();
                *self.current.borrow_mut() = new_scope;
                let result = self.exec_body(body);
                *self.current.borrow_mut() = old;
                match result? {
                    CF::Return(v) => Ok(v),
                    _ => Ok(Value::Nil),
                }
            }
        }
    }

    fn call_builtin(&self, kind: BuiltinKind, args: &[Value], ln: usize) -> Result<Value, RuntimeError> {
        let bad = |name: &str| RuntimeError{line:ln, msg:format!("bad argument to {}", name)};
        match kind {
            BuiltinKind::Print => {
                let parts: Vec<String> = args.iter().map(|v| display(v, false, &mut vec![])).collect();
                self.output.borrow_mut().push_str(&parts.join(" "));
                self.output.borrow_mut().push('\n');
                Ok(Value::Nil)
            }
            BuiltinKind::Str => Ok(Value::Str(display(&args[0], false, &mut vec![]))),
            BuiltinKind::TypeOf => Ok(Value::Str(type_name(&args[0]).to_string())),
            BuiltinKind::Len => {
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(bad("len"))
                }
            }
            BuiltinKind::Push => {
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(bad("push"))
                }
            }
            BuiltinKind::Pop => {
                match &args[0] {
                    Value::List(l) => {
                        l.borrow_mut().pop().ok_or_else(|| bad("pop"))
                    }
                    _ => Err(bad("pop"))
                }
            }
            BuiltinKind::Range => {
                match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Value::Int(i)); i += 1; }
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(bad("range"))
                }
            }
            BuiltinKind::Slice => {
                match (&args[0], &args[1], &args[2]) {
                    (Value::Str(s), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        if a > b || b > s.len() { return Err(bad("slice")); }
                        Ok(Value::Str(s[a..b].to_string()))
                    }
                    (Value::List(l), Value::Int(a), Value::Int(b)) => {
                        let a = *a as usize; let b = *b as usize;
                        let items = l.borrow();
                        if a > b || b > items.len() { return Err(bad("slice")); }
                        Ok(Value::List(Rc::new(RefCell::new(items[a..b].to_vec()))))
                    }
                    _ => Err(bad("slice"))
                }
            }
        }
    }

    fn exec_body(&self, stmts: &[Stmt]) -> Result<CF, RuntimeError> {
        for s in stmts {
            match self.exec_stmt(s)? {
                CF::Normal => continue,
                other => return Ok(other),
            }
        }
        Ok(CF::Normal)
    }

    fn exec_block(&self, stmts: &[Stmt]) -> Result<CF, RuntimeError> {
        let old = self.current.borrow().clone();
        let new = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(old.clone())}));
        *self.current.borrow_mut() = new;
        let r = self.exec_body(stmts);
        *self.current.borrow_mut() = old;
        r
    }

    fn exec_stmt(&self, s: &Stmt) -> Result<CF, RuntimeError> {
        match s {
            Stmt::Let(name, expr, _) => {
                let v = self.eval(expr)?;
                self.cur().borrow_mut().vars.insert(name.clone(), v);
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, _) => {
                let fv = Value::Func(Rc::new(FuncData::User{
                    params: params.clone(), body: body.clone(), captured: self.cur()
                }));
                self.cur().borrow_mut().vars.insert(name.clone(), fv);
                Ok(CF::Normal)
            }
            Stmt::If(cond, body, els, _) => {
                let cv = self.eval(cond)?;
                if truthy(&cv) {
                    self.exec_block(body)
                } else {
                    match els {
                        Some(ElseBranch::Block(b)) => self.exec_block(b),
                        Some(ElseBranch::IfStmt(s)) => self.exec_stmt(s),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body, _) => {
                loop {
                    let cv = self.eval(cond)?;
                    if !truthy(&cv) { break; }
                    match self.exec_block(body)? {
                        CF::Break => break,
                        CF::Continue => continue,
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => {}
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, expr, body, ln) => {
                let list_val = self.eval(expr)?;
                let list = match &list_val {
                    Value::List(l) => l.clone(),
                    _ => return Err(RuntimeError{line:*ln, msg:format!("cannot iterate {}", type_name(&list_val))}),
                };
                let mut i: usize = 0;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let old = self.current.borrow().clone();
                    let mut vars = HashMap::new();
                    vars.insert(var.clone(), elem);
                    let new_scope = Rc::new(RefCell::new(Scope{vars, parent:Some(old.clone())}));
                    *self.current.borrow_mut() = new_scope;
                    let r = self.exec_body(body);
                    *self.current.borrow_mut() = old;
                    match r? {
                        CF::Break => break,
                        CF::Continue => { i += 1; continue; }
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => { i += 1; }
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::Return(expr, _) => {
                let v = match expr { Some(e) => self.eval(e)?, None => Value::Nil };
                Ok(CF::Return(v))
            }
            Stmt::Break(_) => Ok(CF::Break),
            Stmt::Continue(_) => Ok(CF::Continue),
            Stmt::Assign(name, expr, ln) => {
                let v = self.eval(expr)?;
                self.assign(name, v).map_err(|e| RuntimeError{line:*ln, msg:e.msg})?;
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(base, idx, val, ln) => {
                let bv = self.eval(base)?;
                let iv = self.eval(idx)?;
                let vv = self.eval(val)?;
                match (&bv, &iv) {
                    (Value::List(items), Value::Int(i)) => {
                        let i = *i as usize;
                        let len = items.borrow().len();
                        if i >= len {
                            return Err(RuntimeError{line:*ln, msg:format!("index {} out of range for length {}", *i, len)});
                        }
                        items.borrow_mut()[i] = vv;
                    }
                    (Value::List(_), _) => return Err(RuntimeError{line:*ln, msg:format!("cannot index list with {}", type_name(&iv))}),
                    _ => return Err(RuntimeError{line:*ln, msg:format!("cannot assign into {}", type_name(&bv))}),
                }
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(e, _) => {
                self.eval(e)?;
                Ok(CF::Normal)
            }
        }
    }
}

// ===== MAIN =====

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = std::fs::read_to_string(&path).unwrap();
    let toks = lex(&src);
    let mut parser = Parser::new(toks);
    let program = parser.parse_program();
    let interp = Interp::new();
    let result = interp.exec_body(&program);
    let mut out = interp.output.borrow().clone();
    if let Err(e) = result {
        out.push_str(&format!("error at line {}: {}\n", e.line, e.msg));
    }
    let stdout = std::io::stdout();
    let mut w = stdout.lock();
    w.write_all(out.as_bytes()).unwrap();
    w.flush().unwrap();
}

import Foundation

let crcTable: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var crc = UInt32(i)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
        table[i] = crc
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc = crcTable[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

func splitIntoLines(_ content: [UInt8]) -> [[UInt8]] {
    if content.isEmpty { return [] }
    var lines: [[UInt8]] = []
    var start = 0
    for i in 0..<content.count {
        if content[i] == 0x0A {
            lines.append(Array(content[start...i]))
            start = i + 1
        }
    }
    if start < content.count {
        lines.append(Array(content[start...]))
    }
    return lines
}

func joinLines(_ lines: [[UInt8]]) -> [UInt8] {
    var result: [UInt8] = []
    for line in lines {
        result.append(contentsOf: line)
    }
    return result
}

func hasPrefix(_ bytes: [UInt8], _ str: String) -> Bool {
    let prefix = Array(str.utf8)
    if bytes.count < prefix.count { return false }
    for i in 0..<prefix.count {
        if bytes[i] != prefix[i] { return false }
    }
    return true
}

enum Kind: String {
    case create
    case delete
    case modify
}

struct Hunk {
    let a: Int
    let b: Int
    let c: Int
    let d: Int
    let oldLines: [[UInt8]]
    let newLines: [[UInt8]]
    let malformed: Bool
}

struct Section {
    let path: String
    let kind: Kind
    let hunks: [Hunk]
}

enum HunkResult {
    case applied(position: Int, offset: Int)
    case rejected
    case malformed
}

func parseHunkHeader(_ line: [UInt8]) -> (Int, Int, Int, Int) {
    var idx = 4 // skip "@@ -"
    func parseNum() -> Int {
        var num = 0
        while idx < line.count && line[idx] >= 0x30 && line[idx] <= 0x39 {
            num = num * 10 + Int(line[idx] - 0x30)
            idx += 1
        }
        return num
    }
    let a = parseNum()
    var b = 1
    if idx < line.count && line[idx] == 0x2C {
        idx += 1
        b = parseNum()
    }
    idx += 2 // skip " +"
    let c = parseNum()
    var d = 1
    if idx < line.count && line[idx] == 0x2C {
        idx += 1
        d = parseNum()
    }
    return (a, b, c, d)
}

func parseDiff(_ diffLines: [[UInt8]]) -> [Section] {
    var sections: [Section] = []
    var i = 0
    while i < diffLines.count {
        if hasPrefix(diffLines[i], "diff --git a/") {
            let line = diffLines[i]
            let prefixLen = Array("diff --git a/".utf8).count
            let rest = Array(line[prefixLen...])
            // Find first space (paths have no spaces)
            guard let spaceIdx = rest.firstIndex(of: 0x20) else { i += 1; continue }
            let pathBytes = Array(rest[..<spaceIdx])
            let path = String(bytes: pathBytes, encoding: .utf8) ?? ""
            i += 1

            var kind: Kind = .modify
            while i < diffLines.count {
                let l = diffLines[i]
                if hasPrefix(l, "new file mode ") {
                    kind = .create; i += 1
                } else if hasPrefix(l, "deleted file mode ") {
                    kind = .delete; i += 1
                } else if hasPrefix(l, "index ") {
                    i += 1
                } else if hasPrefix(l, "--- ") {
                    i += 1
                } else if hasPrefix(l, "+++ ") {
                    i += 1
                } else {
                    break
                }
            }

            var hunks: [Hunk] = []
            while i < diffLines.count {
                let l = diffLines[i]
                if hasPrefix(l, "@@ ") {
                    let (a, b, c, d) = parseHunkHeader(l)
                    i += 1
                    var bodyLines: [(UInt8, [UInt8])] = []
                    while i < diffLines.count {
                        let bl = diffLines[i]
                        if bl.isEmpty { break }
                        let marker = bl[0]
                        if marker == 0x40 && hasPrefix(bl, "@@ ") { break }
                        if hasPrefix(bl, "diff --git ") { break }
                        let content = Array(bl[1...])
                        bodyLines.append((marker, content))
                        i += 1
                    }
                    var oldLines: [[UInt8]] = []
                    var newLines: [[UInt8]] = []
                    var j = 0
                    while j < bodyLines.count {
                        let (marker, content) = bodyLines[j]
                        if marker == 0x5C {
                            j += 1
                            continue
                        }
                        var lineBytes = content
                        var noNewline = false
                        if j + 1 < bodyLines.count && bodyLines[j + 1].0 == 0x5C {
                            noNewline = true
                            j += 1
                        }
                        if !noNewline {
                            lineBytes.append(0x0A)
                        }
                        switch marker {
                        case 0x20:
                            oldLines.append(lineBytes)
                            newLines.append(lineBytes)
                        case 0x2D:
                            oldLines.append(lineBytes)
                        case 0x2B:
                            newLines.append(lineBytes)
                        default:
                            break
                        }
                        j += 1
                    }
                    let malformed = (oldLines.count != b) || (newLines.count != d)
                    hunks.append(Hunk(a: a, b: b, c: c, d: d, oldLines: oldLines, newLines: newLines, malformed: malformed))
                } else if hasPrefix(l, "diff --git ") {
                    break
                } else {
                    i += 1
                }
            }
            sections.append(Section(path: path, kind: kind, hunks: hunks))
        } else {
            i += 1
        }
    }
    return sections
}

func linesMatch(_ content: [[UInt8]], _ oldLines: [[UInt8]], at p: Int) -> Bool {
    let startIdx = p - 1
    if startIdx < 0 || startIdx + oldLines.count > content.count { return false }
    for i in 0..<oldLines.count {
        if content[startIdx + i] != oldLines[i] { return false }
    }
    return true
}

func applyHunks(content: [[UInt8]], hunks: [Hunk]) -> (result: [[UInt8]], results: [HunkResult]) {
    var lines = content
    var delta = 0
    var results: [HunkResult] = []
    for hunk in hunks {
        if hunk.malformed {
            results.append(.malformed)
            continue
        }
        let P = hunk.a + delta
        if hunk.b == 0 {
            if P >= 0 && P <= lines.count {
                lines.insert(contentsOf: hunk.newLines, at: P)
                results.append(.applied(position: P, offset: 0))
                delta += hunk.d - hunk.b
            } else {
                results.append(.rejected)
            }
        } else {
            let maxP = lines.count - hunk.b + 1
            var found = false
            var matchedP = -1
            if maxP >= 1 {
                var k = 0
                while true {
                    let p1 = P - k
                    if p1 >= 1 && p1 <= maxP {
                        if linesMatch(lines, hunk.oldLines, at: p1) {
                            found = true; matchedP = p1; break
                        }
                    }
                    if k > 0 {
                        let p2 = P + k
                        if p2 >= 1 && p2 <= maxP {
                            if linesMatch(lines, hunk.oldLines, at: p2) {
                                found = true; matchedP = p2; break
                            }
                        }
                    }
                    let leftDone = (P - k) < 1
                    let rightDone = (P + k) > maxP
                    if leftDone && rightDone { break }
                    k += 1
                }
            }
            if found {
                let startIdx = matchedP - 1
                lines.removeSubrange(startIdx..<startIdx + hunk.b)
                lines.insert(contentsOf: hunk.newLines, at: startIdx)
                let offset = matchedP - P
                results.append(.applied(position: matchedP, offset: offset))
                delta += hunk.d - hunk.b
            } else {
                results.append(.rejected)
            }
        }
    }
    return (lines, results)
}

// Main
let dir = CommandLine.arguments[1]
let diffPath = "\(dir)/changes.diff"
let diffData = try! Data(contentsOf: URL(fileURLWithPath: diffPath))
let diffBytes = [UInt8](diffData)

var diffLines: [[UInt8]] = []
do {
    var start = 0
    for i in 0..<diffBytes.count {
        if diffBytes[i] == 0x0A {
            diffLines.append(Array(diffBytes[start..<i]))
            start = i + 1
        }
    }
    if start < diffBytes.count {
        diffLines.append(Array(diffBytes[start...]))
    }
}

let sections = parseDiff(diffLines)
let sorted = sections.sorted { s1, s2 in
    Array(s1.path.utf8).lexicographicallyPrecedes(Array(s2.path.utf8))
}

var output = ""
for section in sorted {
    output += "\(section.path): \(section.kind.rawValue)\n"
    let filePath = "\(dir)/tree/\(section.path)"
    let fileExists = FileManager.default.fileExists(atPath: filePath)

    if section.kind == .create {
        if fileExists {
            output += "  error: already exists\n"
            continue
        }
    } else {
        if !fileExists {
            output += "  error: not found\n"
            continue
        }
    }

    var content: [[UInt8]] = []
    if section.kind != .create {
        let fileData = try! Data(contentsOf: URL(fileURLWithPath: filePath))
        content = splitIntoLines([UInt8](fileData))
    }

    let (resultLines, hunkResults) = applyHunks(content: content, hunks: section.hunks)

    for (idx, hr) in hunkResults.enumerated() {
        let n = idx + 1
        switch hr {
