    static int compareBytes(byte[] a, byte[] b) {
        int len = Math.min(a.length, b.length);
        for (int i = 0; i < len; i++) {
            int cmp = (a[i] & 0xFF) - (b[i] & 0xFF);
            if (cmp != 0) return cmp;
        }
        return a.length - b.length;
    }

    static List<byte[]> splitDiffLines(byte[] data) {
        List<byte[]> lines = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                lines.add(Arrays.copyOfRange(data, start, i));
                start = i + 1;
            }
        }
        if (start < data.length) {
            lines.add(Arrays.copyOfRange(data, start, data.length));
        }
        return lines;
    }

    static List<byte[]> splitFileLines(byte[] content) {
        List<byte[]> lines = new ArrayList<>();
        if (content.length == 0) return lines;
        int start = 0;
        for (int i = 0; i < content.length; i++) {
            if (content[i] == '\n') {
                lines.add(Arrays.copyOfRange(content, start, i + 1));
                start = i + 1;
            }
        }
        if (start < content.length) {
            lines.add(Arrays.copyOfRange(content, start, content.length));
        }
        return lines;
    }

    static boolean startsWith(byte[] data, String prefix) {
        byte[] p = prefix.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        if (data.length < p.length) return false;
        for (int i = 0; i < p.length; i++) {
            if (data[i] != p[i]) return false;
        }
        return true;
    }

    static List<Section> parseDiff(byte[] diffBytes) {
        List<Section> sections = new ArrayList<>();
        List<byte[]> lines = splitDiffLines(diffBytes);

        int i = 0;
        while (i < lines.size()) {
            if (startsWith(lines.get(i), "diff --git ")) {
                Section sec = new Section();
                String lineStr = new String(lines.get(i), "UTF-8");
                String prefix = "diff --git a/";
                int pathStart = prefix.length();
                int spaceAfterPath = lineStr.indexOf(' ', pathStart);
                sec.path = lineStr.substring(pathStart, spaceAfterPath);
                sec.kind = "modify";
                i++;

                while (i < lines.size() && !startsWith(lines.get(i), "diff --git ")) {
                    byte[] l = lines.get(i);
                    String ls = new String(l, "UTF-8");

                    if (ls.startsWith("new file mode ")) {
                        sec.kind = "create";
                        i++;
                    } else if (ls.startsWith("deleted file mode ")) {
                        sec.kind = "delete";
                        i++;
                    } else if (ls.startsWith("index ")) {
                        i++;
                    } else if (ls.startsWith("--- ")) {
                        i++;
                    } else if (ls.startsWith("+++ ")) {
                        i++;
                    } else if (ls.startsWith("@@ ")) {
                        Hunk hunk = parseHunk(lines, i);
                        sec.hunks.add(hunk);
                        i = hunk.nextIndex;
                    } else {
                        i++;
                    }
                }
                sections.add(sec);
            } else {
                i++;
            }
        }
        return sections;
    }

    static Hunk parseHunk(List<byte[]> lines, int start) {
        Hunk hunk = new Hunk();
        String header = new String(lines.get(start), "UTF-8");
        Matcher m = Pattern.compile("@@ -(\\d+)(?:,(\\d+))? \\+(\\d+)(?:,(\\d+))? @@").matcher(header);
        if (m.find()) {
            hunk.a = Integer.parseInt(m.group(1));
            hunk.b = m.group(2) != null ? Integer.parseInt(m.group(2)) : 1;
            hunk.c = Integer.parseInt(m.group(3));
            hunk.d = m.group(4) != null ? Integer.parseInt(m.group(4)) : 1;
        }

        int i = start + 1;
        char lastMarker = 0;

        while (i < lines.size()) {
            byte[] l = lines.get(i);
            if (l.length == 0) {
                break;
            }
            char marker = (char) (l[0] & 0xFF);
            if (marker == '@' && startsWith(l, "@@ ")) break;
            if (marker == 'd' && startsWith(l, "diff --git ")) break;

            if (marker == '\\') {
                if (lastMarker == ' ') {
                    removeTrailingNewline(hunk.oldLines, hunk.oldLines.size() - 1);
                    removeTrailingNewline(hunk.newLines, hunk.newLines.size() - 1);
                } else if (lastMarker == '-') {
                    removeTrailingNewline(hunk.oldLines, hunk.oldLines.size() - 1);
                } else if (lastMarker == '+') {
                    removeTrailingNewline(hunk.newLines, hunk.newLines.size() - 1);
                }
                i++;
                continue;
            }

            byte[] content = Arrays.copyOfRange(l, 1, l.length);
            byte[] lineBytes = addNewline(content);

            if (marker == ' ') {
                hunk.oldLines.add(lineBytes);
                hunk.newLines.add(lineBytes.clone());
            } else if (marker == '-') {
                hunk.oldLines.add(lineBytes);
            } else if (marker == '+') {
                hunk.newLines.add(lineBytes);
            }

            lastMarker = marker;
            i++;
        }

        hunk.nextIndex = i;

        if (hunk.oldLines.size() != hunk.b || hunk.newLines.size() != hunk.d) {
            hunk.malformed = true;
        }

        return hunk;
    }

    static byte[] addNewline(byte[] content) {
        byte[] result = new byte[content.length + 1];
        System.arraycopy(content, 0, result, 0, content.length);
        result[content.length] = '\n';
        return result;
    }

    static void removeTrailingNewline(List<byte[]> lines, int idx) {
        if (idx < 0 || idx >= lines.size()) return;
        byte[] line = lines.get(idx);
        if (line.length > 0 && line[line.length - 1] == '\n') {
            lines.set(idx, Arrays.copyOfRange(line, 0, line.length - 1));
        }
    }

    static void processSection(Section sec, String dir, StringBuilder out) {
        out.append(sec.path).append(": ").append(sec.kind).append("\n");

        Path filePath = Paths.get(dir, "tree", sec.path);
        List<byte[]> content;

        if (sec.kind.equals("create")) {
            if (Files.exists(filePath)) {
                out.append("  error: already exists\n");
                return;
            }
            content = new ArrayList<>();
        } else {
            if (!Files.exists(filePath)) {
                out.append("  error: not found\n");
                return;
            }
            try {
                byte[] fileBytes = Files.readAllBytes(filePath);
                content = splitFileLines(fileBytes);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int delta = 0;
        boolean allApplied = true;

        for (int h = 0; h < sec.hunks.size(); h++) {
            Hunk hunk = sec.hunks.get(h);
            int hunkNum = h + 1;

            if (hunk.malformed) {
                out.append("  hunk ").append(hunkNum).append(": malformed\n");
                allApplied = false;
                continue;
            }

            int P = hunk.a + delta;

            if (hunk.b == 0) {
                if (P >= 0 && P <= content.size()) {
                    content.addAll(P, new ArrayList<>(hunk.newLines));
                    out.append("  hunk ").append(hunkNum).append(": applied at ").append(P).append(" (offset 0)\n");
                    delta += hunk.d - hunk.b;
                    hunk.applied = true;
                } else {
                    out.append("  hunk ").append(hunkNum).append(": rejected\n");
                    allApplied = false;
                }
            } else {
                int lineCount = content.size();
                int found = -1;

                if (hunk.b <= lineCount) {
                    int maxP = lineCount - hunk.b + 1;
                    for (int dist = 0; ; dist++) {
                        int p1 = P - dist;
                        if (p1 >= 1 && p1 <= maxP) {
                            if (matchAt(content, p1 - 1, hunk.oldLines)) {
                                found = p1;
                                break;
                            }
                        }
                        if (dist > 0) {
                            int p2 = P + dist;
                            if (p2 >= 1 && p2 <= maxP) {
                                if (matchAt(content, p2 - 1, hunk.oldLines)) {
                                    found = p2;
                                    break;
                                }
                            }
                        }
                        if (P - dist < 1 && P + dist > maxP) break;
                    }
                }

                if (found >= 0) {
                    int startIdx = found - 1;
                    for (int j = 0; j < hunk.b; j++) {
                        content.remove(startIdx);
                    }
                    content.addAll(startIdx, new ArrayList<>(hunk.newLines));
                    int offset = found - P;
                    String offStr = offset > 0 ? "+" + offset : "" + offset;
                    out.append("  hunk ").append(hunkNum).append(": applied at ").append(found)
                            .append(" (offset ").append(offStr).append(")\n");
                    delta += hunk.d - hunk.b;
                    hunk.applied = true;
                } else {
                    out.append("  hunk ").append(hunkNum).append(": rejected\n");
                    allApplied = false;
                }
            }
        }

        if (sec.kind.equals("delete") && allApplied && content.isEmpty()) {
            out.append("  result: deleted\n");
        } else {
            byte[] finalBytes = concatLines(content);
            CRC32 crc = new CRC32();
            crc.update(finalBytes);
            long crcVal = crc.getValue();
            out.append("  result: ").append(content.size()).append(" lines, crc32 ")
                    .append(String.format("%08x", crcVal)).append("\n");
        }
    }

    static boolean matchAt(List<byte[]> content, int startIdx, List<byte[]> oldLines) {
        for (int i = 0; i < oldLines.size(); i++) {
            if (!Arrays.equals(content.get(startIdx + i), oldLines.get(i))) {
                return false;
            }
        }
        return true;
    }

    static byte[] concatLines(List<byte[]> lines) {
        int totalLen = 0;
        for (byte[] l : lines) totalLen += l.length;
        byte[] result = new byte[totalLen];
        int pos = 0;
        for (byte[] l : lines) {
            System.arraycopy(l, 0, result, pos, l.length);
            pos += l.length;
        }
        return result;
    }
}

