function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) {
        crc = (crc >>> 1) ^ 0xEDB88320;
      } else {
        crc = crc >>> 1;
      }
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

interface FileLine {
  bytes: Buffer;
  hasNewline: boolean;
}

function splitLines(content: Buffer): FileLine[] {
  if (content.length === 0) return [];
  const lines: FileLine[] = [];
  let start = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 0x0A) {
      lines.push({ bytes: content.subarray(start, i), hasNewline: true });
      start = i + 1;
    }
  }
  if (start < content.length) {
    lines.push({ bytes: content.subarray(start), hasNewline: false });
  }
  return lines;
}

function linesToBuffer(lines: FileLine[]): Buffer {
  const parts: Buffer[] = [];
  for (const l of lines) {
    parts.push(l.bytes);
    if (l.hasNewline) {
      parts.push(Buffer.from([0x0A]));
    }
  }
  return Buffer.concat(parts);
}

