/* ============ ARENA ALLOCATOR ============ */
typedef struct ArenaBlock {
    struct ArenaBlock *next;
    char data[];
} ArenaBlock;

typedef struct {
    ArenaBlock *head;
    char *cur, *end;
} Arena;

static Arena g_arena;

static void arena_init(Arena *a) {
    a->head = NULL; a->cur = NULL; a->end = NULL;
}

static void *arena_alloc(Arena *a, size_t sz) {
    sz = (sz + 7) & ~(size_t)7;
    if (!a->cur || a->cur + sz > a->end) {
        size_t bsz = sz + (1 << 20);
        ArenaBlock *b = (ArenaBlock*)malloc(sizeof(ArenaBlock) + bsz);
        b->next = a->head; a->head = b;
        a->cur = b->data; a->end = b->data + bsz;
    }
    void *r = a->cur; a->cur += sz;
    return r;
}

static void *arena_calloc(Arena *a, size_t sz) {
    void *p = arena_alloc(a, sz);
    memset(p, 0, sz);
    return p;
}

/* ============ TOKENS ============ */
enum {
    TOK_INT, TOK_STR, TOK_IDENT,
    TOK_LET, TOK_FN, TOK_IF, TOK_ELSE, TOK_WHILE, TOK_FOR, TOK_IN,
    TOK_RETURN, TOK_BREAK, TOK_CONTINUE, TOK_AND, TOK_OR, TOK_NOT,
    TOK_TRUE, TOK_FALSE, TOK_NIL,
    TOK_EQ, TOK_NEQ, TOK_LE, TOK_GE, TOK_LT, TOK_GT,
