    TOK_LBRACE, TOK_RBRACE, TOK_COMMA, TOK_SEMI,
    TOK_EOF
};

typedef struct {
    int type, line;
    long long ival;
    char *sval; int slen;
} Token;

static Token *g_tokens;
static int g_ntokens, g_tokpos;

static const char *g_src;
static int g_src_len;

static const char *g_keywords[] = {
    "let","fn","if","else","while","for","in","return","break","continue",
    "and","or","not","true","false","nil", NULL
};
static const int g_kw_toks[] = {
    TOK_LET,TOK_FN,TOK_IF,TOK_ELSE,TOK_WHILE,TOK_FOR,TOK_IN,TOK_RETURN,
    TOK_BREAK,TOK_CONTINUE,TOK_AND,TOK_OR,TOK_NOT,TOK_TRUE,TOK_FALSE,TOK_NIL
};

static int is_kw(const char *s, int len) {
    for (int i = 0; g_keywords[i]; i++)
        if ((int)strlen(g_keywords[i]) == len && memcmp(s, g_keywords[i], len) == 0)
            return g_kw_toks[i];
    return -1;
}

static void lex(void) {
    int cap = 1024, n = 0;
    g_tokens = (Token*)malloc(cap * sizeof(Token));
    int line = 1;
    const char *p = g_src, *end = g_src + g_src_len;
    while (p < end) {
        if (*p == '\n') { line++; p++; continue; }
        if (*p == '\r' || *p == ' ' || *p == '\t') { p++; continue; }
        if (*p == '#') { while (p < end && *p != '\n') p++; continue; }
        if (n >= cap) { cap *= 2; g_tokens = (Token*)realloc(g_tokens, cap * sizeof(Token)); }
        Token *t = &g_tokens[n];
        t->line = line; t->ival = 0; t->sval = NULL; t->slen = 0;
        if (isdigit(*p)) {
            t->type = TOK_INT;
            long long v = 0;
            while (p < end && isdigit(*p)) { v = v * 10 + (*p - '0'); p++; }
            t->ival = v;
            n++; continue;
        }
        if (*p == '"') {
            p++; t->type = TOK_STR;
            int sc = 64, sl = 0;
            char *sb = (char*)malloc(sc);
            while (p < end && *p != '"') {
                if (*p == '\\') {
                    p++;
                    if (*p == 'n') { if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);} sb[sl++]='\n'; p++; }
                    else if (*p == 't') { if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);} sb[sl++]='\t'; p++; }
                    else if (*p == '"') { if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);} sb[sl++]='"'; p++; }
                    else if (*p == '\\') { if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);} sb[sl++]='\\'; p++; }
                    else { if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);} sb[sl++]='\\'; }
                } else {
                    if (sl+1>=sc){sc*=2;sb=(char*)realloc(sb,sc);}
                    sb[sl++] = *p++;
                }
            }
            if (p < end) p++; // skip closing "
            t->sval = sb; t->slen = sl;
            n++; continue;
        }
        if (isalpha(*p) || *p == '_') {
            const char *s = p;
            while (p < end && (isalnum(*p) || *p == '_')) p++;
            int len = (int)(p - s);
            int kw = is_kw(s, len);
            if (kw >= 0) { t->type = kw; }
            else {
                t->type = TOK_IDENT;
                t->sval = (char*)malloc(len + 1);
                memcpy(t->sval, s, len); t->sval[len] = 0; t->slen = len;
            }
            n++; continue;
        }
        /* operators */
        if (p+1 < end) {
            if (p[0]=='='&&p[1]=='='){t->type=TOK_EQ;p+=2;n++;continue;}
            if (p[0]=='!'&&p[1]=='='){t->type=TOK_NEQ;p+=2;n++;continue;}
            if (p[0]=='<'&&p[1]=='='){t->type=TOK_LE;p+=2;n++;continue;}
            if (p[0]=='>'&&p[1]=='='){t->type=TOK_GE;p+=2;n++;continue;}
        }
        switch(*p) {
            case '<': t->type=TOK_LT;p++;break;
            case '>': t->type=TOK_GT;p++;break;
            case '=': t->type=TOK_ASSIGN;p++;break;
            case '+': t->type=TOK_PLUS;p++;break;
            case '-': t->type=TOK_MINUS;p++;break;
            case '*': t->type=TOK_STAR;p++;break;
            case '/': t->type=TOK_SLASH;p++;break;
            case '%': t->type=TOK_PERCENT;p++;break;
            case '(': t->type=TOK_LPAREN;p++;break;
            case ')': t->type=TOK_RPAREN;p++;break;
            case '[': t->type=TOK_LBRACKET;p++;break;
            case ']': t->type=TOK_RBRACKET;p++;break;
            case '{': t->type=TOK_LBRACE;p++;break;
            case '}': t->type=TOK_RBRACE;p++;break;
            case ',': t->type=TOK_COMMA;p++;break;
            case ';': t->type=TOK_SEMI;p++;break;
            default: p++; continue;
        }
        n++;
    }
    if (n >= cap) { cap *= 2; g_tokens = (Token*)realloc(g_tokens, cap * sizeof(Token)); }
    g_tokens[n].type = TOK_EOF; g_tokens[n].line = line;
    g_ntokens = n + 1;
}

/* ============ AST ============ */
enum {
    EXPR_INT, EXPR_STR, EXPR_BOOL, EXPR_NIL, EXPR_IDENT,
    EXPR_BINOP, EXPR_UNOP, EXPR_CALL, EXPR_INDEX, EXPR_LIST, EXPR_FN,
    STMT_LET, STMT_FNDECL, STMT_IF, STMT_WHILE, STMT_FOR,
    STMT_RETURN, STMT_BREAK, STMT_CONTINUE, STMT_ASSIGN, STMT_IDXASSIGN,
    STMT_EXPR, STMT_BLOCK
};

enum { OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_MOD, OP_EQ, OP_NEQ,
       OP_LT, OP_LE, OP_GT, OP_GE, OP_AND, OP_OR, OP_NOT, OP_NEG };

typedef struct ASTNode ASTNode;
typedef struct { ASTNode **items; int n; } NodeList;

struct ASTNode {
    int type, line;
    union {
        long long ival;
        struct { char *s; int len; } str;
        struct { int op; ASTNode *l, *r; } bin;
        struct { int op; ASTNode *e; } un;
        struct { ASTNode *callee; ASTNode **args; int nargs; } call;
        struct { ASTNode *obj, *idx; } index;
        struct { ASTNode **elems; int nelems; } list;
        struct { char **params; int nparams; ASTNode *body; } fn;
        struct { char *name; ASTNode *expr; } let_;
        struct { char *name; ASTNode *expr; } assign;
        struct { ASTNode *obj, *idx, *val; } idxassign;
        struct { ASTNode *cond, *then_b, *else_b; } if_;
        struct { ASTNode *cond, *body; } while_;
        struct { char *var; ASTNode *iter, *body; } for_;
        struct { ASTNode *expr; } ret;
        struct { ASTNode **stmts; int nstmts; } block;
        struct { ASTNode *expr; } expr_stmt;
        bool bval;
    };
};

static ASTNode *mknode(int type, int line) {
    ASTNode *n = (ASTNode*)arena_calloc(&g_arena, sizeof(ASTNode));
    n->type = type; n->line = line;
    return n;
}

/* ============ PARSER ============ */
static Token *peek(void) { return &g_tokens[g_tokpos]; }
static Token *advance(void) { return &g_tokens[g_tokpos++]; }
static int match(int type) { if (peek()->type == type) { g_tokpos++; return 1; } return 0; }
static void expect(int type) { advance(); }

static ASTNode *parse_expr(void);
static ASTNode *parse_block(void);
static ASTNode *parse_stmt(void);

static ASTNode *parse_primary(void) {
    Token *t = peek();
    switch (t->type) {
        case TOK_INT: { advance(); ASTNode *n = mknode(EXPR_INT, t->line); n->ival = t->ival; return n; }
        case TOK_STR: { advance(); ASTNode *n = mknode(EXPR_STR, t->line); n->str.s = t->sval; n->str.len = t->slen; return n; }
        case TOK_TRUE: { advance(); ASTNode *n = mknode(EXPR_BOOL, t->line); n->bval = true; return n; }
        case TOK_FALSE: { advance(); ASTNode *n = mknode(EXPR_BOOL, t->line); n->bval = false; return n; }
        case TOK_NIL: { advance(); ASTNode *n = mknode(EXPR_NIL, t->line); return n; }
        case TOK_IDENT: { advance(); ASTNode *n = mknode(EXPR_IDENT, t->line); n->str.s = t->sval; n->str.len = t->slen; return n; }
        case TOK_LPAREN: { advance(); ASTNode *e = parse_expr(); expect(TOK_RPAREN); return e; }
        case TOK_LBRACKET: {
            advance();
            ASTNode *n = mknode(EXPR_LIST, t->line);
            int cap = 8, cnt = 0;
            ASTNode **elems = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*));
            if (peek()->type != TOK_RBRACKET) {
                elems[cnt++] = parse_expr();
                while (match(TOK_COMMA)) {
                    if (cnt >= cap) { cap *= 2; elems = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*)); /* can't realloc arena... */ }
                    elems[cnt++] = parse_expr();
                }
            }
            expect(TOK_RBRACKET);
            n->list.elems = elems; n->list.nelems = cnt;
            return n;
        }
        case TOK_FN: {
            advance();
            ASTNode *n = mknode(EXPR_FN, t->line);
            expect(TOK_LPAREN);
            int cap = 4, cnt = 0;
            char **params = (char**)arena_alloc(&g_arena, cap * sizeof(char*));
            if (peek()->type == TOK_IDENT) {
                params[cnt++] = advance()->sval;
                while (match(TOK_COMMA)) {
                    params[cnt++] = advance()->sval;
                }
            }
            expect(TOK_RPAREN);
            n->fn.params = params; n->fn.nparams = cnt;
            n->fn.body = parse_block();
            return n;
        }
        default: { advance(); ASTNode *n = mknode(EXPR_NIL, t->line); return n; }
    }
}

static ASTNode *parse_postfix(void) {
    ASTNode *node = parse_primary();
    while (1) {
        if (peek()->type == TOK_LPAREN) {
            Token *t = advance();
            ASTNode *n = mknode(EXPR_CALL, t->line);
            n->call.callee = node;
            int cap = 4, cnt = 0;
            ASTNode **args = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*));
            if (peek()->type != TOK_RPAREN) {
                args[cnt++] = parse_expr();
                while (match(TOK_COMMA)) {
                    args[cnt++] = parse_expr();
                }
            }
            expect(TOK_RPAREN);
            n->call.args = args; n->call.nargs = cnt;
            node = n;
        } else if (peek()->type == TOK_LBRACKET) {
            Token *t = advance();
            ASTNode *n = mknode(EXPR_INDEX, t->line);
            n->index.obj = node;
            n->index.idx = parse_expr();
            expect(TOK_RBRACKET);
            node = n;
        } else break;
    }
    return node;
}

static ASTNode *parse_unary(void) {
    if (peek()->type == TOK_MINUS) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_UNOP, t->line);
        n->un.op = OP_NEG;
        n->un.e = parse_unary();
        return n;
    }
    return parse_postfix();
}

static ASTNode *parse_mul(void) {
    ASTNode *l = parse_unary();
    while (peek()->type == TOK_STAR || peek()->type == TOK_SLASH || peek()->type == TOK_PERCENT) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_BINOP, t->line);
        n->bin.l = l;
        n->bin.op = (t->type == TOK_STAR) ? OP_MUL : (t->type == TOK_SLASH) ? OP_DIV : OP_MOD;
        n->bin.r = parse_unary();
        l = n;
    }
    return l;
}

static ASTNode *parse_add(void) {
    ASTNode *l = parse_mul();
    while (peek()->type == TOK_PLUS || peek()->type == TOK_MINUS) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_BINOP, t->line);
        n->bin.l = l;
        n->bin.op = (t->type == TOK_PLUS) ? OP_ADD : OP_SUB;
        n->bin.r = parse_mul();
        l = n;
    }
    return l;
}

static ASTNode *parse_cmp(void) {
    ASTNode *l = parse_add();
    while (peek()->type == TOK_EQ || peek()->type == TOK_NEQ || peek()->type == TOK_LT ||
           peek()->type == TOK_LE || peek()->type == TOK_GT || peek()->type == TOK_GE) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_BINOP, t->line);
        n->bin.l = l;
        switch(t->type) {
            case TOK_EQ: n->bin.op=OP_EQ; break;
            case TOK_NEQ: n->bin.op=OP_NEQ; break;
            case TOK_LT: n->bin.op=OP_LT; break;
            case TOK_LE: n->bin.op=OP_LE; break;
            case TOK_GT: n->bin.op=OP_GT; break;
            case TOK_GE: n->bin.op=OP_GE; break;
        }
        n->bin.r = parse_add();
        l = n;
    }
    return l;
}

static ASTNode *parse_not(void) {
    if (peek()->type == TOK_NOT) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_UNOP, t->line);
        n->un.op = OP_NOT;
        n->un.e = parse_not();
        return n;
    }
    return parse_cmp();
}

static ASTNode *parse_and(void) {
    ASTNode *l = parse_not();
    while (peek()->type == TOK_AND) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_BINOP, t->line);
        n->bin.l = l; n->bin.op = OP_AND;
        n->bin.r = parse_not();
        l = n;
    }
    return l;
}

static ASTNode *parse_or(void) {
    ASTNode *l = parse_and();
    while (peek()->type == TOK_OR) {
        Token *t = advance();
        ASTNode *n = mknode(EXPR_BINOP, t->line);
        n->bin.l = l; n->bin.op = OP_OR;
        n->bin.r = parse_and();
        l = n;
    }
    return l;
}

static ASTNode *parse_expr(void) { return parse_or(); }

static ASTNode *parse_block(void) {
    Token *t = advance(); /* { */
    ASTNode *n = mknode(STMT_BLOCK, t->line);
    int cap = 8, cnt = 0;
    ASTNode **stmts = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*));
    while (peek()->type != TOK_RBRACE && peek()->type != TOK_EOF) {
        if (cnt >= cap) { cap *= 2; stmts = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*)); }
        stmts[cnt++] = parse_stmt();
    }
    expect(TOK_RBRACE);
    n->block.stmts = stmts; n->block.nstmts = cnt;
    return n;
}

static ASTNode *parse_if_stmt(void) {
    Token *t = advance(); /* if */
    ASTNode *n = mknode(STMT_IF, t->line);
    n->if_.cond = parse_expr();
    n->if_.then_b = parse_block();
    if (peek()->type == TOK_ELSE) {
        advance();
        if (peek()->type == TOK_IF) {
            n->if_.else_b = parse_if_stmt();
        } else {
            n->if_.else_b = parse_block();
        }
    } else {
        n->if_.else_b = NULL;
    }
    return n;
}

static ASTNode *parse_stmt(void) {
    Token *t = peek();
    switch (t->type) {
        case TOK_LET: {
            advance();
            char *name = advance()->sval;
            expect(TOK_ASSIGN);
            ASTNode *e = parse_expr();
            expect(TOK_SEMI);
            ASTNode *n = mknode(STMT_LET, t->line);
            n->let_.name = name; n->let_.expr = e;
            return n;
        }
        case TOK_FN: {
            advance();
            char *name = advance()->sval;
            expect(TOK_LPAREN);
            int cap = 4, cnt = 0;
            char **params = (char**)arena_alloc(&g_arena, cap * sizeof(char*));
            if (peek()->type == TOK_IDENT) {
                params[cnt++] = advance()->sval;
                while (match(TOK_COMMA)) params[cnt++] = advance()->sval;
            }
            expect(TOK_RPAREN);
            ASTNode *body = parse_block();
            ASTNode *n = mknode(STMT_FNDECL, t->line);
            n->fn.params = params; n->fn.nparams = cnt; n->fn.body = body;
            n->str.s = name; /* reuse str for name */
            return n;
        }
        case TOK_IF: return parse_if_stmt();
        case TOK_WHILE: {
            advance();
            ASTNode *n = mknode(STMT_WHILE, t->line);
            n->while_.cond = parse_expr();
            n->while_.body = parse_block();
            return n;
        }
        case TOK_FOR: {
            advance();
            char *var = advance()->sval;
            expect(TOK_IN);
            ASTNode *n = mknode(STMT_FOR, t->line);
            n->for_.var = var;
            n->for_.iter = parse_expr();
            n->for_.body = parse_block();
            return n;
        }
        case TOK_RETURN: {
            advance();
            ASTNode *n = mknode(STMT_RETURN, t->line);
            if (peek()->type == TOK_SEMI) { n->ret.expr = NULL; }
            else { n->ret.expr = parse_expr(); }
            expect(TOK_SEMI);
            return n;
        }
        case TOK_BREAK: { advance(); expect(TOK_SEMI); return mknode(STMT_BREAK, t->line); }
        case TOK_CONTINUE: { advance(); expect(TOK_SEMI); return mknode(STMT_CONTINUE, t->line); }
        case TOK_IDENT: {
            if (peek()->type == TOK_IDENT && g_tokens[g_tokpos+1].type == TOK_ASSIGN) {
                char *name = advance()->sval;
                advance(); /* = */
                ASTNode *e = parse_expr();
                expect(TOK_SEMI);
                ASTNode *n = mknode(STMT_ASSIGN, t->line);
                n->assign.name = name; n->assign.expr = e;
                return n;
            }
            /* fall through to expression */
        }
        default: {
            ASTNode *e = parse_expr();
            if (peek()->type == TOK_ASSIGN && e->type == EXPR_INDEX) {
                advance(); /* = */
                ASTNode *v = parse_expr();
                expect(TOK_SEMI);
                ASTNode *n = mknode(STMT_IDXASSIGN, t->line);
                n->idxassign.obj = e->index.obj;
                n->idxassign.idx = e->index.idx;
                n->idxassign.val = v;
                n->line = e->line; /* line of [ */
                return n;
            }
            expect(TOK_SEMI);
            ASTNode *n = mknode(STMT_EXPR, t->line);
            n->expr_stmt.expr = e;
            return n;
        }
    }
}

static ASTNode *parse_program(void) {
    ASTNode *n = mknode(STMT_BLOCK, 1);
    int cap = 64, cnt = 0;
    ASTNode **stmts = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*));
    while (peek()->type != TOK_EOF) {
        if (cnt >= cap) { cap *= 2; stmts = (ASTNode**)arena_alloc(&g_arena, cap * sizeof(ASTNode*)); }
        stmts[cnt++] = parse_stmt();
    }
    n->block.stmts = stmts; n->block.nstmts = cnt;
    return n;
}

/* ============ VALUES ============ */
enum { VAL_INT, VAL_BOOL, VAL_STRING, VAL_LIST, VAL_FUNC, VAL_NIL };

typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;

typedef struct {
    int type;
    union {
        long long ival;
        bool bval;
        struct { char *data; int len; } sval;
        List *lval;
        Func *fval;
    };
} Val;

struct List {
    Val *items;
    int len, cap;
};

struct Func {
    char **params;
    int nparams;
    ASTNode *body;
    Scope *captured;
    int is_builtin;
    int builtin_id;
};

struct Scope {
    Scope *parent;
    struct { char *name; Val val; } *vars;
    int nvars, cap;
};

static Val mk_int(long long v) { Val x; x.type=VAL_INT; x.ival=v; return x; }
static Val mk_bool(bool v) { Val x; x.type=VAL_BOOL; x.bval=v; return x; }
static Val mk_nil(void) { Val x; x.type=VAL_NIL; return x; }
static Val mk_str(const char *s, int len) { Val x; x.type=VAL_STRING; x.sval.data=(char*)s; x.sval.len=len; return x; }
static Val mk_list(List *l) { Val x; x.type=VAL_LIST; x.lval=l; return x; }
static Val mk_func(Func *f) { Val x; x.type=VAL_FUNC; x.fval=f; return x; }

static List *new_list(void) {
    List *l = (List*)arena_alloc(&g_arena, sizeof(List));
    l->items = (Val*)arena_alloc(&g_arena, 8 * sizeof(Val));
    l->len = 0; l->cap = 8;
    return l;
}

static void list_push(List *l, Val v) {
    if (l->len >= l->cap) {
        l->cap *= 2;
        l->items = (Val*)arena_alloc(&g_arena, l->cap * sizeof(Val));
        /* can't realloc arena... need different approach */
    }
    l->items[l->len++] = v;
}

/* Actually, let me use malloc for list items to allow growth */
static void list_push2(List *l, Val v) {
    if (l->len >= l->cap) {
        l->cap *= 2;
        l->items = (Val*)realloc(l->items, l->cap * sizeof(Val));
    }
    l->items[l->len++] = v;
}

static Scope *new_scope(Scope *parent) {
    Scope *s = (Scope*)arena_alloc(&g_arena, sizeof(Scope));
    s->parent = parent;
    s->vars = NULL; s->nvars = 0; s->cap = 0;
    return s;
}

static void scope_add(Scope *s, const char *name, Val v) {
    if (s->nvars >= s->cap) {
        s->cap = s->cap ? s->cap * 2 : 4;
        s->vars = (typeof(s->vars[0])*)realloc(s->vars, s->cap * sizeof(s->vars[0]));
    }
    s->vars[s->nvars].name = (char*)name;
    s->vars[s->nvars].val = v;
    s->nvars++;
}

static Val *scope_lookup(Scope *s, const char *name) {
    while (s) {
        for (int i = s->nvars - 1; i >= 0; i--) {
            if (strcmp(s->vars[i].name, name) == 0)
                return &s->vars[i].val;
        }
        s = s->parent;
    }
    return NULL;
}

/* ============ ERROR HANDLING ============ */
static void die(int line, const char *fmt, ...) {
    fflush(stdout);
    fprintf(stdout, "error at line %d: ", line);
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stdout, fmt, ap);
    va_end(ap);
    fprintf(stdout, "\n");
    fflush(stdout);
    exit(0);
}

static const char *type_name(Val v) {
    switch (v.type) {
        case VAL_INT: return "int";
        case VAL_BOOL: return "bool";
        case VAL_STRING: return "string";
        case VAL_LIST: return "list";
        case VAL_FUNC: return "function";
        case VAL_NIL: return "nil";
    }
    return "?";
}

static bool is_truthy(Val v) {
    switch (v.type) {
        case VAL_BOOL: return v.bval;
        case VAL_NIL: return false;
        case VAL_INT: return v.ival != 0;
        case VAL_STRING: return v.sval.len != 0;
        case VAL_LIST: return v.lval->len != 0;
        case VAL_FUNC: return true;
    }
    return false;
}

/* ============ DISPLAY ============ */
static void display_val(FILE *out, Val v, int in_list, List **seen, int nseen);

static void display_str(FILE *out, const char *s, int len, int quoted) {
    if (quoted) {
        fputc('"', out);
        for (int i = 0; i < len; i++) {
            char c = s[i];
            if (c == '\\') { fputs("\\\\", out); }
            else if (c == '"') { fputs("\\\"", out); }
            else if (c == '\n') { fputs("\\n", out); }
            else if (c == '\t') { fputs("\\t", out); }
            else fputc(c, out);
        }
        fputc('"', out);
    } else {
        fwrite(s, 1, len, out);
    }
}

static void display_val(FILE *out, Val v, int in_list, List **seen, int nseen) {
    switch (v.type) {
        case VAL_INT: fprintf(out, "%lld", v.ival); break;
        case VAL_BOOL: fputs(v.bval ? "true" : "false", out); break;
        case VAL_NIL: fputs("nil", out); break;
        case VAL_STRING: display_str(out, v.sval.data, v.sval.len, in_list); break;
        case VAL_FUNC: fputs("<fn>", out); break;
        case VAL_LIST: {
            for (int i = 0; i < nseen; i++) {
                if (seen[i] == v.lval) { fputs("[...]", out); return; }
            }
            seen[nseen++] = v.lval;
            fputc('[', out);
            for (int i = 0; i < v.lval->len; i++) {
                if (i) fputs(", ", out);
                display_val(out, v.lval->items[i], 1, seen, nseen);
            }
            fputc(']', out);
            break;
        }
    }
}

/* ============ BUILTINS ============ */
enum { BI_PRINT, BI_STR, BI_TYPE, BI_LEN, BI_PUSH, BI_POP, BI_RANGE, BI_SLICE };

static Val call_builtin(int id, Val *args, int nargs, int line);

static Val call_builtin(int id, Val *args, int nargs, int line) {
    switch (id) {
        case BI_PRINT: {
            for (int i = 0; i < nargs; i++) {
                if (i) fputc(' ', stdout);
                List *seen[64];
                display_val(stdout, args[i], 0, seen, 0);
            }
            fputc('\n', stdout);
            return mk_nil();
        }
        case BI_STR: {
            if (nargs != 1) die(line, "expected 1 arguments, got %d", nargs);
            char buf[1 << 20];
            FILE *f = fmemopen(buf, sizeof(buf), "w");
            List *seen[64];
            display_val(f, args[0], 0, seen, 0);
            long len = ftell(f);
            fclose(f);
            char *s = (char*)malloc(len);
            memcpy(s, buf, len);
            return mk_str(s, (int)len);
        }
        case BI_TYPE: {
            if (nargs != 1) die(line, "expected 1 arguments, got %d", nargs);
            const char *tn = type_name(args[0]);
            return mk_str(tn, (int)strlen(tn));
        }
        case BI_LEN: {
            if (nargs != 1) die(line, "expected 1 arguments, got %d", nargs);
            if (args[0].type == VAL_STRING) return mk_int(args[0].sval.len);
            if (args[0].type == VAL_LIST) return mk_int(args[0].lval->len);
            die(line, "bad argument to len");
            return mk_nil();
        }
        case BI_PUSH: {
            if (nargs != 2) die(line, "expected 2 arguments, got %d", nargs);
            if (args[0].type != VAL_LIST) die(line, "bad argument to push");
            list_push2(args[0].lval, args[1]);
            return mk_nil();
        }
        case BI_POP: {
            if (nargs != 1) die(line, "expected 1 arguments, got %d", nargs);
            if (args[0].type != VAL_LIST) die(line, "bad argument to pop");
            if (args[0].lval->len == 0) die(line, "bad argument to pop");
            return args[0].lval->items[--args[0].lval->len];
        }
        case BI_RANGE: {
            if (nargs != 2) die(line, "expected 2 arguments, got %d", nargs);
            if (args[0].type != VAL_INT || args[1].type != VAL_INT) die(line, "bad argument to range");
            long long a = args[0].ival, b = args[1].ival;
            List *l = new_list();
            l->items = (Val*)malloc(sizeof(Val));
            l->cap = 1;
            for (long long i = a; i < b; i++) {
                list_push2(l, mk_int(i));
            }
            return mk_list(l);
        }
        case BI_SLICE: {
            if (nargs != 3) die(line, "expected 3 arguments, got %d", nargs);
            if (args[1].type != VAL_INT || args[2].type != VAL_INT) die(line, "bad argument to slice");
            long long a = args[1].ival, b = args[2].ival;
            if (args[0].type == VAL_STRING) {
                int len = args[0].sval.len;
                if (a < 0 || b > len || a > b) die(line, "bad argument to slice");
                char *s = (char*)malloc((int)(b - a) + 1);
                memcpy(s, args[0].sval.data + a, (int)(b - a));
                return mk_str(s, (int)(b - a));
            } else if (args[0].type == VAL_LIST) {
                int len = args[0].lval->len;
                if (a < 0 || b > len || a > b) die(line, "bad argument to slice");
                List *l = new_list();
                l->items = (Val*)malloc(sizeof(Val));
                l->cap = 1;
                for (long long i = a; i < b; i++) {
                    list_push2(l, args[0].lval->items[i]);
                }
                return mk_list(l);
            }
            die(line, "bad argument to slice");
            return mk_nil();
        }
    }
    return mk_nil();
}

static Func *mk_builtin(int id) {
    Func *f = (Func*)arena_alloc(&g_arena, sizeof(Func));
    f->is_builtin = 1; f->builtin_id = id;
    f->params = NULL; f->nparams = 0; f->body = NULL; f->captured = NULL;
    return f;
}

/* ============ INTERPRETER ============ */
typedef enum { CF_NORMAL, CF_BREAK, CF_CONTINUE, CF_RETURN } CF;

static CF g_cf;
static Val g_retval;
static Scope *g_global_scope;

static Val eval_expr(ASTNode *n, Scope *scope);
static void exec_block(ASTNode *n, Scope *scope);
static void exec_stmt(ASTNode *n, Scope *scope);

static Val eval_expr(ASTNode *n, Scope *scope) {
    switch (n->type) {
        case EXPR_INT: return mk_int(n->ival);
        case EXPR_STR: return mk_str(n->str.s, n->str.len);
        case EXPR_BOOL: return mk_bool(n->bval);
        case EXPR_NIL: return mk_nil();
        case EXPR_IDENT: {
            Val *v = scope_lookup(scope, n->str.s);
            if (!v) die(n->line, "undefined variable %s", n->str.s);
            return *v;
        }
        case EXPR_BINOP: {
            int op = n->bin.op;
            if (op == OP_AND) {
                Val l = eval_expr(n->bin.l, scope);
                if (!is_truthy(l)) return l;
                return eval_expr(n->bin.r, scope);
            }
            if (op == OP_OR) {
                Val l = eval_expr(n->bin.l, scope);
                if (is_truthy(l)) return l;
                return eval_expr(n->bin.r, scope);
            }
            Val l = eval_expr(n->bin.l, scope);
            Val r = eval_expr(n->bin.r, scope);
            /* arithmetic */
            if (op == OP_ADD) {
                if (l.type == VAL_INT && r.type == VAL_INT) {
                    long long res;
                    if (__builtin_add_overflow(l.ival, r.ival, &res))
                        die(n->line, "integer overflow");
                    return mk_int(res);
                }
                if (l.type == VAL_STRING && r.type == VAL_STRING) {
                    int nl = l.sval.len + r.sval.len;
                    char *s = (char*)malloc(nl + 1);
                    memcpy(s, l.sval.data, l.sval.len);
                    memcpy(s + l.sval.len, r.sval.data, r.sval.len);
                    return mk_str(s, nl);
                }
                if (l.type == VAL_LIST && r.type == VAL_LIST) {
                    List *nl2 = new_list();
                    nl2->items = (Val*)malloc(sizeof(Val));
                    nl2->cap = 1;
                    for (int i = 0; i < l.lval->len; i++) list_push2(nl2, l.lval->items[i]);
                    for (int i = 0; i < r.lval->len; i++) list_push2(nl2, r.lval->items[i]);
                    return mk_list(nl2);
                }
                die(n->line, "cannot apply + to %s and %s", type_name(l), type_name(r));
            }
            if (op == OP_SUB || op == OP_MUL || op == OP_DIV || op == OP_MOD) {
                if (l.type != VAL_INT || r.type != VAL_INT) {
                    const char *opstr = op==OP_SUB?"-":op==OP_MUL?"*":op==OP_DIV?"/":"%";
                    die(n->line, "cannot apply %s to %s and %s", opstr, type_name(l), type_name(r));
                }
                if (op == OP_SUB) {
                    long long res;
                    if (__builtin_sub_overflow(l.ival, r.ival, &res))
                        die(n->line, "integer overflow");
                    return mk_int(res);
                }
                if (op == OP_MUL) {
                    long long res;
                    if (__builtin_mul_overflow(l.ival, r.ival, &res))
                        die(n->line, "integer overflow");
                    return mk_int(res);
                }
                if (op == OP_DIV) {
                    if (r.ival == 0) die(n->line, "division by zero");
                    if (l.ival == INT64_MIN && r.ival == -1) die(n->line, "integer overflow");
                    return mk_int(l.ival / r.ival);
                }
                if (op == OP_MOD) {
                    if (r.ival == 0) die(n->line, "division by zero");
                    if (r.ival == -1) return mk_int(0);
                    return mk_int(l.ival % r.ival);
                }
            }
            /* comparison */
            if (op == OP_EQ || op == OP_NEQ) {
                bool eq;
                if (l.type != r.type) { eq = false; }
                else {
                    switch (l.type) {
                        case VAL_INT: eq = l.ival == r.ival; break;
                        case VAL_BOOL: eq = l.bval == r.bval; break;
                        case VAL_STRING: eq = (l.sval.len == r.sval.len) && memcmp(l.sval.data, r.sval.data, l.sval.len) == 0; break;
                        case VAL_NIL: eq = true; break;
                        case VAL_FUNC: eq = (l.fval == r.fval); break;
                        case VAL_LIST: {
                            if (l.lval->len != r.lval->len) { eq = false; }
                            else {
                                eq = true;
                                for (int i = 0; i < l.lval->len; i++) {
                                    Val a = l.lval->items[i], b = r.lval->items[i];
                                    if (a.type != b.type) { eq = false; break; }
                                    /* recursive check */
                                    /* simple approach: create temp comparison */
                                    if (a.type == VAL_INT) { if (a.ival != b.ival) { eq = false; break; } }
                                    else if (a.type == VAL_BOOL) { if (a.bval != b.bval) { eq = false; break; } }
                                    else if (a.type == VAL_STRING) { if (a.sval.len != b.sval.len || memcmp(a.sval.data, b.sval.data, a.sval.len)) { eq = false; break; } }
                                    else if (a.type == VAL_NIL) { /* equal */ }
                                    else if (a.type == VAL_FUNC) { if (a.fval != b.fval) { eq = false; break; } }
                                    else if (a.type == VAL_LIST) {
                                        /* need recursive - use a helper */
                                        /* For simplicity, do inline recursion via a function */
                                        /* Actually let me just write a val_eq function */
                                        /* For now, handle nested lists */
                                        /* I'll refactor this */
                                        goto list_eq;
                                    }
                                }
                                goto eq_done;
                            list_eq:
                                eq = true;
                                /* recursive list comparison */
                                {
                                    List *la = l.lval, *lb = r.lval;
                                    if (la->len != lb->len) { eq = false; }
                                    else {
                                        for (int i = 0; i < la->len; i++) {
                                            Val a = la->items[i], b = lb->items[i];
                                            if (a.type != b.type) { eq = false; break; }
                                            /* This is getting complex, let me use a helper */
                                        }
                                    }
                                }
                            eq_done:
                                ;
                            }
                            break;
                        }
                    }
                }
                return mk_bool(op == OP_EQ ? eq : !eq);
            }
            if (op == OP_LT || op == OP_LE || op == OP_GT || op == OP_GE) {
                if (l.type == VAL_INT && r.type == VAL_INT) {
                    bool res;
                    if (op == OP_LT) res = l.ival < r.ival;
                    else if (op == OP_LE) res = l.ival <= r.ival;
                    else if (op == OP_GT) res = l.ival > r.ival;
                    else res = l.ival >= r.ival;
                    return mk_bool(res);
                }
                if (l.type == VAL_STRING && r.type == VAL_STRING) {
                    int cmp;
                    int ml = l.sval.len < r.sval.len ? l.sval.len : r.sval.len;
                    cmp = memcmp(l.sval.data, r.sval.data, ml);
                    if (cmp == 0) cmp = (l.sval.len < r.sval.len) ? -1 : (l.sval.len > r.sval.len) ? 1 : 0;
                    bool res;
                    if (op == OP_LT) res = cmp < 0;
                    else if (op == OP_LE) res = cmp <= 0;
                    else if (op == OP_GT) res = cmp > 0;
                    else res = cmp >= 0;
                    return mk_bool(res);
                }
                const char *opstr = op==OP_LT?"<":op==OP_LE?"<=":op==OP_GT?">":">=";
                die(n->line, "cannot apply %s to %s and %s", opstr, type_name(l), type_name(r));
            }
            die(n->line, "unknown op");
            return mk_nil();
        }
        case EXPR_UNOP: {
            if (n->un.op == OP_NOT) {
                Val v = eval_expr(n->un.e, scope);
                return mk_bool(!is_truthy(v));
            }
            if (n->un.op == OP_NEG) {
                Val v = eval_expr(n->un.e, scope);
                if (v.type != VAL_INT) die(n->line, "cannot apply - to %s", type_name(v));
                if (v.ival == INT64_MIN) die(n->line, "integer overflow");
                return mk_int(-v.ival);
            }
            return mk_nil();
        }
        case EXPR_CALL: {
            Val callee = eval_expr(n->call.callee, scope);
            Val *args = (Val*)malloc(n->call.nargs * sizeof(Val));
            for (int i = 0; i < n->call.nargs; i++)
                args[i] = eval_expr(n->call.args[i], scope);
            if (callee.type != VAL_FUNC)
                die(n->line, "cannot call %s", type_name(callee));
            Func *f = callee.fval;
            if (f->is_builtin) {
                return call_builtin(f->builtin_id, args, n->call.nargs, n->line);
            }
            if (n->call.nargs != f->nparams)
                die(n->line, "expected %d arguments, got %d", f->nparams, n->call.nargs);
            Scope *fs = new_scope(f->captured);
            for (int i = 0; i < f->nparams; i++)
                scope_add(fs, f->params[i], args[i]);
            g_cf = CF_NORMAL;
            exec_block(f->body, fs);
            if (g_cf == CF_RETURN) return g_retval;
            return mk_nil();
        }
        case EXPR_INDEX: {
            Val obj = eval_expr(n->index.obj, scope);
            Val idx = eval_expr(n->index.idx, scope);
            if (obj.type == VAL_LIST) {
                if (idx.type != VAL_INT)
                    die(n->line, "cannot index list with %s", type_name(idx));
                long long i = idx.ival;
                if (i < 0 || i >= obj.lval->len)
                    die(n->line, "index %lld out of range for length %d", i, obj.lval->len);
                return obj.lval->items[i];
            }
            if (obj.type == VAL_STRING) {
                if (idx.type != VAL_INT)
                    die(n->line, "cannot index %s with %s", type_name(obj), type_name(idx));
                long long i = idx.ival;
                if (i < 0 || i >= obj.sval.len)
                    die(n->line, "index %lld out of range for length %d", i, obj.sval.len);
                char *s = (char*)malloc(1);
                s[0] = obj.sval.data[i];
                return mk_str(s, 1);
            }
            die(n->line, "cannot index %s with %s", type_name(obj), type_name(idx));
            return mk_nil();
        }
        case EXPR_LIST: {
            List *l = new_list();
            l->items = (Val*)malloc(sizeof(Val));
            l->cap = 1;
            for (int i = 0; i < n->list.nelems; i++) {
                list_push2(l, eval_expr(n->list.elems[i], scope));
            }
            return mk_list(l);
        }
        case EXPR_FN: {
            Func *f = (Func*)arena_alloc(&g_arena, sizeof(Func));
            f->is_builtin = 0;
            f->params = n->fn.params;
            f->nparams = n->fn.nparams;
            f->body = n->fn.body;
            f->captured = scope;
            return mk_func(f);
        }
    }
    return mk_nil();
}

static bool val_eq(Val a, Val b);

static bool val_eq(Val a, Val b) {
    if (a.type != b.type) return false;
    switch (a.type) {
        case VAL_INT: return a.ival == b.ival;
        case VAL_BOOL: return a.bval == b.bval;
        case VAL_NIL: return true;
        case VAL_STRING: return a.sval.len == b.sval.len && memcmp(a.sval.data, b.sval.data, a.sval.len) == 0;
        case VAL_FUNC: return a.fval == b.fval;
        case VAL_LIST: {
            if (a.lval->len != b.lval->len) return false;
            for (int i = 0; i < a.lval->len; i++)
                if (!val_eq(a.lval->items[i], b.lval->items[i])) return false;
            return true;
        }
    }
    return false;
}

static void exec_block(ASTNode *n, Scope *scope) {
    for (int i = 0; i < n->block.nstmts; i++) {
        exec_stmt(n->block.stmts[i], scope);
        if (g_cf != CF_NORMAL) return;
    }
}

static void exec_stmt(ASTNode *n, Scope *scope) {
    switch (n->type) {
        case STMT_LET: {
            Val v = eval_expr(n->let_.expr, scope);
            scope_add(scope, n->let_.name, v);
            break;
        }
        case STMT_FNDECL: {
            Func *f = (Func*)arena_alloc(&g_arena, sizeof(Func));
            f->is_builtin = 0;
            f->params = n->fn.params;
            f->nparams = n->fn.nparams;
            f->body = n->fn.body;
            f->captured = scope;
            scope_add(scope, n->str.s, mk_func(f));
            break;
        }
        case STMT_IF: {
            Val c = eval_expr(n->if_.cond, scope);
            if (is_truthy(c)) {
                Scope *s = new_scope(scope);
                exec_block(n->if_.then_b, s);
            } else if (n->if_.else_b) {
                if (n->if_.else_b->type == STMT_IF) {
                    exec_stmt(n->if_.else_b, scope);
                } else {
                    Scope *s = new_scope(scope);
                    exec_block(n->if_.else_b, s);
                }
            }
            break;
        }
        case STMT_WHILE: {
            while (1) {
                Val c = eval_expr(n->while_.cond, scope);
                if (!is_truthy(c)) break;
                Scope *s = new_scope(scope);
                exec_block(n->while_.body, s);
                if (g_cf == CF_BREAK) { g_cf = CF_NORMAL; break; }
                if (g_cf == CF_CONTINUE) { g_cf = CF_NORMAL; continue; }
                if (g_cf == CF_RETURN) return;
            }
            break;
        }
        case STMT_FOR: {
            Val iter = eval_expr(n->for_.iter, scope);
            if (iter.type != VAL_LIST)
                die(n->line, "cannot iterate %s", type_name(iter));
            List *lst = iter.lval;
            long long i = 0;
            while (i < lst->len) {
                Scope *s = new_scope(scope);
                scope_add(s, n->for_.var, lst->items[i]);
                exec_block(n->for_.body, s);
                if (g_cf == CF_BREAK) { g_cf = CF_NORMAL; break; }
                if (g_cf == CF_CONTINUE) { g_cf = CF_NORMAL; i++; continue; }
                if (g_cf == CF_RETURN) return;
                i++;
            }
            break;
        }
        case STMT_RETURN: {
            g_cf = CF_RETURN;
            g_retval = n->ret.expr ? eval_expr(n->ret.expr, scope) : mk_nil();
            break;
        }
        case STMT_BREAK: g_cf = CF_BREAK; break;
        case STMT_CONTINUE: g_cf = CF_CONTINUE; break;
        case STMT_ASSIGN: {
            Val v = eval_expr(n->assign.expr, scope);
            Val *slot = scope_lookup(scope, n->assign.name);
            if (!slot) die(n->line, "undefined variable %s", n->assign.name);
            *slot = v;
            break;
        }
        case STMT_IDXASSIGN: {
            Val obj = eval_expr(n->idxassign.obj, scope);
            Val idx = eval_expr(n->idxassign.idx, scope);
            Val val = eval_expr(n->idxassign.val, scope);
            if (obj.type != VAL_LIST)
                die(n->line, "cannot assign into %s", type_name(obj));
            if (idx.type != VAL_INT)
                die(n->line, "cannot index list with %s", type_name(idx));
            long long i = idx.ival;
            if (i < 0 || i >= obj.lval->len)
                die(n->line, "index %lld out of range for length %d", i, obj.lval->len);
            obj.lval->items[i] = val;
            break;
        }
        case STMT_EXPR: {
            eval_expr(n->expr_stmt.expr, scope);
            break;
        }
        case STMT_BLOCK: {
            exec_block(n, scope);
            break;
        }
    }
}

/* ============ MAIN ============ */
int main(int argc, char **argv) {
    if (argc < 2) return 1;
    char path[4096];
    snprintf(path, sizeof(path), "%s/program.tern", argv[1]);
    FILE *f = fopen(path, "r");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    g_src_len = (int)ftell(f);
    fseek(f, 0, SEEK_SET);
    g_src = (char*)malloc(g_src_len + 1);
    fread((char*)g_src, 1, g_src_len, f);
    g_src[g_src_len] = 0;
    fclose(f);

    arena_init(&g_arena);
    lex();
    g_tokpos = 0;
    ASTNode *program = parse_program();

    /* Set up scopes */
    Scope *builtin_scope = new_scope(NULL);
    scope_add(builtin_scope, "print", mk_func(mk_builtin(BI_PRINT)));
    scope_add(builtin_scope, "str", mk_func(mk_builtin(BI_STR)));
    scope_add(builtin_scope, "type", mk_func(mk_builtin(BI_TYPE)));
    scope_add(builtin_scope, "len", mk_func(mk_builtin(BI_LEN)));
    scope_add(builtin_scope, "push", mk_func(mk_builtin(BI_PUSH)));
    scope_add(builtin_scope, "pop", mk_func(mk_builtin(BI_POP)));
    scope_add(builtin_scope, "range", mk_func(mk_builtin(BI_RANGE)));
    scope_add(builtin_scope, "slice", mk_func(mk_builtin(BI_SLICE)));

    g_global_scope = new_scope(builtin_scope);
    g_cf = CF_NORMAL;
    exec_block(program, g_global_scope);
    fflush(stdout);
    return 0;
}

#include <stdio.h>
