// CRC-32 table (PNG/zlib polynomial 0xEDB88320)
const crcTable: number[] = new Array(256);
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c >>> 0;
}

function crc32(data: Buffer, start: number = 0, end: number = data.length): number {
  let c = 0xFFFFFFFF;
  for (let i = start; i < end; i++) {
    c = crcTable[(c ^ data[i]) & 0xFF] ^ (c >>> 8);
  }
  return (c ^ 0xFFFFFFFF) >>> 0;
}

function adler32(data: Buffer): number {
  let s1 = 1, s2 = 0;
  for (let i = 0; i < data.length; i++) {
    s1 = (s1 + data[i]) % 65521;
    s2 = (s2 + s1) % 65521;
  }
  return ((s2 << 16) | s1) >>> 0;
}

class BitReader {
  buf: Buffer;
  pos: number;
  bitPos: number;
  constructor(buf: Buffer, pos: number = 0) {
    this.buf = buf;
    this.pos = pos;
    this.bitPos = 0;
  }
  readBit(): number {
    const byte = this.buf[this.pos];
    const bit = (byte >> this.bitPos) & 1;
    this.bitPos++;
    if (this.bitPos === 8) { this.bitPos = 0; this.pos++; }
    return bit;
  }
  readBits(n: number): number {
    let val = 0;
    for (let i = 0; i < n; i++) {
      val |= this.readBit() << i;
    }
    return val;
  }
  alignToByte(): void {
    if (this.bitPos !== 0) { this.bitPos = 0; this.pos++; }
  }
}

