    code = (code + blCount[len - 1]) << 1;
    nextCode[len] = code;
  }
  const tree: TreeNode[] = [{ left: -1, right: -1, sym: -1 }];
  for (let sym = 0; sym < lengths.length; sym++) {
    const len = lengths[sym];
    if (len === 0) continue;
    const c = nextCode[len]++;
    let node = 0;
    for (let i = len - 1; i >= 0; i--) {
      const bit = (c >> i) & 1;
      if (bit === 0) {
        if (tree[node].left === -1) {
          tree.push({ left: -1, right: -1, sym: -1 });
          tree[node].left = tree.length - 1;
        }
        node = tree[node].left;
      } else {
        if (tree[node].right === -1) {
          tree.push({ left: -1, right: -1, sym: -1 });
          tree[node].right = tree.length - 1;
        }
        node = tree[node].right;
