static void c_push(Content*c,const unsigned char*d,size_t n,int nl){
    if(c->cnt>=c->cap){c->cap=c->cap?c->cap*2:16;c->L=realloc(c->L,c->cap*sizeof(Line));}
    c->L[c->cnt].d=(unsigned char*)malloc(n+1);
    if(n)memcpy(c->L[c->cnt].d,d,n);
    c->L[c->cnt].n=n;c->L[c->cnt].nl=nl;c->cnt++;
}
static void c_parse(const unsigned char*buf,size_t len,Content*c){
