    for(size_t i=0;i<c->cnt;i++)tot+=c->L[i].n+(c->L[i].nl?1:0);
    unsigned char*b=(unsigned char*)malloc(tot?tot:1);
    size_t p=0;
    for(size_t i=0;i<c->cnt;i++){
        if(c->L[i].n)memcpy(b+p,c->L[i].d,c->L[i].n);
        p+=c->L[i].n;
        if(c->L[i].nl)b[p++]='\n';
    }
