    crc_init();
    const char*dir=argv[1];

    char dp[8192];snprintf(dp,sizeof(dp),"%s/changes.diff",dir);
    size_t dlen;unsigned char*dbuf=rdfile(dp,&dlen);
    if(!dbuf)return 1;

    DL*dl=NULL;int dlc=0,dlcap=0;
    {size_t s=0;for(size_t i=0;i<=dlen;i++){
        if(i==dlen||dbuf[i]=='\n'){
            if(dlc>=dlcap){dlcap=dlcap?dlcap*2:256;dl=realloc(dl,dlcap*sizeof(DL));}
            dl[dlc].d=dbuf+s;dl[dlc].n=i-s;dlc++;s=i+1;
        }
    }}

    Sec*secs=NULL;int sc=0,sccap=0;
    int i=0;
    while(i<dlc){
        if(dl[i].n>=10&&memcmp(dl[i].d,"diff --git ",9)==0){
            const unsigned char*p=dl[i].d+9;
            size_t plen=dl[i].n-9;
            const unsigned char*sep=NULL;
            for(size_t j=0;j+2<plen;j++){
                if(p[j]==' '&&p[j+1]=='b'&&p[j+2]=='/'){sep=p+j;break;}
            }
            if(!sep){i++;continue;}
            size_t pathlen=sep-(p+2);
            char*path=(char*)malloc(pathlen+1);
            memcpy(path,p+2,pathlen);path[pathlen]=0;

            if(sc>=sccap){sccap=sccap?sccap*2:16;secs=realloc(secs,sccap*sizeof(Sec));}
            Sec*s=&secs[sc];
            s->path=path;s->kind=KIND_MODIFY;s->h=NULL;s->hc=0;
            int hcap=0;
            i++;

            int has_new=0,has_del=0;
            while(i<dlc){
                if(dl[i].n>=10&&memcmp(dl[i].d,"diff --git ",9)==0)break;
                if(dl[i].n>=3&&memcmp(dl[i].d,"@@ ",3)==0)break;
                if(dl[i].n>=14&&memcmp(dl[i].d,"new file mode ",14)==0){has_new=1;i++;continue;}
                if(dl[i].n>=17&&memcmp(dl[i].d,"deleted file mode ",17)==0){has_del=1;i++;continue;}
                if(dl[i].n>=6&&memcmp(dl[i].d,"index ",6)==0){i++;continue;}
                if(dl[i].n>=4&&memcmp(dl[i].d,"--- ",4)==0){i++;continue;}
                if(dl[i].n>=4&&memcmp(dl[i].d,"+++ ",4)==0){i++;continue;}
                break;
            }
            if(has_new)s->kind=KIND_CREATE;
            else if(has_del)s->kind=KIND_DELETE;

            while(i<dlc){
                if(dl[i].n>=10&&memcmp(dl[i].d,"diff --git ",9)==0)break;
                if(dl[i].n>=3&&memcmp(dl[i].d,"@@ ",3)==0){
                    Hunk hk;memset(&hk,0,sizeof(hk));
                    const unsigned char*hp=dl[i].d+3;
                    size_t hpl=dl[i].n-3;
                    int pos=0;
                    if(pos<hpl&&hp[pos]=='-')pos++;
                    hk.a=0;while(pos<hpl&&hp[pos]>='0'&&hp[pos]<='9'){hk.a=hk.a*10+(hp[pos++]-'0');}
                    if(pos<hpl&&hp[pos]==','){pos++;hk.b=0;while(pos<hpl&&hp[pos]>='0'&&hp[pos]<='9'){hk.b=hk.b*10+(hp[pos++]-'0');}}
                    else hk.b=1;
                    while(pos<hpl&&hp[pos]==' ')pos++;
                    if(pos<hpl&&hp[pos]=='+')pos++;
                    hk.c=0;while(pos<hpl&&hp[pos]>='0'&&hp[pos]<='9'){hk.c=hk.c*10+(hp[pos++]-'0');}
                    if(pos<hpl&&hp[pos]==','){pos++;hk.d=0;while(pos<hpl&&hp[pos]>='0'&&hp[pos]<='9'){hk.d=hk.d*10+(hp[pos++]-'0');}}
                    else hk.d=1;
                    i++;

                    int bs=i;
                    while(i<dlc){
                        if(dl[i].n>=3&&memcmp(dl[i].d,"@@ ",3)==0)break;
                        if(dl[i].n>=10&&memcmp(dl[i].d,"diff --git ",9)==0)break;
                        i++;
                    }
                    int be=i;

                    Line*ol=NULL;int oc=0,ocap=0;
                    Line*nl=NULL;int nc=0,ncap=0;
                    int lmark=0,loi=-1,nii=-1;

                    for(int j=bs;j<be;j++){
                        if(dl[j].n==0)continue;
                        unsigned char m=dl[j].d[0];
                        const unsigned char*ct=dl[j].d+1;
