                            else if(lmark=='-'){if(loi>=0)ol[loi].nl=0;}
                            else if(lmark=='+'){if(nii>=0)nl[nii].nl=0;}
                        }
                    }
                    hk.old_l=ol;hk.old_n=oc;
                    hk.new_l=nl;hk.new_n=nc;
                    hk.malformed=(oc!=hk.b||nc!=hk.d);

                    if(s->hc>=hcap){hcap=hcap?hcap*2:8;s->h=realloc(s->h,hcap*sizeof(Hunk));}
                    s->h[s->hc++]=hk;
                }else{i++;}
            }
