        secs[k+1]=t;
    }

    for(int s=0;s<sc;s++){
        Sec*sec=&secs[s];
        const char*kn=sec->kind==KIND_CREATE?"create":sec->kind==KIND_DELETE?"delete":"modify";
        printf("%s: %s\n",sec->path,kn);

        char fp[8192];snprintf(fp,sizeof(fp),"%s/tree/%s",dir,sec->path);
        Content content;c_init(&content);

        if(sec->kind==KIND_CREATE){
            if(fexists(fp)){printf("  error: already exists\n");continue;}
        }else{
            if(!fexists(fp)){printf("  error: not found\n");continue;}
            size_t fl;unsigned char*fb=rdfile(fp,&fl);
            c_parse(fb,fl,&content);free(fb);
        }

        int delta=0;
        int all_applied=1;
        for(int h=0;h<sec->hc;h++){
            Hunk*hk=&sec->h[h];
            if(hk->malformed){
                printf("  hunk %d: malformed\n",h+1);
                all_applied=0;
                continue;
            }
            int P=hk->a+delta;

            if(hk->b==0){
                if(P>=0&&P<=(int)content.cnt){
                    size_t newcnt=content.cnt+hk->new_n;
                    if(newcnt>content.cap){content.cap=newcnt;content.L=realloc(content.L,content.cap*sizeof(Line));}
                    memmove(&content.L[P+hk->new_n],&content.L[P],(content.cnt-P)*sizeof(Line));
                    for(int k=0;k<hk->new_n;k++){
                        content.L[P+k].d=(unsigned char*)malloc(hk->new_l[k].n+1);
                        if(hk->new_l[k].n)memcpy(content.L[P+k].d,hk->new_l[k].d,hk->new_l[k].n);
                        content.L[P+k].n=hk->new_l[k].n;
                        content.L[P+k].nl=hk->new_l[k].nl;
                    }
                    content.cnt=newcnt;
                    printf("  hunk %d: applied at %d (offset 0)\n",h+1,P);
                    delta+=hk->d-hk->b;
                }else{
                    printf("  hunk %d: rejected\n",h+1);
                    all_applied=0;
                }
            }else{
                int lc=(int)content.cnt;
                int found=0,mp=-1;
                if(hk->b<=lc){
                    int max_p=lc-hk->b+1;
                    for(int dist=0;;dist++){
                        int left=P-dist;
                        int right=P+dist;
                        int any=0;
                        if(left>=1&&left<=max_p){
                            any=1;
                            int ok=1;
                            for(int k=0;k<hk->b;k++){
                                if(!line_eq(&content.L[left-1+k],&hk->old_l[k])){ok=0;break;}
                            }
                            if(ok){mp=left;found=1;break;}
                        }
                        if(dist>0&&right>=1&&right<=max_p){
                            any=1;
                            int ok=1;
                            for(int k=0;k<hk->b;k++){
                                if(!line_eq(&content.L[right-1+k],&hk->old_l[k])){ok=0;break;}
                            }
                            if(ok){mp=right;found=1;break;}
                        }
                        if(left<1&&right>max_p)break;
                    }
                }
                if(found){
                    int start=mp-1;
                    size_t newcnt=content.cnt-hk->b+hk->new_n;
                    if(newcnt>content.cap){content.cap=newcnt;content.L=realloc(content.L,content.cap*sizeof(Line));}
                    memmove(&content.L[start+hk->new_n],&content.L[start+hk->b],(content.cnt-start-hk->b)*sizeof(Line));
                    for(int k=0;k<hk->new_n;k++){
                        content.L[start+k].d=(unsigned char*)malloc(hk->new_l[k].n+1);
                        if(hk->new_l[k].n)memcpy(content.L[start+k].d,hk->new_l[k].d,hk->new_l[k].n);
                        content.L[start+k].n=hk->new_l[k].n;
                        content.L[start+k].nl=hk->new_l[k].nl;
                    }
                    content.cnt=newcnt;
                    int off=mp-P;
                    printf("  hunk %d: applied at %d (offset ",h+1,mp);
                    if(off>0)printf("+%d",off);else printf("%d",off);
                    printf(")\n");
                    delta+=hk->d-hk->b;
                }else{
                    printf("  hunk %d: rejected\n",h+1);
                    all_applied=0;
                }
            }
        }

        if(sec->kind==KIND_DELETE&&all_applied&&content.cnt==0){
            printf("  result: deleted\n");
        }else{
            size_t clen;unsigned char*cb=c_ser(&content,&clen);
            uint32_t cv=crc32(cb,clen);
            printf("  result: %zu lines, crc32 %08x\n",content.cnt,cv);
            free(cb);
        }
        c_free(&content);
    }

    free(dbuf);free(dl);
    return 0;
}

