                            ol[oc].d=(unsigned char*)malloc(cn+1);if(cn)memcpy(ol[oc].d,ct,cn);
                            ol[oc].n=cn;ol[oc].nl=1;oc++;
                            if(nc>=ncap){ncap=ncap?ncap*2:16;nl=realloc(nl,ncap*sizeof(Line));}
                            nl[nc].d=(unsigned char*)malloc(cn+1);if(cn)memcpy(nl[nc].d,ct,cn);
                            nl[nc].n=cn;nl[nc].nl=1;nc++;
                            lmark=' ';loi=oc-1;nii=nc-1;
                        }else if(m=='-'){
                            if(oc>=ocap){ocap=ocap?ocap*2:16;ol=realloc(ol,ocap*sizeof(Line));}
                            ol[oc].d=(unsigned char*)malloc(cn+1);if(cn)memcpy(ol[oc].d,ct,cn);
                            ol[oc].n=cn;ol[oc].nl=1;oc++;
                            lmark='-';loi=oc-1;
                        }else if(m=='+'){
                            if(nc>=ncap){ncap=ncap?ncap*2:16;nl=realloc(nl,ncap*sizeof(Line));}
                            nl[nc].d=(unsigned char*)malloc(cn+1);if(cn)memcpy(nl[nc].d,ct,cn);
                            nl[nc].n=cn;nl[nc].nl=1;nc++;
                            lmark='+';nii=nc-1;
                        }else if(m=='\\'){
                            if(lmark==' '){if(loi>=0)ol[loi].nl=0;if(nii>=0)nl[nii].nl=0;}
                            else if(lmark=='-'){if(loi>=0)ol[loi].nl=0;}
                            else if(lmark=='+'){if(nii>=0)nl[nii].nl=0;}
                        }
                    }
                    hk.old_l=ol;hk.old_n=oc;
                    hk.new_l=nl;hk.new_n=nc;
                    hk.malformed=(oc!=hk.b||nc!=hk.d);

                    if(s->hc>=hcap){hcap=hcap?hcap*2:8;s->h=realloc(s->h,hcap*sizeof(Hunk));}
                    s->h[s->hc++]=hk;
                }else{i++;}
            }
            sc++;
        }else{i++;}
    }

    for(int j=1;j<sc;j++){
        Sec t=secs[j];int k=j-1;
        while(k>=0&&strcmp(secs[k].path,t.path)>0){secs[k+1]=secs[k];k--;}
        secs[k+1]=t;
    }

    for(int s=0;s<sc;s++){
        Sec*sec=&secs[s];
        const char*kn=sec->kind==KIND_CREATE?"create":sec->kind==KIND_DELETE?"delete":"modify";
        printf("%s: %s\n",sec->path,kn);

        char fp[8192];snprintf(fp,sizeof(fp),"%s/tree/%s",dir,sec->path);
        Content content;c_init(&content);

        if(sec->kind==KIND_CREATE){
            if(fexists(fp)){printf("  error: already exists\n");continue;}
        }else{
            if(!fexists(fp)){printf("  error: not found\n");continue;}
            size_t fl;unsigned char*fb=rdfile(fp,&fl);
            c_parse(fb,fl,&content);free(fb);
        }

        int delta=0;
        int all_applied=1;
        for(int h=0;h<sec->hc;h++){
            Hunk*hk=&sec->h[h];
            if(hk->malformed){
                printf("  hunk %d: malformed\n",h+1);
                all_applied=0;
                continue;
            }
            int P=hk->a+delta;

            if(hk->b==0){
                if(P>=0&&P<=(int)content.cnt){
                    size_t newcnt=content.cnt+hk->new_n;
                    if(newcnt>content.cap){content.cap=newcnt;content.L=realloc(content.L,content.cap*sizeof(Line));}
                    memmove(&content.L[P+hk->new_n],&content.L[P],(content.cnt-P)*sizeof(Line));
                    for(int k=0;k<hk->new_n;k++){
                        content.L[P+k].d=(unsigned char*)malloc(hk->new_l[k].n+1);
                        if(hk->new_l[k].n)memcpy(content.L[P+k].d,hk->new_l[k].d,hk->new_l[k].n);
                        content.L[P+k].n=hk->new_l[k].n;
                        content.L[P+k].nl=hk->new_l[k].nl;
                    }
                    content.cnt=newcnt;
                    printf("  hunk %d: applied at %d (offset 0)\n",h+1,P);
                    delta+=hk->d-hk->b;
                }else{
                    printf("  hunk %d: rejected\n",h+1);
                    all_applied=0;
                }
            }else{
                int lc=(int)content.cnt;
                int found=0,mp=-1;
                if(hk->b<=lc){
                    int max_p=lc-hk->b+1;
                    for(int dist=0;;dist++){
                        int left=P-dist;
                        int right=P+dist;
                        int any=0;
                        if(left>=1&&left<=max_p){
                            any=1;
                            int ok=1;
                            for(int k=0;k<hk->b;k++){
                                if(!line_eq(&content.L[left-1+k],&hk->old_l[k])){ok=0;break;}
                            }
                            if(ok){mp=left;found=1;break;}
                        }
                        if(dist>0&&right>=1&&right<=max_p){
                            any=1;
                            int ok=1;
                            for(int k=0;k<hk->b;k++){
                                if(!line_eq(&content.L[right-1+k],&hk->old_l[k])){ok=0;break;}
                            }
                            if(ok){mp=right;found=1;break;}
                        }
                        if(!any)break;
                    }
                }
                if(found){
                    int start=mp-1;
                    size_t newcnt=content.cnt-hk->b+hk->new_n;
                    if(newcnt>content.cap){content.cap=newcnt;content.L=realloc(content.L,content.cap*sizeof(Line));}
                    memmove(&content.L[start+hk->new_n],&content.L[start+hk->b],(content.cnt-start-hk->b)*sizeof(Line));
                    for(int k=0;k<hk->new_n;k++){
                        content.L[start+k].d=(unsigned char*)malloc(hk->new_l[k].n+1);
                        if(hk->new_l[k].n)memcpy(content.L[start+k].d,hk->new_l[k].d,hk->new_l[k].n);
                        content.L[start+k].n=hk->new_l[k].n;
                        content.L[start+k].nl=hk->new_l[k].nl;
                    }
                    content.cnt=newcnt;
                    int off=mp-P;
                    printf("  hunk %d: applied at %d (offset ",h+1,mp);
                    if(off>0)printf("+%d",off);else printf("%d",off);
                    printf(")\n");
                    delta+=hk->d-hk->b;
                }else{
                    printf("  hunk %d: rejected\n",h+1);
                    all_applied=0;
                }
            }
        }

        if(sec->kind==KIND_DELETE&&all_applied&&content.cnt==0){
            printf("  result: deleted\n");
        }else{
            size_t clen;unsigned char*cb=c_ser(&content,&clen);
            uint32_t cv=crc32(cb,clen);
            printf("  result: %zu lines, crc32 %08x\n",content.cnt,cv);
            free(cb);
        }
        c_free(&content);
    }

    free(dbuf);free(dl);
    return 0;
}

use std::fs;
use std::path::Path;

#[derive(Clone, PartialEq)]
enum Kind { Create, Delete, Modify }

struct Hunk {
    a: usize, b: usize, c: usize, d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
}

struct Section {
    path: String,
    kind: Kind,
    hunks: Vec<Hunk>,
}

enum HunkResult {
    Applied { position: usize, offset: i64 },
    Rejected,
    Malformed,
}

enum SectionResult {
    Ok { results: Vec<HunkResult>, content: Vec<u8> },
    Deleted,
    Error(String),
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let diff_content = fs::read(format!("{}/changes.diff", dir)).unwrap();
    let mut sections = parse_diff(&diff_content);
    sections.sort_by(|a, b| a.path.as_bytes().cmp(b.path.as_bytes()));

    let mut output = String::new();
    for section in &sections {
        output.push_str(&format!("{}: {}\n", section.path, kind_str(&section.kind)));
        let result = apply_section(dir, section);
        match result {
            SectionResult::Error(msg) => {
                output.push_str(&format!("  error: {}\n", msg));
            }
            SectionResult::Deleted => {
                output.push_str("  result: deleted\n");
            }
            SectionResult::Ok { results, content } => {
                for (i, r) in results.iter().enumerate() {
                    match r {
                        HunkResult::Applied { position, offset } => {
                            output.push_str(&format!("  hunk {}: applied at {} (offset {})\n",
                                i + 1, position, format_offset(*offset)));
                        }
                        HunkResult::Rejected => {
                            output.push_str(&format!("  hunk {}: rejected\n", i + 1));
                        }
                        HunkResult::Malformed => {
                            output.push_str(&format!("  hunk {}: malformed\n", i + 1));
                        }
                    }
                }
                let lines = split_lines(&content);
                output.push_str(&format!("  result: {} lines, crc32 {:08x}\n", lines.len(), crc32(&content)));
            }
        }
    }
    print!("{}", output);
}

fn kind_str(k: &Kind) -> &'static str {
    match k { Kind::Create => "create", Kind::Delete => "delete", Kind::Modify => "modify" }
}

fn format_offset(k: i64) -> String {
    if k > 0 { format!("+{}", k) }
    else if k < 0 { format!("{}", k) }
    else { "0".to_string() }
}

fn split_lines(content: &[u8]) -> Vec<Vec<u8>> {
    if content.is_empty() { return vec![]; }
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..content.len() {
        if content[i] == b'\n' {
            lines.push(content[start..=i].to_vec());
            start = i + 1;
        }
    }
    if start < content.len() {
        lines.push(content[start..].to_vec());
    }
    lines
}

fn join_lines(lines: &[Vec<u8>]) -> Vec<u8> {
    let mut r = Vec::new();
    for l in lines { r.extend_from_slice(l); }
    r
}

fn split_diff_lines(content: &[u8]) -> Vec<Vec<u8>> {
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..content.len() {
        if content[i] == b'\n' {
            lines.push(content[start..i].to_vec());
            start = i + 1;
        }
    }
    if start < content.len() {
        lines.push(content[start..].to_vec());
    }
    lines
}

fn parse_diff(content: &[u8]) -> Vec<Section> {
    let lines = split_diff_lines(content);
    let mut sections = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        if lines[i].starts_with(b"diff --git ") {
            let (sec, next) = parse_section(&lines, i);
            sections.push(sec);
            i = next;
        } else {
            i += 1;
        }
    }
    sections
}

fn extract_path(line: &[u8]) -> String {
    let parts: Vec<&[u8]> = line.splitn(4, |&c| c == b' ').collect();
    let path_bytes = &parts[2][2..];
    String::from_utf8_lossy(path_bytes).to_string()
}

fn parse_section(lines: &[Vec<u8>], start: usize) -> (Section, usize) {
    let path = extract_path(&lines[start]);
    let mut kind = Kind::Modify;
    let mut i = start + 1;

    while i < lines.len() {
        let l = &lines[i];
        if l.starts_with(b"@@ ") || l.starts_with(b"diff --git ") { break; }
        if l.starts_with(b"new file mode ") { kind = Kind::Create; }
        else if l.starts_with(b"deleted file mode ") { kind = Kind::Delete; }
        i += 1;
    }

    let mut hunks = Vec::new();
    while i < lines.len() && lines[i].starts_with(b"@@ ") {
        let (h, next) = parse_hunk(lines, i);
        hunks.push(h);
        i = next;
    }

    (Section { path, kind, hunks }, i)
}

fn parse_hunk(lines: &[Vec<u8>], start: usize) -> (Hunk, usize) {
    let (a, b, c, d) = parse_hunk_header(&lines[start]);
    let mut old_lines: Vec<Vec<u8>> = Vec::new();
    let mut new_lines: Vec<Vec<u8>> = Vec::new();
    let mut last_marker: Option<u8> = None;

    let mut i = start + 1;
    while i < lines.len() {
        let l = &lines[i];
        if l.starts_with(b"@@ ") || l.starts_with(b"diff --git ") { break; }
        if l.is_empty() { i += 1; continue; }

        let marker = l[0];
        let content = &l[1..];

        match marker {
            b' ' => {
                let mut line = content.to_vec();
                line.push(b'\n');
                old_lines.push(line.clone());
                new_lines.push(line);
                last_marker = Some(b' ');
            }
            b'-' => {
                let mut line = content.to_vec();
                line.push(b'\n');
                old_lines.push(line);
                last_marker = Some(b'-');
            }
            b'+' => {
                let mut line = content.to_vec();
                line.push(b'\n');
                new_lines.push(line);
                last_marker = Some(b'+');
            }
            b'\\' => {
                match last_marker {
                    Some(b' ') => {
                        if let Some(last) = old_lines.last_mut() {
                            if last.last() == Some(&b'\n') { last.pop(); }
                        }
                        if let Some(last) = new_lines.last_mut() {
                            if last.last() == Some(&b'\n') { last.pop(); }
                        }
                    }
                    Some(b'-') => {
                        if let Some(last) = old_lines.last_mut() {
                            if last.last() == Some(&b'\n') { last.pop(); }
                        }
                    }
                    Some(b'+') => {
                        if let Some(last) = new_lines.last_mut() {
                            if last.last() == Some(&b'\n') { last.pop(); }
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }
        i += 1;
    }

    (Hunk { a, b, c, d, old_lines, new_lines }, i)
}

fn parse_hunk_header(line: &[u8]) -> (usize, usize, usize, usize) {
    let rest = &line[3..];
    let close_pos = find_subslice(rest, b"@@").unwrap_or(rest.len());
    let range_str = &rest[..close_pos];
    let parts: Vec<&[u8]> = range_str.split(|&ch| ch == b' ').filter(|s| !s.is_empty()).collect();
    let (a, b) = parse_range(parts[0]);
    let (c, d) = parse_range(parts[1]);
    (a, b, c, d)
}

fn parse_range(s: &[u8]) -> (usize, usize) {
    let s = &s[1..];
    if let Some(comma) = s.iter().position(|&c| c == b',') {
        let start: usize = std::str::from_utf8(&s[..comma]).unwrap().parse().unwrap();
        let count: usize = std::str::from_utf8(&s[comma+1..]).unwrap().parse().unwrap();
        (start, count)
    } else {
        let start: usize = std::str::from_utf8(s).unwrap().parse().unwrap();
        (start, 1)
    }
}

fn find_subslice(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.len() > hay.len() { return None; }
    for i in 0..=hay.len() - needle.len() {
        if &hay[i..i+needle.len()] == needle { return Some(i); }
    }
    None
}

fn apply_section(dir: &str, section: &Section) -> SectionResult {
    let full_path = format!("{}/tree/{}", dir, section.path);
    let exists = Path::new(&full_path).exists();

    match section.kind {
        Kind::Create => {
            if exists {
                return SectionResult::Error("already exists".to_string());
            }
            let mut content: Vec<Vec<u8>> = vec![];
            let results = apply_hunks(&mut content, &section.hunks);
            SectionResult::Ok { results, content: join_lines(&content) }
        }
        Kind::Modify | Kind::Delete => {
            if !exists {
                return SectionResult::Error("not found".to_string());
            }
            let file_content = fs::read(&full_path).unwrap();
            let mut content = split_lines(&file_content);
            let results = apply_hunks(&mut content, &section.hunks);

            if section.kind == Kind::Delete {
                let all_applied = results.iter().all(|r| matches!(r, HunkResult::Applied{..}));
                if all_applied && content.is_empty() {
                    return SectionResult::Deleted;
                }
            }

            SectionResult::Ok { results, content: join_lines(&content) }
        }
    }
}

fn apply_hunks(content: &mut Vec<Vec<u8>>, hunks: &[Hunk]) -> Vec<HunkResult> {
    let mut results = Vec::new();
    let mut delta: i64 = 0;

    for hunk in hunks {
        if hunk.old_lines.len() != hunk.b || hunk.new_lines.len() != hunk.d {
            results.push(HunkResult::Malformed);
            continue;
        }

        let p_expected = (hunk.a as i64) + delta;

        if hunk.b == 0 {
            if p_expected >= 0 && (p_expected as usize) <= content.len() {
                let pos = p_expected as usize;
                content.splice(pos..pos, hunk.new_lines.iter().cloned());
                results.push(HunkResult::Applied { position: pos, offset: 0 });
                delta += (hunk.d - hunk.b) as i64;
            } else {
                results.push(HunkResult::Rejected);
            }
        } else {
            match find_match(content, &hunk.old_lines, p_expected, hunk.b) {
                Some(p) => {
                    let start_idx = p - 1;
                    let end_idx = p - 1 + hunk.b;
                    content.splice(start_idx..end_idx, hunk.new_lines.iter().cloned());
                    let offset = p as i64 - p_expected;
                    results.push(HunkResult::Applied { position: p, offset });
                    delta += (hunk.d - hunk.b) as i64;
                }
                None => {
                    results.push(HunkResult::Rejected);
                }
            }
        }
    }
    results
}

fn find_match(content: &[Vec<u8>], old_lines: &[Vec<u8>], p_start: i64, b: usize) -> Option<usize> {
    let n = content.len();
    if b == 0 || b > n { return None; }
    let hi = n - b + 1;

    if p_start > hi as i64 {
        for p in (1..=hi).rev() {
            if &content[p-1..p-1+b] == old_lines { return Some(p); }
        }
        return None;
    }

    if p_start < 1 {
        for p in 1..=hi {
            if &content[p-1..p-1+b] == old_lines { return Some(p); }
        }
        return None;
    }

    let mut offset: i64 = 0;
    loop {
        let below = p_start - offset;
        let above = p_start + offset;

        if below >= 1 && (below as usize) <= hi {
            let p = below as usize;
            if &content[p-1..p-1+b] == old_lines { return Some(p); }
        }
        if offset > 0 && above >= 1 && (above as usize) <= hi {
            let p = above as usize;
            if &content[p-1..p-1+b] == old_lines { return Some(p); }
        }

        if below < 1 && above > hi as i64 { break; }
        offset += 1;
    }
    None
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

