func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func makeChunk(_ type: [UInt8], _ data: [UInt8]) -> [UInt8] {
    var chunk = [UInt8]()
    let len = UInt32(data.count)
    chunk.append(UInt8((len >> 24) & 0xFF))
    chunk.append(UInt8((len >> 16) & 0xFF))
    chunk.append(UInt8((len >> 8) & 0xFF))
    chunk.append(UInt8(len & 0xFF))
    chunk.append(contentsOf: type)
    chunk.append(contentsOf: data)
    var crcInput = type
    crcInput.append(contentsOf: data)
    let crc = crc32(crcInput)
    chunk.append(UInt8((crc >> 24) & 0xFF))
    chunk.append(UInt8((crc >> 16) & 0xFF))
    chunk.append(UInt8((crc >> 8) & 0xFF))
    chunk.append(UInt8(crc & 0xFF))
    return chunk
}

func writeBE32(_ val: UInt32) -> [UInt8] {
    return [UInt8((val >> 24) & 0xFF), UInt8((val >> 16) & 0xFF), UInt8((val >> 8) & 0xFF), UInt8(val & 0xFF)]
}

// Build raw image data (filter byte 0 + RGB per row)
var rawData = [UInt8]()
rawData.reserveCapacity(height * (1 + width * 3))
for y in 0..<height {
    rawData.append(0) // filter: None
    let rowBase = y * width
    for x in 0..<width {
        let idx = (rowBase + x) * 3
        rawData.append(UInt8(canvas[idx]))
        rawData.append(UInt8(canvas[idx + 1]))
        rawData.append(UInt8(canvas[idx + 2]))
    }
}

// Build zlib stream with stored DEFLATE blocks
var zlibData = [UInt8]()
// zlib header: CMF=0x78 (deflate, 32K window), FLG=0x01 (check bits)
zlibData.append(0x78)
zlibData.append(0x01)

// DEFLATE stored blocks
let maxBlock = 65535
var offset = 0
let totalLen = rawData.count
if totalLen == 0 {
    // edge case: emit one empty stored block
    zlibData.append(0x01) // BFINAL=1, BTYPE=00
    zlibData.append(0x00); zlibData.append(0x00) // LEN = 0
    zlibData.append(0xFF); zlibData.append(0xFF) // NLEN = 65535
} else {
    while offset < totalLen {
        let blockLen = min(maxBlock, totalLen - offset)
        let isLast = (offset + blockLen >= totalLen)
        let bfinal: UInt8 = isLast ? 1 : 0
        // Stored block: BFINAL(1 bit) + BTYPE=00(2 bits) + 5 bits padding = 1 byte
        zlibData.append(bfinal)
        let len16 = UInt16(blockLen)
        let nlen16: UInt16 = ~len16
        zlibData.append(UInt8(len16 & 0xFF))
        zlibData.append(UInt8((len16 >> 8) & 0xFF))
        zlibData.append(UInt8(nlen16 & 0xFF))
        zlibData.append(UInt8((nlen16 >> 8) & 0xFF))
        zlibData.append(contentsOf: rawData[offset..<(offset + blockLen)])
        offset += blockLen
    }
}

// Adler-32 of uncompressed data
let adler = adler32(rawData)
zlibData.append(contentsOf: writeBE32(adler))

// Build PNG file
var png = [UInt8]()
// PNG signature
png.append(contentsOf: [137, 80, 78, 71, 13, 10, 26, 10])

// IHDR
let ihdrType: [UInt8] = [73, 72, 68, 82] // "IHDR"
var ihdrData = [UInt8]()
ihdrData.append(contentsOf: writeBE32(UInt32(width)))
ihdrData.append(contentsOf: writeBE32(UInt32(height)))
ihdrData.append(8)  // bit depth
ihdrData.append(2)  // color type: RGB
ihdrData.append(0)  // compression method
ihdrData.append(0)  // filter method
ihdrData.append(0)  // interlace method
png.append(contentsOf: makeChunk(ihdrType, ihdrData))

// IDAT
let idatType: [UInt8] = [73, 68, 65, 84] // "IDAT"
png.append(contentsOf: makeChunk(idatType, zlibData))

// IEND
let iendType: [UInt8] = [73, 69, 78, 68] // "IEND"
png.append(contentsOf: makeChunk(iendType, []))

// Write file
let outURL = URL(fileURLWithPath: "out.png")
