// ============ TOKENIZER ============
interface Token { type: 'IDENT' | 'NUM' | 'STR' | 'PUNCT'; value: string; }

function tokenize(text: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < text.length) {
    if (text[i] === ' ' || text[i] === '\t' || text[i] === '\n' || text[i] === '\r' || text[i] === '\f' || text[i] === '\v') { i++; continue; }
    if (text[i] === '/' && i + 1 < text.length && text[i + 1] === '/') { i += 2; while (i < text.length && text[i] !== '\n') i++; continue; }
    if (text[i] === '/' && i + 1 < text.length && text[i + 1] === '*') { i += 2; while (i + 1 < text.length && !(text[i] === '*' && text[i + 1] === '/')) i++; i += 2; continue; }
    if (text[i] === '"') { i++; let s = ''; while (i < text.length && text[i] !== '"') { s += text[i]; i++; } if (i < text.length) i++; tokens.push({ type: 'STR', value: s }); continue; }
    if (/[0-9]/.test(text[i]) || (text[i] === '-' && i + 1 < text.length && /[0-9]/.test(text[i + 1]))) {
      let s = ''; if (text[i] === '-') { s += '-'; i++; }
      while (i < text.length && /[0-9]/.test(text[i])) { s += text[i]; i++; }
      if (i < text.length && text[i] === '.' && i + 1 < text.length && /[0-9]/.test(text[i + 1])) { s += '.'; i++; while (i < text.length && /[0-9]/.test(text[i])) { s += text[i]; i++; } }
      if (i < text.length && (text[i] === 'e' || text[i] === 'E')) { let j = i + 1; if (j < text.length && (text[j] === '+' || text[j] === '-')) j++; if (j < text.length && /[0-9]/.test(text[j])) { s += text[i]; i++; if (text[i] === '+' || text[i] === '-') { s += text[i]; i++; } while (i < text.length && /[0-9]/.test(text[i])) { s += text[i]; i++; } } }
      tokens.push({ type: 'NUM', value: s }); continue;
    }
    if (/[a-zA-Z_]/.test(text[i])) { let s = ''; while (i < text.length && /[a-zA-Z0-9_]/.test(text[i])) { s += text[i]; i++; } tokens.push({ type: 'IDENT', value: s }); continue; }
    tokens.push({ type: 'PUNCT', value: text[i] }); i++;
  }
  return tokens;
}

// ============ SCHEMA ============
interface FieldDef { name: string; number: number; type: string; label: 'singular' | 'repeated' | 'optional'; isMap: boolean; mapKeyType?: string; mapValueType?: string; oneofName?: string; }
interface MessageDef { name: string; fields: Map<number, FieldDef>; oneofs: Map<string, number[]>; }
interface EnumDef { name: string; values: Map<number, string>; }

const messages = new Map<string, MessageDef>();
const enums = new Map<string, EnumDef>();
let rootMessageName = '';

const SCALAR_TYPES = new Set(['int32','int64','uint32','uint64','sint32','sint64','bool','string','bytes','fixed32','fixed64','sfixed32','sfixed64']);
const VARINT_TYPES = new Set(['int32','int64','uint32','uint64','sint32','sint64','bool']);
const FIXED32_TYPES = new Set(['fixed32','sfixed32']);
const FIXED64_TYPES = new Set(['fixed64','sfixed64']);

function isMessageType(t: string): boolean { return !SCALAR_TYPES.has(t) && !enums.has(t); }
function isEnumType(t: string): boolean { return enums.has(t); }
function isNumericOrBoolOrEnum(t: string): boolean { return VARINT_TYPES.has(t) || FIXED32_TYPES.has(t) || FIXED64_TYPES.has(t) || enums.has(t); }

// ============ PARSER ============
class ProtoParser {
  tokens: Token[]; pos: number;
  constructor(tokens: Token[]) { this.tokens = tokens; this.pos = 0; }
  peek(): Token | undefined { return this.tokens[this.pos]; }
  next(): Token { return this.tokens[this.pos++]; }
  expect(type: string, value?: string): Token { const t = this.next(); if (!t || t.type !== type || (value !== undefined && t.value !== value)) throw new Error(`Expected ${type} ${value}, got ${t?.type} ${t?.value}`); return t; }
  skipToSemicolon(): void { while (this.pos < this.tokens.length) { const t = this.next(); if (t.type === 'PUNCT' && t.value === ';') return; } }
  skipBrackets(): void { while (this.pos < this.tokens.length) { const t = this.next(); if (t.type === 'PUNCT' && t.value === ']') return; } }
  parseFile(): void {
    while (this.pos < this.tokens.length) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'IDENT') {
        if (t.value === 'syntax' || t.value === 'package' || t.value === 'option') { this.next(); this.skipToSemicolon(); }
        else if (t.value === 'message') this.parseMessage();
        else if (t.value === 'enum') this.parseEnum();
        else this.next();
      } else this.next();
    }
  }
  parseMessage(): void {
    this.expect('IDENT', 'message');
    const name = this.expect('IDENT').value;
    this.expect('PUNCT', '{');
    const msgDef: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    messages.set(name, msgDef);
    if (!rootMessageName) rootMessageName = name;
    while (this.pos < this.tokens.length) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'PUNCT' && t.value === '}') { this.next(); break; }
      if (t.type === 'IDENT') {
        if (t.value === 'option') { this.next(); this.skipToSemicolon(); }
        else if (t.value === 'reserved') { this.next(); this.skipToSemicolon(); }
        else if (t.value === 'message') this.parseMessage();
        else if (t.value === 'enum') this.parseEnum();
        else if (t.value === 'oneof') this.parseOneof(msgDef);
        else if (t.value === 'map') this.parseMapField(msgDef, undefined);
        else if (t.value === 'repeated' || t.value === 'optional') { const lbl = t.value as 'repeated' | 'optional'; this.next(); this.parseFieldAfterLabel(msgDef, lbl, undefined); }
        else this.parseFieldAfterLabel(msgDef, 'singular', undefined);
      } else this.next();
    }
  }
  parseOneof(msgDef: MessageDef): void {
    this.expect('IDENT', 'oneof');
    const oneofName = this.expect('IDENT').value;
    this.expect('PUNCT', '{');
    const fieldNums: number[] = [];
    while (this.pos < this.tokens.length) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'PUNCT' && t.value === '}') { this.next(); break; }
      if (t.type === 'IDENT') {
        if (t.value === 'option') { this.next(); this.skipToSemicolon(); }
        else if (t.value === 'map') { this.parseMapField(msgDef, oneofName); }
        else { this.parseFieldAfterLabel(msgDef, 'singular', oneofName); }
      } else this.next();
    }
    msgDef.oneofs.set(oneofName, fieldNums);
  }
  parseFieldAfterLabel(msgDef: MessageDef, label: 'singular' | 'repeated' | 'optional', oneofName: string | undefined): void {
    const typeToken = this.expect('IDENT');
    const type = typeToken.value;
    const name = this.expect('IDENT').value;
    this.expect('PUNCT', '=');
    const numToken = this.expect('NUM');
    const fieldNum = parseInt(numToken.value);
    if (this.peek()?.type === 'PUNCT' && this.peek()?.value === '[') { this.next(); this.skipBrackets(); }
    this.expect('PUNCT', ';');
    const fd: FieldDef = { name, number: fieldNum, type, label, isMap: false, oneofName };
    msgDef.fields.set(fieldNum, fd);
    if (oneofName) { const arr = msgDef.oneofs.get(oneofName); if (arr) arr.push(fieldNum); }
  }
  parseMapField(msgDef: MessageDef, oneofName: string | undefined): void {
    this.expect('IDENT', 'map');
    this.expect('PUNCT', '<');
    const keyType = this.expect('IDENT').value;
    this.expect('PUNCT', ',');
    const valType = this.expect('IDENT').value;
    this.expect('PUNCT', '>');
    const name = this.expect('IDENT').value;
    this.expect('PUNCT', '=');
    const numToken = this.expect('NUM');
    const fieldNum = parseInt(numToken.value);
    if (this.peek()?.type === 'PUNCT' && this.peek()?.value === '[') { this.next(); this.skipBrackets(); }
    this.expect('PUNCT', ';');
    const fd: FieldDef = { name, number: fieldNum, type: 'map', label: 'repeated', isMap: true, mapKeyType: keyType, mapValueType: valType, oneofName };
    msgDef.fields.set(fieldNum, fd);
  }
  parseEnum(): void {
    this.expect('IDENT', 'enum');
    const name = this.expect('IDENT').value;
    this.expect('PUNCT', '{');
    const enumDef: EnumDef = { name, values: new Map() };
    enums.set(name, enumDef);
    while (this.pos < this.tokens.length) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'PUNCT' && t.value === '}') { this.next(); break; }
      if (t.type === 'IDENT') {
        if (t.value === 'option') { this.next(); this.skipToSemicolon(); }
        else if (t.value === 'reserved') { this.next(); this.skipToSemicolon(); }
        else {
          const vname = this.next().value;
          this.expect('PUNCT', '=');
          const vnum = parseInt(this.expect('NUM').value);
          if (this.peek()?.type === 'PUNCT' && this.peek()?.value === '[') { this.next(); this.skipBrackets(); }
          this.expect('PUNCT', ';');
          enumDef.values.set(vnum, vname);
        }
      } else this.next();
    }
  }
}

// ============ VARINT & WIRE HELPERS ============
function readVarint(buf: Buffer, pos: number): [bigint, number] {
  let result = 0n; let shift = 0n;
  for (let i = 0; i < 10; i++) {
    const b = buf[pos + i];
    result |= BigInt(b & 0x7F) << shift;
    if ((b & 0x80) === 0) return [result, pos + i + 1];
    shift += 7n;
  }
  throw new Error("varint too long");
}

function skipVarint(buf: Buffer, pos: number): number {
  for (let i = 0; i < 10; i++) { if ((buf[pos + i] & 0x80) === 0) return pos + i + 1; }
  throw new Error("varint too long");
}

function skipField(buf: Buffer, pos: number, fieldNum: number, wireType: number): number {
  switch (wireType) {
    case 0: return skipVarint(buf, pos);
    case 1: return pos + 8;
    case 2: { const [len, np] = readVarint(buf, pos); return np + Number(len); }
    case 5: return pos + 4;
    case 3: {
      while (true) {
        const [key, kPos] = readVarint(buf, pos); pos = kPos;
        const fn = Number(key >> 3n); const wt = Number(key & 7n);
        if (wt === 4 && fn === fieldNum) return pos;
        pos = skipField(buf, pos, fn, wt);
      }
    }
    case 4: return pos;
    default: throw new Error("unknown wire type " + wireType);
  }
}

// ============ DECODER ============
interface FieldState { occurred: boolean; value: any; }
interface DecodedMsg { fields: Map<number, FieldState>; oneofSet: Map<string, number>; }

function decodeVarintValue(buf: Buffer, pos: number, type: string): [any, number] {
  const [raw, newPos] = readVarint(buf, pos);
  switch (type) {
    case 'int32': return [Number(BigInt.asIntN(32, raw)), newPos];
    case 'int64': return [BigInt.asIntN(64, raw), newPos];
    case 'uint32': return [Number(BigInt.asUintN(32, raw)), newPos];
    case 'uint64': return [BigInt.asUintN(64, raw), newPos];
    case 'sint32': { let n = (raw >> 1n) ^ (-(raw & 1n)); return [Number(BigInt.asIntN(32, n)), newPos]; }
    case 'sint64': { let n = (raw >> 1n) ^ (-(raw & 1n)); return [BigInt.asIntN(64, n), newPos]; }
    case 'bool': return [raw !== 0n, newPos];
    case 'enum_placeholder': return [Number(BigInt.asIntN(32, raw)), newPos];
    default: return [Number(BigInt.asIntN(32, raw)), newPos]; // enum
  }
}

function decodeFixed32(buf: Buffer, pos: number, type: string): [any, number] {
  const u = buf.readUInt32LE(pos);
  if (type === 'sfixed32') return [u | 0, pos + 4]; // signed
  return [u, pos + 4];
}

function decodeFixed64(buf: Buffer, pos: number, type: string): [any, number] {
  const lo = BigInt(buf.readUInt32LE(pos));
  const hi = BigInt(buf.readUInt32LE(pos + 4));
  const u = (hi << 32n) | lo;
  if (type === 'sfixed64') return [BigInt.asIntN(64, u), pos + 8];
  return [BigInt.asUintN(64, u), pos + 8];
}

function decodeBytes(buf: Buffer, pos: number): [Buffer, number] {
  const [len, np] = readVarint(buf, pos);
  const l = Number(len);
  return [buf.subarray(np, np + l), np + l];
}

function decodeScalar(buf: Buffer, pos: number, wireType: number, type: string): [any, number] {
  if (type === 'string') { const [b, np] = decodeBytes(buf, pos); return [b.toString('utf8'), np]; }
  if (type === 'bytes') { const [b, np] = decodeBytes(buf, pos); return [b, np]; }
  if (wireType === 0) return decodeVarintValue(buf, pos, type);
  if (wireType === 1) return decodeFixed64(buf, pos, type);
  if (wireType === 5) return decodeFixed32(buf, pos, type);
  throw new Error("unexpected wire type " + wireType + " for " + type);
}

function decodeMessage(buf: Buffer, start: number, end: number, msgDef: MessageDef): DecodedMsg {
  const result: DecodedMsg = { fields: new Map(), oneofSet: new Map() };
  let pos = start;
  while (pos < end) {
    const [key, kPos] = readVarint(buf, pos); pos = kPos;
    const fieldNum = Number(key >> 3n);
    const wireType = Number(key & 7n);
    const fd = msgDef.fields.get(fieldNum);
    if (!fd) { pos = skipField(buf, pos, fieldNum, wireType); continue; }
    if (fd.isMap) {
      if (wireType !== 2) { pos = skipField(buf, pos, fieldNum, wireType); continue; }
      const [entryBuf, np] = decodeBytes(buf, pos); pos = np;
      const [k, v] = decodeMapEntry(entryBuf, 0, entryBuf.length, fd.mapKeyType!, fd.mapValueType!);
      let mapState = result.fields.get(fieldNum);
      if (!mapState) { mapState = { occurred: true, value: new Map() }; result.fields.set(fieldNum, mapState); }
      mapState.value.set(k, v);
    } else if (fd.label === 'repeated') {
      if (isNumericOrBoolOrEnum(fd.type) && wireType === 2) {
        // packed
        const [packedBuf, np] = decodeBytes(buf, pos); pos = np;
        let repState = result.fields.get(fieldNum);
        if (!repState) { repState = { occurred: true, value: [] }; result.fields.set(fieldNum, repState); }
        let pp = 0;
        while (pp < packedBuf.length) {
          const [val, npp] = decodeScalar(packedBuf, pp, wireTypeForType(fd.type), fd.type);
          repState.value.push(val); pp = npp;
        }
      } else {
        const [val, np] = decodeFieldValue(buf, pos, wireType, fd);
        pos = np;
        let repState = result.fields.get(fieldNum);
        if (!repState) { repState = { occurred: true, value: [] }; result.fields.set(fieldNum, repState); }
        repState.value.push(val);
      }
    } else {
      // singular
      if (fd.oneofName) {
        const on = fd.oneofName;
        const cur = result.oneofSet.get(on);
        if (cur !== undefined && cur !== fieldNum) { result.fields.delete(cur); }
        if (cur === fieldNum && isMessageType(fd.type)) {
          const subDef = messages.get(fd.type)!;
          if (wireType !== 2) { pos = skipField(buf, pos, fieldNum, wireType); continue; }
          const [subBuf, np] = decodeBytes(buf, pos); pos = np;
          const newSub = decodeMessage(subBuf, 0, subBuf.length, subDef);
          const existing = result.fields.get(fieldNum);
          if (existing && existing.occurred) { mergeMessages(existing.value, newSub, subDef); }
          else { result.fields.set(fieldNum, { occurred: true, value: newSub }); }
        } else {
          result.fields.delete(fieldNum);
          const [val, np] = decodeFieldValue(buf, pos, wireType, fd);
          pos = np;
          result.fields.set(fieldNum, { occurred: true, value: val });
        }
        result.oneofSet.set(on, fieldNum);
      } else if (isMessageType(fd.type)) {
        if (wireType !== 2) { pos = skipField(buf, pos, fieldNum, wireType); continue; }
        const subDef = messages.get(fd.type)!;
        const [subBuf, np] = decodeBytes(buf, pos); pos = np;
        const newSub = decodeMessage(subBuf, 0, subBuf.length, subDef);
        const existing = result.fields.get(fieldNum);
        if (existing && existing.occurred) { mergeMessages(existing.value, newSub, subDef); }
        else { result.fields.set(fieldNum, { occurred: true, value: newSub }); }
      } else {
        const [val, np] = decodeFieldValue(buf, pos, wireType, fd);
        pos = np;
        result.fields.set(fieldNum, { occurred: true, value: val });
      }
    }
  }
  return result;
}

function wireTypeForType(type: string): number {
  if (VARINT_TYPES.has(type) || enums.has(type)) return 0;
  if (FIXED32_TYPES.has(type)) return 5;
  if (FIXED64_TYPES.has(type)) return 1;
  return 2;
}

function decodeFieldValue(buf: Buffer, pos: number, wireType: number, fd: FieldDef): [any, number] {
  if (isMessageType(fd.type)) {
    const subDef = messages.get(fd.type)!;
    const [subBuf, np] = decodeBytes(buf, pos);
    return [decodeMessage(subBuf, 0, subBuf.length, subDef), np];
  }
  return decodeScalar(buf, pos, wireType, fd.type);
}

function decodeMapEntry(buf: Buffer, start: number, end: number, keyType: string, valType: string): [any, any] {
  let key: any = keyType === 'string' ? '' : 0;
  let value: any;
  if (valType === 'string') value = '';
  else if (valType === 'bytes') value = Buffer.alloc(0);
  else if (isMessageType(valType)) value = decodeMessage(Buffer.alloc(0), 0, 0, messages.get(valType)!);
  else if (enums.has(valType)) value = 0;
  else if (valType === 'bool') value = false;
  else if (valType === 'int64' || valType === 'uint64' || valType === 'sint64' || valType === 'fixed64' || valType === 'sfixed64') value = 0n;
  else value = 0;

  let pos = start;
  while (pos < end) {
    const [keyV, kPos] = readVarint(buf, pos); pos = kPos;
    const fn = Number(keyV >> 3n);
    const wt = Number(keyV & 7n);
    if (fn === 1) {
      const [k, np] = decodeScalar(buf, pos, wt, keyType); key = k; pos = np;
    } else if (fn === 2) {
      if (isMessageType(valType)) {
        const subDef = messages.get(valType)!;
        const [subBuf, np] = decodeBytes(buf, pos);
        value = decodeMessage(subBuf, 0, subBuf.length, subDef); pos = np;
      } else {
        const [v, np] = decodeScalar(buf, pos, wt, valType); value = v; pos = np;
      }
    } else {
      pos = skipField(buf, pos, fn, wt);
    }
  }
  return [key, value];
}

function mergeMessages(target: DecodedMsg, source: DecodedMsg, msgDef: MessageDef): void {
  for (const [fn, sf] of source.fields) {
    if (!sf.occurred) continue;
    const fd = msgDef.fields.get(fn);
    if (!fd) continue;
    if (fd.isMap) {
      let existing = target.fields.get(fn);
      if (!existing) { existing = { occurred: true, value: new Map() }; target.fields.set(fn, existing); }
      for (const [k, v] of sf.value) existing.value.set(k, v);
    } else if (fd.label === 'repeated') {
      let existing = target.fields.get(fn);
      if (!existing) { existing = { occurred: true, value: [] }; target.fields.set(fn, existing); }
      existing.value.push(...sf.value);
    } else if (isMessageType(fd.type)) {
      const existing = target.fields.get(fn);
      if (existing && existing.occurred) { mergeMessages(existing.value, sf.value, messages.get(fd.type)!); }
      else { target.fields.set(fn, { occurred: true, value: sf.value }); }
    } else {
      target.fields.set(fn, { occurred: true, value: sf.value });
    }
  }
  for (const [on, setFn] of source.oneofSet) {
    const cur = target.oneofSet.get(on);
    if (cur !== undefined && cur !== setFn) { target.fields.delete(cur); }
    target.oneofSet.set(on, setFn);
  }
}

// ============ JSON SERIALIZER ============
function toLowerCamelCase(name: string): string {
  let result = ''; let i = 0;
  while (i < name.length) {
    if (name[i] === '_') {
      i++;
      if (i < name.length) {
        const c = name[i];
        if (c >= 'a' && c <= 'z') result += c.toUpperCase();
        else result += c;
        i++;
      }
    } else { result += name[i]; i++; }
  }
  return result;
}

function escapeJsonString(s: string): string {
  let r = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    const code = s.charCodeAt(i);
    if (c === '"') r += '\\"';
    else if (c === '\\') r += '\\\\';
    else if (code === 8) r += '\\b';
    else if (code === 9) r += '\\t';
    else if (code === 10) r += '\\n';
    else if (code === 12) r += '\\f';
    else if (code === 13) r += '\\r';
    else if (code < 0x20) r += '\\u' + code.toString(16).padStart(4, '0');
    else r += c;
  }
  return r;
}

function isDefaultScalar(type: string, value: any): boolean {
  if (type === 'string') return value === '';
  if (type === 'bytes') return value.length === 0;
  if (type === 'bool') return value === false;
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return value === 0n;
  if (enums.has(type)) return value === 0;
  return value === 0;
}

function serializeValue(val: any, type: string): string {
  if (isMessageType(type)) {
    return serializeMessage(val, messages.get(type)!);
  }
  if (enums.has(type)) {
    const ed = enums.get(type)!;
    const name = ed.values.get(val);
    if (name !== undefined) return '"' + escapeJsonString(name) + '"';
    return String(val);
  }
  if (type === 'string') return '"' + escapeJsonString(val) + '"';
  if (type === 'bytes') return '"' + val.toString('base64') + '"';
  if (type === 'bool') return val ? 'true' : 'false';
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return '"' + val.toString() + '"';
  return String(val);
}

function serializeMessage(msg: DecodedMsg, msgDef: MessageDef): string {
  const parts: string[] = [];
  const sortedFieldNums = [...msgDef.fields.keys()].sort((a, b) => a - b);
  for (const fn of sortedFieldNums) {
    const fd = msgDef.fields.get(fn)!;
    const fs = msg.fields.get(fn);
    if (!fs || !fs.occurred) continue;
    // Check if in oneof and not the set member
    if (fd.oneofName) {
      const setMember = msg.oneofSet.get(fd.oneofName);
      if (setMember !== fn) continue;
    }
    if (fd.isMap) {
      if (fs.value.size === 0) continue;
      parts.push('"' + escapeJsonString(toLowerCamelCase(fd.name)) + '":' + serializeMap(fs.value, fd.mapKeyType!, fd.mapValueType!));
    } else if (fd.label === 'repeated') {
      if (fs.value.length === 0) continue;
      const elems = fs.value.map((v: any) => serializeValue(v, fd.type));
      parts.push('"' + escapeJsonString(toLowerCamelCase(fd.name)) + '":[' + elems.join(',') + ']');
    } else if (isMessageType(fd.type)) {
      parts.push('"' + escapeJsonString(toLowerCamelCase(fd.name)) + '":' + serializeValue(fs.value, fd.type));
    } else if (fd.label === 'optional' || fd.oneofName) {
      parts.push('"' + escapeJsonString(toLowerCamelCase(fd.name)) + '":' + serializeValue(fs.value, fd.type));
    } else {
      if (isDefaultScalar(fd.type, fs.value)) continue;
      parts.push('"' + escapeJsonString(toLowerCamelCase(fd.name)) + '":' + serializeValue(fs.value, fd.type));
    }
  }
  return '{' + parts.join(',') + '}';
}

function serializeMap(map: Map<any, any>, keyType: string, valType: string): string {
  const entries: [string, string][] = [];
  if (keyType === 'string') {
    const keys = [...map.keys()] as string[];
    keys.sort((a, b) => {
      const ba = Buffer.from(a, 'utf8'); const bb = Buffer.from(b, 'utf8');
      return Buffer.compare(ba, bb);
    });
    for (const k of keys) {
      entries.push(['"' + escapeJsonString(k) + '"', serializeValue(map.get(k), valType)]);
    }
  } else {
    const keys = [...map.keys()] as number[];
    keys.sort((a, b) => a - b);
    for (const k of keys) {
      entries.push(['"' + String(k) + '"', serializeValue(map.get(k), valType)]);
    }
  }
  return '{' + entries.map(([k, v]) => k + ':' + v).join(',') + '}';
}

// ============ MAIN ============
function main(): void {
  const dir = process.argv[2];
  if (!dir) { process.exit(1); }
  const protoText = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf8');
  const tokens = tokenize(protoText);
  const parser = new ProtoParser(tokens);
  parser.parseFile();

  const binData = fs.readFileSync(path.join(dir, 'messages.bin'));
  const rootDef = messages.get(rootMessageName)!;

  let pos = 0;
  const lines: string[] = [];
  while (pos < binData.length) {
    const [len, np] = readVarint(binData, pos);
    pos = np;
    const msgStart = pos;
    const msgEnd = pos + Number(len);
    pos = msgEnd;
    const decoded = decodeMessage(binData, msgStart, msgEnd, rootDef);
    lines.push(serializeMessage(decoded, rootDef));
  }
  process.stdout.write(lines.join('\n') + (lines.length > 0 ? '\n' : ''));
}

main();

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::Read;

// ==================== UTILITIES ====================

const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn base64_encode(data: &[u8]) -> String {
    let mut r = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i + 2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(B64[((n >> 18) & 63) as usize] as char);
        r.push(B64[((n >> 12) & 63) as usize] as char);
        if i + 1 < data.len() { r.push(B64[((n >> 6) & 63) as usize] as char); } else { r.push('='); }
        if i + 2 < data.len() { r.push(B64[(n & 63) as usize] as char); } else { r.push('='); }
        i += 3;
    }
    r
}

fn camel_case(name: &str) -> String {
    let mut r = String::new();
    let mut upper_next = false;
    for ch in name.chars() {
        if ch == '_' {
            upper_next = true;
        } else {
            if upper_next {
                upper_next = false;
                if ch.is_ascii_lowercase() {
                    r.push(ch.to_ascii_uppercase());
                } else {
                    r.push(ch);
                }
            } else {
                r.push(ch);
            }
        }
    }
    r
}

fn json_escape(s: &str) -> String {
    let mut r = String::new();
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\t' => r.push_str("\\t"),
            '\n' => r.push_str("\\n"),
            '\u{0C}' => r.push_str("\\f"),
            '\r' => r.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                r.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => r.push(c),
        }
    }
    r
}

// ==================== SCHEMA TYPES ====================

#[derive(Debug, Clone, PartialEq)]
enum ScalarType { Int32, Int64, Uint32, Uint64, Sint32, Sint64, Bool, Str, Bytes, Fixed32, Fixed64, Sfixed32, Sfixed64 }

#[derive(Debug, Clone)]
enum TypeRef { Scalar(ScalarType), Named(String) }

#[derive(Debug, Clone, PartialEq)]
enum Label { Singular, Optional, Repeated, Oneof }

#[derive(Debug, Clone)]
struct FieldDef {
    name: String,
    number: u32,
    label: Label,
    type_ref: TypeRef,
    oneof_name: Option<String>,
    map_key: Option<TypeRef>,
    map_val: Option<TypeRef>,
}

#[derive(Debug, Clone)]
struct MsgDef { name: String, fields: Vec<FieldDef> }

#[derive(Debug, Clone)]
struct EnumDef { name: String, values: Vec<(String, i32)> }

struct Schema {
    messages: HashMap<String, MsgDef>,
    enums: HashMap<String, EnumDef>,
    root: String,
}

// ==================== LEXER ====================

struct Lexer { data: Vec<u8>, pos: usize }

impl Lexer {
    fn new(data: Vec<u8>) -> Self { Lexer { data, pos: 0 } }
    fn eof(&self) -> bool { self.pos >= self.data.len() }
    fn peek_byte(&self) -> Option<u8> { if self.pos < self.data.len() { Some(self.data[self.pos]) } else { None } }
    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.data.len() && (self.data[self.pos] as char).is_ascii_whitespace() { self.pos += 1; }
            if self.pos + 1 < self.data.len() && self.data[self.pos] == b'/' && self.data[self.pos + 1] == b'/' {
                while self.pos < self.data.len() && self.data[self.pos] != b'\n' { self.pos += 1; }
                continue;
            }
            if self.pos + 1 < self.data.len() && self.data[self.pos] == b'/' && self.data[self.pos + 1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.data.len() {
                    if self.data[self.pos] == b'*' && self.data[self.pos + 1] == b'/' { self.pos += 2; break; }
                    self.pos += 1;
                }
                continue;
            }
            break;
        }
    }
    fn peek_char(&mut self) -> Option<u8> { self.skip_ws(); self.peek_byte() }
    fn expect_byte(&mut self, b: u8) { self.skip_ws(); if self.pos < self.data.len() && self.data[self.pos] == b { self.pos += 1; } }
    fn read_ident(&mut self) -> String {
        self.skip_ws();
        let start = self.pos;
        while self.pos < self.data.len() && (self.data[self.pos] as char).is_ascii_alphanumeric() || (self.pos < self.data.len() && self.data[self.pos] == b'_') {
            self.pos += 1;
        }
        String::from_utf8_lossy(&self.data[start..self.pos]).into_owned()
    }
    fn read_string(&mut self) -> String {
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b'"' {
            self.pos += 1;
            let start = self.pos;
            while self.pos < self.data.len() && self.data[self.pos] != b'"' { self.pos += 1; }
            let s = String::from_utf8_lossy(&self.data[start..self.pos]).into_owned();
            if self.pos < self.data.len() { self.pos += 1; }
            s
        } else { String::new() }
    }
    fn read_number(&mut self) -> i64 {
        self.skip_ws();
        let neg = if self.pos < self.data.len() && self.data[self.pos] == b'-' { self.pos += 1; true } else { false };
        let start = self.pos;
        while self.pos < self.data.len() && (self.data[self.pos] as char).is_ascii_digit() { self.pos += 1; }
        let v: i64 = String::from_utf8_lossy(&self.data[start..self.pos]).parse().unwrap_or(0);
        if neg { -v } else { v }
    }
    fn skip_to(&mut self, b: u8) {
        self.skip_ws();
        while self.pos < self.data.len() {
            if self.data[self.pos] == b { self.pos += 1; return; }
            if self.data[self.pos] == b'"' {
                self.pos += 1;
                while self.pos < self.data.len() && self.data[self.pos] != b'"' { self.pos += 1; }
                if self.pos < self.data.len() { self.pos += 1; }
            } else {
                self.pos += 1;
            }
        }
    }
    fn skip_option_value(&mut self) {
        self.skip_ws();
        match self.peek_byte() {
            Some(b'"') => { self.read_string(); }
            Some(b'-') | Some(b'0')..=Some(b'9') => { self.read_number(); }
            _ => { self.read_ident(); }
        }
    }
}

// ==================== PARSER ====================

fn parse_scalar_type(name: &str) -> Option<ScalarType> {
    match name {
        "int32" => Some(ScalarType::Int32), "int64" => Some(ScalarType::Int64),
        "uint32" => Some(ScalarType::Uint32), "uint64" => Some(ScalarType::Uint64),
        "sint32" => Some(ScalarType::Sint32), "sint64" => Some(ScalarType::Sint64),
        "bool" => Some(ScalarType::Bool), "string" => Some(ScalarType::Str),
        "bytes" => Some(ScalarType::Bytes), "fixed32" => Some(ScalarType::Fixed32),
        "fixed64" => Some(ScalarType::Fixed64), "sfixed32" => Some(ScalarType::Sfixed32),
        "sfixed64" => Some(ScalarType::Sfixed64),
        _ => None,
    }
}

fn parse_type_ref(lx: &mut Lexer) -> TypeRef {
    let name = lx.read_ident();
    if let Some(st) = parse_scalar_type(&name) { TypeRef::Scalar(st) } else { TypeRef::Named(name) }
}

fn skip_options_brackets(lx: &mut Lexer) {
    if lx.peek_char() == Some(b'[') {
        lx.expect_byte(b'[');
        loop {
            let c = lx.peek_char();
            if c == Some(b']') || c == None { lx.expect_byte(b']'); break; }
            lx.read_ident(); // option name
            lx.expect_byte(b'=');
            lx.skip_option_value();
            if lx.peek_char() == Some(b',') { lx.expect_byte(b','); }
        }
    }
}

fn parse_fields_in_block(lx: &mut Lexer, msg: &mut MsgDef, oneof_name: Option<&str>) {
    loop {
        let c = lx.peek_char();
        if c == Some(b'}') || c == None { break; }
        let ident = {
            let save = lx.pos;
            lx.skip_ws();
            let s = lx.read_ident();
            if s.is_empty() { lx.pos = save; break; }
            s
        };
        match ident.as_str() {
            "message" => { lx.read_ident(); lx.expect_byte(b'{'); let mut _m = MsgDef { name: String::new(), fields: vec![] }; parse_fields_in_block(lx, &mut _m, None); lx.expect_byte(b'}'); }
            "enum" => { lx.read_ident(); lx.expect_byte(b'{'); loop { let c2 = lx.peek_char(); if c2 == Some(b'}') || c2 == None { break; } lx.read_ident(); lx.expect_byte(b'='); lx.read_number(); skip_options_brackets(lx); lx.expect_byte(b';'); } lx.expect_byte(b'}'); }
            "oneof" => { let oname = lx.read_ident(); lx.expect_byte(b'{'); parse_fields_in_block(lx, msg, Some(&oname)); lx.expect_byte(b'}'); }
            "reserved" => { lx.skip_to(b';'); }
            "option" => { lx.read_ident(); lx.expect_byte(b'='); lx.skip_option_value(); lx.expect_byte(b';'); }
            "map" => {
                lx.expect_byte(b'<');
                let kt = parse_type_ref(lx);
                lx.expect_byte(b',');
                let vt = parse_type_ref(lx);
                lx.expect_byte(b'>');
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                msg.fields.push(FieldDef { name: fname, number: fnum, label: Label::Repeated, type_ref: TypeRef::Named(String::new()), oneof_name: None, map_key: Some(kt), map_val: Some(vt) });
            }
            "repeated" | "optional" => {
                let label = if ident == "repeated" { Label::Repeated } else { Label::Optional };
                let tr = parse_type_ref(lx);
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                msg.fields.push(FieldDef { name: fname, number: fnum, label, type_ref: tr, oneof_name: oneof_name.map(|s| s.to_string()), map_key: None, map_val: None });
            }
            _ => {
                // It's a type name (field declaration without label)
                let tr = if let Some(st) = parse_scalar_type(&ident) { TypeRef::Scalar(st) } else { TypeRef::Named(ident) };
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                let label = if oneof_name.is_some() { Label::Oneof } else { Label::Singular };
                msg.fields.push(FieldDef { name: fname, number: fnum, label, type_ref: tr, oneof_name: oneof_name.map(|s| s.to_string()), map_key: None, map_val: None });
            }
        }
    }
}

fn parse_proto(content: Vec<u8>) -> Schema {
    let mut lx = Lexer::new(content);
    let mut messages: HashMap<String, MsgDef> = HashMap::new();
    let mut enums: HashMap<String, EnumDef> = HashMap::new();
    let mut root = String::new();
    let mut first_msg = true;

    loop {
        let c = lx.peek_char();
        if c == None { break; }
        let ident = lx.read_ident();
        if ident.is_empty() { break; }
        match ident.as_str() {
            "syntax" | "package" => { lx.expect_byte(b'='); lx.skip_to(b';'); }
            "option" => { lx.read_ident(); lx.expect_byte(b'='); lx.skip_option_value(); lx.expect_byte(b';'); }
            "import" => { lx.skip_to(b';'); }
            "message" => {
                let name = lx.read_ident();
                lx.expect_byte(b'{');
                let mut msg = MsgDef { name: name.clone(), fields: vec![] };
                parse_fields_in_block(&mut lx, &mut msg, None);
                lx.expect_byte(b'}');
                if first_msg { root = name.clone(); first_msg = false; }
                messages.insert(name, msg);
            }
            "enum" => {
                let name = lx.read_ident();
                lx.expect_byte(b'{');
                let mut ed = EnumDef { name: name.clone(), values: vec![] };
                loop {
                    let c2 = lx.peek_char();
                    if c2 == Some(b'}') || c2 == None { break; }
                    let vname = lx.read_ident();
                    lx.expect_byte(b'=');
                    let vval = lx.read_number() as i32;
                    skip_options_brackets(&mut lx);
                    lx.expect_byte(b';');
                    ed.values.push((vname, vval));
                }
                lx.expect_byte(b'}');
                enums.insert(name, ed);
            }
            _ => { lx.skip_to(b';'); }
        }
    }
    Schema { messages, enums, root }
}

// ==================== DECODER ====================

#[derive(Debug, Clone)]
enum DecodedValue {
    Int32(i32), Int64(i64), Uint32(u32), Uint64(u64),
    Bool(bool), Str(String), Bytes(Vec<u8>),
    EnumVal(i32), Message(Box<DecodedMsg>),
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum MapKey { Str(String), Int(i32) }

#[derive(Debug, Clone)]
struct FieldData {
    seen: bool,
    values: Vec<DecodedValue>,
    map_entries: HashMap<MapKey, DecodedValue>,
}

#[derive(Debug, Clone)]
struct DecodedMsg {
    fields: HashMap<u32, FieldData>,
    oneof_state: HashMap<String, Option<u32>>,
}

impl DecodedMsg {
    fn new() -> Self { DecodedMsg { fields: HashMap::new(), oneof_state: HashMap::new() } }
}

struct Reader<'a> { data: &'a [u8], pos: usize }

impl<'a> Reader<'a> {
    fn new(data: &'a [u8]) -> Self { Reader { data, pos: 0 } }
    fn eof(&self) -> bool { self.pos >= self.data.len() }
    fn read_byte(&mut self) -> Option<u8> { if self.pos < self.data.len() { let b = self.data[self.pos]; self.pos += 1; Some(b) } else { None } }
    fn read_varint(&mut self) -> Option<u64> {
        let mut result: u64 = 0;
        let mut shift = 0;
        for _ in 0..10 {
            let b = self.read_byte()?;
            result |= ((b & 0x7F) as u64) << shift;
            if b & 0x80 == 0 { return Some(result); }
            shift += 7;
        }
        Some(result)
    }
    fn read_fixed32(&mut self) -> Option<u32> {
        if self.pos + 4 > self.data.len() { return None; }
        let v = u32::from_le_bytes([self.data[self.pos], self.data[self.pos+1], self.data[self.pos+2], self.data[self.pos+3]]);
        self.pos += 4;
        Some(v)
    }
    fn read_fixed64(&mut self) -> Option<u64> {
        if self.pos + 8 > self.data.len() { return None; }
        let v = u64::from_le_bytes([self.data[self.pos],self.data[self.pos+1],self.data[self.pos+2],self.data[self.pos+3],self.data[self.pos+4],self.data[self.pos+5],self.data[self.pos+6],self.data[self.pos+7]]);
        self.pos += 8;
        Some(v)
    }
    fn read_bytes(&mut self) -> Option<&'a [u8]> {
        let len = self.read_varint()? as usize;
        if self.pos + len > self.data.len() { return None; }
        let b = &self.data[self.pos..self.pos+len];
        self.pos += len;
        Some(b)
    }
}

fn is_numeric_or_enum(tr: &TypeRef, schema: &Schema) -> bool {
    match tr {
        TypeRef::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
            ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool |
            ScalarType::Fixed32 | ScalarType::Fixed64 | ScalarType::Sfixed32 | ScalarType::Sfixed64 => true,
            _ => false,
        },
        TypeRef::Named(n) => schema.enums.contains_key(n),
    }
}

fn scalar_wire_type(st: &ScalarType) -> u8 {
    match st {
        ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool => 0,
        ScalarType::Str | ScalarType::Bytes => 2,
        ScalarType::Fixed32 | ScalarType::Sfixed32 => 5,
        ScalarType::Fixed64 | ScalarType::Sfixed64 => 1,
    }
}

fn decode_scalar_value(rd: &mut Reader, st: &ScalarType) -> Option<DecodedValue> {
    match st {
        ScalarType::Int32 => { let v = rd.read_varint()?; Some(DecodedValue::Int32(v as u32 as i32)) }
        ScalarType::Int64 => { let v = rd.read_varint()?; Some(DecodedValue::Int64(v as i64)) }
        ScalarType::Uint32 => { let v = rd.read_varint()?; Some(DecodedValue::Uint32(v as u32)) }
        ScalarType::Uint64 => { let v = rd.read_varint()?; Some(DecodedValue::Uint64(v)) }
        ScalarType::Sint32 => { let v = rd.read_varint()?; let v32 = v as u32; Some(DecodedValue::Int32(((v32 >> 1) as i32) ^ -((v32 & 1) as i32))) }
        ScalarType::Sint64 => { let v = rd.read_varint()?; Some(DecodedValue::Int64(((v >> 1) as i64) ^ -((v & 1) as i64))) }
        ScalarType::Bool => { let v = rd.read_varint()?; Some(DecodedValue::Bool(v != 0)) }
        ScalarType::Str => { let b = rd.read_bytes()?; Some(DecodedValue::Str(String::from_utf8_lossy(b).into_owned())) }
        ScalarType::Bytes => { let b = rd.read_bytes()?; Some(DecodedValue::Bytes(b.to_vec())) }
        ScalarType::Fixed32 => { let v = rd.read_fixed32()?; Some(DecodedValue::Uint32(v)) }
        ScalarType::Fixed64 => { let v = rd.read_fixed64()?; Some(DecodedValue::Uint64(v)) }
        ScalarType::Sfixed32 => { let v = rd.read_fixed32()?; Some(DecodedValue::Int32(v as i32)) }
        ScalarType::Sfixed64 => { let v = rd.read_fixed64()?; Some(DecodedValue::Int64(v as i64)) }
    }
}

fn decode_enum_value(rd: &mut Reader) -> Option<DecodedValue> {
    let v = rd.read_varint()?;
    Some(DecodedValue::EnumVal(v as u32 as i32))
}

fn decode_packed(rd: &mut Reader, st: &ScalarType) -> Vec<DecodedValue> {
    let mut vals = vec![];
    while !rd.eof() {
        match decode_scalar_value(rd, st) {
            Some(v) => vals.push(v),
            None => break,
        }
    }
    vals
}

fn decode_packed_enum(rd: &mut Reader) -> Vec<DecodedValue> {
    let mut vals = vec![];
    while !rd.eof() {
        match decode_enum_value(rd) {
            Some(v) => vals.push(v),
            None => break,
        }
    }
    vals
}

fn skip_field(rd: &mut Reader, wt: u8) {
    match wt {
        0 => { rd.read_varint(); }
        1 => { rd.read_fixed64(); }
        2 => { rd.read_bytes(); }
        5 => { rd.read_fixed32(); }
        3 => {
            // group: skip until matching end group
            let fnum = 0; // we don't know the field number here, but we need to match
            // Actually we need to track field numbers for groups
            // This is handled in the caller
        }
        4 => {}
        _ => {}
    }
}

fn skip_group(rd: &mut Reader, group_fnum: u32) {
    loop {
        let key = match rd.read_varint() { Some(k) => k, None => return };
        let fnum = (key >> 3) as u32;
        let wt = (key & 7) as u8;
        if wt == 4 && fnum == group_fnum { return; }
        match wt {
            0 => { rd.read_varint(); }
            1 => { rd.read_fixed64(); }
            2 => { rd.read_bytes(); }
            5 => { rd.read_fixed32(); }
            3 => { skip_group(rd, fnum); }
            4 => { /* stray end group */ }
            _ => { return; }
        }
    }
}

fn decode_message(data: &[u8], schema: &Schema, msg_name: &str) -> DecodedMsg {
    let mut msg = DecodedMsg::new();
    let mdef = match schema.messages.get(msg_name) { Some(m) => m, None => return msg };
    let mut rd = Reader::new(data);

    while !rd.eof() {
        let key = match rd.read_varint() { Some(k) => k, None => break };
        let fnum = (key >> 3) as u32;
        let wt = (key & 7) as u8;

        // Find field definition
        let fdef = mdef.fields.iter().find(|f| f.number == fnum);
        let fdef = match fdef { Some(f) => f.clone(), None => {
            // Unknown field
            match wt {
                0 => { rd.read_varint(); }
                1 => { rd.read_fixed64(); }
                2 => { rd.read_bytes(); }
                5 => { rd.read_fixed32(); }
                3 => { skip_group(&mut rd, fnum); }
                4 => {}
                _ => { break; }
            }
            continue;
        }};

        // Handle oneof: clear other members
        if let Some(ref oname) = fdef.oneof_name {
            let current = msg.oneof_state.get(oname).cloned().flatten();
            if current != Some(fnum) {
                // Clear all fields in this oneof
                for f in &mdef.fields {
                    if f.oneof_name.as_deref() == Some(oname.as_str()) && f.number != fnum {
                        msg.fields.remove(&f.number);
                    }
                }
                msg.oneof_state.insert(oname.clone(), Some(fnum));
            }
        }

        let is_map = fdef.map_key.is_some();
        let is_repeated = fdef.label == Label::Repeated && !is_map;

        // Decode value based on field type and wire type
        if is_map {
            // Map field: wire type 2, embedded message with key=1, value=2
            if wt != 2 { match wt { 0 => { rd.read_varint(); } 1 => { rd.read_fixed64(); } 5 => { rd.read_fixed32(); } _ => {} } continue; }
            let payload = match rd.read_bytes() { Some(b) => b, None => break };
            let (key, val) = decode_map_entry(payload, schema, fdef.map_key.as_ref().unwrap(), fdef.map_value_type());
            let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            fd.map_entries.insert(key, val);
        } else if is_repeated && wt == 2 && is_numeric_or_enum(&fdef.type_ref, schema) {
            // Packed repeated
            let payload = match rd.read_bytes() { Some(b) => b, None => break };
            let mut prd = Reader::new(payload);
            let vals = match &fdef.type_ref {
                TypeRef::Scalar(st) => decode_packed(&mut prd, st),
                TypeRef::Named(_) => decode_packed_enum(&mut prd),
            };
            let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            fd.values.extend(vals);
        } else {
            // Normal field
            let val = decode_field_value(&mut rd, wt, &fdef.type_ref, schema, msg_name);
            match val {
                Some(v) => {
                    let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
                    fd.seen = true;
                    if is_repeated {
                        fd.values.push(v);
                    } else {
                        // Singular: check if message merge
                        if let DecodedValue::Message(ref new_msg) = v {
                            if let Some(DecodedValue::Message(_)) = fd.values.first() {
                                // Merge: re-decode into existing
                                // Actually we need to merge the new message into the existing one
                                // Let's handle this by decoding the payload into the existing msg
                                // For now, we'll handle merge differently
                                fd.values[0] = v;
                            } else {
                                fd.values = vec![v];
                            }
                        } else {
                            fd.values = vec![v];
                        }
                    }
                }
                None => {
                    match wt {
                        0 => { rd.read_varint(); }
                        1 => { rd.read_fixed64(); }
                        2 => { rd.read_bytes(); }
                        5 => { rd.read_fixed32(); }
                        3 => { skip_group(&mut rd, fnum); }
                        4 => {}
                        _ => {}
                    }
                }
            }
        }
    }
    msg
}

fn decode_field_value(rd: &mut Reader, wt: u8, tr: &TypeRef, schema: &Schema, _parent_msg: &str) -> Option<DecodedValue> {
    match tr {
        TypeRef::Scalar(st) => {
            let expected_wt = scalar_wire_type(st);
            if wt == expected_wt {
                decode_scalar_value(rd, st)
            } else if wt == 2 && (matches!(st, ScalarType::Int32|ScalarType::Int64|ScalarType::Uint32|ScalarType::Uint64|ScalarType::Sint32|ScalarType::Sint64|ScalarType::Bool|ScalarType::Fixed32|ScalarType::Fixed64|ScalarType::Sfixed32|ScalarType::Sfixed64)) {
                // Packed single element (shouldn't happen for singular, but handle)
                let payload = rd.read_bytes()?;
                let mut prd = Reader::new(payload);
                decode_scalar_value(&mut prd, st)
            } else {
                match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None }
            }
        }
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name) {
                if wt == 0 { decode_enum_value(rd) } else { match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None } }
            } else if schema.messages.contains_key(name) {
                if wt == 2 {
                    let payload = rd.read_bytes()?;
                    let sub = decode_message(payload, schema, name);
                    Some(DecodedValue::Message(Box::new(sub)))
                } else { match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 5 => { rd.read_fixed32()?; None } _ => None } }
            } else {
                match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None }
            }
        }
    }
}

fn decode_map_entry(data: &[u8], schema: &Schema, key_type: &TypeRef, val_type: &TypeRef) -> (MapKey, DecodedValue) {
    let mut key: Option<MapKey> = None;
    let mut val: Option<DecodedValue> = None;
    let mut rd = Reader::new(data);
    while !rd.eof() {
        let k = match rd.read_varint() { Some(k) => k, None => break };
        let fn_ = (k >> 3) as u32;
        let wt = (k & 7) as u8;
        if fn_ == 1 {
            key = Some(decode_map_key(&mut rd, wt, key_type));
        } else if fn_ == 2 {
            val = decode_field_value(&mut rd, wt, val_type, schema, "");
        } else {
            match wt { 0 => { rd.read_varint(); } 1 => { rd.read_fixed64(); } 2 => { rd.read_bytes(); } 5 => { rd.read_fixed32(); } 3 => { skip_group(&mut rd, fn_); } 4 => {} _ => {} }
        }
    }
    let mk = key.unwrap_or(MapKey::Str(String::new()));
    let mv = val.unwrap_or_else(|| default_value(val_type, schema));
    (mk, mv)
}

fn decode_map_key(rd: &mut Reader, wt: u8, kt: &TypeRef) -> MapKey {
    match kt {
        TypeRef::Scalar(ScalarType::Str) => {
            if wt == 2 { let b = rd.read_bytes().unwrap_or(&[]); MapKey::Str(String::from_utf8_lossy(b).into_owned()) } else { MapKey::Str(String::new()) }
        }
        TypeRef::Scalar(ScalarType::Int32) => {
            if wt == 0 { let v = rd.read_varint().unwrap_or(0); MapKey::Int(v as u32 as i32) } else { MapKey::Int(0) }
        }
        _ => MapKey::Str(String::new()),
    }
}

fn default_value(tr: &TypeRef, schema: &Schema) -> DecodedValue {
    match tr {
        TypeRef::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Sint32 | ScalarType::Sfixed32 => DecodedValue::Int32(0),
            ScalarType::Int64 | ScalarType::Sint64 | ScalarType::Sfixed64 => DecodedValue::Int64(0),
            ScalarType::Uint32 | ScalarType::Fixed32 => DecodedValue::Uint32(0),
            ScalarType::Uint64 | ScalarType::Fixed64 => DecodedValue::Uint64(0),
            ScalarType::Bool => DecodedValue::Bool(false),
            ScalarType::Str => DecodedValue::Str(String::new()),
            ScalarType::Bytes => DecodedValue::Bytes(vec![]),
        },
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name) { DecodedValue::EnumVal(0) }
            else if schema.messages.contains_key(name) { DecodedValue::Message(Box::new(DecodedMsg::new())) }
            else { DecodedValue::Int32(0) }
        }
    }
}

// ==================== JSON OUTPUT ====================

fn is_default_scalar(v: &DecodedValue) -> bool {
    match v {
        DecodedValue::Int32(x) => *x == 0,
        DecodedValue::Int64(x) => *x == 0,
        DecodedValue::Uint32(x) => *x == 0,
        DecodedValue::Uint64(x) => *x == 0,
        DecodedValue::Bool(x) => !*x,
        DecodedValue::Str(x) => x.is_empty(),
        DecodedValue::Bytes(x) => x.is_empty(),
        DecodedValue::EnumVal(x) => *x == 0,
        DecodedValue::Message(_) => false,
    }
}

fn value_to_json(v: &DecodedValue, schema: &Schema, type_ref: &TypeRef) -> String {
    match v {
        DecodedValue::Int32(x) => format!("{}", x),
        DecodedValue::Int64(x) => format!("\"{}\"", x),
        DecodedValue::Uint32(x) => format!("{}", x),
        DecodedValue::Uint64(x) => format!("\"{}\"", x),
        DecodedValue::Bool(x) => if *x { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(s) => format!("\"{}\"", json_escape(s)),
        DecodedValue::Bytes(b) => format!("\"{}\"", base64_encode(b)),
        DecodedValue::EnumVal(x) => {
            if let TypeRef::Named(name) = type_ref {
                if let Some(ed) = schema.enums.get(name) {
                    if let Some((vname, _)) = ed.values.iter().find(|(_, n)| *n == *x) {
                        return format!("\"{}\"", json_escape(vname));
                    }
                }
            }
            format!("{}", x)
        }
        DecodedValue::Message(m) => msg_to_json(m, schema, type_ref),
    }
}

fn msg_to_json(msg: &DecodedMsg, schema: &Schema, type_ref: &TypeRef) -> String {
    let msg_name = match type_ref {
        TypeRef::Named(n) => n.as_str(),
        _ => "",
    };
    msg_to_json_named(msg, schema, msg_name)
}

fn msg_to_json_named(msg: &DecodedMsg, schema: &Schema, msg_name: &str) -> String {
    let mdef = match schema.messages.get(msg_name) { Some(m) => m, None => return "{}".to_string() };
    let mut parts: Vec<String> = vec![];
    let mut sorted_fields: Vec<&FieldDef> = mdef.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    for fdef in &sorted_fields {
        let fd = match msg.fields.get(&fdef.number) { Some(fd) => fd, None => continue };
        if !fd.seen { continue; }

        let is_map = fdef.map_key.is_some();
        let is_repeated = fdef.label == Label::Repeated && !is_map;
        let is_oneof = fdef.label == Label::Oneof;
        let is_optional = fdef.label == Label::Optional;

        if is_map {
            if fd.map_entries.is_empty() { continue; }
            let mut entries: Vec<(&MapKey, &DecodedValue)> = fd.map_entries.iter().collect();
            entries.sort_by(|a, b| match (a.0, b.0) {
                (MapKey::Str(a), MapKey::Str(b)) => a.as_bytes().cmp(b.as_bytes()),
                (MapKey::Int(a), MapKey::Int(b)) => a.cmp(b),
                _ => std::cmp::Ordering::Equal,
            });
            let mut map_parts = vec![];
            for (k, v) in &entries {
                let key_str = match k {
                    MapKey::Str(s) => format!("\"{}\"", json_escape(s)),
                    MapKey::Int(i) => format!("\"{}\"", i),
                };
                let val_json = value_to_json(v, schema, fdef.map_val.as_ref().unwrap());
                map_parts.push(format!("{}:{}", key_str, val_json));
            }
            parts.push(format!("\"{}\":{{{}}}", camel_case(&fdef.name), map_parts.join(",")));
        } else if is_repeated {
            if fd.values.is_empty() { continue; }
            let arr: Vec<String> = fd.values.iter().map(|v| value_to_json(v, schema, &fdef.type_ref)).collect();
            parts.push(format!("\"{}\":[{}]", camel_case(&fdef.name), arr.join(",")));
        } else {
            // Singular, optional, or oneof
            let v = match fd.values.first() { Some(v) => v, None => continue };
            // Presence check
            if is_oneof {
                // Check if this is the set member
                if let Some(ref oname) = fdef.oneof_name {
                    let set_member = msg.oneof_state.get(oname).cloned().flatten();
                    if set_member != Some(fdef.number) { continue; }
                }
                // Always print oneof members
                parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
            } else if is_optional {
                // Always print optional fields that appeared
                parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
            } else {
                // Singular: omit if default
                let is_msg = matches!(v, DecodedValue::Message(_));
                if is_msg {
                    parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
                } else if !is_default_scalar(v) {
                    parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
                }
            }
        }
    }
    format!("{{{}}}", parts.join(","))
}

// ==================== MAIN ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = if args.len() > 1 { &args[1] } else { "." };

    let proto_path = format!("{}/schema.proto", dir);
    let bin_path = format!("{}/messages.bin", dir);

    let proto_content = fs::read(&proto_path).unwrap_or_default();
    let bin_content = fs::read(&bin_path).unwrap_or_default();

    let schema = parse_proto(proto_content);

    let mut rd = Reader::new(&bin_content);
    let mut output = String::new();
    while !rd.eof() {
        let len = match rd.read_varint() { Some(l) => l as usize, None => break };
        if rd.pos + len > rd.data.len() { break; }
        let msg_data = &rd.data[rd.pos..rd.pos + len];
        rd.pos += len;
        let decoded = decode_message(msg_data, &schema, &schema.root);
        let json = msg_to_json_named(&decoded, &schema, &schema.root);
        output.push_str(&json);
        output.push('\n');
    }
    print!("{}", output);
}

use std::collections::HashMap;
use std::env;
use std::fs;

// ==================== UTILITIES ====================

const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn base64_encode(data: &[u8]) -> String {
    let mut r = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i + 2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(B64[((n >> 18) & 63) as usize] as char);
        r.push(B64[((n >> 12) & 63) as usize] as char);
        if i + 1 < data.len() { r.push(B64[((n >> 6) & 63) as usize] as char); } else { r.push('='); }
        if i + 2 < data.len() { r.push(B64[(n & 63) as usize] as char); } else { r.push('='); }
        i += 3;
    }
    r
}

fn camel_case(name: &str) -> String {
    let mut r = String::new();
    let mut upper_next = false;
    for ch in name.chars() {
        if ch == '_' {
            upper_next = true;
        } else {
            if upper_next {
                upper_next = false;
                if ch.is_ascii_lowercase() {
                    r.push(ch.to_ascii_uppercase());
                } else {
                    r.push(ch);
                }
            } else {
                r.push(ch);
            }
        }
    }
    r
}

fn json_escape(s: &str) -> String {
    let mut r = String::new();
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\t' => r.push_str("\\t"),
            '\n' => r.push_str("\\n"),
            '\u{0C}' => r.push_str("\\f"),
            '\r' => r.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                r.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => r.push(ch),
        }
    }
    r
}

// ==================== SCHEMA TYPES ====================

#[derive(Debug, Clone, PartialEq)]
enum ScalarType { Int32, Int64, Uint32, Uint64, Sint32, Sint64, Bool, Str, Bytes, Fixed32, Fixed64, Sfixed32, Sfixed64 }

#[derive(Debug, Clone)]
enum TypeRef { Scalar(ScalarType), Named(String) }

#[derive(Debug, Clone, PartialEq)]
enum Label { Singular, Optional, Repeated, Oneof }

#[derive(Debug, Clone)]
struct FieldDef {
    name: String,
    number: u32,
    label: Label,
    type_ref: TypeRef,
    oneof_name: Option<String>,
    map_key: Option<TypeRef>,
    map_val: Option<TypeRef>,
}

#[derive(Debug, Clone)]
struct MsgDef { name: String, fields: Vec<FieldDef> }

#[derive(Debug, Clone)]
struct EnumDef { name: String, values: Vec<(String, i32)> }

struct Schema {
    messages: HashMap<String, MsgDef>,
    enums: HashMap<String, EnumDef>,
    root: String,
}

// ==================== LEXER ====================

struct Lexer { data: Vec<u8>, pos: usize }

impl Lexer {
    fn new(data: Vec<u8>) -> Self { Lexer { data, pos: 0 } }
    fn eof(&self) -> bool { self.pos >= self.data.len() }
    fn peek_byte(&self) -> Option<u8> { if self.pos < self.data.len() { Some(self.data[self.pos]) } else { None } }
    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.data.len() && (self.data[self.pos] as char).is_ascii_whitespace() { self.pos += 1; }
            if self.pos + 1 < self.data.len() && self.data[self.pos] == b'/' && self.data[self.pos + 1] == b'/' {
                while self.pos < self.data.len() && self.data[self.pos] != b'\n' { self.pos += 1; }
                continue;
            }
            if self.pos + 1 < self.data.len() && self.data[self.pos] == b'/' && self.data[self.pos + 1] == b'*' {
                self.pos += 2;
                while self.pos + 1 < self.data.len() {
                    if self.data[self.pos] == b'*' && self.data[self.pos + 1] == b'/' { self.pos += 2; break; }
                    self.pos += 1;
                }
                continue;
            }
            break;
        }
    }
    fn peek_char(&mut self) -> Option<u8> { self.skip_ws(); self.peek_byte() }
    fn expect_byte(&mut self, b: u8) { self.skip_ws(); if self.pos < self.data.len() && self.data[self.pos] == b { self.pos += 1; } }
    fn read_ident(&mut self) -> String {
        self.skip_ws();
        let start = self.pos;
        while self.pos < self.data.len() && ((self.data[self.pos] as char).is_ascii_alphanumeric() || self.data[self.pos] == b'_') {
            self.pos += 1;
        }
        String::from_utf8_lossy(&self.data[start..self.pos]).into_owned()
    }
    fn read_string(&mut self) -> String {
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b'"' {
            self.pos += 1;
            let start = self.pos;
            while self.pos < self.data.len() && self.data[self.pos] != b'"' { self.pos += 1; }
            let s = String::from_utf8_lossy(&self.data[start..self.pos]).into_owned();
            if self.pos < self.data.len() { self.pos += 1; }
            s
        } else { String::new() }
    }
    fn read_number(&mut self) -> i64 {
        self.skip_ws();
        let neg = if self.pos < self.data.len() && self.data[self.pos] == b'-' { self.pos += 1; true } else { false };
        let start = self.pos;
        while self.pos < self.data.len() && (self.data[self.pos] as char).is_ascii_digit() { self.pos += 1; }
        let v: i64 = String::from_utf8_lossy(&self.data[start..self.pos]).parse().unwrap_or(0);
        if neg { -v } else { v }
    }
    fn skip_to(&mut self, b: u8) {
        self.skip_ws();
        while self.pos < self.data.len() {
            if self.data[self.pos] == b { self.pos += 1; return; }
            if self.data[self.pos] == b'"' {
                self.pos += 1;
                while self.pos < self.data.len() && self.data[self.pos] != b'"' { self.pos += 1; }
                if self.pos < self.data.len() { self.pos += 1; }
            } else {
                self.pos += 1;
            }
        }
    }
    fn skip_option_value(&mut self) {
        self.skip_ws();
        match self.peek_byte() {
            Some(b'"') => { self.read_string(); }
            Some(b'-') => { self.read_number(); }
            Some(c) if c >= b'0' && c <= b'9' => { self.read_number(); }
            _ => { self.read_ident(); }
        }
    }
}

// ==================== PARSER ====================

fn parse_scalar_type(name: &str) -> Option<ScalarType> {
    match name {
        "int32" => Some(ScalarType::Int32), "int64" => Some(ScalarType::Int64),
        "uint32" => Some(ScalarType::Uint32), "uint64" => Some(ScalarType::Uint64),
        "sint32" => Some(ScalarType::Sint32), "sint64" => Some(ScalarType::Sint64),
        "bool" => Some(ScalarType::Bool), "string" => Some(ScalarType::Str),
        "bytes" => Some(ScalarType::Bytes), "fixed32" => Some(ScalarType::Fixed32),
        "fixed64" => Some(ScalarType::Fixed64), "sfixed32" => Some(ScalarType::Sfixed32),
        "sfixed64" => Some(ScalarType::Sfixed64),
        _ => None,
    }
}

fn parse_type_ref(lx: &mut Lexer) -> TypeRef {
    let name = lx.read_ident();
    if let Some(st) = parse_scalar_type(&name) { TypeRef::Scalar(st) } else { TypeRef::Named(name) }
}

fn skip_options_brackets(lx: &mut Lexer) {
    if lx.peek_char() == Some(b'[') {
        lx.expect_byte(b'[');
        loop {
            let c = lx.peek_char();
            if c == Some(b']') || c == None { lx.expect_byte(b']'); break; }
            lx.read_ident();
            lx.expect_byte(b'=');
            lx.skip_option_value();
            if lx.peek_char() == Some(b',') { lx.expect_byte(b','); }
        }
    }
}

fn parse_fields_in_block(lx: &mut Lexer, msg: &mut MsgDef, oneof_name: Option<&str>) {
    loop {
        let c = lx.peek_char();
        if c == Some(b'}') || c == None { break; }
        let ident = {
            let save = lx.pos;
            lx.skip_ws();
            let s = lx.read_ident();
            if s.is_empty() { lx.pos = save; break; }
            s
        };
        match ident.as_str() {
            "message" => { lx.read_ident(); lx.expect_byte(b'{'); let mut _m = MsgDef { name: String::new(), fields: vec![] }; parse_fields_in_block(lx, &mut _m, None); lx.expect_byte(b'}'); }
            "enum" => { lx.read_ident(); lx.expect_byte(b'{'); loop { let c2 = lx.peek_char(); if c2 == Some(b'}') || c2 == None { break; } lx.read_ident(); lx.expect_byte(b'='); lx.read_number(); skip_options_brackets(lx); lx.expect_byte(b';'); } lx.expect_byte(b'}'); }
            "oneof" => { let oname = lx.read_ident(); lx.expect_byte(b'{'); parse_fields_in_block(lx, msg, Some(&oname)); lx.expect_byte(b'}'); }
            "reserved" => { lx.skip_to(b';'); }
            "option" => { lx.read_ident(); lx.expect_byte(b'='); lx.skip_option_value(); lx.expect_byte(b';'); }
            "map" => {
                lx.expect_byte(b'<');
                let kt = parse_type_ref(lx);
                lx.expect_byte(b',');
                let vt = parse_type_ref(lx);
                lx.expect_byte(b'>');
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                msg.fields.push(FieldDef { name: fname, number: fnum, label: Label::Repeated, type_ref: TypeRef::Named(String::new()), oneof_name: None, map_key: Some(kt), map_val: Some(vt) });
            }
            "repeated" | "optional" => {
                let label = if ident == "repeated" { Label::Repeated } else { Label::Optional };
                let tr = parse_type_ref(lx);
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                msg.fields.push(FieldDef { name: fname, number: fnum, label, type_ref: tr, oneof_name: oneof_name.map(|s| s.to_string()), map_key: None, map_val: None });
            }
            _ => {
                let tr = if let Some(st) = parse_scalar_type(&ident) { TypeRef::Scalar(st) } else { TypeRef::Named(ident) };
                let fname = lx.read_ident();
                lx.expect_byte(b'=');
                let fnum = lx.read_number() as u32;
                skip_options_brackets(lx);
                lx.expect_byte(b';');
                let label = if oneof_name.is_some() { Label::Oneof } else { Label::Singular };
                msg.fields.push(FieldDef { name: fname, number: fnum, label, type_ref: tr, oneof_name: oneof_name.map(|s| s.to_string()), map_key: None, map_val: None });
            }
        }
    }
}

fn parse_proto(content: Vec<u8>) -> Schema {
    let mut lx = Lexer::new(content);
    let mut messages: HashMap<String, MsgDef> = HashMap::new();
    let mut enums: HashMap<String, EnumDef> = HashMap::new();
    let mut root = String::new();
    let mut first_msg = true;

    loop {
        let c = lx.peek_char();
        if c == None { break; }
        let ident = lx.read_ident();
        if ident.is_empty() { break; }
        match ident.as_str() {
            "syntax" | "package" => { lx.expect_byte(b'='); lx.skip_to(b';'); }
            "option" => { lx.read_ident(); lx.expect_byte(b'='); lx.skip_option_value(); lx.expect_byte(b';'); }
            "import" => { lx.skip_to(b';'); }
            "message" => {
                let name = lx.read_ident();
                lx.expect_byte(b'{');
                let mut msg = MsgDef { name: name.clone(), fields: vec![] };
                parse_fields_in_block(&mut lx, &mut msg, None);
                lx.expect_byte(b'}');
                if first_msg { root = name.clone(); first_msg = false; }
                messages.insert(name, msg);
            }
            "enum" => {
                let name = lx.read_ident();
                lx.expect_byte(b'{');
                let mut ed = EnumDef { name: name.clone(), values: vec![] };
                loop {
                    let c2 = lx.peek_char();
                    if c2 == Some(b'}') || c2 == None { break; }
                    let vname = lx.read_ident();
                    lx.expect_byte(b'=');
                    let vval = lx.read_number() as i32;
                    skip_options_brackets(&mut lx);
                    lx.expect_byte(b';');
                    ed.values.push((vname, vval));
                }
                lx.expect_byte(b'}');
                enums.insert(name, ed);
            }
            _ => { lx.skip_to(b';'); }
        }
    }
    Schema { messages, enums, root }
}

// ==================== DECODER ====================

#[derive(Debug, Clone)]
enum DecodedValue {
    Int32(i32), Int64(i64), Uint32(u32), Uint64(u64),
    Bool(bool), Str(String), Bytes(Vec<u8>),
    EnumVal(i32), Message(Box<DecodedMsg>),
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum MapKey { Str(String), Int(i32) }

#[derive(Debug, Clone)]
struct FieldData {
    seen: bool,
    values: Vec<DecodedValue>,
    map_entries: HashMap<MapKey, DecodedValue>,
}

#[derive(Debug, Clone)]
struct DecodedMsg {
    fields: HashMap<u32, FieldData>,
    oneof_state: HashMap<String, Option<u32>>,
}

impl DecodedMsg {
    fn new() -> Self { DecodedMsg { fields: HashMap::new(), oneof_state: HashMap::new() } }
}

struct Reader<'a> { data: &'a [u8], pos: usize }

impl<'a> Reader<'a> {
    fn new(data: &'a [u8]) -> Self { Reader { data, pos: 0 } }
    fn eof(&self) -> bool { self.pos >= self.data.len() }
    fn read_byte(&mut self) -> Option<u8> { if self.pos < self.data.len() { let b = self.data[self.pos]; self.pos += 1; Some(b) } else { None } }
    fn read_varint(&mut self) -> Option<u64> {
        let mut result: u64 = 0;
        let mut shift = 0;
        for _ in 0..10 {
            let b = self.read_byte()?;
            result |= ((b & 0x7F) as u64) << shift;
            if b & 0x80 == 0 { return Some(result); }
            shift += 7;
        }
        Some(result)
    }
    fn read_fixed32(&mut self) -> Option<u32> {
        if self.pos + 4 > self.data.len() { return None; }
        let v = u32::from_le_bytes([self.data[self.pos], self.data[self.pos+1], self.data[self.pos+2], self.data[self.pos+3]]);
        self.pos += 4;
        Some(v)
    }
    fn read_fixed64(&mut self) -> Option<u64> {
        if self.pos + 8 > self.data.len() { return None; }
        let v = u64::from_le_bytes([self.data[self.pos],self.data[self.pos+1],self.data[self.pos+2],self.data[self.pos+3],self.data[self.pos+4],self.data[self.pos+5],self.data[self.pos+6],self.data[self.pos+7]]);
        self.pos += 8;
        Some(v)
    }
    fn read_bytes(&mut self) -> Option<&'a [u8]> {
        let len = self.read_varint()? as usize;
        if self.pos + len > self.data.len() { return None; }
        let b = &self.data[self.pos..self.pos+len];
        self.pos += len;
        Some(b)
    }
}

fn is_numeric_or_enum(tr: &TypeRef, schema: &Schema) -> bool {
    match tr {
        TypeRef::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
            ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool |
            ScalarType::Fixed32 | ScalarType::Fixed64 | ScalarType::Sfixed32 | ScalarType::Sfixed64 => true,
            _ => false,
        },
        TypeRef::Named(n) => schema.enums.contains_key(n),
    }
}

fn scalar_wire_type(st: &ScalarType) -> u8 {
    match st {
        ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool => 0,
        ScalarType::Str | ScalarType::Bytes => 2,
        ScalarType::Fixed32 | ScalarType::Sfixed32 => 5,
        ScalarType::Fixed64 | ScalarType::Sfixed64 => 1,
    }
}

fn decode_scalar_value(rd: &mut Reader, st: &ScalarType) -> Option<DecodedValue> {
    match st {
        ScalarType::Int32 => { let v = rd.read_varint()?; Some(DecodedValue::Int32(v as u32 as i32)) }
        ScalarType::Int64 => { let v = rd.read_varint()?; Some(DecodedValue::Int64(v as i64)) }
        ScalarType::Uint32 => { let v = rd.read_varint()?; Some(DecodedValue::Uint32(v as u32)) }
        ScalarType::Uint64 => { let v = rd.read_varint()?; Some(DecodedValue::Uint64(v)) }
        ScalarType::Sint32 => { let v = rd.read_varint()?; let v32 = v as u32; Some(DecodedValue::Int32(((v32 >> 1) as i32) ^ -((v32 & 1) as i32))) }
        ScalarType::Sint64 => { let v = rd.read_varint()?; Some(DecodedValue::Int64(((v >> 1) as i64) ^ -((v & 1) as i64))) }
        ScalarType::Bool => { let v = rd.read_varint()?; Some(DecodedValue::Bool(v != 0)) }
        ScalarType::Str => { let b = rd.read_bytes()?; Some(DecodedValue::Str(String::from_utf8_lossy(b).into_owned())) }
        ScalarType::Bytes => { let b = rd.read_bytes()?; Some(DecodedValue::Bytes(b.to_vec())) }
        ScalarType::Fixed32 => { let v = rd.read_fixed32()?; Some(DecodedValue::Uint32(v)) }
        ScalarType::Fixed64 => { let v = rd.read_fixed64()?; Some(DecodedValue::Uint64(v)) }
        ScalarType::Sfixed32 => { let v = rd.read_fixed32()?; Some(DecodedValue::Int32(v as i32)) }
        ScalarType::Sfixed64 => { let v = rd.read_fixed64()?; Some(DecodedValue::Int64(v as i64)) }
    }
}

fn decode_enum_value(rd: &mut Reader) -> Option<DecodedValue> {
    let v = rd.read_varint()?;
    Some(DecodedValue::EnumVal(v as u32 as i32))
}

fn decode_packed(rd: &mut Reader, st: &ScalarType) -> Vec<DecodedValue> {
    let mut vals = vec![];
    while !rd.eof() {
        match decode_scalar_value(rd, st) {
            Some(v) => vals.push(v),
            None => break,
        }
    }
    vals
}

fn decode_packed_enum(rd: &mut Reader) -> Vec<DecodedValue> {
    let mut vals = vec![];
    while !rd.eof() {
        match decode_enum_value(rd) {
            Some(v) => vals.push(v),
            None => break,
        }
    }
    vals
}

fn skip_group(rd: &mut Reader, group_fnum: u32) {
    loop {
        let key = match rd.read_varint() { Some(k) => k, None => return };
        let fnum = (key >> 3) as u32;
        let wt = (key & 7) as u8;
        if wt == 4 && fnum == group_fnum { return; }
        match wt {
            0 => { rd.read_varint(); }
            1 => { rd.read_fixed64(); }
            2 => { rd.read_bytes(); }
            5 => { rd.read_fixed32(); }
            3 => { skip_group(rd, fnum); }
            4 => {}
            _ => { return; }
        }
    }
}

fn decode_message(data: &[u8], schema: &Schema, msg_name: &str) -> DecodedMsg {
    let mut msg = DecodedMsg::new();
    let mdef = match schema.messages.get(msg_name) { Some(m) => m, None => return msg };
    let mut rd = Reader::new(data);

    while !rd.eof() {
        let key = match rd.read_varint() { Some(k) => k, None => break };
        let fnum = (key >> 3) as u32;
        let wt = (key & 7) as u8;

        let fdef = mdef.fields.iter().find(|f| f.number == fnum);
        let fdef = match fdef { Some(f) => f.clone(), None => {
            match wt {
                0 => { rd.read_varint(); }
                1 => { rd.read_fixed64(); }
                2 => { rd.read_bytes(); }
                5 => { rd.read_fixed32(); }
                3 => { skip_group(&mut rd, fnum); }
                4 => {}
                _ => { break; }
            }
            continue;
        }};

        // Handle oneof: clear other members
        if let Some(ref oname) = fdef.oneof_name {
            let current = msg.oneof_state.get(oname).cloned().flatten();
            if current != Some(fnum) {
                for f in &mdef.fields {
                    if f.oneof_name.as_deref() == Some(oname.as_str()) && f.number != fnum {
                        msg.fields.remove(&f.number);
                    }
                }
                msg.oneof_state.insert(oname.clone(), Some(fnum));
            }
        }

        let is_map = fdef.map_key.is_some();
        let is_repeated = fdef.label == Label::Repeated && !is_map;

        if is_map {
            if wt != 2 { match wt { 0 => { rd.read_varint(); } 1 => { rd.read_fixed64(); } 5 => { rd.read_fixed32(); } _ => {} } continue; }
            let payload = match rd.read_bytes() { Some(b) => b, None => break };
            let (key, val) = decode_map_entry(payload, schema, fdef.map_key.as_ref().unwrap(), fdef.map_val.as_ref().unwrap());
            let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            fd.map_entries.insert(key, val);
        } else if is_repeated && wt == 2 && is_numeric_or_enum(&fdef.type_ref, schema) {
            let payload = match rd.read_bytes() { Some(b) => b, None => break };
            let mut prd = Reader::new(payload);
            let vals = match &fdef.type_ref {
                TypeRef::Scalar(st) => decode_packed(&mut prd, st),
                TypeRef::Named(_) => decode_packed_enum(&mut prd),
            };
            let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            fd.values.extend(vals);
        } else {
            let val = decode_field_value(&mut rd, wt, &fdef.type_ref, schema);
            match val {
                Some(v) => {
                    let fd = msg.fields.entry(fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
                    fd.seen = true;
                    if is_repeated {
                        fd.values.push(v);
                    } else {
                        if let DecodedValue::Message(ref new_msg) = v {
                            if let Some(DecodedValue::Message(_)) = fd.values.first() {
                                fd.values[0] = DecodedValue::Message(Box::new(merge_messages(fd.values[0].clone(), new_msg, schema, &fdef.type_ref)));
                            } else {
                                fd.values = vec![v];
                            }
                        } else {
                            fd.values = vec![v];
                        }
                    }
                }
                None => {
                    match wt {
                        0 => { rd.read_varint(); }
                        1 => { rd.read_fixed64(); }
                        2 => { rd.read_bytes(); }
                        5 => { rd.read_fixed32(); }
                        3 => { skip_group(&mut rd, fnum); }
                        4 => {}
                        _ => {}
                    }
                }
            }
        }
    }
    msg
}

fn merge_messages(existing: DecodedValue, new_msg: &DecodedMsg, schema: &Schema, type_ref: &TypeRef) -> DecodedMsg {
    let msg_name = match type_ref {
        TypeRef::Named(n) => n.as_str(),
        _ => return (*new_msg).clone(),
    };
    let mut result = match existing {
        DecodedValue::Message(m) => (*m).clone(),
        _ => DecodedMsg::new(),
    };
    let mdef = match schema.messages.get(msg_name) { Some(m) => m, None => return result };

    for (fnum, new_fd) in &new_msg.fields {
        let fdef = mdef.fields.iter().find(|f| f.number == *fnum);
        let fdef = match fdef { Some(f) => f, None => continue };
        let is_map = fdef.map_key.is_some();
        let is_repeated = fdef.label == Label::Repeated && !is_map;

        if is_map {
            let fd = result.fields.entry(*fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            for (k, v) in &new_fd.map_entries {
                fd.map_entries.insert(k.clone(), v.clone());
            }
        } else if is_repeated {
            let fd = result.fields.entry(*fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
            fd.seen = true;
            fd.values.extend(new_fd.values.iter().cloned());
        } else {
            // singular or oneof
            let is_msg_field = matches!(fdef.type_ref, TypeRef::Named(ref n) if schema.messages.contains_key(n));
            if is_msg_field && !new_fd.values.is_empty() {
                if let Some(DecodedValue::Message(ref existing_msg)) = fd_values_first(&result, *fnum) {
                    let merged = merge_messages(DecodedValue::Message(existing_msg.clone()), new_msg, schema, &fdef.type_ref);
                    let fd = result.fields.entry(*fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
                    fd.seen = true;
                    fd.values = vec![DecodedValue::Message(Box::new(merged))];
                } else {
                    let fd = result.fields.entry(*fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
                    fd.seen = true;
                    fd.values = new_fd.values.clone();
                }
            } else {
                let fd = result.fields.entry(*fnum).or_insert_with(|| FieldData { seen: false, values: vec![], map_entries: HashMap::new() });
                fd.seen = true;
                fd.values = new_fd.values.clone();
            }
        }
    }
    // Merge oneof_state
    for (k, v) in &new_msg.oneof_state {
        if v.is_some() {
            result.oneof_state.insert(k.clone(), v.clone());
        }
    }
    result
}

fn fd_values_first(msg: &DecodedMsg, fnum: u32) -> Option<DecodedValue> {
    msg.fields.get(&fnum).and_then(|fd| fd.values.first().cloned())
}

fn decode_field_value(rd: &mut Reader, wt: u8, tr: &TypeRef, schema: &Schema) -> Option<DecodedValue> {
    match tr {
        TypeRef::Scalar(st) => {
            let expected_wt = scalar_wire_type(st);
            if wt == expected_wt {
                decode_scalar_value(rd, st)
            } else if wt == 2 && matches!(st, ScalarType::Int32|ScalarType::Int64|ScalarType::Uint32|ScalarType::Uint64|ScalarType::Sint32|ScalarType::Sint64|ScalarType::Bool|ScalarType::Fixed32|ScalarType::Fixed64|ScalarType::Sfixed32|ScalarType::Sfixed64) {
                let payload = rd.read_bytes()?;
                let mut prd = Reader::new(payload);
                decode_scalar_value(&mut prd, st)
            } else {
                match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None }
            }
        }
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name) {
                if wt == 0 { decode_enum_value(rd) } else { match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None } }
            } else if schema.messages.contains_key(name) {
                if wt == 2 {
                    let payload = rd.read_bytes()?;
                    let sub = decode_message(payload, schema, name);
                    Some(DecodedValue::Message(Box::new(sub)))
                } else { match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 5 => { rd.read_fixed32()?; None } _ => None } }
            } else {
                match wt { 0 => { rd.read_varint()?; None } 1 => { rd.read_fixed64()?; None } 2 => { rd.read_bytes()?; None } 5 => { rd.read_fixed32()?; None } _ => None }
            }
        }
    }
}

fn decode_map_entry(data: &[u8], schema: &Schema, key_type: &TypeRef, val_type: &TypeRef) -> (MapKey, DecodedValue) {
    let mut key: Option<MapKey> = None;
    let mut val: Option<DecodedValue> = None;
    let mut rd = Reader::new(data);
    while !rd.eof() {
        let k = match rd.read_varint() { Some(k) => k, None => break };
        let fn_ = (k >> 3) as u32;
        let wt = (k & 7) as u8;
        if fn_ == 1 {
            key = Some(decode_map_key(&mut rd, wt, key_type));
        } else if fn_ == 2 {
            val = decode_field_value(&mut rd, wt, val_type, schema);
        } else {
            match wt { 0 => { rd.read_varint(); } 1 => { rd.read_fixed64(); } 2 => { rd.read_bytes(); } 5 => { rd.read_fixed32(); } 3 => { skip_group(&mut rd, fn_); } 4 => {} _ => {} }
        }
    }
    let mk = key.unwrap_or(MapKey::Str(String::new()));
    let mv = val.unwrap_or_else(|| default_value(val_type, schema));
    (mk, mv)
}

fn decode_map_key(rd: &mut Reader, wt: u8, kt: &TypeRef) -> MapKey {
    match kt {
        TypeRef::Scalar(ScalarType::Str) => {
            if wt == 2 { let b = rd.read_bytes().unwrap_or(&[]); MapKey::Str(String::from_utf8_lossy(b).into_owned()) } else { MapKey::Str(String::new()) }
        }
        TypeRef::Scalar(ScalarType::Int32) => {
            if wt == 0 { let v = rd.read_varint().unwrap_or(0); MapKey::Int(v as u32 as i32) } else { MapKey::Int(0) }
        }
        _ => MapKey::Str(String::new()),
    }
}

fn default_value(tr: &TypeRef, schema: &Schema) -> DecodedValue {
    match tr {
        TypeRef::Scalar(st) => match st {
            ScalarType::Int32 | ScalarType::Sint32 | ScalarType::Sfixed32 => DecodedValue::Int32(0),
            ScalarType::Int64 | ScalarType::Sint64 | ScalarType::Sfixed64 => DecodedValue::Int64(0),
            ScalarType::Uint32 | ScalarType::Fixed32 => DecodedValue::Uint32(0),
            ScalarType::Uint64 | ScalarType::Fixed64 => DecodedValue::Uint64(0),
            ScalarType::Bool => DecodedValue::Bool(false),
            ScalarType::Str => DecodedValue::Str(String::new()),
            ScalarType::Bytes => DecodedValue::Bytes(vec![]),
        },
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name) { DecodedValue::EnumVal(0) }
            else if schema.messages.contains_key(name) { DecodedValue::Message(Box::new(DecodedMsg::new())) }
            else { DecodedValue::Int32(0) }
        }
    }
}

// ==================== JSON OUTPUT ====================

fn is_default_scalar(v: &DecodedValue) -> bool {
    match v {
        DecodedValue::Int32(x) => *x == 0,
        DecodedValue::Int64(x) => *x == 0,
        DecodedValue::Uint32(x) => *x == 0,
        DecodedValue::Uint64(x) => *x == 0,
        DecodedValue::Bool(x) => !*x,
        DecodedValue::Str(x) => x.is_empty(),
        DecodedValue::Bytes(x) => x.is_empty(),
        DecodedValue::EnumVal(x) => *x == 0,
        DecodedValue::Message(_) => false,
    }
}

fn value_to_json(v: &DecodedValue, schema: &Schema, type_ref: &TypeRef) -> String {
    match v {
        DecodedValue::Int32(x) => format!("{}", x),
        DecodedValue::Int64(x) => format!("\"{}\"", x),
        DecodedValue::Uint32(x) => format!("{}", x),
        DecodedValue::Uint64(x) => format!("\"{}\"", x),
        DecodedValue::Bool(x) => if *x { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(s) => format!("\"{}\"", json_escape(s)),
        DecodedValue::Bytes(b) => format!("\"{}\"", base64_encode(b)),
        DecodedValue::EnumVal(x) => {
            if let TypeRef::Named(name) = type_ref {
                if let Some(ed) = schema.enums.get(name) {
                    if let Some((vname, _)) = ed.values.iter().find(|(_, n)| *n == *x) {
                        return format!("\"{}\"", json_escape(vname));
                    }
                }
            }
            format!("{}", x)
        }
        DecodedValue::Message(m) => msg_to_json(m, schema, type_ref),
    }
}

fn msg_to_json(msg: &DecodedMsg, schema: &Schema, type_ref: &TypeRef) -> String {
    let msg_name = match type_ref {
        TypeRef::Named(n) => n.as_str(),
        _ => "",
    };
    msg_to_json_named(msg, schema, msg_name)
}

fn msg_to_json_named(msg: &DecodedMsg, schema: &Schema, msg_name: &str) -> String {
    let mdef = match schema.messages.get(msg_name) { Some(m) => m, None => return "{}".to_string() };
    let mut parts: Vec<String> = vec![];
    let mut sorted_fields: Vec<&FieldDef> = mdef.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    for fdef in &sorted_fields {
        let fd = match msg.fields.get(&fdef.number) { Some(fd) => fd, None => continue };
        if !fd.seen { continue; }

        let is_map = fdef.map_key.is_some();
        let is_repeated = fdef.label == Label::Repeated && !is_map;
        let is_oneof = fdef.label == Label::Oneof;
        let is_optional = fdef.label == Label::Optional;

        if is_map {
            if fd.map_entries.is_empty() { continue; }
            let mut entries: Vec<(&MapKey, &DecodedValue)> = fd.map_entries.iter().collect();
            entries.sort_by(|a, b| match (a.0, b.0) {
                (MapKey::Str(a), MapKey::Str(b)) => a.as_bytes().cmp(b.as_bytes()),
                (MapKey::Int(a), MapKey::Int(b)) => a.cmp(b),
                _ => std::cmp::Ordering::Equal,
            });
            let mut map_parts = vec![];
            for (k, v) in &entries {
                let key_str = match k {
                    MapKey::Str(s) => format!("\"{}\"", json_escape(s)),
                    MapKey::Int(i) => format!("\"{}\"", i),
                };
                let val_json = value_to_json(v, schema, fdef.map_val.as_ref().unwrap());
                map_parts.push(format!("{}:{}", key_str, val_json));
            }
            parts.push(format!("\"{}\":{{{}}}", camel_case(&fdef.name), map_parts.join(",")));
        } else if is_repeated {
            if fd.values.is_empty() { continue; }
            let arr: Vec<String> = fd.values.iter().map(|v| value_to_json(v, schema, &fdef.type_ref)).collect();
            parts.push(format!("\"{}\":[{}]", camel_case(&fdef.name), arr.join(",")));
        } else {
            let v = match fd.values.first() { Some(v) => v, None => continue };
            if is_oneof {
                if let Some(ref oname) = fdef.oneof_name {
                    let set_member = msg.oneof_state.get(oname).cloned().flatten();
                    if set_member != Some(fdef.number) { continue; }
                }
                parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
            } else if is_optional {
                parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
            } else {
                let is_msg = matches!(v, DecodedValue::Message(_));
                if is_msg {
                    parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
                } else if !is_default_scalar(v) {
                    parts.push(format!("\"{}\":{}", camel_case(&fdef.name), value_to_json(v, schema, &fdef.type_ref)));
                }
            }
        }
    }
    format!("{{{}}}", parts.join(","))
}

// ==================== MAIN ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = if args.len() > 1 { &args[1] } else { "." };

    let proto_path = format!("{}/schema.proto", dir);
    let bin_path = format!("{}/messages.bin", dir);

    let proto_content = fs::read(&proto_path).unwrap_or_default();
    let bin_content = fs::read(&bin_path).unwrap_or_default();

    let schema = parse_proto(proto_content);

    let mut rd = Reader::new(&bin_content);
    let mut output = String::new();
    while !rd.eof() {
        let len = match rd.read_varint() { Some(l) => l as usize, None => break };
        if rd.pos + len > rd.data.len() { break; }
        let msg_data = &rd.data[rd.pos..rd.pos + len];
        rd.pos += len;
        let decoded = decode_message(msg_data, &schema, &schema.root);
        let json = msg_to_json_named(&decoded, &schema, &schema.root);
        output.push_str(&json);
        output.push('\n');
    }
    print!("{}", output);
}

