                SMsg*nm=add_msg(id->text);
                parse_message_body(nm,-1);
                continue;
            }
            if(!strcmp(toks[tp].text,"enum")){
                tp++;Tok*id=expect(TK_IDENT);
                SEnum*e=add_enum(id->text);
                parse_enum_body(e);
                continue;
            }
            if(!strcmp(toks[tp].text,"oneof")){
                tp++;expect(TK_IDENT);
                int oid=m->nof++;
                parse_message_body(m,oid);
                continue;
            }
            if(!strcmp(toks[tp].text,"reserved")){tp++;skip_reserved();continue;}
            if(!strcmp(toks[tp].text,"option")){tp++;skip_option_stmt();continue;}
            /* field */
            int lbl=LBL_SING;
            if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"repeated")){tp++;lbl=LBL_REP;}
            else if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"optional")){tp++;lbl=LBL_OPT;}
            parse_field(m,lbl,cur_oneof);
        }else{tp++;}
    }
    expect(TK_RB);
}

static void parse_schema(void){
    tp=0;
    while(tp<ntoks&&toks[tp].t!=TK_EOF){
        if(toks[tp].t==TK_IDENT){
            if(!strcmp(toks[tp].text,"syntax")){skip_to_semi();continue;}
            if(!strcmp(toks[tp].text,"package")){skip_to_semi();continue;}
            if(!strcmp(toks[tp].text,"option")){tp++;skip_option_stmt();continue;}
            if(!strcmp(toks[tp].text,"message")){
                tp++;Tok*id=expect(TK_IDENT);
                SMsg*m=add_msg(id->text);
                if(!root_msg)root_msg=m;
                parse_message_body(m,-1);
                continue;
            }
            if(!strcmp(toks[tp].text,"enum")){
                tp++;Tok*id=expect(TK_IDENT);
                SEnum*e=add_enum(id->text);
                parse_enum_body(e);
                continue;
            }
        }
        tp++;
    }
    /* resolve type names */
    for(int i=0;i<nmsg;i++){
        SMsg*m=&msgs[i];
        for(int j=0;j<m->nf;j++){
            SField*f=&m->fields[j];
            if(f->type==FT_MESSAGE&&f->type_name){
                if(find_msg(f->type_name))f->type=FT_MESSAGE;
                else if(find_enum(f->type_name))f->type=FT_ENUM;
            }
            if(f->is_map&&f->map_val_type_name){
                if(find_msg(f->map_val_type_name))f->map_val_type=FT_MESSAGE;
                else if(find_enum(f->map_val_type_name))f->map_val_type=FT_ENUM;
            }
        }
    }
}

/* ============ Decoded Message ============ */
typedef struct DMsg DMsg;
typedef struct{
    FType type;char*type_name;
    int64_t i64;uint64_t u64;
    char*sdata;size_t slen;
    DMsg*msg;
}DVal;

typedef struct{
    SField*sf;bool is_set;
    int nv,cap;DVal*vals;
}DField;

struct DMsg{
    SMsg*schema;
    DField*fields;int nf;
    int*oneof_set;int nof;
};

static DVal*ensure_vals(DField*df,int n){
    if(df->nv+n>df->cap){df->cap=df->cap?df->cap*2:4;while(df->cap<df->nv+n)df->cap*=2;df->vals=xrealloc(df->vals,df->cap*sizeof(DVal));}
    return df->vals+df->nv;
}

static DMsg*new_dmsg(SMsg*m){
    DMsg*d=xmalloc(sizeof(DMsg));
    d->schema=m;d->nf=m->nf;
    d->fields=xmalloc(m->nf*sizeof(DField));
    memset(d->fields,0,m->nf*sizeof(DField));
    for(int i=0;i<m->nf;i++)d->fields[i].sf=&m->fields[i];
    d->nof=m->nof;
    d->oneof_set=xmalloc((m->nof>0?m->nof:1)*sizeof(int));
    for(int i=0;i<m->nof;i++)d->oneof_set[i]=-1;
    return d;
}

static SField*find_field(SMsg*m,int num){
    for(int i=0;i<m->nf;i++)if(m->fields[i].number==num)return &m->fields[i];
    return NULL;
}
static int field_idx(SMsg*m,int num){for(int i=0;i<m->nf;i++)if(m->fields[i].number==num)return i;return -1;}

/* ============ Binary Reader ============ */
static uint8_t *bindata;static size_t binlen,binpos;

static uint64_t rd_varint(void){
    uint64_t r=0;int sh=0;
    for(int i=0;i<10;i++){
        if(binpos>=binlen)return 0;
        uint8_t b=bindata[binpos++];
        r|=(uint64_t)(b&0x7F)<<sh;
        if(!(b&0x80))break;
        sh+=7;
    }
    return r;
}
static uint64_t rd_varint_at(uint8_t*d,size_t*p,size_t l){
    uint64_t r=0;int sh=0;
    for(int i=0;i<10;i++){
        if(*p>=l)return 0;
        uint8_t b=d[(*p)++];
        r|=(uint64_t)(b&0x7F)<<sh;
        if(!(b&0x80))break;
        sh+=7;
    }
    return r;
}

static void skip_unknown(uint8_t*d,size_t*p,size_t l,int wt,int fn){
    switch(wt){
        case 0:rd_varint_at(d,p,l);break;
        case 1:*p+=8;break;
        case 5:*p+=4;break;
        case 2:{uint64_t len=rd_varint_at(d,p,l);*p+=len;break;}
        case 3:{
            int depth=1;
            while(depth>0&&*p<l){
                uint64_t k=rd_varint_at(d,p,l);
                int w2=k&7,f2=k>>3;
                if(w2==3)depth++;
                else if(w2==4){if(f2==fn)depth--;else{/*shouldn't happen*/}}
                else skip_unknown(d,p,l,w2,f2);
            }
            break;
        }
        case 4:break;
    }
}

static uint64_t zigzag32(uint64_t n){return((uint32_t)n>>1)^-(uint32_t)(n&1);}
static uint64_t zigzag64(uint64_t n){return(n>>1)^-(n&1);}

static void decode_val(DVal*v,FType ft,const char*tn,uint8_t*d,size_t*p,size_t l,int wt){
    memset(v,0,sizeof(*v));
    v->type=ft;v->type_name=(char*)tn;
    switch(ft){
        case FT_INT32:case FT_UINT32:case FT_SINT32:case FT_BOOL:case FT_ENUM:
        case FT_INT64:case FT_UINT64:case FT_SINT64:
            v->u64=rd_varint_at(d,p,l);
            if(ft==FT_SINT32)v->u64=zigzag32(v->u64);
            if(ft==FT_SINT64)v->u64=zigzag64(v->u64);
            break;
        case FT_FIXED32:case FT_SFIXED32:{
            uint32_t x=0;if(*p+4<=l){x=d[*p]|(d[*p+1]<<8)|(d[*p+2]<<16)|((uint32_t)d[*p+3]<<24);}*p+=4;v->u64=x;break;
        }
        case FT_FIXED64:case FT_SFIXED64:{
            uint64_t x=0;if(*p+8<=l)memcpy(&x,d+*p,8);*p+=8;v->u64=x;break;
        }
        case FT_STRING:case FT_BYTES:{
            uint64_t len=rd_varint_at(d,p,l);
            if(*p+len<=l){v->sdata=xmalloc(len+1);memcpy(v->sdata,d+*p,len);v->sdata[len]=0;v->slen=len;}
            else{v->sdata=xmalloc(1);v->sdata[0]=0;v->slen=0;}
            *p+=len;break;
        }
        case FT_MESSAGE:{
            uint64_t len=rd_varint_at(d,p,l);
            SMsg*sm=find_msg(tn);
            if(!sm)sm=find_msg(tn);/* fallback */
            if(!sm){v->msg=new_dmsg(root_msg);}/* shouldn't happen */
            else{
                v->msg=new_dmsg(sm);
                size_t sub_start=*p;size_t sub_end=*p+len;
                if(sub_end>l)sub_end=l;
                decode_msg(d,sub_start,sub_end,v->msg,sm);
                *p=sub_end;
            }
            break;
        }
        default:break;
    }
}

static void decode_msg(uint8_t*d,size_t start,size_t end,DMsg*msg,SMsg*schema);

static void decode_msg(uint8_t*d,size_t start,size_t end,DMsg*msg,SMsg*schema){
    size_t p=start;
    while(p<end){
        uint64_t key=rd_varint_at(d,&p,end);
        int fn=key>>3,wt=key&7;
        SField*sf=find_field(schema,fn);
        if(!sf){skip_unknown(d,&p,end,wt,fn);continue;}
        int idx=field_idx(schema,fn);
        DField*df=&msg->fields[idx];
        if(sf->is_map){
            /* map entry: wire type 2, embedded msg with key=1, value=2 */
            if(wt!=2){skip_unknown(d,&p,end,wt,fn);continue;}
            uint64_t elen=rd_varint_at(d,&p,end);
            size_t es=p,ee=p+elen;if(ee>end)ee=end;
            /* decode key and value */
            DVal kv,vv;memset(&kv,0,sizeof(kv));memset(&vv,0,sizeof(vv));
            kv.type=sf->map_key_type;
            vv.type=sf->map_val_type;vv.type_name=sf->map_val_type_name;
            size_t ep=es;
            while(ep<ee){
                uint64_t ek=rd_varint_at(d,&ep,ee);
                int efn=ek>>3,ewt=ek&7;
                if(efn==1){
                    if(sf->map_key_type==FT_STRING){
                        uint64_t kl=rd_varint_at(d,&ep,ee);
                        if(ep+kl<=ee){kv.sdata=xmalloc(kl+1);memcpy(kv.sdata,d+ep,kl);kv.sdata[kl]=0;kv.slen=kl;}
                        else{kv.sdata=xmalloc(1);kv.sdata[0]=0;kv.slen=0;}
                        ep+=kl;
                    }else{kv.u64=rd_varint_at(d,&ep,ee);}
                }else if(efn==2){
                    decode_val(&vv,sf->map_val_type,sf->map_val_type_name,d,&ep,ee,ewt);
                }else{
                    skip_unknown(d,&ep,ee,ewt,efn);
                }
            }
            if(!kv.sdata&&sf->map_key_type==FT_STRING){kv.sdata=xmalloc(1);kv.sdata[0]=0;kv.slen=0;}
            /* update or add */
            bool found=false;
            for(int i=0;i<df->nv;i++){
                bool eq=false;
                if(sf->map_key_type==FT_STRING)eq=(df->vals[i].slen==kv.slen&&(!kv.slen||!memcmp(df->vals[i].sdata,kv.sdata,kv.slen)));
                else eq=(df->vals[i].u64==kv.u64);
                if(eq){df->vals[i+df->nv]=vv;/* store value in second half? No... */
                    /* Actually store key in vals[i], value in a parallel array */
                    /* Let me restructure: store pairs */
                    found=true;break;
                }
            }
            /* Hmm, I need to store key-value pairs. Let me use a different approach for maps. */
            /* For simplicity, store entries as: vals[2*i] = key, vals[2*i+1] = value */
            /* Actually let me just redo this with a proper approach */
            /* I'll store map entries in a separate way */
            p=ee;
            /* For now, append as pair */
            if(found){
                /* find and replace value */
                for(int i=0;i<df->nv;i++){
                    bool eq=false;
                    if(sf->map_key_type==FT_STRING)eq=(df->vals[2*i].slen==kv.slen&&(!kv.slen||!memcmp(df->vals[2*i].sdata,kv.sdata,kv.slen)));
                    else eq=(df->vals[2*i].u64==kv.u64);
                    if(eq){df->vals[2*i+1]=vv;break;}
                }
            }else{
                DVal*slot=ensure_vals(df,2);
                slot[0]=kv;slot[1]=vv;df->nv+=2;
            }
            df->is_set=true;
            continue;
        }
        if(sf->label==LBL_REP){
            /* repeated field */
            bool packable=(sf->type==FT_INT32||sf->type==FT_INT64||sf->type==FT_UINT32||sf->type==FT_UINT64||
                          sf->type==FT_SINT32||sf->type==FT_SINT64||sf->type==FT_BOOL||sf->type==FT_ENUM||
                          sf->type==FT_FIXED32||sf->type==FT_FIXED64||sf->type==FT_SFIXED32||sf->type==FT_SFIXED64);
            if(packable&&wt==2){
                /* packed */
                uint64_t plen=rd_varint_at(d,&p,end);
                size_t ps=p,pe=p+plen;if(pe>end)pe=end;
                while(ps<pe){
                    DVal*v=ensure_vals(df,1);
                    decode_val(v,sf->type,sf->type_name,d,&ps,pe,wt==2?0:wt);
                    /* determine correct wt for element */
                    df->nv++;
                }
                p=pe;
            }else{
                DVal*v=ensure_vals(df,1);
                decode_val(v,sf->type,sf->type_name,d,&p,end,wt);
                df->nv++;
            }
            df->is_set=true;
        }else if(sf->type==FT_MESSAGE){
            /* singular message */
            if(wt!=2){skip_unknown(d,&p,end,wt,fn);continue;}
            uint64_t mlen=rd_varint_at(d,&p,end);
            size_t ms=p,me=p+mlen;if(me>end)me=end;
            SMsg*sm=find_msg(sf->type_name);
            if(!sm){p=me;continue;}
            if(!df->is_set){
                df->is_set=true;df->nv=1;df->cap=1;
                df->vals=xmalloc(sizeof(DVal));
                memset(&df->vals[0],0,sizeof(DVal));
                df->vals[0].type=FT_MESSAGE;df->vals[0].type_name=sf->type_name;
                df->vals[0].msg=new_dmsg(sm);
                decode_msg(d,ms,me,df->vals[0].msg,sm);
            }else{
                /* merge */
                DMsg tmp;memset(&tmp,0,sizeof(tmp));
                DMsg*nm=new_dmsg(sm);
                decode_msg(d,ms,me,nm,sm);
                merge_msg(df->vals[0].msg,nm);
            }
            p=me;
            /* handle oneof */
            if(sf->oneof_idx>=0){
                int oi=sf->oneof_idx;
                int cur=msg->oneof_set[oi];
                if(cur>=0&&cur!=idx){
                    msg->fields[cur].is_set=false;msg->fields[cur].nv=0;
                }
                msg->oneof_set[oi]=idx;
            }
        }else{
            /* singular scalar */
            DVal v;
            decode_val(&v,sf->type,sf->type_name,d,&p,end,wt);
            if(sf->oneof_idx>=0){
                int oi=sf->oneof_idx;
                int cur=msg->oneof_set[oi];
                if(cur>=0&&cur!=idx){
                    msg->fields[cur].is_set=false;msg->fields[cur].nv=0;
                }
                msg->oneof_set[oi]=idx;
            }
            if(!df->is_set){df->cap=1;df->vals=xmalloc(sizeof(DVal));df->nv=1;}
            else df->nv=1;
            df->vals[0]=v;df->is_set=true;
        }
    }
}

/* Forward declaration fix - decode_val needs decode_msg */
/* Actually let me restructure. decode_val calls decode_msg for message types. */
/* I'll use a forward declaration. */

static void merge_msg(DMsg*dst,DMsg*src){
    for(int i=0;i<dst->nf;i++){
        DField*sf=&src->fields[i];
        if(!sf->is_set)continue;
        DField*df=&dst->fields[i];
        SField*sch=df->sf;
        if(sch->is_map){
            /* merge map entries */
            for(int j=0;j<sf->nv;j+=2){
                bool found=false;
                for(int k=0;k<df->nv;k+=2){
                    bool eq=false;
                    if(sch->map_key_type==FT_STRING)eq=(sf->vals[j].slen==df->vals[k].slen&&(!sf->vals[j].slen||!memcmp(sf->vals[j].sdata,df->vals[k].sdata,sf->vals[j].slen)));
                    else eq=(sf->vals[j].u64==df->vals[k].u64);
                    if(eq){df->vals[k+1]=sf->vals[j+1];found=true;break;}
                }
                if(!found){
                    DVal*slot=ensure_vals(df,2);
                    slot[0]=sf->vals[j];slot[1]=sf->vals[j+1];df->nv+=2;
                }
            }
            df->is_set=true;
        }else if(sch->label==LBL_REP){
            for(int j=0;j<sf->nv;j++){
                DVal*slot=ensure_vals(df,1);
                *slot=sf->vals[j];df->nv++;
            }
            df->is_set=true;
        }else if(sch->type==FT_MESSAGE){
            if(!df->is_set){
                df->is_set=true;df->nv=1;df->cap=1;
                df->vals=xmalloc(sizeof(DVal));
                df->vals[0]=sf->vals[0];
            }else{
                merge_msg(df->vals[0].msg,sf->vals[0].msg);
            }
            if(sch->oneof_idx>=0){
                int oi=sch->oneof_idx;
                int cur=dst->oneof_set[oi];
                if(cur>=0&&cur!=i){dst->fields[cur].is_set=false;dst->fields[cur].nv=0;}
                dst->oneof_set[oi]=i;
            }
        }else{
            /* scalar */
            if(sch->oneof_idx>=0){
                int oi=sch->oneof_idx;
                int cur=dst->oneof_set[oi];
                if(cur>=0&&cur!=i){dst->fields[cur].is_set=false;dst->fields[cur].nv=0;}
                dst->oneof_set[oi]=i;
            }
            if(!df->is_set){df->cap=1;df->vals=xmalloc(sizeof(DVal));df->nv=1;}
            else df->nv=1;
            df->vals[0]=sf->vals[0];df->is_set=true;
        }
    }
}

/* ============ JSON Output ============ */
static void emit_str(const char*s,size_t len){
    putchar('"');
    for(size_t i=0;i<len;i++){
        unsigned char c=s[i];
        if(c=='"')printf("\\\"");
        else if(c=='\\')printf("\\\\");
        else if(c==0x08)printf("\\b");
        else if(c==0x09)printf("\\t");
        else if(c==0x0A)printf("\\n");
        else if(c==0x0C)printf("\\f");
        else if(c==0x0D)printf("\\r");
        else if(c<0x20)printf("\\u00%02x",c);
        else putchar(c);
    }
    putchar('"');
}

static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void emit_b64(const char*data,size_t len){
    putchar('"');
    for(size_t i=0;i<len;i+=3){
        size_t rem=len-i;
        uint32_t v=(uint32_t)(unsigned char)data[i]<<16;
        if(rem>1)v|=(uint32_t)(unsigned char)data[i+1]<<8;
        if(rem>2)v|=(uint32_t)(unsigned char)data[i+2];
        putchar(b64[(v>>18)&63]);
        putchar(b64[(v>>12)&63]);
        putchar(rem>1?b64[(v>>6)&63]:'=');
        putchar(rem>2?b64[v&63]:'=');
    }
    putchar('"');
}

static void camel_name(const char*name){
    /* convert to lowerCamelCase */
    char buf[1024];int j=0;
    for(int i=0;name[i];i++){
        if(name[i]=='_'){
            i++;
            if(name[i]&&name[i]>='a'&&name[i]<='z')buf[j++]=name[i]-'a'+'A';
            else if(name[i])buf[j++]=name[i];
        }else buf[j++]=name[i];
    }
    buf[j]=0;
    emit_str(buf,j);
}

static bool is_default(DVal*v){
    switch(v->type){
        case FT_INT32:case FT_INT64:case FT_SINT32:case FT_SINT64:
        case FT_UINT32:case FT_UINT64:case FT_FIXED32:case FT_FIXED64:
        case FT_SFIXED32:case FT_SFIXED64:case FT_BOOL:case FT_ENUM:
            return v->u64==0;
        case FT_STRING:case FT_BYTES:
            return v->slen==0;
        default:return true;
    }
}

static void emit_val(DVal*v){
    switch(v->type){
        case FT_INT32:case FT_SINT32:case FT_SFIXED32:
            printf("%"PRId32,(int32_t)(uint32_t)v->u64);break;
        case FT_UINT32:case FT_FIXED32:
            printf("%"PRIu32,(uint32_t)v->u64);break;
        case FT_INT64:case FT_SINT64:case FT_SFIXED64:
            printf("\"%"PRId64"\"",(int64_t)v->u64);break;
        case FT_UINT64:case FT_FIXED64:
            printf("\"%"PRIu64"\"",v->u64);break;
        case FT_BOOL:
            printf(v->u64?"true":"false");break;
        case FT_STRING:
            emit_str(v->sdata,v->slen);break;
        case FT_BYTES:
            emit_b64(v->sdata,v->slen);break;
        case FT_ENUM:{
            SEnum*e=find_enum(v->type_name);
            int32_t val=(int32_t)(uint32_t)v->u64;
            if(e){
                for(int i=0;i<e->nv;i++){
                    if(e->vv[i]==val){printf("\"%s\"",e->vn[i]);return;}
                }
            }
            printf("%"PRId32,val);break;
        }
        case FT_MESSAGE:
            emit_msg(v->msg);break;
        default:break;
    }
}

static void emit_msg(DMsg*m);

/* map key comparison */
static int cmp_str_key(const void*a,const void*b){
    const DVal*va=(const DVal*)a;const DVal*vb=(const DVal*)b;
    return memcmp(va->sdata,vb->sdata,va->slen<vb->slen?va->slen:vb->slen)
           ||(int)va->slen-(int)vb->slen;
}
static int cmp_int_key(const void*a,const void*b){
    const DVal*va=(const DVal*)a;const DVal*vb=(const DVal*)b;
    int32_t ka=(int32_t)(uint32_t)va->u64,kb=(int32_t)(uint32_t)vb->u64;
    return (ka<kb)?-1:(ka>kb)?1:0;
}

static void emit_msg(DMsg*m){
    putchar('{');
    bool first=true;
    /* collect fields sorted by number */
    int *order=xmalloc(m->nf*sizeof(int));
    for(int i=0;i<m->nf;i++)order[i]=i;
    for(int i=0;i<m->nf;i++)for(int j=i+1;j<m->nf;j++){
        if(m->fields[order[j]].sf->number<m->fields[order[i]].sf->number){int t=order[i];order[i]=order[j];order[j]=t;}
    }
    for(int oi=0;oi<m->nf;oi++){
        int i=order[oi];
        DField*df=&m->fields[i];
        SField*sf=df->sf;
        if(!df->is_set)continue;
        /* presence check */
        if(sf->is_map){
            if(df->nv==0)continue;
        }else if(sf->label==LBL_REP){
            if(df->nv==0)continue;
        }else if(sf->type==FT_MESSAGE){
            /* always print if set */
        }else{
            /* singular scalar */
            bool in_oneof=sf->oneof_idx>=0;
            bool is_opt=(sf->label==LBL_OPT);
            if(in_oneof){
                if(m->oneof_set[sf->oneof_idx]!=i)continue;
            }else if(!is_opt){
                if(is_default(&df->vals[0]))continue;
            }
        }
        if(!first)putchar(',');
        first=false;
        camel_name(sf->name);
        putchar(':');
        if(sf->is_map){
            /* sort entries */
            int ne=df->nv/2;
            int *eo=xmalloc(ne*sizeof(int));
            for(int i=0;i<ne;i++)eo[i]=i;
            for(int i=0;i<ne;i++)for(int j=i+1;j<ne;j++){
                int cmp;
                if(sf->map_key_type==FT_STRING)cmp=cmp_str_key(&df->vals[2*eo[j]],&df->vals[2*eo[i]]);
                else cmp=cmp_int_key(&df->vals[2*eo[j]],&df->vals[2*eo[i]]);
                if(cmp<0){int t=eo[i];eo[i]=eo[j];eo[j]=t;}
            }
            putchar('{');
            for(int ei=0;ei<ne;ei++){
                if(ei)putchar(',');
                int idx2=2*eo[ei];
                if(sf->map_key_type==FT_STRING)emit_str(df->vals[idx2].sdata,df->vals[idx2].slen);
                else printf("\"%"PRId32"\"",(int32_t)(uint32_t)df->vals[idx2].u64);
                putchar(':');
                emit_val(&df->vals[idx2+1]);
            }
            putchar('}');
        }else if(sf->label==LBL_REP){
            putchar('[');
            for(int j=0;j<df->nv;j++){
                if(j)putchar(',');
                emit_val(&df->vals[j]);
            }
            putchar(']');
        }else{
            emit_val(&df->vals[0]);
        }
    }
    putchar('}');
}

/* ============ Main ============ */
int main(int argc,char*argv[]){
    (void)argc;(void)argv;
    /* read schema.proto */
    FILE*f=fopen("schema.proto","rb");
    if(!f){perror("schema.proto");return 1;}
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    src=xmalloc(sz+1);fread(src,1,sz,f);src[sz]=0;fclose(f);
    src_len=sz;
    tokenize();
    parse_schema();

    /* read messages.bin */
    f=fopen("messages.bin","rb");
    if(!f){perror("messages.bin");return 1;}
    fseek(f,0,SEEK_END);long bsz=ftell(f);fseek(f,0,SEEK_SET);
    bindata=xmalloc(bsz);fread(bindata,1,bsz,f);fclose(f);
    binlen=bsz;binpos=0;

    while(binpos<binlen){
        uint64_t rlen=rd_varint();
        if(rlen==0&&binpos>=binlen)break;
        if(binpos+rlen>binlen)rlen=binlen-binpos;
        DMsg*dm=new_dmsg(root_msg);
        decode_msg(bindata,binpos,binpos+rlen,dm,root_msg);
        emit_msg(dm);
        putchar('\n');
        binpos+=rlen;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <ctype.h>
#include <inttypes.h>

/* ============ Utilities ============ */
static void *xmalloc(size_t n){void*p=malloc(n);if(!p){fprintf(stderr,"OOM\n");exit(1);}return p;}
static void *xrealloc(void*p,size_t n){void*r=realloc(p,n);if(!r){fprintf(stderr,"OOM\n");exit(1);}return r;}
static char *xstrdup(const char*s){char*r=strdup(s);if(!r){fprintf(stderr,"OOM\n");exit(1);}return r;}

/* ============ Tokenizer ============ */
typedef enum{TK_EOF,TK_IDENT,TK_INT,TK_STR,TK_LB,TK_RB,TK_SEMI,TK_EQ,TK_LT,TK_GT,TK_LK,TK_RK,TK_COMMA,TK_DOT,TK_COLON,TK_MINUS}TokType;
typedef struct{TokType t;char*text;int ival;}Tok;

static char *src;
static size_t src_len,src_pos;
static Tok *toks;static int ntoks,ctoks;

static void add_tok(Tok t){if(ntoks>=ctoks){ctoks=ctoks?ctoks*2:256;toks=xrealloc(toks,ctoks*sizeof(Tok));}toks[ntoks++]=t;}

static void tokenize(void){
    src_pos=0;
    while(src_pos<src_len){
        while(src_pos<src_len&&isspace((unsigned char)src[src_pos]))src_pos++;
        if(src_pos>=src_len)break;
        if(src[src_pos]=='/'&&src_pos+1<src_len&&src[src_pos+1]=='/'){
            while(src_pos<src_len&&src[src_pos]!='\n')src_pos++;
            continue;
        }
        if(src[src_pos]=='/'&&src_pos+1<src_len&&src[src_pos+1]=='*'){
            src_pos+=2;
            while(src_pos+1<src_len&&!(src[src_pos]=='*'&&src[src_pos+1]=='/'))src_pos++;
            if(src_pos+1<src_len)src_pos+=2;
            continue;
        }
        char c=src[src_pos];
        if(c=='"'){
            src_pos++;
            size_t s=src_pos;
            while(src_pos<src_len&&src[src_pos]!='"')src_pos++;
            size_t len=src_pos-s;
            char*buf=xmalloc(len+1);memcpy(buf,src+s,len);buf[len]=0;
            if(src_pos<src_len)src_pos++;
            Tok t={TK_STR,buf,0};add_tok(t);
        }else if(isalpha((unsigned char)c)||c=='_'){
            size_t s=src_pos;
            while(src_pos<src_len&&(isalnum((unsigned char)src[src_pos])||src[src_pos]=='_'))src_pos++;
            size_t len=src_pos-s;
            char*buf=xmalloc(len+1);memcpy(buf,src+s,len);buf[len]=0;
            Tok t={TK_IDENT,buf,0};add_tok(t);
        }else if(isdigit((unsigned char)c)){
            size_t s=src_pos;
            while(src_pos<src_len&&isdigit((unsigned char)src[src_pos]))src_pos++;
            size_t len=src_pos-s;
            char*buf=xmalloc(len+1);memcpy(buf,src+s,len);buf[len]=0;
            Tok t={TK_INT,buf,(int)strtol(buf,NULL,10)};add_tok(t);
        }else{
            src_pos++;
            TokType tt;
            switch(c){
                case'{':tt=TK_LB;break;case'}':tt=TK_RB;break;
                case';':tt=TK_SEMI;break;case'=':tt=TK_EQ;break;
                case'<':tt=TK_LT;break;case'>':tt=TK_GT;break;
                case'[':tt=TK_LK;break;case']':tt=TK_RK;break;
                case',':tt=TK_COMMA;break;case'.':tt=TK_DOT;break;
                case':':tt=TK_COLON;break;case'-':tt=TK_MINUS;break;
                default:continue;
            }
            Tok t={tt,NULL,0};add_tok(t);
        }
    }
    Tok eof={TK_EOF,NULL,0};add_tok(eof);
}

static int tp;
static Tok*cur(void){return &toks[tp];}
static Tok*adv(void){return &toks[tp++];}
static bool match(TokType t){if(toks[tp].t==t){tp++;return true;}return false;}
static Tok*expect(TokType t){if(toks[tp].t!=t){fprintf(stderr,"Parse error at token %d type %d\n",tp,t);exit(1);}return &toks[tp++];}

/* ============ Schema ============ */
typedef enum{FT_INT32,FT_INT64,FT_UINT32,FT_UINT64,FT_SINT32,FT_SINT64,FT_BOOL,FT_STRING,FT_BYTES,FT_FIXED32,FT_FIXED64,FT_SFIXED32,FT_SFIXED64,FT_MESSAGE,FT_ENUM}FType;

#define LBL_SING 0
#define LBL_OPT 1
#define LBL_REP 2

typedef struct{
    char*name;int number;FType type;char*type_name;
    int label;int oneof_idx;
    bool is_map;FType map_key_type;FType map_val_type;char*map_val_type_name;
}SField;

typedef struct{char*name;int nv;char**vn;int*vv;}SEnum;
typedef struct{char*name;int nf;SField*fields;int cap_f;int nof;}SMsg;

static SMsg *msgs;static int nmsg,cm;
static SEnum *enums;static int nen,ce;
static SMsg *root_msg;

static SMsg*add_msg(const char*n){
    if(nmsg>=cm){cm=cm?cm*2:16;msgs=xrealloc(msgs,cm*sizeof(SMsg));}
    memset(&msgs[nmsg],0,sizeof(SMsg));
    msgs[nmsg].name=xstrdup(n);
    return &msgs[nmsg++];
}
static SEnum*add_enum(const char*n){
    if(nen>=ce){ce=ce?ce*2:16;enums=xrealloc(enums,ce*sizeof(SEnum));}
    memset(&enums[nen],0,sizeof(SEnum));
    enums[nen].name=xstrdup(n);
    return &enums[nen++];
}
static SMsg*find_msg(const char*n){for(int i=0;i<nmsg;i++)if(!strcmp(msgs[i].name,n))return &msgs[i];return NULL;}
static SEnum*find_enum(const char*n){for(int i=0;i<nen;i++)if(!strcmp(enums[i].name,n))return &enums[i];return NULL;}

static void add_field(SMsg*m,SField f){
    if(m->nf>=m->cap_f){m->cap_f=m->cap_f?m->cap_f*2:8;m->fields=xrealloc(m->fields,m->cap_f*sizeof(SField));}
    m->fields[m->nf++]=f;
}

static bool is_primitive(const char*n){
    static const char*prims[]={"int32","int64","uint32","uint64","sint32","sint64","bool","string","bytes","fixed32","fixed64","sfixed32","sfixed64",NULL};
    for(int i=0;prims[i];i++)if(!strcmp(n,prims[i]))return true;
    return false;
}
static FType prim_type(const char*n){
    if(!strcmp(n,"int32"))return FT_INT32;if(!strcmp(n,"int64"))return FT_INT64;
    if(!strcmp(n,"uint32"))return FT_UINT32;if(!strcmp(n,"uint64"))return FT_UINT64;
    if(!strcmp(n,"sint32"))return FT_SINT32;if(!strcmp(n,"sint64"))return FT_SINT64;
    if(!strcmp(n,"bool"))return FT_BOOL;if(!strcmp(n,"string"))return FT_STRING;
    if(!strcmp(n,"bytes"))return FT_BYTES;if(!strcmp(n,"fixed32"))return FT_FIXED32;
    if(!strcmp(n,"fixed64"))return FT_FIXED64;if(!strcmp(n,"sfixed32"))return FT_SFIXED32;
    if(!strcmp(n,"sfixed64"))return FT_SFIXED64;return FT_INT32;
}

static void skip_to_semi(void){while(tp<ntoks&&toks[tp].t!=TK_SEMI)tp++;if(tp<ntoks)tp++;}
static void skip_options(void){if(toks[tp].t==TK_LK){tp++;while(tp<ntoks&&toks[tp].t!=TK_RK)tp++;if(tp<ntoks)tp++;}}
static void skip_option_stmt(void){while(tp<ntoks&&toks[tp].t!=TK_SEMI)tp++;if(tp<ntoks)tp++;}
static void skip_reserved(void){while(tp<ntoks&&toks[tp].t!=TK_SEMI)tp++;if(tp<ntoks)tp++;}

static void parse_enum_body(SEnum*e){
    expect(TK_LB);
    while(tp<ntoks&&toks[tp].t!=TK_RB){
        if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"option")){tp++;skip_option_stmt();continue;}
        Tok*id=expect(TK_IDENT);
        expect(TK_EQ);
        int val=0;bool neg=false;
        if(toks[tp].t==TK_MINUS){tp++;neg=true;}
        Tok*n=expect(TK_INT);val=n->ival;if(neg)val=-val;
        skip_options();
        expect(TK_SEMI);
        e->vn=xrealloc(e->vn,(e->nv+1)*sizeof(char*));
        e->vv=xrealloc(e->vv,(e->nv+1)*sizeof(int));
        e->vn[e->nv]=xstrdup(id->text);e->vv[e->nv]=val;e->nv++;
    }
    expect(TK_RB);
}

static void parse_message_body(SMsg*m,int cur_oneof);
static void parse_field(SMsg*m,int label,int oneof_idx){
    SField f;memset(&f,0,sizeof(f));
    f.oneof_idx=oneof_idx;f.label=label;
    if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"map")){
        tp++;expect(TK_LT);
        Tok*kt=expect(TK_IDENT);
        f.map_key_type=prim_type(kt->text);f.is_map=true;
        expect(TK_COMMA);
        Tok*vt=expect(TK_IDENT);
        if(is_primitive(vt->text)){f.map_val_type=prim_type(vt->text);f.map_val_type_name=NULL;}
        else{f.map_val_type=FT_MESSAGE;f.map_val_type_name=xstrdup(vt->text);}
        expect(TK_GT);
        Tok*fn=expect(TK_IDENT);f.name=xstrdup(fn->text);
        expect(TK_EQ);
        f.number=expect(TK_INT)->ival;
        skip_options();
        expect(TK_SEMI);
        f.type=FT_MESSAGE;f.type_name=NULL;
        add_field(m,f);return;
    }
    Tok*tn=expect(TK_IDENT);
    if(is_primitive(tn->text)){f.type=prim_type(tn->text);f.type_name=NULL;}
    else{f.type=FT_MESSAGE;f.type_name=xstrdup(tn->text);}
    Tok*fn=expect(TK_IDENT);f.name=xstrdup(fn->text);
    expect(TK_EQ);
    f.number=expect(TK_INT)->ival;
    skip_options();
    expect(TK_SEMI);
    add_field(m,f);
}

static void parse_message_body(SMsg*m,int cur_oneof){
    expect(TK_LB);
    while(tp<ntoks&&toks[tp].t!=TK_RB){
        if(toks[tp].t==TK_IDENT){
            if(!strcmp(toks[tp].text,"message")){
                tp++;Tok*id=expect(TK_IDENT);
                SMsg*nm=add_msg(id->text);
                parse_message_body(nm,-1);
                continue;
            }
            if(!strcmp(toks[tp].text,"enum")){
                tp++;Tok*id=expect(TK_IDENT);
                SEnum*e=add_enum(id->text);
                parse_enum_body(e);
                continue;
            }
            if(!strcmp(toks[tp].text,"oneof")){
                tp++;expect(TK_IDENT);
                int oid=m->nof++;
                parse_message_body(m,oid);
                continue;
            }
            if(!strcmp(toks[tp].text,"reserved")){tp++;skip_reserved();continue;}
            if(!strcmp(toks[tp].text,"option")){tp++;skip_option_stmt();continue;}
            int lbl=LBL_SING;
            if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"repeated")){tp++;lbl=LBL_REP;}
            else if(toks[tp].t==TK_IDENT&&!strcmp(toks[tp].text,"optional")){tp++;lbl=LBL_OPT;}
            parse_field(m,lbl,cur_oneof);
        }else{tp++;}
    }
    expect(TK_RB);
}

static void parse_schema(void){
    tp=0;
    while(tp<ntoks&&toks[tp].t!=TK_EOF){
        if(toks[tp].t==TK_IDENT){
            if(!strcmp(toks[tp].text,"syntax")){skip_to_semi();continue;}
            if(!strcmp(toks[tp].text,"package")){skip_to_semi();continue;}
            if(!strcmp(toks[tp].text,"option")){tp++;skip_option_stmt();continue;}
            if(!strcmp(toks[tp].text,"message")){
                tp++;Tok*id=expect(TK_IDENT);
                SMsg*m=add_msg(id->text);
                if(!root_msg)root_msg=m;
                parse_message_body(m,-1);
                continue;
            }
            if(!strcmp(toks[tp].text,"enum")){
                tp++;Tok*id=expect(TK_IDENT);
                SEnum*e=add_enum(id->text);
                parse_enum_body(e);
                continue;
            }
        }
        tp++;
    }
    for(int i=0;i<nmsg;i++){
        SMsg*m=&msgs[i];
        for(int j=0;j<m->nf;j++){
            SField*f=&m->fields[j];
            if(f->type==FT_MESSAGE&&f->type_name){
                if(find_msg(f->type_name))f->type=FT_MESSAGE;
                else if(find_enum(f->type_name))f->type=FT_ENUM;
            }
            if(f->is_map&&f->map_val_type_name){
                if(find_msg(f->map_val_type_name))f->map_val_type=FT_MESSAGE;
                else if(find_enum(f->map_val_type_name))f->map_val_type=FT_ENUM;
            }
        }
    }
}

/* ============ Decoded Message ============ */
typedef struct DMsg DMsg;
typedef struct{
    FType type;char*type_name;
    int64_t i64;uint64_t u64;
    char*sdata;size_t slen;
    DMsg*msg;
}DVal;

typedef struct{
    SField*sf;bool is_set;
    int nv,cap;DVal*vals;
}DField;

struct DMsg{
    SMsg*schema;
    DField*fields;int nf;
    int*oneof_set;int nof;
};

/* Forward declarations */
static void decode_msg(uint8_t*d,size_t start,size_t end,DMsg*msg,SMsg*schema);
static void merge_msg(DMsg*dst,DMsg*src);
static void emit_msg(DMsg*m);

static DVal*ensure_vals(DField*df,int n){
    if(df->nv+n>df->cap){df->cap=df->cap?df->cap*2:4;while(df->cap<df->nv+n)df->cap*=2;df->vals=xrealloc(df->vals,df->cap*sizeof(DVal));}
    return df->vals+df->nv;
}

static DMsg*new_dmsg(SMsg*m){
    DMsg*d=xmalloc(sizeof(DMsg));
    d->schema=m;d->nf=m->nf;
    d->fields=xmalloc(m->nf*sizeof(DField));
    memset(d->fields,0,m->nf*sizeof(DField));
    for(int i=0;i<m->nf;i++)d->fields[i].sf=&m->fields[i];
    d->nof=m->nof;
    d->oneof_set=xmalloc((m->nof>0?m->nof:1)*sizeof(int));
    for(int i=0;i<m->nof;i++)d->oneof_set[i]=-1;
    return d;
}

static SField*find_field(SMsg*m,int num){
    for(int i=0;i<m->nf;i++)if(m->fields[i].number==num)return &m->fields[i];
    return NULL;
}
static int field_idx(SMsg*m,int num){for(int i=0;i<m->nf;i++)if(m->fields[i].number==num)return i;return -1;}

/* ============ Binary Reader ============ */
static uint8_t *bindata;static size_t binlen,binpos;

static uint64_t rd_varint(void){
    uint64_t r=0;int sh=0;
    for(int i=0;i<10;i++){
        if(binpos>=binlen)return 0;
        uint8_t b=bindata[binpos++];
        r|=(uint64_t)(b&0x7F)<<sh;
        if(!(b&0x80))break;
        sh+=7;
    }
    return r;
}
static uint64_t rd_varint_at(uint8_t*d,size_t*p,size_t l){
    uint64_t r=0;int sh=0;
    for(int i=0;i<10;i++){
        if(*p>=l)return 0;
        uint8_t b=d[(*p)++];
        r|=(uint64_t)(b&0x7F)<<sh;
        if(!(b&0x80))break;
        sh+=7;
    }
    return r;
}

static void skip_unknown(uint8_t*d,size_t*p,size_t l,int wt,int fn){
    switch(wt){
        case 0:rd_varint_at(d,p,l);break;
        case 1:*p+=8;break;
        case 5:*p+=4;break;
        case 2:{uint64_t len=rd_varint_at(d,p,l);*p+=len;break;}
        case 3:{
            int depth=1;
            while(depth>0&&*p<l){
                uint64_t k=rd_varint_at(d,p,l);
                int w2=(int)(k&7),f2=(int)(k>>3);
                if(w2==3)depth++;
                else if(w2==4){if(f2==fn)depth--;}
                else skip_unknown(d,p,l,w2,f2);
            }
            break;
        }
        case 4:break;
        default:break;
    }
}

static uint64_t zigzag32(uint64_t n){return((uint32_t)n>>1)^-(uint32_t)(n&1);}
static uint64_t zigzag64(uint64_t n){return(n>>1)^-(n&1);}

static void decode_val(DVal*v,FType ft,const char*tn,uint8_t*d,size_t*p,size_t l,int wt){
    (void)wt;
    memset(v,0,sizeof(*v));
    v->type=ft;v->type_name=(char*)tn;
    switch(ft){
        case FT_INT32:case FT_UINT32:case FT_SINT32:case FT_BOOL:case FT_ENUM:
        case FT_INT64:case FT_UINT64:case FT_SINT64:
            v->u64=rd_varint_at(d,p,l);
            if(ft==FT_SINT32)v->u64=zigzag32(v->u64);
            if(ft==FT_SINT64)v->u64=zigzag64(v->u64);
            break;
        case FT_FIXED32:case FT_SFIXED32:{
            uint32_t x=0;if(*p+4<=l){x=(uint32_t)d[*p]|((uint32_t)d[*p+1]<<8)|((uint32_t)d[*p+2]<<16)|((uint32_t)d[*p+3]<<24);}*p+=4;v->u64=x;break;
        }
        case FT_FIXED64:case FT_SFIXED64:{
            uint64_t x=0;if(*p+8<=l)memcpy(&x,d+*p,8);*p+=8;v->u64=x;break;
        }
        case FT_STRING:case FT_BYTES:{
            uint64_t len=rd_varint_at(d,p,l);
            if(*p+len<=l){v->sdata=xmalloc(len+1);memcpy(v->sdata,d+*p,len);v->sdata[len]=0;v->slen=len;}
            else{v->sdata=xmalloc(1);v->sdata[0]=0;v->slen=0;}
            *p+=len;break;
        }
        case FT_MESSAGE:{
            uint64_t len=rd_varint_at(d,p,l);
            SMsg*sm=find_msg(tn);
            if(!sm){v->msg=new_dmsg(root_msg);*p+=len;break;}
            v->msg=new_dmsg(sm);
            size_t sub_start=*p;size_t sub_end=*p+len;
            if(sub_end>l)sub_end=l;
            decode_msg(d,sub_start,sub_end,v->msg,sm);
            *p=sub_end;break;
        }
        default:break;
    }
}

static void decode_msg(uint8_t*d,size_t start,size_t end,DMsg*msg,SMsg*schema){
    size_t p=start;
    while(p<end){
        uint64_t key=rd_varint_at(d,&p,end);
        int fn=(int)(key>>3),wt=(int)(key&7);
        SField*sf=find_field(schema,fn);
        if(!sf){skip_unknown(d,&p,end,wt,fn);continue;}
        int idx=field_idx(schema,fn);
        DField*df=&msg->fields[idx];
        if(sf->is_map){
            if(wt!=2){skip_unknown(d,&p,end,wt,fn);continue;}
            uint64_t elen=rd_varint_at(d,&p,end);
            size_t es=p,ee=p+elen;if(ee>end)ee=end;
            DVal kv,vv;memset(&kv,0,sizeof(kv));memset(&vv,0,sizeof(vv));
            kv.type=sf->map_key_type;
            vv.type=sf->map_val_type;vv.type_name=sf->map_val_type_name;
            size_t ep=es;
            while(ep<ee){
                uint64_t ek=rd_varint_at(d,&ep,ee);
                int efn=(int)(ek>>3),ewt=(int)(ek&7);
                if(efn==1){
                    if(sf->map_key_type==FT_STRING){
                        uint64_t kl=rd_varint_at(d,&ep,ee);
                        if(ep+kl<=ee){kv.sdata=xmalloc(kl+1);memcpy(kv.sdata,d+ep,kl);kv.sdata[kl]=0;kv.slen=kl;}
                        else{kv.sdata=xmalloc(1);kv.sdata[0]=0;kv.slen=0;}
                        ep+=kl;
                    }else{kv.u64=rd_varint_at(d,&ep,ee);}
                }else if(efn==2){
                    decode_val(&vv,sf->map_val_type,sf->map_val_type_name,d,&ep,ee,ewt);
                }else{
                    skip_unknown(d,&ep,ee,ewt,efn);
                }
            }
            if(!kv.sdata&&sf->map_key_type==FT_STRING){kv.sdata=xmalloc(1);kv.sdata[0]=0;kv.slen=0;}
            /* find existing entry or add new */
            bool found=false;
            int ne=df->nv/2;
            for(int i=0;i<ne;i++){
                bool eq=false;
                if(sf->map_key_type==FT_STRING)eq=(df->vals[2*i].slen==kv.slen&&(!kv.slen||!memcmp(df->vals[2*i].sdata,kv.sdata,kv.slen)));
                else eq=(df->vals[2*i].u64==kv.u64);
                if(eq){df->vals[2*i+1]=vv;found=true;break;}
            }
            if(!found){
                DVal*slot=ensure_vals(df,2);
                slot[0]=kv;slot[1]=vv;df->nv+=2;
            }
            df->is_set=true;
            p=ee;
            continue;
        }
        if(sf->label==LBL_REP){
            bool packable=(sf->type==FT_INT32||sf->type==FT_INT64||sf->type==FT_UINT32||sf->type==FT_UINT64||
                          sf->type==FT_SINT32||sf->type==FT_SINT64||sf->type==FT_BOOL||sf->type==FT_ENUM||
                          sf->type==FT_FIXED32||sf->type==FT_FIXED64||sf->type==FT_SFIXED32||sf->type==FT_SFIXED64);
            if(packable&&wt==2){
                uint64_t plen=rd_varint_at(d,&p,end);
                size_t ps=p,pe=p+plen;if(pe>end)pe=end;
                while(ps<pe){
                    DVal*v=ensure_vals(df,1);
                    decode_val(v,sf->type,sf->type_name,d,&ps,pe,0);
                    df->nv++;
                }
                p=pe;
            }else{
                DVal*v=ensure_vals(df,1);
                decode_val(v,sf->type,sf->type_name,d,&p,end,wt);
                df->nv++;
            }
            df->is_set=true;
        }else if(sf->type==FT_MESSAGE){
            if(wt!=2){skip_unknown(d,&p,end,wt,fn);continue;}
            uint64_t mlen=rd_varint_at(d,&p,end);
            size_t ms=p,me=p+mlen;if(me>end)me=end;
            SMsg*sm=find_msg(sf->type_name);
            if(!sm){p=me;continue;}
            if(!df->is_set){
                df->is_set=true;df->nv=1;df->cap=1;
                df->vals=xmalloc(sizeof(DVal));
                memset(&df->vals[0],0,sizeof(DVal));
                df->vals[0].type=FT_MESSAGE;df->vals[0].type_name=sf->type_name;
                df->vals[0].msg=new_dmsg(sm);
                decode_msg(d,ms,me,df->vals[0].msg,sm);
            }else{
                DMsg*nm=new_dmsg(sm);
                decode_msg(d,ms,me,nm,sm);
                merge_msg(df->vals[0].msg,nm);
            }
            p=me;
            if(sf->oneof_idx>=0){
                int oi=sf->oneof_idx;
                int cur=msg->oneof_set[oi];
                if(cur>=0&&cur!=idx){
                    msg->fields[cur].is_set=false;msg->fields[cur].nv=0;
                }
                msg->oneof_set[oi]=idx;
            }
        }else{
            DVal v;
            decode_val(&v,sf->type,sf->type_name,d,&p,end,wt);
            if(sf->oneof_idx>=0){
                int oi=sf->oneof_idx;
                int cur=msg->oneof_set[oi];
                if(cur>=0&&cur!=idx){
                    msg->fields[cur].is_set=false;msg->fields[cur].nv=0;
                }
                msg->oneof_set[oi]=idx;
            }
            if(!df->is_set){df->cap=1;df->vals=xmalloc(sizeof(DVal));df->nv=1;}
            else df->nv=1;
            df->vals[0]=v;df->is_set=true;
        }
    }
}

static void merge_msg(DMsg*dst,DMsg*src){
    for(int i=0;i<dst->nf;i++){
        DField*sf=&src->fields[i];
        if(!sf->is_set)continue;
        DField*df=&dst->fields[i];
        SField*sch=df->sf;
        if(sch->is_map){
            int sne=sf->nv/2;
            for(int j=0;j<sne;j++){
                bool found=false;
                int dne=df->nv/2;
                for(int k=0;k<dne;k++){
                    bool eq=false;
                    if(sch->map_key_type==FT_STRING)eq=(sf->vals[2*j].slen==df->vals[2*k].slen&&(!sf->vals[2*j].slen||!memcmp(sf->vals[2*j].sdata,df->vals[2*k].sdata,sf->vals[2*j].slen)));
                    else eq=(sf->vals[2*j].u64==df->vals[2*k].u64);
                    if(eq){df->vals[2*k+1]=sf->vals[2*j+1];found=true;break;}
                }
                if(!found){
                    DVal*slot=ensure_vals(df,2);
                    slot[0]=sf->vals[2*j];slot[1]=sf->vals[2*j+1];df->nv+=2;
                }
            }
            df->is_set=true;
        }else if(sch->label==LBL_REP){
            for(int j=0;j<sf->nv;j++){
                DVal*slot=ensure_vals(df,1);
                *slot=sf->vals[j];df->nv++;
            }
            df->is_set=true;
        }else if(sch->type==FT_MESSAGE){
            if(!df->is_set){
                df->is_set=true;df->nv=1;df->cap=1;
                df->vals=xmalloc(sizeof(DVal));
                df->vals[0]=sf->vals[0];
            }else{
                merge_msg(df->vals[0].msg,sf->vals[0].msg);
            }
            if(sch->oneof_idx>=0){
                int oi=sch->oneof_idx;
                int cur=dst->oneof_set[oi];
                if(cur>=0&&cur!=i){dst->fields[cur].is_set=false;dst->fields[cur].nv=0;}
                dst->oneof_set[oi]=i;
            }
        }else{
            if(sch->oneof_idx>=0){
                int oi=sch->oneof_idx;
                int cur=dst->oneof_set[oi];
                if(cur>=0&&cur!=i){dst->fields[cur].is_set=false;dst->fields[cur].nv=0;}
                dst->oneof_set[oi]=i;
            }
            if(!df->is_set){df->cap=1;df->vals=xmalloc(sizeof(DVal));df->nv=1;}
            else df->nv=1;
            df->vals[0]=sf->vals[0];df->is_set=true;
        }
    }
}

/* ============ JSON Output ============ */
static void emit_str(const char*s,size_t len){
    putchar('"');
    for(size_t i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"')printf("\\\"");
        else if(c=='\\')printf("\\\\");
        else if(c==0x08)printf("\\b");
        else if(c==0x09)printf("\\t");
        else if(c==0x0A)printf("\\n");
        else if(c==0x0C)printf("\\f");
        else if(c==0x0D)printf("\\r");
        else if(c<0x20)printf("\\u00%02x",c);
        else putchar(c);
    }
    putchar('"');
}

static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void emit_b64(const char*data,size_t len){
    putchar('"');
    for(size_t i=0;i<len;i+=3){
        size_t rem=len-i;
        uint32_t v=(uint32_t)(unsigned char)data[i]<<16;
        if(rem>1)v|=(uint32_t)(unsigned char)data[i+1]<<8;
        if(rem>2)v|=(uint32_t)(unsigned char)data[i+2];
        putchar(b64[(v>>18)&63]);
        putchar(b64[(v>>12)&63]);
        putchar(rem>1?b64[(v>>6)&63]:'=');
        putchar(rem>2?b64[v&63]:'=');
    }
    putchar('"');
}

static void camel_name(const char*name){
    char buf[4096];int j=0;
    for(int i=0;name[i];i++){
        if(name[i]=='_'){
            i++;
            if(name[i]&&name[i]>='a'&&name[i]<='z')buf[j++]=name[i]-'a'+'A';
            else if(name[i])buf[j++]=name[i];
        }else buf[j++]=name[i];
    }
    buf[j]=0;
    emit_str(buf,j);
}

static bool is_default(DVal*v){
    switch(v->type){
        case FT_INT32:case FT_INT64:case FT_SINT32:case FT_SINT64:
        case FT_UINT32:case FT_UINT64:case FT_FIXED32:case FT_FIXED64:
        case FT_SFIXED32:case FT_SFIXED64:case FT_BOOL:case FT_ENUM:
            return v->u64==0;
        case FT_STRING:case FT_BYTES:
            return v->slen==0;
        default:return true;
    }
}

static void emit_val(DVal*v){
    switch(v->type){
        case FT_INT32:case FT_SINT32:case FT_SFIXED32:
            printf("%"PRId32,(int32_t)(uint32_t)v->u64);break;
        case FT_UINT32:case FT_FIXED32:
            printf("%"PRIu32,(uint32_t)v->u64);break;
        case FT_INT64:case FT_SINT64:case FT_SFIXED64:
            printf("\"%"PRId64"\"",(int64_t)v->u64);break;
        case FT_UINT64:case FT_FIXED64:
            printf("\"%"PRIu64"\"",v->u64);break;
        case FT_BOOL:
            printf(v->u64?"true":"false");break;
        case FT_STRING:
            emit_str(v->sdata,v->slen);break;
        case FT_BYTES:
            emit_b64(v->sdata,v->slen);break;
        case FT_ENUM:{
            SEnum*e=find_enum(v->type_name);
            int32_t val=(int32_t)(uint32_t)v->u64;
            if(e){
                for(int i=0;i<e->nv;i++){
                    if(e->vv[i]==val){printf("\"%s\"",e->vn[i]);return;}
                }
            }
            printf("%"PRId32,val);break;
        }
        case FT_MESSAGE:
            emit_msg(v->msg);break;
        default:break;
    }
}

static int cmp_str_key(const void*a,const void*b){
    const DVal*va=(const DVal*)a;const DVal*vb=(const DVal*)b;
    size_t ml=va->slen<vb->slen?va->slen:vb->slen;
    int r=memcmp(va->sdata,vb->sdata,ml);
    if(r)return r;
    return (int)va->slen-(int)vb->slen;
}
static int cmp_int_key(const void*a,const void*b){
    const DVal*va=(const DVal*)a;const DVal*vb=(const DVal*)b;
    int32_t ka=(int32_t)(uint32_t)va->u64,kb=(int32_t)(uint32_t)vb->u64;
    return (ka<kb)?-1:(ka>kb)?1:0;
}

static void emit_msg(DMsg*m){
    putchar('{');
    bool first=true;
    int *order=xmalloc(m->nf*sizeof(int));
    for(int i=0;i<m->nf;i++)order[i]=i;
    /* insertion sort by field number */
    for(int i=1;i<m->nf;i++){
        int tmp=order[i];int j=i-1;
        while(j>=0&&m->fields[order[j]].sf->number>m->fields[tmp].sf->number){order[j+1]=order[j];j--;}
        order[j+1]=tmp;
    }
    for(int oi=0;oi<m->nf;oi++){
        int i=order[oi];
        DField*df=&m->fields[i];
        SField*sf=df->sf;
        if(!df->is_set)continue;
        if(sf->is_map){
            if(df->nv==0)continue;
        }else if(sf->label==LBL_REP){
            if(df->nv==0)continue;
        }else if(sf->type==FT_MESSAGE){
            /* always print if set */
        }else{
            bool in_oneof=sf->oneof_idx>=0;
            bool is_opt=(sf->label==LBL_OPT);
            if(in_oneof){
                if(m->oneof_set[sf->oneof_idx]!=i)continue;
            }else if(!is_opt){
                if(is_default(&df->vals[0]))continue;
            }
        }
        if(!first)putchar(',');
        first=false;
        camel_name(sf->name);
        putchar(':');
        if(sf->is_map){
            int ne=df->nv/2;
            int *eo=xmalloc(ne*sizeof(int));
            for(int i=0;i<ne;i++)eo[i]=i;
            /* insertion sort */
            for(int i=1;i<ne;i++){
                int tmp=eo[i];int j=i-1;
                int cmp;
                while(j>=0){
                    if(sf->map_key_type==FT_STRING)cmp=cmp_str_key(&df->vals[2*eo[j]],&df->vals[2*tmp]);
                    else cmp=cmp_int_key(&df->vals[2*eo[j]],&df->vals[2*tmp]);
                    if(cmp>0){eo[j+1]=eo[j];j--;}
                    else break;
                }
                eo[j+1]=tmp;
            }
            putchar('{');
            for(int ei=0;ei<ne;ei++){
                if(ei)putchar(',');
                int idx2=2*eo[ei];
                if(sf->map_key_type==FT_STRING)emit_str(df->vals[idx2].sdata,df->vals[idx2].slen);
                else printf("\"%"PRId32"\"",(int32_t)(uint32_t)df->vals[idx2].u64);
                putchar(':');
                emit_val(&df->vals[idx2+1]);
            }
            putchar('}');
        }else if(sf->label==LBL_REP){
            putchar('[');
            for(int j=0;j<df->nv;j++){
                if(j)putchar(',');
                emit_val(&df->vals[j]);
            }
            putchar(']');
        }else{
            emit_val(&df->vals[0]);
        }
    }
    putchar('}');
}

/* ============ Main ============ */
int main(int argc,char*argv[]){
    (void)argc;(void)argv;
    FILE*f=fopen("schema.proto","rb");
    if(!f){perror("schema.proto");return 1;}
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    src=xmalloc(sz+1);fread(src,1,sz,f);src[sz]=0;fclose(f);
    src_len=sz;
    tokenize();
    parse_schema();

    f=fopen("messages.bin","rb");
    if(!f){perror("messages.bin");return 1;}
    fseek(f,0,SEEK_END);long bsz=ftell(f);fseek(f,0,SEEK_SET);
    bindata=xmalloc(bsz?bsz:1);fread(bindata,1,bsz,f);fclose(f);
    binlen=bsz;binpos=0;

    while(binpos<binlen){
        uint64_t rlen=rd_varint();
        if(rlen==0&&binpos>=binlen)break;
        if(binpos+rlen>binlen)rlen=binlen-binpos;
        DMsg*dm=new_dmsg(root_msg);
        decode_msg(bindata,binpos,binpos+rlen,dm,root_msg);
        emit_msg(dm);
        putchar('\n');
        binpos+=rlen;
    }
    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    static PrintStream out;
    static String json;
    static int pos;

    public static void main(String[] args) throws Exception {
        out = new PrintStream(new FileOutputStream(FileDescriptor.out), true, "UTF-8");
        String dataDir = args[0];
        String baseUrl = args[1];

        byte[] clientBytes = Files.readAllBytes(Paths.get(dataDir, "client.json"));
        String clientJson = new String(clientBytes, StandardCharsets.UTF_8);
        @SuppressWarnings("unchecked")
        Map<String, Object> client = (Map<String, Object>) parseJson(clientJson);
        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = ((Number) client.get("page_size")).intValue();

        URI uri = new URI(baseUrl);
        String host = uri.getHost();
        int port = uri.getPort();
        if (port == -1) port = 80;
        String basePath = uri.getPath();

        String token = getToken(host, port, basePath, clientId, clientSecret, scope);
        int reauthCount = 0;
        int pageCount = 0;
        int retryCount = 0;
        int totalOrders = 0;

        Map<String, Map<String, Long>> totals = new HashMap<>();
        Map<String, Integer> statusCounts = new TreeMap<>();

        String cursor = null;
        boolean hasCursor = false;
        boolean freshToken = true;

        while (true) {
            String reqPath;
            if (!hasCursor) {
                reqPath = basePath + "/orders?limit=" + pageSize;
            } else {
                reqPath = basePath + "/orders?limit=" + pageSize + "&cursor=" + percentEncode(cursor);
            }

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);

            HttpResponse resp = sendRequest(host, port, "GET", reqPath, headers, null);

            if (resp.status == 429) {
                retryCount++;
                String ra = resp.headers.get("retry-after");
                int wait = (ra != null) ? Integer.parseInt(ra.trim()) : 1;
                Thread.sleep(wait * 1000L);
                continue;
            }
            if (resp.status == 503) {
                retryCount++;
                Thread.sleep(500);
                continue;
            }
            if (resp.status == 401) {
                if (freshToken) {
                    out.println("ERROR " + resp.status + " " + resp.body);
                    out.flush();
                    System.exit(0);
                }
                token = getToken(host, port, basePath, clientId, clientSecret, scope);
                reauthCount++;
                freshToken = true;
                continue;
            }
            if (resp.status != 200) {
                out.println("ERROR " + resp.status + " " + resp.body);
                out.flush();
                System.exit(0);
            }

            pageCount++;
            freshToken = false;

            @SuppressWarnings("unchecked")
            Map<String, Object> page = (Map<String, Object>) parseJson(resp.body);
            @SuppressWarnings("unchecked")
            List<Object> data = (List<Object>) page.get("data");
            if (data != null) {
                for (Object obj : data) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> order = (Map<String, Object>) obj;
                    totalOrders++;
                    String status = (String) order.get("status");
                    statusCounts.merge(status, 1, Integer::sum);
                    if (!"cancelled".equals(status)) {
                        @SuppressWarnings("unchecked")
                        Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                        String name = (String) customer.get("name");
                        String currency = (String) order.get("currency");
                        String amountStr = (String) order.get("amount");
                        long cents = parseAmount(amountStr);
                        totals.computeIfAbsent(name, k -> new HashMap<>()).merge(currency, cents, Long::sum);
                    }
                }
            }
            Object nextCursor = page.get("next_cursor");
            if (nextCursor == null) break;
            cursor = (String) nextCursor;
            hasCursor = true;
        }

        List<String[]> totalLines = new ArrayList<>();
        for (Map.Entry<String, Map<String, Long>> e : totals.entrySet()) {
            String name = e.getKey();
            for (Map.Entry<String, Long> ce : e.getValue().entrySet()) {
                totalLines.add(new String[]{name, ce.getKey(), formatAmount(ce.getValue())});
            }
        }
        totalLines.sort((a, b) -> {
            int c = compareCodePoints(a[0], b[0]);
            if (c != 0) return c;
            return a[1].compareTo(b[1]);
        });
        for (String[] line : totalLines) {
            out.println("total " + line[1] + " " + line[2] + " " + line[0]);
        }
        for (Map.Entry<String, Integer> e : statusCounts.entrySet()) {
            out.println("status " + e.getKey() + " " + e.getValue());
        }
        out.println("orders " + totalOrders + " pages " + pageCount + " retries " + retryCount + " reauth " + reauthCount);
        out.flush();
    }

    static String getToken(String host, int port, String basePath, String clientId, String clientSecret, String scope) throws Exception {
        String tokenPath = basePath + "/oauth/token";
        String credentials = formEncode(clientId) + ":" + formEncode(clientSecret);
        String b64 = Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));
        String body = "grant_type=client_credentials&scope=" + formEncode(scope);
        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);

        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("Content-Type", "application/x-www-form-urlencoded");
        headers.put("Authorization", "Basic " + b64);
        headers.put("Content-Length", String.valueOf(bodyBytes.length));

        HttpResponse resp = sendRequest(host, port, "POST", tokenPath, headers, body);
        if (resp.status != 200) {
            out.println("ERROR " + resp.status + " " + resp.body);
            out.flush();
            System.exit(0);
        }
        @SuppressWarnings("unchecked")
        Map<String, Object> tokenResp = (Map<String, Object>) parseJson(resp.body);
        return (String) tokenResp.get("access_token");
    }

    static HttpResponse sendRequest(String host, int port, String method, String path,
                                    Map<String, String> headers, String body) throws Exception {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 30000);
        socket.setSoTimeout(30000);
        try {
            OutputStream os = socket.getOutputStream();
            StringBuilder req = new StringBuilder();
            req.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
            req.append("Host: ").append(host);
            if (port != 80) req.append(":").append(port);
            req.append("\r\n");
            for (Map.Entry<String, String> h : headers.entrySet()) {
                req.append(h.getKey()).append(": ").append(h.getValue()).append("\r\n");
            }
            req.append("\r\n");
            os.write(req.toString().getBytes(StandardCharsets.UTF_8));
            if (body != null) {
                os.write(body.getBytes(StandardCharsets.UTF_8));
            }
            os.flush();

            InputStream is = new BufferedInputStream(socket.getInputStream());
            String statusLine = readLine(is);
            String[] parts = statusLine.split(" ", 3);
            int status = Integer.parseInt(parts[1]);

            Map<String, String> respHeaders = new HashMap<>();
            String line;
            while ((line = readLine(is)) != null && !line.isEmpty()) {
                int idx = line.indexOf(':');
                if (idx >= 0) {
                    respHeaders.put(line.substring(0, idx).trim().toLowerCase(), line.substring(idx + 1).trim());
                }
            }

            byte[] bodyBytes;
            String te = respHeaders.get("transfer-encoding");
            String cl = respHeaders.get("content-length");
            if (te != null && te.toLowerCase().contains("chunked")) {
                bodyBytes = readChunked(is);
            } else if (cl != null) {
                int len = Integer.parseInt(cl.trim());
                bodyBytes = readBytes(is, len);
            } else {
                bodyBytes = readAllBytes(is);
            }
            String respBody = new String(bodyBytes, StandardCharsets.UTF_8);
            return new HttpResponse(status, respHeaders, respBody);
        } finally {
            socket.close();
        }
    }

    static String readLine(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        int b;
        while ((b = is.read()) != -1) {
            if (b == '\r') {
                int next = is.read();
                if (next == '\n') break;
                buf.write('\r');
                if (next != -1) buf.write(next);
            } else if (b == '\n') {
                break;
            } else {
                buf.write(b);
            }
        }
        if (buf.size() == 0 && b == -1) return null;
        return buf.toString("ISO-8859-1");
    }

    static byte[] readBytes(InputStream is, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = is.read(buf, off, n - off);
            if (r == -1) break;
            off += r;
        }
        return Arrays.copyOf(buf, off);
    }

    static byte[] readAllBytes(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] tmp = new byte[4096];
        int r;
        while ((r = is.read(tmp)) != -1) {
            buf.write(tmp, 0, r);
        }
        return buf.toByteArray();
    }

    static byte[] readChunked(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        while (true) {
            String sizeLine = readLine(is);
            if (sizeLine == null) break;
            int semi = sizeLine.indexOf(';');
            if (semi >= 0) sizeLine = sizeLine.substring(0, semi);
            int chunkSize = Integer.parseInt(sizeLine.trim(), 16);
            if (chunkSize == 0) {
                readLine(is);
                break;
            }
            byte[] chunk = readBytes(is, chunkSize);
            buf.write(chunk);
            readLine(is);
        }
        return buf.toByteArray();
    }

    static Object parseJson(String s) {
        json = s;
        pos = 0;
        return parseValue();
    }

    static Object parseValue() {
        skipWs();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBool();
        if (c == 'n') return parseNull();
        return parseNumber();
    }

    static void skipWs() {
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') pos++;
            else break;
        }
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            pos++; // ':'
            skipWs();
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            char c = json.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == '}') { pos++; break; }
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            skipWs();
            list.add(parseValue());
            skipWs();
            char c = json.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == ']') { pos++; break; }
        }
        return list;
    }

    static String parseString() {
        pos++; // skip "
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = json.charAt(pos);
            if (c == '"') { pos++; break; }
            if (c == '\\') {
                pos++;
                char esc = json.charAt(pos);
                pos++;
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        int cp = parseHex4();
                        if (Character.isHighSurrogate((char) cp)) {
                            if (pos + 1 < json.length() && json.charAt(pos) == '\\' && json.charAt(pos + 1) == 'u') {
                                pos += 2;
                                int cp2 = parseHex4();
                                if (Character.isLowSurrogate((char) cp2)) {
                                    sb.appendCodePoint(Character.toCodePoint((char) cp, (char) cp2));
                                } else {
                                    sb.append((char) cp);
                                    sb.append((char) cp2);
                                }
                            } else {
                                sb.append((char) cp);
                            }
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    default: sb.append(esc);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }

    static int parseHex4() {
        int val = 0;
        for (int i = 0; i < 4; i++) {
            char c = json.charAt(pos++);
            if (c >= '0' && c <= '9') val = val * 16 + (c - '0');
            else if (c >= 'a' && c <= 'f') val = val * 16 + (c - 'a' + 10);
            else if (c >= 'A' && c <= 'F') val = val * 16 + (c - 'A' + 10);
        }
        return val;
    }

    static Object parseBool() {
        if (json.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
        pos += 5; return Boolean.FALSE;
    }

    static Object parseNull() {
        pos += 4;
        return null;
    }

    static Object parseNumber() {
        int start = pos;
        if (json.charAt(pos) == '-') pos++;
        while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        boolean isFloat = false;
        if (pos < json.length() && json.charAt(pos) == '.') {
            isFloat = true; pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
            isFloat = true; pos++;
            if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        String numStr = json.substring(start, pos);
        if (isFloat) return Double.parseDouble(numStr);
        return Long.parseLong(numStr);
    }

    static String formEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static String percentEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static long parseAmount(String s) {
        int i = 0;
        boolean neg = false;
        if (s.charAt(i) == '-') { neg = true; i++; }
        long intPart = 0;
        while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
            intPart = intPart * 10 + (s.charAt(i) - '0');
            i++;
        }
        long fracPart = 0;
        int fracDigits = 0;
        if (i < s.length() && s.charAt(i) == '.') {
            i++;
            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                fracPart = fracPart * 10 + (s.charAt(i) - '0');
                fracDigits++;
                i++;
            }
        }
        if (fracDigits == 1) fracPart *= 10;
        long cents = intPart * 100 + fracPart;
        return neg ? -cents : cents;
    }

    static String formatAmount(long cents) {
        if (cents == 0) return "0.00";
        String sign = "";
        long abs = cents;
        if (cents < 0) { sign = "-"; abs = -cents; }
        long intPart = abs / 100;
        long fracPart = abs % 100;
        return sign + intPart + "." + (fracPart < 10 ? "0" : "") + fracPart;
    }

    static int compareCodePoints(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }

    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
        HttpResponse(int status, Map<String, String> headers, String body) {
            this.status = status;
            this.headers = headers;
            this.body = body;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // AST nodes
    static abstract class Node {}
    static class Alt extends Node { List<Node> branches; Alt(List<Node> b){branches=b;} }
    static class Seq extends Node { List<Node> pieces; Seq(List<Node> p){pieces=p;} }
    static class Lit extends Node { char ch; Lit(char c){ch=c;} }
    static class Any extends Node {}
    static class Begin extends Node {}
    static class End extends Node {}
    static class ClassNode extends Node { List<int[]> ranges; boolean negated; }
    static class Group extends Node { int num; Node inner; }
    static class Quant extends Node { Node atom; int min, max; boolean lazy; }

    // NFA state types
    static final int CHAR=0, CLASS=1, ANY=2, SPLIT=3, JMP=4, SAVE=5, MATCH=6,
                     BEGIN=7, END=8, SAVE_ITER=9, CHECK_ITER=10;

    static int[] sType, sNext, sNext2, sCh, sGrp, sSaveEnd, sIterId;
    static boolean[] sNegated;
    static int[][] sClass;
    static int numStates, numIters;
    static int numGroups;

    static String subject;
    static int subjLen;
    static boolean[][] memo;
    static int[] captures;
    static int[] iterPos;
    static int groupCounter;

    static int emit(int type) {
        if (numStates >= sType.length) grow();
        sType[numStates] = type;
        sNext[numStates] = -1;
        sNext2[numStates] = -1;
        sGrp[numStates] = 0;
        sSaveEnd[numStates] = 0;
        sIterId[numStates] = 0;
        sNegated[numStates] = false;
        sClass[numStates] = null;
        return numStates++;
    }

    static void grow() {
        int nc = sType.length * 2;
        sType = Arrays.copyOf(sType, nc);
        sNext = Arrays.copyOf(sNext, nc);
        sNext2 = Arrays.copyOf(sNext2, nc);
        sCh = Arrays.copyOf(sCh, nc);
        sGrp = Arrays.copyOf(sGrp, nc);
        sSaveEnd = Arrays.copyOf(sSaveEnd, nc);
        sIterId = Arrays.copyOf(sIterId, nc);
        sNegated = Arrays.copyOf(sNegated, nc);
        sClass = Arrays.copyOf(sClass, nc);
    }

    // Parsing
    static Node parseRegex(String pat, int[] pos) {
        List<Node> branches = new ArrayList<>();
        branches.add(parseBranch(pat, pos));
        while (pos[0] < pat.length() && pat.charAt(pos[0]) == '|') {
            pos[0]++;
            branches.add(parseBranch(pat, pos));
        }
        if (branches.size() == 1) return branches.get(0);
        return new Alt(branches);
    }

    static Node parseBranch(String pat, int[] pos) {
        List<Node> pieces = new ArrayList<>();
        while (pos[0] < pat.length() && pat.charAt(pos[0]) != '|' && pat.charAt(pos[0]) != ')') {
            pieces.add(parsePiece(pat, pos));
        }
        if (pieces.size() == 1) return pieces.get(0);
        return new Seq(pieces);
    }

    static Node parsePiece(String pat, int[] pos) {
        Node atom = parseAtom(pat, pos);
        if (pos[0] < pat.length()) {
            char c = pat.charAt(pos[0]);
            if (c == '*' || c == '+' || c == '?' || c == '{') {
                return parseQuant(pat, pos, atom);
            }
        }
        return atom;
    }

    static Node parseQuant(String pat, int[] pos, Node atom) {
        int min, max;
        char c = pat.charAt(pos[0]);
        if (c == '*') { pos[0]++; min = 0; max = -1; }
        else if (c == '+') { pos[0]++; min = 1; max = -1; }
        else if (c == '?') { pos[0]++; min = 0; max = 1; }
        else { // '{'
            pos[0]++; // skip '{'
            min = parseNum(pat, pos);
            if (pat.charAt(pos[0]) == '}') {
                pos[0]++;
                max = min;
            } else {
                pos[0]++; // skip ','
                if (pat.charAt(pos[0]) == '}') {
                    pos[0]++;
                    max = -1;
                } else {
                    max = parseNum(pat, pos);
                    pos[0]++; // skip '}'
                }
            }
        }
        boolean lazy = false;
        if (pos[0] < pat.length() && pat.charAt(pos[0]) == '?') {
            pos[0]++;
            lazy = true;
        }
        Quant q = new Quant();
        q.atom = atom; q.min = min; q.max = max; q.lazy = lazy;
        return q;
    }

    static int parseNum(String pat, int[] pos) {
        int val = 0;
        while (pos[0] < pat.length() && pat.charAt(pos[0]) >= '0' && pat.charAt(pos[0]) <= '9') {
            val = val * 10 + (pat.charAt(pos[0]) - '0');
            pos[0]++;
        }
        return val;
    }

    static Node parseAtom(String pat, int[] pos) {
        char c = pat.charAt(pos[0]);
        if (c == '(') {
            if (pos[0]+2 < pat.length() && pat.charAt(pos[0]+1) == '?' && pat.charAt(pos[0]+2) == ':') {
                pos[0] += 3;
                Node inner = parseRegex(pat, pos);
                pos[0]++; // skip ')'
                Group g = new Group(); g.num = -1; g.inner = inner; return g;
            } else {
                pos[0]++;
                groupCounter++;
                int num = groupCounter;
                Node inner = parseRegex(pat, pos);
                pos[0]++; // skip ')'
                Group g = new Group(); g.num = num; g.inner = inner; return g;
            }
        } else if (c == '.') { pos[0]++; return new Any(); }
        else if (c == '^') { pos[0]++; return new Begin(); }
        else if (c == '$') { pos[0]++; return new End(); }
        else if (c == '[') { return parseClass(pat, pos); }
        else if (c == '\\') { return parseEscape(pat, pos); }
        else { pos[0]++; return new Lit(c); }
    }

    static Node parseEscape(String pat, int[] pos) {
        pos[0]++; // skip '\'
        char c = pat.charAt(pos[0]); pos[0]++;
        if (c == 'd' || c == 'D' || c == 'w' || c == 'W' || c == 's' || c == 'S') {
            ClassNode cn = new ClassNode();
            cn.ranges = getClassRanges(c);
            cn.negated = (c == 'D' || c == 'W' || c == 'S');
            return cn;
        }
        return new Lit(c);
    }

    static List<int[]> getClassRanges(char type) {
        List<int[]> r = new ArrayList<>();
        if (type == 'd' || type == 'D') { r.add(new int[]{48,57}); }
        else if (type == 'w' || type == 'W') {
            r.add(new int[]{48,57}); r.add(new int[]{65,90});
            r.add(new int[]{95,95}); r.add(new int[]{97,122});
        }
        else if (type == 's' || type == 'S') {
            r.add(new int[]{9,13}); r.add(new int[]{32,32});
        }
        return r;
    }

    static Node parseClass(String pat, int[] pos) {
        pos[0]++; // skip '['
        boolean negated = false;
        if (pos[0] < pat.length() && pat.charAt(pos[0]) == '^') {
            negated = true; pos[0]++;
        }
        List<int[]> ranges = new ArrayList<>();
        while (pos[0] < pat.length() && pat.charAt(pos[0]) != ']') {
            char c1;
            if (pat.charAt(pos[0]) == '\\') {
                pos[0]++;
                char esc = pat.charAt(pos[0]);
                if (esc == 'd' || esc == 'D' || esc == 'w' || esc == 'W' || esc == 's' || esc == 'S') {
                    ranges.addAll(getClassRanges(esc));
                    pos[0]++;
                    continue;
                }
                c1 = esc; pos[0]++;
            } else {
                c1 = pat.charAt(pos[0]); pos[0]++;
            }
            // Check for range
            if (pos[0] + 1 < pat.length() && pat.charAt(pos[0]) == '-' && pat.charAt(pos[0]+1) != ']') {
                pos[0]++; // skip '-'
                char c2;
                if (pat.charAt(pos[0]) == '\\') {
                    pos[0]++;
                    c2 = pat.charAt(pos[0]); pos[0]++;
                } else {
                    c2 = pat.charAt(pos[0]); pos[0]++;
                }
                ranges.add(new int[]{c1, c2});
            } else {
                ranges.add(new int[]{c1, c1});
            }
        }
        pos[0]++; // skip ']'
        ClassNode cn = new ClassNode();
        cn.ranges = ranges; cn.negated = negated;
        return cn;
    }

    // NFA compilation
    static int compile(Node node, int next) {
        if (node instanceof Lit) {
            int s = emit(CHAR); sCh[s] = ((Lit)node).ch; sNext[s] = next; return s;
        }
        if (node instanceof Any) {
            int s = emit(ANY); sNext[s] = next; return s;
        }
        if (node instanceof Begin) {
            int s = emit(BEGIN); sNext[s] = next; return s;
        }
        if (node instanceof End) {
            int s = emit(END); sNext[s] = next; return s;
        }
        if (node instanceof ClassNode) {
            int s = emit(CLASS);
            sClass[s] = ((ClassNode)node).ranges.toArray(new int[0][]);
            sNegated[s] = ((ClassNode)node).negated;
            sNext[s] = next; return s;
        }
        if (node instanceof Alt) {
            Alt alt = (Alt)node;
            int result = next;
            for (int i = alt.branches.size()-1; i >= 0; i--) {
                int bStart = compile(alt.branches.get(i), next);
                int sp = emit(SPLIT);
                sNext[sp] = bStart;
                sNext2[sp] = result;
                result = sp;
            }
            return result;
        }
        if (node instanceof Seq) {
            Seq seq = (Seq)node;
            int curNext = next;
            for (int i = seq.pieces.size()-1; i >= 0; i--) {
                curNext = compile(seq.pieces.get(i), curNext);
            }
            return curNext;
        }
        if (node instanceof Group) {
            Group g = (Group)node;
            if (g.num >= 0) {
                int endS = emit(SAVE); sGrp[endS] = g.num; sSaveEnd[endS] = 1; sNext[endS] = next;
                int innerS = compile(g.inner, endS);
                int startS = emit(SAVE); sGrp[startS] = g.num; sSaveEnd[startS] = 0; sNext[startS] = innerS;
                return startS;
            } else {
                return compile(g.inner, next);
            }
        }
        if (node instanceof Quant) {
            return compileQuant((Quant)node, next);
        }
        return next;
    }

    static int compileQuant(Quant q, int next) {
        int curNext = next;
        if (q.max == -1) {
            // Unbounded optional: loop
            int saveIter = emit(SAVE_ITER);
            int checkIter = emit(CHECK_ITER);
            int splitState = emit(SPLIT);
            int jmpState = emit(JMP);
            int initSplit = emit(SPLIT);
            int qid = numIters++;
            sIterId[saveIter] = qid;
            sIterId[checkIter] = qid;
            int atomStart = compile(q.atom, checkIter);
            sNext[saveIter] = atomStart;
            sNext[checkIter] = splitState;
            sNext2[checkIter] = next;
            if (!q.lazy) {
                sNext[splitState] = jmpState;
                sNext2[splitState] = next;
                sNext[initSplit] = saveIter;
                sNext2[initSplit] = next;
            } else {
                sNext[splitState] = next;
                sNext2[splitState] = jmpState;
                sNext[initSplit] = next;
                sNext2[initSplit] = saveIter;
            }
            sNext[jmpState] = saveIter;
            curNext = initSplit;
        } else {
            int optCount = q.max - q.min;
            for (int i = optCount - 1; i >= 0; i--) {
                int saveIter = emit(SAVE_ITER);
                int checkIter = emit(CHECK_ITER);
                int qid = numIters++;
                sIterId[saveIter] = qid;
                sIterId[checkIter] = qid;
                int atomStart = compile(q.atom, checkIter);
                sNext[saveIter] = atomStart;
                if (i == optCount - 1) {
                    sNext[checkIter] = next;
                    sNext2[checkIter] = next;
                } else {
                    int splitState = emit(SPLIT);
                    sNext[checkIter] = splitState;
                    sNext2[checkIter] = next;
                    if (!q.lazy) {
                        sNext[splitState] = curNext;
                        sNext2[splitState] = next;
                    } else {
                        sNext[splitState] = next;
                        sNext2[splitState] = curNext;
                    }
                }
                curNext = saveIter;
            }
            // Add initial split for "skip all optional"
            if (optCount > 0) {
                int initSplit = emit(SPLIT);
                if (!q.lazy) {
                    sNext[initSplit] = curNext;
                    sNext2[initSplit] = next;
                } else {
                    sNext[initSplit] = next;
                    sNext2[initSplit] = curNext;
                }
                curNext = initSplit;
            }
        }
        // Mandatory part
        for (int i = 0; i < q.min; i++) {
            curNext = compile(q.atom, curNext);
        }
        return curNext;
    }

    // Matching
    static boolean match(int state, int pos) {
        if (memo[state][pos]) return false;
        int type = sType[state];
        switch (type) {
            case CHAR:
                if (pos < subjLen && subject.charAt(pos) == (char)sCh[state]) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case CLASS:
                if (pos < subjLen && matchesClass(subject.charAt(pos), state)) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case ANY:
                if (pos < subjLen) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case SPLIT:
                if (match(sNext[state], pos)) return true;
                if (match(sNext2[state], pos)) return true;
                memo[state][pos] = true; return false;
            case JMP:
                return match(sNext[state], pos);
            case SAVE: {
                int g = sGrp[state], se = sSaveEnd[state];
                int old = captures[2*g+se];
                captures[2*g+se] = pos;
                if (match(sNext[state], pos)) return true;
                captures[2*g+se] = old;
                memo[state][pos] = true; return false;
            }
            case SAVE_ITER: {
                int q = sIterId[state];
                int oldp = iterPos[q];
                iterPos[q] = pos;
                if (match(sNext[state], pos)) return true;
                iterPos[q] = oldp;
                memo[state][pos] = true; return false;
            }
            case CHECK_ITER: {
                int q = sIterId[state];
                if (pos > iterPos[q]) {
                    if (match(sNext[state], pos)) return true;
                } else {
                    if (match(sNext2[state], pos)) return true;
                }
                // Don't memoize CHECK_ITER (iterPos may differ)
                return false;
            }
            case BEGIN:
                if (pos == 0) {
                    if (match(sNext[state], pos)) return true;
                }
                memo[state][pos] = true; return false;
            case END:
                if (pos == subjLen) {
                    if (match(sNext[state], pos)) return true;
                }
                memo[state][pos] = true; return false;
            case MATCH:
                return true;
        }
        return false;
    }

    static boolean matchesClass(char c, int state) {
        int[][] ranges = sClass[state];
        boolean in = false;
        for (int[] r : ranges) {
            if (c >= r[0] && c <= r[1]) { in = true; break; }
        }
        return sNegated[state] ? !in : in;
    }

    static String solve(String pattern, String subj) {
        subject = subj;
        subjLen = subj.length();
        groupCounter = 0;
        numIters = 0;
        numStates = 0;

        int[] pos = {0};
        Node ast = parseRegex(pattern, pos);
        numGroups = groupCounter;

        // Initialize NFA arrays
        sType = new int[4096]; sNext = new int[4096]; sNext2 = new int[4096];
        sCh = new int[4096]; sGrp = new int[4096]; sSaveEnd = new int[4096];
        sIterId = new int[4096]; sNegated = new boolean[4096]; sClass = new int[4096][];
        numStates = 0;

        int matchState = emit(MATCH);
        int startState = compile(ast, matchState);

        captures = new int[2 * (numGroups + 1)];
        iterPos = new int[numIters + 1];
        memo = new boolean[numStates][subjLen + 1];

        for (int sp = 0; sp <= subjLen; sp++) {
            Arrays.fill(captures, -1);
            Arrays.fill(iterPos, -1);
            for (int i = 0; i < numStates; i++) Arrays.fill(memo[i], false);
            if (match(startState, sp)) {
                StringBuilder sb = new StringBuilder();
                sb.append(sp).append("-").append(getMatchEnd());
                for (int g = 1; g <= numGroups; g++) {
                    sb.append(" ");
                    if (captures[2*g] == -1) {
                        sb.append("-");
                    } else {
                        sb.append(captures[2*g]).append("-").append(captures[2*g+1]);
                    }
                }
                return sb.toString();
            }
        }
        return "no match";
    }

    static int getMatchEnd() {
        // The match end is the position when MATCH was reached
        // We need to track this. Let's use a global.
        return lastMatchEnd;
    }

    static int lastMatchEnd;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        BufferedReader br = new BufferedReader(new FileReader(dir + "/cases.txt"));
        String line;
        int lineNum = 0;
        while ((line = br.readLine()) != null) {
            lineNum++;
            int tab = line.indexOf('\t');
            String pattern = line.substring(0, tab);
            String subj = line.substring(tab + 1);
            String result = solve(pattern, subj);
            System.out.println(lineNum + ": " + result);
        }
        br.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // AST nodes
    static abstract class Node {}
    static class Alt extends Node { List<Node> branches; Alt(List<Node> b){branches=b;} }
    static class Seq extends Node { List<Node> pieces; Seq(List<Node> p){pieces=p;} }
    static class Lit extends Node { char ch; Lit(char c){ch=c;} }
    static class Any extends Node {}
    static class Begin extends Node {}
    static class End extends Node {}
    static class ClassNode extends Node { List<int[]> ranges; boolean negated; }
    static class Group extends Node { int num; Node inner; }
    static class Quant extends Node { Node atom; int min, max; boolean lazy; }

    // NFA state types
    static final int CHAR=0, CLASS=1, ANY=2, SPLIT=3, JMP=4, SAVE=5, MATCH=6,
                     BEGIN=7, END=8, SAVE_ITER=9, CHECK_ITER=10;

    static int[] sType, sNext, sNext2, sCh, sGrp, sSaveEnd, sIterId;
    static boolean[] sNegated;
    static int[][][] sClass;
    static int numStates, numIters;
    static int numGroups;

    static String subject;
    static int subjLen;
    static boolean[][] memo;
    static int[] captures;
    static int[] iterPos;
    static int groupCounter;
    static int lastMatchEnd;

    static int emit(int type) {
        if (numStates >= sType.length) grow();
        sType[numStates] = type;
        sNext[numStates] = -1;
        sNext2[numStates] = -1;
        sGrp[numStates] = 0;
        sSaveEnd[numStates] = 0;
        sIterId[numStates] = 0;
        sNegated[numStates] = false;
        sClass[numStates] = null;
        return numStates++;
    }

    static void grow() {
        int nc = sType.length * 2;
        sType = Arrays.copyOf(sType, nc);
        sNext = Arrays.copyOf(sNext, nc);
        sNext2 = Arrays.copyOf(sNext2, nc);
        sCh = Arrays.copyOf(sCh, nc);
        sGrp = Arrays.copyOf(sGrp, nc);
        sSaveEnd = Arrays.copyOf(sSaveEnd, nc);
        sIterId = Arrays.copyOf(sIterId, nc);
        sNegated = Arrays.copyOf(sNegated, nc);
        sClass = Arrays.copyOf(sClass, nc);
    }

    // Parsing
    static Node parseRegex(String pat, int[] pos) {
        List<Node> branches = new ArrayList<>();
        branches.add(parseBranch(pat, pos));
        while (pos[0] < pat.length() && pat.charAt(pos[0]) == '|') {
            pos[0]++;
            branches.add(parseBranch(pat, pos));
        }
        if (branches.size() == 1) return branches.get(0);
        return new Alt(branches);
    }

    static Node parseBranch(String pat, int[] pos) {
        List<Node> pieces = new ArrayList<>();
        while (pos[0] < pat.length() && pat.charAt(pos[0]) != '|' && pat.charAt(pos[0]) != ')') {
            pieces.add(parsePiece(pat, pos));
        }
        if (pieces.size() == 1) return pieces.get(0);
        return new Seq(pieces);
    }

    static Node parsePiece(String pat, int[] pos) {
        Node atom = parseAtom(pat, pos);
        if (pos[0] < pat.length()) {
            char c = pat.charAt(pos[0]);
            if (c == '*' || c == '+' || c == '?' || c == '{') {
                return parseQuant(pat, pos, atom);
            }
        }
        return atom;
    }

    static Node parseQuant(String pat, int[] pos, Node atom) {
        int min, max;
        char c = pat.charAt(pos[0]);
        if (c == '*') { pos[0]++; min = 0; max = -1; }
        else if (c == '+') { pos[0]++; min = 1; max = -1; }
        else if (c == '?') { pos[0]++; min = 0; max = 1; }
        else { // '{'
            pos[0]++; // skip '{'
            min = parseNum(pat, pos);
            if (pat.charAt(pos[0]) == '}') {
                pos[0]++;
                max = min;
            } else {
                pos[0]++; // skip ','
                if (pat.charAt(pos[0]) == '}') {
                    pos[0]++;
                    max = -1;
                } else {
                    max = parseNum(pat, pos);
                    pos[0]++; // skip '}'
                }
            }
        }
        boolean lazy = false;
        if (pos[0] < pat.length() && pat.charAt(pos[0]) == '?') {
            pos[0]++;
            lazy = true;
        }
        Quant q = new Quant();
        q.atom = atom; q.min = min; q.max = max; q.lazy = lazy;
        return q;
    }

    static int parseNum(String pat, int[] pos) {
        int val = 0;
        while (pos[0] < pat.length() && pat.charAt(pos[0]) >= '0' && pat.charAt(pos[0]) <= '9') {
            val = val * 10 + (pat.charAt(pos[0]) - '0');
            pos[0]++;
        }
        return val;
    }

    static Node parseAtom(String pat, int[] pos) {
        char c = pat.charAt(pos[0]);
        if (c == '(') {
            if (pos[0]+2 < pat.length() && pat.charAt(pos[0]+1) == '?' && pat.charAt(pos[0]+2) == ':') {
                pos[0] += 3;
                Node inner = parseRegex(pat, pos);
                pos[0]++; // skip ')'
                Group g = new Group(); g.num = -1; g.inner = inner; return g;
            } else {
                pos[0]++;
                groupCounter++;
                int num = groupCounter;
                Node inner = parseRegex(pat, pos);
                pos[0]++; // skip ')'
                Group g = new Group(); g.num = num; g.inner = inner; return g;
            }
        } else if (c == '.') { pos[0]++; return new Any(); }
        else if (c == '^') { pos[0]++; return new Begin(); }
        else if (c == '$') { pos[0]++; return new End(); }
        else if (c == '[') { return parseClass(pat, pos); }
        else if (c == '\\') { return parseEscape(pat, pos); }
        else { pos[0]++; return new Lit(c); }
    }

    static Node parseEscape(String pat, int[] pos) {
        pos[0]++; // skip '\'
        char c = pat.charAt(pos[0]); pos[0]++;
        if (c == 'd' || c == 'D' || c == 'w' || c == 'W' || c == 's' || c == 'S') {
            ClassNode cn = new ClassNode();
            cn.ranges = getClassRanges(c);
            cn.negated = (c == 'D' || c == 'W' || c == 'S');
            return cn;
        }
        return new Lit(c);
    }

    static List<int[]> getClassRanges(char type) {
        List<int[]> r = new ArrayList<>();
        if (type == 'd' || type == 'D') { r.add(new int[]{48,57}); }
        else if (type == 'w' || type == 'W') {
            r.add(new int[]{48,57}); r.add(new int[]{65,90});
            r.add(new int[]{95,95}); r.add(new int[]{97,122});
        }
        else if (type == 's' || type == 'S') {
            r.add(new int[]{9,13}); r.add(new int[]{32,32});
        }
        return r;
    }

    static Node parseClass(String pat, int[] pos) {
        pos[0]++; // skip '['
        boolean negated = false;
        if (pos[0] < pat.length() && pat.charAt(pos[0]) == '^') {
            negated = true; pos[0]++;
        }
        List<int[]> ranges = new ArrayList<>();
        while (pos[0] < pat.length() && pat.charAt(pos[0]) != ']') {
            char c1;
            if (pat.charAt(pos[0]) == '\\') {
                pos[0]++;
                char esc = pat.charAt(pos[0]);
                if (esc == 'd' || esc == 'D' || esc == 'w' || esc == 'W' || esc == 's' || esc == 'S') {
                    ranges.addAll(getClassRanges(esc));
                    pos[0]++;
                    continue;
                }
                c1 = esc; pos[0]++;
            } else {
                c1 = pat.charAt(pos[0]); pos[0]++;
            }
            // Check for range
            if (pos[0] + 1 < pat.length() && pat.charAt(pos[0]) == '-' && pat.charAt(pos[0]+1) != ']') {
                pos[0]++; // skip '-'
                char c2;
                if (pat.charAt(pos[0]) == '\\') {
                    pos[0]++;
                    c2 = pat.charAt(pos[0]); pos[0]++;
                } else {
                    c2 = pat.charAt(pos[0]); pos[0]++;
                }
                ranges.add(new int[]{c1, c2});
            } else {
                ranges.add(new int[]{c1, c1});
            }
        }
        pos[0]++; // skip ']'
        ClassNode cn = new ClassNode();
        cn.ranges = ranges; cn.negated = negated;
        return cn;
    }

    // NFA compilation
    static int compile(Node node, int next) {
        if (node instanceof Lit) {
            int s = emit(CHAR); sCh[s] = ((Lit)node).ch; sNext[s] = next; return s;
        }
        if (node instanceof Any) {
            int s = emit(ANY); sNext[s] = next; return s;
        }
        if (node instanceof Begin) {
            int s = emit(BEGIN); sNext[s] = next; return s;
        }
        if (node instanceof End) {
            int s = emit(END); sNext[s] = next; return s;
        }
        if (node instanceof ClassNode) {
            int s = emit(CLASS);
            List<int[]> r = ((ClassNode)node).ranges;
            sClass[s] = r.toArray(new int[0][]);
            sNegated[s] = ((ClassNode)node).negated;
            sNext[s] = next; return s;
        }
        if (node instanceof Alt) {
            Alt alt = (Alt)node;
            int result = next;
            for (int i = alt.branches.size()-1; i >= 0; i--) {
                int bStart = compile(alt.branches.get(i), next);
                int sp = emit(SPLIT);
                sNext[sp] = bStart;
                sNext2[sp] = result;
                result = sp;
            }
            return result;
        }
        if (node instanceof Seq) {
            Seq seq = (Seq)node;
            int curNext = next;
            for (int i = seq.pieces.size()-1; i >= 0; i--) {
                curNext = compile(seq.pieces.get(i), curNext);
            }
            return curNext;
        }
        if (node instanceof Group) {
            Group g = (Group)node;
            if (g.num >= 0) {
                int endS = emit(SAVE); sGrp[endS] = g.num; sSaveEnd[endS] = 1; sNext[endS] = next;
                int innerS = compile(g.inner, endS);
                int startS = emit(SAVE); sGrp[startS] = g.num; sSaveEnd[startS] = 0; sNext[startS] = innerS;
                return startS;
            } else {
                return compile(g.inner, next);
            }
        }
        if (node instanceof Quant) {
            return compileQuant((Quant)node, next);
        }
        return next;
    }

    static int compileQuant(Quant q, int next) {
        int curNext = next;
        if (q.max == -1) {
            // Unbounded: loop with CHECK_ITER
            int saveIter = emit(SAVE_ITER);
            int checkIter = emit(CHECK_ITER);
            int splitState = emit(SPLIT);
            int jmpState = emit(JMP);
            int initSplit = emit(SPLIT);
            int qid = numIters++;
            sIterId[saveIter] = qid;
            sIterId[checkIter] = qid;
            int atomStart = compile(q.atom, checkIter);
            sNext[saveIter] = atomStart;
            sNext[checkIter] = splitState;
            sNext2[checkIter] = next;
            if (!q.lazy) {
                sNext[splitState] = jmpState;
                sNext2[splitState] = next;
                sNext[initSplit] = saveIter;
                sNext2[initSplit] = next;
            } else {
                sNext[splitState] = next;
                sNext2[splitState] = jmpState;
                sNext[initSplit] = next;
                sNext2[initSplit] = saveIter;
            }
            sNext[jmpState] = saveIter;
            curNext = initSplit;
        } else {
            int optCount = q.max - q.min;
            if (optCount > 0) {
                // Build optional iterations from last to first
                for (int i = optCount - 1; i >= 0; i--) {
                    int saveIter = emit(SAVE_ITER);
                    int checkIter = emit(CHECK_ITER);
                    int qid = numIters++;
                    sIterId[saveIter] = qid;
                    sIterId[checkIter] = qid;
                    int atomStart = compile(q.atom, checkIter);
                    sNext[saveIter] = atomStart;
                    if (i == optCount - 1) {
                        sNext[checkIter] = next;
                        sNext2[checkIter] = next;
                    } else {
                        int splitState = emit(SPLIT);
                        sNext[checkIter] = splitState;
                        sNext2[checkIter] = next;
                        if (!q.lazy) {
                            sNext[splitState] = curNext;
                            sNext2[splitState] = next;
                        } else {
                            sNext[splitState] = next;
                            sNext2[splitState] = curNext;
                        }
                    }
                    curNext = saveIter;
                }
                int initSplit = emit(SPLIT);
                if (!q.lazy) {
                    sNext[initSplit] = curNext;
                    sNext2[initSplit] = next;
                } else {
                    sNext[initSplit] = next;
                    sNext2[initSplit] = curNext;
                }
                curNext = initSplit;
            }
        }
        // Mandatory part
        for (int i = 0; i < q.min; i++) {
            curNext = compile(q.atom, curNext);
        }
        return curNext;
    }

    // Matching
    static boolean match(int state, int pos) {
        if (memo[state][pos]) return false;
        int type = sType[state];
        switch (type) {
            case CHAR:
                if (pos < subjLen && subject.charAt(pos) == (char)sCh[state]) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case CLASS:
                if (pos < subjLen && matchesClass(subject.charAt(pos), state)) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case ANY:
                if (pos < subjLen) {
                    if (match(sNext[state], pos+1)) return true;
                }
                memo[state][pos] = true; return false;
            case SPLIT:
                if (match(sNext[state], pos)) return true;
                if (match(sNext2[state], pos)) return true;
                memo[state][pos] = true; return false;
            case JMP:
                return match(sNext[state], pos);
            case SAVE: {
                int g = sGrp[state], se = sSaveEnd[state];
                int old = captures[2*g+se];
                captures[2*g+se] = pos;
                if (match(sNext[state], pos)) return true;
                captures[2*g+se] = old;
                memo[state][pos] = true; return false;
            }
            case SAVE_ITER: {
                int q = sIterId[state];
                int oldp = iterPos[q];
                iterPos[q] = pos;
                if (match(sNext[state], pos)) return true;
                iterPos[q] = oldp;
                memo[state][pos] = true; return false;
            }
            case CHECK_ITER: {
                int q = sIterId[state];
                if (pos > iterPos[q]) {
                    if (match(sNext[state], pos)) return true;
                } else {
                    if (match(sNext2[state], pos)) return true;
                }
                return false;
            }
            case BEGIN:
                if (pos == 0) {
                    if (match(sNext[state], pos)) return true;
                }
                memo[state][pos] = true; return false;
            case END:
                if (pos == subjLen) {
                    if (match(sNext[state], pos)) return true;
                }
                memo[state][pos] = true; return false;
            case MATCH:
                lastMatchEnd = pos;
                return true;
        }
        return false;
    }

    static boolean matchesClass(char c, int state) {
        int[][] ranges = sClass[state];
        boolean in = false;
        for (int[] r : ranges) {
            if (c >= r[0] && c <= r[1]) { in = true; break; }
        }
        return sNegated[state] ? !in : in;
    }

    static String solve(String pattern, String subj) {
        subject = subj;
        subjLen = subj.length();
        groupCounter = 0;
        numIters = 0;
        numStates = 0;

        int[] pos = {0};
        Node ast = parseRegex(pattern, pos);
        numGroups = groupCounter;

        // Initialize NFA arrays
        int initCap = 4096;
        sType = new int[initCap]; sNext = new int[initCap]; sNext2 = new int[initCap];
        sCh = new int[initCap]; sGrp = new int[initCap]; sSaveEnd = new int[initCap];
        sIterId = new int[initCap]; sNegated = new boolean[initCap]; sClass = new int[initCap][][];
        numStates = 0;

        int matchState = emit(MATCH);
        int startState = compile(ast, matchState);

        captures = new int[2 * (numGroups + 1)];
        iterPos = new int[numIters + 1];
        memo = new boolean[numStates][subjLen + 1];

        for (int sp = 0; sp <= subjLen; sp++) {
            Arrays.fill(captures, -1);
            Arrays.fill(iterPos, -1);
            for (int i = 0; i < numStates; i++) Arrays.fill(memo[i], false);
            if (match(startState, sp)) {
                StringBuilder sb = new StringBuilder();
                sb.append(sp).append("-").append(lastMatchEnd);
                for (int g = 1; g <= numGroups; g++) {
                    sb.append(" ");
                    if (captures[2*g] == -1) {
                        sb.append("-");
                    } else {
                        sb.append(captures[2*g]).append("-").append(captures[2*g+1]);
                    }
                }
                return sb.toString();
            }
        }
        return "no match";
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        BufferedReader br = new BufferedReader(new FileReader(dir + "/cases.txt"));
        String line;
        int lineNum = 0;
        while ((line = br.readLine()) != null) {
            lineNum++;
            int tab = line.indexOf('\t');
            String pattern = line.substring(0, tab);
            String subj = line.substring(tab + 1);
            String result = solve(pattern, subj);
            System.out.println(lineNum + ": " + result);
        }
        br.close();
    }
}

import Foundation

// MARK: - Form URL Encoding (RFC 6749 §2.3.1)
func formURLEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 65 && byte <= 90) ||
           (byte >= 97 && byte <= 122) ||
           (byte >= 48 && byte <= 57) ||
           byte == 45 || byte == 46 || byte == 95 || byte == 42 {
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 32 {
            result.append("+")
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

// MARK: - Percent Encoding for query params
func percentEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 65 && byte <= 90) ||
           (byte >= 97 && byte <= 122) ||
           (byte >= 48 && byte <= 57) ||
           byte == 45 || byte == 46 || byte == 95 || byte == 126 {
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

// MARK: - HTTP Response
struct HTTPResponse {
    let status: Int
    let headers: [String: String]
    let body: String
}

// MARK: - Chunked Decoding
func decodeChunked(_ raw: String) -> String {
    let bytes = Array(raw.utf8)
    var result = ""
    var pos = 0
    while pos < bytes.count {
        var sizeStr = ""
        while pos < bytes.count && bytes[pos] != 0x0D {
            sizeStr.append(Character(UnicodeScalar(bytes[pos])))
            pos += 1
        }
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
        guard let chunkSize = Int(sizeStr, radix: 16) else { break }
        if chunkSize == 0 { break }
        let end = pos + chunkSize
        if end <= bytes.count {
            result += String(data: Data(bytes[pos..<end]), encoding: .utf8) ?? ""
        }
        pos = end
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
    }
    return result
}

// MARK: - HTTP Exchange
func httpExchange(host: String, port: UInt16, method: String, path: String,
                  headers: [(String, String)], body: String?) -> HTTPResponse {
    let sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    precondition(sock >= 0, "socket() failed")
    var tv = timeval(tv_sec: 60, tv_usec: 0)
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))
    setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)

    let cr = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(sock, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    precondition(cr == 0, "connect() failed to \(host):\(port)")

    var req = "\(method) \(path) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    if let b = body {
        req += "Content-Length: \(Data(b.utf8).count)\r\n"
    }
    req += "\r\n"
    if let b = body { req += b }

    let reqData = Data(req.utf8)
    reqData.withUnsafeBytes { ptr in
        var sent = 0
        while sent < reqData.count {
            let n = send(sock, ptr.baseAddress!.advanced(by: sent), reqData.count - sent, 0)
            if n <= 0 { break }
            sent += n
        }
    }

    var buf = Data()
    var tmp = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(sock, &tmp, tmp.count, 0)
        if n <= 0 { break }
        buf.append(contentsOf: tmp[0..<n])
    }
    close(sock)

    guard let respStr = String(data: buf, encoding: .utf8) else {
        return HTTPResponse(status: 0, headers: [:], body: "")
    }
    guard let hdrEnd = respStr.range(of: "\r\n\r\n") else {
        return HTTPResponse(status: 0, headers: [:], body: "")
    }
    let hdrSection = String(respStr[respStr.startIndex..<hdrEnd.lowerBound])
    var bodySection = String(respStr[hdrEnd.upperBound...])

    let lines = hdrSection.components(separatedBy: "\r\n")
    var status = 0
    if let sl = lines.first {
        let parts = sl.components(separatedBy: " ")
        if parts.count >= 2 { status = Int(parts[1]) ?? 0 }
    }
    var hdrs: [String: String] = [:]
    for i in 1..<lines.count {
        if let ci = lines[i].firstIndex(of: ":") {
            let k = String(lines[i][lines[i].startIndex..<ci]).lowercased()
            let v = String(lines[i][lines[i].index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            hdrs[k] = v
        }
    }
    if let te = hdrs["transfer-encoding"], te.lowercased().contains("chunked") {
        bodySection = decodeChunked(bodySection)
    }
    return HTTPResponse(status: status, headers: hdrs, body: bodySection)
}

// MARK: - Amount Parsing (exact cents)
func parseAmount(_ s: String) -> Int64 {
    var idx = s.startIndex
    var negative = false
    if s[idx] == "-" { negative = true; idx = s.index(after: idx) }
    var intPart = ""
    while idx < s.endIndex && s[idx] != "." {
        intPart.append(s[idx])
        idx = s.index(after: idx)
    }
    var fracPart = ""
    if idx < s.endIndex && s[idx] == "." {
        idx = s.index(after: idx)
        while idx < s.endIndex {
            fracPart.append(s[idx])
            idx = s.index(after: idx)
        }
    }
    while fracPart.count < 2 { fracPart.append("0") }
    if fracPart.count > 2 { fracPart = String(fracPart.prefix(2)) }
    let cents = (Int64(intPart) ?? 0) * 100 + (Int64(fracPart) ?? 0)
    return negative ? -cents : cents
}

func formatCents(_ cents: Int64) -> String {
    let neg = cents < 0
    let absC = neg ? -cents : cents
    let whole = absC / 100
    let frac = absC % 100
    let sign = neg ? "-" : ""
    return "\(sign)\(whole).\(String(format: "%02lld", frac))"
}

// MARK: - UTF-8 byte comparison
func utf8Less(_ a: String, _ b: String) -> Bool {
    let ab = Array(a.utf8)
    let bb = Array(b.utf8)
    let n = min(ab.count, bb.count)
    for i in 0..<n {
        if ab[i] != bb[i] { return ab[i] < bb[i] }
    }
    return ab.count < bb.count
}

// MARK: - Fatal error
func fatal(_ status: Int, _ body: String) -> Never {
    print("ERROR \(status) \(body)")
    exit(0)
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 3 else { fatalError("usage: main <data_dir> <base_url>") }
let dataDir = args[1]
let baseUrl = args[2]

// Read client.json
let clientPath = dataDir + "/client.json"
let clientData = try! Data(contentsOf: URL(fileURLWithPath: clientPath))
let clientJson = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientId = clientJson["client_id"] as! String
let clientSecret = clientJson["client_secret"] as! String
let scope = clientJson["scope"] as! String
let pageSize = (clientJson["page_size"] as! NSNumber).intValue

// Parse base URL: http://host:port/path
var remaining = baseUrl
if remaining.hasPrefix("http://") { remaining = String(remaining.dropFirst(7)) }
guard let slashPos = remaining.firstIndex(of: "/") else { fatalError("bad url") }
let hostPort = String(remaining[remaining.startIndex..<slashPos])
let pathPrefix = String(remaining[slashPos...])
guard let colonPos = hostPort.lastIndex(of: ":") else { fatalError("bad host:port") }
let host = String(hostPort[hostPort.startIndex..<colonPos])
let port = UInt16(hostPort[hostPort.index(after: colonPos)...])!

// MARK: Get Token
func getToken() -> String {
    let encId = formURLEncode(clientId)
    let encSecret = formURLEncode(clientSecret)
    let credentials = encId + ":" + encSecret
    let b64 = Data(credentials.utf8).base64EncodedString()
    let tokenBody = "grant_type=client_credentials&scope=" + formURLEncode(scope)
    let resp = httpExchange(host: host, port: port, method: "POST",
                            path: pathPrefix + "/oauth/token",
                            headers: [("Content-Type", "application/x-www-form-urlencoded"),
                                      ("Authorization", "Basic " + b64)],
                            body: tokenBody)
    if resp.status != 200 { fatal(resp.status, resp.body) }
    let json = try! JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as! [String: Any]
    return json["access_token"] as! String
}

// MARK: Fetch Pages
var accessToken = getToken()
var firstReqWithToken = true
var totalPages = 0
var totalRetries = 0
var totalReauths = 0
var allOrders: [[String: Any]] = []

var cursor: String? = nil

while true {
    var query = "?limit=\(pageSize)"
    if let c = cursor {
        query += "&cursor=" + percentEncode(c)
    }
    let path = pathPrefix + "/orders" + query

    while true {
        let resp = httpExchange(host: host, port: port, method: "GET", path: path,
                                headers: [("Authorization", "Bearer " + accessToken)],
                                body: nil)
        if resp.status == 429 {
            totalRetries += 1
            let ra = Int(resp.headers["retry-after"] ?? "1") ?? 1
            Thread.sleep(forTimeInterval: Double(ra))
            continue
        }
        if resp.status == 503 {
            totalRetries += 1
            Thread.sleep(forTimeInterval: 0.5)
            continue
        }
        if resp.status == 401 {
            if firstReqWithToken {
                fatal(resp.status, resp.body)
            }
            totalReauths += 1
            accessToken = getToken()
            firstReqWithToken = true
            continue
        }
        if resp.status != 200 {
            fatal(resp.status, resp.body)
        }
        // 200
        firstReqWithToken = false
        totalPages += 1
        let json = try! JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as! [String: Any]
        if let dataArr = json["data"] as? [Any] {
            for item in dataArr {
                if let order = item as? [String: Any] {
                    allOrders.append(order)
                }
            }
        }
        if let nc = json["next_cursor"], !(nc is NSNull) {
            cursor = nc as? String
        } else {
            cursor = nil
        }
        break
    }
    if cursor == nil { break }
}

// MARK: Aggregate
var totals: [(name: String, currency: String, cents: Int64)] = []
var statusCounts: [String: Int] = [:]

for order in allOrders {
    let status = (order["status"] as? String) ?? ""
    statusCounts[status, default: 0] += 1

    if status != "cancelled" {
        let customer = order["customer"] as? [String: Any]
        let name = (customer?["name"] as? String) ?? ""
        let currency = (order["currency"] as? String) ?? ""
        let amountStr = (order["amount"] as? String) ?? "0"
        let cents = parseAmount(amountStr)

        var found = false
        for i in 0..<totals.count {
            if totals[i].name == name && totals[i].currency == currency {
                totals[i].cents += cents
                found = true
                break
            }
        }
        if !found {
            totals.append((name: name, currency: currency, cents: cents))
        }
    }
}

// Sort totals by name (UTF-8 bytes), then currency
totals.sort { a, b in
    if utf8Less(a.name, b.name) { return true }
    if utf8Less(b.name, a.name) { return false }
    return utf8Less(a.currency, b.currency)
}

// Print totals
for t in totals {
    print("total \(t.currency) \(formatCents(t.cents)) \(t.name)")
}

// Print statuses sorted
let sortedStatuses = statusCounts.keys.sorted()
for s in sortedStatuses {
    print("status \(s) \(statusCounts[s]!)")
}

// Print summary
print("orders \(allOrders.count) pages \(totalPages) retries \(totalRetries) reauth \(totalReauths)")

exit(0)

import sys
sys.setrecursionlimit(1000000)

DIGITS = set('0123456789')
WORD_CHARS = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_')
SPACE_CHARS = set(' \t\n\r\x0c\x0b')

def matches_ce(c, name):
    if name == 'd': return c in DIGITS
    if name == 'D': return c not in DIGITS
    if name == 'w': return c in WORD_CHARS
    if name == 'W': return c not in WORD_CHARS
    if name == 's': return c in SPACE_CHARS
    if name == 'S': return c not in SPACE_CHARS
    return False

def matches_class(c, items, negated):
    found = False
    for item in items:
        if item[0] == 'char':
            if c == item[1]:
                found = True
                break
        elif item[0] == 'range':
            if item[1] <= c <= item[2]:
                found = True
                break
        elif item[0] == 'class_escape':
            if matches_ce(c, item[1]):
                found = True
                break
    return (not found) if negated else found

class Parser:
    def __init__(self, pattern):
        self.p = pattern
        self.pos = 0
        self.group_count = 0

    def parse(self):
        return self.parse_regex()

    def peek(self):
        if self.pos < len(self.p):
            return self.p[self.pos]
        return None

    def eat(self):
        c = self.p[self.pos]
        self.pos += 1
        return c

    def parse_regex(self):
        branches = [self.parse_branch()]
        while self.peek() == '|':
            self.eat()
            branches.append(self.parse_branch())
        if len(branches) == 1:
            return branches[0]
        return ('alt', branches)

    def parse_branch(self):
        pieces = []
        while self.pos < len(self.p) and self.p[self.pos] not in '|)':
            pieces.append(self.parse_piece())
        if not pieces:
            return ('empty',)
        if len(pieces) == 1:
            return pieces[0]
        return ('concat', pieces)

    def parse_piece(self):
        atom = self.parse_atom()
        if self.pos < len(self.p) and self.p[self.pos] in '*+?{':
            q = self.parse_quantifier()
            if q is not None:
                return ('quant', atom, q[0], q[1], q[2])
        return atom

    def parse_quantifier(self):
        c = self.peek()
        if c == '*':
            self.eat()
            g = True
            if self.peek() == '?':
                self.eat()
                g = False
            return (0, None, g)
        elif c == '+':
            self.eat()
            g = True
            if self.peek() == '?':
                self.eat()
                g = False
            return (1, None, g)
        elif c == '?':
            self.eat()
            g = True
            if self.peek() == '?':
                self.eat()
                g = False
            return (0, 1, g)
        elif c == '{':
            self.eat()
            m = self.parse_int()
            if self.peek() == ',':
                self.eat()
                if self.peek() == '}':
                    n = None
                else:
                    n = self.parse_int()
            else:
                n = m
            self.eat()
            g = True
            if self.peek() == '?':
                self.eat()
                g = False
            return (m, n, g)
        return None

    def parse_int(self):
        s = self.pos
        while self.pos < len(self.p) and self.p[self.pos].isdigit():
            self.pos += 1
        return int(self.p[s:self.pos])

    def parse_atom(self):
        c = self.peek()
        if c == '(':
            self.eat()
            if self.p[self.pos:self.pos+2] == '?:':
                self.pos += 2
                r = self.parse_regex()
                self.eat()
                return ('group', r, None)
            else:
                self.group_count += 1
                gid = self.group_count
                r = self.parse_regex()
                self.eat()
                return ('group', r, gid)
        elif c == '.':
            self.eat()
            return ('dot',)
        elif c == '^':
            self.eat()
            return ('assert_start',)
        elif c == '$':
            self.eat()
            return ('assert_end',)
        elif c == '[':
            return self.parse_class()
        elif c == '\\':
            self.eat()
            c2 = self.eat()
            if c2 in 'dDwWsS':
                return ('class_escape', c2)
            return ('char', c2)
        else:
            self.eat()
            return ('char', c)

    def parse_class(self):
        self.eat()
        negated = False
        if self.peek() == '^':
            self.eat()
            negated = True
        items = []
        while self.peek() != ']':
            if self.peek() == '\\':
                self.eat()
                c = self.eat()
                if c in 'dDwWsS':
                    items.append(('class_escape', c))
                    continue
                if self.peek() == '-' and self.pos + 1 < len(self.p) and self.p[self.pos+1] != ']':
                    self.eat()
                    if self.peek() == '\\':
                        self.eat()
                        end_c = self.eat()
                    else:
                        end_c = self.eat()
                    items.append(('range', c, end_c))
                else:
                    items.append(('char', c))
            else:
                c = self.eat()
                if self.peek() == '-' and self.pos + 1 < len(self.p) and self.p[self.pos+1] != ']':
                    self.eat()
                    if self.peek() == '\\':
                        self.eat()
                        end_c = self.eat()
                    else:
                        end_c = self.eat()
                    items.append(('range', c, end_c))
                else:
                    items.append(('char', c))
        self.eat()
        return ('class', items, negated)


class Compiler:
    def __init__(self, ngroups):
        self.prog = []
        self.ngroups = ngroups
        self.loop_count = 0

    def compile(self, ast):
        self.compile_node(ast)
        self.prog.append(('match',))

    def compile_node(self, node):
        op = node[0]
        if op == 'empty':
            pass
        elif op == 'char':
            self.prog.append(('char', node[1]))
        elif op == 'dot':
            self.prog.append(('dot',))
        elif op == 'assert_start':
            self.prog.append(('assert_start',))
        elif op == 'assert_end':
            self.prog.append(('assert_end',))
        elif op == 'class':
            self.prog.append(('class', node[1], node[2]))
        elif op == 'class_escape':
            self.prog.append(('class_escape', node[1]))
        elif op == 'concat':
            for piece in node[1]:
                self.compile_node(piece)
        elif op == 'alt':
            self.compile_alt(node[1])
        elif op == 'group':
            regex, gid = node[1], node[2]
            if gid is not None:
                self.prog.append(('save', 2*(gid-1)))
                self.compile_node(regex)
                self.prog.append(('save', 2*(gid-1)+1))
            else:
                self.compile_node(regex)
        elif op == 'quant':
            atom, mn, mx, greedy = node[1], node[2], node[3], node[4]
            self.compile_quant(atom, mn, mx, greedy)

    def compile_alt(self, branches):
        if len(branches) == 1:
            self.compile_node(branches[0])
            return
        split_pc = len(self.prog)
        self.prog.append(('split', 0, 0))
        first_start = len(self.prog)
        self.compile_node(branches[0])
        jmp_pc = len(self.prog)
        self.prog.append(('jmp', 0))
        rest_start = len(self.prog)
        self.compile_alt(branches[1:])
        end_pc = len(self.prog)
        self.prog[split_pc] = ('split', first_start, rest_start)
        self.prog[jmp_pc] = ('jmp', end_pc)

    def compile_quant(self, atom, mn, mx, greedy):
        for _ in range(mn):
            self.compile_node(atom)
        if mx is None:
            self.compile_optional_loop(atom, greedy)
        elif mx > mn:
            self.compile_bounded_optional(atom, mx - mn, greedy)

    def compile_optional_loop(self, atom, greedy):
        loop_id = self.loop_count
        self.loop_count += 1
        split_pc = len(self.prog)
        self.prog.append(('split', 0, 0))
        body_start = len(self.prog)
        self.prog.append(('save_loop', loop_id))
        self.compile_node(atom)
        check_pc = len(self.prog)
        self.prog.append(('check_empty', loop_id, 0, 0))
        exit_pc = len(self.prog)
        if greedy:
            self.prog[split_pc] = ('split', body_start, exit_pc)
        else:
            self.prog[split_pc] = ('split', exit_pc, body_start)
        self.prog[check_pc] = ('check_empty', loop_id, split_pc, exit_pc)

    def compile_bounded_optional(self, atom, count, greedy):
        split_indices = []
        check_indices = []
        loop_ids = []
        for _ in range(count):
            split_pc = len(self.prog)
            self.prog.append(('split', 0, 0))
            split_indices.append(split_pc)
            lid = self.loop_count
            self.loop_count += 1
            loop_ids.append(lid)
            self.prog.append(('save_loop', lid))
            self.compile_node(atom)
            check_pc = len(self.prog)
            self.prog.append(('check_empty', lid, 0, 0))
            check_indices.append(check_pc)
        exit_pc = len(self.prog)
        for i in range(count):
            if greedy:
                self.prog[split_indices[i]] = ('split', split_indices[i] + 1, exit_pc)
            else:
                self.prog[split_indices[i]] = ('split', exit_pc, split_indices[i] + 1)
            if i < count - 1:
                next_pc = split_indices[i + 1]
            else:
                next_pc = exit_pc
            self.prog[check_indices[i]] = ('check_empty', loop_ids[i], next_pc, exit_pc)


def backtrack(prog, pc, pos, subject, caps, loop_pos, memo, n):
    key = (pc, pos)
    if key in memo:
        return memo[key]
    instr = prog[pc]
    op = instr[0]
    result = None
    if op == 'match':
        result = pos
    elif op == 'char':
        if pos < n and subject[pos] == instr[1]:
            result = backtrack(prog, pc + 1, pos + 1, subject, caps, loop_pos, memo, n)
    elif op == 'dot':
        if pos < n:
            result = backtrack(prog, pc + 1, pos + 1, subject, caps, loop_pos, memo, n)
    elif op == 'class':
        if pos < n and matches_class(subject[pos], instr[1], instr[2]):
            result = backtrack(prog, pc + 1, pos + 1, subject, caps, loop_pos, memo, n)
    elif op == 'class_escape':
        if pos < n and matches_ce(subject[pos], instr[1]):
            result = backtrack(prog, pc + 1, pos + 1, subject, caps, loop_pos, memo, n)
    elif op == 'split':
        result = backtrack(prog, instr[1], pos, subject, caps, loop_pos, memo, n)
        if result is None:
            result = backtrack(prog, instr[2], pos, subject, caps, loop_pos, memo, n)
    elif op == 'jmp':
        result = backtrack(prog, instr[1], pos, subject, caps, loop_pos, memo, n)
    elif op == 'save':
        idx = instr[1]
        old = caps[idx]
        caps[idx] = pos
        result = backtrack(prog, pc + 1, pos, subject, caps, loop_pos, memo, n)
        if result is None:
            caps[idx] = old
    elif op == 'save_loop':
        lid = instr[1]
        old = loop_pos[lid]
        loop_pos[lid] = pos
        result = backtrack(prog, pc + 1, pos, subject, caps, loop_pos, memo, n)
        if result is None:
            loop_pos[lid] = old
    elif op == 'check_empty':
        lid, loop_target, exit_target = instr[1], instr[2], instr[3]
        if pos == loop_pos[lid]:
            result = backtrack(prog, exit_target, pos, subject, caps, loop_pos, memo, n)
        else:
            result = backtrack(prog, loop_target, pos, subject, caps, loop_pos, memo, n)
    elif op == 'assert_start':
        if pos == 0:
            result = backtrack(prog, pc + 1, pos, subject, caps, loop_pos, memo, n)
    elif op == 'assert_end':
        if pos == n:
            result = backtrack(prog, pc + 1, pos, subject, caps, loop_pos, memo, n)
    memo[key] = result
    return result


def regex_search(pattern, subject):
    parser = Parser(pattern)
    ast = parser.parse()
    ngroups = parser.group_count
    compiler = Compiler(ngroups)
    compiler.compile(ast)
    prog = compiler.prog
    nloops = compiler.loop_count
    n = len(subject)
    for start in range(n + 1):
        caps = [None] * (2 * ngroups)
        loop_pos = [None] * nloops
        memo = {}
        result = backtrack(prog, 0, start, subject, caps, loop_pos, memo, n)
        if result is not None:
            captures = []
            for g in range(ngroups):
                s, e = caps[2*g], caps[2*g+1]
                if s is not None and e is not None:
                    captures.append((s, e))
                else:
                    captures.append(None)
            return (start, result, captures)
    return None


def main():
    dir_path = sys.argv[1]
    with open(dir_path + '/cases.txt', 'r') as f:
        content = f.read()
    lines = content.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    for i, line in enumerate(lines, 1):
        tab_pos = line.index('\t')
        pattern = line[:tab_pos]
        subject = line[tab_pos+1:]
        result = regex_search(pattern, subject)
        if result is None:
            print(f"{i}: no match")
        else:
            start, end, captures = result
            parts = [f"{start}-{end}"]
            for cap in captures:
                if cap is None:
                    parts.append("-")
                else:
                    parts.append(f"{cap[0]}-{cap[1]}")
            print(f"{i}: {' '.join(parts)}")

if __name__ == '__main__':
    main()

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface ClientConfig {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

interface HttpResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

function formUrlEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf-8');
  let result = '';
  for (const b of bytes) {
    if ((b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57) ||
        b === 45 || b === 46 || b === 95 || b === 42) {
      result += String.fromCharCode(b);
    } else if (b === 32) {
      result += '+';
    } else {
      result += '%' + b.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function percentEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf-8');
  let result = '';
  for (const b of bytes) {
    if ((b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57) ||
        b === 45 || b === 46 || b === 95 || b === 126) {
      result += String.fromCharCode(b);
    } else {
      result += '%' + b.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function makeRequest(
  method: string,
  hostname: string,
  port: number,
  reqPath: string,
  headers: Record<string, string>,
  body?: string
): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const allHeaders: Record<string, string> = { ...headers, 'Host': `${hostname}:${port}` };
    if (body !== undefined) {
      allHeaders['Content-Length'] = Buffer.byteLength(body, 'utf-8').toString();
    }
    const req = http.request({
      method,
      hostname,
      port,
      path: reqPath,
      headers: allHeaders,
      httpVersion: '1.1',
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode!,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

function parseCents(s: string): bigint {
  let negative = false;
  if (s[0] === '-') {
    negative = true;
    s = s.slice(1);
  }
  const dotIdx = s.indexOf('.');
  let intPart: string, fracPart: string;
  if (dotIdx === -1) {
    intPart = s;
    fracPart = '00';
  } else {
    intPart = s.slice(0, dotIdx);
    fracPart = s.slice(dotIdx + 1);
    if (fracPart.length === 1) fracPart += '0';
  }
  const cents = BigInt(intPart) * 100n + BigInt(fracPart);
  return negative ? -cents : cents;
}

function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / 100n;
  const fracPart = abs % 100n;
  const fracStr = fracPart.toString().padStart(2, '0');
  return (negative ? '-' : '') + intPart.toString() + '.' + fracStr;
}

async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const clientConfig: ClientConfig = JSON.parse(
    fs.readFileSync(path.join(dataDir, 'client.json'), 'utf-8')
  );

  const url = new URL(baseUrl);
  const hostname = url.hostname;
  const port = url.port ? parseInt(url.port) : 80;
  const basePath = url.pathname;

  let totalPages = 0;
  let totalRetries = 0;
  let totalReauth = 0;
  let totalOrders = 0;

  function buildAuthHeader(): string {
    const encodedId = formUrlEncode(clientConfig.client_id);
    const encodedSecret = formUrlEncode(clientConfig.client_secret);
    const combined = encodedId + ':' + encodedSecret;
    return 'Basic ' + Buffer.from(combined, 'ascii').toString('base64');
  }

  async function getToken(): Promise<string> {
    const tokenPath = basePath + '/oauth/token';
    const body = 'grant_type=client_credentials&scope=' + formUrlEncode(clientConfig.scope);
    const res = await makeRequest('POST', hostname, port, tokenPath, {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': buildAuthHeader(),
    }, body);
    if (res.status !== 200) {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }
    const data = JSON.parse(res.body);
    return data.access_token;
  }

  let accessToken = await getToken();
  let tokenUsed = false;

  const totals = new Map<string, bigint>();
  const statusCounts = new Map<string, number>();
  let cursor: string | null = null;
  let firstPage = true;

  while (true) {
    let reqPath = basePath + '/orders?limit=' + clientConfig.page_size;
    if (!firstPage && cursor !== null) {
      reqPath += '&cursor=' + percentEncode(cursor);
    }

    const res = await makeRequest('GET', hostname, port, reqPath, {
      'Authorization': 'Bearer ' + accessToken,
    });

    if (res.status === 429) {
      totalRetries++;
      const retryAfter = parseInt((res.headers['retry-after'] as string) || '1', 10);
      await sleep(retryAfter * 1000);
      continue;
    }

    if (res.status === 503) {
      totalRetries++;
      await sleep(100);
      continue;
    }

    if (res.status === 401) {
      if (!tokenUsed) {
        process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
        process.exit(0);
      }
      totalReauth++;
      accessToken = await getToken();
      tokenUsed = false;
      continue;
    }

    if (res.status !== 200) {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }

    tokenUsed = true;
    totalPages++;
    const pageData = JSON.parse(res.body);
    const orders: any[] = pageData.data || [];
    totalOrders += orders.length;

    for (const order of orders) {
      const status: string = order.status;
      statusCounts.set(status, (statusCounts.get(status) || 0) + 1);
      if (status !== 'cancelled') {
        const name: string = order.customer.name;
        const currency: string = order.currency;
        const key = name + '\x00' + currency;
        const cents = parseCents(order.amount);
        totals.set(key, (totals.get(key) || 0n) + cents);
      }
    }

    cursor = pageData.next_cursor;
    firstPage = false;
    if (cursor === null) {
      break;
    }
  }

  // Build output lines for totals
  const totalEntries: { name: string; currency: string; cents: bigint }[] = [];
  for (const [key, cents] of totals) {
    const sepIdx = key.indexOf('\x00');
    const name = key.slice(0, sepIdx);
    const currency = key.slice(sepIdx + 1);
    totalEntries.push({ name, currency, cents });
  }
  totalEntries.sort((a, b) => {
    const cmp = Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8'));
    if (cmp !== 0) return cmp;
    return Buffer.compare(Buffer.from(a.currency, 'utf-8'), Buffer.from(b.currency, 'utf-8'));
  });

  for (const entry of totalEntries) {
    process.stdout.write(`total ${entry.currency} ${formatCents(entry.cents)} ${entry.name}\n`);
  }

  const sortedStatuses = [...statusCounts.entries()].sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  );
  for (const [status, count] of sortedStatuses) {
    process.stdout.write(`status ${status} ${count}\n`);
  }

  process.stdout.write(
    `orders ${totalOrders} pages ${totalPages} retries ${totalRetries} reauth ${totalReauth}\n`
  );
}

main().catch((err) => {
  process.stderr.write(String(err) + '\n');
  process.exit(1);
});

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::Read;
use std::net::TcpStream;
use std::process;
use std::thread;
use std::time::Duration;

// ============ JSON ============

#[derive(Debug, Clone)]
enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(ref pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(ref s) = self { Some(s) } else { None }
    }
    fn as_array(&self) -> Option<&[Json]> {
        if let Json::Array(ref a) = self { Some(a) } else { None }
    }
    fn is_null(&self) -> bool { matches!(self, Json::Null) }
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn peek(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self, c: u8) { assert!(self.p < self.s.len() && self.s[self.p] == c); self.p += 1; }
    fn parse(&mut self) -> Json {
        self.ws();
        match self.peek() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => Json::Str(self.string()),
            Some(b't') => { assert!(&self.s[self.p..self.p+4]==b"true"); self.p+=4; Json::Bool(true) }
            Some(b'f') => { assert!(&self.s[self.p..self.p+5]==b"false"); self.p+=5; Json::Bool(false) }
            Some(b'n') => { assert!(&self.s[self.p..self.p+4]==b"null"); self.p+=4; Json::Null }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Json {
        self.eat(b'{');
        let mut pairs = Vec::new();
        self.ws();
        if self.peek()==Some(b'}') { self.p+=1; return Json::Object(pairs); }
        loop {
            self.ws();
            let k = self.string();
            self.ws(); self.eat(b':'); self.ws();
            let v = self.parse();
            pairs.push((k,v));
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b'}');
        Json::Object(pairs)
    }
    fn arr(&mut self) -> Json {
        self.eat(b'[');
        let mut items = Vec::new();
        self.ws();
        if self.peek()==Some(b']') { self.p+=1; return Json::Array(items); }
        loop {
            self.ws();
            items.push(self.parse());
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b']');
        Json::Array(items)
    }
    fn string(&mut self) -> String {
        self.eat(b'"');
        let mut r = Vec::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let c2 = self.s[self.p]; self.p += 1;
                match c2 {
                    b'"' => r.push(b'"'),
                    b'\\' => r.push(b'\\'),
                    b'/' => r.push(b'/'),
                    b'b' => r.push(8),
                    b'f' => r.push(12),
                    b'n' => r.push(b'\n'),
                    b'r' => r.push(b'\r'),
                    b't' => r.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert!(self.s[self.p]==b'\\' && self.s[self.p+1]==b'u');
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000u32 + ((cp-0xD800)<<10) + (lo-0xDC00);
                            let ch = char::from_u32(code).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        } else {
                            let ch = char::from_u32(cp).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => panic!("bad esc"),
                }
            } else {
                r.push(c);
            }
        }
        String::from_utf8(r).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let h = &self.s[self.p..self.p+4]; self.p += 4;
        let mut v = 0u32;
        for &b in h { v <<= 4; v |= match b {
            b'0'..=b'9' => (b-b'0') as u32,
            b'a'..=b'f' => (b-b'a'+10) as u32,
            b'A'..=b'F' => (b-b'A'+10) as u32,
            _ => panic!("hex"),
        }; }
        v
    }
    fn num(&mut self) -> Json {
        let st = self.p;
        if self.peek()==Some(b'-') { self.p+=1; }
        while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; }
        if self.p<self.s.len() && self.s[self.p]==b'.' { self.p+=1; while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        if self.p<self.s.len() && (self.s[self.p]==b'e'||self.s[self.p]==b'E') { self.p+=1; if self.p<self.s.len() && (self.s[self.p]==b'+'||self.s[self.p]==b'-') { self.p+=1; } while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        Json::Num(std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap())
    }
}

fn parse_json(s: &str) -> Json { JP::new(s).parse() }

// ============ Base64 ============

fn b64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    let mut i = 0;
    while i + 2 < data.len() {
        let n = ((data[i] as u32) << 16) | ((data[i+1] as u32) << 8) | (data[i+2] as u32);
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        r.push(T[((n>>6)&63) as usize] as char);
        r.push(T[(n&63) as usize] as char);
        i += 3;
    }
    if i < data.len() {
        let n = ((data[i] as u32) << 16) | if i+1<data.len() { (data[i+1] as u32)<<8 } else { 0 };
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() {
            r.push(T[((n>>6)&63) as usize] as char);
            r.push('=');
        } else {
            r.push('=');
            r.push('=');
        }
    }
    r
}

// ============ Encoding ============

fn form_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'.' || b==b'_' || b==b'*' {
            r.push(b as char);
        } else if b == b' ' {
            r.push('+');
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn query_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'_' || b==b'.' || b==b'~' {
            r.push(b as char);
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

// ============ HTTP ============

struct Resp { status: u16, headers: Vec<(String,String)>, body: String }

fn parse_headers(raw: &[u8]) -> (u16, Vec<(String,String)>, usize) {
    let text = std::str::from_utf8(raw).unwrap();
    let mut lines = text.split("\r\n");
    let status_line = lines.next().unwrap();
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts[1].parse().unwrap();
    let mut headers = Vec::new();
    let mut body_start = status_line.len() + 2;
    for line in lines {
        if line.is_empty() { body_start += 2; break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_lowercase();
            let v = line[idx+1..].trim().to_string();
            headers.push((k, v));
        }
        body_start += line.len() + 2;
    }
    (status, headers, body_start)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        let nl = find_crlf(data, pos);
        let size_str = std::str::from_utf8(&data[pos..nl]).unwrap().trim();
        // handle possible extensions after ;
        let size_str = if let Some(semi) = size_str.find(';') { &size_str[..semi] } else { size_str };
        let size = usize::from_str_radix(size_str, 16).unwrap();
        pos = nl + 2;
        if size == 0 { break; }
        result.extend_from_slice(&data[pos..pos+size]);
        pos += size + 2; // skip trailing \r\n
    }
    result
}

fn find_crlf(data: &[u8], from: usize) -> usize {
    let mut i = from;
    while i + 1 < data.len() {
        if data[i]==b'\r' && data[i+1]==b'\n' { return i; }
        i += 1;
    }
    data.len()
}

fn http_request(method: &str, host: &str, port: u16, path: &str, extra_headers: &[(&str,&str)], body: Option<&str>) -> Resp {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    stream.set_read_timeout(Some(Duration::from_secs(30))).unwrap();

    let host_hdr = if port == 80 { format!("{}", host) } else { format!("{}:{}", host, port) };
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host_hdr);
    for (k,v) in extra_headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("\r\n");
    if let Some(b) = body { req.push_str(b); }

    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();

    let (status, headers, body_start) = parse_headers(&raw);
    let body_bytes = &raw[body_start..];

    let body_vec = if headers.iter().any(|(k,v)| k=="transfer-encoding" && v.contains("chunked")) {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    Resp { status, headers, body: String::from_utf8(body_vec).unwrap() }
}

// ============ URL parsing ============

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { panic!("bad url") };
    let slash = rest.find('/').unwrap_or(rest.len());
    let authority = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "" };
    let (host, port) = if let Some(colon) = authority.rfind(':') {
        // Check it's not an IPv6 bracket
        if authority[colon..].contains(']') {
            (authority.to_string(), 80u16)
        } else {
            (authority[..colon].to_string(), authority[colon+1..].parse().unwrap())
        }
    } else {
        (authority.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

// ============ Amount ============

fn parse_cents(s: &str) -> i64 {
    let (neg, s2) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(dot) = s2.find('.') {
        (&s2[..dot], &s2[dot+1..])
    } else {
        (s2, "")
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 {
            (frac_part.as_bytes()[0] - b'0') as i64 * 10
        } else {
            frac_part.parse::<i64>().unwrap()
        };
        cents += f;
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(cents: i64) -> String {
    let neg = cents < 0;
    let abs = if neg { (cents as i128).wrapping_neg() as i64 } else { cents };
    let int_part = abs / 100;
    let frac_part = abs % 100;
    if neg {
        format!("-{}.{}", int_part, format!("{:02}", frac_part))
    } else {
        format!("{}.{}", int_part, format!("{:02}", frac_part))
    }
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json_str = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let client = parse_json(&client_json_str);
    let client_id = client.get("client_id").unwrap().as_str().unwrap().to_string();
    let client_secret = client.get("client_secret").unwrap().as_str().unwrap().to_string();
    let scope = client.get("scope").unwrap().as_str().unwrap().to_string();
    let page_size = client.get("page_size").unwrap();
    let page_size = if let Json::Num(n) = page_size { n as usize } else { panic!("page_size") };

    let (host, port, path_prefix) = parse_url(base_url);

    // Step 1: get token
    let token_body = format!("grant_type=client_credentials&scope={}", form_encode(&scope));
    let b64_creds = b64_encode(format!("{}:{}", form_encode(&client_id), form_encode(&client_secret)).as_bytes());
    let auth_hdr = format!("Basic {}", b64_creds);

    let get_token = || -> String {
        let r = http_request("POST", &host, port, &format!("{}/oauth/token", path_prefix),
            &[("Content-Type","application/x-www-form-urlencoded"), ("Authorization", auth_hdr.as_str())],
            Some(&token_body));
        if r.status != 200 {
            println!("ERROR {} {}", r.status, r.body);
            process::exit(0);
        }
        let j = parse_json(&r.body);
        j.get("access_token").unwrap().as_str().unwrap().to_string()
    };

    let mut access_token = get_token();
    let mut reauth_count: usize = 0;
    let mut got_200_with_token = false;

    let mut total_orders: usize = 0;
    let mut total_pages: usize = 0;
    let total_retries: usize = 0;
    let mut retries: usize = 0;

    // Aggregation
    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut status_counts: BTreeMap<String, usize> = BTreeMap::new();

    let mut cursor: Option<String> = None;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}/orders?limit={}&cursor={}", path_prefix, page_size, query_encode(c))
        } else {
            format!("{}/orders?limit={}", path_prefix, page_size)
        };

        let r = loop {
            let resp = http_request("GET", &host, port, &path,
                &[("Authorization", &format!("Bearer {}", access_token))], None);
            match resp.status {
                429 => {
                    retries += 1;
                    let ra = resp.headers.iter().find(|(k,_)| k=="retry-after")
                        .map(|(_,v)| v.trim().parse::<u64>().unwrap_or(1)).unwrap_or(1);
                    thread::sleep(Duration::from_secs(ra));
                    continue;
                }
                503 => {
                    retries += 1;
                    thread::sleep(Duration::from_millis(500));
                    continue;
                }
                401 => {
                    if !got_200_with_token {
                        println!("ERROR {} {}", resp.status, resp.body);
                        process::exit(0);
                    }
                    access_token = get_token();
                    reauth_count += 1;
                    got_200_with_token = false;
                    continue;
                }
                200 => { break resp; }
                _ => {
                    println!("ERROR {} {}", resp.status, resp.body);
                    process::exit(0);
                }
            }
        };

        got_200_with_token = true;
        total_pages += 1;

        let page = parse_json(&r.body);
        let data = page.get("data").unwrap().as_array().unwrap();
        total_orders += data.len();

        for order in data {
            let status = order.get("status").unwrap().as_str().unwrap().to_string();
            *status_counts.entry(status.clone()).or_insert(0) += 1;

            if status != "cancelled" {
                let customer = order.get("customer").unwrap();
                let name = customer.get("name").unwrap().as_str().unwrap().to_string();
                let currency = order.get("currency").unwrap().as_str().unwrap().to_string();
                let amount_str = order.get("amount").unwrap().as_str().unwrap();
                let cents = parse_cents(amount_str);
                *totals.entry((name, currency)).or_insert(0) += cents;
            }
        }

        let nc = page.get("next_cursor").unwrap();
        if nc.is_null() {
            break;
        }
        cursor = Some(nc.as_str().unwrap().to_string());
    }

    // Output
    let mut lines: Vec<(String, String, i64, String)> = Vec::new();
    for ((name, currency), cents) in &totals {
        lines.push((name.clone(), currency.clone(), *cents, format!("total {} {} {}", currency, fmt_cents(*cents), name)));
    }
    lines.sort_by(|a, b| {
        a.0.as_bytes().cmp(b.0.as_bytes())
            .then_with(|| a.1.as_bytes().cmp(b.1.as_bytes()))
    });
    for (_,_,_, line) in &lines {
        println!("{}", line);
    }

    for (status, count) in &status_counts {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", total_orders, total_pages, retries, reauth_count);
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process;
use std::thread;
use std::time::Duration;

// ============ JSON ============

#[derive(Debug, Clone)]
enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(ref pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(ref s) = self { Some(s) } else { None }
    }
    fn as_array(&self) -> Option<&[Json]> {
        if let Json::Array(ref a) = self { Some(a) } else { None }
    }
    fn is_null(&self) -> bool { matches!(self, Json::Null) }
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn peek(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self, c: u8) { assert!(self.p < self.s.len() && self.s[self.p] == c); self.p += 1; }
    fn parse(&mut self) -> Json {
        self.ws();
        match self.peek() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => Json::Str(self.string()),
            Some(b't') => { assert!(&self.s[self.p..self.p+4]==b"true"); self.p+=4; Json::Bool(true) }
            Some(b'f') => { assert!(&self.s[self.p..self.p+5]==b"false"); self.p+=5; Json::Bool(false) }
            Some(b'n') => { assert!(&self.s[self.p..self.p+4]==b"null"); self.p+=4; Json::Null }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Json {
        self.eat(b'{');
        let mut pairs = Vec::new();
        self.ws();
        if self.peek()==Some(b'}') { self.p+=1; return Json::Object(pairs); }
        loop {
            self.ws();
            let k = self.string();
            self.ws(); self.eat(b':'); self.ws();
            let v = self.parse();
            pairs.push((k,v));
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b'}');
        Json::Object(pairs)
    }
    fn arr(&mut self) -> Json {
        self.eat(b'[');
        let mut items = Vec::new();
        self.ws();
        if self.peek()==Some(b']') { self.p+=1; return Json::Array(items); }
        loop {
            self.ws();
            items.push(self.parse());
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b']');
        Json::Array(items)
    }
    fn string(&mut self) -> String {
        self.eat(b'"');
        let mut r = Vec::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let c2 = self.s[self.p]; self.p += 1;
                match c2 {
                    b'"' => r.push(b'"'),
                    b'\\' => r.push(b'\\'),
                    b'/' => r.push(b'/'),
                    b'b' => r.push(8),
                    b'f' => r.push(12),
                    b'n' => r.push(b'\n'),
                    b'r' => r.push(b'\r'),
                    b't' => r.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert!(self.s[self.p]==b'\\' && self.s[self.p+1]==b'u');
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000u32 + ((cp-0xD800)<<10) + (lo-0xDC00);
                            let ch = char::from_u32(code).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        } else {
                            let ch = char::from_u32(cp).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => panic!("bad esc"),
                }
            } else {
                r.push(c);
            }
        }
        String::from_utf8(r).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let h = &self.s[self.p..self.p+4]; self.p += 4;
        let mut v = 0u32;
        for &b in h { v <<= 4; v |= match b {
            b'0'..=b'9' => (b-b'0') as u32,
            b'a'..=b'f' => (b-b'a'+10) as u32,
            b'A'..=b'F' => (b-b'A'+10) as u32,
            _ => panic!("hex"),
        }; }
        v
    }
    fn num(&mut self) -> Json {
        let st = self.p;
        if self.peek()==Some(b'-') { self.p+=1; }
        while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; }
        if self.p<self.s.len() && self.s[self.p]==b'.' { self.p+=1; while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        if self.p<self.s.len() && (self.s[self.p]==b'e'||self.s[self.p]==b'E') { self.p+=1; if self.p<self.s.len() && (self.s[self.p]==b'+'||self.s[self.p]==b'-') { self.p+=1; } while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        Json::Num(std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap())
    }
}

fn parse_json(s: &str) -> Json { JP::new(s).parse() }

// ============ Base64 ============

fn b64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    let mut i = 0;
    while i + 2 < data.len() {
        let n = ((data[i] as u32) << 16) | ((data[i+1] as u32) << 8) | (data[i+2] as u32);
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        r.push(T[((n>>6)&63) as usize] as char);
        r.push(T[(n&63) as usize] as char);
        i += 3;
    }
    if i < data.len() {
        let n = ((data[i] as u32) << 16) | if i+1<data.len() { (data[i+1] as u32)<<8 } else { 0 };
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() {
            r.push(T[((n>>6)&63) as usize] as char);
            r.push('=');
        } else {
            r.push('=');
            r.push('=');
        }
    }
    r
}

// ============ Encoding ============

fn form_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'.' || b==b'_' || b==b'*' {
            r.push(b as char);
        } else if b == b' ' {
            r.push('+');
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn query_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'_' || b==b'.' || b==b'~' {
            r.push(b as char);
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

// ============ HTTP ============

struct Resp { status: u16, headers: Vec<(String,String)>, body: String }

fn parse_headers(raw: &[u8]) -> (u16, Vec<(String,String)>, usize) {
    let text = std::str::from_utf8(raw).unwrap();
    let mut lines = text.split("\r\n");
    let status_line = lines.next().unwrap();
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts[1].parse().unwrap();
    let mut headers = Vec::new();
    let mut body_start = status_line.len() + 2;
    for line in lines {
        if line.is_empty() { body_start += 2; break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_lowercase();
            let v = line[idx+1..].trim().to_string();
            headers.push((k, v));
        }
        body_start += line.len() + 2;
    }
    (status, headers, body_start)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        let nl = find_crlf(data, pos);
        let size_str = std::str::from_utf8(&data[pos..nl]).unwrap().trim();
        let size_str = if let Some(semi) = size_str.find(';') { &size_str[..semi] } else { size_str };
        let size = usize::from_str_radix(size_str.trim(), 16).unwrap();
        pos = nl + 2;
        if size == 0 { break; }
        result.extend_from_slice(&data[pos..pos+size]);
        pos += size + 2;
    }
    result
}

fn find_crlf(data: &[u8], from: usize) -> usize {
    let mut i = from;
    while i + 1 < data.len() {
        if data[i]==b'\r' && data[i+1]==b'\n' { return i; }
        i += 1;
    }
    data.len()
}

fn http_request(method: &str, host: &str, port: u16, path: &str, extra_headers: &[(&str,&str)], body: Option<&str>) -> Resp {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    stream.set_read_timeout(Some(Duration::from_secs(30))).unwrap();

    let host_hdr = if port == 80 { format!("{}", host) } else { format!("{}:{}", host, port) };
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host_hdr);
    for (k,v) in extra_headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("\r\n");
    if let Some(b) = body { req.push_str(b); }

    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();

    let (status, headers, body_start) = parse_headers(&raw);
    let body_bytes = &raw[body_start..];

    let body_vec = if headers.iter().any(|(k,v)| k=="transfer-encoding" && v.contains("chunked")) {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    Resp { status, headers, body: String::from_utf8(body_vec).unwrap() }
}

// ============ URL parsing ============

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { panic!("bad url") };
    let slash = rest.find('/').unwrap_or(rest.len());
    let authority = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "" };
    let (host, port) = if let Some(colon) = authority.rfind(':') {
        if authority[colon..].contains(']') {
            (authority.to_string(), 80u16)
        } else {
            (authority[..colon].to_string(), authority[colon+1..].parse().unwrap())
        }
    } else {
        (authority.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

// ============ Amount ============

fn parse_cents(s: &str) -> i64 {
    let (neg, s2) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(dot) = s2.find('.') {
        (&s2[..dot], &s2[dot+1..])
    } else {
        (s2, "")
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 {
            (frac_part.as_bytes()[0] - b'0') as i64 * 10
        } else {
            frac_part.parse::<i64>().unwrap()
        };
        cents += f;
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(cents: i64) -> String {
    let neg = cents < 0;
    let abs: i64 = if neg { (cents as i128).wrapping_neg() as i64 } else { cents };
    let int_part = abs / 100;
    let frac_part = abs % 100;
    if neg {
        format!("-{}.{}", int_part, format!("{:02}", frac_part))
    } else {
        format!("{}.{}", int_part, format!("{:02}", frac_part))
    }
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json_str = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let client = parse_json(&client_json_str);
    let client_id = client.get("client_id").unwrap().as_str().unwrap().to_string();
    let client_secret = client.get("client_secret").unwrap().as_str().unwrap().to_string();
    let scope = client.get("scope").unwrap().as_str().unwrap().to_string();
    let page_size = match client.get("page_size").unwrap() {
        Json::Num(n) => *n as usize,
        _ => panic!("page_size"),
    };

    let (host, port, path_prefix) = parse_url(base_url);

    // Step 1: get token
    let token_body = format!("grant_type=client_credentials&scope={}", form_encode(&scope));
    let b64_creds = b64_encode(format!("{}:{}", form_encode(&client_id), form_encode(&client_secret)).as_bytes());
    let auth_hdr = format!("Basic {}", b64_creds);

    let get_token = || -> String {
        let r = http_request("POST", &host, port, &format!("{}/oauth/token", path_prefix),
            &[("Content-Type","application/x-www-form-urlencoded"), ("Authorization", auth_hdr.as_str())],
            Some(&token_body));
        if r.status != 200 {
            println!("ERROR {} {}", r.status, r.body);
            process::exit(0);
        }
        let j = parse_json(&r.body);
        j.get("access_token").unwrap().as_str().unwrap().to_string()
    };

    let mut access_token = get_token();
    let mut reauth_count: usize = 0;
    let mut got_200_with_token = false;

    let mut total_orders: usize = 0;
    let mut total_pages: usize = 0;
    let mut retries: usize = 0;

    // Aggregation
    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut status_counts: BTreeMap<String, usize> = BTreeMap::new();

    let mut cursor: Option<String> = None;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}/orders?limit={}&cursor={}", path_prefix, page_size, query_encode(c))
        } else {
            format!("{}/orders?limit={}", path_prefix, page_size)
        };

        let r = loop {
            let resp = http_request("GET", &host, port, &path,
                &[("Authorization", &format!("Bearer {}", access_token))], None);
            match resp.status {
                429 => {
                    retries += 1;
                    let ra = resp.headers.iter().find(|(k,_)| k=="retry-after")
                        .map(|(_,v)| v.trim().parse::<u64>().unwrap_or(1)).unwrap_or(1);
                    thread::sleep(Duration::from_secs(ra));
                    continue;
                }
                503 => {
                    retries += 1;
                    thread::sleep(Duration::from_millis(500));
                    continue;
                }
                401 => {
                    if !got_200_with_token {
                        println!("ERROR {} {}", resp.status, resp.body);
                        process::exit(0);
                    }
                    access_token = get_token();
                    reauth_count += 1;
                    got_200_with_token = false;
                    continue;
                }
                200 => { break resp; }
                _ => {
                    println!("ERROR {} {}", resp.status, resp.body);
                    process::exit(0);
                }
            }
        };

        got_200_with_token = true;
        total_pages += 1;

        let page = parse_json(&r.body);
        let data = page.get("data").unwrap().as_array().unwrap();
        total_orders += data.len();

        for order in data {
            let status = order.get("status").unwrap().as_str().unwrap().to_string();
            *status_counts.entry(status.clone()).or_insert(0) += 1;

            if status != "cancelled" {
                let customer = order.get("customer").unwrap();
                let name = customer.get("name").unwrap().as_str().unwrap().to_string();
                let currency = order.get("currency").unwrap().as_str().unwrap().to_string();
                let amount_str = order.get("amount").unwrap().as_str().unwrap();
                let cents = parse_cents(amount_str);
                *totals.entry((name, currency)).or_insert(0) += cents;
            }
        }

        let nc = page.get("next_cursor").unwrap();
        if nc.is_null() {
            break;
        }
        cursor = Some(nc.as_str().unwrap().to_string());
    }

    // Output
    let mut lines: Vec<(String, String, i64, String)> = Vec::new();
    for ((name, currency), cents) in &totals {
        lines.push((name.clone(), currency.clone(), *cents, format!("total {} {} {}", currency, fmt_cents(*cents), name)));
    }
    lines.sort_by(|a, b| {
        a.0.as_bytes().cmp(b.0.as_bytes())
            .then_with(|| a.1.as_bytes().cmp(b.1.as_bytes()))
    });
    for (_,_,_, line) in &lines {
        println!("{}", line);
    }

    for (status, count) in &status_counts {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", total_orders, total_pages, retries, reauth_count);
}

import * as fs from 'fs';
import * as path from 'path';

interface ClassItem {
  type: 'char' | 'range' | 'escape';
  ch?: string;
  from?: string;
  to?: string;
  name?: string;
}

type AST =
  | { type: 'concat'; children: AST[] }
  | { type: 'alt'; branches: AST[] }
  | { type: 'group'; capture: number | null; child: AST }
  | { type: 'quant'; child: AST; min: number; max: number; greedy: boolean }
  | { type: 'char'; ch: string }
  | { type: 'dot' }
  | { type: 'class'; items: ClassItem[]; negated: boolean }
  | { type: 'anchor'; kind: 'bol' | 'eol' }
  | { type: 'empty' };

class Parser {
  private pattern: string;
  private pos: number;
  private groupCount: number;

  constructor(pattern: string) {
    this.pattern = pattern;
    this.pos = 0;
    this.groupCount = 0;
  }

  parse(): { ast: AST; numGroups: number } {
    const ast = this.parseAlt();
    return { ast, numGroups: this.groupCount };
  }

  private parseAlt(): AST {
    const branches: AST[] = [this.parseBranch()];
    while (this.pos < this.pattern.length && this.pattern[this.pos] === '|') {
      this.pos++;
      branches.push(this.parseBranch());
    }
    if (branches.length === 1) return branches[0];
    return { type: 'alt', branches };
  }

  private parseBranch(): AST {
    const pieces: AST[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== '|' && this.pattern[this.pos] !== ')') {
      pieces.push(this.parsePiece());
    }
    if (pieces.length === 0) return { type: 'empty' };
    if (pieces.length === 1) return pieces[0];
    return { type: 'concat', children: pieces };
  }

  private parsePiece(): AST {
    const atom = this.parseAtom();
    if (this.pos < this.pattern.length) {
      const c = this.pattern[this.pos];
      if (c === '*' || c === '+' || c === '?' || c === '{') {
        if (atom.type === 'anchor') return atom;
        return this.parseQuantifier(atom);
      }
    }
    return atom;
  }

  private parseQuantifier(atom: AST): AST {
    let min: number, max: number;
    const c = this.pattern[this.pos];
    if (c === '*') { this.pos++; min = 0; max = Infinity; }
    else if (c === '+') { this.pos++; min = 1; max = Infinity; }
    else if (c === '?') { this.pos++; min = 0; max = 1; }
    else {
      this.pos++;
      min = this.parseInt();
      if (this.pos < this.pattern.length && this.pattern[this.pos] === ',') {
        this.pos++;
        if (this.pos < this.pattern.length && this.pattern[this.pos] === '}') {
          max = Infinity;
        } else {
          max = this.parseInt();
        }
      } else {
        max = min;
      }
      this.pos++;
    }
    let greedy = true;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') {
      greedy = false;
      this.pos++;
    }
    return { type: 'quant', child: atom, min, max, greedy };
  }

  private parseInt(): number {
    let n = 0;
    while (this.pos < this.pattern.length && this.pattern[this.pos] >= '0' && this.pattern[this.pos] <= '9') {
      n = n * 10 + (this.pattern[this.pos].charCodeAt(0) - 48);
      this.pos++;
    }
    return n;
  }

  private parseAtom(): AST {
    const c = this.pattern[this.pos];
    if (c === '(') {
      this.pos++;
      let capture: number | null = null;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?' &&
          this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] === ':') {
        this.pos += 2;
      } else {
        this.groupCount++;
        capture = this.groupCount;
      }
      const child = this.parseAlt();
      if (this.pos < this.pattern.length && this.pattern[this.pos] === ')') this.pos++;
      return { type: 'group', capture, child };
    } else if (c === '.') { this.pos++; return { type: 'dot' }; }
    else if (c === '^') { this.pos++; return { type: 'anchor', kind: 'bol' }; }
    else if (c === '$') { this.pos++; return { type: 'anchor', kind: 'eol' }; }
    else if (c === '[') { return this.parseClass(); }
    else if (c === '\\') {
      this.pos++;
      const ec = this.pattern[this.pos]; this.pos++;
      if ('dDwWsS'.includes(ec)) {
        return { type: 'class', items: [{ type: 'escape', name: ec }], negated: false };
      }
      return { type: 'char', ch: ec };
    } else { this.pos++; return { type: 'char', ch: c }; }
  }

  private parseClass(): AST {
    this.pos++;
    let negated = false;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '^') {
      negated = true; this.pos++;
    }
    const items: ClassItem[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== ']') {
      let fromCh: string;
      if (this.pattern[this.pos] === '\\') {
        this.pos++;
        const ec = this.pattern[this.pos]; this.pos++;
        if ('dDwWsS'.includes(ec)) { items.push({ type: 'escape', name: ec }); continue; }
        fromCh = ec;
      } else {
        fromCh = this.pattern[this.pos]; this.pos++;
      }
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '-' &&
          this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] !== ']') {
        this.pos++;
        let toCh: string;
        if (this.pattern[this.pos] === '\\') { this.pos++; toCh = this.pattern[this.pos]; this.pos++; }
        else { toCh = this.pattern[this.pos]; this.pos++; }
        items.push({ type: 'range', from: fromCh, to: toCh });
      } else {
        items.push({ type: 'char', ch: fromCh });
      }
    }
    this.pos++;
    return { type: 'class', items, negated };
  }
}

type Instr =
  | { op: 'char'; ch: string; next: number }
  | { op: 'class'; items: ClassItem[]; negated: boolean; next: number }
  | { op: 'dot'; next: number }
  | { op: 'split'; a: number; b: number }
  | { op: 'jump'; target: number }
  | { op: 'save'; slot: number; next: number }
  | { op: 'assert'; kind: 'bol' | 'eol'; next: number }
  | { op: 'match' };

class NFABuilder {
  instrs: Instr[] = [];
  private subjectLen: number;

  constructor(subjectLen: number) { this.subjectLen = subjectLen; }

  private emit(instr: Instr): number {
    this.instrs.push(instr);
    return this.instrs.length - 1;
  }

  build(ast: AST): Instr[] {
    this.emit({ op: 'match' });
    this.compile(ast, 0);
    return this.instrs;
  }

  private compile(node: AST, next: number): number {
    switch (node.type) {
      case 'empty': return this.emit({ op: 'jump', target: next });
      case 'char': return this.emit({ op: 'char', ch: node.ch, next });
      case 'dot': return this.emit({ op: 'dot', next });
      case 'class': return this.emit({ op: 'class', items: node.items, negated: node.negated, next });
      case 'anchor': return this.emit({ op: 'assert', kind: node.kind, next });
      case 'concat': {
        if (node.children.length === 0) return this.emit({ op: 'jump', target: next });
        let nxt = next;
        for (let i = node.children.length - 1; i >= 0; i--) nxt = this.compile(node.children[i], nxt);
        return nxt;
      }
      case 'alt': {
        const starts: number[] = [];
        for (const branch of node.branches) starts.push(this.compile(branch, next));
        let result = starts[starts.length - 1];
        for (let i = starts.length - 2; i >= 0; i--) result = this.emit({ op: 'split', a: starts[i], b: result });
        return result;
      }
      case 'group': {
        let nxt = next;
        if (node.capture !== null) nxt = this.emit({ op: 'save', slot: 2 * (node.capture - 1) + 1, next: nxt });
        nxt = this.compile(node.child, nxt);
        if (node.capture !== null) nxt = this.emit({ op: 'save', slot: 2 * (node.capture - 1), next: nxt });
        return nxt;
      }
      case 'quant': return this.compileQuant(node, next);
    }
  }

  private compileQuant(node: AST & { type: 'quant' }, next: number): number {
    const { child, min, max, greedy } = node;
    if (max === Infinity) {
      const K = this.subjectLen + 1;
      let nxt = next;
      for (let i = 0; i < K; i++) nxt = this.compileOptional(child, nxt, greedy);
      for (let i = 0; i < min; i++) nxt = this.compile(child, nxt);
      return nxt;
    } else {
      let nxt = next;
      for (let i = 0; i < max - min; i++) nxt = this.compileOptional(child, nxt, greedy);
      for (let i = 0; i < min; i++) nxt = this.compile(child, nxt);
      return nxt;
    }
  }

  private compileOptional(child: AST, next: number, greedy: boolean): number {
    const splitIdx = this.emit({ op: 'split', a: -1, b: -1 });
    const bodyStart = this.compile(child, next);
    if (greedy) { (this.instrs[splitIdx] as any).a = bodyStart; (this.instrs[splitIdx] as any).b = next; }
    else { (this.instrs[splitIdx] as any).a = next; (this.instrs[splitIdx] as any).b = bodyStart; }
    return splitIdx;
  }
}

function matchClassItem(item: ClassItem, ch: string): boolean {
  switch (item.type) {
    case 'char': return ch === item.ch;
    case 'range': return ch >= item.from! && ch <= item.to!;
    case 'escape': {
      const isD = ch >= '0' && ch <= '9';
      const isW = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || isD || ch === '_';
      const isS = ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
      switch (item.name) {
        case 'd': return isD; case 'D': return !isD;
        case 'w': return isW; case 'W': return !isW;
        case 's': return isS; case 'S': return !isS;
      }
    }
  }
  return false;
}

function matchClass(items: ClassItem[], negated: boolean, ch: string): boolean {
  let any = false;
  for (const item of items) { if (matchClassItem(item, ch)) { any = true; break; } }
  return negated ? !any : any;
}

interface Thread { pc: number; saves: number[]; }

function addThread(
  pc: number, pos: number, list: Thread[], visited: Set<number>,
  saves: number[], instrs: Instr[], n: number
): void {
  const key = pc * (n + 1) + pos;
  if (visited.has(key)) return;
  visited.add(key);
  const instr = instrs[pc];
  switch (instr.op) {
    case 'split':
      addThread(instr.a, pos, list, visited, saves, instrs, n);
      addThread(instr.b, pos, list, visited, saves, instrs, n);
      break;
    case 'jump':
      addThread(instr.target, pos, list, visited, saves, instrs, n);
      break;
    case 'save': {
      const ns = [...saves]; ns[instr.slot] = pos;
      addThread(instr.next, pos, list, visited, ns, instrs, n);
      break;
    }
    case 'assert':
      if ((instr.kind === 'bol' && pos === 0) || (instr.kind === 'eol' && pos === n))
        addThread(instr.next, pos, list, visited, saves, instrs, n);
      break;
    default:
      list.push({ pc, saves });
      break;
  }
}

function pikeVM(instrs: Instr[], subject: string, numSlots: number):
  { start: number; end: number; captures: (number | null)[] } | null {
  const n = subject.length;
  for (let startPos = 0; startPos <= n; startPos++) {
    const threadList: Thread[] = [];
    addThread(0, startPos, threadList, new Set(), new Array(numSlots).fill(-1), instrs, n);
    for (let pos = startPos; pos <= n; pos++) {
      for (const t of threadList) {
        if (instrs[t.pc].op === 'match') {
          const captures: (number | null)[] = [];
          for (let g = 0; g < numSlots; g += 2) {
            if (t.saves[g] >= 0 && t.saves[g + 1] >= 0) captures.push(t.saves[g], t.saves[g + 1]);
            else captures.push(null, null);
          }
          return { start: startPos, end: pos, captures };
        }
      }
      if (pos === n) break;
      const nextList: Thread[] = [];
      const nextVisited = new Set<number>();
      for (const t of threadList) {
        const instr = instrs[t.pc];
        let npc = -1;
        if (instr.op === 'char') { if (subject[pos] === instr.ch) npc = instr.next; }
        else if (instr.op === 'dot') { npc = instr.next; }
        else if (instr.op === 'class') { if (matchClass(instr.items, instr.negated, subject[pos])) npc = instr.next; }
        if (npc >= 0) addThread(npc, pos + 1, nextList, nextVisited, t.saves, instrs, n);
      }
      if (nextList.length === 0) break;
      threadList.length = 0;
      for (const t of nextList) threadList.push(t);
    }
  }
  return null;
}

function main(): void {
  const dir = process.argv[2];
  const content = fs.readFileSync(path.join(dir, 'cases.txt'), 'utf-8');
  const lines = content.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  const results: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const tabIdx = line.indexOf('\t');
    const pattern = tabIdx >= 0 ? line.substring(0, tabIdx) : line;
    const subject = tabIdx >= 0 ? line.substring(tabIdx + 1) : '';

    const parser = new Parser(pattern);
    const { ast, numGroups } = parser.parse();

    const builder = new NFABuilder(subject.length);
    const instrs = builder.build(ast);

    const numSlots = 2 * numGroups;
    const result = pikeVM(instrs, subject, numSlots);

    const ln = i + 1;
    if (result === null) {
      results.push(`${ln}: no match`);
    } else {
      let out = `${ln}: ${result.start}-${result.end}`;
      for (let g = 0; g < numGroups; g++) {
        const s = result.captures[g * 2];
        const e = result.captures[g * 2 + 1];
        if (s === null || e === null) out += ' -';
        else out += ` ${s}-${e}`;
      }
      results.push(out);
    }
  }
  console.log(results.join('\n'));
}

main();

import * as fs from 'fs';
import * as path from 'path';

interface ClassItem {
  type: 'char' | 'range' | 'escape';
  ch?: string;
  from?: string;
  to?: string;
  name?: string;
}

type AST =
  | { type: 'concat'; children: AST[] }
  | { type: 'alt'; branches: AST[] }
  | { type: 'group'; capture: number | null; child: AST }
  | { type: 'quant'; child: AST; min: number; max: number; greedy: boolean }
  | { type: 'char'; ch: string }
  | { type: 'dot' }
  | { type: 'class'; items: ClassItem[]; negated: boolean }
  | { type: 'anchor'; kind: 'bol' | 'eol' }
  | { type: 'empty' };

class Parser {
  private pattern: string;
  private pos: number;
  private groupCount: number;

  constructor(pattern: string) {
    this.pattern = pattern;
    this.pos = 0;
    this.groupCount = 0;
  }

  parse(): { ast: AST; numGroups: number } {
    const ast = this.parseAlt();
    return { ast, numGroups: this.groupCount };
  }

  private parseAlt(): AST {
    const branches: AST[] = [this.parseBranch()];
    while (this.pos < this.pattern.length && this.pattern[this.pos] === '|') {
      this.pos++;
      branches.push(this.parseBranch());
    }
    if (branches.length === 1) return branches[0];
    return { type: 'alt', branches };
  }

  private parseBranch(): AST {
    const pieces: AST[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== '|' && this.pattern[this.pos] !== ')') {
      pieces.push(this.parsePiece());
    }
    if (pieces.length === 0) return { type: 'empty' };
    if (pieces.length === 1) return pieces[0];
    return { type: 'concat', children: pieces };
  }

  private parsePiece(): AST {
    const atom = this.parseAtom();
    if (this.pos < this.pattern.length) {
      const c = this.pattern[this.pos];
      if (c === '*' || c === '+' || c === '?' || c === '{') {
        if (atom.type === 'anchor') return atom;
        return this.parseQuantifier(atom);
      }
    }
    return atom;
  }

  private parseQuantifier(atom: AST): AST {
    let min: number, max: number;
    const c = this.pattern[this.pos];
    if (c === '*') { this.pos++; min = 0; max = Infinity; }
    else if (c === '+') { this.pos++; min = 1; max = Infinity; }
    else if (c === '?') { this.pos++; min = 0; max = 1; }
    else {
      this.pos++;
      min = this.parseInt();
      if (this.pos < this.pattern.length && this.pattern[this.pos] === ',') {
        this.pos++;
        if (this.pos < this.pattern.length && this.pattern[this.pos] === '}') {
          max = Infinity;
        } else {
          max = this.parseInt();
        }
      } else {
        max = min;
      }
      this.pos++; // skip '}'
    }
    let greedy = true;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '?') {
      greedy = false;
      this.pos++;
    }
    return { type: 'quant', child: atom, min, max, greedy };
  }

  private parseInt(): number {
    let n = 0;
    while (this.pos < this.pattern.length && this.pattern[this.pos] >= '0' && this.pattern[this.pos] <= '9') {
      n = n * 10 + (this.pattern[this.pos].charCodeAt(0) - 48);
      this.pos++;
    }
    return n;
  }

  private parseAtom(): AST {
    const c = this.pattern[this.pos];
    if (c === '(') {
      this.pos++;
      let capture: number | null = null;
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '?' &&
          this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] === ':') {
        this.pos += 2;
      } else {
        this.groupCount++;
        capture = this.groupCount;
      }
      const child = this.parseAlt();
      if (this.pos < this.pattern.length && this.pattern[this.pos] === ')') this.pos++;
      return { type: 'group', capture, child };
    } else if (c === '.') { this.pos++; return { type: 'dot' }; }
    else if (c === '^') { this.pos++; return { type: 'anchor', kind: 'bol' }; }
    else if (c === '$') { this.pos++; return { type: 'anchor', kind: 'eol' }; }
    else if (c === '[') { return this.parseClass(); }
    else if (c === '\\') {
      this.pos++;
      const ec = this.pattern[this.pos]; this.pos++;
      if ('dDwWsS'.includes(ec)) {
        return { type: 'class', items: [{ type: 'escape', name: ec }], negated: false };
      }
      return { type: 'char', ch: ec };
    } else { this.pos++; return { type: 'char', ch: c }; }
  }

  private parseClass(): AST {
    this.pos++; // skip '['
    let negated = false;
    if (this.pos < this.pattern.length && this.pattern[this.pos] === '^') {
      negated = true; this.pos++;
    }
    const items: ClassItem[] = [];
    while (this.pos < this.pattern.length && this.pattern[this.pos] !== ']') {
      let fromCh: string;
      if (this.pattern[this.pos] === '\\') {
        this.pos++;
        const ec = this.pattern[this.pos]; this.pos++;
        if ('dDwWsS'.includes(ec)) { items.push({ type: 'escape', name: ec }); continue; }
        fromCh = ec;
      } else {
        fromCh = this.pattern[this.pos]; this.pos++;
      }
      if (this.pos < this.pattern.length && this.pattern[this.pos] === '-' &&
          this.pos + 1 < this.pattern.length && this.pattern[this.pos + 1] !== ']') {
        this.pos++; // skip '-'
        let toCh: string;
        if (this.pattern[this.pos] === '\\') { this.pos++; toCh = this.pattern[this.pos]; this.pos++; }
        else { toCh = this.pattern[this.pos]; this.pos++; }
        items.push({ type: 'range', from: fromCh, to: toCh });
      } else {
        items.push({ type: 'char', ch: fromCh });
      }
    }
    this.pos++; // skip ']'
    return { type: 'class', items, negated };
  }
}

type Instr =
  | { op: 'char'; ch: string; next: number }
  | { op: 'class'; items: ClassItem[]; negated: boolean; next: number }
  | { op: 'dot'; next: number }
  | { op: 'split'; a: number; b: number }
  | { op: 'jump'; target: number }
  | { op: 'save'; slot: number; next: number }
  | { op: 'assert'; kind: 'bol' | 'eol'; next: number }
  | { op: 'match' };

class NFABuilder {
  instrs: Instr[] = [];
  private subjectLen: number;

  constructor(subjectLen: number) { this.subjectLen = subjectLen; }

  private emit(instr: Instr): number {
    this.instrs.push(instr);
    return this.instrs.length - 1;
  }

  build(ast: AST): { instrs: Instr[]; start: number } {
    const matchIdx = this.emit({ op: 'match' });
    const start = this.compile(ast, matchIdx);
    return { instrs: this.instrs, start };
  }

  private compile(node: AST, next: number): number {
    switch (node.type) {
      case 'empty': return this.emit({ op: 'jump', target: next });
      case 'char': return this.emit({ op: 'char', ch: node.ch, next });
      case 'dot': return this.emit({ op: 'dot', next });
      case 'class': return this.emit({ op: 'class', items: node.items, negated: node.negated, next });
      case 'anchor': return this.emit({ op: 'assert', kind: node.kind, next });
      case 'concat': {
        if (node.children.length === 0) return this.emit({ op: 'jump', target: next });
        let nxt = next;
        for (let i = node.children.length - 1; i >= 0; i--) nxt = this.compile(node.children[i], nxt);
        return nxt;
      }
      case 'alt': {
        const starts: number[] = [];
        for (const branch of node.branches) starts.push(this.compile(branch, next));
        let result = starts[starts.length - 1];
        for (let i = starts.length - 2; i >= 0; i--) result = this.emit({ op: 'split', a: starts[i], b: result });
        return result;
      }
      case 'group': {
        let nxt = next;
        if (node.capture !== null) nxt = this.emit({ op: 'save', slot: 2 * (node.capture - 1) + 1, next: nxt });
        nxt = this.compile(node.child, nxt);
        if (node.capture !== null) nxt = this.emit({ op: 'save', slot: 2 * (node.capture - 1), next: nxt });
        return nxt;
      }
      case 'quant': return this.compileQuant(node, next);
    }
  }

  private compileQuant(node: AST & { type: 'quant' }, next: number): number {
    const { child, min, max, greedy } = node;
    if (max === Infinity) {
      const K = this.subjectLen + 1;
      let nxt = next;
      for (let i = 0; i < K; i++) nxt = this.compileOptional(child, nxt, greedy);
      for (let i = 0; i < min; i++) nxt = this.compile(child, nxt);
      return nxt;
    } else {
      let nxt = next;
      for (let i = 0; i < max - min; i++) nxt = this.compileOptional(child, nxt, greedy);
      for (let i = 0; i < min; i++) nxt = this.compile(child, nxt);
      return nxt;
    }
  }

  private compileOptional(child: AST, next: number, greedy: boolean): number {
    const splitIdx = this.emit({ op: 'split', a: -1, b: -1 });
    const bodyStart = this.compile(child, next);
    if (greedy) { (this.instrs[splitIdx] as any).a = bodyStart; (this.instrs[splitIdx] as any).b = next; }
    else { (this.instrs[splitIdx] as any).a = next; (this.instrs[splitIdx] as any).b = bodyStart; }
    return splitIdx;
  }
}

function matchClassItem(item: ClassItem, ch: string): boolean {
  switch (item.type) {
    case 'char': return ch === item.ch;
    case 'range': return ch >= item.from! && ch <= item.to!;
    case 'escape': {
      const isD = ch >= '0' && ch <= '9';
      const isW = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || isD || ch === '_';
      const isS = ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
      switch (item.name) {
        case 'd': return isD; case 'D': return !isD;
        case 'w': return isW; case 'W': return !isW;
        case 's': return isS; case 'S': return !isS;
      }
    }
  }
  return false;
}

function matchClass(items: ClassItem[], negated: boolean, ch: string): boolean {
  let any = false;
  for (const item of items) { if (matchClassItem(item, ch)) { any = true; break; } }
  return negated ? !any : any;
}

interface Thread { pc: number; saves: number[]; }

function addThread(
  pc: number, pos: number, list: Thread[], visited: Set<number>,
  saves: number[], instrs: Instr[], n: number
): void {
  const key = pc * (n + 1) + pos;
  if (visited.has(key)) return;
  visited.add(key);
  const instr = instrs[pc];
  switch (instr.op) {
    case 'split':
      addThread(instr.a, pos, list, visited, saves, instrs, n);
      addThread(instr.b, pos, list, visited, saves, instrs, n);
      break;
    case 'jump':
      addThread(instr.target, pos, list, visited, saves, instrs, n);
      break;
    case 'save': {
      const ns = [...saves]; ns[instr.slot] = pos;
      addThread(instr.next, pos, list, visited, ns, instrs, n);
      break;
    }
    case 'assert':
      if ((instr.kind === 'bol' && pos === 0) || (instr.kind === 'eol' && pos === n))
        addThread(instr.next, pos, list, visited, saves, instrs, n);
      break;
    default:
      list.push({ pc, saves });
      break;
  }
}

function pikeVM(instrs: Instr[], start: number, subject: string, numSlots: number):
  { start: number; end: number; captures: (number | null)[] } | null {
  const n = subject.length;
  for (let startPos = 0; startPos <= n; startPos++) {
    const threadList: Thread[] = [];
    addThread(start, startPos, threadList, new Set(), new Array(numSlots).fill(-1), instrs, n);
    for (let pos = startPos; pos <= n; pos++) {
      for (const t of threadList) {
        if (instrs[t.pc].op === 'match') {
          const captures: (number | null)[] = [];
          for (let g = 0; g < numSlots; g += 2) {
            if (t.saves[g] >= 0 && t.saves[g + 1] >= 0) captures.push(t.saves[g], t.saves[g + 1]);
            else captures.push(null, null);
          }
          return { start: startPos, end: pos, captures };
        }
      }
      if (pos === n) break;
      const nextList: Thread[] = [];
      const nextVisited = new Set<number>();
      for (const t of threadList) {
        const instr = instrs[t.pc];
        let npc = -1;
        if (instr.op === 'char') { if (subject[pos] === instr.ch) npc = instr.next; }
        else if (instr.op === 'dot') { npc = instr.next; }
        else if (instr.op === 'class') { if (matchClass(instr.items, instr.negated, subject[pos])) npc = instr.next; }
        if (npc >= 0) addThread(npc, pos + 1, nextList, nextVisited, t.saves, instrs, n);
      }
      if (nextList.length === 0) break;
      threadList.length = 0;
      for (const t of nextList) threadList.push(t);
    }
  }
  return null;
}

function main(): void {
  const dir = process.argv[2];
  const content = fs.readFileSync(path.join(dir, 'cases.txt'), 'utf-8');
  const lines = content.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  const results: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const tabIdx = line.indexOf('\t');
    const pattern = tabIdx >= 0 ? line.substring(0, tabIdx) : line;
    const subject = tabIdx >= 0 ? line.substring(tabIdx + 1) : '';

    const parser = new Parser(pattern);
    const { ast, numGroups } = parser.parse();

    const builder = new NFABuilder(subject.length);
    const { instrs, start } = builder.build(ast);

    const numSlots = 2 * numGroups;
    const result = pikeVM(instrs, start, subject, numSlots);

    const ln = i + 1;
    if (result === null) {
      results.push(`${ln}: no match`);
    } else {
      let out = `${ln}: ${result.start}-${result.end}`;
      for (let g = 0; g < numGroups; g++) {
        const s = result.captures[g * 2];
        const e = result.captures[g * 2 + 1];
        if (s === null || e === null) out += ' -';
        else out += ` ${s}-${e}`;
      }
      results.push(out);
    }
  }
  console.log(results.join('\n'));
}

