/* ============ Dynamic Buffer ============ */
typedef struct {
    char *data;
    size_t len;
    size_t cap;
} Buf;

static void buf_init(Buf *b) { b->data = NULL; b->len = 0; b->cap = 0; }
static void buf_ensure(Buf *b, size_t extra) {
    if (b->len + extra > b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 256;
        while (nc < b->len + extra) nc *= 2;
        b->data = realloc(b->data, nc);
        b->cap = nc;
    }
}
static void buf_append(Buf *b, const char *s, size_t n) {
    buf_ensure(b, n);
    memcpy(b->data + b->len, s, n);
    b->len += n;
    b->data[b->len] = '\0';
}
static void buf_appendc(Buf *b, char c) { buf_append(b, &c, 1); }
static void buf_appendstr(Buf *b, const char *s) { buf_append(b, s, strlen(s)); }

/* ============ Portable helpers ============ */
static char *my_strndup(const char *s, size_t n) {
    size_t len = 0;
    while (len < n && s[len]) len++;
    char *r = (char*)malloc(len + 1);
    if (!r) return NULL;
    memcpy(r, s, len);
    r[len] = '\0';
    return r;
}
static int my_strncasecmp(const char *a, const char *b, size_t n) {
    for (size_t i = 0; i < n; i++) {
        int d = tolower((unsigned char)a[i]) - tolower((unsigned char)b[i]);
        if (d) return d;
        if (!a[i]) return 0;
    }
    return 0;
}
static char *my_strcasestr(const char *hay, const char *needle) {
    size_t nlen = strlen(needle);
    if (nlen == 0) return (char*)hay;
    for (const char *p = hay; *p; p++) {
        size_t i;
        for (i = 0; i < nlen; i++) {
            if (tolower((unsigned char)p[i]) != tolower((unsigned char)needle[i])) break;
        }
        if (i == nlen) return (char*)p;
    }
    return NULL;
}
static void my_sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

/* ============ Base64 ============ */
static const char b64chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void base64_encode(const unsigned char *in, size_t inlen, Buf *out) {
    size_t i = 0;
    while (i < inlen) {
        uint32_t v = (uint32_t)in[i] << 16;
        if (i + 1 < inlen) v |= (uint32_t)in[i+1] << 8;
        if (i + 2 < inlen) v |= (uint32_t)in[i+2];
        buf_appendc(out, b64chars[(v >> 18) & 0x3F]);
        buf_appendc(out, b64chars[(v >> 12) & 0x3F]);
        buf_appendc(out, i + 1 < inlen ? b64chars[(v >> 6) & 0x3F] : '=');
        buf_appendc(out, i + 2 < inlen ? b64chars[v & 0x3F] : '=');
        i += 3;
    }
}

/* ============ Form-urlencoded (OAuth style) ============ */
static void form_encode(const char *s, Buf *out) {
    for (const unsigned char *p = (const unsigned char*)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '*') {
            buf_appendc(out, c);
        } else if (c == ' ') {
            buf_appendc(out, '+');
        } else {
            buf_appendc(out, '%');
            buf_appendc(out, "0123456789ABCDEF"[c >> 4]);
            buf_appendc(out, "0123456789ABCDEF"[c & 0xF]);
        }
    }
}

/* ============ Percent-encode for query (RFC 3986 unreserved) ============ */
static void pct_encode(const char *s, Buf *out) {
    for (const unsigned char *p = (const unsigned char*)s; *p; p++) {
        unsigned char c = *p;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '~') {
            buf_appendc(out, c);
        } else {
            buf_appendc(out, '%');
            buf_appendc(out, "0123456789ABCDEF"[c >> 4]);
            buf_appendc(out, "0123456789ABCDEF"[c & 0xF]);
        }
    }
}

/* ============ URL Parsing ============ */
typedef struct {
    char host[256];
    int port;
    char path[1024];
} Url;

static void parse_url(const char *url, Url *u) {
    memset(u, 0, sizeof(*u));
    u->port = 80;
    const char *p = url;
    if (strncmp(p, "http://", 7) == 0) p += 7;
    const char *slash = strchr(p, '/');
    const char *hostend = slash ? slash : p + strlen(p);
    const char *colon = (const char*)memchr(p, ':', (size_t)(hostend - p));
    if (colon) {
        size_t hl = (size_t)(colon - p);
        if (hl >= sizeof(u->host)) hl = sizeof(u->host) - 1;
        memcpy(u->host, p, hl);
        u->port = atoi(colon + 1);
    } else {
        size_t hl = (size_t)(hostend - p);
        if (hl >= sizeof(u->host)) hl = sizeof(u->host) - 1;
        memcpy(u->host, p, hl);
    }
    if (slash) {
        strncpy(u->path, slash, sizeof(u->path) - 1);
    } else {
        strcpy(u->path, "/");
    }
}

/* ============ HTTP Client ============ */
typedef struct {
    int status;
    char *body;
    size_t body_len;
    char retry_after[64];
} HttpResponse;

static int tcp_connect(const Url *u) {
    char portstr[16];
    snprintf(portstr, sizeof(portstr), "%d", u->port);
    struct addrinfo hints; memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    struct addrinfo *res = NULL;
    if (getaddrinfo(u->host, portstr, &hints, &res) != 0) return -1;
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) { freeaddrinfo(res); return -1; }
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) { close(fd); freeaddrinfo(res); return -1; }
    freeaddrinfo(res);
    return fd;
}

static void send_all(int fd, const char *buf, size_t len) {
    size_t sent = 0;
    while (sent < len) {
        ssize_t n = send(fd, buf + sent, len - sent, 0);
        if (n <= 0) { if (errno == EINTR) continue; break; }
        sent += (size_t)n;
    }
}

static int recv_all(int fd, Buf *raw) {
    char tmp[65536];
    for (;;) {
        ssize_t n = recv(fd, tmp, sizeof(tmp), 0);
        if (n < 0) { if (errno == EINTR) continue; return -1; }
        if (n == 0) break;
        buf_append(raw, tmp, (size_t)n);
    }
    return 0;
}

static int parse_chunked_body(const char *data, size_t len, Buf *out) {
    size_t pos = 0;
    while (pos < len) {
        /* skip any leading whitespace/newlines between chunks */
        while (pos < len && (data[pos] == '\r' || data[pos] == '\n' || data[pos] == ' ' || data[pos] == '\t'))
            pos++;
        if (pos >= len) break;
        /* read hex size */
        size_t sz = 0;
        int got_digit = 0;
        while (pos < len && isxdigit((unsigned char)data[pos])) {
            char c = data[pos];
            sz = sz * 16 + (isdigit((unsigned char)c) ? (size_t)(c - '0') : (size_t)(tolower(c) - 'a' + 10));
            pos++;
            got_digit = 1;
        }
        if (!got_digit) break;
        /* skip optional chunk extensions */
        while (pos < len && data[pos] != '\r' && data[pos] != '\n') pos++;
        /* skip \r\n */
        if (pos < len && data[pos] == '\r') pos++;
        if (pos < len && data[pos] == '\n') pos++;
        if (sz == 0) break;
        if (pos + sz <= len) {
            buf_append(out, data + pos, sz);
            pos += sz;
        } else {
            buf_append(out, data + pos, len - pos);
            pos = len;
        }
        /* skip trailing \r\n after chunk data */
        if (pos < len && data[pos] == '\r') pos++;
        if (pos < len && data[pos] == '\n') pos++;
    }
    return 0;
}

static void http_request(const Url *base, const char *method, const char *path,
                         const char *content_type, const char *body,
                         const char *auth_header, HttpResponse *resp) {
    memset(resp, 0, sizeof(*resp));
    resp->retry_after[0] = '\0';
    Url u = *base;
    char fullpath[2048];
    snprintf(fullpath, sizeof(fullpath), "%s%s", base->path, path);

    int fd = tcp_connect(&u);
    if (fd < 0) { resp->status = -1; return; }

    Buf req; buf_init(&req);
    buf_appendstr(&req, method);
    buf_appendc(&req, ' ');
    buf_appendstr(&req, fullpath);
    buf_appendstr(&req, " HTTP/1.1\r\n");
    buf_appendstr(&req, "Host: ");
    buf_appendstr(&req, u.host);
    if (u.port != 80) {
        buf_appendc(&req, ':');
        char ps[16]; snprintf(ps, sizeof(ps), "%d", u->port);
        buf_appendstr(&req, ps);
    }
    buf_appendstr(&req, "\r\n");
    buf_appendstr(&req, "Connection: close\r\n");
    if (content_type) {
        buf_appendstr(&req, "Content-Type: ");
        buf_appendstr(&req, content_type);
        buf_appendstr(&req, "\r\n");
    }
    if (body) {
        char cl[32]; snprintf(cl, sizeof(cl), "%zu", strlen(body));
        buf_appendstr(&req, "Content-Length: ");
        buf_appendstr(&req, cl);
        buf_appendstr(&req, "\r\n");
    }
    if (auth_header) {
        buf_appendstr(&req, "Authorization: ");
        buf_appendstr(&req, auth_header);
        buf_appendstr(&req, "\r\n");
    }
    buf_appendstr(&req, "\r\n");
    if (body) buf_appendstr(&req, body);

    send_all(fd, req.data, req.len);
    free(req.data);

    Buf raw; buf_init(&raw);
    recv_all(fd, &raw);
    close(fd);

    if (raw.len == 0) { resp->status = -1; free(raw.data); return; }

    /* parse status line WITHOUT modifying raw.data */
    {
        const char *sp = (const char*)memchr(raw.data, ' ', raw.len);
        if (!sp) { resp->status = -1; free(raw.data); return; }
        resp->status = atoi(sp + 1);
    }

    /* find end of headers (\r\n\r\n) */
    char *hdr_end = NULL;
    for (size_t i = 0; i + 3 < raw.len; i++) {
        if (raw.data[i] == '\r' && raw.data[i+1] == '\n' &&
            raw.data[i+2] == '\r' && raw.data[i+3] == '\n') {
            hdr_end = raw.data + i + 4;
            break;
        }
    }
    if (!hdr_end) { resp->status = -1; free(raw.data); return; }

    /* parse headers - copy to separate buffer to avoid modifying raw.data */
    size_t hdr_len = (size_t)(hdr_end - raw.data) - 4;
    char *hdrs = my_strndup(raw.data, hdr_len);
    size_t content_len = 0;
    int is_chunked = 0;
    if (hdrs) {
        char *line = strtok(hdrs, "\r\n");
        while (line) {
            if (my_strncasecmp(line, "Content-Length:", 15) == 0) {
                content_len = (size_t)atoi(line + 15);
            } else if (my_strncasecmp(line, "Transfer-Encoding:", 18) == 0) {
                if (my_strcasestr(line + 18, "chunked")) is_chunked = 1;
            } else if (my_strncasecmp(line, "Retry-After:", 12) == 0) {
                char *v = line + 12;
                while (*v == ' ') v++;
                strncpy(resp->retry_after, v, sizeof(resp->retry_after) - 1);
                resp->retry_after[sizeof(resp->retry_after) - 1] = '\0';
            }
            line = strtok(NULL, "\r\n");
        }
        free(hdrs);
    }

    /* extract body */
    size_t remaining = raw.len - (size_t)(hdr_end - raw.data);
    if (is_chunked) {
        Buf b; buf_init(&b);
        parse_chunked_body(hdr_end, remaining, &b);
        resp->body = b.data;
        resp->body_len = b.len;
    } else if (content_len > 0) {
        resp->body = (char*)malloc(content_len + 1);
        size_t copy = content_len < remaining ? content_len : remaining;
        memcpy(resp->body, hdr_end, copy);
        resp->body[copy] = '\0';
        resp->body_len = copy;
    } else {
        resp->body = (char*)malloc(remaining + 1);
        memcpy(resp->body, hdr_end, remaining);
        resp->body[remaining] = '\0';
        resp->body_len = remaining;
    }
    free(raw.data);
}

/* ============ JSON Parser ============ */
typedef enum { JV_NULL, JV_BOOL, JV_NUM, JV_STR, JV_ARR, JV_OBJ } JType;
typedef struct JValue JValue;
struct JValue {
    JType type;
    union {
        int bval;
        long long nval;
        char *sval;
        struct { JValue **items; size_t count; size_t cap; } arr;
        struct { char **keys; JValue **vals; size_t count; size_t cap; } obj;
    };
};

typedef struct { const char *p; const char *end; } JCtx;

static JValue *jval_new(JType t) {
    JValue *v = (JValue*)calloc(1, sizeof(JValue));
    v->type = t;
    return v;
}

static void jskip_ws(JCtx *c) {
    while (c->p < c->end && (*c->p == ' ' || *c->p == '\t' || *c->p == '\n' || *c->p == '\r'))
        c->p++;
}

static JValue *jparse(JCtx *c);

static char *jparse_string(JCtx *c) {
    if (*c->p != '"') return NULL;
    c->p++;
    Buf b; buf_init(&b);
    while (c->p < c->end && *c->p != '"') {
        if (*c->p == '\\') {
            c->p++;
            if (c->p >= c->end) break;
            switch (*c->p) {
                case '"': buf_appendc(&b, '"'); c->p++; break;
                case '\\': buf_appendc(&b, '\\'); c->p++; break;
                case '/': buf_appendc(&b, '/'); c->p++; break;
                case 'b': buf_appendc(&b, '\b'); c->p++; break;
                case 'f': buf_appendc(&b, '\f'); c->p++; break;
                case 'n': buf_appendc(&b, '\n'); c->p++; break;
                case 'r': buf_appendc(&b, '\r'); c->p++; break;
                case 't': buf_appendc(&b, '\t'); c->p++; break;
                case 'u': {
                    c->p++;
                    if (c->p + 4 > c->end) break;
                    unsigned cp = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = c->p[i];
                        cp = cp * 16 + (unsigned)(isdigit((unsigned char)h) ? h - '0' : (tolower(h) - 'a' + 10));
                    }
                    c->p += 4;
                    if (cp >= 0xD800 && cp <= 0xDBFF && c->p + 6 <= c->end &&
                        c->p[0] == '\\' && c->p[1] == 'u') {
                        c->p += 2;
                        unsigned lo = 0;
                        for (int i = 0; i < 4; i++) {
                            char h = c->p[i];
                            lo = lo * 16 + (unsigned)(isdigit((unsigned char)h) ? h - '0' : (tolower(h) - 'a' + 10));
                        }
                        c->p += 4;
                        if (lo >= 0xDC00 && lo <= 0xDFFF) {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        }
                    }
                    if (cp < 0x80) {
                        buf_appendc(&b, (char)cp);
                    } else if (cp < 0x800) {
                        buf_appendc(&b, (char)(0xC0 | (cp >> 6)));
                        buf_appendc(&b, (char)(0x80 | (cp & 0x3F)));
                    } else if (cp < 0x10000) {
                        buf_appendc(&b, (char)(0xE0 | (cp >> 12)));
                        buf_appendc(&b, (char)(0x80 | ((cp >> 6) & 0x3F)));
                        buf_appendc(&b, (char)(0x80 | (cp & 0x3F)));
                    } else {
                        buf_appendc(&b, (char)(0xF0 | (cp >> 18)));
                        buf_appendc(&b, (char)(0x80 | ((cp >> 12) & 0x3F)));
                        buf_appendc(&b, (char)(0x80 | ((cp >> 6) & 0x3F)));
                        buf_appendc(&b, (char)(0x80 | (cp & 0x3F)));
                    }
                    break;
                }
                default: buf_appendc(&b, *c->p); c->p++; break;
            }
        } else {
            buf_appendc(&b, *c->p);
            c->p++;
        }
    }
    if (c->p < c->end && *c->p == '"') c->p++;
    buf_appendc(&b, '\0');
    return b.data;
}

static JValue *jparse(JCtx *c) {
    jskip_ws(c);
    if (c->p >= c->end) return NULL;
    char ch = *c->p;
    if (ch == '"') {
        JValue *v = jval_new(JV_STR);
        v->sval = jparse_string(c);
        return v;
    } else if (ch == '{') {
        c->p++;
        JValue *v = jval_new(JV_OBJ);
        jskip_ws(c);
        if (c->p < c->end && *c->p == '}') { c->p++; return v; }
        for (;;) {
            jskip_ws(c);
            char *key = jparse_string(c);
            jskip_ws(c);
            if (c->p < c->end && *c->p == ':') c->p++;
            JValue *val = jparse(c);
            if (v->obj.count >= v->obj.cap) {
                v->obj.cap = v->obj.cap ? v->obj.cap * 2 : 8;
                v->obj.keys = (char**)realloc(v->obj.keys, v->obj.cap * sizeof(char*));
                v->obj.vals = (JValue**)realloc(v->obj.vals, v->obj.cap * sizeof(JValue*));
            }
            v->obj.keys[v->obj.count] = key;
            v->obj.vals[v->obj.count] = val;
            v->obj.count++;
            jskip_ws(c);
            if (c->p < c->end && *c->p == ',') { c->p++; continue; }
            if (c->p < c->end && *c->p == '}') { c->p++; break; }
            break;
        }
        return v;
    } else if (ch == '[') {
        c->p++;
        JValue *v = jval_new(JV_ARR);
        jskip_ws(c);
        if (c->p < c->end && *c->p == ']') { c->p++; return v; }
        for (;;) {
            JValue *val = jparse(c);
            if (v->arr.count >= v->arr.cap) {
                v->arr.cap = v->arr.cap ? v->arr.cap * 2 : 8;
                v->arr.items = (JValue**)realloc(v->arr.items, v->arr.cap * sizeof(JValue*));
            }
            v->arr.items[v->arr.count++] = val;
            jskip_ws(c);
            if (c->p < c->end && *c->p == ',') { c->p++; continue; }
            if (c->p < c->end && *c->p == ']') { c->p++; break; }
            break;
        }
        return v;
    } else if (ch == 't') {
        if (c->p + 4 <= c->end && memcmp(c->p, "true", 4) == 0) { c->p += 4; JValue *v = jval_new(JV_BOOL); v->bval = 1; return v; }
        c->p += 4; return NULL;
    } else if (ch == 'f') {
        if (c->p + 5 <= c->end && memcmp(c->p, "false", 5) == 0) { c->p += 5; JValue *v = jval_new(JV_BOOL); v->bval = 0; return v; }
        c->p += 5; return NULL;
    } else if (ch == 'n') {
        if (c->p + 4 <= c->end && memcmp(c->p, "null", 4) == 0) { c->p += 4; return jval_new(JV_NULL); }
        c->p += 4; return NULL;
    } else {
        const char *start = c->p;
        if (*c->p == '-') c->p++;
        while (c->p < c->end && isdigit((unsigned char)*c->p)) c->p++;
        if (c->p < c->end && *c->p == '.') { c->p++; while (c->p < c->end && isdigit((unsigned char)*c->p)) c->p++; }
        if (c->p < c->end && (*c->p == 'e' || *c->p == 'E')) { c->p++; if (*c->p=='+'||*c->p=='-') c->p++; while (c->p < c->end && isdigit((unsigned char)*c->p)) c->p++; }
        JValue *v = jval_new(JV_NUM);
        v->nval = strtoll(start, NULL, 10);
        return v;
    }
}

static JValue *jobj_get(JValue *obj, const char *key) {
    if (!obj || obj->type != JV_OBJ) return NULL;
    for (size_t i = 0; i < obj->obj.count; i++) {
        if (strcmp(obj->obj.keys[i], key) == 0) return obj->obj.vals[i];
    }
    return NULL;
}

static JValue *jparse_json(const char *s, size_t len) {
    JCtx c = {s, s + len};
    return jparse(&c);
}

/* ============ Amount Parsing ============ */
static long long parse_amount(const char *s) {
    int neg = 0;
    if (*s == '-') { neg = 1; s++; }
    long long intpart = 0;
    while (*s >= '0' && *s <= '9') { intpart = intpart * 10 + (*s - '0'); s++; }
    long long cents = intpart * 100;
    if (*s == '.') {
        s++;
        int d1 = -1, d2 = -1;
        if (*s >= '0' && *s <= '9') { d1 = *s - '0'; s++; }
        if (*s >= '0' && *s <= '9') { d2 = *s - '0'; s++; }
        if (d1 >= 0 && d2 >= 0) {
            cents = intpart * 100 + d1 * 10 + d2;
        } else if (d1 >= 0) {
            cents = intpart * 100 + d1 * 10;
        }
    }
    return neg ? -cents : cents;
}

static void format_amount(long long cents, Buf *out) {
    if (cents < 0) {
        buf_appendc(out, '-');
        cents = -cents;
    }
    long long ip = cents / 100;
    long long fp = cents % 100;
    char tmp[64];
    snprintf(tmp, sizeof(tmp), "%lld.%02lld", ip, fp);
    buf_appendstr(out, tmp);
}

/* ============ Output Data Structures ============ */
typedef struct {
    char *name;
    char *currency;
    long long total;
} TotalEntry;

typedef struct {
    char *status;
    int count;
} StatusEntry;

static int cmp_total(const void *a, const void *b) {
    const TotalEntry *ta = (const TotalEntry*)a, *tb = (const TotalEntry*)b;
    int r = strcmp(ta->name, tb->name);
    if (r) return r;
    return strcmp(ta->currency, tb->currency);
}
static int cmp_status(const void *a, const void *b) {
    const StatusEntry *sa = (const StatusEntry*)a, *sb = (const StatusEntry*)b;
    return strcmp(sa->status, sb->status);
}

/* ============ Main ============ */
int main(int argc, char *argv[]) {
    if (argc != 3) return 1;
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    /* Read client.json */
    char cpath[1024];
    snprintf(cpath, sizeof(cpath), "%s/client.json", data_dir);
    FILE *f = fopen(cpath, "rb");
    if (!f) return 1;
    Buf cbuf; buf_init(&cbuf);
    {
        char tmp[4096];
        size_t n;
        while ((n = fread(tmp, 1, sizeof(tmp), f)) > 0) buf_append(&cbuf, tmp, n);
    }
    fclose(f);

    JValue *cj = jparse_json(cbuf.data, cbuf.len);
    JValue *jid = jobj_get(cj, "client_id");
    JValue *jsec = jobj_get(cj, "client_secret");
    JValue *jsp = jobj_get(cj, "scope");
    JValue *jps = jobj_get(cj, "page_size");
    const char *client_id = jid ? jid->sval : "";
    const char *client_secret = jsec ? jsec->sval : "";
    const char *scope = jsp ? jsp->sval : "";
    int page_size = (int)(jps ? jps->nval : 10);
    free(cbuf.data);

    Url base;
    parse_url(base_url, &base);

    /* Build Basic auth header */
    Buf idenc, secenc, credstr, b64buf;
    buf_init(&idenc); buf_init(&secenc); buf_init(&credstr); buf_init(&b64buf);
    form_encode(client_id, &idenc);
    form_encode(client_secret, &secenc);
    buf_append(&credstr, idenc.data, idenc.len);
    buf_appendc(&credstr, ':');
    buf_append(&credstr, secenc.data, secenc.len);
    base64_encode((const unsigned char*)credstr.data, credstr.len, &b64buf);
    Buf authbasic; buf_init(&authbasic);
    buf_appendstr(&authbasic, "Basic ");
    buf_append(&authbasic, b64buf.data, b64buf.len);

    /* Build token request body */
    Buf tokbody; buf_init(&tokbody);
    buf_appendstr(&tokbody, "grant_type=client_credentials&scope=");
    form_encode(scope, &tokbody);

    /* Counters */
    long long total_orders = 0;
    int pages = 0;
    int retries = 0;
    int reauths = 0;

    /* Totals and statuses */
    TotalEntry *totals = NULL; size_t ntotals = 0, cap_totals = 0;
    StatusEntry *statuses = NULL; size_t nstatuses = 0, cap_statuses = 0;

    /* Get token */
    char access_token[4096] = "";
    {
        HttpResponse r;
        http_request(&base, "POST", "/oauth/token",
                     "application/x-www-form-urlencoded", tokbody.data, authbasic.data, &r);
        if (r.status != 200) {
            printf("ERROR %d %s\n", r.status, r.body ? r.body : "");
            free(r.body); return 0;
        }
        JValue *tj = jparse_json(r.body, r.body_len);
        JValue *at = jobj_get(tj, "access_token");
        if (at && at->type == JV_STR) {
            strncpy(access_token, at->sval, sizeof(access_token) - 1);
            access_token[sizeof(access_token) - 1] = '\0';
        }
        free(r.body);
    }

    /* Fetch pages */
    char cursor[4096] = "";
    int has_cursor = 0;
    int first_with_token = 1;

    for (;;) {
        Buf qpath; buf_init(&qpath);
        buf_appendstr(&qpath, "/orders?limit=");
        char ps[16]; snprintf(ps, sizeof(ps), "%d", page_size);
        buf_appendstr(&qpath, ps);
        if (has_cursor) {
            buf_appendstr(&qpath, "&cursor=");
            pct_encode(cursor, &qpath);
        }

        Buf authbearer; buf_init(&authbearer);
        buf_appendstr(&authbearer, "Bearer ");
        buf_appendstr(&authbearer, access_token);

        HttpResponse r;
        http_request(&base, "GET", qpath.data, NULL, NULL, authbearer.data, &r);
        free(qpath.data);
        free(authbearer.data);

        if (r.status == 429) {
            retries++;
            int wait = atoi(r.retry_after);
            if (wait < 1) wait = 1;
            free(r.body);
            sleep((unsigned)wait);
            continue;
        }
        if (r.status == 503) {
            retries++;
            free(r.body);
            my_sleep_ms(500);
            continue;
        }
        if (r.status == 401) {
            if (first_with_token) {
                printf("ERROR %d %s\n", r.status, r.body ? r.body : "");
                free(r.body); return 0;
            }
            free(r.body);
            HttpResponse tr;
            http_request(&base, "POST", "/oauth/token",
                         "application/x-www-form-urlencoded", tokbody.data, authbasic.data, &tr);
            if (tr.status != 200) {
                printf("ERROR %d %s\n", tr.status, tr.body ? tr.body : "");
                free(tr.body); return 0;
            }
            JValue *tj = jparse_json(tr.body, tr.body_len);
            JValue *at = jobj_get(tj, "access_token");
            if (at && at->type == JV_STR) {
                strncpy(access_token, at->sval, sizeof(access_token) - 1);
                access_token[sizeof(access_token) - 1] = '\0';
            }
            free(tr.body);
            reauths++;
            first_with_token = 1;
            continue;
        }
        if (r.status != 200) {
            printf("ERROR %d %s\n", r.status, r.body ? r.body : "");
            free(r.body); return 0;
        }

        pages++;
        first_with_token = 0;

        JValue *pj = jparse_json(r.body, r.body_len);
        free(r.body);

        JValue *data = jobj_get(pj, "data");
        if (data && data->type == JV_ARR) {
            for (size_t i = 0; i < data->arr.count; i++) {
                JValue *ord = data->arr.items[i];
                total_orders++;

                JValue *jstatus = jobj_get(ord, "status");
                JValue *jcurrency = jobj_get(ord, "currency");
                JValue *jamount = jobj_get(ord, "amount");
                JValue *jcustomer = jobj_get(ord, "customer");
                JValue *jname = jcustomer ? jobj_get(jcustomer, "name") : NULL;

                const char *status = (jstatus && jstatus->type == JV_STR) ? jstatus->sval : "";
                const char *currency = (jcurrency && jcurrency->type == JV_STR) ? jcurrency->sval : "";
                const char *amount_s = (jamount && jamount->type == JV_STR) ? jamount->sval : "0";
                const char *name = (jname && jname->type == JV_STR) ? jname->sval : "";

                int found = 0;
                for (size_t s = 0; s < nstatuses; s++) {
                    if (strcmp(statuses[s].status, status) == 0) {
                        statuses[s].count++;
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    if (nstatuses >= cap_statuses) {
                        cap_statuses = cap_statuses ? cap_statuses * 2 : 16;
                        statuses = (StatusEntry*)realloc(statuses, cap_statuses * sizeof(StatusEntry));
                    }
                    statuses[nstatuses].status = strdup(status);
                    statuses[nstatuses].count = 1;
                    nstatuses++;
                }

                if (strcmp(status, "cancelled") != 0) {
                    long long cents = parse_amount(amount_s);
                    found = 0;
                    for (size_t t = 0; t < ntotals; t++) {
                        if (strcmp(totals[t].name, name) == 0 &&
                            strcmp(totals[t].currency, currency) == 0) {
                            totals[t].total += cents;
                            found = 1;
                            break;
                        }
                    }
                    if (!found) {
                        if (ntotals >= cap_totals) {
                            cap_totals = cap_totals ? cap_totals * 2 : 64;
                            totals = (TotalEntry*)realloc(totals, cap_totals * sizeof(TotalEntry));
                        }
                        totals[ntotals].name = strdup(name);
                        totals[ntotals].currency = strdup(currency);
                        totals[ntotals].total = cents;
                        ntotals++;
                    }
                }
            }
        }

        JValue *nc = jobj_get(pj, "next_cursor");
        if (nc && nc->type == JV_STR) {
            strncpy(cursor, nc->sval, sizeof(cursor) - 1);
            cursor[sizeof(cursor) - 1] = '\0';
            has_cursor = 1;
        } else {
            has_cursor = 0;
            break;
        }
    }

    /* Output */
    qsort(totals, ntotals, sizeof(TotalEntry), cmp_total);
    for (size_t i = 0; i < ntotals; i++) {
        Buf line; buf_init(&line);
        buf_appendstr(&line, "total ");
        buf_appendstr(&line, totals[i].currency);
        buf_appendc(&line, ' ');
        format_amount(totals[i].total, &line);
        buf_appendc(&line, ' ');
        buf_appendstr(&line, totals[i].name);
        fwrite(line.data, 1, line.len, stdout);
        fputc('\n', stdout);
        free(line.data);
    }

    qsort(statuses, nstatuses, sizeof(StatusEntry), cmp_status);
    for (size_t i = 0; i < nstatuses; i++) {
        printf("status %s %d\n", statuses[i].status, statuses[i].count);
    }

    printf("orders %lld pages %d retries %d reauth %d\n",
           total_orders, pages, retries, reauths);

    return 0;
}

import json
import http.client
import sys
from urllib.parse import urlparse


def escape_string(s):
    result = []
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        else:
            result.append(ch)
    return ''.join(result)


def parse_sse(body_bytes):
    text = body_bytes.decode('utf-8')
    events = []
    current_event = None
    current_data_lines = []

    lines = text.split('\n')

    for line in lines:
        if line.endswith('\r'):
            line = line[:-1]

        if line == '':
            if current_data_lines or current_event is not None:
                data = '\n'.join(current_data_lines)
                events.append((current_event, data))
            current_event = None
            current_data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('event:'):
            val = line[6:]
            if val.startswith(' '):
                val = val[1:]
            current_event = val
        elif line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            current_data_lines.append(val)

    return events


def parse_reply(events):
    blocks = {}
    stop_reason = None
    input_tokens = 0
    output_tokens = 0
    cache_read_tokens = 0

    for event_type, data_str in events:
        if event_type is None:
            continue
        if event_type == 'ping':
            continue
        try:
            data = json.loads(data_str)
        except (json.JSONDecodeError, ValueError):
            continue

        if event_type == 'message_start':
            usage = data.get('message', {}).get('usage', {})
            input_tokens += usage.get('input_tokens', 0)
            cache_read_tokens += usage.get('cache_read_input_tokens', 0)
        elif event_type == 'content_block_start':
            idx = data['index']
            cb = data['content_block']
            blocks[idx] = {
                'type': cb['type'],
                'text': '',
                'signature': '',
                'id': cb.get('id', ''),
                'name': cb.get('name', ''),
                'input_json': '',
            }
        elif event_type == 'content_block_delta':
            idx = data['index']
            delta = data['delta']
            block = blocks[idx]
            dtype = delta['type']
            if dtype == 'thinking_delta':
                block['text'] += delta['thinking']
            elif dtype == 'signature_delta':
                block['signature'] += delta['signature']
            elif dtype == 'text_delta':
                block['text'] += delta['text']
            elif dtype == 'input_json_delta':
                block['input_json'] += delta['partial_json']
        elif event_type == 'content_block_stop':
            pass
        elif event_type == 'message_delta':
            stop_reason = data['delta']['stop_reason']
            usage = data.get('usage', {})
            output_tokens += usage.get('output_tokens', 0)
        elif event_type == 'message_stop':
            pass

    return blocks, stop_reason, input_tokens, output_tokens, cache_read_tokens


def execute_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        if unit == 'code_points':
            return str(len(text)), False
        elif unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        elif unit == 'utf16_units':
            count = 0
            for ch in text:
                if ord(ch) > 0xFFFF:
                    count += 2
                else:
                    count += 1
            return str(count), False
        else:
            return 'unsupported unit: ' + unit, True
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return text[::-1], False
    else:
        return 'unknown tool: ' + name, True


def make_request(base_url, api_key, model, max_tokens, thinking_budget, system, tools, messages):
    parsed = urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or (443 if parsed.scheme == 'https' else 80)
    path = parsed.path + '/v1/messages'

    body = json.dumps({
        "model": model,
        "max_tokens": max_tokens,
        "stream": True,
        "thinking": {"type": "enabled", "budget_tokens": thinking_budget},
        "system": system,
        "tools": tools,
        "messages": messages
    })

    body_bytes = body.encode('utf-8')

    headers = {
        "x-api-key": api_key,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
    }

    conn = http.client.HTTPConnection(host, port)
    conn.request("POST", path, body=body_bytes, headers=headers)
    response = conn.getresponse()

    if response.status != 200:
        error_body = response.read().decode('utf-8')
        conn.close()
        error_data = json.loads(error_body)
        return None, (response.status, error_data['error']['type'], error_data['error']['message'])

    resp_body = response.read()
    conn.close()
    return resp_body, None


def print_blocks(blocks):
    for idx in sorted(blocks.keys()):
        block = blocks[idx]
        if block['type'] == 'thinking':
            print(f"thinking {escape_string(block['text'])}")
            print(f"signature {escape_string(block['signature'])}")
        elif block['type'] == 'text':
            print(f"text {escape_string(block['text'])}")
        elif block['type'] == 'tool_use':
            print(f"tool_use {block['id']} {block['name']} {escape_string(block['input_json'])}")


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f'{data_dir}/request.json', 'r') as f:
        config = json.load(f)

    api_key = config['api_key']
    model = config['model']
    max_tokens = config['max_tokens']
    thinking_budget = config['thinking_budget']
    system = config['system']
    prompt = config['prompt']
    tools = config['tools']

    total_input = 0
    total_output = 0
    total_cache_read = 0

    # Request 1
    messages_1 = [{"role": "user", "content": prompt}]

    print("request 1")
    body_bytes, error = make_request(base_url, api_key, model, max_tokens, thinking_budget, system, tools, messages_1)

    if error:
        print(f"ERROR {error[0]} {error[1]}: {error[2]}")
        sys.exit(0)

    events = parse_sse(body_bytes)
    blocks_1, stop_reason_1, inp, out, cr = parse_reply(events)
    total_input += inp
    total_output += out
    total_cache_read += cr

    print_blocks(blocks_1)
    print(f"stop_reason {stop_reason_1}")

    # Execute tools
    tool_results = []
    for idx in sorted(blocks_1.keys()):
        block = blocks_1[idx]
        if block['type'] == 'tool_use':
            input_json_text = block['input_json']
            if input_json_text.strip():
                input_obj = json.loads(input_json_text)
            else:
                input_obj = {}
            result, is_error = execute_tool(block['name'], input_obj)
            tool_results.append((block['id'], result, is_error))
            if is_error:
                print(f"error {block['id']} {escape_string(result)}")
            else:
                print(f"result {block['id']} {escape_string(result)}")

    # Build request 2 messages
    assistant_content = []
    for idx in sorted(blocks_1.keys()):
        block = blocks_1[idx]
        if block['type'] == 'thinking':
            assistant_content.append({
                "type": "thinking",
                "thinking": block['text'],
                "signature": block['signature']
            })
        elif block['type'] == 'text':
            assistant_content.append({
                "type": "text",
                "text": block['text']
            })
        elif block['type'] == 'tool_use':
            input_json_text = block['input_json']
            if input_json_text.strip():
                input_obj = json.loads(input_json_text)
            else:
                input_obj = {}
            assistant_content.append({
                "type": "tool_use",
                "id": block['id'],
                "name": block['name'],
                "input": input_obj
            })

    tool_result_content = []
    for (tool_use_id, result, is_error) in tool_results:
        block = {"type": "tool_result", "tool_use_id": tool_use_id, "content": result}
        if is_error:
            block["is_error"] = True
        tool_result_content.append(block)

    messages_2 = [
        {"role": "user", "content": prompt},
        {"role": "assistant", "content": assistant_content},
        {"role": "user", "content": tool_result_content}
    ]

    # Request 2
    print("request 2")
    body_bytes, error = make_request(base_url, api_key, model, max_tokens, thinking_budget, system, tools, messages_2)

    if error:
        print(f"ERROR {error[0]} {error[1]}: {error[2]}")
        sys.exit(0)

    events = parse_sse(body_bytes)
    blocks_2, stop_reason_2, inp, out, cr = parse_reply(events)
    total_input += inp
    total_output += out
    total_cache_read += cr

    print_blocks(blocks_2)
    print(f"stop_reason {stop_reason_2}")

    print(f"usage input={total_input} output={total_output} cache_read={total_cache_read}")


if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static byte[] fileData;
    static int pageSize;
    static int reservedBytes;
    static int usableSize;

    static class CellData {
        long rowid;
        byte[] payload;
        CellData(long r, byte[] p) { rowid = r; payload = p; }
    }

    static class SchemaEntry {
        String name;
        long rootpage;
        String sql;
        SchemaEntry(String n, long r, String s) { name = n; rootpage = r; sql = s; }
    }

    static class ColDef {
        String name;
        boolean isRowidAlias;
        ColDef(String n, boolean a) { name = n; isRowidAlias = a; }
    }

    static class Value {
        int type; // 0=NULL,1=INT,2=REAL,3=TEXT,4=BLOB
        long intVal;
        double realVal;
        byte[] bytesVal;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        fileData = Files.readAllBytes(Paths.get(dir, "db.sqlite"));

        pageSize = ((fileData[16] & 0xFF) << 8) | (fileData[17] & 0xFF);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = fileData[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<CellData> schemaCells = new ArrayList<>();
        walkTableBTree(1, schemaCells);

        List<SchemaEntry> tables = new ArrayList<>();
        for (CellData cd : schemaCells) {
            Value[] vals = decodeRecord(cd.payload);
            if (vals.length < 5) continue;
            if (vals[0].type != 3) continue;
            String type = new String(vals[0].bytesVal, StandardCharsets.UTF_8);
            if (!"table".equals(type)) continue;
            if (vals[1].type != 3) continue;
            String name = new String(vals[1].bytesVal, StandardCharsets.UTF_8);
            if (name.startsWith("sqlite_")) continue;
            if (vals[3].type != 1) continue;
            long rootpage = vals[3].intVal;
            String sql = vals[4].type == 3 ? new String(vals[4].bytesVal, StandardCharsets.UTF_8) : "";
            tables.add(new SchemaEntry(name, rootpage, sql));
        }

        tables.sort((a, b) -> {
            byte[] an = a.name.getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.name.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int c = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (c != 0) return c;
            }
            return an.length - bn.length;
        });

        boolean firstTable = true;
        for (SchemaEntry t : tables) {
            if (!firstTable) System.out.println();
            firstTable = false;

            List<ColDef> cols = parseColumns(t.sql);
            List<CellData> rows = new ArrayList<>();
            if (t.rootpage > 0) walkTableBTree((int) t.rootpage, rows);
            rows.sort((a, b) -> Long.compare(a.rowid, b.rowid));

            System.out.println("TABLE " + t.name + " rows=" + rows.size());
            StringBuilder cl = new StringBuilder("COLUMNS ");
            for (int i = 0; i < cols.size(); i++) {
                if (i > 0) cl.append(", ");
                cl.append(cols.get(i).name);
            }
            System.out.println(cl);

            for (CellData row : rows) {
                Value[] vals = decodeRecord(row.payload);
                StringBuilder sb = new StringBuilder();
                sb.append(row.rowid).append(": ");
                for (int i = 0; i < cols.size(); i++) {
                    if (i > 0) sb.append(", ");
                    if (cols.get(i).isRowidAlias) {
                        sb.append(row.rowid);
                    } else if (i < vals.length) {
                        sb.append(formatValue(vals[i]));
                    } else {
                        sb.append("NULL");
                    }
                }
                System.out.println(sb);
            }
        }
    }

    static void walkTableBTree(int pageNum, List<CellData> cells) {
        int pageOff = (pageNum - 1) * pageSize;
        int hdrOff = (pageNum == 1) ? 100 : 0;
        int pageType = fileData[pageOff + hdrOff] & 0xFF;

        if (pageType == 0x0D) {
            int numCells = readUint16(pageOff + hdrOff + 3);
            int cptrStart = hdrOff + 8;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(pageOff + cptrStart + i * 2);
                cells.add(readLeafCell(pageOff, cellOff));
            }
        } else if (pageType == 0x05) {
            int numCells = readUint16(pageOff + hdrOff + 3);
            int cptrStart = hdrOff + 12;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(pageOff + cptrStart + i * 2);
                int childPage = readUint32(pageOff + cellOff);
                walkTableBTree(childPage, cells);
            }
            int rightPage = readUint32(pageOff + hdrOff + 8);
            walkTableBTree(rightPage, cells);
        }
    }

    static CellData readLeafCell(int pageOff, int cellOff) {
        int pos = pageOff + cellOff;
        int[] p = {pos};
        long payloadSize = readVarint(p);
        long rowid = readVarint(p);

        int P = (int) payloadSize;
        int X = usableSize - 35;
        int M = ((usableSize - 12) * 32 / 255) - 23;
        int localSize;
        if (P <= X) {
            localSize = P;
        } else {
            int K = M + ((P - M) % (usableSize - 4));
            if (K <= X) {
                localSize = K;
            } else {
                localSize = M;
            }
        }

        byte[] local = Arrays.copyOfRange(fileData, p[0], p[0] + localSize);
        byte[] fullPayload;

        if (P > localSize) {
            long overflowPage = readUint32(fileData, p[0] + localSize) & 0xFFFFFFFFL;
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            baos.write(local, 0, local.length);
            int remaining = P - localSize;
            while (overflowPage != 0 && remaining > 0) {
                int opOff = (int) ((overflowPage - 1) * pageSize);
                long nextOp = readUint32(fileData, opOff) & 0xFFFFFFFFL;
                int chunk = Math.min(remaining, usableSize - 4);
                baos.write(fileData, opOff + 4, chunk);
                remaining -= chunk;
                overflowPage = nextOp;
            }
            fullPayload = baos.toByteArray();
        } else {
            fullPayload = local;
        }

        return new CellData(rowid, fullPayload);
    }

    static Value[] decodeRecord(byte[] payload) {
        int[] p = {0};
        long headerSize = readVarint(p);
        if (payload.length == 0) return new Value[0];
        long numCols = readVarint(p);
        int nc = (int) numCols;
        long[] stypes = new long[nc];
        for (int i = 0; i < nc; i++) {
            stypes[i] = readVarint(p);
        }
        Value[] vals = new Value[nc];
        for (int i = 0; i < nc; i++) {
            vals[i] = decodeValue(payload, p, stypes[i]);
        }
        return vals;
    }

    static Value decodeValue(byte[] data, int[] p, long stype) {
        Value v = new Value();
        if (stype == 0) {
            v.type = 0;
        } else if (stype == 1) {
            v.type = 1;
            v.intVal = (byte) data[p[0]];
            p[0] += 1;
        } else if (stype == 2) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 2);
            p[0] += 2;
        } else if (stype == 3) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 3);
            p[0] += 3;
        } else if (stype == 4) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 4);
            p[0] += 4;
        } else if (stype == 5) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 6);
            p[0] += 6;
        } else if (stype == 6) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 8);
            p[0] += 8;
        } else if (stype == 7) {
            v.type = 2;
            long bits = readSignedInt(data, p[0], 8);
            v.realVal = Double.longBitsToDouble(bits);
            p[0] += 8;
        } else if (stype == 8) {
            v.type = 1;
            v.intVal = 0;
        } else if (stype == 9) {
            v.type = 1;
            v.intVal = 1;
        } else if (stype >= 12 && (stype & 1) == 0) {
            v.type = 4;
            int len = (int) ((stype - 12) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else if (stype >= 13 && (stype & 1) == 1) {
            v.type = 3;
            int len = (int) ((stype - 13) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else {
            v.type = 0;
        }
        return v;
    }

    static long readSignedInt(byte[] data, int off, int n) {
        long val;
        if (n == 0) return 0;
        if ((data[off] & 0x80) != 0) val = -1;
        else val = 0;
        for (int i = 0; i < n; i++) {
            val = (val << 8) | (data[off + i] & 0xFF);
        }
        return val;
    }

    static long readVarint(int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = fileData[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static long readVarint(byte[] data, int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = data[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static int readUint16(int off) {
        return ((fileData[off] & 0xFF) << 8) | (fileData[off + 1] & 0xFF);
    }

    static int readUint32(int off) {
        return ((fileData[off] & 0xFF) << 24) | ((fileData[off + 1] & 0xFF) << 16) |
               ((fileData[off + 2] & 0xFF) << 8) | (fileData[off + 3] & 0xFF);
    }

    static String formatValue(Value v) {
        switch (v.type) {
            case 0: return "NULL";
            case 1: return Long.toString(v.intVal);
            case 2: return formatReal(v.realVal);
            case 3: return formatText(v.bytesVal);
            case 4: return formatBlob(v.bytesVal);
            default: return "NULL";
        }
    }

    static String formatReal(double d) {
        BigDecimal bd = new BigDecimal(d);
        bd = bd.stripTrailingZeros();
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        return s;
    }

    static String formatText(byte[] data) {
        if (data.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(data);
            return "<TEXT len=" + data.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write('"');
        for (byte b : data) {
            int v = b & 0xFF;
            if (v == '\\') { baos.write('\\'); baos.write('\\'); }
            else if (v == '"') { baos.write('\\'); baos.write('"'); }
            else if (v == '\n') { baos.write('\\'); baos.write('n'); }
            else if (v == '\r') { baos.write('\\'); baos.write('r'); }
            else if (v == '\t') { baos.write('\\'); baos.write('t'); }
            else if (v < 0x20 || v == 0x7F) {
                baos.write('\\'); baos.write('x');
                String hex = String.format("%02X", v);
                baos.write(hex.charAt(0)); baos.write(hex.charAt(1));
            } else {
                baos.write(v);
            }
        }
        baos.write('"');
        return new String(baos.toByteArray(), StandardCharsets.UTF_8);
    }

    static String formatBlob(byte[] data) {
        if (data.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(data);
            return "<BLOB len=" + data.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder("X'");
        for (byte b : data) {
            sb.append(String.format("%02X", b & 0xFF));
        }
        sb.append("'");
        return sb.toString();
    }

    static List<ColDef> parseColumns(String sql) {
        List<ColDef> cols = new ArrayList<>();
        String s = sql.trim();
        // Skip "CREATE TABLE"
        int idx = skipKeyword(s, 0, "CREATE");
        idx = skipWhitespace(s, idx);
        idx = skipKeyword(s, idx, "TABLE");
        idx = skipWhitespace(s, idx);
        // Skip table name (possibly quoted)
        idx = skipName(s, idx);
        idx = skipWhitespace(s, idx);
        // Expect '('
        if (idx < s.length() && s.charAt(idx) == '(') {
            idx++;
        }
        // Find matching ')'
        int depth = 1;
        int defsStart = idx;
        int defsEnd = idx;
        while (idx < s.length() && depth > 0) {
            if (s.charAt(idx) == '(') depth++;
            else if (s.charAt(idx) == ')') depth--;
            if (depth > 0) idx++;
        }
        defsEnd = idx;
        String defs = s.substring(defsStart, defsEnd);

        // Split by commas at depth 0
        List<String> defsList = splitDefs(defs);
        for (String def : defsList) {
            String trimmed = def.trim();
            if (trimmed.isEmpty()) continue;
            String colName = extractColName(trimmed);
            boolean isAlias = isRowidAlias(trimmed);
            cols.add(new ColDef(colName, isAlias));
        }
        return cols;
    }

    static int skipKeyword(String s, int idx, String kw) {
        idx = skipWhitespace(s, idx);
        if (idx + kw.length() <= s.length() && s.substring(idx, idx + kw.length()).equalsIgnoreCase(kw)) {
            idx += kw.length();
        }
        return idx;
    }

    static int skipWhitespace(String s, int idx) {
        while (idx < s.length() && Character.isWhitespace(s.charAt(idx))) idx++;
        return idx;
    }

    static int skipName(String s, int idx) {
        if (idx < s.length() && s.charAt(idx) == '"') {
            idx++;
            while (idx < s.length() && s.charAt(idx) != '"') idx++;
            if (idx < s.length()) idx++;
        } else {
            while (idx < s.length() && !Character.isWhitespace(s.charAt(idx)) && s.charAt(idx) != '(' && s.charAt(idx) != ')') idx++;
        }
        return idx;
    }

    static List<String> splitDefs(String defs) {
        List<String> result = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < defs.length(); i++) {
            char c = defs.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') depth--;
            else if (c == ',' && depth == 0) {
                result.add(defs.substring(start, i));
                start = i + 1;
            }
        }
        if (start < defs.length()) {
            result.add(defs.substring(start));
        }
        return result;
    }

    static String extractColName(String def) {
        def = def.trim();
        if (def.startsWith("\"")) {
            int end = def.indexOf('"', 1);
            if (end > 0) return def.substring(1, end);
            return def.substring(1);
        }
        int i = 0;
        while (i < def.length() && !Character.isWhitespace(def.charAt(i)) && def.charAt(i) != '(') {
            i++;
        }
        return def.substring(0, i);
    }

    static boolean isRowidAlias(String def) {
        def = def.trim();
        int i = 0;
        // Skip column name
        if (def.startsWith("\"")) {
            i = def.indexOf('"', 1) + 1;
        } else {
            while (i < def.length() && !Character.isWhitespace(def.charAt(i)) && def.charAt(i) != '(') i++;
        }
        // Skip whitespace
        while (i < def.length() && Character.isWhitespace(def.charAt(i))) i++;
        // Read type identifier
        int typeStart = i;
        while (i < def.length() && (Character.isLetterOrDigit(def.charAt(i)) || def.charAt(i) == '_')) i++;
        String typeName = def.substring(typeStart, i);
        // Skip optional (N) or (N,M)
        while (i < def.length() && Character.isWhitespace(def.charAt(i))) i++;
        if (i < def.length() && def.charAt(i) == '(') {
            int d = 1; i++;
            while (i < def.length() && d > 0) {
                if (def.charAt(i) == '(') d++;
                else if (def.charAt(i) == ')') d--;
                i++;
            }
        }
        if (!typeName.equalsIgnoreCase("INTEGER")) return false;
        // Check for PRIMARY KEY in the rest
        String rest = def.substring(typeStart).replaceAll("\\s+", " ").toUpperCase();
        return rest.contains("PRIMARY KEY");
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.math.BigDecimal;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static byte[] fileData;
    static int pageSize;
    static int reservedBytes;
    static int usableSize;

    static class CellData {
        long rowid;
        byte[] payload;
        CellData(long r, byte[] p) { rowid = r; payload = p; }
    }

    static class SchemaEntry {
        String name;
        long rootpage;
        String sql;
        SchemaEntry(String n, long r, String s) { name = n; rootpage = r; sql = s; }
    }

    static class ColDef {
        String name;
        boolean isRowidAlias;
        ColDef(String n, boolean a) { name = n; isRowidAlias = a; }
    }

    static class Value {
        int type; // 0=NULL,1=INT,2=REAL,3=TEXT,4=BLOB
        long intVal;
        double realVal;
        byte[] bytesVal;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        fileData = Files.readAllBytes(Paths.get(dir, "db.sqlite"));

        pageSize = ((fileData[16] & 0xFF) << 8) | (fileData[17] & 0xFF);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = fileData[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<CellData> schemaCells = new ArrayList<>();
        walkTableBTree(1, schemaCells);

        List<SchemaEntry> tables = new ArrayList<>();
        for (CellData cd : schemaCells) {
            Value[] vals = decodeRecord(cd.payload);
            if (vals.length < 5) continue;
            if (vals[0].type != 3) continue;
            String type = new String(vals[0].bytesVal, StandardCharsets.UTF_8);
            if (!"table".equals(type)) continue;
            if (vals[1].type != 3) continue;
            String name = new String(vals[1].bytesVal, StandardCharsets.UTF_8);
            if (name.startsWith("sqlite_")) continue;
            if (vals[3].type != 1) continue;
            long rootpage = vals[3].intVal;
            String sql = vals[4].type == 3 ? new String(vals[4].bytesVal, StandardCharsets.UTF_8) : "";
            tables.add(new SchemaEntry(name, rootpage, sql));
        }

        tables.sort((a, b) -> {
            byte[] an = a.name.getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.name.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int c = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (c != 0) return c;
            }
            return an.length - bn.length;
        });

        boolean firstTable = true;
        for (SchemaEntry t : tables) {
            if (!firstTable) System.out.println();
            firstTable = false;

            List<ColDef> cols = parseColumns(t.sql);
            List<CellData> rows = new ArrayList<>();
            if (t.rootpage > 0) walkTableBTree((int) t.rootpage, rows);
            rows.sort((a, b) -> Long.compare(a.rowid, b.rowid));

            System.out.println("TABLE " + t.name + " rows=" + rows.size());
            StringBuilder cl = new StringBuilder("COLUMNS ");
            for (int i = 0; i < cols.size(); i++) {
                if (i > 0) cl.append(", ");
                cl.append(cols.get(i).name);
            }
            System.out.println(cl);

            for (CellData row : rows) {
                Value[] vals = decodeRecord(row.payload);
                StringBuilder sb = new StringBuilder();
                sb.append(row.rowid).append(": ");
                for (int i = 0; i < cols.size(); i++) {
                    if (i > 0) sb.append(", ");
                    if (cols.get(i).isRowidAlias) {
                        sb.append(row.rowid);
                    } else if (i < vals.length) {
                        sb.append(formatValue(vals[i]));
                    } else {
                        sb.append("NULL");
                    }
                }
                System.out.println(sb);
            }
        }
    }

    static void walkTableBTree(int pageNum, List<CellData> cells) {
        int pageOff = (pageNum - 1) * pageSize;
        int hdrOff = (pageNum == 1) ? 100 : 0;
        int pageType = fileData[pageOff + hdrOff] & 0xFF;

        if (pageType == 0x0D) {
            int numCells = readUint16(pageOff + hdrOff + 3);
            int cptrStart = hdrOff + 8;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(pageOff + cptrStart + i * 2);
                cells.add(readLeafCell(pageOff, cellOff));
            }
        } else if (pageType == 0x05) {
            int numCells = readUint16(pageOff + hdrOff + 3);
            int cptrStart = hdrOff + 12;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(pageOff + cptrStart + i * 2);
                int childPage = readUint32(pageOff + cellOff);
                walkTableBTree(childPage, cells);
            }
            int rightPage = readUint32(pageOff + hdrOff + 8);
            walkTableBTree(rightPage, cells);
        }
    }

    static CellData readLeafCell(int pageOff, int cellOff) {
        int pos = pageOff + cellOff;
        int[] p = {pos};
        long payloadSize = readVarint(p);
        long rowid = readVarint(p);

        int P = (int) payloadSize;
        int X = usableSize - 35;
        int M = ((usableSize - 12) * 32 / 255) - 23;
        int localSize;
        if (P <= X) {
            localSize = P;
        } else {
            int K = M + ((P - M) % (usableSize - 4));
            if (K <= X) {
                localSize = K;
            } else {
                localSize = M;
            }
        }

        byte[] local = Arrays.copyOfRange(fileData, p[0], p[0] + localSize);
        byte[] fullPayload;

        if (P > localSize) {
            long overflowPage = (long) readUint32(p[0] + localSize) & 0xFFFFFFFFL;
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            baos.write(local, 0, local.length);
            int remaining = P - localSize;
            while (overflowPage != 0 && remaining > 0) {
                int opOff = (int) ((overflowPage - 1) * pageSize);
                long nextOp = (long) readUint32(opOff) & 0xFFFFFFFFL;
                int chunk = Math.min(remaining, usableSize - 4);
                baos.write(fileData, opOff + 4, chunk);
                remaining -= chunk;
                overflowPage = nextOp;
            }
            fullPayload = baos.toByteArray();
        } else {
            fullPayload = local;
        }

        return new CellData(rowid, fullPayload);
    }

    static Value[] decodeRecord(byte[] payload) {
        if (payload.length == 0) return new Value[0];
        int[] p = {0};
        long headerSize = readVarint(payload, p);
        long numCols = readVarint(payload, p);
        int nc = (int) numCols;
        long[] stypes = new long[nc];
        for (int i = 0; i < nc; i++) {
            stypes[i] = readVarint(payload, p);
        }
        Value[] vals = new Value[nc];
        for (int i = 0; i < nc; i++) {
            vals[i] = decodeValue(payload, p, stypes[i]);
        }
        return vals;
    }

    static Value decodeValue(byte[] data, int[] p, long stype) {
        Value v = new Value();
        if (stype == 0) {
            v.type = 0;
        } else if (stype == 1) {
            v.type = 1;
            v.intVal = (byte) data[p[0]];
            p[0] += 1;
        } else if (stype == 2) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 2);
            p[0] += 2;
        } else if (stype == 3) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 3);
            p[0] += 3;
        } else if (stype == 4) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 4);
            p[0] += 4;
        } else if (stype == 5) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 6);
            p[0] += 6;
        } else if (stype == 6) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 8);
            p[0] += 8;
        } else if (stype == 7) {
            v.type = 2;
            long bits = readSignedInt(data, p[0], 8);
            v.realVal = Double.longBitsToDouble(bits);
            p[0] += 8;
        } else if (stype == 8) {
            v.type = 1;
            v.intVal = 0;
        } else if (stype == 9) {
            v.type = 1;
            v.intVal = 1;
        } else if (stype >= 12 && (stype & 1) == 0) {
            v.type = 4;
            int len = (int) ((stype - 12) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else if (stype >= 13 && (stype & 1) == 1) {
            v.type = 3;
            int len = (int) ((stype - 13) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else {
            v.type = 0;
        }
        return v;
    }

    static long readSignedInt(byte[] data, int off, int n) {
        long val;
        if (n == 0) return 0;
        if ((data[off] & 0x80) != 0) val = -1;
        else val = 0;
        for (int i = 0; i < n; i++) {
            val = (val << 8) | (data[off + i] & 0xFF);
        }
        return val;
    }

    static long readVarint(int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = fileData[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static long readVarint(byte[] data, int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = data[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static int readUint16(int off) {
        return ((fileData[off] & 0xFF) << 8) | (fileData[off + 1] & 0xFF);
    }

    static int readUint32(int off) {
        return ((fileData[off] & 0xFF) << 24) | ((fileData[off + 1] & 0xFF) << 16) |
               ((fileData[off + 2] & 0xFF) << 8) | (fileData[off + 3] & 0xFF);
