            }
        }
        if (!typeName.equalsIgnoreCase("INTEGER")) return false;
        String rest = def.substring(typeStart).replaceAll("\\s+", " ").toUpperCase();
        return rest.contains("PRIMARY KEY");
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // ==================== JSON Parser ====================
    static int jPos;
    static String jSrc;

    static Object parseJson(String s) {
        jPos = 0;
        jSrc = s;
        skipWs();
        return parseVal();
    }

    static void skipWs() {
        while (jPos < jSrc.length()) {
            char c = jSrc.charAt(jPos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') jPos++;
            else break;
        }
    }

    static Object parseVal() {
        skipWs();
        char c = jSrc.charAt(jPos);
        if (c == '{') return parseObj();
        if (c == '[') return parseArr();
        if (c == '"') return parseStr();
        if (c == 't') { jPos += 4; return Boolean.TRUE; }
        if (c == 'f') { jPos += 5; return Boolean.FALSE; }
        if (c == 'n') { jPos += 4; return null; }
        return parseNum();
    }

    static Map<String, Object> parseObj() {
        LinkedHashMap<String, Object> m = new LinkedHashMap<>();
        jPos++;
        skipWs();
        if (jSrc.charAt(jPos) == '}') { jPos++; return m; }
        while (true) {
            skipWs();
            String key = parseStr();
            skipWs();
            jPos++; // ':'
            skipWs();
            m.put(key, parseVal());
            skipWs();
            if (jSrc.charAt(jPos) == ',') { jPos++; continue; }
            jPos++; // '}'
            break;
        }
        return m;
    }

    static List<Object> parseArr() {
        ArrayList<Object> a = new ArrayList<>();
        jPos++;
        skipWs();
        if (jSrc.charAt(jPos) == ']') { jPos++; return a; }
        while (true) {
            skipWs();
            a.add(parseVal());
            skipWs();
            if (jSrc.charAt(jPos) == ',') { jPos++; continue; }
            jPos++; // ']'
            break;
        }
        return a;
    }

    static String parseStr() {
        jPos++; // opening "
        StringBuilder sb = new StringBuilder();
        while (jSrc.charAt(jPos) != '"') {
            char c = jSrc.charAt(jPos);
            if (c == '\\') {
                jPos++;
                char e = jSrc.charAt(jPos);
                if (e == '"') { sb.append('"'); }
                else if (e == '\\') { sb.append('\\'); }
                else if (e == '/') { sb.append('/'); }
                else if (e == 'b') { sb.append('\b'); }
                else if (e == 'f') { sb.append('\f'); }
                else if (e == 'n') { sb.append('\n'); }
                else if (e == 'r') { sb.append('\r'); }
                else if (e == 't') { sb.append('\t'); }
                else if (e == 'u') {
                    int hi = Integer.parseInt(jSrc.substring(jPos + 1, jPos + 5), 16);
                    jPos += 4;
                    if (Character.isHighSurrogate((char) hi)) {
                        jPos++; // backslash
                        jPos++; // 'u'
                        int lo = Integer.parseInt(jSrc.substring(jPos + 1, jPos + 5), 16);
                        jPos += 4;
                        sb.appendCodePoint(Character.toCodePoint((char) hi, (char) lo));
                    } else {
                        sb.append((char) hi);
                    }
                }
            } else {
                sb.append(c);
            }
            jPos++;
        }
        jPos++; // closing "
        return sb.toString();
    }

    static Object parseNum() {
        int start = jPos;
        if (jPos < jSrc.length() && jSrc.charAt(jPos) == '-') jPos++;
        while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++;
        boolean isFloat = false;
        if (jPos < jSrc.length() && jSrc.charAt(jPos) == '.') { isFloat = true; jPos++; while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++; }
        if (jPos < jSrc.length() && (jSrc.charAt(jPos) == 'e' || jSrc.charAt(jPos) == 'E')) { isFloat = true; jPos++; if (jPos < jSrc.length() && (jSrc.charAt(jPos) == '+' || jSrc.charAt(jPos) == '-')) jPos++; while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++; }
        String s = jSrc.substring(start, jPos);
        if (isFloat) return Double.parseDouble(s);
        return Long.parseLong(s);
    }

    // ==================== JSON Serializer ====================
    @SuppressWarnings("unchecked")
    static String toJson(Object o) {
        if (o == null) return "null";
        if (o instanceof Boolean) return o.toString();
        if (o instanceof Long) return o.toString();
        if (o instanceof Integer) return o.toString();
        if (o instanceof Double) {
            double d = (Double) o;
            if (d == Math.floor(d) && !Double.isInfinite(d)) return String.valueOf((long) d);
            return o.toString();
        }
        if (o instanceof String) return jsonStr((String) o);
        if (o instanceof Map) {
            Map<String, Object> m = (Map<String, Object>) o;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append(jsonStr(e.getKey())).append(':').append(toJson(e.getValue()));
            }
            sb.append('}');
            return sb.toString();
        }
        if (o instanceof List) {
            List<Object> l = (List<Object>) o;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : l) {
                if (!first) sb.append(',');
                first = false;
                sb.append(toJson(item));
            }
            sb.append(']');
            return sb.toString();
        }
        return o.toString();
    }

    static String jsonStr(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    // ==================== Output Escaping ====================
    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    // ==================== HTTP ====================
    static class HttpResponse {
        int status;
        byte[] body;
    }

    static HttpResponse httpPost(String host, int port, String path, String apiKey, byte[] body) throws IOException {
        Socket sock = new Socket(host, port);
        sock.setSoTimeout(60000);
        OutputStream out = sock.getOutputStream();
        InputStream in = sock.getInputStream();

        String hdr = "POST " + path + " HTTP/1.1\r\n" +
                "Host: " + host + ":" + port + "\r\n" +
                "Content-Length: " + body.length + "\r\n" +
                "x-api-key: " + apiKey + "\r\n" +
                "anthropic-version: 2023-06-01\r\n" +
                "content-type: application/json\r\n" +
                "\r\n";
        out.write(hdr.getBytes(StandardCharsets.US_ASCII));
        out.write(body);
        out.flush();

        HttpResponse resp = new HttpResponse();
        String statusLine = readLine(in);
        resp.status = Integer.parseInt(statusLine.split("\\s+")[1]);

        Map<String, String> headers = new LinkedHashMap<>();
        String line;
        while ((line = readLine(in)) != null && !line.isEmpty()) {
            int ci = line.indexOf(':');
            if (ci >= 0) headers.put(line.substring(0, ci).trim().toLowerCase(), line.substring(ci + 1).trim());
        }

        String te = headers.get("transfer-encoding");
        String cl = headers.get("content-length");
        if (te != null && te.toLowerCase().contains("chunked")) {
            resp.body = readChunked(in);
        } else if (cl != null) {
            resp.body = readN(in, Integer.parseInt(cl));
        } else {
            resp.body = readAll(in);
        }
        sock.close();
        return resp;
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '\r') sb.setLength(sb.length() - 1);
                return sb.toString();
            }
            sb.append((char) c);
        }
        return sb.length() > 0 ? sb.toString() : null;
    }

    static byte[] readN(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = in.read(buf, off, n - off);
            if (r < 0) break;
            off += r;
        }
        return buf;
    }

    static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        int r;
        while ((r = in.read(buf)) != -1) baos.write(buf, 0, r);
        return baos.toByteArray();
    }

    static byte[] readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String szLine = readLine(in);
            if (szLine == null) break;
            int semi = szLine.indexOf(';');
            if (semi >= 0) szLine = szLine.substring(0, semi);
            szLine = szLine.trim();
            if (szLine.isEmpty()) continue;
            int sz = Integer.parseInt(szLine, 16);
            if (sz == 0) break;
            byte[] data = readN(in, sz);
            baos.write(data);
            // consume trailing CRLF
            int c;
            while ((c = in.read()) != -1 && c != '\n') {}
        }
        return baos.toByteArray();
    }

    // ==================== SSE Parsing ====================
    static class SseEvent {
        String event;
        String data;
    }

    static List<SseEvent> parseSse(String text) {
        List<SseEvent> events = new ArrayList<>();
        String curEvent = null;
        StringBuilder curData = new StringBuilder();
        boolean hasData = false;

        String[] lines = text.split("\n", -1);
        for (String raw : lines) {
            String ln = raw;
            if (ln.endsWith("\r")) ln = ln.substring(0, ln.length() - 1);

            if (ln.isEmpty()) {
                if (hasData || curEvent != null) {
                    SseEvent ev = new SseEvent();
                    ev.event = curEvent;
                    ev.data = hasData ? curData.toString() : "";
                    events.add(ev);
                }
                curEvent = null;
                curData = new StringBuilder();
                hasData = false;
                continue;
            }
            if (ln.charAt(0) == ':') continue; // comment

            int colon = ln.indexOf(':');
            String field, value;
            if (colon >= 0) {
                field = ln.substring(0, colon);
                value = ln.substring(colon + 1);
                if (value.startsWith(" ")) value = value.substring(1);
            } else {
                field = ln;
                value = "";
            }

            if (field.equals("event")) {
                curEvent = value;
            } else if (field.equals("data")) {
                if (hasData) curData.append('\n');
                curData.append(value);
                hasData = true;
            }
        }
        // handle trailing event without blank line
        if (hasData || curEvent != null) {
            SseEvent ev = new SseEvent();
            ev.event = curEvent;
            ev.data = hasData ? curData.toString() : "";
            events.add(ev);
        }
        return events;
    }

    // ==================== Content Blocks ====================
    static class CBlock {
        String type;
        StringBuilder thinking = new StringBuilder();
        StringBuilder signature = new StringBuilder();
        StringBuilder text = new StringBuilder();
        String id, name;
        StringBuilder inputJson = new StringBuilder();
    }

    // ==================== Tool Execution ====================
    static String runTool(String name, Map<String, Object> input) {
        if (name.equals("measure")) {
            String txt = (String) input.get("text");
            String unit = (String) input.get("unit");
            if (txt == null || unit == null) return "unsupported unit: " + unit;
            if (unit.equals("code_points")) {
                return String.valueOf(txt.codePointCount(0, txt.length()));
            } else if (unit.equals("utf8_bytes")) {
                return String.valueOf(txt.getBytes(StandardCharsets.UTF_8).length);
            } else if (unit.equals("utf16_units")) {
                return String.valueOf(txt.length());
            } else {
                return null; // error
            }
        } else if (name.equals("reverse")) {
            String txt = (String) input.get("text");
            if (txt == null) return "";
            int[] cps = txt.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return sb.toString();
        } else {
            return null; // unknown tool
        }
    }

    // ==================== Main ====================
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read request.json
        byte[] fileBytes = readN(new FileInputStream(dataDir + "/request.json"), (int) new File(dataDir + "/request.json").length());
        String reqText = new String(fileBytes, StandardCharsets.UTF_8);
        Map<String, Object> reqCfg = (Map<String, Object>) parseJson(reqText);

        String apiKey = (String) reqCfg.get("api_key");
        String model = (String) reqCfg.get("model");
        long maxTokens = ((Number) reqCfg.get("max_tokens")).longValue();
        long thinkingBudget = ((Number) reqCfg.get("thinking_budget")).longValue();
        String system = (String) reqCfg.get("system");
        String prompt = (String) reqCfg.get("prompt");
        List<Object> tools = (List<Object>) reqCfg.get("tools");

        // Parse URL
        URI uri = new URI(baseUrl);
        String host = uri.getHost();
        int port = uri.getPort();
        if (port < 0) port = 80;
        String basePath = uri.getPath(); // e.g. "/c/0"
        String endpoint = basePath + "/v1/messages";

        long totalInput = 0, totalOutput = 0, totalCacheRead = 0;

        // ===== Request 1 =====
        Map<String, Object> body1 = new LinkedHashMap<>();
        body1.put("model", model);
        body1.put("max_tokens", maxTokens);
        body1.put("stream", true);
        Map<String, Object> thinkingCfg = new LinkedHashMap<>();
        thinkingCfg.put("type", "enabled");
        thinkingCfg.put("budget_tokens", thinkingBudget);
        body1.put("thinking", thinkingCfg);
        body1.put("system", system);
        body1.put("tools", tools);
        List<Object> msgs1 = new ArrayList<>();
        Map<String, Object> userMsg1 = new LinkedHashMap<>();
        userMsg1.put("role", "user");
        userMsg1.put("content", prompt);
        msgs1.add(userMsg1);
        body1.put("messages", msgs1);

        byte[] bodyBytes1 = toJson(body1).getBytes(StandardCharsets.UTF_8);
        HttpResponse resp1 = httpPost(host, port, endpoint, apiKey, bodyBytes1);

        if (resp1.status != 200) {
            String errBody = new String(resp1.body, StandardCharsets.UTF_8);
            Map<String, Object> errObj = (Map<String, Object>) parseJson(errBody);
            Map<String, Object> err = (Map<String, Object>) errObj.get("error");
            System.out.println("ERROR " + resp1.status + " " + err.get("type") + ": " + err.get("message"));
            System.out.flush();
            return;
        }

        String sseText1 = new String(resp1.body, StandardCharsets.UTF_8);
        List<SseEvent> events1 = parseSse(sseText1);

        // Parse events for request 1
        Map<Integer, CBlock> blocks1 = new TreeMap<>();
        String stopReason1 = "";
        for (SseEvent ev : events1) {
            if (ev.data == null || ev.data.isEmpty()) continue;
            Map<String, Object> d = (Map<String, Object>) parseJson(ev.data);
            String type = (String) d.get("type");
            if (type == null) continue;
            switch (type) {
                case "message_start": {
                    Map<String, Object> msg = (Map<String, Object>) d.get("message");
                    Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
                    if (usage != null) {
                        if (usage.get("input_tokens") != null) totalInput += ((Number) usage.get("input_tokens")).longValue();
                        if (usage.get("cache_read_input_tokens") != null) totalCacheRead += ((Number) usage.get("cache_read_input_tokens")).longValue();
                    }
                    break;
                }
                case "content_block_start": {
                    int idx = ((Number) d.get("index")).intValue();
                    Map<String, Object> cb = (Map<String, Object>) d.get("content_block");
                    CBlock blk = new CBlock();
                    blk.type = (String) cb.get("type");
                    if (blk.type.equals("tool_use")) {
                        blk.id = (String) cb.get("id");
                        blk.name = (String) cb.get("name");
                    }
                    blocks1.put(idx, blk);
                    break;
                }
                case "content_block_delta": {
                    int idx = ((Number) d.get("index")).intValue();
                    Map<String, Object> delta = (Map<String, Object>) d.get("delta");
                    String dt = (String) delta.get("type");
                    CBlock blk = blocks1.get(idx);
                    if (blk == null) break;
                    if ("thinking_delta".equals(dt)) blk.thinking.append((String) delta.get("thinking"));
                    else if ("signature_delta".equals(dt)) blk.signature.append((String) delta.get("signature"));
                    else if ("text_delta".equals(dt)) blk.text.append((String) delta.get("text"));
                    else if ("input_json_delta".equals(dt)) blk.inputJson.append((String) delta.get("partial_json"));
                    break;
                }
                case "message_delta": {
                    Map<String, Object> delta = (Map<String, Object>) d.get("delta");
                    if (delta != null && delta.get("stop_reason") != null) stopReason1 = (String) delta.get("stop_reason");
                    Map<String, Object> usage = (Map<String, Object>) d.get("usage");
                    if (usage != null && usage.get("output_tokens") != null) totalOutput += ((Number) usage.get("output_tokens")).longValue();
                    break;
                }
                default: break;
            }
        }

        // Print request 1 transcript
        System.out.println("request 1");
        List<CBlock> orderedBlocks1 = new ArrayList<>(blocks1.values());
        for (CBlock blk : orderedBlocks1) {
            if (blk.type.equals("thinking")) {
                System.out.println("thinking " + esc(blk.thinking.toString()));
                System.out.println("signature " + esc(blk.signature.toString()));
            } else if (blk.type.equals("text")) {
                System.out.println("text " + esc(blk.text.toString()));
            } else if (blk.type.equals("tool_use")) {
                System.out.println("tool_use " + blk.id + " " + blk.name + " " + esc(blk.inputJson.toString()));
            }
        }
        System.out.println("stop_reason " + stopReason1);

        // Execute tools
        List<Map<String, Object>> toolResults = new ArrayList<>();
        for (CBlock blk : orderedBlocks1) {
            if (!blk.type.equals("tool_use")) continue;
            String rawInput = blk.inputJson.toString();
            Map<String, Object> inputObj;
            if (rawInput.isEmpty()) {
                inputObj = new LinkedHashMap<>();
            } else {
                inputObj = (Map<String, Object>) parseJson(rawInput);
            }
            String result;
            boolean isError = false;
            if (blk.name.equals("measure")) {
                String unit = (String) inputObj.get("unit");
                if (unit != null && !unit.equals("code_points") && !unit.equals("utf8_bytes") && !unit.equals("utf16_units")) {
                    result = "unsupported unit: " + unit;
                    isError = true;
                } else {
                    result = runTool("measure", inputObj);
                }
            } else if (blk.name.equals("reverse")) {
                result = runTool("reverse", inputObj);
            } else {
                result = "unknown tool: " + blk.name;
                isError = true;
            }
            System.out.println((isError ? "error " : "result ") + blk.id + " " + esc(result));
            Map<String, Object> tr = new LinkedHashMap<>();
            tr.put("type", "tool_result");
            tr.put("tool_use_id", blk.id);
            tr.put("content", result);
            if (isError) tr.put("is_error", true);
            toolResults.add(tr);
        }

        // ===== Request 2 =====
        Map<String, Object> body2 = new LinkedHashMap<>();
        body2.put("model", model);
        body2.put("max_tokens", maxTokens);
        body2.put("stream", true);
        body2.put("thinking", thinkingCfg);
        body2.put("system", system);
        body2.put("tools", tools);
        List<Object> msgs2 = new ArrayList<>();

        // user message (same as request 1)
        Map<String, Object> um2 = new LinkedHashMap<>();
        um2.put("role", "user");
        um2.put("content", prompt);
        msgs2.add(um2);

        // assistant message with content blocks
        Map<String, Object> asMsg = new LinkedHashMap<>();
        asMsg.put("role", "assistant");
        List<Object> asContent = new ArrayList<>();
        for (CBlock blk : orderedBlocks1) {
            if (blk.type.equals("thinking")) {
                Map<String, Object> cb = new LinkedHashMap<>();
                cb.put("type", "thinking");
                cb.put("thinking", blk.thinking.toString());
                cb.put("signature", blk.signature.toString());
                asContent.add(cb);
            } else if (blk.type.equals("text")) {
                Map<String, Object> cb = new LinkedHashMap<>();
                cb.put("type", "text");
                cb.put("text", blk.text.toString());
                asContent.add(cb);
            } else if (blk.type.equals("tool_use")) {
                Map<String, Object> cb = new LinkedHashMap<>();
                cb.put("type", "tool_use");
                cb.put("id", blk.id);
                cb.put("name", blk.name);
                String rawInput = blk.inputJson.toString();
                Object parsedInput = rawInput.isEmpty() ? new LinkedHashMap<>() : parseJson(rawInput);
                cb.put("input", parsedInput);
                asContent.add(cb);
            }
        }
        asMsg.put("content", asContent);
        msgs2.add(asMsg);

        // user message with tool results
        Map<String, Object> um3 = new LinkedHashMap<>();
        um3.put("role", "user");
        um3.put("content", toolResults);
        msgs2.add(um3);

        body2.put("messages", msgs2);

        byte[] bodyBytes2 = toJson(body2).getBytes(StandardCharsets.UTF_8);
        HttpResponse resp2 = httpPost(host, port, endpoint, apiKey, bodyBytes2);

        if (resp2.status != 200) {
            String errBody = new String(resp2.body, StandardCharsets.UTF_8);
            Map<String, Object> errObj = (Map<String, Object>) parseJson(errBody);
            Map<String, Object> err = (Map<String, Object>) errObj.get("error");
            System.out.println("ERROR " + resp2.status + " " + err.get("type") + ": " + err.get("message"));
            System.out.flush();
            return;
        }

        String sseText2 = new String(resp2.body, StandardCharsets.UTF_8);
        List<SseEvent> events2 = parseSse(sseText2);

        Map<Integer, CBlock> blocks2 = new TreeMap<>();
        String stopReason2 = "";
        for (SseEvent ev : events2) {
            if (ev.data == null || ev.data.isEmpty()) continue;
            Map<String, Object> d = (Map<String, Object>) parseJson(ev.data);
            String type = (String) d.get("type");
            if (type == null) continue;
            switch (type) {
                case "message_start": {
                    Map<String, Object> msg = (Map<String, Object>) d.get("message");
                    Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
                    if (usage != null) {
                        if (usage.get("input_tokens") != null) totalInput += ((Number) usage.get("input_tokens")).longValue();
                        if (usage.get("cache_read_input_tokens") != null) totalCacheRead += ((Number) usage.get("cache_read_input_tokens")).longValue();
                    }
                    break;
