                    Map<String, Object> cb = (Map<String, Object>) d.get("content_block");
                    CBlock blk = new CBlock();
                    blk.type = (String) cb.get("type");
                    if (blk.type.equals("tool_use")) {
                        blk.id = (String) cb.get("id");
                        blk.name = (String) cb.get("name");
                    }
                    blocks2.put(idx, blk);
                    break;
                }
                case "content_block_delta": {
                    int idx = ((Number) d.get("index")).intValue();
                    Map<String, Object> delta = (Map<String, Object>) d.get("delta");
                    String dt = (String) delta.get("type");
                    CBlock blk = blocks2.get(idx);
                    if (blk == null) break;
                    if ("thinking_delta".equals(dt)) blk.thinking.append((String) delta.get("thinking"));
                    else if ("signature_delta".equals(dt)) blk.signature.append((String) delta.get("signature"));
                    else if ("text_delta".equals(dt)) blk.text.append((String) delta.get("text"));
                    else if ("input_json_delta".equals(dt)) blk.inputJson.append((String) delta.get("partial_json"));
                    break;
                }
                case "message_delta": {
                    Map<String, Object> delta = (Map<String, Object>) d.get("delta");
                    if (delta != null && delta.get("stop_reason") != null) stopReason2 = (String) delta.get("stop_reason");
                    Map<String, Object> usage = (Map<String, Object>) d.get("usage");
                    if (usage != null && usage.get("output_tokens") != null) totalOutput += ((Number) usage.get("output_tokens")).longValue();
                    break;
                }
                default: break;
            }
        }

        // Print request 2 transcript
        System.out.println("request 2");
        List<CBlock> orderedBlocks2 = new ArrayList<>(blocks2.values());
        for (CBlock blk : orderedBlocks2) {
            if (blk.type.equals("thinking")) {
                System.out.println("thinking " + esc(blk.thinking.toString()));
                System.out.println("signature " + esc(blk.signature.toString()));
            } else if (blk.type.equals("text")) {
                System.out.println("text " + esc(blk.text.toString()));
            } else if (blk.type.equals("tool_use")) {
                System.out.println("tool_use " + blk.id + " " + blk.name + " " + esc(blk.inputJson.toString()));
            }
        }
        System.out.println("stop_reason " + stopReason2);

        System.out.println("usage input=" + totalInput + " output=" + totalOutput + " cache_read=" + totalCacheRead);
        System.out.flush();
    }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

const dataDir = process.argv[2];
const baseUrl = process.argv[3];

const config = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf-8'));

const outputLines: string[] = [];

function escapeStr(s: string): string {
  let result = '';
  for (const ch of s) {
    if (ch === '\\') result += '\\\\';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\r') result += '\\r';
    else if (ch === '\t') result += '\\t';
    else result += ch;
  }
  return result;
}

function makeRequest(body: any): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/v1/messages');
    const bodyStr = JSON.stringify(body);
    const bodyBuf = Buffer.from(bodyStr, 'utf-8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.port ? `${url.hostname}:${url.port}` : url.hostname,
        'Content-Length': String(bodyBuf.length),
        'x-api-key': config.api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({ status: res.statusCode!, body: Buffer.concat(chunks).toString('utf-8') });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    req.write(bodyBuf);
    req.end();
  });
}

interface SSEEvent {
  event: string;
  data: string;
}

function parseSSE(text: string): SSEEvent[] {
  const events: SSEEvent[] = [];
  let currentEvent = '';
  let currentData: string[] = [];

  const lines = text.split(/\r?\n/);

  for (const line of lines) {
    if (line === '') {
      if (currentData.length > 0) {
        events.push({ event: currentEvent, data: currentData.join('\n') });
      }
      currentEvent = '';
      currentData = [];
    } else if (line.startsWith(':')) {
      // comment, ignore
    } else {
      const colonIdx = line.indexOf(':');
      if (colonIdx === -1) continue;
      const name = line.slice(0, colonIdx);
      let value = line.slice(colonIdx + 1);
      if (value.startsWith(' ')) value = value.slice(1);

      if (name === 'event') {
        currentEvent = value;
      } else if (name === 'data') {
        currentData.push(value);
      }
    }
  }

  return events;
}

interface ContentBlock {
  type: string;
  index: number;
  thinking: string;
  signature: string;
  text: string;
  id: string;
  name: string;
  partialJson: string;
}

interface ParsedResponse {
  blocks: ContentBlock[];
  stopReason: string;
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
}

function processResponse(body: string): ParsedResponse {
  const events = parseSSE(body);
  const blocksMap = new Map<number, ContentBlock>();
  let stopReason = '';
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheReadTokens = 0;

  for (const ev of events) {
    if (ev.event === 'ping' || !ev.data) continue;

    let obj: any;
    try {
      obj = JSON.parse(ev.data);
    } catch {
      continue;
    }

    const type = obj.type;

    if (type === 'message_start') {
      const msg = obj.message;
      if (msg && msg.usage) {
        inputTokens = msg.usage.input_tokens ?? 0;
        cacheReadTokens = msg.usage.cache_read_input_tokens ?? 0;
      }
    } else if (type === 'content_block_start') {
      const idx = obj.index;
      const cb = obj.content_block;
      const block: ContentBlock = {
        type: cb.type,
        index: idx,
        thinking: '',
        signature: '',
        text: '',
        id: '',
        name: '',
        partialJson: '',
      };
      if (cb.type === 'tool_use') {
        block.id = cb.id || '';
        block.name = cb.name || '';
      }
      blocksMap.set(idx, block);
    } else if (type === 'content_block_delta') {
      const idx = obj.index;
      const delta = obj.delta;
      const block = blocksMap.get(idx);
      if (!block) continue;

      if (delta.type === 'thinking_delta') {
        block.thinking += delta.thinking ?? '';
      } else if (delta.type === 'signature_delta') {
        block.signature += delta.signature ?? '';
      } else if (delta.type === 'text_delta') {
        block.text += delta.text ?? '';
      } else if (delta.type === 'input_json_delta') {
        block.partialJson += delta.partial_json ?? '';
      }
    } else if (type === 'message_delta') {
      if (obj.delta && obj.delta.stop_reason) {
        stopReason = obj.delta.stop_reason;
      }
      if (obj.usage && obj.usage.output_tokens !== undefined) {
        outputTokens = obj.usage.output_tokens;
      }
    } else if (type === 'message_stop') {
      // end of reply
    }
  }

  const sortedBlocks = Array.from(blocksMap.values()).sort((a, b) => a.index - b.index);

  return { blocks: sortedBlocks, stopReason, inputTokens, outputTokens, cacheReadTokens };
}

function executeTool(name: string, input: any): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = input.text ?? '';
    const unit = input.unit ?? '';
    if (unit === 'code_points') {
      return { result: String([...text].length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = input.text ?? '';
    return { result: [...text].reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

function printBlocks(parsed: ParsedResponse): void {
  for (const block of parsed.blocks) {
    if (block.type === 'thinking') {
      outputLines.push(`thinking ${escapeStr(block.thinking)}`);
      outputLines.push(`signature ${escapeStr(block.signature)}`);
    } else if (block.type === 'text') {
      outputLines.push(`text ${escapeStr(block.text)}`);
    } else if (block.type === 'tool_use') {
      outputLines.push(`tool_use ${block.id} ${block.name} ${escapeStr(block.partialJson)}`);
    }
  }
  outputLines.push(`stop_reason ${parsed.stopReason}`);
}

function flushAndExit(): void {
  for (const line of outputLines) {
    process.stdout.write(line + '\n');
  }
  process.exit(0);
}

async function main(): Promise<void> {
  // Request 1
  const req1Body = {
    model: config.model,
    max_tokens: config.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: config.thinking_budget },
    system: config.system,
    tools: config.tools,
    messages: [{ role: 'user', content: config.prompt }],
  };

  outputLines.push('request 1');

  const res1 = await makeRequest(req1Body);

  if (res1.status !== 200) {
    try {
      const err = JSON.parse(res1.body);
      outputLines.push(`ERROR ${res1.status} ${err.error.type}: ${err.error.message}`);
    } catch {
      outputLines.push(`ERROR ${res1.status} unknown: ${res1.body}`);
    }
    flushAndExit();
  }

  const parsed1 = processResponse(res1.body);
  printBlocks(parsed1);

  // Execute tools and collect results
  const toolResults: any[] = [];
  for (const block of parsed1.blocks) {
    if (block.type === 'tool_use') {
      let input: any = {};
      try {
        input = JSON.parse(block.partialJson);
      } catch {
        input = {};
      }
      const { result, isError } = executeTool(block.name, input);
      if (isError) {
        outputLines.push(`error ${block.id} ${escapeStr(result)}`);
      } else {
        outputLines.push(`result ${block.id} ${escapeStr(result)}`);
      }
      const trb: any = {
        type: 'tool_result',
        tool_use_id: block.id,
        content: result,
      };
      if (isError) trb.is_error = true;
      toolResults.push(trb);
    }
  }

  // Build assistant content for request 2
  const assistantContent: any[] = [];
  for (const block of parsed1.blocks) {
    if (block.type === 'thinking') {
      assistantContent.push({
        type: 'thinking',
        thinking: block.thinking,
        signature: block.signature,
      });
    } else if (block.type === 'text') {
      assistantContent.push({
        type: 'text',
        text: block.text,
      });
    } else if (block.type === 'tool_use') {
      let input: any = {};
      try {
        input = JSON.parse(block.partialJson);
      } catch {
        input = {};
      }
      assistantContent.push({
        type: 'tool_use',
        id: block.id,
        name: block.name,
        input: input,
      });
    }
  }

  // Request 2
  const req2Body = {
    model: config.model,
    max_tokens: config.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: config.thinking_budget },
    system: config.system,
    tools: config.tools,
    messages: [
      { role: 'user', content: config.prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResults },
    ],
  };

  outputLines.push('request 2');

  const res2 = await makeRequest(req2Body);

  if (res2.status !== 200) {
    try {
      const err = JSON.parse(res2.body);
      outputLines.push(`ERROR ${res2.status} ${err.error.type}: ${err.error.message}`);
    } catch {
      outputLines.push(`ERROR ${res2.status} unknown: ${res2.body}`);
    }
    flushAndExit();
  }

  const parsed2 = processResponse(res2.body);
  printBlocks(parsed2);

  // Usage totals
  const totalInput = parsed1.inputTokens + parsed2.inputTokens;
  const totalOutput = parsed1.outputTokens + parsed2.outputTokens;
  const totalCacheRead = parsed1.cacheReadTokens + parsed2.cacheReadTokens;

  outputLines.push(`usage input=${totalInput} output=${totalOutput} cache_read=${totalCacheRead}`);

  flushAndExit();
}

main().catch((err) => {
  process.stderr.write(String(err) + '\n');
  process.exit(1);
});

import Foundation

// MARK: - Utilities

func escapeStr(_ s: String) -> String {
    var result = ""
    for c in s {
        switch c {
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default: result.append(c)
        }
    }
    return result
}

func parseURL(_ urlStr: String) -> (host: String, port: Int, pathPrefix: String) {
    var rest = urlStr
    if rest.hasPrefix("http://") { rest = String(rest.dropFirst(7)) }
    else if rest.hasPrefix("https://") { rest = String(rest.dropFirst(8)) }
    let slashIdx = rest.firstIndex(of: "/")
    let hostPort: String
    let pathPrefix: String
    if let idx = slashIdx {
        hostPort = String(rest[..<idx])
        pathPrefix = String(rest[idx...])
    } else {
        hostPort = rest
        pathPrefix = ""
    }
    let colonIdx = hostPort.lastIndex(of: ":")
    let host: String
    let port: Int
    if let idx = colonIdx {
        host = String(hostPort[..<idx])
        port = Int(hostPort[hostPort.index(after: idx)...])!
    } else {
        host = hostPort
        port = 80
    }
    return (host, port, pathPrefix)
}

// MARK: - Networking

func createConnectedSocket(host: String, port: Int) -> Int32 {
    var hints = addrinfo(
        ai_flags: 0,
        ai_family: AF_INET,
        ai_socktype: SOCK_STREAM,
        ai_protocol: IPPROTO_TCP,
        ai_addrlen: 0,
        ai_canonname: nil,
        ai_addr: nil,
        ai_next: nil
    )
    var res: UnsafeMutablePointer<addrinfo>?
    let status = getaddrinfo(host, String(port), &hints, &res)
    guard status == 0, let addrInfo = res else {
        fatalError("getaddrinfo failed")
    }
    defer { freeaddrinfo(res) }
    let sock = socket(addrInfo.pointee.ai_family, addrInfo.pointee.ai_socktype, addrInfo.pointee.ai_protocol)
    guard sock >= 0 else { fatalError("socket() failed") }
    let ret = connect(sock, addrInfo.pointee.ai_addr, addrInfo.pointee.ai_addrlen)
    guard ret == 0 else { close(sock); fatalError("connect() failed") }
    return sock
}

func readAll(_ fd: Int32) -> Data {
    var data = Data()
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = read(fd, &buf, buf.count)
        if n <= 0 { break }
        data.append(contentsOf: buf[0..<n])
    }
    return data
}

func sendAll(_ fd: Int32, _ data: Data) {
    data.withUnsafeBytes { ptr in
        var sent = 0
        while sent < data.count {
            let n = write(fd, ptr.baseAddress!.advanced(by: sent), data.count - sent)
            if n <= 0 { break }
            sent += n
        }
    }
}

func decodeChunked(_ data: Data) -> Data {
    var result = Data()
    let bytes = [UInt8](data)
    var pos = 0
    while pos < bytes.count {
        var sizeStr = ""
        while pos < bytes.count && bytes[pos] != 0x0D {
            if bytes[pos] == 0x3B { // ';' chunk-ext
                while pos < bytes.count && bytes[pos] != 0x0D { pos += 1 }
                break
            }
            sizeStr.append(Character(UnicodeScalar(bytes[pos])))
            pos += 1
        }
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
        let chunkSize = Int(sizeStr, radix: 16) ?? 0
        if chunkSize == 0 { break }
        if pos + chunkSize <= bytes.count {
            result.append(contentsOf: bytes[pos..<(pos + chunkSize)])
        }
        pos += chunkSize
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
    }
    return result
}

struct HttpResponse {
    let status: Int
    let headers: [String: String]
    let body: Data
}

func httpPost(host: String, port: Int, path: String, extraHeaders: [(String, String)], body: Data) -> HttpResponse {
    let sock = createConnectedSocket(host: host, port: port)
    var reqStr = "POST \(path) HTTP/1.1\r\n"
    reqStr += "Host: \(host):\(port)\r\n"
    for (k, v) in extraHeaders {
        reqStr += "\(k): \(v)\r\n"
    }
    reqStr += "Content-Length: \(body.count)\r\n"
    reqStr += "\r\n"
    sendAll(sock, reqStr.data(using: .utf8)!)
    sendAll(sock, body)
    let allData = readAll(sock)
    close(sock)

    let bytes = [UInt8](allData)
    var headerEnd = -1
    if bytes.count >= 4 {
        for i in 0...(bytes.count - 4) {
            if bytes[i] == 0x0D && bytes[i+1] == 0x0A && bytes[i+2] == 0x0D && bytes[i+3] == 0x0A {
                headerEnd = i
                break
            }
        }
    }
    guard headerEnd >= 0 else { fatalError("No header terminator") }

    let headerStr = String(bytes: bytes[0..<headerEnd], encoding: .utf8) ?? ""
    let bodyBytes = Data(bytes[(headerEnd + 4)...])

    let lines = headerStr.components(separatedBy: "\r\n")
    let statusParts = lines[0].components(separatedBy: " ")
    let statusCode = Int(statusParts[1]) ?? 0

    var respHeaders: [String: String] = [:]
    for i in 1..<lines.count {
        if let ci = lines[i].firstIndex(of: ":") {
            let key = String(lines[i][..<ci]).lowercased()
            let val = String(lines[i][lines[i].index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            respHeaders[key] = val
        }
    }

    var finalBody = bodyBytes
    if respHeaders["transfer-encoding"]?.lowercased().contains("chunked") == true {
        finalBody = decodeChunked(bodyBytes)
    }
    return HttpResponse(status: statusCode, headers: respHeaders, body: finalBody)
}

// MARK: - SSE Parsing

struct SSEEvent {
    let event: String
    let data: String
}

func parseSSE(_ data: Data) -> [SSEEvent] {
    var events: [SSEEvent] = []
    let bytes = [UInt8](data)
    var lines: [Data] = []
    var lineStart = 0
    var i = 0
    while i < bytes.count {
        if bytes[i] == 0x0D {
            lines.append(Data(bytes[lineStart..<i]))
            if i + 1 < bytes.count && bytes[i+1] == 0x0A { i += 1 }
            lineStart = i + 1
        } else if bytes[i] == 0x0A {
            lines.append(Data(bytes[lineStart..<i]))
            lineStart = i + 1
        }
        i += 1
    }
    if lineStart < bytes.count {
        lines.append(Data(bytes[lineStart..<bytes.count]))
    }

    var currentEvent = ""
    var currentData: [String] = []
    for lineData in lines {
        let line = String(data: lineData, encoding: .utf8) ?? ""
        if line.isEmpty {
            if !currentEvent.isEmpty || !currentData.isEmpty {
                events.append(SSEEvent(event: currentEvent, data: currentData.joined(separator: "\n")))
            }
            currentEvent = ""
            currentData = []
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            currentEvent = v
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            currentData.append(v)
        }
    }
    return events
}

// MARK: - Content Block Accumulation

struct ContentBlock {
    var type = ""
    var id = ""
    var name = ""
    var thinking = ""
    var signature = ""
    var text = ""
    var partialJson = ""
    var input: [String: Any] = [:]
}

struct StreamResult {
    var blocks: [ContentBlock] = []
    var stopReason = ""
    var inputTokens = 0
    var outputTokens = 0
    var cacheRead = 0
}

func processStream(_ data: Data) -> StreamResult {
    let events = parseSSE(data)
    var blocks: [Int: ContentBlock] = [:]
    var result = StreamResult()

    for ev in events {
        guard let jData = ev.data.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: jData) as? [String: Any] else { continue }
        let type = json["type"] as? String ?? ev.event

        switch type {
        case "message_start":
            if let msg = json["message"] as? [String: Any],
               let usage = msg["usage"] as? [String: Any] {
                result.inputTokens += usage["input_tokens"] as? Int ?? 0
                result.cacheRead += usage["cache_read_input_tokens"] as? Int ?? 0
            }
        case "content_block_start":
            let idx = json["index"] as? Int ?? 0
            if let cb = json["content_block"] as? [String: Any] {
                var blk = ContentBlock()
                blk.type = cb["type"] as? String ?? ""
                blk.id = cb["id"] as? String ?? ""
                blk.name = cb["name"] as? String ?? ""
                blocks[idx] = blk
            }
        case "content_block_delta":
            let idx = json["index"] as? Int ?? 0
            guard var blk = blocks[idx], let delta = json["delta"] as? [String: Any] else { continue }
            let dt = delta["type"] as? String ?? ""
            switch dt {
            case "thinking_delta":
                blk.thinking += delta["thinking"] as? String ?? ""
            case "signature_delta":
                blk.signature += delta["signature"] as? String ?? ""
            case "text_delta":
                blk.text += delta["text"] as? String ?? ""
            case "input_json_delta":
                blk.partialJson += delta["partial_json"] as? String ?? ""
            default: break
            }
            blocks[idx] = blk
        case "content_block_stop":
            let idx = json["index"] as? Int ?? 0
            if var blk = blocks[idx], blk.type == "tool_use" {
                if blk.partialJson.isEmpty {
                    blk.input = [:]
                } else if let jD = blk.partialJson.data(using: .utf8),
                          let parsed = try? JSONSerialization.jsonObject(with: jD) as? [String: Any] {
                    blk.input = parsed
                }
                blocks[idx] = blk
            }
        case "message_delta":
            if let delta = json["delta"] as? [String: Any] {
                result.stopReason = delta["stop_reason"] as? String ?? ""
            }
            if let usage = json["usage"] as? [String: Any] {
                result.outputTokens += usage["output_tokens"] as? Int ?? 0
            }
        case "message_stop":
            break
        default:
            break
        }
    }

    result.blocks = blocks.keys.sorted().compactMap { blocks[$0] }
    return result
}

// MARK: - Tool Execution

func executeTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points": return (String(text.unicodeScalars.count), false)
        case "utf8_bytes": return (String(text.utf8.count), false)
        case "utf16_units": return (String(text.utf16.count), false)
        default: return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        let rev = String(String.UnicodeScalarView(text.unicodeScalars.reversed()))
        return (rev, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 3 else {
    FileHandle.standardError.write("Usage: main <data_dir> <base_url>\n".data(using: .utf8)!)
    exit(1)
}
let dataDir = args[1]
let baseUrl = args[2]

let requestPath = "\(dataDir)/request.json"
let fileData = try! Data(contentsOf: URL(fileURLWithPath: requestPath))
let reqJson = try! JSONSerialization.jsonObject(with: fileData) as! [String: Any]

let apiKey = reqJson["api_key"] as! String
