def read_varint(data, offset):
    result = 0
    for i in range(9):
        byte = data[offset + i]
        if i < 8:
            result = (result << 7) | (byte & 0x7F)
            if not (byte & 0x80):
                return result, offset + i + 1
        else:
            result = (result << 8) | byte
            return result, offset + i + 1
    return result, offset + 9


def get_value(data, offset, serial_type):
    if serial_type == 0:
        return None, offset
    elif serial_type == 1:
        val = struct.unpack_from('>b', data, offset)[0]
        return val, offset + 1
    elif serial_type == 2:
        val = struct.unpack_from('>h', data, offset)[0]
        return val, offset + 2
    elif serial_type == 3:
        val = int.from_bytes(data[offset:offset+3], 'big', signed=True)
        return val, offset + 3
    elif serial_type == 4:
        val = struct.unpack_from('>i', data, offset)[0]
        return val, offset + 4
    elif serial_type == 5:
        val = int.from_bytes(data[offset:offset+6], 'big', signed=True)
        return val, offset + 6
    elif serial_type == 6:
        val = struct.unpack_from('>q', data, offset)[0]
        return val, offset + 8
    elif serial_type == 7:
        val = struct.unpack_from('>d', data, offset)[0]
        return val, offset + 8
    elif serial_type == 8:
        return 0, offset
    elif serial_type == 9:
        return 1, offset
    elif serial_type >= 12:
        n = (serial_type - 12) // 2
        if serial_type % 2 == 0:
            return ('BLOB', data[offset:offset+n]), offset + n
        else:
            return ('TEXT', data[offset:offset+n]), offset + n
    else:
        return None, offset


def format_real(value):
    if value == 0.0:
        if math.copysign(1.0, value) < 0:
            return '-0.0'
        return '0.0'
    sign = '-' if math.copysign(1.0, value) < 0 else ''
    d = Decimal(abs(value))
    s = str(d)
    if '.' in s:
        int_part, frac_part = s.split('.')
        frac_part = frac_part.rstrip('0')
        if not frac_part:
            frac_part = '0'
    else:
        int_part = s
        frac_part = '0'
    return sign + int_part + '.' + frac_part


def escape_text(data):
    result = []
    i = 0
    while i < len(data):
        b = data[i]
        if b == 0x5C:
            result.append('\\\\')
            i += 1
        elif b == 0x22:
            result.append('\\"')
            i += 1
        elif b == 0x0A:
            result.append('\\n')
            i += 1
        elif b == 0x0D:
            result.append('\\r')
            i += 1
        elif b == 0x09:
            result.append('\\t')
            i += 1
        elif b < 0x20:
            result.append(f'\\x{b:02X}')
            i += 1
        elif b == 0x7F:
            result.append('\\x7F')
            i += 1
        elif b < 0x80:
            result.append(chr(b))
            i += 1
        else:
            if b < 0xC0:
                result.append(chr(b))
                i += 1
            elif b < 0xE0:
                result.append(data[i:i+2].decode('utf-8'))
                i += 2
            elif b < 0xF0:
                result.append(data[i:i+3].decode('utf-8'))
                i += 3
            else:
                result.append(data[i:i+4].decode('utf-8'))
                i += 4
    return ''.join(result)


def format_value(val):
    if val is None:
        return 'NULL'
    if isinstance(val, bool):
        return str(int(val))
    if isinstance(val, int):
        return str(val)
    if isinstance(val, float):
        return format_real(val)
    if isinstance(val, tuple):
        vtype, vdata = val
        if vtype == 'TEXT':
            if len(vdata) <= 100:
                return '"' + escape_text(vdata) + '"'
            else:
                crc = zlib.crc32(vdata) & 0xFFFFFFFF
                return f'<TEXT len={len(vdata)} crc32={crc:08x}>'
        elif vtype == 'BLOB':
            if len(vdata) <= 100:
                return "X'" + vdata.hex().upper() + "'"
            else:
                crc = zlib.crc32(vdata) & 0xFFFFFFFF
                return f'<BLOB len={len(vdata)} crc32={crc:08x}>'
    return str(val)


def extract_text(val):
    if isinstance(val, tuple) and val[0] == 'TEXT':
        return val[1].decode('utf-8')
    return val


def parse_create_table(sql_text):
    if sql_text is None:
        return []
    s = sql_text
    # Find the first '(' not inside double quotes
    in_quotes = False
    open_paren = -1
    for i, c in enumerate(s):
        if c == '"' and not in_quotes:
            in_quotes = True
        elif c == '"' and in_quotes:
            in_quotes = False
        elif c == '(' and not in_quotes:
            open_paren = i
            break
