    depth = 0
    in_quotes = False
    current = []
    for c in defs_str:
        if c == '"' and not in_quotes:
            in_quotes = True
            current.append(c)
        elif c == '"' and in_quotes:
            in_quotes = False
            current.append(c)
        elif not in_quotes:
            if c == '(':
                depth += 1
                current.append(c)
            elif c == ')':
                depth -= 1
                current.append(c)
            elif c == ',' and depth == 0:
                defs.append(''.join(current))
                current = []
            else:
                current.append(c)
        else:
            current.append(c)
    if current:
        defs.append(''.join(current))

    columns = []
    for defn in defs:
        defn = defn.strip()
        if not defn:
            continue
        if defn[0] == '"':
            end = defn.index('"', 1)
            col_name = defn[1:end]
            rest = defn[end+1:]
        else:
            j = 0
            while j < len(defn) and defn[j] not in (' ', '\t', '\n', '\r', '('):
