        }
        Jv::Arr(items)
    }
    fn parse_str(&mut self) -> String {
        self.pos += 1; // "
        let mut out = Vec::new();
        loop {
            if self.pos >= self.s.len() { break; }
            let c = self.s[self.pos];
            self.pos += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                if self.pos >= self.s.len() { break; }
                let e = self.s[self.pos]; self.pos += 1;
                match e {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'u' => {
                        let cp = self.read_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            // high surrogate
                            if self.pos + 1 < self.s.len() && self.s[self.pos] == b'\\' && self.s[self.pos+1] == b'u' {
                                self.pos += 2;
                                let lo = self.read_hex4();
                                if lo >= 0xDC00 && lo <= 0xDFFF {
                                    let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                    self.push_utf8(&mut out, full);
                                } else {
                                    self.push_utf8(&mut out, cp);
                                    self.push_utf8(&mut out, lo);
                                }
                            } else {
                                self.push_utf8(&mut out, cp);
                            }
                        } else {
                            self.push_utf8(&mut out, cp);
                        }
                    }
                    _ => { out.push(b'\\'); out.push(e); }
                }
            } else {
                out.push(c);
            }
        }
        String::from_utf8_lossy(&out).into_owned()
    }
    fn read_hex4(&mut self) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..4 {
            let c = self.s[self.pos] as char;
            self.pos += 1;
            v = v * 16 + c.to_digit(16).unwrap_or(0);
        }
        v
    }
    fn push_utf8(&self, out: &mut Vec<u8>, cp: u32) {
        let ch = char::from_u32(cp).unwrap_or('\u{FFFD}');
        let mut buf = [0u8; 4];
        let s = ch.encode_utf8(&mut buf);
        out.extend_from_slice(s.as_bytes());
    }
    fn parse_num(&mut self) -> Jv {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.s.len() && (self.s[self.pos].is_ascii_digit() || self.s[self.pos] == b'.' || self.s[self.pos] == b'e' || self.s[self.pos] == b'E' || self.s[self.pos] == b'+' || self.s[self.pos] == b'-') {
            self.pos += 1;
        }
        Jv::Num(String::from_utf8_lossy(&self.s[start..self.pos]).into_owned())
    }
}

// ─── JSON Serializer ──────────────────────────────────────────────────────────

fn json_escape_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => { out.push_str(&format!("\\u{:04x}", c as u32)); }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn ser_json(v: &Jv, out: &mut String) {
    match v {
        Jv::Null => out.push_str("null"),
        Jv::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Jv::Num(s) => out.push_str(s),
        Jv::Str(s) => json_escape_str(s, out),
        Jv::Arr(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_json(item, out);
            }
            out.push(']');
        }
        Jv::Obj(pairs) => {
            out.push('{');
            for (i, (k, v)) in pairs.iter().enumerate() {
                if i > 0 { out.push(','); }
                json_escape_str(k, out);
                out.push(':');
                ser_json(v, out);
            }
            out.push('}');
        }
    }
}

// ─── Output Escaping ──────────────────────────────────────────────────────────

fn esc(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out
}

// ─── HTTP Client ──────────────────────────────────────────────────────────────

struct HttpResp {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn http_post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> HttpResp {
    let addr = format!("{}:{}", host, port);
    let mut sock = TcpStream::connect(&addr).expect("connect failed");

    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        path, host, body.len(), api_key, body
    );
    sock.write_all(req.as_bytes()).expect("write failed");
    sock.flush().expect("flush failed");

    // Read all bytes until EOF
    let mut raw = Vec::new();
    sock.read_to_end(&mut raw).expect("read failed");

    // Parse HTTP response
    let header_end = find_subsequence(&raw, b"\r\n\r\n").expect("no header end");
    let header_bytes = &raw[..header_end];
    let body_start = header_end + 4;

    let header_str = String::from_utf8_lossy(header_bytes).into_owned();
    let mut lines = header_str.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);

    let mut headers = Vec::new();
    for line in lines {
        if let Some(idx) = line.find(':') {
            let name = line[..idx].trim().to_lowercase();
            let val = line[idx+1..].trim().to_string();
            headers.push((name, val));
        }
    }

    let body_data = &raw[body_start..];
    let is_chunked = headers.iter().any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));

    let body = if is_chunked {
        decode_chunked(body_data)
    } else {
        body_data.to_vec()
    };

    HttpResp { status, headers, body }
}

fn find_subsequence(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack.windows(needle.len()).position(|w| w == needle)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut pos = 0;
    loop {
        // Read chunk size line
        let line_end = find_subsequence(&data[pos..], b"\r\n");
        let line_end = match line_end {
            Some(e) => pos + e,
            None => break,
        };
        let size_str = String::from_utf8_lossy(&data[pos..line_end]).into_owned();
        let size_str = size_str.trim();
        // Handle chunk extensions (ignore after ';')
        let size_str = size_str.split(';').next().unwrap_or("0").trim();
        let chunk_size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        pos = line_end + 2; // skip \r\n

        if chunk_size == 0 { break; }

        // Read chunk data
        if pos + chunk_size <= data.len() {
            out.extend_from_slice(&data[pos..pos+chunk_size]);
            pos += chunk_size;
        } else {
            out.extend_from_slice(&data[pos..]);
            break;
        }

        // Skip trailing \r\n after chunk data
        if pos + 2 <= data.len() && data[pos] == b'\r' && data[pos+1] == b'\n' {
            pos += 2;
        }
    }
    out
}

// ─── SSE Parser ───────────────────────────────────────────────────────────────

struct SseEvent {
    event: String,
    data: String,
}

fn parse_sse(data: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(data).into_owned();
    let mut events = Vec::new();
    let mut event_name = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let mut has_data = false;

    let lines = split_sse_lines(&text);

    for line in lines {
        if line.is_empty() {
            // Blank line: dispatch event
            if has_data {
                events.push(SseEvent {
                    event: event_name.clone(),
                    data: data_lines.join("\n"),
                });
            }
            event_name.clear();
            data_lines.clear();
            has_data = false;
        } else if line.starts_with(':') {
            // Comment, ignore
        } else if line.starts_with("event:") {
            let val = &line[6..];
            event_name = if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() };
        } else if line.starts_with("data:") {
            let val = &line[5..];
            let v = if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() };
            data_lines.push(v);
            has_data = true;
        }
        // Ignore other fields (id:, retry:, etc.)
    }

    events
}

fn split_sse_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let bytes = text.as_bytes();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            let mut end = i;
            if end > start && bytes[end - 1] == b'\r' { end -= 1; }
            lines.push(String::from_utf8_lossy(&bytes[start..end]).into_owned());
            start = i + 1;
        }
        i += 1;
    }
    if start < bytes.len() {
        lines.push(String::from_utf8_lossy(&bytes[start..]).into_owned());
    }
    lines
}

// ─── Content Block Accumulation ───────────────────────────────────────────────

#[derive(Clone)]
enum Block {
    Thinking { thinking: String, signature: String },
    Text { text: String },
    ToolUse { id: String, name: String, raw_input: String, parsed_input: Jv },
}

struct Reply {
    blocks: Vec<Block>,
    stop_reason: String,
    input_tokens: i64,
    output_tokens: i64,
    cache_read_tokens: i64,
}

fn process_sse_events(events: &[SseEvent]) -> Reply {
    let mut blocks: Vec<Block> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens: i64 = 0;
    let mut output_tokens: i64 = 0;
    let mut cache_read_tokens: i64 = 0;

    // Track per-index data
    let mut block_types: Vec<String> = Vec::new();
    let mut thinking_texts: Vec<String> = Vec::new();
    let mut signatures: Vec<String> = Vec::new();
    let mut texts: Vec<String> = Vec::new();
    let mut tool_ids: Vec<String> = Vec::new();
    let mut tool_names: Vec<String> = Vec::new();
    let mut tool_raw_inputs: Vec<String> = Vec::new();

    for ev in events {
        let data = match Jp::new(&ev.data).parse() {
            Jv::Obj(_) => Jp::new(&ev.data).parse(),
            _ => Jv::Null,
        };
        // Re-parse (the match above consumed it)
        let data = Jp::new(&ev.data).parse();

        match ev.event.as_str() {
            "message_start" => {
                if let Some(msg) = data.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        if let Some(v) = usage.get("input_tokens") { input_tokens = v.as_num_str().parse().unwrap_or(0); }
                        if let Some(v) = usage.get("cache_read_input_tokens") { cache_read_tokens = v.as_num_str().parse().unwrap_or(0); }
                    }
                }
            }
            "content_block_start" => {
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                let cb = data.get("content_block").unwrap_or(&Jv::Null);
                let btype = cb.get("type").map(|v| v.as_str().to_string()).unwrap_or_default();

                while block_types.len() <= idx {
                    block_types.push(String::new());
                    thinking_texts.push(String::new());
                    signatures.push(String::new());
                    texts.push(String::new());
                    tool_ids.push(String::new());
                    tool_names.push(String::new());
                    tool_raw_inputs.push(String::new());
                }

                block_types[idx] = btype.clone();
                if btype == "tool_use" {
                    tool_ids[idx] = cb.get("id").map(|v| v.as_str().to_string()).unwrap_or_default();
                    tool_names[idx] = cb.get("name").map(|v| v.as_str().to_string()).unwrap_or_default();
                }
            }
            "content_block_delta" => {
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                let delta = data.get("delta").unwrap_or(&Jv::Null);
                let dtype = delta.get("type").map(|v| v.as_str()).unwrap_or("");

                while thinking_texts.len() <= idx {
                    thinking_texts.push(String::new());
                    signatures.push(String::new());
                    texts.push(String::new());
                    tool_raw_inputs.push(String::new());
                }

                match dtype {
                    "thinking_delta" => {
                        if let Some(t) = delta.get("thinking") { thinking_texts[idx].push_str(t.as_str()); }
                    }
                    "signature_delta" => {
                        if let Some(s) = delta.get("signature") { signatures[idx].push_str(s.as_str()); }
                    }
                    "text_delta" => {
                        if let Some(t) = delta.get("text") { texts[idx].push_str(t.as_str()); }
                    }
                    "input_json_delta" => {
                        if let Some(t) = delta.get("partial_json") { tool_raw_inputs[idx].push_str(t.as_str()); }
                    }
                    _ => {}
                }
            }
            "content_block_stop" => {
                // finalize block
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                if idx < block_types.len() {
                    match block_types[idx].as_str() {
                        "thinking" => blocks.push(Block::Thinking {
                            thinking: thinking_texts[idx].clone(),
                            signature: signatures[idx].clone(),
                        }),
                        "text" => blocks.push(Block::Text {
                            text: texts[idx].clone(),
                        }),
                        "tool_use" => {
                            let raw = tool_raw_inputs[idx].clone();
                            let parsed = if raw.is_empty() {
                                Jv::Obj(vec![])
                            } else {
                                Jp::new(&raw).parse()
                            };
                            blocks.push(Block::ToolUse {
                                id: tool_ids[idx].clone(),
                                name: tool_names[idx].clone(),
                                raw_input: raw,
                                parsed_input: parsed,
                            });
                        }
                        _ => {}
                    }
                }
            }
            "message_delta" => {
                if let Some(d) = data.get("delta") {
                    if let Some(sr) = d.get("stop_reason") {
                        stop_reason = sr.as_str().to_string();
                    }
                }
                if let Some(usage) = data.get("usage") {
                    if let Some(v) = usage.get("output_tokens") { output_tokens = v.as_num_str().parse().unwrap_or(0); }
                }
            }
            _ => {} // ping, message_stop, etc.
        }
    }

    Reply { blocks, stop_reason, input_tokens, output_tokens, cache_read_tokens }
}

// ─── Tool Execution ───────────────────────────────────────────────────────────

fn execute_tool(name: &str, input: &Jv) -> (String, bool) {
    match name {
        "measure" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let unit = input.get("unit").map(|v| v.as_str().to_string()).unwrap_or_default();
            match unit.as_str() {
                "code_points" => {
                    let count = text.chars().count();
                    (count.to_string(), false)
                }
                "utf8_bytes" => {
                    let count = text.len();
                    (count.to_string(), false)
                }
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let reversed: String = text.chars().rev().collect();
            (reversed, false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: main <data_dir> <base_url>");
        std::process::exit(1);
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    // Read request.json
    let req_path = format!("{}/request.json", data_dir);
    let req_content = fs::read_to_string(&req_path).expect("cannot read request.json");
    let req_json = Jp::new(&req_content).parse();

    let api_key = req_json.get("api_key").map(|v| v.as_str().to_string()).unwrap_or_default();
    let model = req_json.get("model").map(|v| v.as_str().to_string()).unwrap_or_default();
    let max_tokens_str = req_json.get("max_tokens").map(|v| v.as_num_str().to_string()).unwrap_or_else(|| "8000".to_string());
    let thinking_budget_str = req_json.get("thinking_budget").map(|v| v.as_num_str().to_string()).unwrap_or_else(|| "2048".to_string());
    let system = req_json.get("system").map(|v| v.as_str().to_string()).unwrap_or_default();
    let prompt = req_json.get("prompt").map(|v| v.as_str().to_string()).unwrap_or_default();
    let tools = req_json.get("tools").cloned().unwrap_or(Jv::Arr(vec![]));

    // Parse URL
    let url = base_url.strip_prefix("http://").unwrap_or(base_url);
    let (host_port, path) = match url.find('/') {
        Some(idx) => (&url[..idx], &url[idx..]),
        None => (url, ""),
    };
    let (host, port) = match host_port.rfind(':') {
        Some(idx) => (&host_port[..idx], host_port[idx+1..].parse::<u16>().unwrap_or(80)),
        None => (host_port, 80u16),
    };
    let endpoint = format!("{}/v1/messages", path);

    // Build request 1 body
    let body1 = build_request_body(&model, &max_tokens_str, &thinking_budget_str, &system, &tools, 1, &prompt, &[], &[]);

    // Send request 1
    println!("request 1");
    let resp1 = http_post(host, port, &endpoint, &api_key, &body1);

    if resp1.status != 200 {
        let body_str = String::from_utf8_lossy(&resp1.body).into_owned();
        let err_json = Jp::new(&body_str).parse();
        let etype = err_json.get("error").and_then(|e| e.get("type")).map(|v| v.as_str().to_string()).unwrap_or_default();
        let emsg = err_json.get("error").and_then(|e| e.get("message")).map(|v| v.as_str().to_string()).unwrap_or_default();
        println!("ERROR {} {}: {}", resp1.status, etype, emsg);
        return;
    }

    let events1 = parse_sse(&resp1.body);
    let reply1 = process_sse_events(&events1);

    // Print reply 1
    print_reply(&reply1);

    // Execute tools
    let tool_uses: Vec<&Block> = reply1.blocks.iter().filter(|b| matches!(b, Block::ToolUse{..})).collect();
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();

    for block in &tool_uses {
        if let Block::ToolUse { id, name, parsed_input, .. } = block {
            let (result, is_error) = execute_tool(name, parsed_input);
            tool_results.push((id.clone(), result.clone(), is_error));
            if is_error {
                println!("error {} {}", id, esc(&result));
            } else {
                println!("result {} {}", id, esc(&result));
            }
        }
    }

    // Build request 2 body
    let body2 = build_request_body(&model, &max_tokens_str, &thinking_budget_str, &system, &tools, 2, &prompt, &reply1.blocks, &tool_results);

    // Send request 2
    println!("request 2");
    let resp2 = http_post(host, port, &endpoint, &api_key, &body2);

    if resp2.status != 200 {
        let body_str = String::from_utf8_lossy(&resp2.body).into_owned();
        let err_json = Jp::new(&body_str).parse();
        let etype = err_json.get("error").and_then(|e| e.get("type")).map(|v| v.as_str().to_string()).unwrap_or_default();
        let emsg = err_json.get("error").and_then(|e| e.get("message")).map(|v| v.as_str().to_string()).unwrap_or_default();
        println!("ERROR {} {}: {}", resp2.status, etype, emsg);
        return;
    }

    let events2 = parse_sse(&resp2.body);
    let reply2 = process_sse_events(&events2);

    // Print reply 2
    print_reply(&reply2);

    // Print usage
    let total_input = reply1.input_tokens + reply2.input_tokens;
    let total_output = reply1.output_tokens + reply2.output_tokens;
    let total_cache = reply1.cache_read_tokens + reply2.cache_read_tokens;
    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache);
}

fn print_reply(reply: &Reply) {
    for block in &reply.blocks {
        match block {
            Block::Thinking { thinking, signature } => {
                println!("thinking {}", esc(thinking));
                println!("signature {}", esc(signature));
            }
            Block::Text { text } => {
                println!("text {}", esc(text));
            }
            Block::ToolUse { id, name, raw_input, .. } => {
                println!("tool_use {} {} {}", esc(id), esc(name), esc(raw_input));
            }
        }
    }
    println!("stop_reason {}", reply.stop_reason);
}

fn build_request_body(
    model: &str, max_tokens: &str, thinking_budget: &str,
    system: &str, tools: &Jv, which: i32,
    prompt: &str, blocks: &[Block], tool_results: &[(String, String, bool)],
) -> String {
    let mut out = String::from('{');

    out.push_str("\"model\":");
    json_escape_str(model, &mut out);

    out.push_str(",\"max_tokens\":");
    out.push_str(max_tokens);

    out.push_str(",\"stream\":true");

    out.push_str(",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    out.push_str(thinking_budget);
    out.push('}');

    out.push_str(",\"system\":");
    json_escape_str(system, &mut out);

    out.push_str(",\"tools\":");
    ser_json(tools, &mut out);

    out.push_str(",\"messages\":[");

    // User message
    out.push_str("{\"role\":\"user\",\"content\":");
    json_escape_str(prompt, &mut out);
    out.push('}');

    if which == 2 {
        // Assistant message
        out.push_str(",{\"role\":\"assistant\",\"content\":[");
        for (i, block) in blocks.iter().enumerate() {
            if i > 0 { out.push(','); }
            match block {
                Block::Thinking { thinking, signature } => {
                    out.push_str("{\"type\":\"thinking\",\"thinking\":");
                    json_escape_str(thinking, &mut out);
                    out.push_str(",\"signature\":");
                    json_escape_str(signature, &mut out);
                    out.push('}');
                }
                Block::Text { text } => {
                    out.push_str("{\"type\":\"text\",\"text\":");
                    json_escape_str(text, &mut out);
                    out.push('}');
                }
                Block::ToolUse { id, name, parsed_input, .. } => {
                    out.push_str("{\"type\":\"tool_use\",\"id\":");
                    json_escape_str(id, &mut out);
                    out.push_str(",\"name\":");
                    json_escape_str(name, &mut out);
                    out.push_str(",\"input\":");
                    ser_json(parsed_input, &mut out);
                    out.push('}');
                }
            }
        }
        out.push_str("]}");

        // Tool results user message
        out.push_str(",{\"role\":\"user\",\"content\":[");
        for (i, (id, result, is_error)) in tool_results.iter().enumerate() {
            if i > 0 { out.push(','); }
            out.push_str("{\"type\":\"tool_result\",\"tool_use_id\":");
            json_escape_str(id, &mut out);
            out.push_str(",\"content\":");
            json_escape_str(result, &mut out);
            if *is_error {
                out.push_str(",\"is_error\":true");
            }
            out.push('}');
        }
        out.push_str("]}");
    }

    out.push_str("]}");
    out
}

