use std::env;
use std::fs;
use std::io::{self, Write};

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut val: u64 = 0;
    for i in 0..9 {
        let b = data[*pos];
        *pos += 1;
        if i < 8 {
            if b < 0x80 {
                val = (val << 7) | (b as u64);
                return val;
            }
            val = (val << 7) | ((b & 0x7F) as u64);
        } else {
            val = (val << 8) | (b as u64);
            return val;
        }
    }
    unreachable!()
}

fn read_signed_int(data: &[u8], pos: &mut usize, n: usize) -> i64 {
    let mut val: i64 = 0;
    for _ in 0..n {
        val = (val << 8) | (data[*pos] as i64);
        *pos += 1;
    }
    let shift = 64 - (n * 8);
    (val << shift) >> shift
}

fn read_value(data: &[u8], pos: &mut usize, st: u64) -> Value {
    match st {
        0 => Value::Null,
        1 => Value::Integer(read_signed_int(data, pos, 1)),
        2 => Value::Integer(read_signed_int(data, pos, 2)),
        3 => Value::Integer(read_signed_int(data, pos, 3)),
        4 => Value::Integer(read_signed_int(data, pos, 4)),
        5 => Value::Integer(read_signed_int(data, pos, 6)),
        6 => Value::Integer(read_signed_int(data, pos, 8)),
        7 => {
            let mut bytes = [0u8; 8];
            bytes.copy_from_slice(&data[*pos..*pos + 8]);
            *pos += 8;
            Value::Real(f64::from_be_bytes(bytes))
        }
        8 => Value::Integer(0),
        9 => Value::Integer(1),
        n if n >= 12 && n % 2 == 0 => {
            let len = ((n - 12) / 2) as usize;
            let bytes = data[*pos..*pos + len].to_vec();
            *pos += len;
            Value::Blob(bytes)
        }
        n if n >= 13 && n % 2 == 1 => {
            let len = ((n - 13) / 2) as usize;
            let bytes = data[*pos..*pos + len].to_vec();
            *pos += len;
            Value::Text(bytes)
        }
        _ => Value::Null,
    }
}

fn parse_record(data: &[u8], num_columns: usize) -> Vec<Value> {
    let mut pos = 0;
    let header_size = read_varint(data, &mut pos) as usize;
    let header_end = header_size;
    let mut serial_types = Vec::new();
    while pos < header_end {
        serial_types.push(read_varint(data, &mut pos));
    }
    let mut values = Vec::new();
    for &st in &serial_types {
        values.push(read_value(data, &mut pos, st));
    }
    while values.len() < num_columns {
        values.push(Value::Null);
    }
    values
}

fn walk_table_raw(data: &[u8], page_size: usize, reserved: usize, page_num: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    if page_num == 0 {
        return;
    }
    let page_start = (page_num - 1) * page_size;
    let header_off = if page_num == 1 { 100 } else { 0 };
    let page_type = data[page_start + header_off];
    let num_cells =
        u16::from_be_bytes([data[page_start + header_off + 3], data[page_start + header_off + 4]]) as usize;
    let cell_ptr_off = header_off + if page_type == 5 { 12 } else { 8 };

    if page_type == 13 {
        let u = page_size - reserved;
        let m = u - 35;
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([
                data[page_start + cell_ptr_off + i * 2],
                data[page_start + cell_ptr_off + i * 2 + 1],
            ]) as usize;
            let cell_start = page_start + cell_off;
            let mut pos = cell_start;
            let payload_size = read_varint(data, &mut pos) as usize;
            let rowid = read_varint(data, &mut pos) as i64;
            let mut payload = Vec::with_capacity(payload_size);
            if payload_size <= m {
                payload.extend_from_slice(&data[pos..pos + payload_size]);
            } else {
                let min_local = (u - 12) * 32 / 255 - 23;
                let max_local = u - 35;
                let k = min_local + ((payload_size - min_local) % (u - 4));
                let local_size = if k <= max_local { k } else { min_local };
                payload.extend_from_slice(&data[pos..pos + local_size]);
                let mut overflow_page = u32::from_be_bytes([
                    data[pos + local_size],
                    data[pos + local_size + 1],
                    data[pos + local_size + 2],
                    data[pos + local_size + 3],
                ]) as usize;
                while overflow_page != 0 {
                    let op_start = (overflow_page - 1) * page_size;
                    let next_op = u32::from_be_bytes([
                        data[op_start],
                        data[op_start + 1],
                        data[op_start + 2],
                        data[op_start + 3],
                    ]) as usize;
                    let chunk = u - 4;
                    let remaining = payload_size - payload.len();
                    let to_read = chunk.min(remaining);
                    payload.extend_from_slice(&data[op_start + 4..op_start + 4 + to_read]);
                    overflow_page = next_op;
                }
            }
            rows.push((rowid, payload));
        }
    } else if page_type == 5 {
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([
                data[page_start + cell_ptr_off + i * 2],
                data[page_start + cell_ptr_off + i * 2 + 1],
            ]) as usize;
            let child_page = u32::from_be_bytes([
                data[page_start + cell_off],
                data[page_start + cell_off + 1],
                data[page_start + cell_off + 2],
                data[page_start + cell_off + 3],
            ]) as usize;
            walk_table_raw(data, page_size, reserved, child_page, rows);
        }
        let rightmost = u32::from_be_bytes([
            data[page_start + header_off + 8],
            data[page_start + header_off + 9],
            data[page_start + header_off + 10],
            data[page_start + header_off + 11],
        ]) as usize;
        walk_table_raw(data, page_size, reserved, rightmost, rows);
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(val: f64) -> String {
    if val == 0.0 {
        return "0.0".to_string();
    }
    let neg = val < 0.0;
    let abs_val = val.abs();
    if abs_val >= (1u64 << 52) as f64 {
        let int_val = abs_val as i128;
        let s = format!("{}", int_val);
        if neg {
            format!("-{}.0", s)
        } else {
            format!("{}.0", s)
        }
    } else {
        let scaled = (abs_val * 1e8).round() as u128;
        let int_part = scaled / 100_000_000;
        let frac_part = scaled % 100_000_000;
        let mut s = format!("{}", int_part);
        if frac_part == 0 {
            s.push_str(".0");
        } else {
            let frac_str = format!("{:08}", frac_part);
            let trimmed = frac_str.trim_end_matches('0');
            s.push('.');
            s.push_str(trimmed);
        }
        if neg {
            s.insert(0, '-');
        }
        s
    }
}

fn format_text(bytes: &[u8]) -> String {
    let mut s = String::from("\"");
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        match b {
            b'\\' => {
                s.push_str("\\\\");
                i += 1;
            }
            b'"' => {
                s.push_str("\\\"");
                i += 1;
            }
            b'\n' => {
                s.push_str("\\n");
                i += 1;
            }
            b'\r' => {
                s.push_str("\\r");
                i += 1;
            }
            b'\t' => {
                s.push_str("\\t");
                i += 1;
            }
            0x7F => {
                s.push_str(&format!("\\x{:02X}", b));
                i += 1;
            }
            _ if b < 0x20 => {
                s.push_str(&format!("\\x{:02X}", b));
                i += 1;
            }
            _ => {
                let start = i;
                while i < bytes.len() {
                    let b = bytes[i];
                    if b == b'\\' || b == b'"' || b == b'\n' || b == b'\r' || b == b'\t' || b == 0x7F || b < 0x20 {
                        break;
                    }
                    i += 1;
                }
                if let Ok(chunk) = std::str::from_utf8(&bytes[start..i]) {
                    s.push_str(chunk);
                }
            }
        }
    }
    s.push('"');
    s
}

fn format_value(val: &Value) -> String {
    match val {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => format!("{}", n),
        Value::Real(f) => format_real(*f),
        Value::Text(bytes) => {
            if bytes.len() <= 100 {
                format_text(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
        Value::Blob(bytes) => {
            if bytes.len() <= 100 {
                let hex: String = bytes.iter().map(|b| format!("{:02X}", b)).collect();
                format!("X'{}'", hex)
            } else {
                let crc = crc32(bytes);
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
    }
}

fn skip_ws(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }
    pos
}

fn skip_ident(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') {
        pos += 1;
    }
    pos
}

fn split_top_level(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0usize;
    let mut start = 0;
    for (i, c) in s.char_indices() {
        match c {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                parts.push(s[start..i].to_string());
                start = i + 1;
            }
            _ => {}
        }
    }
    parts.push(s[start..].to_string());
    parts
}

fn contains_primary_key(def: &str) -> bool {
    let upper = def.to_uppercase();
    let bytes = upper.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if i + 7 <= bytes.len() && &bytes[i..i + 7] == b"PRIMARY" {
            if i > 0 && (bytes[i - 1].is_ascii_alphanumeric() || bytes[i - 1] == b'_') {
                i += 1;
                continue;
            }
            let mut j = i + 7;
            while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                j += 1;
            }
            if j + 3 <= bytes.len() && &bytes[j..j + 3] == b"KEY" {
                if j + 3 >= bytes.len() || !(bytes[j + 3].is_ascii_alphanumeric() || bytes[j + 3] == b'_') {
                    return true;
                }
            }
        }
        i += 1;
    }
    false
}

fn parse_col_def(def: &str) -> (String, String, bool, bool) {
    let bytes = def.as_bytes();
    let mut pos = 0;
    let col_name;
    if bytes[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
        pos += 1;
    } else {
        let start = pos;
        while pos < bytes.len() && !bytes[pos].is_ascii_whitespace() && bytes[pos] != b'(' && bytes[pos] != b',' {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
    }
    pos = skip_ws(bytes, pos);
    let type_start = pos;
    while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') {
        pos += 1;
    }
    let type_name = def[type_start..pos].to_string();
    let mut has_size = false;
    let mut saved = pos;
    while saved < bytes.len() && bytes[saved].is_ascii_whitespace() {
        saved += 1;
    }
    if saved < bytes.len() && bytes[saved] == b'(' {
        has_size = true;
        pos = saved + 1;
        let mut depth = 1;
        while pos < bytes.len() && depth > 0 {
            if bytes[pos] == b'(' {
                depth += 1;
            }
            if bytes[pos] == b')' {
                depth -= 1;
            }
            pos += 1;
        }
    }
    let has_pk = contains_primary_key(def);
    (col_name, type_name, has_size, has_pk)
}

fn parse_create_table(sql: &str) -> (Vec<String>, Vec<bool>) {
    let bytes = sql.as_bytes();
    let mut pos = 0;
    pos = skip_ws(bytes, pos);
    pos = skip_ident(bytes, pos);
    pos = skip_ws(bytes, pos);
    pos = skip_ident(bytes, pos);
    pos = skip_ws(bytes, pos);
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        pos += 1;
    } else {
        while pos < bytes.len() && !bytes[pos].is_ascii_whitespace() && bytes[pos] != b'(' {
            pos += 1;
        }
    }
    pos = skip_ws(bytes, pos);
    assert!(pos < bytes.len() && bytes[pos] == b'(');
    pos += 1;
    let content_start = pos;
    let mut depth = 1usize;
    while pos < bytes.len() && depth > 0 {
        if bytes[pos] == b'(' {
            depth += 1;
        }
        if bytes[pos] == b')' {
            depth -= 1;
        }
        pos += 1;
    }
    let content = &sql[content_start..pos - 1];
    let defs = split_top_level(content);
    let mut names = Vec::new();
    let mut is_ipk = Vec::new();
    for def in defs {
        let def_trimmed = def.trim();
        if def_trimmed.is_empty() {
            continue;
        }
        let (col_name, type_name, has_size, has_pk) = parse_col_def(def_trimmed);
        names.push(col_name);
        is_ipk.push(type_name.eq_ignore_ascii_case("INTEGER") && !has_size && has_pk);
    }
    (names, is_ipk)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    let page_size_raw = u16::from_be_bytes([data[16], data[17]]);
    let page_size = if page_size_raw == 1 {
        65536usize
    } else {
        page_size_raw as usize
    };
    let reserved_bytes = data[20] as usize;

    let mut schema_rows: Vec<(i64, Vec<u8>)> = Vec::new();
    walk_table_raw(&data, page_size, reserved_bytes, 1, &mut schema_rows);

    let mut tables: Vec<(String, usize, String)> = Vec::new();
    for (_, payload) in &schema_rows {
        let values = parse_record(payload, 5);
        if values.len() < 5 {
            continue;
        }
        let type_str = match &values[0] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        if type_str != "table" {
            continue;
        }
        let name = match &values[1] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        if name.starts_with("sqlite_") {
            continue;
        }
        let rootpage = match &values[3] {
            Value::Integer(n) => *n as usize,
            _ => continue,
        };
        let sql = match &values[4] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        tables.push((name, rootpage, sql));
    }

    tables.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let stdout = io::stdout();
    let mut out = stdout.lock();

    for (i, (name, rootpage, sql)) in tables.iter().enumerate() {
        if i > 0 {
            writeln!(out).unwrap();
        }

        let (col_names, is_ipk) = parse_create_table(sql);
        let num_cols = col_names.len();

        let mut rows: Vec<(i64, Vec<u8>)> = Vec::new();
        walk_table_raw(&data, page_size, reserved_bytes, *rootpage, &mut rows);

        writeln!(out, "TABLE {} rows={}", name, rows.len()).unwrap();
        writeln!(out, "COLUMNS {}", col_names.join(", ")).unwrap();

        for (rowid, payload) in &rows {
            let values = parse_record(payload, num_cols);
            let mut vals_str = Vec::new();
            for j in 0..num_cols {
                if is_ipk[j] {
                    vals_str.push(format!("{}", rowid));
                } else {
                    vals_str.push(format_value(&values[j]));
                }
            }
            writeln!(out, "{}: {}", rowid, vals_str.join(", ")).unwrap();
        }
    }
}

use std::env;
use std::fs;
use std::io::{self, Write};

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut val: u64 = 0;
    for i in 0..9 {
        let b = data[*pos];
        *pos += 1;
        if i < 8 {
            if b < 0x80 {
                val = (val << 7) | (b as u64);
                return val;
            }
            val = (val << 7) | ((b & 0x7F) as u64);
        } else {
            val = (val << 8) | (b as u64);
            return val;
        }
    }
    unreachable!()
}

fn read_signed_int(data: &[u8], pos: &mut usize, n: usize) -> i64 {
    let mut val: i64 = 0;
    for _ in 0..n {
        val = (val << 8) | (data[*pos] as i64);
        *pos += 1;
    }
    let shift = 64 - (n * 8);
    (val << shift) >> shift
}

fn read_value(data: &[u8], pos: &mut usize, st: u64) -> Value {
    match st {
        0 => Value::Null,
        1 => Value::Integer(read_signed_int(data, pos, 1)),
        2 => Value::Integer(read_signed_int(data, pos, 2)),
        3 => Value::Integer(read_signed_int(data, pos, 3)),
        4 => Value::Integer(read_signed_int(data, pos, 4)),
        5 => Value::Integer(read_signed_int(data, pos, 6)),
        6 => Value::Integer(read_signed_int(data, pos, 8)),
        7 => {
            let mut bytes = [0u8; 8];
            bytes.copy_from_slice(&data[*pos..*pos + 8]);
            *pos += 8;
            Value::Real(f64::from_be_bytes(bytes))
        }
        8 => Value::Integer(0),
        9 => Value::Integer(1),
        n if n >= 12 && n % 2 == 0 => {
            let len = ((n - 12) / 2) as usize;
            let bytes = data[*pos..*pos + len].to_vec();
            *pos += len;
            Value::Blob(bytes)
        }
        n if n >= 13 && n % 2 == 1 => {
            let len = ((n - 13) / 2) as usize;
            let bytes = data[*pos..*pos + len].to_vec();
            *pos += len;
            Value::Text(bytes)
        }
        _ => Value::Null,
    }
}

fn parse_record(data: &[u8], num_columns: usize) -> Vec<Value> {
    let mut pos = 0;
    let header_size = read_varint(data, &mut pos) as usize;
    let header_end = header_size;
    let mut serial_types = Vec::new();
    while pos < header_end {
        serial_types.push(read_varint(data, &mut pos));
    }
    let mut values = Vec::new();
    for &st in &serial_types {
        values.push(read_value(data, &mut pos, st));
    }
    while values.len() < num_columns {
        values.push(Value::Null);
    }
    values
}

fn walk_table_raw(data: &[u8], page_size: usize, reserved: usize, page_num: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    if page_num == 0 {
        return;
    }
    let page_start = (page_num - 1) * page_size;
    let header_off = if page_num == 1 { 100 } else { 0 };
    let page_type = data[page_start + header_off];
    let num_cells =
        u16::from_be_bytes([data[page_start + header_off + 3], data[page_start + header_off + 4]]) as usize;
    let cell_ptr_off = header_off + if page_type == 5 { 12 } else { 8 };

    if page_type == 13 {
        let u = page_size - reserved;
        let m = u - 35;
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([
                data[page_start + cell_ptr_off + i * 2],
                data[page_start + cell_ptr_off + i * 2 + 1],
            ]) as usize;
            let cell_start = page_start + cell_off;
            let mut pos = cell_start;
            let payload_size = read_varint(data, &mut pos) as usize;
            let rowid = read_varint(data, &mut pos) as i64;
            let mut payload = Vec::with_capacity(payload_size);
            if payload_size <= m {
                payload.extend_from_slice(&data[pos..pos + payload_size]);
            } else {
                let min_local = (u - 12) * 32 / 255 - 23;
                let max_local = u - 35;
                let k = min_local + ((payload_size - min_local) % (u - 4));
                let local_size = if k <= max_local { k } else { min_local };
                payload.extend_from_slice(&data[pos..pos + local_size]);
                let mut overflow_page = u32::from_be_bytes([
                    data[pos + local_size],
                    data[pos + local_size + 1],
                    data[pos + local_size + 2],
                    data[pos + local_size + 3],
                ]) as usize;
                while overflow_page != 0 {
                    let op_start = (overflow_page - 1) * page_size;
                    let next_op = u32::from_be_bytes([
                        data[op_start],
                        data[op_start + 1],
                        data[op_start + 2],
                        data[op_start + 3],
                    ]) as usize;
                    let chunk = u - 4;
                    let remaining = payload_size - payload.len();
                    let to_read = chunk.min(remaining);
                    payload.extend_from_slice(&data[op_start + 4..op_start + 4 + to_read]);
                    overflow_page = next_op;
                }
            }
            rows.push((rowid, payload));
        }
    } else if page_type == 5 {
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([
                data[page_start + cell_ptr_off + i * 2],
                data[page_start + cell_ptr_off + i * 2 + 1],
            ]) as usize;
            let child_page = u32::from_be_bytes([
                data[page_start + cell_off],
                data[page_start + cell_off + 1],
                data[page_start + cell_off + 2],
                data[page_start + cell_off + 3],
            ]) as usize;
            walk_table_raw(data, page_size, reserved, child_page, rows);
        }
        let rightmost = u32::from_be_bytes([
            data[page_start + header_off + 8],
            data[page_start + header_off + 9],
            data[page_start + header_off + 10],
            data[page_start + header_off + 11],
        ]) as usize;
        walk_table_raw(data, page_size, reserved, rightmost, rows);
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(val: f64) -> String {
    if val == 0.0 {
        if val.is_sign_negative() {
            return "-0.0".to_string();
        }
        return "0.0".to_string();
    }
    let neg = val < 0.0;
    let abs_val = val.abs();

    let int_part_f = abs_val.trunc();
    let frac = abs_val - int_part_f;

    if frac == 0.0 {
        // Integer value, print with .0
        let int_str = format!("{}", int_part_f as u128);
        if neg {
            format!("-{}.0", int_str)
        } else {
            format!("{}.0", int_str)
        }
    } else {
        // Has fractional part; integer part fits in u64 (max ~4.5e15)
        let int_part = int_part_f as u64;
        let frac_scaled = (frac * 1e8).round() as u64;
        let mut s = format!("{}", int_part);
        if frac_scaled == 0 {
            s.push_str(".0");
        } else {
            let frac_str = format!("{:08}", frac_scaled);
            let trimmed = frac_str.trim_end_matches('0');
            s.push('.');
            s.push_str(trimmed);
        }
        if neg {
            s.insert(0, '-');
        }
        s
    }
}

fn format_text(bytes: &[u8]) -> String {
    let mut s = String::from("\"");
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        match b {
            b'\\' => {
                s.push_str("\\\\");
                i += 1;
            }
            b'"' => {
                s.push_str("\\\"");
                i += 1;
            }
            b'\n' => {
                s.push_str("\\n");
                i += 1;
            }
            b'\r' => {
                s.push_str("\\r");
                i += 1;
            }
            b'\t' => {
                s.push_str("\\t");
                i += 1;
            }
            0x7F => {
                s.push_str(&format!("\\x{:02X}", b));
                i += 1;
            }
            _ if b < 0x20 => {
                s.push_str(&format!("\\x{:02X}", b));
                i += 1;
            }
            _ => {
                let start = i;
                while i < bytes.len() {
                    let b = bytes[i];
                    if b == b'\\' || b == b'"' || b == b'\n' || b == b'\r' || b == b'\t' || b == 0x7F || b < 0x20 {
                        break;
                    }
                    i += 1;
                }
                if let Ok(chunk) = std::str::from_utf8(&bytes[start..i]) {
                    s.push_str(chunk);
                }
            }
        }
    }
    s.push('"');
    s
}

fn format_value(val: &Value) -> String {
    match val {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => format!("{}", n),
        Value::Real(f) => format_real(*f),
        Value::Text(bytes) => {
            if bytes.len() <= 100 {
                format_text(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
        Value::Blob(bytes) => {
            if bytes.len() <= 100 {
                let hex: String = bytes.iter().map(|b| format!("{:02X}", b)).collect();
                format!("X'{}'", hex)
            } else {
                let crc = crc32(bytes);
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
    }
}

fn skip_ws(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() {
        pos += 1;
    }
    pos
}

fn skip_ident(bytes: &[u8], mut pos: usize) -> usize {
    while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') {
        pos += 1;
    }
    pos
}

fn split_top_level(s: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut depth = 0usize;
    let mut start = 0;
    for (i, c) in s.char_indices() {
        match c {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                parts.push(s[start..i].to_string());
                start = i + 1;
            }
            _ => {}
        }
    }
    parts.push(s[start..].to_string());
    parts
}

fn contains_primary_key(def: &str) -> bool {
    let upper = def.to_uppercase();
    let bytes = upper.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if i + 7 <= bytes.len() && &bytes[i..i + 7] == b"PRIMARY" {
            if i > 0 && (bytes[i - 1].is_ascii_alphanumeric() || bytes[i - 1] == b'_') {
                i += 1;
                continue;
            }
            let mut j = i + 7;
            while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                j += 1;
            }
            if j + 3 <= bytes.len() && &bytes[j..j + 3] == b"KEY" {
                if j + 3 >= bytes.len() || !(bytes[j + 3].is_ascii_alphanumeric() || bytes[j + 3] == b'_') {
                    return true;
                }
            }
        }
        i += 1;
    }
    false
}

fn parse_col_def(def: &str) -> (String, String, bool, bool) {
    let bytes = def.as_bytes();
    let mut pos = 0;
    let col_name;
    if bytes[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
        pos += 1;
    } else {
        let start = pos;
        while pos < bytes.len() && !bytes[pos].is_ascii_whitespace() && bytes[pos] != b'(' && bytes[pos] != b',' {
            pos += 1;
        }
        col_name = def[start..pos].to_string();
    }
    pos = skip_ws(bytes, pos);
    let type_start = pos;
    while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') {
        pos += 1;
    }
    let type_name = def[type_start..pos].to_string();
    let mut has_size = false;
    let mut saved = pos;
    while saved < bytes.len() && bytes[saved].is_ascii_whitespace() {
        saved += 1;
    }
    if saved < bytes.len() && bytes[saved] == b'(' {
        has_size = true;
        pos = saved + 1;
        let mut depth = 1;
        while pos < bytes.len() && depth > 0 {
            if bytes[pos] == b'(' {
                depth += 1;
            }
            if bytes[pos] == b')' {
                depth -= 1;
            }
            pos += 1;
        }
    }
    let has_pk = contains_primary_key(def);
    (col_name, type_name, has_size, has_pk)
}

fn parse_create_table(sql: &str) -> (Vec<String>, Vec<bool>) {
    let bytes = sql.as_bytes();
    let mut pos = 0;
    pos = skip_ws(bytes, pos);
    pos = skip_ident(bytes, pos);
    pos = skip_ws(bytes, pos);
    pos = skip_ident(bytes, pos);
    pos = skip_ws(bytes, pos);
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' {
            pos += 1;
        }
        pos += 1;
    } else {
        while pos < bytes.len() && !bytes[pos].is_ascii_whitespace() && bytes[pos] != b'(' {
            pos += 1;
        }
    }
    pos = skip_ws(bytes, pos);
    assert!(pos < bytes.len() && bytes[pos] == b'(');
    pos += 1;
    let content_start = pos;
    let mut depth = 1usize;
    while pos < bytes.len() && depth > 0 {
        if bytes[pos] == b'(' {
            depth += 1;
        }
        if bytes[pos] == b')' {
            depth -= 1;
        }
        pos += 1;
    }
    let content = &sql[content_start..pos - 1];
    let defs = split_top_level(content);
    let mut names = Vec::new();
    let mut is_ipk = Vec::new();
    for def in defs {
        let def_trimmed = def.trim();
        if def_trimmed.is_empty() {
            continue;
        }
        let (col_name, type_name, has_size, has_pk) = parse_col_def(def_trimmed);
        names.push(col_name);
        is_ipk.push(type_name.eq_ignore_ascii_case("INTEGER") && !has_size && has_pk);
    }
    (names, is_ipk)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    let page_size_raw = u16::from_be_bytes([data[16], data[17]]);
    let page_size = if page_size_raw == 1 {
        65536usize
    } else {
        page_size_raw as usize
    };
    let reserved_bytes = data[20] as usize;

    let mut schema_rows: Vec<(i64, Vec<u8>)> = Vec::new();
    walk_table_raw(&data, page_size, reserved_bytes, 1, &mut schema_rows);

    let mut tables: Vec<(String, usize, String)> = Vec::new();
    for (_, payload) in &schema_rows {
        let values = parse_record(payload, 5);
        if values.len() < 5 {
            continue;
        }
        let type_str = match &values[0] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        if type_str != "table" {
            continue;
        }
        let name = match &values[1] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        if name.starts_with("sqlite_") {
            continue;
        }
        let rootpage = match &values[3] {
            Value::Integer(n) => *n as usize,
            _ => continue,
        };
        let sql = match &values[4] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        tables.push((name, rootpage, sql));
    }

    tables.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let stdout = io::stdout();
    let mut out = stdout.lock();

    for (i, (name, rootpage, sql)) in tables.iter().enumerate() {
        if i > 0 {
            writeln!(out).unwrap();
        }

        let (col_names, is_ipk) = parse_create_table(sql);
        let num_cols = col_names.len();

        let mut rows: Vec<(i64, Vec<u8>)> = Vec::new();
        walk_table_raw(&data, page_size, reserved_bytes, *rootpage, &mut rows);

        writeln!(out, "TABLE {} rows={}", name, rows.len()).unwrap();
        writeln!(out, "COLUMNS {}", col_names.join(", ")).unwrap();

        for (rowid, payload) in &rows {
            let values = parse_record(payload, num_cols);
            let mut vals_str = Vec::new();
            for j in 0..num_cols {
                if is_ipk[j] {
                    vals_str.push(format!("{}", rowid));
                } else {
                    vals_str.push(format_value(&values[j]));
                }
            }
            writeln!(out, "{}: {}", rowid, vals_str.join(", ")).unwrap();
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

const fileBuf = Buffer.from(fs.readFileSync(path.join(process.argv[2], 'db.sqlite')));

let pageSize = fileBuf.readUInt16BE(16);
if (pageSize === 1) pageSize = 65536;
const reservedBytes = fileBuf[20];
const usableSize = pageSize - reservedBytes;

const U_leaf = Math.floor((usableSize - 35) * 64 / 255) - 23;
const M_leaf = Math.floor((usableSize - 12) * 32 / 255) - 23;

function readVarint(buf: Buffer, offset: number): [bigint, number] {
    let value = 0n;
    let i = 0;
    for (; i < 8; i++) {
        const byte = buf[offset + i];
        value = (value << 7n) | BigInt(byte & 0x7F);
        if ((byte & 0x80) === 0) return [value, offset + i + 1];
    }
    value = (value << 8n) | BigInt(buf[offset + 8]);
    return [value, offset + 9];
}

function toSigned64(v: bigint): bigint {
    if (v >= (1n << 63n)) return v - (1n << 64n);
    return v;
}

function readSignedBE(buf: Buffer, offset: number, len: number): bigint {
    let val = 0n;
    for (let i = 0; i < len; i++) {
        val = (val << 8n) | BigInt(buf[offset + i]);
    }
    if (buf[offset] & 0x80) {
        val -= (1n << BigInt(len * 8));
    }
    return val;
}

function pageBase(pg: number): number { return (pg - 1) * pageSize; }
function headerOff(pg: number): number { return pg === 1 ? 100 : 0; }

function readOverflow(startPage: number, totalSize: number): Buffer {
    const chunks: Buffer[] = [];
    let remaining = totalSize;
    let pg = startPage;
    while (pg !== 0 && remaining > 0) {
        const base = pageBase(pg);
        const nextPage = fileBuf.readUInt32BE(base);
        const chunkSize = Math.min(remaining, usableSize - 4);
        chunks.push(fileBuf.slice(base + 4, base + 4 + chunkSize));
        remaining -= chunkSize;
        pg = nextPage;
    }
    return Buffer.concat(chunks);
}

function walkBTree(pg: number, rows: { rowid: bigint; payload: Buffer }[]) {
    const base = pageBase(pg);
    const hOff = headerOff(pg);
    const type = fileBuf[base + hOff];
    const numCells = fileBuf.readUInt16BE(base + hOff + 3);
    const cellPtrOff = base + hOff + (type === 5 ? 12 : 8);

    if (type === 13) {
        for (let i = 0; i < numCells; i++) {
            const cellOff = fileBuf.readUInt16BE(cellPtrOff + i * 2);
            let pos = base + cellOff;
            let [overflowPage, np] = readVarint(fileBuf, pos); pos = np;
            let [rowidU, np2] = readVarint(fileBuf, pos); pos = np2;
            let [payloadSizeU, np3] = readVarint(fileBuf, pos); pos = np3;
            const P = Number(payloadSizeU);
            let local: number;
            if (P <= U_leaf) {
                local = P;
            } else {
                local = M_leaf + ((P - M_leaf) % (usableSize - 4));
                if (local > U_leaf) local = U_leaf;
            }
            const localPayload = fileBuf.slice(pos, pos + local);
            let payload: Buffer;
            if (overflowPage !== 0n) {
                const overflowData = readOverflow(Number(overflowPage), P - local);
                payload = Buffer.concat([localPayload, overflowData]);
            } else {
                payload = localPayload;
            }
            rows.push({ rowid: toSigned64(rowidU), payload });
        }
    } else if (type === 5) {
        for (let i = 0; i < numCells; i++) {
            const cellOff = fileBuf.readUInt16BE(cellPtrOff + i * 2);
            const childPage = fileBuf.readUInt32BE(base + cellOff);
            walkBTree(childPage, rows);
        }
        const rightmost = fileBuf.readUInt32BE(base + hOff + 8);
        walkBTree(rightmost, rows);
    }
}

function decodeRecord(payload: Buffer, numCols: number): Value[] {
    let pos = 0;
    const [headerSize, np] = readVarint(payload, pos); pos = np;
    const headerEnd = Number(headerSize);
    const serialTypes: number[] = [];
    while (pos < headerEnd) {
        const [st, np2] = readVarint(payload, pos); pos = np2;
        serialTypes.push(Number(st));
    }
    const values: Value[] = [];
    for (let i = 0; i < numCols; i++) {
        if (i >= serialTypes.length) { values.push({ cls: 'NULL' }); continue; }
        const st = serialTypes[i];
        if (st === 0) { values.push({ cls: 'NULL' }); }
        else if (st >= 1 && st <= 6) {
            const val = readSignedBE(payload, pos, st);
            pos += st;
            values.push({ cls: 'INTEGER', intVal: val });
        } else if (st === 7) {
            const d = payload.readDoubleBE(pos);
            pos += 8;
            values.push({ cls: 'REAL', realVal: d });
        } else if (st === 8) {
            values.push({ cls: 'INTEGER', intVal: 0n });
        } else if (st === 9) {
            values.push({ cls: 'INTEGER', intVal: 1n });
        } else if (st >= 12 && st % 2 === 0) {
            const len = (st - 12) / 2;
            const data = payload.slice(pos, pos + len);
            pos += len;
            values.push({ cls: 'BLOB', blobVal: data });
        } else if (st >= 13 && st % 2 === 1) {
            const len = (st - 13) / 2;
            const data = payload.slice(pos, pos + len);
            pos += len;
            values.push({ cls: 'TEXT', textVal: data });
        } else {
            values.push({ cls: 'NULL' });
        }
    }
    return values;
}

type Value =
    | { cls: 'NULL' }
    | { cls: 'INTEGER'; intVal: bigint }
    | { cls: 'REAL'; realVal: number }
    | { cls: 'TEXT'; textVal: Buffer }
    | { cls: 'BLOB'; blobVal: Buffer };

function crc32(data: Buffer): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
            else crc >>>= 1;
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(d: number): string {
    const buf = Buffer.alloc(8);
    buf.writeDoubleBE(d, 0);
    const hi = buf.readUInt32BE(0);
    const lo = buf.readUInt32BE(4);
    const sign = (hi >>> 31) & 1;
