#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <math.h>

static uint8_t *g_data;
static size_t g_fsize;
static int g_ps, g_res, g_us;

static uint16_t rd16(const uint8_t*p){return(uint16_t)(p[0]<<8|p[1]);}
static uint32_t rd32(const uint8_t*p){return(uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3];}
static uint64_t rd64(const uint8_t*p){uint64_t v=0;for(int i=0;i<8;i++)v=(v<<8)|p[i];return v;}

static uint64_t rvi(const uint8_t*d,size_t*o,size_t end){
    if(*o>=end)return 0;
    uint8_t f=d[(*o)++];
    if(f<=240)return f;
    if(f<=252){if(*o>=end)return 0;return(uint64_t)(f-241)*256+d[(*o)++];}
    if(f==253){if(*o+2>=end){*o=end;return 0;}uint64_t v=(uint64_t)d[*o]<<16|(uint64_t)d[*o+1]<<8|d[*o+2];*o+=3;return v;}
    if(f==254){if(*o+3>=end){*o=end;return 0;}uint64_t v=(uint64_t)d[*o]<<24|(uint32_t)d[*o+1]<<16|(uint32_t)d[*o+2]<<8|d[*o+3];*o+=4;return v;}
    if(*o+7>=end){*o=end;return 0;}
    uint64_t v=0;for(int i=0;i<8;i++)v=(v<<8)|d[*o+i];*o+=8;return v;
}

static const uint8_t*pg(int n){return g_data+(size_t)(n-1)*g_ps;}
static const uint8_t*hd(int n){return n==1?g_data+100:g_data+(size_t)(n-1)*g_ps;}

typedef struct{int64_t rid;uint8_t*pl;size_t pn;}Row;
typedef struct{Row*a;int n,c;}RL;
static void radd(RL*r,int64_t rid,uint8_t*pl,size_t pn){
    if(r->n>=r->c){r->c=r->c?r->c*2:32;r->a=realloc(r->a,r->c*sizeof(Row));}
    r->a[r->n].rid=rid;r->a[r->n].pl=pl;r->a[r->n].pn=pn;r->n++;
}

static void walk(int pn,RL*out){
    const uint8_t*h=hd(pn);
    int type=h[0],nc=rd16(h+3);
    const uint8_t*p=pg(pn);
    if(type==13){
        int cpo=(pn==1)?108:8;
        for(int i=0;i<nc;i++){
            int co=rd16(p+cpo+i*2);
            size_t off=(size_t)co;
            uint64_t psz=rvi(p,&off,(size_t)g_ps);
            uint64_t rid=rvi(p,&off,(size_t)g_ps);
            int lmax=g_us-35;
            int llen=(int)psz;if(llen>lmax)llen=lmax;
            uint8_t*pl=malloc(psz?psz:1);
            if(llen>0)memcpy(pl,p+off,llen);
            off+=(size_t)llen;
            if((int)psz>lmax){
                uint32_t ovf=rd32(p+off);off+=4;
                size_t rem=psz-(size_t)llen,pos=(size_t)llen;
                while(ovf){
                    const uint8_t*op=pg(ovf);
                    uint32_t nxt=rd32(op);
                    int chunk=g_us-4;
                    if(chunk>(int)rem)chunk=(int)rem;
                    memcpy(pl+pos,op+4,chunk);
                    pos+=(size_t)chunk;rem-=(size_t)chunk;ovf=nxt;
                }
            }
            radd(out,(int64_t)rid,pl,(size_t)psz);
        }
    }else if(type==5){
        int cpo=(pn==1)?112:12;
        for(int i=0;i<nc;i++){
            int co=rd16(p+cpo+i*2);
            walk((int)rd32(p+co),out);
        }
        walk((int)rd32(h+8),out);
    }
}

static uint32_t crc32_fn(const uint8_t*d,size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++){c^=d[i];for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;}
    return c^0xFFFFFFFF;
}

static int ci_eq(const char*a,const char*b,int len){
    for(int i=0;i<len;i++){
        char ca=a[i],cb=b[i];
        if(ca>='A'&&ca<='Z')ca+=32;
        if(cb>='A'&&cb<='Z')cb+=32;
        if(ca!=cb)return 0;
    }
    return 1;
}

static int has_pk(const char*s,int len){
    for(int i=0;i<len;i++){
        if((s[i]=='P'||s[i]=='p')&&i+6<len&&
           (s[i+1]=='R'||s[i+1]=='r')&&(s[i+2]=='I'||s[i+2]=='i')&&
           (s[i+3]=='M'||s[i+3]=='m')&&(s[i+4]=='A'||s[i+4]=='a')&&
           (s[i+5]=='R'||s[i+5]=='r')&&(s[i+6]=='Y'||s[i+6]=='y')){
            int j=i+7;
            while(j<len&&(s[j]==' '||s[j]=='\t'||s[j]=='\n'||s[j]=='\r'))j++;
            if(j+2<len&&(s[j]=='K'||s[j]=='k')&&(s[j+1]=='E'||s[j+1]=='e')&&(s[j+2]=='Y'||s[j+2]=='y'))
                return 1;
        }
    }
    return 0;
}

typedef struct{char*name;int is_rowid;}ColInfo;

static void parse_create_table(const char*sql,int slen,ColInfo**cols,int*ncols){
    int i=0;
    /* find first '(' not inside quotes */
    while(i<slen){
        if(sql[i]=='"'){i++;while(i<slen&&sql[i]!='"')i++;i++;}
        else if(sql[i]=='(')break;
        else i++;
    }
    if(i>=slen){*cols=NULL;*ncols=0;return;}
    int open=i;
    /* find matching ')' */
    int depth=0,close=-1;
    for(i=open;i<slen;i++){
        if(sql[i]=='"'){i++;while(i<slen&&sql[i]!='"')i++;}
        else if(sql[i]=='(')depth++;
        else if(sql[i]==')'){depth--;if(depth==0){close=i;break;}}
    }
    if(close<0){*cols=NULL;*ncols=0;return;}
    /* content between open+1 and close-1 */
    int cs=open+1,ce=close;
    /* split by commas at depth 0 */
    int cap=16,nc=0;
    ColInfo*cl=malloc(cap*sizeof(ColInfo));
    i=cs;
    while(i<ce){
        /* find end of this definition */
        int d=0,j=i;
        while(j<ce){
            if(sql[j]=='"'){j++;while(j<ce&&sql[j]!='"')j++;j++;}
            else if(sql[j]=='('){d++;j++;}
            else if(sql[j]==')'){d--;j++;}
            else if(sql[j]==','&&d==0)break;
            else j++;
        }
        int dlen=j-i;
        if(dlen>0){
            /* extract column name */
            int k=i;
            while(k<ce&&(sql[k]==' '||sql[k]=='\t'||sql[k]=='\n'||sql[k]=='\r'))k++;
            char*nm=NULL;
            if(k<ce&&sql[k]=='"'){
                k++;int ns=k;
                while(k<ce&&sql[k]!='"')k++;
                nm=malloc(k-ns+1);memcpy(nm,sql+ns,k-ns);nm[k-ns]=0;
                k++; /* skip closing " */
            }else{
                int ns=k;
                while(k<ce&&sql[k]!=' '&&sql[k]!='\t'&&sql[k]!='\n'&&sql[k]!='\r'&&sql[k]!='('&&sql[k]!=','&&sql[k]!=')')k++;
                nm=malloc(k-ns+1);memcpy(nm,sql+ns,k-ns);nm[k-ns]=0;
            }
            /* extract type: next word after name */
            while(k<ce&&(sql[k]==' '||sql[k]=='\t'||sql[k]=='\n'||sql[k]=='\r'))k++;
            int ts=k;
            while(k<ce&&((sql[k]>='a'&&sql[k]<='z')||(sql[k]>='A'&&sql[k]<='Z')||(sql[k]>='0'&&sql[k]<='9')||sql[k]=='_'))k++;
            int tlen=k-ts;
            /* check if followed by '(' -> type has size suffix */
            int has_paren=0;
            {int tmp=k;while(tmp<ce&&(sql[tmp]==' '||sql[tmp]=='\t'||sql[tmp]=='\n'||sql[tmp]=='\r'))tmp++;
             if(tmp<ce&&sql[tmp]=='(')has_paren=1;}
            int is_rid=0;
            if(tlen==7&&!has_paren&&ci_eq(sql+ts,"INTEGER",7)){
                if(has_pk(sql+i,dlen))is_rid=1;
            }
            if(nc>=cap){cap*=2;cl=realloc(cl,cap*sizeof(ColInfo));}
            cl[nc].name=nm;cl[nc].is_rowid=is_rid;nc++;
        }
        i=j+1;
    }
    *cols=cl;*ncols=nc;
}

static void print_text(const uint8_t*d,size_t n){
    putchar('"');
    for(size_t i=0;i<n;i++){
        uint8_t c=d[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t*d,size_t n){
    printf("X'");
    for(size_t i=0;i<n;i++)printf("%02X",d[i]);
    printf("'");
}

static void print_real(double v){
    char buf[64];
    snprintf(buf,sizeof buf,"%.8f",v);
    int len=strlen(buf);
    char*dot=strchr(buf,'.');
    if(dot){
        while(len>1&&buf[len-1]=='0'&&buf[len-2]!='.')len--;
        buf[len]=0;
    }
    printf("%s",buf);
}

static void print_val(uint64_t st,const uint8_t*body,size_t*bp,uint64_t rowid,int is_rowid_col){
    if(is_rowid_col){
        printf("%" PRId64,(int64_t)rowid);
        /* still need to skip the body bytes for this column (serial type 0 = 0 bytes) */
        return;
    }
    if(st==0){printf("NULL");return;}
    if(st==1){int8_t v=(int8_t)body[*bp];*bp+=1;printf("%" PRId64,(int64_t)v);return;}
    if(st==2){int16_t v=(int16_t)(body[*bp]<<8|body[*bp+1]);*bp+=2;printf("%" PRId64,(int64_t)v);return;}
    if(st==3){int32_t v=(int32_t)(body[*bp]<<16|body[*bp+1]<<8|body[*bp+2]);if(v&0x800000)v|=~0xFFFFFF;*bp+=3;printf("%" PRId64,(int64_t)v);return;}
    if(st==4){int32_t v=(int32_t)rd32(body+*bp);*bp+=4;printf("%" PRId64,(int64_t)v);return;}
    if(st==5){int64_t v=0;for(int i=0;i<6;i++)v=(v<<8)|body[*bp+i];if(v&(1LL<<47))v|=(~0LL<<48);*bp+=6;printf("%" PRId64,v);return;}
    if(st==6){int64_t v=(int64_t)rd64(body+*bp);*bp+=8;printf("%" PRId64,v);return;}
    if(st==7){double v;uint64_t bits=rd64(body+*bp);memcpy(&v,&bits,8);*bp+=8;print_real(v);return;}
    if(st==8){printf("0");return;}
    if(st==9){printf("1");return;}
    if(st>=12){
        size_t blen=(st-12)/2;
        int is_text=(st&1);
        const uint8_t*vd=body+*bp;*bp+=blen;
        if(blen>100){
            uint32_t c=crc32_fn(vd,blen);
            if(is_text)printf("<TEXT len=%zu crc32=%08x>",blen,c);
            else printf("<BLOB len=%zu crc32=%08x>",blen,c);
        }else{
            if(is_text)print_text(vd,blen);
            else print_blob(vd,blen);
        }
        return;
    }
    printf("NULL");
}

typedef struct{char*name;uint32_t rootpage;ColInfo*cols;int ncols;}Tbl;

int main(int argc,char*argv[]){
    if(argc<2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];
    snprintf(path,sizeof path,"%s/db.sqlite",argv[1]);
    FILE*f=fopen(path,"rb");
    if(!f){perror("fopen");return 1;}
    fseek(f,0,SEEK_END);g_fsize=(size_t)ftell(f);fseek(f,0,SEEK_SET);
    g_data=malloc(g_fsize);
    if(fread(g_data,1,g_fsize,f)!=g_fsize){fprintf(stderr,"read error\n");return 1;}
    fclose(f);

    g_ps=(int)rd16(g_data+16);if(g_ps==1)g_ps=65536;
    g_res=g_data[20];
    g_us=g_ps-g_res;

    /* Walk schema table (page 1) */
    RL schema={0,0,0};
    walk(1,&schema);

    /* Extract table info from schema */
    Tbl*tbls=NULL;int ntbls=0,tcap=16;
    tbls=malloc(tcap*sizeof(Tbl));

    for(int ri=0;ri<schema.n;ri++){
        Row*r=&schema.a[ri];
        /* parse record */
        const uint8_t*pl=r->pl;size_t pn=r->pn;
        size_t off=0;
        uint64_t hdr_sz=rvi(pl,&off,pn);
        size_t hdr_end=hdr_sz;
        /* read serial types */
        int stcap=8,nt=0;uint64_t*sts=malloc(stcap*sizeof(uint64_t));
        while(off<hdr_end&&off<pn){
            if(nt>=stcap){stcap*=2;sts=realloc(stcap,sizeof(uint64_t)*stcap);}
            sts[nt++]=rvi(pl,&off,hdr_end);
        }
        const uint8_t*body=pl+hdr_end;size_t bpos=0;

        /* read type (col 0) */
        const char*type_str=NULL;size_t type_len=0;
        if(nt>0&&sts[0]>=13&&sts[0]&1){type_len=(sts[0]-13)/2;type_str=(const char*)(body+bpos);bpos+=type_len;}
        /* read name (col 1) */
        const char*name_str=NULL;size_t name_len=0;
        if(nt>1&&sts[1]>=13&&sts[1]&1){name_len=(sts[1]-13)/2;name_str=(const char*)(body+bpos);bpos+=name_len;}
        /* read tbl_name (col 2) */
        if(nt>2){if(sts[2]>=13&&sts[2]&1)bpos+=(sts[2]-13)/2;else if(sts[2]>=12&&!(sts[2]&1))bpos+=(sts[2]-12)/2;else if(sts[2]==1)bpos+=1;else if(sts[2]==2)bpos+=2;else if(sts[2]==3)bpos+=3;else if(sts[2]==4)bpos+=4;else if(sts[2]==5)bpos+=6;else if(sts[2]==6)bpos+=8;else if(sts[2]==7)bpos+=8;}
        /* read rootpage (col 3) */
        uint32_t rootpg=0;
        if(nt>3){
            if(sts[3]==1){rootpg=(uint8_t)body[bpos];bpos+=1;}
            else if(sts[3]==2){rootpg=rd16(body+bpos);bpos+=2;}
            else if(sts[3]==3){rootpg=(uint32_t)(body[bpos]<<16|body[bpos+1]<<8|body[bpos+2]);bpos+=3;}
            else if(sts[3]==4){rootpg=rd32(body+bpos);bpos+=4;}
            else if(sts[3]==5){uint64_t v=0;for(int i=0;i<6;i++)v=(v<<8)|body[bpos+i];rootpg=(uint32_t)v;bpos+=6;}
            else if(sts[3]==6){rootpg=(uint32_t)rd64(body+bpos);bpos+=8;}
            else if(sts[3]==8){rootpg=0;}
            else if(sts[3]==9){rootpg=1;}
            else if(sts[3]==0){rootpg=0;}
        }
        /* read sql (col 4) */
        const char*sql_str=NULL;size_t sql_len=0;
        if(nt>4&&sts[4]>=13&&sts[4]&1){sql_len=(sts[4]-13)/2;sql_str=(const char*)(body+bpos);bpos+=sql_len;}

        free(sts);

        if(!type_str||type_len!=5||memcmp(type_str,"table",5)!=0)continue;
        if(!name_str||name_len==0)continue;
        if(name_len>=7&&memcmp(name_str,"sqlite_",7)==0)continue;
        if(!sql_str)continue;

        if(ntbls>=tcap){tcap*=2;tbls=realloc(tbls,tcap*sizeof(Tbl));}
        Tbl*t=&tbls[ntbls];
        t->name=malloc(name_len+1);memcpy(t->name,name_str,name_len);t->name[name_len]=0;
        t->rootpage=rootpg;
        parse_create_table(sql_str,(int)sql_len,&t->cols,&t->ncols);
        ntbls++;
    }

    /* sort tables by name (byte-wise) */
    for(int i=0;i<ntbls;i++)for(int j=i+1;j<ntbls;j++){
        if(strcmp(tbls[i].name,tbls[j].name)>0){Tbl tmp=tbls[i];tbls[i]=tbls[j];tbls[j]=tmp;}
    }

    /* output */
    for(int ti=0;ti<ntbls;ti++){
        if(ti>0)printf("\n");
        Tbl*t=&tbls[ti];
        RL rows={0,0,0};
        if(t->rootpage>0)walk((int)t->rootpage,&rows);
        printf("TABLE %s rows=%d\n",t->name,rows.n);
        printf("COLUMNS");
        for(int ci=0;ci<t->ncols;ci++){
            if(ci==0)printf(" %s",t->cols[ci].name);
            else printf(", %s",t->cols[ci].name);
        }
        printf("\n");
        for(int ri=0;ri<rows.n;ri++){
            Row*r=&rows.a[ri];
            printf("%" PRId64":",r->rid);
            const uint8_t*pl=r->pl;size_t pn=r->pn;
            size_t off=0;
            uint64_t hdr_sz=rvi(pl,&off,pn);
            size_t hdr_end=hdr_sz;
            int stcap=16,nt=0;uint64_t*sts=malloc(stcap*sizeof(uint64_t));
            while(off<hdr_end&&off<pn){
                if(nt>=stcap){stcap*=2;sts=realloc(stcap,sizeof(uint64_t)*stcap);}
                sts[nt++]=rvi(pl,&off,hdr_end);
            }
            const uint8_t*body=pl+hdr_end;size_t bpos=0;
            for(int ci=0;ci<t->ncols;ci++){
                if(ci>0)printf(",");
                printf(" ");
                if(t->cols[ci].is_rowid){
                    printf("%" PRId64,r->rid);
                    /* skip body bytes for this col if serial type present */
                    if(ci<nt){
                        uint64_t st=sts[ci];
                        if(st>=12){size_t bl=(st-12)/2;bpos+=bl;}
                        else if(st>=1&&st<=7){
                            int bs[]={0,1,2,3,4,6,8,8};
                            bpos+=bs[st];
                        }
                    }
                }else if(ci<nt){
                    print_val(sts[ci],body,&bpos,(uint64_t)r->rid,0);
                }else{
                    printf("NULL");
                }
            }
            printf("\n");
            free(sts);
        }
        for(int i=0;i<rows.n;i++)free(rows.a[i].pl);
        free(rows.a);
        for(int ci=0;ci<t->ncols;ci++)free(t->cols[ci].name);
        free(t->cols);
        free(t->name);
    }

    for(int i=0;i<schema.n;i++)free(schema.a[i].pl);
    free(schema.a);
    free(tbls);
    free(g_data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>
#include <math.h>

static uint8_t *g_data;
static size_t g_fsize;
static int g_ps, g_res, g_us;

static uint16_t rd16(const uint8_t*p){return(uint16_t)(p[0]<<8|p[1]);}
static uint32_t rd32(const uint8_t*p){return(uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3];}
static uint64_t rd64(const uint8_t*p){uint64_t v=0;for(int i=0;i<8;i++)v=(v<<8)|p[i];return v;}

static uint64_t rvi(const uint8_t*d,size_t*o,size_t end){
    if(*o>=end)return 0;
    uint8_t f=d[(*o)++];
    if(f<=240)return f;
    if(f<=252){if(*o>=end)return 0;return(uint64_t)(f-241)*256+d[(*o)++];}
    if(f==253){if(*o+2>=end){*o=end;return 0;}uint64_t v=(uint64_t)d[*o]<<16|(uint64_t)d[*o+1]<<8|d[*o+2];*o+=3;return v;}
    if(f==254){if(*o+3>=end){*o=end;return 0;}uint64_t v=(uint64_t)d[*o]<<24|(uint32_t)d[*o+1]<<16|(uint32_t)d[*o+2]<<8|d[*o+3];*o+=4;return v;}
    if(*o+7>=end){*o=end;return 0;}
    uint64_t v=0;for(int i=0;i<8;i++)v=(v<<8)|d[*o+i];*o+=8;return v;
}

static const uint8_t*pg(int n){return g_data+(size_t)(n-1)*g_ps;}
static const uint8_t*hd(int n){return n==1?g_data+100:g_data+(size_t)(n-1)*g_ps;}

typedef struct{int64_t rid;uint8_t*pl;size_t pn;}Row;
typedef struct{Row*a;int n,c;}RL;
static void radd(RL*r,int64_t rid,uint8_t*pl,size_t pn){
    if(r->n>=r->c){r->c=r->c?r->c*2:32;r->a=realloc(r->a,r->c*sizeof(Row));}
    r->a[r->n].rid=rid;r->a[r->n].pl=pl;r->a[r->n].pn=pn;r->n++;
}

static void walk(int pn,RL*out){
    const uint8_t*h=hd(pn);
    int type=h[0],nc=rd16(h+3);
    const uint8_t*p=pg(pn);
    if(type==13){
        int cpo=(pn==1)?108:8;
        for(int i=0;i<nc;i++){
            int co=rd16(p+cpo+i*2);
            size_t off=(size_t)co;
            uint64_t psz=rvi(p,&off,(size_t)g_ps);
            uint64_t rid=rvi(p,&off,(size_t)g_ps);
            int lmax=g_us-35;
            int llen=(int)psz;if(llen>lmax)llen=lmax;
            uint8_t*pl=malloc(psz?psz:1);
            if(llen>0)memcpy(pl,p+off,llen);
            off+=(size_t)llen;
            if((int)psz>lmax){
                uint32_t ovf=rd32(p+off);off+=4;
                size_t rem=psz-(size_t)llen,pos=(size_t)llen;
                while(ovf){
                    const uint8_t*op=pg(ovf);
                    uint32_t nxt=rd32(op);
                    int chunk=g_us-4;
                    if(chunk>(int)rem)chunk=(int)rem;
                    memcpy(pl+pos,op+4,chunk);
                    pos+=(size_t)chunk;rem-=(size_t)chunk;ovf=nxt;
                }
            }
            radd(out,(int64_t)rid,pl,(size_t)psz);
        }
    }else if(type==5){
        int cpo=(pn==1)?112:12;
        for(int i=0;i<nc;i++){
            int co=rd16(p+cpo+i*2);
            walk((int)rd32(p+co),out);
        }
        walk((int)rd32(h+8),out);
    }
}

static uint32_t crc32_fn(const uint8_t*d,size_t n){
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++){c^=d[i];for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;}
    return c^0xFFFFFFFF;
}

static int ci_eq(const char*a,const char*b,int len){
    for(int i=0;i<len;i++){
        char ca=a[i],cb=b[i];
        if(ca>='A'&&ca<='Z')ca+=32;
        if(cb>='A'&&cb<='Z')cb+=32;
        if(ca!=cb)return 0;
    }
    return 1;
}

static int has_pk(const char*s,int len){
    for(int i=0;i<len;i++){
        if((s[i]=='P'||s[i]=='p')&&i+6<len&&
           (s[i+1]=='R'||s[i+1]=='r')&&(s[i+2]=='I'||s[i+2]=='i')&&
           (s[i+3]=='M'||s[i+3]=='m')&&(s[i+4]=='A'||s[i+4]=='a')&&
           (s[i+5]=='R'||s[i+5]=='r')&&(s[i+6]=='Y'||s[i+6]=='y')){
            int j=i+7;
            while(j<len&&(s[j]==' '||s[j]=='\t'||s[j]=='\n'||s[j]=='\r'))j++;
            if(j+2<len&&(s[j]=='K'||s[j]=='k')&&(s[j+1]=='E'||s[j+1]=='e')&&(s[j+2]=='Y'||s[j+2]=='y'))
                return 1;
        }
    }
    return 0;
}

typedef struct{char*name;int is_rowid;}ColInfo;

static void parse_create_table(const char*sql,int slen,ColInfo**cols,int*ncols){
    int i=0;
    while(i<slen){
        if(sql[i]=='"'){i++;while(i<slen&&sql[i]!='"')i++;i++;}
        else if(sql[i]=='(')break;
        else i++;
    }
    if(i>=slen){*cols=NULL;*ncols=0;return;}
    int open=i;
    int depth=0,close=-1;
    for(i=open;i<slen;i++){
        if(sql[i]=='"'){i++;while(i<slen&&sql[i]!='"')i++;}
        else if(sql[i]=='(')depth++;
        else if(sql[i]==')'){depth--;if(depth==0){close=i;break;}}
    }
    if(close<0){*cols=NULL;*ncols=0;return;}
    int cs=open+1,ce=close;
    int cap=16,nc=0;
    ColInfo*cl=malloc(cap*sizeof(ColInfo));
    i=cs;
    while(i<ce){
        int d=0,j=i;
        while(j<ce){
            if(sql[j]=='"'){j++;while(j<ce&&sql[j]!='"')j++;j++;}
            else if(sql[j]=='('){d++;j++;}
            else if(sql[j]==')'){d--;j++;}
            else if(sql[j]==','&&d==0)break;
            else j++;
        }
        int dlen=j-i;
        if(dlen>0){
            int k=i;
            while(k<ce&&(sql[k]==' '||sql[k]=='\t'||sql[k]=='\n'||sql[k]=='\r'))k++;
            char*nm=NULL;
            if(k<ce&&sql[k]=='"'){
                k++;int ns=k;
                while(k<ce&&sql[k]!='"')k++;
                nm=malloc(k-ns+1);memcpy(nm,sql+ns,k-ns);nm[k-ns]=0;
                k++;
            }else{
                int ns=k;
                while(k<ce&&sql[k]!=' '&&sql[k]!='\t'&&sql[k]!='\n'&&sql[k]!='\r'&&sql[k]!='('&&sql[k]!=','&&sql[k]!=')')k++;
                nm=malloc(k-ns+1);memcpy(nm,sql+ns,k-ns);nm[k-ns]=0;
            }
            while(k<ce&&(sql[k]==' '||sql[k]=='\t'||sql[k]=='\n'||sql[k]=='\r'))k++;
            int ts=k;
            while(k<ce&&((sql[k]>='a'&&sql[k]<='z')||(sql[k]>='A'&&sql[k]<='Z')||(sql[k]>='0'&&sql[k]<='9')||sql[k]=='_'))k++;
            int tlen=k-ts;
            int has_paren=0;
            {int tmp=k;while(tmp<ce&&(sql[tmp]==' '||sql[tmp]=='\t'||sql[tmp]=='\n'||sql[tmp]=='\r'))tmp++;
             if(tmp<ce&&sql[tmp]=='(')has_paren=1;}
            int is_rid=0;
            if(tlen==7&&!has_paren&&ci_eq(sql+ts,"INTEGER",7)){
                if(has_pk(sql+i,dlen))is_rid=1;
            }
            if(nc>=cap){cap*=2;cl=realloc(cl,cap*sizeof(ColInfo));}
            cl[nc].name=nm;cl[nc].is_rowid=is_rid;nc++;
        }
        i=j+1;
    }
    *cols=cl;*ncols=nc;
}

static void print_text(const uint8_t*d,size_t n){
    putchar('"');
    for(size_t i=0;i<n;i++){
        uint8_t c=d[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t*d,size_t n){
    printf("X'");
    for(size_t i=0;i<n;i++)printf("%02X",d[i]);
    printf("'");
}

static void print_real(double v){
    char buf[400];
    snprintf(buf,sizeof buf,"%.8f",v);
    int len=strlen(buf);
    char*dot=strchr(buf,'.');
    if(dot){
        while(len>1&&buf[len-1]=='0'&&buf[len-2]!='.')len--;
        buf[len]=0;
    }
    printf("%s",buf);
}

static void print_val(uint64_t st,const uint8_t*body,size_t*bp,uint64_t rowid,int is_rowid_col){
    if(is_rowid_col){
        printf("%" PRId64,(int64_t)rowid);
        return;
    }
    if(st==0){printf("NULL");return;}
    if(st==1){int8_t v=(int8_t)body[*bp];*bp+=1;printf("%" PRId64,(int64_t)v);return;}
    if(st==2){int16_t v=(int16_t)((body[*bp]<<8)|body[*bp+1]);*bp+=2;printf("%" PRId64,(int64_t)v);return;}
    if(st==3){int32_t v=(int32_t)((body[*bp]<<16)|(body[*bp+1]<<8)|body[*bp+2]);if(v&0x800000)v|=(int32_t)0xFF000000;*bp+=3;printf("%" PRId64,(int64_t)v);return;}
    if(st==4){int32_t v=(int32_t)rd32(body+*bp);*bp+=4;printf("%" PRId64,(int64_t)v);return;}
    if(st==5){int64_t v=0;for(int i=0;i<6;i++)v=(v<<8)|body[*bp+i];if(v&(1LL<<47))v=(int64_t)((uint64_t)v|0xFFFF000000000000ULL);*bp+=6;printf("%" PRId64,v);return;}
    if(st==6){int64_t v=(int64_t)rd64(body+*bp);*bp+=8;printf("%" PRId64,v);return;}
    if(st==7){double v;uint64_t bits=rd64(body+*bp);memcpy(&v,&bits,8);*bp+=8;print_real(v);return;}
    if(st==8){printf("0");return;}
    if(st==9){printf("1");return;}
    if(st>=12){
        size_t blen=(st-12)/2;
        int is_text=(st&1);
        const uint8_t*vd=body+*bp;*bp+=blen;
        if(blen>100){
            uint32_t c=crc32_fn(vd,blen);
            if(is_text)printf("<TEXT len=%zu crc32=%08x>",blen,c);
            else printf("<BLOB len=%zu crc32=%08x>",blen,c);
        }else{
            if(is_text)print_text(vd,blen);
            else print_blob(vd,blen);
        }
        return;
    }
    printf("NULL");
}

static int skip_serial_bytes(uint64_t st){
    if(st==0||st==8||st==9||st==10||st==11)return 0;
    if(st>=1&&st<=6){int bs[]={0,1,2,3,4,6,8};return bs[st];}
    if(st==7)return 8;
    if(st>=12)return(int)((st-12)/2);
    return 0;
}

typedef struct{char*name;uint32_t rootpage;ColInfo*cols;int ncols;}Tbl;

int main(int argc,char*argv[]){
    if(argc<2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];
    snprintf(path,sizeof path,"%s/db.sqlite",argv[1]);
    FILE*f=fopen(path,"rb");
    if(!f){perror("fopen");return 1;}
    fseek(f,0,SEEK_END);g_fsize=(size_t)ftell(f);fseek(f,0,SEEK_SET);
    g_data=malloc(g_fsize);
    if(fread(g_data,1,g_fsize,f)!=g_fsize){fprintf(stderr,"read error\n");return 1;}
    fclose(f);

    g_ps=(int)rd16(g_data+16);if(g_ps==1)g_ps=65536;
    g_res=g_data[20];
    g_us=g_ps-g_res;

    RL schema={0,0,0};
    walk(1,&schema);

    Tbl*tbls=NULL;int ntbls=0,tcap=16;
    tbls=malloc(tcap*sizeof(Tbl));

    for(int ri=0;ri<schema.n;ri++){
        Row*r=&schema.a[ri];
        const uint8_t*pl=r->pl;size_t pn=r->pn;
        size_t off=0;
        uint64_t hdr_sz=rvi(pl,&off,pn);
        size_t hdr_end=hdr_sz;
        int stcap=8,nt=0;uint64_t*sts=malloc(stcap*sizeof(uint64_t));
        while(off<hdr_end&&off<pn){
            if(nt>=stcap){stcap*=2;sts=realloc(sts,stcap*sizeof(uint64_t));}
            sts[nt++]=rvi(pl,&off,hdr_end);
        }
        const uint8_t*body=pl+hdr_end;size_t bpos=0;

        const char*type_str=NULL;size_t type_len=0;
        if(nt>0&&sts[0]>=13&&(sts[0]&1)){type_len=(sts[0]-13)/2;type_str=(const char*)(body+bpos);bpos+=type_len;}
        const char*name_str=NULL;size_t name_len=0;
        if(nt>1&&sts[1]>=13&&(sts[1]&1)){name_len=(sts[1]-13)/2;name_str=(const char*)(body+bpos);bpos+=name_len;}
        if(nt>2){bpos+=skip_serial_bytes(sts[2]);}
        uint32_t rootpg=0;
        if(nt>3){
            if(sts[3]==1){rootpg=(uint8_t)body[bpos];bpos+=1;}
            else if(sts[3]==2){rootpg=rd16(body+bpos);bpos+=2;}
            else if(sts[3]==3){rootpg=(uint32_t)((body[bpos]<<16)|(body[bpos+1]<<8)|body[bpos+2]);bpos+=3;}
            else if(sts[3]==4){rootpg=rd32(body+bpos);bpos+=4;}
            else if(sts[3]==5){uint64_t v=0;for(int i=0;i<6;i++)v=(v<<8)|body[bpos+i];rootpg=(uint32_t)v;bpos+=6;}
            else if(sts[3]==6){rootpg=(uint32_t)rd64(body+bpos);bpos+=8;}
            else if(sts[3]==8){rootpg=0;}
            else if(sts[3]==9){rootpg=1;}
            else if(sts[3]==0){rootpg=0;}
        }
        const char*sql_str=NULL;size_t sql_len=0;
        if(nt>4&&sts[4]>=13&&(sts[4]&1)){sql_len=(sts[4]-13)/2;sql_str=(const char*)(body+bpos);bpos+=sql_len;}

        free(sts);

        if(!type_str||type_len!=5||memcmp(type_str,"table",5)!=0)continue;
        if(!name_str||name_len==0)continue;
        if(name_len>=7&&memcmp(name_str,"sqlite_",7)==0)continue;
        if(!sql_str)continue;

        if(ntbls>=tcap){tcap*=2;tbls=realloc(tbls,tcap*sizeof(Tbl));}
        Tbl*t=&tbls[ntbls];
        t->name=malloc(name_len+1);memcpy(t->name,name_str,name_len);t->name[name_len]=0;
        t->rootpage=rootpg;
        parse_create_table(sql_str,(int)sql_len,&t->cols,&t->ncols);
        ntbls++;
    }

    for(int i=0;i<ntbls;i++)for(int j=i+1;j<ntbls;j++){
        if(strcmp(tbls[i].name,tbls[j].name)>0){Tbl tmp=tbls[i];tbls[i]=tbls[j];tbls[j]=tmp;}
    }

    for(int ti=0;ti<ntbls;ti++){
        if(ti>0)printf("\n");
        Tbl*t=&tbls[ti];
        RL rows={0,0,0};
        if(t->rootpage>0)walk((int)t->rootpage,&rows);
        printf("TABLE %s rows=%d\n",t->name,rows.n);
        printf("COLUMNS");
        for(int ci=0;ci<t->ncols;ci++){
            if(ci==0)printf(" %s",t->cols[ci].name);
            else printf(", %s",t->cols[ci].name);
        }
        printf("\n");
        for(int ri=0;ri<rows.n;ri++){
            Row*r=&rows.a[ri];
            printf("%" PRId64":",r->rid);
            const uint8_t*pl=r->pl;size_t pn=r->pn;
            size_t off=0;
            uint64_t hdr_sz=rvi(pl,&off,pn);
            size_t hdr_end=hdr_sz;
            int stcap=16,nt=0;uint64_t*sts=malloc(stcap*sizeof(uint64_t));
            while(off<hdr_end&&off<pn){
                if(nt>=stcap){stcap*=2;sts=realloc(sts,stcap*sizeof(uint64_t));}
                sts[nt++]=rvi(pl,&off,hdr_end);
            }
            const uint8_t*body=pl+hdr_end;size_t bpos=0;
            for(int ci=0;ci<t->ncols;ci++){
                if(ci>0)printf(",");
                printf(" ");
                if(t->cols[ci].is_rowid){
                    printf("%" PRId64,r->rid);
                    if(ci<nt){
                        bpos+=skip_serial_bytes(sts[ci]);
                    }
                }else if(ci<nt){
                    print_val(sts[ci],body,&bpos,(uint64_t)r->rid,0);
                }else{
                    printf("NULL");
                }
            }
            printf("\n");
            free(sts);
        }
        for(int i=0;i<rows.n;i++)free(rows.a[i].pl);
        free(rows.a);
        for(int ci=0;ci<t->ncols;ci++)free(t->cols[ci].name);
        free(t->cols);
        free(t->name);
    }

    for(int i=0;i<schema.n;i++)free(schema.a[i].pl);
    free(schema.a);
    free(tbls);
    free(g_data);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

function jsonEscape(s: string): string {
  let result = '"';
  for (let i = 0; i < s.length; ) {
    const cp = s.codePointAt(i)!;
    if (cp === 0x22) { result += '\\"'; i++; }
    else if (cp === 0x5C) { result += '\\\\'; i++; }
    else if (cp === 0x08) { result += '\\b'; i++; }
    else if (cp === 0x0C) { result += '\\f'; i++; }
    else if (cp === 0x0A) { result += '\\n'; i++; }
    else if (cp === 0x0D) { result += '\\r'; i++; }
    else if (cp === 0x09) { result += '\\t'; i++; }
    else if (cp < 0x20) { result += '\\u' + cp.toString(16).padStart(4, '0'); i++; }
    else {
      result += String.fromCodePoint(cp);
      i += cp > 0xFFFF ? 2 : 1;
    }
  }
  result += '"';
  return result;
}

function parseCSV(text: string): string[][] {
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  const records: string[][] = [];
  let i = 0;
  const len = text.length;
  while (i < len) {
    const record: string[] = [];
    while (true) {
      let field = '';
      if (i < len && text[i] === '"') {
        i++;
        while (i < len) {
          if (text[i] === '"') {
            if (i + 1 < len && text[i + 1] === '"') {
              field += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            field += text[i];
            i++;
          }
        }
      } else {
        while (i < len && text[i] !== ',' && text[i] !== '\r' && text[i] !== '\n') {
          field += text[i];
          i++;
        }
      }
      record.push(field);
      if (i < len && text[i] === ',') {
        i++;
      } else {
        if (i < len && text[i] === '\r') { i++; if (i < len && text[i] === '\n') i++; }
        else if (i < len && text[i] === '\n') { i++; }
        break;
      }
    }
    if (record.length > 1 || (record.length === 1 && record[0] !== '') || i < len) {
      records.push(record);
    }
  }
  return records;
}

interface InventoryItem {
  sku: string;
  name: string;
  price_cents: number;
  currency: string;
  stock: number;
}

function parseInventory(text: string): Map<string, InventoryItem> {
  const records = parseCSV(text);
  const map = new Map<string, InventoryItem>();
  for (let i = 1; i < records.length; i++) {
    const rec = records[i];
    if (rec.length < 5) continue;
    map.set(rec[0], {
      sku: rec[0],
      name: rec[1],
      price_cents: parseInt(rec[2], 10),
      currency: rec[3],
      stock: parseInt(rec[4], 10),
    });
  }
  return map;
}

function executeTool(name: string, argsStr: string, inventory: Map<string, InventoryItem>, rates: Record<string, number>): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const item = inventory.get(sku);
    if (item) {
      return '{"sku":' + jsonEscape(item.sku) + ',"name":' + jsonEscape(item.name) + ',"price_cents":' + item.price_cents + ',"currency":' + jsonEscape(item.currency) + ',"stock":' + item.stock + '}';
    } else {
      return '{"error":' + jsonEscape('unknown sku: ' + sku) + '}';
    }
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates[from]);
    const rateTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = numerator / denominator;
    return '{"amount_cents":' + converted.toString() + ',"currency":' + jsonEscape(to) + '}';
  } else {
    return '{"error":' + jsonEscape('unknown tool: ' + name) + '}';
  }
}

function doRequest(url: URL, apiKey: string, body: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const port = url.port ? parseInt(url.port, 10) : 80;
    const req = http.request({
      hostname: url.hostname,
      port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.port ? `${url.hostname}:${url.port}` : url.hostname,
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body, 'utf-8'),
      },
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => { chunks.push(chunk); });
      res.on('end', () => {
        let text = Buffer.concat(chunks).toString('utf-8');
        if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
        resolve({ status: res.statusCode || 0, body: text });
      });
    });
    req.on('error', reject);
    req.write(body, 'utf-8');
    req.end();
  });
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8');
  const task = JSON.parse(taskRaw.charCodeAt(0) === 0xFEFF ? taskRaw.slice(1) : taskRaw);
  const csvText = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8');
  const ratesData = JSON.parse(ratesRaw.charCodeAt(0) === 0xFEFF ? ratesRaw.slice(1) : ratesRaw);

  const inventory = parseInventory(csvText);
  const rates: Record<string, number> = ratesData.rates;

  const conversation: any[] = [
    { role: 'system', content: task.system },
    { role: 'user', content: task.user },
  ];

  const url = new URL(baseUrl + '/chat/completions');

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requests = 0;
  const outputLines: string[] = [];

  while (true) {
    const reqBody = JSON.stringify({
      model: task.model,
      messages: conversation,
      tools: task.tools,
      tool_choice: 'auto',
    });

    const resp = await doRequest(url, task.api_key, reqBody);
    requests++;

    if (resp.status !== 200) {
      for (const line of outputLines) console.log(line);
      let errMsg = '';
      try {
        const errJson = JSON.parse(resp.body);
        errMsg = errJson.error?.message || '';
      } catch { /* ignore */ }
      console.log(`ERROR ${resp.status} ${errMsg}`);
      process.exit(0);
    }

    const respObj = JSON.parse(resp.body);

    if (respObj.usage) {
      totalPrompt += respObj.usage.prompt_tokens || 0;
      totalCompletion += respObj.usage.completion_tokens || 0;
      totalTotal += respObj.usage.total_tokens || 0;
    }

    const choice = respObj.choices[0];
    const message = choice.message;
    const finishReason: string = choice.finish_reason;

    if (finishReason === 'tool_calls') {
      if (typeof message.content === 'string') {
        outputLines.push(`SAY ${message.content}`);
      }

      const toolCalls = message.tool_calls || [];

      for (const tc of toolCalls) {
        outputLines.push(`CALL ${tc.id} ${tc.function.name}`);
      }

      const toolMessages: any[] = [];
      for (const tc of toolCalls) {
        const result = executeTool(tc.function.name, tc.function.arguments, inventory, rates);
        outputLines.push(`RESULT ${tc.id} ${result}`);
        toolMessages.push({ role: 'tool', tool_call_id: tc.id, content: result });
      }

      const assistantMsg: any = {
        role: 'assistant',
        content: message.content !== undefined ? message.content : null,
        tool_calls: toolCalls.map((tc: any) => ({
          id: tc.id,
          type: tc.type,
          function: {
            name: tc.function.name,
            arguments: tc.function.arguments,
          },
        })),
      };
      conversation.push(assistantMsg);
      for (const tm of toolMessages) {
        conversation.push(tm);
      }
    } else {
      outputLines.push(`FINAL ${message.content}`);
      break;
    }
  }

  for (const line of outputLines) console.log(line);
  console.log(`USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalTotal} requests=${requests}`);
  process.exit(0);
}

main().catch((e) => {
  console.error(e);
  process.exit(0);
});

