func executeTool(name: String, argumentsStr: String, inventory: [String: [String: Any]], rates: [String: Int]) -> String {
    guard let argsData = argumentsStr.data(using: .utf8),
          let argsJson = try? JSONSerialization.jsonObject(with: argsData) as? [String: Any] else {
        return "{\"error\":\"unknown tool: \(name)\"}"
    }

