    case "inventory_lookup":
        let sku = argsJson["sku"] as? String ?? ""
        if let row = inventory[sku] {
            let skuVal = row["sku"] as! String
            let nameVal = row["name"] as! String
            let priceVal = row["price_cents"] as! Int
            let currencyVal = row["currency"] as! String
            let stockVal = row["stock"] as! Int
            return "{\"sku\":\(jsonEncodeString(skuVal)),\"name\":\(jsonEncodeString(nameVal)),\"price_cents\":\(priceVal),\"currency\":\(jsonEncodeString(currencyVal)),\"stock\":\(stockVal)}"
        } else {
            return "{\"error\":\"unknown sku: \(jsonEncodeString(sku))\"}"
        }
    case "convert_currency":
        let amountCents = argsJson["amount_cents"] as? Int ?? 0
        let from = argsJson["from"] as? String ?? ""
        let to = argsJson["to"] as? String ?? ""
        let rateFrom = rates[from] ?? 1000000
        let rateTo = rates[to] ?? 1000000
        let numerator = 2 * amountCents * rateTo + rateFrom
        let denominator = 2 * rateFrom
        let converted = numerator / denominator
        return "{\"amount_cents\":\(converted),\"currency\":\(jsonEncodeString(to))}"
    default:
        return "{\"error\":\"unknown tool: \(jsonEncodeString(name))\"}"
    }
}

