// MARK: - JSON encoding helpers
func jEsc(_ s: String) -> String {
    var r = ""
    for sc in s.unicodeScalars {
        switch sc {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\u{0C}": r += "\\f"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if sc.value < 0x20 { r += String(format: "\\u%04x", sc.value) }
            else { r.unicodeScalars.append(sc) }
        }
    }
    return r
}
func jStr(_ s: String) -> String { return "\"" + jEsc(s) + "\"" }

// MARK: - CSV Parser
func parseCSV(_ data: Data) -> [[String]] {
    var text = String(data: data, encoding: .utf8)!
    if text.hasPrefix("\u{FEFF}") { text = String(text.dropFirst()) }
    var records: [[String]] = []
    var fields: [String] = []
    var cur = ""
    var inQ = false
    let chars = Array(text)
    let n = chars.count
    var i = 0
    while i < n {
        let c = chars[i]
        if inQ {
            if c == "\"" {
                if i + 1 < n && chars[i+1] == "\"" { cur.append("\""); i += 2 }
                else { inQ = false; i += 1 }
            } else { cur.append(c); i += 1 }
        } else {
            if c == "\"" { inQ = true; i += 1 }
            else if c == "," { fields.append(cur); cur = ""; i += 1 }
            else if c == "\r" {
                if i + 1 < n && chars[i+1] == "\n" { fields.append(cur); cur = ""; records.append(fields); fields = []; i += 2 }
                else { cur.append(c); i += 1 }
            } else if c == "\n" { fields.append(cur); cur = ""; records.append(fields); fields = []; i += 1 }
            else { cur.append(c); i += 1 }
        }
    }
    if !cur.isEmpty || !fields.isEmpty { fields.append(cur); records.append(fields) }
    return records
}

// MARK: - Extract raw JSON value text for a top-level key
func extractRaw(_ json: String, _ key: String) -> String {
    let search = "\"" + key + "\""
    guard let range = json.range(of: search) else { return "null" }
    var idx = json.index(range.upperBound, offsetBy: 0)
    while idx < json.endIndex && (json[idx] == " " || json[idx] == "\t" || json[idx] == "\n" || json[idx] == "\r" || json[idx] == ":") {
        idx = json.index(after: idx)
    }
    let start = idx
    var depth = 0
    var inStr = false
    var esc = false
    while idx < json.endIndex {
        let c = json[idx]
        if esc { esc = false }
        else if inStr && c == "\\" { esc = true }
        else if c == "\"" { inStr.toggle() }
        else if !inStr {
            if c == "[" || c == "{" { depth += 1 }
            else if c == "]" || c == "}" { depth -= 1; if depth == 0 { idx = json.index(after: idx); break } }
            else if depth == 0 && (c == "," || c == "}") { break }
        }
        idx = json.index(after: idx)
    }
    return String(json[start..<idx])
}

