    }
    task.resume()
    sem.wait()
    return (code, rdata)
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dataDir = args[1]
let baseUrl = args[2]

// Read task.json
let taskRaw = try! String(contentsOfFile: dataDir + "/task.json", encoding: .utf8)
var tjp = JParser(taskRaw)
guard case let .obj(taskObj) = tjp.parse() else { exit(1) }

var apiKey = "", model = "", systemMsg = "", userMsg = ""
var toolsRaw = "[]"
for (k, v) in taskObj {
    if k == "api_key", case let .str(s,_) = v { apiKey = s }
    if k == "model", case let .str(s,_) = v { model = s }
    if k == "system", case let .str(s,_) = v { systemMsg = s }
    if k == "user", case let .str(s,_) = v { userMsg = s }
    if k == "tools" {
        // extract raw text
        toolsRaw = extractRaw(taskRaw, "tools")
    }
}

// Read inventory.csv
let invData = FileManager.default.contents(atPath: dataDir + "/inventory.csv")!
let csvRecs = parseCSV(invData)
var inventory: [String: (String,String,Int,String,Int)] = [:]
if csvRecs.count > 1 {
    for i in 1..<csvRecs.count {
        let row = csvRecs[i]
        if row.count >= 5 {
            let sku = row[0]
            let nm = row[1]
            let pc = Int(row[2]) ?? 0
            let cur = row[3]
            let stk = Int(row[4]) ?? 0
            inventory[sku] = (sku, nm, pc, cur, stk)
        }
    }
}

// Read rates.json
let ratesRaw = try! String(contentsOfFile: dataDir + "/rates.json", encoding: .utf8)
var rjp = JParser(ratesRaw)
var rates: [String:Int] = [:]
if case let .obj(rObj) = rjp.parse() {
    for (k,v) in rObj {
        if k == "rates", case let .obj(ratesObj) = v {
            for (ck, cv) in ratesObj {
                if case let .num(ns) = cv { rates[ck] = Int(ns) ?? 0 }
            }
        }
    }
}

// Conversation messages - stored as raw JSON strings for exact re-sending
var messages: [String] = []
messages.append("{\"role\":\"system\",\"content\":" + jStr(systemMsg) + "}")
messages.append("{\"role\":\"user\",\"content\":" + jStr(userMsg) + "}")

var outputLines: [String] = []
var totalPrompt = 0, totalCompletion = 0, totalTotal = 0, numRequests = 0
let endpoint = baseUrl + "/chat/completions"

while true {
    let body = "{\"model\":" + jStr(model) + ",\"messages\":[" + messages.joined(separator: ",") + "],\"tools\":" + toolsRaw + ",\"tool_choice\":\"auto\"}"
    let (statusCode, respData) = doRequest(url: endpoint, apiKey: apiKey, body: body)
    numRequests += 1

    if statusCode != 200 {
        var errMsg = ""
        let respStr = String(data: respData, encoding: .utf8) ?? ""
        var ejp = JParser(respStr)
        if case let .obj(eObj) = ejp.parse() {
            for (k,v) in eObj {
                if k == "error", case let .obj(errObj) = v {
                    for (ek, ev) in errObj {
                        if ek == "message", case let .str(s,_) = ev { errMsg = s }
                    }
                }
            }
        }
        for l in outputLines { print(l) }
        print("ERROR \(statusCode) \(errMsg)")
        exit(0)
    }

    let respStr = String(data: respData, encoding: .utf8) ?? ""
    var rjp2 = JParser(respStr)
    guard case let .obj(respObj) = rjp2.parse() else {
        for l in outputLines { print(l) }
        print("ERROR \(statusCode) parse error")
        exit(0)
    }

    // Usage
    for (k,v) in respObj {
        if k == "usage", case let .obj(uObj) = v {
            for (uk,uv) in uObj {
                if uk == "prompt_tokens", case let .num(ns) = uv { totalPrompt += Int(ns) ?? 0 }
                if uk == "completion_tokens", case let .num(ns) = uv { totalCompletion += Int(ns) ?? 0 }
                if uk == "total_tokens", case let .num(ns) = uv { totalTotal += Int(ns) ?? 0 }
            }
        }
    }

    // Choices
    var finishReason = ""
    var msgObj: [(String, JSONVal)] = []
    for (k,v) in respObj {
        if k == "choices", case let .arr(choices) = v, let first = choices.first, case let .obj(cObj) = first {
            for (ck, cv) in cObj {
                if ck == "finish_reason", case let .str(s,_) = cv { finishReason = s }
                if ck == "message", case let .obj(mObj) = cv { msgObj = mObj }
            }
        }
    }

    if finishReason == "stop" {
        var content = ""
        for (k,v) in msgObj { if k == "content", case let .str(s,_) = v { content = s } }
        for l in outputLines { print(l) }
        print("FINAL \(content)")
        print("USAGE prompt=\(totalPrompt) completion=\(totalCompletion) total=\(totalTotal) requests=\(numRequests)")
        exit(0)
    }

    if finishReason == "tool_calls" {
        // Get content (string or null)
        var contentJson = "null"
        var contentStr: String? = nil
        for (k,v) in msgObj {
            if k == "content" {
                if case let .str(s, raw) = v { contentJson = raw; contentStr = s }
                else if case .null = v { contentJson = "null" }
            }
        }
        if let c = contentStr { outputLines.append("SAY \(c)") }

        // Get tool_calls - need raw arguments text
        var toolCallsData: [(id: String, type: String, name: String, argsRaw: String)] = []
        for (k,v) in msgObj {
            if k == "tool_calls", case let .arr(tcArr) = v {
                for tcVal in tcArr {
                    guard case let .obj(tcObj) = tcVal else { continue }
                    var tcId = "", tcType = "function", tcName = "", tcArgsRaw = "\"\""
                    for (tk, tv) in tcObj {
                        if tk == "id", case let .str(s,_) = tv { tcId = s }
                        if tk == "type", case let .str(s,_) = tv { tcType = s }
                        if tk == "function", case let .obj(fObj) = tv {
                            for (fk, fv) in fObj {
                                if fk == "name", case let .str(s,_) = fv { tcName = s }
                                if fk == "arguments", case let .str(_, raw) = fv { tcArgsRaw = raw }
                            }
                        }
                    }
                    toolCallsData.append((tcId, tcType, tcName, tcArgsRaw))
                }
            }
        }

        // Build assistant message JSON (preserve raw arguments)
        var tcParts: [String] = []
        for tc in toolCallsData {
            tcParts.append("{\"id\":" + jStr(tc.id) + ",\"type\":" + jStr(tc.type) + ",\"function\":{\"name\":" + jStr(tc.name) + ",\"arguments\":" + tc.argsRaw + "}}")
        }
        let assistantJson = "{\"role\":\"assistant\",\"content\":" + contentJson + ",\"tool_calls\":[" + tcParts.joined(separator: ",") + "]}"
        messages.append(assistantJson)

        // Print CALL lines
        for tc in toolCallsData { outputLines.append("CALL \(tc.id) \(tc.name)") }

        // Execute tools and print RESULT lines, append tool messages
        for tc in toolCallsData {
            // Parse arguments for execution (but don't re-serialize)
            let result = execTool(name: tc.name, argsStr: tc.argsRaw, inventory: inventory, rates: rates)
            outputLines.append("RESULT \(tc.id) \(result)")
            let toolMsg = "{\"role\":\"tool\",\"tool_call_id\":" + jStr(tc.id) + ",\"content\":" + jStr(result) + "}"
            messages.append(toolMsg)
        }
    } else {
        // Treat as stop
        var content = ""
        for (k,v) in msgObj { if k == "content", case let .str(s,_) = v { content = s } }
        for l in outputLines { print(l) }
        print("FINAL \(content)")
        print("USAGE prompt=\(totalPrompt) completion=\(totalCompletion) total=\(totalTotal) requests=\(numRequests)")
        exit(0)
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process;
use std::time::Duration;

#[derive(Clone, Debug)]
enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Arr(Vec<Json>, usize, usize),
    Obj(Vec<(String, Json)>, usize, usize),
}

struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a [u8]) -> Self { Parser { s, pos: 0 } }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        if self.pos < self.s.len() { Some(self.s[self.pos]) } else { None }
    }
    fn eat(&mut self, c: u8) {
        self.skip_ws();
        assert!(self.pos < self.s.len() && self.s[self.pos] == c, "Expected '{}' at {}", c as char, self.pos);
        self.pos += 1;
    }
    fn eat_lit(&mut self, lit: &[u8]) {
        for &c in lit {
            assert!(self.pos < self.s.len() && self.s[self.pos] == c, "Expected literal at {}", self.pos);
            self.pos += 1;
        }
    }
    fn parse(&mut self) -> Json {
        self.skip_ws();
        let start = self.pos;
        match self.peek().unwrap() {
            b'{' => self.parse_obj(start),
            b'[' => self.parse_arr(start),
            b'"' => Json::Str(self.parse_str()),
            b't' => { self.eat_lit(b"true"); Json::Bool(true) }
            b'f' => { self.eat_lit(b"false"); Json::Bool(false) }
            b'n' => { self.eat_lit(b"null"); Json::Null }
            _ => self.parse_num(),
        }
    }
    fn parse_str(&mut self) -> String {
        self.eat(b'"');
        let mut buf = Vec::new();
        loop {
            let c = self.s[self.pos];
            self.pos += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let e = self.s[self.pos]; self.pos += 1;
                match e {
                    b'"' => buf.push(b'"'),
                    b'\\' => buf.push(b'\\'),
                    b'/' => buf.push(b'/'),
                    b'b' => buf.push(8),
                    b'f' => buf.push(12),
                    b'n' => buf.push(b'\n'),
                    b'r' => buf.push(b'\r'),
                    b't' => buf.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert!(self.s[self.pos] == b'\\' && self.s[self.pos + 1] == b'u');
                            self.pos += 2;
                            let lo = self.hex4();
                            let c = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            let ch = char::from_u32(c).unwrap();
                            let mut tmp = [0u8; 4];
                            buf.extend_from_slice(ch.encode_utf8(&mut tmp).as_bytes());
                        } else {
                            let ch = char::from_u32(cp).unwrap();
                            let mut tmp = [0u8; 4];
                            buf.extend_from_slice(ch.encode_utf8(&mut tmp).as_bytes());
                        }
                    }
                    _ => panic!("bad escape"),
                }
            } else {
                buf.push(c);
            }
        }
        String::from_utf8(buf).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.s[self.pos]; self.pos += 1;
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => panic!("bad hex"),
            };
        }
        v
    }
    fn parse_num(&mut self) -> Json {
        let start = self.pos;
        if self.s[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.s.len() && self.s[self.pos].is_ascii_digit() { self.pos += 1; }
        let mut is_f = false;
        if self.pos < self.s.len() && self.s[self.pos] == b'.' {
            is_f = true; self.pos += 1;
            while self.pos < self.s.len() && self.s[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.s.len() && (self.s[self.pos] | 32) == b'e' {
            is_f = true; self.pos += 1;
            if self.pos < self.s.len() && (self.s[self.pos] == b'+' || self.s[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.s.len() && self.s[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let t = std::str::from_utf8(&self.s[start..self.pos]).unwrap();
        if is_f { Json::Float(t.parse().unwrap()) } else { Json::Int(t.parse().unwrap()) }
    }
    fn parse_arr(&mut self, start: usize) -> Json {
        self.eat(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Json::Arr(items, start, self.pos); }
        loop {
            items.push(self.parse());
            self.skip_ws();
            if self.peek() == Some(b',') { self.pos += 1; } else { break; }
        }
        self.eat(b']');
        Json::Arr(items, start, self.pos)
    }
    fn parse_obj(&mut self, start: usize) -> Json {
        self.eat(b'{');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Json::Obj(items, start, self.pos); }
        loop {
            self.skip_ws();
            let k = self.parse_str();
            self.eat(b':');
            let v = self.parse();
            items.push((k, v));
            self.skip_ws();
            if self.peek() == Some(b',') { self.pos += 1; } else { break; }
        }
        self.eat(b'}');
        Json::Obj(items, start, self.pos)
    }
}

fn parse_json(data: &[u8]) -> Json {
    let mut p = Parser::new(data);
    p.parse()
}

fn obj_get<'a>(j: &'a Json, key: &str) -> &'a Json {
    if let Json::Obj(items, _, _) = j {
        for (k, v) in items {
            if k == key { return v; }
        }
    }
    panic!("key not found: {}", key);
}

fn obj_get_opt<'a>(j: &'a Json, key: &str) -> Option<&'a Json> {
    if let Json::Obj(items, _, _) = j {
        for (k, v) in items {
            if k == key { return Some(v); }
        }
    }
    None
}

fn obj_pos(j: &Json) -> (usize, usize) {
    if let Json::Obj(_, s, e) = j { (*s, *e) } else { panic!("not an obj") }
}

fn as_str(j: &Json) -> &str {
    if let Json::Str(s) = j { s } else { panic!("not a string") }
}

fn as_int(j: &Json) -> i64 {
    match j {
        Json::Int(i) => *i,
        Json::Float(f) => *f as i64,
        _ => panic!("not a number"),
    }
}

fn as_arr(j: &Json) -> &[Json] {
    if let Json::Arr(items, _, _) = j { items } else { panic!("not an array") }
}

fn json_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\u{0C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => { r.push_str(&format!("\\u{:04x}", c as u32)); }
            _ => r.push(c),
        }
    }
    r.push('"');
    r
}

fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let mut data = data;
    if data.len() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
        data = &data[3..];
    }
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut pos = 0usize;
    while pos < data.len() {
        let mut fields: Vec<String> = Vec::new();
        loop {
            if pos < data.len() && data[pos] == b'"' {
                pos += 1;
                let mut field = Vec::new();
                loop {
                    if pos >= data.len() { break; }
                    if data[pos] == b'"' {
                        if pos + 1 < data.len() && data[pos + 1] == b'"' {
                            field.push(b'"');
                            pos += 2;
                        } else {
                            pos += 1;
                            break;
                        }
                    } else {
                        field.push(data[pos]);
                        pos += 1;
                    }
                }
                fields.push(String::from_utf8(field).unwrap());
            } else {
                let mut field = Vec::new();
                while pos < data.len() && data[pos] != b',' && data[pos] != b'\r' && data[pos] != b'\n' {
                    field.push(data[pos]);
                    pos += 1;
                }
                fields.push(String::from_utf8(field).unwrap());
            }
            if pos < data.len() && data[pos] == b',' {
                pos += 1;
            } else {
                break;
            }
        }
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        if pos < data.len() && data[pos] == b'\n' { pos += 1; }
        if !(fields.len() == 1 && fields[0].is_empty() && pos >= data.len()) {
            records.push(fields);
        }
    }
    records
}

struct InvRow {
    sku: String,
    name: String,
    price_cents: i64,
    currency: String,
    stock: i64,
}

fn http_post(host: &str, port: u16, path: &str, auth: &str, body: &[u8]) -> (u16, Vec<u8>) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    stream.set_read_timeout(Some(Duration::from_secs(120))).unwrap();
    stream.set_write_timeout(Some(Duration::from_secs(60))).unwrap();
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        path, host, port, auth, body.len()
    );
    stream.write_all(req.as_bytes()).unwrap();
    stream.write_all(body).unwrap();
    stream.flush().unwrap();
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).unwrap();
    let mut sep = None;
    for i in 0..buf.len().saturating_sub(3) {
        if buf[i] == b'\r' && buf[i+1] == b'\n' && buf[i+2] == b'\r' && buf[i+3] == b'\n' {
            sep = Some(i);
            break;
        }
    }
    let sep = sep.expect("no header separator");
    let header_bytes = &buf[..sep];
    let body_bytes = &buf[sep + 4..];
    let status_line = std::str::from_utf8(&header_bytes[..header_bytes.iter().position(|&b| b == b'\r').unwrap_or(header_bytes.len())]).unwrap();
    let status: u16 = status_line.split_whitespace().nth(1).unwrap().parse().unwrap();
    (status, body_bytes.to_vec())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let task_data = fs::read(format!("{}/task.json", data_dir)).unwrap();
    let inv_data = fs::read(format!("{}/inventory.csv", data_dir)).unwrap();
    let rates_data = fs::read(format!("{}/rates.json", data_dir)).unwrap();

    let task = parse_json(&task_data);
    let api_key = as_str(obj_get(&task, "api_key")).to_string();
    let model = as_str(obj_get(&task, "model")).to_string();
    let system = as_str(obj_get(&task, "system")).to_string();
    let user = as_str(obj_get(&task, "user")).to_string();
    let (tools_start, tools_end) = if let Json::Arr(_, s, e) = obj_get(&task, "tools") { (*s, *e) } else { panic!("tools not arr") };
    let tools_raw = String::from_utf8(task_data[tools_start..tools_end].to_vec()).unwrap();

    let csv = parse_csv(&inv_data);
    let mut inventory: HashMap<String, InvRow> = HashMap::new();
    for (i, row) in csv.iter().enumerate() {
        if i == 0 { continue; } // skip header
        if row.len() < 5 { continue; }
        let inv = InvRow {
            sku: row[0].clone(),
            name: row[1].clone(),
            price_cents: row[2].parse::<i64>().unwrap(),
            currency: row[3].clone(),
            stock: row[4].parse::<i64>().unwrap(),
        };
        inventory.insert(inv.sku.clone(), inv);
    }

    let rates_json = parse_json(&rates_data);
    let rates_obj = obj_get(&rates_json, "rates");
    let mut rates_map: HashMap<String, i64> = HashMap::new();
    if let Json::Obj(items, _, _) = rates_obj {
        for (k, v) in items {
            rates_map.insert(k.clone(), as_int(v));
        }
    }

    let (host, port, path) = parse_url(base_url);
    let endpoint = format!("{}/chat/completions", path);

    let mut messages: Vec<String> = Vec::new();
    messages.push(format!("{{\"role\":\"system\",\"content\":{}}}", json_str(&system)));
    messages.push(format!("{{\"role\":\"user\",\"content\":{}}}", json_str(&user)));

    let mut total_prompt: i64 = 0;
    let mut total_completion: i64 = 0;
    let mut total_tokens: i64 = 0;
    let mut num_requests: i64 = 0;

    loop {
        let msgs_json = format!("[{}]", messages.join(","));
        let body = format!("{{\"model\":{},\"messages\":{},\"tools\":{},\"tool_choice\":\"auto\"}}",
            json_str(&model), msgs_json, tools_raw);

        num_requests += 1;
        let (status, resp_body) = http_post(&host, port, &endpoint, &api_key, body.as_bytes());

        if status != 200 {
            let err_json = parse_json(&resp_body);
            let err_obj = obj_get(&err_json, "error");
            let err_msg = as_str(obj_get(err_obj, "message"));
            println!("ERROR {} {}", status, err_msg);
            process::exit(0);
        }

        let resp = parse_json(&resp_body);

        if let Some(usage) = obj_get_opt(&resp, "usage") {
            total_prompt += as_int(obj_get(usage, "prompt_tokens"));
            total_completion += as_int(obj_get(usage, "completion_tokens"));
            total_tokens += as_int(obj_get(usage, "total_tokens"));
        }

        let choices = as_arr(obj_get(&resp, "choices"));
        let choice = &choices[0];
        let finish_reason = as_str(obj_get(choice, "finish_reason"));
        let msg = obj_get(choice, "message");

        if finish_reason == "tool_calls" {
            if let Some(content_val) = obj_get_opt(msg, "content") {
                if let Json::Str(s) = content_val {
                    println!("SAY {}", s);
                }
            }

            let tool_calls = as_arr(obj_get(msg, "tool_calls"));
            let mut results: Vec<(String, String)> = Vec::new();

            for tc in tool_calls {
                let id = as_str(obj_get(tc, "id")).to_string();
                let func = obj_get(tc, "function");
                let name = as_str(obj_get(func, "name")).to_string();
                let args_str = as_str(obj_get(func, "arguments")).to_string();
                println!("CALL {} {}", id, name);
                let result = execute_tool(&name, &args_str, &inventory, &rates_map);
                results.push((id, result));
            }

            for (id, result) in &results {
                println!("RESULT {} {}", id, result);
            }

            let (ms, me) = obj_pos(msg);
            let raw_msg = String::from_utf8(resp_body[ms..me].to_vec()).unwrap();
            messages.push(raw_msg);

            for (id, result) in &results {
                messages.push(format!("{{\"role\":\"tool\",\"tool_call_id\":{},\"content\":{}}}",
                    json_str(id), json_str(result)));
            }
        } else {
            let content = as_str(obj_get(msg, "content"));
            println!("FINAL {}", content);
            break;
        }
    }

    println!("USAGE prompt={} completion={} total={} requests={}",
        total_prompt, total_completion, total_tokens, num_requests);
}

fn execute_tool(name: &str, args_str: &str, inventory: &HashMap<String, InvRow>, rates: &HashMap<String, i64>) -> String {
    match name {
        "inventory_lookup" => {
            let args = parse_json(args_str.as_bytes());
            let sku = as_str(obj_get(&args, "sku"));
            match inventory.get(sku) {
                Some(row) => {
                    format!("{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                        json_str(&row.sku), json_str(&row.name), row.price_cents,
                        json_str(&row.currency), row.stock)
                }
                None => {
                    format!("{{\"error\":{}}}", json_str(&format!("unknown sku: {}", sku)))
                }
            }
        }
        "convert_currency" => {
            let args = parse_json(args_str.as_bytes());
            let amount_cents = as_int(obj_get(&args, "amount_cents"));
            let from = as_str(obj_get(&args, "from"));
            let to = as_str(obj_get(&args, "to"));
            let rate_from = rates[from];
            let rate_to = rates[to];
            let numerator = 2 * amount_cents * rate_to + rate_from;
            let denominator = 2 * rate_from;
            let converted = numerator / denominator;
            format!("{{\"amount_cents\":{},\"currency\":{}}}", converted, json_str(to))
        }
        _ => {
            format!("{{\"error\":{}}}", json_str(&format!("unknown tool: {}", name)))
        }
    }
}

fn parse_url(url: &str) -> (String, u16, String) {
    let url = url.strip_prefix("http://").unwrap_or(url);
    let slash_pos = url.find('/').unwrap_or(url.len());
    let host_port = &url[..slash_pos];
    let path = if slash_pos < url.len() { &url[slash_pos..] } else { "" };
    let (host, port) = if let Some(cp) = host_port.rfind(':') {
        (host_port[..cp].to_string(), host_port[cp + 1..].parse::<u16>().unwrap())
    } else {
        (host_port.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
