import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> wavFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wavFiles.add(f);
            }
        }

        wavFiles.sort((a, b) -> {
            byte[] an = a.getName().getBytes("UTF-8");
            byte[] bn = b.getName().getBytes("UTF-8");
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int cmp = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return an.length - bn.length;
        });

        boolean first = true;
        for (File f : wavFiles) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        String name = f.getName();

        if (data.length < 12) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F'
                || data[8] != 'W' || data[9] != 'A' || data[10] != 'V' || data[11] != 'E') {
            System.out.println(name + ": unsupported");
            return;
        }

        byte[] fmtBody = null;
        byte[] dataBody = null;
        int pos = 12;
        while (pos + 8 <= data.length) {
            String chunkId = new String(data, pos, 4, "US-ASCII");
            int chunkSize = readLE32(data, pos + 4);
            pos += 8;
            if (pos + chunkSize > data.length) chunkSize = data.length - pos;
            if (chunkId.equals("fmt ")) {
                fmtBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            } else if (chunkId.equals("data")) {
                dataBody = Arrays.copyOfRange(data, pos, pos + chunkSize);
            }
            pos += chunkSize;
            if (chunkSize % 2 != 0) pos++;
        }

        if (fmtBody == null || dataBody == null || fmtBody.length < 16) {
            System.out.println(name + ": unsupported");
            return;
        }

        int formatTag = readLE16(fmtBody, 0);
        int channels = readLE16(fmtBody, 2);
        int sampleRate = readLE32(fmtBody, 4);
        int bitsPerSample = readLE16(fmtBody, 14);

        int effectiveFormat;
        if (formatTag == 0xFFFE) {
            if (fmtBody.length > 25) {
                effectiveFormat = readLE16(fmtBody, 24);
            } else {
                effectiveFormat = formatTag;
            }
        } else {
            effectiveFormat = formatTag;
        }

        if (effectiveFormat != 1 || bitsPerSample != 16) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (channels != 1 && channels != 2) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (sampleRate != 8000 && sampleRate != 16000) {
            System.out.println(name + ": unsupported");
            return;
        }

        int numFrames = dataBody.length / (2 * channels);
        int[] leftSamples = new int[numFrames];
        for (int i = 0; i < numFrames; i++) {
            int offset = i * 2 * channels;
            leftSamples[i] = (short) readLE16(dataBody, offset);
        }

        int N = sampleRate / 50;
        int numBlocks = numFrames / N;

        double[] lowFreqs = {697, 770, 852, 941};
        double[] highFreqs = {1209, 1336, 1477, 1633};
        char[][] keypad = {
            {'1', '2', '3', 'A'},
            {'4', '5', '6', 'B'},
            {'7', '8', '9', 'C'},
            {'*', '0', '#', 'D'}
        };

        char[] labels = new char[numBlocks];

        for (int b = 0; b < numBlocks; b++) {
            int start = b * N;
            double E = 0;
            for (int n = 0; n < N; n++) {
                double x = leftSamples[start + n];
                E += x * x;
            }

            if (E < 1000000.0 * N) {
                labels[b] = 0;
                continue;
            }

            double maxRl = -1, maxRh = -1;
            int bestLi = -1, bestHi = -1;

            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(leftSamples, start, N, lowFreqs[fi], sampleRate, E);
                if (r > maxRl) {
                    maxRl = r;
                    bestLi = fi;
                }
            }
            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(leftSamples, start, N, highFreqs[fi], sampleRate, E);
                if (r > maxRh) {
                    maxRh = r;
                    bestHi = fi;
                }
            }

            if (maxRl >= 0.1 && maxRh >= 0.1 && maxRl + maxRh >= 0.6) {
                labels[b] = keypad[bestLi][bestHi];
            } else {
                labels[b] = 0;
            }
        }

        // Bridging: use original labels for neighbor checks
        char[] bridged = Arrays.copyOf(labels, numBlocks);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (labels[i] == 0 && labels[i - 1] != 0 && labels[i - 1] == labels[i + 1]) {
                bridged[i] = labels[i - 1];
            }
        }

        // Events: maximal runs of same digit >= 2 blocks
        List<int[]> events = new ArrayList<>();
        List<Character> eventDigits = new ArrayList<>();

        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == 0) {
                i++;
                continue;
            }
            char digit = bridged[i];
            int startBlock = i;
            while (i < numBlocks && bridged[i] == digit) {
                i++;
            }
            int endBlock = i - 1;
            if (endBlock - startBlock + 1 >= 2) {
                events.add(new int[]{startBlock, endBlock});
                eventDigits.add(digit);
            }
        }

        // Output
        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        StringBuilder digits = new StringBuilder();
        for (int ei = 0; ei < events.size(); ei++) {
            int[] ev = events.get(ei);
            int startMs = 20 * ev[0];
            int endMs = 20 * (ev[1] + 1);
            System.out.println(eventDigits.get(ei) + " " + startMs + " " + endMs);
            digits.append(eventDigits.get(ei));
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(int[] samples, int start, int N, double freq, int rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double x = samples[start + n];
            double s = x + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readLE16(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }

    static int readLE32(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8)
             | ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }
}

