import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Type {
        int gmtoff;
        boolean isdst;
        String abbr;
        Type(int gmtoff, boolean isdst, String abbr) {
            this.gmtoff = gmtoff; this.isdst = isdst; this.abbr = abbr;
        }
    }

    static class TzifData {
        long[] transTimes;
        int[] transTypeIdx;
        Type[] types;
        String stdName, dstName;
        int stdGmtoff, dstGmtoff;
        boolean hasDst, hasRule;
        int sm, sw, sd, sh, smi, ss;
        int em, ew, ed, eh, emi, es;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData d = cache.get(fileName);
            if (d == null) {
                d = parseTzif(dir + "/" + fileName);
                cache.put(fileName, d);
            }

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                out.append(line).append(" -> ").append(utcQuery(d, t)).append("\n");
            } else {
                String wall = parts[2];
                out.append(line).append(" -> ").append(localQuery(d, wall)).append("\n");
            }
        }
        System.out.print(out.toString());
    }

    static TzifData parseTzif(String path) throws Exception {
        byte[] b = Files.readAllBytes(Paths.get(path));
        int pos = 0;
        // First header: 44 bytes
        pos += 4; // TZif
        pos += 1; // version
        pos += 15; // unused
        int isutcnt1 = readInt32(b, pos); pos += 4;
        int isstdcnt1 = readInt32(b, pos); pos += 4;
        int leapcnt1 = readInt32(b, pos); pos += 4;
        int timecnt1 = readInt32(b, pos); pos += 4;
        int typecnt1 = readInt32(b, pos); pos += 4;
        int charcnt1 = readInt32(b, pos); pos += 4;
        // Skip first data block
        pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        // Second header: 44 bytes
        pos += 4; pos += 1; pos += 15;
        int isutcnt = readInt32(b, pos); pos += 4;
        int isstdcnt = readInt32(b, pos); pos += 4;
        int leapcnt = readInt32(b, pos); pos += 4;
        int timecnt = readInt32(b, pos); pos += 4;
        int typecnt = readInt32(b, pos); pos += 4;
        int charcnt = readInt32(b, pos); pos += 4;

        TzifData d = new TzifData();
        d.transTimes = new long[timecnt];
        d.transTypeIdx = new int[timecnt];
        d.types = new Type[typecnt];

        for (int i = 0; i < timecnt; i++) {
            d.transTimes[i] = readInt64(b, pos); pos += 8;
        }
        for (int i = 0; i < timecnt; i++) {
            d.transTypeIdx[i] = b[pos] & 0xFF; pos++;
        }
        for (int i = 0; i < typecnt; i++) {
            int gmtoff = readInt32(b, pos); pos += 4;
            boolean isdst = b[pos] != 0; pos++;
            int abbrIdx = b[pos] & 0xFF; pos++;
            d.types[i] = new Type(gmtoff, isdst, null); // abbr filled later
        }
        byte[] abbrs = Arrays.copyOfRange(b, pos, pos + charcnt); pos += charcnt;
        for (int i = 0; i < typecnt; i++) {
            int idx = 0;
            for (int j = 0; j < i; j++) {
                idx = d.types[j].abbr.length();
                while (idx < abbrs.length && abbrs[idx] != 0) idx++;
                idx++; // skip NUL
            }
            // Actually let's recompute: find the abbreviation for type i
            // We need to find the start of the i-th abbreviation
            // Let me redo this properly
        }
        // Redo abbreviation parsing
        for (int i = 0; i < typecnt; i++) {
            int abbrIdx = getAbbrIdx(b, pos - charcnt - typecnt * 6 + i * 6 + 5);
            // Actually the abbr index was stored in the type record. Let me re-read.
            // I'll store it temporarily.
        }
        // Let me redo the type parsing to store abbr index
        // Actually let me restructure: read abbr indices first, then resolve
        // I'll re-parse types
        int typeStart = pos - charcnt - typecnt * 6;
        for (int i = 0; i < typecnt; i++) {
            int abbrIdx = b[typeStart + i * 6 + 5] & 0xFF;
            d.types[i] = new Type(readInt32(b, typeStart + i * 6), b[typeStart + i * 6 + 4] != 0, null);
            d.types[i].abbr = readNullTerminated(abbrs, abbrIdx);
        }
        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;
        // Footer: \n POSIX \n
        pos++; // skip newline
        int footStart = pos;
        while (pos < b.length && b[pos] != '\n') pos++;
        String posixStr = new String(b, footStart, pos - footStart, "ISO-8859-1");
        parsePosix(d, posixStr);
        return d;
    }

    static int getAbbrIdx(byte[] b, int off) { return b[off] & 0xFF; }

    static String readNullTerminated(byte[] arr, int start) {
        int end = start;
        while (end < arr.length && arr[end] != 0) end++;
        return new String(arr, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
    }

    static void parsePosix(TzifData d, String s) {
        if (s == null || s.isEmpty()) {
            d.hasDst = false; d.hasRule = false;
            d.stdName = ""; d.stdGmtoff = 0;
            return;
        }
        int pos = 0;
        // Parse std name
        int[] r = parseName(s, pos);
        d.stdName = s.substring(pos, r[0]); pos = r[0];
        // Parse std offset
        r = parseOffset(s, pos);
        d.stdGmtoff = -r[0]; pos = r[1]; // gmtoff = -posix_offset
        d.hasDst = false; d.hasRule = false;
        d.dstGmtoff = d.stdGmtoff + 3600;
        if (pos >= s.length()) return;
        // Parse dst name
        r = parseName(s, pos);
        d.dstName = s.substring(pos, r[0]); pos = r[0];
        d.hasDst = true;
        // Parse dst offset (optional, not if next char is ',')
        if (pos < s.length() && s.charAt(pos) != ',') {
            r = parseOffset(s, pos);
            d.dstGmtoff = -r[0]; pos = r[1];
        } else {
            d.dstGmtoff = d.stdGmtoff + 3600;
        }
        // Parse rules
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++; // skip comma
            d.hasRule = true;
            r = parseRule(s, pos);
            d.sm = r[0]; d.sw = r[1]; d.sd = r[2]; d.sh = r[3]; d.smi = r[4]; d.ss = r[5];
            pos = r[6];
            if (pos < s.length() && s.charAt(pos) == ',') pos++;
            r = parseRule(s, pos);
            d.em = r[0]; d.ew = r[1]; d.ed = r[2]; d.eh = r[3]; d.emi = r[4]; d.es = r[5];
        }
    }

    static int[] parseName(String s, int pos) {
        if (s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            return new int[]{end + 1};
        } else {
            int end = pos;
            while (end < s.length() && Character.isLetter(s.charAt(end))) end++;
            return new int[]{end};
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (s.charAt(pos) == '+') { pos++; }
        else if (s.charAt(pos) == '-') { sign = -1; pos++; }
        int h = 0, m = 0, sec = 0;
        int start = pos;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { h = h * 10 + (s.charAt(pos++) - '0'); }
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { m = m * 10 + (s.charAt(pos++) - '0'); }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { sec = sec * 10 + (s.charAt(pos++) - '0'); }
            }
        }
        return new int[]{sign * (h * 3600 + m * 60 + sec), pos};
    }

    static int[] parseRule(String s, int pos) {
        // Mm.w.d[/time]
        // s.charAt(pos) should be 'M'
        pos++; // skip M
        int m = 0; while (Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int w = 0; while (Character.isDigit(s.charAt(pos))) w = w * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int d = 0; while (Character.isDigit(s.charAt(pos))) d = d * 10 + (s.charAt(pos++) - '0');
        int h = 2, mi = 0, sec = 0;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int sign = 1;
            if (s.charAt(pos) == '+') pos++;
            else if (s.charAt(pos) == '-') { sign = -1; pos++; }
            h = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) h = h * 10 + (s.charAt(pos++) - '0');
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) mi = mi * 10 + (s.charAt(pos++) - '0');
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) sec = sec * 10 + (s.charAt(pos++) - '0');
                }
            }
            h *= sign;
        }
        return new int[]{m, w, d, h, mi, sec, pos};
    }

    static Type getTypeAt(TzifData d, long t) {
        if (d.transTimes.length == 0) {
            return posixType(d, t);
        }
        if (t < d.transTimes[0]) return d.types[0];
        if (t > d.transTimes[d.transTimes.length - 1]) return posixType(d, t);
        // Binary search: latest transition <= t
        int lo = 0, hi = d.transTimes.length - 1, idx = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (d.transTimes[mid] <= t) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return d.types[d.transTypeIdx[idx]];
    }

    static Type posixType(TzifData d, long t) {
        if (!d.hasDst || !d.hasRule) return new Type(d.stdGmtoff, false, d.stdName);
        int year = epochToYear(t);
        long startUtc = posixTransitionUtc(d, year, true);
        long endUtc = posixTransitionUtc(d, year, false);
        boolean inDst;
        if (startUtc <= endUtc) {
            inDst = t >= startUtc && t < endUtc;
        } else {
            inDst = t >= startUtc || t < endUtc;
        }
        if (inDst) return new Type(d.dstGmtoff, true, d.dstName);
        else return new Type(d.stdGmtoff, false, d.stdName);
    }

    static long posixTransitionUtc(TzifData d, int year, boolean isStart) {
        int m, w, dow, h, mi, sec, gmtoff;
        if (isStart) {
            m = d.sm; w = d.sw; dow = d.sd; h = d.sh; mi = d.smi; sec = d.ss;
            gmtoff = d.stdGmtoff;
        } else {
            m = d.em; w = d.ew; dow = d.ed; h = d.eh; mi = d.emi; sec = d.es;
            gmtoff = d.dstGmtoff;
        }
        int day = computeMDay(year, m, w, dow);
        long localSec = dateTimeToEpoch(year, m, day, h, mi, sec);
        return localSec - gmtoff; // UTC = local - gmtoff
    }

    static String utcQuery(TzifData d, long t) {
        Type type = getTypeAt(d, t);
        long localSec = t + type.gmtoff;
        String dt = epochToDateTimeStr(localSec);
        String off = formatOffset(type.gmtoff);
        return dt + off + " " + type.abbr;
    }

    static String localQuery(TzifData d, String wall) {
        // Parse wall clock
        int y = Integer.parseInt(wall.substring(0, 4));
        int mo = Integer.parseInt(wall.substring(5, 7));
        int da = Integer.parseInt(wall.substring(8, 10));
        int h = Integer.parseInt(wall.substring(11, 13));
        int mi = Integer.parseInt(wall.substring(14, 16));
        int se = Integer.parseInt(wall.substring(17, 19));
        long localEpoch = dateTimeToEpoch(y, mo, da, h, mi, se);

        // Collect all candidate (gmtoff, abbr) pairs
        Set<String> seen = new HashSet<>();
        List<int[]> candidates = new ArrayList<>(); // [gmtoff, abbrIndex]
        List<String> abbrs = new ArrayList<>();

        // From types
        for (Type tp : d.types) {
            String key = tp.gmtoff + "|" + tp.abbr;
            if (seen.add(key)) {
                candidates.add(new int[]{tp.gmtoff, -1});
                abbrs.add(tp.abbr);
            }
        }
        // From POSIX
        if (d.stdName != null && !d.stdName.isEmpty()) {
            String key = d.stdGmtoff + "|" + d.stdName;
            if (seen.add(key)) {
                candidates.add(new int[]{d.stdGmtoff, -1});
                abbrs.add(d.stdName);
            }
        }
        if (d.hasDst && d.dstName != null && !d.dstName.isEmpty()) {
            String key = d.dstGmtoff + "|" + d.dstName;
            if (seen.add(key)) {
                candidates.add(new int[]{d.dstGmtoff, -1});
                abbrs.add(d.dstName);
            }
        }

        // Enumerate and verify
        List<long[]> results = new ArrayList<>(); // [t, gmtoff, abbrIdx]
        for (int i = 0; i < candidates.size(); i++) {
            int gmtoff = candidates.get(i)[0];
            String abbr = abbrs.get(i);
            long tCand = localEpoch - gmtoff;
            Type actual = getTypeAt(d, tCand);
            if (actual.gmtoff == gmtoff && actual.abbr.equals(abbr)) {
                results.add(new long[]{tCand, gmtoff, i});
            }
        }
        results.sort((a, b) -> Long.compare(a[0], b[0]));

        if (results.size() == 1) {
            long t = results.get(0)[0];
            int gmtoff = (int)results.get(0)[1];
            String abbr = abbrs.get((int)results.get(0)[2]);
            return t + " " + formatOffset(gmtoff) + " " + abbr;
        } else if (results.size() == 2) {
            long t1 = results.get(0)[0]; int g1 = (int)results.get(0)[1]; String a1 = abbrs.get((int)results.get(0)[2]);
            long t2 = results.get(1)[0]; int g2 = (int)results.get(1)[1]; String a2 = abbrs.get((int)results.get(1)[2]);
            return t1 + " " + formatOffset(g1) + " " + a1 + " | " + t2 + " " + formatOffset(g2) + " " + a2;
        } else {
            // Gap: find the transition that skipped this wall-clock time
            // t = localEpoch - gmtoff_before
            long tGap = findGapT(d, localEpoch);
            Type typeAtGap = getTypeAt(d, tGap);
            String dt = epochToDateTimeStr(tGap + typeAtGap.gmtoff);
            String off = formatOffset(typeAtGap.gmtoff);
            return "GAP " + tGap + " " + dt + off + " " + typeAtGap.abbr;
        }
    }

    static long findGapT(TzifData d, long localEpoch) {
        // Check TZif transitions
        for (int i = 0; i < d.transTimes.length; i++) {
            long T = d.transTimes[i];
            Type before;
            if (i == 0) before = d.types[0];
            else before = d.types[d.transTypeIdx[i - 1]];
            Type after = d.types[d.transTypeIdx[i]];
            if (after.gmtoff > before.gmtoff) {
                long gapStart = T + before.gmtoff;
                long gapEnd = T + after.gmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - before.gmtoff;
                }
            }
        }
        // Check POSIX transitions for nearby years
        int year = epochToYear(localEpoch); // approximate
        for (int yr = year - 1; yr <= year + 1; yr++) {
            if (!d.hasDst || !d.hasRule) continue;
            long startUtc = posixTransitionUtc(d, yr, true);
            long endUtc = posixTransitionUtc(d, yr, false);
            // Spring forward: STD -> DST at startUtc
            if (d.dstGmtoff > d.stdGmtoff) {
                long gapStart = startUtc + d.stdGmtoff;
                long gapEnd = startUtc + d.dstGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.stdGmtoff;
                }
            }
            // Check if end is also a spring forward (unusual)
            if (d.stdGmtoff > d.dstGmtoff) {
                long gapStart = endUtc + d.dstGmtoff;
                long gapEnd = endUtc + d.stdGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.dstGmtoff;
                }
            }
        }
        // Fallback (shouldn't happen)
        return localEpoch;
    }

    // --- Date/Time utilities ---

    static long dateTimeToEpoch(int y, int m, int d, int h, int mi, int s) {
        long days = daysFromCivil(y, m, d);
        return days * 86400L + h * 3600L + mi * 60L + s;
    }

    static String epochToDateTimeStr(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        long rem = Math.floorMod(epochSec, 86400);
        int[] ymd = civilFromDays(days);
        int h = (int)(rem / 3600); rem %= 3600;
        int mi = (int)(rem / 60);
        int se = (int)(rem % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", ymd[0], ymd[1], ymd[2], h, mi, se);
    }

    static int epochToYear(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        return civilFromDays(days)[0];
    }

    // Howard Hinnant's algorithms
    static long daysFromCivil(long y, long m, long d) {
        y -= m <= 2 ? 1 : 0;
        long era = (y >= 0 ? y : y - 399) / 400;
        long yoe = y - era * 400;
        long mp = m + (m > 2 ? -3 : 9);
        long doy = (153 * mp + 2) / 5 + d - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe - 719468;
    }

    static int[] civilFromDays(long z) {
        z += 719468;
        long era = (z >= 0 ? z : z - 146096) / 146097;
        long doe = z - era * 146097;
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        long mp = (5 * doy + 2) / 153;
        long d = doy - (153 * mp + 2) / 5 + 1;
        long m = mp < 10 ? mp + 3 : mp - 9;
        y += (m <= 2) ? 1 : 0;
        return new int[]{(int)y, (int)m, (int)d};
    }

    static int dayOfWeek(int y, int m, int d) {
        long days = daysFromCivil(y, m, d);
        return (int)((days + 4) % 7 + 7) % 7; // 0=Sun
    }

    static int daysInMonth(int y, int m) {
        int[] dm = {0,31,28,31,30,31,30,31,31,30,31,30,31};
        if (m == 2 && isLeap(y)) return 29;
        return dm[m];
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int computeMDay(int year, int month, int week, int dow) {
        int dowFirst = dayOfWeek(year, month, 1);
        int first = 1 + ((dow - dowFirst + 7) % 7);
        if (week == 5) {
            int lastDay = daysInMonth(year, month);
            int dowLast = dayOfWeek(year, month, lastDay);
            return lastDay - ((dowLast - dow + 7) % 7);
        } else {
            return first + (week - 1) * 7;
        }
    }

    static String formatOffset(int gmtoff) {
        int sign = gmtoff >= 0 ? 1 : -1;
        int abs = Math.abs(gmtoff);
        int h = abs / 3600; abs %= 3600;
        int m = abs / 60;
        int s = abs % 60;
        String signStr = sign >= 0 ? "+" : "-";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", signStr, h, m, s);
        } else {
            return String.format("%s%02d:%02d", signStr, h, m);
        }
    }

    // --- Binary reading ---
    static int readInt32(byte[] b, int off) {
        return ((b[off] & 0xFF) << 24) | ((b[off+1] & 0xFF) << 16) |
               ((b[off+2] & 0xFF) << 8) | (b[off+3] & 0xFF);
    }

    static long readInt64(byte[] b, int off) {
        return ((long)readInt32(b, off) << 32) | (readInt32(b, off + 4) & 0xFFFFFFFFL);
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Type {
        int gmtoff;
        boolean isdst;
        String abbr;
        Type(int gmtoff, boolean isdst, String abbr) {
            this.gmtoff = gmtoff; this.isdst = isdst; this.abbr = abbr;
        }
    }

    static class TzifData {
        long[] transTimes;
        int[] transTypeIdx;
        Type[] types;
        String stdName, dstName;
        int stdGmtoff, dstGmtoff;
        boolean hasDst, hasRule;
        int sm, sw, sd, sh, smi, ss;
        int em, ew, ed, eh, emi, es;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData d = cache.get(fileName);
            if (d == null) {
                d = parseTzif(dir + "/" + fileName);
                cache.put(fileName, d);
            }

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                out.append(line).append(" -> ").append(utcQuery(d, t)).append("\n");
            } else {
                String wall = parts[2];
                out.append(line).append(" -> ").append(localQuery(d, wall)).append("\n");
            }
        }
        System.out.print(out.toString());
    }

    static TzifData parseTzif(String path) throws Exception {
        byte[] b = Files.readAllBytes(Paths.get(path));
        int pos = 0;
        // First header: 44 bytes
        pos += 4; // TZif
        pos += 1; // version
        pos += 15; // unused
        int isutcnt1 = readInt32(b, pos); pos += 4;
        int isstdcnt1 = readInt32(b, pos); pos += 4;
        int leapcnt1 = readInt32(b, pos); pos += 4;
        int timecnt1 = readInt32(b, pos); pos += 4;
        int typecnt1 = readInt32(b, pos); pos += 4;
        int charcnt1 = readInt32(b, pos); pos += 4;
        // Skip first data block
        pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        // Second header: 44 bytes
        pos += 4; pos += 1; pos += 15;
        int isutcnt = readInt32(b, pos); pos += 4;
        int isstdcnt = readInt32(b, pos); pos += 4;
        int leapcnt = readInt32(b, pos); pos += 4;
        int timecnt = readInt32(b, pos); pos += 4;
        int typecnt = readInt32(b, pos); pos += 4;
        int charcnt = readInt32(b, pos); pos += 4;

        TzifData d = new TzifData();
        d.transTimes = new long[timecnt];
        d.transTypeIdx = new int[timecnt];
        d.types = new Type[typecnt];

        for (int i = 0; i < timecnt; i++) {
            d.transTimes[i] = readInt64(b, pos); pos += 8;
        }
        for (int i = 0; i < timecnt; i++) {
            d.transTypeIdx[i] = b[pos] & 0xFF; pos++;
        }
        int[] abbrIdxs = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            int gmtoff = readInt32(b, pos); pos += 4;
            boolean isdst = b[pos] != 0; pos++;
            abbrIdxs[i] = b[pos] & 0xFF; pos++;
            d.types[i] = new Type(gmtoff, isdst, null);
        }
        byte[] abbrs = Arrays.copyOfRange(b, pos, pos + charcnt); pos += charcnt;
        for (int i = 0; i < typecnt; i++) {
            d.types[i].abbr = readNullTerminated(abbrs, abbrIdxs[i]);
        }
        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;
        // Footer: \n POSIX \n
        pos++; // skip newline
        int footStart = pos;
        while (pos < b.length && b[pos] != '\n') pos++;
        String posixStr = new String(b, footStart, pos - footStart, "ISO-8859-1");
        parsePosix(d, posixStr);
        return d;
    }

    static String readNullTerminated(byte[] arr, int start) {
        int end = start;
        while (end < arr.length && arr[end] != 0) end++;
        return new String(arr, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
    }

    static void parsePosix(TzifData d, String s) {
        if (s == null || s.isEmpty()) {
            d.hasDst = false; d.hasRule = false;
            d.stdName = ""; d.stdGmtoff = 0;
            d.dstName = ""; d.dstGmtoff = 0;
            return;
        }
        int pos = 0;
        // Parse std name
        int[] r = parseName(s, pos);
        d.stdName = s.substring(pos, r[0]); pos = r[0];
        // Parse std offset
        r = parseOffset(s, pos);
        d.stdGmtoff = -r[0]; pos = r[1];
        d.hasDst = false; d.hasRule = false;
        d.dstName = ""; d.dstGmtoff = d.stdGmtoff + 3600;
        if (pos >= s.length()) return;
        // Parse dst name
        r = parseName(s, pos);
        d.dstName = s.substring(pos, r[0]); pos = r[0];
        d.hasDst = true;
        // Parse dst offset (optional, not if next char is ',')
        if (pos < s.length() && s.charAt(pos) != ',') {
            r = parseOffset(s, pos);
            d.dstGmtoff = -r[0]; pos = r[1];
        } else {
            d.dstGmtoff = d.stdGmtoff + 3600;
        }
        // Parse rules
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++; // skip comma
            d.hasRule = true;
            r = parseRule(s, pos);
            d.sm = r[0]; d.sw = r[1]; d.sd = r[2]; d.sh = r[3]; d.smi = r[4]; d.ss = r[5];
            pos = r[6];
            if (pos < s.length() && s.charAt(pos) == ',') pos++;
            r = parseRule(s, pos);
            d.em = r[0]; d.ew = r[1]; d.ed = r[2]; d.eh = r[3]; d.emi = r[4]; d.es = r[5];
        }
    }

    static int[] parseName(String s, int pos) {
        if (s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            return new int[]{end + 1};
        } else {
            int end = pos;
            while (end < s.length() && Character.isLetter(s.charAt(end))) end++;
            return new int[]{end};
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (s.charAt(pos) == '+') { pos++; }
        else if (s.charAt(pos) == '-') { sign = -1; pos++; }
        int h = 0, m = 0, sec = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { h = h * 10 + (s.charAt(pos++) - '0'); }
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { m = m * 10 + (s.charAt(pos++) - '0'); }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { sec = sec * 10 + (s.charAt(pos++) - '0'); }
            }
        }
        return new int[]{sign * (h * 3600 + m * 60 + sec), pos};
    }

    static int[] parseRule(String s, int pos) {
        // Mm.w.d[/time]
        pos++; // skip M
        int m = 0; while (Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int w = 0; while (Character.isDigit(s.charAt(pos))) w = w * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int d = 0; while (Character.isDigit(s.charAt(pos))) d = d * 10 + (s.charAt(pos++) - '0');
        int h = 2, mi = 0, sec = 0;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int sign = 1;
            if (s.charAt(pos) == '+') pos++;
            else if (s.charAt(pos) == '-') { sign = -1; pos++; }
            h = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) h = h * 10 + (s.charAt(pos++) - '0');
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) mi = mi * 10 + (s.charAt(pos++) - '0');
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) sec = sec * 10 + (s.charAt(pos++) - '0');
                }
            }
            h *= sign;
        }
        return new int[]{m, w, d, h, mi, sec, pos};
    }

    static Type getTypeAt(TzifData d, long t) {
        if (d.transTimes.length == 0) {
            return posixType(d, t);
        }
        if (t < d.transTimes[0]) return d.types[0];
        if (t > d.transTimes[d.transTimes.length - 1]) return posixType(d, t);
        // Binary search: latest transition <= t
        int lo = 0, hi = d.transTimes.length - 1, idx = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (d.transTimes[mid] <= t) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return d.types[d.transTypeIdx[idx]];
    }

    static Type posixType(TzifData d, long t) {
        if (!d.hasDst || !d.hasRule) return new Type(d.stdGmtoff, false, d.stdName);
        int year = epochToYear(t);
        // Check year-1, year, year+1 to handle edge cases near year boundaries
        long startUtc = posixTransitionUtc(d, year, true);
        long endUtc = posixTransitionUtc(d, year, false);
        boolean inDst;
        if (startUtc <= endUtc) {
            inDst = t >= startUtc && t < endUtc;
        } else {
            inDst = t >= startUtc || t < endUtc;
        }
        if (inDst) return new Type(d.dstGmtoff, true, d.dstName);
        else return new Type(d.stdGmtoff, false, d.stdName);
    }

    static long posixTransitionUtc(TzifData d, int year, boolean isStart) {
        int m, w, dow, h, mi, sec, gmtoff;
        if (isStart) {
            m = d.sm; w = d.sw; dow = d.sd; h = d.sh; mi = d.smi; sec = d.ss;
            gmtoff = d.stdGmtoff;
        } else {
            m = d.em; w = d.ew; dow = d.ed; h = d.eh; mi = d.emi; sec = d.es;
            gmtoff = d.dstGmtoff;
        }
        int day = computeMDay(year, m, w, dow);
        long localSec = dateTimeToEpoch(year, m, day, h, mi, sec);
        return localSec - gmtoff; // UTC = local - gmtoff
    }

    static String utcQuery(TzifData d, long t) {
        Type type = getTypeAt(d, t);
        long localSec = t + type.gmtoff;
        String dt = epochToDateTimeStr(localSec);
        String off = formatOffset(type.gmtoff);
        return dt + off + " " + type.abbr;
    }

    static String localQuery(TzifData d, String wall) {
        int y = Integer.parseInt(wall.substring(0, 4));
        int mo = Integer.parseInt(wall.substring(5, 7));
        int da = Integer.parseInt(wall.substring(8, 10));
        int h = Integer.parseInt(wall.substring(11, 13));
        int mi = Integer.parseInt(wall.substring(14, 16));
        int se = Integer.parseInt(wall.substring(17, 19));
        long localEpoch = dateTimeToEpoch(y, mo, da, h, mi, se);

        // Collect all candidate (gmtoff, abbr) pairs
        Set<String> seen = new HashSet<>();
        List<long[]> candidates = new ArrayList<>(); // [gmtoff]
        List<String> abbrs = new ArrayList<>();

        // From types in TZif
        for (Type tp : d.types) {
            String key = tp.gmtoff + "|" + tp.abbr;
            if (seen.add(key)) {
                candidates.add(new long[]{tp.gmtoff});
                abbrs.add(tp.abbr);
            }
        }
        // From POSIX std
        if (d.stdName != null && !d.stdName.isEmpty()) {
            String key = d.stdGmtoff + "|" + d.stdName;
            if (seen.add(key)) {
                candidates.add(new long[]{d.stdGmtoff});
                abbrs.add(d.stdName);
            }
        }
        // From POSIX dst
        if (d.hasDst && d.dstName != null && !d.dstName.isEmpty()) {
            String key = d.dstGmtoff + "|" + d.dstName;
            if (seen.add(key)) {
                candidates.add(new long[]{d.dstGmtoff});
                abbrs.add(d.dstName);
            }
        }

        // Enumerate and verify
        List<long[]> results = new ArrayList<>(); // [t, gmtoff, abbrIdx]
        for (int i = 0; i < candidates.size(); i++) {
            int gmtoff = (int)candidates.get(i)[0];
            String abbr = abbrs.get(i);
            long tCand = localEpoch - gmtoff;
            Type actual = getTypeAt(d, tCand);
            if (actual.gmtoff == gmtoff && actual.abbr.equals(abbr)) {
                results.add(new long[]{tCand, gmtoff, i});
            }
        }
        results.sort((a, b) -> Long.compare(a[0], b[0]));

        if (results.size() == 1) {
            long t = results.get(0)[0];
            int gmtoff = (int)results.get(0)[1];
            String abbr = abbrs.get((int)results.get(0)[2]);
            return t + " " + formatOffset(gmtoff) + " " + abbr;
        } else if (results.size() == 2) {
            long t1 = results.get(0)[0]; int g1 = (int)results.get(0)[1]; String a1 = abbrs.get((int)results.get(0)[2]);
            long t2 = results.get(1)[0]; int g2 = (int)results.get(1)[1]; String a2 = abbrs.get((int)results.get(1)[2]);
            return t1 + " " + formatOffset(g1) + " " + a1 + " | " + t2 + " " + formatOffset(g2) + " " + a2;
        } else {
            // Gap: find the transition that skipped this wall-clock time
            long tGap = findGapT(d, localEpoch);
            Type typeAtGap = getTypeAt(d, tGap);
            String dt = epochToDateTimeStr(tGap + typeAtGap.gmtoff);
            String off = formatOffset(typeAtGap.gmtoff);
            return "GAP " + tGap + " " + dt + off + " " + typeAtGap.abbr;
        }
    }

    static long findGapT(TzifData d, long localEpoch) {
        // Check TZif transitions
        for (int i = 0; i < d.transTimes.length; i++) {
            long T = d.transTimes[i];
            Type before;
            if (i == 0) before = d.types[0];
            else before = d.types[d.transTypeIdx[i - 1]];
            Type after = d.types[d.transTypeIdx[i]];
            if (after.gmtoff > before.gmtoff) {
                long gapStart = T + before.gmtoff;
                long gapEnd = T + after.gmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - before.gmtoff;
                }
            }
        }
        // Check POSIX transitions for nearby years
        int year = epochToYear(localEpoch);
        for (int yr = year - 1; yr <= year + 1; yr++) {
            if (!d.hasDst || !d.hasRule) continue;
            long startUtc = posixTransitionUtc(d, yr, true);
            long endUtc = posixTransitionUtc(d, yr, false);
            // Spring forward: STD -> DST at startUtc (gap if dstGmtoff > stdGmtoff)
            if (d.dstGmtoff > d.stdGmtoff) {
                long gapStart = startUtc + d.stdGmtoff;
                long gapEnd = startUtc + d.dstGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.stdGmtoff;
                }
            }
            // End transition: DST -> STD (gap if stdGmtoff > dstGmtoff, unusual)
            if (d.stdGmtoff > d.dstGmtoff) {
                long gapStart = endUtc + d.dstGmtoff;
                long gapEnd = endUtc + d.stdGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.dstGmtoff;
                }
            }
        }
        // Fallback
        return localEpoch;
    }

    // --- Date/Time utilities ---

    static long dateTimeToEpoch(int y, int m, int d, int h, int mi, int s) {
        long days = daysFromCivil(y, m, d);
        return days * 86400L + h * 3600L + mi * 60L + s;
    }

    static String epochToDateTimeStr(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        long rem = Math.floorMod(epochSec, 86400);
        int[] ymd = civilFromDays(days);
        int h = (int)(rem / 3600); rem %= 3600;
        int mi = (int)(rem / 60);
        int se = (int)(rem % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", ymd[0], ymd[1], ymd[2], h, mi, se);
    }

    static int epochToYear(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        return civilFromDays(days)[0];
    }

    static long daysFromCivil(long y, long m, long d) {
        y -= m <= 2 ? 1 : 0;
        long era = (y >= 0 ? y : y - 399) / 400;
        long yoe = y - era * 400;
        long mp = m + (m > 2 ? -3 : 9);
        long doy = (153 * mp + 2) / 5 + d - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe - 719468;
    }

    static int[] civilFromDays(long z) {
        z += 719468;
        long era = (z >= 0 ? z : z - 146096) / 146097;
        long doe = z - era * 146097;
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        long mp = (5 * doy + 2) / 153;
        long d = doy - (153 * mp + 2) / 5 + 1;
        long m = mp < 10 ? mp + 3 : mp - 9;
        y += (m <= 2) ? 1 : 0;
        return new int[]{(int)y, (int)m, (int)d};
    }

    static int dayOfWeek(int y, int m, int d) {
        long days = daysFromCivil(y, m, d);
        return (int)(((days % 7) + 7 + 4) % 7); // 0=Sun
    }

    static int daysInMonth(int y, int m) {
        int[] dm = {0,31,28,31,30,31,30,31,31,30,31,30,31};
        if (m == 2 && isLeap(y)) return 29;
        return dm[m];
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int computeMDay(int year, int month, int week, int dow) {
        int dowFirst = dayOfWeek(year, month, 1);
        int first = 1 + ((dow - dowFirst + 7) % 7);
        if (week == 5) {
            int lastDay = daysInMonth(year, month);
            int dowLast = dayOfWeek(year, month, lastDay);
            return lastDay - ((dowLast - dow + 7) % 7);
        } else {
            return first + (week - 1) * 7;
        }
    }

    static String formatOffset(int gmtoff) {
        int sign = gmtoff >= 0 ? 1 : -1;
        int abs = Math.abs(gmtoff);
        int h = abs / 3600; abs %= 3600;
        int m = abs / 60;
        int s = abs % 60;
        String signStr = sign >= 0 ? "+" : "-";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", signStr, h, m, s);
        } else {
            return String.format("%s%02d:%02d", signStr, h, m);
        }
    }

    // --- Binary reading ---
    static int readInt32(byte[] b, int off) {
        return ((b[off] & 0xFF) << 24) | ((b[off+1] & 0xFF) << 16) |
               ((b[off+2] & 0xFF) << 8) | (b[off+3] & 0xFF);
    }

    static long readInt64(byte[] b, int off) {
        return ((long)readInt32(b, off) << 32) | (readInt32(b, off + 4) & 0xFFFFFFFFL);
    }
}

import Foundation

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
let allEntries = try! fm.contentsOfDirectory(atPath: dir)
let wavFiles = allEntries.filter { $0.hasSuffix(".wav") }
let sortedFiles = wavFiles.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

let lowFreqs: [Double] = [697, 770, 852, 941]
let highFreqs: [Double] = [1209, 1336, 1477, 1633]

let keypad: [[String]] = [
    ["1", "2", "3", "A"],
    ["4", "5", "6", "B"],
    ["7", "8", "9", "C"],
    ["*", "0", "#", "D"]
]

func readU16(_ d: [UInt8], _ off: Int) -> UInt16 {
    return UInt16(d[off]) | (UInt16(d[off + 1]) << 8)
}

func readU32(_ d: [UInt8], _ off: Int) -> UInt32 {
    return UInt32(d[off]) | (UInt32(d[off + 1]) << 8) | (UInt32(d[off + 2]) << 16) | (UInt32(d[off + 3]) << 24)
}

var firstOutput = true

for filename in sortedFiles {
    if !firstOutput { print("") }
    firstOutput = false

    let path = dir + "/" + filename
    guard let fileData = fm.contents(atPath: path) else { continue }
    let bytes = [UInt8](fileData)

    guard bytes.count >= 12 else { continue }
    guard bytes[0] == 0x52, bytes[1] == 0x49, bytes[2] == 0x46, bytes[3] == 0x46 else { continue }
    guard bytes[8] == 0x57, bytes[9] == 0x41, bytes[10] == 0x56, bytes[11] == 0x45 else { continue }

    var offset = 12
    var fmtBody: [UInt8]? = nil
    var dataBody: [UInt8]? = nil

    while offset + 8 <= bytes.count {
        let id = String(bytes: bytes[offset..<offset+4], encoding: .ascii) ?? ""
        let chunkSize = Int(readU32(bytes, offset + 4))
        let bodyStart = offset + 8
        let bodyEnd = bodyStart + chunkSize

        if id == "fmt " {
            fmtBody = Array(bytes[bodyStart..<min(bodyEnd, bytes.count)])
        } else if id == "data" {
            dataBody = Array(bytes[bodyStart..<min(bodyEnd, bytes.count)])
        }

        var next = bodyEnd
        if chunkSize & 1 == 1 { next += 1 }
        offset = next
    }

    guard let fmt = fmtBody, let dataChunk = dataBody else { continue }
    guard fmt.count >= 16 else { continue }

    var formatTag = Int(readU16(fmt, 0))
    let channels = Int(readU16(fmt, 2))
    let sampleRate = Int(readU32(fmt, 4))
    let bitsPerSample = Int(readU16(fmt, 14))

    if formatTag == 0xFFFE {
        guard fmt.count > 24 else { continue }
        formatTag = Int(readU16(fmt, 24))
    }

    if formatTag != 1 || bitsPerSample != 16 {
        print("\(filename): unsupported")
        continue
    }
    if (channels != 1 && channels != 2) || (sampleRate != 8000 && sampleRate != 16000) {
        print("\(filename): unsupported")
        continue
    }

    let framesCount = dataChunk.count / (2 * channels)
    var samples = [Double](repeating: 0, count: framesCount)
    for i in 0..<framesCount {
        let byteOff = i * 2 * channels
        samples[i] = Double(Int16(bitPattern: readU16(dataChunk, byteOff)))
    }

    let N = sampleRate / 50
    let numBlocks = framesCount / N

    // Step 3: detect digit per block
    var labels: [String?] = []
    labels.reserveCapacity(numBlocks)

    for b in 0..<numBlocks {
        let base = b * N
        var E: Double = 0
        for n in 0..<N { let x = samples[base + n]; E += x * x }

        if E < 1_000_000.0 * Double(N) {
            labels.append(nil)
            continue
        }

        var maxLowR: Double = -1
        var maxLowIdx: Int = 0
        for fi in 0..<4 {
            let c = 2.0 * cos(2.0 * Double.pi * lowFreqs[fi] / Double(sampleRate))
            var s1: Double = 0, s2: Double = 0
            for n in 0..<N {
                let s = samples[base + n] + c * s1 - s2
                s2 = s1; s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            let r = 2.0 * P / (Double(N) * E)
            if r > maxLowR { maxLowR = r; maxLowIdx = fi }
        }

        var maxHighR: Double = -1
        var maxHighIdx: Int = 0
        for fi in 0..<4 {
            let c = 2.0 * cos(2.0 * Double.pi * highFreqs[fi] / Double(sampleRate))
            var s1: Double = 0, s2: Double = 0
            for n in 0..<N {
                let s = samples[base + n] + c * s1 - s2
                s2 = s1; s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            let r = 2.0 * P / (Double(N) * E)
            if r > maxHighR { maxHighR = r; maxHighIdx = fi }
        }

        if maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6 {
            labels.append(keypad[maxLowIdx][maxHighIdx])
        } else {
            labels.append(nil)
        }
    }

    // Step 4: bridging (use original step-3 labels for decisions)
    var bridged = labels
    for i in 0..<numBlocks {
        if labels[i] == nil && i > 0 && i < numBlocks - 1 {
            if let d = labels[i - 1], d == labels[i + 1] {
                bridged[i] = d
            }
        }
    }

    // Step 5: events (runs >= 2)
    var events: [(digit: String, start: Int, end: Int)] = []
    var i = 0
    while i < numBlocks {
        if let digit = bridged[i] {
            var j = i + 1
            while j < numBlocks && bridged[j] == digit { j += 1 }
            if j - i >= 2 {
                events.append((digit: digit, start: 20 * i, end: 20 * j))
            }
            i = j
        } else {
            i += 1
        }
    }

    // Output
    print("\(filename): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks")
    for ev in events {
        print("\(ev.digit) \(ev.start) \(ev.end)")
    }
    let allDigits = events.map { $0.digit }.joined()
    print("digits: \(allDigits)")
}

exit(0)

import * as fs from 'fs';
import * as path from 'path';

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];
const KEYPAD = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

function goertzel(x: number[], N: number, f: number, rate: number, E: number): number {
  const c = 2 * Math.cos(2 * Math.PI * f / rate);
  let s1 = 0, s2 = 0;
  for (let n = 0; n < N; n++) {
    const s = x[n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  const P = s1 * s1 + s2 * s2 - c * s1 * s2;
  return 2 * P / (N * E);
}

function processFile(name: string, buf: Buffer): string {
  if (buf.length < 12) return `${name}: unsupported`;
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return `${name}: unsupported`;
  if (buf.toString('ascii', 8, 12) !== 'WAVE') return `${name}: unsupported`;

  let fmtBody: Buffer | null = null;
  let dataBody: Buffer | null = null;
  let offset = 12;

  while (offset + 8 <= buf.length) {
    const chunkId = buf.toString('ascii', offset, offset + 4);
    const chunkSize = buf.readUInt32LE(offset + 4);
    const bodyStart = offset + 8;
    const bodyEnd = bodyStart + chunkSize;

    if (bodyEnd > buf.length) break;

    if (chunkId === 'fmt ') {
      fmtBody = buf.subarray(bodyStart, bodyEnd);
    } else if (chunkId === 'data') {
      dataBody = buf.subarray(bodyStart, bodyEnd);
    }

    offset = bodyEnd + (chunkSize % 2 === 1 ? 1 : 0);
  }

  if (!fmtBody || !dataBody) return `${name}: unsupported`;
  if (fmtBody.length < 16) return `${name}: unsupported`;

  let formatTag = fmtBody.readUInt16LE(0);
  const channels = fmtBody.readUInt16LE(2);
  const sampleRate = fmtBody.readUInt32LE(4);
  const bitsPerSample = fmtBody.readUInt16LE(14);

  if (formatTag === 0xFFFE) {
    if (fmtBody.length < 26) return `${name}: unsupported`;
    formatTag = fmtBody.readUInt16LE(24);
  }

  if (formatTag !== 1 || bitsPerSample !== 16) return `${name}: unsupported`;
  if (channels !== 1 && channels !== 2) return `${name}: unsupported`;
  if (sampleRate !== 8000 && sampleRate !== 16000) return `${name}: unsupported`;

  const bytesPerFrame = 2 * channels;
  const numFrames = Math.floor(dataBody.length / bytesPerFrame);
  const samples: number[] = new Array(numFrames);
  for (let i = 0; i < numFrames; i++) {
    samples[i] = dataBody.readInt16LE(i * bytesPerFrame);
  }

  const N = sampleRate / 50;
  const numBlocks = Math.floor(samples.length / N);

  const labels: (string | null)[] = new Array(numBlocks);

  for (let b = 0; b < numBlocks; b++) {
    const blockStart = b * N;
    const x: number[] = new Array(N);
    for (let n = 0; n < N; n++) {
      x[n] = samples[blockStart + n];
    }

    let E = 0;
    for (let n = 0; n < N; n++) {
      E += x[n] * x[n];
    }

    if (E < 1000000 * N) {
      labels[b] = null;
      continue;
    }

    const rLow: number[] = new Array(4);
    const rHigh: number[] = new Array(4);

    for (let i = 0; i < 4; i++) {
      rLow[i] = goertzel(x, N, LOW_FREQS[i], sampleRate, E);
    }
    for (let i = 0; i < 4; i++) {
      rHigh[i] = goertzel(x, N, HIGH_FREQS[i], sampleRate, E);
    }

    let maxLowIdx = 0, maxHighIdx = 0;
    for (let i = 1; i < 4; i++) {
      if (rLow[i] > rLow[maxLowIdx]) maxLowIdx = i;
      if (rHigh[i] > rHigh[maxHighIdx]) maxHighIdx = i;
    }

    const rFl = rLow[maxLowIdx];
    const rFh = rHigh[maxHighIdx];

    if (rFl >= 0.1 && rFh >= 0.1 && rFl + rFh >= 0.6) {
      labels[b] = KEYPAD[maxLowIdx][maxHighIdx];
    } else {
      labels[b] = null;
    }
  }

  // Bridging
  const bridged: (string | null)[] = labels.slice();
  for (let i = 1; i < numBlocks - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }

  // Events
  const events: { digit: string; start: number; end: number }[] = [];
  let i = 0;
  while (i < numBlocks) {
    if (bridged[i] === null) {
      i++;
      continue;
    }
    const digit = bridged[i]!;
    const start = i;
    while (i < numBlocks && bridged[i] === digit) {
      i++;
    }
    const end = i - 1;
    if (end - start + 1 >= 2) {
      events.push({ digit, start: 20 * start, end: 20 * (end + 1) });
    }
  }

  const lines: string[] = [];
  lines.push(`${name}: ${sampleRate} Hz, ${channels} ch, ${numBlocks} blocks`);
  for (const ev of events) {
    lines.push(`${ev.digit} ${ev.start} ${ev.end}`);
  }
  lines.push(`digits: ${events.map(e => e.digit).join('')}`);

  return lines.join('\n');
}

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.wav')).sort((a, b) => {
    return Buffer.compare(Buffer.from(a, 'utf-8'), Buffer.from(b, 'utf-8'));
  });

  const outputs: string[] = [];

  for (const file of files) {
    const filePath = path.join(dir, file);
    const buf = fs.readFileSync(filePath);
    outputs.push(processFile(file, buf));
  }

  process.stdout.write(outputs.join('\n\n') + '\n');
}

main();

use std::env;
use std::fs;
use std::path::Path;

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([data[offset], data[offset + 1]])
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn goertzel(block: &[i16], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = (x as f64) + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn process_file(name: &str, data: &[u8]) {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" {
        println!("{}: unsupported", name);
        return;
    }

    let mut pos = 12usize;
    let mut fmt_body: Option<Vec<u8>> = None;
    let mut data_body: Option<Vec<u8>> = None;

    while pos + 8 <= data.len() {
        let chunk_id = &data[pos..pos + 4];
        let chunk_size = read_u32_le(data, pos + 4) as usize;
        let body_start = pos + 8;
        let actual_size = std::cmp::min(chunk_size, data.len().saturating_sub(body_start));

        if chunk_id == b"fmt " {
            fmt_body = Some(data[body_start..body_start + actual_size].to_vec());
        } else if chunk_id == b"data" {
            data_body = Some(data[body_start..body_start + actual_size].to_vec());
        }

        pos = body_start + chunk_size;
        if chunk_size % 2 == 1 {
            pos += 1;
        }
    }

    let fmt = match fmt_body {
        Some(f) => f,
        None => { println!("{}: unsupported", name); return; }
    };
    let samples_data = match data_body {
        Some(d) => d,
        None => { println!("{}: unsupported", name); return; }
    };

    if fmt.len() < 16 {
        println!("{}: unsupported", name);
        return;
    }

    let mut format_tag = read_u16_le(&fmt, 0) as u32;
    let channels = read_u16_le(&fmt, 2) as usize;
    let rate = read_u32_le(&fmt, 4) as usize;
    let bits_per_sample = read_u16_le(&fmt, 14);

    if format_tag == 0xFFFE {
        if fmt.len() < 26 {
            println!("{}: unsupported", name);
            return;
        }
        format_tag = read_u16_le(&fmt, 24) as u32;
    }

    if format_tag != 1 || bits_per_sample != 16 {
        println!("{}: unsupported", name);
        return;
    }
    if channels != 1 && channels != 2 {
        println!("{}: unsupported", name);
        return;
    }
    if rate != 8000 && rate != 16000 {
        println!("{}: unsupported", name);
        return;
    }

    let frame_bytes = 2 * channels;
    let num_frames = samples_data.len() / frame_bytes;

    let mut left_samples: Vec<i16> = Vec::with_capacity(num_frames);
    for i in 0..num_frames {
        let off = i * frame_bytes;
        let sample = i16::from_le_bytes([samples_data[off], samples_data[off + 1]]);
        left_samples.push(sample);
    }

    let n = rate / 50;
    let num_blocks = if n > 0 { left_samples.len() / n } else { 0 };

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];

    let keypad: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut labels: Vec<Option<char>> = vec![None; num_blocks];

    for block_idx in 0..num_blocks {
        let start = block_idx * n;
        let block = &left_samples[start..start + n];

        let e: f64 = block.iter().map(|&x| (x as f64) * (x as f64)).sum();

        if e < 1000000.0 * n as f64 {
            continue;
        }

        let mut r_low: [f64; 4] = [0.0; 4];
        let mut r_high: [f64; 4] = [0.0; 4];

        for fi in 0..4 {
            r_low[fi] = goertzel(block, low_freqs[fi], rate as f64, n, e);
            r_high[fi] = goertzel(block, high_freqs[fi], rate as f64, n, e);
        }

        let mut max_low_idx = 0usize;
        let mut max_high_idx = 0usize;
        for i in 1..4 {
            if r_low[i] > r_low[max_low_idx] { max_low_idx = i; }
            if r_high[i] > r_high[max_high_idx] { max_high_idx = i; }
        }

        let r_fl = r_low[max_low_idx];
        let r_fh = r_high[max_high_idx];

        if r_fl >= 0.1 && r_fh >= 0.1 && r_fl + r_fh >= 0.6 {
            labels[block_idx] = Some(keypad[max_low_idx][max_high_idx]);
        }
    }

    // Bridging: use original step-3 labels for neighbor checks
    let original_labels = labels.clone();
    if num_blocks >= 3 {
        for i in 1..num_blocks - 1 {
            if labels[i].is_none() {
                if let Some(prev) = original_labels[i - 1] {
                    if let Some(next) = original_labels[i + 1] {
                        if prev == next {
                            labels[i] = Some(prev);
                        }
                    }
                }
            }
        }
    }

    // Events: maximal runs of same digit >= 2 blocks
    let mut events: Vec<(char, usize, usize)> = Vec::new();
    let mut i = 0usize;
    while i < num_blocks {
        if let Some(d) = labels[i] {
            let start_block = i;
            while i < num_blocks && labels[i] == Some(d) {
                i += 1;
            }
            let end_block = i - 1;
            let run_len = end_block - start_block + 1;
            if run_len >= 2 {
                let start_ms = 20 * start_block;
                let end_ms = 20 * (end_block + 1);
                events.push((d, start_ms, end_ms));
            }
        } else {
            i += 1;
        }
    }

    // Output
    println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, num_blocks);
    for (d, start_ms, end_ms) in &events {
        println!("{} {} {}", d, start_ms, end_ms);
    }
    let digits: String = events.iter().map(|(d, _, _)| *d).collect();
    println!("digits: {}", digits);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut entries: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".wav") {
            entries.push(name);
        }
    }
    entries.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));

    let mut first = true;
    for name in &entries {
        if !first {
            println!();
        }
        first = false;

        let path = Path::new(dir).join(name);
        let file_data = fs::read(&path).unwrap();

        process_file(name, &file_data);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <dirent.h>
#include <stdint.h>

static uint16_t read_u16(const unsigned char *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32(const unsigned char *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | (p[3] << 24));
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

static const double low_freqs[4] = {697.0, 770.0, 852.0, 941.0};
static const double high_freqs[4] = {1209.0, 1336.0, 1477.0, 1633.0};
static const char digit_table[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

int main(int argc, char *argv[]) {
    if (argc != 2) return 1;

    DIR *dir = opendir(argv[1]);
    if (!dir) return 1;

    char **files = NULL;
    int nfiles = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            files = realloc(files, (nfiles + 1) * sizeof(char *));
            files[nfiles++] = strdup(name);
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(char *), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        char path[8192];
        snprintf(path, sizeof(path), "%s/%s", argv[1], files[fi]);

        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", files[fi]);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        if (fsize < 12) {
            fclose(fp);
            printf("%s: unsupported\n", files[fi]);
            continue;
        }

        unsigned char *buf = malloc(fsize);
        if (!buf || (long)fread(buf, 1, fsize, fp) != fsize) {
            fclose(fp);
            free(buf);
            printf("%s: unsupported\n", files[fi]);
            continue;
        }
        fclose(fp);

        if (memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        unsigned char *fmt_body = NULL;
        uint32_t fmt_size = 0;
        unsigned char *data_body = NULL;
        uint32_t data_size = 0;

        long pos = 12;
        while (pos + 8 <= fsize) {
            uint32_t csize = read_u32(buf + pos + 4);
            long body_start = pos + 8;
            if (body_start + (long)csize > fsize) break;

            if (memcmp(buf + pos, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = csize;
            } else if (memcmp(buf + pos, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = csize;
            }

            pos = body_start + csize;
            if (csize & 1) pos++;
        }

        if (!fmt_body || !data_body) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        if (fmt_size < 16) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        uint16_t fmt_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t sample_rate = read_u32(fmt_body + 4);
        uint16_t bits = read_u16(fmt_body + 14);

        uint16_t effective = fmt_tag;
        if (fmt_tag == 0xFFFE) {
            if (fmt_size < 26) {
                printf("%s: unsupported\n", files[fi]);
                free(buf);
                continue;
            }
            effective = read_u16(fmt_body + 24);
        }

        if (effective != 1 || bits != 16 ||
            (channels != 1 && channels != 2) ||
            (sample_rate != 8000 && sample_rate != 16000)) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        uint32_t frames = data_size / (2 * channels);
        int N = (int)(sample_rate / 50);
        int nblocks = (N > 0) ? (int)(frames / N) : 0;

        double *x = malloc(frames * sizeof(double));
        for (uint32_t i = 0; i < frames; i++) {
            int16_t val = (int16_t)read_u16(data_body + i * 2 * channels);
            x[i] = (double)val;
        }

        int *labels = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));

        for (int b = 0; b < nblocks; b++) {
            double *blk = x + (size_t)b * N;

            double E = 0.0;
            for (int n = 0; n < N; n++) {
                E += blk[n] * blk[n];
            }

            if (E < 1000000.0 * N) {
                labels[b] = -1;
                continue;
            }

            double r_low[4], r_high[4];

            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * M_PI * low_freqs[i] / sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = blk[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[i] = 2.0 * P / ((double)N * E);
            }

            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * M_PI * high_freqs[i] / sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = blk[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = best_low * 4 + best_high;
            } else {
                labels[b] = -1;
            }
        }

        /* Bridging: use original labels for decisions */
        int *final_labels = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        memcpy(final_labels, labels, nblocks * sizeof(int));

        for (int b = 1; b < nblocks - 1; b++) {
            if (labels[b] == -1 && labels[b - 1] != -1 && labels[b - 1] == labels[b + 1]) {
                final_labels[b] = labels[b - 1];
            }
        }

        /* Events: maximal runs of same digit, length >= 2 */
        char *ev_digits = malloc((nblocks > 0 ? nblocks : 1) * sizeof(char));
        int *ev_start = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        int *ev_end = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        int nev = 0;

        int i = 0;
        while (i < nblocks) {
            if (final_labels[i] == -1) { i++; continue; }
            int j = i + 1;
            while (j < nblocks && final_labels[j] == final_labels[i]) j++;
            if (j - i >= 2) {
                int d = final_labels[i];
                ev_digits[nev] = digit_table[d / 4][d % 4];
                ev_start[nev] = 20 * i;
                ev_end[nev] = 20 * j;
                nev++;
            }
            i = j;
        }

        printf("%s: %u Hz, %u ch, %d blocks\n", files[fi], sample_rate, channels, nblocks);
        for (int e = 0; e < nev; e++) {
            printf("%c %d %d\n", ev_digits[e], ev_start[e], ev_end[e]);
        }
        printf("digits: ");
        for (int e = 0; e < nev; e++) {
            printf("%c", ev_digits[e]);
        }
        printf("\n");

        free(x);
        free(labels);
        free(final_labels);
        free(ev_digits);
        free(ev_start);
        free(ev_end);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);

    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        SecureRandom random = new SecureRandom();
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            handleSession(args[i], random);
        }
    }

    static void handleSession(String url, SecureRandom random) throws Exception {
        String rest = url.substring(5); // remove "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx >= 0) {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        } else {
            hostPort = rest;
            path = "/";
        }
        int colonIdx = hostPort.lastIndexOf(':');
        String host;
        int port;
        if (colonIdx >= 0) {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        } else {
            host = hostPort;
            port = 80;
        }

        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 10000);
        socket.setSoTimeout(30000);
        InputStream in = new BufferedInputStream(socket.getInputStream(), 65536);
        OutputStream out = new BufferedOutputStream(socket.getOutputStream());

        byte[] keyBytes = new byte[16];
        random.nextBytes(keyBytes);
        String key = Base64.getEncoder().encodeToString(keyBytes);

        String handshake = "GET " + path + " HTTP/1.1\r\n"
                + "Host: " + host + ":" + port + "\r\n"
                + "Upgrade: websocket\r\n"
                + "Connection: Upgrade\r\n"
                + "Sec-WebSocket-Version: 13\r\n"
                + "Sec-WebSocket-Key: " + key + "\r\n"
                + "\r\n";
        out.write(handshake.getBytes(StandardCharsets.US_ASCII));
        out.flush();

        // Read HTTP response
        String statusLine = readHttpLine(in);
        if (statusLine == null) {
            socket.close();
            return;
        }
        int firstSpace = statusLine.indexOf(' ');
        int secondSpace = statusLine.indexOf(' ', firstSpace + 1);
        int statusCode;
        String reason;
        if (secondSpace == -1) {
            statusCode = Integer.parseInt(statusLine.substring(firstSpace + 1).trim());
            reason = "";
        } else {
            statusCode = Integer.parseInt(statusLine.substring(firstSpace + 1, secondSpace).trim());
            reason = statusLine.substring(secondSpace + 1);
        }

        if (statusCode != 101) {
            // consume remaining headers
            String hl;
            while ((hl = readHttpLine(in)) != null && !hl.isEmpty()) {}
            System.out.println("handshake failed: " + statusCode + " " + reason);
            socket.close();
            return;
        }

        String acceptValue = null;
        String hl;
        while ((hl = readHttpLine(in)) != null && !hl.isEmpty()) {
            int cp = hl.indexOf(':');
            if (cp >= 0) {
                String name = hl.substring(0, cp).trim();
                String value = hl.substring(cp + 1).trim();
                if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                    acceptValue = value;
                }
            }
        }

        String expectedAccept = computeAccept(key);
        if (acceptValue == null || !acceptValue.equals(expectedAccept)) {
            System.out.println("handshake failed: bad Sec-WebSocket-Accept");
            socket.close();
            return;
        }

        // WebSocket frame loop
        boolean inMessage = false;
        int messageType = -1;
        ByteArrayOutputStream msgBuf = null;
        boolean pendingSha1 = false;
        boolean closeSent = false;
        boolean byeReceived = false;

        while (true) {
            Frame f = readFrame(in);
            if (f == null) break;

            if (f.opcode == 9) { // ping
                sendFrame(out, 10, f.payload, random);
                out.flush();
                continue;
            }
            if (f.opcode == 10) { // pong
                continue;
            }
            if (f.opcode == 8) { // close
                int code = 1005;
                String closeReason = "";
                if (f.payload.length >= 2) {
                    code = ((f.payload[0] & 0xFF) << 8) | (f.payload[1] & 0xFF);
                }
                if (f.payload.length > 2) {
                    closeReason = new String(f.payload, 2, f.payload.length - 2, StandardCharsets.UTF_8);
                }
                if (closeReason.isEmpty()) {
                    System.out.println("closed " + code);
                } else {
                    System.out.println("closed " + code + " " + closeReason);
                }
                if (!closeSent) {
                    byte[] cp = new byte[]{(byte) (code >> 8), (byte) (code & 0xFF)};
                    sendFrame(out, 8, cp, random);
                    out.flush();
                    closeSent = true;
                }
                break;
            }

            if (byeReceived) continue;

            if (f.opcode == 1 || f.opcode == 2) {
                if (f.fin) {
                    handleData(f.opcode, f.payload, out, random, pendingSha1, new boolean[]{false});
                    if (f.opcode == 1) {
                        String text = new String(f.payload, StandardCharsets.UTF_8);
                        if (text.equals("SHA1")) {
                            pendingSha1 = true;
                        } else if (text.equals("BYE")) {
                            byeReceived = true;
                            byte[] cp = new byte[]{0x03, (byte) 0xE8};
                            sendFrame(out, 8, cp, random);
                            out.flush();
                            closeSent = true;
                        } else if (text.startsWith("ADD ")) {
                            String params = text.substring(4).trim();
                            String[] parts = params.split("\\s+");
                            long a = Long.parseLong(parts[0]);
                            long b = Long.parseLong(parts[1]);
                            long sum = a + b;
                            String reply = Long.toString(sum);
                            sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println(text + " -> " + reply);
                        } else if (text.startsWith("REV ")) {
                            String toReverse = text.substring(4);
                            String reversed = reverseByCodePoint(toReverse);
                            sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println(text + " -> " + reversed);
                        }
                    } else if (f.opcode == 2 && pendingSha1) {
                        pendingSha1 = false;
                        MessageDigest md = MessageDigest.getInstance("SHA-1");
                        byte[] hash = md.digest(f.payload);
                        String hex = bytesToHex(hash);
                        sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8), random);
                        out.flush();
                        System.out.println("SHA1 " + f.payload.length + " -> " + hex);
                    }
                } else {
                    inMessage = true;
                    messageType = f.opcode;
                    msgBuf = new ByteArrayOutputStream();
                    msgBuf.write(f.payload);
                }
            } else if (f.opcode == 0) { // continuation
                if (inMessage) {
                    msgBuf.write(f.payload);
                    if (f.fin) {
                        byte[] fullPayload = msgBuf.toByteArray();
                        inMessage = false;
                        if (messageType == 1) {
                            String text = new String(fullPayload, StandardCharsets.UTF_8);
                            if (text.equals("SHA1")) {
                                pendingSha1 = true;
                            } else if (text.equals("BYE")) {
                                byeReceived = true;
                                byte[] cp = new byte[]{0x03, (byte) 0xE8};
                                sendFrame(out, 8, cp, random);
                                out.flush();
                                closeSent = true;
                            } else if (text.startsWith("ADD ")) {
                                String params = text.substring(4).trim();
                                String[] parts = params.split("\\s+");
                                long a = Long.parseLong(parts[0]);
                                long b = Long.parseLong(parts[1]);
                                long sum = a + b;
                                String reply = Long.toString(sum);
                                sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8), random);
                                out.flush();
                                System.out.println(text + " -> " + reply);
                            } else if (text.startsWith("REV ")) {
                                String toReverse = text.substring(4);
                                String reversed = reverseByCodePoint(toReverse);
                                sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8), random);
                                out.flush();
                                System.out.println(text + " -> " + reversed);
                            }
                        } else if (messageType == 2 && pendingSha1) {
                            pendingSha1 = false;
                            MessageDigest md = MessageDigest.getInstance("SHA-1");
                            byte[] hash = md.digest(fullPayload);
                            String hex = bytesToHex(hash);
                            sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println("SHA1 " + fullPayload.length + " -> " + hex);
                        }
                    }
                }
            }
        }
        socket.close();
    }

    static void handleData(int opcode, byte[] payload, OutputStream out, SecureRandom random, boolean pendingSha1, boolean[] dummy) {
        // placeholder - logic is inline in the loop
    }

    static String reverseByCodePoint(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--) {
            sb.appendCodePoint(cps[i]);
        }
        return sb.toString();
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static String computeAccept(String key) throws Exception {
        String magic = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] hash = md.digest(magic.getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(hash);
    }

    static String readHttpLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int b;
        while ((b = in.read()) != -1) {
            if (b == '\n') {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '\r') {
                    sb.setLength(sb.length() - 1);
                }
                break;
            }
            sb.append((char) b);
        }
        if (b == -1 && sb.length() == 0) return null;
        return sb.toString();
    }

    static Frame readFrame(InputStream in) throws IOException {
        int b0 = in.read();
        if (b0 == -1) return null;
        boolean fin = (b0 & 0x80) != 0;
        int opcode = b0 & 0x0F;

        int b1 = in.read();
        if (b1 == -1) return null;
        boolean masked = (b1 & 0x80) != 0;
        long payloadLen = b1 & 0x7F;

        if (payloadLen == 126) {
            int hi = in.read();
            int lo = in.read();
            if (hi == -1 || lo == -1) return null;
            payloadLen = ((hi & 0xFF) << 8) | (lo & 0xFF);
        } else if (payloadLen == 127) {
            payloadLen = 0;
            for (int i = 0; i < 8; i++) {
                int bb = in.read();
                if (bb == -1) return null;
                payloadLen = (payloadLen << 8) | (bb & 0xFFL);
            }
        }

        byte[] maskKey = null;
        if (masked) {
            maskKey = new byte[4];
            readFully(in, maskKey);
        }

        byte[] payload = new byte[(int) payloadLen];
        if (payloadLen > 0) {
            readFully(in, payload);
        }

        if (masked && maskKey != null) {
            for (int i = 0; i < payload.length; i++) {
                payload[i] ^= maskKey[i % 4];
            }
        }

        return new Frame(fin, opcode, payload);
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int n = in.read(buf, off, buf.length - off);
            if (n == -1) throw new EOFException();
            off += n;
        }
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload, SecureRandom random) throws IOException {
        ByteArrayOutputStream frame = new ByteArrayOutputStream();
        frame.write(0x80 | opcode); // FIN + opcode, RSV clear

        int len = payload.length;
        if (len <= 125) {
            frame.write(0x80 | len);
        } else if (len <= 65535) {
            frame.write(0x80 | 126);
            frame.write((len >> 8) & 0xFF);
            frame.write(len & 0xFF);
        } else {
            frame.write(0x80 | 127);
            long flen = len;
            for (int i = 7; i >= 0; i--) {
                frame.write((int) ((flen >> (i * 8)) & 0xFF));
            }
        }

        byte[] maskKey = new byte[4];
        do {
            random.nextBytes(maskKey);
        } while (maskKey[0] == 0 && maskKey[1] == 0 && maskKey[2] == 0 && maskKey[3] == 0);
        frame.write(maskKey);

        for (int i = 0; i < payload.length; i++) {
            frame.write(payload[i] ^ maskKey[i % 4]);
        }

        out.write(frame.toByteArray());
    }

    static class Frame {
        final boolean fin;
        final int opcode;
        final byte[] payload;

        Frame(boolean fin, int opcode, byte[] payload) {
            this.fin = fin;
            this.opcode = opcode;
            this.payload = payload;
        }
    }
}

#!/usr/bin/env python3
import struct
import os
import sys
from datetime import date, timedelta


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    # First header (44 bytes)
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = struct.unpack('>6i', data[20:44])

    block1_size = (timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 +
                   leapcnt1 * 8 + isstdcnt1 + isutcnt1)

    # Second header
    off = 44 + block1_size
    isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = struct.unpack('>6i', data[off+20:off+44])
    off += 44

    # Transition times (64-bit)
    trans_times = list(struct.unpack(f'>{timecnt}q', data[off:off+timecnt*8])) if timecnt else []
    off += timecnt * 8

    # Type indices
    trans_types = list(data[off:off+timecnt]) if timecnt else []
    off += timecnt

    # Type records
    types = []
    for i in range(typecnt):
        gmtoff = struct.unpack('>i', data[off:off+4])[0]
        isdst = data[off+4]
        abbrind = data[off+5]
        types.append((gmtoff, isdst, abbrind))
        off += 6

    # Abbreviation characters
    abbr_chars = data[off:off+charcnt]
    off += charcnt

    # Skip leap seconds, isstdcnt, isutcnt
    off += leapcnt * 12 + isstdcnt + isutcnt

    # Footer: \n + posix_string + \n
    if off < len(data) and data[off] == 0x0a:
        off += 1
    try:
        end = data.index(0x0a, off)
    except ValueError:
        end = len(data)
    posix_str = data[off:end].decode('ascii')

    return trans_times, trans_types, types, abbr_chars, posix_str


def parse_abbr(abbr_chars, abbrind):
    end = abbr_chars.index(0, abbrind)
    return abbr_chars[abbrind:end].decode('ascii')


def parse_posix_tz(posix_str):
    if not posix_str:
        return None
    pos = 0
    std_name, pos = _parse_name(posix_str, pos)
    std_gmtoff, pos = _parse_offset(posix_str, pos)

    if pos >= len(posix_str):
        return (std_name, std_gmtoff, None, None, None, None)

    dst_name, pos = _parse_name(posix_str, pos)

    dst_gmtoff = None
    if pos < len(posix_str) and posix_str[pos] in '+-':
        dst_gmtoff, pos = _parse_offset(posix_str, pos)

    if dst_gmtoff is None:
        dst_gmtoff = std_gmtoff + 3600

    start_rule = None
    end_rule = None
    if pos < len(posix_str) and posix_str[pos] == ',':
        pos += 1
        start_rule, pos = _parse_rule(posix_str, pos)
        if pos < len(posix_str) and posix_str[pos] == ',':
            pos += 1
            end_rule, pos = _parse_rule(posix_str, pos)

    return (std_name, std_gmtoff, dst_name, dst_gmtoff, start_rule, end_rule)


def _parse_name(s, pos):
    if pos < len(s) and s[pos] == '<':
        end = s.index('>', pos)
        return s[pos+1:end], end + 1
    start = pos
    while pos < len(s) and s[pos].isalpha():
        pos += 1
    return s[start:pos], pos


def _parse_offset(s, pos):
    sign = 1
    if s[pos] == '-':
        sign = -1
        pos += 1
    elif s[pos] == '+':
        pos += 1
    h_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    hours = int(s[h_start:pos])
    minutes = 0
    seconds = 0
    if pos < len(s) and s[pos] == ':':
        pos += 1
        m_start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        minutes = int(s[m_start:pos])
        if pos < len(s) and s[pos] == ':':
            pos += 1
            sec_start = pos
            while pos < len(s) and s[pos].isdigit():
                pos += 1
            seconds = int(s[sec_start:pos])
    total = sign * (hours * 3600 + minutes * 60 + seconds)
    return -total, pos


def _parse_rule(s, pos):
    assert s[pos] == 'M'
    pos += 1
    m_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    month = int(s[m_start:pos])
    assert s[pos] == '.'
    pos += 1
    w_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    week = int(s[w_start:pos])
    assert s[pos] == '.'
    pos += 1
    d_start = pos
    while pos < len(s) and s[pos].isdigit():
        pos += 1
    day = int(s[d_start:pos])
    time_sec = 7200
    if pos < len(s) and s[pos] == '/':
        pos += 1
        sign = 1
        if pos < len(s) and s[pos] == '-':
            sign = -1
            pos += 1
        elif pos < len(s) and s[pos] == '+':
            pos += 1
        h_start = pos
        while pos < len(s) and s[pos].isdigit():
            pos += 1
        hours = int(s[h_start:pos])
        minutes = 0
        seconds = 0
        if pos < len(s) and s[pos] == ':':
            pos += 1
            m_start = pos
            while pos < len(s) and s[pos].isdigit():
                pos += 1
            minutes = int(s[m_start:pos])
            if pos < len(s) and s[pos] == ':':
                pos += 1
                sec_start = pos
                while pos < len(s) and s[pos].isdigit():
                    pos += 1
                seconds = int(s[sec_start:pos])
        time_sec = sign * (hours * 3600 + minutes * 60 + seconds)
    return (month, week, day, time_sec), pos


def _weekday(year, month, day):
    """0=Sunday, 1=Monday, ..., 6=Saturday"""
    d = date(year, month, day)
    return (d.weekday() + 1) % 7


def _days_in_month(year, month):
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - date(year, month, 1)).days


def find_mwd(year, month, week, day):
    first = None
    for d in range(1, 8):
        if _weekday(year, month, d) == day:
            first = d
            break
    if week <= 4:
        return first + (week - 1) * 7
    else:
        last_day = _days_in_month(year, month)
        wd = _weekday(year, month, last_day)
        return last_day - ((wd - day) % 7)


def _date_to_epoch(y, m, d):
    return (date(y, m, d) - date(1970, 1, 1)).days * 86400


def get_footer_transitions(year, posix_info):
    std_name, std_gmtoff, dst_name, dst_gmtoff, start_rule, end_rule = posix_info
    if start_rule is None or end_rule is None:
        return None, None
    sm, sw, sd, stime = start_rule
    em, ew, ed, etime = end_rule
    s_day = find_mwd(year, sm, sw, sd)
    e_day = find_mwd(year, em, ew, ed)
    utc_start = _date_to_epoch(year, sm, s_day) + stime - std_gmtoff
    utc_end = _date_to_epoch(year, em, e_day) + etime - dst_gmtoff
    return utc_start, utc_end


def get_type_at(t, trans_times, trans_types, types, abbr_chars, posix_info):
    if not trans_times:
        gmtoff, isdst, abbrind = types[0]
        return gmtoff, isdst, parse_abbr(abbr_chars, abbrind)

    if t < trans_times[0]:
        gmtoff, isdst, abbrind = types[0]
        return gmtoff, isdst, parse_abbr(abbr_chars, abbrind)

    if t > trans_times[-1]:
        if posix_info is None:
            type_idx = trans_types[-1]
            gmtoff, isdst, abbrind = types[type_idx]
            return gmtoff, isdst, parse_abbr(abbr_chars, abbrind)
        std_name, std_gmtoff, dst_name, dst_gmtoff, start_rule, end_rule = posix_info
        if start_rule is None:
            return std_gmtoff, 0, std_name
        approx_year = 1970 + (t + 43200) // 31556952
        for year in range(approx_year - 2, approx_year + 3):
            utc_start, utc_end = get_footer_transitions(year, posix_info)
            if utc_start is None:
                continue
            year_start = _date_to_epoch(year, 1, 1)
            year_end = _date_to_epoch(year + 1, 1, 1)
            if not (year_start <= t < year_end):
                continue
            if utc_start <= utc_end:
                if utc_start <= t < utc_end:
                    return dst_gmtoff, 1, dst_name
                else:
                    return std_gmtoff, 0, std_name
            else:
                if t < utc_end or t >= utc_start:
                    return dst_gmtoff, 1, dst_name
                else:
                    return std_gmtoff, 0, std_name
        return std_gmtoff, 0, std_name

    # Between transitions (inclusive of last transition)
    lo, hi = 0, len(trans_times) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if trans_times[mid] <= t:
            lo = mid
        else:
            hi = mid - 1
    type_idx = trans_types[lo]
    gmtoff, isdst, abbrind = types[type_idx]
    return gmtoff, isdst, parse_abbr(abbr_chars, abbrind)


def format_offset(gmtoff):
    if gmtoff < 0:
        sign = '-'
        gmtoff = -gmtoff
    else:
        sign = '+'
    hours = gmtoff // 3600
    minutes = (gmtoff % 3600) // 60
    seconds = gmtoff % 60
    if seconds:
        return f"{sign}{hours:02d}:{minutes:02d}:{seconds:02d}"
    return f"{sign}{hours:02d}:{minutes:02d}"


def format_local(t, gmtoff):
    local_epoch = t + gmtoff
    days = local_epoch // 86400
    rem = local_epoch % 86400
    d = date(1970, 1, 1) + timedelta(days=days)
    h = rem // 3600
    m = (rem % 3600) // 60
    s = rem % 60
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}T{h:02d}:{m:02d}:{s:02d}"


def parse_wall(s):
    dp, tp = s.split('T')
    y, mo, d = map(int, dp.split('-'))
    h, mi, sec = map(int, tp.split(':'))
    return (date(y, mo, d) - date(1970, 1, 1)).days * 86400 + h * 3600 + mi * 60 + sec


def find_gap(line, wall, trans_times, trans_types, types, abbr_chars, posix_info):
    for i in range(len(trans_times)):
        T = trans_times[i]
        if i > 0:
            old_idx = trans_types[i - 1]
        else:
            old_idx = 0
        new_idx = trans_types[i]
        old_off = types[old_idx][0]
        new_off = types[new_idx][0]
        if new_off > old_off:
            gap_start = T + old_off
            gap_end = T + new_off
            if gap_start <= wall < gap_end:
                t = wall - old_off
                gmtoff, isdst, abbr = get_type_at(t, trans_times, trans_types, types, abbr_chars, posix_info)
                local_str = format_local(t, gmtoff)
                off_str = format_offset(gmtoff)
                return f"{line} -> GAP {t} {local_str}{off_str} {abbr}"

    if posix_info:
        std_name, std_gmtoff, dst_name, dst_gmtoff, start_rule, end_rule = posix_info
        if start_rule is not None and dst_gmtoff > std_gmtoff:
            approx_year = 1970 + (wall + 43200) // 31556952
            for year in range(approx_year - 2, approx_year + 3):
                utc_start, utc_end = get_footer_transitions(year, posix_info)
                if utc_start is None:
                    continue
                gap_start = utc_start + std_gmtoff
                gap_end = utc_start + dst_gmtoff
                if gap_start <= wall < gap_end:
                    t = wall - std_gmtoff
                    gmtoff, isdst, abbr = get_type_at(t, trans_times, trans_types, types, abbr_chars, posix_info)
                    local_str = format_local(t, gmtoff)
                    off_str = format_offset(gmtoff)
                    return f"{line} -> GAP {t} {local_str}{off_str} {abbr}"

    return f"{line} -> ERROR"


def main():
    work_dir = sys.argv[1]

    with open(os.path.join(work_dir, 'queries.txt'), 'r') as f:
        lines = f.readlines()

    cache = {}

    def get_tzif(fn):
        if fn not in cache:
            cache[fn] = parse_tzif(os.path.join(work_dir, fn))
        return cache[fn]

    results = []

    for line in lines:
        line = line.rstrip('\n')
        if not line.strip():
            continue

        parts = line.split(' ')
        qtype = parts[0]
        fn = parts[1]

        trans_times, trans_types, types, abbr_chars, posix_str = get_tzif(fn)
        posix_info = parse_posix_tz(posix_str) if posix_str else None

        if qtype == 'UTC':
            t = int(parts[2])
            gmtoff, isdst, abbr = get_type_at(t, trans_times, trans_types, types, abbr_chars, posix_info)
            local_str = format_local(t, gmtoff)
            off_str = format_offset(gmtoff)
            results.append(f"{line} -> {local_str}{off_str} {abbr}")

        elif qtype == 'LOCAL':
            wall_str = parts[2]
            wall = parse_wall(wall_str)

            offsets_to_check = set()
            offsets_to_check.add(types[0][0])
            for i in range(len(trans_types)):
                offsets_to_check.add(types[trans_types[i]][0])
            if posix_info:
                offsets_to_check.add(posix_info[1])
                if posix_info[3] is not None:
                    offsets_to_check.add(posix_info[3])

            candidates = []
            for off in offsets_to_check:
                t_cand = wall - off
                gmtoff, isdst, abbr = get_type_at(t_cand, trans_times, trans_types, types, abbr_chars, posix_info)
                if gmtoff == off:
                    candidates.append((t_cand, gmtoff, abbr))

            seen = set()
            unique = []
            for c in candidates:
                if c[0] not in seen:
                    seen.add(c[0])
                    unique.append(c)
            candidates = sorted(unique, key=lambda x: x[0])

            if len(candidates) == 1:
                t, off, abbr = candidates[0]
                results.append(f"{line} -> {t} {format_offset(off)} {abbr}")
            elif len(candidates) == 2:
                (t1, o1, a1), (t2, o2, a2) = candidates
                results.append(f"{line} -> {t1} {format_offset(o1)} {a1} | {t2} {format_offset(o2)} {a2}")
            elif len(candidates) == 0:
                gap_result = find_gap(line, wall, trans_times, trans_types, types, abbr_chars, posix_info)
                results.append(gap_result)
            else:
                results.append(f"{line} -> ERROR")

    for r in results:
        print(r)


if __name__ == '__main__':
    main()

import Foundation
import CommonCrypto

// MARK: - SHA-1

func sha1Hash(_ data: Data) -> Data {
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    data.withUnsafeBytes { ptr in
        _ = CC_SHA1(ptr.baseAddress, CC_LONG(data.count), &digest)
    }
    return Data(digest)
}

func sha1Hex(_ data: Data) -> String {
    let digest = sha1Hash(data)
    return digest.map { String(format: "%02x", $0) }.joined()
}

// MARK: - Random

func randomBytes(_ count: Int) -> Data {
    var bytes = [UInt8](repeating: 0, count: count)
    for i in 0..<count {
        bytes[i] = UInt8.random(in: 0...255)
    }
    return Data(bytes)
}

// MARK: - URL Parsing

struct WSURL {
    let host: String
    let port: UInt16
    let requestTarget: String
}

func parseWSURL(_ url: String) -> WSURL? {
    guard url.hasPrefix("ws://") else { return nil }
    let rest = String(url.dropFirst(5))
    guard let slashIdx = rest.firstIndex(of: "/") else { return nil }
    let hostPort = String(rest[..<slashIdx])
    let requestTarget = String(rest[slashIdx...])
    let parts = hostPort.split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
    guard parts.count == 2 else { return nil }
    let host = String(parts[0])
    guard let port = UInt16(parts[1]) else { return nil }
    return WSURL(host: host, port: port, requestTarget: requestTarget)
}

// MARK: - Buffered TCP Connection

class Connection {
    let fd: Int32
    var buf: [UInt8] = []
    var pos: Int = 0

    init(fd: Int32) { self.fd = fd }

    func fill(min: Int) -> Bool {
        while buf.count - pos < min {
            if pos > 0 {
                buf.removeFirst(pos)
                pos = 0
            }
            var tmp = [UInt8](repeating: 0, count: 65536)
            let n = recv(fd, &tmp, tmp.count, 0)
            if n <= 0 { return false }
            buf.append(contentsOf: tmp[0..<n])
        }
        return true
    }

    func readExact(_ n: Int) -> Data? {
        if n == 0 { return Data() }
        guard fill(min: n) else { return nil }
        let d = Data(buf[pos..<pos+n])
        pos += n
        return d
    }

    func readHeaders() -> String? {
        let pat: [UInt8] = [13, 10, 13, 10]
        while true {
            if let idx = findPat(buf, from: pos, pat: pat) {
                let hdr = String(bytes: buf[pos..<idx], encoding: .ascii) ?? ""
                pos = idx + 4
                return hdr
            }
            var tmp = [UInt8](repeating: 0, count: 65536)
            let n = recv(fd, &tmp, tmp.count, 0)
            if n <= 0 { return nil }
            buf.append(contentsOf: tmp[0..<n])
        }
    }

    func writeData(_ data: Data) {
        var off = 0
        data.withUnsafeBytes { ptr in
            while off < data.count {
                let n = send(fd, ptr.baseAddress!.advanced(by: off), data.count - off, 0)
                if n <= 0 { return }
                off += n
            }
        }
    }

    func closeSocket() {
        Darwin.close(fd)
    }
}

func findPat(_ data: [UInt8], from start: Int, pat: [UInt8]) -> Int? {
    let end = data.count - pat.count
    var i = start
    while i <= end {
        var ok = true
        for j in 0..<pat.count {
            if data[i+j] != pat[j] { ok = false; break }
        }
        if ok { return i }
        i += 1
    }
    return nil
}

// MARK: - WebSocket Frames

struct WSFrame {
    let fin: Bool
    let opcode: UInt8
    let payload: Data
}

func readFrame(_ conn: Connection) -> WSFrame? {
    guard let hdr = conn.readExact(2) else { return nil }
    let b0 = hdr[hdr.startIndex]
    let b1 = hdr[hdr.startIndex + 1]
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let masked = (b1 & 0x80) != 0
    var len = Int(b1 & 0x7F)

    if len == 126 {
        guard let ext = conn.readExact(2) else { return nil }
        len = (Int(ext[ext.startIndex]) << 8) | Int(ext[ext.startIndex + 1])
    } else if len == 127 {
        guard let ext = conn.readExact(8) else { return nil }
        len = 0
        for i in 0..<8 {
            len = (len << 8) | Int(ext[ext.startIndex + i])
        }
    }

    var maskKey: [UInt8] = []
    if masked {
        guard let mk = conn.readExact(4) else { return nil }
        maskKey = [UInt8](mk)
    }

    var payload = Data()
    if len > 0 {
        guard let p = conn.readExact(len) else { return nil }
        payload = p
        if masked {
            for i in 0..<payload.count {
                payload[payload.startIndex + i] ^= maskKey[i % 4]
            }
        }
    }

    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

func sendFrame(_ conn: Connection, opcode: UInt8, payload: Data) {
    var frame = Data()
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in (0..<8).reversed() {
            frame.append(UInt8((len >> (8 * i)) & 0xFF))
        }
    }

    var maskKey: [UInt8]
    repeat {
        maskKey = [UInt8](randomBytes(4))
    } while maskKey == [0, 0, 0, 0]

    frame.append(contentsOf: maskKey)

    for i in 0..<payload.count {
        frame.append(payload[payload.startIndex + i] ^ maskKey[i % 4])
    }

    conn.writeData(frame)
}

// MARK: - Close Handling

func handleServerClose(_ conn: Connection, frame: WSFrame, sentClose: inout Bool) {
    var code = 1005
    var reason = ""
    if frame.payload.count >= 2 {
        let p = frame.payload
        code = (Int(p[p.startIndex]) << 8) | Int(p[p.startIndex + 1])
        if frame.payload.count > 2 {
            reason = String(data: frame.payload[(frame.payload.startIndex + 2)...], encoding: .utf8) ?? ""
        }
    }

    if reason.isEmpty {
        print("closed \(code)")
    } else {
        print("closed \(code) \(reason)")
    }

    if !sentClose {
        let closePayload = Data([UInt8(code >> 8), UInt8(code & 0xFF)])
        sendFrame(conn, opcode: 8, payload: closePayload)
        sentClose = true
    }
}

// MARK: - Read next data message (handling pings/pongs between fragments)

func readDataMessage(_ conn: Connection, sentClose: inout Bool) -> (opcode: UInt8, payload: Data)? {
    while true {
        guard let frame = readFrame(conn) else { return nil }
        switch frame.opcode {
        case 9: // ping
            sendFrame(conn, opcode: 10, payload: frame.payload)
            continue
        case 10: // pong
            continue
        case 8: // close
            handleServerClose(conn, frame: frame, sentClose: &sentClose)
            return nil
        case 1, 2:
            var payload = frame.payload
            let msgOpcode = frame.opcode
            if !frame.fin {
                while true {
                    guard let cont = readFrame(conn) else { return nil }
                    switch cont.opcode {
                    case 9:
                        sendFrame(conn, opcode: 10, payload: cont.payload)
                        continue
                    case 10:
                        continue
                    case 8:
                        handleServerClose(conn, frame: cont, sentClose: &sentClose)
                        return nil
                    case 0:
                        payload.append(cont.payload)
                        if cont.fin { break }
                    default:
                        break
                    }
                    if cont.fin { break }
                }
            }
            return (msgOpcode, payload)
        default:
            continue
        }
    }
}

// MARK: - Session Handler

func handleSession(_ url: WSURL, sessionNum: Int) {
    print("session \(sessionNum)")

    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0 { return }

    var noSigPipe: Int32 = 1
    setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &noSigPipe, socklen_t(MemoryLayout<Int32>.size))

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = url.port.bigEndian
    inet_pton(AF_INET, url.host, &addr.sin_addr)

    let connResult = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            Darwin.connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if connResult != 0 {
        Darwin.close(fd)
        return
    }

    let conn = Connection(fd: fd)

    // Handshake
    let keyData = randomBytes(16)
    let key = keyData.base64EncodedString()

    let request = "GET \(url.requestTarget) HTTP/1.1\r\n" +
        "Host: \(url.host):\(url.port)\r\n" +
        "Upgrade: websocket\r\n" +
        "Connection: Upgrade\r\n" +
        "Sec-WebSocket-Version: 13\r\n" +
        "Sec-WebSocket-Key: \(key)\r\n" +
        "\r\n"

    conn.writeData(Data(request.utf8))

    guard let headerStr = conn.readHeaders() else {
        conn.closeSocket()
        return
    }

    let lines = headerStr.components(separatedBy: "\r\n")
    guard let statusLine = lines.first else {
        conn.closeSocket()
        return
    }

    let statusParts = statusLine.components(separatedBy: " ")
    guard statusParts.count >= 2, let statusCode = Int(statusParts[1]) else {
        conn.closeSocket()
        return
    }

    if statusCode != 101 {
        let reason = statusParts.count > 2 ? statusParts[2...].joined(separator: " ") : ""
        print("handshake failed: \(statusCode) \(reason)")
        conn.closeSocket()
        return
    }

    // Check Sec-WebSocket-Accept
    var acceptValue: String? = nil
    for line in lines.dropFirst() {
        if let colonIdx = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<colonIdx]).lowercased()
            let value = String(line[line.index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
            if name == "sec-websocket-accept" {
                acceptValue = value
            }
        }
    }

    let expectedAccept = sha1Hash(Data((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").utf8))
        .base64EncodedString()

    if acceptValue != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        conn.closeSocket()
        return
    }

    // Process frames
    var sentClose = false

    while true {
        guard let msg = readDataMessage(conn, sentClose: &sentClose) else {
            break
        }

        if msg.opcode != 1 { continue } // only text messages are commands

        guard let text = String(data: msg.payload, encoding: .utf8) else { continue }

        if text == "BYE" {
            sendFrame(conn, opcode: 8, payload: Data([0x03, 0xE8]))
            sentClose = true
            // Read until server close
            while true {
                guard let f = readFrame(conn) else { break }
                switch f.opcode {
                case 9:
                    sendFrame(conn, opcode: 10, payload: f.payload)
                case 10:
                    break
                case 8:
                    handleServerClose(conn, frame: f, sentClose: &sentClose)
                    conn.closeSocket()
                    return
                default:
                    break
                }
            }
            conn.closeSocket()
            return
        } else if text.hasPrefix("ADD ") {
            let parts = text.split(separator: " ")
            if parts.count >= 3, let a = Int64(parts[1]), let b = Int64(parts[2]) {
                let sum = a + b
                let reply = String(sum)
                sendFrame(conn, opcode: 1, payload: Data(reply.utf8))
                print("\(text) -> \(reply)")
            }
        } else if text.hasPrefix("REV ") {
            let textToReverse = String(text.dropFirst(4))
            var reversed = ""
            for s in textToReverse.unicodeScalars.reversed() {
                reversed.unicodeScalars.append(s)
            }
            sendFrame(conn, opcode: 1, payload: Data(reversed.utf8))
            print("REV \(textToReverse) -> \(reversed)")
        } else if text == "SHA1" {
            guard let binMsg = readDataMessage(conn, sentClose: &sentClose) else {
                conn.closeSocket()
                return
            }
            let hex = sha1Hex(binMsg.payload)
            sendFrame(conn, opcode: 1, payload: Data(hex.utf8))
            print("SHA1 \(binMsg.payload.count) -> \(hex)")
        }
    }

    conn.closeSocket()
}

// MARK: - Main

let args = CommandLine.arguments
if args.count < 2 {
    exit(0)
}

for i in 1..<args.count {
    guard let url = parseWSURL(args[i]) else { continue }
    handleSession(url, sessionNum: i)
}

exit(0)

import Foundation

// MARK: - Date/Time Utilities

func isLeapYear(_ y: Int) -> Bool {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

func daysInMonth(_ y: Int, _ m: Int) -> Int {
    switch m {
    case 1,3,5,7,8,10,12: return 31
    case 4,6,9,11: return 30
    case 2: return isLeapYear(y) ? 29 : 28
    default: return 0
    }
}

func civilFromDays(_ z0: Int64) -> (Int, Int, Int) {
    var z = z0 + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2) / 153
    let d = doy - (153*mp + 2) / 5 + 1
    let m = mp < 10 ? mp + 3 : mp - 9
    return (Int(y + (m <= 2 ? 1 : 0)), Int(m), Int(d))
}

func daysFromCivil(_ y0: Int, _ m0: Int, _ d0: Int) -> Int64 {
    var y = Int64(y0)
    let m = Int64(m0)
    let d = Int64(d0)
    y -= m <= 2 ? 1 : 0
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let mp = m + (m > 2 ? -3 : 9)
    let doy = (153*mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe/4 - yoe/100 + doy
    return era * 146097 + doe - 719468
}

func dayOfWeek(_ y: Int, _ m: Int, _ d: Int) -> Int {
    let days = daysFromCivil(y, m, d)
    return Int(((days % 7) + 4 + 7) % 7)
}

func yearFromUnix(_ t: Int64) -> Int {
    let days: Int64 = t >= 0 ? t / 86400 : (t - 86399) / 86400
    let (y, _, _) = civilFromDays(days)
    return y
}

func formatOffset(_ off: Int) -> String {
    let sign = off >= 0 ? "+" : "-"
    let a = abs(off)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalDateTime(_ t: Int64, _ offset: Int) -> String {
    let lt = t + Int64(offset)
    let days: Int64 = lt >= 0 ? lt / 86400 : (lt - 86399) / 86400
    let rem = lt - days * 86400
    let (y, m, d) = civilFromDays(days)
    let h = Int(rem) / 3600
    let mi = (Int(rem) % 3600) / 60
    let s = Int(rem) % 60
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s)
}

func parseWallClock(_ s: Substring) -> Int64 {
    let parts = s.split(separator: "T")
    let dp = parts[0].split(separator: "-")
    let tp = parts[1].split(separator: ":")
    let y = Int(dp[0])!
    let m = Int(dp[1])!
    let d = Int(dp[2])!
    let h = Int(tp[0])!
    let mi = Int(tp[1])!
    let s = Int(tp[2])!
    return daysFromCivil(y, m, d) * 86400 + Int64(h)*3600 + Int64(mi)*60 + Int64(s)
}

// MARK: - TZif Structures

struct LocalTimeType {
    let gmtoff: Int32
    let isdst: Bool
    let abbr: String
}

struct Transition {
    let time: Int64
    let typeIdx: Int
}

struct PosixTZ {
    let stdName: String
    let stdOffset: Int
    let dstName: String?
    let dstOffset: Int
    let hasDst: Bool
    let startMonth: Int
    let startWeek: Int
    let startDay: Int
    let startTime: Int
    let endMonth: Int
    let endWeek: Int
    let endDay: Int
    let endTime: Int
    let hasRules: Bool
}

struct TZifData {
    var transitions: [Transition] = []
    var types: [LocalTimeType] = []
    var posixTZ: PosixTZ? = nil
}

// MARK: - Big-Endian Readers

func readBE32(_ b: [UInt8], _ o: Int) -> Int32 {
    return Int32(bitPattern: UInt32(b[o]) << 24 | UInt32(b[o+1]) << 16 | UInt32(b[o+2]) << 8 | UInt32(b[o+3]))
}

func readBE64(_ b: [UInt8], _ o: Int) -> Int64 {
    var v: UInt64 = 0
    for i in 0..<8 { v = (v << 8) | UInt64(b[o+i]) }
    return Int64(bitPattern: v)
}

// MARK: - TZif Parsing

func parseTZif(_ path: String) -> TZifData {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)
    var result = TZifData()

    // First header: 44 bytes
    let isutcnt1 = Int(readBE32(bytes, 20))
    let isstdcnt1 = Int(readBE32(bytes, 24))
    let leapcnt1 = Int(readBE32(bytes, 28))
    let timecnt1 = Int(readBE32(bytes, 32))
    let typecnt1 = Int(readBE32(bytes, 36))
    let charcnt1 = Int(readBE32(bytes, 40))
    _ = isutcnt1; _ = isstdcnt1; _ = leapcnt1; _ = typecnt1; _ = charcnt1

    let block1Size = timecnt1*4 + timecnt1 + typecnt1*6 + charcnt1 + leapcnt1*8 + isstdcnt1 + isutcnt1
    var off = 44 + block1Size

    // Second header: 44 bytes
    let isutcnt2 = Int(readBE32(bytes, off + 20))
    let isstdcnt2 = Int(readBE32(bytes, off + 24))
    let leapcnt2 = Int(readBE32(bytes, off + 28))
    let timecnt2 = Int(readBE32(bytes, off + 32))
    let typecnt2 = Int(readBE32(bytes, off + 36))
    let charcnt2 = Int(readBE32(bytes, off + 40))
    off += 44

    // Transition times (64-bit)
    var transTimes = [Int64]()
    for _ in 0..<timecnt2 {
        transTimes.append(readBE64(bytes, off))
        off += 8
    }

    // Type indices
    var transTypeIdx = [Int]()
    for _ in 0..<timecnt2 {
        transTypeIdx.append(Int(bytes[off]))
        off += 1
    }

    for i in 0..<timecnt2 {
        result.transitions.append(Transition(time: transTimes[i], typeIdx: transTypeIdx[i]))
    }

    // Local time type records
    let typesOff = off
    off += typecnt2 * 6

    // Abbreviation chars
    let abbrStart = off
    off += charcnt2

    // Leap seconds (skip)
    off += leapcnt2 * 12
    // isstd/isut (skip)
    off += isstdcnt2
    off += isutcnt2

    // Parse types
    for i in 0..<typecnt2 {
        let ro = typesOff + i*6
        let gmtoff = readBE32(bytes, ro)
        let isdst = bytes[ro+4] != 0
        let abbrIdx = Int(bytes[ro+5])
        var abbr = ""
        var j = abbrStart + abbrIdx
        while j < bytes.count && bytes[j] != 0 {
            abbr.append(Character(UnicodeScalar(bytes[j])))
            j += 1
        }
        result.types.append(LocalTimeType(gmtoff: gmtoff, isdst: isdst, abbr: abbr))
    }

    // Footer: \n POSIX_TZ \n
    if off < bytes.count && bytes[off] == 0x0A {
        off += 1
        var tzStr = ""
        while off < bytes.count && bytes[off] != 0x0A {
            tzStr.append(Character(UnicodeScalar(bytes[off])))
            off += 1
        }
        if !tzStr.isEmpty {
            result.posixTZ = parsePosixTZ(tzStr)
        }
    }

    return result
}

// MARK: - POSIX TZ Parsing

func parsePosixTZ(_ s: String) -> PosixTZ? {
    let chars = Array(s)
    var pos = 0

    func peek() -> Character? { pos < chars.count ? chars[pos] : nil }
    func consume() -> Character? { guard pos < chars.count else { return nil }; let c = chars[pos]; pos += 1; return c }

    func parseName() -> String? {
        guard let c = peek() else { return nil }
        if c == "<" {
            pos += 1
            var name = ""
            while let ch = consume(), ch != ">" { name.append(ch) }
            return name
        } else if c.isLetter {
            var name = ""
            while let ch = peek(), ch.isLetter { name.append(consume()!) }
            return name.count >= 3 ? name : nil
        }
        return nil
    }

    func parseOffsetVal() -> Int? {
        var sign = 1
        if let c = peek(), c == "+" { pos += 1 }
        else if let c = peek(), c == "-" { pos += 1; sign = -1 }
        var hours = 0; var nd = 0
        while let c = peek(), c.isNumber, nd < 3 { hours = hours*10 + Int(String(consume()!))!; nd += 1 }
        if nd == 0 { return nil }
        var mins = 0; var secs = 0
        if peek() == ":" {
            pos += 1; nd = 0
            while let c = peek(), c.isNumber, nd < 2 { mins = mins*10 + Int(String(consume()!))!; nd += 1 }
        }
        if peek() == ":" {
            pos += 1; nd = 0
            while let c = peek(), c.isNumber, nd < 2 { secs = secs*10 + Int(String(consume()!))!; nd += 1 }
        }
        return sign * (hours*3600 + mins*60 + secs)
    }

    func parseNum() -> Int? {
        var n = 0; var nd = 0
        while let c = peek(), c.isNumber { n = n*10 + Int(String(consume()!))!; nd += 1 }
        return nd > 0 ? n : nil
    }

    func parseMWD() -> (Int, Int, Int)? {
        guard let c = peek(), c == "M" else { return nil }
        pos += 1
        guard let m = parseNum() else { return nil }
        guard peek() == "." else { return nil }
        pos += 1
        guard let w = parseNum() else { return nil }
        guard peek() == "." else { return nil }
        pos += 1
        guard let d = parseNum() else { return nil }
        return (m, w, d)
    }

    func parseTimeVal() -> Int {
        var sign = 1
        if let c = peek(), c == "+" { pos += 1 }
        else if let c = peek(), c == "-" { pos += 1; sign = -1 }
        var hours = 0
        while let c = peek(), c.isNumber { hours = hours*10 + Int(String(consume()!))! }
        var mins = 0; var secs = 0
        if peek() == ":" {
            pos += 1
            while let c = peek(), c.isNumber { mins = mins*10 + Int(String(consume()!))! }
        }
        if peek() == ":" {
            pos += 1
            while let c = peek(), c.isNumber { secs = secs*10 + Int(String(consume()!))! }
        }
        return sign * (hours*3600 + mins*60 + secs)
    }

    guard let stdName = parseName() else { return nil }
    guard let stdOffset = parseOffsetVal() else { return nil }

    var dstName: String? = nil
    var dstOffset = stdOffset - 3600
    var hasDst = false
    var sMonth = 3, sWeek = 2, sDay = 0, sTime = 7200
    var eMonth = 11, eWeek = 1, eDay = 0, eTime = 7200
    var hasRules = false

    if pos < chars.count {
        if let dn = parseName() {
            dstName = dn
            hasDst = true
            if pos < chars.count {
                let c = chars[pos]
                if c == "+" || c == "-" || c.isNumber {
                    if let doff = parseOffsetVal() { dstOffset = doff }
                }
            }
            if peek() == "," {
                pos += 1
                if let (m, w, d) = parseMWD() { sMonth = m; sWeek = w; sDay = d }
                if peek() == "/" { pos += 1; sTime = parseTimeVal() }
                if peek() == "," {
                    pos += 1
                    if let (m, w, d) = parseMWD() { eMonth = m; eWeek = w; eDay = d }
                    if peek() == "/" { pos += 1; eTime = parseTimeVal() }
                }
                hasRules = true
            }
        }
    }

    return PosixTZ(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset,
                   hasDst: hasDst, startMonth: sMonth, startWeek: sWeek, startDay: sDay, startTime: sTime,
                   endMonth: eMonth, endWeek: eWeek, endDay: eDay, endTime: eTime, hasRules: hasRules)
}

// MARK: - Footer Transition Computation

func computeFooterTrans(year: Int, month: Int, week: Int, day: Int, time: Int, posixOff: Int) -> Int64 {
    let dim = daysInMonth(year, month)
    let dow1 = dayOfWeek(year, month, 1)
    let firstDay = 1 + ((day - dow1 + 7) % 7)
    var targetDay: Int
    if week == 5 {
        targetDay = firstDay + ((dim - firstDay) / 7) * 7
    } else {
        targetDay = firstDay + (week - 1) * 7
    }
    let baseSec = daysFromCivil(year, month, targetDay) * 86400
    return baseSec + Int64(time) + Int64(posixOff)
}

func footerTypeAt(t: Int64, posix: PosixTZ) -> (utcOff: Int, abbr: String) {
    let stdUtcOff = -posix.stdOffset
    let dstUtcOff = -posix.dstOffset
    if !posix.hasDst {
        return (stdUtcOff, posix.stdName)
    }
    let y = yearFromUnix(t)
    let startT = computeFooterTrans(year: y, month: posix.startMonth, week: posix.startWeek, day: posix.startDay, time: posix.startTime, posixOff: posix.stdOffset)
    let endT = computeFooterTrans(year: y, month: posix.endMonth, week: posix.endWeek, day: posix.endDay, time: posix.endTime, posixOff: posix.dstOffset)
    if startT < endT {
        if t >= startT && t < endT { return (dstUtcOff, posix.dstName!) }
        else { return (stdUtcOff, posix.stdName) }
    } else {
        let ys = daysFromCivil(y, 1, 1) * 86400
        let ye = daysFromCivil(y+1, 1, 1) * 86400
        if (t >= startT && t < ye) || (t >= ys && t < endT) { return (dstUtcOff, posix.dstName!) }
        else { return (stdUtcOff, posix.stdName) }
    }
}

// MARK: - Type Determination

func typeAtTime(tzif: TZifData, t: Int64) -> (utcOff: Int, abbr: String) {
    let n = tzif.transitions.count
    if n == 0 {
        if let p = tzif.posixTZ { return footerTypeAt(t: t, posix: p) }
        if !tzif.types.isEmpty { return (Int(tzif.types[0].gmtoff), tzif.types[0].abbr) }
        return (0, "")
    }
    let firstT = tzif.transitions[0].time
    let lastT = tzif.transitions[n-1].time
    if t < firstT {
        return (Int(tzif.types[0].gmtoff), tzif.types[0].abbr)
    }
    if t > lastT {
        if let p = tzif.posixTZ { return footerTypeAt(t: t, posix: p) }
        return (Int(tzif.types[tzif.transitions[n-1].typeIdx].gmtoff), tzif.types[tzif.transitions[n-1].typeIdx].abbr)
    }
    // t is in [firstT, lastT], binary search for latest transition <= t
    var lo = 0, hi = n - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tzif.transitions[mid].time <= t { lo = mid }
        else { hi = mid - 1 }
    }
    let ti = tzif.transitions[lo].typeIdx
    return (Int(tzif.types[ti].gmtoff), tzif.types[ti].abbr)
}

// MARK: - Query Processing

func processUTC(tzif: TZifData, t: Int64) -> String {
    let (off, abbr) = typeAtTime(tzif: tzif, t: t)
    let localStr = formatLocalDateTime(t, off)
    let offStr = formatOffset(off)
    return "\(localStr)\(offStr) \(abbr)"
}

func processLocal(tzif: TZifData, wallClockStr: Substring) -> String {
    let wSec = parseWallClock(wallClockStr)
    var results: [(t: Int64, off: Int, abbr: String)] = []

    let n = tzif.transitions.count
    if n == 0 {
        // No transitions: use footer or type 0
        if let p = tzif.posixTZ {
            let stdOff = -p.stdOffset
            let t1 = wSec - Int64(stdOff)
            let (o, a) = typeAtTime(tzif: tzif, t: t1)
            if o == stdOff { results.append((t1, stdOff, p.stdName)) }
            if p.hasDst {
                let dstOff = -p.dstOffset
                let t2 = wSec - Int64(dstOff)
                let (o2, a2) = typeAtTime(tzif: tzif, t: t2)
                if o2 == dstOff && t2 != t1 { results.append((t2, dstOff, p.dstName!)) }
            }
        } else if !tzif.types.isEmpty {
            let off0 = Int(tzif.types[0].gmtoff)
            let tc = wSec - Int64(off0)
            results.append((tc, off0, tzif.types[0].abbr))
        }
    } else {
        let firstT = tzif.transitions[0].time
        let lastT = tzif.transitions[n-1].time

        // Segment (-inf, firstT): type 0
        let off0 = Int(tzif.types[0].gmtoff)
        let tc0 = wSec - Int64(off0)
        if tc0 < firstT {
            results.append((tc0, off0, tzif.types[0].abbr))
        }

        // Segments [Ti, Ti+1) for i in 0..n-2
        for i in 0..<(n-1) {
            let ti = tzif.transitions[i].typeIdx
            let off = Int(tzif.types[ti].gmtoff)
            let tc = wSec - Int64(off)
            if tc >= tzif.transitions[i].time && tc < tzif.transitions[i+1].time {
                results.append((tc, off, tzif.types[ti].abbr))
            }
        }

        // Single point [lastT, lastT]: type of last transition
        let lastTi = tzif.transitions[n-1].typeIdx
        let lastOff = Int(tzif.types[lastTi].gmtoff)
        let tcLast = wSec - Int64(lastOff)
        if tcLast == lastT {
            results.append((tcLast, lastOff, tzif.types[lastTi].abbr))
        }

        // Footer: (lastT, +inf)
        if let p = tzif.posixTZ {
            let stdOff = -p.stdOffset
            let tStd = wSec - Int64(stdOff)
            if tStd > lastT {
                let (o, _) = typeAtTime(tzif: tzif, t: tStd)
                if o == stdOff {
                    results.append((tStd, stdOff, p.stdName))
                }
            }
            if p.hasDst {
                let dstOff = -p.dstOffset
                let tDst = wSec - Int64(dstOff)
                if tDst > lastT {
                    let (o, _) = typeAtTime(tzif: tzif, t: tDst)
                    if o == dstOff {
                        // Avoid duplicate
                        if !results.contains(where: { $0.t == tDst }) {
                            results.append((tDst, dstOff, p.dstName!))
                        }
                    }
                }
            }
        }
    }

    results.sort { $0.t < $1.t }

    if results.count == 1 {
        let r = results[0]
        return " \(r.t) \(formatOffset(r.off)) \(r.abbr)"
    } else if results.count >= 2 {
        let r1 = results[0], r2 = results[1]
        return " \(r1.t) \(formatOffset(r1.off)) \(r1.abbr) | \(r2.t) \(formatOffset(r2.off)) \(r2.abbr)"
    }

    // GAP: find the forward transition that skipped this wall-clock time
    var gapT: Int64 = 0
    var gapOff: Int = 0
    var found = false

    // Check table transitions
    for i in 0..<n {
        let Ti = tzif.transitions[i].time
        let newOff = Int(tzif.types[tzif.transitions[i].typeIdx].gmtoff)
        let oldOff: Int
        if i == 0 { oldOff = Int(tzif.types[0].gmtoff) }
        else { oldOff = Int(tzif.types[tzif.transitions[i-1].typeIdx].gmtoff) }
        if newOff > oldOff {
            if Ti + Int64(oldOff) <= wSec && wSec < Ti + Int64(newOff) {
                gapT = wSec - Int64(oldOff)
                gapOff = oldOff
                found = true
                break
            }
        }
    }

    // Check footer DST start transitions
    if !found, let p = tzif.posixTZ, p.hasDst {
        let stdOff = -p.stdOffset
        let dstOff = -p.dstOffset
        if dstOff > stdOff {
            let approxY = yearFromUnix(wSec)
            for y in (approxY-1)...(approxY+1) {
                let startT = computeFooterTrans(year: y, month: p.startMonth, week: p.startWeek, day: p.startDay, time: p.startTime, posixOff: p.stdOffset)
                if startT > lastT {
                    if startT + Int64(stdOff) <= wSec && wSec < startT + Int64(dstOff) {
                        gapT = wSec - Int64(stdOff)
                        gapOff = stdOff
                        found = true
                        break
                    }
                }
            }
        }
    }

    if found {
        let (localOff, localAbbr) = typeAtTime(tzif: tzif, t: gapT)
        let localStr = formatLocalDateTime(gapT, localOff)
        let offStr = formatOffset(localOff)
        return " GAP \(gapT) \(localStr)\(offStr) \(localAbbr)"
    }

    // Fallback (shouldn't happen)
    return " GAP \(wSec) \(formatLocalDateTime(wSec, 0))+00:00 "
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let queriesPath = dir + "/queries.txt"
let queriesContent = try! String(contentsOfFile: queriesPath, encoding: .utf8)
let lines = queriesContent.components(separatedBy: "\n")

var tzifCache: [String: TZifData] = [:]

for line in lines {
    if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }
    let fields = line.split(separator: " ", omittingEmptySubsequences: false)
    guard fields.count >= 3 else { continue }
    let qType = String(fields[0])
    let fileName = String(fields[1])

    if tzifCache[fileName] == nil {
        let path = dir + "/" + fileName
        tzifCache[fileName] = parseTZif(path)
    }
    let tzif = tzifCache[fileName]!

    if qType == "UTC" {
        let t = Int64(String(fields[2]))!
        let result = processUTC(tzif: tzif, t: t)
        print("\(line) -> \(result)")
    } else if qType == "LOCAL" {
        let wallClock = fields[2]
        let result = processLocal(tzif: tzif, wallClockStr: wallClock)
        print("\(line) ->\(result)")
    }
}

import Foundation

// MARK: - Date/Time Utilities

func isLeapYear(_ y: Int) -> Bool {
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

func daysInMonth(_ y: Int, _ m: Int) -> Int {
    switch m {
    case 1,3,5,7,8,10,12: return 31
    case 4,6,9,11: return 30
    case 2: return isLeapYear(y) ? 29 : 28
    default: return 0
    }
}

func civilFromDays(_ z0: Int64) -> (Int, Int, Int) {
    let z = z0 + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2) / 153
    let d = doy - (153*mp + 2) / 5 + 1
    let m = mp < 10 ? mp + 3 : mp - 9
    return (Int(y + (m <= 2 ? 1 : 0)), Int(m), Int(d))
}

func daysFromCivil(_ y0: Int, _ m0: Int, _ d0: Int) -> Int64 {
    var y = Int64(y0)
    let m = Int64(m0)
    let d = Int64(d0)
    y -= m <= 2 ? 1 : 0
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let mp = m + (m > 2 ? -3 : 9)
    let doy = (153*mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe/4 - yoe/100 + doy
    return era * 146097 + doe - 719468
}

func dayOfWeek(_ y: Int, _ m: Int, _ d: Int) -> Int {
    let days = daysFromCivil(y, m, d)
    return Int(((days % 7) + 4 + 7) % 7)
}

func yearFromUnix(_ t: Int64) -> Int {
    let days: Int64 = t >= 0 ? t / 86400 : (t - 86399) / 86400
    let (y, _, _) = civilFromDays(days)
    return y
}

func formatOffset(_ off: Int) -> String {
    let sign = off >= 0 ? "+" : "-"
    let a = abs(off)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalDateTime(_ t: Int64, _ offset: Int) -> String {
    let lt = t + Int64(offset)
    let days: Int64 = lt >= 0 ? lt / 86400 : (lt - 86399) / 86400
    let rem = lt - days * 86400
    let (y, m, d) = civilFromDays(days)
    let h = Int(rem) / 3600
    let mi = (Int(rem) % 3600) / 60
    let s = Int(rem) % 60
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s)
}

func parseWallClock(_ s: Substring) -> Int64 {
    let parts = s.split(separator: "T")
    let dp = parts[0].split(separator: "-")
    let tp = parts[1].split(separator: ":")
    let y = Int(dp[0])!
    let m = Int(dp[1])!
    let d = Int(dp[2])!
    let h = Int(tp[0])!
    let mi = Int(tp[1])!
    let s = Int(tp[2])!
    return daysFromCivil(y, m, d) * 86400 + Int64(h)*3600 + Int64(mi)*60 + Int64(s)
}

// MARK: - TZif Structures

struct LocalTimeType {
    let gmtoff: Int32
    let isdst: Bool
    let abbr: String
}

struct Transition {
    let time: Int64
    let typeIdx: Int
}

struct PosixTZ {
    let stdName: String
    let stdOffset: Int
    let dstName: String?
    let dstOffset: Int
    let hasDst: Bool
    let startMonth: Int
    let startWeek: Int
    let startDay: Int
    let startTime: Int
    let endMonth: Int
    let endWeek: Int
    let endDay: Int
    let endTime: Int
    let hasRules: Bool
}

struct TZifData {
    var transitions: [Transition] = []
    var types: [LocalTimeType] = []
    var posixTZ: PosixTZ? = nil
}

// MARK: - Big-Endian Readers

func readBE32(_ b: [UInt8], _ o: Int) -> Int32 {
    return Int32(bitPattern: UInt32(b[o]) << 24 | UInt32(b[o+1]) << 16 | UInt32(b[o+2]) << 8 | UInt32(b[o+3]))
}

func readBE64(_ b: [UInt8], _ o: Int) -> Int64 {
    var v: UInt64 = 0
    for i in 0..<8 { v = (v << 8) | UInt64(b[o+i]) }
    return Int64(bitPattern: v)
}

// MARK: - TZif Parsing

func parseTZif(_ path: String) -> TZifData {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)
    var result = TZifData()

    // First header: 44 bytes
    let isutcnt1 = Int(readBE32(bytes, 20))
    let isstdcnt1 = Int(readBE32(bytes, 24))
    let leapcnt1 = Int(readBE32(bytes, 28))
    let timecnt1 = Int(readBE32(bytes, 32))
    let typecnt1 = Int(readBE32(bytes, 36))
    let charcnt1 = Int(readBE32(bytes, 40))
    _ = isutcnt1; _ = isstdcnt1; _ = leapcnt1; _ = typecnt1; _ = charcnt1

    let block1Size = timecnt1*4 + timecnt1 + typecnt1*6 + charcnt1 + leapcnt1*8 + isstdcnt1 + isutcnt1
    var off = 44 + block1Size

    // Second header: 44 bytes
    let isutcnt2 = Int(readBE32(bytes, off + 20))
    let isstdcnt2 = Int(readBE32(bytes, off + 24))
    let leapcnt2 = Int(readBE32(bytes, off + 28))
    let timecnt2 = Int(readBE32(bytes, off + 32))
    let typecnt2 = Int(readBE32(bytes, off + 36))
    let charcnt2 = Int(readBE32(bytes, off + 40))
    off += 44

    // Transition times (64-bit)
    var transTimes = [Int64]()
    for _ in 0..<timecnt2 {
        transTimes.append(readBE64(bytes, off))
        off += 8
    }

    // Type indices
    var transTypeIdx = [Int]()
    for _ in 0..<timecnt2 {
        transTypeIdx.append(Int(bytes[off]))
        off += 1
    }

    for i in 0..<timecnt2 {
        result.transitions.append(Transition(time: transTimes[i], typeIdx: transTypeIdx[i]))
    }

    // Local time type records
    let typesOff = off
    off += typecnt2 * 6

    // Abbreviation chars
    let abbrStart = off
    off += charcnt2

    // Leap seconds (skip)
    off += leapcnt2 * 12
    // isstd/isut (skip)
    off += isstdcnt2
    off += isutcnt2

    // Parse types
    for i in 0..<typecnt2 {
        let ro = typesOff + i*6
        let gmtoff = readBE32(bytes, ro)
        let isdst = bytes[ro+4] != 0
        let abbrIdx = Int(bytes[ro+5])
        var abbr = ""
        var j = abbrStart + abbrIdx
        while j < bytes.count && bytes[j] != 0 {
            abbr.append(Character(UnicodeScalar(bytes[j])))
            j += 1
        }
        result.types.append(LocalTimeType(gmtoff: gmtoff, isdst: isdst, abbr: abbr))
    }

    // Footer: \n POSIX_TZ \n
    if off < bytes.count && bytes[off] == 0x0A {
        off += 1
        var tzStr = ""
        while off < bytes.count && bytes[off] != 0x0A {
            tzStr.append(Character(UnicodeScalar(bytes[off])))
            off += 1
        }
        if !tzStr.isEmpty {
            result.posixTZ = parsePosixTZ(tzStr)
        }
    }

    return result
}

// MARK: - POSIX TZ Parsing

func parsePosixTZ(_ s: String) -> PosixTZ? {
    let chars = Array(s)
    var pos = 0

    func peek() -> Character? { pos < chars.count ? chars[pos] : nil }
    func consume() -> Character? { guard pos < chars.count else { return nil }; let c = chars[pos]; pos += 1; return c }

    func parseName() -> String? {
        guard let c = peek() else { return nil }
        if c == "<" {
            pos += 1
            var name = ""
            while let ch = consume(), ch != ">" { name.append(ch) }
            return name
        } else if c.isLetter {
            var name = ""
            while let ch = peek(), ch.isLetter { name.append(consume()!) }
            return name.count >= 3 ? name : nil
        }
        return nil
    }

    func parseOffsetVal() -> Int? {
        var sign = 1
        if let c = peek(), c == "+" { pos += 1 }
        else if let c = peek(), c == "-" { pos += 1; sign = -1 }
        var hours = 0; var nd = 0
        while let c = peek(), c.isNumber, nd < 3 { hours = hours*10 + Int(String(consume()!))!; nd += 1 }
        if nd == 0 { return nil }
        var mins = 0; var secs = 0
        if peek() == ":" {
            pos += 1; nd = 0
            while let c = peek(), c.isNumber, nd < 2 { mins = mins*10 + Int(String(consume()!))!; nd += 1 }
        }
        if peek() == ":" {
            pos += 1; nd = 0
            while let c = peek(), c.isNumber, nd < 2 { secs = secs*10 + Int(String(consume()!))!; nd += 1 }
        }
        return sign * (hours*3600 + mins*60 + secs)
    }

    func parseNum() -> Int? {
        var n = 0; var nd = 0
        while let c = peek(), c.isNumber { n = n*10 + Int(String(consume()!))!; nd += 1 }
        return nd > 0 ? n : nil
    }

    func parseMWD() -> (Int, Int, Int)? {
        guard let c = peek(), c == "M" else { return nil }
        pos += 1
        guard let m = parseNum() else { return nil }
        guard peek() == "." else { return nil }
        pos += 1
        guard let w = parseNum() else { return nil }
        guard peek() == "." else { return nil }
        pos += 1
        guard let d = parseNum() else { return nil }
        return (m, w, d)
    }

    func parseTimeVal() -> Int {
        var sign = 1
        if let c = peek(), c == "+" { pos += 1 }
        else if let c = peek(), c == "-" { pos += 1; sign = -1 }
        var hours = 0
        while let c = peek(), c.isNumber { hours = hours*10 + Int(String(consume()!))! }
        var mins = 0; var secs = 0
        if peek() == ":" {
            pos += 1
            while let c = peek(), c.isNumber { mins = mins*10 + Int(String(consume()!))! }
        }
        if peek() == ":" {
            pos += 1
            while let c = peek(), c.isNumber { secs = secs*10 + Int(String(consume()!))! }
        }
        return sign * (hours*3600 + mins*60 + secs)
    }

    guard let stdName = parseName() else { return nil }
    guard let stdOffset = parseOffsetVal() else { return nil }

    var dstName: String? = nil
    var dstOffset = stdOffset - 3600
    var hasDst = false
    var sMonth = 3, sWeek = 2, sDay = 0, sTime = 7200
    var eMonth = 11, eWeek = 1, eDay = 0, eTime = 7200
    var hasRules = false

    if pos < chars.count {
        if let dn = parseName() {
            dstName = dn
            hasDst = true
            if pos < chars.count {
                let c = chars[pos]
                if c == "+" || c == "-" || c.isNumber {
                    if let doff = parseOffsetVal() { dstOffset = doff }
                }
            }
            if peek() == "," {
                pos += 1
                if let (m, w, d) = parseMWD() { sMonth = m; sWeek = w; sDay = d }
                if peek() == "/" { pos += 1; sTime = parseTimeVal() }
                if peek() == "," {
                    pos += 1
                    if let (m, w, d) = parseMWD() { eMonth = m; eWeek = w; eDay = d }
                    if peek() == "/" { pos += 1; eTime = parseTimeVal() }
                }
                hasRules = true
            }
        }
    }

    return PosixTZ(stdName: stdName, stdOffset: stdOffset, dstName: dstName, dstOffset: dstOffset,
                   hasDst: hasDst, startMonth: sMonth, startWeek: sWeek, startDay: sDay, startTime: sTime,
                   endMonth: eMonth, endWeek: eWeek, endDay: eDay, endTime: eTime, hasRules: hasRules)
}

// MARK: - Footer Transition Computation

func computeFooterTrans(year: Int, month: Int, week: Int, day: Int, time: Int, posixOff: Int) -> Int64 {
    let dim = daysInMonth(year, month)
    let dow1 = dayOfWeek(year, month, 1)
    let firstDay = 1 + ((day - dow1 + 7) % 7)
    var targetDay: Int
    if week == 5 {
        targetDay = firstDay + ((dim - firstDay) / 7) * 7
    } else {
        targetDay = firstDay + (week - 1) * 7
    }
    let baseSec = daysFromCivil(year, month, targetDay) * 86400
    return baseSec + Int64(time) + Int64(posixOff)
}

func footerTypeAt(t: Int64, posix: PosixTZ) -> (utcOff: Int, abbr: String) {
    let stdUtcOff = -posix.stdOffset
    let dstUtcOff = -posix.dstOffset
    if !posix.hasDst {
        return (stdUtcOff, posix.stdName)
    }
    let y = yearFromUnix(t)
    let startT = computeFooterTrans(year: y, month: posix.startMonth, week: posix.startWeek, day: posix.startDay, time: posix.startTime, posixOff: posix.stdOffset)
    let endT = computeFooterTrans(year: y, month: posix.endMonth, week: posix.endWeek, day: posix.endDay, time: posix.endTime, posixOff: posix.dstOffset)
    if startT < endT {
        if t >= startT && t < endT { return (dstUtcOff, posix.dstName!) }
        else { return (stdUtcOff, posix.stdName) }
    } else {
        let ys = daysFromCivil(y, 1, 1) * 86400
        let ye = daysFromCivil(y+1, 1, 1) * 86400
        if (t >= startT && t < ye) || (t >= ys && t < endT) { return (dstUtcOff, posix.dstName!) }
        else { return (stdUtcOff, posix.stdName) }
    }
}

// MARK: - Type Determination

func typeAtTime(tzif: TZifData, t: Int64) -> (utcOff: Int, abbr: String) {
    let n = tzif.transitions.count
    if n == 0 {
        if let p = tzif.posixTZ { return footerTypeAt(t: t, posix: p) }
        if !tzif.types.isEmpty { return (Int(tzif.types[0].gmtoff), tzif.types[0].abbr) }
        return (0, "")
    }
    let firstT = tzif.transitions[0].time
    let lastT = tzif.transitions[n-1].time
    if t < firstT {
        return (Int(tzif.types[0].gmtoff), tzif.types[0].abbr)
    }
    if t > lastT {
        if let p = tzif.posixTZ { return footerTypeAt(t: t, posix: p) }
        return (Int(tzif.types[tzif.transitions[n-1].typeIdx].gmtoff), tzif.types[tzif.transitions[n-1].typeIdx].abbr)
    }
    // t is in [firstT, lastT], binary search for latest transition <= t
    var lo = 0, hi = n - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tzif.transitions[mid].time <= t { lo = mid }
        else { hi = mid - 1 }
    }
    let ti = tzif.transitions[lo].typeIdx
    return (Int(tzif.types[ti].gmtoff), tzif.types[ti].abbr)
}

// MARK: - Query Processing

func processUTC(tzif: TZifData, t: Int64) -> String {
    let (off, abbr) = typeAtTime(tzif: tzif, t: t)
    let localStr = formatLocalDateTime(t, off)
    let offStr = formatOffset(off)
    return "\(localStr)\(offStr) \(abbr)"
}

func processLocal(tzif: TZifData, wallClockStr: Substring) -> String {
    let wSec = parseWallClock(wallClockStr)
    var results: [(t: Int64, off: Int, abbr: String)] = []

    let n = tzif.transitions.count
    let firstT: Int64 = n > 0 ? tzif.transitions[0].time : Int64.min
    let lastT: Int64 = n > 0 ? tzif.transitions[n-1].time : Int64.min

    if n == 0 {
        // No transitions: use footer or type 0
        if let p = tzif.posixTZ {
            let stdOff = -p.stdOffset
            let t1 = wSec - Int64(stdOff)
            let (o, _) = typeAtTime(tzif: tzif, t: t1)
            if o == stdOff { results.append((t1, stdOff, p.stdName)) }
            if p.hasDst {
                let dstOff = -p.dstOffset
                let t2 = wSec - Int64(dstOff)
                let (o2, _) = typeAtTime(tzif: tzif, t: t2)
                if o2 == dstOff && t2 != t1 { results.append((t2, dstOff, p.dstName!)) }
            }
        } else if !tzif.types.isEmpty {
            let off0 = Int(tzif.types[0].gmtoff)
            let tc = wSec - Int64(off0)
            results.append((tc, off0, tzif.types[0].abbr))
        }
    } else {
        // Segment (-inf, firstT): type 0
        let off0 = Int(tzif.types[0].gmtoff)
        let tc0 = wSec - Int64(off0)
        if tc0 < firstT {
            results.append((tc0, off0, tzif.types[0].abbr))
        }

        // Segments [Ti, Ti+1) for i in 0..n-2
        for i in 0..<(n-1) {
            let ti = tzif.transitions[i].typeIdx
            let off = Int(tzif.types[ti].gmtoff)
            let tc = wSec - Int64(off)
            if tc >= tzif.transitions[i].time && tc < tzif.transitions[i+1].time {
                results.append((tc, off, tzif.types[ti].abbr))
            }
        }

        // Single point [lastT, lastT]: type of last transition
        let lastTi = tzif.transitions[n-1].typeIdx
        let lastOff = Int(tzif.types[lastTi].gmtoff)
        let tcLast = wSec - Int64(lastOff)
        if tcLast == lastT {
            results.append((tcLast, lastOff, tzif.types[lastTi].abbr))
        }

        // Footer: (lastT, +inf)
        if let p = tzif.posixTZ {
            let stdOff = -p.stdOffset
            let tStd = wSec - Int64(stdOff)
            if tStd > lastT {
                let (o, _) = typeAtTime(tzif: tzif, t: tStd)
                if o == stdOff {
                    results.append((tStd, stdOff, p.stdName))
                }
            }
            if p.hasDst {
                let dstOff = -p.dstOffset
                let tDst = wSec - Int64(dstOff)
                if tDst > lastT {
                    let (o, _) = typeAtTime(tzif: tzif, t: tDst)
                    if o == dstOff {
                        if !results.contains(where: { $0.t == tDst }) {
                            results.append((tDst, dstOff, p.dstName!))
                        }
                    }
                }
            }
        }
    }

    results.sort { $0.t < $1.t }

    if results.count == 1 {
        let r = results[0]
        return " \(r.t) \(formatOffset(r.off)) \(r.abbr)"
    } else if results.count >= 2 {
        let r1 = results[0], r2 = results[1]
        return " \(r1.t) \(formatOffset(r1.off)) \(r1.abbr) | \(r2.t) \(formatOffset(r2.off)) \(r2.abbr)"
    }

    // GAP: find the forward transition that skipped this wall-clock time
    var gapT: Int64 = 0
    var gapOff: Int = 0
    var found = false

    // Check table transitions
    for i in 0..<n {
        let Ti = tzif.transitions[i].time
        let newOff = Int(tzif.types[tzif.transitions[i].typeIdx].gmtoff)
        let oldOff: Int
        if i == 0 { oldOff = Int(tzif.types[0].gmtoff) }
        else { oldOff = Int(tzif.types[tzif.transitions[i-1].typeIdx].gmtoff) }
        if newOff > oldOff {
            if Ti + Int64(oldOff) <= wSec && wSec < Ti + Int64(newOff) {
                gapT = wSec - Int64(oldOff)
                gapOff = oldOff
                found = true
                break
            }
        }
    }

    // Check footer DST start transitions
    if !found, let p = tzif.posixTZ, p.hasDst {
        let stdOff = -p.stdOffset
        let dstOff = -p.dstOffset
        if dstOff > stdOff {
            let approxY = yearFromUnix(wSec)
            for y in (approxY-1)...(approxY+1) {
                let startT = computeFooterTrans(year: y, month: p.startMonth, week: p.startWeek, day: p.startDay, time: p.startTime, posixOff: p.stdOffset)
                if startT > lastT {
                    if startT + Int64(stdOff) <= wSec && wSec < startT + Int64(dstOff) {
                        gapT = wSec - Int64(stdOff)
                        gapOff = stdOff
                        found = true
                        break
                    }
                }
            }
        }
    }

    if found {
        let (localOff, localAbbr) = typeAtTime(tzif: tzif, t: gapT)
        let localStr = formatLocalDateTime(gapT, localOff)
        let offStr = formatOffset(localOff)
        return " GAP \(gapT) \(localStr)\(offStr) \(localAbbr)"
    }

    // Fallback (shouldn't happen)
    return " GAP \(wSec) \(formatLocalDateTime(wSec, 0))+00:00 "
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let queriesPath = dir + "/queries.txt"
let queriesContent = try! String(contentsOfFile: queriesPath, encoding: .utf8)
let lines = queriesContent.components(separatedBy: "\n")

var tzifCache: [String: TZifData] = [:]

for line in lines {
    if line.trimmingCharacters(in: .whitespaces).isEmpty { continue }
    let fields = line.split(separator: " ", omittingEmptySubsequences: false)
    guard fields.count >= 3 else { continue }
    let qType = String(fields[0])
    let fileName = String(fields[1])

    if tzifCache[fileName] == nil {
        let path = dir + "/" + fileName
        tzifCache[fileName] = parseTZif(path)
    }
    let tzif = tzifCache[fileName]!

    if qType == "UTC" {
        let t = Int64(String(fields[2]))!
        let result = processUTC(tzif: tzif, t: t)
        print("\(line) -> \(result)")
    } else if qType == "LOCAL" {
        let wallClock = fields[2]
        let result = processLocal(tzif: tzif, wallClockStr: wallClock)
        print("\(line) ->\(result)")
    }
}

import * as fs from 'fs';
import * as path from 'path';

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
  abbr: string;
}

interface Transition {
  time: number;
  typeIndex: number;
}

interface PosixRule {
  month: number;
  week: number;
  day: number;
  time: number;
}

interface PosixTZ {
  stdAbbr: string;
  stdOffset: number;
  dstAbbr?: string;
  dstOffset?: number;
  startRule?: PosixRule;
  endRule?: PosixRule;
}

interface TZData {
  transitions: Transition[];
  types: TypeRecord[];
  posixTZ: PosixTZ | null;
}

function parseTZif(filePath: string): TZData {
  const buf = fs.readFileSync(filePath);

  const isutcnt1 = buf.readInt32BE(20);
  const isstdcnt1 = buf.readInt32BE(24);
  const leapcnt1 = buf.readInt32BE(28);
  const timecnt1 = buf.readInt32BE(32);
  const typecnt1 = buf.readInt32BE(36);
  const charcnt1 = buf.readInt32BE(40);

  const block1Size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
  const off2 = 44 + block1Size;

  const isutcnt2 = buf.readInt32BE(off2 + 20);
  const isstdcnt2 = buf.readInt32BE(off2 + 24);
  const leapcnt2 = buf.readInt32BE(off2 + 28);
  const timecnt2 = buf.readInt32BE(off2 + 32);
  const typecnt2 = buf.readInt32BE(off2 + 36);
  const charcnt2 = buf.readInt32BE(off2 + 40);

  let pos = off2 + 44;

  const transitions: Transition[] = [];
  for (let i = 0; i < timecnt2; i++) {
    const t = Number(buf.readBigInt64BE(pos));
    pos += 8;
    transitions.push({ time: t, typeIndex: 0 });
  }

  for (let i = 0; i < timecnt2; i++) {
    transitions[i].typeIndex = buf[pos];
    pos += 1;
  }

  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buf.readInt32BE(pos);
    const isdst = buf[pos + 4];
    const abbrIndex = buf[pos + 5];
    pos += 6;
    types.push({ gmtoff, isdst, abbrIndex, abbr: '' });
  }

  const abbrStart = pos;
  pos += charcnt2;

  for (const t of types) {
    let end = t.abbrIndex;
    while (end < charcnt2 && buf[abbrStart + end] !== 0) end++;
    t.abbr = buf.slice(abbrStart + t.abbrIndex, abbrStart + end).toString('ascii');
  }

  pos += leapcnt2 * 12;
  pos += isstdcnt2;
  pos += isutcnt2;

  pos++; // skip '\n'
  let endPos = pos;
  while (endPos < buf.length && buf[endPos] !== 0x0a) endPos++;
  const posixStr = buf.slice(pos, endPos).toString('ascii');

  const posixTZ = posixStr.length > 0 ? parsePosixTZ(posixStr) : null;

  return { transitions, types, posixTZ };
}

function parsePosixTZ(s: string): PosixTZ | null {
  let pos = 0;

  function parseName(): string {
    if (pos < s.length && s[pos] === '<') {
      const end = s.indexOf('>', pos + 1);
      const name = s.slice(pos + 1, end);
      pos = end + 1;
      return name;
    } else {
      const start = pos;
      while (pos < s.length && /[a-zA-Z]/.test(s[pos])) pos++;
      return s.slice(start, pos);
    }
  }

  function parseOffset(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }

    let start = pos;
    while (pos < s.length && /\d/.test(s[pos])) pos++;
    const hours = parseInt(s.slice(start, pos));

    let minutes = 0, seconds = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      start = pos;
      while (pos < s.length && /\d/.test(s[pos])) pos++;
      minutes = parseInt(s.slice(start, pos));

      if (pos < s.length && s[pos] === ':') {
        pos++;
        start = pos;
        while (pos < s.length && /\d/.test(s[pos])) pos++;
        seconds = parseInt(s.slice(start, pos));
      }
    }

    return sign * (hours * 3600 + minutes * 60 + seconds);
  }

  function parseRule(): PosixRule | null {
    if (pos >= s.length || s[pos] !== 'M') return null;
    pos++;

    let start = pos;
    while (pos < s.length && /\d/.test(s[pos])) pos++;
    const month = parseInt(s.slice(start, pos));

    if (pos < s.length && s[pos] === '.') pos++;
    start = pos;
    while (pos < s.length && /\d/.test(s[pos])) pos++;
    const week = parseInt(s.slice(start, pos));

    if (pos < s.length && s[pos] === '.') pos++;
    start = pos;
    while (pos < s.length && /\d/.test(s[pos])) pos++;
    const day = parseInt(s.slice(start, pos));

    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') {
      pos++;
      if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
        time = parseOffset();
      }
    }

    return { month, week, day, time };
  }

  const stdAbbr = parseName();
  if (!stdAbbr) return null;
  const stdOffset = parseOffset();

  let dstAbbr: string | undefined;
  let dstOffset: number | undefined;

  if (pos < s.length && (s[pos] === '<' || /[a-zA-Z]/.test(s[pos]))) {
    dstAbbr = parseName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      dstOffset = parseOffset();
    } else {
      dstOffset = stdOffset - 3600;
    }
  }

  let startRule: PosixRule | undefined;
  let endRule: PosixRule | undefined;

  if (pos < s.length && s[pos] === ',') {
    pos++;
    startRule = parseRule() ?? undefined;
    if (pos < s.length && s[pos] === ',') {
      pos++;
      endRule = parseRule() ?? undefined;
    }
  }

  return { stdAbbr, stdOffset, dstAbbr, dstOffset, startRule, endRule };
}

function civilToDays(year: number, month: number, day: number): number {
  let y = year;
  if (month <= 2) y--;
  const era = Math.floor((y >= 0 ? y : y - 399) / 400);
  const yoe = y - era * 400;
  const mp = (month + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + day - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function daysToCivil(days: number): { year: number; month: number; day: number } {
  const z = days + 719468;
  const era = Math.floor((z >= 0 ? z : z - 146096) / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp < 10 ? mp + 3 : mp - 9;
  return { year: m <= 2 ? y + 1 : y, month: m, day: d };
}

function dayOfWeek(year: number, month: number, day: number): number {
  const d = civilToDays(year, month, day);
  return ((d % 7) + 4 + 7) % 7;
}

function daysInMonth(year: number, month: number): number {
  if (month === 2) {
    if (year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)) return 29;
    return 28;
  }
  if (month <= 7) return month % 2 === 1 ? 31 : 30;
  return month % 2 === 0 ? 31 : 30;
}

function findNthDayOfWeek(year: number, month: number, week: number, dow: number): { year: number; month: number; day: number } {
  const firstDow = dayOfWeek(year, month, 1);
  let firstDay = 1 + ((dow - firstDow + 7) % 7);

  if (week <= 4) {
    return { year, month, day: firstDay + (week - 1) * 7 };
  } else {
    const dim = daysInMonth(year, month);
    let lastDay = firstDay + 4 * 7;
    if (lastDay > dim) lastDay -= 7;
    return { year, month, day: lastDay };
  }
}

function ruleToUTC(rule: PosixRule, year: number, localOffset: number): number {
  const date = findNthDayOfWeek(year, rule.month, rule.week, rule.day);
  const localSecs = civilToDays(date.year, date.month, date.day) * 86400 + rule.time;
  return localSecs - localOffset;
}

function getPosixOffset(posixTZ: PosixTZ, t: number): { offset: number; abbr: string; isdst: number } {
  const stdUTCOffset = -posixTZ.stdOffset;

  if (!posixTZ.dstAbbr || !posixTZ.startRule || !posixTZ.endRule) {
    return { offset: stdUTCOffset, abbr: posixTZ.stdAbbr, isdst: 0 };
  }

  const dstUTCOffset = -posixTZ.dstOffset!;

  const days = Math.floor(t / 86400);
  const civil = daysToCivil(days);
  const year = civil.year;

  const utcStart = ruleToUTC(posixTZ.startRule, year, stdUTCOffset);
  const utcEnd = ruleToUTC(posixTZ.endRule, year, dstUTCOffset);

  let dstInEffect: boolean;
  if (utcStart < utcEnd) {
    dstInEffect = t >= utcStart && t < utcEnd;
  } else {
    dstInEffect = t >= utcStart || t < utcEnd;
  }

  if (dstInEffect) {
    return { offset: dstUTCOffset, abbr: posixTZ.dstAbbr, isdst: 1 };
  } else {
    return { offset: stdUTCOffset, abbr: posixTZ.stdAbbr, isdst: 0 };
  }
}

function getUTCOffset(data: TZData, t: number): { offset: number; abbr: string; isdst: number } {
  const { transitions, types, posixTZ } = data;

  if (transitions.length === 0) {
    if (posixTZ) return getPosixOffset(posixTZ, t);
    if (types.length > 0) return { offset: types[0].gmtoff, abbr: types[0].abbr, isdst: types[0].isdst };
    return { offset: 0, abbr: 'UTC', isdst: 0 };
  }

  if (t < transitions[0].time) {
    const type = types[0];
    return { offset: type.gmtoff, abbr: type.abbr, isdst: type.isdst };
  }

  if (t > transitions[transitions.length - 1].time) {
    if (posixTZ) return getPosixOffset(posixTZ, t);
    const type = types[transitions[transitions.length - 1].typeIndex];
    return { offset: type.gmtoff, abbr: type.abbr, isdst: type.isdst };
  }

  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (transitions[mid].time <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  const type = types[transitions[lo].typeIndex];
  return { offset: type.gmtoff, abbr: type.abbr, isdst: type.isdst };
}

function pad2(n: number): string {
  return n < 10 ? '0' + n : '' + n;
}

function pad4(n: number): string {
  if (n < 10) return '000' + n;
  if (n < 100) return '00' + n;
  if (n < 1000) return '0' + n;
  return '' + n;
}

function formatOffset(offset: number): string {
  const sign = offset >= 0 ? '+' : '-';
  const abs = Math.abs(offset);
  const hours = Math.floor(abs / 3600);
  const minutes = Math.floor((abs % 3600) / 60);
  const seconds = abs % 60;

  let result = `${sign}${pad2(hours)}:${pad2(minutes)}`;
  if (seconds !== 0) {
    result += `:${pad2(seconds)}`;
  }
  return result;
}

function formatLocal(t: number, offset: number): string {
  const localSecs = t + offset;
  const days = Math.floor(localSecs / 86400);
  const remSecs = localSecs - days * 86400;

  const civil = daysToCivil(days);
  const hours = Math.floor(remSecs / 3600);
  const minutes = Math.floor((remSecs % 3600) / 60);
  const seconds = remSecs % 60;

  return `${pad4(civil.year)}-${pad2(civil.month)}-${pad2(civil.day)}T${pad2(hours)}:${pad2(minutes)}:${pad2(seconds)}${formatOffset(offset)}`;
}

function parseWallClock(s: string): number {
  const [datePart, timePart] = s.split('T');
  const [yearStr, monthStr, dayStr] = datePart.split('-');
  const [hourStr, minStr, secStr] = timePart.split(':');
  const year = parseInt(yearStr);
  const month = parseInt(monthStr);
  const day = parseInt(dayStr);
  const hour = parseInt(hourStr);
  const min = parseInt(minStr);
  const sec = parseInt(secStr);

  return civilToDays(year, month, day) * 86400 + hour * 3600 + min * 60 + sec;
}

function handleLocal(data: TZData, wallStr: string): string {
  const wallSecs = parseWallClock(wallStr);

  const offsetSet = new Map<number, { abbr: string; isdst: number }>();
  for (const type of data.types) {
    if (!offsetSet.has(type.gmtoff)) {
      offsetSet.set(type.gmtoff, { abbr: type.abbr, isdst: type.isdst });
    }
  }
  if (data.posixTZ) {
    const stdOff = -data.posixTZ.stdOffset;
    if (!offsetSet.has(stdOff)) {
      offsetSet.set(stdOff, { abbr: data.posixTZ.stdAbbr, isdst: 0 });
    }
    if (data.posixTZ.dstAbbr) {
      const dstOff = -data.posixTZ.dstOffset!;
      if (!offsetSet.has(dstOff)) {
        offsetSet.set(dstOff, { abbr: data.posixTZ.dstAbbr, isdst: 1 });
      }
    }
  }

  const results: { t: number; offset: number; abbr: string }[] = [];
  for (const [offset] of offsetSet) {
    const t = wallSecs - offset;
    const actual = getUTCOffset(data, t);
    if (actual.offset === offset) {
      results.push({ t, offset, abbr: actual.abbr });
    }
  }

  const seen = new Set<number>();
  const uniqueResults: typeof results = [];
  for (const r of results) {
    if (!seen.has(r.t)) {
      seen.add(r.t);
      uniqueResults.push(r);
    }
  }

  uniqueResults.sort((a, b) => a.t - b.t);

  if (uniqueResults.length === 1) {
    return `${uniqueResults[0].t} ${formatOffset(uniqueResults[0].offset)} ${uniqueResults[0].abbr}`;
  } else if (uniqueResults.length === 2) {
    return `${uniqueResults[0].t} ${formatOffset(uniqueResults[0].offset)} ${uniqueResults[0].abbr} | ${uniqueResults[1].t} ${formatOffset(uniqueResults[1].offset)} ${uniqueResults[1].abbr}`;
  } else {
    return handleGap(data, wallSecs);
  }
}

function handleGap(data: TZData, wallSecs: number): string {
  const { transitions, types, posixTZ } = data;

  let offsetBefore: number | null = null;

  for (let i = 0; i < transitions.length; i++) {
    const T = transitions[i].time;
    const newOffset = types[transitions[i].typeIndex].gmtoff;
    let oldOffset: number;
    if (i === 0) {
      oldOffset = types[0].gmtoff;
    } else {
      oldOffset = types[transitions[i - 1].typeIndex].gmtoff;
    }

    if (newOffset > oldOffset) {
      if (wallSecs >= T + oldOffset && wallSecs < T + newOffset) {
        offsetBefore = oldOffset;
        break;
      }
    }
  }

  if (offsetBefore === null && posixTZ && posixTZ.dstAbbr && posixTZ.startRule && posixTZ.endRule) {
    const stdUTCOffset = -posixTZ.stdOffset;
    const dstUTCOffset = -posixTZ.dstOffset!;

    const approxYear = Math.floor(wallSecs / (365.25 * 86400)) + 1970;

    for (let y = approxYear - 2; y <= approxYear + 2; y++) {
      if (dstUTCOffset > stdUTCOffset) {
        const utcStart = ruleToUTC(posixTZ.startRule, y, stdUTCOffset);
        if (wallSecs >= utcStart + stdUTCOffset && wallSecs < utcStart + dstUTCOffset) {
          offsetBefore = stdUTCOffset;
          break;
        }
      }

      if (stdUTCOffset > dstUTCOffset) {
        const utcEnd = ruleToUTC(posixTZ.endRule, y, dstUTCOffset);
        if (wallSecs >= utcEnd + dstUTCOffset && wallSecs < utcEnd + stdUTCOffset) {
          offsetBefore = dstUTCOffset;
          break;
        }
      }
    }
  }

  if (offsetBefore !== null) {
    const t = wallSecs - offsetBefore;
    const local = getUTCOffset(data, t);
    const localStr = formatLocal(t, local.offset);
    return `GAP ${t} ${localStr} ${local.abbr}`;
  }

  return `GAP 0 1970-01-01T00:00:00+00:00 UTC`;
}

function main() {
  const dir = process.argv[2];
  const queriesPath = path.join(dir, 'queries.txt');
  const content = fs.readFileSync(queriesPath, 'utf-8');
  const lines = content.split('\n');

  const tzCache = new Map<string, TZData>();

  function getTZData(fileName: string): TZData {
    if (!tzCache.has(fileName)) {
      tzCache.set(fileName, parseTZif(path.join(dir, fileName)));
    }
    return tzCache.get(fileName)!;
  }

  const output: string[] = [];

  for (const rawLine of lines) {
    const line = rawLine.replace(/\r$/, '');
    if (line.trim() === '') continue;

    const parts = line.split(' ');
    const queryType = parts[0];
    const fileName = parts[1];

    if (queryType === 'UTC') {
      const t = parseInt(parts[2]);
      const data = getTZData(fileName);
      const { offset, abbr } = getUTCOffset(data, t);
      const localStr = formatLocal(t, offset);
      output.push(`${line} -> ${localStr} ${abbr}`);
    } else if (queryType === 'LOCAL') {
      const wallStr = parts[2];
      const data = getTZData(fileName);
      const result = handleLocal(data, wallStr);
      output.push(`${line} -> ${result}`);
    }
  }

  process.stdout.write(output.join('\n') + '\n');
}

main();

import * as net from 'net';
import * as crypto from 'crypto';

class SocketReader {
  private buffer: Buffer = Buffer.alloc(0);
  private dataResolve: (() => void) | null = null;
  private closed = false;

  constructor(private socket: net.Socket) {
    socket.on('data', (chunk: Buffer) => {
      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.wake();
    });
    socket.on('end', () => { this.closed = true; this.wake(); });
    socket.on('close', () => { this.closed = true; this.wake(); });
    socket.on('error', () => { this.closed = true; this.wake(); });
  }

  private wake(): void {
    if (this.dataResolve) {
      const r = this.dataResolve;
      this.dataResolve = null;
      r();
    }
  }

  async readExact(n: number): Promise<Buffer> {
    while (this.buffer.length < n) {
      if (this.closed) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.dataResolve = resolve; });
    }
    const result = this.buffer.subarray(0, n);
    this.buffer = this.buffer.subarray(n);
    return result;
  }

  async readUntil(delim: Buffer): Promise<Buffer> {
    while (true) {
      const idx = this.buffer.indexOf(delim);
      if (idx !== -1) {
        const result = this.buffer.subarray(0, idx + delim.length);
        this.buffer = this.buffer.subarray(idx + delim.length);
        return result;
      }
      if (this.closed) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.dataResolve = resolve; });
    }
  }
}

function sendFrame(socket: net.Socket, opcode: number, payload: Buffer): void {
  let maskKey: Buffer;
  do {
    maskKey = crypto.randomBytes(4);
  } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);

  const parts: Buffer[] = [];
  const header = Buffer.alloc(2);
  header[0] = 0x80 | (opcode & 0x0F);
  header[1] = 0x80;

  if (payload.length <= 125) {
    header[1] |= payload.length;
    parts.push(header);
  } else if (payload.length <= 65535) {
    header[1] |= 126;
    parts.push(header);
    const ext = Buffer.alloc(2);
    ext.writeUInt16BE(payload.length);
    parts.push(ext);
  } else {
    header[1] |= 127;
    parts.push(header);
    const ext = Buffer.alloc(8);
    ext.writeBigUInt64BE(BigInt(payload.length));
    parts.push(ext);
  }

  parts.push(maskKey);

  const masked = Buffer.alloc(payload.length);
  for (let i = 0; i < payload.length; i++) {
    masked[i] = payload[i] ^ maskKey[i & 3];
  }
  parts.push(masked);

  socket.write(Buffer.concat(parts));
}

async function readFrame(reader: SocketReader): Promise<{ fin: boolean; opcode: number; payload: Buffer }> {
  const h = await reader.readExact(2);
  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let len = h[1] & 0x7F;

  if (len === 126) {
    const lb = await reader.readExact(2);
    len = lb.readUInt16BE(0);
  } else if (len === 127) {
    const lb = await reader.readExact(8);
    len = Number(lb.readBigUInt64BE(0));
  }

  let payload: Buffer;
  if (masked) {
    const mk = await reader.readExact(4);
    const raw = await reader.readExact(len);
    payload = Buffer.alloc(len);
    for (let i = 0; i < len; i++) payload[i] = raw[i] ^ mk[i & 3];
  } else {
    payload = await reader.readExact(len);
  }

  return { fin, opcode, payload };
}

type MsgResult = { type: 'data'; opcode: number; payload: Buffer } | { type: 'close'; code: number; reason: string };

async function readMessage(reader: SocketReader, socket: net.Socket): Promise<MsgResult> {
  while (true) {
    const frame = await readFrame(reader);

    if (frame.opcode === 9) {
      sendFrame(socket, 10, frame.payload);
      continue;
    }
    if (frame.opcode === 10) {
      continue;
    }
    if (frame.opcode === 8) {
      let code = 1005;
      let reason = '';
      if (frame.payload.length >= 2) {
        code = frame.payload.readUInt16BE(0);
        reason = frame.payload.subarray(2).toString('utf8');
      }
      return { type: 'close', code, reason };
    }

    if (frame.opcode === 1 || frame.opcode === 2) {
      const fragments: Buffer[] = [frame.payload];
      let fin = frame.fin;
      while (!fin) {
        const nf = await readFrame(reader);
        if (nf.opcode === 9) { sendFrame(socket, 10, nf.payload); continue; }
        if (nf.opcode === 10) continue;
        if (nf.opcode === 8) {
          let code = 1005;
          let reason = '';
          if (nf.payload.length >= 2) {
            code = nf.payload.readUInt16BE(0);
            reason = nf.payload.subarray(2).toString('utf8');
          }
          return { type: 'close', code, reason };
        }
        fragments.push(nf.payload);
        fin = nf.fin;
      }
      return { type: 'data', opcode: frame.opcode, payload: Buffer.concat(fragments) };
    }

    // unexpected opcode, skip
  }
}

function handleCommand(command: string, socket: net.Socket): void {
  if (command.startsWith('ADD ')) {
    const rest = command.substring(4);
    const spaceIdx = rest.indexOf(' ');
    const a = BigInt(rest.substring(0, spaceIdx));
    const b = BigInt(rest.substring(spaceIdx + 1));
    const sum = (a + b).toString();
    console.log(`${command} -> ${sum}`);
    sendFrame(socket, 1, Buffer.from(sum, 'utf8'));
  } else if (command.startsWith('REV ')) {
    const text = command.substring(4);
    const reversed = [...text].reverse().join('');
    console.log(`${command} -> ${reversed}`);
    sendFrame(socket, 1, Buffer.from(reversed, 'utf8'));
  }
}

function parseWsUrl(url: string): { port: number; requestTarget: string } {
  const m = url.match(/^ws:\/\/127\.0\.0\.1:(\d+)(\/.*)?$/);
  if (!m) throw new Error(`Bad URL: ${url}`);
  return { port: parseInt(m[1], 10), requestTarget: m[2] || '/' };
}

async function handleSession(url: string, n: number): Promise<void> {
  console.log(`session ${n}`);

  const { port, requestTarget } = parseWsUrl(url);
  const socket = new net.Socket();

  try {
    await new Promise<void>((resolve, reject) => {
      socket.connect(port, '127.0.0.1', resolve);
      socket.on('error', reject);
    });
  } catch {
    return;
  }

  const reader = new SocketReader(socket);

  // Handshake
  const key = crypto.randomBytes(16).toString('base64');
  const req =
    `GET ${requestTarget} HTTP/1.1\r\n` +
    `Host: 127.0.0.1:${port}\r\n` +
    `Upgrade: websocket\r\n` +
    `Connection: Upgrade\r\n` +
    `Sec-WebSocket-Version: 13\r\n` +
    `Sec-WebSocket-Key: ${key}\r\n` +
    `\r\n`;
  socket.write(req);

  let headerBlock: Buffer;
  try {
    headerBlock = await reader.readUntil(Buffer.from('\r\n\r\n'));
  } catch {
    socket.destroy();
    return;
  }

  const headerStr = headerBlock.toString('ascii');
  const lines = headerStr.split('\r\n');
  const statusLine = lines[0];
  const sm = statusLine.match(/^HTTP\/\d\.\d (\d{3})(?: (.*))?$/);
  if (!sm) {
    socket.destroy();
    return;
  }
  const statusCode = parseInt(sm[1], 10);
  const reasonPhrase = sm[2] || '';

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');

  let acceptVal: string | undefined;
  for (let i = 1; i < lines.length; i++) {
    const ci = lines[i].indexOf(':');
    if (ci === -1) continue;
    const name = lines[i].substring(0, ci).trim().toLowerCase();
    if (name === 'sec-websocket-accept') {
      acceptVal = lines[i].substring(ci + 1).trim();
      break;
    }
  }

  if (acceptVal !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  // Frame processing loop
  let sentClose = false;

  while (true) {
    let msg: MsgResult;
    try {
      msg = await readMessage(reader, socket);
    } catch {
      socket.destroy();
      return;
    }

    if (msg.type === 'close') {
      if (msg.reason) {
        console.log(`closed ${msg.code} ${msg.reason}`);
      } else {
        console.log(`closed ${msg.code}`);
      }
      if (!sentClose) {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(msg.code);
        sendFrame(socket, 8, cp);
      }
      socket.destroy();
      return;
    }

    // Data message
    if (msg.opcode === 1) {
      const command = msg.payload.toString('utf8');

      if (command === 'SHA1') {
        let nextMsg: MsgResult;
        try {
          nextMsg = await readMessage(reader, socket);
        } catch {
          socket.destroy();
          return;
        }
        if (nextMsg.type === 'close') {
          if (nextMsg.reason) {
            console.log(`closed ${nextMsg.code} ${nextMsg.reason}`);
          } else {
            console.log(`closed ${nextMsg.code}`);
          }
          if (!sentClose) {
            const cp = Buffer.alloc(2);
            cp.writeUInt16BE(nextMsg.code);
            sendFrame(socket, 8, cp);
          }
          socket.destroy();
          return;
        }
        const hash = crypto.createHash('sha1').update(nextMsg.payload).digest('hex');
        console.log(`SHA1 ${nextMsg.payload.length} -> ${hash}`);
        sendFrame(socket, 1, Buffer.from(hash, 'utf8'));
      } else if (command === 'BYE') {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(1000);
        sendFrame(socket, 8, cp);
        sentClose = true;
        // Read until server's close
        while (true) {
          let cm: MsgResult;
          try {
            cm = await readMessage(reader, socket);
          } catch {
            socket.destroy();
            return;
          }
          if (cm.type === 'close') {
            if (cm.reason) {
              console.log(`closed ${cm.code} ${cm.reason}`);
            } else {
              console.log(`closed ${cm.code}`);
            }
            socket.destroy();
            return;
          }
          // ignore data messages during BYE close handshake
        }
      } else {
        handleCommand(command, socket);
      }
    }
    // binary messages outside SHA1 context: ignore
  }
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    await handleSession(args[i], i + 1);
  }
  process.exit(0);
}

