            e = d; d = c; c = b.rotate_left(30); b = a; a = tmp;
        }
        h[0]=h[0].wrapping_add(a); h[1]=h[1].wrapping_add(b); h[2]=h[2].wrapping_add(c);
        h[3]=h[3].wrapping_add(d); h[4]=h[4].wrapping_add(e);
    }
    let mut r = [0u8; 20];
    for i in 0..5 { r[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes()); }
    r
}

fn hex_lower(data: &[u8]) -> String {
    data.iter().map(|b| format!("{:02x}", b)).collect()
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let hostport = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let colon_pos = hostport.rfind(':').unwrap();
    let host = &hostport[..colon_pos];
    let port: u16 = hostport[colon_pos+1..].parse().unwrap();
    (host.to_string(), port, path.to_string())
}

struct WsConn {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
}

impl WsConn {
    fn new(stream: TcpStream) -> Self {
        WsConn { stream, buf: Vec::new(), pos: 0 }
    }

    fn read_byte(&mut self) -> Option<u8> {
        if self.pos < self.buf.len() {
            let b = self.buf[self.pos]; self.pos += 1; Some(b)
        } else {
            self.buf.clear(); self.pos = 0;
            let mut b = [0u8; 1];
            match self.stream.read_exact(&mut b) { Ok(_) => Some(b[0]), Err(_) => None }
        }
    }

    fn read_n(&mut self, n: usize) -> Option<Vec<u8>> {
        if n == 0 { return Some(vec![]); }
        let mut result = Vec::with_capacity(n);
        let avail = self.buf.len() - self.pos;
        let take = avail.min(n);
        result.extend_from_slice(&self.buf[self.pos..self.pos+take]);
        self.pos += take;
        if result.len() < n {
            let mut tmp = vec![0u8; n - result.len()];
            match self.stream.read_exact(&mut tmp) {
                Ok(_) => result.extend_from_slice(&tmp),
                Err(_) => return None,
            }
        }
        Some(result)
    }

    fn write_frame(&mut self, opcode: u8, payload: &[u8]) {
        let mut frame = Vec::new();
        frame.push(0x80 | opcode);
        let mk = random_mask();
        let len = payload.len();
        if len <= 125 {
            frame.push(0x80 | len as u8);
        } else if len <= 65535 {
            frame.push(0x80 | 126);
            frame.extend_from_slice(&(len as u16).to_be_bytes());
        } else {
            frame.push(0x80 | 127);
            frame.extend_from_slice(&(len as u64).to_be_bytes());
        }
        frame.extend_from_slice(&mk);
        for (i, b) in payload.iter().enumerate() {
            frame.push(b ^ mk[i % 4]);
        }
        self.stream.write_all(&frame).unwrap();
        self.stream.flush().unwrap();
    }

    fn read_frame(&mut self) -> Option<(bool, u8, Vec<u8>)> {
        let b0 = self.read_byte()?;
        let b1 = self.read_byte()?;
        let fin = (b0 & 0x80) != 0;
        let opcode = b0 & 0x0F;
        let mut plen = (b1 & 0x7F) as usize;
        if plen == 126 {
            let b = self.read_n(2)?;
            plen = u16::from_be_bytes([b[0], b[1]]) as usize;
        } else if plen == 127 {
            let b = self.read_n(8)?;
            let mut a = [0u8; 8]; a.copy_from_slice(&b);
            plen = u64::from_be_bytes(a) as usize;
        }
        let payload = self.read_n(plen)?;
        Some((fin, opcode, payload))
    }

    /// Read a complete message (handling fragmentation and interleaved pings/pongs).
    /// Returns (opcode, payload). Returns None on connection close.
    fn read_message(&mut self, fin: bool, opcode: u8, mut payload: Vec<u8>) -> Option<(u8, Vec<u8>)> {
        let mut f = fin;
        let op = opcode;
        while !f {
            match self.read_frame() {
                Some((f2, op2, p)) => {
                    if op2 == 9 {
                        self.write_frame(10, &p);
                        continue;
                    }
                    if op2 == 10 { continue; }
                    if op2 == 8 {
                        // close during message assembly; return what we have
                        return Some((op, payload));
                    }
                    payload.extend_from_slice(&p);
                    f = f2;
                }
                None => return None,
            }
        }
        Some((op, payload))
    }

    /// Read the next data message (text or binary), handling pings/pongs.
    fn read_next_data(&mut self) -> Option<Vec<u8>> {
        loop {
            match self.read_frame() {
                Some((fin, opcode, payload)) => {
                    if opcode == 9 {
                        self.write_frame(10, &payload);
                        continue;
                    }
                    if opcode == 10 { continue; }
                    if opcode == 1 || opcode == 2 {
                        return self.read_message(fin, opcode, payload).map(|(_, msg)| msg);
                    }
                    if opcode == 8 {
                        return Some(vec![]);
                    }
                }
                None => return None,
            }
        }
    }
}

fn parse_close_payload(payload: &[u8]) -> (u16, String) {
    if payload.len() >= 2 {
        let code = u16::from_be_bytes([payload[0], payload[1]]);
        let reason = String::from_utf8_lossy(&payload[2..]).to_string();
        (code, reason)
    } else {
        (1005, String::new())
    }
}

fn handle_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let addr = format!("{}:{}", host, port);
    let stream = match TcpStream::connect(&addr) {
        Ok(s) => s,
        Err(_) => return,
    };
    stream.set_nodelay(true).ok();

    let key_bytes = random_bytes(16);
    let key = base64_encode(&key_bytes);

    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, key
    );

    let mut conn = WsConn::new(stream);
    conn.stream.write_all(req.as_bytes()).unwrap();
    conn.stream.flush().unwrap();

    // Read HTTP response headers up to and including \r\n\r\n
    let mut header_buf: Vec<u8> = Vec::new();
    let mut state = 0usize;
    loop {
        match conn.read_byte() {
            Some(b) => {
                header_buf.push(b);
                match state {
                    0 => { if b == b'\r' { state = 1; } }
                    1 => { if b == b'\n' { state = 2; } else { state = 0; } }
                    2 => { if b == b'\r' { state = 3; } else { state = 0; } }
                    3 => { if b == b'\n' { break; } else { state = 0; } }
                    _ => state = 0,
                }
            }
            None => return,
        }
    }

    // Parse status line
    let header_str = String::from_utf8_lossy(&header_buf).to_string();
    let lines: Vec<&str> = header_str.split("\r\n").collect();
    let status_line = lines[0];
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    if parts.len() < 2 {
        println!("handshake failed: 0 ");
        return;
    }
    let status_code: u16 = parts[1].parse().unwrap_or(0);
    let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

    if status_code != 101 {
        println!("handshake failed: {} {}", status_code, reason_phrase);
        return;
    }

    // Check Sec-WebSocket-Accept
    let expected_accept = {
        let mut input = key.clone();
        input.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
        let digest = sha1(input.as_bytes());
        base64_encode(&digest)
    };

    let mut accept_ok = false;
    for line in &lines[1..] {
        if let Some(colon) = line.find(':') {
            let name = line[..colon].trim().to_lowercase();
            if name == "sec-websocket-accept" {
                let val = line[colon+1..].trim();
                if val == expected_accept { accept_ok = true; }
            }
        }
    }

    if !accept_ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    // Main frame loop
    let mut sent_close = false;

    loop {
        let (fin, opcode, payload) = match conn.read_frame() {
            Some(f) => f,
            None => break,
        };

        match opcode {
            1 | 2 => {
                // Text or binary message, possibly fragmented
                let (op, msg) = match conn.read_message(fin, opcode, payload) {
                    Some(r) => r,
                    None => break,
                };
                if op == 1 {
                    // Text command
                    let text = String::from_utf8_lossy(&msg).to_string();
                    if text == "BYE" {
                        let close_payload = vec![0x03u8, 0xE8u8];
                        conn.write_frame(8, &close_payload);
                        sent_close = true;
                        // Read frames until close arrives
                        loop {
                            match conn.read_frame() {
                                Some((_, op2, p2)) => {
                                    if op2 == 9 {
                                        conn.write_frame(10, &p2);
                                    } else if op2 == 10 {
                                        // ignore
                                    } else if op2 == 8 {
                                        let (code, reason) = parse_close_payload(&p2);
                                        if reason.is_empty() {
                                            println!("closed {}", code);
                                        } else {
                                            println!("closed {} {}", code, reason);
                                        }
                                        break;
                                    }
                                }
                                None => break,
                            }
                        }
                        return;
                    } else if text.starts_with("ADD ") {
                        let rest = &text[4..];
                        let sp = rest.find(' ').unwrap();
                        let a_str = &rest[..sp];
                        let b_str = &rest[sp+1..];
                        let a: i64 = a_str.parse().unwrap();
                        let b: i64 = b_str.parse().unwrap();
                        let sum = a + b;
                        let reply = sum.to_string();
                        conn.write_frame(1, reply.as_bytes());
                        println!("ADD {} {} -> {}", a_str, b_str, sum);
                    } else if text.starts_with("REV ") {
                        let txt = &text[4..];
                        let reversed: String = txt.chars().rev().collect();
                        conn.write_frame(1, reversed.as_bytes());
                        println!("REV {} -> {}", txt, reversed);
                    } else if text == "SHA1" {
                        // Read next data message (binary)
                        let bin_payload = match conn.read_next_data() {
                            Some(p) => p,
                            None => break,
                        };
                        let digest = sha1(&bin_payload);
                        let hex = hex_lower(&digest);
                        conn.write_frame(1, hex.as_bytes());
                        println!("SHA1 {} -> {}", bin_payload.len(), hex);
                    }
                }
                // Binary outside SHA1 context: ignore
            }
            9 => {
                // Ping: reply with pong immediately
                conn.write_frame(10, &payload);
            }
            10 => {
                // Pong: ignore
            }
            8 => {
                // Close
                let (code, reason) = parse_close_payload(&payload);
                if reason.is_empty() {
                    println!("closed {}", code);
                } else {
                    println!("closed {} {}", code, reason);
                }
                if !sent_close {
                    let cp = vec![(code >> 8) as u8, (code & 0xFF) as u8];
                    conn.write_frame(8, &cp);
                }
                return;
            }
            _ => {}
        }
    }
}

#!/usr/bin/env python3
import sys
import socket
import hashlib
import base64
import os
import struct
import urllib.parse


def main():
    urls = sys.argv[1:]
    for i, url in enumerate(urls, 1):
        print(f"session {i}")
        handle_session(url)


def handle_session(url):
    parsed = urllib.parse.urlparse(url)
    host = parsed.hostname
    port = parsed.port
    path = parsed.path
    query = parsed.query
    request_target = path + ("?" + query if query else "")

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.connect((host, port))
    except OSError:
        print("handshake failed: connection refused")
        return

    key_bytes = os.urandom(16)
    key = base64.b64encode(key_bytes).decode('ascii')

    handshake = (
        f"GET {request_target} HTTP/1.1\r\n"
        f"Host: {host}:{port}\r\n"
        f"Upgrade: websocket\r\n"
        f"Connection: Upgrade\r\n"
        f"Sec-WebSocket-Version: 13\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        f"\r\n"
    )
    sock.sendall(handshake.encode('ascii'))

    buf = b""
    while b"\r\n\r\n" not in buf:
        data = sock.recv(65536)
        if not data:
            print("handshake failed: connection closed")
            sock.close()
            return
        buf += data

    header_end = buf.index(b"\r\n\r\n") + 4
    header_data = buf[:header_end].decode('ascii')
    buf = buf[header_end:]

    lines = header_data.split("\r\n")
    status_line = lines[0]
    parts = status_line.split(' ', 2)
    status_code = int(parts[1])
    reason_phrase = parts[2] if len(parts) > 2 else ""

    if status_code != 101:
        print(f"handshake failed: {status_code} {reason_phrase}")
        sock.close()
        return

    headers = {}
    for line in lines[1:]:
        if ':' in line:
            name, value = line.split(':', 1)
            headers[name.strip().lower()] = value.strip()

    expected_accept = base64.b64encode(
        hashlib.sha1((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode('ascii')).digest()
    ).decode('ascii')

    if headers.get('sec-websocket-accept') != expected_accept:
        print("handshake failed: bad Sec-WebSocket-Accept")
        sock.close()
        return

    try:
        process_frames(sock, buf)
    except (ConnectionError, OSError):
        pass
    finally:
        try:
            sock.close()
        except OSError:
            pass


def process_frames(sock, buf):
    sent_close = False
    msg_type = None
    msg_data = bytearray()
    expect_binary = False
    in_bye = False

    def read_exact(n):
        nonlocal buf
        while len(buf) < n:
            data = sock.recv(65536)
            if not data:
                raise ConnectionError("connection closed")
            buf += data
        result = buf[:n]
        buf = buf[n:]
        return result

    def read_frame():
        header = read_exact(2)
        fin = (header[0] >> 7) & 1
        opcode = header[0] & 0x0F
        masked = (header[1] >> 7) & 1
        payload_len = header[1] & 0x7F

        if payload_len == 126:
            payload_len = struct.unpack('!H', read_exact(2))[0]
        elif payload_len == 127:
            payload_len = struct.unpack('!Q', read_exact(8))[0]

        if masked:
            mask_key = read_exact(4)

        payload = read_exact(payload_len) if payload_len > 0 else b""

        if masked:
            payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))

        return fin, opcode, payload

    def send_frame(opcode, payload):
        frame = bytearray()
        frame.append(0x80 | opcode)

        mask_key = os.urandom(4)
        while mask_key == b'\x00\x00\x00\x00':
            mask_key = os.urandom(4)

        length = len(payload)
        if length <= 125:
            frame.append(0x80 | length)
        elif length <= 65535:
            frame.append(0x80 | 126)
            frame.extend(struct.pack('!H', length))
        else:
            frame.append(0x80 | 127)
            frame.extend(struct.pack('!Q', length))

        frame.extend(mask_key)
        masked_payload = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))
        frame.extend(masked_payload)
        sock.sendall(bytes(frame))

    def handle_close(payload):
        nonlocal sent_close
        if len(payload) >= 2:
            code = struct.unpack('!H', payload[:2])[0]
            reason_bytes = payload[2:]
            reason_str = reason_bytes.decode('utf-8') if reason_bytes else ""
        else:
            code = 1005
            reason_str = ""

        if reason_str:
            print(f"closed {code} {reason_str}")
        else:
            print(f"closed {code}")

        if not sent_close:
            try:
                send_frame(8, struct.pack('!H', code))
            except OSError:
                pass
            sent_close = True

    def process_text(text):
        nonlocal expect_binary, in_bye, sent_close
        if text == "SHA1":
            expect_binary = True
        elif text == "BYE":
            try:
                send_frame(8, struct.pack('!H', 1000))
            except OSError:
                pass
            sent_close = True
            in_bye = True
        elif text.startswith("ADD "):
            rest = text[4:]
            sp = rest.index(' ')
            a_str = rest[:sp]
            b_str = rest[sp + 1:]
            a = int(a_str)
            b = int(b_str)
            s = a + b
            try:
                send_frame(1, str(s).encode('utf-8'))
            except OSError:
                pass
            print(f"{text} -> {s}")
        elif text.startswith("REV "):
            original = text[4:]
            reversed_text = original[::-1]
            try:
                send_frame(1, reversed_text.encode('utf-8'))
            except OSError:
                pass
            print(f"{text} -> {reversed_text}")

    def process_binary(data):
        nonlocal expect_binary
        if expect_binary:
            h = hashlib.sha1(data).hexdigest()
            print(f"SHA1 {len(data)} -> {h}")
            expect_binary = False

    while True:
        try:
            fin, opcode, payload = read_frame()
        except ConnectionError:
            return

        if opcode == 9:
            try:
                send_frame(10, payload)
            except OSError:
                pass
            continue

        if opcode == 10:
            continue

        if opcode == 8:
            handle_close(payload)
            return

        if in_bye:
            continue

        if opcode in (1, 2):
            if fin:
                if opcode == 1:
                    text = payload.decode('utf-8')
                    process_text(text)
                elif opcode == 2:
                    process_binary(payload)
            else:
                msg_type = opcode
                msg_data = bytearray(payload)

        elif opcode == 0:
            if msg_type is not None:
                msg_data.extend(payload)
                if fin:
                    if msg_type == 1:
                        text = bytes(msg_data).decode('utf-8')
                        process_text(text)
                    elif msg_type == 2:
                        process_binary(bytes(msg_data))
                    msg_type = None
                    msg_data = bytearray()


if __name__ == "__main__":
    main()

