            except OSError:
                pass
            sent_close = True
            in_bye = True
        elif text.startswith("ADD "):
            rest = text[4:]
            sp = rest.index(' ')
            a_str = rest[:sp]
            b_str = rest[sp + 1:]
            a = int(a_str)
            b = int(b_str)
            s = a + b
            try:
                send_frame(1, str(s).encode('utf-8'))
            except OSError:
                pass
            print(f"{text} -> {s}")
        elif text.startswith("REV "):
            original = text[4:]
            reversed_text = original[::-1]
            try:
                send_frame(1, reversed_text.encode('utf-8'))
            except OSError:
                pass
            print(f"{text} -> {reversed_text}")

    def process_binary(data):
        nonlocal expect_binary
        if expect_binary:
            h = hashlib.sha1(data).hexdigest()
            try:
                send_frame(1, h.encode('utf-8'))
            except OSError:
                pass
            print(f"SHA1 {len(data)} -> {h}")
            expect_binary = False

    while True:
        try:
            fin, opcode, payload = read_frame()
        except ConnectionError:
            return

        if opcode == 9:
            try:
                send_frame(10, payload)
            except OSError:
                pass
            continue

        if opcode == 10:
            continue

        if opcode == 8:
            handle_close(payload)
            return

        if in_bye:
            continue

        if opcode in (1, 2):
            if fin:
                if opcode == 1:
                    text = payload.decode('utf-8')
                    process_text(text)
                elif opcode == 2:
                    process_binary(payload)
            else:
                msg_type = opcode
                msg_data = bytearray(payload)

        elif opcode == 0:
            if msg_type is not None:
                msg_data.extend(payload)
                if fin:
                    if msg_type == 1:
                        text = bytes(msg_data).decode('utf-8')
                        process_text(text)
                    elif msg_type == 2:
                        process_binary(bytes(msg_data))
                    msg_type = None
                    msg_data = bytearray()


