/* ===== SHA-1 ===== */
static uint32_t rotl32(uint32_t x, int n) { return (x << n) | (x >> (32 - n)); }

static void sha1(const uint8_t *msg, size_t len, uint8_t out[20]) {
    uint32_t h0=0x67452301,h1=0xEFCDAB89,h2=0x98BADCFE,h3=0x10325476,h4=0xC3D2E1F0;
    size_t total = len;
    size_t padded_len = ((len + 9 + 63) / 64) * 64;
    uint8_t *buf = calloc(padded_len, 1);
    memcpy(buf, msg, len);
    buf[len] = 0x80;
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) buf[padded_len - 1 - i] = (uint8_t)(bits >> (i * 8));
    for (size_t off = 0; off < padded_len; off += 64) {
        uint32_t w[80];
        for (int i = 0; i < 16; i++)
            w[i] = ((uint32_t)buf[off+i*4]<<24)|((uint32_t)buf[off+i*4+1]<<16)|
                   ((uint32_t)buf[off+i*4+2]<<8)|buf[off+i*4+3];
        for (int i = 16; i < 80; i++) w[i] = rotl32(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);
        uint32_t a=h0,b=h1,c=h2,d=h3,e=h4;
        for (int i = 0; i < 80; i++) {
            uint32_t f, k;
            if (i < 20) { f = (b&c)|(~b&d); k = 0x5A827999; }
            else if (i < 40) { f = b^c^d; k = 0x6ED9EBA1; }
            else if (i < 60) { f = (b&c)|(b&d)|(c&d); k = 0x8F1BBCDC; }
            else { f = b^c^d; k = 0xCA62C1D6; }
            uint32_t tmp = rotl32(a,5)+f+e+k+w[i];
            e=d; d=c; c=rotl32(b,30); b=a; a=tmp;
        }
        h0+=a; h1+=b; h2+=c; h3+=d; h4+=e;
    }
    free(buf);
    for (int i = 0; i < 4; i++) {
        out[i]    = (uint8_t)(h0 >> (24-i*8));
        out[4+i]  = (uint8_t)(h1 >> (24-i*8));
        out[8+i]  = (uint8_t)(h2 >> (24-i*8));
        out[12+i] = (uint8_t)(h3 >> (24-i*8));
        out[16+i] = (uint8_t)(h4 >> (24-i*8));
    }
}

/* ===== Base64 ===== */
static const char b64chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static char *base64_encode(const uint8_t *data, size_t len) {
    size_t olen = 4 * ((len + 2) / 3);
    char *out = malloc(olen + 1);
    size_t j = 0;
    for (size_t i = 0; i < len; i += 3) {
        uint32_t v = ((uint32_t)data[i]) << 16;
        if (i+1 < len) v |= ((uint32_t)data[i+1]) << 8;
        if (i+2 < len) v |= data[i+2];
        out[j++] = b64chars[(v >> 18) & 0x3F];
        out[j++] = b64chars[(v >> 12) & 0x3F];
        out[j++] = (i+1 < len) ? b64chars[(v >> 6) & 0x3F] : '=';
        out[j++] = (i+2 < len) ? b64chars[v & 0x3F] : '=';
    }
    out[j] = '\0';
    return out;
}

/* ===== Random ===== */
static void get_random(uint8_t *buf, size_t len) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd >= 0) {
        size_t off = 0;
        while (off < len) {
            ssize_t r = read(fd, buf + off, len - off);
            if (r <= 0) break;
            off += r;
        }
        close(fd);
    }
}

static void get_random_mask(uint8_t *buf) {
    do { get_random(buf, 4); } while (buf[0]==0 && buf[1]==0 && buf[2]==0 && buf[3]==0);
}

/* ===== UTF-8 ===== */
static size_t utf8_decode(const uint8_t *s, size_t len, uint32_t *cp) {
    if (len == 0) { *cp = 0; return 0; }
    uint8_t c = s[0];
    if (c < 0x80) { *cp = c; return 1; }
    if ((c & 0xE0) == 0xC0 && len >= 2) {
        *cp = ((uint32_t)(c & 0x1F) << 6) | (s[1] & 0x3F); return 2;
    }
    if ((c & 0xF0) == 0xE0 && len >= 3) {
        *cp = ((uint32_t)(c & 0x0F) << 12) | ((uint32_t)(s[1] & 0x3F) << 6) | (s[2] & 0x3F); return 3;
    }
    if ((c & 0xF8) == 0xF0 && len >= 4) {
        *cp = ((uint32_t)(c & 0x07) << 18) | ((uint32_t)(s[1] & 0x3F) << 12) |
              ((uint32_t)(s[2] & 0x3F) << 6) | (s[3] & 0x3F); return 4;
    }
    *cp = c; return 1;
}

static size_t utf8_encode(uint32_t cp, uint8_t *out) {
    if (cp < 0x80) { out[0] = (uint8_t)cp; return 1; }
    if (cp < 0x800) {
        out[0] = 0xC0 | (cp >> 6); out[1] = 0x80 | (cp & 0x3F); return 2;
    }
    if (cp < 0x10000) {
        out[0] = 0xE0 | (cp >> 12); out[1] = 0x80 | ((cp >> 6) & 0x3F); out[2] = 0x80 | (cp & 0x3F); return 3;
    }
    out[0] = 0xF0 | (cp >> 18); out[1] = 0x80 | ((cp >> 12) & 0x3F);
    out[2] = 0x80 | ((cp >> 6) & 0x3F); out[3] = 0x80 | (cp & 0x3F); return 4;
}

/* ===== URL parsing ===== */
typedef struct { char host[256]; int port; char path[4096]; } WSUrl;

static void parse_url(const char *url, WSUrl *u) {
    const char *p = url;
    if (strncmp(p, "ws://", 5) == 0) p += 5;
    const char *colon = strchr(p, ':');
    const char *slash = strchr(p, '/');
    if (colon && (!slash || colon < slash)) {
        size_t hlen = colon - p;
        if (hlen >= sizeof(u->host)) hlen = sizeof(u->host) - 1;
        memcpy(u->host, p, hlen); u->host[hlen] = 0;
        u->port = atoi(colon + 1);
    } else {
        size_t hlen = slash ? (size_t)(slash - p) : strlen(p);
        if (hlen >= sizeof(u->host)) hlen = sizeof(u->host) - 1;
        memcpy(u->host, p, hlen); u->host[hlen] = 0;
        u->port = 80;
    }
    if (slash) { strncpy(u->path, slash, sizeof(u->path)-1); u->path[sizeof(u->path)-1]=0; }
    else strcpy(u->path, "/");
}

/* ===== Buffered reader ===== */
#define RBUF_SZ (1 << 16)
typedef struct { int fd; uint8_t buf[RBUF_SZ]; size_t start, end; } Reader;

static void reader_init(Reader *r, int fd) { r->fd = fd; r->start = r->end = 0; }

static int read_exact(Reader *r, uint8_t *dst, size_t n) {
    size_t got = 0;
    while (got < n) {
        if (r->start < r->end) {
            size_t avail = r->end - r->start;
            size_t take = avail < (n - got) ? avail : (n - got);
            memcpy(dst + got, r->buf + r->start, take);
            r->start += take;
            got += take;
        } else {
            ssize_t rd = read(r->fd, r->buf, RBUF_SZ);
            if (rd <= 0) return -1;
            r->start = 0; r->end = (size_t)rd;
        }
    }
    return 0;
}

static int write_all(int fd, const uint8_t *data, size_t len) {
    size_t off = 0;
    while (off < len) {
        ssize_t w = write(fd, data + off, len - off);
        if (w <= 0) return -1;
        off += w;
    }
    return 0;
}

/* ===== WebSocket frame ===== */
typedef struct {
    int fin, opcode;
    uint8_t *payload;
    size_t plen;
} Frame;

static int read_frame(Reader *r, Frame *f) {
    uint8_t hdr[2];
    if (read_exact(r, hdr, 2) < 0) return -1;
    f->fin = (hdr[0] >> 7) & 1;
    f->opcode = hdr[0] & 0x0F;
    uint8_t len7 = hdr[1] & 0x7F;
    uint64_t plen;
    if (len7 < 126) {
        plen = len7;
    } else if (len7 == 126) {
        uint8_t ext[2];
        if (read_exact(r, ext, 2) < 0) return -1;
        plen = ((uint64_t)ext[0] << 8) | ext[1];
    } else {
        uint8_t ext[8];
        if (read_exact(r, ext, 8) < 0) return -1;
        plen = 0;
        for (int i = 0; i < 8; i++) plen = (plen << 8) | ext[i];
    }
    if (hdr[1] & 0x80) {
        uint8_t mk[4];
        if (read_exact(r, mk, 4) < 0) return -1;
        f->payload = malloc(plen + 1);
        if (plen > 0 && read_exact(r, f->payload, plen) < 0) { free(f->payload); return -1; }
        for (uint64_t i = 0; i < plen; i++) f->payload[i] ^= mk[i % 4];
    } else {
        f->payload = malloc(plen + 1);
        if (plen > 0 && read_exact(r, f->payload, plen) < 0) { free(f->payload); return -1; }
    }
    f->plen = (size_t)plen;
    f->payload[f->plen] = 0;
    return 0;
}

static void send_frame(int fd, int fin, int opcode, const uint8_t *payload, size_t plen) {
    uint8_t hdr[14];
    size_t hlen = 0;
    hdr[hlen++] = (fin ? 0x80 : 0) | (opcode & 0x0F);
    if (plen < 126) {
        hdr[hlen++] = 0x80 | (uint8_t)plen;
    } else if (plen <= 65535) {
        hdr[hlen++] = 0x80 | 126;
        hdr[hlen++] = (uint8_t)(plen >> 8);
        hdr[hlen++] = (uint8_t)(plen & 0xFF);
    } else {
        hdr[hlen++] = 0x80 | 127;
        for (int i = 7; i >= 0; i--) hdr[hlen++] = (uint8_t)(plen >> (i * 8));
    }
    uint8_t mask[4];
    get_random_mask(mask);
    hdr[hlen++] = mask[0]; hdr[hlen++] = mask[1];
    hdr[hlen++] = mask[2]; hdr[hlen++] = mask[3];
    uint8_t *masked = NULL;
    if (plen > 0) {
        masked = malloc(plen);
        for (size_t i = 0; i < plen; i++) masked[i] = payload[i] ^ mask[i % 4];
    }
    write_all(fd, hdr, hlen);
    if (plen > 0) { write_all(fd, masked, plen); free(masked); }
}

/* ===== Handshake ===== */
static int do_handshake(int fd, const WSUrl *u, char *key_out) {
    uint8_t rawkey[16];
    get_random(rawkey, 16);
    char *key_b64 = base64_encode(rawkey, 16);
    strcpy(key_out, key_b64);
    free(key_b64);

    char req[8192];
    int n = snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        u->path, u->host, u->port, key_out);

    if (write_all(fd, (uint8_t*)req, n) < 0) return -1;

    /* Read response headers */
    Reader r;
    reader_init(&r, fd);
    char hbuf[65536];
    size_t hlen = 0;
    int state = 0;
    while (state < 4 && hlen < sizeof(hbuf) - 1) {
        uint8_t c;
        if (read_exact(&r, &c, 1) < 0) return -1;
        hbuf[hlen++] = (char)c;
        if (state == 0 && c == '\r') state = 1;
        else if (state == 1 && c == '\n') state = 2;
        else if (state == 2 && c == '\r') state = 3;
        else if (state == 3 && c == '\n') state = 4;
        else state = (c == '\r') ? 1 : 0;
    }
    hbuf[hlen] = 0;

    /* Parse status line */
    int status = 0;
    char reason[256] = "";
    if (strncmp(hbuf, "HTTP/1.1 ", 9) == 0) {
        status = atoi(hbuf + 9);
        char *sp = strchr(hbuf + 9, ' ');
        if (sp) {
            sp++;
            char *eol = strstr(sp, "\r\n");
            if (eol) { size_t rl = eol - sp; if (rl >= sizeof(reason)) rl = sizeof(reason)-1; memcpy(reason, sp, rl); reason[rl]=0; }
        }
    }

    if (status != 101) {
        printf("handshake failed: %d %s\n", status, reason);
        return -1;
    }

    /* Find Sec-WebSocket-Accept */
    char accept_val[256] = "";
    char *line = strstr(hbuf, "\r\n");
    while (line) {
        line += 2;
        char *eol = strstr(line, "\r\n");
        if (!eol) eol = line + strlen(line);
        size_t llen = eol - line;
        if (llen == 0) break;
        char *colon = memchr(line, ':', llen);
        if (colon) {
            size_t nlen = colon - line;
            if (nlen == 20 && strncasecmp(line, "Sec-WebSocket-Accept", 20) == 0) {
                char *v = colon + 1;
                while (v < eol && *v == ' ') v++;
                size_t vlen = eol - v;
                if (vlen >= sizeof(accept_val)) vlen = sizeof(accept_val) - 1;
                memcpy(accept_val, v, vlen);
                accept_val[vlen] = 0;
            }
        }
        line = strstr(eol, "\r\n");
    }

    /* Validate accept */
    char concat[256];
    snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key_out);
    uint8_t digest[20];
    sha1((const uint8_t*)concat, strlen(concat), digest);
    char *expected = base64_encode(digest, 20);
    if (strcmp(accept_val, expected) != 0) {
        free(expected);
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        return -1;
    }
    free(expected);

    /* Re-initialize reader to preserve any buffered frame data */
    reader_init(&r, fd);
    /* We need to pass the reader back - but since it's local, let's restructure */
    /* Actually we need to keep the reader's buffer state. Let me restructure. */
    return 0;
}

/* We need to restructure: the reader must be created before handshake reading
   so that bytes past the header block are preserved in the buffer. */

/* ===== Read a data message (text/binary), handling pings/pongs ===== */
static int read_data_message(Reader *r, int fd, int *opcode, uint8_t **payload, size_t *plen) {
    uint8_t *msg = NULL;
    size_t msglen = 0, msgcap = 0;
    int msg_opcode = -1;

    for (;;) {
        Frame f;
        if (read_frame(r, &f) < 0) { free(msg); return -1; }
        if (f.opcode == 9) {
            send_frame(fd, 1, 10, f.payload, f.plen);
            free(f.payload);
            continue;
        }
        if (f.opcode == 10) {
            free(f.payload);
            continue;
        }
        if (f.opcode == 8) {
            *payload = f.payload;
            *plen = f.plen;
            free(msg);
            return 1;
        }
        if (f.opcode == 1 || f.opcode == 2) {
            msg_opcode = f.opcode;
            msgcap = f.plen + 1;
            msg = malloc(msgcap);
            if (f.plen > 0) memcpy(msg, f.payload, f.plen);
            msglen = f.plen;
            free(f.payload);
            if (f.fin) {
                *opcode = msg_opcode;
                *payload = msg;
                *plen = msglen;
                return 0;
            }
            continue;
        }
        if (f.opcode == 0) {
            if (!msg) { free(f.payload); continue; }
            if (msglen + f.plen + 1 > msgcap) {
                msgcap = msglen + f.plen + 1;
                msg = realloc(msg, msgcap);
            }
            if (f.plen > 0) memcpy(msg + msglen, f.payload, f.plen);
            msglen += f.plen;
            free(f.payload);
            if (f.fin) {
                *opcode = msg_opcode;
                *payload = msg;
                *plen = msglen;
                return 0;
            }
            continue;
        }
        free(f.payload);
    }
}

/* ===== Handle close frame ===== */
static void handle_close(int fd, const uint8_t *payload, size_t plen, int sent_close) {
    uint16_t code = 1005;
    char reason[4096] = "";
    if (plen >= 2) {
        code = ((uint16_t)payload[0] << 8) | payload[1];
        size_t rlen = plen - 2;
        if (rlen >= sizeof(reason)) rlen = sizeof(reason) - 1;
        memcpy(reason, payload + 2, rlen);
        reason[rlen] = 0;
    }
    if (reason[0])
        printf("closed %u %s\n", code, reason);
    else
        printf("closed %u\n", code);
    if (!sent_close) {
        uint8_t cp[2] = { (uint8_t)(code >> 8), (uint8_t)(code & 0xFF) };
        send_frame(fd, 1, 8, cp, 2);
    }
}

/* ===== Process a text command ===== */
static int process_text(Reader *r, int fd, const char *text, size_t tlen, int *sent_close) {
    if (strncmp(text, "ADD ", 4) == 0) {
        const char *args = text + 4;
        char *end1, *end2;
        long long a = strtoll(args, &end1, 10);
        while (*end1 == ' ') end1++;
        long long b = strtoll(end1, &end2, 10);
        long long sum = a + b;
        char reply[64];
        snprintf(reply, sizeof(reply), "%lld", sum);
        send_frame(fd, 1, 1, (const uint8_t*)reply, strlen(reply));
        printf("%s -> %s\n", text, reply);
        return 0;
    }
    if (strncmp(text, "REV ", 4) == 0) {
        const char *txt = text + 4;
        size_t txtlen = tlen - 4;
        size_t max_cp = txtlen + 1;
        uint32_t *cps = malloc(max_cp * sizeof(uint32_t));
        size_t ncps = 0;
        size_t pos = 0;
        while (pos < txtlen) {
            uint32_t cp;
            size_t sz = utf8_decode((const uint8_t*)txt + pos, txtlen - pos, &cp);
            if (sz == 0) break;
            cps[ncps++] = cp;
            pos += sz;
        }
        for (size_t i = 0; i < ncps / 2; i++) {
            uint32_t tmp = cps[i]; cps[i] = cps[ncps-1-i]; cps[ncps-1-i] = tmp;
        }
        size_t max_out = txtlen + ncps * 4 + 1;
        uint8_t *out = malloc(max_out);
        size_t olen = 0;
        for (size_t i = 0; i < ncps; i++) olen += utf8_encode(cps[i], out + olen);
        out[olen] = 0;
        send_frame(fd, 1, 1, out, olen);
        printf("REV %s -> %s\n", txt, (char*)out);
        free(cps); free(out);
        return 0;
    }
    if (strcmp(text, "SHA1") == 0) {
        int bopcode;
        uint8_t *bpayload;
        size_t blen;
        int ret = read_data_message(r, fd, &bopcode, &bpayload, &blen);
        if (ret != 0) {
            if (ret == 1) {
                handle_close(fd, bpayload, blen, *sent_close);
                free(bpayload);
                return 1;
            }
            free(bpayload);
            return -1;
        }
        uint8_t digest[20];
        sha1(bpayload, blen, digest);
        char hex[41];
        for (int i = 0; i < 20; i++) sprintf(hex + i*2, "%02x", digest[i]);
        hex[40] = 0;
        send_frame(fd, 1, 1, (const uint8_t*)hex, 40);
        printf("SHA1 %zu -> %s\n", blen, hex);
        free(bpayload);
        return 0;
    }
    if (strcmp(text, "BYE") == 0) {
        uint8_t cp[2] = { 0x03, 0xE8 };
        send_frame(fd, 1, 8, cp, 2);
        *sent_close = 1;
        for (;;) {
            Frame f;
            if (read_frame(r, &f) < 0) return -1;
            if (f.opcode == 9) {
                send_frame(fd, 1, 10, f.payload, f.plen);
                free(f.payload);
                continue;
            }
            if (f.opcode == 10) { free(f.payload); continue; }
            if (f.opcode == 8) {
                handle_close(fd, f.payload, f.plen, *sent_close);
                free(f.payload);
                return 1;
            }
            free(f.payload);
        }
    }
    return 0;
}

/* ===== Session ===== */
static void do_session(const char *url) {
    WSUrl u;
    parse_url(url, &u);
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return;
    struct sockaddr_in sa;
    memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET;
    sa.sin_port = htons(u.port);
    inet_pton(AF_INET, u.host, &sa.sin_addr);
    if (connect(fd, (struct sockaddr*)&sa, sizeof(sa)) < 0) { close(fd); return; }

    char key[64];
    uint8_t rawkey[16];
    get_random(rawkey, 16);
    char *key_b64 = base64_encode(rawkey, 16);
    strcpy(key, key_b64);
    free(key_b64);

    char req[8192];
    int n = snprintf(req, sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        u.path, u.host, u.port, key);

    if (write_all(fd, (uint8_t*)req, n) < 0) { close(fd); return; }

    /* Read response headers using a reader that preserves leftover bytes */
    Reader r;
    reader_init(&r, fd);
    char hbuf[65536];
    size_t hlen = 0;
    int state = 0;
    while (state < 4 && hlen < sizeof(hbuf) - 1) {
        uint8_t c;
        if (read_exact(&r, &c, 1) < 0) { close(fd); return; }
        hbuf[hlen++] = (char)c;
        if (state == 0 && c == '\r') state = 1;
        else if (state == 1 && c == '\n') state = 2;
        else if (state == 2 && c == '\r') state = 3;
        else if (state == 3 && c == '\n') state = 4;
        else state = (c == '\r') ? 1 : 0;
    }
    hbuf[hlen] = 0;

    int status = 0;
    char reason[256] = "";
    if (strncmp(hbuf, "HTTP/1.1 ", 9) == 0) {
        status = atoi(hbuf + 9);
        char *sp = strchr(hbuf + 9, ' ');
        if (sp) {
            sp++;
            char *eol = strstr(sp, "\r\n");
            if (eol) { size_t rl = eol - sp; if (rl >= sizeof(reason)) rl = sizeof(reason)-1; memcpy(reason, sp, rl); reason[rl]=0; }
        }
    }

    if (status != 101) {
        printf("handshake failed: %d %s\n", status, reason);
        close(fd);
        return;
    }

    /* Find Sec-WebSocket-Accept */
    char accept_val[256] = "";
    char *line = strstr(hbuf, "\r\n");
    while (line) {
        line += 2;
        char *eol = strstr(line, "\r\n");
        if (!eol) eol = line + strlen(line);
        size_t llen = eol - line;
        if (llen == 0) break;
        char *colon = memchr(line, ':', llen);
        if (colon) {
            size_t nlen = colon - line;
            if (nlen == 20 && strncasecmp(line, "Sec-WebSocket-Accept", 20) == 0) {
                char *v = colon + 1;
                while (v < eol && *v == ' ') v++;
                size_t vlen = eol - v;
                if (vlen >= sizeof(accept_val)) vlen = sizeof(accept_val) - 1;
                memcpy(accept_val, v, vlen);
                accept_val[vlen] = 0;
            }
        }
        line = strstr(eol, "\r\n");
    }

    char concat[256];
    snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key);
    uint8_t digest[20];
    sha1((const uint8_t*)concat, strlen(concat), digest);
    char *expected = base64_encode(digest, 20);
    if (strcmp(accept_val, expected) != 0) {
        free(expected);
        printf("handshake failed: bad Sec-WebSocket-Accept\n");
        close(fd);
        return;
    }
    free(expected);

    /* The reader 'r' still has buffered data past the header block - use it for frames */
    int sent_close = 0;

    for (;;) {
        int opcode;
        uint8_t *payload;
        size_t plen;
        int ret = read_data_message(&r, fd, &opcode, &payload, &plen);
        if (ret == 1) {
            handle_close(fd, payload, plen, sent_close);
            free(payload);
            break;
        }
        if (ret < 0) { free(payload); break; }
        if (opcode == 1) {
            payload[plen] = 0;
            int pr = process_text(&r, fd, (const char*)payload, plen, &sent_close);
            free(payload);
            if (pr != 0) break;
        } else {
            free(payload);
        }
    }
    close(fd);
}

/* ===== Main ===== */
int main(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        printf("session %d\n", i);
        fflush(stdout);
        do_session(argv[i]);
    }
    return 0;
}

use std::env;
use std::fs;
use std::collections::HashMap;

fn read_i32_be(d: &[u8], p: usize) -> i32 {
    i32::from_be_bytes([d[p], d[p+1], d[p+2], d[p+3]])
}
fn read_i64_be(d: &[u8], p: usize) -> i64 {
    i64::from_be_bytes([d[p],d[p+1],d[p+2],d[p+3],d[p+4],d[p+5],d[p+6],d[p+7]])
}

#[derive(Clone)]
struct TzType { utc_offset: i32, isdst: bool, abbr_idx: u8 }

#[derive(Clone)]
struct RuleTime { month: u32, week: u32, day: u32, time: i32 }

#[derive(Clone)]
struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start: Option<RuleTime>,
    end: Option<RuleTime>,
}

#[derive(Clone)]
struct TzifData {
    transitions: Vec<(i64, usize)>,
    types: Vec<TzType>,
    abbrs_data: Vec<u8>,
    posix: Option<PosixRule>,
}

impl TzifData {
    fn get_abbr(&self, idx: u8) -> String {
        let s = idx as usize;
        let mut e = s;
        while e < self.abbrs_data.len() && self.abbrs_data[e] != 0 { e += 1; }
        String::from_utf8_lossy(&self.abbrs_data[s..e]).to_string()
    }

    fn get_type_at(&self, t: i64) -> (i32, String) {
        if self.transitions.is_empty() {
            if self.posix.is_some() { return self.footer_type(t); }
            let ty = &self.types[0];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }
        if t < self.transitions[0].0 {
            let ty = &self.types[0];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }
        let last_t = self.transitions.last().unwrap().0;
        if t >= last_t {
            return self.footer_type(t);
        }
        let mut lo = 0usize; let mut hi = self.transitions.len();
        while lo < hi {
            let mid = (lo+hi)/2;
            if self.transitions[mid].0 <= t { lo = mid+1; } else { hi = mid; }
        }
        let ti = self.transitions[lo-1].1;
        let ty = &self.types[ti];
        (ty.utc_offset, self.get_abbr(ty.abbr_idx))
    }

    fn footer_type(&self, t: i64) -> (i32, String) {
        let p = match &self.posix { Some(p) => p, None => {
            let ti = self.transitions.last().unwrap().1;
            let ty = &self.types[ti];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }};
        let dst_off = -(p.dst_offset.unwrap_or(p.std_offset - 3600));
        let std_off = -p.std_offset;
        if p.dst_name.is_none() || p.start.is_none() || p.end.is_none() {
            return (std_off, p.std_name.clone());
        }
        let yr = year_from_unix(t);
        let (st, et) = match posix_transitions(yr, p) { Some(x) => x, None => return (std_off, p.std_name.clone()) };
        if st <= et {
            if t >= st && t < et { (dst_off, p.dst_name.clone().unwrap()) }
            else { (std_off, p.std_name.clone()) }
        } else {
            if t >= st || t < et { (dst_off, p.dst_name.clone().unwrap()) }
            else { (std_off, p.std_name.clone()) }
        }
    }
}

fn parse_tzif(path: &str) -> TzifData {
    let data = fs::read(path).unwrap();
    let mut pos = 0usize;
    // skip block 1
    pos = 44;
    let isutcnt = read_i32_be(&data, pos) as usize;
    let isstdcnt = read_i32_be(&data, pos+4) as usize;
    let leapcnt = read_i32_be(&data, pos+8) as usize;
    let timecnt = read_i32_be(&data, pos+12) as usize;
    let typecnt = read_i32_be(&data, pos+16) as usize;
    let charcnt = read_i32_be(&data, pos+20) as usize;
    pos += 24;
    pos += timecnt*4 + timecnt + typecnt*6 + charcnt + leapcnt*8 + isstdcnt + isutcnt;
    // block 2 header
    pos += 44;
    let isutcnt2 = read_i32_be(&data, pos) as usize;
    let isstdcnt2 = read_i32_be(&data, pos+4) as usize;
    let leapcnt2 = read_i32_be(&data, pos+8) as usize;
    let timecnt2 = read_i32_be(&data, pos+12) as usize;
    let typecnt2 = read_i32_be(&data, pos+16) as usize;
    let charcnt2 = read_i32_be(&data, pos+20) as usize;
    pos += 24;
    let mut trans_times = Vec::with_capacity(timecnt2);
    for _ in 0..timecnt2 { trans_times.push(read_i64_be(&data, pos)); pos += 8; }
    let mut trans_types = Vec::with_capacity(timecnt2);
    for _ in 0..timecnt2 { trans_types.push(data[pos] as usize); pos += 1; }
    let transitions: Vec<(i64,usize)> = trans_times.into_iter().zip(trans_types).collect();
    let mut types = Vec::with_capacity(typecnt2);
    for _ in 0..typecnt2 {
        let off = read_i32_be(&data, pos); pos += 4;
        let dst = data[pos] != 0; pos += 1;
        let ai = data[pos]; pos += 1;
        types.push(TzType{utc_offset:off, isdst:dst, abbr_idx:ai});
    }
    let abbrs_data = data[pos..pos+charcnt2].to_vec();
    pos += charcnt2;
    pos += leapcnt2*12 + isstdcnt2 + isutcnt2;
    // footer
    if pos < data.len() && data[pos] == b'\n' { pos += 1; }
    let fs = pos;
    while pos < data.len() && data[pos] != b'\n' { pos += 1; }
    let posix_str = String::from_utf8_lossy(&data[fs..pos]).to_string();
    let posix = if posix_str.is_empty() { None } else { Some(parse_posix(&posix_str)) };
    TzifData { transitions, types, abbrs_data, posix }
}

fn parse_posix(s: &str) -> PosixRule {
    let c: Vec<char> = s.chars().collect();
    let mut p = 0usize;
    let std_name = parse_name(&c, &mut p);
    let std_offset = parse_offset(&c, &mut p);
    let mut dst_name = None;
    let mut dst_offset = None;
    let mut start = None;
    let mut end = None;
    if p < c.len() && (c[p].is_alphabetic() || c[p] == '<') {
        dst_name = Some(parse_name(&c, &mut p));
        if p < c.len() && (c[p]=='+' || c[p]=='-' || c[p].is_ascii_digit()) {
            dst_offset = Some(parse_offset(&c, &mut p));
        } else {
            dst_offset = Some(std_offset - 3600);
        }
        if p < c.len() && c[p] == ',' {
            p += 1;
            start = Some(parse_rule_time(&c, &mut p));
            if p < c.len() && c[p] == ',' {
                p += 1;
                end = Some(parse_rule_time(&c, &mut p));
            }
        }
    }
    PosixRule { std_name, std_offset, dst_name, dst_offset, start, end }
}

fn parse_name(c: &[char], p: &mut usize) -> String {
    if *p < c.len() && c[*p] == '<' {
        *p += 1;
        let s = *p;
        while *p < c.len() && c[*p] != '>' { *p += 1; }
        let r: String = c[s..*p].iter().collect();
        *p += 1; // skip >
        r
    } else {
        let s = *p;
        while *p < c.len() && c[*p].is_alphabetic() { *p += 1; }
        c[s..*p].iter().collect()
    }
}

fn parse_offset(c: &[char], p: &mut usize) -> i32 {
    let mut sign = 1i32;
    if *p < c.len() && c[*p] == '-' { sign = -1; *p += 1; }
    else if *p < c.len() && c[*p] == '+' { *p += 1; }
    let mut h = 0i32;
    while *p < c.len() && c[*p].is_ascii_digit() { h = h*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
    let mut m = 0i32; let mut s = 0i32;
    if *p < c.len() && c[*p] == ':' {
        *p += 1;
        while *p < c.len() && c[*p].is_ascii_digit() { m = m*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
        if *p < c.len() && c[*p] == ':' {
            *p += 1;
            while *p < c.len() && c[*p].is_ascii_digit() { s = s*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
        }
    }
    sign * (h*3600 + m*60 + s)
}

fn parse_rule_time(c: &[char], p: &mut usize) -> RuleTime {
    assert_eq!(c[*p], 'M'); *p += 1;
    let month = parse_num(c, p);
    assert_eq!(c[*p], '.'); *p += 1;
    let week = parse_num(c, p);
    assert_eq!(c[*p], '.'); *p += 1;
    let day = parse_num(c, p);
    let time = if *p < c.len() && c[*p] == '/' { *p += 1; parse_offset(c, p) } else { 7200 };
    RuleTime { month, week, day, time }
}

fn parse_num(c: &[char], p: &mut usize) -> u32 {
    let mut v = 0u32;
    while *p < c.len() && c[*p].is_ascii_digit() { v = v*10 + (c[*p] as u32 - '0' as u32); *p += 1; }
    v
}

fn posix_transitions(year: i32, p: &PosixRule) -> Option<(i64, i64)> {
    let sr = p.start.as_ref()?;
    let er = p.end.as_ref()?;
    let (sy,sm,sd) = mwd_to_date(year, sr.month, sr.week, sr.day);
    let (ey,em,ed) = mwd_to_date(year, er.month, er.week, er.day);
    let st = date_to_days(sy,sm,sd)*86400 + sr.time as i64 + p.std_offset as i64;
    let dso = p.dst_offset.unwrap_or(p.std_offset - 3600);
    let et = date_to_days(ey,em,ed)*86400 + er.time as i64 + dso as i64;
    Some((st, et))
}

fn mwd_to_date(year: i32, month: u32, week: u32, day: u32) -> (i32,u32,u32) {
    let first_dow = day_of_week(year, month, 1);
    let first_occ = 1 + ((day as i32 - first_dow as i32 + 7) % 7) as u32;
    if week <= 4 {
        (year, month, first_occ + (week-1)*7)
    } else {
        let last_day = days_in_month(year, month);
        let last_dow = day_of_week(year, month, last_day);
        let back = (last_dow as i32 - day as i32 + 7) % 7;
        (year, month, last_day - back as u32)
    }
}

fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1|3|5|7|8|10|12 => 31,
        4|6|9|11 => 30,
        2 => if is_leap(y) {29} else {28},
        _ => 30,
    }
}

fn is_leap(y: i32) -> bool {
    (y%4==0 && y%100!=0) || y%400==0
}

fn day_of_week(y: i32, m: u32, d: u32) -> u32 {
    let dd = date_to_days(y, m, d);
    (((dd + 4) % 7 + 7) % 7) as u32
}

fn date_to_days(y: i32, m: u32, d: u32) -> i64 {
    let yy = y - if m <= 2 {1} else {0};
    let era = if yy >= 0 {yy} else {yy-399} / 400;
    let yoe = (yy - era*400) as i64;
    let mp = ((m + 9) % 12) as i64;
    let doy = (153*mp+2)/5 + d as i64 - 1;
    let doe = yoe*365 + yoe/4 - yoe/100 + doy;
    era as i64 * 146097 + doe - 719468
}

fn days_to_date(days: i64) -> (i32,u32,u32) {
    let z = days + 719468;
    let era = if z >= 0 {z} else {z-146096} / 146097;
    let doe = (z - era*146097) as u64;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    let y = yoe as i64 + era*400;
    let mp = (5*doe+2)/153;
    let d = doe - (153*mp+2)/5 + 1;
    let m = if mp < 10 {mp+3} else {mp-9};
    let year = (y + if m <= 2 {1} else {0}) as i32;
    (year, m as u32, d as u32)
}

fn year_from_unix(t: i64) -> i32 {
    let d = t.div_euclid(86400);
    days_to_date(d).0
}

fn parse_wall(s: &str) -> i64 {
    let y: i32 = s[0..4].parse().unwrap();
    let mo: u32 = s[5..7].parse().unwrap();
    let d: u32 = s[8..10].parse().unwrap();
    let h: u32 = s[11..13].parse().unwrap();
    let mi: u32 = s[14..16].parse().unwrap();
    let se: u32 = s[17..19].parse().unwrap();
    date_to_days(y,mo,d)*86400 + (h as i64)*3600 + (mi as i64)*60 + (se as i64)
}

fn fmt_off(off: i32) -> String {
    let sign = if off >= 0 {'+'} else {'-'};
    let a = off.unsigned_abs();
    let h = a/3600; let m = (a%3600)/60; let s = a%60;
    if s != 0 { format!("{}{:02}:{:02}:{:02}", sign, h, m, s) }
    else { format!("{}{:02}:{:02}", sign, h, m) }
}

fn format_local(t: i64, off: i32) -> String {
    let local = t + off as i64;
    let (y,m,d) = days_to_date(local.div_euclid(86400));
    let tod = local.rem_euclid(86400);
    let h = tod/3600; let mi = (tod%3600)/60; let s = tod%60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}{}", y,m,d,h,mi,s, fmt_off(off))
}

fn get_all_trans_times(tz: &TzifData, lo: i64, hi: i64) -> Vec<i64> {
    let mut times: Vec<i64> = Vec::new();
    for &(t,_) in &tz.transitions {
        if t >= lo && t <= hi { times.push(t); }
    }
    let last_exp = tz.transitions.last().map(|(t,_)|*t).unwrap_or(i64::MIN);
    if let Some(ref p) = tz.posix {
        if p.dst_name.is_some() && p.start.is_some() && p.end.is_some() {
            let yl = year_from_unix(lo.max(last_exp+1)) - 2;
            let yh = year_from_unix(hi) + 2;
            for yr in yl..=yh {
                if let Some((st,et)) = posix_transitions(yr, p) {
                    if st > last_exp && st >= lo && st <= hi { times.push(st); }
                    if et > last_exp && et >= lo && et <= hi { times.push(et); }
                }
            }
        }
    }
    times.sort();
    times.dedup();
    times
}

fn local_to_utc(wall: i64, tz: &TzifData) -> Vec<(i64,i32,String)> {
    let lo = wall - 300000;
    let hi = wall + 300000;
    let tt = get_all_trans_times(tz, lo, hi);
    let mut results = Vec::new();
    // before first transition
    {
        let (off, ab) = tz.get_type_at(lo);
        let cand = wall - off as i64;
        let t_end = tt.first().copied().unwrap_or(i64::MAX);
        if cand >= lo && cand < t_end {
            results.push((cand, off, ab));
        }
    }
    // intervals between transitions
    for i in 0..tt.len() {
        let t_start = tt[i];
        let t_end = if i+1 < tt.len() { tt[i+1] } else { i64::MAX };
        let (off, ab) = tz.get_type_at(t_start);
        let cand = wall - off as i64;
        if cand >= t_start && cand < t_end {
            results.push((cand, off, ab));
        }
    }
    results.sort_by_key(|&(t,_,_)| t);
    results
}

fn find_gap(wall: i64, tz: &TzifData) -> (i64, i32) {
    let lo = wall - 300000;
    let hi = wall + 300000;
    let tt = get_all_trans_times(tz, lo, hi);
    for &t in &tt {
        let off_before = tz.get_type_at(t - 1).0;
        let off_after = tz.get_type_at(t).0;
        if off_after > off_before {
            let gs = t + off_before as i64;
            let ge = t + off_after as i64;
            if wall >= gs && wall < ge {
                return (t, off_before);
            }
        }
    }
    // fallback
    (wall, 0)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let mut cache: HashMap<String, TzifData> = HashMap::new();
    let mut out = String::new();
    for line in content.lines() {
        if line.trim().is_empty() { continue; }
        let parts: Vec<&str> = line.split(' ').collect();
        let qt = parts[0];
        let fnm = parts[1];
        if !cache.contains_key(fnm) {
            cache.insert(fnm.to_string(), parse_tzif(&format!("{}/{}", dir, fnm)));
        }
        let tz = cache.get(fnm).unwrap();
        match qt {
            "UTC" => {
                let t: i64 = parts[2].parse().unwrap();
                let (off, ab) = tz.get_type_at(t);
                let ls = format_local(t, off);
                out.push_str(&format!("{} -> {} {}\n", line, ls, ab));
            }
            "LOCAL" => {
                let wall = parse_wall(parts[2]);
                let res = local_to_utc(wall, tz);
                if res.len() == 1 {
                    let (t, off, ref ab) = res[0];
                    out.push_str(&format!("{} -> {} {} {}\n", line, t, fmt_off(off), ab));
                } else if res.len() >= 2 {
                    let (t1, o1, ref a1) = res[0];
                    let (t2, o2, ref a2) = res[1];
                    out.push_str(&format!("{} -> {} {} {} | {} {} {}\n",
                        line, t1, fmt_off(o1), a1, t2, fmt_off(o2), a2));
                } else {
                    let (t, _off_before) = find_gap(wall, tz);
                    let (off, ab) = tz.get_type_at(t);
                    let ls = format_local(t, off);
                    out.push_str(&format!("{} -> GAP {} {} {}\n", line, t, ls, ab));
                }
            }
            _ => {}
        }
    }
    print!("{}", out);
}

use std::env;
use std::fs;
use std::collections::HashMap;

fn read_i32_be(d: &[u8], p: usize) -> i32 {
    i32::from_be_bytes([d[p], d[p+1], d[p+2], d[p+3]])
}
fn read_i64_be(d: &[u8], p: usize) -> i64 {
    i64::from_be_bytes([d[p],d[p+1],d[p+2],d[p+3],d[p+4],d[p+5],d[p+6],d[p+7]])
}

#[derive(Clone)]
struct TzType { utc_offset: i32, isdst: bool, abbr_idx: u8 }

#[derive(Clone)]
struct RuleTime { month: u32, week: u32, day: u32, time: i32 }

#[derive(Clone)]
struct PosixRule {
    std_name: String,
    std_offset: i32,
    dst_name: Option<String>,
    dst_offset: Option<i32>,
    start: Option<RuleTime>,
    end: Option<RuleTime>,
}

#[derive(Clone)]
struct TzifData {
    transitions: Vec<(i64, usize)>,
    types: Vec<TzType>,
    abbrs_data: Vec<u8>,
    posix: Option<PosixRule>,
}

impl TzifData {
    fn get_abbr(&self, idx: u8) -> String {
        let s = idx as usize;
        let mut e = s;
        while e < self.abbrs_data.len() && self.abbrs_data[e] != 0 { e += 1; }
        String::from_utf8_lossy(&self.abbrs_data[s..e]).to_string()
    }

    fn get_type_at(&self, t: i64) -> (i32, String) {
        if self.transitions.is_empty() {
            if self.posix.is_some() { return self.footer_type(t); }
            let ty = &self.types[0];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }
        if t < self.transitions[0].0 {
            let ty = &self.types[0];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }
        let last_t = self.transitions.last().unwrap().0;
        if t >= last_t {
            return self.footer_type(t);
        }
        let mut lo = 0usize; let mut hi = self.transitions.len();
        while lo < hi {
            let mid = (lo+hi)/2;
            if self.transitions[mid].0 <= t { lo = mid+1; } else { hi = mid; }
        }
        let ti = self.transitions[lo-1].1;
        let ty = &self.types[ti];
        (ty.utc_offset, self.get_abbr(ty.abbr_idx))
    }

    fn footer_type(&self, t: i64) -> (i32, String) {
        let p = match &self.posix { Some(p) => p, None => {
            let ti = self.transitions.last().unwrap().1;
            let ty = &self.types[ti];
            return (ty.utc_offset, self.get_abbr(ty.abbr_idx));
        }};
        let dst_off = -(p.dst_offset.unwrap_or(p.std_offset - 3600));
        let std_off = -p.std_offset;
        if p.dst_name.is_none() || p.start.is_none() || p.end.is_none() {
            return (std_off, p.std_name.clone());
        }
        let yr = year_from_unix(t);
        let (st, et) = match posix_transitions(yr, p) { Some(x) => x, None => return (std_off, p.std_name.clone()) };
        if st <= et {
            if t >= st && t < et { (dst_off, p.dst_name.clone().unwrap()) }
            else { (std_off, p.std_name.clone()) }
        } else {
            if t >= st || t < et { (dst_off, p.dst_name.clone().unwrap()) }
            else { (std_off, p.std_name.clone()) }
        }
    }
}

fn parse_tzif(path: &str) -> TzifData {
    let data = fs::read(path).unwrap();
    // Block 1 header: 44 bytes total
    // magic(4) + version(1) + unused(15) + 6*count(24) = 44
    // Counts at offsets 20,24,28,32,36,40
    let isutcnt  = read_i32_be(&data, 20) as usize;
    let isstdcnt = read_i32_be(&data, 24) as usize;
    let leapcnt  = read_i32_be(&data, 28) as usize;
    let timecnt  = read_i32_be(&data, 32) as usize;
    let typecnt  = read_i32_be(&data, 36) as usize;
    let charcnt  = read_i32_be(&data, 40) as usize;

    // Block 1 data starts at offset 44
    let mut pos = 44usize;
    pos += timecnt * 4;   // 32-bit transition times
    pos += timecnt;       // type indices
    pos += typecnt * 6;   // local time type records
    pos += charcnt;       // abbreviation chars
    pos += leapcnt * 8;   // leap second records (4+4)
    pos += isstdcnt;
    pos += isutcnt;

    // Block 2 header: 44 bytes at current pos
    let isutcnt2  = read_i32_be(&data, pos + 20) as usize;
    let isstdcnt2 = read_i32_be(&data, pos + 24) as usize;
    let leapcnt2  = read_i32_be(&data, pos + 28) as usize;
    let timecnt2  = read_i32_be(&data, pos + 32) as usize;
    let typecnt2  = read_i32_be(&data, pos + 36) as usize;
    let charcnt2  = read_i32_be(&data, pos + 40) as usize;

    // Block 2 data starts after the 44-byte header
    pos += 44;

    let mut trans_times = Vec::with_capacity(timecnt2);
    for _ in 0..timecnt2 { trans_times.push(read_i64_be(&data, pos)); pos += 8; }
    let mut trans_types = Vec::with_capacity(timecnt2);
    for _ in 0..timecnt2 { trans_types.push(data[pos] as usize); pos += 1; }
    let transitions: Vec<(i64,usize)> = trans_times.into_iter().zip(trans_types).collect();

    let mut types = Vec::with_capacity(typecnt2);
    for _ in 0..typecnt2 {
        let off = read_i32_be(&data, pos); pos += 4;
        let dst = data[pos] != 0; pos += 1;
        let ai = data[pos]; pos += 1;
        types.push(TzType{utc_offset:off, isdst:dst, abbr_idx:ai});
    }
    let abbrs_data = data[pos..pos+charcnt2].to_vec();
    pos += charcnt2;
    pos += leapcnt2 * 12; // leap second records (8+4)
    pos += isstdcnt2;
    pos += isutcnt2;

    // Footer: \n POSIX-string \n
    if pos < data.len() && data[pos] == b'\n' { pos += 1; }
    let fs_pos = pos;
    while pos < data.len() && data[pos] != b'\n' { pos += 1; }
    let posix_str = String::from_utf8_lossy(&data[fs_pos..pos]).to_string();
    let posix = if posix_str.is_empty() { None } else { Some(parse_posix(&posix_str)) };

    TzifData { transitions, types, abbrs_data, posix }
}

fn parse_posix(s: &str) -> PosixRule {
    let c: Vec<char> = s.chars().collect();
    let mut p = 0usize;
    let std_name = parse_name(&c, &mut p);
    let std_offset = parse_offset(&c, &mut p);
    let mut dst_name = None;
    let mut dst_offset = None;
    let mut start = None;
    let mut end = None;
    if p < c.len() && (c[p].is_alphabetic() || c[p] == '<') {
        dst_name = Some(parse_name(&c, &mut p));
        if p < c.len() && (c[p]=='+' || c[p]=='-' || c[p].is_ascii_digit()) {
            dst_offset = Some(parse_offset(&c, &mut p));
        } else {
            dst_offset = Some(std_offset - 3600);
        }
        if p < c.len() && c[p] == ',' {
            p += 1;
            start = Some(parse_rule_time(&c, &mut p));
            if p < c.len() && c[p] == ',' {
                p += 1;
                end = Some(parse_rule_time(&c, &mut p));
            }
        }
    }
    PosixRule { std_name, std_offset, dst_name, dst_offset, start, end }
}

fn parse_name(c: &[char], p: &mut usize) -> String {
    if *p < c.len() && c[*p] == '<' {
        *p += 1;
        let s = *p;
        while *p < c.len() && c[*p] != '>' { *p += 1; }
        let r: String = c[s..*p].iter().collect();
        *p += 1;
        r
    } else {
        let s = *p;
        while *p < c.len() && c[*p].is_alphabetic() { *p += 1; }
        c[s..*p].iter().collect()
    }
}

fn parse_offset(c: &[char], p: &mut usize) -> i32 {
    let mut sign = 1i32;
    if *p < c.len() && c[*p] == '-' { sign = -1; *p += 1; }
    else if *p < c.len() && c[*p] == '+' { *p += 1; }
    let mut h = 0i32;
    while *p < c.len() && c[*p].is_ascii_digit() { h = h*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
    let mut m = 0i32; let mut s = 0i32;
    if *p < c.len() && c[*p] == ':' {
        *p += 1;
        while *p < c.len() && c[*p].is_ascii_digit() { m = m*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
        if *p < c.len() && c[*p] == ':' {
            *p += 1;
            while *p < c.len() && c[*p].is_ascii_digit() { s = s*10 + (c[*p] as i32 - '0' as i32); *p += 1; }
        }
    }
    sign * (h*3600 + m*60 + s)
}

fn parse_rule_time(c: &[char], p: &mut usize) -> RuleTime {
    assert_eq!(c[*p], 'M'); *p += 1;
    let month = parse_num(c, p);
    assert_eq!(c[*p], '.'); *p += 1;
    let week = parse_num(c, p);
    assert_eq!(c[*p], '.'); *p += 1;
    let day = parse_num(c, p);
    let time = if *p < c.len() && c[*p] == '/' { *p += 1; parse_offset(c, p) } else { 7200 };
    RuleTime { month, week, day, time }
}

fn parse_num(c: &[char], p: &mut usize) -> u32 {
    let mut v = 0u32;
    while *p < c.len() && c[*p].is_ascii_digit() { v = v*10 + (c[*p] as u32 - '0' as u32); *p += 1; }
    v
}

fn posix_transitions(year: i32, p: &PosixRule) -> Option<(i64, i64)> {
    let sr = p.start.as_ref()?;
    let er = p.end.as_ref()?;
    let (sy,sm,sd) = mwd_to_date(year, sr.month, sr.week, sr.day);
    let (ey,em,ed) = mwd_to_date(year, er.month, er.week, er.day);
    let st = date_to_days(sy,sm,sd)*86400 + sr.time as i64 + p.std_offset as i64;
    let dso = p.dst_offset.unwrap_or(p.std_offset - 3600);
    let et = date_to_days(ey,em,ed)*86400 + er.time as i64 + dso as i64;
    Some((st, et))
}

fn mwd_to_date(year: i32, month: u32, week: u32, day: u32) -> (i32,u32,u32) {
    let first_dow = day_of_week(year, month, 1);
    let first_occ = 1 + ((day as i32 - first_dow as i32 + 7) % 7) as u32;
    if week <= 4 {
        (year, month, first_occ + (week-1)*7)
    } else {
        let last_day = days_in_month(year, month);
        let last_dow = day_of_week(year, month, last_day);
        let back = (last_dow as i32 - day as i32 + 7) % 7;
        (year, month, last_day - back as u32)
    }
}

fn days_in_month(y: i32, m: u32) -> u32 {
    match m {
        1|3|5|7|8|10|12 => 31,
        4|6|9|11 => 30,
        2 => if is_leap(y) {29} else {28},
        _ => 30,
    }
}

fn is_leap(y: i32) -> bool {
    (y%4==0 && y%100!=0) || y%400==0
}

fn day_of_week(y: i32, m: u32, d: u32) -> u32 {
    let dd = date_to_days(y, m, d);
    (((dd + 4) % 7 + 7) % 7) as u32
}

fn date_to_days(y: i32, m: u32, d: u32) -> i64 {
    let yy = y - if m <= 2 {1} else {0};
    let era = if yy >= 0 {yy} else {yy-399} / 400;
    let yoe = (yy - era*400) as i64;
    let mp = ((m + 9) % 12) as i64;
    let doy = (153*mp+2)/5 + d as i64 - 1;
    let doe = yoe*365 + yoe/4 - yoe/100 + doy;
    era as i64 * 146097 + doe - 719468
}

fn days_to_date(days: i64) -> (i32,u32,u32) {
    let z = days + 719468;
    let era = if z >= 0 {z} else {z-146096} / 146097;
    let doe = (z - era*146097) as u64;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    let y = yoe as i64 + era*400;
    let mp = (5*doe+2)/153;
    let d = doe - (153*mp+2)/5 + 1;
    let m = if mp < 10 {mp+3} else {mp-9};
    let year = (y + if m <= 2 {1} else {0}) as i32;
    (year, m as u32, d as u32)
}

fn year_from_unix(t: i64) -> i32 {
    let d = t.div_euclid(86400);
    days_to_date(d).0
}

fn parse_wall(s: &str) -> i64 {
    let y: i32 = s[0..4].parse().unwrap();
    let mo: u32 = s[5..7].parse().unwrap();
    let d: u32 = s[8..10].parse().unwrap();
    let h: u32 = s[11..13].parse().unwrap();
    let mi: u32 = s[14..16].parse().unwrap();
    let se: u32 = s[17..19].parse().unwrap();
    date_to_days(y,mo,d)*86400 + (h as i64)*3600 + (mi as i64)*60 + (se as i64)
}

fn fmt_off(off: i32) -> String {
    let sign = if off >= 0 {'+'} else {'-'};
    let a = off.unsigned_abs();
    let h = a/3600; let m = (a%3600)/60; let s = a%60;
    if s != 0 { format!("{}{:02}:{:02}:{:02}", sign, h, m, s) }
    else { format!("{}{:02}:{:02}", sign, h, m) }
}

fn format_local(t: i64, off: i32) -> String {
    let local = t + off as i64;
    let (y,m,d) = days_to_date(local.div_euclid(86400));
    let tod = local.rem_euclid(86400);
    let h = tod/3600; let mi = (tod%3600)/60; let s = tod%60;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}{}", y,m,d,h,mi,s, fmt_off(off))
}

fn get_all_trans_times(tz: &TzifData, lo: i64, hi: i64) -> Vec<i64> {
    let mut times: Vec<i64> = Vec::new();
    for &(t,_) in &tz.transitions {
        if t >= lo && t <= hi { times.push(t); }
    }
    let last_exp = tz.transitions.last().map(|(t,_)|*t).unwrap_or(i64::MIN);
    if let Some(ref p) = tz.posix {
        if p.dst_name.is_some() && p.start.is_some() && p.end.is_some() {
            let yl = year_from_unix(lo.max(last_exp+1)) - 3;
            let yh = year_from_unix(hi) + 3;
            for yr in yl..=yh {
                if let Some((st,et)) = posix_transitions(yr, p) {
                    if st > last_exp && st >= lo && st <= hi { times.push(st); }
                    if et > last_exp && et >= lo && et <= hi { times.push(et); }
                }
            }
        }
    }
    times.sort();
    times.dedup();
    times
}

fn local_to_utc(wall: i64, tz: &TzifData) -> Vec<(i64,i32,String)> {
    let lo = wall - 400000;
    let hi = wall + 400000;
    let tt = get_all_trans_times(tz, lo, hi);
    let mut results: Vec<(i64,i32,String)> = Vec::new();

    // Before first transition in range (or before all transitions)
    {
        let (off, ab) = tz.get_type_at(lo);
        let cand = wall - off as i64;
        let t_end = tt.first().copied().unwrap_or(i64::MAX);
        if cand >= lo && cand < t_end {
            results.push((cand, off, ab));
        }
    }
    // Intervals between transitions
    for i in 0..tt.len() {
        let t_start = tt[i];
        let t_end = if i+1 < tt.len() { tt[i+1] } else { i64::MAX };
        let (off, ab) = tz.get_type_at(t_start);
        let cand = wall - off as i64;
        if cand >= t_start && cand < t_end {
            results.push((cand, off, ab));
        }
    }
    results.sort_by_key(|&(t,_,_)| t);
    results
}

fn find_gap(wall: i64, tz: &TzifData) -> (i64, i32) {
    let lo = wall - 400000;
    let hi = wall + 400000;
    let tt = get_all_trans_times(tz, lo, hi);
    for &t in &tt {
        let off_before = tz.get_type_at(t - 1).0;
        let off_after = tz.get_type_at(t).0;
        if off_after > off_before {
            let gs = t + off_before as i64;
            let ge = t + off_after as i64;
            if wall >= gs && wall < ge {
                return (t, off_before);
            }
        }
    }
    // fallback: find any transition that creates a gap containing wall
    for &t in &tt {
        let off_before = tz.get_type_at(t - 1).0;
        let off_after = tz.get_type_at(t).0;
        if off_after > off_before {
            let gs = t + off_before as i64;
            let ge = t + off_after as i64;
            if wall >= gs && wall < ge {
                return (t, off_before);
            }
        }
    }
    (wall, 0)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let mut cache: HashMap<String, TzifData> = HashMap::new();
    let mut out = String::new();
    for line in content.lines() {
        if line.trim().is_empty() { continue; }
        let parts: Vec<&str> = line.split(' ').collect();
        let qt = parts[0];
        let fnm = parts[1];
        if !cache.contains_key(fnm) {
            cache.insert(fnm.to_string(), parse_tzif(&format!("{}/{}", dir, fnm)));
        }
        let tz = cache.get(fnm).unwrap();
        match qt {
            "UTC" => {
                let t: i64 = parts[2].parse().unwrap();
                let (off, ab) = tz.get_type_at(t);
                let ls = format_local(t, off);
                out.push_str(&format!("{} -> {} {}\n", line, ls, ab));
            }
            "LOCAL" => {
                let wall = parse_wall(parts[2]);
                let res = local_to_utc(wall, tz);
                if res.len() == 1 {
                    let (t, off, ref ab) = res[0];
                    out.push_str(&format!("{} -> {} {} {}\n", line, t, fmt_off(off), ab));
                } else if res.len() >= 2 {
                    let (t1, o1, ref a1) = res[0];
                    let (t2, o2, ref a2) = res[1];
                    out.push_str(&format!("{} -> {} {} {} | {} {} {}\n",
                        line, t1, fmt_off(o1), a1, t2, fmt_off(o2), a2));
                } else {
                    let (t, off_before) = find_gap(wall, tz);
                    let _ = off_before;
                    let (off, ab) = tz.get_type_at(t);
                    let ls = format_local(t, off);
                    out.push_str(&format!("{} -> GAP {} {} {}\n", line, t, ls, ab));
                }
            }
            _ => {}
        }
    }
    print!("{}", out);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* ─── Big-endian readers ─── */
static int32_t rbe32(const uint8_t *p){return (int32_t)((uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3]);}
static int64_t rbe64(const uint8_t *p){return ((int64_t)rbe32(p)<<32)|(uint32_t)rbe32(p+4);}

/* ─── Proleptic Gregorian helpers ─── */
static int is_leap(int y){return (y%4==0&&y%100!=0)||(y%400==0);}
static int dim(int y,int m){static const int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return m==2&&is_leap(y)?29:d[m-1];}

static int64_t days_from_civil(int y,int m,int d){
    y-=(m<=2);
    int64_t era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153*(m+(m>2?-3:9))+2)/5+d-1;
    unsigned doe=yoe*365+yoe/4-yoe/100+doy;
    return era*146097+(int64_t)doe-719468;
}
static void civil_from_days(int64_t z,int *yy,int *mm,int *dd){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460+doe/36524-doe/146096)/365;
    int64_t yr=(int64_t)yoe+era*400;
    unsigned doy=doe-(365*yoe+yoe/4-yoe/100);
    unsigned mp=(5*doy+2)/153;
    unsigned dd2=doy-(153*mp+2)/5+1;
    unsigned mm2=mp+(mp<10?3:-9);
    yr+=(mm2<=2);
    *yy=(int)yr;*mm=(int)mm2;*dd=(int)dd2;
}
static int dow(int64_t days){int d=(int)((days+4)%7);if(d<0)d+=7;return d;}

static int find_mwd(int year,int m,int w,int d){
    int64_t fd=days_from_civil(year,m,1);
    int fdow=dow(fd);
    int delta=(d-fdow+7)%7;
    int first=1+delta;
    if(w==5){int dm=dim(year,m);return first+7*((dm-first)/7);}
    return first+7*(w-1);
}

/* ─── TZ data structures ─── */
typedef struct{int64_t utc_off;int isdst;char abbr[64];}LTT;
typedef struct{int64_t time;int tidx;}Trans;
typedef struct{int m,w,d;int tod;}Rule;
typedef struct{
    char std_abbr[64],dst_abbr[64];
    int64_t std_off,dst_off;
    int has_dst,has_rules;
    Rule start,end;
}Footer;
typedef struct{
    Trans *tr;int ntr;
    LTT *lt;int nlt;
    Footer ft;int has_ft;
    int64_t first_tr,last_tr;
}TZData;

/* ─── POSIX TZ string parser ─── */
static int p_name(const char*s,int pos,char*nm){
    if(s[pos]=='<'){
        pos++;int st=pos;
        while(s[pos]&&s[pos]!='>')pos++;
        if(s[pos]!='>')return -1;
        int len=pos-st;memcpy(nm,s+st,len);nm[len]=0;pos++;
    }else{
        int st=pos;
        while(isalpha((unsigned char)s[pos]))pos++;
        int len=pos-st;if(len<3)return -1;
        memcpy(nm,s+st,len);nm[len]=0;
    }
    return pos;
}
static int p_off(const char*s,int pos,int64_t*v){
    int sign=1;
    if(s[pos]=='+')pos++;else if(s[pos]=='-'){sign=-1;pos++;}
    int h=0,m=0,sc=0;
    while(isdigit((unsigned char)s[pos])){h=h*10+(s[pos]-'0');pos++;}
    if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){m=m*10+(s[pos]-'0');pos++;}}
    if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){sc=sc*10+(s[pos]-'0');pos++;}}
    *v=sign*(h*3600+m*60+sc);
    return pos;
}
static int p_rule(const char*s,int pos,Rule*r){
    if(s[pos]!='M')return -1;pos++;
    r->m=0;while(isdigit((unsigned char)s[pos])){r->m=r->m*10+(s[pos]-'0');pos++;}
    if(s[pos]!='.')return -1;pos++;
    r->w=0;while(isdigit((unsigned char)s[pos])){r->w=r->w*10+(s[pos]-'0');pos++;}
    if(s[pos]!='.')return -1;pos++;
    r->d=0;while(isdigit((unsigned char)s[pos])){r->d=r->d*10+(s[pos]-'0');pos++;}
    r->tod=7200;
    if(s[pos]=='/'){
        pos++;int sign=1;
        if(s[pos]=='+')pos++;else if(s[pos]=='-'){sign=-1;pos++;}
        int h=0,m=0,sc=0;
        while(isdigit((unsigned char)s[pos])){h=h*10+(s[pos]-'0');pos++;}
        if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){m=m*10+(s[pos]-'0');pos++;}}
        if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){sc=sc*10+(s[pos]-'0');pos++;}}
        r->tod=sign*(h*3600+m*60+sc);
    }
    return pos;
}
static int parse_footer(const char*s,Footer*f){
    memset(f,0,sizeof(*f));
    int pos=p_name(s,0,f->std_abbr);if(pos<0)return -1;
    int64_t ov;pos=p_off(s,pos,&ov);if(pos<0)return -1;
    f->std_off=-ov;
    if(!s[pos]){f->has_dst=0;return 0;}
    pos=p_name(s,pos,f->dst_abbr);if(pos<0)return -1;
    f->has_dst=1;
    if(s[pos]=='+'||s[pos]=='-'||isdigit((unsigned char)s[pos])){
        pos=p_off(s,pos,&ov);if(pos<0)return -1;
        f->dst_off=-ov;
    }else{
        f->dst_off=f->std_off+3600;
    }
    if(s[pos]==','){
        pos++;
        pos=p_rule(s,pos,&f->start);if(pos<0)return -1;
        if(s[pos]!=',')return -1;pos++;
        pos=p_rule(s,pos,&f->end);if(pos<0)return -1;
        f->has_rules=1;
    }
    return 0;
}

/* ─── TZif file parser ─── */
static uint8_t* read_file(const char*path,size_t*len){
    FILE*fp=fopen(path,"rb");if(!fp)return NULL;
    fseek(fp,0,SEEK_END);*len=(size_t)ftell(fp);fseek(fp,0,SEEK_SET);
    uint8_t*buf=(uint8_t*)malloc(*len);
    if(fread(buf,1,*len,fp)!==*len){free(buf);fclose(fp);return NULL;}
    fclose(fp);return buf;
}
static TZData* parse_tzif(const char*path){
    size_t flen;uint8_t*buf=read_file(path,&flen);
    if(!buf)return NULL;
    /* skip first block */
    if(flen<44){free(buf);return NULL;}
    int tcnt1=rbe32(buf+24+3*4); /* timecnt of block1 */
    int lcnt1=rbe32(buf+24+2*4);
    int isdcnt1=rbe32(buf+24+1*4);
    int isucnt1=rbe32(buf+24+0*4);
    int tycnt1=rbe32(buf+24+4*4);
    int chcnt1=rbe32(buf+24+5*4);
    size_t off=44;
    off+=(size_t)tcnt1*4+(size_t)tcnt1*1+(size_t)tycnt1*6+(size_t)chcnt1;
    off+=(size_t)lcnt1*8+(size_t)isdcnt1+(size_t)isucnt1;
    /* second block header */
    if(off+44>flen){free(buf);return NULL;}
    const uint8_t*h2=buf+off;
    int isucnt=rbe32(h2+24+0*4);
    int isdcnt=rbe32(h2+24+1*4);
    int lcnt=rbe32(h2+24+2*4);
    int tcnt=rbe32(h2+24+3*4);
    int tycnt=rbe32(h2+24+4*4);
    int chcnt=rbe32(h2+24+5*4);
    off+=44;
    TZData*tz=(TZData*)calloc(1,sizeof(TZData));
    tz->ntr=tcnt;tz->nlt=tycnt;
    tz->tr=(Trans*)malloc(sizeof(Trans)*(tcnt>0?tcnt:1));
    tz->lt=(LTT*)malloc(sizeof(LTT)*(tycnt>0?tycnt:1));
    /* transition times (64-bit) */
    for(int i=0;i<tcnt;i++){tz->tr[i].time=rbe64(buf+off);off+=8;}
    /* type indices */
    for(int i=0;i<tcnt;i++){tz->tr[i].tidx=buf[off];off++;}
    /* local time types */
    for(int i=0;i<tycnt;i++){
        tz->lt[i].utc_off=rbe32(buf+off);off+=4;
        tz->lt[i].isdst=buf[off];off++;
        tz->lt[i].abbr[0]=0;/* fill later */
    }
    /* abbreviation chars */
    const uint8_t*abchars=buf+off;off+=chcnt;
    for(int i=0;i<tycnt;i++){
        int ai=buf[off-tycnt*6+4+i*6+1];/* recompute: we already advanced off */
    }
    /* re-read abbreviation indices */
    off-=(size_t)chcnt;
    for(int i=0;i<tycnt;i++){
        int ai=buf[off+tycnt*6-tycnt*6+i*6+1];
    }
    /* Let me redo this properly */
    off=off;/* hmm let me recalculate */
    /* Actually let me re-parse from a known offset */
    /* I'll recompute: after the 44-byte header, transitions, type indices, type records */
    size_t base=off-(size_t)tcnt*8-(size_t)tcnt*1-(size_t)tycnt*6;
    /* type records start at base + tcnt*8 + tcnt */
    size_t tr_base=base+44;
    size_t ti_base=tr_base+(size_t)tcnt*8;
    size_t lt_base=ti_base+(size_t)tcnt;
    for(int i=0;i<tycnt;i++){
        int ai=buf[lt_base+i*6+1];
        const char*ap=(const char*)buf+lt_base+(size_t)tycnt*6+ai;
        strncpy(tz->lt[i].abbr,ap,63);tz->lt[i].abbr[63]=0;
    }
    off=lt_base+(size_t)tycnt*6+(size_t)chcnt;
    /* skip leap seconds, isstd, isut */
    off+=(size_t)lcnt*12+(size_t)isdcnt+(size_t)isucnt;
    /* footer: newline, POSIX string, newline */
    if(off<flen&&buf[off]=='\n')off++;
    if(off<flen){
        char ftbuf[512]={0};
        int fi=0;
        while(off<flen&&buf[off]!='\n'&&fi<511){ftbuf[fi++]=buf[off++];}
        ftbuf[fi]=0;
        if(fi>0){
            if(parse_footer(ftbuf,&tz->ft)==0)tz->has_ft=1;
        }
    }
    tz->first_tr=tcnt>0?tz->tr[0].time:0;
    tz->last_tr=tcnt>0?tz->tr[tcnt-1].time:0;
    free(buf);
    return tz;
}

/* ─── Determine type at time t ─── */
static int64_t comp_start_utc(int yr,Footer*f){
    int d=find_mwd(yr,f->start.m,f->start.w,f->start.d);
    int64_t ls=days_from_civil(yr,f->start.m,d)*86400+f->start.tod;
    return ls-f->std_off;
}
static int64_t comp_end_utc(int yr,Footer*f){
    int d=find_mwd(yr,f->end.m,f->end.w,f->end.d);
    int64_t ls=days_from_civil(yr,f->end.m,d)*86400+f->end.tod;
    return ls-f->dst_off;
}
static int is_dst_at(int64_t t,Footer*f){
    if(!f->has_dst||!f->has_rules)return 0;
    int64_t ls=t+f->std_off;
    int64_t dy=ls/86400;if(ls%86400<0)dy--;
    int y,m,d;civil_from_days(dy,&y,&m,&d);
    for(int dy2=-1;dy2<=1;dy2++){
        int yr=y+dy2;
        int64_t su=comp_start_utc(yr,f);
        int64_t eu=comp_end_utc(yr,f);
        if(su<eu){if(t>=su&&t<eu)return 1;}
        else if(su>eu){if(t>=su||t<eu)return 1;}
        else{return 1;}
    }
    return 0;
}
static void get_type_at(int64_t t,TZData*tz,int64_t*off_out,const char**ab_out){
    if(tz->ntr==0){
        if(tz->has_ft){
            if(is_dst_at(t,&tz->ft)){*off_out=tz->ft.dst_off;*ab_out=tz->ft.dst_abbr;}
            else{*off_out=tz->ft.std_off;*ab_out=tz->ft.std_abbr;}
        }else{*off_out=tz->lt[0].utc_off;*ab_out=tz->lt[0].abbr;}
        return;
    }
    if(t<tz->tr[0].time){*off_out=tz->lt[0].utc_off;*ab_out=tz->lt[0].abbr;return;}
    if(t>tz->tr[tz->ntr-1].time){
        if(tz->has_ft){
            if(is_dst_at(t,&tz->ft)){*off_out=tz->ft.dst_off;*ab_out=tz->ft.dst_abbr;}
            else{*off_out=tz->ft.std_off;*ab_out=tz->ft.std_abbr;}
        }else{int ti=tz->tr[tz->ntr-1].tidx;*off_out=tz->lt[ti].utc_off;*ab_out=tz->lt[ti].abbr;}
        return;
    }
    /* binary search: last i with tr[i].time <= t */
    int lo=0,hi=tz->ntr-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->tr[mid].time<=t)lo=mid;else hi=mid-1;}
    int ti=tz->tr[lo].tidx;
    *off_out=tz->lt[ti].utc_off;*ab_out=tz->lt[ti].abbr;
}

/* ─── Formatting ─── */
static void fmt_offset(int64_t off,char*buf){
    char sign=off<0?'-':'+';
    if(off<0)off=-off;
    int h=(int)(off/3600),m=(int)((off%3600)/60),s=(int)(off%60);
    if(s)sprintf(buf,"%c%02d:%02d:%02d",sign,h,m,s);
    else sprintf(buf,"%c%02d:%02d",sign,h,m);
}
static void fmt_local(int64_t local_secs,char*buf){
    int64_t dy=local_secs/86400;if(local_secs%86400<0)dy--;
    int sod=(int)(local_secs-dy*86400);
    int y,m,d;civil_from_days(dy,&y,&m,&d);
    sprintf(buf,"%04d-%02d-%02dT%02d:%02d:%02d",y,m,d,sod/3600,(sod%3600)/60,sod%60);
}

/* ─── UTC query ─── */
static void do_utc(int64_t t,TZData*tz,char*out){
    int64_t off;const char*ab;
    get_type_at(t,tz,&off,&ab);
    int64_t ls=t+off;
    char lbuf[64],obuf[32];
    fmt_local(ls,lbuf);
    fmt_offset(off,obuf);
    sprintf(out,"%s%s %s",lbuf,obuf,ab);
}

/* ─── LOCAL query ─── */
static int64_t parse_wall(const char*s){
    int y,mo,d,h,mi,se;
    sscanf(s,"%d-%d-%dT%d:%d:%d",&y,&mo,&d,&h,&mi,&se);
    return days_from_civil(y,mo,d)*86400+h*3600+mi*60+se;
}
static void do_local(const char*wall,TZData*tz,const char*query,char*out){
    int64_t W=parse_wall(wall);
    /* collect candidate offsets */
    int64_t cands[512];int nc=0;
    for(int i=0;i<tz->nlt;i++){
        int dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->lt[i].utc_off){dup=1;break;}
        if(!dup)cands[nc++]=tz->lt[i].utc_off;
    }
    if(tz->has_ft){
        int dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->ft.std_off){dup=1;break;}
        if(!dup)cands[nc++]=tz->ft.std_off;
        if(tz->ft.has_dst){
            dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->ft.dst_off){dup=1;break;}
            if(!dup)cands[nc++]=tz->ft.dst_off;
        }
    }
    /* find solutions */
    struct{int64_t t;int64_t off;const char*ab;}sols[4];int ns=0;
    for(int ci=0;ci<nc;ci++){
        int64_t t=W-cands[ci];
        int64_t aoff;const char*aab;
        get_type_at(t,tz,&aoff,&aab);
        if(aoff==cands[ci]){
            int dup=0;for(int j=0;j<ns;j++)if(sols[j].t==t){dup=1;break;}
            if(!dup){sols[ns].t=t;sols[ns].off=aoff;sols[ns].ab=aab;ns++;}
        }
    }
    /* sort by t */
    for(int i=0;i<ns-1;i++)for(int j=i+1;j<ns;j++)if(sols[j].t<sols[i].t){
        struct{int64_t t;int64_t off;const char*ab;}tmp=sols[i];sols[i]=sols[j];sols[j]=tmp;
    }
    if(ns==1){
        char ob[32];fmt_offset(sols[0].off,ob);
        sprintf(out,"%s -> %lld %s %s",query,(long long)sols[0].t,ob,sols[0].ab);
    }else if(ns==2){
        char ob1[32],ob2[32];
        fmt_offset(sols[0].off,ob1);fmt_offset(sols[1].off,ob2);
        sprintf(out,"%s -> %lld %s %s | %lld %s %s",query,
            (long long)sols[0].t,ob1,sols[0].ab,(long long)sols[1].t,ob2,sols[1].ab);
    }else{
        /* gap: find transition causing it */
        int64_t off_before=0;int found=0;
        /* check table transitions */
        for(int i=0;i<tz->ntr&&!found;i++){
            int64_t T=tz->tr[i].time;
            int prev_ti=(i==0)?0:tz->tr[i-1].tidx;
            int next_ti=tz->tr[i].tidx;
            int64_t old_off=tz->lt[prev_ti].utc_off;
            int64_t new_off=tz->lt[next_ti].utc_off;
            if(new_off>old_off){
                int64_t gs=T+old_off,ge=T+new_off;
                if(W>=gs&&W<ge){off_before=old_off;found=1;}
            }
        }
        /* check footer transitions */
        if(!found&&tz->has_ft&&tz->ft.has_dst&&tz->ft.has_rules){
            int64_t ls=W+tz->ft.std_off;
            int64_t dy=ls/86400;if(ls%86400<0)dy--;
            int y,m,d;civil_from_days(dy,&y,&m,&d);
            for(int dy2=-1;dy2<=1&&!found;dy2++){
                int yr=y+dy2;
                /* start transition: std->dst */
                if(tz->ft.dst_off>tz->ft.std_off){
                    int64_t su=comp_start_utc(yr,&tz->ft);
                    int64_t gs=su+tz->ft.std_off,ge=su+tz->ft.dst_off;
                    if(W>=gs&&W<ge){off_before=tz->ft.std_off;found=1;}
                }
                /* end transition: dst->std (could be gap if std>dst, unusual) */
                if(tz->ft.std_off>tz->ft.dst_off){
                    int64_t eu=comp_end_utc(yr,&tz->ft);
                    int64_t gs=eu+tz->ft.dst_off,ge=eu+tz->ft.std_off;
                    if(W>=gs&&W<ge){off_before=tz->ft.dst_off;found=1;}
                }
            }
        }
        /* check boundary after last transition to footer */
        if(!found&&tz->ntr>0&&tz->has_ft){
            int64_t T=tz->tr[tz->ntr-1].time;
            int last_ti=tz->tr[tz->ntr-1].tidx;
            int64_t old_off=tz->lt[last_ti].utc_off;
            int64_t T2=T+1;
            int64_t new_off;const char*tmp;
            get_type_at(T2,tz,&new_off,&tmp);
            if(new_off>old_off){
                int64_t gs=T+old_off,ge=T+new_off;
                if(W>=gs&&W<ge){off_before=old_off;found=1;}
            }
        }
        if(!found){
            /* fallback: use offset 0 */
            off_before=0;found=1;
        }
        int64_t t=W-off_before;
        char lbuf[64],obuf[32];
        do_utc(t,tz,lbuf);/* this gives "local+offset abbr" */
        /* extract local and abbr from lbuf */
        /* actually let's redo: */
        int64_t aoff;const char*aab;
        get_type_at(t,tz,&aoff,&aab);
        int64_t ls2=t+aoff;
        fmt_local(ls2,lbuf);
        fmt_offset(aoff,obuf);
        sprintf(out,"%s -> GAP %lld %s%s %s",query,(long long)t,lbuf,obuf,aab);
    }
}

/* ─── Main ─── */
int main(int argc,char*argv[]){
    if(argc!=2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char qpath[4096];
    snprintf(qpath,sizeof(qpath),"%s/queries.txt",argv[1]);
    FILE*fp=fopen(qpath,"r");
    if(!fp){fprintf(stderr,"cannot open queries.txt\n");return 1;}
    char line[4096];
    /* simple file cache */
    struct{char name[256];TZData*tz;}cache[256];int ncache=0;
    while(fgets(line,sizeof(line),fp)){
        /* strip trailing newline */
        size_t len=strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]=0;
        if(len==0)continue;
        /* parse query */
        char type[16]={0},fname[256]={0},rest[2048]={0};
        int n=sscanf(line,"%15s %255s %2047[^\n]",type,fname,rest);
        if(n<3)continue;
        /* find or load TZData */
        TZData*tz=NULL;
        for(int i=0;i<ncache;i++){if(strcmp(cache[i].name,fname)==0){tz=cache[i].tz;break;}}
        if(!tz){
            char fpath[4096];
            snprintf(fpath,sizeof(fpath),"%s/%s",argv[1],fname);
            tz=parse_tzif(fpath);
            if(!tz){fprintf(stderr,"cannot parse %s\n",fpath);continue;}
            if(ncache<256){strncpy(cache[ncache].name,fname,255);cache[ncache].name[255]=0;cache[ncache].tz=tz;ncache++;}
        }
        char out[4096];
        if(strcmp(type,"UTC")==0){
            int64_t t=(int64_t)atoll(rest);
            char result[256];
            do_utc(t,tz,result);
            sprintf(out,"%s -> %s",line,result);
        }else if(strcmp(type,"LOCAL")==0){
            do_local(rest,tz,line,out);
        }else{
            continue;
        }
        printf("%s\n",out);
    }
    fclose(fp);
    for(int i=0;i<ncache;i++){free(cache[i].tz->tr);free(cache[i].tz->lt);free(cache[i].tz);}
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* ─── Big-endian readers ─── */
static int32_t rbe32(const uint8_t *p){return (int32_t)((uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|p[3]);}
static int64_t rbe64(const uint8_t *p){return ((int64_t)rbe32(p)<<32)|(uint32_t)rbe32(p+4);}

/* ─── Proleptic Gregorian helpers ─── */
static int is_leap(int y){return (y%4==0&&y%100!=0)||(y%400==0);}
static int dim(int y,int m){static const int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return m==2&&is_leap(y)?29:d[m-1];}

static int64_t days_from_civil(int y,int m,int d){
    y-=(m<=2);
    int64_t era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153*(m+(m>2?-3:9))+2)/5+d-1;
    unsigned doe=yoe*365+yoe/4-yoe/100+doy;
    return era*146097+(int64_t)doe-719468;
}
static void civil_from_days(int64_t z,int *yy,int *mm,int *dd){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460+doe/36524-doe/146096)/365;
    int64_t yr=(int64_t)yoe+era*400;
    unsigned doy=doe-(365*yoe+yoe/4-yoe/100);
    unsigned mp=(5*doy+2)/153;
    unsigned dd2=doy-(153*mp+2)/5+1;
    unsigned mm2=mp+(mp<10?3:-9);
    yr+=(mm2<=2);
    *yy=(int)yr;*mm=(int)mm2;*dd=(int)dd2;
}
static int dow(int64_t days){int d=(int)((days+4)%7);if(d<0)d+=7;return d;}

static int find_mwd(int year,int m,int w,int d){
    int64_t fd=days_from_civil(year,m,1);
    int fdow=dow(fd);
    int delta=(d-fdow+7)%7;
    int first=1+delta;
    if(w==5){int dm=dim(year,m);return first+7*((dm-first)/7);}
    return first+7*(w-1);
}

/* ─── TZ data structures ─── */
typedef struct{int64_t utc_off;int isdst;char abbr[64];}LTT;
typedef struct{int64_t time;int tidx;}Trans;
typedef struct{int m,w,d;int tod;}Rule;
typedef struct{
    char std_abbr[64],dst_abbr[64];
    int64_t std_off,dst_off;
    int has_dst,has_rules;
    Rule start,end;
}Footer;
typedef struct{
    Trans *tr;int ntr;
    LTT *lt;int nlt;
    Footer ft;int has_ft;
    int64_t first_tr,last_tr;
}TZData;

typedef struct{int64_t t;int64_t off;const char*ab;}SOL;

/* ─── POSIX TZ string parser ─── */
static int p_name(const char*s,int pos,char*nm){
    if(s[pos]=='<'){
        pos++;int st=pos;
        while(s[pos]&&s[pos]!='>')pos++;
        if(s[pos]!='>')return -1;
        int len=pos-st;memcpy(nm,s+st,len);nm[len]=0;pos++;
    }else{
        int st=pos;
        while(isalpha((unsigned char)s[pos]))pos++;
        int len=pos-st;if(len<3)return -1;
        memcpy(nm,s+st,len);nm[len]=0;
    }
    return pos;
}
static int p_off(const char*s,int pos,int64_t*v){
    int sign=1;
    if(s[pos]=='+')pos++;else if(s[pos]=='-'){sign=-1;pos++;}
    int h=0,m=0,sc=0;
    while(isdigit((unsigned char)s[pos])){h=h*10+(s[pos]-'0');pos++;}
    if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){m=m*10+(s[pos]-'0');pos++;}}
    if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){sc=sc*10+(s[pos]-'0');pos++;}}
    *v=sign*(h*3600+m*60+sc);
    return pos;
}
static int p_rule(const char*s,int pos,Rule*r){
    if(s[pos]!='M')return -1;pos++;
    r->m=0;while(isdigit((unsigned char)s[pos])){r->m=r->m*10+(s[pos]-'0');pos++;}
    if(s[pos]!='.')return -1;pos++;
    r->w=0;while(isdigit((unsigned char)s[pos])){r->w=r->w*10+(s[pos]-'0');pos++;}
    if(s[pos]!='.')return -1;pos++;
    r->d=0;while(isdigit((unsigned char)s[pos])){r->d=r->d*10+(s[pos]-'0');pos++;}
    r->tod=7200;
    if(s[pos]=='/'){
        pos++;int sign=1;
        if(s[pos]=='+')pos++;else if(s[pos]=='-'){sign=-1;pos++;}
        int h=0,m=0,sc=0;
        while(isdigit((unsigned char)s[pos])){h=h*10+(s[pos]-'0');pos++;}
        if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){m=m*10+(s[pos]-'0');pos++;}}
        if(s[pos]==':'){pos++;while(isdigit((unsigned char)s[pos])){sc=sc*10+(s[pos]-'0');pos++;}}
        r->tod=sign*(h*3600+m*60+sc);
    }
    return pos;
}
static int parse_footer(const char*s,Footer*f){
    memset(f,0,sizeof(*f));
    int pos=p_name(s,0,f->std_abbr);if(pos<0)return -1;
    int64_t ov;pos=p_off(s,pos,&ov);if(pos<0)return -1;
    f->std_off=-ov;
    if(!s[pos]){f->has_dst=0;return 0;}
    pos=p_name(s,pos,f->dst_abbr);if(pos<0)return -1;
    f->has_dst=1;
    if(s[pos]=='+'||s[pos]=='-'||isdigit((unsigned char)s[pos])){
        pos=p_off(s,pos,&ov);if(pos<0)return -1;
        f->dst_off=-ov;
    }else{
        f->dst_off=f->std_off+3600;
    }
    if(s[pos]==','){
        pos++;
        pos=p_rule(s,pos,&f->start);if(pos<0)return -1;
        if(s[pos]!=',')return -1;pos++;
        pos=p_rule(s,pos,&f->end);if(pos<0)return -1;
        f->has_rules=1;
    }
    return 0;
}

/* ─── TZif file parser ─── */
static uint8_t* read_file(const char*path,size_t*len){
    FILE*fp=fopen(path,"rb");if(!fp)return NULL;
    fseek(fp,0,SEEK_END);*len=(size_t)ftell(fp);fseek(fp,0,SEEK_SET);
    uint8_t*buf=(uint8_t*)malloc(*len);
    if(fread(buf,1,*len,fp)!=(size_t)*len){free(buf);fclose(fp);return NULL;}
    fclose(fp);return buf;
}
static TZData* parse_tzif(const char*path){
    size_t flen;uint8_t*buf=read_file(path,&flen);
    if(!buf)return NULL;
    if(flen<44){free(buf);return NULL;}
    /* skip first block */
    int isucnt1=rbe32(buf+24+0*4);
    int isdcnt1=rbe32(buf+24+1*4);
    int lcnt1=rbe32(buf+24+2*4);
    int tcnt1=rbe32(buf+24+3*4);
    int tycnt1=rbe32(buf+24+4*4);
    int chcnt1=rbe32(buf+24+5*4);
    size_t off=44;
    off+=(size_t)tcnt1*4+(size_t)tcnt1*1+(size_t)tycnt1*6+(size_t)chcnt1;
    off+=(size_t)lcnt1*8+(size_t)isdcnt1+(size_t)isucnt1;
    /* second block header */
    if(off+44>flen){free(buf);return NULL;}
    const uint8_t*h2=buf+off;
    int isucnt=rbe32(h2+24+0*4);
    int isdcnt=rbe32(h2+24+1*4);
    int lcnt=rbe32(h2+24+2*4);
    int tcnt=rbe32(h2+24+3*4);
    int tycnt=rbe32(h2+24+4*4);
    int chcnt=rbe32(h2+24+5*4);
    off+=44;
    TZData*tz=(TZData*)calloc(1,sizeof(TZData));
    tz->ntr=tcnt;tz->nlt=tycnt;
    tz->tr=(Trans*)malloc(sizeof(Trans)*(tcnt>0?tcnt:1));
    tz->lt=(LTT*)malloc(sizeof(LTT)*(tycnt>0?tycnt:1));
    /* data block layout */
    size_t tt_start=off;
    size_t ti_start=tt_start+(size_t)tcnt*8;
    size_t lt_start=ti_start+(size_t)tcnt;
    size_t ab_start=lt_start+(size_t)tycnt*6;
    for(int i=0;i<tcnt;i++){tz->tr[i].time=rbe64(buf+tt_start+i*8);}
    for(int i=0;i<tcnt;i++){tz->tr[i].tidx=buf[ti_start+i];}
    for(int i=0;i<tycnt;i++){
        tz->lt[i].utc_off=rbe32(buf+lt_start+i*6);
        tz->lt[i].isdst=buf[lt_start+i*6+4];
        int ai=buf[lt_start+i*6+5];
        const char*ap=(const char*)buf+ab_start+ai;
        strncpy(tz->lt[i].abbr,ap,63);tz->lt[i].abbr[63]=0;
    }
    off=ab_start+(size_t)chcnt+(size_t)lcnt*12+(size_t)isdcnt+(size_t)isucnt;
    /* footer: newline, POSIX string, newline */
    if(off<flen&&buf[off]=='\n')off++;
    if(off<flen){
        char ftbuf[512]={0};
        int fi=0;
        while(off<flen&&buf[off]!='\n'&&fi<511){ftbuf[fi++]=buf[off++];}
        ftbuf[fi]=0;
        if(fi>0){
            if(parse_footer(ftbuf,&tz->ft)==0)tz->has_ft=1;
        }
    }
    tz->first_tr=tcnt>0?tz->tr[0].time:0;
    tz->last_tr=tcnt>0?tz->tr[tcnt-1].time:0;
    free(buf);
    return tz;
}

/* ─── Determine type at time t ─── */
static int64_t comp_start_utc(int yr,Footer*f){
    int d=find_mwd(yr,f->start.m,f->start.w,f->start.d);
    int64_t ls=days_from_civil(yr,f->start.m,d)*86400+f->start.tod;
    return ls-f->std_off;
}
static int64_t comp_end_utc(int yr,Footer*f){
    int d=find_mwd(yr,f->end.m,f->end.w,f->end.d);
    int64_t ls=days_from_civil(yr,f->end.m,d)*86400+f->end.tod;
    return ls-f->dst_off;
}
static int is_dst_at(int64_t t,Footer*f){
    if(!f->has_dst||!f->has_rules)return 0;
    int64_t ls=t+f->std_off;
    int64_t dy=ls/86400;if(ls%86400<0)dy--;
    int y,m,d;civil_from_days(dy,&y,&m,&d);
    for(int dy2=-1;dy2<=1;dy2++){
        int yr=y+dy2;
        int64_t su=comp_start_utc(yr,f);
        int64_t eu=comp_end_utc(yr,f);
        if(su<eu){if(t>=su&&t<eu)return 1;}
        else if(su>eu){if(t>=su||t<eu)return 1;}
    }
    return 0;
}
static void get_type_at(int64_t t,TZData*tz,int64_t*off_out,const char**ab_out){
    if(tz->ntr==0){
        if(tz->has_ft){
            if(is_dst_at(t,&tz->ft)){*off_out=tz->ft.dst_off;*ab_out=tz->ft.dst_abbr;}
            else{*off_out=tz->ft.std_off;*ab_out=tz->ft.std_abbr;}
        }else{*off_out=tz->lt[0].utc_off;*ab_out=tz->lt[0].abbr;}
        return;
    }
    if(t<tz->tr[0].time){*off_out=tz->lt[0].utc_off;*ab_out=tz->lt[0].abbr;return;}
    if(t>tz->tr[tz->ntr-1].time){
        if(tz->has_ft){
            if(is_dst_at(t,&tz->ft)){*off_out=tz->ft.dst_off;*ab_out=tz->ft.dst_abbr;}
            else{*off_out=tz->ft.std_off;*ab_out=tz->ft.std_abbr;}
        }else{int ti=tz->tr[tz->ntr-1].tidx;*off_out=tz->lt[ti].utc_off;*ab_out=tz->lt[ti].abbr;}
        return;
    }
    /* binary search: last i with tr[i].time <= t */
    int lo=0,hi=tz->ntr-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->tr[mid].time<=t)lo=mid;else hi=mid-1;}
    int ti=tz->tr[lo].tidx;
    *off_out=tz->lt[ti].utc_off;*ab_out=tz->lt[ti].abbr;
}

/* ─── Formatting ─── */
static void fmt_offset(int64_t off,char*buf){
    char sign=off<0?'-':'+';
    if(off<0)off=-off;
    int h=(int)(off/3600),m=(int)((off%3600)/60),s=(int)(off%60);
    if(s)sprintf(buf,"%c%02d:%02d:%02d",sign,h,m,s);
    else sprintf(buf,"%c%02d:%02d",sign,h,m);
}
static void fmt_local(int64_t local_secs,char*buf){
    int64_t dy=local_secs/86400;if(local_secs%86400<0)dy--;
    int sod=(int)(local_secs-dy*86400);
    int y,m,d;civil_from_days(dy,&y,&m,&d);
    sprintf(buf,"%04d-%02d-%02dT%02d:%02d:%02d",y,m,d,sod/3600,(sod%3600)/60,sod%60);
}

/* ─── UTC query ─── */
static void do_utc(int64_t t,TZData*tz,char*out){
    int64_t off;const char*ab;
    get_type_at(t,tz,&off,&ab);
    int64_t ls=t+off;
    char lbuf[64],obuf[32];
    fmt_local(ls,lbuf);
    fmt_offset(off,obuf);
    sprintf(out,"%s%s %s",lbuf,obuf,ab);
}

/* ─── LOCAL query ─── */
static int64_t parse_wall(const char*s){
    int y,mo,d,h,mi,se;
    sscanf(s,"%d-%d-%dT%d:%d:%d",&y,&mo,&d,&h,&mi,&se);
    return days_from_civil(y,mo,d)*86400+h*3600+mi*60+se;
}
static void do_local(const char*wall,TZData*tz,const char*query,char*out){
    int64_t W=parse_wall(wall);
    /* collect candidate offsets */
    int64_t cands[512];int nc=0;
    for(int i=0;i<tz->nlt;i++){
        int dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->lt[i].utc_off){dup=1;break;}
        if(!dup)cands[nc++]=tz->lt[i].utc_off;
    }
    if(tz->has_ft){
        int dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->ft.std_off){dup=1;break;}
        if(!dup)cands[nc++]=tz->ft.std_off;
        if(tz->ft.has_dst){
            dup=0;for(int j=0;j<nc;j++)if(cands[j]==tz->ft.dst_off){dup=1;break;}
            if(!dup)cands[nc++]=tz->ft.dst_off;
        }
    }
    /* find solutions */
    SOL sols[4];int ns=0;
    for(int ci=0;ci<nc;ci++){
        int64_t t=W-cands[ci];
        int64_t aoff;const char*aab;
        get_type_at(t,tz,&aoff,&aab);
        if(aoff==cands[ci]){
            int dup=0;for(int j=0;j<ns;j++)if(sols[j].t==t){dup=1;break;}
            if(!dup){sols[ns].t=t;sols[ns].off=aoff;sols[ns].ab=aab;ns++;}
        }
    }
    /* sort by t */
    for(int i=0;i<ns-1;i++)for(int j=i+1;j<ns;j++)if(sols[j].t<sols[i].t){
        SOL tmp=sols[i];sols[i]=sols[j];sols[j]=tmp;
    }
    if(ns==1){
        char ob[32];fmt_offset(sols[0].off,ob);
        sprintf(out,"%s -> %lld %s %s",query,(long long)sols[0].t,ob,sols[0].ab);
    }else if(ns==2){
        char ob1[32],ob2[32];
        fmt_offset(sols[0].off,ob1);fmt_offset(sols[1].off,ob2);
        sprintf(out,"%s -> %lld %s %s | %lld %s %s",query,
            (long long)sols[0].t,ob1,sols[0].ab,(long long)sols[1].t,ob2,sols[1].ab);
    }else{
        /* gap: find transition causing it */
        int64_t off_before=0;int found=0;
        /* check table transitions */
        for(int i=0;i<tz->ntr&&!found;i++){
            int64_t T=tz->tr[i].time;
            int prev_ti=(i==0)?0:tz->tr[i-1].tidx;
            int next_ti=tz->tr[i].tidx;
            int64_t old_off=tz->lt[prev_ti].utc_off;
            int64_t new_off=tz->lt[next_ti].utc_off;
            if(new_off>old_off){
                int64_t gs=T+old_off,ge=T+new_off;
                if(W>=gs&&W<ge){off_before=old_off;found=1;}
            }
        }
        /* check footer transitions */
        if(!found&&tz->has_ft&&tz->ft.has_dst&&tz->ft.has_rules){
            int64_t ls=W+tz->ft.std_off;
            int64_t dy=ls/86400;if(ls%86400<0)dy--;
            int y,m,d;civil_from_days(dy,&y,&m,&d);
            for(int dy2=-1;dy2<=1&&!found;dy2++){
                int yr=y+dy2;
                if(tz->ft.dst_off>tz->ft.std_off){
                    int64_t su=comp_start_utc(yr,&tz->ft);
                    int64_t gs=su+tz->ft.std_off,ge=su+tz->ft.dst_off;
                    if(W>=gs&&W<ge){off_before=tz->ft.std_off;found=1;}
                }
                if(tz->ft.std_off>tz->ft.dst_off){
                    int64_t eu=comp_end_utc(yr,&tz->ft);
                    int64_t gs=eu+tz->ft.dst_off,ge=eu+tz->ft.std_off;
                    if(W>=gs&&W<ge){off_before=tz->ft.dst_off;found=1;}
                }
            }
        }
        /* check boundary after last transition to footer */
        if(!found&&tz->ntr>0&&tz->has_ft){
            int64_t T=tz->tr[tz->ntr-1].time;
            int last_ti=tz->tr[tz->ntr-1].tidx;
            int64_t old_off=tz->lt[last_ti].utc_off;
            int64_t T2=T+1;
            int64_t new_off;const char*tmp;
            get_type_at(T2,tz,&new_off,&tmp);
            if(new_off>old_off){
                int64_t gs=T+old_off,ge=T+new_off;
                if(W>=gs&&W<ge){off_before=old_off;found=1;}
            }
        }
        if(!found){
            off_before=0;found=1;
        }
        int64_t t=W-off_before;
        int64_t aoff;const char*aab;
        get_type_at(t,tz,&aoff,&aab);
        int64_t ls2=t+aoff;
        char lbuf[64],obuf[32];
        fmt_local(ls2,lbuf);
        fmt_offset(aoff,obuf);
        sprintf(out,"%s -> GAP %lld %s%s %s",query,(long long)t,lbuf,obuf,aab);
    }
}

/* ─── Main ─── */
int main(int argc,char*argv[]){
    if(argc!=2){fprintf(stderr,"usage: %s <dir>\n",argv[0]);return 1;}
    char qpath[4096];
    snprintf(qpath,sizeof(qpath),"%s/queries.txt",argv[1]);
    FILE*fp=fopen(qpath,"r");
    if(!fp){fprintf(stderr,"cannot open queries.txt\n");return 1;}
    char line[4096];
    struct{char name[256];TZData*tz;}cache[256];int ncache=0;
    while(fgets(line,sizeof(line),fp)){
        size_t len=strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]=0;
        if(len==0)continue;
        char type[16]={0},fname[256]={0},rest[2048]={0};
        int n=sscanf(line,"%15s %255s %2047[^\n]",type,fname,rest);
        if(n<3)continue;
        TZData*tz=NULL;
        for(int i=0;i<ncache;i++){if(strcmp(cache[i].name,fname)==0){tz=cache[i].tz;break;}}
        if(!tz){
            char fpath[4096];
            snprintf(fpath,sizeof(fpath),"%s/%s",argv[1],fname);
            tz=parse_tzif(fpath);
            if(!tz){fprintf(stderr,"cannot parse %s\n",fpath);continue;}
            if(ncache<256){strncpy(cache[ncache].name,fname,255);cache[ncache].name[255]=0;cache[ncache].tz=tz;ncache++;}
        }
        char out[4096];
        if(strcmp(type,"UTC")==0){
            int64_t t=(int64_t)atoll(rest);
            char result[256];
            do_utc(t,tz,result);
            sprintf(out,"%s -> %s",line,result);
        }else if(strcmp(type,"LOCAL")==0){
            do_local(rest,tz,line,out);
        }else{
            continue;
        }
        printf("%s\n",out);
    }
    fclose(fp);
    for(int i=0;i<ncache;i++){free(cache[i].tz->tr);free(cache[i].tz->lt);free(cache[i].tz);}
    return 0;
}
